# =============================================================================
# Compatibility types
# =============================================================================
type
  MmClockCtrlRegs* {.bycopy.} = object
    ## Overlay rooted at MM_GLB_MM_CLK_CTRL_CPU.
    mmClkCtrlCpu*: uint32

  CnnClockResetRegs* {.bycopy.} = object
    ## Overlay rooted at MM_GLB_MM_CLK_CPU. Only the CNN clock/reset fields are
    ## named; intervening MM_GLB words remain opaque until recovered.
    mmClkCpu*: uint32
    reserved0*: array[17, uint32]
    swResetCodecSub*: uint32

  MmMiscBusDecodeRegs* {.bycopy.} = object
    ## Overlay rooted at MM_MISC_MM_BUS_DEC_ERR.
    mmBusDecErr*: uint32
    mmBusDecErrAddr*: uint32
    mcuBusDecErr*: uint32
    mcuBusDecErrAddr*: uint32

  MmMiscVramRegs* {.bycopy.} = object
    ## Overlay rooted at MM_MISC_VRAM_CTRL.
    vramCtrl*: uint32

  MmMiscBlaiCommandRegs* {.bycopy.} = object
    ## Overlay rooted at MM_MISC codec_misc_1 for the BLAI command counter.
    codecMisc1*: uint32

  MmMiscInterruptRegs* {.bycopy.} = object
    ## Overlay rooted at MM_INT_STA0 for the MM aggregate interrupt surface.
    status0*: uint32
    mask0*: uint32
    clear0*: uint32
    status1*: uint32
    mask1*: uint32
    clear1*: uint32

  TzcNsecMmBmxTzmidRegs* {.bycopy.} = object
    ## Overlay rooted at TZC_NSEC_TZC_MM_BMX_TZMID.
    mmBmxTzmid*: uint32
    mmBmxTzmidLock*: uint32

  CodecMiscRegs* {.bycopy.} = object
    ## Codec bus/QoS/limiter registers used by the SDK BLAI integration path.
    busCtrl*: uint32
    qosCtrl*: uint32
    busThreshold*: uint32
    reserved0*: array[5, uint32]
    blaiLimiterRead*: uint32
    blaiLimiterWrite*: uint32

  BlaiRegs* {.bycopy.} = object
    ## SDK-recovered BLAI aperture. Layer execution is instruction-stream
    ## driven; this block exposes the low-level launch/configuration registers
    ## without inventing high-level layer dimension registers.
    generalCfg*: uint32
    intCfg*: uint32
    reserved0*: array[2, uint32]
    weightAddr*: uint32
    biasAddr*: uint32
    instAddr*: uint32
    imageAddr*: uint32
    imageSeg*: uint32
    tfCfg0*: uint32
    reserved1*: array[54, uint32]
    actTable*: array[64, uint32]

  NpuClockSource* = enum
    npuClk160M = 0
    npuClk240M = 1
    npuClk320M = 2

  NpuImageInputMode* = enum
    npuInputSound = 0
    npuInputYuv400 = 1
    npuInputYuv422 = 2

  NpuLayerType* = enum
    npuConv     = 0
    npuPool     = 1
    npuFC       = 2
    npuEltwise  = 3

  NpuActivation* = enum
    npuActNone    = 0
    npuActRelu    = 1
    npuActRelu6   = 2
    npuActSigmoid = 3

  NpuPoolType* = enum
    npuMaxPool = 0
    npuAvgPool = 1

  NpuError* = enum
    npuOk
    npuTimeout
    npuBusy
    npuUnsupported

  BlaiLayerType* = enum
    ## Layer type values used by the SDK BLAI instruction decoder.
    blaiConvolutional
    blaiMaxpool
    blaiAvgpool
    blaiRoute
    blaiShortcut
    blaiMatmul
    blaiUpsample
    blaiYolo
    blaiSoftmax
