  doAssert TzcNsecMmBmxBlaiTzmidBit == 1'u32
  doAssert TzcNsecMmBmxBlaiTzmidSelBit == 17'u32
  doAssert TzcNsecMmBmxBlaiTzmidLockBit == 1'u32

template blaiMmioBlock*[T](base: untyped): ptr T =
  ## Localize the MMIO base-address-to-overlay cast behind a typed view.
  cast[ptr T](base)

template mmClockCtrl*(): ptr MmClockCtrlRegs =
  blaiMmioBlock[MmClockCtrlRegs](MmClockCtrl)

template mmMiscVram*(): ptr MmMiscVramRegs =
  blaiMmioBlock[MmMiscVramRegs](MmVramCtrl)

template mmMiscBusDecode*(): ptr MmMiscBusDecodeRegs =
  blaiMmioBlock[MmMiscBusDecodeRegs](MmMiscBusDecode)

template cnnClockReset*(): ptr CnnClockResetRegs =
  blaiMmioBlock[CnnClockResetRegs](MmCnnClock)

template mmMiscBlaiCommand*(): ptr MmMiscBlaiCommandRegs =
  blaiMmioBlock[MmMiscBlaiCommandRegs](MmBlaiCommandStatus)

template mmMiscInterrupt*(): ptr MmMiscInterruptRegs =
  blaiMmioBlock[MmMiscInterruptRegs](MmMiscIntSta0)

template tzcNsecMmBmxTzmid*(): ptr TzcNsecMmBmxTzmidRegs =
  blaiMmioBlock[TzcNsecMmBmxTzmidRegs](TzcNsecMmBmxTzmid)

template codecMisc*(): ptr CodecMiscRegs =
  blaiMmioBlock[CodecMiscRegs](CodecMiscBase)

template blaiRegs*(): ptr BlaiRegs =
  blaiMmioBlock[BlaiRegs](BlaiBase)

proc blaiLoadReg*(reg: var uint32): uint32 =
  ## Read one typed MMIO overlay field through the localized volatile boundary.
  volatileLoad(addr reg)

proc blaiStoreReg*(reg: var uint32, value: uint32) =
  ## Write one typed MMIO overlay field through the localized volatile boundary.
  volatileStore(addr reg, value)

