proc blaiInstructionCountState*(
    instCnt: int32): BlaiInstructionCountState =
  ## Build caller-owned SDK instruction-count state.
  result.instCnt = instCnt

proc blaiInstructionCountApplyPlan*(
    count: uint32): BlaiInstructionCountApplyPlan =
  ## Recover checked `instCnt` projection before mutating a layer.
  let field = blaiInstructionCountAbi(count)
  if not field.valid:
    return
  result.count = count
  result.stateAfter = blaiInstructionCountState(field.value)
  result.valid = true

proc blaiInstructionCountState*(
    plan: BlaiInstructionCountApplyPlan): BlaiInstructionCountState =
  ## Project a valid instruction-count apply plan into caller-owned state.
  doAssert plan.valid
  plan.stateAfter

proc blaiApplyInstructionCountState*(
    layer: var BlaiCpuInstLayer64,
    state: BlaiInstructionCountState) =
  ## Apply recovered instruction-count state to a typed layer object.
  layer.instCnt = state.instCnt
