proc blaiMnistTfliteTensor*(
    role: BlaiMnistTfliteTensorRole,
    tensorType: BlaiMnistTfliteTensorType,
    shapeRank: uint32,
    shape: array[4, uint32],
    bufferBytes: uint32,
    quantization: BlaiMnistTfliteQuantization,
    bufferDigest: BlaiMnistTfliteBufferDigest =
      BlaiMnistTfliteNoBufferDigest): BlaiMnistTfliteTensor =
  ## Build one typed tensor summary for the fetched MNIST model.
  BlaiMnistTfliteTensor(
    role: role,
    tensorType: tensorType,
    shapeRank: shapeRank,
    shape: shape,
    bufferBytes: bufferBytes,
    bufferDigest: bufferDigest,
    quantization: quantization)

proc blaiMnistTfliteOperator*(
    kind: BlaiMnistTfliteOperatorKind,
    inputCount: uint32,
    inputs: array[3, uint32],
    output: uint32): BlaiMnistTfliteOperator =
  ## Build one typed operator wiring record for the fetched MNIST model.
  BlaiMnistTfliteOperator(
    kind: kind,
    inputCount: inputCount,
    inputs: inputs,
    outputCount: 1'u32,
    outputs: [output])

proc blaiMnistTfliteSampleLayerOracle*(
    operatorIndex: uint32,
    kind: BlaiMnistTfliteOperatorKind,
    outputTensor: uint32,
    outputMin, outputMax, outputSum: int32):
    BlaiMnistTfliteSampleLayerOracle =
  ## Build one known-answer sample layer summary.
  BlaiMnistTfliteSampleLayerOracle(
    operatorIndex: operatorIndex,
    kind: kind,
    outputTensor: outputTensor,
    outputMin: outputMin,
    outputMax: outputMax,
    outputSum: outputSum)

proc blaiMnistTfliteSampleOracle*(): BlaiMnistTfliteSampleOracle =
  ## Project the toolchain-shipped MNIST `image/a.bmp` known-answer oracle.
  ##
  ## The output vector is a host CPU int8 oracle for the fetched TFLite graph,
  ## not proof that the BL808 NPU has produced the same bytes yet.
  result.imageBytes = 1862'u32
  result.imageWidth = 28'u32
  result.imageHeight = 28'u32
  result.imageBitsPerPixel = 8'u32
  result.imagePixelOffset = 1078'u32
  result.imagePixelMin = 0'u32
  result.imagePixelMax = 192'u32
  result.imagePixelSum = 13635'u32
  result.inputQuantizedMin = -128
  result.inputQuantizedMax = 64
  result.inputQuantizedSum = -86717
  result.outputTensor = 17'u32
  result.outputVector = [-19'i8, 7, -1, -4, -18, -41, -50, 43, -22, -4]
  result.topClass = 7'u32
  result.topScore = 43'i8
  result.layers = [
    blaiMnistTfliteSampleLayerOracle(
      0'u32, blaiMnistOpConv2d, 12'u32, -128, -13, -287009),
    blaiMnistTfliteSampleLayerOracle(
      1'u32, blaiMnistOpConv2d, 13'u32, -128, -30, -141948),
    blaiMnistTfliteSampleLayerOracle(
      2'u32, blaiMnistOpConv2d, 14'u32, -128, -49, -92273),
    blaiMnistTfliteSampleLayerOracle(
      3'u32, blaiMnistOpConv2d, 15'u32, -128, -51, -22503),
    blaiMnistTfliteSampleLayerOracle(
      4'u32, blaiMnistOpReshape, 16'u32, -128, -51, -22503),
    blaiMnistTfliteSampleLayerOracle(
      5'u32, blaiMnistOpFullyConnected, 17'u32, -50, 43, -109)]
  result.valid =
    result.imageWidth == 28'u32 and result.imageHeight == 28'u32 and
      result.imageBitsPerPixel == 8'u32 and
      result.inputQuantizedMin == -128 and
      result.inputQuantizedMax == 64 and
      result.outputTensor == 17'u32 and
      result.outputVector[7] == result.topScore and
      result.topClass == 7'u32

proc blaiGeneratedModelHeaderContract*(): BlaiGeneratedModelHeaderContract =
  ## Project the fixed `gen_array.py` `blai_model_bin[]` size-table contract.
  result.modelArray = blaiGeneratedModelBinArray
  result.cpuSectionCount = BlaiGeneratedModelCpuSectionCount
  result.npuSectionCount = BlaiGeneratedModelNpuSectionCount
  result.terminatorWordCount = BlaiGeneratedModelTerminatorWordCount
  result.sizeTableWords = BlaiGeneratedModelSizeTableWords
  result.headerBytes = BlaiGeneratedModelSizeTableBytes
  result.arrayMatches = result.modelArray == blaiGeneratedModelBinArray
  result.cpuSectionCountMatches = result.cpuSectionCount == 3'u32
  result.npuSectionCountMatches = result.npuSectionCount == 3'u32
  result.terminatorWordCountMatches = result.terminatorWordCount == 2'u32
  result.sizeTableWordsMatch =
    result.sizeTableWords ==
      result.cpuSectionCount + result.npuSectionCount +
        result.terminatorWordCount
  result.headerBytesMatch =
    result.headerBytes == result.sizeTableWords * sizeof(uint32).uint32
  result.payloadOrderMatchesGenArray = true
  if not result.arrayMatches:
    result.firstBlock = blaiGeneratedModelHeaderContractArray
  elif not result.cpuSectionCountMatches:
    result.firstBlock = blaiGeneratedModelHeaderContractCpuSections
  elif not result.npuSectionCountMatches:
    result.firstBlock = blaiGeneratedModelHeaderContractNpuSections
  elif not result.terminatorWordCountMatches:
    result.firstBlock = blaiGeneratedModelHeaderContractTerminators
  elif not result.sizeTableWordsMatch:
    result.firstBlock = blaiGeneratedModelHeaderContractSizeTable
  elif not result.headerBytesMatch:
    result.firstBlock = blaiGeneratedModelHeaderContractHeaderBytes
  elif not result.payloadOrderMatchesGenArray:
    result.firstBlock = blaiGeneratedModelHeaderContractPayloadOrder
  else:
    result.firstBlock = blaiGeneratedModelHeaderContractNoBlock
  result.valid =
    result.arrayMatches and result.cpuSectionCountMatches and
      result.npuSectionCountMatches and result.terminatorWordCountMatches and
      result.sizeTableWordsMatch and result.headerBytesMatch and
      result.payloadOrderMatchesGenArray and
      result.firstBlock == blaiGeneratedModelHeaderContractNoBlock

proc blaiToolchainConverterOutputArtifact*(
    output: BlaiToolchainConverterOutputKind,
    section: BlaiGeneratedPayloadSectionKind,
    order: uint32): BlaiToolchainConverterOutputArtifact =
  ## Build one recovered converter-output mapping.
  result.output = output
  result.section = section
  result.order = order
  result.consumedByGenArray = true
  result.binarySuffix = true
  result.active = true
  result.valid = result.active and result.consumedByGenArray and result.binarySuffix

proc blaiToolchainConverterOutputContract*():
    BlaiToolchainConverterOutputContract =
  ## Project `write_blai_binaries` output files into generated-model order.
  ##
  ## The names are recovered from the fetched converter strings:
  ## `dspinstruction_b.bin`, `all_dspbias_b.bin`, `all_dspweight_b.bin`,
  ## `instruction_b.bin`, `all_bias_b.bin`, and `all_weight_b.bin`.
  result.artifacts = [
    blaiToolchainConverterOutputArtifact(
      blaiToolchainOutputDspInstructionBin,
      blaiGeneratedCpuInstructionSection, 0'u32),
    blaiToolchainConverterOutputArtifact(
      blaiToolchainOutputDspBiasBin,
      blaiGeneratedCpuBiasSection, 1'u32),
    blaiToolchainConverterOutputArtifact(
      blaiToolchainOutputDspWeightBin,
      blaiGeneratedCpuWeightSection, 2'u32),
    blaiToolchainConverterOutputArtifact(
      blaiToolchainOutputInstructionBin,
      blaiGeneratedNpuInstructionSection, 3'u32),
    blaiToolchainConverterOutputArtifact(
      blaiToolchainOutputBiasBin,
      blaiGeneratedNpuBiasSection, 4'u32),
    blaiToolchainConverterOutputArtifact(
      blaiToolchainOutputWeightBin,
      blaiGeneratedNpuWeightSection, 5'u32)]
  result.artifactCount = blaiOpenArrayLenU32(result.artifacts)
  for artifact in result.artifacts:
    if artifact.order < 3'u32:
      inc result.cpuArtifactCount
    else:
      inc result.npuArtifactCount
    if artifact.binarySuffix:
      inc result.binaryArtifactCount
    if artifact.valid:
      inc result.validArtifactCount
  result.payloadOrderMatchesGenArray =
    result.artifacts[0].section == blaiGeneratedCpuInstructionSection and
      result.artifacts[1].section == blaiGeneratedCpuBiasSection and
      result.artifacts[2].section == blaiGeneratedCpuWeightSection and
      result.artifacts[3].section == blaiGeneratedNpuInstructionSection and
      result.artifacts[4].section == blaiGeneratedNpuBiasSection and
      result.artifacts[5].section == blaiGeneratedNpuWeightSection
  result.producedByWriteBlaiBinaries = true
  result.consumedByGenArray = true
  if result.artifactCount != 6'u32:
    result.firstBlock = blaiToolchainConverterOutputContractArtifactCount
  elif result.cpuArtifactCount != 3'u32:
    result.firstBlock = blaiToolchainConverterOutputContractCpuArtifacts
  elif result.npuArtifactCount != 3'u32:
    result.firstBlock = blaiToolchainConverterOutputContractNpuArtifacts
  elif result.binaryArtifactCount != result.artifactCount:
    result.firstBlock = blaiToolchainConverterOutputContractBinaryArtifacts
  elif not result.payloadOrderMatchesGenArray:
    result.firstBlock = blaiToolchainConverterOutputContractPayloadOrder
  elif not result.producedByWriteBlaiBinaries:
    result.firstBlock = blaiToolchainConverterOutputContractProducer
  elif not result.consumedByGenArray:
    result.firstBlock = blaiToolchainConverterOutputContractConsumer
  elif result.validArtifactCount != result.artifactCount:
    result.firstBlock = blaiToolchainConverterOutputContractArtifact
  else:
    result.firstBlock = blaiToolchainConverterOutputContractNoBlock
  result.valid =
    result.artifactCount == 6'u32 and result.cpuArtifactCount == 3'u32 and
      result.npuArtifactCount == 3'u32 and
      result.binaryArtifactCount == result.artifactCount and
      result.payloadOrderMatchesGenArray and
      result.producedByWriteBlaiBinaries and result.consumedByGenArray and
      result.validArtifactCount == result.artifactCount and
      result.firstBlock == blaiToolchainConverterOutputContractNoBlock

proc blaiToolchainConverterDependencyClass*(
    library: BlaiToolchainConverterDependencyKind):
    BlaiToolchainConverterDependencyClass =
  ## Classify one recovered converter shared-library dependency.
  case library
  of blaiToolchainConverterDependencyNnapiDelegate,
      blaiToolchainConverterDependencyNnapiImplementation,
      blaiToolchainConverterDependencyNnapiSupport:
    blaiToolchainConverterDependencyNnapi
  of blaiToolchainConverterDependencyTensorflowLite:
    blaiToolchainConverterDependencyTensorflow
  of blaiToolchainConverterDependencyDarknet:
    blaiToolchainConverterDependencyDarknetClass
  of blaiToolchainConverterDependencyOpenCvDnn,
      blaiToolchainConverterDependencyOpenCvImgCodecs,
      blaiToolchainConverterDependencyOpenCvImgProc,
      blaiToolchainConverterDependencyOpenCvCore:
    blaiToolchainConverterDependencyOpenCv
  else:
    blaiToolchainConverterDependencyFramework

proc blaiToolchainConverterDependency*(
    library: BlaiToolchainConverterDependencyKind,
    present = false): BlaiToolchainConverterDependency =
  ## Build one required converter dependency from the recovered ldd probe.
  result.library = library
  result.dependencyClass = blaiToolchainConverterDependencyClass(library)
  result.required = true
  result.present = present
  result.missing = result.required and not result.present
  result.valid = result.required

proc blaiToolchainConverterDependencyPlanInto*(
    outResult: var BlaiToolchainConverterDependencyPlan) =
  ## Build the current converter startup-dependency plan.
  outResult = default(BlaiToolchainConverterDependencyPlan)
  outResult.dependencies = [
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyBuiltinOps),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyFrameworkLib),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyKernelUtil),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyMinimalLogging),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyNnapiDelegate),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyNnapiImplementation),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyNnapiSupport),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyQuantizationUtil),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyTensorflowLite),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyDarknet),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyOpenCvDnn),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyOpenCvImgCodecs),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyOpenCvImgProc),
    blaiToolchainConverterDependency(
      blaiToolchainConverterDependencyOpenCvCore)]
  for dependency in outResult.dependencies:
    if dependency.required:
      inc outResult.requiredCount
    if dependency.present:
      inc outResult.presentCount
    if dependency.missing:
      inc outResult.missingCount
      if not outResult.firstMissingCaptured:
        outResult.firstMissing = dependency.library
        outResult.firstMissingCaptured = true
      case dependency.dependencyClass
      of blaiToolchainConverterDependencyFramework:
        inc outResult.frameworkMissing
      of blaiToolchainConverterDependencyNnapi:
        inc outResult.nnapiMissing
      of blaiToolchainConverterDependencyTensorflow:
        inc outResult.tensorflowMissing
      of blaiToolchainConverterDependencyDarknetClass:
        inc outResult.darknetMissing
      of blaiToolchainConverterDependencyOpenCv:
        inc outResult.openCvMissing
  outResult.blocksExecution = outResult.missingCount != 0'u32
  outResult.valid =
    outResult.requiredCount ==
      BlaiToolchainConverterMissingSharedLibraryCount and
      outResult.missingCount ==
        BlaiToolchainConverterMissingSharedLibraryCount and
      outResult.frameworkMissing == 5'u32 and outResult.nnapiMissing == 3'u32 and
      outResult.tensorflowMissing == 1'u32 and
      outResult.darknetMissing == 1'u32 and outResult.openCvMissing == 4'u32 and
      outResult.firstMissingCaptured and outResult.blocksExecution

proc blaiToolchainConverterDependencyPlan*():
    BlaiToolchainConverterDependencyPlan =
  ## Convenience wrapper for converter startup-dependency evidence.
  blaiToolchainConverterDependencyPlanInto(result)

proc blaiToolchainConverterArtifactRegenerationPlanInto*(
    output: BlaiToolchainConverterOutputContract,
    dependencies: BlaiToolchainConverterDependencyPlan,
    artifactsRegenerated = false,
    outResult: var BlaiToolchainConverterArtifactRegenerationPlan) =
  ## Bind the recovered output ABI to the current host converter run gate.
  outResult = default(BlaiToolchainConverterArtifactRegenerationPlan)
  outResult.outputContractValid = output.valid
  outResult.dependencyPlanValid = dependencies.valid
  outResult.expectedArtifactCount = output.artifactCount
  outResult.expectedCpuArtifacts = output.cpuArtifactCount
  outResult.expectedNpuArtifacts = output.npuArtifactCount
  outResult.missingDependencyCount = dependencies.missingCount
  outResult.converterRunnable =
    dependencies.valid and not dependencies.blocksExecution
  outResult.outputArtifactsExpected =
    output.valid and output.artifactCount == 6'u32 and
      output.cpuArtifactCount == 3'u32 and output.npuArtifactCount == 3'u32 and
      output.payloadOrderMatchesGenArray
  outResult.artifactsRegenerated = artifactsRegenerated
  outResult.artifactsAvailable =
    outResult.artifactsRegenerated and outResult.outputArtifactsExpected and
      outResult.converterRunnable
  outResult.blockedByDependencies =
    dependencies.valid and dependencies.blocksExecution and
      dependencies.missingCount != 0'u32
  outResult.staticOutputContractUsable =
    outResult.outputArtifactsExpected and outResult.blockedByDependencies and
      not outResult.artifactsAvailable
  if not outResult.outputContractValid:
    outResult.firstBlock =
      blaiToolchainConverterArtifactRegenerationOutputContract
  elif not outResult.dependencyPlanValid:
    outResult.firstBlock =
      blaiToolchainConverterArtifactRegenerationDependencies
  elif outResult.blockedByDependencies:
    outResult.firstBlock =
      blaiToolchainConverterArtifactRegenerationDependencies
  elif not outResult.converterRunnable:
    outResult.firstBlock =
      blaiToolchainConverterArtifactRegenerationExecution
  elif not outResult.artifactsAvailable:
    outResult.firstBlock =
      blaiToolchainConverterArtifactRegenerationArtifacts
  else:
    outResult.firstBlock =
      blaiToolchainConverterArtifactRegenerationNoBlock
  outResult.valid =
    outResult.outputContractValid and outResult.dependencyPlanValid and
      outResult.outputArtifactsExpected and outResult.blockedByDependencies and
      outResult.staticOutputContractUsable and
      outResult.firstBlock ==
        blaiToolchainConverterArtifactRegenerationDependencies

proc blaiToolchainConverterArtifactRegenerationPlan*(
    output: BlaiToolchainConverterOutputContract,
    dependencies: BlaiToolchainConverterDependencyPlan,
    artifactsRegenerated = false):
    BlaiToolchainConverterArtifactRegenerationPlan =
  ## Convenience wrapper for converter artifact regeneration gating.
  blaiToolchainConverterArtifactRegenerationPlanInto(
    output, dependencies, artifactsRegenerated, result)

proc blaiToolchainConverterArtifactRegenerationPlan*():
    BlaiToolchainConverterArtifactRegenerationPlan =
  ## Compose the current converter artifact regeneration gate.
  blaiToolchainConverterArtifactRegenerationPlan(
    blaiToolchainConverterOutputContract(),
    blaiToolchainConverterDependencyPlan())

proc blaiGeneratedImageSidecarOracle*(
    sample: BlaiMnistTfliteSampleOracle): BlaiGeneratedImageSidecarOracle =
  ## Project the optional `img_bin[]` emitted by `gen_array.py --image`.
  result.imageArray = blaiGeneratedImageBinArray
  result.imageBytes = sample.imageBytes
  result.imageWidth = sample.imageWidth
  result.imageHeight = sample.imageHeight
  result.imageBitsPerPixel = sample.imageBitsPerPixel
  result.imagePixelOffset = sample.imagePixelOffset
  result.imagePixelMin = sample.imagePixelMin
  result.imagePixelMax = sample.imagePixelMax
  result.imagePixelSum = sample.imagePixelSum
  result.imageDigest = BlaiMnistTfliteSampleImageDigest
  result.sampleReady = sample.valid
  result.arrayMatches = result.imageArray == blaiGeneratedImageBinArray
  result.bytesMatch = result.imageBytes == 1862'u32
  result.dimensionsMatch =
    result.imageWidth == 28'u32 and result.imageHeight == 28'u32
  result.formatMatches = result.imageBitsPerPixel == 8'u32
  result.pixelOffsetMatches = result.imagePixelOffset == 1078'u32
  result.pixelSumMatches = result.imagePixelSum == 13635'u32
  result.digestMatches = result.imageDigest == BlaiMnistTfliteSampleImageDigest
  result.matchesSample =
    result.sampleReady and result.bytesMatch and result.dimensionsMatch and
      result.formatMatches and result.pixelOffsetMatches and
      result.pixelSumMatches
  if not result.sampleReady:
    result.firstBlock = blaiGeneratedImageSidecarSample
  elif not result.arrayMatches:
    result.firstBlock = blaiGeneratedImageSidecarArray
  elif not result.bytesMatch:
    result.firstBlock = blaiGeneratedImageSidecarBytes
  elif not result.dimensionsMatch:
    result.firstBlock = blaiGeneratedImageSidecarDimensions
  elif not result.formatMatches:
    result.firstBlock = blaiGeneratedImageSidecarFormat
  elif not result.pixelOffsetMatches:
    result.firstBlock = blaiGeneratedImageSidecarPixelOffset
  elif not result.pixelSumMatches:
    result.firstBlock = blaiGeneratedImageSidecarPixelSum
  elif not result.digestMatches:
    result.firstBlock = blaiGeneratedImageSidecarDigest
  else:
    result.firstBlock = blaiGeneratedImageSidecarNoBlock
  result.valid =
    result.arrayMatches and result.matchesSample and result.digestMatches and
      result.firstBlock == blaiGeneratedImageSidecarNoBlock

proc blaiValidateGeneratedModelHeaderContractInto*(
    plan: BlaiGeneratedModelSectionPlan,
    contract: BlaiGeneratedModelHeaderContract,
    outResult: var BlaiGeneratedModelHeaderValidation) =
  ## Check a parsed generated blob against the recovered `gen_array.py` header.
  outResult = default(BlaiGeneratedModelHeaderValidation)
  outResult.planHeaderBytes = plan.headerBytes
  outResult.contractHeaderBytes = contract.headerBytes
  outResult.cpuSectionCount = contract.cpuSectionCount
  outResult.npuSectionCount = contract.npuSectionCount
  outResult.terminatorWordCount = contract.terminatorWordCount
  outResult.cpuTerminatorWord = plan.directory.prefix.recoveredWord3
  outResult.npuTerminatorWord = plan.directory.cpu.recoveredWord3
  outResult.headerBytesMatch = plan.headerBytes == contract.headerBytes
  outResult.payloadOrderMatches =
    contract.payloadOrderMatchesGenArray and
      plan.cpuInstructionWindow.offset <= plan.cpuBiasWindow.offset and
      plan.cpuBiasWindow.offset <= plan.cpuWeightWindow.offset and
      plan.cpuWeightWindow.offset <= plan.npuInstructionWindow.offset and
      plan.npuInstructionWindow.offset <= plan.npuBiasWindow.offset and
      plan.npuBiasWindow.offset <= plan.npuWeightWindow.offset
  outResult.sectionTableComplete =
    contract.sizeTableWords ==
      contract.cpuSectionCount + contract.npuSectionCount +
        contract.terminatorWordCount
  outResult.terminatorWordsZero =
    outResult.cpuTerminatorWord == 0'u32 and
      outResult.npuTerminatorWord == 0'u32
  if not plan.valid:
    outResult.firstBlock = blaiGeneratedModelHeaderValidationPlan
  elif not contract.valid:
    outResult.firstBlock = blaiGeneratedModelHeaderValidationContract
  elif not outResult.headerBytesMatch:
    outResult.firstBlock = blaiGeneratedModelHeaderValidationHeaderBytes
  elif not outResult.payloadOrderMatches:
    outResult.firstBlock = blaiGeneratedModelHeaderValidationPayloadOrder
  elif not outResult.sectionTableComplete:
    outResult.firstBlock = blaiGeneratedModelHeaderValidationSectionTable
  elif not outResult.terminatorWordsZero:
    outResult.firstBlock = blaiGeneratedModelHeaderValidationTerminators
  else:
    outResult.firstBlock = blaiGeneratedModelHeaderValidationNoBlock
  outResult.valid =
    plan.valid and contract.valid and outResult.headerBytesMatch and
      outResult.payloadOrderMatches and outResult.sectionTableComplete and
      outResult.terminatorWordsZero

proc blaiValidateGeneratedModelHeaderContract*(
    plan: BlaiGeneratedModelSectionPlan,
    contract: BlaiGeneratedModelHeaderContract):
    BlaiGeneratedModelHeaderValidation =
  ## Convenience wrapper for generated-header contract validation.
  blaiValidateGeneratedModelHeaderContractInto(plan, contract, result)

proc blaiGeneratedModelLoadSection*(
    kind: BlaiGeneratedPayloadSectionKind,
    window: BlaiGeneratedModelSectionWindow,
    sdkAllocationGuardActive: bool,
    cacheCleanRequired: bool): BlaiGeneratedModelLoadSection =
  ## Build one checked generated-model load/copy decision.
  result.kind = kind
  result.window = window
  result.bytes = window.bytes
  result.present = window.bytes != 0'u32
  result.copiedToPsram = result.present
  result.cacheCleanRequired = result.present and cacheCleanRequired
  result.sdkAllocationGuardActive = sdkAllocationGuardActive
  result.robustAllocationGuardActive = result.present
  result.windowFirstBlock = window.firstBlock
  result.valid =
    window.ordered and window.withinBlob and
      (not result.present or result.robustAllocationGuardActive)

proc blaiGeneratedModelLoadPlanInto*(
    sectionPlan: BlaiGeneratedModelSectionPlan,
    outResult: var BlaiGeneratedModelLoadPlan) =
  ## Recover `blai_load_model_from_buffer` as typed section-copy decisions.
  outResult = default(BlaiGeneratedModelLoadPlan)
  outResult.sectionPlan = sectionPlan
  outResult.sectionCount = 6'u32
  outResult.payloadBytesExpected = sectionPlan.payloadBytesExpected
  outResult.payloadFits = sectionPlan.payloadFits
  outResult.sdkCpuWeightGuardUsesInstructionSize = true
  outResult.robustCpuWeightGuardUsesWeightSize = true
  outResult.cpuWeightGuardMismatch =
    sectionPlan.cpuInstructionWindow.bytes == 0'u32 and
      sectionPlan.cpuWeightWindow.bytes != 0'u32
  outResult.sections = [
    blaiGeneratedModelLoadSection(
      blaiGeneratedCpuInstructionSection, sectionPlan.cpuInstructionWindow,
      sectionPlan.cpuInstructionWindow.bytes != 0'u32, false),
    blaiGeneratedModelLoadSection(
      blaiGeneratedCpuBiasSection, sectionPlan.cpuBiasWindow,
      sectionPlan.cpuBiasWindow.bytes != 0'u32, false),
    blaiGeneratedModelLoadSection(
      blaiGeneratedCpuWeightSection, sectionPlan.cpuWeightWindow,
      sectionPlan.cpuInstructionWindow.bytes != 0'u32, false),
    blaiGeneratedModelLoadSection(
      blaiGeneratedNpuInstructionSection, sectionPlan.npuInstructionWindow,
      sectionPlan.npuInstructionWindow.bytes != 0'u32, true),
    blaiGeneratedModelLoadSection(
      blaiGeneratedNpuBiasSection, sectionPlan.npuBiasWindow,
      sectionPlan.npuBiasWindow.bytes != 0'u32, true),
    blaiGeneratedModelLoadSection(
      blaiGeneratedNpuWeightSection, sectionPlan.npuWeightWindow,
      sectionPlan.npuWeightWindow.bytes != 0'u32, true)]
  outResult.valid = sectionPlan.valid
  for section in outResult.sections:
    if section.present:
      inc outResult.presentSectionCount
    if section.copiedToPsram:
      inc outResult.copiedSectionCount
    if section.cacheCleanRequired:
      inc outResult.cacheCleanSectionCount
    outResult.valid = outResult.valid and section.valid
  if not sectionPlan.valid:
    outResult.firstBlock = blaiGeneratedModelLoadPlanSectionPlan
    outResult.firstSectionWindowBlock = sectionPlan.firstWindowBlock
  elif not outResult.sections[0].valid:
    outResult.firstBlock = blaiGeneratedModelLoadPlanCpuInstruction
    outResult.firstSectionWindowBlock = outResult.sections[0].windowFirstBlock
  elif not outResult.sections[1].valid:
    outResult.firstBlock = blaiGeneratedModelLoadPlanCpuBias
    outResult.firstSectionWindowBlock = outResult.sections[1].windowFirstBlock
  elif not outResult.sections[2].valid:
    outResult.firstBlock = blaiGeneratedModelLoadPlanCpuWeight
    outResult.firstSectionWindowBlock = outResult.sections[2].windowFirstBlock
  elif not outResult.sections[3].valid:
    outResult.firstBlock = blaiGeneratedModelLoadPlanNpuInstruction
    outResult.firstSectionWindowBlock = outResult.sections[3].windowFirstBlock
  elif not outResult.sections[4].valid:
    outResult.firstBlock = blaiGeneratedModelLoadPlanNpuBias
    outResult.firstSectionWindowBlock = outResult.sections[4].windowFirstBlock
  elif not outResult.sections[5].valid:
    outResult.firstBlock = blaiGeneratedModelLoadPlanNpuWeight
    outResult.firstSectionWindowBlock = outResult.sections[5].windowFirstBlock
  else:
    outResult.firstBlock = blaiGeneratedModelLoadPlanNoBlock
    outResult.firstSectionWindowBlock = blaiGeneratedModelSectionWindowNoBlock

proc blaiGeneratedModelLoadPlan*(
    sectionPlan: BlaiGeneratedModelSectionPlan): BlaiGeneratedModelLoadPlan =
  ## Convenience wrapper for generated-model load planning.
  blaiGeneratedModelLoadPlanInto(sectionPlan, result)

proc blaiGeneratedModelSectionPlanInto*(
    blob: openArray[uint8],
    outPlan: var BlaiGeneratedModelSectionPlan)

proc blaiGeneratedModelPackagePreflightInto*(
    blob: openArray[uint8],
    contract: BlaiGeneratedModelHeaderContract,
    outResult: var BlaiGeneratedModelPackagePreflight) =
  ## Validate a generated model package before any hardware payload staging.
  outResult = default(BlaiGeneratedModelPackagePreflight)
  blaiGeneratedModelSectionPlanInto(blob, outResult.sectionPlan)
  outResult.sectionPlanValid = outResult.sectionPlan.valid
  outResult.sectionPlanFirstBlock = outResult.sectionPlan.firstBlock
  outResult.directoryFirstBlock = outResult.sectionPlan.directoryFirstBlock
  outResult.windowFirstBlock = outResult.sectionPlan.firstWindowBlock
  blaiValidateGeneratedModelHeaderContractInto(
    outResult.sectionPlan, contract, outResult.headerValidation)
  outResult.headerValid = outResult.headerValidation.valid
  outResult.headerFirstBlock = outResult.headerValidation.firstBlock
  blaiGeneratedModelLoadPlanInto(outResult.sectionPlan, outResult.loadPlan)
  outResult.loadPlanValid = outResult.loadPlan.valid
  outResult.loadPlanFirstBlock = outResult.loadPlan.firstBlock
  outResult.readyToStage =
    outResult.sectionPlanValid and outResult.headerValid and
      outResult.loadPlanValid
  if not outResult.sectionPlanValid:
    outResult.firstBlock = blaiGeneratedModelPackagePreflightSectionPlan
  elif not outResult.headerValid:
    outResult.firstBlock = blaiGeneratedModelPackagePreflightHeader
  elif not outResult.loadPlanValid:
    outResult.firstBlock = blaiGeneratedModelPackagePreflightLoadPlan
  else:
    outResult.firstBlock = blaiGeneratedModelPackagePreflightNoBlock
  outResult.valid = outResult.readyToStage and
    outResult.firstBlock == blaiGeneratedModelPackagePreflightNoBlock

proc blaiGeneratedModelPackagePreflight*(
    blob: openArray[uint8],
    contract: BlaiGeneratedModelHeaderContract):
    BlaiGeneratedModelPackagePreflight =
  ## Convenience wrapper for generated-model package preflight.
  blaiGeneratedModelPackagePreflightInto(blob, contract, result)

proc blaiGeneratedModelPackagePreflight*(
    blob: openArray[uint8]): BlaiGeneratedModelPackagePreflight =
  ## Validate a generated model package against the recovered header contract.
  blaiGeneratedModelPackagePreflight(blob, blaiGeneratedModelHeaderContract())

proc blaiMnistTfliteModelPlan*(): BlaiMnistTfliteModelPlan =
  ## Project the fetched M1s MNIST TFLite model into fixed pure-Nim metadata.
  result.version = 3'u32
  result.modelBytes = 40208'u32
  result.tensorCount = 18'u32
  result.operatorCount = 6'u32
  result.persistentTensorBufferBytes = 36300'u32
  result.inputTensor = 0'u32
  result.outputTensor = 17'u32
  result.tensors = [
    blaiMnistTfliteTensor(
      blaiMnistTensorInput, blaiMnistTensorInt8, 4,
      [1'u32, 28, 28, 1], 0,
      blaiMnistTfliteQuantization(0x3B80_8081'u32, -128)),
    blaiMnistTfliteTensor(
      blaiMnistTensorReshapeConst, blaiMnistTensorInt32, 1,
      [2'u32, 0, 0, 0], 8, blaiMnistTfliteNoQuantization(),
      BlaiMnistTfliteReshapeConstDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv0Weight, blaiMnistTensorInt8, 4,
      [12'u32, 3, 3, 1], 108,
      blaiMnistTfliteQuantization(0x3CBE_62E0'u32, 0),
      BlaiMnistTfliteConv0WeightDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv0Bias, blaiMnistTensorInt32, 1,
      [12'u32, 0, 0, 0], 48,
      blaiMnistTfliteQuantization(0x38BF_2203'u32, 0),
      BlaiMnistTfliteConv0BiasDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv1Weight, blaiMnistTensorInt8, 4,
      [24'u32, 3, 3, 12], 2592,
      blaiMnistTfliteQuantization(0x3B45_1F89'u32, 0),
      BlaiMnistTfliteConv1WeightDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv1Bias, blaiMnistTensorInt32, 1,
      [24'u32, 0, 0, 0], 96,
      blaiMnistTfliteQuantization(0x38C2_F1D5'u32, 0),
      BlaiMnistTfliteConv1BiasDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv2Weight, blaiMnistTensorInt8, 4,
      [48'u32, 3, 3, 24], 10368,
      blaiMnistTfliteQuantization(0x3B81_1FAC'u32, 0),
      BlaiMnistTfliteConv2WeightDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv2Bias, blaiMnistTensorInt32, 1,
      [48'u32, 0, 0, 0], 192,
      blaiMnistTfliteQuantization(0x3901_3C45'u32, 0),
      BlaiMnistTfliteConv2BiasDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv3Weight, blaiMnistTensorInt8, 4,
      [48'u32, 3, 3, 48], 20736,
      blaiMnistTfliteQuantization(0x3B8D_79E4'u32, 0),
      BlaiMnistTfliteConv3WeightDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv3Bias, blaiMnistTensorInt32, 1,
      [48'u32, 0, 0, 0], 192,
      blaiMnistTfliteQuantization(0x3903_194F'u32, 0),
      BlaiMnistTfliteConv3BiasDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorFcWeight, blaiMnistTensorInt8, 2,
      [10'u32, 192, 0, 0], 1920,
      blaiMnistTfliteQuantization(0x3BD0_2BDD'u32, 0),
      BlaiMnistTfliteFcWeightDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorFcBias, blaiMnistTensorInt32, 1,
      [10'u32, 0, 0, 0], 40,
      blaiMnistTfliteQuantization(0x3991_3CCA'u32, 0),
      BlaiMnistTfliteFcBiasDigest),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv0Output, blaiMnistTensorInt8, 4,
      [1'u32, 14, 14, 12], 0,
      blaiMnistTfliteQuantization(0x3CFD_2BB9'u32, -128)),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv1Output, blaiMnistTensorInt8, 4,
      [1'u32, 7, 7, 24], 0,
      blaiMnistTfliteQuantization(0x3D00_1C59'u32, -128)),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv2Output, blaiMnistTensorInt8, 4,
      [1'u32, 4, 4, 48], 0,
      blaiMnistTfliteQuantization(0x3CED_38F0'u32, -128)),
    blaiMnistTfliteTensor(
      blaiMnistTensorConv3Output, blaiMnistTensorInt8, 4,
      [1'u32, 2, 2, 48], 0,
      blaiMnistTfliteQuantization(0x3D32_9B4F'u32, -128)),
    blaiMnistTfliteTensor(
      blaiMnistTensorReshapeOutput, blaiMnistTensorInt8, 2,
      [1'u32, 192, 0, 0], 0,
      blaiMnistTfliteQuantization(0x3D32_9B4F'u32, -128)),
    blaiMnistTfliteTensor(
      blaiMnistTensorOutput, blaiMnistTensorInt8, 2,
      [1'u32, 10, 0, 0], 0,
      blaiMnistTfliteQuantization(0x3E99_258E'u32, 4))]
  result.operators = [
    blaiMnistTfliteOperator(blaiMnistOpConv2d, 3, [0'u32, 2, 3], 12),
    blaiMnistTfliteOperator(blaiMnistOpConv2d, 3, [12'u32, 4, 5], 13),
    blaiMnistTfliteOperator(blaiMnistOpConv2d, 3, [13'u32, 6, 7], 14),
    blaiMnistTfliteOperator(blaiMnistOpConv2d, 3, [14'u32, 8, 9], 15),
    blaiMnistTfliteOperator(blaiMnistOpReshape, 2, [15'u32, 1, 0], 16),
    blaiMnistTfliteOperator(blaiMnistOpFullyConnected, 3, [16'u32, 10, 11], 17)]
  result.valid =
    result.version == 3'u32 and result.tensorCount == 18'u32 and
    result.operatorCount == 6'u32 and result.inputTensor == 0'u32 and
      result.outputTensor == 17'u32 and
      result.persistentTensorBufferBytes == 36300'u32

proc blaiMnistOperatorMatches(
    op: BlaiMnistTfliteOperator,
    kind: BlaiMnistTfliteOperatorKind,
    inputCount: uint32,
    inputs: array[3, uint32],
    output: uint32): bool =
  op.kind == kind and op.inputCount == inputCount and op.inputs == inputs and
    op.outputCount == 1'u32 and op.outputs[0] == output

proc blaiMnistTflitePersistentBuffersIdentified*(
    model: BlaiMnistTfliteModelPlan): bool =
  ## Check the fetched-MNIST persistent buffers by size and SHA-256 identity.
  model.tensors[1].bufferBytes == 8'u32 and
    model.tensors[1].bufferDigest == BlaiMnistTfliteReshapeConstDigest and
    model.tensors[2].bufferBytes == 108'u32 and
    model.tensors[2].bufferDigest == BlaiMnistTfliteConv0WeightDigest and
    model.tensors[3].bufferBytes == 48'u32 and
    model.tensors[3].bufferDigest == BlaiMnistTfliteConv0BiasDigest and
    model.tensors[4].bufferBytes == 2592'u32 and
    model.tensors[4].bufferDigest == BlaiMnistTfliteConv1WeightDigest and
    model.tensors[5].bufferBytes == 96'u32 and
    model.tensors[5].bufferDigest == BlaiMnistTfliteConv1BiasDigest and
    model.tensors[6].bufferBytes == 10368'u32 and
    model.tensors[6].bufferDigest == BlaiMnistTfliteConv2WeightDigest and
    model.tensors[7].bufferBytes == 192'u32 and
    model.tensors[7].bufferDigest == BlaiMnistTfliteConv2BiasDigest and
    model.tensors[8].bufferBytes == 20736'u32 and
    model.tensors[8].bufferDigest == BlaiMnistTfliteConv3WeightDigest and
    model.tensors[9].bufferBytes == 192'u32 and
    model.tensors[9].bufferDigest == BlaiMnistTfliteConv3BiasDigest and
    model.tensors[10].bufferBytes == 1920'u32 and
    model.tensors[10].bufferDigest == BlaiMnistTfliteFcWeightDigest and
    model.tensors[11].bufferBytes == 40'u32 and
    model.tensors[11].bufferDigest == BlaiMnistTfliteFcBiasDigest

proc blaiMnistTfliteSupportPlan*(
    model: BlaiMnistTfliteModelPlan): BlaiMnistTfliteSupportPlan =
  ## Classify the fetched MNIST model against the current pure-Nim TFLite path.
  ##
  ## The recovered TFLite activation planner and CPU-reference dispatch cover
  ## the convolution, reshape, and FullyConnected portions represented here.
  ## Hardware output equivalence is still reported as pending until live MNIST
  ## completion and output comparison are recovered.
  result.persistentBuffersIdentified =
    blaiMnistTflitePersistentBuffersIdentified(model)
  result.metadataValid =
    model.valid and model.modelBytes == 40208'u32 and
      model.tensorCount == 18'u32 and model.operatorCount == 6'u32 and
      model.inputTensor == 0'u32 and model.outputTensor == 17'u32 and
      model.persistentTensorBufferBytes == 36300'u32 and
      result.persistentBuffersIdentified
  result.firstUnsupportedOperator = 0xFFFF_FFFF'u32
  result.firstUnsupportedKind = blaiMnistOpConv2d
  result.supportBlock = blaiMnistTfliteNoSupportBlock

  if not result.metadataValid:
    result.supportBlock = blaiMnistTfliteInvalidModel
    result.firstUnsupportedOperator = 0'u32
    return

  result.convolutionOperatorsSupported =
    blaiMnistOperatorMatches(
      model.operators[0], blaiMnistOpConv2d, 3, [0'u32, 2, 3], 12) and
    blaiMnistOperatorMatches(
      model.operators[1], blaiMnistOpConv2d, 3, [12'u32, 4, 5], 13) and
    blaiMnistOperatorMatches(
      model.operators[2], blaiMnistOpConv2d, 3, [13'u32, 6, 7], 14) and
    blaiMnistOperatorMatches(
      model.operators[3], blaiMnistOpConv2d, 3, [14'u32, 8, 9], 15)
  result.reshapeOperatorSupported =
    blaiMnistOperatorMatches(
      model.operators[4], blaiMnistOpReshape, 2, [15'u32, 1, 0], 16)
  result.fullyConnectedOperatorPresent =
    blaiMnistOperatorMatches(
      model.operators[5], blaiMnistOpFullyConnected, 3, [16'u32, 10, 11], 17)

  if not result.convolutionOperatorsSupported:
    result.supportBlock = blaiMnistTfliteUnexpectedGraph
    result.firstUnsupportedOperator = 0'u32
    return
  if not result.reshapeOperatorSupported:
    result.supportBlock = blaiMnistTfliteUnexpectedGraph
    result.firstUnsupportedOperator = 4'u32
    result.firstUnsupportedKind = blaiMnistOpReshape
    return
  if result.fullyConnectedOperatorPresent:
    result.fullyConnectedReferenceSupported = true
    result.parsedReferenceRunnable = true
    result.supportBlock = blaiMnistTfliteNpuOutputValidationPending
    result.firstUnsupportedOperator = 0xFFFF_FFFF'u32
    result.firstUnsupportedKind = blaiMnistOpFullyConnected
    result.npuOutputValidated = false
    result.runnable = false
    return

  result.supportBlock = blaiMnistTfliteUnexpectedGraph
  result.firstUnsupportedOperator = 5'u32
  result.firstUnsupportedKind = blaiMnistOpFullyConnected

proc blaiMnistTfliteSupportPlan*(): BlaiMnistTfliteSupportPlan =
  ## Classify the built-in fetched-MNIST model projection.
  blaiMnistTfliteSupportPlan(blaiMnistTfliteModelPlan())

proc blaiDivOrZero(value, divisor: uint32): uint32 =
  if divisor == 0'u32: 0'u32 else: value div divisor

proc blaiExtraDescriptor*(layer: BlaiCpuInstLayer64): BlaiNpuExtraDescriptor =
  ## Build the recovered `inst_extra` side instruction fields from a CPU-layer
  ## ABI object.
  let
    inputChannels = nonNegativeU32(layer.c)
    outputChannels = nonNegativeU32(layer.outC)
    groups = max(nonNegativeU32(layer.groups), 1'u32)
  result.isExtra = true
  result.inSegW = nonNegativeU32(layer.w)
  result.outSegW = nonNegativeU32(layer.outW)
  result.outW = nonNegativeU32(layer.outW)
  result.inGroupC = blaiDivOrZero(inputChannels, groups)
  result.outGroupC = blaiDivOrZero(outputChannels, groups)
  result.outSegC = outputChannels
  result.outH = nonNegativeU32(layer.outH)
  result.stride = nonNegativeU32(layer.stride)
  result.dilation = nonNegativeU32(layer.dilation)
  result.leftShift = layer.tfLeftShift

proc blaiCommonControlDescriptor*(layerType: BlaiLayerType): BlaiNpuCommonDescriptor =
  ## Build the recovered common descriptor operation bits for a layer type.
  case layerType
  of blaiConvolutional:
    result.macBit = 1
  of blaiRouteConv:
    result.routeBit = true
    result.macBit = 1
  of blaiConvMax:
    result.maxCheck = true
    result.macBit = 1
  of blaiMaxpool:
    result.maxCheck = true
  of blaiRoute:
    result.routeBit = true
  of blaiRouteMax:
    result.maxCheck = true
    result.routeBit = true
  of blaiShortcut:
    result.macBit = 2
  of blaiMatmul:
    result.macBit = 3
  of blaiUpsample:
    result.upsampleBit = true
  of blaiRouteUpsample:
    result.routeBit = true
    result.upsampleBit = true
  else:
    discard

proc blaiFetchMemoryInputSlotCursor*(slot: uint32): BlaiU32ArrayIndexCursor =
  ## Resolve a fetch memory input slot to bounded plan storage.
  blaiU32ArrayIndexCursor(slot, BlaiMaxInputNum)

proc blaiFetchInputStorageCursor*(inputIndex: uint32,
                                  inputStorageLen: int): BlaiU32ArrayIndexCursor =
  ## Resolve a fetch input index to bounded caller-owned input storage.
  blaiU32ArrayIndexCursor(inputIndex, inputStorageLen)

proc blaiNpuCommonInputSlotCursor*(slot: uint32): BlaiU32ArrayIndexCursor =
  ## Resolve a common descriptor input slot to bounded fetch-plan storage.
  blaiFetchMemoryInputSlotCursor(slot)

proc blaiNpuCommonMemorySlots*(
    plan: BlaiFetchMemoryPlan): BlaiNpuCommonMemorySlots =
  ## Project the recovered fetch SRAM slot plan into common descriptor slots.
  let firstInput = blaiNpuCommonInputSlotCursor(0'u32)
  let secondInput = blaiNpuCommonInputSlotCursor(1'u32)
  if plan.inputCount > 0'u32:
    doAssert firstInput.valid
    result.inLayer1Mem = plan.inputSlots[firstInput.index]
  if plan.inputCount > 1'u32:
    doAssert secondInput.valid
    result.inLayer2Mem = plan.inputSlots[secondInput.index]
  result.outLayerMem = plan.outputSlot
  result.midLayerMem = plan.midOutputSlot
  result.valid = true

proc blaiApplyCommonMemorySlots*(common: var BlaiNpuCommonDescriptor,
                                 slots: BlaiNpuCommonMemorySlots) =
  ## Apply a typed SRAM slot projection to the descriptor's memory fields.
  doAssert slots.valid
  common.inLayer1Mem = slots.inLayer1Mem
  common.inLayer2Mem = slots.inLayer2Mem
  common.outLayerMem = slots.outLayerMem
  common.midLayerMem = slots.midLayerMem

proc blaiCommonDescriptor*(layer: BlaiCpuInstLayer64,
                           plan: BlaiFetchMemoryPlan,
                           descriptorHalt: bool = false,
                           midOutState: bool = false): BlaiNpuCommonDescriptor =
  ## Build recovered common descriptor fields from CPU-layer ABI and fetch plan.
  result = blaiCommonControlDescriptor(blaiLayerTypeFromSdk(layer.layerType))
  result.imgIn = layer.imgIn != 0
  let slots = blaiNpuCommonMemorySlots(plan)
  blaiApplyCommonMemorySlots(result, slots)
  result.midOut = layer.midOut != 0
  result.midOutState = midOutState
  result.halt = descriptorHalt
  result.instEndBit = layer.halt != 0

proc blaiFetchDescriptorC2*(layer: BlaiCpuInstLayer64,
                            kind: BlaiFetchMemoryKind): uint32 =
  ## Recover the `layer_c2` operand visible in `fetch_BLAI_data_*`.
  case kind
  of blaiFetchGeneral:
    if nonNegativeU32(layer.n) > 1'u32:
      blaiChannelAlign4(nonNegativeU32(blaiLayerCn(layer, 1'u32)))
    else:
      0'u32
  of blaiFetchRoute:
    if nonNegativeU32(layer.inputNum) > 1'u32:
      blaiChannelAlign4(nonNegativeU32(blaiLayerCn(layer, 1'u32)))
    else:
      0'u32

proc blaiFetchDescriptorNeedsExtra*(layer: BlaiCpuInstLayer64,
                                    ctrl: BlaiPsramCtrl): bool =
  ## Recover the `extra_info` decision before SDK `instruction_encode`.
  let layerType = blaiLayerTypeFromSdk(layer.layerType)
  if layerType in {blaiConvMax, blaiRouteMax} and
     nonNegativeU32(layer.stride) == 1'u32 and
     nonNegativeU32(layer.size) > 3'u32:
    return nonNegativeU32(ctrl.linePatchCount) > 1'u32

  nonNegativeU32(ctrl.weightPatchCount) > 1'u32 or
    nonNegativeU32(ctrl.linePatchCount) > 1'u32 or
    nonNegativeU32(layer.groups) > 1'u32 or
    nonNegativeU32(layer.stride) > 1'u32 or
    nonNegativeU32(layer.dilation) > 1'u32

proc blaiPlanFetchDescriptorOperandsInto*(
    layer: BlaiCpuInstLayer64,
    ctrl: BlaiPsramCtrl,
    kind: BlaiFetchMemoryKind,
    outResult: var BlaiFetchDescriptorOperands) =
  ## Plan descriptor operands recovered from the front of `fetch_BLAI_data_*`.
  outResult = default(BlaiFetchDescriptorOperands)
  outResult.kind = kind
  outResult.layerType = blaiLayerTypeFromSdk(layer.layerType)
  case kind
  of blaiFetchGeneral:
    outResult.multiInputC2 = nonNegativeU32(layer.n) > 1'u32
  of blaiFetchRoute:
    outResult.multiInputC2 = nonNegativeU32(layer.inputNum) > 1'u32
  outResult.alignedFirstInputChannels =
    blaiChannelAlign4(nonNegativeU32(blaiLayerCn(layer, 1'u32)))
  if outResult.multiInputC2:
    outResult.c2 = outResult.alignedFirstInputChannels

  outResult.weightPatchExtra = nonNegativeU32(ctrl.weightPatchCount) > 1'u32
  outResult.linePatchExtra = nonNegativeU32(ctrl.linePatchCount) > 1'u32
  outResult.groupedExtra = nonNegativeU32(layer.groups) > 1'u32
  outResult.strideExtra = nonNegativeU32(layer.stride) > 1'u32
  outResult.dilationExtra = nonNegativeU32(layer.dilation) > 1'u32
  outResult.maxPoolLinePatchExtra =
    outResult.layerType in {blaiConvMax, blaiRouteMax} and
    nonNegativeU32(layer.stride) == 1'u32 and
    nonNegativeU32(layer.size) > 3'u32 and
    outResult.linePatchExtra
  if outResult.layerType in {blaiConvMax, blaiRouteMax} and
     nonNegativeU32(layer.stride) == 1'u32 and
     nonNegativeU32(layer.size) > 3'u32:
    outResult.includeExtra = outResult.maxPoolLinePatchExtra
  else:
    outResult.includeExtra = outResult.weightPatchExtra or
      outResult.linePatchExtra or outResult.groupedExtra or
      outResult.strideExtra or outResult.dilationExtra

proc blaiPlanFetchDescriptorOperands*(
    layer: BlaiCpuInstLayer64,
    ctrl: BlaiPsramCtrl,
    kind: BlaiFetchMemoryKind): BlaiFetchDescriptorOperands =
  ## Convenience result-returning wrapper for fetch descriptor operands.
  blaiPlanFetchDescriptorOperandsInto(layer, ctrl, kind, result)

proc blaiRouteDescriptorNextInputCursor*(
    stepIndex, inputNum: uint32): BlaiRouteDescriptorNextInputCursor =
  ## Resolve the recovered route step to the next logical input channel slot.
  if stepIndex == high(uint32):
    return
  let stepCursor = blaiRouteDescriptorStepCursor(stepIndex)
  if not stepCursor.valid:
    return
  result.stepIndex = stepIndex
  result.logicalInput = stepIndex + 1'u32
  result.cnSlot = stepCursor.index
  result.hasChannels = result.logicalInput < inputNum
  result.valid = true

proc blaiRouteDescriptorLoopCount*(
    rawInputCount: uint32): BlaiRouteDescriptorLoopCount =
  ## Recover the route descriptor count from the SDK input count.
  let inputCount = max(rawInputCount, 2'u32)
  if inputCount > BlaiMaxInputNumU32:
    return

  let descriptorCount = inputCount - 1'u32
  if descriptorCount == 0'u32 or descriptorCount > BlaiMaxRouteInputNumU32:
    return

  result.rawInputCount = rawInputCount
  result.inputCount = inputCount
  result.descriptorCount = descriptorCount
  result.lastStepIndex = descriptorCount - 1'u32
  result.valid = true

proc blaiPlanRouteDescriptorLoopInto*(
    layer: BlaiCpuInstLayer64,
    outResult: var BlaiRouteDescriptorLoopPlan) =
  ## Recover the channel-carrying loop in `fetch_BLAI_data_route`.
  ##
  ## The SDK emits one descriptor for each additional route input. Each
  ## iteration starts from the cumulative channel count so far, uses the next
  ## input channel count as the descriptor's second channel operand, then carries
  ## the sum into the next iteration.
  outResult = default(BlaiRouteDescriptorLoopPlan)
  let loopCount = blaiRouteDescriptorLoopCount(nonNegativeU32(layer.inputNum))
  if not loopCount.valid:
    return

  outResult.count = loopCount
  outResult.inputCount = loopCount.inputCount
  outResult.descriptorCount = loopCount.descriptorCount
  var cumulative = nonNegativeU32(layer.c)
  for index in 0'u32 ..< outResult.descriptorCount:
    let nextInput = blaiRouteDescriptorNextInputCursor(
      index, nonNegativeU32(layer.inputNum))
    if not nextInput.valid:
      return
    let nextChannels =
      if nextInput.hasChannels:
        nonNegativeU32(layer.cn[nextInput.cnSlot])
      else:
        0'u32
    outResult.steps[nextInput.cnSlot] = BlaiRouteDescriptorStep(
      index: index,
      cumulativeInputChannels: cumulative,
      nextInputChannels: nextChannels,
      descriptorC1: cumulative,
      descriptorC2: nextChannels,
      cumulativeOutputChannels: cumulative + nextChannels)
    cumulative += nextChannels
  outResult.fits = true

proc blaiPlanRouteDescriptorLoop*(
    layer: BlaiCpuInstLayer64): BlaiRouteDescriptorLoopPlan =
  ## Convenience result-returning wrapper for route descriptor-loop planning.
  blaiPlanRouteDescriptorLoopInto(layer, result)

proc blaiRouteDescriptorStepPosition*(
    stepIndex: uint32,
    loopCount: BlaiRouteDescriptorLoopCount): BlaiRouteDescriptorStepPosition =
  ## Resolve a recovered route descriptor-loop step and whether it is terminal.
  if not loopCount.valid:
    return
  if stepIndex >= loopCount.descriptorCount:
    return
  let stepCursor = blaiRouteDescriptorStepCursor(stepIndex)
  if not stepCursor.valid:
    return
  result.stepIndex = stepIndex
  result.stepSlot = stepCursor.index
  result.last = stepIndex == loopCount.lastStepIndex
  result.valid = true

proc blaiRouteDescriptorStepPosition*(
    stepIndex, descriptorCount: uint32): BlaiRouteDescriptorStepPosition =
  ## Compatibility wrapper for callers that only have the descriptor count.
  if descriptorCount == 0'u32 or descriptorCount == high(uint32):
    return
  let loopCount = blaiRouteDescriptorLoopCount(descriptorCount + 1'u32)
  if loopCount.descriptorCount != descriptorCount:
    return
  blaiRouteDescriptorStepPosition(stepIndex, loopCount)

proc blaiLayerInstructionBundle*(layer: BlaiCpuInstLayer64,
                                 plan: BlaiFetchMemoryPlan,
                                 useTflite: bool,
                                 c2: uint32 = 0'u32,
                                 includeExtra: bool = false,
                                 descriptorHalt: bool = false,
                                 midOutState: bool = false): BlaiNpuInstructionBundle =
  ## Build the recovered descriptor bundle from a CPU-layer ABI object.
  ##
  ## `c2` and `includeExtra` remain explicit for callers that already resolved
  ## the surrounding `fetch_BLAI_data_*` operand decisions.
  let common = blaiCommonDescriptor(layer, plan, descriptorHalt, midOutState)
  let extra =
    if includeExtra: blaiExtraDescriptor(layer) else: BlaiNpuExtraDescriptor()
  if useTflite:
    blaiTfliteInstructionBundle(
      blaiTfliteDescriptor(layer, c2),
      common,
      blaiTfliteQuantDescriptor(layer),
      extra)
  else:
    blaiNormalInstructionBundle(
      blaiNormalDescriptor(layer, c2),
      common,
      extra)

proc blaiLayerInstructionBundle*(layer: BlaiCpuInstLayer64,
                                 plan: BlaiFetchMemoryPlan,
                                 useTflite: bool,
                                 operands: BlaiFetchDescriptorOperands,
                                 descriptorHalt: bool = false,
                                 midOutState: bool = false): BlaiNpuInstructionBundle =
  ## Build the descriptor bundle using recovered fetch operand decisions.
  blaiLayerInstructionBundle(
    layer, plan, useTflite, operands.c2, operands.includeExtra,
    descriptorHalt, midOutState)

proc blaiInstructionEncodeRequiredInto*(bundle: BlaiNpuInstructionBundle,
                                        outResult: var BlaiInstructionEncodeCountResult)
proc blaiInstructionEncodeRequired*(bundle: BlaiNpuInstructionBundle): uint32
proc blaiInstructionEmittedCountEvidence*(
    bundle: BlaiNpuInstructionBundle,
    emitted: uint32): BlaiInstructionEmittedCountEvidence
proc blaiInstructionStreamCommitEvidence*(
    streamLen, startCount, emitted: uint32): BlaiInstructionStreamCommitEvidence

proc blaiEncodeInstructionsInto*(bundle: BlaiNpuInstructionBundle,
                                 stream: var openArray[BlaiInstruction],
                                 startCount: uint32,
                                 outResult: var BlaiInstructionEncodeResult)

proc blaiEncodeInstructions*(bundle: BlaiNpuInstructionBundle,
                             stream: var openArray[BlaiInstruction],
                             startCount: uint32): BlaiInstructionEncodeResult

proc blaiRouteSramSlotCursor*(slot: uint32): BlaiU32ArrayIndexCursor =
  ## Resolve a recovered route SRAM slot to fixed route slot storage.
  blaiU32ArrayIndexCursor(slot, BlaiMaxInputNum)

proc blaiRouteSlotCursor*(slot: uint32): BlaiRouteSlotCursor =
  ## Resolve a recovered route slot number into a bounded Nim array index.
  let cursor = blaiRouteSramSlotCursor(slot)
  if not cursor.valid:
    return
  result.slotIndex = cursor.index
  result.valid = true

proc blaiRouteNextSlotIndex*(slot: uint32): BlaiRouteNextSlotIndex =
  ## Resolve the recovered route descriptor next-input slot projection.
  if slot == high(uint32):
    return
  let routeSlot = slot + 1'u32
  let cursor = blaiRouteSlotCursor(routeSlot)
  if not cursor.valid:
    return
  result.routeSlot = routeSlot
  result.slotIndex = cursor.slotIndex
  result.valid = true

proc blaiRouteNextSlotCursor*(slot: uint32): BlaiRouteSlotCursor =
  ## Resolve the recovered `slot + 1` route descriptor/SRAM convention.
  let nextSlot = blaiRouteNextSlotIndex(slot)
  if not nextSlot.valid:
    return
  result.slotIndex = nextSlot.slotIndex
  result.valid = true

proc blaiRoutePreviousOutputSlotIndex*(
    stepIndex, outputSlotCount: uint32): BlaiRoutePreviousOutputSlotIndex =
  ## Resolve the recovered previous route output slot for a descriptor step.
  if stepIndex == 0'u32:
    return
  let outputSlot = stepIndex - 1'u32
  if outputSlot >= outputSlotCount:
    return
  result.stepIndex = stepIndex
  result.outputSlotCount = outputSlotCount
  result.outputSlot = outputSlot
  result.valid = true

proc blaiRoutePreviousOutputSlotCursor*(
    stepIndex, outputSlotCount: uint32): BlaiRoutePreviousOutputSlotCursor =
  ## Resolve the previous route output slot for non-initial descriptor steps.
  let outputSlot = blaiRoutePreviousOutputSlotIndex(stepIndex, outputSlotCount)
  if not outputSlot.valid:
    return
  let cursor = blaiRouteSlotCursor(outputSlot.outputSlot)
  if not cursor.valid:
    return
  result.outputSlot = outputSlot.outputSlot
  result.slotIndex = cursor.slotIndex
  result.valid = true

proc blaiRouteOutputSlotCursor*(
    stepIndex, cursor, outputW, outputH, cumulativeChannels,
    patchSize: uint32): BlaiRouteOutputSlotCursor =
  ## Resolve one recovered intermediate route output slot and cursor advance.
  if patchSize == 0'u32:
    return
  let outputSlot = blaiRouteNextSlotCursor(stepIndex)
  if not outputSlot.valid:
    return
  let elements =
    outputW.uint64 * outputH.uint64 * cumulativeChannels.uint64
  var outputElements: uint32
  if not blaiU64ExactU32Count(elements, outputElements):
    return
  let patchCount = blaiCeilDivU32(outputElements, patchSize)
  if patchCount > high(uint32) - cursor:
    return
  result.stepIndex = stepIndex
  result.slotIndex = outputSlot.slotIndex
  result.slot = cursor
  result.outputElements = outputElements
  result.patchCount = patchCount
  result.nextCursor = cursor + patchCount
  result.valid = true

proc blaiRouteStepFetchMemoryPlan(plan: BlaiFetchMemoryPlan,
                                  step: BlaiRouteDescriptorStep): BlaiFetchMemoryPlan =
  result = plan
  result.inputCount = 2
  let firstInput = blaiFetchMemoryInputSlotCursor(0'u32)
  let secondInput = blaiFetchMemoryInputSlotCursor(1'u32)
  doAssert firstInput.valid
  doAssert secondInput.valid
  result.inputSlots[firstInput.index] =
    if step.index == 0'u32:
      plan.inputSlots[firstInput.index]
    else:
      plan.outputSlot
  let nextInput = blaiRouteNextSlotCursor(step.index)
  if nextInput.valid:
    result.inputSlots[secondInput.index] = plan.inputSlots[nextInput.slotIndex]
  else:
    result.inputSlots[secondInput.index] = 0
  result.outputSlot = plan.outputSlot

proc blaiRouteStepFetchMemoryPlan(plan: BlaiRouteSramSlotPlan,
                                  step: BlaiRouteDescriptorStep): BlaiFetchMemoryPlan =
  result = plan.memory
  result.inputCount = 2
  let previousOutput = blaiRoutePreviousOutputSlotCursor(
    step.index, plan.outputSlotCount)
  let firstInput = blaiFetchMemoryInputSlotCursor(0'u32)
  let secondInput = blaiFetchMemoryInputSlotCursor(1'u32)
  doAssert firstInput.valid
  doAssert secondInput.valid
  result.inputSlots[firstInput.index] =
    if step.index == 0'u32:
      plan.memory.inputSlots[firstInput.index]
    elif previousOutput.valid:
      plan.outputSlots[previousOutput.slotIndex]
    else:
      0
  let nextInput = blaiRouteNextSlotCursor(step.index)
  if nextInput.valid:
    result.inputSlots[secondInput.index] =
      plan.memory.inputSlots[nextInput.slotIndex]
  else:
    result.inputSlots[secondInput.index] = 0
  result.outputSlot =
    if step.index < plan.outputSlotCount:
      let currentOutput = blaiRouteSlotCursor(step.index)
      if currentOutput.valid: plan.outputSlots[currentOutput.slotIndex] else: 0'u32
    else:
      plan.memory.outputSlot

proc blaiRouteInstructionStepCoreEvidence*(
    layer: BlaiCpuInstLayer64,
    routeLoop: BlaiRouteDescriptorLoopPlan,
    stepIndex: uint32): BlaiRouteInstructionStepCoreEvidence =
  ## Recover checked route step position and staged layer state.
  result.position =
    blaiRouteDescriptorStepPosition(stepIndex, routeLoop.count)
  if not result.position.valid:
    return
  result.step = routeLoop.steps[result.position.stepSlot]
  result.stepLayerApply = blaiRouteDescriptorLayerApplyPlan(result.step)
  if not result.stepLayerApply.valid:
    return
  result.stagedLayer = layer
  blaiApplyRouteDescriptorLayerState(
    result.stagedLayer,
    blaiRouteDescriptorLayerState(result.stepLayerApply))
  result.valid = true

proc blaiRouteInstructionStepEvidence*(
    core: BlaiRouteInstructionStepCoreEvidence,
    stepPlan: BlaiFetchMemoryPlan,
    useTflite: bool,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiRouteInstructionStepEvidence =
  ## Build one checked route descriptor instruction bundle from core evidence.
  if not core.valid:
    return
  result.position = core.position
  result.step = core.step
  result.stepLayerApply = core.stepLayerApply
  result.stepPlan = stepPlan
  result.bundle = blaiLayerInstructionBundle(
    core.stagedLayer, result.stepPlan, useTflite,
    c2 = result.step.descriptorC2,
    includeExtra = includeExtra,
    descriptorHalt = descriptorHalt and result.position.last,
    midOutState = midOutState)
  result.valid = true

proc blaiRouteInstructionStepEvidence*(
    layer: BlaiCpuInstLayer64,
    plan: BlaiFetchMemoryPlan,
    routeLoop: BlaiRouteDescriptorLoopPlan,
    stepIndex: uint32,
    useTflite: bool,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiRouteInstructionStepEvidence =
  ## Build one checked route descriptor instruction bundle.
  let core = blaiRouteInstructionStepCoreEvidence(layer, routeLoop, stepIndex)
  if not core.valid:
    return
  let stepPlan = blaiRouteStepFetchMemoryPlan(plan, core.step)
  result = blaiRouteInstructionStepEvidence(
    core, stepPlan, useTflite, includeExtra, descriptorHalt, midOutState)

proc blaiRouteInstructionStepEvidence*(
    layer: BlaiCpuInstLayer64,
    plan: BlaiRouteSramSlotPlan,
    routeLoop: BlaiRouteDescriptorLoopPlan,
    stepIndex: uint32,
    useTflite: bool,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiRouteInstructionStepEvidence =
  ## Build one checked route descriptor instruction bundle with route SRAM slots.
  let core = blaiRouteInstructionStepCoreEvidence(layer, routeLoop, stepIndex)
  if not core.valid:
    return
  let stepPlan = blaiRouteStepFetchMemoryPlan(plan, core.step)
  result = blaiRouteInstructionStepEvidence(
    core, stepPlan, useTflite, includeExtra, descriptorHalt, midOutState)

proc blaiEmitRouteLayerInstructionsInto*(layer: var BlaiCpuInstLayer64,
                                         plan: BlaiFetchMemoryPlan,
                                         stream: var openArray[BlaiInstruction],
                                         useTflite: bool,
                                         outResult: var BlaiInstructionEncodeResult,
                                         includeExtra: bool = false,
                                         descriptorHalt: bool = false,
                                         midOutState: bool = false) =
  ## Emit the recovered `fetch_BLAI_data_route` descriptor loop.
  ##
  ## This bounded helper uses the recovered route channel-carrying loop and the
  ## existing descriptor bundle encoder. The overload accepting
  ## `BlaiRouteSramSlotPlan` is used by the default fetch wrapper for recovered
  ## per-step route output slots.
  outResult = default(BlaiInstructionEncodeResult)
  var routeLoop: BlaiRouteDescriptorLoopPlan
  blaiPlanRouteDescriptorLoopInto(layer, routeLoop)
  outResult.startCount = nonNegativeU32(layer.instCnt)
  if not routeLoop.fits:
    outResult.endCount = outResult.startCount
    return

  for stepIndex in 0'u32 ..< routeLoop.descriptorCount:
    let stepEvidence = blaiRouteInstructionStepEvidence(
      layer, plan, routeLoop, stepIndex, useTflite, includeExtra,
      descriptorHalt, midOutState)
    if not stepEvidence.valid:
      outResult.endCount = outResult.startCount
      return
    let emittedEvidence =
      blaiInstructionEmittedCountEvidence(stepEvidence.bundle, outResult.emitted)
    if not emittedEvidence.valid:
      outResult.endCount = outResult.startCount
      return
    outResult.emitted = emittedEvidence.emitted

  let commitEvidence = blaiInstructionStreamCommitEvidence(
    blaiOpenArrayLenU32(stream), outResult.startCount, outResult.emitted)
  outResult.endCount = commitEvidence.endCount
  outResult.fits = commitEvidence.fits
  if not commitEvidence.valid:
    outResult.endCount = outResult.startCount
    outResult.fits = false
    return

  var count = outResult.startCount
  for stepIndex in 0'u32 ..< routeLoop.descriptorCount:
    let stepEvidence = blaiRouteInstructionStepEvidence(
      layer, plan, routeLoop, stepIndex, useTflite, includeExtra,
      descriptorHalt, midOutState)
    if not stepEvidence.valid:
      blaiApplyInstructionCountState(
        layer, blaiInstructionCountState(commitEvidence.startCountApply))
      return
    var encoded: BlaiInstructionEncodeResult
    blaiEncodeInstructionsInto(stepEvidence.bundle, stream, count, encoded)
    doAssert encoded.fits
    count = encoded.endCount
  blaiApplyInstructionCountState(
    layer, blaiInstructionCountState(commitEvidence.endCountApply))

proc blaiEmitRouteLayerInstructions*(layer: var BlaiCpuInstLayer64,
                                     plan: BlaiFetchMemoryPlan,
                                     stream: var openArray[BlaiInstruction],
                                     useTflite: bool,
                                     includeExtra: bool = false,
                                     descriptorHalt: bool = false,
                                     midOutState: bool = false):
                                     BlaiInstructionEncodeResult {.
                                       exportc: "blaiEmitRouteLayerInstructionsMemory".} =
  ## Convenience result-returning wrapper for route descriptor-loop emission.
  blaiEmitRouteLayerInstructionsInto(
    layer, plan, stream, useTflite, result, includeExtra, descriptorHalt,
    midOutState)

proc blaiEmitRouteLayerInstructionsInto*(layer: var BlaiCpuInstLayer64,
                                         plan: BlaiRouteSramSlotPlan,
                                         stream: var openArray[BlaiInstruction],
                                         useTflite: bool,
                                         outResult: var BlaiInstructionEncodeResult,
                                         includeExtra: bool = false,
                                         descriptorHalt: bool = false,
                                         midOutState: bool = false) =
  ## Emit `fetch_BLAI_data_route` descriptors using recovered SRAM_out slots.
  outResult = default(BlaiInstructionEncodeResult)
  var routeLoop: BlaiRouteDescriptorLoopPlan
  blaiPlanRouteDescriptorLoopInto(layer, routeLoop)
  outResult.startCount = nonNegativeU32(layer.instCnt)
  if not routeLoop.fits or not plan.fits or
      plan.outputSlotCount < routeLoop.descriptorCount:
    outResult.endCount = outResult.startCount
    return

  for stepIndex in 0'u32 ..< routeLoop.descriptorCount:
    let stepEvidence = blaiRouteInstructionStepEvidence(
      layer, plan, routeLoop, stepIndex, useTflite, includeExtra,
      descriptorHalt, midOutState)
    if not stepEvidence.valid:
      outResult.endCount = outResult.startCount
      return
    let emittedEvidence =
      blaiInstructionEmittedCountEvidence(stepEvidence.bundle, outResult.emitted)
    if not emittedEvidence.valid:
      outResult.endCount = outResult.startCount
      return
    outResult.emitted = emittedEvidence.emitted

  let commitEvidence = blaiInstructionStreamCommitEvidence(
    blaiOpenArrayLenU32(stream), outResult.startCount, outResult.emitted)
  outResult.endCount = commitEvidence.endCount
  outResult.fits = commitEvidence.fits
  if not commitEvidence.valid:
    outResult.endCount = outResult.startCount
    outResult.fits = false
    return

  var count = outResult.startCount
  for stepIndex in 0'u32 ..< routeLoop.descriptorCount:
    let stepEvidence = blaiRouteInstructionStepEvidence(
      layer, plan, routeLoop, stepIndex, useTflite, includeExtra,
      descriptorHalt, midOutState)
    if not stepEvidence.valid:
      blaiApplyInstructionCountState(
        layer, blaiInstructionCountState(commitEvidence.startCountApply))
      return
    var encoded: BlaiInstructionEncodeResult
    blaiEncodeInstructionsInto(stepEvidence.bundle, stream, count, encoded)
    doAssert encoded.fits
    count = encoded.endCount
  blaiApplyInstructionCountState(
    layer, blaiInstructionCountState(commitEvidence.endCountApply))

proc blaiEmitRouteLayerInstructions*(layer: var BlaiCpuInstLayer64,
                                     plan: BlaiRouteSramSlotPlan,
                                     stream: var openArray[BlaiInstruction],
                                     useTflite: bool,
                                     includeExtra: bool = false,
                                     descriptorHalt: bool = false,
                                     midOutState: bool = false):
                                     BlaiInstructionEncodeResult {.
                                       exportc: "blaiEmitRouteLayerInstructionsSlots".} =
  ## Convenience result-returning wrapper for route SRAM-slot emission.
  blaiEmitRouteLayerInstructionsInto(
    layer, plan, stream, useTflite, result, includeExtra, descriptorHalt,
    midOutState)

proc toDecodedLayer*(layer: BlaiCpuInstLayer64): BlaiDecodedLayer =
  ## Project the recovered SDK CPU-layer ABI into the smaller decoded-layer
  ## shape used by pure Nim eligibility and instruction-header helpers.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.w = nonNegativeU32(layer.w)
  result.h = nonNegativeU32(layer.h)
  result.c = nonNegativeU32(layer.c)
  result.cn0 = nonNegativeU32(blaiLayerCn(layer, 1'u32))
  result.outC = nonNegativeU32(layer.outC)
  result.inLayer1Mem = nonNegativeU32(layer.inLayer1Mem)
  result.inLayer2Mem = nonNegativeU32(layer.inLayer2Mem)
  result.outLayerMem = nonNegativeU32(layer.outLayerMem)
  result.fdata = nonNegativeU32(layer.fdata)
  result.fweight = nonNegativeU32(layer.fweight)
  result.fbias = nonNegativeU32(layer.fbias)
  result.froute1 = nonNegativeU32(layer.froute1)
  result.froute2 = nonNegativeU32(layer.froute2)
  result.fout = nonNegativeU32(layer.fout)
  result.size = nonNegativeU32(layer.size)
  result.activation = nonNegativeU32(layer.activation)
  result.tfOutputOffset = nonNegativeU32(layer.tfOutputOffset)
  result.stride = nonNegativeU32(layer.stride)
  result.dilation = nonNegativeU32(layer.dilation)
  result.groups = nonNegativeU32(layer.groups)
  result.halt = layer.halt != 0

proc blaiChannelAlign4*(channels: uint32): uint32 =
  ## SDK `BALI_CHN_ALIGN`: round a channel count up to a multiple of four.
  ((channels + 3'u32) shr 2) shl 2

proc blaiAlign4*(bytes: uint32): uint32 =
  ## Round a byte count up to the SDK's 4-byte allocation boundary.
  ((bytes + 3'u32) shr 2) shl 2

proc blaiCeilDivU32(numerator, denominator: uint32): uint32 =
  if denominator == 0'u32:
    0'u32
  elif numerator == 0'u32:
    0'u32
  else:
    ((numerator - 1'u32) div denominator) + 1'u32

proc blaiRoundEvenU32(value: uint32): uint32 =
  if (value and 1'u32) == 1'u32: value + 1'u32 else: value

proc blaiSaturatingSubU32(value, decrement: uint32): uint32 =
  if value > decrement: value - decrement else: 0'u32

proc blaiFloorPow2U32(value: uint32): uint32 =
  if value == 0'u32:
    return 0'u32
  result = 1
  while (result shl 1) <= value:
    result = result shl 1

proc blaiIsComboMax*(layerType: BlaiLayerType,
                     stride, size: uint32): bool =
  ## SDK `check_combomax_layer`.
  layerType == blaiMaxpool and stride == 2'u32 and size == 2'u32

proc blaiIsUpsample*(layerType: BlaiLayerType): bool =
  ## SDK `check_upsample_layer`.
  layerType in {blaiUpsample, blaiRouteUpsample}

proc blaiIsConv*(layerType: BlaiLayerType): bool =
  ## SDK `check_conv_layer`.
  layerType in {blaiConvolutional, blaiConvMax, blaiRouteConv}

proc blaiUsesWeights*(layerType: BlaiLayerType): bool =
  ## SDK `check_weight_layer`.
  layerType in {blaiConvolutional, blaiConvMax, blaiRouteConv, blaiMatmul}

proc blaiCpuLoadUsesWeights*(layerType: BlaiLayerType): bool =
  ## SDK `blai_cpu_load_weights` weight stream layer predicate.
  layerType in {blaiConvolutional, blaiMatmul, blaiConvMax, blaiRouteConv,
                blaiSsd}

proc blaiCpuLoadUsesBiases*(layerType: BlaiLayerType): bool =
  ## SDK `blai_cpu_load_weights` bias stream layer predicate.
  layerType in {blaiConvolutional, blaiMatmul, blaiConvMax, blaiRouteConv}

proc blaiIsMultiInput*(layerType: BlaiLayerType): bool =
  ## SDK `check_MultiInput_layer`.
  layerType in {blaiRouteMax, blaiRouteConv, blaiRouteUpsample, blaiRoute,
                blaiShortcut, blaiRouteW, blaiSsd}

proc blaiIsRoute*(layerType: BlaiLayerType): bool =
  ## SDK `check_route_layer`.
  layerType in {blaiRouteMax, blaiRouteConv, blaiRouteUpsample, blaiRoute,
                blaiRouteW}

proc blaiIsCombine*(layerType: BlaiLayerType): bool =
  ## SDK `check_combine_layer` / `check_merge_layer` predicate.
  layerType in {blaiConvMax, blaiRouteMax, blaiRouteConv, blaiRouteUpsample}

proc blaiMergedLayerCount*(layerCount: uint32, layerType: BlaiLayerType): uint32 =
  ## SDK `check_merge_layer` effect for one parsed layer.
  if layerCount > 0'u32 and blaiIsCombine(layerType):
    layerCount - 1'u32
  else:
    layerCount

proc blaiReleaseSlotCursor*(slot: int32): BlaiReleaseSlotCursor =
  ## Resolve one recovered release-list counter to a fixed ABI array slot.
  let cursor = blaiI32ArrayIndexCursor(slot, BlaiMaxInputNum)
  if not cursor.valid:
    return
  result.slotIndex = cursor.index
  result.valid = true

proc blaiGraphLayerMapCursor*(graphLayer: int32,
                              capacity: int): BlaiGraphLayerMapCursor =
  ## Resolve a signed graph-layer id before writing caller-owned graph maps.
  let cursor = blaiI32ArrayIndexCursor(graphLayer, capacity)
  if not cursor.valid:
    return
  result.graphLayer = graphLayer
  result.mapIndex = cursor.index
  result.valid = true

proc blaiReleaseLayerTableWindow*(
    layerCount: int): BlaiReleaseLayerTableWindow =
  ## Resolve the caller-owned release-analysis layer table bounds.
  if layerCount < 0:
    return
  result.count = layerCount
  result.highIndex = layerCount - 1
  result.valid = true

proc blaiReleaseLayerTableCursor*(
    window: BlaiReleaseLayerTableWindow,
    layerIndex: int): BlaiReleaseLayerTableCursor =
  ## Resolve one release-analysis layer row inside a checked table window.
  if not window.valid or layerIndex < 0 or layerIndex >= window.count:
    return
  result.layerIndex = layerIndex
  result.valid = true

proc blaiAppendReleaseLayer(layer: var BlaiCpuInstLayer64,
                            releasedLayer: int,
                            mid: bool): bool =
  if mid:
    let releaseCursor = blaiReleaseSlotCursor(layer.releaseMidNum)
    if not releaseCursor.valid:
      return false
    let releasedLayerAbi = blaiLayerIndexAbi(releasedLayer)
    if not releasedLayerAbi.valid:
      return false
    layer.releaseMidLayers[releaseCursor.slotIndex] = releasedLayerAbi.value
    inc layer.releaseMidNum
  else:
    let releaseCursor = blaiReleaseSlotCursor(layer.releaseNum)
    if not releaseCursor.valid:
      return false
    let releasedLayerAbi = blaiLayerIndexAbi(releasedLayer)
    if not releasedLayerAbi.valid:
      return false
    layer.releaseLayers[releaseCursor.slotIndex] = releasedLayerAbi.value
    inc layer.releaseNum
  true

proc blaiLayerConsumesGraph(layer: BlaiCpuInstLayer64,
                            graphLayer: int32): bool =
  if blaiIsMultiInput(blaiLayerTypeFromSdk(layer.layerType)):
    let inputCount = min(nonNegativeU32(layer.inputNum), BlaiMaxInputNumU32)
    for inputIndex in 0 ..< blaiBoundedU32Count(inputCount, BlaiMaxInputNum):
      if layer.inputLayers[inputIndex] == graphLayer:
        return true
  else:
    result = layer.inputLayers[0] == graphLayer

proc blaiAssignReleaseLayers*(
    layers: var openArray[BlaiCpuInstLayer64],
    graphLayerToLayer: var openArray[int32]): BlaiReleaseLayerPlan =
  ## Recover SDK `assign_release_layer` without heap allocation.
  ##
  ## The SDK builds temporary `release_layer`, `release_layer_mid`, and
  ## `graph_layer_to_layer` arrays. This proc scans the caller-owned layer table
  ## directly, fills each layer's fixed ABI release arrays, and writes the graph
  ## map into caller-owned storage.
  result.layerCount = blaiOpenArrayLenU32(layers)
  result.graphMapFits = true
  result.releaseFits = true
  result.firstGraphMapOverflowLayer = -1
  result.firstReleaseOverflowLayer = -1

  let layerWindow = blaiReleaseLayerTableWindow(layers.len)
  for graphIndex in 0 ..< graphLayerToLayer.len:
    graphLayerToLayer[graphIndex] = 0
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiReleaseLayerTableCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      return
    layers[layerCursor.layerIndex].releaseNum = 0
    layers[layerCursor.layerIndex].releaseMidNum = 0
    layers[layerCursor.layerIndex].midOut = 0

  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiReleaseLayerTableCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      return
    let layerType =
      blaiLayerTypeFromSdk(layers[layerCursor.layerIndex].layerType)
    let combineLayer = blaiIsCombine(layerType)
    var releaseLayer =
      if layerCursor.layerIndex == layerWindow.highIndex:
        layerCursor.layerIndex
      else:
        0
    var jump = false
    for consumerIndex in countdown(
        layerWindow.highIndex, layerCursor.layerIndex + 1):
      let consumerCursor =
        blaiReleaseLayerTableCursor(layerWindow, consumerIndex)
      if not consumerCursor.valid:
        return
      if blaiLayerConsumesGraph(
          layers[consumerCursor.layerIndex],
          layers[layerCursor.layerIndex].graphLayer[0]):
        releaseLayer = consumerCursor.layerIndex
        jump = true
      elif consumerCursor.layerIndex == layerCursor.layerIndex + 1:
        releaseLayer = consumerCursor.layerIndex
      if jump:
        break

    let releaseCursor = blaiReleaseLayerTableCursor(layerWindow, releaseLayer)
    if not releaseCursor.valid:
      return
    if not blaiAppendReleaseLayer(
        layers[releaseCursor.layerIndex], layerCursor.layerIndex, mid = false):
      result.releaseFits = false
      if result.firstReleaseOverflowLayer < 0:
        result.firstReleaseOverflowLayer =
          blaiLayerIndexValue(releaseCursor.layerIndex)
    else:
      inc result.releaseLayerCount

    if combineLayer:
      var releaseMidLayer = 0
      jump = false
      for consumerIndex in countdown(
          layerWindow.highIndex, layerCursor.layerIndex + 1):
        let consumerCursor =
          blaiReleaseLayerTableCursor(layerWindow, consumerIndex)
        if not consumerCursor.valid:
          return
        if blaiLayerConsumesGraph(
            layers[consumerCursor.layerIndex],
            layers[layerCursor.layerIndex].graphLayer[1]):
          releaseMidLayer = consumerCursor.layerIndex
          layers[layerCursor.layerIndex].midOut = 1
          jump = true
        if jump:
          break
      if releaseMidLayer != 0:
        let releaseMidCursor =
          blaiReleaseLayerTableCursor(layerWindow, releaseMidLayer)
        if not releaseMidCursor.valid:
          return
        if not blaiAppendReleaseLayer(
            layers[releaseMidCursor.layerIndex], layerCursor.layerIndex,
            mid = true):
          result.releaseFits = false
          if result.firstReleaseOverflowLayer < 0:
            result.firstReleaseOverflowLayer =
              blaiLayerIndexValue(releaseMidCursor.layerIndex)
        else:
          inc result.releaseMidLayerCount

  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiReleaseLayerTableCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      return
    let graph0 = layers[layerCursor.layerIndex].graphLayer[0]
    let graph0Cursor = blaiGraphLayerMapCursor(graph0, graphLayerToLayer.len)
    if not graph0Cursor.valid:
      result.graphMapFits = false
      if result.firstGraphMapOverflowLayer < 0:
        result.firstGraphMapOverflowLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
    else:
      graphLayerToLayer[graph0Cursor.mapIndex] =
        blaiLayerIndexValue(layerCursor.layerIndex)
    if layers[layerCursor.layerIndex].midOut != 0:
      let graph1 = layers[layerCursor.layerIndex].graphLayer[1]
      let graph1Cursor = blaiGraphLayerMapCursor(graph1, graphLayerToLayer.len)
      if not graph1Cursor.valid:
        result.graphMapFits = false
        if result.firstGraphMapOverflowLayer < 0:
          result.firstGraphMapOverflowLayer =
            blaiLayerIndexValue(layerCursor.layerIndex)
      else:
        graphLayerToLayer[graph1Cursor.mapIndex] =
          blaiLayerIndexValue(layerCursor.layerIndex)

  result.complete = result.graphMapFits and result.releaseFits
  if not result.releaseFits:
    result.firstBlock = blaiReleaseLayerReleaseListOverflow
  elif not result.graphMapFits:
    result.firstBlock = blaiReleaseLayerGraphMapOverflow
  else:
    result.firstBlock = blaiReleaseLayerNoBlock

proc blaiAssignReleaseLayers*(
    layers: var openArray[BlaiCpuParsedLayerState],
    graphLayerToLayer: var openArray[int32]): BlaiReleaseLayerPlan =
  ## Apply recovered `assign_release_layer` to parsed-layer state records.
  ##
  ## This keeps extra-input and YOLO sidecar ownership bundled with each parsed
  ## layer while filling the same fixed ABI release arrays in `layer`.
  result.layerCount = blaiOpenArrayLenU32(layers)
  result.graphMapFits = true
  result.releaseFits = true
  result.firstGraphMapOverflowLayer = -1
  result.firstReleaseOverflowLayer = -1

  let layerWindow = blaiReleaseLayerTableWindow(layers.len)
  for graphIndex in 0 ..< graphLayerToLayer.len:
    graphLayerToLayer[graphIndex] = 0
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiReleaseLayerTableCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      return
    layers[layerCursor.layerIndex].layer.releaseNum = 0
    layers[layerCursor.layerIndex].layer.releaseMidNum = 0
    layers[layerCursor.layerIndex].layer.midOut = 0

  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiReleaseLayerTableCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      return
    let layerType =
      blaiLayerTypeFromSdk(layers[layerCursor.layerIndex].layer.layerType)
    let combineLayer = blaiIsCombine(layerType)
    var releaseLayer =
      if layerCursor.layerIndex == layerWindow.highIndex:
        layerCursor.layerIndex
      else:
        0
    var jump = false
    for consumerIndex in countdown(
        layerWindow.highIndex, layerCursor.layerIndex + 1):
      let consumerCursor =
        blaiReleaseLayerTableCursor(layerWindow, consumerIndex)
      if not consumerCursor.valid:
        return
      if blaiLayerConsumesGraph(
          layers[consumerCursor.layerIndex].layer,
          layers[layerCursor.layerIndex].layer.graphLayer[0]):
        releaseLayer = consumerCursor.layerIndex
        jump = true
      elif consumerCursor.layerIndex == layerCursor.layerIndex + 1:
        releaseLayer = consumerCursor.layerIndex
      if jump:
        break

    let releaseCursor = blaiReleaseLayerTableCursor(layerWindow, releaseLayer)
    if not releaseCursor.valid:
      return
    if not blaiAppendReleaseLayer(
        layers[releaseCursor.layerIndex].layer, layerCursor.layerIndex,
        mid = false):
      result.releaseFits = false
      if result.firstReleaseOverflowLayer < 0:
        result.firstReleaseOverflowLayer =
          blaiLayerIndexValue(releaseCursor.layerIndex)
    else:
      inc result.releaseLayerCount

    if combineLayer:
      var releaseMidLayer = 0
      jump = false
      for consumerIndex in countdown(
          layerWindow.highIndex, layerCursor.layerIndex + 1):
        let consumerCursor =
          blaiReleaseLayerTableCursor(layerWindow, consumerIndex)
        if not consumerCursor.valid:
          return
        if blaiLayerConsumesGraph(
            layers[consumerCursor.layerIndex].layer,
            layers[layerCursor.layerIndex].layer.graphLayer[1]):
          releaseMidLayer = consumerCursor.layerIndex
          layers[layerCursor.layerIndex].layer.midOut = 1
          jump = true
        if jump:
          break
      if releaseMidLayer != 0:
        let releaseMidCursor =
          blaiReleaseLayerTableCursor(layerWindow, releaseMidLayer)
        if not releaseMidCursor.valid:
          return
        if not blaiAppendReleaseLayer(
            layers[releaseMidCursor.layerIndex].layer,
            layerCursor.layerIndex, mid = true):
          result.releaseFits = false
          if result.firstReleaseOverflowLayer < 0:
            result.firstReleaseOverflowLayer =
              blaiLayerIndexValue(releaseMidCursor.layerIndex)
        else:
          inc result.releaseMidLayerCount

  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiReleaseLayerTableCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      return
    let graph0 = layers[layerCursor.layerIndex].layer.graphLayer[0]
    let graph0Cursor = blaiGraphLayerMapCursor(graph0, graphLayerToLayer.len)
    if not graph0Cursor.valid:
      result.graphMapFits = false
      if result.firstGraphMapOverflowLayer < 0:
        result.firstGraphMapOverflowLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
    else:
      graphLayerToLayer[graph0Cursor.mapIndex] =
        blaiLayerIndexValue(layerCursor.layerIndex)
    if layers[layerCursor.layerIndex].layer.midOut != 0:
      let graph1 = layers[layerCursor.layerIndex].layer.graphLayer[1]
      let graph1Cursor = blaiGraphLayerMapCursor(graph1, graphLayerToLayer.len)
      if not graph1Cursor.valid:
        result.graphMapFits = false
        if result.firstGraphMapOverflowLayer < 0:
          result.firstGraphMapOverflowLayer =
            blaiLayerIndexValue(layerCursor.layerIndex)
      else:
        graphLayerToLayer[graph1Cursor.mapIndex] =
          blaiLayerIndexValue(layerCursor.layerIndex)

  result.complete = result.graphMapFits and result.releaseFits
  if not result.releaseFits:
    result.firstBlock = blaiReleaseLayerReleaseListOverflow
  elif not result.graphMapFits:
    result.firstBlock = blaiReleaseLayerGraphMapOverflow
  else:
    result.firstBlock = blaiReleaseLayerNoBlock

proc blaiSetCpuOutputShape(layer: var BlaiCpuInstLayer64,
                           outputW, outputH, outputC: uint32): bool =
  let
    outputWAbi = blaiOutputShapeDimAbi(outputW)
    outputHAbi = blaiOutputShapeDimAbi(outputH)
    outputCAbi = blaiOutputShapeDimAbi(outputC)
  if not outputWAbi.valid or not outputHAbi.valid or not outputCAbi.valid:
    return false
  layer.outW = outputWAbi.value
  layer.outH = outputHAbi.value
  layer.outC = outputCAbi.value
  true

proc blaiSetCpuOutputShapeSigned(layer: var BlaiCpuInstLayer64,
                                 outputW, outputH, outputC: int64): bool =
  if outputW < 0'i64 or outputH < 0'i64 or outputC < 0'i64:
    return false
  if outputW > int64(high(int32)) or outputH > int64(high(int32)) or
      outputC > int64(high(int32)):
    return false
  blaiSetCpuOutputShape(
    layer, outputW.uint32, outputH.uint32, outputC.uint32)

proc blaiCpuTransposeAxisDim(layer: BlaiCpuInstLayer64,
                             rank, perm: uint32): uint32 =
  ## Match SDK `set_output_wh_later` transpose axis muxing.
  if rank == 4'u32:
    if perm == 1'u32:
      nonNegativeU32(layer.h)
    elif perm == 2'u32:
      nonNegativeU32(layer.w)
    else:
      nonNegativeU32(layer.c)
  else:
    if perm == 0'u32:
      nonNegativeU32(layer.h)
    elif perm == 1'u32:
      nonNegativeU32(layer.w)
    else:
      nonNegativeU32(layer.c)

proc blaiApplyCpuTransposeOutputShape*(
    layer: var BlaiCpuInstLayer64,
    mask: BlaiCpuTfliteTransposeMask): BlaiCpuOutputShapeResult =
  ## Apply the SDK `set_output_wh_later` TRANSPOSE shape update.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = result.layerType == blaiTranspose
  if not result.supported:
    result.firstBlock = blaiOutputShapeUnsupportedLayer
    return
  if not mask.active:
    result.firstBlock = blaiOutputShapeMissingTransposeMask
    return
  result.outputC = blaiCpuTransposeAxisDim(layer, mask.rank, mask.cPerm)
  result.outputW = blaiCpuTransposeAxisDim(layer, mask.rank, mask.wPerm)
  result.outputH = blaiCpuTransposeAxisDim(layer, mask.rank, mask.hPerm)
  result.fits = blaiSetCpuOutputShape(
    layer, result.outputW, result.outputH, result.outputC)
  result.updated = result.fits
  result.firstBlock =
    if result.updated: blaiOutputShapeNoBlock
    else: blaiOutputShapeInvalidDimensions

proc blaiApplyCpuPadOutputShape*(
    layer: var BlaiCpuInstLayer64,
    pad: BlaiCpuPadShapeBias): BlaiCpuOutputShapeResult =
  ## Apply the SDK `set_output_wh_later` PAD shape update.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = result.layerType == blaiPad
  if not result.supported:
    result.firstBlock = blaiOutputShapeUnsupportedLayer
    return
  if not pad.active:
    result.firstBlock = blaiOutputShapeMissingPadBias
    return
  let
    outputC = int64(layer.c) + 2'i64 * int64(pad.channel)
    outputW = int64(layer.w) + 2'i64 * int64(pad.width)
    outputH = int64(layer.h) + 2'i64 * int64(pad.height)
  result.fits = blaiSetCpuOutputShapeSigned(layer, outputW, outputH, outputC)
  if result.fits:
    result.outputW = outputW.uint32
    result.outputH = outputH.uint32
    result.outputC = outputC.uint32
    result.updated = true
    result.firstBlock = blaiOutputShapeNoBlock
  else:
    result.firstBlock = blaiOutputShapeInvalidDimensions

proc blaiApplyCpuTransposeLkOutputShape*(
    layer: var BlaiCpuInstLayer64): BlaiCpuOutputShapeResult =
  ## Apply the SDK `set_output_wh_later` TRANSPOSE_LK shape update.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = result.layerType == blaiTransposeLk
  if not result.supported:
    result.firstBlock = blaiOutputShapeUnsupportedLayer
    return
  let
    kernelSize = nonNegativeU32(layer.tfInput1Multiplier)
    stride = nonNegativeU32(layer.stride)
    inputW = nonNegativeU32(layer.w)
    inputH = nonNegativeU32(layer.h)
    channels = nonNegativeU32(layer.c)
    dilationW = nonNegativeU32(layer.tfInput1Offset)
    dilationH = nonNegativeU32(layer.tfInput2Offset)
  let kernelSizeAbi = blaiKernelSizeAbi(kernelSize)
  if not kernelSizeAbi.valid:
    result.firstBlock = blaiOutputShapeInvalidDimensions
    return
  layer.size = kernelSizeAbi.value
  if kernelSize == 0'u32 or stride == 0'u32 or inputW == 0'u32 or
      inputH == 0'u32 or channels == 0'u32:
    result.firstBlock = blaiOutputShapeInvalidTransposeLkParams
    return
  let
    alignedKernel = blaiChannelAlign4(kernelSize)
    sequenceLength = if inputW == 1'u32: inputH else: inputW
    dilation = if inputW == 1'u32: dilationH else: dilationW
    fetchSize = if dilation == 2'u32: kernelSize * dilation - 1'u32
                else: kernelSize
  if dilation == 0'u32 or sequenceLength < fetchSize:
    result.firstBlock = blaiOutputShapeInvalidTransposeLkParams
    return
  let outputChannels =
    blaiReferenceTransposeLkOutputChannels(channels, alignedKernel)
  if outputChannels > high(uint32).uint64:
    result.firstBlock = blaiOutputShapeInvalidDimensions
    return
  result.outputC = outputChannels.uint32
  result.outputW = inputW
  result.outputH = ((sequenceLength - fetchSize) div stride) + 1'u32
  result.fits = blaiSetCpuOutputShape(
    layer, result.outputW, result.outputH, result.outputC)
  result.updated = result.fits
  result.firstBlock =
    if result.updated: blaiOutputShapeNoBlock
    else: blaiOutputShapeInvalidDimensions

proc blaiApplyCpuOutputShapeLater*(
    layer: var BlaiCpuInstLayer64,
    transposeMask: BlaiCpuTfliteTransposeMask = BlaiCpuTfliteTransposeMask(),
    padBias: BlaiCpuPadShapeBias = BlaiCpuPadShapeBias()
      ): BlaiCpuOutputShapeResult =
  ## Apply recovered SDK `set_output_wh_later` shape side effects.
  case blaiLayerTypeFromSdk(layer.layerType)
  of blaiPad:
    blaiApplyCpuPadOutputShape(layer, padBias)
  of blaiTranspose:
    blaiApplyCpuTransposeOutputShape(layer, transposeMask)
  of blaiTransposeLk:
    blaiApplyCpuTransposeLkOutputShape(layer)
  else:
    BlaiCpuOutputShapeResult(
      layerType: blaiLayerTypeFromSdk(layer.layerType),
      supported: false,
      firstBlock: blaiOutputShapeUnsupportedLayer)

proc blaiApplyCpuOutputShapeLater*(
    parsed: var BlaiCpuParsedLayerState,
    transposeMask: BlaiCpuTfliteTransposeMask = BlaiCpuTfliteTransposeMask(),
    padBias: BlaiCpuPadShapeBias = BlaiCpuPadShapeBias()
      ): BlaiCpuOutputShapeResult =
  ## Apply recovered `set_output_wh_later` shape side effects to parsed state.
  ##
  ## The sidecar-bearing parsed record keeps its extra-input and YOLO storage
  ## bundled while only the embedded CPU layer shape fields are updated.
  blaiApplyCpuOutputShapeLater(parsed.layer, transposeMask, padBias)

proc blaiEncodeDispatch*(layerType: BlaiLayerType,
                         inputNum: uint32): BlaiEncodeDispatch =
  ## SDK `BLAI_encode` route-vs-general data emitter selection.
  if layerType in {blaiRoute, blaiRouteMax} and inputNum > 2'u32:
    blaiEncodeRoute
  else:
    blaiEncodeGeneral

proc blaiEncodeDispatch*(layer: BlaiDecodedLayer,
                         inputNum: uint32): BlaiEncodeDispatch =
  blaiEncodeDispatch(layer.layerType, inputNum)

proc blaiEncodeDispatch*(layer: BlaiCpuInstLayer64): BlaiEncodeDispatch =
  blaiEncodeDispatch(blaiLayerTypeFromSdk(layer.layerType),
                     nonNegativeU32(layer.inputNum))

proc blaiEncodeDispatch*(
    parsed: BlaiCpuParsedLayerState): BlaiEncodeDispatch =
  ## Parsed-state wrapper for SDK `BLAI_encode` route-vs-general dispatch.
  blaiEncodeDispatch(parsed.layer)

proc blaiFetchKind*(dispatch: BlaiEncodeDispatch): BlaiFetchMemoryKind =
  case dispatch
  of blaiEncodeGeneral: blaiFetchGeneral
  of blaiEncodeRoute: blaiFetchRoute

proc blaiNpuEligibilityInto*(layer: BlaiDecodedLayer,
                             outResult: var BlaiNpuEligibilityResult)
proc blaiCanRunOnNpu*(layer: BlaiDecodedLayer): bool

proc blaiPlanEncodeInto*(layer: BlaiDecodedLayer,
                         inputNum: uint32,
                         allocationSucceeded: bool,
                         outResult: var BlaiEncodePlan) =
  ## Recovered SDK `BLAI_encode` wrapper decision. This only plans the
  ## eligibility, allocator-success, dispatch, and clear-size gates.
  outResult = default(BlaiEncodePlan)
  var eligibility: BlaiNpuEligibilityResult
  blaiNpuEligibilityInto(layer, eligibility)
  outResult.eligible = eligibility.eligible
  outResult.allocationSucceeded = allocationSucceeded
  outResult.runnable = outResult.eligible and allocationSucceeded
  outResult.dispatch = blaiEncodeDispatch(layer, inputNum)
  outResult.instructionClearBytes = BlaiInstructionScratchSize.uint32

proc blaiPlanEncode*(layer: BlaiDecodedLayer,
                     inputNum: uint32,
                     allocationSucceeded: bool): BlaiEncodePlan =
  ## Convenience result-returning wrapper for `BLAI_encode` gate planning.
  blaiPlanEncodeInto(layer, inputNum, allocationSucceeded, result)

proc blaiPlanEncodeInto*(layer: BlaiCpuInstLayer64,
                         allocationSucceeded: bool,
                         outResult: var BlaiEncodePlan) =
  ## Project the CPU-layer ABI and plan the recovered `BLAI_encode` gate.
  blaiPlanEncodeInto(
    toDecodedLayer(layer), nonNegativeU32(layer.inputNum),
    allocationSucceeded, outResult)

proc blaiPlanEncode*(layer: BlaiCpuInstLayer64,
                     allocationSucceeded: bool): BlaiEncodePlan =
  ## Convenience result-returning wrapper for CPU-layer encode gate planning.
  blaiPlanEncodeInto(layer, allocationSucceeded, result)

proc blaiClearInstructionScratch*(scratch: var openArray[uint8]) =
  ## SDK `memset(l->NPU_inst, 0, MAX_Input_num*NPU_INST_SIZE_BYTE*3)`.
  doAssert scratch.len >= BlaiInstructionScratchSize
  for i in 0 ..< BlaiInstructionScratchSize:
    scratch[i] = 0

proc blaiClearInstructionStream*(stream: var openArray[BlaiInstruction]) =
  ## Clear the recovered SDK instruction scratch as typed 16-byte records.
  const scratchInstructions = BlaiInstructionScratchSize div BlaiInstructionSize
  doAssert stream.len >= scratchInstructions
  for i in 0 ..< scratchInstructions:
    stream[i] = default(BlaiInstruction)

proc blaiEncodeStartState*(instCnt: int32,
                           scratchCleared: bool): BlaiEncodeStartState =
  ## Build caller-owned encode-wrapper start state.
  result.instCnt = instCnt
  result.scratchCleared = scratchCleared

proc blaiEncodeStartApplyPlan*(): BlaiEncodeStartApplyPlan =
  ## Recover the wrapper start state after instruction scratch clear.
  result.stateAfter = blaiEncodeStartState(0'i32, true)
  result.valid = true

proc blaiEncodeStartState*(
    plan: BlaiEncodeStartApplyPlan): BlaiEncodeStartState =
  ## Project a valid encode start apply plan into caller-owned state.
  doAssert plan.valid
  plan.stateAfter

proc blaiApplyEncodeStartState*(
    layer: var BlaiCpuInstLayer64,
    outResult: var BlaiCpuLayerEncodeResult,
    state: BlaiEncodeStartState) =
  ## Apply encode-wrapper start state to caller-owned objects.
  layer.instCnt = state.instCnt
  outResult.scratchCleared = state.scratchCleared

proc blaiInstructionEncodeRequiredInto*(bundle: BlaiNpuInstructionBundle,
                                        outResult: var BlaiInstructionEncodeCountResult) =
  ## Number of 16-byte instructions SDK `instruction_encode` will append.
  outResult = default(BlaiInstructionEncodeCountResult)
  outResult.normalCount = 1
  if bundle.useTflite != 0:
    outResult.tfliteCount = 1
  if bundle.extraInfo != 0:
    outResult.extraCount = 1
  outResult.emitted =
    outResult.normalCount + outResult.tfliteCount + outResult.extraCount

proc blaiInstructionEncodeRequired*(bundle: BlaiNpuInstructionBundle): uint32 =
  ## Boolean-compatible scalar wrapper for recovered append count.
  var count: BlaiInstructionEncodeCountResult
  blaiInstructionEncodeRequiredInto(bundle, count)
  count.emitted

proc blaiInstructionAppendEvidence*(
    bundle: BlaiNpuInstructionBundle,
    streamLen, startCount: uint32): BlaiInstructionAppendEvidence =
  ## Recover append fit and checked `instCnt` end-count projection.
  result.startCount = startCount
  var required: BlaiInstructionEncodeCountResult
  blaiInstructionEncodeRequiredInto(bundle, required)
  result.emitted = required.emitted
  var fit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(streamLen, startCount, result.emitted, fit)
  if not fit.fits:
    result.endCount = startCount
    return
  let endCountApply = blaiInstructionCountApplyPlan(fit.requiredCount)
  if not endCountApply.valid:
    result.endCount = startCount
    return
  result.fits = true
  result.endCount = fit.requiredCount
  result.endCountApply = endCountApply
  result.valid = true

proc blaiInstructionEmittedCountEvidence*(
    bundle: BlaiNpuInstructionBundle,
    emitted: uint32): BlaiInstructionEmittedCountEvidence =
  ## Recover emitted instruction-count accumulation for descriptor loops.
  var count: BlaiInstructionEncodeCountResult
  blaiInstructionEncodeRequiredInto(bundle, count)
  result.appended = count.emitted
  var emittedFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), emitted, count.emitted, emittedFit)
  if not emittedFit.fits:
    return
  result.emitted = emittedFit.requiredCount
  result.valid = true

proc blaiInstructionStreamCommitEvidence*(
    streamLen, startCount, emitted: uint32): BlaiInstructionStreamCommitEvidence =
  ## Recover final stream-fit and count projections for multi-append emitters.
  result.startCount = startCount
  result.emitted = emitted
  var streamFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(streamLen, startCount, emitted, streamFit)
  if not streamFit.cursorFits:
    result.endCount = startCount
    return
  result.endCount = streamFit.requiredCount
  result.fits = streamFit.fits
  if not result.fits:
    result.endCount = startCount
    return
  let
    startCountApply = blaiInstructionCountApplyPlan(startCount)
    endCountApply = blaiInstructionCountApplyPlan(result.endCount)
  if not startCountApply.valid or not endCountApply.valid:
    result.endCount = startCount
    result.fits = false
    return
  result.startCountApply = startCountApply
  result.endCountApply = endCountApply
  result.valid = true

proc blaiEncodeInstructionsInto*(bundle: BlaiNpuInstructionBundle,
                                 stream: var openArray[BlaiInstruction],
                                 startCount: uint32,
                                 outResult: var BlaiInstructionEncodeResult) =
  ## Recover SDK `instruction_encode` without pointer arithmetic.
  ##
  ## The blob appends `inst_tflite` when `use_tflite != 0`, then `inst_extra`
  ## when `extra_info != 0`, then always appends `inst`. This bounded version
  ## leaves the stream unchanged and reports `fits=false` when the target slice
  ## cannot hold the complete append.
  outResult = default(BlaiInstructionEncodeResult)
  outResult.startCount = startCount
  var count: BlaiInstructionEncodeCountResult
  blaiInstructionEncodeRequiredInto(bundle, count)
  outResult.emitted = count.emitted
  var fit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(
    blaiOpenArrayLenU32(stream), startCount, outResult.emitted, fit)
  outResult.endCount = fit.requiredCount
  outResult.fits = fit.fits
  if not outResult.fits:
    outResult.endCount = startCount
    return

  let startCursor = blaiInstructionStreamStartCursor(startCount, stream.len)
  if not startCursor.valid:
    outResult.endCount = startCount
    outResult.fits = false
    return
  var cursor = startCursor.index
  if bundle.useTflite != 0:
    stream[cursor] = bundle.instTflite
    inc cursor
  if bundle.extraInfo != 0:
    stream[cursor] = bundle.instExtra
    inc cursor
  stream[cursor] = bundle.inst

proc blaiEncodeInstructions*(bundle: BlaiNpuInstructionBundle,
                             stream: var openArray[BlaiInstruction],
                             startCount: uint32): BlaiInstructionEncodeResult =
  ## Convenience result-returning wrapper for instruction encoding.
  blaiEncodeInstructionsInto(bundle, stream, startCount, result)

proc blaiEmitLayerInstructionsInto*(layer: var BlaiCpuInstLayer64,
                                    plan: BlaiFetchMemoryPlan,
                                    stream: var openArray[BlaiInstruction],
                                    useTflite: bool,
                                    outResult: var BlaiInstructionEncodeResult,
                                    c2: uint32 = 0'u32,
                                    includeExtra: bool = false,
                                    descriptorHalt: bool = false,
                                    midOutState: bool = false) =
  ## Build and append recovered layer instructions, then update `instCnt`.
  ##
  ## Like `blaiEncodeInstructions`, this leaves the stream and `instCnt`
  ## unchanged when the complete append does not fit.
  let
    startCount = nonNegativeU32(layer.instCnt)
    bundle = blaiLayerInstructionBundle(
      layer, plan, useTflite, c2, includeExtra, descriptorHalt, midOutState)
  let appendEvidence = blaiInstructionAppendEvidence(
    bundle, blaiOpenArrayLenU32(stream), startCount)
  if not appendEvidence.valid:
    outResult = default(BlaiInstructionEncodeResult)
    outResult.startCount = startCount
    outResult.endCount = startCount
    outResult.emitted = appendEvidence.emitted
    return
  blaiEncodeInstructionsInto(bundle, stream, startCount, outResult)
  if outResult.fits:
    blaiApplyInstructionCountState(
      layer, blaiInstructionCountState(appendEvidence.endCountApply))

proc blaiEmitLayerInstructions*(layer: var BlaiCpuInstLayer64,
                                plan: BlaiFetchMemoryPlan,
                                stream: var openArray[BlaiInstruction],
                                useTflite: bool,
                                c2: uint32 = 0'u32,
                                includeExtra: bool = false,
                                descriptorHalt: bool = false,
                                midOutState: bool = false): BlaiInstructionEncodeResult =
  ## Convenience result-returning wrapper for layer instruction emission.
  blaiEmitLayerInstructionsInto(
    layer, plan, stream, useTflite, result, c2, includeExtra, descriptorHalt,
    midOutState)

proc blaiMemoryPlanState*(
    npuOn, bufSize: int32,
    dramIn: array[BlaiMaxInputNum, int32],
    dramMidOut: int32,
    dramOut: array[BlaiMaxInputNum, int32],
    dramPatchSize, dramWeight, dramBias: int32): BlaiMemoryPlanState =
  ## Build caller-owned post-encode memory state.
  result.npuOn = npuOn
  result.bufSize = bufSize
  result.dramIn = dramIn
  result.dramMidOut = dramMidOut
  result.dramOut = dramOut
  result.dramPatchSize = dramPatchSize
  result.dramWeight = dramWeight
  result.dramBias = dramBias

proc blaiMemoryPlanApplyEvidence*(
    layer: BlaiCpuInstLayer64,
    ctrl: BlaiPsramCtrl): BlaiMemoryPlanApplyEvidence =
  ## Project post-encode memory scalars through recovered SDK ABI checks.
  if layer.dramPatchNum < 0 or ctrl.psramPatchSize < 0:
    return
  let patchSize = blaiAllocatorFieldAbi(nonNegativeU32(ctrl.psramPatchSize))
  if not patchSize.valid:
    return
  let bufSize64 =
    layer.dramPatchNum.int64 * ctrl.psramPatchSize.int64
  let bufSize = blaiMemoryPlanBufSizeAbi(bufSize64)
  if not bufSize.valid:
    return
  result.bufSize = bufSize.value
  result.dramPatchSize = patchSize.value
  result.valid = true

proc blaiMemoryPlanApplyPlan*(
    layer: BlaiCpuInstLayer64,
    ctrl: BlaiPsramCtrl): BlaiMemoryPlanApplyPlan =
  ## Recover checked post-`BLAI_encode` layer memory stores.
  let evidence = blaiMemoryPlanApplyEvidence(layer, ctrl)
  if not evidence.valid:
    return
  result.stateAfter = blaiMemoryPlanState(
    1'i32, evidence.bufSize, ctrl.sramIn, ctrl.sramMidOut, ctrl.sramOut,
    evidence.dramPatchSize, ctrl.sramWeight, ctrl.sramBias)
  result.valid = true

proc blaiMemoryPlanState*(
    plan: BlaiMemoryPlanApplyPlan): BlaiMemoryPlanState =
  ## Project a valid post-encode memory apply plan into caller-owned state.
  doAssert plan.valid
  plan.stateAfter

proc blaiApplyMemoryPlanState*(
    layer: var BlaiCpuInstLayer64,
    state: BlaiMemoryPlanState) =
  ## Apply post-encode memory state to a typed layer object.
  layer.npuOn = state.npuOn
  layer.bufSize = state.bufSize
  layer.dramIn = state.dramIn
  layer.dramMidOut = state.dramMidOut
  layer.dramOut = state.dramOut
  layer.dramPatchSize = state.dramPatchSize
  layer.dramWeight = state.dramWeight
  layer.dramBias = state.dramBias

proc blaiApplyMemoryPlan*(layer: var BlaiCpuInstLayer64,
                          ctrl: BlaiPsramCtrl) =
  ## Mirror the post-`BLAI_encode` copies in SDK `gen_npu_inst_layer`.
  ##
  ## `dramPatchNum` is left as allocator-owned state, matching the SDK code
  ## which uses the layer field after `BLAI_MEM_alloc`.
  let applyPlan = blaiMemoryPlanApplyPlan(layer, ctrl)
  doAssert applyPlan.valid
  blaiApplyMemoryPlanState(layer, blaiMemoryPlanState(applyPlan))

proc blaiEncodeFailureState*(npuOn: int32): BlaiEncodeFailureState =
  ## Build caller-owned encode-wrapper failure state.
  result.npuOn = npuOn

proc blaiEncodeFailureApplyPlan*(): BlaiEncodeFailureApplyPlan =
  ## Recover the wrapper failure state written by `gen_npu_inst_layer`.
  result.stateAfter = blaiEncodeFailureState(0'i32)
  result.valid = true

proc blaiEncodeFailureState*(
    plan: BlaiEncodeFailureApplyPlan): BlaiEncodeFailureState =
  ## Project a valid wrapper failure apply plan into caller-owned state.
  doAssert plan.valid
  plan.stateAfter

proc blaiApplyEncodeFailureState*(
    layer: var BlaiCpuInstLayer64,
    state: BlaiEncodeFailureState) =
  ## Apply wrapper failure state to a typed layer object.
  layer.npuOn = state.npuOn

proc blaiMarkEncodeFailed*(layer: var BlaiCpuInstLayer64) =
  ## SDK `gen_npu_inst_layer` stores false in `NPU_on` on wrapper failure.
  let applyPlan = blaiEncodeFailureApplyPlan()
  doAssert applyPlan.valid
  blaiApplyEncodeFailureState(layer, blaiEncodeFailureState(applyPlan))

proc blaiMemAllocSinglePatchMidPlan*(
    layerType: BlaiLayerType,
    inputWidth, inputHeight, inputChannels, outputChannels: uint32,
    midOut: bool,
    psramPatchSize: uint32): BlaiMemAllocSinglePatchMidPlan =
  ## Recover optional one-patch fallback mid-output source and patch count.
  if not midOut or psramPatchSize == 0'u32:
    return
  if layerType == blaiSoftmax:
    result.source = blaiMemAllocSinglePatchMidSoftmaxOutputChannels
    result.inputElements = inputWidth * inputHeight * outputChannels
  else:
    result.source = blaiMemAllocSinglePatchMidInputChannels
    result.inputElements = inputWidth * inputHeight * inputChannels
  result.psramMidPatchCount =
    blaiCeilDivU32(result.inputElements, psramPatchSize)

proc blaiMemAllocSinglePatchShape*(
    layer: BlaiCpuInstLayer64): BlaiMemAllocSinglePatchShape =
  ## Recover the one-patch fallback shape used by `BLAI_MEM_alloc`.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.outputChannels = nonNegativeU32(layer.outC)
  result.alignedOutputChannels = blaiChannelAlign4(result.outputChannels)
  result.outputWidth = nonNegativeU32(layer.outW)
  result.outputHeight = nonNegativeU32(layer.outH)
  result.inputWidth = nonNegativeU32(layer.w)
  result.inputHeight = nonNegativeU32(layer.h)
  result.inputChannels = nonNegativeU32(layer.c)
  result.outputElements = result.outputWidth * result.outputHeight
  result.psramPatchSize = result.outputElements * result.alignedOutputChannels
  let midPlan = blaiMemAllocSinglePatchMidPlan(
    result.layerType, result.inputWidth, result.inputHeight,
    result.inputChannels, result.outputChannels, layer.midOut == 1,
    result.psramPatchSize)
  result.midSource = midPlan.source
  result.midInputElements = midPlan.inputElements
  result.psramMidPatchCount = midPlan.psramMidPatchCount
  result.valid = true

proc blaiPlanSinglePatchMemAllocInto*(layer: BlaiCpuInstLayer64,
                                      outResult: var BlaiMemAllocSinglePatchPlan) =
  ## Recover the small-layer `BLAI_MEM_alloc` stores at the one-patch fallback.
  ##
  ## The full allocator chooses whether this branch is valid. This helper only
  ## mirrors the fields written once that branch is selected.
  outResult = default(BlaiMemAllocSinglePatchPlan)
  let shape = blaiMemAllocSinglePatchShape(layer)
  outResult.weightPatchCount = BlaiMemAllocSinglePatchWeightPatchCount
  outResult.firstWeightPatchOutC = shape.outputChannels
  outResult.psramPatchCount = BlaiMemAllocSinglePatchPsramPatchCount
  outResult.psramPatchSize = shape.psramPatchSize
  outResult.midSource = shape.midSource
  outResult.midInputElements = shape.midInputElements
  outResult.psramMidPatchCount = shape.psramMidPatchCount

proc blaiPlanSinglePatchMemAlloc*(layer: BlaiCpuInstLayer64): BlaiMemAllocSinglePatchPlan =
  ## Convenience result-returning wrapper for the one-patch allocator branch.
  blaiPlanSinglePatchMemAllocInto(layer, result)

proc blaiMemAllocSinglePatchApplyPlan*(
    plan: BlaiMemAllocSinglePatchPlan): BlaiMemAllocSinglePatchApplyPlan =
  ## Recover checked one-patch allocator stores before mutating `PSRAM_ctrl`.
  let
    weightPatchCount = blaiAllocatorFieldAbi(plan.weightPatchCount)
    firstWeightPatchOutC = blaiAllocatorFieldAbi(plan.firstWeightPatchOutC)
    psramPatchSize = blaiAllocatorFieldAbi(plan.psramPatchSize)
    psramPatchCount = blaiAllocatorFieldAbi(plan.psramPatchCount)
    psramMidPatchCount = blaiAllocatorFieldAbi(plan.psramMidPatchCount)
  if not weightPatchCount.valid or not firstWeightPatchOutC.valid or
     not psramPatchSize.valid or not psramPatchCount.valid or
     not psramMidPatchCount.valid:
    return
  result.weightPatchCount = weightPatchCount.value
  result.firstWeightPatchOutC = firstWeightPatchOutC.value
  result.psramPatchSize = psramPatchSize.value
  result.psramPatchCount = psramPatchCount.value
  result.psramMidPatchCount = psramMidPatchCount.value
  result.valid = true

proc blaiMemAllocSinglePatchState*(
    weightPatchCount: int32,
    firstWeightPatchOutC: int32,
    psramPatchSize: int32,
    psramPatchCount: int32,
    psramMidPatchCount: int32): BlaiMemAllocSinglePatchState =
  ## Build caller-owned state for one-patch allocator stores.
  result.weightPatchCount = weightPatchCount
  result.firstWeightPatchOutC = firstWeightPatchOutC
  result.psramPatchSize = psramPatchSize
  result.psramPatchCount = psramPatchCount
  result.psramMidPatchCount = psramMidPatchCount

proc blaiMemAllocSinglePatchState*(
    plan: BlaiMemAllocSinglePatchApplyPlan): BlaiMemAllocSinglePatchState =
  ## Project a valid one-patch apply plan into caller-owned state.
  doAssert plan.valid
  blaiMemAllocSinglePatchState(
    plan.weightPatchCount, plan.firstWeightPatchOutC,
    plan.psramPatchSize, plan.psramPatchCount, plan.psramMidPatchCount)

proc blaiApplySinglePatchMemAllocState*(
    ctrl: var BlaiPsramCtrl,
    state: BlaiMemAllocSinglePatchState) =
  ## Apply one-patch allocator state to `PSRAM_ctrl`.
  let firstPatchCursor = blaiWeightPatchCursor(0'u32)
  doAssert firstPatchCursor.valid
  ctrl.weightPatchCount = state.weightPatchCount
  ctrl.weightPatchOutC[firstPatchCursor.index] = state.firstWeightPatchOutC
  ctrl.psramPatchSize = state.psramPatchSize
  ctrl.psramPatchCount = state.psramPatchCount
  ctrl.psramMidPatchCount = state.psramMidPatchCount

proc blaiApplySinglePatchMemAllocScalarState*(
    weightPatchCount: var int32,
    firstWeightPatchOutC: var int32,
    psramPatchSize: var int32,
    psramPatchCount: var int32,
    psramMidPatchCount: var int32,
    state: BlaiMemAllocSinglePatchState): bool =
  ## Apply recovered one-patch scalar metadata from typed state.
  weightPatchCount = state.weightPatchCount
  firstWeightPatchOutC = state.firstWeightPatchOutC
  psramPatchSize = state.psramPatchSize
  psramPatchCount = state.psramPatchCount
  psramMidPatchCount = state.psramMidPatchCount
  true

proc blaiApplySinglePatchMemAllocScalars*(
    weightPatchCount: var int32,
    firstWeightPatchOutC: var int32,
    psramPatchSize: var int32,
    psramPatchCount: var int32,
    psramMidPatchCount: var int32,
    plan: BlaiMemAllocSinglePatchApplyPlan): bool =
  ## Apply recovered one-patch scalar metadata.
  if not plan.valid:
    return false
  blaiApplySinglePatchMemAllocScalarState(
    weightPatchCount, firstWeightPatchOutC, psramPatchSize, psramPatchCount,
    psramMidPatchCount, blaiMemAllocSinglePatchState(plan))

proc blaiApplySinglePatchMemAlloc*(ctrl: var BlaiPsramCtrl,
                                   plan: BlaiMemAllocSinglePatchPlan) =
  ## Apply the recovered one-patch `BLAI_MEM_alloc` stores to `PSRAM_ctrl`.
  let applyPlan = blaiMemAllocSinglePatchApplyPlan(plan)
  doAssert applyPlan.valid
  blaiApplySinglePatchMemAllocState(
    ctrl, blaiMemAllocSinglePatchState(applyPlan))

proc blaiMemAllocRouteInputPosition*(
    extraInputIndex: uint32): BlaiMemAllocRouteInputPosition =
  ## Resolve recovered route extra-input order to a logical input number.
  if extraInputIndex == high(uint32):
    return
  result.extraInputIndex = extraInputIndex
  result.logicalInput = extraInputIndex + 1'u32
  result.valid = true

proc blaiMemAllocRouteInputCursor*(
    extraInputIndex: uint32): BlaiMemAllocRouteInputCursor =
  ## Resolve recovered route extra-input order to the matching `cn[]` slot.
  let position = blaiMemAllocRouteInputPosition(extraInputIndex)
  if not position.valid:
    return
  let cnCursor = blaiLayerCnCursor(position.logicalInput)
  if not cnCursor.valid:
    return
  result.extraInputIndex = position.extraInputIndex
  result.logicalInput = position.logicalInput
  result.cnIndex = cnCursor.cnIndex
  result.valid = true

proc blaiMemAllocRouteChannels(layer: BlaiCpuInstLayer64): tuple[channels: uint32,
                                                                 routed: bool] =
  let layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.channels = nonNegativeU32(layer.c)
  result.routed = layerType in {blaiRoute, blaiRouteMax, blaiRouteConv,
                                blaiRouteUpsample}
  if result.routed:
    let extraInputs = min(blaiSaturatingSubU32(nonNegativeU32(layer.inputNum), 1'u32),
                          BlaiMaxRouteInputNumU32)
    for i in 0'u32 ..< extraInputs:
      let routeInput = blaiMemAllocRouteInputCursor(i)
      if routeInput.valid:
        result.channels += nonNegativeU32(layer.cn[routeInput.cnIndex])

proc blaiMemAllocStartPatchPressure*(
    layer: BlaiCpuInstLayer64): BlaiMemAllocStartPatchPressure =
  ## Recover the initial input/output pressure for allocator split search.
  let route = blaiMemAllocRouteChannels(layer)
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.routed = route.routed
  result.routeChannels = route.channels
  result.inputWidth = nonNegativeU32(layer.w)
  result.outputWidth = nonNegativeU32(layer.outW)
  result.outputChannels = nonNegativeU32(layer.outC)
  result.shortcutDoubleInput = result.layerType == blaiShortcut
  result.suppressConvOutput = result.layerType == blaiConvolutional
  if result.shortcutDoubleInput:
    result.inputBytes = result.inputWidth * result.routeChannels * 2'u32
  else:
    result.inputBytes = result.inputWidth * result.routeChannels
  if not result.suppressConvOutput:
    result.outputBytes = result.outputWidth * result.outputChannels
  result.inputPatchCount =
    blaiCeilDivU32(result.inputBytes, BlaiNpuLocalBufferBytes)
  result.outputPatchCount =
    blaiCeilDivU32(result.outputBytes, BlaiNpuLocalBufferBytes)
  result.startPatchCount =
    max(result.inputPatchCount, result.outputPatchCount)

proc blaiPlanMemAllocStartPatchInto*(
    layer: BlaiCpuInstLayer64,
    outResult: var BlaiMemAllocStartPatchPlan) =
  ## Recover the initial 4 KiB split pressure used by `BLAI_MEM_alloc`.
  outResult = default(BlaiMemAllocStartPatchPlan)
  let pressure = blaiMemAllocStartPatchPressure(layer)
  outResult.layerType = pressure.layerType
  outResult.routed = pressure.routed
  outResult.routeChannels = pressure.routeChannels
  outResult.inputWidth = pressure.inputWidth
  outResult.outputWidth = pressure.outputWidth
  outResult.outputChannels = pressure.outputChannels
  outResult.shortcutDoubleInput = pressure.shortcutDoubleInput
  outResult.suppressConvOutput = pressure.suppressConvOutput
  outResult.inputBytes = pressure.inputBytes
  outResult.outputBytes = pressure.outputBytes
  outResult.inputPatchCount = pressure.inputPatchCount
  outResult.outputPatchCount = pressure.outputPatchCount
  outResult.startPatchCount = pressure.startPatchCount

proc blaiPlanMemAllocStartPatch*(
    layer: BlaiCpuInstLayer64): BlaiMemAllocStartPatchPlan =
  ## Convenience result-returning wrapper for line-patch search pressure.
  blaiPlanMemAllocStartPatchInto(layer, result)

proc blaiMemAllocPatchSegmentPosition*(
    patchIndex, patchCount: uint32): BlaiMemAllocPatchSegmentPosition =
  ## Resolve one recovered allocator patch segment position.
  if patchIndex >= patchCount:
    return
  result.patchIndex = patchIndex
  result.patchCount = patchCount
  result.last = patchIndex == patchCount - 1'u32
  result.valid = true

proc blaiMemAllocFinalPatchSegmentPosition*(
    patchCount: uint32): BlaiMemAllocPatchSegmentPosition =
  ## Resolve the recovered final allocator patch segment position.
  if patchCount == 0'u32:
    return
  blaiMemAllocPatchSegmentPosition(patchCount - 1'u32, patchCount)

proc blaiMemAllocPatchSegmentCursor*(
    patchIndex, patchCount: uint32): BlaiMemAllocPatchSegmentCursor =
  ## Resolve a recovered allocator patch index into bounded plan storage.
  let position = blaiMemAllocPatchSegmentPosition(patchIndex, patchCount)
  if not position.valid:
    return
  let patchCursor = blaiWeightPatchCursor(patchIndex)
  if not patchCursor.valid:
    return
  result.patchIndex = position.patchIndex
  result.patchSlot = patchCursor.index
  result.last = position.last
  result.valid = true

proc blaiToolchainPatchInitialRequestPlanInto*(
    layer: BlaiCpuInstLayer64,
    outResult: var BlaiToolchainPatchInitialRequestPlan) =
  ## Recover first-layer request count used before initial patch reservation.
  ##
  ## In the first-layer path, `PSRAM_allocate` multiplies height, width, and a
  ## recovered channel selector before floor-dividing by `PATCH_SIZE`. The
  ## channel selector preserves the converter quirk that raw channel counts 2
  ## and 3 are forced to 4; other non-negative counts pass through unchanged.
  outResult = default(BlaiToolchainPatchInitialRequestPlan)
  outResult.layerType = layer.layerType
  outResult.patchSizeBytes = BlaiToolchainPatchSizeBytes
  if outResult.patchSizeBytes == 0'u32:
    outResult.firstBlock = blaiToolchainPatchInitialRequestPatchSize
    return
  if layer.h < 0 or layer.w < 0 or layer.c < 0:
    outResult.firstBlock = blaiToolchainPatchInitialRequestLayerShape
    return

  outResult.inputHeight = layer.h.uint32
  outResult.inputWidth = layer.w.uint32
  outResult.inputChannels = layer.c.uint32
  outResult.smallChannelForced = layer.c == 2 or layer.c == 3
  outResult.selectedChannels =
    if outResult.smallChannelForced:
      4'u32
    else:
      outResult.inputChannels

  let pixelCount =
    outResult.inputHeight.uint64 * outResult.inputWidth.uint64
  let byteCount = pixelCount * outResult.selectedChannels.uint64
  if not blaiU64ExactU32Count(pixelCount, outResult.inputPixels) or
     not blaiU64ExactU32Count(byteCount, outResult.inputBytes):
    outResult.firstBlock = blaiToolchainPatchInitialRequestOverflow
    return

  outResult.requestedPatchCount =
    outResult.inputBytes div outResult.patchSizeBytes
  outResult.firstBlock = blaiToolchainPatchInitialRequestNoBlock
  outResult.valid = true

proc blaiToolchainPatchInitialRequestPlan*(
    layer: BlaiCpuInstLayer64): BlaiToolchainPatchInitialRequestPlan =
  ## Convenience wrapper for recovered first-layer request count.
  blaiToolchainPatchInitialRequestPlanInto(layer, result)

proc blaiToolchainPatchInitialStorePlanInto*(
    request: BlaiToolchainPatchInitialRequestPlan,
    outResult: var BlaiToolchainPatchInitialStorePlan) =
  ## Recover the first-layer request metadata store before slot reservation.
  ##
  ## The converter stores the computed request count at recovered control-block
  ## offset `0xcb70` before deciding whether the initial patch reservation loop
  ## should run.
  outResult = default(BlaiToolchainPatchInitialStorePlan)
  outResult.request = request
  outResult.metadataOffset = BlaiToolchainPatchInitialRequestStoreOffset
  if not request.valid:
    outResult.firstBlock = blaiToolchainPatchInitialStoreRequest
    return
  let requestCount = blaiToolchainPatchRequestCountAbi(
    request.requestedPatchCount)
  if not requestCount.valid:
    outResult.firstBlock = blaiToolchainPatchInitialStoreOverflow
    return

  outResult.requestedPatchCount = request.requestedPatchCount
  outResult.storedRequestCount = requestCount.value
  outResult.writesApplied = 1'u32
  outResult.firstBlock = blaiToolchainPatchInitialStoreNoBlock
  outResult.valid = true

proc blaiToolchainPatchInitialStorePlan*(
    request: BlaiToolchainPatchInitialRequestPlan):
    BlaiToolchainPatchInitialStorePlan =
  ## Convenience wrapper for recovered first-layer request metadata store.
  blaiToolchainPatchInitialStorePlanInto(request, result)

proc blaiToolchainPatchInitialStoreState*(
    metadataOffset: uint32,
    requestedPatchCount: uint32,
    storedRequestCount: int32,
    writesApplied: uint32): BlaiToolchainPatchInitialStoreState =
  ## Build caller-owned state for the recovered initial metadata store.
  result.metadataOffset = metadataOffset
  result.requestedPatchCount = requestedPatchCount
  result.storedRequestCount = storedRequestCount
  result.writesApplied = writesApplied

proc blaiToolchainPatchInitialStoreApplyPlanInto*(
    store: BlaiToolchainPatchInitialStorePlan,
    outResult: var BlaiToolchainPatchInitialStoreApplyPlan) =
  ## Project a valid initial store plan into caller-owned state.
  outResult = default(BlaiToolchainPatchInitialStoreApplyPlan)
  outResult.store = store
  if not store.valid:
    outResult.firstBlock = blaiToolchainPatchInitialStoreApplyStorePlan
    return

  outResult.stateAfter = blaiToolchainPatchInitialStoreState(
    store.metadataOffset, store.requestedPatchCount,
    store.storedRequestCount, store.writesApplied)
  outResult.firstBlock = blaiToolchainPatchInitialStoreApplyNoBlock
  outResult.valid = true

proc blaiToolchainPatchInitialStoreApplyPlan*(
    store: BlaiToolchainPatchInitialStorePlan):
    BlaiToolchainPatchInitialStoreApplyPlan =
  ## Convenience wrapper for checked first-layer metadata-state projection.
  blaiToolchainPatchInitialStoreApplyPlanInto(store, result)

proc blaiApplyToolchainPatchInitialStoreState*(
    state: var BlaiToolchainPatchInitialStoreState,
    plan: BlaiToolchainPatchInitialStoreApplyPlan): bool =
  ## Apply a checked initial metadata-state projection.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPatchInitialStoreMetadataState*(
    requestMetadata: var int32,
    state: BlaiToolchainPatchInitialStoreState) =
  ## Apply initial request metadata from typed state to scalar storage.
  requestMetadata = state.storedRequestCount

proc blaiApplyToolchainPatchInitialStoreScalarState*(
    metadataOffset: var uint32,
    requestedPatchCount: var uint32,
    storedRequestCount: var int32,
    writesApplied: var uint32,
    state: BlaiToolchainPatchInitialStoreState): bool =
  ## Apply recovered initial request metadata-store scalars from typed state.
  metadataOffset = state.metadataOffset
  requestedPatchCount = state.requestedPatchCount
  storedRequestCount = state.storedRequestCount
  writesApplied = state.writesApplied
  true

proc blaiApplyToolchainPatchInitialStoreScalars*(
    metadataOffset: var uint32,
    requestedPatchCount: var uint32,
    storedRequestCount: var int32,
    writesApplied: var uint32,
    plan: BlaiToolchainPatchInitialStoreApplyPlan): bool =
  ## Apply recovered initial request metadata-store scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPatchInitialStoreScalarState(
    metadataOffset, requestedPatchCount, storedRequestCount, writesApplied,
    plan.stateAfter)

proc blaiApplyToolchainPatchInitialStore*(
    requestMetadata: var int32,
    plan: BlaiToolchainPatchInitialStorePlan): bool =
  ## Apply the recovered first-layer request-count metadata write.
  let applyPlan = blaiToolchainPatchInitialStoreApplyPlan(plan)
  if not applyPlan.valid:
    return false
  blaiApplyToolchainPatchInitialStoreMetadataState(
    requestMetadata, applyPlan.stateAfter)
  true

proc blaiToolchainPatchInitialPlanInto*(
    occupied: openArray[bool],
    owners: openArray[int32],
    requestedPatchCount: uint32,
    outResult: var BlaiToolchainPatchInitialPlan) =
  ## Recover initial patch reservation from `PSRAM_allocate`.
  ##
  ## The converter initializes the first `requestedPatchCount` patch bitmap
  ## entries to occupied and assigns owner layer zero. This checked plan keeps
  ## that mutation explicit before caller-owned arrays are changed.
  outResult = default(BlaiToolchainPatchInitialPlan)
  outResult.patchStorageCount = blaiOpenArrayLenU32(occupied)
  outResult.ownerStorageCount = blaiOpenArrayLenU32(owners)
  outResult.requestedPatchCount = requestedPatchCount
  outResult.owner = 0'i32
  if requestedPatchCount == 0'u32:
    outResult.firstBlock = blaiToolchainPatchInitialRequestedCount
    return
  if requestedPatchCount > outResult.patchStorageCount or
     requestedPatchCount > outResult.ownerStorageCount:
    outResult.firstBlock = blaiToolchainPatchInitialStorage
    return

  outResult.writesApplied = requestedPatchCount
  outResult.firstBlock = blaiToolchainPatchInitialNoBlock
  outResult.valid = true

proc blaiToolchainPatchInitialPlan*(
    occupied: openArray[bool],
    owners: openArray[int32],
    requestedPatchCount: uint32): BlaiToolchainPatchInitialPlan =
  ## Convenience wrapper for recovered initial patch reservation.
  blaiToolchainPatchInitialPlanInto(
    occupied, owners, requestedPatchCount, result)

proc blaiToolchainPatchInitialState*(
    requestedPatchCount: uint32,
    owner: int32,
    writesApplied: uint32,
    occupiedAfter: array[BlaiMaxWeightPatches, bool],
    ownerAfter: array[BlaiMaxWeightPatches, int32]):
    BlaiToolchainPatchInitialState =
  ## Build caller-owned state for recovered initial patch reservation.
  result.requestedPatchCount = requestedPatchCount
  result.owner = owner
  result.writesApplied = writesApplied
  result.occupiedAfter = occupiedAfter
  result.ownerAfter = ownerAfter

proc blaiToolchainPatchInitialApplyPlanInto*(
    reservation: BlaiToolchainPatchInitialPlan,
    occupied: openArray[bool],
    owners: openArray[int32],
    outResult: var BlaiToolchainPatchInitialApplyPlan) =
  ## Project a valid initial reservation into checked caller-owned state.
  outResult = default(BlaiToolchainPatchInitialApplyPlan)
  outResult.reservation = reservation
  outResult.patchStorageCount = blaiOpenArrayLenU32(occupied)
  outResult.ownerStorageCount = blaiOpenArrayLenU32(owners)
  if not reservation.valid:
    outResult.firstBlock = blaiToolchainPatchInitialApplyReservationPlan
    return
  if reservation.requestedPatchCount > BlaiMaxWeightPatchesU32:
    outResult.firstBlock = blaiToolchainPatchInitialApplyStorage
    return

  outResult.stateAfter.requestedPatchCount = reservation.requestedPatchCount
  outResult.stateAfter.owner = reservation.owner
  outResult.stateAfter.writesApplied = reservation.writesApplied
  for patchIndex in 0'u32 ..< reservation.requestedPatchCount:
    let occupiedCursor =
      blaiToolchainPatchOccupiedCursor(patchIndex, occupied.len)
    let ownerCursor =
      blaiToolchainPatchOwnerCursor(patchIndex, owners.len)
    let stateCursor = blaiToolchainPatchStateCursor(patchIndex)
    if not occupiedCursor.valid or not ownerCursor.valid or
       not stateCursor.valid:
      outResult = default(BlaiToolchainPatchInitialApplyPlan)
      outResult.reservation = reservation
      outResult.patchStorageCount = blaiOpenArrayLenU32(occupied)
      outResult.ownerStorageCount = blaiOpenArrayLenU32(owners)
      outResult.firstBlock = blaiToolchainPatchInitialApplyStorage
      return
    outResult.stateAfter.occupiedAfter[stateCursor.index] = true
    outResult.stateAfter.ownerAfter[stateCursor.index] = reservation.owner

  outResult.firstBlock = blaiToolchainPatchInitialApplyNoBlock
  outResult.valid = true

proc blaiToolchainPatchInitialApplyPlan*(
    reservation: BlaiToolchainPatchInitialPlan,
    occupied: openArray[bool],
    owners: openArray[int32]): BlaiToolchainPatchInitialApplyPlan =
  ## Convenience wrapper for checked initial reservation-state projection.
  blaiToolchainPatchInitialApplyPlanInto(
    reservation, occupied, owners, result)

proc blaiApplyToolchainPatchInitialReservationTableState*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    state: BlaiToolchainPatchInitialState): bool =
  ## Apply checked initial reservation state to caller-owned arrays.
  for patchIndex in 0'u32 ..< state.writesApplied:
    let occupiedCursor =
      blaiToolchainPatchOccupiedCursor(patchIndex, occupied.len)
    let ownerCursor =
      blaiToolchainPatchOwnerCursor(patchIndex, owners.len)
    let stateCursor = blaiToolchainPatchStateCursor(patchIndex)
    if not occupiedCursor.valid or not ownerCursor.valid or
       not stateCursor.valid:
      return false
    occupied[occupiedCursor.index] =
      state.occupiedAfter[stateCursor.index]
    owners[ownerCursor.index] =
      state.ownerAfter[stateCursor.index]
  true

proc blaiApplyToolchainPatchInitialReservationState*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    plan: BlaiToolchainPatchInitialApplyPlan): bool =
  ## Apply checked initial reservation state to caller-owned arrays.
  if not plan.valid:
    return false
  blaiApplyToolchainPatchInitialReservationTableState(
    occupied, owners, plan.stateAfter)

proc blaiApplyToolchainPatchInitialReservationScalarState*(
    requestedPatchCount: var uint32,
    owner: var int32,
    writesApplied: var uint32,
    state: BlaiToolchainPatchInitialState): bool =
  ## Apply recovered initial reservation metadata from typed state.
  requestedPatchCount = state.requestedPatchCount
  owner = state.owner
  writesApplied = state.writesApplied
  true

proc blaiApplyToolchainPatchInitialReservationScalars*(
    requestedPatchCount: var uint32,
    owner: var int32,
    writesApplied: var uint32,
    plan: BlaiToolchainPatchInitialApplyPlan): bool =
  ## Apply recovered initial reservation metadata.
  if not plan.valid:
    return false
  blaiApplyToolchainPatchInitialReservationScalarState(
    requestedPatchCount, owner, writesApplied, plan.stateAfter)

proc blaiApplyToolchainPatchInitialReservation*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    plan: BlaiToolchainPatchInitialPlan): bool =
  ## Apply recovered initial bitmap/owner writes for slots starting at zero.
  let applyPlan = blaiToolchainPatchInitialApplyPlan(plan, occupied, owners)
  blaiApplyToolchainPatchInitialReservationState(occupied, owners, applyPlan)

proc blaiToolchainPatchPreviousOwnerPlanInto*(
    layerTypeValue: int32,
    inheritedPreviousOwnerFlag: bool,
    outResult: var BlaiToolchainPatchPreviousOwnerPlan) =
  ## Recover previous-owner flag selection before `search_set_patch`.
  ##
  ## `PSRAM_allocate` passes a previous-owner flag into the patch-search helper
  ## after OR-ing the inherited flag with a raw toolchain layer-type check for
  ## 0x1b. The owner-selection plan consumes the resulting boolean.
  outResult = default(BlaiToolchainPatchPreviousOwnerPlan)
  outResult.layerTypeValue = layerTypeValue
  outResult.inheritedPreviousOwnerFlag = inheritedPreviousOwnerFlag
  outResult.typeMatchesPreviousOwner =
    layerTypeValue == BlaiToolchainPatchPreviousOwnerType
  outResult.selectedPreviousOwnerFlag =
    inheritedPreviousOwnerFlag or outResult.typeMatchesPreviousOwner
  outResult.valid = true

proc blaiToolchainPatchPreviousOwnerPlan*(
    layerTypeValue: int32,
    inheritedPreviousOwnerFlag: bool): BlaiToolchainPatchPreviousOwnerPlan =
  ## Convenience wrapper for recovered previous-owner flag selection.
  blaiToolchainPatchPreviousOwnerPlanInto(
    layerTypeValue, inheritedPreviousOwnerFlag, result)

proc blaiToolchainPatchOwnerPlanInto*(
    mode: BlaiToolchainPatchOwnerMode,
    currentLayerIndex, relationConsumerLayerIndex: int32,
    relationConsumerFound, previousOwnerFlag: bool,
    outResult: var BlaiToolchainPatchOwnerPlan) =
  ## Recover owner selection before patch-search assignment writes.
  ##
  ## `search_set_patch` keeps owner `current - 1` when its previous-owner flag
  ## is active; otherwise it uses the future relation consumer when present, or
  ## `current + 1`. `search_set_dsp_patch` uses the same previous/future
  ## gates, but falls back to owner `current`. `tflite_search_set_patch` uses
  ## the future consumer when present and owner `1` otherwise.
  outResult = default(BlaiToolchainPatchOwnerPlan)
  outResult.mode = mode
  outResult.currentLayerIndex = currentLayerIndex
  outResult.relationConsumerLayerIndex = relationConsumerLayerIndex
  outResult.relationConsumerFound = relationConsumerFound
  outResult.previousOwnerFlag = previousOwnerFlag
  if currentLayerIndex < 0:
    outResult.firstBlock = blaiToolchainPatchOwnerLayerIndex
    return
  if relationConsumerFound and relationConsumerLayerIndex < 0:
    outResult.firstBlock = blaiToolchainPatchOwnerConsumer
    return

  case mode
  of blaiToolchainPatchOwnerGeneral:
    if previousOwnerFlag:
      if currentLayerIndex == low(int32):
        outResult.firstBlock = blaiToolchainPatchOwnerLayerIndex
        return
      outResult.selectedOwner = currentLayerIndex - 1
    elif relationConsumerFound:
      outResult.selectedOwner = relationConsumerLayerIndex
    else:
      if currentLayerIndex == high(int32):
        outResult.firstBlock = blaiToolchainPatchOwnerLayerIndex
        return
      outResult.selectedOwner = currentLayerIndex + 1
  of blaiToolchainPatchOwnerDsp:
    if previousOwnerFlag:
      if currentLayerIndex == low(int32):
        outResult.firstBlock = blaiToolchainPatchOwnerLayerIndex
        return
      outResult.selectedOwner = currentLayerIndex - 1
    elif relationConsumerFound:
      outResult.selectedOwner = relationConsumerLayerIndex
    else:
      outResult.selectedOwner = currentLayerIndex
  of blaiToolchainPatchOwnerTflite:
    if relationConsumerFound:
      outResult.selectedOwner = relationConsumerLayerIndex
    else:
      outResult.selectedOwner = 1'i32
  outResult.firstBlock = blaiToolchainPatchOwnerNoBlock
  outResult.valid = true

proc blaiToolchainPatchOwnerPlan*(
    mode: BlaiToolchainPatchOwnerMode,
    currentLayerIndex, relationConsumerLayerIndex: int32,
    relationConsumerFound, previousOwnerFlag: bool):
    BlaiToolchainPatchOwnerPlan =
  ## Convenience wrapper for recovered patch-search owner selection.
  blaiToolchainPatchOwnerPlanInto(
    mode, currentLayerIndex, relationConsumerLayerIndex, relationConsumerFound,
    previousOwnerFlag, result)

proc blaiToolchainPatchDispatchPlanInto*(
    mode: BlaiToolchainPatchOwnerMode,
    currentLayerIndex: int32,
    requestedPatchCount: uint32,
    relationConsumerLayerIndex: int32,
    relationConsumerFound, previousOwnerFlag, debugLogFlag: bool,
    outResult: var BlaiToolchainPatchDispatchPlan) =
  ## Recover the caller-side `PSRAM_allocate` patch-search dispatch ABI.
  outResult = default(BlaiToolchainPatchDispatchPlan)
  outResult.mode = mode
  outResult.currentLayerIndex = currentLayerIndex
  outResult.requestedPatchCount = requestedPatchCount
  outResult.relationConsumerLayerIndex = relationConsumerLayerIndex
  outResult.relationConsumerFound = relationConsumerFound
  outResult.previousOwnerFlag = previousOwnerFlag
  outResult.debugLogFlag = debugLogFlag
  blaiToolchainPatchOwnerPlanInto(
    mode, currentLayerIndex, relationConsumerLayerIndex, relationConsumerFound,
    previousOwnerFlag, outResult.owner)
  if not outResult.owner.valid:
    outResult.firstBlock = blaiToolchainPatchDispatchOwner
    return

  case mode
  of blaiToolchainPatchOwnerGeneral:
    outResult.metadataMode = blaiToolchainPatchMetadataGeneral
    outResult.generalSearchCall = true
  of blaiToolchainPatchOwnerDsp:
    outResult.metadataMode = blaiToolchainPatchMetadataDsp
    outResult.generalSearchCall = true
    outResult.dspSearchCall = true
  of blaiToolchainPatchOwnerTflite:
    outResult.metadataMode = blaiToolchainPatchMetadataTflite
    outResult.tfliteSearchCall = true
  outResult.firstBlock = blaiToolchainPatchDispatchNoBlock
  outResult.valid = true

proc blaiToolchainPatchDispatchPlan*(
    mode: BlaiToolchainPatchOwnerMode,
    currentLayerIndex: int32,
    requestedPatchCount: uint32,
    relationConsumerLayerIndex: int32,
    relationConsumerFound, previousOwnerFlag, debugLogFlag: bool):
    BlaiToolchainPatchDispatchPlan =
  ## Convenience wrapper for recovered patch-search dispatch.
  blaiToolchainPatchDispatchPlanInto(
    mode, currentLayerIndex, requestedPatchCount, relationConsumerLayerIndex,
    relationConsumerFound, previousOwnerFlag, debugLogFlag, result)

proc blaiToolchainPatchSearchPlanInto*(
    occupied: openArray[bool],
    requestedPatchCount: uint32,
    outResult: var BlaiToolchainPatchSearchPlan) =
  ## Recover toolchain `search_set_patch` contiguous free patch-slot search.
  ##
  ## The converter walks the `MAX_PSRAM_PATCH` bitmap, finds the first
  ## contiguous free run large enough for the request, and rejects assignments
  ## whose first slot is above 31.
  outResult = default(BlaiToolchainPatchSearchPlan)
  outResult.patchStorageCount = blaiOpenArrayLenU32(occupied)
  outResult.requestedPatchCount = requestedPatchCount
  outResult.maxStartPatchSlot = BlaiToolchainMaxPatchStartSlot
  if requestedPatchCount == 0'u32:
    outResult.firstBlock = blaiToolchainPatchSearchRequestedCount
    return
  if requestedPatchCount > outResult.patchStorageCount:
    outResult.firstBlock = blaiToolchainPatchSearchStorage
    return

  var runStart = 0'u32
  var runLength = 0'u32
  var found = false
  for patchIndex in 0'u32 ..< outResult.patchStorageCount:
    let patchCursor =
      blaiToolchainPatchOccupiedCursor(patchIndex, occupied.len)
    if not patchCursor.valid:
      outResult.firstBlock = blaiToolchainPatchSearchStorage
      return
    inc outResult.scannedPatchSlots
    if occupied[patchCursor.index]:
      runLength = 0
      continue
    if runLength == 0'u32:
      runStart = patchIndex
    inc runLength
    if runLength == requestedPatchCount:
      found = true
      break

  if not found:
    outResult.firstBlock = blaiToolchainPatchSearchNoRun
    return
  if runStart > BlaiToolchainMaxPatchStartSlot:
    outResult.startPatchSlot = runStart
    outResult.assignedPatchCount = requestedPatchCount
    outResult.firstBlock = blaiToolchainPatchSearchStartSlot
    return

  outResult.startPatchSlot = runStart
  outResult.assignedPatchCount = requestedPatchCount
  outResult.firstBlock = blaiToolchainPatchSearchNoBlock
  outResult.valid = true

proc blaiToolchainPatchSearchPlan*(
    occupied: openArray[bool],
    requestedPatchCount: uint32): BlaiToolchainPatchSearchPlan =
  ## Convenience wrapper for toolchain patch-slot search.
  blaiToolchainPatchSearchPlanInto(occupied, requestedPatchCount, result)

proc blaiToolchainPatchMetadataPlanInto*(
    mode: BlaiToolchainPatchMetadataMode,
    search: BlaiToolchainPatchSearchPlan,
    layerIndex: int32,
    outResult: var BlaiToolchainPatchMetadataPlan)

proc blaiToolchainPatchSearchHelperEvidenceInto*(
    occupied: openArray[bool],
    requestedPatchCount: uint32,
    layerIndex: int32,
    alternateOwner: int32,
    outResult: var BlaiToolchainPatchSearchHelperEvidence) =
  ## Compare recovered normal and TFLite patch-search helper semantics.
  outResult = default(BlaiToolchainPatchSearchHelperEvidence)
  blaiToolchainPatchSearchPlanInto(
    occupied, requestedPatchCount, outResult.search)
  blaiToolchainPatchMetadataPlanInto(
    blaiToolchainPatchMetadataGeneral, outResult.search, layerIndex,
    outResult.normalMetadata)
  blaiToolchainPatchMetadataPlanInto(
    blaiToolchainPatchMetadataTflite, outResult.search, layerIndex,
    outResult.tfliteMetadata)
  outResult.tfliteDefaultOwner = 1'i32
  outResult.tfliteAlternateOwner = alternateOwner
  outResult.searchShared = outResult.search.valid
  outResult.rejectsStartAbove31 =
    outResult.search.maxStartPatchSlot == BlaiToolchainMaxPatchStartSlot
  outResult.normalStoresPatchCount =
    outResult.normalMetadata.valid and outResult.normalMetadata.storesPatchCount
  outResult.tfliteStoresOnlyStart =
    outResult.tfliteMetadata.valid and
      outResult.tfliteMetadata.mode == blaiToolchainPatchMetadataTflite and
      not outResult.tfliteMetadata.storesPatchCount and
      outResult.tfliteMetadata.startPatchSlot ==
        outResult.normalMetadata.startPatchSlot
  outResult.tfliteDefaultOwnerOne = outResult.tfliteDefaultOwner == 1'i32
  outResult.tfliteAlternateOwnerSelectable =
    alternateOwner >= 0 and outResult.tfliteAlternateOwner == alternateOwner
  outResult.valid =
    outResult.searchShared and outResult.rejectsStartAbove31 and
      outResult.normalStoresPatchCount and outResult.tfliteStoresOnlyStart and
      outResult.tfliteDefaultOwnerOne and
      outResult.tfliteAlternateOwnerSelectable

proc blaiToolchainPatchSearchHelperEvidence*(
    occupied: openArray[bool],
    requestedPatchCount: uint32,
    layerIndex: int32,
    alternateOwner: int32): BlaiToolchainPatchSearchHelperEvidence =
  ## Convenience wrapper for patch-search helper-pair evidence.
  blaiToolchainPatchSearchHelperEvidenceInto(
    occupied, requestedPatchCount, layerIndex, alternateOwner, result)

proc blaiToolchainPatchMetadataPlanInto*(
    mode: BlaiToolchainPatchMetadataMode,
    search: BlaiToolchainPatchSearchPlan,
    layerIndex: int32,
    outResult: var BlaiToolchainPatchMetadataPlan) =
  ## Recover metadata stores after a toolchain patch assignment.
  ##
  ## `search_set_patch` records both start slot and requested patch count.
  ## `search_set_dsp_patch` and `tflite_search_set_patch` each record only
  ## the start slot in their converter-side metadata banks.
  outResult = default(BlaiToolchainPatchMetadataPlan)
  outResult.mode = mode
  outResult.search = search
  outResult.layerIndex = layerIndex
  if not search.valid:
    outResult.firstBlock = blaiToolchainPatchMetadataSearchPlan
    return
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPatchMetadataLayerIndex
    return
  let startSlot = blaiToolchainPatchStartSlotAbi(search.startPatchSlot)
  if not startSlot.valid:
    outResult.firstBlock = blaiToolchainPatchMetadataOverflow
    return
  let patchCount = blaiToolchainPatchCountAbi(search.assignedPatchCount)
  if not patchCount.valid:
    outResult.firstBlock = blaiToolchainPatchMetadataOverflow
    return

  outResult.startPatchSlot = startSlot.value
  case mode
  of blaiToolchainPatchMetadataGeneral:
    outResult.startOffset = BlaiToolchainPatchDebugGeneralStartOffset
    outResult.countOffset = BlaiToolchainPatchDebugGeneralCountOffset
    outResult.patchCount = patchCount.value
    outResult.storesPatchCount = true
  of blaiToolchainPatchMetadataDsp:
    outResult.startOffset = BlaiToolchainPsramDspDebugStartOffset
    outResult.patchCount = 0
    outResult.storesPatchCount = false
  of blaiToolchainPatchMetadataTflite:
    outResult.startOffset = BlaiToolchainPsramTfliteStartOffset
    outResult.patchCount = 0
    outResult.storesPatchCount = false
  outResult.firstBlock = blaiToolchainPatchMetadataNoBlock
  outResult.valid = true

proc blaiToolchainPatchMetadataPlan*(
    mode: BlaiToolchainPatchMetadataMode,
    search: BlaiToolchainPatchSearchPlan,
    layerIndex: int32): BlaiToolchainPatchMetadataPlan =
  ## Convenience wrapper for recovered patch-search metadata projection.
  blaiToolchainPatchMetadataPlanInto(mode, search, layerIndex, result)

proc blaiToolchainPatchMetadataState*(
    mode: BlaiToolchainPatchMetadataMode,
    layerIndex: int32,
    startOffset, countOffset: uint32,
    startPatchSlot, patchCount: int32,
    storesPatchCount: bool): BlaiToolchainPatchMetadataState =
  ## Build a typed caller-owned patch-search metadata state.
  result.mode = mode
  result.layerIndex = layerIndex
  result.startOffset = startOffset
  result.countOffset = countOffset
  result.startPatchSlot = startPatchSlot
  result.patchCount = patchCount
  result.storesPatchCount = storesPatchCount

proc blaiToolchainPatchMetadataApplyPlanInto*(
    metadata: BlaiToolchainPatchMetadataPlan,
    outResult: var BlaiToolchainPatchMetadataApplyPlan) =
  ## Prepare checked application of patch-search metadata state.
  outResult = default(BlaiToolchainPatchMetadataApplyPlan)
  outResult.metadata = metadata
  if not metadata.valid:
    outResult.firstBlock = blaiToolchainPatchMetadataApplyMetadataPlan
    return

  outResult.stateAfter = blaiToolchainPatchMetadataState(
    metadata.mode, metadata.layerIndex, metadata.startOffset,
    metadata.countOffset, metadata.startPatchSlot, metadata.patchCount,
    metadata.storesPatchCount)
  outResult.firstBlock = blaiToolchainPatchMetadataApplyNoBlock
  outResult.valid = true

proc blaiToolchainPatchMetadataApplyPlan*(
    metadata: BlaiToolchainPatchMetadataPlan):
    BlaiToolchainPatchMetadataApplyPlan =
  ## Convenience wrapper for checked patch-search metadata application.
  blaiToolchainPatchMetadataApplyPlanInto(metadata, result)

proc blaiApplyToolchainPatchMetadataState*(
    state: var BlaiToolchainPatchMetadataState,
    plan: BlaiToolchainPatchMetadataApplyPlan): bool =
  ## Apply recovered patch-search metadata to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPatchMetadataBankState*(
    startPatchSlots: var openArray[int32],
    patchCounts: var openArray[int32],
    state: BlaiToolchainPatchMetadataState): bool =
  ## Apply recovered patch-search metadata state to caller-owned banks.
  let bankIndex = blaiToolchainPsramMetadataBankIndexAbi(state.layerIndex)
  if not bankIndex.valid:
    return false
  let startCursor =
    blaiToolchainPsramMetadataBankCursor(
      bankIndex.value, startPatchSlots.len)
  if not startCursor.valid:
    return false
  var countIndex = 0
  if state.storesPatchCount:
    let countCursor =
      blaiToolchainPsramMetadataBankCursor(
        bankIndex.value, patchCounts.len)
    if not countCursor.valid:
      return false
    countIndex = countCursor.index
  startPatchSlots[startCursor.index] = state.startPatchSlot
  if state.storesPatchCount:
    patchCounts[countIndex] = state.patchCount
  true

proc blaiApplyToolchainPatchMetadataScalarState*(
    mode: var BlaiToolchainPatchMetadataMode,
    layerIndex: var int32,
    startOffset: var uint32,
    countOffset: var uint32,
    startPatchSlot: var int32,
    patchCount: var int32,
    storesPatchCount: var bool,
    state: BlaiToolchainPatchMetadataState): bool =
  ## Apply recovered patch-search metadata scalars from typed state.
  mode = state.mode
  layerIndex = state.layerIndex
  startOffset = state.startOffset
  countOffset = state.countOffset
  startPatchSlot = state.startPatchSlot
  patchCount = state.patchCount
  storesPatchCount = state.storesPatchCount
  true

proc blaiApplyToolchainPatchMetadataScalars*(
