    mode, layerIndex, startOffset, countOffset, startPatchSlot, patchCount,
    storesPatchCount, plan.stateAfter)

proc blaiApplyToolchainPatchMetadata*(
    startPatchSlots: var openArray[int32],
    patchCounts: var openArray[int32],
    plan: BlaiToolchainPatchMetadataPlan): bool =
  ## Apply recovered patch-search metadata stores to typed caller-owned banks.
  let applyPlan = blaiToolchainPatchMetadataApplyPlan(plan)
  if not applyPlan.valid:
    return false
  blaiApplyToolchainPatchMetadataBankState(
    startPatchSlots, patchCounts, applyPlan.stateAfter)

proc blaiToolchainPatchDebugMetadataSnapshotPlanInto*(
    layerIndex: int32,
    debugLogFlag: bool,
    requestTableCount, generalStartPatchSlot, generalPatchCount,
    auxiliaryStartPatchSlot, secondaryStartPatchSlot, layerScalar: int32,
    outResult: var BlaiToolchainPatchDebugMetadataSnapshotPlan) =
  ## Recover the post-dispatch metadata reload used by toolchain logging.
  ##
  ## `PSRAM_allocate` reloads the request table count, general start/count
  ## metadata, two additional patch metadata banks, and a copied-layer scalar
  ## immediately before its debug print. The auxiliary/secondary names are
  ## placeholders until the exact C++ field names behind those banks are known.
  outResult = default(BlaiToolchainPatchDebugMetadataSnapshotPlan)
  outResult.layerIndex = layerIndex
  outResult.debugLogFlag = debugLogFlag
  outResult.requestTableOffset = BlaiToolchainPatchDebugRequestTableOffset
  outResult.generalStartOffset = BlaiToolchainPatchDebugGeneralStartOffset
  outResult.generalCountOffset = BlaiToolchainPatchDebugGeneralCountOffset
  outResult.auxiliaryStartOffset =
    BlaiToolchainPatchDebugAuxiliaryStartOffset
  outResult.secondaryStartOffset =
    BlaiToolchainPatchDebugSecondaryStartOffset
  outResult.metadataStackBytes = BlaiToolchainPatchDebugMetadataStackBytes
  outResult.requestTableCount = requestTableCount
  outResult.generalStartPatchSlot = generalStartPatchSlot
  outResult.generalPatchCount = generalPatchCount
  outResult.auxiliaryStartPatchSlot = auxiliaryStartPatchSlot
  outResult.secondaryStartPatchSlot = secondaryStartPatchSlot
  outResult.layerScalar = layerScalar
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPatchDebugMetadataSnapshotLayerIndex
    return

  outResult.printRequested = debugLogFlag
  outResult.firstBlock = blaiToolchainPatchDebugMetadataSnapshotNoBlock
  outResult.valid = true

proc blaiToolchainPatchDebugMetadataSnapshotPlan*(
    layerIndex: int32,
    debugLogFlag: bool,
    requestTableCount, generalStartPatchSlot, generalPatchCount,
    auxiliaryStartPatchSlot, secondaryStartPatchSlot, layerScalar: int32):
    BlaiToolchainPatchDebugMetadataSnapshotPlan =
  ## Convenience wrapper for recovered post-dispatch debug metadata reload.
  blaiToolchainPatchDebugMetadataSnapshotPlanInto(
    layerIndex, debugLogFlag, requestTableCount, generalStartPatchSlot,
    generalPatchCount, auxiliaryStartPatchSlot, secondaryStartPatchSlot,
    layerScalar, result)

proc blaiToolchainPatchDebugMetadataSnapshotState*(
    requestTableCount, generalStartPatchSlot, generalPatchCount,
    auxiliaryStartPatchSlot, secondaryStartPatchSlot, layerScalar: int32):
    BlaiToolchainPatchDebugMetadataSnapshotState =
  ## Build a typed caller-owned debug metadata snapshot state.
  result.requestTableCount = requestTableCount
  result.generalStartPatchSlot = generalStartPatchSlot
  result.generalPatchCount = generalPatchCount
  result.auxiliaryStartPatchSlot = auxiliaryStartPatchSlot
  result.secondaryStartPatchSlot = secondaryStartPatchSlot
  result.layerScalar = layerScalar

proc blaiToolchainPatchDebugMetadataSnapshotApplyPlanInto*(
    snapshot: BlaiToolchainPatchDebugMetadataSnapshotPlan,
    outResult: var BlaiToolchainPatchDebugMetadataSnapshotApplyPlan) =
  ## Prepare checked application of debug metadata snapshot state.
  outResult = default(BlaiToolchainPatchDebugMetadataSnapshotApplyPlan)
  outResult.snapshot = snapshot
  if not snapshot.valid:
    outResult.firstBlock =
      blaiToolchainPatchDebugMetadataSnapshotApplySnapshotPlan
    return

  outResult.printRequested = snapshot.printRequested
  if snapshot.printRequested:
    outResult.stateAfter = blaiToolchainPatchDebugMetadataSnapshotState(
      snapshot.requestTableCount, snapshot.generalStartPatchSlot,
      snapshot.generalPatchCount, snapshot.auxiliaryStartPatchSlot,
      snapshot.secondaryStartPatchSlot, snapshot.layerScalar)
  outResult.firstBlock = blaiToolchainPatchDebugMetadataSnapshotApplyNoBlock
  outResult.valid = true

proc blaiToolchainPatchDebugMetadataSnapshotApplyPlan*(
    snapshot: BlaiToolchainPatchDebugMetadataSnapshotPlan):
    BlaiToolchainPatchDebugMetadataSnapshotApplyPlan =
  ## Convenience wrapper for checked debug metadata snapshot application.
  blaiToolchainPatchDebugMetadataSnapshotApplyPlanInto(snapshot, result)

proc blaiApplyToolchainPatchDebugMetadataSnapshot*(
