    plan: BlaiToolchainPatchDebugMetadataSnapshotApplyPlan): bool =
  ## Apply recovered debug metadata snapshot values to caller-owned state.
  if not plan.valid:
    return false
  if plan.printRequested:
    state = plan.stateAfter
  true

proc blaiApplyToolchainPatchDebugMetadataSnapshotScalarState*(
    requestTableCount: var int32,
