  requestTableCount = state.requestTableCount
  generalStartPatchSlot = state.generalStartPatchSlot
  generalPatchCount = state.generalPatchCount
  auxiliaryStartPatchSlot = state.auxiliaryStartPatchSlot
  secondaryStartPatchSlot = state.secondaryStartPatchSlot
