proc blaiToolchainPatchDebugStartSlotLookupPlanInto*(
    layerIndex: int32,
    debugLogFlag: bool,
    generalStartPatchSlot: int32,
    slotTable: openArray[int32],
    outResult: var BlaiToolchainPatchDebugStartSlotLookupPlan) =
  ## Recover the debug-only slot-table read after patch metadata dispatch.
  ##
  ## The converter reads `slotTable[generalStartPatchSlot]` only on the
  ## logging path. The table's exact C++ name is still under recovery, so this
  ## helper keeps the neutral `slotTableValue` name while making the index
  ## check explicit and typed.
  outResult = default(BlaiToolchainPatchDebugStartSlotLookupPlan)
  outResult.layerIndex = layerIndex
  outResult.debugLogFlag = debugLogFlag
  outResult.generalStartPatchSlot = generalStartPatchSlot
  outResult.slotTableCount = blaiOpenArrayLenU32(slotTable)
  outResult.lookupRequested = debugLogFlag
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPatchDebugStartSlotLookupLayerIndex
    return
  if not debugLogFlag:
    outResult.firstBlock = blaiToolchainPatchDebugStartSlotLookupNoBlock
    outResult.valid = true
    return
  let startIndex =
    blaiToolchainPatchDebugStartSlotIndexAbi(generalStartPatchSlot)
  if not startIndex.valid:
    outResult.firstBlock = blaiToolchainPatchDebugStartSlotLookupStartSlot
    return

  let cursor =
    blaiU32ArrayIndexCursor(startIndex.value, slotTable.len)
  if not cursor.valid:
    outResult.firstBlock = blaiToolchainPatchDebugStartSlotLookupStorage
    return

  outResult.slotTableValue = slotTable[cursor.index]
  outResult.firstBlock = blaiToolchainPatchDebugStartSlotLookupNoBlock
  outResult.valid = true

proc blaiToolchainPatchDebugStartSlotLookupPlan*(
    layerIndex: int32,
    debugLogFlag: bool,
    generalStartPatchSlot: int32,
    slotTable: openArray[int32]):
    BlaiToolchainPatchDebugStartSlotLookupPlan =
  ## Convenience wrapper for recovered debug-only start-slot lookup.
  blaiToolchainPatchDebugStartSlotLookupPlanInto(
    layerIndex, debugLogFlag, generalStartPatchSlot, slotTable, result)

proc blaiToolchainPatchDebugStartSlotLookupState*(
    lookupRequested: bool,
    slotTableValueAfter: int32): BlaiToolchainPatchDebugStartSlotLookupState =
  ## Build a typed caller-owned debug start-slot lookup state.
  result.lookupRequested = lookupRequested
  result.slotTableValueAfter = slotTableValueAfter

proc blaiToolchainPatchDebugStartSlotLookupApplyPlanInto*(
    lookup: BlaiToolchainPatchDebugStartSlotLookupPlan,
    outResult: var BlaiToolchainPatchDebugStartSlotLookupApplyPlan) =
  ## Prepare checked application of debug start-slot lookup state.
  outResult = default(BlaiToolchainPatchDebugStartSlotLookupApplyPlan)
  outResult.lookup = lookup
  if not lookup.valid:
    outResult.firstBlock =
      blaiToolchainPatchDebugStartSlotLookupApplyLookupPlan
    return

  outResult.lookupRequested = lookup.lookupRequested
  if lookup.lookupRequested:
    outResult.slotTableValueAfter = lookup.slotTableValue
  outResult.stateAfter = blaiToolchainPatchDebugStartSlotLookupState(
    outResult.lookupRequested, outResult.slotTableValueAfter)
  outResult.firstBlock = blaiToolchainPatchDebugStartSlotLookupApplyNoBlock
  outResult.valid = true

proc blaiToolchainPatchDebugStartSlotLookupApplyPlan*(
    lookup: BlaiToolchainPatchDebugStartSlotLookupPlan):
    BlaiToolchainPatchDebugStartSlotLookupApplyPlan =
  ## Convenience wrapper for checked debug start-slot lookup application.
  blaiToolchainPatchDebugStartSlotLookupApplyPlanInto(lookup, result)

proc blaiApplyToolchainPatchDebugStartSlotLookupScalarState*(
    debugSlotValue: var int32,
    state: BlaiToolchainPatchDebugStartSlotLookupState): bool =
  ## Apply recovered debug start-slot lookup state to caller-owned scalar storage.
  if state.lookupRequested:
    debugSlotValue = state.slotTableValueAfter
  true

proc blaiApplyToolchainPatchDebugStartSlotLookup*(
