proc blaiToolchainPatchDebugSearchSnapshotPlanInto*(
    layerIndex: int32,
    debugLogFlag: bool,
    patchCountScalar, layerCursorScalar: int32,
    previousOwnerFlag: bool,
    outResult: var BlaiToolchainPatchDebugSearchSnapshotPlan) =
  ## Recover the debug scalar reload after repeated `search_set_patch` calls.
  ##
  ## `PSRAM_allocate` gates this print on the debug flag, reloads two caller
  ## scalars, and masks the previous-owner flag with `1` before printing. The
  ## scalar names remain neutral until the surrounding C++ field names are
  ## recovered from the toolchain.
  outResult = default(BlaiToolchainPatchDebugSearchSnapshotPlan)
  outResult.layerIndex = layerIndex
  outResult.debugLogFlag = debugLogFlag
  outResult.patchCountScalar = patchCountScalar
  outResult.layerCursorScalar = layerCursorScalar
  outResult.previousOwnerFlag = previousOwnerFlag
  outResult.previousOwnerFlagBit =
    if previousOwnerFlag:
      1'u32
    else:
      0'u32
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPatchDebugSearchSnapshotLayerIndex
    return

  outResult.printRequested = debugLogFlag
  outResult.firstBlock = blaiToolchainPatchDebugSearchSnapshotNoBlock
  outResult.valid = true

proc blaiToolchainPatchDebugSearchSnapshotPlan*(
    layerIndex: int32,
    debugLogFlag: bool,
    patchCountScalar, layerCursorScalar: int32,
    previousOwnerFlag: bool):
    BlaiToolchainPatchDebugSearchSnapshotPlan =
  ## Convenience wrapper for recovered patch-search debug scalar reload.
  blaiToolchainPatchDebugSearchSnapshotPlanInto(
    layerIndex, debugLogFlag, patchCountScalar, layerCursorScalar,
    previousOwnerFlag, result)

proc blaiToolchainPatchDebugSearchSnapshotState*(
    patchCountScalar, layerCursorScalar: int32,
    previousOwnerFlag: bool): BlaiToolchainPatchDebugSearchSnapshotState =
  ## Build a typed caller-owned debug search snapshot state.
  result.patchCountScalar = patchCountScalar
  result.layerCursorScalar = layerCursorScalar
  result.previousOwnerFlag = previousOwnerFlag
  result.previousOwnerFlagBit =
    if previousOwnerFlag:
      1'u32
    else:
      0'u32

proc blaiToolchainPatchDebugSearchSnapshotApplyPlanInto*(
    snapshot: BlaiToolchainPatchDebugSearchSnapshotPlan,
    outResult: var BlaiToolchainPatchDebugSearchSnapshotApplyPlan) =
  ## Prepare checked application of debug search snapshot state.
  outResult = default(BlaiToolchainPatchDebugSearchSnapshotApplyPlan)
  outResult.snapshot = snapshot
  if not snapshot.valid:
    outResult.firstBlock =
      blaiToolchainPatchDebugSearchSnapshotApplySnapshotPlan
    return

  outResult.printRequested = snapshot.printRequested
  if snapshot.printRequested:
    outResult.stateAfter = blaiToolchainPatchDebugSearchSnapshotState(
      snapshot.patchCountScalar, snapshot.layerCursorScalar,
      snapshot.previousOwnerFlag)
  outResult.firstBlock = blaiToolchainPatchDebugSearchSnapshotApplyNoBlock
  outResult.valid = true

proc blaiToolchainPatchDebugSearchSnapshotApplyPlan*(
    snapshot: BlaiToolchainPatchDebugSearchSnapshotPlan):
    BlaiToolchainPatchDebugSearchSnapshotApplyPlan =
  ## Convenience wrapper for checked debug search snapshot application.
  blaiToolchainPatchDebugSearchSnapshotApplyPlanInto(snapshot, result)

proc blaiApplyToolchainPatchDebugSearchSnapshot*(
    state: var BlaiToolchainPatchDebugSearchSnapshotState,
    plan: BlaiToolchainPatchDebugSearchSnapshotApplyPlan): bool =
  ## Apply recovered debug search snapshot values to caller-owned state.
  if not plan.valid:
    return false
  if plan.printRequested:
    state = plan.stateAfter
  true

proc blaiApplyToolchainPatchDebugSearchSnapshotScalarState*(
    patchCountScalar: var int32,
    layerCursorScalar: var int32,
    previousOwnerFlag: var bool,
    state: BlaiToolchainPatchDebugSearchSnapshotState): bool =
  ## Apply recovered debug search snapshot scalars from typed state.
  patchCountScalar = state.patchCountScalar
  layerCursorScalar = state.layerCursorScalar
  previousOwnerFlag = state.previousOwnerFlag
  true

proc blaiApplyToolchainPatchDebugSearchSnapshotScalars*(
    patchCountScalar: var int32,
    layerCursorScalar: var int32,
    previousOwnerFlag: var bool,
    plan: BlaiToolchainPatchDebugSearchSnapshotApplyPlan): bool =
  ## Apply recovered debug search snapshot scalars.
  if not plan.valid:
    return false
  if plan.printRequested:
    return blaiApplyToolchainPatchDebugSearchSnapshotScalarState(
      patchCountScalar, layerCursorScalar, previousOwnerFlag, plan.stateAfter)
  true

static:
  let staticPatchDebugSearchSnapshot =
    BlaiToolchainPatchDebugSearchSnapshotPlan(
      layerIndex: 3,
      debugLogFlag: true,
      patchCountScalar: 2,
      layerCursorScalar: 4,
      previousOwnerFlag: true,
      previousOwnerFlagBit: 1,
      printRequested: true,
      firstBlock: blaiToolchainPatchDebugSearchSnapshotNoBlock,
      valid: true)
  var staticPatchDebugSearchSnapshotApplyInto:
    BlaiToolchainPatchDebugSearchSnapshotApplyPlan
  blaiToolchainPatchDebugSearchSnapshotApplyPlanInto(
    staticPatchDebugSearchSnapshot,
    staticPatchDebugSearchSnapshotApplyInto)
  let staticPatchDebugSearchSnapshotApply =
    blaiToolchainPatchDebugSearchSnapshotApplyPlan(
      staticPatchDebugSearchSnapshot)
  doAssert staticPatchDebugSearchSnapshotApplyInto ==
    staticPatchDebugSearchSnapshotApply
  doAssert staticPatchDebugSearchSnapshotApply.valid
  doAssert staticPatchDebugSearchSnapshotApply.printRequested
  doAssert staticPatchDebugSearchSnapshotApply.stateAfter ==
    blaiToolchainPatchDebugSearchSnapshotState(2, 4, true)
  var staticPatchDebugSearchState =
    blaiToolchainPatchDebugSearchSnapshotState(-1, -1, false)
  doAssert blaiApplyToolchainPatchDebugSearchSnapshot(
    staticPatchDebugSearchState, staticPatchDebugSearchSnapshotApply)
  doAssert staticPatchDebugSearchState ==
    blaiToolchainPatchDebugSearchSnapshotState(2, 4, true)
  var staticPatchDebugSearchPatchScalar = -1'i32
  var staticPatchDebugSearchLayerScalar = -2'i32
  var staticPatchDebugSearchPreviousOwner = false
  doAssert blaiApplyToolchainPatchDebugSearchSnapshotScalarState(
    staticPatchDebugSearchPatchScalar, staticPatchDebugSearchLayerScalar,
    staticPatchDebugSearchPreviousOwner,
    staticPatchDebugSearchSnapshotApply.stateAfter)
  doAssert staticPatchDebugSearchPatchScalar == 2
  doAssert staticPatchDebugSearchLayerScalar == 4
  doAssert staticPatchDebugSearchPreviousOwner
  staticPatchDebugSearchPatchScalar = -1
  staticPatchDebugSearchLayerScalar = -2
  staticPatchDebugSearchPreviousOwner = false
  doAssert blaiApplyToolchainPatchDebugSearchSnapshotScalars(
    staticPatchDebugSearchPatchScalar, staticPatchDebugSearchLayerScalar,
    staticPatchDebugSearchPreviousOwner, staticPatchDebugSearchSnapshotApply)
  doAssert staticPatchDebugSearchPatchScalar == 2
  doAssert staticPatchDebugSearchLayerScalar == 4
  doAssert staticPatchDebugSearchPreviousOwner
  var staticQuietPatchDebugSearchSnapshot =
    staticPatchDebugSearchSnapshot
  staticQuietPatchDebugSearchSnapshot.debugLogFlag = false
  staticQuietPatchDebugSearchSnapshot.printRequested = false
  staticQuietPatchDebugSearchSnapshot.previousOwnerFlag = false
  staticQuietPatchDebugSearchSnapshot.previousOwnerFlagBit = 0
  let staticQuietPatchDebugSearchSnapshotApply =
    blaiToolchainPatchDebugSearchSnapshotApplyPlan(
      staticQuietPatchDebugSearchSnapshot)
  doAssert staticQuietPatchDebugSearchSnapshotApply.valid
  doAssert not staticQuietPatchDebugSearchSnapshotApply.printRequested
  var staticQuietPatchDebugSearchState =
    blaiToolchainPatchDebugSearchSnapshotState(-7, -7, true)
  doAssert blaiApplyToolchainPatchDebugSearchSnapshot(
    staticQuietPatchDebugSearchState, staticQuietPatchDebugSearchSnapshotApply)
  doAssert staticQuietPatchDebugSearchState ==
    blaiToolchainPatchDebugSearchSnapshotState(-7, -7, true)
  staticPatchDebugSearchPatchScalar = -1
  staticPatchDebugSearchLayerScalar = -2
  staticPatchDebugSearchPreviousOwner = true
  doAssert blaiApplyToolchainPatchDebugSearchSnapshotScalars(
    staticPatchDebugSearchPatchScalar, staticPatchDebugSearchLayerScalar,
    staticPatchDebugSearchPreviousOwner,
    staticQuietPatchDebugSearchSnapshotApply)
  doAssert staticPatchDebugSearchPatchScalar == -1
  doAssert staticPatchDebugSearchLayerScalar == -2
  doAssert staticPatchDebugSearchPreviousOwner
  let staticBlockedPatchDebugSearchSnapshotApply =
    blaiToolchainPatchDebugSearchSnapshotApplyPlan(
      BlaiToolchainPatchDebugSearchSnapshotPlan(
        layerIndex: -1,
        debugLogFlag: true,
        printRequested: true,
        firstBlock: blaiToolchainPatchDebugSearchSnapshotLayerIndex,
        valid: false))
  doAssert not staticBlockedPatchDebugSearchSnapshotApply.valid
  doAssert staticBlockedPatchDebugSearchSnapshotApply.firstBlock ==
    blaiToolchainPatchDebugSearchSnapshotApplySnapshotPlan
  var staticBlockedPatchDebugSearchState =
    blaiToolchainPatchDebugSearchSnapshotState(-9, -9, true)
  doAssert not blaiApplyToolchainPatchDebugSearchSnapshot(
    staticBlockedPatchDebugSearchState,
    staticBlockedPatchDebugSearchSnapshotApply)
  doAssert staticBlockedPatchDebugSearchState ==
    blaiToolchainPatchDebugSearchSnapshotState(-9, -9, true)
  staticPatchDebugSearchPatchScalar = -1
  staticPatchDebugSearchLayerScalar = -2
  staticPatchDebugSearchPreviousOwner = true
  doAssert not blaiApplyToolchainPatchDebugSearchSnapshotScalars(
    staticPatchDebugSearchPatchScalar, staticPatchDebugSearchLayerScalar,
    staticPatchDebugSearchPreviousOwner,
    staticBlockedPatchDebugSearchSnapshotApply)
  doAssert staticPatchDebugSearchPatchScalar == -1
  doAssert staticPatchDebugSearchLayerScalar == -2
  doAssert staticPatchDebugSearchPreviousOwner

proc blaiToolchainPatchApplyPlanInto*(
    search: BlaiToolchainPatchSearchPlan,
    owners: openArray[int32],
    owner: int32,
    outResult: var BlaiToolchainPatchApplyPlan) =
  ## Check the owner table before applying a recovered patch assignment.
  outResult = default(BlaiToolchainPatchApplyPlan)
  outResult.search = search
  outResult.owner = owner
  outResult.ownerStorageCount = blaiOpenArrayLenU32(owners)
  outResult.storageFits =
    search.valid and
      search.startPatchSlot <= outResult.ownerStorageCount and
      search.assignedPatchCount <=
        outResult.ownerStorageCount - search.startPatchSlot
  if not search.valid:
    outResult.firstBlock = search.firstBlock
    return
  if not outResult.storageFits:
    outResult.firstBlock = blaiToolchainPatchSearchStorage
    return
  outResult.writesApplied = search.assignedPatchCount
  outResult.firstBlock = blaiToolchainPatchSearchNoBlock
  outResult.valid = true

proc blaiToolchainPatchApplyPlan*(
    search: BlaiToolchainPatchSearchPlan,
    owners: openArray[int32],
    owner: int32): BlaiToolchainPatchApplyPlan =
  ## Convenience wrapper for checked toolchain patch assignment writes.
  blaiToolchainPatchApplyPlanInto(search, owners, owner, result)

proc blaiToolchainPatchAssignmentState*(
    startPatchSlot: uint32,
    assignedPatchCount: uint32,
    owner: int32,
    writesApplied: uint32,
    occupiedAfter: array[BlaiMaxWeightPatches, bool],
    ownerAfter: array[BlaiMaxWeightPatches, int32]):
    BlaiToolchainPatchAssignmentState =
  ## Build caller-owned state for one patch-search assignment.
  result.startPatchSlot = startPatchSlot
  result.assignedPatchCount = assignedPatchCount
  result.owner = owner
  result.writesApplied = writesApplied
  result.occupiedAfter = occupiedAfter
  result.ownerAfter = ownerAfter

proc blaiToolchainPatchAssignmentApplyPlanInto*(
    assignment: BlaiToolchainPatchApplyPlan,
    occupied: openArray[bool],
    owners: openArray[int32],
    outResult: var BlaiToolchainPatchAssignmentApplyPlan) =
  ## Project a valid patch-search assignment into checked state.
  outResult = default(BlaiToolchainPatchAssignmentApplyPlan)
  outResult.assignment = assignment
  outResult.occupiedStorageCount = blaiOpenArrayLenU32(occupied)
  outResult.ownerStorageCount = blaiOpenArrayLenU32(owners)
  if not assignment.valid:
    outResult.firstBlock = blaiToolchainPatchApplyAssignmentPlan
    return
  if assignment.search.assignedPatchCount > BlaiMaxWeightPatchesU32:
    outResult.firstBlock = blaiToolchainPatchApplyStorage
    return

  outResult.stateAfter.startPatchSlot = assignment.search.startPatchSlot
  outResult.stateAfter.assignedPatchCount =
    assignment.search.assignedPatchCount
  outResult.stateAfter.owner = assignment.owner
  outResult.stateAfter.writesApplied = assignment.writesApplied
  for patchOffset in 0'u32 ..< assignment.search.assignedPatchCount:
    if patchOffset > high(uint32) - assignment.search.startPatchSlot:
      outResult.firstBlock = blaiToolchainPatchApplyStorage
      return
    let patchIndex = assignment.search.startPatchSlot + patchOffset
    let occupiedCursor =
      blaiToolchainPatchOccupiedCursor(patchIndex, occupied.len)
    let ownerCursor =
      blaiToolchainPatchOwnerCursor(patchIndex, owners.len)
    let stateCursor = blaiToolchainPatchStateCursor(patchOffset)
    if not occupiedCursor.valid or not ownerCursor.valid or
       not stateCursor.valid:
      outResult = default(BlaiToolchainPatchAssignmentApplyPlan)
      outResult.assignment = assignment
      outResult.occupiedStorageCount = blaiOpenArrayLenU32(occupied)
      outResult.ownerStorageCount = blaiOpenArrayLenU32(owners)
      outResult.firstBlock = blaiToolchainPatchApplyStorage
      return
    outResult.stateAfter.occupiedAfter[stateCursor.index] = true
    outResult.stateAfter.ownerAfter[stateCursor.index] = assignment.owner

  outResult.firstBlock = blaiToolchainPatchApplyNoBlock
  outResult.valid = true

proc blaiToolchainPatchAssignmentApplyPlan*(
    assignment: BlaiToolchainPatchApplyPlan,
    occupied: openArray[bool],
    owners: openArray[int32]): BlaiToolchainPatchAssignmentApplyPlan =
  ## Convenience wrapper for checked patch-search assignment state.
  blaiToolchainPatchAssignmentApplyPlanInto(
    assignment, occupied, owners, result)

proc blaiApplyToolchainPatchAssignmentTableState*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    state: BlaiToolchainPatchAssignmentState): bool =
  ## Apply checked patch-search assignment state to caller-owned arrays.
  for patchOffset in 0'u32 ..< state.writesApplied:
    if patchOffset > high(uint32) - state.startPatchSlot:
      return false
    let patchIndex = state.startPatchSlot + patchOffset
    let occupiedCursor =
      blaiToolchainPatchOccupiedCursor(patchIndex, occupied.len)
    let ownerCursor =
      blaiToolchainPatchOwnerCursor(patchIndex, owners.len)
    let stateCursor = blaiToolchainPatchStateCursor(patchOffset)
    if not occupiedCursor.valid or not ownerCursor.valid or
       not stateCursor.valid:
      return false
    occupied[occupiedCursor.index] =
      state.occupiedAfter[stateCursor.index]
    owners[ownerCursor.index] =
      state.ownerAfter[stateCursor.index]
  true

proc blaiApplyToolchainPatchAssignmentState*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    plan: BlaiToolchainPatchAssignmentApplyPlan): bool =
  ## Apply checked patch-search assignment state to caller-owned arrays.
  if not plan.valid:
    return false
  blaiApplyToolchainPatchAssignmentTableState(
    occupied, owners, plan.stateAfter)

proc blaiApplyToolchainPatchAssignmentScalarState*(
    startPatchSlot: var uint32,
    assignedPatchCount: var uint32,
    owner: var int32,
    writesApplied: var uint32,
    state: BlaiToolchainPatchAssignmentState): bool =
  ## Apply recovered patch assignment metadata from typed state.
  startPatchSlot = state.startPatchSlot
  assignedPatchCount = state.assignedPatchCount
  owner = state.owner
  writesApplied = state.writesApplied
  true

proc blaiApplyToolchainPatchAssignmentScalars*(
    startPatchSlot: var uint32,
    assignedPatchCount: var uint32,
    owner: var int32,
    writesApplied: var uint32,
    plan: BlaiToolchainPatchAssignmentApplyPlan): bool =
  ## Apply recovered patch assignment metadata.
  if not plan.valid:
    return false
  blaiApplyToolchainPatchAssignmentScalarState(
    startPatchSlot, assignedPatchCount, owner, writesApplied, plan.stateAfter)

proc blaiApplyToolchainPatchAssignment*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    plan: BlaiToolchainPatchApplyPlan): bool =
  ## Apply recovered bitmap and owner writes for one toolchain patch run.
  let applyPlan = blaiToolchainPatchAssignmentApplyPlan(
    plan, occupied, owners)
  blaiApplyToolchainPatchAssignmentState(occupied, owners, applyPlan)

proc blaiToolchainSramGlobalsEvidenceInto*(
    outResult: var BlaiToolchainSramGlobalsEvidence) =
  ## Project converter `PATCH_SIZE` and `MAX_PSRAM_PATCH` data symbols.
  outResult = default(BlaiToolchainSramGlobalsEvidence)
  outResult.patchSizeBytes = BlaiToolchainPatchSizeBytes
  outResult.maxPsramPatchSlots = BlaiToolchainMaxPsramPatchSlots
  outResult.maxStartPatchSlot = BlaiToolchainMaxPatchStartSlot
  outResult.localPlannerCapacity = BlaiMaxWeightPatchesU32
  outResult.maxPatchSlotsFitLocalPlanner =
    outResult.maxPsramPatchSlots <= outResult.localPlannerCapacity
  outResult.maxStartFitsPatchSlots =
    outResult.maxStartPatchSlot < outResult.maxPsramPatchSlots
  outResult.valid =
    outResult.patchSizeBytes != 0'u32 and
      outResult.maxPatchSlotsFitLocalPlanner and
      outResult.maxStartFitsPatchSlots

proc blaiToolchainSramGlobalsEvidence*(): BlaiToolchainSramGlobalsEvidence =
  ## Convenience wrapper for recovered converter SRAM planner globals.
  blaiToolchainSramGlobalsEvidenceInto(result)

proc blaiToolchainCfgMemoryEvidenceInto*(
    outResult: var BlaiToolchainCfgMemoryEvidence) =
  ## Project `BLAI.cfg` memory units into recovered byte-sized globals.
  outResult = default(BlaiToolchainCfgMemoryEvidence)
  outResult.cfgPatchSizeElements = BlaiToolchainCfgPatchSizeElements
  outResult.cfgPatchElementBytes = BlaiToolchainCfgPatchElementBytes
  outResult.recoveredPatchSizeBytes = BlaiToolchainPatchSizeBytes
  outResult.cfgPatchNum = BlaiToolchainCfgPatchNum
  outResult.maxPsramPatchSlots = BlaiToolchainMaxPsramPatchSlots
  outResult.cfgPatchSizeBytes =
    outResult.cfgPatchSizeElements * outResult.cfgPatchElementBytes
  outResult.patchSizeMatchesRecovered =
    outResult.cfgPatchSizeBytes == outResult.recoveredPatchSizeBytes
  outResult.cfgCoversPlannerSlots =
    outResult.cfgPatchNum >= outResult.maxPsramPatchSlots
  outResult.cfgTotalBytes =
    outResult.cfgPatchSizeBytes * outResult.cfgPatchNum
  outResult.activePlannerBytes =
    outResult.recoveredPatchSizeBytes * outResult.maxPsramPatchSlots
  if outResult.cfgCoversPlannerSlots:
    outResult.sparePatchSlots =
      outResult.cfgPatchNum - outResult.maxPsramPatchSlots
    outResult.sparePatchBytes =
      outResult.sparePatchSlots * outResult.cfgPatchSizeBytes
  outResult.cfgCapacityCoversPlanner =
    outResult.cfgTotalBytes >= outResult.activePlannerBytes and
      outResult.cfgTotalBytes == outResult.activePlannerBytes +
        outResult.sparePatchBytes
  outResult.valid =
    outResult.cfgPatchSizeElements != 0'u32 and
      outResult.cfgPatchElementBytes == sizeof(int32).uint32 and
      outResult.patchSizeMatchesRecovered and
      outResult.cfgCoversPlannerSlots and
      outResult.cfgCapacityCoversPlanner

proc blaiToolchainCfgMemoryEvidence*(): BlaiToolchainCfgMemoryEvidence =
  ## Convenience wrapper for recovered toolchain cfg memory-unit evidence.
  blaiToolchainCfgMemoryEvidenceInto(result)

proc blaiMnistGeneratedPackageContractInto*(
    model: BlaiMnistTfliteModelPlan,
    sample: BlaiMnistTfliteSampleOracle,
    cfgMemory: BlaiToolchainCfgMemoryEvidence,
    outResult: var BlaiMnistGeneratedPackageContract) =
  ## Compose the fetched MNIST model, sample BMP, cfg, and generated-header ABI.
  outResult = default(BlaiMnistGeneratedPackageContract)
  outResult.model = model
  outResult.sample = sample
  outResult.cfgMemory = cfgMemory
  outResult.converterOutputs = blaiToolchainConverterOutputContract()
  outResult.header = blaiGeneratedModelHeaderContract()
  outResult.imageSidecar = blaiGeneratedImageSidecarOracle(sample)
  outResult.modelReady = model.valid
  outResult.sampleReady = sample.valid
  outResult.modelMatchesSample =
    outResult.modelReady and outResult.sampleReady and model.inputTensor == 0'u32 and
      model.outputTensor == sample.outputTensor and
      model.tensors[0].shape == [1'u32, 28, 28, 1] and
      model.tensors[17].shape == [1'u32, 10, 0, 0]
  outResult.converterReady = outResult.converterOutputs.valid
  outResult.cfgReady = cfgMemory.valid
  outResult.headerReady = outResult.header.valid
  outResult.imageSidecarReady = outResult.imageSidecar.valid
  outResult.outputOracleReady =
    outResult.sampleReady and sample.outputVector[7] == sample.topScore and
      sample.topClass == 7'u32
  if not outResult.modelReady:
    outResult.firstBlock = blaiMnistGeneratedPackageModel
  elif not outResult.sampleReady:
    outResult.firstBlock = blaiMnistGeneratedPackageSample
  elif not outResult.modelMatchesSample:
    outResult.firstBlock = blaiMnistGeneratedPackageModelSample
  elif not outResult.converterReady:
    outResult.firstBlock = blaiMnistGeneratedPackageConverter
  elif not outResult.cfgReady:
    outResult.firstBlock = blaiMnistGeneratedPackageCfg
  elif not outResult.headerReady:
    outResult.firstBlock = blaiMnistGeneratedPackageHeader
  elif not outResult.imageSidecarReady:
    outResult.firstBlock = blaiMnistGeneratedPackageImageSidecar
  elif not outResult.outputOracleReady:
    outResult.firstBlock = blaiMnistGeneratedPackageOutputOracle
  else:
    outResult.firstBlock = blaiMnistGeneratedPackageNoBlock
  outResult.valid =
    outResult.modelMatchesSample and outResult.converterReady and
      outResult.cfgReady and outResult.headerReady and
      outResult.imageSidecarReady and outResult.outputOracleReady

proc blaiMnistGeneratedPackageContract*(
    model: BlaiMnistTfliteModelPlan,
    sample: BlaiMnistTfliteSampleOracle,
    cfgMemory: BlaiToolchainCfgMemoryEvidence):
    BlaiMnistGeneratedPackageContract =
  ## Convenience wrapper for the generated MNIST package contract.
  blaiMnistGeneratedPackageContractInto(model, sample, cfgMemory, result)

proc blaiMnistGeneratedPackageContract*():
    BlaiMnistGeneratedPackageContract =
  ## Compose the current fetched-MNIST generated-package contract.
  blaiMnistGeneratedPackageContract(
    blaiMnistTfliteModelPlan(),
    blaiMnistTfliteSampleOracle(),
    blaiToolchainCfgMemoryEvidence())

proc blaiMnistToolchainSramReadinessEvidenceInto*(
    package: BlaiMnistGeneratedPackageContract,
    globals: BlaiToolchainSramGlobalsEvidence,
    outResult: var BlaiMnistToolchainSramReadinessEvidence) =
  ## Bind the generated MNIST package to recovered toolchain SRAM geometry.
  outResult = default(BlaiMnistToolchainSramReadinessEvidence)
  outResult.packageValid = package.valid
  outResult.packageFirstBlock = package.firstBlock
  outResult.sramGlobalsValid = globals.valid
  outResult.cfgMemoryValid = package.cfgMemory.valid
  outResult.patchSizeBytes = globals.patchSizeBytes
  outResult.cfgPatchSizeBytes = package.cfgMemory.cfgPatchSizeBytes
  outResult.activePlannerSlots = globals.maxPsramPatchSlots
  outResult.cfgPatchSlots = package.cfgMemory.cfgPatchNum
  outResult.sparePatchSlots = package.cfgMemory.sparePatchSlots
  outResult.activePlannerBytes = package.cfgMemory.activePlannerBytes
  outResult.cfgTotalBytes = package.cfgMemory.cfgTotalBytes
  outResult.sparePatchBytes = package.cfgMemory.sparePatchBytes
  outResult.localPlannerCapacity = globals.localPlannerCapacity
  outResult.persistentTensorBufferBytes =
    package.model.persistentTensorBufferBytes
  outResult.persistentTensorPatchSlots =
    blaiCeilDivU32(
      outResult.persistentTensorBufferBytes, outResult.patchSizeBytes)
  if outResult.persistentTensorBufferBytes <= outResult.patchSizeBytes:
    outResult.persistentTensorSpareBytes =
      outResult.patchSizeBytes - outResult.persistentTensorBufferBytes
  outResult.patchSizeMatchesCfg =
    package.cfgMemory.patchSizeMatchesRecovered and
      outResult.patchSizeBytes == outResult.cfgPatchSizeBytes
  outResult.cfgCoversActivePlanner =
    package.cfgMemory.cfgCoversPlannerSlots and
      outResult.cfgPatchSlots >= outResult.activePlannerSlots
  outResult.cfgSpareSlotsExpected =
    outResult.cfgCoversActivePlanner and
      outResult.sparePatchSlots == 5'u32 and
      outResult.cfgPatchSlots == outResult.activePlannerSlots +
        outResult.sparePatchSlots
  outResult.localPlannerCoversToolchain =
    globals.maxPatchSlotsFitLocalPlanner and
      outResult.localPlannerCapacity >= outResult.activePlannerSlots
  outResult.persistentBufferFitsOnePatch =
    outResult.persistentTensorBufferBytes != 0'u32 and
      outResult.persistentTensorBufferBytes <= outResult.patchSizeBytes
  outResult.converterArtifactsReady = package.converterReady
  outResult.outputOracleReady = package.outputOracleReady
  outResult.realModelPlannerReady =
    outResult.packageValid and outResult.sramGlobalsValid and
      outResult.cfgMemoryValid and outResult.patchSizeMatchesCfg and
      outResult.cfgCoversActivePlanner and
      outResult.cfgSpareSlotsExpected and
      outResult.localPlannerCoversToolchain and
      outResult.persistentBufferFitsOnePatch and
      outResult.converterArtifactsReady and outResult.outputOracleReady
  outResult.outputValidationStillBlocked = outResult.realModelPlannerReady
  if not outResult.packageValid:
    outResult.firstBlock = blaiMnistToolchainSramReadinessPackage
  elif not outResult.sramGlobalsValid:
    outResult.firstBlock = blaiMnistToolchainSramReadinessGlobals
  elif not outResult.cfgMemoryValid:
    outResult.firstBlock = blaiMnistToolchainSramReadinessCfgMemory
  elif not outResult.patchSizeMatchesCfg:
    outResult.firstBlock = blaiMnistToolchainSramReadinessPatchSize
  elif not outResult.cfgCoversActivePlanner:
    outResult.firstBlock = blaiMnistToolchainSramReadinessCfgCapacity
  elif not outResult.cfgSpareSlotsExpected:
    outResult.firstBlock = blaiMnistToolchainSramReadinessCfgSpare
  elif not outResult.localPlannerCoversToolchain:
    outResult.firstBlock = blaiMnistToolchainSramReadinessLocalPlanner
  elif not outResult.persistentBufferFitsOnePatch:
    outResult.firstBlock = blaiMnistToolchainSramReadinessPersistentBuffer
  elif not outResult.converterArtifactsReady:
    outResult.firstBlock = blaiMnistToolchainSramReadinessConverterArtifacts
  elif not outResult.outputOracleReady:
    outResult.firstBlock = blaiMnistToolchainSramReadinessOutputOracle
  else:
    outResult.firstBlock = blaiMnistToolchainSramReadinessNoBlock
  outResult.valid =
    outResult.realModelPlannerReady and outResult.outputValidationStillBlocked and
      outResult.firstBlock == blaiMnistToolchainSramReadinessNoBlock

proc blaiMnistToolchainSramReadinessEvidence*(
    package: BlaiMnistGeneratedPackageContract,
    globals: BlaiToolchainSramGlobalsEvidence):
    BlaiMnistToolchainSramReadinessEvidence =
  ## Convenience wrapper for MNIST SRAM planner readiness evidence.
  blaiMnistToolchainSramReadinessEvidenceInto(package, globals, result)

proc blaiMnistToolchainSramReadinessEvidence*():
    BlaiMnistToolchainSramReadinessEvidence =
  ## Compose the current generated-MNIST SRAM planner readiness.
  blaiMnistToolchainSramReadinessEvidence(
    blaiMnistGeneratedPackageContract(),
    blaiToolchainSramGlobalsEvidence())

proc blaiMnistConverterGenerationEvidenceInto*(
    package: BlaiMnistGeneratedPackageContract,
    sram: BlaiMnistToolchainSramReadinessEvidence,
    outResult: var BlaiMnistConverterGenerationEvidence) =
  ## Bind MNIST package readiness to the current host converter block.
  outResult = default(BlaiMnistConverterGenerationEvidence)
  outResult.packageValid = package.valid
  outResult.packageFirstBlock = package.firstBlock
  outResult.sramReadinessValid = sram.valid
  outResult.sramReadinessFirstBlock = sram.firstBlock
  outResult.converterArtifactContractReady = package.converterOutputs.valid
  outResult.staticOracleUsable =
    package.modelMatchesSample and package.imageSidecarReady and
      package.outputOracleReady
  blaiToolchainConverterDependencyPlanInto(outResult.dependencyPlan)
  outResult.missingSharedLibraryCount = outResult.dependencyPlan.missingCount
  outResult.frameworkMissingCount = outResult.dependencyPlan.frameworkMissing
  outResult.nnapiMissingCount = outResult.dependencyPlan.nnapiMissing
  outResult.tensorflowMissingCount = outResult.dependencyPlan.tensorflowMissing
  outResult.darknetMissingCount = outResult.dependencyPlan.darknetMissing
  outResult.openCvMissingCount = outResult.dependencyPlan.openCvMissing
  outResult.firstMissingDependency = outResult.dependencyPlan.firstMissing
  blaiToolchainConverterArtifactRegenerationPlanInto(
    package.converterOutputs, outResult.dependencyPlan, false,
    outResult.artifactRegeneration)
  outResult.executionBlock =
    if outResult.missingSharedLibraryCount == 0'u32:
      blaiToolchainConverterExecutionNoBlock
    else:
      blaiToolchainConverterExecutionMissingSharedLibraries
  outResult.converterExecutionBlocked =
    outResult.dependencyPlan.blocksExecution and
      outResult.executionBlock != blaiToolchainConverterExecutionNoBlock
  outResult.canGenerateArtifacts =
    outResult.packageValid and outResult.sramReadinessValid and
      outResult.converterArtifactContractReady and
      outResult.artifactRegeneration.converterRunnable and
      not outResult.converterExecutionBlocked
  outResult.generatedArtifactsRegenerated =
    outResult.artifactRegeneration.artifactsRegenerated
  outResult.generatedArtifactsNotRegenerated =
    not outResult.artifactRegeneration.artifactsAvailable
  outResult.liveModelValidationBlocked =
    sram.outputValidationStillBlocked or outResult.converterExecutionBlocked
  if not outResult.packageValid:
    outResult.firstBlock = blaiMnistConverterGenerationPackage
  elif not outResult.sramReadinessValid:
    outResult.firstBlock = blaiMnistConverterGenerationSramReadiness
  elif not outResult.converterArtifactContractReady:
    outResult.firstBlock = blaiMnistConverterGenerationArtifactContract
  elif not outResult.staticOracleUsable:
    outResult.firstBlock = blaiMnistConverterGenerationStaticOracle
  elif outResult.converterExecutionBlocked:
    outResult.firstBlock = blaiMnistConverterGenerationExecution
  elif outResult.generatedArtifactsNotRegenerated:
    outResult.firstBlock = blaiMnistConverterGenerationArtifactsNotRegenerated
  elif outResult.liveModelValidationBlocked:
    outResult.firstBlock = blaiMnistConverterGenerationLiveValidation
  else:
    outResult.firstBlock = blaiMnistConverterGenerationNoBlock
  outResult.valid =
    outResult.packageValid and outResult.sramReadinessValid and
      outResult.converterArtifactContractReady and outResult.staticOracleUsable and
      outResult.artifactRegeneration.valid and
      outResult.converterExecutionBlocked and
      outResult.generatedArtifactsNotRegenerated and
      outResult.liveModelValidationBlocked and
      outResult.firstBlock == blaiMnistConverterGenerationExecution

proc blaiMnistConverterGenerationEvidence*(
    package: BlaiMnistGeneratedPackageContract,
    sram: BlaiMnistToolchainSramReadinessEvidence):
    BlaiMnistConverterGenerationEvidence =
  ## Convenience wrapper for host converter generation evidence.
  blaiMnistConverterGenerationEvidenceInto(package, sram, result)

proc blaiMnistConverterGenerationEvidence*():
    BlaiMnistConverterGenerationEvidence =
  ## Compose the current MNIST converter generation gate.
  let package = blaiMnistGeneratedPackageContract()
  blaiMnistConverterGenerationEvidence(
    package,
    blaiMnistToolchainSramReadinessEvidence(
      package, blaiToolchainSramGlobalsEvidence()))

proc blaiToolchainPsramAllocateScratchPlanInto*(
    outResult: var BlaiToolchainPsramAllocateScratchPlan) =
  ## Recover `PSRAM_allocate` scratch-table sizes and initialization values.
  outResult = default(BlaiToolchainPsramAllocateScratchPlan)
  outResult.layerCapacity = BlaiToolchainPsramAllocateLayerCapacity
  outResult.relationSlotsPerLayer = BlaiToolchainPsramAllocateRelationSlots
  outResult.relationEntryCount = BlaiToolchainPsramAllocateRelationEntryCount
  outResult.relationInitValue = BlaiToolchainPsramAllocateRelationInitValue
  outResult.requestTableCount = BlaiToolchainPsramAllocateRequestTableCount
  outResult.bitmapSlotCount = BlaiToolchainPsramAllocateBitmapSlotCount
  outResult.ownerSlotCount = BlaiToolchainPsramAllocateOwnerSlotCount
  outResult.valid =
    outResult.layerCapacity == BlaiToolchainPsramAllocateLayerCapacity and
      outResult.relationSlotsPerLayer ==
        BlaiToolchainPsramAllocateRelationSlots and
      outResult.relationEntryCount ==
        BlaiToolchainPsramAllocateRelationEntryCount and
      outResult.relationInitValue ==
        BlaiToolchainPsramAllocateRelationInitValue and
      outResult.requestTableCount ==
        BlaiToolchainPsramAllocateRequestTableCount and
      outResult.bitmapSlotCount ==
        BlaiToolchainPsramAllocateBitmapSlotCount and
      outResult.ownerSlotCount == BlaiToolchainPsramAllocateOwnerSlotCount

proc blaiToolchainPsramAllocateScratchPlan*():
    BlaiToolchainPsramAllocateScratchPlan =
  ## Convenience wrapper for recovered `PSRAM_allocate` scratch layout.
  blaiToolchainPsramAllocateScratchPlanInto(result)

proc blaiToolchainPsramLayerProcessDecision*(
    layerTypeValue: int32): BlaiToolchainPsramLayerProcessDecision =
  ## Recover whether a copied layer participates in PSRAM planning.
  result.layerTypeValue = layerTypeValue
  result.skippedLayer =
    layerTypeValue == BlaiToolchainPsramAllocateSkipLayerType
  result.processLayer = not result.skippedLayer
  result.valid = true

proc blaiToolchainPsramLayerLoopPlanInto*(layerIndex, layerCount,
    layerTypeValue: int32, outResult: var BlaiToolchainPsramLayerLoopPlan) =
  ## Recover the layer-loop gate at the head of toolchain `PSRAM_allocate`.
  ##
  ## The converter returns immediately when the network layer count is not
  ## positive, iterates indexes `0 ..< layerCount`, and skips raw layer type
  ## `0x1A` before request-count or patch metadata planning.
  outResult = default(BlaiToolchainPsramLayerLoopPlan)
  outResult.layerIndex = layerIndex
  outResult.layerCount = layerCount
  outResult.layerTypeValue = layerTypeValue
  if layerCount <= 0'i32:
    outResult.firstBlock = blaiToolchainPsramLayerLoopLayerCount
    return
  if layerIndex < 0'i32 or layerIndex >= layerCount:
    outResult.firstBlock = blaiToolchainPsramLayerLoopLayerIndex
    return

  outResult.withinLoopBounds = true
  let processDecision =
    blaiToolchainPsramLayerProcessDecision(layerTypeValue)
  outResult.skippedLayer = processDecision.skippedLayer
  outResult.processLayer = processDecision.processLayer
  outResult.firstBlock = blaiToolchainPsramLayerLoopNoBlock
  outResult.valid = true

proc blaiToolchainPsramLayerLoopPlan*(layerIndex, layerCount,
    layerTypeValue: int32): BlaiToolchainPsramLayerLoopPlan =
  ## Convenience wrapper for recovered `PSRAM_allocate` layer-loop gate.
  blaiToolchainPsramLayerLoopPlanInto(
    layerIndex, layerCount, layerTypeValue, result)

proc blaiToolchainPsramSignedAlign4Abi*(
    rawValue: int32): BlaiToolchainPsramSignedAlign4Abi =
  ## Mirror the converter's signed align-to-4 sequence for one copied scalar.
  if (rawValue and 0x3'i32) == 0'i32:
    result.value = rawValue
    result.valid = true
    return

  let base =
    if rawValue >= 0'i32:
      rawValue.int64
    else:
      rawValue.int64 + 3'i64
  let quotient =
    if base >= 0'i64:
      base div 4'i64
    else:
      -(((-base) + 3'i64) div 4'i64)
  let aligned64 = quotient * 4'i64 + 4'i64
  if aligned64 < low(int32).int64 or aligned64 > high(int32).int64:
    return

  result.value = aligned64.int32
  result.valid = true

proc blaiToolchainPsramLayerTransitionPlanInto*(
    completedLayerIndex, layerCount, layerTypeValue, rawAlignScalar: int32,
    outResult: var BlaiToolchainPsramLayerTransitionPlan) =
  ## Recover the post-cleanup transition to the next `darknet::layer` copy.
  ##
  ## `PSRAM_allocate` increments the layer cursor, advances by the recovered
  ## `0x978` byte stride, copies `0x12f` qwords into stack scratch, skips raw
  ## type `0x1a`, then aligns one copied signed scalar to four.
  outResult = default(BlaiToolchainPsramLayerTransitionPlan)
  outResult.completedLayerIndex = completedLayerIndex
  outResult.layerCount = layerCount
  outResult.layerTypeValue = layerTypeValue
  outResult.rawAlignScalar = rawAlignScalar
  outResult.layerStrideBytes = BlaiToolchainPsramLayerStrideBytes
  outResult.layerCopyQwords = BlaiToolchainPsramLayerCopyQwords
  outResult.layerCopyBytes = BlaiToolchainPsramLayerCopyBytes
  if layerCount <= 0'i32:
    outResult.firstBlock = blaiToolchainPsramLayerTransitionLayerCount
    return
  if completedLayerIndex < -1'i32 or completedLayerIndex >= layerCount:
    outResult.firstBlock = blaiToolchainPsramLayerTransitionLayerIndex
    return

  outResult.nextLayerIndex = completedLayerIndex + 1'i32
  outResult.endReached = outResult.nextLayerIndex >= layerCount
  if outResult.endReached:
    outResult.firstBlock = blaiToolchainPsramLayerTransitionNoBlock
    outResult.valid = true
    return

  outResult.copyRequested = true
  let processDecision =
    blaiToolchainPsramLayerProcessDecision(layerTypeValue)
  outResult.skippedLayer = processDecision.skippedLayer
  outResult.processLayer = processDecision.processLayer
  if outResult.processLayer:
    let alignedScalar = blaiToolchainPsramSignedAlign4Abi(rawAlignScalar)
    if not alignedScalar.valid:
      outResult.firstBlock = blaiToolchainPsramLayerTransitionOverflow
      return
    outResult.alignedScalar = alignedScalar.value
  else:
    outResult.alignedScalar = rawAlignScalar

  outResult.firstBlock = blaiToolchainPsramLayerTransitionNoBlock
  outResult.valid = true

proc blaiToolchainPsramLayerTransitionPlan*(
    completedLayerIndex, layerCount, layerTypeValue, rawAlignScalar: int32):
    BlaiToolchainPsramLayerTransitionPlan =
  ## Convenience wrapper for recovered post-cleanup layer transition.
  blaiToolchainPsramLayerTransitionPlanInto(
    completedLayerIndex, layerCount, layerTypeValue, rawAlignScalar, result)

proc blaiToolchainPsramLayerRequestPlanInto*(
    layer: BlaiCpuInstLayer64,
    outResult: var BlaiToolchainPsramLayerRequestPlan) =
  ## Recover the initial per-layer patch request from toolchain `PSRAM_allocate`.
  outResult = default(BlaiToolchainPsramLayerRequestPlan)
  outResult.layerType = layer.layerType
  outResult.patchSizeBytes = BlaiToolchainPatchSizeBytes
  let processDecision =
    blaiToolchainPsramLayerProcessDecision(layer.layerType)
  if processDecision.skippedLayer:
    outResult.firstBlock = blaiToolchainPsramLayerRequestSkippedLayer
    return
  if outResult.patchSizeBytes == 0'u32:
    outResult.firstBlock = blaiToolchainPsramLayerRequestPatchSize
    return

  outResult.inputHeight = nonNegativeU32(layer.h)
  outResult.inputWidth = nonNegativeU32(layer.w)
  outResult.inputChannels = nonNegativeU32(layer.c)
  outResult.alignedInputChannels = blaiChannelAlign4(outResult.inputChannels)
  let pixelCount =
    outResult.inputHeight.uint64 * outResult.inputWidth.uint64
  let byteCount = pixelCount * outResult.alignedInputChannels.uint64
  if not blaiU64ExactU32Count(pixelCount, outResult.inputPixels) or
     not blaiU64ExactU32Count(byteCount, outResult.inputBytes):
    outResult.firstBlock = blaiToolchainPsramLayerRequestOverflow
    return

  outResult.requestedPatchCount =
    outResult.inputBytes div outResult.patchSizeBytes
  outResult.firstBlock = blaiToolchainPsramLayerRequestNoBlock
  outResult.valid = true

proc blaiToolchainPsramLayerRequestPlan*(
    layer: BlaiCpuInstLayer64): BlaiToolchainPsramLayerRequestPlan =
  ## Convenience wrapper for recovered `PSRAM_allocate` layer request count.
  blaiToolchainPsramLayerRequestPlanInto(layer, result)

proc blaiToolchainPsramDspRequestPlanInto*(
    areaA, areaB, countToAlign: int32,
    outResult: var BlaiToolchainPsramDspRequestPlan) =
  ## Recover the DSP patch request count inside `PSRAM_allocate`.
  ##
  ## The DSP branch at `PSRAM_allocate+0x6df` uses a copied layer area product
  ## and a separately aligned count value before calling `search_set_patch` and
  ## `search_set_dsp_patch`. Keeping the inputs scalar here avoids binding this
  ## logic to a still-partial C++ `darknet::layer` object layout.
  outResult = default(BlaiToolchainPsramDspRequestPlan)
  outResult.patchSizeBytes = BlaiToolchainPatchSizeBytes
  if outResult.patchSizeBytes == 0'u32:
    outResult.firstBlock = blaiToolchainPsramDspRequestPatchSize
    return
  if areaA < 0 or areaB < 0 or countToAlign < 0:
    outResult.firstBlock = blaiToolchainPsramDspRequestShape
    return

  let areaAField = blaiToolchainPsramDspRequestScalarAbi(areaA)
  let areaBField = blaiToolchainPsramDspRequestScalarAbi(areaB)
  let countToAlignField =
    blaiToolchainPsramDspRequestScalarAbi(countToAlign)
  if not areaAField.valid or not areaBField.valid or
      not countToAlignField.valid:
    outResult.firstBlock = blaiToolchainPsramDspRequestShape
    return

  outResult.areaA = areaAField.value
  outResult.areaB = areaBField.value
  outResult.countToAlign = countToAlignField.value
  outResult.alignedCount = blaiAlign4(outResult.countToAlign)
  if outResult.alignedCount < outResult.countToAlign:
    outResult.firstBlock = blaiToolchainPsramDspRequestOverflow
    return

  let area64 = outResult.areaA.uint64 * outResult.areaB.uint64
  let byteCount64 = area64 * outResult.alignedCount.uint64
  if not blaiU64ExactU32Count(area64, outResult.areaElements) or
     not blaiU64ExactU32Count(byteCount64, outResult.inputBytes):
    outResult.firstBlock = blaiToolchainPsramDspRequestOverflow
    return

  outResult.requestedPatchCount =
    outResult.inputBytes div outResult.patchSizeBytes
  outResult.firstBlock = blaiToolchainPsramDspRequestNoBlock
  outResult.valid = true

proc blaiToolchainPsramDspRequestPlan*(
    areaA, areaB, countToAlign: int32): BlaiToolchainPsramDspRequestPlan =
  ## Convenience wrapper for recovered DSP-area request count.
  blaiToolchainPsramDspRequestPlanInto(areaA, areaB, countToAlign, result)

proc blaiToolchainPsramDspVolumeRequestPlanInto*(
    factorA, factorB, factorC: int32,
    outResult: var BlaiToolchainPsramDspVolumeRequestPlan) =
  ## Recover the three-factor DSP request count inside `PSRAM_allocate`.
  ##
  ## The branch at `PSRAM_allocate+0x859` multiplies three copied layer scalars
  ## directly, divides that product by `PATCH_SIZE`, then calls
  ## `search_set_patch` followed by `search_set_dsp_patch`.
  outResult = default(BlaiToolchainPsramDspVolumeRequestPlan)
  outResult.patchSizeBytes = BlaiToolchainPatchSizeBytes
  if outResult.patchSizeBytes == 0'u32:
    outResult.firstBlock = blaiToolchainPsramDspVolumeRequestPatchSize
    return
  if factorA < 0 or factorB < 0 or factorC < 0:
    outResult.firstBlock = blaiToolchainPsramDspVolumeRequestShape
    return

  let factorAField = blaiToolchainPsramDspRequestScalarAbi(factorA)
  let factorBField = blaiToolchainPsramDspRequestScalarAbi(factorB)
  let factorCField = blaiToolchainPsramDspRequestScalarAbi(factorC)
  if not factorAField.valid or not factorBField.valid or
      not factorCField.valid:
    outResult.firstBlock = blaiToolchainPsramDspVolumeRequestShape
    return

  outResult.factorA = factorAField.value
  outResult.factorB = factorBField.value
  outResult.factorC = factorCField.value
  let volume64 =
    outResult.factorA.uint64 * outResult.factorB.uint64 *
      outResult.factorC.uint64
  if not blaiU64ExactU32Count(volume64, outResult.volumeElements):
    outResult.firstBlock = blaiToolchainPsramDspVolumeRequestOverflow
    return

  outResult.requestedPatchCount =
    outResult.volumeElements div outResult.patchSizeBytes
  outResult.firstBlock = blaiToolchainPsramDspVolumeRequestNoBlock
  outResult.valid = true

proc blaiToolchainPsramDspVolumeRequestPlan*(
    factorA, factorB, factorC: int32):
    BlaiToolchainPsramDspVolumeRequestPlan =
  ## Convenience wrapper for recovered three-factor DSP request count.
  blaiToolchainPsramDspVolumeRequestPlanInto(
    factorA, factorB, factorC, result)

proc blaiToolchainPsramGeneralPatchPlanInto*(
    requestedPatchCount: uint32,
    prepare: BlaiToolchainPatchSearchCallPreparePlan,
    debugLogFlag: bool,
    outResult: var BlaiToolchainPsramGeneralPatchPlan) =
  ## Recover the general branch's single patch-search helper call.
  ##
  ## Several adjacent `PSRAM_allocate` branches prepare future-consumer and
  ## previous-owner scalars, then call only `search_set_patch`. The lower-level
  ## dispatch plan owns owner selection; this branch plan keeps the caller-side
  ## single-helper shape explicit.
  outResult = default(BlaiToolchainPsramGeneralPatchPlan)
  outResult.prepare = prepare
  outResult.requestedPatchCount = requestedPatchCount
  outResult.debugLogFlag = debugLogFlag
  if not prepare.valid:
    outResult.firstBlock = blaiToolchainPsramGeneralPatchPrepare
    return

  blaiToolchainPatchDispatchPlanInto(
    blaiToolchainPatchOwnerGeneral, prepare.currentLayerIndex,
    requestedPatchCount, prepare.relationConsumerLayerIndex,
    prepare.relationConsumerFound, prepare.selectedPreviousOwnerFlag,
    debugLogFlag, outResult.dispatch)
  if not outResult.dispatch.valid:
    outResult.firstBlock = blaiToolchainPsramGeneralPatchDispatch
    return

  outResult.currentLayerIndex = prepare.currentLayerIndex
  outResult.relationConsumerLayerIndex = prepare.relationConsumerLayerIndex
  outResult.relationConsumerFound = prepare.relationConsumerFound
  outResult.selectedPreviousOwnerFlag = prepare.selectedPreviousOwnerFlag
  outResult.generalSearchCall = outResult.dispatch.generalSearchCall
  outResult.metadataMode = outResult.dispatch.metadataMode
  outResult.owner = outResult.dispatch.owner.selectedOwner
  outResult.firstBlock = blaiToolchainPsramGeneralPatchNoBlock
  outResult.valid = true

proc blaiToolchainPsramGeneralPatchPlan*(
    requestedPatchCount: uint32,
    prepare: BlaiToolchainPatchSearchCallPreparePlan,
    debugLogFlag: bool): BlaiToolchainPsramGeneralPatchPlan =
  ## Convenience wrapper for recovered general patch-search dispatch.
  blaiToolchainPsramGeneralPatchPlanInto(
    requestedPatchCount, prepare, debugLogFlag, result)

proc blaiToolchainPsramGeneralPatchState*(
    currentLayerIndex: int32,
    requestedPatchCount: uint32,
    relationConsumerLayerIndex: int32,
    relationConsumerFound: bool,
    selectedPreviousOwnerFlag: bool,
    debugLogFlag: bool,
    generalSearchCall: bool,
    metadataMode: BlaiToolchainPatchMetadataMode,
    owner: int32): BlaiToolchainPsramGeneralPatchState =
  ## Build a typed caller-owned general patch handoff state.
  result.currentLayerIndex = currentLayerIndex
  result.requestedPatchCount = requestedPatchCount
  result.relationConsumerLayerIndex = relationConsumerLayerIndex
  result.relationConsumerFound = relationConsumerFound
  result.selectedPreviousOwnerFlag = selectedPreviousOwnerFlag
  result.debugLogFlag = debugLogFlag
  result.generalSearchCall = generalSearchCall
  result.metadataMode = metadataMode
  result.owner = owner

proc blaiToolchainPsramGeneralPatchApplyPlanInto*(
    patch: BlaiToolchainPsramGeneralPatchPlan,
    outResult: var BlaiToolchainPsramGeneralPatchApplyPlan) =
  ## Prepare checked application of general patch handoff state.
  outResult = default(BlaiToolchainPsramGeneralPatchApplyPlan)
  outResult.patch = patch
  if not patch.valid:
    outResult.firstBlock = blaiToolchainPsramGeneralPatchApplyPatchPlan
    return

  outResult.stateAfter = blaiToolchainPsramGeneralPatchState(
    patch.currentLayerIndex, patch.requestedPatchCount,
    patch.relationConsumerLayerIndex, patch.relationConsumerFound,
    patch.selectedPreviousOwnerFlag, patch.debugLogFlag,
    patch.generalSearchCall, patch.metadataMode, patch.owner)
  outResult.firstBlock = blaiToolchainPsramGeneralPatchApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramGeneralPatchApplyPlan*(
    patch: BlaiToolchainPsramGeneralPatchPlan):
    BlaiToolchainPsramGeneralPatchApplyPlan =
  ## Convenience wrapper for checked general patch handoff application.
  blaiToolchainPsramGeneralPatchApplyPlanInto(patch, result)

proc blaiApplyToolchainPsramGeneralPatch*(
    state: var BlaiToolchainPsramGeneralPatchState,
    plan: BlaiToolchainPsramGeneralPatchApplyPlan): bool =
  ## Apply recovered general patch handoff state to caller-owned storage.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPsramGeneralPatchScalarState*(
    currentLayerIndex: var int32,
    requestedPatchCount: var uint32,
    relationConsumerLayerIndex: var int32,
    relationConsumerFound: var bool,
    selectedPreviousOwnerFlag: var bool,
    debugLogFlag: var bool,
    generalSearchCall: var bool,
    metadataMode: var BlaiToolchainPatchMetadataMode,
    owner: var int32,
    state: BlaiToolchainPsramGeneralPatchState): bool =
  ## Apply recovered general patch handoff metadata scalars from typed state.
  currentLayerIndex = state.currentLayerIndex
  requestedPatchCount = state.requestedPatchCount
  relationConsumerLayerIndex = state.relationConsumerLayerIndex
  relationConsumerFound = state.relationConsumerFound
  selectedPreviousOwnerFlag = state.selectedPreviousOwnerFlag
  debugLogFlag = state.debugLogFlag
  generalSearchCall = state.generalSearchCall
  metadataMode = state.metadataMode
  owner = state.owner
  true

proc blaiApplyToolchainPsramGeneralPatchScalars*(
    currentLayerIndex: var int32,
    requestedPatchCount: var uint32,
    relationConsumerLayerIndex: var int32,
    relationConsumerFound: var bool,
    selectedPreviousOwnerFlag: var bool,
    debugLogFlag: var bool,
    generalSearchCall: var bool,
    metadataMode: var BlaiToolchainPatchMetadataMode,
    owner: var int32,
    plan: BlaiToolchainPsramGeneralPatchApplyPlan): bool =
  ## Apply recovered general patch handoff metadata scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramGeneralPatchScalarState(
    currentLayerIndex, requestedPatchCount, relationConsumerLayerIndex,
    relationConsumerFound, selectedPreviousOwnerFlag, debugLogFlag,
    generalSearchCall, metadataMode, owner, plan.stateAfter)

proc blaiApplyToolchainPsramGeneralPatchDispatchState*(
    generalSearchCall: var bool,
    metadataMode: var BlaiToolchainPatchMetadataMode,
    owner: var int32,
    state: BlaiToolchainPsramGeneralPatchState): bool =
  ## Apply recovered general patch-search dispatch outputs to caller storage.
  generalSearchCall = state.generalSearchCall
  metadataMode = state.metadataMode
  owner = state.owner
  true

proc blaiApplyToolchainPsramGeneralPatchDispatch*(
    generalSearchCall: var bool,
    metadataMode: var BlaiToolchainPatchMetadataMode,
    owner: var int32,
    plan: BlaiToolchainPsramGeneralPatchApplyPlan): bool =
  ## Apply recovered general patch-search dispatch outputs.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramGeneralPatchDispatchState(
    generalSearchCall, metadataMode, owner, plan.stateAfter)

static:
  let staticGeneralPatch = BlaiToolchainPsramGeneralPatchPlan(
    currentLayerIndex: 1,
    requestedPatchCount: 2,
    relationConsumerLayerIndex: 4,
    relationConsumerFound: true,
    selectedPreviousOwnerFlag: true,
    debugLogFlag: true,
    generalSearchCall: true,
    metadataMode: blaiToolchainPatchMetadataGeneral,
    owner: 0,
    firstBlock: blaiToolchainPsramGeneralPatchNoBlock,
    valid: true)
  var staticGeneralPatchApplyInto: BlaiToolchainPsramGeneralPatchApplyPlan
  blaiToolchainPsramGeneralPatchApplyPlanInto(
    staticGeneralPatch, staticGeneralPatchApplyInto)
  let staticGeneralPatchApply =
    blaiToolchainPsramGeneralPatchApplyPlan(staticGeneralPatch)
  doAssert staticGeneralPatchApplyInto == staticGeneralPatchApply
  doAssert staticGeneralPatchApply.valid
  doAssert staticGeneralPatchApply.stateAfter ==
    blaiToolchainPsramGeneralPatchState(
      1, 2'u32, 4, true, true, true, true,
      blaiToolchainPatchMetadataGeneral, 0)
  var staticGeneralPatchState =
    blaiToolchainPsramGeneralPatchState(
      -1, 0'u32, -1, false, false, false, false,
      blaiToolchainPatchMetadataDsp, -1)
  doAssert blaiApplyToolchainPsramGeneralPatch(
    staticGeneralPatchState, staticGeneralPatchApply)
  doAssert staticGeneralPatchState ==
    blaiToolchainPsramGeneralPatchState(
      1, 2'u32, 4, true, true, true, true,
      blaiToolchainPatchMetadataGeneral, 0)
  var staticGeneralPatchScalarLayer = -9'i32
  var staticGeneralPatchScalarRequest = 99'u32
  var staticGeneralPatchScalarRelation = -8'i32
  var staticGeneralPatchScalarRelationFound = false
  var staticGeneralPatchScalarPreviousOwner = false
  var staticGeneralPatchScalarDebug = false
  var staticGeneralPatchScalarSearchCall = false
  var staticGeneralPatchScalarMetadata = blaiToolchainPatchMetadataTflite
  var staticGeneralPatchScalarOwner = -7'i32
  doAssert blaiApplyToolchainPsramGeneralPatchScalarState(
    staticGeneralPatchScalarLayer, staticGeneralPatchScalarRequest,
    staticGeneralPatchScalarRelation, staticGeneralPatchScalarRelationFound,
    staticGeneralPatchScalarPreviousOwner, staticGeneralPatchScalarDebug,
    staticGeneralPatchScalarSearchCall, staticGeneralPatchScalarMetadata,
    staticGeneralPatchScalarOwner, staticGeneralPatchApply.stateAfter)
  doAssert staticGeneralPatchScalarLayer == 1
  doAssert staticGeneralPatchScalarRequest == 2
  doAssert staticGeneralPatchScalarRelation == 4
  doAssert staticGeneralPatchScalarRelationFound
  doAssert staticGeneralPatchScalarPreviousOwner
  doAssert staticGeneralPatchScalarDebug
  doAssert staticGeneralPatchScalarSearchCall
  doAssert staticGeneralPatchScalarMetadata == blaiToolchainPatchMetadataGeneral
  doAssert staticGeneralPatchScalarOwner == 0
  staticGeneralPatchScalarLayer = -19
  staticGeneralPatchScalarRequest = 199
  staticGeneralPatchScalarRelation = -18
  staticGeneralPatchScalarRelationFound = false
  staticGeneralPatchScalarPreviousOwner = false
  staticGeneralPatchScalarDebug = false
  staticGeneralPatchScalarSearchCall = false
  staticGeneralPatchScalarMetadata = blaiToolchainPatchMetadataTflite
  staticGeneralPatchScalarOwner = -17
  doAssert blaiApplyToolchainPsramGeneralPatchScalars(
    staticGeneralPatchScalarLayer, staticGeneralPatchScalarRequest,
    staticGeneralPatchScalarRelation, staticGeneralPatchScalarRelationFound,
    staticGeneralPatchScalarPreviousOwner, staticGeneralPatchScalarDebug,
    staticGeneralPatchScalarSearchCall, staticGeneralPatchScalarMetadata,
    staticGeneralPatchScalarOwner, staticGeneralPatchApply)
  doAssert staticGeneralPatchScalarLayer == 1
  doAssert staticGeneralPatchScalarRequest == 2
  doAssert staticGeneralPatchScalarRelation == 4
  doAssert staticGeneralPatchScalarRelationFound
  doAssert staticGeneralPatchScalarPreviousOwner
  doAssert staticGeneralPatchScalarDebug
  doAssert staticGeneralPatchScalarSearchCall
  doAssert staticGeneralPatchScalarMetadata == blaiToolchainPatchMetadataGeneral
  doAssert staticGeneralPatchScalarOwner == 0
  var staticGeneralPatchSearchCall = false
  var staticGeneralPatchMetadataMode = blaiToolchainPatchMetadataTflite
  var staticGeneralPatchOwner = -1'i32
  doAssert blaiApplyToolchainPsramGeneralPatchDispatch(
    staticGeneralPatchSearchCall, staticGeneralPatchMetadataMode,
    staticGeneralPatchOwner, staticGeneralPatchApply)
  doAssert staticGeneralPatchSearchCall
  doAssert staticGeneralPatchMetadataMode == blaiToolchainPatchMetadataGeneral
  doAssert staticGeneralPatchOwner == 0
  var staticGeneralPatchSearchCallFromState = false
  var staticGeneralPatchMetadataModeFromState = blaiToolchainPatchMetadataTflite
  var staticGeneralPatchOwnerFromState = -1'i32
  doAssert blaiApplyToolchainPsramGeneralPatchDispatchState(
    staticGeneralPatchSearchCallFromState,
    staticGeneralPatchMetadataModeFromState,
    staticGeneralPatchOwnerFromState,
    staticGeneralPatchApply.stateAfter)
  doAssert staticGeneralPatchSearchCallFromState
  doAssert staticGeneralPatchMetadataModeFromState ==
    blaiToolchainPatchMetadataGeneral
  doAssert staticGeneralPatchOwnerFromState == 0
  let staticBlockedGeneralPatchApply =
    blaiToolchainPsramGeneralPatchApplyPlan(
      BlaiToolchainPsramGeneralPatchPlan(
        requestedPatchCount: 1,
        firstBlock: blaiToolchainPsramGeneralPatchPrepare,
        valid: false))
  doAssert not staticBlockedGeneralPatchApply.valid
  doAssert staticBlockedGeneralPatchApply.firstBlock ==
    blaiToolchainPsramGeneralPatchApplyPatchPlan
  var staticBlockedGeneralPatchState =
    blaiToolchainPsramGeneralPatchState(
      7, 3'u32, 8, true, false, true, false,
      blaiToolchainPatchMetadataTflite, 9)
  doAssert not blaiApplyToolchainPsramGeneralPatch(
    staticBlockedGeneralPatchState, staticBlockedGeneralPatchApply)
  doAssert staticBlockedGeneralPatchState ==
    blaiToolchainPsramGeneralPatchState(
      7, 3'u32, 8, true, false, true, false,
      blaiToolchainPatchMetadataTflite, 9)
  doAssert not blaiApplyToolchainPsramGeneralPatchScalars(
    staticGeneralPatchScalarLayer, staticGeneralPatchScalarRequest,
    staticGeneralPatchScalarRelation, staticGeneralPatchScalarRelationFound,
    staticGeneralPatchScalarPreviousOwner, staticGeneralPatchScalarDebug,
    staticGeneralPatchScalarSearchCall, staticGeneralPatchScalarMetadata,
    staticGeneralPatchScalarOwner, staticBlockedGeneralPatchApply)
  doAssert staticGeneralPatchScalarLayer == 1
  doAssert staticGeneralPatchScalarRequest == 2
