proc blaiToolchainPsramDspPatchPairPlanInto*(
    request: BlaiToolchainPsramDspRequestPlan,
    prepare: BlaiToolchainPatchSearchCallPreparePlan,
    debugLogFlag: bool,
    outResult: var BlaiToolchainPsramDspPatchPairPlan) =
  ## Recover the DSP branch's paired patch-search helper calls.
  ##
  ## The DSP path in `PSRAM_allocate` calls `search_set_patch` first, then
  ## `search_set_dsp_patch` with the same prepared relation-consumer and
  ## previous-owner scalars. The dispatch helper owns the exact owner selection
  ## and call booleans; this plan keeps the pair explicit.
  outResult = default(BlaiToolchainPsramDspPatchPairPlan)
  outResult.request = request
  outResult.prepare = prepare
  outResult.debugLogFlag = debugLogFlag
  outResult.dspDebugStartOffset = BlaiToolchainPsramDspDebugStartOffset
  outResult.dspDebugStackBytes = BlaiToolchainPsramDspDebugStackBytes
  if not request.valid:
    outResult.firstBlock = blaiToolchainPsramDspPatchPairRequest
    return
  if not prepare.valid:
    outResult.firstBlock = blaiToolchainPsramDspPatchPairPrepare
    return

  blaiToolchainPatchDispatchPlanInto(
    blaiToolchainPatchOwnerDsp, prepare.currentLayerIndex,
    request.requestedPatchCount, prepare.relationConsumerLayerIndex,
    prepare.relationConsumerFound, prepare.selectedPreviousOwnerFlag,
    debugLogFlag, outResult.dispatch)
  if not outResult.dispatch.valid:
    outResult.firstBlock = blaiToolchainPsramDspPatchPairDispatch
    return

  outResult.currentLayerIndex = prepare.currentLayerIndex
  outResult.requestedPatchCount = request.requestedPatchCount
  outResult.relationConsumerLayerIndex = prepare.relationConsumerLayerIndex
  outResult.relationConsumerFound = prepare.relationConsumerFound
  outResult.selectedPreviousOwnerFlag = prepare.selectedPreviousOwnerFlag
  outResult.generalSearchCall = outResult.dispatch.generalSearchCall
  outResult.dspSearchCall = outResult.dispatch.dspSearchCall
  outResult.metadataMode = outResult.dispatch.metadataMode
  outResult.owner = outResult.dispatch.owner.selectedOwner
  outResult.dspDebugPrintRequested = debugLogFlag
  outResult.previousOwnerFlagPushed = debugLogFlag
  outResult.firstBlock = blaiToolchainPsramDspPatchPairNoBlock
  outResult.valid = true

proc blaiToolchainPsramDspPatchPairPlan*(
    request: BlaiToolchainPsramDspRequestPlan,
    prepare: BlaiToolchainPatchSearchCallPreparePlan,
    debugLogFlag: bool): BlaiToolchainPsramDspPatchPairPlan =
  ## Convenience wrapper for recovered DSP patch-search pair dispatch.
  blaiToolchainPsramDspPatchPairPlanInto(
    request, prepare, debugLogFlag, result)

proc blaiToolchainPsramDspPatchPairState*(
    currentLayerIndex: int32,
    requestedPatchCount: uint32,
    relationConsumerLayerIndex: int32,
    relationConsumerFound: bool,
    selectedPreviousOwnerFlag: bool,
    debugLogFlag: bool,
    generalSearchCall: bool,
    dspSearchCall: bool,
    metadataMode: BlaiToolchainPatchMetadataMode,
    owner: int32,
    dspDebugStartOffset: uint32,
    dspDebugStackBytes: uint32,
    dspDebugPrintRequested: bool,
    previousOwnerFlagPushed: bool): BlaiToolchainPsramDspPatchPairState =
  ## Build a typed caller-owned DSP patch-pair handoff state.
  result.currentLayerIndex = currentLayerIndex
