  result.relationConsumerLayerIndex = relationConsumerLayerIndex
  result.relationConsumerFound = relationConsumerFound
  result.selectedPreviousOwnerFlag = selectedPreviousOwnerFlag
  result.debugLogFlag = debugLogFlag
