  result.previousOwnerFlagPushed = previousOwnerFlagPushed

proc blaiToolchainPsramDspPatchPairApplyPlanInto*(
    pair: BlaiToolchainPsramDspPatchPairPlan,
    outResult: var BlaiToolchainPsramDspPatchPairApplyPlan) =
  ## Prepare checked application of DSP patch-pair handoff state.
  outResult = default(BlaiToolchainPsramDspPatchPairApplyPlan)
  outResult.pair = pair
  if not pair.valid:
    outResult.firstBlock = blaiToolchainPsramDspPatchPairApplyPairPlan
    return

  outResult.stateAfter = blaiToolchainPsramDspPatchPairState(
    pair.currentLayerIndex, pair.requestedPatchCount,
    pair.relationConsumerLayerIndex, pair.relationConsumerFound,
    pair.selectedPreviousOwnerFlag, pair.debugLogFlag,
    pair.generalSearchCall, pair.dspSearchCall, pair.metadataMode,
    pair.owner, pair.dspDebugStartOffset, pair.dspDebugStackBytes,
    pair.dspDebugPrintRequested, pair.previousOwnerFlagPushed)
  outResult.firstBlock = blaiToolchainPsramDspPatchPairApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramDspPatchPairApplyPlan*(
    pair: BlaiToolchainPsramDspPatchPairPlan):
    BlaiToolchainPsramDspPatchPairApplyPlan =
  ## Convenience wrapper for checked DSP patch-pair handoff application.
  blaiToolchainPsramDspPatchPairApplyPlanInto(pair, result)

