proc blaiToolchainPsramDspVolumePatchPairPlanInto*(
    request: BlaiToolchainPsramDspVolumeRequestPlan,
    prepare: BlaiToolchainPatchSearchCallPreparePlan,
    debugLogFlag: bool,
    outResult: var BlaiToolchainPsramDspVolumePatchPairPlan) =
  ## Recover the volume DSP branch's paired patch-search helper calls.
  ##
  ## This branch computes its request from three raw copied scalars, then calls
  ## `search_set_patch` followed by `search_set_dsp_patch` with the same
  ## relation-consumer and previous-owner arguments used by the aligned-count
  ## DSP branch.
  outResult = default(BlaiToolchainPsramDspVolumePatchPairPlan)
  outResult.request = request
  outResult.prepare = prepare
  outResult.debugLogFlag = debugLogFlag
  outResult.dspDebugStartOffset = BlaiToolchainPsramDspDebugStartOffset
  if not request.valid:
    outResult.firstBlock = blaiToolchainPsramDspVolumePatchPairRequest
    return
  if not prepare.valid:
    outResult.firstBlock = blaiToolchainPsramDspVolumePatchPairPrepare
    return

  blaiToolchainPatchDispatchPlanInto(
    blaiToolchainPatchOwnerDsp, prepare.currentLayerIndex,
    request.requestedPatchCount, prepare.relationConsumerLayerIndex,
    prepare.relationConsumerFound, prepare.selectedPreviousOwnerFlag,
    debugLogFlag, outResult.dispatch)
  if not outResult.dispatch.valid:
    outResult.firstBlock = blaiToolchainPsramDspVolumePatchPairDispatch
    return

  outResult.currentLayerIndex = prepare.currentLayerIndex
  outResult.requestedPatchCount = request.requestedPatchCount
  outResult.relationConsumerLayerIndex = prepare.relationConsumerLayerIndex
  outResult.relationConsumerFound = prepare.relationConsumerFound
  outResult.selectedPreviousOwnerFlag = prepare.selectedPreviousOwnerFlag
  outResult.generalSearchCall = outResult.dispatch.generalSearchCall
  outResult.dspSearchCall = outResult.dispatch.dspSearchCall
  outResult.metadataMode = outResult.dispatch.metadataMode
  outResult.owner = outResult.dispatch.owner.selectedOwner
  outResult.dspDebugPrintRequested = debugLogFlag
  outResult.firstBlock = blaiToolchainPsramDspVolumePatchPairNoBlock
  outResult.valid = true

