proc blaiToolchainPsramTfliteRequestPlanInto*(
    areaA, areaB, countToSelect: int32,
    outResult: var BlaiToolchainPsramTfliteRequestPlan) =
  ## Recover the TFLite patch request count inside `PSRAM_allocate`.
  ##
  ## The branch at `PSRAM_allocate+0x36d` multiplies two copied geometry fields
  ## by a count field, forcing count values `2` and `3` to `4`, then
  ## floor-divides by `PATCH_SIZE` before calling `tflite_search_set_patch`.
  outResult = default(BlaiToolchainPsramTfliteRequestPlan)
  outResult.patchSizeBytes = BlaiToolchainPatchSizeBytes
  if outResult.patchSizeBytes == 0'u32:
    outResult.firstBlock = blaiToolchainPsramTfliteRequestPatchSize
    return
  if areaA < 0 or areaB < 0 or countToSelect < 0:
    outResult.firstBlock = blaiToolchainPsramTfliteRequestShape
    return

  let areaAField = blaiToolchainPsramTfliteRequestScalarAbi(areaA)
  let areaBField = blaiToolchainPsramTfliteRequestScalarAbi(areaB)
  let countToSelectField =
    blaiToolchainPsramTfliteRequestScalarAbi(countToSelect)
  if not areaAField.valid or not areaBField.valid or
      not countToSelectField.valid:
    outResult.firstBlock = blaiToolchainPsramTfliteRequestShape
    return

  outResult.areaA = areaAField.value
  outResult.areaB = areaBField.value
  outResult.countToSelect = countToSelectField.value
  outResult.smallCountForced =
    outResult.countToSelect == 2'u32 or outResult.countToSelect == 3'u32
  outResult.selectedCount =
    if outResult.smallCountForced:
      4'u32
    else:
      outResult.countToSelect

  let area64 = outResult.areaA.uint64 * outResult.areaB.uint64
  let elementCount64 = area64 * outResult.selectedCount.uint64
  if not blaiU64ExactU32Count(elementCount64, outResult.inputElements):
    outResult.firstBlock = blaiToolchainPsramTfliteRequestOverflow
    return

  outResult.requestedPatchCount =
    outResult.inputElements div outResult.patchSizeBytes
  outResult.firstBlock = blaiToolchainPsramTfliteRequestNoBlock
  outResult.valid = true

proc blaiToolchainPsramTfliteRequestPlan*(
    areaA, areaB, countToSelect: int32): BlaiToolchainPsramTfliteRequestPlan =
  ## Convenience wrapper for recovered TFLite request count.
  blaiToolchainPsramTfliteRequestPlanInto(areaA, areaB, countToSelect, result)

proc blaiToolchainPsramTflitePatchPlanInto*(
    request: BlaiToolchainPsramTfliteRequestPlan,
    prepare: BlaiToolchainPatchSearchCallPreparePlan,
    debugLogFlag: bool,
    outResult: var BlaiToolchainPsramTflitePatchPlan) =
  ## Recover the TFLite branch's `tflite_search_set_patch` handoff.
  ##
  ## Unlike the DSP branch, the TFLite path calls only the TFLite patch-search
  ## helper. The recovered dispatch still consumes the same relation-consumer
  ## preparation so future consumers select the owner passed to the helper.
  outResult = default(BlaiToolchainPsramTflitePatchPlan)
  outResult.request = request
  outResult.prepare = prepare
  outResult.debugLogFlag = debugLogFlag
  if not request.valid:
    outResult.firstBlock = blaiToolchainPsramTflitePatchRequest
    return
  if not prepare.valid:
    outResult.firstBlock = blaiToolchainPsramTflitePatchPrepare
    return

  blaiToolchainPatchDispatchPlanInto(
    blaiToolchainPatchOwnerTflite, prepare.currentLayerIndex,
    request.requestedPatchCount, prepare.relationConsumerLayerIndex,
    prepare.relationConsumerFound, prepare.selectedPreviousOwnerFlag,
    debugLogFlag, outResult.dispatch)
  if not outResult.dispatch.valid:
    outResult.firstBlock = blaiToolchainPsramTflitePatchDispatch
    return

  outResult.currentLayerIndex = prepare.currentLayerIndex
  outResult.requestedPatchCount = request.requestedPatchCount
  outResult.relationConsumerLayerIndex = prepare.relationConsumerLayerIndex
  outResult.relationConsumerFound = prepare.relationConsumerFound
  outResult.selectedPreviousOwnerFlag = prepare.selectedPreviousOwnerFlag
  outResult.tfliteSearchCall = outResult.dispatch.tfliteSearchCall
  outResult.metadataMode = outResult.dispatch.metadataMode
  outResult.owner = outResult.dispatch.owner.selectedOwner
  outResult.firstBlock = blaiToolchainPsramTflitePatchNoBlock
  outResult.valid = true

proc blaiToolchainPsramTflitePatchPlan*(
    request: BlaiToolchainPsramTfliteRequestPlan,
    prepare: BlaiToolchainPatchSearchCallPreparePlan,
    debugLogFlag: bool): BlaiToolchainPsramTflitePatchPlan =
  ## Convenience wrapper for recovered TFLite patch-search dispatch.
  blaiToolchainPsramTflitePatchPlanInto(
    request, prepare, debugLogFlag, result)

proc blaiToolchainPsramTflitePatchState*(
    currentLayerIndex: int32,
    requestedPatchCount: uint32,
    relationConsumerLayerIndex: int32,
    relationConsumerFound: bool,
    selectedPreviousOwnerFlag: bool,
    debugLogFlag: bool,
    tfliteSearchCall: bool,
    metadataMode: BlaiToolchainPatchMetadataMode,
    owner: int32): BlaiToolchainPsramTflitePatchState =
  ## Build a typed caller-owned TFLite patch handoff state.
  result.currentLayerIndex = currentLayerIndex
  result.requestedPatchCount = requestedPatchCount
  result.relationConsumerLayerIndex = relationConsumerLayerIndex
  result.relationConsumerFound = relationConsumerFound
  result.selectedPreviousOwnerFlag = selectedPreviousOwnerFlag
  result.debugLogFlag = debugLogFlag
  result.tfliteSearchCall = tfliteSearchCall
  result.metadataMode = metadataMode
  result.owner = owner

proc blaiToolchainPsramTflitePatchApplyPlanInto*(
    patch: BlaiToolchainPsramTflitePatchPlan,
    outResult: var BlaiToolchainPsramTflitePatchApplyPlan) =
  ## Prepare checked application of TFLite patch handoff state.
  outResult = default(BlaiToolchainPsramTflitePatchApplyPlan)
  outResult.patch = patch
  if not patch.valid:
    outResult.firstBlock = blaiToolchainPsramTflitePatchApplyPatchPlan
    return

  outResult.stateAfter = blaiToolchainPsramTflitePatchState(
    patch.currentLayerIndex, patch.requestedPatchCount,
    patch.relationConsumerLayerIndex, patch.relationConsumerFound,
    patch.selectedPreviousOwnerFlag, patch.debugLogFlag,
    patch.tfliteSearchCall, patch.metadataMode, patch.owner)
  outResult.firstBlock = blaiToolchainPsramTflitePatchApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramTflitePatchApplyPlan*(
    patch: BlaiToolchainPsramTflitePatchPlan):
    BlaiToolchainPsramTflitePatchApplyPlan =
  ## Convenience wrapper for checked TFLite patch handoff application.
  blaiToolchainPsramTflitePatchApplyPlanInto(patch, result)

proc blaiApplyToolchainPsramTflitePatch*(
    state: var BlaiToolchainPsramTflitePatchState,
    plan: BlaiToolchainPsramTflitePatchApplyPlan): bool =
  ## Apply recovered TFLite patch handoff state to caller-owned storage.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

