  doAssert not blaiApplyToolchainPsramTflitePatchDispatch(
    staticBlockedTflitePatchSearchCall,
    staticBlockedTflitePatchMetadataMode,
    staticBlockedTflitePatchOwner,
    staticBlockedTflitePatchApply)
  doAssert staticBlockedTflitePatchSearchCall
  doAssert staticBlockedTflitePatchMetadataMode == blaiToolchainPatchMetadataDsp
  doAssert staticBlockedTflitePatchOwner == 9

proc blaiToolchainPsramLayerRequestStorePlanInto*(
    request: BlaiToolchainPsramLayerRequestPlan,
    layerIndex: int32,
    requestTable: openArray[uint32],
    outResult: var BlaiToolchainPsramLayerRequestStorePlan) =
  ## Recover the request-table store after `PSRAM_allocate` request calculation.
  outResult = default(BlaiToolchainPsramLayerRequestStorePlan)
  outResult.request = request
  outResult.layerIndex = layerIndex
  outResult.requestTableOffset = BlaiToolchainPatchDebugRequestTableOffset
  outResult.requestTableCount = blaiOpenArrayLenU32(requestTable)
  if not request.valid:
    outResult.firstBlock = blaiToolchainPsramLayerRequestStoreRequestPlan
    return
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramLayerRequestStoreLayerIndex
    return
  let requestTableIndex = blaiToolchainPsramRequestTableIndexAbi(layerIndex)
  if not requestTableIndex.valid:
    outResult.firstBlock = blaiToolchainPsramLayerRequestStoreLayerIndex
    return
  let requestCursor =
    blaiToolchainPsramRequestTableCursor(
      requestTableIndex.value, requestTable.len)
  if not requestCursor.valid:
    outResult.firstBlock = blaiToolchainPsramLayerRequestStoreStorage
    return

  outResult.requestedPatchCount = request.requestedPatchCount
  outResult.writesApplied = 1
  outResult.firstBlock = blaiToolchainPsramLayerRequestStoreNoBlock
  outResult.valid = true

proc blaiToolchainPsramLayerRequestStorePlan*(
    request: BlaiToolchainPsramLayerRequestPlan,
    layerIndex: int32,
    requestTable: openArray[uint32]):
    BlaiToolchainPsramLayerRequestStorePlan =
  ## Convenience wrapper for recovered request-table metadata store.
  blaiToolchainPsramLayerRequestStorePlanInto(
    request, layerIndex, requestTable, result)

proc blaiToolchainPsramLayerRequestStoreState*(
    layerIndex: int32,
    requestTableOffset: uint32,
    requestTableIndex: uint32,
    requestTableCount: uint32,
    requestedPatchCount: uint32,
    writesApplied: uint32): BlaiToolchainPsramLayerRequestStoreState =
  ## Build a typed caller-owned request-table store state.
  result.layerIndex = layerIndex
  result.requestTableOffset = requestTableOffset
  result.requestTableIndex = requestTableIndex
  result.requestTableCount = requestTableCount
  result.requestedPatchCount = requestedPatchCount
  result.writesApplied = writesApplied

proc blaiToolchainPsramLayerRequestStoreApplyPlanInto*(
    store: BlaiToolchainPsramLayerRequestStorePlan,
    outResult: var BlaiToolchainPsramLayerRequestStoreApplyPlan) =
  ## Prepare checked application of request-table store state.
  outResult = default(BlaiToolchainPsramLayerRequestStoreApplyPlan)
  outResult.store = store
  if not store.valid:
    outResult.firstBlock = blaiToolchainPsramLayerRequestStoreApplyStorePlan
    return

  let requestTableIndex =
    blaiToolchainPsramRequestTableIndexAbi(store.layerIndex)
  if not requestTableIndex.valid:
    outResult.firstBlock = blaiToolchainPsramLayerRequestStoreApplyStorePlan
    return

  outResult.stateAfter = blaiToolchainPsramLayerRequestStoreState(
    store.layerIndex, store.requestTableOffset, requestTableIndex.value,
    store.requestTableCount, store.requestedPatchCount, store.writesApplied)
  outResult.firstBlock = blaiToolchainPsramLayerRequestStoreApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramLayerRequestStoreApplyPlan*(
    store: BlaiToolchainPsramLayerRequestStorePlan):
    BlaiToolchainPsramLayerRequestStoreApplyPlan =
  ## Convenience wrapper for checked request-table store state projection.
  blaiToolchainPsramLayerRequestStoreApplyPlanInto(store, result)

proc blaiApplyToolchainPsramLayerRequestStoreState*(
    state: var BlaiToolchainPsramLayerRequestStoreState,
    plan: BlaiToolchainPsramLayerRequestStoreApplyPlan): bool =
  ## Apply recovered request-table store state to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPsramLayerRequestStoreTableState*(
    requestTable: var openArray[uint32],
    state: BlaiToolchainPsramLayerRequestStoreState): bool =
  ## Apply recovered request-table store state to caller-owned table storage.
  let requestCursor =
    blaiToolchainPsramRequestTableCursor(
      state.requestTableIndex, requestTable.len)
  if not requestCursor.valid:
    return false
  requestTable[requestCursor.index] = state.requestedPatchCount
  true

proc blaiApplyToolchainPsramLayerRequestStoreScalarState*(
    layerIndex: var int32,
    requestTableIndex: var uint32,
    requestedPatchCount: var uint32,
    state: BlaiToolchainPsramLayerRequestStoreState): bool =
  ## Apply recovered request-table store scalars to caller-owned storage.
  layerIndex = state.layerIndex
  requestTableIndex = state.requestTableIndex
  requestedPatchCount = state.requestedPatchCount
  true

proc blaiApplyToolchainPsramLayerRequestStoreScalars*(
    layerIndex: var int32,
    requestTableIndex: var uint32,
    requestedPatchCount: var uint32,
    plan: BlaiToolchainPsramLayerRequestStoreApplyPlan): bool =
  ## Apply recovered request-table store scalar metadata.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramLayerRequestStoreScalarState(
    layerIndex, requestTableIndex, requestedPatchCount, plan.stateAfter)

proc blaiApplyToolchainPsramLayerRequestStore*(
    requestTable: var openArray[uint32],
    plan: BlaiToolchainPsramLayerRequestStorePlan): bool =
  ## Apply recovered request-count store to a caller-owned request table.
  let applyPlan = blaiToolchainPsramLayerRequestStoreApplyPlan(plan)
  if not applyPlan.valid:
    return false
  blaiApplyToolchainPsramLayerRequestStoreTableState(
    requestTable, applyPlan.stateAfter)

proc blaiToolchainSetWeiPatchCallPlanInto*(
    request: BlaiToolchainPsramLayerRequestPlan,
    layerIndex: int32,
    debugLogFlag: bool,
    outResult: var BlaiToolchainSetWeiPatchCallPlan) =
  ## Recover scalar `PSRAM_allocate` arguments for `set_wei_patch`.
  ##
  ## The toolchain stores the computed request count, initializes the by-ref
  ## patch-count result to zero, then passes the layer index, request count,
  ## by-ref result address, and debug/log flag into `set_wei_patch`. The large
  ## C++ network/layer value copies around that call are intentionally not
  ## modeled here until their object layouts are recovered.
  outResult = default(BlaiToolchainSetWeiPatchCallPlan)
  outResult.request = request
  outResult.layerIndex = layerIndex
  outResult.debugLogFlag = debugLogFlag
  outResult.byRefPatchCountInitial = 0'i32
  if not request.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchCallRequestPlan
    return
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainSetWeiPatchCallLayerIndex
    return

  outResult.requestedPatchCount = request.requestedPatchCount
  outResult.firstBlock = blaiToolchainSetWeiPatchCallNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchCallPlan*(
    request: BlaiToolchainPsramLayerRequestPlan,
    layerIndex: int32,
    debugLogFlag: bool): BlaiToolchainSetWeiPatchCallPlan =
  ## Convenience wrapper for the recovered `set_wei_patch` scalar call ABI.
  blaiToolchainSetWeiPatchCallPlanInto(
    request, layerIndex, debugLogFlag, result)

proc blaiToolchainSetWeiPatchCallFramePlanInto*(
    call: BlaiToolchainSetWeiPatchCallPlan,
    outResult: var BlaiToolchainSetWeiPatchCallFramePlan) =
  ## Recover by-value stack copies around the `set_wei_patch` call boundary.
  ##
  ## `PSRAM_allocate` initializes the by-ref patch count to zero, copies the
  ## current layer as `0x12f` qwords, copies the network as `0x47` qwords, then
  ## unwinds the combined `0xbb0` byte call frame after `set_wei_patch`.
  outResult = default(BlaiToolchainSetWeiPatchCallFramePlan)
  outResult.call = call
  outResult.layerCopyQwords = BlaiToolchainPsramLayerCopyQwords
  outResult.layerCopyBytes = BlaiToolchainPsramLayerCopyBytes
  outResult.networkCopyQwords = BlaiToolchainSetWeiPatchNetworkCopyQwords
  outResult.networkCopyBytes = BlaiToolchainSetWeiPatchNetworkCopyBytes
  outResult.callFrameBytes = BlaiToolchainSetWeiPatchCallFrameBytes
  outResult.byRefPatchCountInitial = call.byRefPatchCountInitial
  if not call.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchCallFrameCallPlan
    return
  if outResult.callFrameBytes !=
      outResult.layerCopyBytes + outResult.networkCopyBytes:
    outResult.firstBlock = blaiToolchainSetWeiPatchCallFrameSize
    return

  outResult.copiesLayerByValue = true
  outResult.copiesNetworkByValue = true
  outResult.byRefPatchCountPrepared =
    outResult.byRefPatchCountInitial == 0'i32
  outResult.firstBlock = blaiToolchainSetWeiPatchCallFrameNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchCallFramePlan*(
    call: BlaiToolchainSetWeiPatchCallPlan):
    BlaiToolchainSetWeiPatchCallFramePlan =
  ## Convenience wrapper for recovered `set_wei_patch` by-value call frame.
  blaiToolchainSetWeiPatchCallFramePlanInto(call, result)

proc blaiToolchainSetWeiPatchReturnPlanInto*(
    call: BlaiToolchainSetWeiPatchCallPlan,
    byRefPatchCountAfter: int32,
    outResult: var BlaiToolchainSetWeiPatchReturnPlan) =
  ## Recover `PSRAM_allocate` capture of `set_wei_patch`'s by-ref result.
  ##
  ## `set_wei_patch` writes its by-reference patch-count result before return.
  ## The caller immediately reloads that integer and stores it in layer-local
  ## scratch. This plan keeps that handoff typed without exposing stack offsets.
  outResult = default(BlaiToolchainSetWeiPatchReturnPlan)
  outResult.call = call
  outResult.byRefPatchCountInitial = call.byRefPatchCountInitial
  outResult.byRefPatchCountAfter = byRefPatchCountAfter
  if not call.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchReturnCallPlan
    return

  outResult.scratchPatchCount = byRefPatchCountAfter
  outResult.changed =
    byRefPatchCountAfter != outResult.byRefPatchCountInitial
  outResult.firstBlock = blaiToolchainSetWeiPatchReturnNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchReturnPlan*(
    call: BlaiToolchainSetWeiPatchCallPlan,
    byRefPatchCountAfter: int32): BlaiToolchainSetWeiPatchReturnPlan =
  ## Convenience wrapper for recovered by-ref result capture.
  blaiToolchainSetWeiPatchReturnPlanInto(
    call, byRefPatchCountAfter, result)

proc blaiToolchainSetWeiPatchReturnState*(
    scratchPatchCount, byRefPatchCountInitial, byRefPatchCountAfter: int32,
    changed: bool): BlaiToolchainSetWeiPatchReturnState =
  ## Build a typed caller-owned `set_wei_patch` return state.
  result.scratchPatchCount = scratchPatchCount
  result.byRefPatchCountInitial = byRefPatchCountInitial
  result.byRefPatchCountAfter = byRefPatchCountAfter
  result.changed = changed

proc blaiToolchainSetWeiPatchReturnApplyPlanInto*(
    returnPlan: BlaiToolchainSetWeiPatchReturnPlan,
    outResult: var BlaiToolchainSetWeiPatchReturnApplyPlan) =
  ## Prepare checked application of `set_wei_patch` return metadata.
  outResult = default(BlaiToolchainSetWeiPatchReturnApplyPlan)
  outResult.returnPlan = returnPlan
  if not returnPlan.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchReturnApplyReturnPlan
    return

  outResult.stateAfter = blaiToolchainSetWeiPatchReturnState(
    returnPlan.scratchPatchCount, returnPlan.byRefPatchCountInitial,
    returnPlan.byRefPatchCountAfter, returnPlan.changed)
  outResult.scratchPatchCountAfter = outResult.stateAfter.scratchPatchCount
  outResult.firstBlock = blaiToolchainSetWeiPatchReturnApplyNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchReturnApplyPlan*(
    returnPlan: BlaiToolchainSetWeiPatchReturnPlan):
    BlaiToolchainSetWeiPatchReturnApplyPlan =
  ## Convenience wrapper for checked `set_wei_patch` return-state projection.
  blaiToolchainSetWeiPatchReturnApplyPlanInto(returnPlan, result)

proc blaiApplyToolchainSetWeiPatchReturnState*(
    state: var BlaiToolchainSetWeiPatchReturnState,
    plan: BlaiToolchainSetWeiPatchReturnApplyPlan): bool =
  ## Apply recovered `set_wei_patch` return metadata to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainSetWeiPatchReturnScratchState*(
    scratchPatchCount: var int32,
    state: BlaiToolchainSetWeiPatchReturnState) =
  ## Apply recovered `set_wei_patch` scratch patch count from typed state.
  scratchPatchCount = state.scratchPatchCount

proc blaiApplyToolchainSetWeiPatchReturnScalarState*(
    scratchPatchCount: var int32,
    byRefPatchCountInitial: var int32,
    byRefPatchCountAfter: var int32,
    changed: var bool,
    state: BlaiToolchainSetWeiPatchReturnState): bool =
  ## Apply recovered `set_wei_patch` return scalars from typed state.
  scratchPatchCount = state.scratchPatchCount
  byRefPatchCountInitial = state.byRefPatchCountInitial
  byRefPatchCountAfter = state.byRefPatchCountAfter
  changed = state.changed
  true

proc blaiApplyToolchainSetWeiPatchReturnScalars*(
    scratchPatchCount: var int32,
    byRefPatchCountInitial: var int32,
    byRefPatchCountAfter: var int32,
    changed: var bool,
    plan: BlaiToolchainSetWeiPatchReturnApplyPlan): bool =
  ## Apply recovered `set_wei_patch` return scalar metadata.
  if not plan.valid:
    return false
  blaiApplyToolchainSetWeiPatchReturnScalarState(
    scratchPatchCount, byRefPatchCountInitial, byRefPatchCountAfter, changed,
    plan.stateAfter)

proc blaiApplyToolchainSetWeiPatchReturn*(
    scratchPatchCount: var int32,
    plan: BlaiToolchainSetWeiPatchReturnPlan): bool =
  ## Apply recovered `set_wei_patch` by-ref result to caller-owned scratch.
  let applyPlan = blaiToolchainSetWeiPatchReturnApplyPlan(plan)
  if not applyPlan.valid:
    return false
  blaiApplyToolchainSetWeiPatchReturnScratchState(
    scratchPatchCount, applyPlan.stateAfter)
  true

proc blaiToolchainSetWeiPatchReturnFramePlanInto*(
    callFrame: BlaiToolchainSetWeiPatchCallFramePlan,
    returnPlan: BlaiToolchainSetWeiPatchReturnPlan,
    outResult: var BlaiToolchainSetWeiPatchReturnFramePlan) =
  ## Recover the caller-side frame copy after `set_wei_patch` returns.
  ##
  ## The converter reloads the by-ref patch-count result from frame offset
  ## `0xc7c`, copies it to caller-frame offset `0xbb0`, then unwinds `0xbb0`
  ## bytes before continuing with the outer `PSRAM_allocate` loop.
  outResult = default(BlaiToolchainSetWeiPatchReturnFramePlan)
  outResult.callFrame = callFrame
  outResult.returnPlan = returnPlan
  outResult.byRefResultFrameOffset =
    BlaiToolchainSetWeiPatchByRefResultFrameOffset
  outResult.returnStoreFrameOffset =
    BlaiToolchainSetWeiPatchReturnStoreFrameOffset
  outResult.frameUnwindBytes = BlaiToolchainSetWeiPatchCallFrameBytes
  outResult.byRefPatchCountAfter = returnPlan.byRefPatchCountAfter
  if not callFrame.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchReturnFrameCallFrame
    return
  if not returnPlan.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchReturnFrameReturnPlan
    return
  if outResult.returnStoreFrameOffset != outResult.frameUnwindBytes:
    outResult.firstBlock = blaiToolchainSetWeiPatchReturnFrameSize
    return

  outResult.resultCopiedToCallerFrame = true
  outResult.frameUnwindMatchesCallFrame =
    callFrame.callFrameBytes == outResult.frameUnwindBytes
  if not outResult.frameUnwindMatchesCallFrame:
    outResult.firstBlock = blaiToolchainSetWeiPatchReturnFrameSize
    return
  outResult.firstBlock = blaiToolchainSetWeiPatchReturnFrameNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchReturnFramePlan*(
    callFrame: BlaiToolchainSetWeiPatchCallFramePlan,
    returnPlan: BlaiToolchainSetWeiPatchReturnPlan):
    BlaiToolchainSetWeiPatchReturnFramePlan =
  ## Convenience wrapper for recovered post-call frame result copy.
  blaiToolchainSetWeiPatchReturnFramePlanInto(
    callFrame, returnPlan, result)

proc blaiToolchainPsramOwnerTransitionPlanInto*(
    owners: openArray[int32],
    slot: uint32,
    currentLayerIndex, nextLayerIndex: int32,
    currentLayerType, nextLayerType: BlaiLayerType,
    startPatchSlot: int32,
    debugConvMaxPath: bool,
    outResult: var BlaiToolchainPsramOwnerTransitionPlan) =
  ## Recover one post-layer patch owner transition from `PSRAM_allocate`.
  outResult = default(BlaiToolchainPsramOwnerTransitionPlan)
  outResult.slot = slot
  outResult.currentLayerIndex = currentLayerIndex
  outResult.nextLayerIndex = nextLayerIndex
  outResult.currentLayerType = currentLayerType
  outResult.nextLayerType = nextLayerType
  outResult.startPatchSlot = startPatchSlot
  outResult.debugConvMaxPath = debugConvMaxPath
  if currentLayerIndex < 0 or nextLayerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramOwnerLayerIndex
    return
  let ownerCursor = blaiToolchainPatchOwnerCursor(slot, owners.len)
  if not ownerCursor.valid:
    outResult.firstBlock = blaiToolchainPsramOwnerSlot
    return

  outResult.ownerBefore = owners[ownerCursor.index]
  if outResult.ownerBefore != currentLayerIndex:
    outResult.action = blaiToolchainPsramOwnerIgnore
    outResult.ownerAfter = outResult.ownerBefore
    outResult.occupiedAfter = true
    outResult.firstBlock = blaiToolchainPsramOwnerNoBlock
    outResult.valid = true
    return

  let transfer =
    startPatchSlot == BlaiToolchainPatchInvalidStartSlot or
      (currentLayerType == blaiConvolutional and nextLayerType == blaiRoute) or
      (debugConvMaxPath and currentLayerType == blaiConvMax)
  if transfer:
    outResult.action = blaiToolchainPsramOwnerTransfer
    outResult.ownerAfter = nextLayerIndex
    outResult.occupiedAfter = true
  else:
    outResult.action = blaiToolchainPsramOwnerRelease
    outResult.ownerAfter = outResult.ownerBefore
    outResult.occupiedAfter = false
  outResult.firstBlock = blaiToolchainPsramOwnerNoBlock
  outResult.valid = true

proc blaiToolchainPsramOwnerTransitionPlan*(
    owners: openArray[int32],
    slot: uint32,
    currentLayerIndex, nextLayerIndex: int32,
    currentLayerType, nextLayerType: BlaiLayerType,
    startPatchSlot: int32,
    debugConvMaxPath: bool): BlaiToolchainPsramOwnerTransitionPlan =
  ## Convenience wrapper for one recovered patch-owner transition.
  blaiToolchainPsramOwnerTransitionPlanInto(
    owners, slot, currentLayerIndex, nextLayerIndex, currentLayerType,
    nextLayerType, startPatchSlot, debugConvMaxPath, result)

proc blaiToolchainPsramOwnerTransitionState*(
    slot: uint32,
    action: BlaiToolchainPsramOwnerTransitionAction,
    ownerBefore, ownerAfter: int32,
    occupiedAfter, writesOwner, writesOccupied: bool):
    BlaiToolchainPsramOwnerTransitionState =
  ## Build a typed caller-owned owner/bitmap transition state.
  result.slot = slot
  result.action = action
  result.ownerBefore = ownerBefore
  result.ownerAfter = ownerAfter
  result.occupiedAfter = occupiedAfter
  result.writesOwner = writesOwner
  result.writesOccupied = writesOccupied

proc blaiToolchainPsramOwnerTransitionApplyEvidence*(
    transition: BlaiToolchainPsramOwnerTransitionPlan,
    occupied: openArray[bool],
    owners: openArray[int32]): BlaiToolchainPsramOwnerTransitionApplyEvidence =
  ## Build checked evidence for applying one owner/bitmap transition.
  result.transitionValid = transition.valid
  result.occupiedStorageCount = blaiOpenArrayLenU32(occupied)
  result.ownerStorageCount = blaiOpenArrayLenU32(owners)
  if not transition.valid:
    result.firstBlock =
      blaiToolchainPsramOwnerTransitionApplyTransitionPlan
    return
  result.occupiedCursor =
    blaiToolchainPatchOccupiedCursor(transition.slot, occupied.len)
  result.ownerCursor =
    blaiToolchainPatchOwnerCursor(transition.slot, owners.len)
  result.storageValid = result.occupiedCursor.valid and result.ownerCursor.valid
  if not result.storageValid:
    result.firstBlock = blaiToolchainPsramOwnerTransitionApplyStorage
    return

  result.writesOwner =
    transition.action == blaiToolchainPsramOwnerTransfer
  result.writesOccupied =
    transition.action == blaiToolchainPsramOwnerRelease
  result.stateAfter = blaiToolchainPsramOwnerTransitionState(
    transition.slot, transition.action, transition.ownerBefore,
    transition.ownerAfter, transition.occupiedAfter, result.writesOwner,
    result.writesOccupied)
  result.firstBlock = blaiToolchainPsramOwnerTransitionApplyNoBlock
  result.valid = true

proc blaiToolchainPsramOwnerTransitionApplyPlanInto*(
    transition: BlaiToolchainPsramOwnerTransitionPlan,
    occupied: openArray[bool],
    owners: openArray[int32],
    outResult: var BlaiToolchainPsramOwnerTransitionApplyPlan) =
  ## Prepare checked application of one recovered owner/bitmap transition.
  outResult = default(BlaiToolchainPsramOwnerTransitionApplyPlan)
  outResult.transition = transition
  let evidence = blaiToolchainPsramOwnerTransitionApplyEvidence(
    transition, occupied, owners)
  outResult.evidence = evidence
  outResult.occupiedStorageCount = evidence.occupiedStorageCount
  outResult.ownerStorageCount = evidence.ownerStorageCount
  outResult.stateAfter = evidence.stateAfter
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainPsramOwnerTransitionApplyPlan*(
    transition: BlaiToolchainPsramOwnerTransitionPlan,
    occupied: openArray[bool],
    owners: openArray[int32]): BlaiToolchainPsramOwnerTransitionApplyPlan =
  ## Convenience wrapper for checked owner/bitmap transition application.
  blaiToolchainPsramOwnerTransitionApplyPlanInto(
    transition, occupied, owners, result)

proc blaiApplyToolchainPsramOwnerTransitionTablesState*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    state: BlaiToolchainPsramOwnerTransitionState): bool =
  ## Apply checked owner/bitmap transition state to caller-owned arrays.
  let occupiedCursor =
    blaiToolchainPatchOccupiedCursor(state.slot, occupied.len)
  let ownerCursor =
    blaiToolchainPatchOwnerCursor(state.slot, owners.len)
  if not occupiedCursor.valid or not ownerCursor.valid:
    return false
  if state.writesOwner:
    owners[ownerCursor.index] = state.ownerAfter
  if state.writesOccupied:
    occupied[occupiedCursor.index] = state.occupiedAfter
  true

proc blaiApplyToolchainPsramOwnerTransitionScalarState*(
    slot: var uint32,
    action: var BlaiToolchainPsramOwnerTransitionAction,
    ownerBefore, ownerAfter: var int32,
    occupiedAfter, writesOwner, writesOccupied: var bool,
    state: BlaiToolchainPsramOwnerTransitionState): bool =
  ## Apply recovered owner transition metadata scalars from typed state.
  slot = state.slot
  action = state.action
  ownerBefore = state.ownerBefore
  ownerAfter = state.ownerAfter
  occupiedAfter = state.occupiedAfter
  writesOwner = state.writesOwner
  writesOccupied = state.writesOccupied
  true

proc blaiApplyToolchainPsramOwnerTransitionScalars*(
    slot: var uint32,
    action: var BlaiToolchainPsramOwnerTransitionAction,
    ownerBefore, ownerAfter: var int32,
    occupiedAfter, writesOwner, writesOccupied: var bool,
    plan: BlaiToolchainPsramOwnerTransitionApplyPlan): bool =
  ## Apply recovered owner transition metadata scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramOwnerTransitionScalarState(
    slot, action, ownerBefore, ownerAfter, occupiedAfter, writesOwner,
    writesOccupied, plan.stateAfter)

proc blaiApplyToolchainPsramOwnerTransitionState*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    plan: BlaiToolchainPsramOwnerTransitionApplyPlan): bool =
  ## Apply checked owner/bitmap transition state to caller-owned arrays.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramOwnerTransitionTablesState(
    occupied, owners, plan.stateAfter)

proc blaiApplyToolchainPsramOwnerTransition*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    plan: BlaiToolchainPsramOwnerTransitionPlan): bool =
  ## Apply one recovered post-layer owner/bitmap transition.
  let applyPlan = blaiToolchainPsramOwnerTransitionApplyPlan(
    plan, occupied, owners)
  blaiApplyToolchainPsramOwnerTransitionState(occupied, owners, applyPlan)

proc blaiToolchainPsramCleanupRetainPlan*(
    currentLayerTypeValue, nextLayerTypeValue: int32,
    startPatchSlot: int32,
    routeDebugFlag: bool): BlaiToolchainPsramCleanupRetainPlan =
  ## Recover the shared cleanup retain/release predicate.
  result.currentLayerTypeValue = currentLayerTypeValue
  result.nextLayerTypeValue = nextLayerTypeValue
  result.startPatchSlot = startPatchSlot
  result.routeDebugFlag = routeDebugFlag
  result.invalidStartRetain =
    startPatchSlot == BlaiToolchainPatchInvalidStartSlot
  result.convRouteRetain =
    currentLayerTypeValue == BlaiToolchainPsramOwnerConvType and
      nextLayerTypeValue == BlaiToolchainPsramOwnerRouteType
  result.routeDebugRetain =
    routeDebugFlag and
      currentLayerTypeValue == BlaiToolchainPsramRelationRouteType
  if currentLayerTypeValue == BlaiToolchainPsramOwnerConvType:
    result.retain = result.convRouteRetain or result.invalidStartRetain
  else:
    result.retain = result.invalidStartRetain or result.routeDebugRetain
  result.valid = true

proc blaiToolchainPsramOwnerCleanupPlanInto*(
    owners: openArray[int32],
    slot: uint32,
    currentLayerIndex, nextLayerIndex: int32,
    currentLayerTypeValue, nextLayerTypeValue: int32,
    startPatchSlot: int32,
    routeDebugFlag: bool,
    outResult: var BlaiToolchainPsramOwnerCleanupPlan) =
  ## Recover one raw post-search owner cleanup decision from `PSRAM_allocate`.
  ##
  ## The converter keeps ownership when the slot is needed by a downstream
  ## consumer and otherwise clears the occupied bitmap while leaving the owner
  ## table value untouched.
  outResult = default(BlaiToolchainPsramOwnerCleanupPlan)
  outResult.slot = slot
  outResult.currentLayerIndex = currentLayerIndex
  outResult.nextLayerIndex = nextLayerIndex
  outResult.currentLayerTypeValue = currentLayerTypeValue
  outResult.nextLayerTypeValue = nextLayerTypeValue
  outResult.startPatchSlot = startPatchSlot
  outResult.routeDebugFlag = routeDebugFlag
  if currentLayerIndex < 0 or nextLayerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramOwnerCleanupLayerIndex
    return
  let ownerCursor = blaiToolchainPatchOwnerCursor(slot, owners.len)
  if not ownerCursor.valid:
    outResult.firstBlock = blaiToolchainPsramOwnerCleanupSlot
    return

  outResult.ownerBefore = owners[ownerCursor.index]
  if outResult.ownerBefore != currentLayerIndex:
    outResult.action = blaiToolchainPsramOwnerCleanupIgnore
    outResult.ownerAfter = outResult.ownerBefore
    outResult.occupiedAfter = true
    outResult.firstBlock = blaiToolchainPsramOwnerCleanupNoBlock
    outResult.valid = true
    return

  let retainPlan =
    blaiToolchainPsramCleanupRetainPlan(
      currentLayerTypeValue, nextLayerTypeValue, startPatchSlot,
      routeDebugFlag)
  if retainPlan.retain:
    outResult.action = blaiToolchainPsramOwnerCleanupTransfer
    outResult.ownerAfter = nextLayerIndex
    outResult.occupiedAfter = true
  else:
    outResult.action = blaiToolchainPsramOwnerCleanupRelease
    outResult.ownerAfter = outResult.ownerBefore
    outResult.occupiedAfter = false
  outResult.firstBlock = blaiToolchainPsramOwnerCleanupNoBlock
  outResult.valid = true

proc blaiToolchainPsramOwnerCleanupPlan*(
    owners: openArray[int32],
    slot: uint32,
    currentLayerIndex, nextLayerIndex: int32,
    currentLayerTypeValue, nextLayerTypeValue: int32,
    startPatchSlot: int32,
    routeDebugFlag: bool): BlaiToolchainPsramOwnerCleanupPlan =
  ## Convenience wrapper for recovered raw owner cleanup.
  blaiToolchainPsramOwnerCleanupPlanInto(
    owners, slot, currentLayerIndex, nextLayerIndex, currentLayerTypeValue,
    nextLayerTypeValue, startPatchSlot, routeDebugFlag, result)

proc blaiToolchainPsramOwnerCleanupState*(
    slot: uint32,
    action: BlaiToolchainPsramOwnerCleanupAction,
    ownerBefore, ownerAfter: int32,
    occupiedAfter, writesOwner, writesOccupied: bool):
    BlaiToolchainPsramOwnerCleanupState =
  ## Build a typed caller-owned raw owner cleanup state.
  result.slot = slot
  result.action = action
  result.ownerBefore = ownerBefore
  result.ownerAfter = ownerAfter
  result.occupiedAfter = occupiedAfter
  result.writesOwner = writesOwner
  result.writesOccupied = writesOccupied

proc blaiToolchainPsramOwnerCleanupApplyEvidence*(
    cleanup: BlaiToolchainPsramOwnerCleanupPlan,
    occupied: openArray[bool],
    owners: openArray[int32]): BlaiToolchainPsramOwnerCleanupApplyEvidence =
  ## Build checked evidence for applying one raw owner cleanup state.
  result.cleanupValid = cleanup.valid
  result.occupiedStorageCount = blaiOpenArrayLenU32(occupied)
  result.ownerStorageCount = blaiOpenArrayLenU32(owners)
  if not cleanup.valid:
    result.firstBlock = blaiToolchainPsramOwnerCleanupApplyCleanupPlan
    return
  result.occupiedCursor =
    blaiToolchainPatchOccupiedCursor(cleanup.slot, occupied.len)
  result.ownerCursor =
    blaiToolchainPatchOwnerCursor(cleanup.slot, owners.len)
  result.storageValid = result.occupiedCursor.valid and result.ownerCursor.valid
  if not result.storageValid:
    result.firstBlock = blaiToolchainPsramOwnerCleanupApplyStorage
    return

  result.writesOwner =
    cleanup.action == blaiToolchainPsramOwnerCleanupTransfer
  result.writesOccupied =
    cleanup.action == blaiToolchainPsramOwnerCleanupRelease
  result.stateAfter = blaiToolchainPsramOwnerCleanupState(
    cleanup.slot, cleanup.action, cleanup.ownerBefore, cleanup.ownerAfter,
    cleanup.occupiedAfter, result.writesOwner, result.writesOccupied)
  result.firstBlock = blaiToolchainPsramOwnerCleanupApplyNoBlock
  result.valid = true

proc blaiToolchainPsramOwnerCleanupApplyPlanInto*(
    cleanup: BlaiToolchainPsramOwnerCleanupPlan,
    occupied: openArray[bool],
    owners: openArray[int32],
    outResult: var BlaiToolchainPsramOwnerCleanupApplyPlan) =
  ## Prepare checked application of one raw owner cleanup state.
  outResult = default(BlaiToolchainPsramOwnerCleanupApplyPlan)
  outResult.cleanup = cleanup
  let evidence = blaiToolchainPsramOwnerCleanupApplyEvidence(
    cleanup, occupied, owners)
  outResult.evidence = evidence
  outResult.occupiedStorageCount = evidence.occupiedStorageCount
  outResult.ownerStorageCount = evidence.ownerStorageCount
  outResult.stateAfter = evidence.stateAfter
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainPsramOwnerCleanupApplyPlan*(
    cleanup: BlaiToolchainPsramOwnerCleanupPlan,
    occupied: openArray[bool],
    owners: openArray[int32]): BlaiToolchainPsramOwnerCleanupApplyPlan =
  ## Convenience wrapper for checked raw owner cleanup application.
  blaiToolchainPsramOwnerCleanupApplyPlanInto(
    cleanup, occupied, owners, result)

proc blaiApplyToolchainPsramOwnerCleanupTablesState*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    state: BlaiToolchainPsramOwnerCleanupState): bool =
  ## Apply checked raw owner cleanup state to caller-owned arrays.
  let occupiedCursor =
    blaiToolchainPatchOccupiedCursor(state.slot, occupied.len)
  let ownerCursor =
    blaiToolchainPatchOwnerCursor(state.slot, owners.len)
  if not occupiedCursor.valid or not ownerCursor.valid:
    return false
  if state.writesOwner:
    owners[ownerCursor.index] = state.ownerAfter
  if state.writesOccupied:
    occupied[occupiedCursor.index] = state.occupiedAfter
  true

proc blaiApplyToolchainPsramOwnerCleanupScalarState*(
    slot: var uint32,
    action: var BlaiToolchainPsramOwnerCleanupAction,
    ownerBefore, ownerAfter: var int32,
    occupiedAfter, writesOwner, writesOccupied: var bool,
    state: BlaiToolchainPsramOwnerCleanupState): bool =
  ## Apply recovered raw owner cleanup metadata scalars from typed state.
  slot = state.slot
  action = state.action
  ownerBefore = state.ownerBefore
  ownerAfter = state.ownerAfter
  occupiedAfter = state.occupiedAfter
  writesOwner = state.writesOwner
  writesOccupied = state.writesOccupied
  true

proc blaiApplyToolchainPsramOwnerCleanupScalars*(
    slot: var uint32,
    action: var BlaiToolchainPsramOwnerCleanupAction,
    ownerBefore, ownerAfter: var int32,
    occupiedAfter, writesOwner, writesOccupied: var bool,
    plan: BlaiToolchainPsramOwnerCleanupApplyPlan): bool =
  ## Apply recovered raw owner cleanup metadata scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramOwnerCleanupScalarState(
    slot, action, ownerBefore, ownerAfter, occupiedAfter, writesOwner,
    writesOccupied, plan.stateAfter)

proc blaiApplyToolchainPsramOwnerCleanupState*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    plan: BlaiToolchainPsramOwnerCleanupApplyPlan): bool =
  ## Apply checked raw owner cleanup state to caller-owned arrays.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramOwnerCleanupTablesState(
    occupied, owners, plan.stateAfter)

proc blaiApplyToolchainPsramOwnerCleanup*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    plan: BlaiToolchainPsramOwnerCleanupPlan): bool =
  ## Apply one recovered raw post-search owner cleanup decision.
  let applyPlan = blaiToolchainPsramOwnerCleanupApplyPlan(
    plan, occupied, owners)
  blaiApplyToolchainPsramOwnerCleanupState(occupied, owners, applyPlan)

proc blaiToolchainPsramOwnerCleanupSweepTally*(
    action: BlaiToolchainPsramOwnerCleanupAction):
    BlaiToolchainPsramOwnerCleanupSweepTally =
  ## Project one recovered cleanup action into sweep counters.
  result.scannedSlots = 1'u32
  case action
  of blaiToolchainPsramOwnerCleanupIgnore:
    result.ignoredSlots = 1'u32
  of blaiToolchainPsramOwnerCleanupTransfer:
    result.transferredSlots = 1'u32
  of blaiToolchainPsramOwnerCleanupRelease:
    result.releasedSlots = 1'u32
  result.valid = true

proc blaiToolchainPsramOwnerCleanupSweepPlanInto*(
    owners: openArray[int32],
    currentLayerIndex, nextLayerIndex: int32,
    currentLayerTypeValue, nextLayerTypeValue: int32,
    startPatchSlot: int32,
    routeDebugFlag: bool,
    outResult: var BlaiToolchainPsramOwnerCleanupSweepPlan) =
  ## Recover the `MAX_PSRAM_PATCH` post-search cleanup sweep.
  outResult = default(BlaiToolchainPsramOwnerCleanupSweepPlan)
  outResult.slotCount = BlaiToolchainMaxPsramPatchSlots
  outResult.ownerStorageCount = blaiOpenArrayLenU32(owners)
  outResult.currentLayerIndex = currentLayerIndex
  outResult.nextLayerIndex = nextLayerIndex
  outResult.currentLayerTypeValue = currentLayerTypeValue
  outResult.nextLayerTypeValue = nextLayerTypeValue
  outResult.startPatchSlot = startPatchSlot
  outResult.routeDebugFlag = routeDebugFlag
  if outResult.ownerStorageCount < outResult.slotCount:
    outResult.firstBlock = blaiToolchainPsramOwnerCleanupSweepStorage
    return

  for slot in 0'u32 ..< outResult.slotCount:
    var slotPlan: BlaiToolchainPsramOwnerCleanupPlan
    blaiToolchainPsramOwnerCleanupPlanInto(
      owners, slot, currentLayerIndex, nextLayerIndex, currentLayerTypeValue,
      nextLayerTypeValue, startPatchSlot, routeDebugFlag, slotPlan)
    if not slotPlan.valid:
      outResult.firstBlock = blaiToolchainPsramOwnerCleanupSweepSlot
      return
    let slotTally =
      blaiToolchainPsramOwnerCleanupSweepTally(slotPlan.action)
    if not slotTally.valid:
      outResult.firstBlock = blaiToolchainPsramOwnerCleanupSweepSlot
      return
    outResult.scannedSlots += slotTally.scannedSlots
    outResult.ignoredSlots += slotTally.ignoredSlots
    outResult.transferredSlots += slotTally.transferredSlots
    outResult.releasedSlots += slotTally.releasedSlots

  outResult.firstBlock = blaiToolchainPsramOwnerCleanupSweepNoBlock
  outResult.valid = true

proc blaiToolchainPsramOwnerCleanupSweepPlan*(
    owners: openArray[int32],
    currentLayerIndex, nextLayerIndex: int32,
    currentLayerTypeValue, nextLayerTypeValue: int32,
    startPatchSlot: int32,
    routeDebugFlag: bool): BlaiToolchainPsramOwnerCleanupSweepPlan =
  ## Convenience wrapper for recovered owner cleanup sweep.
  blaiToolchainPsramOwnerCleanupSweepPlanInto(
    owners, currentLayerIndex, nextLayerIndex, currentLayerTypeValue,
    nextLayerTypeValue, startPatchSlot, routeDebugFlag, result)

proc blaiToolchainPsramOwnerCleanupSweepState*(
    slotCount, occupiedStorageCount, ownerStorageCount, scannedSlots,
    ignoredSlots, transferredSlots, releasedSlots: uint32):
    BlaiToolchainPsramOwnerCleanupSweepState =
  ## Build a typed caller-owned owner cleanup sweep state.
  result.slotCount = slotCount
  result.occupiedStorageCount = occupiedStorageCount
  result.ownerStorageCount = ownerStorageCount
  result.scannedSlots = scannedSlots
  result.ignoredSlots = ignoredSlots
  result.transferredSlots = transferredSlots
  result.releasedSlots = releasedSlots

proc blaiToolchainPsramOwnerCleanupSweepApplyEvidence*(
    sweep: BlaiToolchainPsramOwnerCleanupSweepPlan,
    occupied: openArray[bool],
    owners: openArray[int32]):
    BlaiToolchainPsramOwnerCleanupSweepApplyEvidence =
  ## Build checked evidence for applying recovered owner cleanup sweep state.
  result.sweepValid = sweep.valid
  if not sweep.valid:
    result.firstBlock =
      blaiToolchainPsramOwnerCleanupSweepApplySweepPlan
    return
  result.occupiedStorageCount = blaiOpenArrayLenU32(occupied)
  result.ownerStorageCount = blaiOpenArrayLenU32(owners)
  result.storageValid =
    result.occupiedStorageCount >= sweep.slotCount and
      result.ownerStorageCount >= sweep.slotCount
  if not result.storageValid:
    result.firstBlock = blaiToolchainPsramOwnerCleanupSweepApplyStorage
    return

  result.stateAfter = blaiToolchainPsramOwnerCleanupSweepState(
    sweep.slotCount, result.occupiedStorageCount, result.ownerStorageCount,
    sweep.scannedSlots, sweep.ignoredSlots, sweep.transferredSlots,
    sweep.releasedSlots)
  result.firstBlock = blaiToolchainPsramOwnerCleanupSweepApplyNoBlock
  result.valid = true

proc blaiToolchainPsramOwnerCleanupSweepApplyPlanInto*(
    sweep: BlaiToolchainPsramOwnerCleanupSweepPlan,
    occupied: openArray[bool],
    owners: openArray[int32],
    outResult: var BlaiToolchainPsramOwnerCleanupSweepApplyPlan) =
  ## Prepare checked application of recovered owner cleanup sweep state.
  outResult = default(BlaiToolchainPsramOwnerCleanupSweepApplyPlan)
  outResult.sweep = sweep
  let evidence = blaiToolchainPsramOwnerCleanupSweepApplyEvidence(
    sweep, occupied, owners)
  outResult.evidence = evidence
  outResult.stateAfter = evidence.stateAfter
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainPsramOwnerCleanupSweepApplyPlan*(
    sweep: BlaiToolchainPsramOwnerCleanupSweepPlan,
    occupied: openArray[bool],
    owners: openArray[int32]):
    BlaiToolchainPsramOwnerCleanupSweepApplyPlan =
  ## Convenience wrapper for checked owner cleanup sweep application.
  blaiToolchainPsramOwnerCleanupSweepApplyPlanInto(
    sweep, occupied, owners, result)

proc blaiApplyToolchainPsramOwnerCleanupSweepScalarState*(
    slotCount, occupiedStorageCount, ownerStorageCount: var uint32,
    scannedSlots, ignoredSlots, transferredSlots, releasedSlots: var uint32,
    state: BlaiToolchainPsramOwnerCleanupSweepState): bool =
  ## Apply recovered owner cleanup sweep metadata scalars from typed state.
  slotCount = state.slotCount
  occupiedStorageCount = state.occupiedStorageCount
  ownerStorageCount = state.ownerStorageCount
  scannedSlots = state.scannedSlots
  ignoredSlots = state.ignoredSlots
  transferredSlots = state.transferredSlots
  releasedSlots = state.releasedSlots
  true

proc blaiApplyToolchainPsramOwnerCleanupSweepScalars*(
    slotCount, occupiedStorageCount, ownerStorageCount: var uint32,
    scannedSlots, ignoredSlots, transferredSlots, releasedSlots: var uint32,
    plan: BlaiToolchainPsramOwnerCleanupSweepApplyPlan): bool =
  ## Apply recovered owner cleanup sweep metadata scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramOwnerCleanupSweepScalarState(
    slotCount, occupiedStorageCount, ownerStorageCount, scannedSlots,
    ignoredSlots, transferredSlots, releasedSlots, plan.stateAfter)

proc blaiApplyToolchainPsramOwnerCleanupSweepState*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    sweep: BlaiToolchainPsramOwnerCleanupSweepPlan,
    state: BlaiToolchainPsramOwnerCleanupSweepState): bool =
  ## Apply recovered owner cleanup sweep state to caller-owned tables.
  for slot in 0'u32 ..< state.slotCount:
    var slotPlan: BlaiToolchainPsramOwnerCleanupPlan
    blaiToolchainPsramOwnerCleanupPlanInto(
      owners, slot, sweep.currentLayerIndex, sweep.nextLayerIndex,
      sweep.currentLayerTypeValue, sweep.nextLayerTypeValue,
      sweep.startPatchSlot, sweep.routeDebugFlag, slotPlan)
    let slotApplyPlan = blaiToolchainPsramOwnerCleanupApplyPlan(
      slotPlan, occupied, owners)
    if not blaiApplyToolchainPsramOwnerCleanupState(
        occupied, owners, slotApplyPlan):
      return false
  true

proc blaiApplyToolchainPsramOwnerCleanupSweep*(
    occupied: var openArray[bool],
    owners: var openArray[int32],
    plan: BlaiToolchainPsramOwnerCleanupSweepPlan): bool =
  ## Apply recovered 40-slot post-search cleanup to caller-owned tables.
  let applyPlan = blaiToolchainPsramOwnerCleanupSweepApplyPlan(
    plan, occupied, owners)
  if not applyPlan.valid:
    return false
  blaiApplyToolchainPsramOwnerCleanupSweepState(
    occupied, owners, applyPlan.sweep, applyPlan.stateAfter)

proc blaiToolchainPsramCleanupEntryPlanInto*(
    currentLayerIndex: int32,
    debugLogFlag: bool,
    maxPatchSlots: int32,
    outResult: var BlaiToolchainPsramCleanupEntryPlan) =
  ## Recover the post-search branch that enters the cleanup sweep.
  ##
  ## After `search_set_patch` returns, `PSRAM_allocate` stores the debug flag,
  ## skips the debug snapshot path when it is zero, checks `MAX_PSRAM_PATCH`,
  ## and either initializes the cleanup loop at slot zero with `current + 1` as
  ## the next-layer scalar or jumps directly to the layer transition.
  outResult = default(BlaiToolchainPsramCleanupEntryPlan)
  outResult.currentLayerIndex = currentLayerIndex
  outResult.maxPatchSlots = maxPatchSlots
  outResult.savedDebugLogFlag = debugLogFlag
  outResult.debugSnapshotPath = debugLogFlag
  if currentLayerIndex < 0 or currentLayerIndex == high(int32):
    outResult.firstBlock = blaiToolchainPsramCleanupEntryLayerIndex
    return
  if maxPatchSlots < 0:
    outResult.firstBlock = blaiToolchainPsramCleanupEntryMaxPatchSlots
    return

  outResult.nextLayerIndex = currentLayerIndex + 1'i32
  outResult.cleanupSlotStart = 0'u32
  outResult.entersCleanupSweep = maxPatchSlots > 0
  outResult.jumpsLayerTransition = not outResult.entersCleanupSweep
  outResult.firstBlock = blaiToolchainPsramCleanupEntryNoBlock
  outResult.valid = true

proc blaiToolchainPsramCleanupEntryPlan*(
    currentLayerIndex: int32,
    debugLogFlag: bool,
    maxPatchSlots: int32 = BlaiToolchainMaxPsramPatchSlotsI32):
    BlaiToolchainPsramCleanupEntryPlan =
  ## Convenience wrapper for recovered post-search cleanup-loop entry.
  blaiToolchainPsramCleanupEntryPlanInto(
    currentLayerIndex, debugLogFlag, maxPatchSlots, result)

proc blaiToolchainPsramCleanupEntryState*(
    nextLayerIndex: int32,
    cleanupSlotStart: uint32,
    savedDebugLogFlag, debugSnapshotPath, entersCleanupSweep,
    jumpsLayerTransition: bool): BlaiToolchainPsramCleanupEntryState =
  ## Build a typed caller-owned cleanup-entry branch state.
  result.nextLayerIndex = nextLayerIndex
  result.cleanupSlotStart = cleanupSlotStart
  result.savedDebugLogFlag = savedDebugLogFlag
  result.debugSnapshotPath = debugSnapshotPath
  result.entersCleanupSweep = entersCleanupSweep
  result.jumpsLayerTransition = jumpsLayerTransition

proc blaiToolchainPsramCleanupEntryApplyEvidence*(
    entry: BlaiToolchainPsramCleanupEntryPlan):
    BlaiToolchainPsramCleanupEntryApplyEvidence =
  ## Build checked evidence for applying recovered cleanup-entry state.
  result.entryValid = entry.valid
  if not entry.valid:
    result.firstBlock = blaiToolchainPsramCleanupEntryApplyEntryPlan
    return

  result.stateAfter = blaiToolchainPsramCleanupEntryState(
    entry.nextLayerIndex, entry.cleanupSlotStart, entry.savedDebugLogFlag,
    entry.debugSnapshotPath, entry.entersCleanupSweep,
    entry.jumpsLayerTransition)
  result.nextLayerIndexAfter = result.stateAfter.nextLayerIndex
  result.cleanupSlotStartAfter = result.stateAfter.cleanupSlotStart
  result.savedDebugLogFlagAfter = result.stateAfter.savedDebugLogFlag
  result.debugSnapshotPath = result.stateAfter.debugSnapshotPath
  result.entersCleanupSweep = result.stateAfter.entersCleanupSweep
  result.jumpsLayerTransition = result.stateAfter.jumpsLayerTransition
  result.firstBlock = blaiToolchainPsramCleanupEntryApplyNoBlock
  result.valid = true

proc blaiToolchainPsramCleanupEntryApplyPlanInto*(
    entry: BlaiToolchainPsramCleanupEntryPlan,
    outResult: var BlaiToolchainPsramCleanupEntryApplyPlan) =
  ## Prepare checked application of recovered cleanup-entry state.
  outResult = default(BlaiToolchainPsramCleanupEntryApplyPlan)
  outResult.entry = entry
  let evidence = blaiToolchainPsramCleanupEntryApplyEvidence(entry)
  outResult.evidence = evidence
  outResult.stateAfter = evidence.stateAfter
  outResult.nextLayerIndexAfter = evidence.nextLayerIndexAfter
  outResult.cleanupSlotStartAfter = evidence.cleanupSlotStartAfter
  outResult.savedDebugLogFlagAfter = evidence.savedDebugLogFlagAfter
  outResult.debugSnapshotPath = evidence.debugSnapshotPath
  outResult.entersCleanupSweep = evidence.entersCleanupSweep
  outResult.jumpsLayerTransition = evidence.jumpsLayerTransition
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainPsramCleanupEntryApplyPlan*(
    entry: BlaiToolchainPsramCleanupEntryPlan):
    BlaiToolchainPsramCleanupEntryApplyPlan =
  ## Convenience wrapper for checked cleanup-entry state projection.
  blaiToolchainPsramCleanupEntryApplyPlanInto(entry, result)

