    plan: BlaiToolchainPsramCleanupEntryApplyPlan): bool =
  ## Apply recovered cleanup-entry branch state to caller-owned storage.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

static:
  let staticCleanupEntry = blaiToolchainPsramCleanupEntryPlan(3, true)
  var staticCleanupEntryApplyInto: BlaiToolchainPsramCleanupEntryApplyPlan
  blaiToolchainPsramCleanupEntryApplyPlanInto(
