  doAssert staticCleanupSummarySavedDebug
  doAssert staticCleanupSummaryDebugPath
  doAssert staticCleanupSummarySweep
  doAssert not staticCleanupSummaryJump
  staticCleanupSummaryNextLayer = -19
  staticCleanupSummarySlot = 29
  staticCleanupSummarySavedDebug = false
  staticCleanupSummaryDebugPath = false
  staticCleanupSummarySweep = false
  staticCleanupSummaryJump = true
  doAssert blaiApplyToolchainPsramCleanupEntrySummaryScalars(
    staticCleanupSummaryNextLayer, staticCleanupSummarySlot,
    staticCleanupSummarySavedDebug, staticCleanupSummaryDebugPath,
    staticCleanupSummarySweep, staticCleanupSummaryJump,
