  doAssert staticCleanupSummaryNextLayer == 4
  doAssert staticCleanupSummarySlot == 0
  doAssert staticCleanupSummarySavedDebug
  doAssert staticCleanupSummaryDebugPath
  doAssert staticCleanupSummarySweep
