proc blaiToolchainPsramPostSearchSlotPlanInto*(
    slotValues: openArray[int32],
    slot: uint32,
    currentLayerIndex: int32,
    currentLayerTypeValue, nextLayerTypeValue: int32,
    startPatchSlot: int32,
    routeDebugFlag: bool,
    retainedValue: int32,
    outResult: var BlaiToolchainPsramPostSearchSlotPlan) =
  ## Recover one slot-table cleanup action after `search_set_patch`.
  ##
  ## In `PSRAM_allocate+0x193a`, slots owned by the current layer either keep
  ## live metadata by storing the recovered retained value, or clear the
  ## occupied bitmap. Slots owned by another layer are ignored.
  outResult = default(BlaiToolchainPsramPostSearchSlotPlan)
  outResult.slot = slot
  outResult.currentLayerIndex = currentLayerIndex
  outResult.currentLayerTypeValue = currentLayerTypeValue
  outResult.nextLayerTypeValue = nextLayerTypeValue
  outResult.startPatchSlot = startPatchSlot
  outResult.routeDebugFlag = routeDebugFlag
  outResult.retainedValue = retainedValue
  if currentLayerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramPostSearchSlotLayerIndex
    return
  let slotCursor =
    blaiToolchainPatchSlotValueCursor(slot, slotValues.len)
  if not slotCursor.valid:
    outResult.firstBlock = blaiToolchainPsramPostSearchSlotSlot
    return

  outResult.slotValueBefore = slotValues[slotCursor.index]
  outResult.slotValueAfter = outResult.slotValueBefore
  outResult.occupiedAfter = true
  if outResult.slotValueBefore != currentLayerIndex:
    outResult.action = blaiToolchainPsramPostSearchSlotIgnore
    outResult.firstBlock = blaiToolchainPsramPostSearchSlotNoBlock
    outResult.valid = true
    return

  let retainPlan =
    blaiToolchainPsramCleanupRetainPlan(
      currentLayerTypeValue, nextLayerTypeValue, startPatchSlot,
      routeDebugFlag)
  if retainPlan.retain:
    outResult.action = blaiToolchainPsramPostSearchSlotStoreRetained
    outResult.slotValueAfter = retainedValue
  else:
    outResult.action = blaiToolchainPsramPostSearchSlotRelease
    outResult.occupiedAfter = false
  outResult.firstBlock = blaiToolchainPsramPostSearchSlotNoBlock
  outResult.valid = true

proc blaiToolchainPsramPostSearchSlotPlan*(
    slotValues: openArray[int32],
    slot: uint32,
    currentLayerIndex: int32,
    currentLayerTypeValue, nextLayerTypeValue: int32,
    startPatchSlot: int32,
    routeDebugFlag: bool,
    retainedValue: int32): BlaiToolchainPsramPostSearchSlotPlan =
  ## Convenience wrapper for one recovered post-search slot cleanup action.
  blaiToolchainPsramPostSearchSlotPlanInto(
    slotValues, slot, currentLayerIndex, currentLayerTypeValue,
    nextLayerTypeValue, startPatchSlot, routeDebugFlag, retainedValue, result)

proc blaiToolchainPsramPostSearchSlotState*(
    slot: uint32,
    action: BlaiToolchainPsramPostSearchSlotAction,
    slotValueBefore: int32,
    slotValueAfter: int32,
    occupiedAfter: bool,
    retainedValue: int32): BlaiToolchainPsramPostSearchSlotState =
  ## Build a typed caller-owned post-search slot cleanup state.
  result.slot = slot
  result.action = action
  result.slotValueBefore = slotValueBefore
  result.slotValueAfter = slotValueAfter
  result.occupiedAfter = occupiedAfter
  result.retainedValue = retainedValue

proc blaiToolchainPsramPostSearchSlotApplyEvidence*(
    slotPlan: BlaiToolchainPsramPostSearchSlotPlan):
    BlaiToolchainPsramPostSearchSlotApplyEvidence =
  ## Recover checked evidence for applying one post-search slot decision.
  result.slotPlanValid = slotPlan.valid
  if not slotPlan.valid:
    result.firstBlock = blaiToolchainPsramPostSearchSlotApplySlotPlan
    return

  result.stateAfter = blaiToolchainPsramPostSearchSlotState(
    slotPlan.slot, slotPlan.action, slotPlan.slotValueBefore,
    slotPlan.slotValueAfter, slotPlan.occupiedAfter, slotPlan.retainedValue)
  result.firstBlock = blaiToolchainPsramPostSearchSlotApplyNoBlock
  result.valid = true

proc blaiToolchainPsramPostSearchSlotApplyPlanInto*(
    slotPlan: BlaiToolchainPsramPostSearchSlotPlan,
    outResult: var BlaiToolchainPsramPostSearchSlotApplyPlan) =
  ## Prepare checked application of one post-search slot cleanup decision.
  outResult = default(BlaiToolchainPsramPostSearchSlotApplyPlan)
  outResult.slotPlan = slotPlan
  let evidence = blaiToolchainPsramPostSearchSlotApplyEvidence(slotPlan)
  outResult.evidence = evidence
  outResult.stateAfter = evidence.stateAfter
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainPsramPostSearchSlotApplyPlan*(
    slotPlan: BlaiToolchainPsramPostSearchSlotPlan):
    BlaiToolchainPsramPostSearchSlotApplyPlan =
  ## Convenience wrapper for checked post-search slot cleanup state.
  blaiToolchainPsramPostSearchSlotApplyPlanInto(slotPlan, result)

proc blaiApplyToolchainPsramPostSearchSlotState*(
    state: var BlaiToolchainPsramPostSearchSlotState,
    plan: BlaiToolchainPsramPostSearchSlotApplyPlan): bool =
  ## Apply recovered post-search slot cleanup to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPsramPostSearchSlotTablesState*(
    occupied: var openArray[bool],
    slotValues: var openArray[int32],
    state: BlaiToolchainPsramPostSearchSlotState): bool =
  ## Apply recovered post-search slot state to caller-owned tables.
  let occupiedCursor =
    blaiToolchainPatchOccupiedCursor(state.slot, occupied.len)
  let slotCursor =
    blaiToolchainPatchSlotValueCursor(state.slot, slotValues.len)
  if not occupiedCursor.valid or not slotCursor.valid:
    return false
  case state.action
  of blaiToolchainPsramPostSearchSlotIgnore:
    discard
  of blaiToolchainPsramPostSearchSlotStoreRetained:
    slotValues[slotCursor.index] = state.slotValueAfter
  of blaiToolchainPsramPostSearchSlotRelease:
    occupied[occupiedCursor.index] = state.occupiedAfter
  true

proc blaiApplyToolchainPsramPostSearchSlotScalarState*(
    slot: var uint32,
    action: var BlaiToolchainPsramPostSearchSlotAction,
    slotValueBefore: var int32,
    slotValueAfter: var int32,
    occupiedAfter: var bool,
    retainedValue: var int32,
    state: BlaiToolchainPsramPostSearchSlotState): bool =
  ## Apply recovered post-search slot metadata from typed state.
  slot = state.slot
  action = state.action
  slotValueBefore = state.slotValueBefore
  slotValueAfter = state.slotValueAfter
  occupiedAfter = state.occupiedAfter
  retainedValue = state.retainedValue
  true

proc blaiApplyToolchainPsramPostSearchSlotScalars*(
    slot: var uint32,
    action: var BlaiToolchainPsramPostSearchSlotAction,
    slotValueBefore: var int32,
    slotValueAfter: var int32,
    occupiedAfter: var bool,
    retainedValue: var int32,
    plan: BlaiToolchainPsramPostSearchSlotApplyPlan): bool =
  ## Apply recovered post-search slot metadata.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramPostSearchSlotScalarState(
    slot, action, slotValueBefore, slotValueAfter, occupiedAfter,
    retainedValue, plan.stateAfter)

proc blaiApplyToolchainPsramPostSearchSlot*(
    occupied: var openArray[bool],
    slotValues: var openArray[int32],
    plan: BlaiToolchainPsramPostSearchSlotPlan): bool =
  ## Apply one recovered post-search slot-table cleanup action.
  let applyPlan = blaiToolchainPsramPostSearchSlotApplyPlan(plan)
  if not applyPlan.valid:
    return false
  blaiApplyToolchainPsramPostSearchSlotTablesState(
    occupied, slotValues, applyPlan.stateAfter)

proc blaiToolchainPsramCleanupDebugSlotPlanInto*(
    occupied: openArray[bool],
    slot: uint32,
    debugLogFlag: bool,
    outResult: var BlaiToolchainPsramCleanupDebugSlotPlan) =
  ## Recover the cleanup-loop debug reload of the occupied bitmap slot.
  ##
  ## After the cleanup action for a `MAX_PSRAM_PATCH` slot, `PSRAM_allocate`
  ## reloads the occupied table entry only when debug logging is active. The
  ## table is represented as a typed boolean view in Nim.
  outResult = default(BlaiToolchainPsramCleanupDebugSlotPlan)
  outResult.slot = slot
  outResult.debugLogFlag = debugLogFlag
  outResult.occupiedStorageCount = blaiOpenArrayLenU32(occupied)
  outResult.printRequested = debugLogFlag
  if not debugLogFlag:
    outResult.firstBlock = blaiToolchainPsramCleanupDebugSlotNoBlock
    outResult.valid = true
    return

  let occupiedCursor =
    blaiToolchainPatchOccupiedCursor(slot, occupied.len)
  if not occupiedCursor.valid:
    outResult.firstBlock = blaiToolchainPsramCleanupDebugSlotSlot
    return

  outResult.occupiedValue = occupied[occupiedCursor.index]
  outResult.firstBlock = blaiToolchainPsramCleanupDebugSlotNoBlock
  outResult.valid = true

proc blaiToolchainPsramCleanupDebugSlotPlan*(
    occupied: openArray[bool],
    slot: uint32,
    debugLogFlag: bool): BlaiToolchainPsramCleanupDebugSlotPlan =
  ## Convenience wrapper for recovered cleanup-loop debug bitmap reload.
  blaiToolchainPsramCleanupDebugSlotPlanInto(
    occupied, slot, debugLogFlag, result)

proc blaiToolchainPsramCleanupDebugSlotState*(
    slot: uint32,
    occupiedValue: bool): BlaiToolchainPsramCleanupDebugSlotState =
  ## Build a typed caller-owned cleanup debug bitmap state.
  result.slot = slot
  result.occupiedValue = occupiedValue

proc blaiToolchainPsramCleanupDebugSlotSummaryState*(
    printRequested: bool,
    slot: uint32,
    occupiedValue: bool): BlaiToolchainPsramCleanupDebugSlotSummaryState =
  ## Build a typed caller-owned cleanup debug summary state.
  result.printRequested = printRequested
  result.slot = slot
  result.occupiedValue = occupiedValue

proc blaiToolchainPsramCleanupDebugSlotApplyEvidence*(
    slot: BlaiToolchainPsramCleanupDebugSlotPlan):
    BlaiToolchainPsramCleanupDebugSlotApplyEvidence =
  ## Recover checked evidence for cleanup debug bitmap reload application.
  result.slotPlanValid = slot.valid
  if not slot.valid:
    result.firstBlock = blaiToolchainPsramCleanupDebugSlotApplySlotPlan
    return

  result.printRequested = slot.printRequested
  result.summaryStateAfter = blaiToolchainPsramCleanupDebugSlotSummaryState(
    slot.printRequested, slot.slot, slot.occupiedValue)
  if slot.printRequested:
    result.stateAfter = blaiToolchainPsramCleanupDebugSlotState(
      slot.slot, slot.occupiedValue)
  result.firstBlock = blaiToolchainPsramCleanupDebugSlotApplyNoBlock
  result.valid = true

proc blaiToolchainPsramCleanupDebugSlotApplyPlanInto*(
    slot: BlaiToolchainPsramCleanupDebugSlotPlan,
    outResult: var BlaiToolchainPsramCleanupDebugSlotApplyPlan) =
  ## Prepare checked application of cleanup debug bitmap reload state.
  outResult = default(BlaiToolchainPsramCleanupDebugSlotApplyPlan)
  outResult.slot = slot
  let evidence = blaiToolchainPsramCleanupDebugSlotApplyEvidence(slot)
  outResult.evidence = evidence
  outResult.printRequested = evidence.printRequested
  outResult.stateAfter = evidence.stateAfter
  outResult.summaryStateAfter = evidence.summaryStateAfter
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainPsramCleanupDebugSlotApplyPlan*(
    slot: BlaiToolchainPsramCleanupDebugSlotPlan):
    BlaiToolchainPsramCleanupDebugSlotApplyPlan =
  ## Convenience wrapper for checked cleanup debug bitmap reload application.
  blaiToolchainPsramCleanupDebugSlotApplyPlanInto(slot, result)

proc blaiApplyToolchainPsramCleanupDebugSlot*(
    state: var BlaiToolchainPsramCleanupDebugSlotState,
    plan: BlaiToolchainPsramCleanupDebugSlotApplyPlan): bool =
  ## Apply recovered cleanup debug bitmap state to caller-owned storage.
  if not plan.valid:
    return false
  if plan.printRequested:
    state = plan.stateAfter
  true

proc blaiApplyToolchainPsramCleanupDebugSlotScalarState*(
    slot: var uint32,
    occupiedValue: var bool,
    state: BlaiToolchainPsramCleanupDebugSlotState): bool =
  ## Apply recovered cleanup debug slot metadata from typed state.
  slot = state.slot
  occupiedValue = state.occupiedValue
  true

proc blaiApplyToolchainPsramCleanupDebugSlotSummaryScalarState*(
    printRequested: var bool,
    slot: var uint32,
