proc blaiApplyToolchainPsramCleanupDebugSlotSummaryScalars*(
    printRequested: var bool,
    slot: var uint32,
    occupiedValue: var bool,
    plan: BlaiToolchainPsramCleanupDebugSlotApplyPlan): bool =
  ## Apply recovered cleanup debug summary metadata.
  if not plan.valid:
