proc blaiApplyToolchainPsramCleanupDebugSlotScalars*(
    slot: var uint32,
    occupiedValue: var bool,
    plan: BlaiToolchainPsramCleanupDebugSlotApplyPlan): bool =
  ## Apply recovered cleanup debug slot metadata.
  if not plan.valid:
    return false
  if plan.printRequested:
    return blaiApplyToolchainPsramCleanupDebugSlotScalarState(
      slot, occupiedValue, plan.stateAfter)
  true

static:
  let staticCleanupDebugSlot = BlaiToolchainPsramCleanupDebugSlotPlan(
    slot: 1'u32,
    debugLogFlag: true,
    occupiedStorageCount: 3,
    occupiedValue: false,
    printRequested: true,
    firstBlock: blaiToolchainPsramCleanupDebugSlotNoBlock,
    valid: true)
  var staticCleanupDebugSlotApplyInto:
    BlaiToolchainPsramCleanupDebugSlotApplyPlan
  blaiToolchainPsramCleanupDebugSlotApplyPlanInto(
    staticCleanupDebugSlot, staticCleanupDebugSlotApplyInto)
  let staticCleanupDebugSlotApply =
    blaiToolchainPsramCleanupDebugSlotApplyPlan(staticCleanupDebugSlot)
  let staticCleanupDebugSlotEvidence =
    blaiToolchainPsramCleanupDebugSlotApplyEvidence(staticCleanupDebugSlot)
  doAssert staticCleanupDebugSlotEvidence.valid
  doAssert staticCleanupDebugSlotEvidence.slotPlanValid
  doAssert staticCleanupDebugSlotApply.evidence == staticCleanupDebugSlotEvidence
  doAssert staticCleanupDebugSlotApply.summaryStateAfter ==
    staticCleanupDebugSlotEvidence.summaryStateAfter
  doAssert staticCleanupDebugSlotApplyInto == staticCleanupDebugSlotApply
  doAssert staticCleanupDebugSlotApply.valid
  doAssert staticCleanupDebugSlotApply.printRequested
  doAssert staticCleanupDebugSlotApply.stateAfter ==
    blaiToolchainPsramCleanupDebugSlotState(1'u32, false)
  doAssert staticCleanupDebugSlotApply.summaryStateAfter ==
    blaiToolchainPsramCleanupDebugSlotSummaryState(true, 1'u32, false)
  var staticCleanupDebugState =
    blaiToolchainPsramCleanupDebugSlotState(99'u32, true)
  doAssert blaiApplyToolchainPsramCleanupDebugSlot(
    staticCleanupDebugState, staticCleanupDebugSlotApply)
  doAssert staticCleanupDebugState ==
    blaiToolchainPsramCleanupDebugSlotState(1'u32, false)
  var staticCleanupDebugSlotScalar = 99'u32
  var staticCleanupDebugOccupiedScalar = true
  doAssert blaiApplyToolchainPsramCleanupDebugSlotScalarState(
    staticCleanupDebugSlotScalar, staticCleanupDebugOccupiedScalar,
    staticCleanupDebugSlotApply.stateAfter)
  doAssert staticCleanupDebugSlotScalar == 1'u32
  doAssert not staticCleanupDebugOccupiedScalar
  var staticCleanupDebugPrintRequested = false
  staticCleanupDebugSlotScalar = 99'u32
  staticCleanupDebugOccupiedScalar = true
  doAssert blaiApplyToolchainPsramCleanupDebugSlotSummaryScalarState(
    staticCleanupDebugPrintRequested, staticCleanupDebugSlotScalar,
    staticCleanupDebugOccupiedScalar,
    staticCleanupDebugSlotApply.summaryStateAfter)
  doAssert staticCleanupDebugPrintRequested
  doAssert staticCleanupDebugSlotScalar == 1'u32
  doAssert not staticCleanupDebugOccupiedScalar
  staticCleanupDebugPrintRequested = false
  staticCleanupDebugSlotScalar = 88'u32
  staticCleanupDebugOccupiedScalar = true
  doAssert blaiApplyToolchainPsramCleanupDebugSlotSummaryScalars(
    staticCleanupDebugPrintRequested, staticCleanupDebugSlotScalar,
    staticCleanupDebugOccupiedScalar, staticCleanupDebugSlotApply)
  doAssert staticCleanupDebugPrintRequested
  doAssert staticCleanupDebugSlotScalar == 1'u32
  doAssert not staticCleanupDebugOccupiedScalar
  staticCleanupDebugSlotScalar = 88'u32
  staticCleanupDebugOccupiedScalar = true
  doAssert blaiApplyToolchainPsramCleanupDebugSlotScalars(
    staticCleanupDebugSlotScalar, staticCleanupDebugOccupiedScalar,
    staticCleanupDebugSlotApply)
  doAssert staticCleanupDebugSlotScalar == 1'u32
  doAssert not staticCleanupDebugOccupiedScalar
  let staticQuietCleanupDebugSlot = BlaiToolchainPsramCleanupDebugSlotPlan(
    slot: 9'u32,
    debugLogFlag: false,
    occupiedStorageCount: 0,
    printRequested: false,
    firstBlock: blaiToolchainPsramCleanupDebugSlotNoBlock,
    valid: true)
  let staticQuietCleanupDebugSlotApply =
    blaiToolchainPsramCleanupDebugSlotApplyPlan(staticQuietCleanupDebugSlot)
  let staticQuietCleanupDebugSlotEvidence =
    blaiToolchainPsramCleanupDebugSlotApplyEvidence(staticQuietCleanupDebugSlot)
  doAssert staticQuietCleanupDebugSlotEvidence.valid
  doAssert staticQuietCleanupDebugSlotEvidence.slotPlanValid
  doAssert staticQuietCleanupDebugSlotApply.evidence ==
    staticQuietCleanupDebugSlotEvidence
  doAssert staticQuietCleanupDebugSlotApply.valid
  doAssert not staticQuietCleanupDebugSlotApply.printRequested
  doAssert staticQuietCleanupDebugSlotApply.summaryStateAfter ==
    blaiToolchainPsramCleanupDebugSlotSummaryState(false, 9'u32, false)
  var staticQuietCleanupDebugState =
    blaiToolchainPsramCleanupDebugSlotState(7'u32, true)
  doAssert blaiApplyToolchainPsramCleanupDebugSlot(
    staticQuietCleanupDebugState, staticQuietCleanupDebugSlotApply)
  doAssert staticQuietCleanupDebugState ==
    blaiToolchainPsramCleanupDebugSlotState(7'u32, true)
  staticCleanupDebugSlotScalar = 88'u32
  staticCleanupDebugOccupiedScalar = true
  doAssert blaiApplyToolchainPsramCleanupDebugSlotScalars(
    staticCleanupDebugSlotScalar, staticCleanupDebugOccupiedScalar,
    staticQuietCleanupDebugSlotApply)
  doAssert staticCleanupDebugSlotScalar == 88'u32
  doAssert staticCleanupDebugOccupiedScalar
  staticCleanupDebugPrintRequested = true
  doAssert blaiApplyToolchainPsramCleanupDebugSlotSummaryScalars(
    staticCleanupDebugPrintRequested, staticCleanupDebugSlotScalar,
    staticCleanupDebugOccupiedScalar, staticQuietCleanupDebugSlotApply)
  doAssert not staticCleanupDebugPrintRequested
  doAssert staticCleanupDebugSlotScalar == 9'u32
  doAssert not staticCleanupDebugOccupiedScalar
  let staticBlockedCleanupDebugSlotApply =
    blaiToolchainPsramCleanupDebugSlotApplyPlan(
      BlaiToolchainPsramCleanupDebugSlotPlan(
        slot: 9'u32,
        debugLogFlag: true,
        occupiedStorageCount: 3,
        printRequested: true,
        firstBlock: blaiToolchainPsramCleanupDebugSlotSlot,
        valid: false))
  doAssert not staticBlockedCleanupDebugSlotApply.evidence.valid
  doAssert not staticBlockedCleanupDebugSlotApply.evidence.slotPlanValid
  doAssert not staticBlockedCleanupDebugSlotApply.valid
  doAssert staticBlockedCleanupDebugSlotApply.firstBlock ==
    blaiToolchainPsramCleanupDebugSlotApplySlotPlan
  var staticBlockedCleanupDebugState =
    blaiToolchainPsramCleanupDebugSlotState(11'u32, true)
  doAssert not blaiApplyToolchainPsramCleanupDebugSlot(
    staticBlockedCleanupDebugState, staticBlockedCleanupDebugSlotApply)
  doAssert staticBlockedCleanupDebugState ==
    blaiToolchainPsramCleanupDebugSlotState(11'u32, true)
  staticCleanupDebugSlotScalar = 88'u32
  staticCleanupDebugOccupiedScalar = true
  doAssert not blaiApplyToolchainPsramCleanupDebugSlotScalars(
    staticCleanupDebugSlotScalar, staticCleanupDebugOccupiedScalar,
    staticBlockedCleanupDebugSlotApply)
  doAssert staticCleanupDebugSlotScalar == 88'u32
  doAssert staticCleanupDebugOccupiedScalar
  staticCleanupDebugPrintRequested = true
  doAssert not blaiApplyToolchainPsramCleanupDebugSlotSummaryScalars(
    staticCleanupDebugPrintRequested, staticCleanupDebugSlotScalar,
    staticCleanupDebugOccupiedScalar, staticBlockedCleanupDebugSlotApply)
  doAssert staticCleanupDebugPrintRequested
  doAssert staticCleanupDebugSlotScalar == 88'u32
  doAssert staticCleanupDebugOccupiedScalar

proc blaiToolchainPsramMetadataDiscardGate*(
    layerInputCount, nextLayerTypeValue: int32,
    fieldAValue, fieldBValue: int32,
    relationConsumerFound: bool): BlaiToolchainPsramMetadataDiscardGate =
  ## Recover the special general-metadata discard predicate.
  result.layerInputCount = layerInputCount
  result.nextLayerTypeValue = nextLayerTypeValue
  result.fieldAValue = fieldAValue
  result.fieldBValue = fieldBValue
  result.relationConsumerFound = relationConsumerFound
  result.oneInputLayer =
    layerInputCount == BlaiToolchainPsramMetadataDiscardInputCount
  result.nextLayerIsRoute =
    nextLayerTypeValue == BlaiToolchainPsramOwnerRouteType
  result.fieldAMatches =
    fieldAValue == BlaiToolchainPsramMetadataDiscardFieldValue
  result.fieldBMatches =
    fieldBValue == BlaiToolchainPsramMetadataDiscardFieldValue
  result.noFutureConsumer = not relationConsumerFound
  result.clearGeneralMetadata =
    result.oneInputLayer and result.nextLayerIsRoute and
      result.fieldAMatches and result.fieldBMatches and
      result.noFutureConsumer
  result.valid = true

proc blaiToolchainPsramMetadataDiscardPlanInto*(
    currentLayerIndex, layerInputCount, nextLayerTypeValue: int32,
    fieldAValue, fieldBValue: int32,
    relationConsumerFound: bool,
    currentStartPatchSlot, currentPatchCount: int32,
    outResult: var BlaiToolchainPsramMetadataDiscardPlan) =
  ## Recover special `PSRAM_allocate` clearing of general patch metadata.
  ##
  ## The converter writes the recovered invalid start/count sentinels when a
  ## one-input layer feeds raw next type 3, two recovered layer fields are both
  ## 2, and no future relation consumer was found.
  outResult = default(BlaiToolchainPsramMetadataDiscardPlan)
  outResult.currentLayerIndex = currentLayerIndex
  outResult.layerInputCount = layerInputCount
  outResult.nextLayerTypeValue = nextLayerTypeValue
  outResult.fieldAOffset = BlaiToolchainPsramMetadataDiscardFieldAOffset
  outResult.fieldBOffset = BlaiToolchainPsramMetadataDiscardFieldBOffset
  outResult.generalStartOffset = BlaiToolchainPatchDebugGeneralStartOffset
  outResult.generalCountOffset = BlaiToolchainPatchDebugGeneralCountOffset
  outResult.fieldAValue = fieldAValue
  outResult.fieldBValue = fieldBValue
  outResult.relationConsumerFound = relationConsumerFound
  outResult.currentStartPatchSlot = currentStartPatchSlot
  outResult.currentPatchCount = currentPatchCount
  outResult.startPatchSlotAfter = currentStartPatchSlot
  outResult.patchCountAfter = currentPatchCount
  if currentLayerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramMetadataDiscardLayerIndex
    return

  let discardGate =
    blaiToolchainPsramMetadataDiscardGate(
      layerInputCount, nextLayerTypeValue, fieldAValue, fieldBValue,
      relationConsumerFound)
  outResult.clearGeneralMetadata = discardGate.clearGeneralMetadata
  if outResult.clearGeneralMetadata:
    outResult.startPatchSlotAfter = BlaiToolchainPatchInvalidStartSlot
    outResult.patchCountAfter = BlaiToolchainPatchInvalidCount
  outResult.firstBlock = blaiToolchainPsramMetadataDiscardNoBlock
  outResult.valid = true

proc blaiToolchainPsramMetadataDiscardPlan*(
    currentLayerIndex, layerInputCount, nextLayerTypeValue: int32,
    fieldAValue, fieldBValue: int32,
    relationConsumerFound: bool,
    currentStartPatchSlot, currentPatchCount: int32):
    BlaiToolchainPsramMetadataDiscardPlan =
  ## Convenience wrapper for recovered general patch metadata invalidation.
  blaiToolchainPsramMetadataDiscardPlanInto(
    currentLayerIndex, layerInputCount, nextLayerTypeValue, fieldAValue,
    fieldBValue, relationConsumerFound, currentStartPatchSlot,
    currentPatchCount, result)

proc blaiToolchainPsramMetadataDiscardState*(
    currentLayerIndex: int32,
    generalStartOffset: uint32,
    generalCountOffset: uint32,
    clearGeneralMetadata: bool,
    startPatchSlotAfter: int32,
    patchCountAfter: int32): BlaiToolchainPsramMetadataDiscardState =
  ## Build a typed caller-owned metadata discard field state.
  result.currentLayerIndex = currentLayerIndex
  result.generalStartOffset = generalStartOffset
  result.generalCountOffset = generalCountOffset
  result.clearGeneralMetadata = clearGeneralMetadata
  result.startPatchSlotAfter = startPatchSlotAfter
  result.patchCountAfter = patchCountAfter

proc blaiToolchainPsramMetadataDiscardApplyEvidence*(
    discardPlan: BlaiToolchainPsramMetadataDiscardPlan):
    BlaiToolchainPsramMetadataDiscardApplyEvidence =
  ## Recover checked evidence for metadata discard state application.
  result.discardPlanValid = discardPlan.valid
  if not discardPlan.valid:
    result.firstBlock = blaiToolchainPsramMetadataDiscardApplyDiscardPlan
    return

  result.stateAfter = blaiToolchainPsramMetadataDiscardState(
    discardPlan.currentLayerIndex, discardPlan.generalStartOffset,
    discardPlan.generalCountOffset, discardPlan.clearGeneralMetadata,
    discardPlan.startPatchSlotAfter, discardPlan.patchCountAfter)
  result.firstBlock = blaiToolchainPsramMetadataDiscardApplyNoBlock
  result.valid = true

proc blaiToolchainPsramMetadataDiscardApplyPlanInto*(
    discardPlan: BlaiToolchainPsramMetadataDiscardPlan,
    outResult: var BlaiToolchainPsramMetadataDiscardApplyPlan) =
  ## Prepare checked application of metadata discard field state.
  outResult = default(BlaiToolchainPsramMetadataDiscardApplyPlan)
  outResult.discardPlan = discardPlan
  let evidence = blaiToolchainPsramMetadataDiscardApplyEvidence(discardPlan)
  outResult.evidence = evidence
  outResult.stateAfter = evidence.stateAfter
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainPsramMetadataDiscardApplyPlan*(
    discardPlan: BlaiToolchainPsramMetadataDiscardPlan):
    BlaiToolchainPsramMetadataDiscardApplyPlan =
  ## Convenience wrapper for checked metadata discard state projection.
  blaiToolchainPsramMetadataDiscardApplyPlanInto(discardPlan, result)

proc blaiApplyToolchainPsramMetadataDiscardState*(
    state: var BlaiToolchainPsramMetadataDiscardState,
    plan: BlaiToolchainPsramMetadataDiscardApplyPlan): bool =
  ## Apply recovered metadata discard to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPsramMetadataDiscardScalarState*(
    startPatchSlot, patchCount: var int32,
    state: BlaiToolchainPsramMetadataDiscardState) =
  ## Apply recovered metadata discard state to scalar metadata fields.
  startPatchSlot = state.startPatchSlotAfter
  patchCount = state.patchCountAfter

proc blaiApplyToolchainPsramMetadataDiscardSummaryScalarState*(
    currentLayerIndex: var int32,
    generalStartOffset, generalCountOffset: var uint32,
    clearGeneralMetadata: var bool,
    startPatchSlotAfter, patchCountAfter: var int32,
    state: BlaiToolchainPsramMetadataDiscardState): bool =
  ## Apply recovered metadata discard summary scalars from typed state.
  currentLayerIndex = state.currentLayerIndex
  generalStartOffset = state.generalStartOffset
  generalCountOffset = state.generalCountOffset
  clearGeneralMetadata = state.clearGeneralMetadata
  startPatchSlotAfter = state.startPatchSlotAfter
  patchCountAfter = state.patchCountAfter
  true

proc blaiApplyToolchainPsramMetadataDiscardSummaryScalars*(
    currentLayerIndex: var int32,
    generalStartOffset, generalCountOffset: var uint32,
    clearGeneralMetadata: var bool,
    startPatchSlotAfter, patchCountAfter: var int32,
    plan: BlaiToolchainPsramMetadataDiscardApplyPlan): bool =
  ## Apply recovered metadata discard summary scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramMetadataDiscardSummaryScalarState(
    currentLayerIndex, generalStartOffset, generalCountOffset,
    clearGeneralMetadata, startPatchSlotAfter, patchCountAfter,
    plan.stateAfter)

proc blaiApplyToolchainPsramMetadataDiscardBankState*(
    startPatchSlots: var openArray[int32],
    patchCounts: var openArray[int32],
    state: BlaiToolchainPsramMetadataDiscardState): bool =
  ## Apply recovered metadata discard state to per-layer metadata banks.
  let bankIndex =
    blaiToolchainPsramMetadataBankIndexAbi(state.currentLayerIndex)
  if not bankIndex.valid:
    return false
  let startCursor =
    blaiToolchainPsramMetadataBankCursor(
      bankIndex.value, startPatchSlots.len)
  let countCursor =
    blaiToolchainPsramMetadataBankCursor(
      bankIndex.value, patchCounts.len)
  if not startCursor.valid or not countCursor.valid:
    return false
  startPatchSlots[startCursor.index] = state.startPatchSlotAfter
  patchCounts[countCursor.index] = state.patchCountAfter
  true

