proc blaiToolchainPsramFallbackTypeExclusion*(
    layerTypeValue: int32): BlaiToolchainPsramFallbackTypeExclusion =
  ## Recover raw layer types that cannot arm fallback metadata.
  result.layerTypeValue = layerTypeValue
  result.routeTypeExcluded =
    layerTypeValue == BlaiToolchainPsramOwnerRouteType
  result.relationRouteTypeExcluded =
    layerTypeValue == BlaiToolchainPsramRelationRouteType
  result.specialTypeExcluded =
    layerTypeValue == BlaiToolchainPsramFallbackExcludedType
  result.excluded =
    result.routeTypeExcluded or
      result.relationRouteTypeExcluded or
      result.specialTypeExcluded
  result.valid = true

proc blaiToolchainPsramFallbackGatePlanInto*(
    layerTypeValue, inputCount: int32,
    outResult: var BlaiToolchainPsramFallbackGatePlan) =
  ## Recover the gate that arms unassigned patch metadata fallback.
  ##
  ## At `PSRAM_allocate+0x108d`, the converter arms this path for layers with
  ## at most two inputs, excluding raw route type `3`, raw relation route type
  ## `9`, and the still-unnamed raw type `0x26`.
  outResult = default(BlaiToolchainPsramFallbackGatePlan)
  outResult.layerTypeValue = layerTypeValue
  outResult.inputCount = inputCount
  if inputCount < 0:
    outResult.firstBlock = blaiToolchainPsramFallbackGateShape
    return

  outResult.inputCountWithinFallbackLimit =
    inputCount <= BlaiToolchainPsramFallbackMaxInputCount
  let typeExclusion =
    blaiToolchainPsramFallbackTypeExclusion(layerTypeValue)
  outResult.routeTypeExcluded = typeExclusion.routeTypeExcluded
  outResult.relationRouteTypeExcluded =
    typeExclusion.relationRouteTypeExcluded
  outResult.specialTypeExcluded = typeExclusion.specialTypeExcluded
  outResult.fallbackArmed =
    outResult.inputCountWithinFallbackLimit and not typeExclusion.excluded
  outResult.firstBlock = blaiToolchainPsramFallbackGateNoBlock
  outResult.valid = true

proc blaiToolchainPsramFallbackGatePlan*(
    layerTypeValue, inputCount: int32): BlaiToolchainPsramFallbackGatePlan =
  ## Convenience wrapper for recovered fallback arming gate.
  blaiToolchainPsramFallbackGatePlanInto(layerTypeValue, inputCount, result)

proc blaiToolchainPsramUnassignedMetadataGate*(
    relationConsumerFound, fallbackArmed: bool,
    gateValue: int32): BlaiToolchainPsramUnassignedMetadataGate =
  ## Recover the unassigned general-metadata write predicate.
  result.relationConsumerFound = relationConsumerFound
  result.fallbackArmed = fallbackArmed
  result.gateValue = gateValue
  result.noFutureConsumer = not relationConsumerFound
  result.fallbackActive = fallbackArmed
  result.gateIsZero = gateValue == 0
  result.writeFallbackMetadata =
    result.noFutureConsumer and result.fallbackActive and result.gateIsZero
  result.valid = true

proc blaiToolchainPsramUnassignedMetadataPlanInto*(
    layerIndex: int32,
    relationConsumerFound, fallbackArmed: bool,
    gateValue, scratchPatchCount: int32,
    currentStartPatchSlot, currentPatchCount: int32,
    outResult: var BlaiToolchainPsramUnassignedMetadataPlan) =
  ## Recover general metadata fallback when no future patch owner is found.
  ##
  ## After the relation-consumer scan, `PSRAM_allocate` writes
  ## `MAX_PSRAM_PATCH + 1` to the general start-slot metadata and the current
  ## scratch patch count to the general count metadata when no future consumer
  ## was found, the fallback path is armed, and the recovered gate value is
  ## zero. Otherwise the caller-owned metadata is preserved.
  outResult = default(BlaiToolchainPsramUnassignedMetadataPlan)
  outResult.layerIndex = layerIndex
  outResult.relationConsumerFound = relationConsumerFound
  outResult.fallbackArmed = fallbackArmed
  outResult.gateValue = gateValue
  outResult.scratchPatchCount = scratchPatchCount
  outResult.currentStartPatchSlot = currentStartPatchSlot
  outResult.currentPatchCount = currentPatchCount
  outResult.startPatchSlotAfter = currentStartPatchSlot
  outResult.patchCountAfter = currentPatchCount
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramUnassignedMetadataLayerIndex
    return
  let unassignedStartSlot = blaiToolchainPsramUnassignedStartSlotAbi()
  if not unassignedStartSlot.valid:
    outResult.firstBlock = blaiToolchainPsramUnassignedMetadataOverflow
    return

  outResult.unassignedStartSlot = unassignedStartSlot.value
  let metadataGate =
    blaiToolchainPsramUnassignedMetadataGate(
      relationConsumerFound, fallbackArmed, gateValue)
  outResult.writeFallbackMetadata = metadataGate.writeFallbackMetadata
  if outResult.writeFallbackMetadata:
    outResult.startPatchSlotAfter = outResult.unassignedStartSlot
    outResult.patchCountAfter = scratchPatchCount
    outResult.writesApplied = 2
  outResult.firstBlock = blaiToolchainPsramUnassignedMetadataNoBlock
  outResult.valid = true

proc blaiToolchainPsramUnassignedMetadataPlan*(
    layerIndex: int32,
    relationConsumerFound, fallbackArmed: bool,
    gateValue, scratchPatchCount: int32,
    currentStartPatchSlot, currentPatchCount: int32):
    BlaiToolchainPsramUnassignedMetadataPlan =
  ## Convenience wrapper for recovered unassigned general metadata fallback.
  blaiToolchainPsramUnassignedMetadataPlanInto(
    layerIndex, relationConsumerFound, fallbackArmed, gateValue,
    scratchPatchCount, currentStartPatchSlot, currentPatchCount, result)

