proc blaiToolchainPsramFallbackMetadataRawType*(
    layerTypeValue: int32): BlaiToolchainPsramFallbackMetadataRawType =
  ## Recover raw type selection after fallback metadata is armed.
  result.layerTypeValue = layerTypeValue
  result.selectsUnassigned =
    layerTypeValue == BlaiToolchainPsramOwnerConvType
  result.selectsClearInvalid = not result.selectsUnassigned
  result.valid = true

proc blaiToolchainPsramFallbackMetadataSelection*(
    layerTypeValue: int32,
    relationConsumerFound, fallbackArmed: bool):
    BlaiToolchainPsramFallbackMetadataSelection =
  ## Recover the post-search fallback metadata mode selector.
  result.layerTypeValue = layerTypeValue
  result.relationConsumerFound = relationConsumerFound
  result.fallbackArmed = fallbackArmed
  result.preservesForConsumer = relationConsumerFound
  result.preservesForInactiveFallback = not fallbackArmed
  let rawType =
    blaiToolchainPsramFallbackMetadataRawType(layerTypeValue)
  result.selectsUnassigned =
    not result.preservesForConsumer and
      not result.preservesForInactiveFallback and rawType.selectsUnassigned
  result.selectsClearInvalid =
    not result.preservesForConsumer and
      not result.preservesForInactiveFallback and
      rawType.selectsClearInvalid
  if result.preservesForConsumer or result.preservesForInactiveFallback:
    result.mode = blaiToolchainPsramFallbackMetadataPreserve
  elif result.selectsUnassigned:
    result.mode = blaiToolchainPsramFallbackMetadataUnassigned
  else:
    result.mode = blaiToolchainPsramFallbackMetadataClearInvalid
  result.valid = true

proc blaiToolchainPsramFallbackMetadataPlanInto*(
    layerIndex, layerTypeValue: int32,
    relationConsumerFound, fallbackArmed: bool,
    scratchPatchCount: int32,
    currentStartPatchSlot, currentPatchCount: int32,
    outResult: var BlaiToolchainPsramFallbackMetadataPlan) =
  ## Recover post-search fallback metadata selection in `PSRAM_allocate`.
  ##
  ## After the future-consumer scan, the converter preserves metadata when a
  ## consumer was found or the fallback gate is inactive. If fallback remains
  ## armed, raw type 0 writes the unassigned sentinel (`MAX_PSRAM_PATCH + 1`)
  ## and scratch patch count; other raw types clear general metadata to the
  ## recovered invalid start/count sentinels.
  outResult = default(BlaiToolchainPsramFallbackMetadataPlan)
  outResult.layerIndex = layerIndex
  outResult.layerTypeValue = layerTypeValue
  outResult.relationConsumerFound = relationConsumerFound
  outResult.fallbackArmed = fallbackArmed
  outResult.scratchPatchCount = scratchPatchCount
  outResult.currentStartPatchSlot = currentStartPatchSlot
  outResult.currentPatchCount = currentPatchCount
  outResult.startPatchSlotAfter = currentStartPatchSlot
  outResult.patchCountAfter = currentPatchCount
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramFallbackMetadataLayerIndex
    return
  let unassignedStartSlot = blaiToolchainPsramUnassignedStartSlotAbi()
  if not unassignedStartSlot.valid:
    outResult.firstBlock = blaiToolchainPsramFallbackMetadataOverflow
    return

  outResult.unassignedStartSlot = unassignedStartSlot.value
  let selection =
    blaiToolchainPsramFallbackMetadataSelection(
      layerTypeValue, relationConsumerFound, fallbackArmed)
  outResult.mode = selection.mode
  case selection.mode
  of blaiToolchainPsramFallbackMetadataPreserve:
    discard
  of blaiToolchainPsramFallbackMetadataUnassigned:
    outResult.startPatchSlotAfter = outResult.unassignedStartSlot
    outResult.patchCountAfter = scratchPatchCount
    outResult.writesApplied = 2
  of blaiToolchainPsramFallbackMetadataClearInvalid:
    outResult.startPatchSlotAfter = BlaiToolchainPatchInvalidStartSlot
    outResult.patchCountAfter = BlaiToolchainPatchInvalidCount
    outResult.writesApplied = 2
  outResult.firstBlock = blaiToolchainPsramFallbackMetadataNoBlock
  outResult.valid = true

proc blaiToolchainPsramFallbackMetadataPlan*(
    layerIndex, layerTypeValue: int32,
    relationConsumerFound, fallbackArmed: bool,
    scratchPatchCount: int32,
    currentStartPatchSlot, currentPatchCount: int32):
    BlaiToolchainPsramFallbackMetadataPlan =
  ## Convenience wrapper for recovered fallback metadata selection.
  blaiToolchainPsramFallbackMetadataPlanInto(
    layerIndex, layerTypeValue, relationConsumerFound, fallbackArmed,
    scratchPatchCount, currentStartPatchSlot, currentPatchCount, result)

