proc blaiToolchainPsramSplitMetadataDerivedStart*(
    selectedSplitCount, splitDenominator: uint32,
    scratchPatchCount, currentStartPatchSlot: int32):
    BlaiToolchainPsramSplitMetadataDerivedStart =
  ## Recover aggregate split-start arithmetic before per-split writes.
  if splitDenominator == 0'u32:
    return
  let denominator = blaiToolchainPsramSplitDenominatorAbi(splitDenominator)
  if not denominator.valid:
    return
  let quotient = scratchPatchCount div denominator.value
  let multiplier = selectedSplitCount - 2'u32
  let initialRemaining64 = quotient.int64 * multiplier.int64
  let firstStart64 = currentStartPatchSlot.int64 + initialRemaining64
  let initialRemaining = blaiToolchainPsramSplitMetadataScalarAbi(
    initialRemaining64)
  let firstStart = blaiToolchainPsramSplitMetadataScalarAbi(firstStart64)
  if not initialRemaining.valid or not firstStart.valid:
    return

  result.selectedSplitCount = selectedSplitCount
  result.splitDenominator = splitDenominator
  result.scratchPatchCount = scratchPatchCount
  result.currentStartPatchSlot = currentStartPatchSlot
  result.quotientPatchCount = quotient
  result.initialRemainingPatchCount = initialRemaining.value
  result.firstStartPatchSlot = firstStart.value
  result.valid = true

proc blaiToolchainPsramSplitMetadataPlanInto*(
    layerIndex, rawSplitCount, scratchPatchCount, currentStartPatchSlot: int32,
    outResult: var BlaiToolchainPsramSplitMetadataPlan) =
  ## Recover split start-slot metadata after unassigned fallback handling.
  ##
  ## `PSRAM_allocate` clamps a copied raw split count to at least two, divides
  ## the current scratch patch count by `selected - 1`, then writes derived
  ## start slots for split indexes `1 ..< selected`.
  outResult = default(BlaiToolchainPsramSplitMetadataPlan)
  outResult.layerIndex = layerIndex
  outResult.rawSplitCount = rawSplitCount
  outResult.scratchPatchCount = scratchPatchCount
  outResult.currentStartPatchSlot = currentStartPatchSlot
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataLayerIndex
    return
  if scratchPatchCount < 0 or currentStartPatchSlot < 0:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataScratchCount
    return

  let selected = blaiToolchainPsramSplitCountAbi(rawSplitCount)
  if not selected.valid:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataOverflow
    return
  outResult.selectedSplitCount = selected.value
  outResult.splitDenominator = selected.value - 1'u32
  outResult.writesApplied = outResult.splitDenominator
  if outResult.splitDenominator == 0'u32:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataOverflow
    return

  let derivedStart =
    blaiToolchainPsramSplitMetadataDerivedStart(
      selected.value, outResult.splitDenominator, scratchPatchCount,
      currentStartPatchSlot)
  if not derivedStart.valid:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataOverflow
    return

  outResult.quotientPatchCount = derivedStart.quotientPatchCount
  outResult.initialRemainingPatchCount =
    derivedStart.initialRemainingPatchCount
  outResult.firstStartPatchSlot = derivedStart.firstStartPatchSlot
  outResult.lastStartPatchSlot = currentStartPatchSlot
  outResult.firstBlock = blaiToolchainPsramSplitMetadataNoBlock
  outResult.valid = true

proc blaiToolchainPsramSplitMetadataPlan*(
    layerIndex, rawSplitCount, scratchPatchCount, currentStartPatchSlot: int32):
    BlaiToolchainPsramSplitMetadataPlan =
  ## Convenience wrapper for recovered split start-slot metadata planning.
  blaiToolchainPsramSplitMetadataPlanInto(
    layerIndex, rawSplitCount, scratchPatchCount, currentStartPatchSlot, result)

proc blaiToolchainPsramSplitMetadataState*(
    layerIndex: int32,
    selectedSplitCount: uint32,
    splitDenominator: uint32,
    quotientPatchCount: int32,
    initialRemainingPatchCount: int32,
    firstStartPatchSlot: int32,
    lastStartPatchSlot: int32,
    writesApplied: uint32): BlaiToolchainPsramSplitMetadataState =
  ## Build a typed caller-owned split metadata write state.
  result.layerIndex = layerIndex
  result.selectedSplitCount = selectedSplitCount
  result.splitDenominator = splitDenominator
  result.quotientPatchCount = quotientPatchCount
  result.initialRemainingPatchCount = initialRemainingPatchCount
  result.firstStartPatchSlot = firstStartPatchSlot
  result.lastStartPatchSlot = lastStartPatchSlot
  result.writesApplied = writesApplied

proc blaiToolchainPsramSplitMetadataApplyPlanInto*(
    metadataPlan: BlaiToolchainPsramSplitMetadataPlan,
    outResult: var BlaiToolchainPsramSplitMetadataApplyPlan) =
  ## Prepare checked application of split metadata write state.
  outResult = default(BlaiToolchainPsramSplitMetadataApplyPlan)
  outResult.metadataPlan = metadataPlan
  if not metadataPlan.valid:
    outResult.firstBlock =
      blaiToolchainPsramSplitMetadataApplyMetadataPlan
    return

  outResult.stateAfter = blaiToolchainPsramSplitMetadataState(
    metadataPlan.layerIndex, metadataPlan.selectedSplitCount,
    metadataPlan.splitDenominator, metadataPlan.quotientPatchCount,
    metadataPlan.initialRemainingPatchCount,
    metadataPlan.firstStartPatchSlot, metadataPlan.lastStartPatchSlot,
    metadataPlan.writesApplied)
  outResult.firstBlock = blaiToolchainPsramSplitMetadataApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramSplitMetadataApplyPlan*(
    metadataPlan: BlaiToolchainPsramSplitMetadataPlan):
    BlaiToolchainPsramSplitMetadataApplyPlan =
  ## Convenience wrapper for checked split metadata state projection.
  blaiToolchainPsramSplitMetadataApplyPlanInto(metadataPlan, result)

proc blaiApplyToolchainPsramSplitMetadataState*(
    state: var BlaiToolchainPsramSplitMetadataState,
    plan: BlaiToolchainPsramSplitMetadataApplyPlan): bool =
  ## Apply recovered split metadata summary to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPsramSplitMetadataScalarState*(
    layerIndex: var int32,
    selectedSplitCount, splitDenominator: var uint32,
    quotientPatchCount, initialRemainingPatchCount: var int32,
    firstStartPatchSlot, lastStartPatchSlot: var int32,
    writesApplied: var uint32,
    state: BlaiToolchainPsramSplitMetadataState): bool =
  ## Apply recovered split metadata summary scalars from typed state.
  layerIndex = state.layerIndex
  selectedSplitCount = state.selectedSplitCount
  splitDenominator = state.splitDenominator
  quotientPatchCount = state.quotientPatchCount
  initialRemainingPatchCount = state.initialRemainingPatchCount
  firstStartPatchSlot = state.firstStartPatchSlot
  lastStartPatchSlot = state.lastStartPatchSlot
  writesApplied = state.writesApplied
  true

proc blaiApplyToolchainPsramSplitMetadataScalars*(
    layerIndex: var int32,
    selectedSplitCount, splitDenominator: var uint32,
    quotientPatchCount, initialRemainingPatchCount: var int32,
    firstStartPatchSlot, lastStartPatchSlot: var int32,
    writesApplied: var uint32,
    plan: BlaiToolchainPsramSplitMetadataApplyPlan): bool =
  ## Apply recovered split metadata summary scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramSplitMetadataScalarState(
    layerIndex, selectedSplitCount, splitDenominator, quotientPatchCount,
    initialRemainingPatchCount, firstStartPatchSlot, lastStartPatchSlot,
    writesApplied, plan.stateAfter)

proc blaiToolchainPsramSplitMetadataPosition*(
    splitIndex, selectedSplitCount: uint32):
    BlaiToolchainPsramSplitMetadataPosition =
  ## Recover the loop position for split metadata indexes
  ## `1 ..< selectedSplitCount`.
  if splitIndex == 0'u32 or splitIndex >= selectedSplitCount:
    return

  result.splitIndex = splitIndex
  result.selectedSplitCount = selectedSplitCount
  result.offsetIndex = splitIndex - 1'u32
  result.last = splitIndex == selectedSplitCount - 1'u32
  result.valid = true

proc blaiToolchainPsramSplitMetadataCursorStart*(
    firstStartPatchSlot, quotientPatchCount: int32,
    position: BlaiToolchainPsramSplitMetadataPosition):
    BlaiToolchainPsramSplitMetadataCursorStart =
  ## Recover one split metadata cursor's derived start slot.
  if not position.valid:
    return

  let decrement64 =
    quotientPatchCount.int64 * position.offsetIndex.int64
  let start64 = firstStartPatchSlot.int64 - decrement64
  let startPatchSlot = blaiToolchainPsramSplitMetadataScalarAbi(start64)
  if not startPatchSlot.valid:
    return

  result.firstStartPatchSlot = firstStartPatchSlot
  result.quotientPatchCount = quotientPatchCount
  result.offsetIndex = position.offsetIndex
  result.decrementPatchCount = decrement64
  result.startPatchSlot = startPatchSlot.value
  result.last = position.last
  result.valid = true

proc blaiToolchainPsramSplitMetadataCursorInto*(
    plan: BlaiToolchainPsramSplitMetadataPlan,
    splitIndex: uint32,
    outResult: var BlaiToolchainPsramSplitMetadataCursor) =
  ## Recover one loop iteration of split start-slot metadata writes.
  ##
  ## `PSRAM_allocate` writes split indexes `1 ..< selectedSplitCount`, starting
  ## from the first derived start slot and subtracting the quotient per entry.
  outResult = default(BlaiToolchainPsramSplitMetadataCursor)
  outResult.splitIndex = splitIndex
  outResult.selectedSplitCount = plan.selectedSplitCount
  if not plan.valid:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataCursorPlan
    return
  let position =
    blaiToolchainPsramSplitMetadataPosition(splitIndex, plan.selectedSplitCount)
  if not position.valid:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataCursorIndex
    return

  let cursorStart =
    blaiToolchainPsramSplitMetadataCursorStart(
      plan.firstStartPatchSlot, plan.quotientPatchCount, position)
  if not cursorStart.valid:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataCursorOverflow
    return

  outResult.startPatchSlot = cursorStart.startPatchSlot
  outResult.last = cursorStart.last
  outResult.firstBlock = blaiToolchainPsramSplitMetadataCursorNoBlock
  outResult.valid = true

proc blaiToolchainPsramSplitMetadataCursor*(
    plan: BlaiToolchainPsramSplitMetadataPlan,
    splitIndex: uint32): BlaiToolchainPsramSplitMetadataCursor =
  ## Convenience wrapper for one recovered split metadata write cursor.
  blaiToolchainPsramSplitMetadataCursorInto(plan, splitIndex, result)

proc blaiToolchainPsramSplitMetadataCursorInto*(
    state: BlaiToolchainPsramSplitMetadataState,
    splitIndex: uint32,
    outResult: var BlaiToolchainPsramSplitMetadataCursor) =
  ## Recover one split metadata write cursor from typed aggregate state.
  outResult = default(BlaiToolchainPsramSplitMetadataCursor)
  outResult.splitIndex = splitIndex
  outResult.selectedSplitCount = state.selectedSplitCount
  if state.selectedSplitCount == 0'u32 or state.splitDenominator == 0'u32:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataCursorPlan
    return
  let position =
    blaiToolchainPsramSplitMetadataPosition(splitIndex, state.selectedSplitCount)
  if not position.valid:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataCursorIndex
    return

  let cursorStart =
    blaiToolchainPsramSplitMetadataCursorStart(
      state.firstStartPatchSlot, state.quotientPatchCount, position)
  if not cursorStart.valid:
    outResult.firstBlock = blaiToolchainPsramSplitMetadataCursorOverflow
    return

  outResult.startPatchSlot = cursorStart.startPatchSlot
  outResult.last = cursorStart.last
  outResult.firstBlock = blaiToolchainPsramSplitMetadataCursorNoBlock
  outResult.valid = true

proc blaiToolchainPsramSplitMetadataCursor*(
    state: BlaiToolchainPsramSplitMetadataState,
    splitIndex: uint32): BlaiToolchainPsramSplitMetadataCursor =
  ## Convenience wrapper for one typed-state split metadata write cursor.
  blaiToolchainPsramSplitMetadataCursorInto(state, splitIndex, result)

proc blaiApplyToolchainPsramSplitMetadataState*(
    splitStartSlots: var openArray[int32],
    state: BlaiToolchainPsramSplitMetadataState): bool =
  ## Apply recovered split start-slot metadata state to caller-owned storage.
  if splitStartSlots.len < int(state.selectedSplitCount):
    return false
  for splitIndex in 1'u32 ..< state.selectedSplitCount:
    let cursor = blaiToolchainPsramSplitMetadataCursor(state, splitIndex)
    if not cursor.valid:
      return false
    let splitCursor =
      blaiToolchainPsramSplitStartSlotCursor(
        splitIndex, splitStartSlots.len)
    if not splitCursor.valid:
      return false
    splitStartSlots[splitCursor.index] = cursor.startPatchSlot
  true

proc blaiApplyToolchainPsramSplitMetadata*(
    splitStartSlots: var openArray[int32],
    plan: BlaiToolchainPsramSplitMetadataPlan): bool =
  ## Apply recovered split start-slot metadata to caller-owned storage.
  let applyPlan = blaiToolchainPsramSplitMetadataApplyPlan(plan)
  if not applyPlan.valid:
    return false
  blaiApplyToolchainPsramSplitMetadataState(
    splitStartSlots, applyPlan.stateAfter)

proc blaiToolchainPsramRelationAppendInputDecision*(
    layerIndex, inputLayer: int32):
    BlaiToolchainPsramRelationAppendInputDecision =
  ## Recover whether one graph input becomes a relation-row append.
  if layerIndex <= 0:
    return

  result.layerIndex = layerIndex
  result.directPredecessorIndex = layerIndex - 1
  result.inputLayer = inputLayer
  result.skipDirectPredecessor =
    inputLayer == result.directPredecessorIndex
  result.appendRelation = not result.skipDirectPredecessor
  result.valid = true

proc blaiToolchainPsramRelationAppendEligibility*(
    layerTypeValue: int32,
    tfliteMode: bool): BlaiToolchainPsramRelationAppendEligibility =
  ## Recover whether a layer participates in relation-row append planning.
  result.layerTypeValue = layerTypeValue
  result.tfliteMode = tfliteMode
  result.tfliteEligible = tfliteMode
  result.routeTypeEligible =
    layerTypeValue == BlaiToolchainPsramRelationRouteType
  result.routeWTypeEligible =
    layerTypeValue == BlaiToolchainPsramRelationRouteWType
  result.eligibleLayer =
    result.tfliteEligible or result.routeTypeEligible or
      result.routeWTypeEligible
  result.valid = true

proc blaiToolchainPsramRelationAppendPlanInto*(
    layerIndex, layerTypeValue: int32,
    tfliteMode: bool,
    inputLayers: openArray[int32],
    relationRow: openArray[int32],
    relationCountBefore: uint32,
    outResult: var BlaiToolchainPsramRelationAppendPlan) =
  ## Recover one `PSRAM_allocate` non-linear input relation-row update.
  ##
  ## For TFLite graphs the converter applies this to every layer. For the
  ## Darknet path it applies only to raw toolchain layer types 0x09 and 0x0e.
  ## Inputs equal to the direct predecessor are skipped; other inputs append to
  ## the current layer's five-entry relation row.
  outResult = default(BlaiToolchainPsramRelationAppendPlan)
  outResult.layerIndex = layerIndex
  outResult.layerTypeValue = layerTypeValue
  outResult.tfliteMode = tfliteMode
  outResult.inputCount = blaiOpenArrayLenU32(inputLayers)
  outResult.relationCountBefore = relationCountBefore
  outResult.relationCountAfter = relationCountBefore
  let eligibility =
    blaiToolchainPsramRelationAppendEligibility(layerTypeValue, tfliteMode)
  outResult.eligibleLayer = eligibility.eligibleLayer
  if not outResult.eligibleLayer:
    outResult.firstBlock = blaiToolchainPsramRelationInactive
    return
  if layerIndex <= 0:
    outResult.firstBlock = blaiToolchainPsramRelationLayerIndex
    return
  outResult.directPredecessorIndex = layerIndex - 1
  if relationRow.len < BlaiToolchainPsramAllocateRelationSlotsInt:
    outResult.firstBlock = blaiToolchainPsramRelationStorage
    return
  if relationCountBefore > BlaiToolchainPsramAllocateRelationSlots:
    outResult.firstBlock = blaiToolchainPsramRelationCapacity
    return

  for relationIndex in 0'u32 ..< BlaiToolchainPsramAllocateRelationSlots:
    let cursor = blaiToolchainPsramRelationEntryCursor(relationIndex)
    if not cursor.valid:
      outResult.firstBlock = blaiToolchainPsramRelationStorage
      return
    outResult.relationValues[cursor.index] = relationRow[cursor.index]

  for inputIndex in 0'u32 ..< outResult.inputCount:
    let inputCursor =
      blaiToolchainPsramInputListCursor(inputIndex, inputLayers.len)
    if not inputCursor.valid:
      outResult.firstBlock = blaiToolchainPsramRelationStorage
      return
    let inputLayer = inputLayers[inputCursor.index]
    let inputDecision =
      blaiToolchainPsramRelationAppendInputDecision(layerIndex, inputLayer)
    if not inputDecision.valid:
      outResult.firstBlock = blaiToolchainPsramRelationLayerIndex
      return
    if inputDecision.skipDirectPredecessor:
      inc outResult.skippedDirectPredecessorCount
      continue
    if not inputDecision.appendRelation:
      continue
    if outResult.relationCountAfter >= BlaiToolchainPsramAllocateRelationSlots:
      outResult.firstBlock = blaiToolchainPsramRelationCapacity
      return
    let relationCursor =
      blaiToolchainPsramRelationEntryCursor(outResult.relationCountAfter)
    if not relationCursor.valid:
      outResult.firstBlock = blaiToolchainPsramRelationStorage
      return
    outResult.relationValues[relationCursor.index] = inputLayer
    inc outResult.relationCountAfter
    inc outResult.appendedCount

  outResult.firstBlock = blaiToolchainPsramRelationNoBlock
  outResult.valid = true

proc blaiToolchainPsramRelationAppendPlan*(
    layerIndex, layerTypeValue: int32,
    tfliteMode: bool,
    inputLayers: openArray[int32],
    relationRow: openArray[int32],
    relationCountBefore: uint32): BlaiToolchainPsramRelationAppendPlan =
  ## Convenience wrapper for one recovered relation-row update.
  blaiToolchainPsramRelationAppendPlanInto(
    layerIndex, layerTypeValue, tfliteMode, inputLayers, relationRow,
    relationCountBefore, result)

proc blaiToolchainPsramRelationAppendState*(
    layerIndex: int32,
    relationCountAfter: uint32,
    appendedCount: uint32,
    skippedDirectPredecessorCount: uint32,
    relationValues: array[BlaiToolchainPsramAllocateRelationSlotsInt, int32]):
    BlaiToolchainPsramRelationAppendState =
  ## Build a typed caller-owned relation append state.
  result.layerIndex = layerIndex
  result.relationCountAfter = relationCountAfter
  result.appendedCount = appendedCount
  result.skippedDirectPredecessorCount = skippedDirectPredecessorCount
  result.relationValues = relationValues

proc blaiToolchainPsramRelationAppendApplyPlanInto*(
    appendPlan: BlaiToolchainPsramRelationAppendPlan,
    outResult: var BlaiToolchainPsramRelationAppendApplyPlan) =
  ## Prepare checked application of relation-row append state.
  outResult = default(BlaiToolchainPsramRelationAppendApplyPlan)
  outResult.appendPlan = appendPlan
  if not appendPlan.valid:
    outResult.firstBlock = blaiToolchainPsramRelationAppendApplyAppendPlan
    return

  outResult.stateAfter = blaiToolchainPsramRelationAppendState(
    appendPlan.layerIndex, appendPlan.relationCountAfter,
    appendPlan.appendedCount, appendPlan.skippedDirectPredecessorCount,
    appendPlan.relationValues)
  outResult.firstBlock = blaiToolchainPsramRelationAppendApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramRelationAppendApplyPlan*(
    appendPlan: BlaiToolchainPsramRelationAppendPlan):
    BlaiToolchainPsramRelationAppendApplyPlan =
  ## Convenience wrapper for checked relation append state projection.
  blaiToolchainPsramRelationAppendApplyPlanInto(appendPlan, result)

proc blaiApplyToolchainPsramRelationAppendState*(
    state: var BlaiToolchainPsramRelationAppendState,
    plan: BlaiToolchainPsramRelationAppendApplyPlan): bool =
  ## Apply recovered relation-row append to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPsramRelationAppendRowState*(
    relationRow: var openArray[int32],
    relationCount: var uint32,
    state: BlaiToolchainPsramRelationAppendState): bool =
  ## Apply recovered relation-row append state to caller-owned row storage.
  if relationRow.len < BlaiToolchainPsramAllocateRelationSlotsInt:
    return false
  for relationIndex in 0'u32 ..< BlaiToolchainPsramAllocateRelationSlots:
    let cursor = blaiToolchainPsramRelationEntryCursor(relationIndex)
    if not cursor.valid:
      return false
    relationRow[cursor.index] = state.relationValues[cursor.index]
  relationCount = state.relationCountAfter
  true

proc blaiApplyToolchainPsramRelationAppendScalarState*(
    layerIndex: var int32,
    relationCountAfter, appendedCount: var uint32,
    skippedDirectPredecessorCount: var uint32,
    state: BlaiToolchainPsramRelationAppendState): bool =
  ## Apply recovered relation append metadata scalars from typed state.
  layerIndex = state.layerIndex
  relationCountAfter = state.relationCountAfter
  appendedCount = state.appendedCount
  skippedDirectPredecessorCount = state.skippedDirectPredecessorCount
  true

proc blaiApplyToolchainPsramRelationAppendScalars*(
    layerIndex: var int32,
    relationCountAfter, appendedCount: var uint32,
    skippedDirectPredecessorCount: var uint32,
    plan: BlaiToolchainPsramRelationAppendApplyPlan): bool =
  ## Apply recovered relation append metadata scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramRelationAppendScalarState(
    layerIndex, relationCountAfter, appendedCount,
    skippedDirectPredecessorCount, plan.stateAfter)

proc blaiApplyToolchainPsramRelationAppend*(
    relationRow: var openArray[int32],
    relationCount: var uint32,
    plan: BlaiToolchainPsramRelationAppendPlan): bool =
  ## Apply a checked `PSRAM_allocate` relation-row update.
  let applyPlan = blaiToolchainPsramRelationAppendApplyPlan(plan)
  if not applyPlan.valid:
    return false
  blaiApplyToolchainPsramRelationAppendRowState(
    relationRow, relationCount, applyPlan.stateAfter)

proc blaiToolchainPsramInputMembershipPlanInto*(
    layerIndex, inputCount: int32,
    inputLayers: openArray[int32],
    outResult: var BlaiToolchainPsramInputMembershipPlan) =
  ## Recover the counted input-layer membership scan in `PSRAM_allocate`.
  outResult = default(BlaiToolchainPsramInputMembershipPlan)
  outResult.layerIndex = layerIndex
  outResult.inputCount = inputCount
  outResult.inputStorageCount = blaiOpenArrayLenU32(inputLayers)
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramInputMembershipLayerIndex
    return
  if inputCount <= 0:
    outResult.firstBlock = blaiToolchainPsramInputMembershipNoBlock
    outResult.valid = true
    return
  let countField = blaiToolchainPsramInputCountAbi(inputCount)
  if not countField.valid:
    outResult.firstBlock = blaiToolchainPsramInputMembershipStorage
    return
  if countField.value > outResult.inputStorageCount:
    outResult.firstBlock = blaiToolchainPsramInputMembershipStorage
    return

  for inputIndex in 0'u32 ..< countField.value:
    let inputCursor =
      blaiToolchainPsramInputListCursor(inputIndex, inputLayers.len)
    if not inputCursor.valid:
      outResult.firstBlock = blaiToolchainPsramInputMembershipStorage
      return
    inc outResult.scannedEntries
    if not outResult.found and inputLayers[inputCursor.index] == layerIndex:
      outResult.found = true

  outResult.firstBlock = blaiToolchainPsramInputMembershipNoBlock
  outResult.valid = true

proc blaiToolchainPsramInputMembershipPlan*(
    layerIndex, inputCount: int32,
    inputLayers: openArray[int32]): BlaiToolchainPsramInputMembershipPlan =
  ## Convenience wrapper for recovered input-layer membership scanning.
  blaiToolchainPsramInputMembershipPlanInto(
    layerIndex, inputCount, inputLayers, result)

proc blaiToolchainPsramInputMembershipState*(
    layerIndex, inputCount: int32,
    scannedEntries: uint32,
    found: bool): BlaiToolchainPsramInputMembershipState =
  ## Build a typed caller-owned input-membership scan state.
  result.layerIndex = layerIndex
  result.inputCount = inputCount
  result.scannedEntries = scannedEntries
  result.found = found

proc blaiToolchainPsramInputMembershipApplyPlanInto*(
    membership: BlaiToolchainPsramInputMembershipPlan,
    outResult: var BlaiToolchainPsramInputMembershipApplyPlan) =
  ## Prepare checked application of input-membership scan state.
  outResult = default(BlaiToolchainPsramInputMembershipApplyPlan)
  outResult.membership = membership
  if not membership.valid:
    outResult.firstBlock =
      blaiToolchainPsramInputMembershipApplyMembershipPlan
    return

  outResult.stateAfter = blaiToolchainPsramInputMembershipState(
    membership.layerIndex, membership.inputCount,
    membership.scannedEntries, membership.found)
  outResult.firstBlock = blaiToolchainPsramInputMembershipApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramInputMembershipApplyPlan*(
    membership: BlaiToolchainPsramInputMembershipPlan):
    BlaiToolchainPsramInputMembershipApplyPlan =
  ## Convenience wrapper for checked input-membership scan projection.
  blaiToolchainPsramInputMembershipApplyPlanInto(membership, result)

proc blaiApplyToolchainPsramInputMembershipState*(
    state: var BlaiToolchainPsramInputMembershipState,
    plan: BlaiToolchainPsramInputMembershipApplyPlan): bool =
  ## Apply recovered input-membership scan to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPsramInputMembershipScalarState*(
    layerIndex, inputCount: var int32,
    scannedEntries: var uint32,
    found: var bool,
    state: BlaiToolchainPsramInputMembershipState): bool =
  ## Apply recovered input-membership scan metadata scalars from typed state.
  layerIndex = state.layerIndex
  inputCount = state.inputCount
  scannedEntries = state.scannedEntries
  found = state.found
  true

proc blaiApplyToolchainPsramInputMembershipScalars*(
    layerIndex, inputCount: var int32,
    scannedEntries: var uint32,
    found: var bool,
    plan: BlaiToolchainPsramInputMembershipApplyPlan): bool =
  ## Apply recovered input-membership scan metadata scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramInputMembershipScalarState(
    layerIndex, inputCount, scannedEntries, found, plan.stateAfter)

proc blaiToolchainPsramInputMembershipResumeSpan*(
    inputByteOffset, inputElementBytes: uint32):
    BlaiToolchainPsramInputMembershipResumeSpan =
  ## Recover the counted input-list scan span from a byte offset.
  if inputElementBytes == 0'u32:
    return
  if inputByteOffset mod inputElementBytes != 0'u32:
    return
  let lastEntryIndex = inputByteOffset div inputElementBytes
  if lastEntryIndex > high(uint32) - 1'u32:
    return
  let scannedEntries = lastEntryIndex + 1'u32
  if scannedEntries > (high(uint32) div inputElementBytes):
    return
  result.inputByteOffset = inputByteOffset
  result.inputElementBytes = inputElementBytes
  result.scannedEntries = scannedEntries
  result.scannedByteCount = scannedEntries * inputElementBytes
  result.valid = true

proc blaiToolchainPsramInputMembershipResumePlanInto*(
    returnFrame: BlaiToolchainSetWeiPatchReturnFramePlan,
    layerIndex, inputCount: int32,
    inputByteOffset: uint32,
    inputLayers: openArray[int32],
    outResult: var BlaiToolchainPsramInputMembershipResumePlan) =
  ## Recover the caller resume path after `set_wei_patch` returns.
  ##
  ## After the frame unwind, `PSRAM_allocate` gates on the copied input count.
  ## For positive counts it reloads the input-list base and byte offset from
  ## caller-frame slots, clears the found flag, and resumes at the shared
  ## membership loop. This plan expresses that as a checked count/byte range.
  outResult = default(BlaiToolchainPsramInputMembershipResumePlan)
  outResult.returnFrame = returnFrame
  outResult.layerIndex = layerIndex
  outResult.inputCount = inputCount
  outResult.inputByteOffset = inputByteOffset
  outResult.inputElementBytes = BlaiToolchainPsramInputListElementBytes
  outResult.inputBaseFrameOffset =
    BlaiToolchainPsramInputResumeBaseFrameOffset
  outResult.inputByteOffsetFrameOffset =
    BlaiToolchainPsramInputResumeByteOffsetFrameOffset
  outResult.endBiasBytes = BlaiToolchainPsramInputResumeEndBiasBytes
  if not returnFrame.valid:
    outResult.firstBlock =
      blaiToolchainPsramInputMembershipResumeReturnFrame
    return

  if inputCount <= 0:
    blaiToolchainPsramInputMembershipPlanInto(
      layerIndex, 0, inputLayers, outResult.membership)
    outResult.foundFlagCleared = true
    outResult.firstBlock = blaiToolchainPsramInputMembershipResumeNoBlock
    outResult.valid = outResult.membership.valid
    if not outResult.valid:
      outResult.firstBlock =
        blaiToolchainPsramInputMembershipResumeMembership
    return

  let resumeSpan =
    blaiToolchainPsramInputMembershipResumeSpan(
      inputByteOffset, outResult.inputElementBytes)
  if not resumeSpan.valid:
    outResult.firstBlock =
      blaiToolchainPsramInputMembershipResumeByteOffset
    return
  outResult.scannedByteCount = resumeSpan.scannedByteCount
  let countField = blaiToolchainPsramInputCountAbi(inputCount)
  if not countField.valid or resumeSpan.scannedEntries != countField.value:
    outResult.firstBlock =
      blaiToolchainPsramInputMembershipResumeByteOffset
    return

  blaiToolchainPsramInputMembershipPlanInto(
    layerIndex, inputCount, inputLayers, outResult.membership)
  if not outResult.membership.valid:
    outResult.firstBlock =
      blaiToolchainPsramInputMembershipResumeMembership
    return
  outResult.foundFlagCleared = true
  outResult.jumpsToMembershipLoop = true
  outResult.firstBlock = blaiToolchainPsramInputMembershipResumeNoBlock
  outResult.valid = true

proc blaiToolchainPsramInputMembershipResumePlan*(
    returnFrame: BlaiToolchainSetWeiPatchReturnFramePlan,
    layerIndex, inputCount: int32,
    inputByteOffset: uint32,
    inputLayers: openArray[int32]):
    BlaiToolchainPsramInputMembershipResumePlan =
  ## Convenience wrapper for post-`set_wei_patch` membership resume planning.
  blaiToolchainPsramInputMembershipResumePlanInto(
    returnFrame, layerIndex, inputCount, inputByteOffset, inputLayers, result)

proc blaiToolchainPsramInputMembershipResumeState*(
    layerIndex: int32,
    membershipFound, foundFlagCleared, jumpsToMembershipLoop: bool,
    scannedEntries: uint32): BlaiToolchainPsramInputMembershipResumeState =
  ## Build a typed caller-owned resumed membership state.
  result.layerIndex = layerIndex
  result.membershipFound = membershipFound
  result.foundFlagCleared = foundFlagCleared
  result.jumpsToMembershipLoop = jumpsToMembershipLoop
  result.scannedEntries = scannedEntries

proc blaiToolchainPsramInputMembershipResumeApplyPlanInto*(
    resume: BlaiToolchainPsramInputMembershipResumePlan,
    outResult: var BlaiToolchainPsramInputMembershipResumeApplyPlan) =
  ## Prepare checked application of the resumed membership-found flag.
  outResult = default(BlaiToolchainPsramInputMembershipResumeApplyPlan)
  outResult.resume = resume
  outResult.layerIndex = resume.layerIndex
  if not resume.valid:
    outResult.firstBlock =
      blaiToolchainPsramInputMembershipResumeApplyResumePlan
    return

  outResult.foundAfterResume = resume.membership.found
  outResult.foundFlagCleared = resume.foundFlagCleared
  outResult.jumpsToMembershipLoop = resume.jumpsToMembershipLoop
  outResult.scannedEntries = resume.membership.scannedEntries
  outResult.stateAfter = blaiToolchainPsramInputMembershipResumeState(
    resume.layerIndex, resume.membership.found, resume.foundFlagCleared,
    resume.jumpsToMembershipLoop, resume.membership.scannedEntries)
  outResult.firstBlock = blaiToolchainPsramInputMembershipResumeApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramInputMembershipResumeApplyPlan*(
    resume: BlaiToolchainPsramInputMembershipResumePlan):
    BlaiToolchainPsramInputMembershipResumeApplyPlan =
  ## Convenience wrapper for checked resumed membership projection.
  blaiToolchainPsramInputMembershipResumeApplyPlanInto(resume, result)

proc blaiApplyToolchainPsramInputMembershipResumeState*(
    state: var BlaiToolchainPsramInputMembershipResumeState,
    plan: BlaiToolchainPsramInputMembershipResumeApplyPlan): bool =
  ## Apply recovered resumed membership state to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPsramInputMembershipResumeScalarState*(
    membershipFound: var bool,
    state: BlaiToolchainPsramInputMembershipResumeState): bool =
  ## Apply recovered resumed membership flag state to caller-owned storage.
  membershipFound = state.membershipFound
  true

proc blaiApplyToolchainPsramInputMembershipResumeSummaryScalarState*(
    layerIndex: var int32,
    membershipFound, foundFlagCleared, jumpsToMembershipLoop: var bool,
    scannedEntries: var uint32,
    state: BlaiToolchainPsramInputMembershipResumeState): bool =
  ## Apply recovered resumed membership summary state to caller-owned storage.
  layerIndex = state.layerIndex
  membershipFound = state.membershipFound
  foundFlagCleared = state.foundFlagCleared
  jumpsToMembershipLoop = state.jumpsToMembershipLoop
  scannedEntries = state.scannedEntries
  true

proc blaiApplyToolchainPsramInputMembershipResumeSummaryScalars*(
    layerIndex: var int32,
    membershipFound, foundFlagCleared, jumpsToMembershipLoop: var bool,
    scannedEntries: var uint32,
    plan: BlaiToolchainPsramInputMembershipResumeApplyPlan): bool =
  ## Apply recovered resumed membership summary scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramInputMembershipResumeSummaryScalarState(
    layerIndex, membershipFound, foundFlagCleared, jumpsToMembershipLoop,
    scannedEntries, plan.stateAfter)

proc blaiApplyToolchainPsramInputMembershipResume*(
    membershipFound: var bool,
    plan: BlaiToolchainPsramInputMembershipResumeApplyPlan): bool =
  ## Apply the recovered resumed membership flag to caller-owned state.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramInputMembershipResumeScalarState(
    membershipFound, plan.stateAfter)

static:
  let staticInputMembershipResumePlan =
    BlaiToolchainPsramInputMembershipResumePlan(
      membership: BlaiToolchainPsramInputMembershipPlan(
        scannedEntries: 4'u32,
        found: true,
        valid: true),
      layerIndex: 3,
      foundFlagCleared: true,
      jumpsToMembershipLoop: true,
      valid: true)
  var staticInputMembershipResumeApplyPlanInto:
    BlaiToolchainPsramInputMembershipResumeApplyPlan
  blaiToolchainPsramInputMembershipResumeApplyPlanInto(
    staticInputMembershipResumePlan, staticInputMembershipResumeApplyPlanInto)
  let staticInputMembershipResumeApplyPlan =
    blaiToolchainPsramInputMembershipResumeApplyPlan(
      staticInputMembershipResumePlan)
  doAssert staticInputMembershipResumeApplyPlanInto ==
    staticInputMembershipResumeApplyPlan
  doAssert staticInputMembershipResumeApplyPlan.valid
  doAssert staticInputMembershipResumeApplyPlan.foundAfterResume
  doAssert staticInputMembershipResumeApplyPlan.foundFlagCleared
  doAssert staticInputMembershipResumeApplyPlan.jumpsToMembershipLoop
  doAssert staticInputMembershipResumeApplyPlan.scannedEntries == 4'u32
  doAssert staticInputMembershipResumeApplyPlan.stateAfter ==
    blaiToolchainPsramInputMembershipResumeState(
      3, true, true, true, 4'u32)
  var staticInputMembershipFound = false
  doAssert blaiApplyToolchainPsramInputMembershipResume(
    staticInputMembershipFound, staticInputMembershipResumeApplyPlan)
  doAssert staticInputMembershipFound
  var staticInputMembershipFoundFromState = false
  doAssert blaiApplyToolchainPsramInputMembershipResumeScalarState(
    staticInputMembershipFoundFromState,
    staticInputMembershipResumeApplyPlan.stateAfter)
  doAssert staticInputMembershipFoundFromState
  var staticInputMembershipResumeSummaryLayer = -1'i32
  var staticInputMembershipResumeSummaryFound = false
  var staticInputMembershipResumeSummaryCleared = false
  var staticInputMembershipResumeSummaryLoop = false
  var staticInputMembershipResumeSummaryScanned = 0'u32
  doAssert blaiApplyToolchainPsramInputMembershipResumeSummaryScalars(
    staticInputMembershipResumeSummaryLayer,
    staticInputMembershipResumeSummaryFound,
    staticInputMembershipResumeSummaryCleared,
    staticInputMembershipResumeSummaryLoop,
    staticInputMembershipResumeSummaryScanned,
    staticInputMembershipResumeApplyPlan)
  doAssert staticInputMembershipResumeSummaryLayer == 3'i32
  doAssert staticInputMembershipResumeSummaryFound
  doAssert staticInputMembershipResumeSummaryCleared
  doAssert staticInputMembershipResumeSummaryLoop
  doAssert staticInputMembershipResumeSummaryScanned == 4'u32
  staticInputMembershipResumeSummaryLayer = -1'i32
  staticInputMembershipResumeSummaryFound = false
  staticInputMembershipResumeSummaryCleared = false
  staticInputMembershipResumeSummaryLoop = false
  staticInputMembershipResumeSummaryScanned = 0'u32
  doAssert blaiApplyToolchainPsramInputMembershipResumeSummaryScalarState(
    staticInputMembershipResumeSummaryLayer,
    staticInputMembershipResumeSummaryFound,
    staticInputMembershipResumeSummaryCleared,
    staticInputMembershipResumeSummaryLoop,
    staticInputMembershipResumeSummaryScanned,
    staticInputMembershipResumeApplyPlan.stateAfter)
  doAssert staticInputMembershipResumeSummaryLayer == 3'i32
  doAssert staticInputMembershipResumeSummaryFound
  doAssert staticInputMembershipResumeSummaryCleared
  doAssert staticInputMembershipResumeSummaryLoop
  doAssert staticInputMembershipResumeSummaryScanned == 4'u32
  var staticInputMembershipResumeState =
    blaiToolchainPsramInputMembershipResumeState(
      -1, false, false, false, 0'u32)
  doAssert blaiApplyToolchainPsramInputMembershipResumeState(
    staticInputMembershipResumeState, staticInputMembershipResumeApplyPlan)
  doAssert staticInputMembershipResumeState ==
    blaiToolchainPsramInputMembershipResumeState(
      3, true, true, true, 4'u32)
  let staticInvalidInputMembershipResumeApplyPlan =
    blaiToolchainPsramInputMembershipResumeApplyPlan(
      default(BlaiToolchainPsramInputMembershipResumePlan))
  doAssert not staticInvalidInputMembershipResumeApplyPlan.valid
  doAssert staticInvalidInputMembershipResumeApplyPlan.firstBlock ==
    blaiToolchainPsramInputMembershipResumeApplyResumePlan
  var staticBlockedInputMembershipFound = true
  doAssert not blaiApplyToolchainPsramInputMembershipResume(
    staticBlockedInputMembershipFound,
    staticInvalidInputMembershipResumeApplyPlan)
  doAssert staticBlockedInputMembershipFound
  var staticBlockedInputMembershipResumeSummaryLayer = 9'i32
  var staticBlockedInputMembershipResumeSummaryFound = true
  var staticBlockedInputMembershipResumeSummaryCleared = true
  var staticBlockedInputMembershipResumeSummaryLoop = true
  var staticBlockedInputMembershipResumeSummaryScanned = 10'u32
  doAssert not blaiApplyToolchainPsramInputMembershipResumeSummaryScalars(
    staticBlockedInputMembershipResumeSummaryLayer,
    staticBlockedInputMembershipResumeSummaryFound,
    staticBlockedInputMembershipResumeSummaryCleared,
    staticBlockedInputMembershipResumeSummaryLoop,
    staticBlockedInputMembershipResumeSummaryScanned,
    staticInvalidInputMembershipResumeApplyPlan)
  doAssert staticBlockedInputMembershipResumeSummaryLayer == 9'i32
  doAssert staticBlockedInputMembershipResumeSummaryFound
  doAssert staticBlockedInputMembershipResumeSummaryCleared
  doAssert staticBlockedInputMembershipResumeSummaryLoop
  doAssert staticBlockedInputMembershipResumeSummaryScanned == 10'u32
  var staticBlockedInputMembershipResumeState =
    blaiToolchainPsramInputMembershipResumeState(
      9, true, true, true, 10'u32)
  doAssert not blaiApplyToolchainPsramInputMembershipResumeState(
    staticBlockedInputMembershipResumeState,
    staticInvalidInputMembershipResumeApplyPlan)
  doAssert staticBlockedInputMembershipResumeState ==
    blaiToolchainPsramInputMembershipResumeState(
      9, true, true, true, 10'u32)

proc blaiToolchainPsramInitialInputGatePlanInto*(
    layerIndex: int32,
    tfliteInputFlag: bool,
    copiedInputCount: int32,
    previousMembershipFound: bool,
    outResult: var BlaiToolchainPsramInitialInputGatePlan) =
  ## Recover the first-layer input-scan gate before the layer-type switch.
  ##
  ## Around `PSRAM_allocate+0x260`, the converter checks a recovered input
  ## flag and the current layer index. Only layer zero with the flag set and a
  ## positive copied input count enters the special input-scan setup; other
  ## non-zero layers continue to the main layer-type switch, while layer zero
  ## without the flag follows the separate first-layer path.
  outResult = default(BlaiToolchainPsramInitialInputGatePlan)
  outResult.layerIndex = layerIndex
  outResult.tfliteInputFlag = tfliteInputFlag
  outResult.copiedInputCount = copiedInputCount
  outResult.previousMembershipFound = previousMembershipFound
  outResult.inputFlagOffset = BlaiToolchainPsramInitialInputFlagOffset
  outResult.inputCountOffset = BlaiToolchainPsramInitialInputCountOffset
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramInitialInputGateLayerIndex
    return
  if copiedInputCount < 0:
    outResult.firstBlock = blaiToolchainPsramInitialInputGateCount
    return

  if not tfliteInputFlag and layerIndex == 0:
    outResult.action = blaiToolchainPsramInitialInputGateFirstLayerNoFlag
  elif layerIndex != 0:
    outResult.action = blaiToolchainPsramInitialInputGateLayerTypeSwitch
  elif copiedInputCount <= 0:
    outResult.action = blaiToolchainPsramInitialInputGateLayerTypeSwitch
  else:
    outResult.action = blaiToolchainPsramInitialInputGateScanInputs
    outResult.savedPreviousMembershipFound = previousMembershipFound
    outResult.initializesRelationScan = true
    outResult.resetsScanSentinel = true

  outResult.firstBlock = blaiToolchainPsramInitialInputGateNoBlock
  outResult.valid = true

proc blaiToolchainPsramInitialInputGatePlan*(
    layerIndex: int32,
    tfliteInputFlag: bool,
    copiedInputCount: int32,
    previousMembershipFound: bool):
    BlaiToolchainPsramInitialInputGatePlan =
  ## Convenience wrapper for recovered first-layer input-scan branch selection.
  blaiToolchainPsramInitialInputGatePlanInto(
    layerIndex, tfliteInputFlag, copiedInputCount, previousMembershipFound,
    result)

proc blaiToolchainPsramInitialInputGateState*(
    action: BlaiToolchainPsramInitialInputGateAction,
    savedPreviousMembershipFound: bool,
    initializesRelationScan: bool,
    scanSentinelAfter: int32): BlaiToolchainPsramInitialInputGateState =
  ## Build a typed caller-owned initial input gate state.
  result.action = action
  result.savedPreviousMembershipFound = savedPreviousMembershipFound
  result.initializesRelationScan = initializesRelationScan
  result.scanSentinelAfter = scanSentinelAfter

proc blaiToolchainPsramInitialInputGateApplyPlanInto*(
    gate: BlaiToolchainPsramInitialInputGatePlan,
    outResult: var BlaiToolchainPsramInitialInputGateApplyPlan) =
  ## Prepare checked application of initial input branch state.
  outResult = default(BlaiToolchainPsramInitialInputGateApplyPlan)
  outResult.gate = gate
  if not gate.valid:
    outResult.firstBlock = blaiToolchainPsramInitialInputGateApplyGatePlan
    return

  let scanSentinel =
    if gate.resetsScanSentinel:
      BlaiToolchainPsramInitialRelationSentinel
    else:
      0'i32
  outResult.stateAfter = blaiToolchainPsramInitialInputGateState(
    gate.action, gate.savedPreviousMembershipFound,
    gate.initializesRelationScan, scanSentinel)
  outResult.firstBlock = blaiToolchainPsramInitialInputGateApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramInitialInputGateApplyPlan*(
    gate: BlaiToolchainPsramInitialInputGatePlan):
    BlaiToolchainPsramInitialInputGateApplyPlan =
  ## Convenience wrapper for checked initial input gate application.
  blaiToolchainPsramInitialInputGateApplyPlanInto(gate, result)

proc blaiApplyToolchainPsramInitialInputGate*(
    state: var BlaiToolchainPsramInitialInputGateState,
    plan: BlaiToolchainPsramInitialInputGateApplyPlan): bool =
  ## Apply recovered initial input gate state to caller-owned storage.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPsramInitialInputGateScalarState*(
    savedPreviousMembershipFound: var bool,
    scanSentinel: var int32,
    state: BlaiToolchainPsramInitialInputGateState): bool =
  ## Apply recovered initial input gate scalar state to caller-owned storage.
  savedPreviousMembershipFound = state.savedPreviousMembershipFound
  if state.initializesRelationScan:
    scanSentinel = state.scanSentinelAfter
  true

proc blaiApplyToolchainPsramInitialInputGateSummaryScalarState*(
    action: var BlaiToolchainPsramInitialInputGateAction,
    savedPreviousMembershipFound, initializesRelationScan: var bool,
    scanSentinelAfter: var int32,
    state: BlaiToolchainPsramInitialInputGateState): bool =
  ## Apply recovered initial input gate summary scalars from typed state.
  action = state.action
  savedPreviousMembershipFound = state.savedPreviousMembershipFound
  initializesRelationScan = state.initializesRelationScan
  scanSentinelAfter = state.scanSentinelAfter
  true

proc blaiApplyToolchainPsramInitialInputGateSummaryScalars*(
    action: var BlaiToolchainPsramInitialInputGateAction,
    savedPreviousMembershipFound, initializesRelationScan: var bool,
    scanSentinelAfter: var int32,
    plan: BlaiToolchainPsramInitialInputGateApplyPlan): bool =
  ## Apply recovered initial input gate summary scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramInitialInputGateSummaryScalarState(
    action, savedPreviousMembershipFound, initializesRelationScan,
    scanSentinelAfter, plan.stateAfter)

proc blaiApplyToolchainPsramInitialInputGate*(
    savedPreviousMembershipFound: var bool,
    scanSentinel: var int32,
    plan: BlaiToolchainPsramInitialInputGateApplyPlan): bool =
  ## Apply recovered initial input gate scalar side effects.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramInitialInputGateScalarState(
    savedPreviousMembershipFound, scanSentinel, plan.stateAfter)

static:
  let staticInitialInputGate = BlaiToolchainPsramInitialInputGatePlan(
    layerIndex: 0,
    tfliteInputFlag: true,
    copiedInputCount: 2,
    previousMembershipFound: true,
    inputFlagOffset: BlaiToolchainPsramInitialInputFlagOffset,
    inputCountOffset: BlaiToolchainPsramInitialInputCountOffset,
    savedPreviousMembershipFound: true,
    initializesRelationScan: true,
    resetsScanSentinel: true,
    action: blaiToolchainPsramInitialInputGateScanInputs,
    firstBlock: blaiToolchainPsramInitialInputGateNoBlock,
    valid: true)
  var staticInitialInputGateApplyInto:
    BlaiToolchainPsramInitialInputGateApplyPlan
  blaiToolchainPsramInitialInputGateApplyPlanInto(
    staticInitialInputGate, staticInitialInputGateApplyInto)
  let staticInitialInputGateApply =
    blaiToolchainPsramInitialInputGateApplyPlan(staticInitialInputGate)
  doAssert staticInitialInputGateApplyInto == staticInitialInputGateApply
  doAssert staticInitialInputGateApply.valid
  doAssert staticInitialInputGateApply.stateAfter ==
    blaiToolchainPsramInitialInputGateState(
      blaiToolchainPsramInitialInputGateScanInputs, true, true,
      BlaiToolchainPsramInitialRelationSentinel)
  var staticInitialInputGateState =
    blaiToolchainPsramInitialInputGateState(
      blaiToolchainPsramInitialInputGateLayerTypeSwitch, false, false, 7)
  doAssert blaiApplyToolchainPsramInitialInputGate(
    staticInitialInputGateState, staticInitialInputGateApply)
  doAssert staticInitialInputGateState ==
    blaiToolchainPsramInitialInputGateState(
      blaiToolchainPsramInitialInputGateScanInputs, true, true,
      BlaiToolchainPsramInitialRelationSentinel)
  var staticInitialInputSavedMembership = false
  var staticInitialInputScanSentinel = 7'i32
  doAssert blaiApplyToolchainPsramInitialInputGate(
    staticInitialInputSavedMembership, staticInitialInputScanSentinel,
    staticInitialInputGateApply)
  doAssert staticInitialInputSavedMembership
  doAssert staticInitialInputScanSentinel ==
    BlaiToolchainPsramInitialRelationSentinel
  var staticInitialInputAction =
    blaiToolchainPsramInitialInputGateLayerTypeSwitch
  var staticInitialInputSummarySaved = false
  var staticInitialInputSummaryInitializes = false
  var staticInitialInputSummarySentinel = 7'i32
  doAssert blaiApplyToolchainPsramInitialInputGateSummaryScalarState(
    staticInitialInputAction, staticInitialInputSummarySaved,
    staticInitialInputSummaryInitializes, staticInitialInputSummarySentinel,
    staticInitialInputGateApply.stateAfter)
  doAssert staticInitialInputAction ==
    blaiToolchainPsramInitialInputGateScanInputs
  doAssert staticInitialInputSummarySaved
  doAssert staticInitialInputSummaryInitializes
  doAssert staticInitialInputSummarySentinel ==
    BlaiToolchainPsramInitialRelationSentinel
  staticInitialInputAction =
    blaiToolchainPsramInitialInputGateLayerTypeSwitch
  staticInitialInputSummarySaved = false
  staticInitialInputSummaryInitializes = false
  staticInitialInputSummarySentinel = 17
  doAssert blaiApplyToolchainPsramInitialInputGateSummaryScalars(
    staticInitialInputAction, staticInitialInputSummarySaved,
    staticInitialInputSummaryInitializes, staticInitialInputSummarySentinel,
    staticInitialInputGateApply)
  doAssert staticInitialInputAction ==
    blaiToolchainPsramInitialInputGateScanInputs
  doAssert staticInitialInputSummarySaved
  doAssert staticInitialInputSummaryInitializes
  doAssert staticInitialInputSummarySentinel ==
    BlaiToolchainPsramInitialRelationSentinel
  let staticSwitchInitialInputGate = BlaiToolchainPsramInitialInputGatePlan(
    layerIndex: 3,
    tfliteInputFlag: true,
    copiedInputCount: 2,
    action: blaiToolchainPsramInitialInputGateLayerTypeSwitch,
    firstBlock: blaiToolchainPsramInitialInputGateNoBlock,
    valid: true)
  let staticSwitchInitialInputGateApply =
    blaiToolchainPsramInitialInputGateApplyPlan(staticSwitchInitialInputGate)
  doAssert staticSwitchInitialInputGateApply.valid
  doAssert staticSwitchInitialInputGateApply.stateAfter ==
    blaiToolchainPsramInitialInputGateState(
      blaiToolchainPsramInitialInputGateLayerTypeSwitch, false, false, 0)
  var staticSwitchInputSavedMembership = true
  var staticSwitchInputScanSentinel = 9'i32
  doAssert blaiApplyToolchainPsramInitialInputGate(
    staticSwitchInputSavedMembership, staticSwitchInputScanSentinel,
    staticSwitchInitialInputGateApply)
  doAssert not staticSwitchInputSavedMembership
  doAssert staticSwitchInputScanSentinel == 9'i32
  doAssert blaiApplyToolchainPsramInitialInputGateSummaryScalars(
    staticInitialInputAction, staticInitialInputSummarySaved,
    staticInitialInputSummaryInitializes, staticInitialInputSummarySentinel,
    staticSwitchInitialInputGateApply)
  doAssert staticInitialInputAction ==
    blaiToolchainPsramInitialInputGateLayerTypeSwitch
  doAssert not staticInitialInputSummarySaved
  doAssert not staticInitialInputSummaryInitializes
  doAssert staticInitialInputSummarySentinel == 0
  let staticBlockedInitialInputGateApply =
    blaiToolchainPsramInitialInputGateApplyPlan(
      BlaiToolchainPsramInitialInputGatePlan(
        layerIndex: -1,
        tfliteInputFlag: true,
        copiedInputCount: 2,
        firstBlock: blaiToolchainPsramInitialInputGateLayerIndex,
        valid: false))
  doAssert not staticBlockedInitialInputGateApply.valid
  doAssert staticBlockedInitialInputGateApply.firstBlock ==
    blaiToolchainPsramInitialInputGateApplyGatePlan
  var staticBlockedInitialInputGateState =
    blaiToolchainPsramInitialInputGateState(
      blaiToolchainPsramInitialInputGateFirstLayerNoFlag, true, true, -3)
  doAssert not blaiApplyToolchainPsramInitialInputGate(
    staticBlockedInitialInputGateState, staticBlockedInitialInputGateApply)
  doAssert staticBlockedInitialInputGateState ==
    blaiToolchainPsramInitialInputGateState(
      blaiToolchainPsramInitialInputGateFirstLayerNoFlag, true, true, -3)
  var staticBlockedInputSavedMembership = true
  var staticBlockedInputScanSentinel = -4'i32
  doAssert not blaiApplyToolchainPsramInitialInputGate(
    staticBlockedInputSavedMembership, staticBlockedInputScanSentinel,
    staticBlockedInitialInputGateApply)
  doAssert staticBlockedInputSavedMembership
  doAssert staticBlockedInputScanSentinel == -4'i32
  doAssert not blaiApplyToolchainPsramInitialInputGateSummaryScalars(
    staticInitialInputAction, staticInitialInputSummarySaved,
    staticInitialInputSummaryInitializes, staticInitialInputSummarySentinel,
    staticBlockedInitialInputGateApply)
  doAssert staticInitialInputAction ==
    blaiToolchainPsramInitialInputGateLayerTypeSwitch
  doAssert not staticInitialInputSummarySaved
  doAssert not staticInitialInputSummaryInitializes
  doAssert staticInitialInputSummarySentinel == 0

proc blaiToolchainPsramInitialRelationScanPlanInto*(
    gate: BlaiToolchainPsramInitialInputGatePlan,
    layerCount: uint32,
    relationCounts: openArray[uint32],
    relationRows: openArray[array[BlaiToolchainPsramAllocateRelationSlotsInt, int32]],
    outResult: var BlaiToolchainPsramInitialRelationScanPlan) =
  ## Recover first-layer relation sentinel scanning after the input gate.
  ##
  ## The converter initializes the selected layer to `-1`, scans relation rows
  ## from the current layer through `layerCount`, compares bounded row entries
  ## with the `-1` sentinel, and keeps the last layer whose row contains it.
  outResult = default(BlaiToolchainPsramInitialRelationScanPlan)
  outResult.gate = gate
  outResult.layerIndex = gate.layerIndex
  outResult.layerCount = layerCount
  outResult.relationSentinel = BlaiToolchainPsramInitialRelationSentinel
  outResult.relationCountElementBytes =
    BlaiToolchainPsramRelationCountElementBytes
  outResult.relationRowStrideEntries =
    BlaiToolchainPsramAllocateRelationSlots
  outResult.relationRowStrideBytes =
    BlaiToolchainPsramRelationRowStrideBytes
  outResult.selectedLayerIndex = BlaiToolchainPsramInitialRelationSentinel
  if not gate.valid or
      gate.action != blaiToolchainPsramInitialInputGateScanInputs:
    outResult.firstBlock = blaiToolchainPsramInitialRelationScanGate
    return
  if gate.layerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramInitialRelationScanLayerIndex
    return
  let scanStartLayer = blaiToolchainPsramScanStartLayerAbi(gate.layerIndex)
  if not scanStartLayer.valid:
    outResult.firstBlock = blaiToolchainPsramInitialRelationScanLayerIndex
    return
  outResult.scanStartLayer = scanStartLayer.value
  if outResult.scanStartLayer >= layerCount:
    outResult.firstBlock = blaiToolchainPsramInitialRelationScanLayerIndex
    return
  if layerCount > blaiOpenArrayLenU32(relationCounts) or
      layerCount > blaiOpenArrayLenU32(relationRows):
    outResult.firstBlock = blaiToolchainPsramInitialRelationScanStorage
    return

  for scanLayer in outResult.scanStartLayer ..< layerCount:
    let countCursor = blaiToolchainPsramRelationCountCursor(
      scanLayer, relationCounts.len)
    let rowCursor = blaiToolchainPsramRelationRowCursor(
      scanLayer, relationRows.len)
    if not countCursor.valid or not rowCursor.valid:
      outResult.firstBlock = blaiToolchainPsramInitialRelationScanStorage
      return
    inc outResult.scannedRows
    let rowCount = relationCounts[countCursor.index]
    if rowCount > BlaiToolchainPsramAllocateRelationSlots:
      outResult.firstBlock = blaiToolchainPsramInitialRelationScanCapacity
      return
    if rowCount == 0:
      continue
    for relationIndex in 0'u32 ..< rowCount:
      let entryCursor =
        blaiToolchainPsramRelationEntryCursor(relationIndex)
      if not entryCursor.valid:
        outResult.firstBlock = blaiToolchainPsramInitialRelationScanStorage
        return
      inc outResult.scannedEntries
      if relationRows[rowCursor.index][entryCursor.index] ==
          outResult.relationSentinel:
        let selectedLayer = blaiToolchainPsramRelationLayerIndexAbi(scanLayer)
        if not selectedLayer.valid:
          outResult.firstBlock = blaiToolchainPsramInitialRelationScanLayerIndex
          return
        outResult.found = true
        inc outResult.matchCount
        outResult.selectedLayerIndex = selectedLayer.value

  outResult.firstBlock = blaiToolchainPsramInitialRelationScanNoBlock
  outResult.valid = true

proc blaiToolchainPsramInitialRelationScanPlan*(
    gate: BlaiToolchainPsramInitialInputGatePlan,
    layerCount: uint32,
    relationCounts: openArray[uint32],
    relationRows: openArray[array[BlaiToolchainPsramAllocateRelationSlotsInt, int32]]):
    BlaiToolchainPsramInitialRelationScanPlan =
  ## Convenience wrapper for recovered first-layer relation sentinel scanning.
  blaiToolchainPsramInitialRelationScanPlanInto(
    gate, layerCount, relationCounts, relationRows, result)

proc blaiToolchainPsramInitialRelationScanState*(
    layerIndex, selectedLayerIndex, relationSentinel: int32,
    scannedRows, scannedEntries, matchCount: uint32,
    found: bool): BlaiToolchainPsramInitialRelationScanState =
  ## Build a typed caller-owned initial relation scan state.
  result.layerIndex = layerIndex
  result.selectedLayerIndex = selectedLayerIndex
  result.relationSentinel = relationSentinel
  result.scannedRows = scannedRows
  result.scannedEntries = scannedEntries
  result.matchCount = matchCount
  result.found = found

proc blaiToolchainPsramInitialRelationScanApplyPlanInto*(
    scan: BlaiToolchainPsramInitialRelationScanPlan,
    outResult: var BlaiToolchainPsramInitialRelationScanApplyPlan) =
  ## Prepare checked application of initial relation scan state.
  outResult = default(BlaiToolchainPsramInitialRelationScanApplyPlan)
  outResult.scan = scan
  if not scan.valid:
    outResult.firstBlock =
      blaiToolchainPsramInitialRelationScanApplyScanPlan
    return

  outResult.stateAfter = blaiToolchainPsramInitialRelationScanState(
    scan.layerIndex, scan.selectedLayerIndex, scan.relationSentinel,
    scan.scannedRows, scan.scannedEntries, scan.matchCount, scan.found)
  outResult.firstBlock = blaiToolchainPsramInitialRelationScanApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramInitialRelationScanApplyPlan*(
    scan: BlaiToolchainPsramInitialRelationScanPlan):
    BlaiToolchainPsramInitialRelationScanApplyPlan =
  ## Convenience wrapper for checked initial relation scan projection.
  blaiToolchainPsramInitialRelationScanApplyPlanInto(scan, result)

proc blaiApplyToolchainPsramInitialRelationScanState*(
    state: var BlaiToolchainPsramInitialRelationScanState,
    plan: BlaiToolchainPsramInitialRelationScanApplyPlan): bool =
  ## Apply recovered initial relation scan to caller-owned state.
  if not plan.valid:
    return false
