proc blaiToolchainPsramInitialTfliteRequestPlanInto*(
    scan: BlaiToolchainPsramInitialRelationScanPlan,
    factorA, factorB, countToSelect, nextLayerTypeValue: int32,
    inheritedPreviousOwnerFlag: bool,
    outResult: var BlaiToolchainPsramInitialTfliteRequestPlan) =
  ## Recover selected-layer TFLite request setup after initial relation scan.
  ##
  ## After the initial scan, `PSRAM_allocate` addresses the selected layer with
  ## the recovered `0x978` stride, reads three scalar fields, forces counts 2/3
  ## through the existing TFLite request helper, and prepares the previous-owner
  ## flag from the next layer's raw type.
  outResult = default(BlaiToolchainPsramInitialTfliteRequestPlan)
  outResult.scan = scan
  outResult.selectedLayerIndex = scan.selectedLayerIndex
  outResult.factorAOffset = BlaiToolchainPsramInitialTfliteFactorAOffset
  outResult.factorBOffset = BlaiToolchainPsramInitialTfliteFactorBOffset
  outResult.countOffset = BlaiToolchainPsramInitialTfliteCountOffset
  outResult.factorA = factorA
  outResult.factorB = factorB
  outResult.countToSelect = countToSelect
  outResult.nextLayerTypeValue = nextLayerTypeValue
  if not scan.valid:
    outResult.firstBlock = blaiToolchainPsramInitialTfliteRequestScan
    return
  if scan.selectedLayerIndex < 0:
    outResult.firstBlock =
      blaiToolchainPsramInitialTfliteRequestSelectedLayer
    return

  blaiToolchainPsramTfliteRequestPlanInto(
    factorA, factorB, countToSelect, outResult.request)
  if not outResult.request.valid:
    outResult.firstBlock = blaiToolchainPsramInitialTfliteRequestRequest
    return
  blaiToolchainPatchPreviousOwnerPlanInto(
    nextLayerTypeValue, inheritedPreviousOwnerFlag, outResult.previousOwner)
  if not outResult.previousOwner.valid:
    outResult.firstBlock =
      blaiToolchainPsramInitialTfliteRequestPreviousOwner
    return

  outResult.requestedPatchCount = outResult.request.requestedPatchCount
  outResult.selectedPreviousOwnerFlag =
    outResult.previousOwner.selectedPreviousOwnerFlag
  outResult.firstBlock = blaiToolchainPsramInitialTfliteRequestNoBlock
  outResult.valid = true

proc blaiToolchainPsramInitialTfliteRequestPlan*(
    scan: BlaiToolchainPsramInitialRelationScanPlan,
    factorA, factorB, countToSelect, nextLayerTypeValue: int32,
    inheritedPreviousOwnerFlag: bool):
    BlaiToolchainPsramInitialTfliteRequestPlan =
  ## Convenience wrapper for selected-layer TFLite request setup.
  blaiToolchainPsramInitialTfliteRequestPlanInto(
    scan, factorA, factorB, countToSelect, nextLayerTypeValue,
    inheritedPreviousOwnerFlag, result)

proc blaiToolchainPsramInitialTfliteRequestState*(
    selectedLayerIndex: int32,
