    selectedCount: uint32,
    nextLayerTypeValue: int32,
    requestedPatchCount: uint32,
    selectedPreviousOwnerFlag: bool):
    BlaiToolchainPsramInitialTfliteRequestState =
  ## Build a typed caller-owned selected-layer TFLite request state.
  result.selectedLayerIndex = selectedLayerIndex
  result.factorAOffset = factorAOffset
  result.factorBOffset = factorBOffset
  result.countOffset = countOffset
  result.factorA = factorA
  result.factorB = factorB
  result.countToSelect = countToSelect
  result.selectedCount = selectedCount
  result.nextLayerTypeValue = nextLayerTypeValue
  result.requestedPatchCount = requestedPatchCount
  result.selectedPreviousOwnerFlag = selectedPreviousOwnerFlag

proc blaiToolchainPsramInitialTfliteRequestApplyPlanInto*(
    request: BlaiToolchainPsramInitialTfliteRequestPlan,
    outResult: var BlaiToolchainPsramInitialTfliteRequestApplyPlan) =
  ## Prepare checked application of selected-layer TFLite request state.
  outResult = default(BlaiToolchainPsramInitialTfliteRequestApplyPlan)
  outResult.request = request
  if not request.valid:
    outResult.firstBlock =
      blaiToolchainPsramInitialTfliteRequestApplyRequestPlan
    return

  outResult.stateAfter = blaiToolchainPsramInitialTfliteRequestState(
    request.selectedLayerIndex,
    request.factorAOffset, request.factorBOffset, request.countOffset,
    request.factorA, request.factorB, request.countToSelect,
    request.request.selectedCount, request.nextLayerTypeValue,
    request.requestedPatchCount, request.selectedPreviousOwnerFlag)
  outResult.firstBlock =
    blaiToolchainPsramInitialTfliteRequestApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramInitialTfliteRequestApplyPlan*(
