proc blaiToolchainPsramInitialTflitePatchPlanInto*(
    request: BlaiToolchainPsramInitialTfliteRequestPlan,
    debugLogFlag: bool,
    outResult: var BlaiToolchainPsramInitialTflitePatchPlan) =
  ## Compose the initial selected-layer request into TFLite patch dispatch.
  ##
  ## The initial TFLite branch uses the selected layer from the relation scan as
  ## both the patch-search current layer and the future-consumer owner source.
  ## This keeps that handoff typed before the existing `tflite_search_set_patch`
  ## dispatch plan consumes it.
  outResult = default(BlaiToolchainPsramInitialTflitePatchPlan)
  outResult.request = request
  outResult.debugLogFlag = debugLogFlag
  if not request.valid:
    outResult.firstBlock = blaiToolchainPsramInitialTflitePatchRequest
    return

  let prepare = BlaiToolchainPatchSearchCallPreparePlan(
    currentLayerIndex: request.selectedLayerIndex,
    layerCount: request.scan.layerCount,
    nextLayerTypeValue: request.nextLayerTypeValue,
    inheritedPreviousOwnerFlag: false,
    previousOwner: request.previousOwner,
    relationConsumerLayerIndex: request.scan.selectedLayerIndex,
    relationConsumerFound: request.scan.found,
    selectedPreviousOwnerFlag: request.selectedPreviousOwnerFlag,
    firstBlock: blaiToolchainPatchSearchCallPrepareNoBlock,
    valid: true)
  blaiToolchainPsramTflitePatchPlanInto(
    request.request, prepare, debugLogFlag, outResult.patch)
  if not outResult.patch.valid:
    outResult.firstBlock = blaiToolchainPsramInitialTflitePatchDispatch
    return

  outResult.selectedLayerIndex = request.selectedLayerIndex
  outResult.requestedPatchCount = request.requestedPatchCount
  outResult.relationConsumerLayerIndex =
    outResult.patch.relationConsumerLayerIndex
  outResult.relationConsumerFound = outResult.patch.relationConsumerFound
  outResult.selectedPreviousOwnerFlag =
    outResult.patch.selectedPreviousOwnerFlag
  outResult.tfliteSearchCall = outResult.patch.tfliteSearchCall
  outResult.metadataMode = outResult.patch.metadataMode
  outResult.owner = outResult.patch.owner
  outResult.firstBlock = blaiToolchainPsramInitialTflitePatchNoBlock
  outResult.valid = true

