proc blaiToolchainPsramInitialTfliteJoinRequestEvidence*(
    join: BlaiToolchainPsramInitialTfliteJoinPlan,
    factorA, factorB, countToSelect, nextLayerTypeValue: int32,
    inheritedPreviousOwnerFlag: bool):
    BlaiToolchainPsramInitialTfliteJoinRequestEvidence =
  ## Recover no-match join convergence into selected-layer request setup.
  ##
  ## The converter's no-match path clears relation-consumer scalars and then
  ## jumps into the same selected-layer request setup used after a relation
  ## match. This bridge represents that convergence without exposing stack
  ## temporaries or raw relation-table pointers.
  result.joinValid = join.valid
  result.factorA = factorA
  result.factorB = factorB
  result.countToSelect = countToSelect
  result.nextLayerTypeValue = nextLayerTypeValue
  if not join.valid:
    result.firstBlock = blaiToolchainPsramInitialTfliteJoinRequestJoin
    return

  result.syntheticScan = BlaiToolchainPsramInitialRelationScanPlan(
    gate: join.gate,
    layerIndex: join.selectedLayerIndex,
    layerCount: join.layerCount,
    selectedLayerIndex: join.selectedLayerIndex,
    found: join.relationConsumerFound,
    firstBlock: blaiToolchainPsramInitialRelationScanNoBlock,
    valid: true)
  blaiToolchainPsramInitialTfliteRequestPlanInto(
    result.syntheticScan, factorA, factorB, countToSelect, nextLayerTypeValue,
    inheritedPreviousOwnerFlag, result.request)
  result.requestValid = result.request.valid
  if not result.requestValid:
    result.firstBlock = blaiToolchainPsramInitialTfliteJoinRequestRequest
    return

  result.selectedLayerIndex = join.selectedLayerIndex
  result.relationConsumerLayerIndex = join.relationConsumerLayerIndex
  result.relationConsumerFound = join.relationConsumerFound
  result.requestedPatchCount = result.request.requestedPatchCount
  result.selectedPreviousOwnerFlag =
    result.request.selectedPreviousOwnerFlag
  result.firstBlock = blaiToolchainPsramInitialTfliteJoinRequestNoBlock
  result.valid = true

proc blaiToolchainPsramInitialTfliteJoinRequestPlanInto*(
    join: BlaiToolchainPsramInitialTfliteJoinPlan,
    factorA, factorB, countToSelect, nextLayerTypeValue: int32,
    inheritedPreviousOwnerFlag: bool,
    outResult: var BlaiToolchainPsramInitialTfliteJoinRequestPlan) =
  ## Compose a no-match TFLite join into selected-layer request setup.
  outResult = default(BlaiToolchainPsramInitialTfliteJoinRequestPlan)
  outResult.join = join
  let evidence = blaiToolchainPsramInitialTfliteJoinRequestEvidence(
    join, factorA, factorB, countToSelect, nextLayerTypeValue,
    inheritedPreviousOwnerFlag)
  outResult.evidence = evidence
  outResult.syntheticScan = evidence.syntheticScan
  outResult.request = evidence.request
  outResult.factorA = evidence.factorA
  outResult.factorB = evidence.factorB
  outResult.countToSelect = evidence.countToSelect
  outResult.nextLayerTypeValue = evidence.nextLayerTypeValue
  outResult.selectedLayerIndex = evidence.selectedLayerIndex
  outResult.relationConsumerLayerIndex =
    evidence.relationConsumerLayerIndex
  outResult.relationConsumerFound = evidence.relationConsumerFound
  outResult.requestedPatchCount = evidence.requestedPatchCount
  outResult.selectedPreviousOwnerFlag =
    evidence.selectedPreviousOwnerFlag
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

