proc blaiToolchainPsramInitialTfliteJoinRequestApplyEvidence*(
    request: BlaiToolchainPsramInitialTfliteJoinRequestPlan):
    BlaiToolchainPsramInitialTfliteJoinRequestApplyEvidence =
  ## Project a valid no-match join request into state and summary views.
  result.requestValid = request.valid
  if not request.valid:
    result.firstBlock =
      blaiToolchainPsramInitialTfliteJoinRequestApplyRequestPlan
    return

  result.stateAfter = blaiToolchainPsramInitialTfliteJoinRequestState(
    request.selectedLayerIndex, request.relationConsumerLayerIndex,
    request.relationConsumerFound,
    request.request.factorAOffset, request.request.factorBOffset,
    request.request.countOffset, request.factorA, request.factorB,
    request.countToSelect, request.request.request.selectedCount,
    request.nextLayerTypeValue, request.requestedPatchCount,
    request.selectedPreviousOwnerFlag, request.join.joinsRequestPath)
  result.summaryStateAfter =
    blaiToolchainPsramInitialTfliteJoinRequestSummaryState(
      request.selectedLayerIndex, request.relationConsumerLayerIndex,
      request.relationConsumerFound,
      request.request.factorAOffset, request.request.factorBOffset,
      request.request.countOffset, request.factorA, request.factorB,
      request.countToSelect, request.request.request.selectedCount,
      request.nextLayerTypeValue, request.requestedPatchCount,
      request.selectedPreviousOwnerFlag, request.join.joinsRequestPath)
  result.firstBlock =
    blaiToolchainPsramInitialTfliteJoinRequestApplyNoBlock
  result.valid = true

proc blaiToolchainPsramInitialTfliteJoinRequestApplyPlanInto*(
    request: BlaiToolchainPsramInitialTfliteJoinRequestPlan,
    outResult: var BlaiToolchainPsramInitialTfliteJoinRequestApplyPlan) =
  ## Prepare checked application of no-match join request state.
  outResult = default(BlaiToolchainPsramInitialTfliteJoinRequestApplyPlan)
  outResult.request = request
  let evidence =
    blaiToolchainPsramInitialTfliteJoinRequestApplyEvidence(request)
  outResult.evidence = evidence
  outResult.stateAfter = evidence.stateAfter
  outResult.summaryStateAfter = evidence.summaryStateAfter
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainPsramInitialTfliteJoinRequestApplyPlan*(
    request: BlaiToolchainPsramInitialTfliteJoinRequestPlan):
    BlaiToolchainPsramInitialTfliteJoinRequestApplyPlan =
  ## Convenience wrapper for checked no-match join request projection.
  blaiToolchainPsramInitialTfliteJoinRequestApplyPlanInto(request, result)

proc blaiApplyToolchainPsramInitialTfliteJoinRequestState*(
    state: var BlaiToolchainPsramInitialTfliteJoinRequestState,
    plan: BlaiToolchainPsramInitialTfliteJoinRequestApplyPlan): bool =
  ## Apply no-match join request setup to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

