proc blaiToolchainPsramRelationConsumerScanStart*(
    currentLayer, layerCount: uint32):
    BlaiToolchainPsramRelationConsumerScanStart =
  ## Resolve where the recovered future relation-consumer scan starts.
  if currentLayer >= layerCount:
    return
  if currentLayer == high(uint32):
    return
  result.currentLayer = currentLayer
  result.layerCount = layerCount
  result.firstFutureLayer = currentLayer + 1'u32
  result.hasFutureRows = result.firstFutureLayer < layerCount
  result.valid = true

proc blaiToolchainPsramRelationConsumerPlanInto*(
    layerIndex: int32,
    layerCount: uint32,
    relationCounts: openArray[uint32],
    relationRows: openArray[array[BlaiToolchainPsramAllocateRelationSlotsInt, int32]],
    outResult: var BlaiToolchainPsramRelationConsumerPlan) =
  ## Recover the `PSRAM_allocate` future relation-consumer scan.
  ##
  ## The converter scans relation rows after the current layer and records a
  ## downstream layer whenever that row contains the current layer index. It
  ## does not stop at the first match; the last matching future row remains in
  ## the value passed to the patch-search helper.
  outResult = default(BlaiToolchainPsramRelationConsumerPlan)
  outResult.layerIndex = layerIndex
  outResult.layerCount = layerCount
  outResult.consumerLayerIndex = -1
  if layerIndex < 0:
    outResult.firstBlock = blaiToolchainPsramRelationConsumerLayerIndex
    return
  let currentLayerIndex = blaiToolchainPsramScanStartLayerAbi(layerIndex)
  if not currentLayerIndex.valid:
    outResult.firstBlock = blaiToolchainPsramRelationConsumerLayerIndex
    return
  let currentLayer = currentLayerIndex.value
  if currentLayer >= layerCount:
    outResult.firstBlock = blaiToolchainPsramRelationConsumerLayerIndex
    return
  if layerCount > blaiOpenArrayLenU32(relationCounts) or
     layerCount > blaiOpenArrayLenU32(relationRows):
    outResult.firstBlock = blaiToolchainPsramRelationConsumerStorage
    return

  let scanStart =
    blaiToolchainPsramRelationConsumerScanStart(currentLayer, layerCount)
  if not scanStart.valid:
    outResult.firstBlock = blaiToolchainPsramRelationConsumerLayerIndex
    return
  if scanStart.hasFutureRows:
    for scanLayer in scanStart.firstFutureLayer ..< layerCount:
      let countCursor = blaiToolchainPsramRelationCountCursor(
        scanLayer, relationCounts.len)
      let rowCursor = blaiToolchainPsramRelationRowCursor(
        scanLayer, relationRows.len)
      if not countCursor.valid or not rowCursor.valid:
        outResult.firstBlock = blaiToolchainPsramRelationConsumerStorage
        return
      inc outResult.scannedRows
      let rowCount = relationCounts[countCursor.index]
      if rowCount > BlaiToolchainPsramAllocateRelationSlots:
        outResult.firstBlock = blaiToolchainPsramRelationConsumerCapacity
        return
      for relationIndex in 0'u32 ..< rowCount:
        let entryCursor =
          blaiToolchainPsramRelationEntryCursor(relationIndex)
        if not entryCursor.valid:
          outResult.firstBlock = blaiToolchainPsramRelationConsumerStorage
          return
        inc outResult.scannedEntries
        if relationRows[rowCursor.index][entryCursor.index] == layerIndex:
          let consumerLayer = blaiToolchainPsramRelationLayerIndexAbi(scanLayer)
          if not consumerLayer.valid:
            outResult.firstBlock = blaiToolchainPsramRelationConsumerLayerIndex
            return
          outResult.found = true
          outResult.consumerLayerIndex = consumerLayer.value
          inc outResult.matchCount

  outResult.firstBlock = blaiToolchainPsramRelationConsumerNoBlock
  outResult.valid = true

proc blaiToolchainPsramRelationConsumerPlan*(
    layerIndex: int32,
    layerCount: uint32,
    relationCounts: openArray[uint32],
    relationRows: openArray[array[BlaiToolchainPsramAllocateRelationSlotsInt, int32]]):
    BlaiToolchainPsramRelationConsumerPlan =
  ## Convenience wrapper for the recovered future relation-consumer scan.
  blaiToolchainPsramRelationConsumerPlanInto(
    layerIndex, layerCount, relationCounts, relationRows, result)

proc blaiToolchainPsramRelationConsumerState*(
    found: bool,
    consumerLayerIndex: int32): BlaiToolchainPsramRelationConsumerState =
  ## Build a typed caller-owned relation-consumer selection state.
  result.found = found
  result.consumerLayerIndex = consumerLayerIndex

proc blaiToolchainPsramRelationConsumerSummaryState*(
    layerIndex: int32,
    layerCount, scannedRows, scannedEntries, matchCount: uint32,
    consumerLayerIndex: int32,
    found: bool): BlaiToolchainPsramRelationConsumerSummaryState =
  ## Build a typed caller-owned relation-consumer scan summary state.
  result.layerIndex = layerIndex
  result.layerCount = layerCount
  result.scannedRows = scannedRows
  result.scannedEntries = scannedEntries
  result.matchCount = matchCount
  result.consumerLayerIndex = consumerLayerIndex
  result.found = found

proc blaiToolchainPsramRelationConsumerApplyPlanInto*(
    consumer: BlaiToolchainPsramRelationConsumerPlan,
    outResult: var BlaiToolchainPsramRelationConsumerApplyPlan) =
  ## Prepare checked application of relation-consumer scan state.
  outResult = default(BlaiToolchainPsramRelationConsumerApplyPlan)
  outResult.consumer = consumer
  if not consumer.valid:
    outResult.firstBlock = blaiToolchainPsramRelationConsumerApplyConsumerPlan
    return

  outResult.stateAfter = blaiToolchainPsramRelationConsumerState(
    consumer.found, consumer.consumerLayerIndex)
  outResult.summaryStateAfter = blaiToolchainPsramRelationConsumerSummaryState(
    consumer.layerIndex, consumer.layerCount, consumer.scannedRows,
    consumer.scannedEntries, consumer.matchCount, consumer.consumerLayerIndex,
    consumer.found)
  outResult.firstBlock = blaiToolchainPsramRelationConsumerApplyNoBlock
  outResult.valid = true

proc blaiToolchainPsramRelationConsumerApplyPlan*(
    consumer: BlaiToolchainPsramRelationConsumerPlan):
    BlaiToolchainPsramRelationConsumerApplyPlan =
  ## Convenience wrapper for checked relation-consumer scan application.
  blaiToolchainPsramRelationConsumerApplyPlanInto(consumer, result)

proc blaiApplyToolchainPsramRelationConsumerScalarState*(
    found: var bool,
    consumerLayerIndex: var int32,
    state: BlaiToolchainPsramRelationConsumerState): bool =
  ## Apply recovered relation-consumer scan scalars to caller-owned storage.
  found = state.found
  consumerLayerIndex = state.consumerLayerIndex
  true

proc blaiApplyToolchainPsramRelationConsumerSummaryScalarState*(
    layerIndex: var int32,
    layerCount, scannedRows, scannedEntries, matchCount: var uint32,
    consumerLayerIndex: var int32,
    found: var bool,
    state: BlaiToolchainPsramRelationConsumerSummaryState): bool =
  ## Apply recovered relation-consumer scan summary scalars.
  layerIndex = state.layerIndex
  layerCount = state.layerCount
  scannedRows = state.scannedRows
  scannedEntries = state.scannedEntries
  matchCount = state.matchCount
  consumerLayerIndex = state.consumerLayerIndex
  found = state.found
  true

proc blaiApplyToolchainPsramRelationConsumerSummaryScalars*(
    layerIndex: var int32,
    layerCount, scannedRows, scannedEntries, matchCount: var uint32,
    consumerLayerIndex: var int32,
    found: var bool,
    plan: BlaiToolchainPsramRelationConsumerApplyPlan): bool =
  ## Apply recovered relation-consumer scan summary scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramRelationConsumerSummaryScalarState(
    layerIndex, layerCount, scannedRows, scannedEntries, matchCount,
    consumerLayerIndex, found, plan.summaryStateAfter)

proc blaiApplyToolchainPsramRelationConsumer*(
    state: var BlaiToolchainPsramRelationConsumerState,
    plan: BlaiToolchainPsramRelationConsumerApplyPlan): bool =
  ## Apply recovered relation-consumer scan state to caller-owned storage.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainPsramRelationConsumer*(
    found: var bool,
    consumerLayerIndex: var int32,
    plan: BlaiToolchainPsramRelationConsumerApplyPlan): bool =
  ## Apply recovered relation-consumer scan scalars to caller-owned storage.
  if not plan.valid:
    return false
  blaiApplyToolchainPsramRelationConsumerScalarState(
    found, consumerLayerIndex, plan.stateAfter)

static:
  let staticRelationConsumer = BlaiToolchainPsramRelationConsumerPlan(
