  var staticRelationConsumerApplyInto:
    BlaiToolchainPsramRelationConsumerApplyPlan
  blaiToolchainPsramRelationConsumerApplyPlanInto(
    staticRelationConsumer, staticRelationConsumerApplyInto)
  let staticRelationConsumerApply =
    blaiToolchainPsramRelationConsumerApplyPlan(staticRelationConsumer)
  doAssert staticRelationConsumerApplyInto == staticRelationConsumerApply
  doAssert staticRelationConsumerApply.valid
  doAssert staticRelationConsumerApply.stateAfter ==
    blaiToolchainPsramRelationConsumerState(true, 4)
  doAssert staticRelationConsumerApply.summaryStateAfter ==
    blaiToolchainPsramRelationConsumerSummaryState(1, 5, 3, 4, 2, 4, true)
  var staticRelationConsumerState =
    blaiToolchainPsramRelationConsumerState(false, -1)
  doAssert blaiApplyToolchainPsramRelationConsumer(
    staticRelationConsumerState, staticRelationConsumerApply)
  doAssert staticRelationConsumerState ==
    blaiToolchainPsramRelationConsumerState(true, 4)
  var staticRelationConsumerFound = false
  var staticRelationConsumerLayer = -1'i32
  doAssert blaiApplyToolchainPsramRelationConsumer(
    staticRelationConsumerFound, staticRelationConsumerLayer,
    staticRelationConsumerApply)
  doAssert staticRelationConsumerFound
  doAssert staticRelationConsumerLayer == 4
  var staticRelationConsumerFoundFromState = false
  var staticRelationConsumerLayerFromState = -1'i32
  doAssert blaiApplyToolchainPsramRelationConsumerScalarState(
    staticRelationConsumerFoundFromState,
    staticRelationConsumerLayerFromState,
    staticRelationConsumerApply.stateAfter)
  doAssert staticRelationConsumerFoundFromState
  doAssert staticRelationConsumerLayerFromState == 4
  var staticRelationSummaryLayer = -1'i32
  var staticRelationSummaryLayerCount = 0'u32
  var staticRelationSummaryRows = 0'u32
  var staticRelationSummaryEntries = 0'u32
  var staticRelationSummaryMatches = 0'u32
  var staticRelationSummaryConsumer = -1'i32
  var staticRelationSummaryFound = false
  doAssert blaiApplyToolchainPsramRelationConsumerSummaryScalarState(
    staticRelationSummaryLayer, staticRelationSummaryLayerCount,
    staticRelationSummaryRows, staticRelationSummaryEntries,
    staticRelationSummaryMatches, staticRelationSummaryConsumer,
    staticRelationSummaryFound, staticRelationConsumerApply.summaryStateAfter)
  doAssert staticRelationSummaryLayer == 1
  doAssert staticRelationSummaryLayerCount == 5
  doAssert staticRelationSummaryRows == 3
  doAssert staticRelationSummaryEntries == 4
  doAssert staticRelationSummaryMatches == 2
  doAssert staticRelationSummaryConsumer == 4
  doAssert staticRelationSummaryFound
  staticRelationSummaryLayer = -9
  staticRelationSummaryLayerCount = 9
  staticRelationSummaryRows = 10
  staticRelationSummaryEntries = 11
  staticRelationSummaryMatches = 12
  staticRelationSummaryConsumer = -7
  staticRelationSummaryFound = false
  doAssert blaiApplyToolchainPsramRelationConsumerSummaryScalars(
    staticRelationSummaryLayer, staticRelationSummaryLayerCount,
    staticRelationSummaryRows, staticRelationSummaryEntries,
    staticRelationSummaryMatches, staticRelationSummaryConsumer,
    staticRelationSummaryFound, staticRelationConsumerApply)
  doAssert staticRelationSummaryLayer == 1
  doAssert staticRelationSummaryLayerCount == 5
  doAssert staticRelationSummaryRows == 3
  doAssert staticRelationSummaryEntries == 4
  doAssert staticRelationSummaryMatches == 2
  doAssert staticRelationSummaryConsumer == 4
  doAssert staticRelationSummaryFound
  let staticMissingRelationConsumer = BlaiToolchainPsramRelationConsumerPlan(
    layerIndex: 4,
    layerCount: 5,
    consumerLayerIndex: -1,
    found: false,
    firstBlock: blaiToolchainPsramRelationConsumerNoBlock,
    valid: true)
  let staticMissingRelationConsumerApply =
    blaiToolchainPsramRelationConsumerApplyPlan(staticMissingRelationConsumer)
  doAssert staticMissingRelationConsumerApply.valid
  doAssert staticMissingRelationConsumerApply.stateAfter ==
    blaiToolchainPsramRelationConsumerState(false, -1)
  doAssert staticMissingRelationConsumerApply.summaryStateAfter ==
    blaiToolchainPsramRelationConsumerSummaryState(4, 5, 0, 0, 0, -1, false)
  var staticMissingRelationConsumerState =
    blaiToolchainPsramRelationConsumerState(true, 7)
  doAssert blaiApplyToolchainPsramRelationConsumer(
    staticMissingRelationConsumerState, staticMissingRelationConsumerApply)
  doAssert staticMissingRelationConsumerState ==
    blaiToolchainPsramRelationConsumerState(false, -1)
  var staticMissingRelationConsumerFound = true
  var staticMissingRelationConsumerLayer = 7'i32
  doAssert blaiApplyToolchainPsramRelationConsumer(
    staticMissingRelationConsumerFound, staticMissingRelationConsumerLayer,
    staticMissingRelationConsumerApply)
  doAssert not staticMissingRelationConsumerFound
  doAssert staticMissingRelationConsumerLayer == -1
  doAssert blaiApplyToolchainPsramRelationConsumerSummaryScalars(
    staticRelationSummaryLayer, staticRelationSummaryLayerCount,
    staticRelationSummaryRows, staticRelationSummaryEntries,
    staticRelationSummaryMatches, staticRelationSummaryConsumer,
    staticRelationSummaryFound, staticMissingRelationConsumerApply)
  doAssert staticRelationSummaryLayer == 4
  doAssert staticRelationSummaryLayerCount == 5
  doAssert staticRelationSummaryRows == 0
  doAssert staticRelationSummaryEntries == 0
  doAssert staticRelationSummaryMatches == 0
  doAssert staticRelationSummaryConsumer == -1
  doAssert not staticRelationSummaryFound
  let staticBlockedRelationConsumerApply =
    blaiToolchainPsramRelationConsumerApplyPlan(
      BlaiToolchainPsramRelationConsumerPlan(
        layerIndex: -1,
        layerCount: 5,
        consumerLayerIndex: -1,
        firstBlock: blaiToolchainPsramRelationConsumerLayerIndex,
        valid: false))
  doAssert not staticBlockedRelationConsumerApply.valid
  doAssert staticBlockedRelationConsumerApply.firstBlock ==
    blaiToolchainPsramRelationConsumerApplyConsumerPlan
  var staticBlockedRelationConsumerState =
    blaiToolchainPsramRelationConsumerState(true, 9)
  doAssert not blaiApplyToolchainPsramRelationConsumer(
    staticBlockedRelationConsumerState, staticBlockedRelationConsumerApply)
  doAssert staticBlockedRelationConsumerState ==
    blaiToolchainPsramRelationConsumerState(true, 9)
  doAssert not blaiApplyToolchainPsramRelationConsumerSummaryScalars(
    staticRelationSummaryLayer, staticRelationSummaryLayerCount,
    staticRelationSummaryRows, staticRelationSummaryEntries,
    staticRelationSummaryMatches, staticRelationSummaryConsumer,
    staticRelationSummaryFound, staticBlockedRelationConsumerApply)
  doAssert staticRelationSummaryLayer == 4
  doAssert staticRelationSummaryLayerCount == 5
  doAssert staticRelationSummaryRows == 0
  doAssert staticRelationSummaryEntries == 0
  doAssert staticRelationSummaryMatches == 0
  doAssert staticRelationSummaryConsumer == -1
  doAssert not staticRelationSummaryFound
  var staticBlockedRelationConsumerFound = true
  var staticBlockedRelationConsumerLayer = 9'i32
  doAssert not blaiApplyToolchainPsramRelationConsumer(
    staticBlockedRelationConsumerFound, staticBlockedRelationConsumerLayer,
    staticBlockedRelationConsumerApply)
  doAssert staticBlockedRelationConsumerFound
  doAssert staticBlockedRelationConsumerLayer == 9

proc blaiToolchainPatchSearchCallPreparePlanInto*(
    currentLayerIndex: int32,
    layerCount: uint32,
    relationCounts: openArray[uint32],
    relationRows: openArray[array[BlaiToolchainPsramAllocateRelationSlotsInt, int32]],
    nextLayerTypeValue: int32,
    inheritedPreviousOwnerFlag: bool,
    outResult: var BlaiToolchainPatchSearchCallPreparePlan) =
  ## Recover repeated scalar preparation before `search_set_patch`.
  ##
  ## The `PSRAM_allocate` callsites first scan future relation rows for the
  ## current layer, then OR the inherited previous-owner flag with the raw next
  ## layer type check for `0x1b`. These three scalars are passed directly into
  ## `search_set_patch`.
  outResult = default(BlaiToolchainPatchSearchCallPreparePlan)
  outResult.currentLayerIndex = currentLayerIndex
  outResult.layerCount = layerCount
  outResult.nextLayerTypeValue = nextLayerTypeValue
  outResult.inheritedPreviousOwnerFlag = inheritedPreviousOwnerFlag
  blaiToolchainPsramRelationConsumerPlanInto(
    currentLayerIndex, layerCount, relationCounts, relationRows,
    outResult.relationConsumer)
  if not outResult.relationConsumer.valid:
    outResult.firstBlock = blaiToolchainPatchSearchCallPrepareRelationConsumer
    return

  blaiToolchainPatchPreviousOwnerPlanInto(
    nextLayerTypeValue, inheritedPreviousOwnerFlag, outResult.previousOwner)
  outResult.relationConsumerLayerIndex =
    outResult.relationConsumer.consumerLayerIndex
  outResult.relationConsumerFound = outResult.relationConsumer.found
  outResult.selectedPreviousOwnerFlag =
    outResult.previousOwner.selectedPreviousOwnerFlag
  outResult.firstBlock = blaiToolchainPatchSearchCallPrepareNoBlock
  outResult.valid = true

proc blaiToolchainPatchSearchCallPreparePlan*(
    currentLayerIndex: int32,
    layerCount: uint32,
    relationCounts: openArray[uint32],
    relationRows: openArray[array[BlaiToolchainPsramAllocateRelationSlotsInt, int32]],
    nextLayerTypeValue: int32,
    inheritedPreviousOwnerFlag: bool):
    BlaiToolchainPatchSearchCallPreparePlan =
  ## Convenience wrapper for recovered `search_set_patch` scalar preparation.
  blaiToolchainPatchSearchCallPreparePlanInto(
    currentLayerIndex, layerCount, relationCounts, relationRows,
    nextLayerTypeValue, inheritedPreviousOwnerFlag, result)

proc blaiToolchainSetWeiPatchRouteGateEvidence*(layerIndex,
    currentLayerTypeValue, sourceLayerTypeValue, previousLayerTypeValue,
    previousInputCount, currentFieldA, currentFieldB: int32):
    BlaiToolchainSetWeiPatchRouteGateEvidence =
  ## Recover the route-family prologue predicates.
  result.layerIndex = layerIndex
  result.currentLayerTypeValue = currentLayerTypeValue
  result.sourceLayerTypeValue = sourceLayerTypeValue
  result.previousLayerTypeValue = previousLayerTypeValue
  result.previousInputCount = previousInputCount
  result.currentFieldA = currentFieldA
  result.currentFieldB = currentFieldB
  result.previousLayerPresent = layerIndex > 0
  result.currentIsRawRoute =
    currentLayerTypeValue == BlaiToolchainPsramOwnerRouteType
  result.previousConvMultiInput =
    result.previousLayerPresent and
      previousInputCount >
        BlaiToolchainSetWeiPatchRouteGateMultiInputThreshold and
      previousLayerTypeValue == BlaiToolchainPsramOwnerConvType
  result.currentFieldsRequestRoute =
    result.currentIsRawRoute and
      (currentFieldA != BlaiToolchainSetWeiPatchRouteGateFieldValue or
        currentFieldB != BlaiToolchainSetWeiPatchRouteGateFieldValue)
  result.sourceLayerRequestsRoute =
    sourceLayerTypeValue == BlaiToolchainPsramOwnerRouteType
  result.routeFamilyPath =
    result.currentIsRawRoute and (
      result.previousConvMultiInput or
      result.currentFieldsRequestRoute or
      result.sourceLayerRequestsRoute)
  result.valid = true

proc blaiToolchainSetWeiPatchRouteGatePlanInto*(layerIndex,
    currentLayerTypeValue, sourceLayerTypeValue, previousLayerTypeValue,
    previousInputCount, currentFieldA, currentFieldB: int32,
    outResult: var BlaiToolchainSetWeiPatchRouteGatePlan) =
  ## Recover the raw route prologue gate near `set_wei_patch+0x5b`.
  ##
  ## The converter enters the route-family path for current raw type `0x03`
  ## when either the previous/source layer evidence requests it or the current
  ## layer's recovered field pair is not both the recovered route-gate field
  ## value. Field names remain under recovery, so this keeps the copied scalars
  ## explicit.
  outResult = default(BlaiToolchainSetWeiPatchRouteGatePlan)
  outResult.layerIndex = layerIndex
  outResult.currentLayerTypeValue = currentLayerTypeValue
  outResult.sourceLayerTypeValue = sourceLayerTypeValue
  outResult.previousLayerTypeValue = previousLayerTypeValue
  outResult.previousInputCount = previousInputCount
  outResult.currentFieldA = currentFieldA
  outResult.currentFieldB = currentFieldB
  if layerIndex < 0 or previousInputCount < 0:
    outResult.firstBlock = blaiToolchainSetWeiPatchRouteGateShape
    return

  let evidence =
    blaiToolchainSetWeiPatchRouteGateEvidence(
      layerIndex, currentLayerTypeValue, sourceLayerTypeValue,
      previousLayerTypeValue, previousInputCount, currentFieldA, currentFieldB)
  outResult.previousLayerPresent = evidence.previousLayerPresent
  outResult.currentIsRawRoute = evidence.currentIsRawRoute
  outResult.previousConvMultiInput = evidence.previousConvMultiInput
  outResult.currentFieldsRequestRoute = evidence.currentFieldsRequestRoute
  outResult.sourceLayerRequestsRoute = evidence.sourceLayerRequestsRoute
  outResult.routeFamilyPath = evidence.routeFamilyPath
  outResult.firstBlock = blaiToolchainSetWeiPatchRouteGateNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchRouteGatePlan*(layerIndex,
    currentLayerTypeValue, sourceLayerTypeValue, previousLayerTypeValue,
    previousInputCount, currentFieldA, currentFieldB: int32):
    BlaiToolchainSetWeiPatchRouteGatePlan =
  ## Convenience wrapper for recovered route-family prologue classification.
  blaiToolchainSetWeiPatchRouteGatePlanInto(
    layerIndex, currentLayerTypeValue, sourceLayerTypeValue,
    previousLayerTypeValue, previousInputCount, currentFieldA, currentFieldB,
    result)

proc blaiToolchainSetWeiPatchRouteSourceSelection*(
    layerTypeValue, sourceLayerTypeValue: int32):
    BlaiToolchainSetWeiPatchRouteSourceSelection =
  ## Recover which copied count feeds route-family page planning.
  result.layerTypeValue = layerTypeValue
  result.sourceLayerTypeValue = sourceLayerTypeValue
  result.routeFamily =
    layerTypeValue == BlaiToolchainPsramRelationRouteType or
      layerTypeValue == BlaiToolchainSetWeiPatchRouteMaxType
  result.routeMax = layerTypeValue == BlaiToolchainSetWeiPatchRouteMaxType
  result.routeMaxUsesRouteCount =
    result.routeMax and
      sourceLayerTypeValue == BlaiToolchainPsramRelationRouteType
  result.useRouteCount =
    layerTypeValue == BlaiToolchainPsramRelationRouteType or
      result.routeMaxUsesRouteCount
  result.valid = true

proc blaiToolchainSetWeiPatchRouteSourcePlanInto*(layerTypeValue,
    sourceLayerTypeValue, mainCount, routeCount, routeNumerator: int32,
    outResult: var BlaiToolchainSetWeiPatchRouteSourcePlan) =
  ## Recover route-family scalar selection near `set_wei_patch+0xcba`.
  ##
  ## Raw route type `0x09` always takes the copied route count. Raw type
  ## `0x37` takes that route count only when the selected source layer is also
  ## raw `0x09`; otherwise it keeps the copied main count. The selected
  ## numerator is the recovered route-family numerator in both cases.
  outResult = default(BlaiToolchainSetWeiPatchRouteSourcePlan)
  outResult.layerTypeValue = layerTypeValue
  outResult.sourceLayerTypeValue = sourceLayerTypeValue
  let selection =
    blaiToolchainSetWeiPatchRouteSourceSelection(
      layerTypeValue, sourceLayerTypeValue)
  outResult.routeFamily = selection.routeFamily
  outResult.routeMax = selection.routeMax
  if not outResult.routeFamily:
    outResult.firstBlock = blaiToolchainSetWeiPatchRouteSourceLayerType
    return
  if mainCount < 0 or routeCount < 0 or routeNumerator < 0:
    outResult.firstBlock = blaiToolchainSetWeiPatchRouteSourceShape
    return

  let mainCountField =
    blaiToolchainSetWeiPatchRouteSourceScalarAbi(mainCount)
  let routeCountField =
    blaiToolchainSetWeiPatchRouteSourceScalarAbi(routeCount)
  let routeNumeratorField =
    blaiToolchainSetWeiPatchRouteSourceScalarAbi(routeNumerator)
  if not mainCountField.valid or not routeCountField.valid or
      not routeNumeratorField.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchRouteSourceShape
    return

  outResult.mainCount = mainCountField.value
  outResult.routeCount = routeCountField.value
  outResult.routeNumerator = routeNumeratorField.value
  outResult.routeMaxUsesRouteCount =
    selection.routeMaxUsesRouteCount
  outResult.selectedCount =
    if selection.useRouteCount:
      outResult.routeCount
    else:
      outResult.mainCount
  outResult.selectedNumerator = outResult.routeNumerator
  outResult.firstBlock = blaiToolchainSetWeiPatchRouteSourceNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchRouteSourcePlan*(layerTypeValue,
    sourceLayerTypeValue, mainCount, routeCount, routeNumerator: int32):
    BlaiToolchainSetWeiPatchRouteSourcePlan =
  ## Convenience wrapper for recovered route-family scalar selection.
  blaiToolchainSetWeiPatchRouteSourcePlanInto(
    layerTypeValue, sourceLayerTypeValue, mainCount, routeCount,
    routeNumerator, result)

proc blaiToolchainSetWeiPatchPagePlanInto*(
    layerType: BlaiLayerType,
    countToAlign, primaryMultiplier, auxiliaryMultiplier: uint32,
    outResult: var BlaiToolchainSetWeiPatchPagePlan) =
  ## Recover the page-count setup at the start of toolchain `set_wei_patch`.
  outResult = default(BlaiToolchainSetWeiPatchPagePlan)
  outResult.layerType = layerType
  outResult.primaryMultiplier = primaryMultiplier
  outResult.auxiliaryMultiplier = auxiliaryMultiplier
  outResult.patchPageBytes = BlaiNpuLocalBufferBytes
  outResult.routeWDoublePrimary = layerType == blaiRouteW
  if outResult.patchPageBytes == 0'u32:
    outResult.firstBlock = blaiToolchainSetWeiPatchPagePatchSize
    return
  if countToAlign > high(uint32) - 3'u32:
    outResult.firstBlock = blaiToolchainSetWeiPatchPageOverflow
    return
  outResult.alignedCount = blaiAlign4(countToAlign)

  var primaryBytes64 = outResult.alignedCount.uint64 * primaryMultiplier.uint64
  if outResult.routeWDoublePrimary:
    primaryBytes64 = primaryBytes64 * 2'u64
  let auxiliaryBytes64 =
    if layerType == blaiConvolutional:
      0'u64
    else:
      outResult.alignedCount.uint64 * auxiliaryMultiplier.uint64
  if not blaiU64ExactU32Count(primaryBytes64, outResult.primaryBytes) or
     not blaiU64ExactU32Count(auxiliaryBytes64, outResult.auxiliaryBytes):
    outResult.firstBlock = blaiToolchainSetWeiPatchPageOverflow
    return

  outResult.primaryPages =
    blaiCeilDivU32(outResult.primaryBytes, outResult.patchPageBytes)
  outResult.auxiliaryPages =
    blaiCeilDivU32(outResult.auxiliaryBytes, outResult.patchPageBytes)
  outResult.selectedStartPatchCount =
    min(outResult.primaryPages, outResult.auxiliaryPages)
  outResult.firstBlock = blaiToolchainSetWeiPatchPageNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchPagePlan*(
    layerType: BlaiLayerType,
    countToAlign, primaryMultiplier, auxiliaryMultiplier: uint32):
    BlaiToolchainSetWeiPatchPagePlan =
  ## Convenience wrapper for recovered `set_wei_patch` page-pressure setup.
  blaiToolchainSetWeiPatchPagePlanInto(
    layerType, countToAlign, primaryMultiplier, auxiliaryMultiplier, result)

proc blaiToolchainRoundEvenSplit(value: uint32): uint32 =
  ## Recovered `set_wei_patch` split rounding: odd positive counts grow by one.
  if (value and 1'u32) == 1'u32:
    if value == high(uint32):
      high(uint32)
    else:
      value + 1'u32
  else:
    value

proc blaiToolchainSetWeiPatchBaseOffsetEvidence*(layerTypeValue,
    recoveredCount, recoveredField: int32):
    BlaiToolchainSetWeiPatchBaseOffsetEvidence =
  ## Recover the raw `set_wei_patch` base-offset selector predicates.
  result.layerTypeValue = layerTypeValue
  result.recoveredCount = recoveredCount
  result.recoveredField = recoveredField
  result.mask = BlaiToolchainSetWeiPatchBaseOffsetMask
  let maskShift = blaiToolchainSetWeiPatchLayerMaskShiftAbi(
    layerTypeValue, BlaiToolchainSetWeiPatchBaseOffsetMaskMaxType)
  result.layerTypeInMaskRange = maskShift.valid
  if maskShift.valid:
    result.layerMaskBitSet =
      ((result.mask shr maskShift.value) and 1'u64) == 1'u64
  result.recoveredCountHigh =
    recoveredCount > BlaiToolchainSetWeiPatchBaseOffsetCountThreshold
  result.recoveredFieldHigh =
    recoveredField > BlaiToolchainSetWeiPatchBaseOffsetFieldThreshold
  result.basePatchOffset =
    if result.layerMaskBitSet:
      BlaiToolchainSetWeiPatchBaseOffsetMaskedValue
    elif result.recoveredCountHigh or result.recoveredFieldHigh:
      BlaiToolchainSetWeiPatchBaseOffsetHighValue
    else:
      BlaiToolchainSetWeiPatchBaseOffsetLowValue
  result.valid = true

proc blaiToolchainSetWeiPatchBaseOffsetPlanInto*(layerTypeValue,
    recoveredCount, recoveredField: int32,
    outResult: var BlaiToolchainSetWeiPatchBaseOffsetPlan) =
  ## Recover `set_wei_patch` base offset for divisor split fitting.
  ##
  ## The converter uses base offset `0` for raw types present in mask
  ## `0x4000004200` within range `<= 0x26`. Otherwise it uses the high offset
  ## when a recovered count or another recovered field exceeds its recovered
  ## threshold, and the low offset for the remaining fall-through.
  outResult = default(BlaiToolchainSetWeiPatchBaseOffsetPlan)
  outResult.layerTypeValue = layerTypeValue
  outResult.recoveredCount = recoveredCount
  outResult.recoveredField = recoveredField
  let evidence = blaiToolchainSetWeiPatchBaseOffsetEvidence(
    layerTypeValue, recoveredCount, recoveredField)
  outResult.mask = evidence.mask
  outResult.layerTypeInMaskRange = evidence.layerTypeInMaskRange
  outResult.layerMaskBitSet = evidence.layerMaskBitSet
  outResult.recoveredCountHigh = evidence.recoveredCountHigh
  outResult.recoveredFieldHigh = evidence.recoveredFieldHigh
  outResult.basePatchOffset = evidence.basePatchOffset
  outResult.firstBlock = blaiToolchainSetWeiPatchBaseOffsetNoBlock
  outResult.valid = evidence.valid

proc blaiToolchainSetWeiPatchBaseOffsetPlan*(layerTypeValue,
    recoveredCount, recoveredField: int32): BlaiToolchainSetWeiPatchBaseOffsetPlan =
  ## Convenience wrapper for recovered divisor base-offset selection.
  blaiToolchainSetWeiPatchBaseOffsetPlanInto(
    layerTypeValue, recoveredCount, recoveredField, result)

proc blaiToolchainSetWeiPatchDivisorPlanInto*(
    pagePlan: BlaiToolchainSetWeiPatchPagePlan,
    layerTypeValue: int32,
    primaryNumerator, auxiliaryNumerator: uint32,
    primaryLocalFactor, auxiliaryLocalFactor: uint32,
    basePatchOffset: uint32,
    outResult: var BlaiToolchainSetWeiPatchDivisorPlan) =
  ## Recover the bounded divisor search after toolchain `set_wei_patch` pages.
  outResult = default(BlaiToolchainSetWeiPatchDivisorPlan)
  outResult.layerTypeValue = layerTypeValue
  outResult.startPatchCount = pagePlan.selectedStartPatchCount
  outResult.maxCandidateCount = BlaiMemAllocSearchSlack
  outResult.basePatchOffset = basePatchOffset
  outResult.primaryNumerator = primaryNumerator
  outResult.auxiliaryNumerator = auxiliaryNumerator
  outResult.primaryLocalFactor = primaryLocalFactor
  outResult.auxiliaryLocalFactor = auxiliaryLocalFactor
  outResult.specialDoubleAuxiliary =
    layerTypeValue == BlaiToolchainSetWeiPatchSpecialDoubleAuxType
  if not pagePlan.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchDivisorPagePlan
    return
  if outResult.startPatchCount <= 1'u32:
    outResult.selectedDivisor = outResult.startPatchCount
    outResult.firstBlock = blaiToolchainSetWeiPatchDivisorStartCount
    outResult.valid = true
    return
  if outResult.startPatchCount > high(uint32) - outResult.maxCandidateCount:
    outResult.firstBlock = blaiToolchainSetWeiPatchDivisorOverflow
    return

  for divisor in outResult.startPatchCount ..<
      outResult.startPatchCount + outResult.maxCandidateCount:
    inc outResult.testedCandidates
    let primaryBase =
      blaiToolchainRoundEvenSplit(blaiCeilDivU32(primaryNumerator, divisor))
    if primaryBase == high(uint32) or primaryBase > high(uint32) - basePatchOffset:
      outResult.firstBlock = blaiToolchainSetWeiPatchDivisorOverflow
      return
    let primarySpan = basePatchOffset + primaryBase
    let auxiliaryBase =
      if outResult.specialDoubleAuxiliary:
        if primaryBase > high(uint32) div 2'u32:
          outResult.firstBlock = blaiToolchainSetWeiPatchDivisorOverflow
          return
        primaryBase * 2'u32
      else:
        blaiToolchainRoundEvenSplit(
          blaiCeilDivU32(auxiliaryNumerator, divisor))
    let primaryBytes64 = primaryLocalFactor.uint64 * primarySpan.uint64
    let auxiliaryBytes64 = auxiliaryLocalFactor.uint64 * auxiliaryBase.uint64
    let primaryBytes = blaiToolchainSetWeiPatchU32ScalarAbi(primaryBytes64)
    let auxiliaryBytes = blaiToolchainSetWeiPatchU32ScalarAbi(auxiliaryBytes64)
    if not primaryBytes.valid or not auxiliaryBytes.valid:
      outResult.firstBlock = blaiToolchainSetWeiPatchDivisorOverflow
      return
    if primaryBytes.value <= BlaiNpuLocalBufferBytes and
       auxiliaryBytes.value <= BlaiNpuLocalBufferBytes:
      outResult.selectedDivisor = divisor
      outResult.roundedPrimarySplit = primarySpan
      outResult.roundedAuxiliarySplit = auxiliaryBase
      outResult.primaryLocalBytes = primaryBytes.value
      outResult.auxiliaryLocalBytes = auxiliaryBytes.value
      outResult.firstBlock = blaiToolchainSetWeiPatchDivisorNoBlock
      outResult.valid = true
      return

  outResult.firstBlock = blaiToolchainSetWeiPatchDivisorNoFit

proc blaiToolchainSetWeiPatchDivisorPlan*(
    pagePlan: BlaiToolchainSetWeiPatchPagePlan,
    layerTypeValue: int32,
    primaryNumerator, auxiliaryNumerator: uint32,
    primaryLocalFactor, auxiliaryLocalFactor: uint32,
    basePatchOffset: uint32): BlaiToolchainSetWeiPatchDivisorPlan =
  ## Convenience wrapper for recovered `set_wei_patch` divisor search.
  blaiToolchainSetWeiPatchDivisorPlanInto(
    pagePlan, layerTypeValue, primaryNumerator, auxiliaryNumerator,
    primaryLocalFactor, auxiliaryLocalFactor, basePatchOffset, result)

proc blaiToolchainFillPatchSplit(
    numerator, patchCount: uint32,
    roundEvenParts: bool,
    splits: var array[BlaiMaxWeightPatches, uint32],
    written: var uint32): BlaiToolchainSetWeiPatchStoreBlock =
  ## Fill recovered `set_wei_patch` split entries, with last entry as remainder.
  if patchCount == 0'u32 or patchCount > BlaiMaxWeightPatchesU32:
    return blaiToolchainSetWeiPatchStoreCapacity
  let partBase =
    if roundEvenParts:
      blaiToolchainRoundEvenSplit(blaiCeilDivU32(numerator, patchCount))
    else:
      numerator div patchCount
  if partBase == high(uint32):
    return blaiToolchainSetWeiPatchStoreOverflow
  var remaining = numerator
  for patchIndex in 0'u32 ..< patchCount:
    let patchPosition = blaiMemAllocPatchSegmentPosition(patchIndex, patchCount)
    if not patchPosition.valid:
      return blaiToolchainSetWeiPatchStoreCapacity
    let patchCursor = blaiWeightPatchCursor(patchIndex)
    if not patchCursor.valid:
      return blaiToolchainSetWeiPatchStoreCapacity
    let value =
      if patchPosition.last:
        remaining
      else:
        partBase
    splits[patchCursor.index] = value
    inc written
    remaining = blaiSaturatingSubU32(remaining, partBase)
  blaiToolchainSetWeiPatchStoreNoBlock

proc blaiToolchainSetWeiPatchStoreSelectEvidence*(largeKernelFlagSet: bool,
    primaryBytes, selectedDivisor, auxiliaryBytes: uint32):
    BlaiToolchainSetWeiPatchStoreSelectEvidence =
  ## Recover the raw branch predicates for `set_wei_patch` store selection.
  result.largeKernelFlagSet = largeKernelFlagSet
  result.primaryBytes = primaryBytes
  result.selectedDivisor = selectedDivisor
  result.auxiliaryBytes = auxiliaryBytes
  result.localBufferBytes = BlaiNpuLocalBufferBytes
  result.primaryPressureExceedsLocal =
    primaryBytes > BlaiNpuLocalBufferBytes
  result.divisorRequiresSplit = selectedDivisor > 1'u32
  result.auxiliaryPressureExceedsLocal =
    auxiliaryBytes > BlaiNpuLocalBufferBytes
  if result.largeKernelFlagSet:
    result.mode = blaiToolchainSetWeiPatchStoreSingle
  elif result.primaryPressureExceedsLocal or result.divisorRequiresSplit:
    result.mode = blaiToolchainSetWeiPatchStoreDivisor
  elif result.auxiliaryPressureExceedsLocal:
    result.mode = blaiToolchainSetWeiPatchStoreAuxiliary
  else:
    result.mode = blaiToolchainSetWeiPatchStoreSingle
  result.valid = true

proc blaiToolchainSetWeiPatchStoreSelectPlanInto*(
    largeKernelFlagSet: bool,
    primaryBytes, selectedDivisor, auxiliaryBytes: uint32,
    outResult: var BlaiToolchainSetWeiPatchStoreSelectPlan) =
  ## Recover the branch selector before `set_wei_patch` split stores.
  outResult = default(BlaiToolchainSetWeiPatchStoreSelectPlan)
  outResult.largeKernelFlagSet = largeKernelFlagSet
  outResult.primaryBytes = primaryBytes
  outResult.selectedDivisor = selectedDivisor
  outResult.auxiliaryBytes = auxiliaryBytes
  let evidence = blaiToolchainSetWeiPatchStoreSelectEvidence(
    largeKernelFlagSet, primaryBytes, selectedDivisor, auxiliaryBytes)
  outResult.localBufferBytes = evidence.localBufferBytes
  outResult.primaryPressureExceedsLocal =
    evidence.primaryPressureExceedsLocal
  outResult.divisorRequiresSplit = evidence.divisorRequiresSplit
  outResult.auxiliaryPressureExceedsLocal =
    evidence.auxiliaryPressureExceedsLocal
  outResult.mode = evidence.mode
  outResult.firstBlock = blaiToolchainSetWeiPatchStoreSelectNoBlock
  outResult.valid = evidence.valid

proc blaiToolchainSetWeiPatchStoreSelectPlan*(
    largeKernelFlagSet: bool,
    primaryBytes, selectedDivisor, auxiliaryBytes: uint32):
    BlaiToolchainSetWeiPatchStoreSelectPlan =
  ## Convenience wrapper for recovered `set_wei_patch` store-path selection.
  blaiToolchainSetWeiPatchStoreSelectPlanInto(
    largeKernelFlagSet, primaryBytes, selectedDivisor, auxiliaryBytes, result)

proc blaiToolchainSetWeiPatchStorePlanInto*(
    divisorPlan: BlaiToolchainSetWeiPatchDivisorPlan,
    auxiliaryPages, auxiliaryBytes: uint32,
    outResult: var BlaiToolchainSetWeiPatchStorePlan) =
  ## Recover patch-count and split metadata stores after `set_wei_patch` search.
  outResult = default(BlaiToolchainSetWeiPatchStorePlan)
  outResult.primaryNumerator = divisorPlan.primaryNumerator
  outResult.selectedDivisor = divisorPlan.selectedDivisor
  outResult.auxiliaryPages = auxiliaryPages
  outResult.primaryLocalBytes = divisorPlan.primaryLocalBytes
  outResult.auxiliaryBytes = auxiliaryBytes
  if not divisorPlan.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchStoreDivisorPlan
    return

  if divisorPlan.primaryLocalBytes <= BlaiNpuLocalBufferBytes and
     divisorPlan.selectedDivisor <= 1'u32 and
     auxiliaryBytes > BlaiNpuLocalBufferBytes:
    outResult.mode = blaiToolchainSetWeiPatchStoreAuxiliary
    outResult.patchCount = auxiliaryPages
    outResult.firstBlock = blaiToolchainFillPatchSplit(
      divisorPlan.primaryNumerator, outResult.patchCount, false,
      outResult.splitValues, outResult.splitCount)
  elif divisorPlan.selectedDivisor > 1'u32 or
       divisorPlan.primaryLocalBytes > BlaiNpuLocalBufferBytes:
    outResult.mode = blaiToolchainSetWeiPatchStoreDivisor
    outResult.patchCount = divisorPlan.selectedDivisor
    outResult.firstBlock = blaiToolchainFillPatchSplit(
      divisorPlan.primaryNumerator, outResult.patchCount, true,
      outResult.splitValues, outResult.splitCount)
  else:
    outResult.mode = blaiToolchainSetWeiPatchStoreSingle
    outResult.patchCount = 1
    outResult.splitCount = 1
    outResult.splitValues[0] = divisorPlan.primaryNumerator
    outResult.firstBlock = blaiToolchainSetWeiPatchStoreNoBlock

  outResult.valid = outResult.firstBlock == blaiToolchainSetWeiPatchStoreNoBlock

proc blaiToolchainSetWeiPatchStorePlan*(
    divisorPlan: BlaiToolchainSetWeiPatchDivisorPlan,
    auxiliaryPages, auxiliaryBytes: uint32): BlaiToolchainSetWeiPatchStorePlan =
  ## Convenience wrapper for recovered `set_wei_patch` metadata stores.
  blaiToolchainSetWeiPatchStorePlanInto(
    divisorPlan, auxiliaryPages, auxiliaryBytes, result)

proc blaiToolchainSetWeiPatchStoreState*(
    mode: BlaiToolchainSetWeiPatchStoreMode,
    patchCount, splitCount: uint32,
    splitValues: array[BlaiMaxWeightPatches, uint32]):
    BlaiToolchainSetWeiPatchStoreState =
  ## Build a typed caller-owned store-path metadata state.
  result.mode = mode
  result.patchCount = patchCount
  result.splitCount = splitCount
  result.splitValues = splitValues

proc blaiToolchainSetWeiPatchStoreApplyPlanInto*(
    store: BlaiToolchainSetWeiPatchStorePlan,
    splitValues: openArray[uint32],
    outResult: var BlaiToolchainSetWeiPatchStoreApplyPlan) =
  ## Prepare checked application of recovered store-path metadata.
  ##
  ## This covers the earlier `set_wei_patch` write of a selected patch count and
  ## split table, before the later large/lower/no-patch branch result is chosen.
  outResult = default(BlaiToolchainSetWeiPatchStoreApplyPlan)
  outResult.store = store
  outResult.splitStorageCount = blaiOpenArrayLenU32(splitValues)
  if not store.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchStoreApplyStorePlan
    return
  if store.splitCount > outResult.splitStorageCount:
    outResult.firstBlock = blaiToolchainSetWeiPatchStoreApplySplitStorage
    return

  outResult.mode = store.mode
  outResult.patchCount = store.patchCount
  outResult.splitCount = store.splitCount
  outResult.splitValues = store.splitValues
  outResult.stateAfter = blaiToolchainSetWeiPatchStoreState(
    store.mode, store.patchCount, store.splitCount, store.splitValues)
  outResult.writesApplied = store.splitCount
  outResult.firstBlock = blaiToolchainSetWeiPatchStoreApplyNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchStoreApplyPlan*(
    store: BlaiToolchainSetWeiPatchStorePlan,
    splitValues: openArray[uint32]): BlaiToolchainSetWeiPatchStoreApplyPlan =
  ## Convenience wrapper for checked store-path metadata application.
  blaiToolchainSetWeiPatchStoreApplyPlanInto(store, splitValues, result)

proc blaiApplyToolchainSetWeiPatchStoreState*(
    state: var BlaiToolchainSetWeiPatchStoreState,
    plan: BlaiToolchainSetWeiPatchStoreApplyPlan): bool =
  ## Apply recovered store-path metadata to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainSetWeiPatchStoreSplitState*(
    patchCount: var uint32,
    splitValues: var openArray[uint32],
    state: BlaiToolchainSetWeiPatchStoreState): bool =
  ## Apply recovered store-path split state to caller-owned storage.
  if state.splitCount > blaiOpenArrayLenU32(splitValues):
    return false

  patchCount = state.patchCount
  for splitIndex in 0'u32 ..< state.splitCount:
    let splitCursor =
      blaiToolchainSetWeiPatchSplitCursor(splitIndex, splitValues.len)
    if not splitCursor.valid:
      return false
    splitValues[splitCursor.index] = state.splitValues[splitCursor.index]
  true

proc blaiApplyToolchainSetWeiPatchStoreScalarState*(
    mode: var BlaiToolchainSetWeiPatchStoreMode,
    patchCount: var uint32,
    splitCount: var uint32,
    state: BlaiToolchainSetWeiPatchStoreState): bool =
  ## Apply recovered store-path scalar metadata from typed state.
  mode = state.mode
  patchCount = state.patchCount
  splitCount = state.splitCount
  true

proc blaiApplyToolchainSetWeiPatchStoreScalars*(
    mode: var BlaiToolchainSetWeiPatchStoreMode,
    patchCount: var uint32,
    splitCount: var uint32,
    plan: BlaiToolchainSetWeiPatchStoreApplyPlan): bool =
  ## Apply recovered store-path scalar metadata.
  if not plan.valid:
    return false
  blaiApplyToolchainSetWeiPatchStoreScalarState(
    mode, patchCount, splitCount, plan.stateAfter)

proc blaiApplyToolchainSetWeiPatchStore*(
    patchCount: var uint32,
    splitValues: var openArray[uint32],
    plan: BlaiToolchainSetWeiPatchStoreApplyPlan): bool =
  ## Apply recovered store-path patch count and split values.
  if not plan.valid:
    return false
  blaiApplyToolchainSetWeiPatchStoreSplitState(
    patchCount, splitValues, plan.stateAfter)

proc blaiToolchainSetWeiPatchStoreCommitPlanInto*(
    select: BlaiToolchainSetWeiPatchStoreSelectPlan,
    store: BlaiToolchainSetWeiPatchStorePlan,
    splitValues: openArray[uint32],
    outResult: var BlaiToolchainSetWeiPatchStoreCommitPlan) =
  ## Compose store-path selection with the metadata write it selected.
  outResult = default(BlaiToolchainSetWeiPatchStoreCommitPlan)
  outResult.select = select
  outResult.store = store
  if not select.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchStoreCommitSelectPlan
    return
  if not store.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchStoreCommitStorePlan
    return
  if select.mode != store.mode:
    outResult.firstBlock = blaiToolchainSetWeiPatchStoreCommitModeMismatch
    return

  blaiToolchainSetWeiPatchStoreApplyPlanInto(
    store, splitValues, outResult.apply)
  if not outResult.apply.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchStoreCommitApplyPlan
    return

  outResult.mode = store.mode
  outResult.patchCount = store.patchCount
  outResult.splitCount = store.splitCount
  outResult.writesApplied = outResult.apply.writesApplied
  outResult.firstBlock = blaiToolchainSetWeiPatchStoreCommitNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchStoreCommitPlan*(
    select: BlaiToolchainSetWeiPatchStoreSelectPlan,
    store: BlaiToolchainSetWeiPatchStorePlan,
    splitValues: openArray[uint32]): BlaiToolchainSetWeiPatchStoreCommitPlan =
  ## Convenience wrapper for composed store selection and metadata commit.
  blaiToolchainSetWeiPatchStoreCommitPlanInto(
    select, store, splitValues, result)

proc blaiToolchainSetWeiPatchStoreCommitState*(
    mode: BlaiToolchainSetWeiPatchStoreMode,
    patchCount: uint32,
    splitCount: uint32,
    splitValues: array[BlaiMaxWeightPatches, uint32],
    writesApplied: uint32): BlaiToolchainSetWeiPatchStoreCommitState =
  ## Build caller-owned state for a composed store metadata commit.
  result.mode = mode
  result.patchCount = patchCount
  result.splitCount = splitCount
  result.splitValues = splitValues
  result.writesApplied = writesApplied

proc blaiToolchainSetWeiPatchStoreCommitSummaryState*(
    selectedMode, storeMode, mode: BlaiToolchainSetWeiPatchStoreMode,
    splitStorageCount, patchCount, splitCount, writesApplied: uint32,
    splitValues: array[BlaiMaxWeightPatches, uint32]):
    BlaiToolchainSetWeiPatchStoreCommitSummaryState =
  ## Build the full diagnostic state for a composed store metadata commit.
  result.selectedMode = selectedMode
  result.storeMode = storeMode
  result.mode = mode
  result.splitStorageCount = splitStorageCount
  result.patchCount = patchCount
  result.splitCount = splitCount
  result.writesApplied = writesApplied
  result.splitValues = splitValues

proc blaiToolchainSetWeiPatchStoreCommitApplyPlanInto*(
    commit: BlaiToolchainSetWeiPatchStoreCommitPlan,
    outResult: var BlaiToolchainSetWeiPatchStoreCommitApplyPlan) =
  ## Project a valid composed store commit into checked caller-owned state.
  outResult = default(BlaiToolchainSetWeiPatchStoreCommitApplyPlan)
  outResult.commit = commit
  if not commit.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchStoreCommitApplyCommitPlan
    return

  outResult.stateAfter = blaiToolchainSetWeiPatchStoreCommitState(
    commit.mode, commit.patchCount, commit.splitCount,
    commit.apply.stateAfter.splitValues, commit.writesApplied)
  outResult.summaryStateAfter =
    blaiToolchainSetWeiPatchStoreCommitSummaryState(
      commit.select.mode, commit.store.mode, commit.mode,
      commit.apply.splitStorageCount, commit.patchCount, commit.splitCount,
      commit.writesApplied, commit.apply.stateAfter.splitValues)
  outResult.firstBlock = blaiToolchainSetWeiPatchStoreCommitApplyNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchStoreCommitApplyPlan*(
    commit: BlaiToolchainSetWeiPatchStoreCommitPlan):
    BlaiToolchainSetWeiPatchStoreCommitApplyPlan =
  ## Convenience wrapper for checked store commit-state projection.
  blaiToolchainSetWeiPatchStoreCommitApplyPlanInto(commit, result)

proc blaiApplyToolchainSetWeiPatchStoreCommitState*(
    state: var BlaiToolchainSetWeiPatchStoreCommitState,
    plan: BlaiToolchainSetWeiPatchStoreCommitApplyPlan): bool =
  ## Apply recovered store commit metadata to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainSetWeiPatchStoreCommitSplitState*(
    patchCount: var uint32,
    splitValues: var openArray[uint32],
    state: BlaiToolchainSetWeiPatchStoreCommitState): bool =
  ## Apply recovered store commit split state to caller-owned storage.
  if state.splitCount > blaiOpenArrayLenU32(splitValues):
    return false

  patchCount = state.patchCount
  for splitIndex in 0'u32 ..< state.splitCount:
    let splitCursor =
      blaiToolchainSetWeiPatchSplitCursor(splitIndex, splitValues.len)
    if not splitCursor.valid:
      return false
    splitValues[splitCursor.index] =
      state.splitValues[splitCursor.index]
  true

proc blaiApplyToolchainSetWeiPatchStoreCommitScalarState*(
    mode: var BlaiToolchainSetWeiPatchStoreMode,
    patchCount: var uint32,
    splitCount: var uint32,
    writesApplied: var uint32,
    state: BlaiToolchainSetWeiPatchStoreCommitState): bool =
  ## Apply recovered store commit scalar metadata from typed state.
  mode = state.mode
  patchCount = state.patchCount
  splitCount = state.splitCount
  writesApplied = state.writesApplied
  true

proc blaiApplyToolchainSetWeiPatchStoreCommitSummaryScalarState*(
    selectedMode, storeMode, mode: var BlaiToolchainSetWeiPatchStoreMode,
    splitStorageCount, patchCount, splitCount, writesApplied: var uint32,
    state: BlaiToolchainSetWeiPatchStoreCommitSummaryState): bool =
  ## Apply full store commit summary scalars from typed state.
  selectedMode = state.selectedMode
  storeMode = state.storeMode
  mode = state.mode
  splitStorageCount = state.splitStorageCount
  patchCount = state.patchCount
  splitCount = state.splitCount
  writesApplied = state.writesApplied
  true

proc blaiApplyToolchainSetWeiPatchStoreCommitScalars*(
    mode: var BlaiToolchainSetWeiPatchStoreMode,
    patchCount: var uint32,
    splitCount: var uint32,
    writesApplied: var uint32,
    plan: BlaiToolchainSetWeiPatchStoreCommitApplyPlan): bool =
  ## Apply recovered store commit scalar metadata.
  if not plan.valid:
    return false
  blaiApplyToolchainSetWeiPatchStoreCommitScalarState(
    mode, patchCount, splitCount, writesApplied, plan.stateAfter)

proc blaiApplyToolchainSetWeiPatchStoreCommitSummaryScalars*(
    selectedMode, storeMode, mode: var BlaiToolchainSetWeiPatchStoreMode,
    splitStorageCount, patchCount, splitCount, writesApplied: var uint32,
    plan: BlaiToolchainSetWeiPatchStoreCommitApplyPlan): bool =
  ## Apply full store commit summary scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainSetWeiPatchStoreCommitSummaryScalarState(
    selectedMode, storeMode, mode, splitStorageCount, patchCount, splitCount,
    writesApplied, plan.summaryStateAfter)

proc blaiApplyToolchainSetWeiPatchStoreCommit*(
    patchCount: var uint32,
    splitValues: var openArray[uint32],
    plan: BlaiToolchainSetWeiPatchStoreCommitPlan): bool =
  ## Apply a validated store selector/metadata commit.
  let applyPlan = blaiToolchainSetWeiPatchStoreCommitApplyPlan(plan)
  if not applyPlan.valid:
    return false
  blaiApplyToolchainSetWeiPatchStoreCommitSplitState(
    patchCount, splitValues, applyPlan.stateAfter)

proc blaiToolchainSetWeiPatchPressurePlanInto*(
    layerTypeValue: int32,
    countA, countB, groupCount, multiplierPrimary, multiplierSecondary,
    multiplierMatchValue, kernelExtent, auxExtent: int32,
    outResult: var BlaiToolchainSetWeiPatchPressurePlan) =
  ## Recover `set_wei_patch` byte-pressure scalar before branch gates.
  ##
  ## The converter aligns two copied counts to four, selects the recovered
  ## matched multiplier when either copied multiplier field matches the
  ## comparison value, otherwise the recovered default multiplier, and divides
  ## by the recovered 1x1 or spatial group factor times the selected group
  ## count.
  outResult = default(BlaiToolchainSetWeiPatchPressurePlan)
  outResult.layerTypeValue = layerTypeValue
  let maskShift = blaiToolchainSetWeiPatchLayerMaskShiftAbi(
    layerTypeValue, BlaiToolchainSetWeiPatchLargeMaskMaxType)
  outResult.maskRange = maskShift.valid
  if maskShift.valid:
    outResult.maskBitSet =
      ((BlaiToolchainSetWeiPatchLargeLayerMask shr maskShift.value) and
        1'u64) == 1'u64
  outResult.pressureMaskAllowed = outResult.maskBitSet

  if countA < 0 or countB < 0 or groupCount < 0 or
     multiplierPrimary < 0 or multiplierSecondary < 0 or
     multiplierMatchValue < 0 or kernelExtent < 0 or auxExtent < 0:
    outResult.firstBlock = blaiToolchainSetWeiPatchPressureShape
    return
  let countAField = blaiToolchainSetWeiPatchI32U32Abi(countA)
  let countBField = blaiToolchainSetWeiPatchI32U32Abi(countB)
  let groupCountField = blaiToolchainSetWeiPatchI32U32Abi(groupCount)
  let kernelExtentField = blaiToolchainSetWeiPatchI32U32Abi(kernelExtent)
  let auxExtentField = blaiToolchainSetWeiPatchI32U32Abi(auxExtent)
  if not countAField.valid or not countBField.valid or
     not groupCountField.valid or not kernelExtentField.valid or
     not auxExtentField.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchPressureShape
    return

  outResult.countA = countAField.value
  outResult.countB = countBField.value
  outResult.groupCount = groupCountField.value
  outResult.selectedGroupCount =
    if outResult.groupCount > 0'u32:
      outResult.groupCount
    else:
      BlaiToolchainSetWeiPatchPressureDefaultGroupCount
  outResult.multiplier =
    if multiplierPrimary == multiplierMatchValue or
       multiplierSecondary == multiplierMatchValue:
      BlaiToolchainSetWeiPatchPressureMatchedMultiplier
    else:
      BlaiToolchainSetWeiPatchPressureDefaultMultiplier
  outResult.kernelExtent = kernelExtentField.value
  outResult.auxExtent = auxExtentField.value
  outResult.oneByOne =
    outResult.kernelExtent ==
      BlaiToolchainSetWeiPatchPressureOneByOneKernelExtent
  outResult.largeKernelOrAux =
    outResult.kernelExtent >
      BlaiToolchainSetWeiPatchPressureLargeKernelExtent or
    outResult.auxExtent >
      BlaiToolchainSetWeiPatchPressureAuxExtentThreshold

  outResult.alignedCountA = blaiAlign4(outResult.countA)
  outResult.alignedCountB = blaiAlign4(outResult.countB)
  if outResult.alignedCountA < outResult.countA or
     outResult.alignedCountB < outResult.countB:
    outResult.firstBlock = blaiToolchainSetWeiPatchPressureOverflow
    return

  if outResult.oneByOne:
    if outResult.selectedGroupCount >
        high(uint32) div
          BlaiToolchainSetWeiPatchPressureOneByOneGroupFactor:
      outResult.firstBlock = blaiToolchainSetWeiPatchPressureOverflow
      return
    outResult.groupDenominator =
      outResult.selectedGroupCount *
        BlaiToolchainSetWeiPatchPressureOneByOneGroupFactor
  else:
    if outResult.selectedGroupCount >
        high(uint32) div BlaiToolchainSetWeiPatchPressureSpatialGroupFactor:
      outResult.firstBlock = blaiToolchainSetWeiPatchPressureOverflow
      return
    outResult.groupDenominator =
      outResult.selectedGroupCount *
        BlaiToolchainSetWeiPatchPressureSpatialGroupFactor
  if outResult.groupDenominator == 0'u32:
    outResult.firstBlock = blaiToolchainSetWeiPatchPressureGroupDivisor
    return

  var numerator = outResult.alignedCountA.uint64
  if outResult.multiplier != 0'u32 and
     numerator > high(uint64) div outResult.multiplier.uint64:
    outResult.firstBlock = blaiToolchainSetWeiPatchPressureOverflow
    return
  numerator = numerator * outResult.multiplier.uint64
  if outResult.alignedCountB != 0'u32 and
     numerator > high(uint64) div outResult.alignedCountB.uint64:
    outResult.firstBlock = blaiToolchainSetWeiPatchPressureOverflow
    return
  numerator = numerator * outResult.alignedCountB.uint64
  if not outResult.oneByOne:
    let spatialFactor =
      if outResult.largeKernelOrAux:
        BlaiToolchainSetWeiPatchPressureLargeSpatialFactor
      else:
        outResult.kernelExtent.uint64 * outResult.kernelExtent.uint64
    if spatialFactor != 0'u64 and numerator > high(uint64) div spatialFactor:
      outResult.firstBlock = blaiToolchainSetWeiPatchPressureOverflow
      return
    numerator = numerator * spatialFactor
  let pressure64 = numerator div outResult.groupDenominator.uint64
  let bytePressure = blaiToolchainSetWeiPatchU32ScalarAbi(pressure64)
  if not bytePressure.valid:
    outResult.firstBlock = blaiToolchainSetWeiPatchPressureOverflow
    return

  outResult.bytePressure = bytePressure.value
  outResult.firstBlock = blaiToolchainSetWeiPatchPressureNoBlock
  outResult.valid = true

proc blaiToolchainSetWeiPatchPressurePlan*(
    layerTypeValue: int32,
    countA, countB, groupCount, multiplierPrimary, multiplierSecondary,
    multiplierMatchValue, kernelExtent, auxExtent: int32):
    BlaiToolchainSetWeiPatchPressurePlan =
  ## Convenience wrapper for recovered `set_wei_patch` byte pressure.
  blaiToolchainSetWeiPatchPressurePlanInto(
    layerTypeValue, countA, countB, groupCount, multiplierPrimary,
    multiplierSecondary, multiplierMatchValue, kernelExtent, auxExtent, result)

proc blaiToolchainSetWeiPatchLargeFlagEvidence*(layerTypeValue: int32,
    bytePressure: uint32): BlaiToolchainSetWeiPatchLargeFlagEvidence =
  ## Recover the raw mask/range/threshold predicates for the large flag gate.
  result.layerTypeValue = layerTypeValue
  result.bytePressure = bytePressure
  result.thresholdBytes = BlaiToolchainSetWeiPatchLargeThresholdBytes
  result.layerMask = BlaiToolchainSetWeiPatchLargeLayerMask
  let maskShift = blaiToolchainSetWeiPatchLayerMaskShiftAbi(
    layerTypeValue, BlaiToolchainSetWeiPatchLargeMaskMaxType)
  result.layerTypeInMaskRange = maskShift.valid
  if maskShift.valid:
    result.layerMaskBitSet =
      ((result.layerMask shr maskShift.value) and 1'u64) == 1'u64
  result.largeEnough = bytePressure > result.thresholdBytes
  result.flagSet = result.largeEnough and result.layerMaskBitSet
  result.valid = true

proc blaiToolchainSetWeiPatchLargeFlagPlanInto*(
    layerTypeValue: int32,
    bytePressure: uint32,
    outResult: var BlaiToolchainSetWeiPatchLargeFlagPlan) =
  ## Recover the large-pressure type-mask flag gate in `set_wei_patch`.
  outResult = default(BlaiToolchainSetWeiPatchLargeFlagPlan)
  outResult.layerTypeValue = layerTypeValue
  outResult.bytePressure = bytePressure
  let evidence = blaiToolchainSetWeiPatchLargeFlagEvidence(
    layerTypeValue, bytePressure)
  outResult.thresholdBytes = evidence.thresholdBytes
  outResult.layerMask = evidence.layerMask
  outResult.layerTypeInMaskRange = evidence.layerTypeInMaskRange
  outResult.layerMaskBitSet = evidence.layerMaskBitSet
  outResult.largeEnough = evidence.largeEnough
  outResult.flagSet = evidence.flagSet
  outResult.valid = evidence.valid

proc blaiToolchainSetWeiPatchLargeFlagPlan*(
    layerTypeValue: int32,
    bytePressure: uint32): BlaiToolchainSetWeiPatchLargeFlagPlan =
  ## Convenience wrapper for the recovered `set_wei_patch` large flag gate.
  blaiToolchainSetWeiPatchLargeFlagPlanInto(
    layerTypeValue, bytePressure, result)

proc blaiToolchainFloorPowerOfTwo(value: uint32): uint32 =
  ## Integer equivalent of converter `pow(2, int(log2(value)))`.
  if value == 0'u32:
    return 0'u32
  result = 1'u32
  while result <= high(uint32) shr 1 and (result shl 1) <= value:
    result = result shl 1

proc blaiToolchainSetWeiPatchPressurePagePlan*(
    bytePressure, pageBytes: uint32): BlaiToolchainSetWeiPatchPressurePagePlan =
  ## Recover split planner page count, including the non-divisible extra page.
  result.bytePressure = bytePressure
  result.pageBytes = pageBytes
  if pageBytes == 0'u32 or bytePressure == 0'u32:
    return

  let roundingBias = blaiToolchainSetWeiPatchU32ScalarAbi(
    BlaiToolchainSetWeiPatchPressurePageRoundingBias)
  if not roundingBias.valid:
    result.overflow = true
    return

  result.nonDivisiblePageExtra =
    (bytePressure and (pageBytes - roundingBias.value)) != 0'u32
  result.roundedPressure =
    bytePressure.uint64 + pageBytes.uint64 - roundingBias.value.uint64
  let roundedPressure = blaiToolchainSetWeiPatchU32ScalarAbi(
    result.roundedPressure)
  if not roundedPressure.valid:
    result.overflow = true
    return

  result.pressurePageCount =
    if result.nonDivisiblePageExtra:
      (roundedPressure.value div pageBytes) +
        BlaiToolchainSetWeiPatchPressureNonDivisibleExtraPages
    else:
      bytePressure div pageBytes
  result.valid = true

proc blaiToolchainFillFixedSplit(
    numerator, patchCount, splitValue: uint32,
    splits: var array[BlaiMaxWeightPatches, uint32],
    written: var uint32): BlaiToolchainSetWeiPatchLargeSplitBlock =
  ## Fill converter-style fixed split entries with the final remainder.
  if patchCount == 0'u32 or patchCount > BlaiMaxWeightPatchesU32:
    return blaiToolchainSetWeiPatchLargeSplitCapacity
  if splitValue == 0'u32:
    return blaiToolchainSetWeiPatchLargeSplitNumerator
  var remaining = numerator
  for patchIndex in 0'u32 ..< patchCount:
    let patchPosition = blaiMemAllocPatchSegmentPosition(patchIndex, patchCount)
    if not patchPosition.valid:
      return blaiToolchainSetWeiPatchLargeSplitCapacity
    let patchCursor = blaiWeightPatchCursor(patchIndex)
    if not patchCursor.valid:
      return blaiToolchainSetWeiPatchLargeSplitCapacity
    let value =
      if patchPosition.last:
        remaining
      else:
        splitValue
    splits[patchCursor.index] = value
    inc written
    remaining = blaiSaturatingSubU32(remaining, splitValue)
  blaiToolchainSetWeiPatchLargeSplitNoBlock

proc blaiToolchainSetWeiPatchLargeSplitEvidence*(
    flagPlan: BlaiToolchainSetWeiPatchLargeFlagPlan,
    splitNumerator: uint32): BlaiToolchainSetWeiPatchLargeSplitEvidence =
  ## Recover large split page count, selected split, and patch count.
  result.flagPlan = flagPlan
  result.splitNumerator = splitNumerator
  result.pageBytes = BlaiToolchainSetWeiPatchLargePageBytes
  if not flagPlan.valid or not flagPlan.flagSet:
    result.firstBlock = blaiToolchainSetWeiPatchLargeSplitFlagPlan
    return
  if result.pageBytes == 0'u32 or flagPlan.bytePressure == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLargeSplitPageCount
    return
  if splitNumerator == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLargeSplitNumerator
    return

  let pagePlan = blaiToolchainSetWeiPatchPressurePagePlan(
    flagPlan.bytePressure, result.pageBytes)
  if pagePlan.overflow:
    result.firstBlock = blaiToolchainSetWeiPatchLargeSplitOverflow
    return
  if not pagePlan.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLargeSplitPageCount
    return
  result.nonDivisiblePageExtra = pagePlan.nonDivisiblePageExtra
  result.pressurePageCount = pagePlan.pressurePageCount
  if result.pressurePageCount == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLargeSplitPageCount
    return

  result.quotientBeforePowerOfTwo =
    splitNumerator div result.pressurePageCount
  result.selectedSplit =
    blaiToolchainFloorPowerOfTwo(result.quotientBeforePowerOfTwo)
  if result.selectedSplit == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLargeSplitNumerator
    return
  result.patchCount = blaiCeilDivU32(splitNumerator, result.selectedSplit)
  result.firstBlock = blaiToolchainSetWeiPatchLargeSplitNoBlock
  result.valid = true

proc blaiToolchainSetWeiPatchLargeSplitPlanInto*(
    flagPlan: BlaiToolchainSetWeiPatchLargeFlagPlan,
    splitNumerator: uint32,
    outResult: var BlaiToolchainSetWeiPatchLargeSplitPlan) =
  ## Recover large-pressure patch count and split metadata after the flag gate.
  outResult = default(BlaiToolchainSetWeiPatchLargeSplitPlan)
  outResult.flagPlan = flagPlan
  outResult.splitNumerator = splitNumerator
  let evidence =
    blaiToolchainSetWeiPatchLargeSplitEvidence(flagPlan, splitNumerator)
  outResult.pageBytes = evidence.pageBytes
  outResult.nonDivisiblePageExtra = evidence.nonDivisiblePageExtra
  outResult.pressurePageCount = evidence.pressurePageCount
  outResult.quotientBeforePowerOfTwo = evidence.quotientBeforePowerOfTwo
  outResult.selectedSplit = evidence.selectedSplit
  outResult.patchCount = evidence.patchCount
  if not evidence.valid:
    outResult.firstBlock = evidence.firstBlock
    return
  outResult.firstBlock = blaiToolchainFillFixedSplit(
    splitNumerator, outResult.patchCount, outResult.selectedSplit,
    outResult.splitValues, outResult.splitCount)
  outResult.valid =
    outResult.firstBlock == blaiToolchainSetWeiPatchLargeSplitNoBlock

proc blaiToolchainSetWeiPatchLargeSplitPlan*(
    flagPlan: BlaiToolchainSetWeiPatchLargeFlagPlan,
    splitNumerator: uint32): BlaiToolchainSetWeiPatchLargeSplitPlan =
  ## Convenience wrapper for recovered large-pressure split metadata.
  blaiToolchainSetWeiPatchLargeSplitPlanInto(
    flagPlan, splitNumerator, result)

proc blaiToolchainSetWeiPatchLargeTotalEvidence*(
    splitPlan: BlaiToolchainSetWeiPatchLargeSplitPlan,
    unitFactor: uint32): BlaiToolchainSetWeiPatchLargeTotalEvidence =
  ## Recover large split local-byte pressure and PSRAM patch-total arithmetic.
  result.splitPlan = splitPlan
  result.unitFactor = unitFactor
  result.patchSizeBytes = BlaiToolchainPatchSizeBytes
  if not splitPlan.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLargeTotalSplitPlan
    return
  if result.patchSizeBytes == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLargeTotalPatchSize
    return

  let finalPatchPosition =
    blaiMemAllocFinalPatchSegmentPosition(splitPlan.patchCount)
  if not finalPatchPosition.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLargeTotalSplitPlan
    return
  let lastCursor = blaiWeightPatchCursor(finalPatchPosition.patchIndex)
  if not lastCursor.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLargeTotalSplitPlan
    return
  result.finalSplitValue = splitPlan.splitValues[lastCursor.index]

  let selectedBytes64 =
    unitFactor.uint64 * splitPlan.selectedSplit.uint64
  let remainderBytes64 =
    unitFactor.uint64 * result.finalSplitValue.uint64
  let splitCountBytes64 =
    unitFactor.uint64 * splitPlan.splitNumerator.uint64
  let selectedBytes = blaiToolchainSetWeiPatchU32ScalarAbi(selectedBytes64)
  let remainderBytes = blaiToolchainSetWeiPatchU32ScalarAbi(remainderBytes64)
  let splitCountBytes = blaiToolchainSetWeiPatchU32ScalarAbi(splitCountBytes64)
  if not selectedBytes.valid or
     not remainderBytes.valid or
     not splitCountBytes.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLargeTotalOverflow
    return

  result.selectedLocalBytes = selectedBytes.value
  result.remainderLocalBytes = remainderBytes.value
  result.maxLocalBytes =
    max(result.selectedLocalBytes, result.remainderLocalBytes)
  result.perPatchContribution =
    result.maxLocalBytes div result.patchSizeBytes
  result.splitCountContribution =
    splitCountBytes.value div result.patchSizeBytes
  let total64 =
    result.perPatchContribution.uint64 * splitPlan.patchCount.uint64 +
      result.splitCountContribution.uint64
  let totalPatchCount = blaiToolchainSetWeiPatchU32ScalarAbi(total64)
  if not totalPatchCount.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLargeTotalOverflow
    return
  result.totalPatchCount = totalPatchCount.value
  result.firstBlock = blaiToolchainSetWeiPatchLargeTotalNoBlock
  result.valid = true

proc blaiToolchainSetWeiPatchLargeTotalPlanInto*(
    splitPlan: BlaiToolchainSetWeiPatchLargeSplitPlan,
    unitFactor: uint32,
    outResult: var BlaiToolchainSetWeiPatchLargeTotalPlan) =
  ## Recover PSRAM patch-total metadata after large-pressure split storage.
  outResult = default(BlaiToolchainSetWeiPatchLargeTotalPlan)
  outResult.splitPlan = splitPlan
  outResult.unitFactor = unitFactor
  let evidence =
    blaiToolchainSetWeiPatchLargeTotalEvidence(splitPlan, unitFactor)
  outResult.patchSizeBytes = evidence.patchSizeBytes
  outResult.finalSplitValue = evidence.finalSplitValue
  outResult.selectedLocalBytes = evidence.selectedLocalBytes
  outResult.remainderLocalBytes = evidence.remainderLocalBytes
  outResult.maxLocalBytes = evidence.maxLocalBytes
  outResult.perPatchContribution = evidence.perPatchContribution
  outResult.splitCountContribution = evidence.splitCountContribution
  outResult.totalPatchCount = evidence.totalPatchCount
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainSetWeiPatchLargeTotalPlan*(
    splitPlan: BlaiToolchainSetWeiPatchLargeSplitPlan,
    unitFactor: uint32): BlaiToolchainSetWeiPatchLargeTotalPlan =
  ## Convenience wrapper for recovered large-pressure PSRAM patch totals.
  blaiToolchainSetWeiPatchLargeTotalPlanInto(
    splitPlan, unitFactor, result)

proc blaiToolchainSetWeiPatchLowerFlagEvidence*(layerTypeValue: int32,
    numerator, divisor, multiplier: uint32):
    BlaiToolchainSetWeiPatchLowerFlagEvidence =
  ## Recover the raw mask/range/threshold predicates for the lower flag gate.
  result.layerTypeValue = layerTypeValue
  result.numerator = numerator
  result.divisor = divisor
  result.multiplier = multiplier
  result.thresholdBytes = BlaiToolchainSetWeiPatchLowerThresholdBytes
  result.layerMask = BlaiToolchainSetWeiPatchLargeLayerMask
  let maskShift = blaiToolchainSetWeiPatchLayerMaskShiftAbi(
    layerTypeValue, BlaiToolchainSetWeiPatchLargeMaskMaxType)
  result.layerTypeInMaskRange = maskShift.valid
  if maskShift.valid:
    result.layerMaskBitSet =
      ((result.layerMask shr maskShift.value) and 1'u64) == 1'u64
  if divisor == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLowerFlagDivisor
    return

  result.quotient = numerator div divisor
  let pressure64 = result.quotient.uint64 * multiplier.uint64
  let bytePressure = blaiToolchainSetWeiPatchU32ScalarAbi(pressure64)
  if not bytePressure.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLowerFlagOverflow
    return
  result.bytePressure = bytePressure.value
  result.lowerEnough = result.bytePressure > result.thresholdBytes
  if result.lowerEnough and result.layerMaskBitSet:
    result.flagValue = BlaiToolchainSetWeiPatchLowerFlagValue
  result.firstBlock = blaiToolchainSetWeiPatchLowerFlagNoBlock
  result.valid = true

proc blaiToolchainSetWeiPatchLowerFlagPlanInto*(
    layerTypeValue: int32,
    numerator, divisor, multiplier: uint32,
    outResult: var BlaiToolchainSetWeiPatchLowerFlagPlan) =
  ## Recover the lower-pressure flag gate after the large-path check.
  outResult = default(BlaiToolchainSetWeiPatchLowerFlagPlan)
  outResult.layerTypeValue = layerTypeValue
  outResult.numerator = numerator
  outResult.divisor = divisor
  outResult.multiplier = multiplier
  let evidence = blaiToolchainSetWeiPatchLowerFlagEvidence(
    layerTypeValue, numerator, divisor, multiplier)
  outResult.quotient = evidence.quotient
  outResult.bytePressure = evidence.bytePressure
  outResult.thresholdBytes = evidence.thresholdBytes
  outResult.layerMask = evidence.layerMask
  outResult.layerTypeInMaskRange = evidence.layerTypeInMaskRange
  outResult.layerMaskBitSet = evidence.layerMaskBitSet
  outResult.lowerEnough = evidence.lowerEnough
  outResult.flagValue = evidence.flagValue
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainSetWeiPatchLowerFlagPlan*(
    layerTypeValue: int32,
    numerator, divisor, multiplier: uint32):
    BlaiToolchainSetWeiPatchLowerFlagPlan =
  ## Convenience wrapper for recovered lower-pressure flag selection.
  blaiToolchainSetWeiPatchLowerFlagPlanInto(
    layerTypeValue, numerator, divisor, multiplier, result)

proc blaiToolchainFillLowerFixedSplit(
    numerator, patchCount, splitValue: uint32,
    splits: var array[BlaiMaxWeightPatches, uint32],
    written: var uint32): BlaiToolchainSetWeiPatchLowerSplitBlock =
  ## Fill lower-branch fixed split entries with the final remainder.
  if patchCount == 0'u32 or patchCount > BlaiMaxWeightPatchesU32:
    return blaiToolchainSetWeiPatchLowerSplitCapacity
  if splitValue == 0'u32:
    return blaiToolchainSetWeiPatchLowerSplitNumerator
  var remaining = numerator
  for patchIndex in 0'u32 ..< patchCount:
    let patchPosition = blaiMemAllocPatchSegmentPosition(patchIndex, patchCount)
    if not patchPosition.valid:
      return blaiToolchainSetWeiPatchLowerSplitCapacity
    let patchCursor = blaiWeightPatchCursor(patchIndex)
    if not patchCursor.valid:
      return blaiToolchainSetWeiPatchLowerSplitCapacity
    let value =
      if patchPosition.last:
        remaining
      else:
        splitValue
    splits[patchCursor.index] = value
    inc written
    remaining = blaiSaturatingSubU32(remaining, splitValue)
  blaiToolchainSetWeiPatchLowerSplitNoBlock

proc blaiToolchainSetWeiPatchLowerSplitEvidence*(
    flagPlan: BlaiToolchainSetWeiPatchLowerFlagPlan,
    splitNumerator: uint32): BlaiToolchainSetWeiPatchLowerSplitEvidence =
  ## Recover lower split page count, selected split, and patch count.
  result.flagPlan = flagPlan
  result.splitNumerator = splitNumerator
  result.pageBytes = BlaiToolchainSetWeiPatchLowerPageBytes
  if not flagPlan.valid or
     flagPlan.flagValue != BlaiToolchainSetWeiPatchLowerFlagValue:
    result.firstBlock = blaiToolchainSetWeiPatchLowerSplitFlagPlan
    return
  if result.pageBytes == 0'u32 or flagPlan.bytePressure == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLowerSplitPageCount
    return
  if splitNumerator == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLowerSplitNumerator
    return

  let pagePlan = blaiToolchainSetWeiPatchPressurePagePlan(
    flagPlan.bytePressure, result.pageBytes)
  if pagePlan.overflow:
    result.firstBlock = blaiToolchainSetWeiPatchLowerSplitOverflow
    return
  if not pagePlan.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLowerSplitPageCount
    return
  result.nonDivisiblePageExtra = pagePlan.nonDivisiblePageExtra
  result.pressurePageCount = pagePlan.pressurePageCount
  if result.pressurePageCount == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLowerSplitPageCount
    return

  result.quotientBeforePowerOfTwo =
    splitNumerator div result.pressurePageCount
  result.selectedSplit =
    blaiToolchainFloorPowerOfTwo(result.quotientBeforePowerOfTwo)
  if result.selectedSplit == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLowerSplitNumerator
    return
  result.patchCount = blaiCeilDivU32(splitNumerator, result.selectedSplit)
  result.firstBlock = blaiToolchainSetWeiPatchLowerSplitNoBlock
  result.valid = true

proc blaiToolchainSetWeiPatchLowerSplitPlanInto*(
    flagPlan: BlaiToolchainSetWeiPatchLowerFlagPlan,
    splitNumerator: uint32,
    outResult: var BlaiToolchainSetWeiPatchLowerSplitPlan) =
  ## Recover lower-pressure patch count and split metadata after flag value 2.
  outResult = default(BlaiToolchainSetWeiPatchLowerSplitPlan)
  outResult.flagPlan = flagPlan
  outResult.splitNumerator = splitNumerator
  let evidence =
    blaiToolchainSetWeiPatchLowerSplitEvidence(flagPlan, splitNumerator)
  outResult.pageBytes = evidence.pageBytes
  outResult.nonDivisiblePageExtra = evidence.nonDivisiblePageExtra
  outResult.pressurePageCount = evidence.pressurePageCount
  outResult.quotientBeforePowerOfTwo = evidence.quotientBeforePowerOfTwo
  outResult.selectedSplit = evidence.selectedSplit
  outResult.patchCount = evidence.patchCount
  if not evidence.valid:
    outResult.firstBlock = evidence.firstBlock
    return
  outResult.firstBlock = blaiToolchainFillLowerFixedSplit(
    splitNumerator, outResult.patchCount, outResult.selectedSplit,
    outResult.splitValues, outResult.splitCount)
  outResult.valid =
    outResult.firstBlock == blaiToolchainSetWeiPatchLowerSplitNoBlock

proc blaiToolchainSetWeiPatchLowerSplitPlan*(
    flagPlan: BlaiToolchainSetWeiPatchLowerFlagPlan,
    splitNumerator: uint32): BlaiToolchainSetWeiPatchLowerSplitPlan =
  ## Convenience wrapper for recovered lower-pressure split metadata.
  blaiToolchainSetWeiPatchLowerSplitPlanInto(
    flagPlan, splitNumerator, result)

proc blaiToolchainSetWeiPatchLowerTotalEvidence*(
    splitPlan: BlaiToolchainSetWeiPatchLowerSplitPlan,
    unitFactor: uint32): BlaiToolchainSetWeiPatchLowerTotalEvidence =
  ## Recover lower split local-byte pressure and PSRAM patch-total arithmetic.
  result.splitPlan = splitPlan
  result.unitFactor = unitFactor
  result.patchSizeBytes = BlaiToolchainPatchSizeBytes
  if not splitPlan.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLowerTotalSplitPlan
    return
  if result.patchSizeBytes == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchLowerTotalPatchSize
    return

  let finalPatchPosition =
    blaiMemAllocFinalPatchSegmentPosition(splitPlan.patchCount)
  if not finalPatchPosition.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLowerTotalSplitPlan
    return
  let lastCursor = blaiWeightPatchCursor(finalPatchPosition.patchIndex)
  if not lastCursor.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLowerTotalSplitPlan
    return
  result.finalSplitValue = splitPlan.splitValues[lastCursor.index]

  let selectedBytes64 =
    unitFactor.uint64 * splitPlan.selectedSplit.uint64
  let remainderBytes64 =
    unitFactor.uint64 * result.finalSplitValue.uint64
  let splitCountBytes64 =
    unitFactor.uint64 * splitPlan.splitNumerator.uint64
  let selectedBytes = blaiToolchainSetWeiPatchU32ScalarAbi(selectedBytes64)
  let remainderBytes = blaiToolchainSetWeiPatchU32ScalarAbi(remainderBytes64)
  let splitCountBytes = blaiToolchainSetWeiPatchU32ScalarAbi(splitCountBytes64)
  if not selectedBytes.valid or
     not remainderBytes.valid or
     not splitCountBytes.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLowerTotalOverflow
    return

  result.selectedLocalBytes = selectedBytes.value
  result.remainderLocalBytes = remainderBytes.value
  result.maxLocalBytes =
    max(result.selectedLocalBytes, result.remainderLocalBytes)
  result.perPatchContribution =
    result.maxLocalBytes div result.patchSizeBytes
  result.splitCountContribution =
    splitCountBytes.value div result.patchSizeBytes
  let total64 =
    result.perPatchContribution.uint64 * splitPlan.patchCount.uint64 +
      result.splitCountContribution.uint64
  let totalPatchCount = blaiToolchainSetWeiPatchU32ScalarAbi(total64)
  if not totalPatchCount.valid:
    result.firstBlock = blaiToolchainSetWeiPatchLowerTotalOverflow
    return
  result.totalPatchCount = totalPatchCount.value
  result.firstBlock = blaiToolchainSetWeiPatchLowerTotalNoBlock
  result.valid = true

proc blaiToolchainSetWeiPatchLowerTotalPlanInto*(
    splitPlan: BlaiToolchainSetWeiPatchLowerSplitPlan,
    unitFactor: uint32,
    outResult: var BlaiToolchainSetWeiPatchLowerTotalPlan) =
  ## Recover PSRAM patch-total metadata after lower-pressure split storage.
  outResult = default(BlaiToolchainSetWeiPatchLowerTotalPlan)
  outResult.splitPlan = splitPlan
  outResult.unitFactor = unitFactor
  let evidence =
    blaiToolchainSetWeiPatchLowerTotalEvidence(splitPlan, unitFactor)
  outResult.patchSizeBytes = evidence.patchSizeBytes
  outResult.finalSplitValue = evidence.finalSplitValue
  outResult.selectedLocalBytes = evidence.selectedLocalBytes
  outResult.remainderLocalBytes = evidence.remainderLocalBytes
  outResult.maxLocalBytes = evidence.maxLocalBytes
  outResult.perPatchContribution = evidence.perPatchContribution
  outResult.splitCountContribution = evidence.splitCountContribution
  outResult.totalPatchCount = evidence.totalPatchCount
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainSetWeiPatchLowerTotalPlan*(
    splitPlan: BlaiToolchainSetWeiPatchLowerSplitPlan,
    unitFactor: uint32): BlaiToolchainSetWeiPatchLowerTotalPlan =
  ## Convenience wrapper for recovered lower-pressure PSRAM patch totals.
  blaiToolchainSetWeiPatchLowerTotalPlanInto(
    splitPlan, unitFactor, result)

proc blaiToolchainSetWeiPatchNoPatchEvidence*(splitNumerator,
    returnedPatchCount: uint32): BlaiToolchainSetWeiPatchNoPatchEvidence =
  ## Recover no-patch metadata when neither split branch is active.
  result.splitNumerator = splitNumerator
  result.returnedPatchCount = returnedPatchCount
  if splitNumerator == 0'u32:
    result.firstBlock = blaiToolchainSetWeiPatchNoPatchNumerator
    return
  result.patchCount = BlaiToolchainSetWeiPatchNoPatchPatchCount
  result.splitCount = BlaiToolchainSetWeiPatchNoPatchSplitCount
  result.splitValues[0] = splitNumerator
  result.psramPatchTotal = BlaiToolchainSetWeiPatchNoPatchPsramPatchTotal
  result.flagValue = BlaiToolchainSetWeiPatchNoPatchFlagValue
  result.firstBlock = blaiToolchainSetWeiPatchNoPatchNoBlock
  result.valid = true

proc blaiToolchainSetWeiPatchNoPatchPlanInto*(
    splitNumerator, returnedPatchCount: uint32,
    outResult: var BlaiToolchainSetWeiPatchNoPatchPlan) =
  ## Recover fall-through `set_wei_patch` metadata when no patch split is used.
  outResult = default(BlaiToolchainSetWeiPatchNoPatchPlan)
  outResult.splitNumerator = splitNumerator
  outResult.returnedPatchCount = returnedPatchCount
  let evidence =
    blaiToolchainSetWeiPatchNoPatchEvidence(splitNumerator, returnedPatchCount)
  outResult.patchCount = evidence.patchCount
  outResult.splitCount = evidence.splitCount
  outResult.splitValues = evidence.splitValues
  outResult.psramPatchTotal = evidence.psramPatchTotal
  outResult.flagValue = evidence.flagValue
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainSetWeiPatchNoPatchPlan*(
    splitNumerator, returnedPatchCount: uint32):
    BlaiToolchainSetWeiPatchNoPatchPlan =
  ## Convenience wrapper for recovered no-patch `set_wei_patch` metadata.
  blaiToolchainSetWeiPatchNoPatchPlanInto(
    splitNumerator, returnedPatchCount, result)

proc blaiToolchainSetWeiPatchBranchSelectionEvidence*(
    largeTotal: BlaiToolchainSetWeiPatchLargeTotalPlan,
    lowerTotal: BlaiToolchainSetWeiPatchLowerTotalPlan,
    noPatch: BlaiToolchainSetWeiPatchNoPatchPlan):
    BlaiToolchainSetWeiPatchBranchSelectionEvidence =
  ## Select the recovered final `set_wei_patch` branch metadata.
  result.largeBranchActive =
    largeTotal.splitPlan.flagPlan.valid and
      largeTotal.splitPlan.flagPlan.flagSet
  result.lowerBranchActive =
    lowerTotal.splitPlan.flagPlan.valid and
      lowerTotal.splitPlan.flagPlan.flagValue ==
        BlaiToolchainSetWeiPatchLowerFlagValue

  if result.largeBranchActive:
    if not largeTotal.valid:
      result.firstBlock = blaiToolchainSetWeiPatchBranchLargeTotal
      return
    result.mode = blaiToolchainSetWeiPatchBranchLarge
    result.patchCount = largeTotal.splitPlan.patchCount
    result.splitCount = largeTotal.splitPlan.splitCount
    result.splitValues = largeTotal.splitPlan.splitValues
    result.psramPatchTotal = largeTotal.totalPatchCount
    result.flagValue = BlaiToolchainSetWeiPatchLargeFlagValue
    result.firstBlock = blaiToolchainSetWeiPatchBranchNoBlock
    result.valid = true
    return

  if result.lowerBranchActive:
    if not lowerTotal.valid:
      result.firstBlock = blaiToolchainSetWeiPatchBranchLowerTotal
      return
    result.mode = blaiToolchainSetWeiPatchBranchLower
    result.patchCount = lowerTotal.splitPlan.patchCount
    result.splitCount = lowerTotal.splitPlan.splitCount
    result.splitValues = lowerTotal.splitPlan.splitValues
    result.psramPatchTotal = lowerTotal.totalPatchCount
    result.flagValue = BlaiToolchainSetWeiPatchLowerFlagValue
    result.firstBlock = blaiToolchainSetWeiPatchBranchNoBlock
    result.valid = true
    return

  if not noPatch.valid:
    result.firstBlock = blaiToolchainSetWeiPatchBranchNoPatchPlan
    return
  result.mode = blaiToolchainSetWeiPatchBranchNoPatch
  result.patchCount = noPatch.patchCount
  result.splitCount = noPatch.splitCount
  result.splitValues = noPatch.splitValues
  result.psramPatchTotal = noPatch.psramPatchTotal
  result.flagValue = noPatch.flagValue
  result.returnedPatchCount = noPatch.returnedPatchCount
  result.firstBlock = blaiToolchainSetWeiPatchBranchNoBlock
  result.valid = true

proc blaiToolchainSetWeiPatchBranchPlanInto*(
    largeTotal: BlaiToolchainSetWeiPatchLargeTotalPlan,
    lowerTotal: BlaiToolchainSetWeiPatchLowerTotalPlan,
    noPatch: BlaiToolchainSetWeiPatchNoPatchPlan,
    outResult: var BlaiToolchainSetWeiPatchBranchPlan) =
  ## Recover branch ordering after `set_wei_patch` pressure gates.
  outResult = default(BlaiToolchainSetWeiPatchBranchPlan)
  outResult.largeTotal = largeTotal
  outResult.lowerTotal = lowerTotal
  outResult.noPatch = noPatch
  let evidence =
    blaiToolchainSetWeiPatchBranchSelectionEvidence(
      largeTotal, lowerTotal, noPatch)
  outResult.largeBranchActive = evidence.largeBranchActive
  outResult.lowerBranchActive = evidence.lowerBranchActive
  outResult.mode = evidence.mode
  outResult.patchCount = evidence.patchCount
  outResult.splitCount = evidence.splitCount
  outResult.splitValues = evidence.splitValues
  outResult.psramPatchTotal = evidence.psramPatchTotal
  outResult.flagValue = evidence.flagValue
  outResult.returnedPatchCount = evidence.returnedPatchCount
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainSetWeiPatchBranchPlan*(
    largeTotal: BlaiToolchainSetWeiPatchLargeTotalPlan,
    lowerTotal: BlaiToolchainSetWeiPatchLowerTotalPlan,
    noPatch: BlaiToolchainSetWeiPatchNoPatchPlan):
    BlaiToolchainSetWeiPatchBranchPlan =
  ## Convenience wrapper for recovered `set_wei_patch` branch ordering.
  blaiToolchainSetWeiPatchBranchPlanInto(
    largeTotal, lowerTotal, noPatch, result)

proc blaiToolchainSetWeiPatchBranchState*(
    mode: BlaiToolchainSetWeiPatchBranchMode,
    patchCount, splitCount: uint32,
    splitValues: array[BlaiMaxWeightPatches, uint32],
    psramPatchTotal, flagValue, returnedPatchCount: uint32):
    BlaiToolchainSetWeiPatchBranchState =
  ## Build a typed caller-owned branch metadata state.
  result.mode = mode
  result.patchCount = patchCount
  result.splitCount = splitCount
  result.splitValues = splitValues
  result.psramPatchTotal = psramPatchTotal
  result.flagValue = flagValue
  result.returnedPatchCount = returnedPatchCount

proc blaiToolchainSetWeiPatchBranchSummaryState*(
    largeBranchActive, lowerBranchActive: bool,
    mode: BlaiToolchainSetWeiPatchBranchMode,
    splitStorageCount, patchCount, splitCount, writesApplied: uint32,
    splitValues: array[BlaiMaxWeightPatches, uint32],
    psramPatchTotal, flagValue, returnedPatchCount: uint32):
    BlaiToolchainSetWeiPatchBranchSummaryState =
  ## Build full diagnostic state for selected branch metadata.
  result.largeBranchActive = largeBranchActive
  result.lowerBranchActive = lowerBranchActive
  result.mode = mode
  result.splitStorageCount = splitStorageCount
  result.patchCount = patchCount
  result.splitCount = splitCount
  result.writesApplied = writesApplied
  result.splitValues = splitValues
  result.psramPatchTotal = psramPatchTotal
  result.flagValue = flagValue
  result.returnedPatchCount = returnedPatchCount

proc blaiToolchainSetWeiPatchBranchApplyEvidence*(
    branch: BlaiToolchainSetWeiPatchBranchPlan,
    splitStorageCount: uint32):
    BlaiToolchainSetWeiPatchBranchApplyEvidence =
  ## Build the checked application evidence for selected branch metadata.
  result.branch = branch
  result.splitStorageCount = splitStorageCount
  if not branch.valid:
    result.firstBlock = blaiToolchainSetWeiPatchBranchApplyBranchPlan
    return
  if branch.splitCount > splitStorageCount:
    result.firstBlock = blaiToolchainSetWeiPatchBranchApplySplitStorage
    return

  result.mode = branch.mode
  result.patchCount = branch.patchCount
  result.splitCount = branch.splitCount
  result.splitValues = branch.splitValues
  result.psramPatchTotal = branch.psramPatchTotal
  result.flagValue = branch.flagValue
  result.returnedPatchCount = branch.returnedPatchCount
  result.stateAfter = blaiToolchainSetWeiPatchBranchState(
    branch.mode, branch.patchCount, branch.splitCount, branch.splitValues,
    branch.psramPatchTotal, branch.flagValue, branch.returnedPatchCount)
  result.writesApplied = branch.splitCount
  result.summaryStateAfter = blaiToolchainSetWeiPatchBranchSummaryState(
    branch.largeBranchActive, branch.lowerBranchActive, branch.mode,
    splitStorageCount, branch.patchCount, branch.splitCount,
    result.writesApplied, branch.splitValues, branch.psramPatchTotal,
    branch.flagValue, branch.returnedPatchCount)
  result.firstBlock = blaiToolchainSetWeiPatchBranchApplyNoBlock
  result.valid = true

proc blaiToolchainSetWeiPatchBranchApplyPlanInto*(
    branch: BlaiToolchainSetWeiPatchBranchPlan,
    splitValues: openArray[uint32],
    outResult: var BlaiToolchainSetWeiPatchBranchApplyPlan) =
  ## Prepare a checked application of selected `set_wei_patch` metadata.
  ##
  ## The converter writes patch count, split entries, PSRAM total, flag, and
  ## return-count metadata after choosing a branch. This plan keeps that as a
  ## typed storage projection and rejects short caller-owned split arrays before
  ## any mutation happens.
  outResult = default(BlaiToolchainSetWeiPatchBranchApplyPlan)
  let evidence = blaiToolchainSetWeiPatchBranchApplyEvidence(
    branch, blaiOpenArrayLenU32(splitValues))
  outResult.branch = evidence.branch
  outResult.splitStorageCount = evidence.splitStorageCount
  outResult.mode = evidence.mode
  outResult.patchCount = evidence.patchCount
  outResult.splitCount = evidence.splitCount
  outResult.splitValues = evidence.splitValues
  outResult.psramPatchTotal = evidence.psramPatchTotal
  outResult.flagValue = evidence.flagValue
  outResult.returnedPatchCount = evidence.returnedPatchCount
  outResult.stateAfter = evidence.stateAfter
  outResult.summaryStateAfter = evidence.summaryStateAfter
  outResult.writesApplied = evidence.writesApplied
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainSetWeiPatchBranchApplyPlan*(
    branch: BlaiToolchainSetWeiPatchBranchPlan,
    splitValues: openArray[uint32]): BlaiToolchainSetWeiPatchBranchApplyPlan =
  ## Convenience wrapper for checked branch metadata application planning.
  blaiToolchainSetWeiPatchBranchApplyPlanInto(branch, splitValues, result)

proc blaiApplyToolchainSetWeiPatchBranchState*(
    state: var BlaiToolchainSetWeiPatchBranchState,
    plan: BlaiToolchainSetWeiPatchBranchApplyPlan): bool =
  ## Apply selected `set_wei_patch` metadata to caller-owned state.
  if not plan.valid:
    return false
  state = plan.stateAfter
  true

proc blaiApplyToolchainSetWeiPatchBranchResultState*(
    patchCount: var uint32,
    splitValues: var openArray[uint32],
    psramPatchTotal, flagValue, returnedPatchCount: var uint32,
    state: BlaiToolchainSetWeiPatchBranchState): bool =
  ## Apply selected `set_wei_patch` result state to caller-owned storage.
  if state.splitCount > blaiOpenArrayLenU32(splitValues):
    return false

  patchCount = state.patchCount
  psramPatchTotal = state.psramPatchTotal
  flagValue = state.flagValue
  returnedPatchCount = state.returnedPatchCount
  for splitIndex in 0'u32 ..< state.splitCount:
    let splitCursor =
      blaiToolchainSetWeiPatchSplitCursor(splitIndex, splitValues.len)
    if not splitCursor.valid:
      return false
    splitValues[splitCursor.index] = state.splitValues[splitCursor.index]
  true

proc blaiApplyToolchainSetWeiPatchBranchScalarState*(
    mode: var BlaiToolchainSetWeiPatchBranchMode,
    patchCount: var uint32,
    splitCount: var uint32,
    psramPatchTotal: var uint32,
    flagValue: var uint32,
    returnedPatchCount: var uint32,
    state: BlaiToolchainSetWeiPatchBranchState): bool =
  ## Apply selected `set_wei_patch` branch scalars from typed state.
  mode = state.mode
  patchCount = state.patchCount
  splitCount = state.splitCount
  psramPatchTotal = state.psramPatchTotal
  flagValue = state.flagValue
  returnedPatchCount = state.returnedPatchCount
  true

proc blaiApplyToolchainSetWeiPatchBranchSummaryScalarState*(
    largeBranchActive, lowerBranchActive: var bool,
    mode: var BlaiToolchainSetWeiPatchBranchMode,
    splitStorageCount, patchCount, splitCount, writesApplied: var uint32,
    psramPatchTotal, flagValue, returnedPatchCount: var uint32,
    state: BlaiToolchainSetWeiPatchBranchSummaryState): bool =
  ## Apply full selected branch summary scalars from typed state.
  largeBranchActive = state.largeBranchActive
  lowerBranchActive = state.lowerBranchActive
  mode = state.mode
  splitStorageCount = state.splitStorageCount
  patchCount = state.patchCount
  splitCount = state.splitCount
  writesApplied = state.writesApplied
  psramPatchTotal = state.psramPatchTotal
  flagValue = state.flagValue
  returnedPatchCount = state.returnedPatchCount
  true

proc blaiApplyToolchainSetWeiPatchBranchScalars*(
    mode: var BlaiToolchainSetWeiPatchBranchMode,
    patchCount: var uint32,
    splitCount: var uint32,
    psramPatchTotal: var uint32,
    flagValue: var uint32,
    returnedPatchCount: var uint32,
    plan: BlaiToolchainSetWeiPatchBranchApplyPlan): bool =
  ## Apply selected `set_wei_patch` branch scalar metadata.
  if not plan.valid:
    return false
  blaiApplyToolchainSetWeiPatchBranchScalarState(
    mode, patchCount, splitCount, psramPatchTotal, flagValue,
    returnedPatchCount, plan.stateAfter)

proc blaiApplyToolchainSetWeiPatchBranchSummaryScalars*(
    largeBranchActive, lowerBranchActive: var bool,
    mode: var BlaiToolchainSetWeiPatchBranchMode,
    splitStorageCount, patchCount, splitCount, writesApplied: var uint32,
    psramPatchTotal, flagValue, returnedPatchCount: var uint32,
    plan: BlaiToolchainSetWeiPatchBranchApplyPlan): bool =
  ## Apply full selected branch summary scalars.
  if not plan.valid:
    return false
  blaiApplyToolchainSetWeiPatchBranchSummaryScalarState(
    largeBranchActive, lowerBranchActive, mode, splitStorageCount,
    patchCount, splitCount, writesApplied, psramPatchTotal, flagValue,
    returnedPatchCount, plan.summaryStateAfter)

proc blaiApplyToolchainSetWeiPatchBranch*(
    patchCount: var uint32,
    splitValues: var openArray[uint32],
    psramPatchTotal, flagValue, returnedPatchCount: var uint32,
    plan: BlaiToolchainSetWeiPatchBranchApplyPlan): bool =
  ## Apply selected `set_wei_patch` metadata to typed caller-owned storage.
  if not plan.valid:
    return false
  blaiApplyToolchainSetWeiPatchBranchResultState(
    patchCount, splitValues, psramPatchTotal, flagValue, returnedPatchCount,
    plan.stateAfter)

proc blaiToolchainSetWeiPatchBranchReturnEvidence*(
    call: BlaiToolchainSetWeiPatchCallPlan,
    branch: BlaiToolchainSetWeiPatchBranchPlan):
    BlaiToolchainSetWeiPatchBranchReturnEvidence =
  ## Build recovered evidence for selected branch to by-ref return state.
  result.call = call
  result.branch = branch
  result.callValid = call.valid
  result.branchValid = branch.valid
  if not call.valid:
    result.firstBlock = blaiToolchainSetWeiPatchBranchReturnCallPlan
    return
  if not branch.valid:
    result.firstBlock = blaiToolchainSetWeiPatchBranchReturnBranchPlan
    return

  let returnedCount = blaiToolchainPatchCountAbi(branch.returnedPatchCount)
  result.returnedPatchCountValid = returnedCount.valid
  if not returnedCount.valid:
    result.firstBlock = blaiToolchainSetWeiPatchBranchReturnReturnedCount
    return

  result.mode = branch.mode
  result.returnedPatchCount = branch.returnedPatchCount
  result.byRefPatchCountInitial = call.byRefPatchCountInitial
  result.byRefPatchCountAfter = returnedCount.value
  result.scratchPatchCount = returnedCount.value
  result.changed =
    result.byRefPatchCountAfter != result.byRefPatchCountInitial
  result.returnPlan =
    blaiToolchainSetWeiPatchReturnPlan(call, result.byRefPatchCountAfter)
  result.returnPlanValid = result.returnPlan.valid
  if not result.returnPlan.valid:
    result.firstBlock = blaiToolchainSetWeiPatchBranchReturnReturnPlan
    return

  result.firstBlock = blaiToolchainSetWeiPatchBranchReturnNoBlock
  result.valid = true

proc blaiToolchainSetWeiPatchBranchReturnPlanInto*(
    call: BlaiToolchainSetWeiPatchCallPlan,
    branch: BlaiToolchainSetWeiPatchBranchPlan,
    outResult: var BlaiToolchainSetWeiPatchBranchReturnPlan) =
  ## Bridge selected `set_wei_patch` branch metadata to the by-ref return path.
  outResult = default(BlaiToolchainSetWeiPatchBranchReturnPlan)
  let evidence = blaiToolchainSetWeiPatchBranchReturnEvidence(call, branch)
  outResult.call = evidence.call
  outResult.branch = evidence.branch
  outResult.evidence = evidence
  outResult.returnPlan = evidence.returnPlan
  outResult.mode = evidence.mode
  outResult.returnedPatchCount = evidence.returnedPatchCount
  outResult.byRefPatchCountInitial = evidence.byRefPatchCountInitial
  outResult.byRefPatchCountAfter = evidence.byRefPatchCountAfter
  outResult.scratchPatchCount = evidence.scratchPatchCount
  outResult.changed = evidence.changed
  outResult.firstBlock = evidence.firstBlock
  outResult.valid = evidence.valid

proc blaiToolchainSetWeiPatchBranchReturnPlan*(
    call: BlaiToolchainSetWeiPatchCallPlan,
    branch: BlaiToolchainSetWeiPatchBranchPlan):
    BlaiToolchainSetWeiPatchBranchReturnPlan =
  ## Convenience wrapper for selected branch to return-state projection.
  blaiToolchainSetWeiPatchBranchReturnPlanInto(call, branch, result)

proc blaiMemAllocRouteKernelPadding*(
    midOut, routed: bool,
    dilation, size: uint32): uint32 =
  ## Recover route/mid-output kernel padding used by line-patch pressure.
  if not (midOut and routed):
    return BlaiMemAllocRouteKernelNoPadding
  if dilation > BlaiMemAllocRouteKernelDilationThreshold:
    return BlaiMemAllocRouteKernelExpandedPadding
  if size <= BlaiMemAllocRouteKernelSmallSizeLimit:
    return BlaiMemAllocRouteKernelSmallPadding
  BlaiMemAllocRouteKernelExpandedPadding

proc blaiMemAllocLinePatchProbe*(
    layer: BlaiCpuInstLayer64,
    patchCount, routeChannels: uint32,
    routed, upsampleLayer: bool): BlaiMemAllocLinePatchProbe =
  ## Recover one candidate byte-pressure check from the line-patch search.
  if patchCount == 0'u32:
    return
  let
    inputWidth = nonNegativeU32(layer.w)
    outputWidth = nonNegativeU32(layer.outW)
    outputChannels = nonNegativeU32(layer.outC)
    midOut = layer.midOut == 1
  result.patchCount = patchCount
  result.inputLine = blaiRoundEvenU32(blaiCeilDivU32(inputWidth, patchCount))
  result.outputLineBase =
    if upsampleLayer:
      result.inputLine * BlaiMemAllocLinePatchUpsampleScale
    else:
      blaiRoundEvenU32(blaiCeilDivU32(outputWidth, patchCount))
  result.routeKernelPadding = blaiMemAllocRouteKernelPadding(
    midOut, routed, nonNegativeU32(layer.dilation), nonNegativeU32(layer.size))
  result.inputLineBytes = (result.inputLine + result.routeKernelPadding) *
    routeChannels
  result.outputBytes = result.outputLineBase * outputChannels
  result.routeBytes = result.inputLine * routeChannels
  result.outputLineBytes = max(result.outputBytes, result.routeBytes)
  result.fits =
    result.inputLineBytes <= BlaiNpuLocalBufferBytes and
    result.outputLineBytes <= BlaiNpuLocalBufferBytes

proc blaiMemAllocLinePatchSelectionEvidence*(
    layer: BlaiCpuInstLayer64,
    startPatchCount, inputWidth, routeChannels: uint32,
    routed, upsampleLayer: bool): BlaiMemAllocLinePatchSelectionEvidence =
  ## Select the recovered line-patch split metadata for one allocator layer.
  result.startPatchCount = startPatchCount
  result.inputWidth = inputWidth
  if startPatchCount <= 1'u32:
    if inputWidth <= BlaiNpuLocalBufferBytes:
      result.fits = true
      result.linePatchCount = 1
      result.linePatchW[0] = inputWidth
    return

  let stopPatchCount = startPatchCount + BlaiMemAllocSearchSlack
  for patchCount in startPatchCount ..< stopPatchCount:
    let probe = blaiMemAllocLinePatchProbe(
      layer, patchCount, routeChannels, routed, upsampleLayer)
    if probe.fits:
      result.fits = true
      result.linePatchCount = patchCount
      result.inputLineBytes = probe.inputLineBytes
      result.outputLineBytes = probe.outputLineBytes
      var remaining = inputWidth
      for patchIndex in 0'u32 ..< min(patchCount, BlaiMaxWeightPatchesU32):
        let patchSegment =
          blaiMemAllocPatchSegmentCursor(patchIndex, patchCount)
        if not patchSegment.valid:
          return
        let patchWidth =
          if patchSegment.last:
            remaining
          else:
            probe.inputLine
        result.linePatchW[patchSegment.patchSlot] = patchWidth
        remaining = blaiSaturatingSubU32(remaining, probe.inputLine)
      break

proc blaiPlanLinePatchMemAllocInto*(layer: BlaiCpuInstLayer64,
                                    outResult: var BlaiMemAllocLinePatchPlan,
                                    upsampleLayer: bool = false) =
  ## Recover the bounded `BLAI_MEM_alloc` line-patch search and stores.
  ##
  ## The SDK starts from the larger 4 KiB input/output split count, then tries
  ## up to 128 wider split counts. This helper mirrors that search and the
  ## resulting `line_patch_num` / `line_patch_w[]` writes. The later weight and
  ## PSRAM patch branches remain separate recovered helpers.
  outResult = default(BlaiMemAllocLinePatchPlan)
  let
    route = blaiMemAllocRouteChannels(layer)
    inputWidth = nonNegativeU32(layer.w)
  blaiPlanMemAllocStartPatchInto(layer, outResult.start)
  outResult.startPatchCount = outResult.start.startPatchCount
  let selection = blaiMemAllocLinePatchSelectionEvidence(
    layer, outResult.startPatchCount, inputWidth, route.channels, route.routed,
    upsampleLayer)
  outResult.fits = selection.fits
  outResult.linePatchCount = selection.linePatchCount
  outResult.linePatchW = selection.linePatchW
  outResult.inputLineBytes = selection.inputLineBytes
  outResult.outputLineBytes = selection.outputLineBytes

proc blaiPlanLinePatchMemAlloc*(layer: BlaiCpuInstLayer64,
                                upsampleLayer: bool = false): BlaiMemAllocLinePatchPlan =
  ## Convenience result-returning wrapper for line-patch allocator planning.
  blaiPlanLinePatchMemAllocInto(layer, result, upsampleLayer)

proc blaiMemAllocLinePatchApplyEvidence*(
    plan: BlaiMemAllocLinePatchPlan): BlaiMemAllocLinePatchApplyEvidence =
  ## Project recovered line-patch stores through the SDK signed-field ABI.
  if not plan.fits:
    return
  let linePatchCount = blaiAllocatorFieldAbi(plan.linePatchCount)
  if not linePatchCount.valid:
    return
  result.linePatchCount = linePatchCount.value
  for patchIndex in 0'u32 ..< BlaiMaxWeightPatchesU32:
    let patchCursor = blaiWeightPatchCursor(patchIndex)
    if not patchCursor.valid:
      return default(BlaiMemAllocLinePatchApplyEvidence)
    let lineWidth = blaiAllocatorFieldAbi(plan.linePatchW[patchCursor.index])
    if not lineWidth.valid:
      return default(BlaiMemAllocLinePatchApplyEvidence)
    result.linePatchW[patchCursor.index] = lineWidth.value
  result.valid = true

proc blaiMemAllocLinePatchApplyPlan*(
    plan: BlaiMemAllocLinePatchPlan): BlaiMemAllocLinePatchApplyPlan =
  ## Recover checked line-patch allocator stores before mutating `PSRAM_ctrl`.
  let evidence = blaiMemAllocLinePatchApplyEvidence(plan)
  result.linePatchCount = evidence.linePatchCount
  result.linePatchW = evidence.linePatchW
  result.valid = evidence.valid

proc blaiMemAllocLinePatchState*(
    linePatchCount: int32,
    linePatchW: array[BlaiMaxWeightPatches, int32]):
    BlaiMemAllocLinePatchState =
  ## Build caller-owned state for line-patch allocator stores.
  result.linePatchCount = linePatchCount
  result.linePatchW = linePatchW

proc blaiMemAllocLinePatchState*(
    plan: BlaiMemAllocLinePatchApplyPlan): BlaiMemAllocLinePatchState =
  ## Project a valid line-patch apply plan into caller-owned state.
  doAssert plan.valid
  blaiMemAllocLinePatchState(plan.linePatchCount, plan.linePatchW)

proc blaiApplyLinePatchMemAllocState*(
  ctrl: var BlaiPsramCtrl,
    state: BlaiMemAllocLinePatchState) =
  ## Apply line-patch allocator state to `PSRAM_ctrl`.
  ctrl.linePatchCount = state.linePatchCount
  for patchIndex in 0'u32 ..< BlaiMaxWeightPatchesU32:
    let patchCursor = blaiWeightPatchCursor(patchIndex)
    doAssert patchCursor.valid
    ctrl.linePatchW[patchCursor.index] =
      state.linePatchW[patchCursor.index]

proc blaiApplyLinePatchMemAllocScalarState*(
    linePatchCount: var int32,
    state: BlaiMemAllocLinePatchState): bool =
  ## Apply recovered line-patch scalar metadata from typed state.
  linePatchCount = state.linePatchCount
  true

proc blaiApplyLinePatchMemAllocScalars*(
    linePatchCount: var int32,
    plan: BlaiMemAllocLinePatchApplyPlan): bool =
  ## Apply recovered line-patch scalar metadata.
  if not plan.valid:
    return false
  blaiApplyLinePatchMemAllocScalarState(
    linePatchCount, blaiMemAllocLinePatchState(plan))

proc blaiApplyLinePatchMemAlloc*(ctrl: var BlaiPsramCtrl,
                                 plan: BlaiMemAllocLinePatchPlan) =
  ## Apply recovered `line_patch_num` and `line_patch_w[]` allocator stores.
  let applyPlan = blaiMemAllocLinePatchApplyPlan(plan)
  doAssert applyPlan.valid
  blaiApplyLinePatchMemAllocState(
    ctrl, blaiMemAllocLinePatchState(applyPlan))

proc blaiMemAllocWeightPatchPressure*(
    layer: BlaiCpuInstLayer64): BlaiMemAllocWeightPatchPressure =
  ## Recover the weight pressure expression used by `BLAI_MEM_alloc`.
  let
    route = blaiMemAllocRouteChannels(layer)
    layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.layerType = layerType
  result.routed = route.routed
  result.routeChannels = route.channels
  result.outputChannels = nonNegativeU32(layer.outC)
  result.groups = max(nonNegativeU32(layer.groups), 1'u32)
  result.size = nonNegativeU32(layer.size)
  result.dilation = nonNegativeU32(layer.dilation)
  result.channelProduct = result.routeChannels * result.outputChannels
  if result.size == BlaiMemAllocWeightPressureOneByOneKernelSize:
    result.mode = blaiWeightPressureOneByOne
    result.bytes = result.channelProduct div
      (result.groups * BlaiMemAllocWeightPressureOneByOneGroupFactor)
  elif result.dilation > BlaiMemAllocWeightPressureDilationThreshold or
       result.size > BlaiMemAllocWeightPressureSmallKernelLimit:
    result.mode = blaiWeightPressureDilatedOrLarge
    result.bytes =
      (BlaiMemAllocWeightPressureLargeSpatialFactor * result.channelProduct) div
        result.groups
  else:
    result.mode = blaiWeightPressureSmallKernel
    result.bytes =
      (result.size * result.channelProduct * result.size) div
      (BlaiMemAllocWeightPressureLargeSpatialFactor * result.groups)

proc blaiEstimateWeightPatchBytes*(layer: BlaiCpuInstLayer64): uint32 =
  ## Compatibility wrapper for the recovered weight pressure byte estimate.
  blaiMemAllocWeightPatchPressure(layer).bytes

proc blaiMemAllocLineFloorBytes*(
    width, linePatchCount, channels: uint32): uint32 =
  ## Recovered floor-divided line byte pressure used by PSRAM patch estimates.
  if linePatchCount == 0'u32:
    return 0'u32
  (width div linePatchCount) * channels

proc blaiMemAllocPatchStoreSize*(
    outputPatchBytes, fullPatchBytes: uint32,
    midChannelBytes: uint32 = 0'u32,
    midFullBytes: uint32 = 0'u32): uint32 =
  ## Recovered max-selection for one weight patch's PSRAM patch size.
  max(max(outputPatchBytes, fullPatchBytes), max(midChannelBytes, midFullBytes))

proc blaiMemAllocHighWeightBranchActive*(estimatedWeightBytes: uint32): bool =
  ## Recovered high-weight branch gate after line splitting.
  estimatedWeightBytes > BlaiMemAllocWeightPatchThresholdBytes

proc blaiMemAllocPsramPatchBranchActive*(
    estimatedWeightBytes, estimatedPsramBytes: uint32): bool =
  ## Recovered lower-threshold PSRAM patch branch gate after line splitting.
  estimatedWeightBytes <= BlaiMemAllocWeightPatchThresholdBytes and
    estimatedPsramBytes > BlaiMemAllocPsramPatchThresholdBytes

proc blaiMemAllocOutputChannelPatchWidth*(
    outputChannels, initialPatches: uint32): uint32 =
  ## Recover power-of-two output-channel patch width with SDK minimum clamp.
  let outputPerPatchBase =
    blaiFloorPow2U32(outputChannels div max(initialPatches, 1'u32))
  max(outputPerPatchBase, 1'u32)

proc blaiMemAllocPsramPatchPressure*(
    layer: BlaiCpuInstLayer64,
    linePlan: BlaiMemAllocLinePatchPlan): BlaiMemAllocPsramPatchPressure =
  ## Recover the lower-threshold PSRAM pressure expression in `BLAI_MEM_alloc`.
  if not linePlan.fits or linePlan.linePatchCount == 0'u32:
    return
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.linePatchCount = linePlan.linePatchCount
  result.outputChannels = nonNegativeU32(layer.outC)
  result.outputWidth = nonNegativeU32(layer.outW)
  result.inputWidth = nonNegativeU32(layer.w)
  result.baseBytes = blaiMemAllocLineFloorBytes(
    result.outputWidth, result.linePatchCount, result.outputChannels)
  result.bytes = result.baseBytes
  result.valid = true
  if result.layerType == blaiConvMax:
    result.convMaxFloorBytes = blaiMemAllocLineFloorBytes(
      result.inputWidth, result.linePatchCount, result.outputWidth)
    result.bytes = max(result.bytes, result.convMaxFloorBytes)

proc blaiEstimatePsramPatchBytes*(layer: BlaiCpuInstLayer64,
                                  linePlan: BlaiMemAllocLinePatchPlan): uint32 =
  ## Compatibility wrapper for the recovered PSRAM pressure byte estimate.
  blaiMemAllocPsramPatchPressure(layer, linePlan).bytes

proc blaiMemAllocWeightPatchStoreEntry*(
    patchIndex, weightPatchCount, emittedChannels, outputChannels,
    outputChannelPatch, outputElements, inputElements: uint32,
    midOut: bool): BlaiMemAllocWeightPatchStoreEntry =
  ## Recover one `wei_patch_out_c[]` write and PSRAM patch-size contribution.
  let patchSegment = blaiMemAllocPatchSegmentCursor(patchIndex, weightPatchCount)
  if not patchSegment.valid:
    return
  result.patchIndex = patchIndex
  result.patchSlot = patchSegment.patchSlot
  result.last = patchSegment.last
  result.emittedChannels = emittedChannels
  result.remainingChannels =
    blaiSaturatingSubU32(outputChannels, emittedChannels)
  result.outputChannelPatch = outputChannelPatch
  result.patchOutC =
    if result.last:
      result.remainingChannels
    else:
      min(outputChannelPatch, result.remainingChannels)
  if result.patchOutC == 0'u32:
    return
  result.outputPatchBytes = result.patchOutC * outputElements
  result.fullPatchBytes = outputChannelPatch * outputElements
  if midOut:
    result.midChannelBytes = result.patchOutC * inputElements
    result.midFullBytes = outputChannelPatch * inputElements
  result.psramPatchSize = blaiMemAllocPatchStoreSize(
    result.outputPatchBytes, result.fullPatchBytes,
    result.midChannelBytes, result.midFullBytes)
  result.nextEmittedChannels = emittedChannels + result.patchOutC
  result.valid = true

proc blaiMemAllocMidPatchElements*(
    layerType: BlaiLayerType,
    inputElements, outputChannels, routeChannels: uint32): uint32 =
  ## Recover mid-output element basis for final PSRAM mid-patch counts.
  if layerType == blaiConvMax:
    inputElements * outputChannels
  else:
    inputElements * routeChannels

proc blaiMemAllocPsramPatchCount*(
    outputChannels, outputElements, psramPatchSize,
    weightPatchCount: uint32): uint32 =
  ## Recover final PSRAM patch count contribution after patch-size selection.
  if psramPatchSize == 0'u32:
    return 0'u32
  (outputChannels * outputElements) div psramPatchSize + weightPatchCount

proc blaiMemAllocPsramMidPatchCount*(
    midElements, psramPatchSize, weightPatchCount: uint32,
    convMaxMidPatchExtra: bool): uint32 =
  ## Recover optional PSRAM mid-patch count after patch-size selection.
  if psramPatchSize == 0'u32:
    return 0'u32
  result = midElements div psramPatchSize
  if convMaxMidPatchExtra:
    result += weightPatchCount

proc blaiMemAllocPatchCountPlan*(
    layerType: BlaiLayerType,
    outputChannels, outputElements, inputElements, routeChannels,
    weightPatchCount, psramPatchSize: uint32,
    midOut: bool): BlaiMemAllocPatchCountPlan =
  ## Recover final `PSRAM_patch_num` and optional mid-patch count stores.
  if psramPatchSize == 0'u32:
    return
  result.layerType = layerType
  result.outputChannels = outputChannels
  result.outputElements = outputElements
  result.inputElements = inputElements
  result.routeChannels = routeChannels
  result.weightPatchCount = weightPatchCount
  result.psramPatchSize = psramPatchSize
  result.psramPatchCount = blaiMemAllocPsramPatchCount(
    outputChannels, outputElements, psramPatchSize, weightPatchCount)
  if midOut:
    result.midElements = blaiMemAllocMidPatchElements(
      layerType, inputElements, outputChannels, routeChannels)
    result.convMaxMidPatchExtra = layerType == blaiConvMax
    result.psramMidPatchCount = blaiMemAllocPsramMidPatchCount(
      result.midElements, psramPatchSize, weightPatchCount,
      result.convMaxMidPatchExtra)
  result.valid = true

proc blaiFillPatchStores(layer: BlaiCpuInstLayer64,
                         initialPatches: uint32,
                         result: var BlaiMemAllocWeightPatchPlan) =
  let
    outputChannels = nonNegativeU32(layer.outC)
    outputElements = nonNegativeU32(layer.outW) * nonNegativeU32(layer.outH)
    inputElements = nonNegativeU32(layer.w) * nonNegativeU32(layer.h)
    route = blaiMemAllocRouteChannels(layer)
  result.outputChannelPatch =
    blaiMemAllocOutputChannelPatchWidth(outputChannels, initialPatches)
  result.weightPatchCount = blaiCeilDivU32(outputChannels, result.outputChannelPatch)
  result.active = true
  if result.weightPatchCount == 0'u32 or
     result.weightPatchCount > BlaiMaxWeightPatchesU32:
    return

  var emittedChannels = 0'u32
  for patchIndex in 0'u32 ..< result.weightPatchCount:
    let patchStore = blaiMemAllocWeightPatchStoreEntry(
      patchIndex, result.weightPatchCount, emittedChannels, outputChannels,
      result.outputChannelPatch, outputElements, inputElements,
      layer.midOut == 1)
    if not patchStore.valid:
      return
    result.weightPatchOutC[patchStore.patchSlot] = patchStore.patchOutC
    result.psramPatchSize = patchStore.psramPatchSize
    emittedChannels = patchStore.nextEmittedChannels

  let countPlan = blaiMemAllocPatchCountPlan(
    blaiLayerTypeFromSdk(layer.layerType), outputChannels, outputElements,
    inputElements, route.channels, result.weightPatchCount,
    result.psramPatchSize, layer.midOut == 1)
  if not countPlan.valid:
    return
  result.psramPatchCount = countPlan.psramPatchCount
  result.psramMidPatchCount = countPlan.psramMidPatchCount
  result.fits = true

proc blaiPlanHighWeightPatchMemAllocInto*(layer: BlaiCpuInstLayer64,
                                          linePlan: BlaiMemAllocLinePatchPlan,
                                          outResult: var BlaiMemAllocWeightPatchPlan) =
  ## Recover the high-weight patch branch after line splitting.
  ##
  ## The SDK enters this branch when the estimated weight pressure exceeds the
  ## recovered 8192-byte threshold and the layer is weight-bearing. It chooses a
  ## power-of-two output-channel patch width, stores every `wei_patch_out_c[]`
  ## entry, then leaves the global PSRAM patch fields set from the final patch.
  outResult = default(BlaiMemAllocWeightPatchPlan)
  outResult.estimatedWeightBytes = blaiEstimateWeightPatchBytes(layer)
  if not linePlan.fits or
     not blaiUsesWeights(blaiLayerTypeFromSdk(layer.layerType)) or
     not blaiMemAllocHighWeightBranchActive(outResult.estimatedWeightBytes):
    return

  blaiFillPatchStores(layer,
    blaiCeilDivU32(outResult.estimatedWeightBytes,
                   BlaiMemAllocWeightPatchThresholdBytes),
    outResult)

proc blaiPlanHighWeightPatchMemAlloc*(layer: BlaiCpuInstLayer64,
                                      linePlan: BlaiMemAllocLinePatchPlan): BlaiMemAllocWeightPatchPlan =
  ## Convenience result-returning wrapper for high-weight patch planning.
  blaiPlanHighWeightPatchMemAllocInto(layer, linePlan, result)

proc blaiPlanPsramPatchMemAllocInto*(layer: BlaiCpuInstLayer64,
                                     linePlan: BlaiMemAllocLinePatchPlan,
                                     outResult: var BlaiMemAllocWeightPatchPlan) =
  ## Recover the lower-threshold PSRAM patch branch after line splitting.
  outResult = default(BlaiMemAllocWeightPatchPlan)
  outResult.estimatedWeightBytes = blaiEstimateWeightPatchBytes(layer)
  outResult.estimatedPsramBytes = blaiEstimatePsramPatchBytes(layer, linePlan)
  if not linePlan.fits or
     not blaiUsesWeights(blaiLayerTypeFromSdk(layer.layerType)) or
     not blaiMemAllocPsramPatchBranchActive(
       outResult.estimatedWeightBytes, outResult.estimatedPsramBytes):
    return

  blaiFillPatchStores(layer,
    blaiCeilDivU32(outResult.estimatedPsramBytes,
                   BlaiMemAllocPsramPatchThresholdBytes),
    outResult)

proc blaiPlanPsramPatchMemAlloc*(layer: BlaiCpuInstLayer64,
                                 linePlan: BlaiMemAllocLinePatchPlan): BlaiMemAllocWeightPatchPlan =
  ## Convenience result-returning wrapper for PSRAM patch planning.
  blaiPlanPsramPatchMemAllocInto(layer, linePlan, result)

proc blaiMemAllocWeightPatchApplyEvidence*(
    plan: BlaiMemAllocWeightPatchPlan): BlaiMemAllocWeightPatchApplyEvidence =
  ## Project recovered weight/PSRAM patch stores through signed-field ABI.
  if not plan.fits or not plan.active:
    return
  let
    weightPatchCount = blaiAllocatorFieldAbi(plan.weightPatchCount)
    psramPatchSize = blaiAllocatorFieldAbi(plan.psramPatchSize)
    psramPatchCount = blaiAllocatorFieldAbi(plan.psramPatchCount)
    psramMidPatchCount = blaiAllocatorFieldAbi(plan.psramMidPatchCount)
  if not weightPatchCount.valid or not psramPatchSize.valid or
     not psramPatchCount.valid or not psramMidPatchCount.valid:
    return
  result.weightPatchCount = weightPatchCount.value
  for patchIndex in 0'u32 ..< BlaiMaxWeightPatchesU32:
    let patchCursor = blaiWeightPatchCursor(patchIndex)
    if not patchCursor.valid:
      return default(BlaiMemAllocWeightPatchApplyEvidence)
    let patchOutC =
      blaiAllocatorFieldAbi(plan.weightPatchOutC[patchCursor.index])
    if not patchOutC.valid:
      return default(BlaiMemAllocWeightPatchApplyEvidence)
    result.weightPatchOutC[patchCursor.index] = patchOutC.value
  result.psramPatchSize = psramPatchSize.value
  result.psramPatchCount = psramPatchCount.value
  result.psramMidPatchCount = psramMidPatchCount.value
  result.valid = true

proc blaiMemAllocWeightPatchApplyPlan*(
    plan: BlaiMemAllocWeightPatchPlan): BlaiMemAllocWeightPatchApplyPlan =
  ## Recover checked weight/PSRAM patch stores before mutating `PSRAM_ctrl`.
  let evidence = blaiMemAllocWeightPatchApplyEvidence(plan)
  result.weightPatchCount = evidence.weightPatchCount
  result.weightPatchOutC = evidence.weightPatchOutC
  result.psramPatchSize = evidence.psramPatchSize
  result.psramPatchCount = evidence.psramPatchCount
  result.psramMidPatchCount = evidence.psramMidPatchCount
  result.valid = evidence.valid

proc blaiMemAllocWeightPatchState*(
    weightPatchCount: int32,
    weightPatchOutC: array[BlaiMaxWeightPatches, int32],
    psramPatchSize: int32,
    psramPatchCount: int32,
    psramMidPatchCount: int32): BlaiMemAllocWeightPatchState =
  ## Build caller-owned state for weight/PSRAM patch allocator stores.
  result.weightPatchCount = weightPatchCount
  result.weightPatchOutC = weightPatchOutC
  result.psramPatchSize = psramPatchSize
  result.psramPatchCount = psramPatchCount
  result.psramMidPatchCount = psramMidPatchCount

proc blaiMemAllocWeightPatchState*(
    plan: BlaiMemAllocWeightPatchApplyPlan): BlaiMemAllocWeightPatchState =
  ## Project a valid weight/PSRAM patch apply plan into caller-owned state.
  doAssert plan.valid
  blaiMemAllocWeightPatchState(
    plan.weightPatchCount, plan.weightPatchOutC, plan.psramPatchSize,
    plan.psramPatchCount, plan.psramMidPatchCount)

proc blaiApplyHighWeightPatchMemAllocState*(
  ctrl: var BlaiPsramCtrl,
    state: BlaiMemAllocWeightPatchState) =
  ## Apply weight/PSRAM patch allocator state to `PSRAM_ctrl`.
  ctrl.weightPatchCount = state.weightPatchCount
  for patchIndex in 0'u32 ..< BlaiMaxWeightPatchesU32:
    let patchCursor = blaiWeightPatchCursor(patchIndex)
    doAssert patchCursor.valid
    ctrl.weightPatchOutC[patchCursor.index] =
      state.weightPatchOutC[patchCursor.index]
  ctrl.psramPatchSize = state.psramPatchSize
  ctrl.psramPatchCount = state.psramPatchCount
  ctrl.psramMidPatchCount = state.psramMidPatchCount

proc blaiApplyWeightPatchMemAllocScalarState*(
    weightPatchCount: var int32,
    psramPatchSize: var int32,
    psramPatchCount: var int32,
    psramMidPatchCount: var int32,
    state: BlaiMemAllocWeightPatchState): bool =
  ## Apply recovered weight/PSRAM patch scalar metadata from typed state.
  weightPatchCount = state.weightPatchCount
  psramPatchSize = state.psramPatchSize
  psramPatchCount = state.psramPatchCount
  psramMidPatchCount = state.psramMidPatchCount
  true

proc blaiApplyWeightPatchMemAllocScalars*(
    weightPatchCount: var int32,
    psramPatchSize: var int32,
    psramPatchCount: var int32,
    psramMidPatchCount: var int32,
    plan: BlaiMemAllocWeightPatchApplyPlan): bool =
  ## Apply recovered weight/PSRAM patch scalar metadata.
  if not plan.valid:
    return false
  blaiApplyWeightPatchMemAllocScalarState(
    weightPatchCount, psramPatchSize, psramPatchCount, psramMidPatchCount,
    blaiMemAllocWeightPatchState(plan))

proc blaiApplyHighWeightPatchMemAlloc*(ctrl: var BlaiPsramCtrl,
                                       plan: BlaiMemAllocWeightPatchPlan) =
  ## Apply recovered high-weight patch stores to `PSRAM_ctrl`.
  let applyPlan = blaiMemAllocWeightPatchApplyPlan(plan)
  doAssert applyPlan.valid
  blaiApplyHighWeightPatchMemAllocState(
    ctrl, blaiMemAllocWeightPatchState(applyPlan))

proc blaiMemAllocPatchBranchEvidence*(
    layer: BlaiCpuInstLayer64,
    linePlan: BlaiMemAllocLinePatchPlan): BlaiMemAllocPatchBranchEvidence =
  ## Select high-weight patching before lower-threshold PSRAM patching.
  var patchPlan: BlaiMemAllocWeightPatchPlan
  blaiPlanHighWeightPatchMemAllocInto(layer, linePlan, patchPlan)
  if patchPlan.fits:
    result.branch = blaiMemAllocHighWeightPatch
    result.patch = patchPlan
    result.valid = true
    return

  blaiPlanPsramPatchMemAllocInto(layer, linePlan, patchPlan)
  if patchPlan.fits:
    result.branch = blaiMemAllocPsramPatch
    result.patch = patchPlan
    result.valid = true

proc blaiPlanPatchMemAllocBranchInto*(layer: BlaiCpuInstLayer64,
                                      linePlan: BlaiMemAllocLinePatchPlan,
                                      outResult: var BlaiMemAllocPatchBranchPlan) =
  ## Recover the selected weight/PSRAM patch allocator branch after line split.
  outResult = default(BlaiMemAllocPatchBranchPlan)
  let evidence = blaiMemAllocPatchBranchEvidence(layer, linePlan)
  outResult.branch = evidence.branch
  outResult.patch = evidence.patch
  outResult.valid = evidence.valid

proc blaiPlanPatchMemAllocBranch*(
    layer: BlaiCpuInstLayer64,
    linePlan: BlaiMemAllocLinePatchPlan): BlaiMemAllocPatchBranchPlan =
  ## Convenience result-returning wrapper for patch-branch selection.
  blaiPlanPatchMemAllocBranchInto(layer, linePlan, result)

proc blaiPlanMemAllocInto*(layer: BlaiCpuInstLayer64,
                           outResult: var BlaiMemAllocPlan) =
  ## Compose the recovered `BLAI_MEM_alloc` branch decisions.
  ##
  ## This is still bounded to the recovered branch set: line split search,
  ## high-weight patching, lower-threshold PSRAM patching, and the one-patch
  ## fallback. The caller applies the selected branch to a typed `BlaiPsramCtrl`.
  outResult = default(BlaiMemAllocPlan)
  blaiPlanLinePatchMemAllocInto(
    layer, outResult.line,
    blaiIsUpsample(blaiLayerTypeFromSdk(layer.layerType)))
  if not outResult.line.fits:
    outResult.branch = blaiMemAllocFailed
    return

  let patchBranch = blaiPlanPatchMemAllocBranch(layer, outResult.line)
  if patchBranch.valid:
    outResult.branch = patchBranch.branch
    outResult.patch = patchBranch.patch
    outResult.fits = true
    return

  blaiPlanSinglePatchMemAllocInto(layer, outResult.single)
  outResult.branch = blaiMemAllocSinglePatch
  outResult.fits = true

proc blaiPlanMemAlloc*(layer: BlaiCpuInstLayer64): BlaiMemAllocPlan =
  ## Convenience result-returning wrapper for recovered `BLAI_MEM_alloc`.
  blaiPlanMemAllocInto(layer, result)

proc blaiMemAllocControlApplyEvidence*(
    plan: BlaiMemAllocPlan): BlaiMemAllocControlApplyEvidence =
  ## Select and validate the recovered composed allocator apply branch.
  if not plan.fits:
    return
  result.branch = plan.branch
  case plan.branch
  of blaiMemAllocFailed:
    discard
  of blaiMemAllocSinglePatch:
    result.single = blaiMemAllocSinglePatchApplyPlan(plan.single)
    result.valid = result.single.valid
  of blaiMemAllocHighWeightPatch, blaiMemAllocPsramPatch:
    result.line = blaiMemAllocLinePatchApplyPlan(plan.line)
    result.patch = blaiMemAllocWeightPatchApplyPlan(plan.patch)
    result.valid = result.line.valid and result.patch.valid

proc blaiMemAllocControlApplyPlan*(
    plan: BlaiMemAllocPlan): BlaiMemAllocControlApplyPlan =
  ## Recover checked `PSRAM_ctrl` stores for the selected allocator branch.
  let evidence = blaiMemAllocControlApplyEvidence(plan)
  result.branch = evidence.branch
  result.line = evidence.line
  result.single = evidence.single
  result.patch = evidence.patch
  result.valid = evidence.valid

proc blaiMemAllocControlState*(
    applyPlan: BlaiMemAllocControlApplyPlan): BlaiMemAllocControlState =
  ## Project a valid composed allocator apply plan into caller-owned state.
  doAssert applyPlan.valid
  result.branch = applyPlan.branch
  case applyPlan.branch
  of blaiMemAllocFailed:
    doAssert false
  of blaiMemAllocSinglePatch:
    result.single = blaiMemAllocSinglePatchState(applyPlan.single)
  of blaiMemAllocHighWeightPatch, blaiMemAllocPsramPatch:
    result.line = blaiMemAllocLinePatchState(applyPlan.line)
    result.patch = blaiMemAllocWeightPatchState(applyPlan.patch)

proc blaiApplyMemAllocControlState*(
    ctrl: var BlaiPsramCtrl,
    state: BlaiMemAllocControlState) =
  ## Apply composed allocator state to `PSRAM_ctrl`.
  case state.branch
  of blaiMemAllocFailed:
    doAssert false
  of blaiMemAllocSinglePatch:
    blaiApplySinglePatchMemAllocState(ctrl, state.single)
  of blaiMemAllocHighWeightPatch, blaiMemAllocPsramPatch:
    blaiApplyLinePatchMemAllocState(ctrl, state.line)
    blaiApplyHighWeightPatchMemAllocState(ctrl, state.patch)

proc blaiApplyMemAllocControlBranchState*(
    branch: var BlaiMemAllocBranch,
    state: BlaiMemAllocControlState): bool =
  ## Apply selected allocator branch metadata from typed state.
  branch = state.branch
  true

proc blaiApplyMemAllocControlBranch*(
    branch: var BlaiMemAllocBranch,
    applyPlan: BlaiMemAllocControlApplyPlan): bool =
  ## Apply selected allocator branch metadata.
  if not applyPlan.valid:
    return false
  blaiApplyMemAllocControlBranchState(
    branch, blaiMemAllocControlState(applyPlan))

proc blaiApplyMemAllocControlApplyPlan*(
    ctrl: var BlaiPsramCtrl,
    applyPlan: BlaiMemAllocControlApplyPlan) =
  ## Apply pre-checked allocator stores to `PSRAM_ctrl`.
  doAssert applyPlan.valid
  blaiApplyMemAllocControlState(ctrl, blaiMemAllocControlState(applyPlan))

proc blaiApplyMemAllocPlan*(ctrl: var BlaiPsramCtrl,
                            plan: BlaiMemAllocPlan) =
  ## Apply a selected recovered `BLAI_MEM_alloc` branch to `PSRAM_ctrl`.
  let applyPlan = blaiMemAllocControlApplyPlan(plan)
  doAssert applyPlan.valid
  blaiApplyMemAllocControlApplyPlan(ctrl, applyPlan)

proc blaiFetchInputCount(layer: BlaiCpuInstLayer64,
                         kind: BlaiFetchMemoryKind): uint32 =
  let inputNum = nonNegativeU32(layer.inputNum)
  case kind
  of blaiFetchGeneral:
    if inputNum > 1'u32: 2'u32 else: 1'u32
  of blaiFetchRoute:
    max(inputNum, 2'u32)

proc blaiFetchPatchBudgetPlan*(
    kind: BlaiFetchMemoryKind,
    inputCount, psramPatchCount: uint32): BlaiFetchPatchBudgetPlan =
  ## Resolve the recovered fetch descriptor patch-slot budget.
  result.kind = kind
  result.inputCount = inputCount
  result.psramPatchCount = psramPatchCount
  case kind
  of blaiFetchGeneral:
    result.budget = BlaiFetchMaxPatchSlots
  of blaiFetchRoute:
    if inputCount == 0'u32:
      return
    result.routeDescriptorCount = inputCount - 1'u32
    result.budget = result.routeDescriptorCount * psramPatchCount
  result.valid = true

proc blaiFetchInputPatchCursor*(
    layer: BlaiCpuInstLayer64,
    inputIndex, totalPatches, patchSize: uint32): BlaiFetchInputPatchCursor =
  ## Resolve one recovered fetch input patch count and total-patch advance.
  if patchSize == 0'u32:
    return
  let inputCursor = blaiFetchMemoryInputSlotCursor(inputIndex)
  if not inputCursor.valid:
    return
  let channels =
    if inputIndex == 0'u32:
      nonNegativeU32(layer.c)
    else:
      nonNegativeU32(blaiLayerCn(layer, inputIndex))
  let elements =
    nonNegativeU32(layer.w).uint64 * nonNegativeU32(layer.h).uint64 *
    channels.uint64
  var inputElements: uint32
  if not blaiU64ExactU32Count(elements, inputElements):
    return
  let patchCount = blaiCeilDivU32(inputElements, patchSize)
  if patchCount > high(uint32) - totalPatches:
    return
  result.inputIndex = inputIndex
  result.slotIndex = inputCursor.index
  result.inputElements = inputElements
  result.patchCount = patchCount
  result.totalPatches = totalPatches
  result.nextTotalPatches = totalPatches + patchCount
  result.valid = true

proc blaiFetchInputSlotCursor*(
    inputIndex, slot: uint32,
    inputPatchCount: openArray[uint32]): BlaiFetchInputSlotCursor =
  ## Resolve one recovered fetch input SRAM slot and next-slot advance.
  let inputCursor =
    blaiFetchInputStorageCursor(inputIndex, inputPatchCount.len)
  if not inputCursor.valid:
    return
  let patchCount = inputPatchCount[inputCursor.index]
  if patchCount > high(uint32) - slot:
    return
  result.inputIndex = inputIndex
  result.slotIndex = inputCursor.index
  result.slot = slot
  result.patchCount = patchCount
  result.nextSlot = slot + patchCount
  result.valid = true

proc blaiFetchInputSlotsPlan*(
    inputCount: uint32,
    inputPatchCount: openArray[uint32]): BlaiFetchInputSlotsPlan =
  ## Recover full fetch input SRAM slot assignment after patch-size selection.
  if inputCount > BlaiMaxInputNumU32:
    return
  result.inputCount = inputCount
  var cursor = 0'u32
  for inputIndex in 0'u32 ..< inputCount:
    let inputSlot = blaiFetchInputSlotCursor(
      inputIndex, cursor, inputPatchCount)
    if not inputSlot.valid:
      return
    result.inputSlots[inputSlot.slotIndex] = inputSlot.slot
    cursor = inputSlot.nextSlot
  result.nextSlot = cursor
  result.valid = true

proc blaiFetchPatchGrowDecision*(
    attempt: int,
    patchSize, totalInputPatches, budget: uint32): BlaiFetchPatchGrowDecision =
  ## Recover one bounded patch-size growth decision in fetch memory planning.
  if attempt < 0 or attempt >= BlaiFetchPatchGrowTries:
    return
  result.attempt = attempt
  result.patchSize = patchSize
  result.totalInputPatches = totalInputPatches
  result.budget = budget
  result.growAttempts = attempt.uint32 + 1'u32
  result.nextPatchSize = patchSize
  result.fits = totalInputPatches <= budget
  if not result.fits and attempt + 1 < BlaiFetchPatchGrowTries:
    if patchSize > high(uint32) div 2'u32:
      return
    result.nextPatchSize = patchSize * 2'u32
    result.grew = true
  result.valid = true

proc blaiFetchPatchGrowEvidence*(
    layer: BlaiCpuInstLayer64,
    kind: BlaiFetchMemoryKind,
    attempt: int,
    inputCount, patchSize, psramPatchCount: uint32): BlaiFetchPatchGrowEvidence =
  ## Recover one complete fetch patch-size growth attempt.
  result.kind = kind
  result.attempt = attempt
  result.inputCount = inputCount
  result.patchSize = patchSize
  var totalInputPatches = 0'u32
  for inputIndex in 0 ..< inputCount:
    let inputPatch = blaiFetchInputPatchCursor(
      layer, inputIndex, totalInputPatches, patchSize)
    if not inputPatch.valid:
      return
    result.inputPatchCount[inputPatch.slotIndex] = inputPatch.patchCount
    totalInputPatches = inputPatch.nextTotalPatches
  result.totalInputPatches = totalInputPatches

  let budgetPlan = blaiFetchPatchBudgetPlan(
    kind, inputCount, psramPatchCount)
  if not budgetPlan.valid:
    return
  result.patchBudget = budgetPlan.budget

  let growDecision = blaiFetchPatchGrowDecision(
    attempt, patchSize, totalInputPatches, budgetPlan.budget)
  if not growDecision.valid:
    return
  result.growAttempts = growDecision.growAttempts
  result.nextPatchSize = growDecision.nextPatchSize
  result.fits = growDecision.fits
  result.grew = growDecision.grew
  result.valid = true

proc blaiFetchOutputSlotPlan*(
    inputCursor, psramMidPatchCount,
    psramPatchCount: uint32): BlaiFetchOutputSlotPlan =
  ## Recover final fetch mid/output/DRAM patch slots after input slots.
  if psramMidPatchCount > high(uint32) - inputCursor:
    return
  let outputSlot = inputCursor + psramMidPatchCount
  if psramPatchCount > high(uint32) - outputSlot:
    return
  result.midOutputSlot = inputCursor
  result.psramMidPatchCount = psramMidPatchCount
  result.outputSlot = outputSlot
  result.psramPatchCount = psramPatchCount
  result.dramPatchCount = outputSlot + psramPatchCount
  result.valid = true

proc blaiFetchSlotLayoutEvidence*(
    inputCount: uint32,
    inputPatchCount: openArray[uint32],
    psramMidPatchCount, psramPatchCount: uint32):
    BlaiFetchSlotLayoutEvidence =
  ## Recover post-growth input, mid-output, output, and DRAM patch slots.
  let inputSlots = blaiFetchInputSlotsPlan(inputCount, inputPatchCount)
  if not inputSlots.valid:
    return
  result.inputCount = inputCount
  result.inputSlots = inputSlots.inputSlots
  result.inputNextSlot = inputSlots.nextSlot
  let outputSlots = blaiFetchOutputSlotPlan(
    inputSlots.nextSlot, psramMidPatchCount, psramPatchCount)
  if not outputSlots.valid:
    return
  result.midOutputSlot = outputSlots.midOutputSlot
  result.outputSlot = outputSlots.outputSlot
  result.dramPatchCount = outputSlots.dramPatchCount
  result.valid = true

proc blaiPlanFetchMemoryInto*(layer: BlaiCpuInstLayer64,
                              ctrl: BlaiPsramCtrl,
                              kind: BlaiFetchMemoryKind,
                              outResult: var BlaiFetchMemoryPlan) =
  ## Recover the fetch_BLAI_data_* PSRAM slot planning before descriptor emit.
  ##
  ## The SDK doubles `PSRAM_patch_size` up to five times until input patch slots
  ## fit the emitter's instruction budget. Descriptor bit packing remains a
  ## separate recovery step.
  outResult = default(BlaiFetchMemoryPlan)
  outResult.kind = kind
  outResult.inputCount = min(blaiFetchInputCount(layer, kind),
                             BlaiMaxInputNumU32)
  outResult.patchSize = nonNegativeU32(ctrl.psramPatchSize)
  if outResult.patchSize == 0'u32:
    return

  for attempt in 0 ..< BlaiFetchPatchGrowTries:
    let growEvidence = blaiFetchPatchGrowEvidence(
      layer, kind, attempt, outResult.inputCount, outResult.patchSize,
      nonNegativeU32(ctrl.psramPatchCount))
    if not growEvidence.valid:
      return
    outResult.inputPatchCount = growEvidence.inputPatchCount
    outResult.totalInputPatches = growEvidence.totalInputPatches
    outResult.patchBudget = growEvidence.patchBudget
    outResult.growAttempts = growEvidence.growAttempts
    if growEvidence.fits:
      outResult.fits = true
      break
    if growEvidence.grew:
      outResult.patchSize = growEvidence.nextPatchSize
      inc outResult.patchGrowCount

  if not outResult.fits:
    return

  let slotLayout = blaiFetchSlotLayoutEvidence(
    outResult.inputCount, outResult.inputPatchCount,
    nonNegativeU32(ctrl.psramMidPatchCount),
    nonNegativeU32(ctrl.psramPatchCount))
  if not slotLayout.valid:
    return
  outResult.inputSlots = slotLayout.inputSlots
  outResult.midOutputSlot = slotLayout.midOutputSlot
  outResult.outputSlot = slotLayout.outputSlot
  outResult.dramPatchCount = slotLayout.dramPatchCount

proc blaiPlanFetchMemory*(layer: BlaiCpuInstLayer64,
                          ctrl: BlaiPsramCtrl,
                          kind: BlaiFetchMemoryKind): BlaiFetchMemoryPlan =
  ## Convenience result-returning wrapper for fetch memory planning.
  blaiPlanFetchMemoryInto(layer, ctrl, kind, result)

proc blaiInstructionWordCursor*(wordIndex: uint32):
    BlaiInstructionWordCursor =
  ## Resolve one 32-bit word inside the fixed 16-byte BLAI instruction layout.
  let byteOffset = wordIndex.uint64 * BlaiNpuBiasElementBytes.uint64
  if byteOffset + BlaiNpuBiasElementBytes.uint64 > BlaiInstructionSize.uint64:
    return
  result.wordIndex = wordIndex
  result.byteOffset = byteOffset.uint32
  result.valid = true

proc blaiInstructionWord*(inst: BlaiInstruction, wordIndex: uint32): uint32 =
  ## Read one little-endian 32-bit word from a fixed 16-byte BLAI instruction.
  let cursor = blaiInstructionWordCursor(wordIndex)
  if not cursor.valid:
    return 0'u32
  discard blaiLoadLe32(inst, cursor.byteOffset, result)

proc blaiInstructionWords*(inst: BlaiInstruction): array[4, uint32] =
  ## Convenience four-word little-endian view of one BLAI instruction.
  for wordIndex in 0'u32 .. 3'u32:
    result[wordIndex.int] = blaiInstructionWord(inst, wordIndex)

proc blaiForwardWorkspaceInstructionStreamEvidenceInto*(
    layer: BlaiCpuInstLayer64,
    ctrl: BlaiPsramCtrl,
    stream: openArray[BlaiInstruction],
    useTflite: bool,
    outResult: var BlaiForwardWorkspaceInstructionStreamEvidence,
    kind: BlaiFetchMemoryKind = blaiFetchGeneral) =
  ## Decode and rebuild one materialized active instruction stream.
  outResult = default(BlaiForwardWorkspaceInstructionStreamEvidence)
  outResult.fetchPlan = blaiPlanFetchMemory(layer, ctrl, kind)
  outResult.operands = blaiPlanFetchDescriptorOperands(layer, ctrl, kind)
  outResult.bundle = blaiLayerInstructionBundle(
    layer, outResult.fetchPlan, useTflite, operands = outResult.operands)
  var rebuilt: array[3, BlaiInstruction]
  outResult.encode = blaiEncodeInstructions(outResult.bundle, rebuilt, 0)
  if stream.len >= 1:
    outResult.decodedQuant = decodeBlaiTfliteQuantInstruction(stream[0])
  if stream.len >= 2:
    outResult.decodedExt = decodeBlaiExternalLayerInfo(stream[1])
  outResult.layerInstructionIndex =
    if outResult.decodedExt.valid: 2'u32 else: 1'u32
  outResult.noExternalLayerInfo = not outResult.decodedExt.valid
  outResult.defaultLayerInstructionIndex =
      outResult.layerInstructionIndex == 1'u32
  outResult.noExtra =
    outResult.noExternalLayerInfo and outResult.defaultLayerInstructionIndex
  let streamCapacity = blaiOpenArrayLenU32(stream)
  let layerInstructionCursor =
    blaiInstructionStreamCursor(outResult.layerInstructionIndex, stream.len)
  if layerInstructionCursor.valid:
    outResult.decodedLayer =
      decodeBlaiLayer(stream[layerInstructionCursor.index],
        outResult.decodedExt)
    if useTflite:
      outResult.decodedTfliteDescriptor =
        decodeBlaiTfliteDescriptorInstruction(
          stream[layerInstructionCursor.index])
  outResult.bundleEndCountInBounds =
    outResult.encode.endCount <= streamCapacity
  let bundleCompareCount = blaiInstructionStreamCountCursor(
    outResult.encode.endCount, min(rebuilt.len, stream.len))
  outResult.bundleBytesEqual =
    outResult.encode.fits and outResult.bundleEndCountInBounds and
      bundleCompareCount.valid
  if outResult.bundleBytesEqual:
    for index in 0 ..< bundleCompareCount.count:
      if rebuilt[index] != stream[index]:
        outResult.bundleBytesEqual = false
  outResult.bundleMatches =
    outResult.encode.fits and outResult.bundleEndCountInBounds and
      outResult.bundleBytesEqual
  outResult.fetchPlanFits = outResult.fetchPlan.fits
  outResult.encodeFits = outResult.encode.fits
  outResult.layerInstructionInBounds =
    layerInstructionCursor.valid
  outResult.valid =
    outResult.fetchPlanFits and outResult.encodeFits and
      outResult.bundleMatches and outResult.layerInstructionInBounds

proc blaiForwardWorkspaceInstructionStreamEvidence*(
    layer: BlaiCpuInstLayer64,
    ctrl: BlaiPsramCtrl,
    stream: openArray[BlaiInstruction],
    useTflite: bool,
    kind: BlaiFetchMemoryKind = blaiFetchGeneral):
    BlaiForwardWorkspaceInstructionStreamEvidence =
  ## Convenience wrapper for materialized active instruction-stream evidence.
  blaiForwardWorkspaceInstructionStreamEvidenceInto(
    layer, ctrl, stream, useTflite, result, kind)

proc blaiForwardWorkspaceInstructionStreamSemanticEvidenceInto*(
    evidence: BlaiForwardWorkspaceInstructionStreamEvidence,
    layer: BlaiCpuInstLayer64,
    stream: openArray[BlaiInstruction],
    outResult: var BlaiForwardWorkspaceInstructionStreamSemanticEvidence) =
  ## Check SDK-level active stream semantics from decoded stream evidence.
  outResult = default(BlaiForwardWorkspaceInstructionStreamSemanticEvidence)
  let
    operands = evidence.operands
    quant = evidence.decodedQuant
    tfliteDescriptor = evidence.decodedTfliteDescriptor
    decoded = evidence.decodedLayer
  outResult.operandC2ZeroMatches = operands.c2 == 0'u32
  outResult.operandNoExtraInfoMatches = not operands.includeExtra
  outResult.operandSingleInputC2Matches = not operands.multiInputC2
  outResult.operandNoWeightPatchExtraMatches = not operands.weightPatchExtra
  outResult.operandNoLinePatchExtraMatches = not operands.linePatchExtra
  outResult.operandNoGroupedExtraMatches = not operands.groupedExtra
  outResult.operandNoStrideExtraMatches = not operands.strideExtra
  outResult.operandNoDilationExtraMatches = not operands.dilationExtra
  outResult.operandPlanMatches =
    outResult.operandC2ZeroMatches and outResult.operandNoExtraInfoMatches and
      outResult.operandSingleInputC2Matches and
      outResult.operandNoWeightPatchExtraMatches and
      outResult.operandNoLinePatchExtraMatches and
      outResult.operandNoGroupedExtraMatches and
      outResult.operandNoStrideExtraMatches and
      outResult.operandNoDilationExtraMatches
  outResult.instructionCountMatches = layer.instCnt == 2
  outResult.decodedLayerCountMatches = blaiLayerCount(stream) == 1'u32
  outResult.oneLayer =
    outResult.instructionCountMatches and outResult.decodedLayerCountMatches
  outResult.layerLinearActivationMatches =
    blaiActivationFromSdk(layer.activation) == blaiActLinear
  outResult.layerDataTypeMatches = layer.dataType == 1
  outResult.layerSemanticsMatch =
    outResult.layerLinearActivationMatches and outResult.layerDataTypeMatches
  outResult.streamFetchPlanFits = evidence.fetchPlanFits
  outResult.streamEncodeFits = evidence.encodeFits
  outResult.streamBundleEndCountInBounds = evidence.bundleEndCountInBounds
  outResult.streamBundleBytesEqual = evidence.bundleBytesEqual
  outResult.streamBundleMatches = evidence.bundleMatches
  outResult.streamLayerInstructionInBounds = evidence.layerInstructionInBounds
  outResult.streamEvidenceValid = evidence.valid
  outResult.noExternalLayerInfo = evidence.noExternalLayerInfo
  outResult.defaultLayerInstructionIndex = evidence.defaultLayerInstructionIndex
  outResult.noExtra = evidence.noExtra
  outResult.halt = decoded.halt
  outResult.typeMatches = decoded.layerType == blaiConvolutional
  outResult.widthMatches = decoded.w == nonNegativeU32(layer.w)
  outResult.heightMatches = decoded.h == nonNegativeU32(layer.h)
  outResult.inputChannelsMatch = decoded.c == nonNegativeU32(layer.c)
  outResult.outputChannelsMatch = decoded.outC == nonNegativeU32(layer.outC)
  outResult.kernelSizeMatches = decoded.size == nonNegativeU32(layer.size)
  outResult.shapeMatches =
    outResult.widthMatches and outResult.heightMatches and
      outResult.inputChannelsMatch and outResult.outputChannelsMatch and
      outResult.kernelSizeMatches
  outResult.c2Matches = decoded.cn0 == operands.c2
  outResult.inputSlotMatches =
    decoded.inLayer1Mem == nonNegativeU32(layer.dramIn[0])
  outResult.outputSlotMatches =
    decoded.outLayerMem == nonNegativeU32(layer.dramOut[0])
  outResult.slotsMatch =
    outResult.inputSlotMatches and outResult.outputSlotMatches
  outResult.strideStepMatches = decoded.stride == nonNegativeU32(layer.stride)
  outResult.dilationMatches = decoded.dilation == nonNegativeU32(layer.dilation)
  outResult.groupsMatches = decoded.groups == nonNegativeU32(layer.groups)
  outResult.strideMatches =
    outResult.strideStepMatches and outResult.dilationMatches and
      outResult.groupsMatches
  outResult.fdataMatches = decoded.fdata == nonNegativeU32(layer.fdata)
  outResult.fweightMatches = decoded.fweight == nonNegativeU32(layer.fweight)
  outResult.fbiasMatches = decoded.fbias == nonNegativeU32(layer.fbias)
  outResult.foutMatches = decoded.fout == nonNegativeU32(layer.fout)
  outResult.fractionsMatch =
    outResult.fdataMatches and outResult.fweightMatches and
      outResult.fbiasMatches and outResult.foutMatches
  outResult.activationKindMatches =
    decoded.activation == nonNegativeU32(layer.activation)
  outResult.tfOutputOffsetMatches =
    tfliteDescriptor.tfOutputOffset == nonNegativeU32(layer.tfOutputOffset)
  outResult.tfliteInput1OffsetMatches =
    tfliteDescriptor.tfInput1Offset == nonNegativeU32(layer.tfInput1Offset)
  outResult.tfliteInput2OffsetMatches =
    tfliteDescriptor.tfInput2Offset == nonNegativeU32(layer.tfInput2Offset)
  outResult.tfliteOutputOffsetMatches = outResult.tfOutputOffsetMatches
  outResult.tfliteOutputShiftMatches =
    tfliteDescriptor.tfOutputShift == layer.tfOutputShift
  outResult.tfliteDescriptorMatches =
    outResult.tfliteInput1OffsetMatches and
      outResult.tfliteInput2OffsetMatches and
      outResult.tfliteOutputOffsetMatches and
      outResult.tfliteOutputShiftMatches
  outResult.activationMatches =
    outResult.activationKindMatches and outResult.tfliteDescriptorMatches
  if stream.len > 0:
    outResult.quantTfliteFlagMatches =
      quant.isTflite
    outResult.quantInput1ShiftMatches =
      quant.tfInput1Shift == layer.tfInput1Shift
    outResult.quantInput2ShiftMatches =
      quant.tfInput2Shift == layer.tfInput2Shift
    outResult.quantSideMatches =
      outResult.quantTfliteFlagMatches and
        outResult.quantInput1ShiftMatches and
        outResult.quantInput2ShiftMatches
    outResult.quantInput1MultiplierMatches =
      quant.tfInput1Multiplier == blaiUint32FromInt32Bits(layer.tfInput1Multiplier)
    outResult.quantInput2MultiplierMatches =
      quant.tfInput2Multiplier == blaiUint32FromInt32Bits(layer.tfInput2Multiplier)
    outResult.quantOutputMultiplierMatches =
      quant.tfOutputMultiplier == blaiUint32FromInt32Bits(layer.tfOutputMultiplier)
    outResult.quantMultipliersMatch =
      outResult.quantInput1MultiplierMatches and
        outResult.quantInput2MultiplierMatches and
        outResult.quantOutputMultiplierMatches
    outResult.quantActivationMinMatches =
      quant.quantizedActivationMin == nonNegativeU32(layer.quantizedActivationMin)
    outResult.quantActivationMaxMatches =
      quant.quantizedActivationMax == nonNegativeU32(layer.quantizedActivationMax)
    outResult.quantClampMatches =
      outResult.quantActivationMinMatches and outResult.quantActivationMaxMatches
  if evidence.layerInstructionInBounds:
    outResult.commonImgInMatches =
      decoded.imgIn == (layer.imgIn != 0)
    outResult.commonMaxCheckMatches = not decoded.maxCheck
    outResult.commonRouteBitMatches = not decoded.routeBit
    outResult.commonMacBitMatches = decoded.macBit == 1'u32
    outResult.commonMidLayerMatches =
      decoded.midLayerMem == evidence.fetchPlan.midOutputSlot
    outResult.commonMidOutMatches =
      decoded.midOut == (layer.midOut != 0)
    outResult.commonMidOutStateClear = not decoded.midOutState
    outResult.commonUpsampleClear = not decoded.upsampleBit
    outResult.commonMacBitExtClear = not decoded.macBitExt
    outResult.commonInstEndMatches = decoded.instEndBit == (layer.halt != 0)
    outResult.commonControlMatches =
      outResult.commonImgInMatches and outResult.commonMaxCheckMatches and
        outResult.commonRouteBitMatches and outResult.commonMacBitMatches and
        outResult.commonMidLayerMatches and outResult.commonMidOutMatches and
        outResult.commonMidOutStateClear and outResult.commonUpsampleClear and
        outResult.commonMacBitExtClear and outResult.commonInstEndMatches
  outResult.bundleFetchFits = evidence.fetchPlan.fits
  outResult.bundleTfliteModeMatches = evidence.bundle.useTflite == 1
  outResult.bundleExtraInfoMatches = evidence.bundle.extraInfo == 0
  outResult.bundleEncodeFits = evidence.encode.fits
  outResult.bundleEndCountMatches = evidence.encode.endCount == 2'u32
  outResult.bundlePlanValid =
    outResult.bundleFetchFits and outResult.bundleTfliteModeMatches and
      outResult.bundleExtraInfoMatches and outResult.bundleEncodeFits and
      outResult.bundleEndCountMatches
  outResult.bundleBytesMatch = evidence.bundleMatches
  outResult.valid =
    outResult.operandPlanMatches and outResult.oneLayer and
      outResult.layerSemanticsMatch and outResult.streamEvidenceValid and
      outResult.noExtra and outResult.halt and outResult.typeMatches and
      outResult.shapeMatches and outResult.c2Matches and
      outResult.slotsMatch and outResult.strideMatches and
      outResult.fractionsMatch and outResult.activationMatches and
      outResult.quantSideMatches and outResult.quantMultipliersMatch and
      outResult.quantClampMatches and outResult.commonControlMatches and
      outResult.bundlePlanValid and outResult.bundleBytesMatch

proc blaiForwardWorkspaceInstructionStreamSemanticEvidence*(
    evidence: BlaiForwardWorkspaceInstructionStreamEvidence,
    layer: BlaiCpuInstLayer64,
    stream: openArray[BlaiInstruction]):
    BlaiForwardWorkspaceInstructionStreamSemanticEvidence =
  ## Convenience wrapper for active stream semantic evidence.
  blaiForwardWorkspaceInstructionStreamSemanticEvidenceInto(
    evidence, layer, stream, result)

proc blaiForwardWorkspaceInstructionRawWordEvidenceInto*(
    evidence: BlaiForwardWorkspaceInstructionStreamEvidence,
    stream: openArray[BlaiInstruction],
    outResult: var BlaiForwardWorkspaceInstructionRawWordEvidence) =
  ## Compare active stream raw words with the recovered encoder output words.
  outResult = default(BlaiForwardWorkspaceInstructionRawWordEvidence)
  outResult.streamCount = blaiOpenArrayLenU32(stream)
  outResult.expectedCount = evidence.encode.endCount
  outResult.countMatches =
    evidence.encode.fits and evidence.encode.endCount == 2'u32 and
      outResult.streamCount >= evidence.encode.endCount
  if stream.len >= 1:
    outResult.quantWords = blaiInstructionWords(stream[0])
    outResult.quantIsTfliteSide = evidence.decodedQuant.isTflite
  if stream.len >= 2:
    outResult.layerWords = blaiInstructionWords(stream[1])
    outResult.noExternalInstruction = not isBlaiExternalInstruction(stream[1])
    outResult.layerIsNormalInstruction = isBlaiLayerInstruction(stream[1])
    outResult.layerHasHalt = blaiInstructionHalt(stream[1])
  if evidence.encode.fits:
    outResult.rebuiltQuantWords = blaiInstructionWords(evidence.bundle.instTflite)
    outResult.rebuiltLayerWords = blaiInstructionWords(evidence.bundle.inst)
  outResult.quantWordsMatch =
    outResult.countMatches and outResult.quantWords == outResult.rebuiltQuantWords
  outResult.layerWordsMatch =
    outResult.countMatches and outResult.layerWords == outResult.rebuiltLayerWords
  outResult.valid =
    outResult.countMatches and outResult.quantWordsMatch and
      outResult.layerWordsMatch and outResult.quantIsTfliteSide and
      outResult.noExternalInstruction and outResult.layerIsNormalInstruction and
      outResult.layerHasHalt

proc blaiForwardWorkspaceInstructionRawWordEvidence*(
    evidence: BlaiForwardWorkspaceInstructionStreamEvidence,
    stream: openArray[BlaiInstruction]):
    BlaiForwardWorkspaceInstructionRawWordEvidence =
  ## Convenience wrapper for active stream raw-word evidence.
  blaiForwardWorkspaceInstructionRawWordEvidenceInto(evidence, stream, result)

proc blaiNpuSdkStreamWalkEvidenceInto*(
    evidence: BlaiForwardWorkspaceInstructionStreamEvidence,
    raw: BlaiForwardWorkspaceInstructionRawWordEvidence,
    stream: openArray[BlaiInstruction],
    outResult: var BlaiNpuSdkStreamWalkEvidence) =
  ## Recover the SDK NPU instruction stream walk used for layer allocation.
  outResult = default(BlaiNpuSdkStreamWalkEvidence)
  outResult.streamCount = blaiOpenArrayLenU32(stream)
  outResult.expectedRecordCount = evidence.encode.endCount
  outResult.recordCountMatches =
    raw.countMatches and evidence.encode.fits and
      evidence.encode.endCount == 2'u32
  outResult.firstRecordInBounds = stream.len >= 1
  outResult.secondRecordInBounds = stream.len >= 2
  if outResult.firstRecordInBounds:
    outResult.firstRecordSideInstruction = isBlaiExternalInstruction(stream[0])
    outResult.firstRecordNotTerminal = not blaiInstructionHalt(stream[0])
  if outResult.secondRecordInBounds:
    outResult.secondRecordLayerInstruction = isBlaiLayerInstruction(stream[1])
    outResult.secondRecordTerminal = blaiInstructionHalt(stream[1])
  outResult.sdkLayerCount = blaiLayerCount(stream)
  outResult.decodedLayerCountMatches =
    outResult.sdkLayerCount == 1'u32 and raw.layerIsNormalInstruction
  outResult.wouldAllocateOneLayer =
    outResult.secondRecordLayerInstruction and outResult.sdkLayerCount == 1'u32
  outResult.scanStopsAtSecondRecord =
    outResult.secondRecordLayerInstruction and outResult.secondRecordTerminal
  outResult.valid =
    outResult.recordCountMatches and outResult.firstRecordSideInstruction and
      outResult.firstRecordNotTerminal and outResult.wouldAllocateOneLayer and
      outResult.scanStopsAtSecondRecord and
      outResult.decodedLayerCountMatches

proc blaiNpuSdkStreamWalkEvidence*(
    evidence: BlaiForwardWorkspaceInstructionStreamEvidence,
    raw: BlaiForwardWorkspaceInstructionRawWordEvidence,
    stream: openArray[BlaiInstruction]): BlaiNpuSdkStreamWalkEvidence =
  ## Convenience wrapper for SDK NPU stream-walk evidence.
  blaiNpuSdkStreamWalkEvidenceInto(evidence, raw, stream, result)

proc blaiForwardWorkspaceInstructionTerminalControlEvidenceInto*(
    evidence: BlaiForwardWorkspaceInstructionStreamEvidence,
    semantics: BlaiForwardWorkspaceInstructionStreamSemanticEvidence,
    raw: BlaiForwardWorkspaceInstructionRawWordEvidence,
    layer: BlaiCpuInstLayer64,
    outResult: var BlaiForwardWorkspaceInstructionTerminalControlEvidence) =
  ## Split the recovered one-layer active terminal control bits.
  outResult = default(BlaiForwardWorkspaceInstructionTerminalControlEvidence)
  let decoded = evidence.decodedLayer
  outResult.streamValid = evidence.valid
  outResult.rawValid = raw.valid
  outResult.oneLayer = semantics.oneLayer
  outResult.noExtra = semantics.noExtra
  outResult.defaultLayerInstructionIndex =
    evidence.defaultLayerInstructionIndex
  outResult.quantSideTflite = raw.quantIsTfliteSide
  outResult.terminalLayerInstruction =
    raw.layerIsNormalInstruction and raw.layerHasHalt
  outResult.descriptorHaltBitClear = not decoded.descriptorHaltBit
  outResult.descriptorHaltBitSet = decoded.descriptorHaltBit
  outResult.streamEndBitSet = decoded.instEndBit and decoded.halt
  outResult.cpuEndBitMatches = decoded.instEndBit == (layer.halt != 0)
  outResult.terminalBitsSplit =
    outResult.descriptorHaltBitClear and outResult.streamEndBitSet
  outResult.terminalBitsSdkStyle =
    outResult.descriptorHaltBitSet and outResult.streamEndBitSet
  outResult.bundleCountTwo =
    raw.countMatches and raw.expectedCount == 2'u32 and
      evidence.encode.endCount == 2'u32
  outResult.controlCoherent =
    outResult.oneLayer and outResult.noExtra and
      outResult.defaultLayerInstructionIndex and outResult.quantSideTflite and
      outResult.terminalLayerInstruction and outResult.cpuEndBitMatches and
      (outResult.terminalBitsSplit or outResult.terminalBitsSdkStyle) and
      outResult.bundleCountTwo
  outResult.valid =
    outResult.streamValid and outResult.rawValid and
      outResult.controlCoherent

proc blaiForwardWorkspaceInstructionTerminalControlEvidence*(
    evidence: BlaiForwardWorkspaceInstructionStreamEvidence,
    semantics: BlaiForwardWorkspaceInstructionStreamSemanticEvidence,
    raw: BlaiForwardWorkspaceInstructionRawWordEvidence,
    layer: BlaiCpuInstLayer64):
    BlaiForwardWorkspaceInstructionTerminalControlEvidence =
  ## Convenience wrapper for active terminal-control evidence.
  blaiForwardWorkspaceInstructionTerminalControlEvidenceInto(
    evidence, semantics, raw, layer, result)

proc blaiForwardD0TerminalControlContrastEvidenceInto*(
    activeTerminal: BlaiForwardWorkspaceInstructionTerminalControlEvidence,
    d0Stream: NpuD0ProbeInstructionStreamEvidence,
    d0Completion: NpuD0ProbeCompletionEdgeEvidence,
    activeOutputReadiness:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence,
    outResult: var BlaiForwardD0TerminalControlContrastEvidence) =
  ## Compare active and D0 terminal controls without claiming model success.
  outResult = default(BlaiForwardD0TerminalControlContrastEvidence)
  outResult.activeTerminalValid = activeTerminal.valid
  outResult.d0StreamValid = d0Stream.valid
  outResult.d0CompletionEvidenceValid = d0Completion.valid
  outResult.activeDescriptorHaltClear =
    activeTerminal.descriptorHaltBitClear
  outResult.d0DescriptorHaltClear =
    d0Stream.terminalDescriptorHaltBitClear
  outResult.activeStreamEndSet = activeTerminal.streamEndBitSet
  outResult.d0StreamEndSet = d0Stream.terminalStreamEndBitSet
  outResult.terminalControlsEquivalent =
    outResult.activeTerminalValid and outResult.d0StreamValid and
      outResult.activeDescriptorHaltClear == outResult.d0DescriptorHaltClear and
      outResult.activeStreamEndSet == outResult.d0StreamEndSet
  outResult.d0MovesDataWithoutCompletion =
    d0Completion.outputMovedWithoutCompletion and
      d0Completion.completionEdgeMissing
  outResult.activeOutputStillGated =
    activeOutputReadiness.valid and
      activeOutputReadiness.outputEquivalenceBlockedByCompletion and
      activeOutputReadiness.completionStillMissing
  outResult.terminalControlNotSoleBlock =
    outResult.terminalControlsEquivalent and
      outResult.d0MovesDataWithoutCompletion and outResult.activeOutputStillGated
  outResult.nextWorkIsEngineContext =
    outResult.terminalControlNotSoleBlock and
      activeOutputReadiness.nextStageOutputEquivalence
  outResult.valid =
    outResult.d0CompletionEvidenceValid and
      outResult.nextWorkIsEngineContext

proc blaiForwardD0TerminalControlContrastEvidence*(
    activeTerminal: BlaiForwardWorkspaceInstructionTerminalControlEvidence,
    d0Stream: NpuD0ProbeInstructionStreamEvidence,
    d0Completion: NpuD0ProbeCompletionEdgeEvidence,
    activeOutputReadiness:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence):
      BlaiForwardD0TerminalControlContrastEvidence =
  ## Convenience wrapper for active/D0 terminal-control contrast evidence.
  blaiForwardD0TerminalControlContrastEvidenceInto(
    activeTerminal, d0Stream, d0Completion, activeOutputReadiness, result)

proc blaiForwardD0EngineContextGapEvidenceInto*(
    instruction: BlaiForwardLaunchInstructionFetchEvidence,
    operand: BlaiForwardLaunchOperandFetchEvidence,
    commandIdle: BlaiParsedForwardConfiguredWorkspaceActiveCommandIdleEvidence,
    terminalContrast: BlaiForwardD0TerminalControlContrastEvidence,
    d0Completion: NpuD0ProbeCompletionEdgeEvidence,
    outResult: var BlaiForwardD0EngineContextGapEvidence) =
  ## Classify the remaining active-vs-D0 engine-context frontier.
  outResult = default(BlaiForwardD0EngineContextGapEvidence)
  outResult.instructionFetchValid = instruction.valid
  outResult.operandFetchValid = operand.valid
  outResult.commandIdleValid = commandIdle.valid
  outResult.terminalContrastValid = terminalContrast.valid
  outResult.d0CompletionEvidenceValid = d0Completion.valid
  outResult.activeInstructionExecutable = instruction.fetchSurfaceExecutable
  outResult.activeOperandSurfaceCoherent = operand.operandSurfaceCoherent
  outResult.activeCommandIdle =
    commandIdle.noCommandActivity and commandIdle.commandIdleMatchesWaitExit
  outResult.activeOutputStillGated = terminalContrast.activeOutputStillGated
  outResult.d0MovedDataWithoutCompletion =
    d0Completion.outputMovedWithoutCompletion and
      terminalContrast.d0MovesDataWithoutCompletion
  outResult.launchOperandContextKnown =
    outResult.instructionFetchValid and outResult.operandFetchValid and
      outResult.activeInstructionExecutable and
      outResult.activeOperandSurfaceCoherent
  outResult.contextDiffExplainsNextFrontier =
    outResult.launchOperandContextKnown and outResult.commandIdleValid and
      outResult.terminalContrastValid and outResult.activeCommandIdle and
      outResult.activeOutputStillGated and outResult.d0MovedDataWithoutCompletion
  outResult.nextWorkIsOperandEngineSemantics =
    outResult.contextDiffExplainsNextFrontier and
      terminalContrast.nextWorkIsEngineContext
  outResult.valid =
    outResult.d0CompletionEvidenceValid and
      outResult.nextWorkIsOperandEngineSemantics

proc blaiForwardD0EngineContextGapEvidence*(
    instruction: BlaiForwardLaunchInstructionFetchEvidence,
    operand: BlaiForwardLaunchOperandFetchEvidence,
    commandIdle: BlaiParsedForwardConfiguredWorkspaceActiveCommandIdleEvidence,
    terminalContrast: BlaiForwardD0TerminalControlContrastEvidence,
    d0Completion: NpuD0ProbeCompletionEdgeEvidence):
      BlaiForwardD0EngineContextGapEvidence =
  ## Convenience wrapper for active-vs-D0 engine-context gap evidence.
  blaiForwardD0EngineContextGapEvidenceInto(
    instruction, operand, commandIdle, terminalContrast, d0Completion, result)

proc blaiForwardD0BufferContextContrastEvidenceInto*(
    activeRaw: BlaiForwardWorkspaceInstructionRawWordEvidence,
    d0Stream: NpuD0ProbeInstructionStreamEvidence,
    activePacked: BlaiNpuPackedWeightBiasEvidence,
    outputReadiness:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence,
    d0Movement: NpuD0ProbeOutputMovementEvidence,
    activeFirstWeightByte, d0FirstWeightByte: uint8,
    activeFirstBias, d0FirstBias: int32,
    activeInputByte, d0InputByte: uint8,
    outResult: var BlaiForwardD0BufferContextContrastEvidence) =
  ## Compare identical instruction records against operand/data context.
  outResult = default(BlaiForwardD0BufferContextContrastEvidence)
  outResult.activeRawValid = activeRaw.valid
  outResult.d0StreamValid = d0Stream.valid
  outResult.activePackedWeightValid = activePacked.valid
  outResult.outputReadinessValid = outputReadiness.valid
  outResult.d0MovementValid = d0Movement.valid
  outResult.setupWordsMatch = activeRaw.quantWords == d0Stream.setupWords
  outResult.terminalWordsMatch = activeRaw.layerWords == d0Stream.terminalWords
  outResult.instructionWordsMatch =
    outResult.setupWordsMatch and outResult.terminalWordsMatch
  outResult.activeFirstWeightByte = activeFirstWeightByte
  outResult.d0FirstWeightByte = d0FirstWeightByte
  outResult.firstWeightDiffers =
    activePacked.firstWeightByteMatches and
      activeFirstWeightByte != d0FirstWeightByte
  outResult.activeFirstBias = activeFirstBias
  outResult.d0FirstBias = d0FirstBias
  outResult.firstBiasMatches = activeFirstBias == d0FirstBias
  outResult.activeInputByte = activeInputByte
  outResult.d0InputByte = d0InputByte
  outResult.inputByteMatches =
    activeInputByte == d0InputByte and d0Movement.inputMatches
  outResult.activeOutputStillGated =
    outputReadiness.outputEquivalenceBlockedByCompletion and
      outputReadiness.completionStillMissing
  outResult.d0OutputMoved = d0Movement.outputMoved
  outResult.sameInstructionsDifferentOperandContext =
    outResult.activeRawValid and outResult.d0StreamValid and
      outResult.activePackedWeightValid and outResult.instructionWordsMatch and
      outResult.firstWeightDiffers and outResult.firstBiasMatches and
      outResult.inputByteMatches
  outResult.nextWorkIsWeightDataOrEngineSemantics =
    outResult.sameInstructionsDifferentOperandContext and
      outResult.outputReadinessValid and outResult.d0MovementValid and
      outResult.activeOutputStillGated and outResult.d0OutputMoved
  outResult.valid = outResult.nextWorkIsWeightDataOrEngineSemantics

proc blaiForwardD0BufferContextContrastEvidence*(
    activeRaw: BlaiForwardWorkspaceInstructionRawWordEvidence,
    d0Stream: NpuD0ProbeInstructionStreamEvidence,
    activePacked: BlaiNpuPackedWeightBiasEvidence,
    outputReadiness:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence,
    d0Movement: NpuD0ProbeOutputMovementEvidence,
    activeFirstWeightByte, d0FirstWeightByte: uint8,
    activeFirstBias, d0FirstBias: int32,
    activeInputByte, d0InputByte: uint8):
      BlaiForwardD0BufferContextContrastEvidence =
  ## Convenience wrapper for active/D0 buffer-context contrast evidence.
  blaiForwardD0BufferContextContrastEvidenceInto(
    activeRaw, d0Stream, activePacked, outputReadiness, d0Movement,
    activeFirstWeightByte, d0FirstWeightByte, activeFirstBias, d0FirstBias,
    activeInputByte, d0InputByte, result)

proc blaiRouteInputPatchTotalCursor*(
    inputIndex, totalPatches: uint32,
    inputPatchCount: openArray[uint32]): BlaiRouteInputPatchTotalCursor =
  ## Accumulate one recovered route input patch count into the output cursor.
  let inputCursor =
    blaiFetchInputStorageCursor(inputIndex, inputPatchCount.len)
  if not inputCursor.valid:
    return
  let patchCount = inputPatchCount[inputCursor.index]
  if patchCount > high(uint32) - totalPatches:
    return
  result.inputIndex = inputIndex
  result.slotIndex = inputCursor.index
  result.patchCount = patchCount
  result.totalPatches = totalPatches
  result.nextTotalPatches = totalPatches + patchCount
  result.valid = true

proc blaiRouteInputPatchTotalPlan*(
    inputCount: uint32,
    inputPatchCount: openArray[uint32]): BlaiRouteInputPatchTotalPlan =
  ## Recover full route input patch-count accumulation before output slots.
  if inputCount > BlaiMaxInputNumU32:
    return
  result.inputCount = inputCount
  var totalInputPatches = 0'u32
  for inputIndex in 0'u32 ..< inputCount:
    let inputTotal = blaiRouteInputPatchTotalCursor(
      inputIndex, totalInputPatches, inputPatchCount)
    if not inputTotal.valid:
      return
    totalInputPatches = inputTotal.nextTotalPatches
  result.totalInputPatches = totalInputPatches
  result.valid = true

proc blaiRouteFirstOutputSlotPlan*(
    totalInputPatches, psramPatchCount: uint32): BlaiRouteFirstOutputSlotPlan =
  ## Recover the first route SRAM output slot and post-output patch cursor.
  if psramPatchCount > high(uint32) - totalInputPatches:
    return
  result.totalInputPatches = totalInputPatches
  result.psramPatchCount = psramPatchCount
  result.outputSlot = totalInputPatches
  result.outputSlotCount = 1
  result.nextCursor = totalInputPatches + psramPatchCount
  result.valid = true

proc blaiRouteIntermediateChannelCursor*(
    stepIndex, cumulativeChannels: uint32,
    cn: openArray[int32]): BlaiRouteIntermediateChannelCursor =
  ## Recover one route intermediate channel accumulation step from `cn[]`.
  let stepCursor = blaiRouteDescriptorStepCursor(stepIndex)
  if not stepCursor.valid or stepCursor.index >= cn.len:
    return
  let inputChannels = nonNegativeU32(cn[stepCursor.index])
  if inputChannels > high(uint32) - cumulativeChannels:
    return
  result.stepIndex = stepIndex
  result.cnSlot = stepCursor.index
  result.inputChannels = inputChannels
  result.cumulativeChannels = cumulativeChannels
  result.nextCumulativeChannels = cumulativeChannels + inputChannels
  result.valid = true

proc blaiRouteIntermediateOutputSlotPlan*(
    stepIndex, cursor, outW, outH, cumulativeChannels, patchSize,
    outputSlotCount: uint32): BlaiRouteIntermediateOutputSlotPlan =
  ## Recover one route intermediate output-slot commit.
  let outputSlot = blaiRouteOutputSlotCursor(
    stepIndex, cursor, outW, outH, cumulativeChannels, patchSize)
  if not outputSlot.valid or outputSlotCount == high(uint32):
    return
  result.stepIndex = stepIndex
  result.slotIndex = outputSlot.slotIndex
  result.outputSlot = outputSlot.slot
  result.outputSlotCount = outputSlotCount
  result.nextOutputSlotCount = outputSlotCount + 1'u32
  result.nextCursor = outputSlot.nextCursor
  result.valid = true

proc blaiRouteIntermediateOutputSlotsPlan*(
    inputCount, firstOutputSlot, firstCursor, firstOutputSlotCount,
    initialChannels, outW, outH, patchSize: uint32,
    cn: openArray[int32]): BlaiRouteIntermediateOutputSlotsPlan =
  ## Recover route intermediate output-slot walk after the first output slot.
  if firstOutputSlotCount == 0'u32 or
     firstOutputSlotCount > BlaiMaxInputNumU32:
    return
  result.inputCount = inputCount
  result.outputSlotCount = firstOutputSlotCount
  result.outputSlots[0] = firstOutputSlot
  var
    cursor = firstCursor
    cumulativeChannels = initialChannels
  result.intermediateCount =
    if inputCount > 2'u32: inputCount - 2'u32 else: 0'u32
  for index in 0'u32 ..< result.intermediateCount:
    if index < BlaiMaxRouteInputNumU32:
      let channelCursor = blaiRouteIntermediateChannelCursor(
        index, cumulativeChannels, cn)
      if not channelCursor.valid:
        return
      cumulativeChannels = channelCursor.nextCumulativeChannels
    let outputCommit = blaiRouteIntermediateOutputSlotPlan(
      index, cursor, outW, outH, cumulativeChannels, patchSize,
      result.outputSlotCount)
    if not outputCommit.valid:
      return
    result.outputSlots[outputCommit.slotIndex] = outputCommit.outputSlot
    result.outputSlotCount = outputCommit.nextOutputSlotCount
    cursor = outputCommit.nextCursor
  result.finalPatchCursor = cursor
  result.finalCumulativeChannels = cumulativeChannels
  result.valid = true

proc blaiRouteSramLayerApplyEvidence*(
    linePatchW0, groups: int32,
    finalPatchCursor: uint32): BlaiRouteSramLayerApplyEvidence =
  ## Project route layer-side state through signed allocator-field ABI.
  let dramPatchNum = blaiAllocatorFieldAbi(finalPatchCursor)
  if not dramPatchNum.valid:
    return
  result.lineW0 = linePatchW0
  result.groups = if groups <= 0: 1'i32 else: groups
  result.dramPatchNum = dramPatchNum.value
  result.valid = true

proc blaiRouteSramLayerApplyPlan*(
    linePatchW0, groups: int32,
    finalPatchCursor: uint32): BlaiRouteSramLayerApplyPlan =
  ## Recover the layer-side assignments made by `fetch_BLAI_data_route`.
  let evidence = blaiRouteSramLayerApplyEvidence(
    linePatchW0, groups, finalPatchCursor)
  result.lineW0 = evidence.lineW0
  result.groups = evidence.groups
  result.dramPatchNum = evidence.dramPatchNum
  result.valid = evidence.valid

proc blaiRouteSramLayerState*(
    lineW0, groups, dramPatchNum: int32): BlaiRouteSramLayerState =
  ## Build caller-owned route layer state.
  result.lineW0 = lineW0
  result.groups = groups
  result.dramPatchNum = dramPatchNum

proc blaiRouteSramLayerState*(
    plan: BlaiRouteSramLayerApplyPlan): BlaiRouteSramLayerState =
  ## Project a valid route layer apply plan into caller-owned state.
  doAssert plan.valid
  blaiRouteSramLayerState(plan.lineW0, plan.groups, plan.dramPatchNum)

proc blaiApplyRouteSramLayerState*(
    ctrl: var BlaiPsramCtrl,
    layer: var BlaiCpuInstLayer64,
    state: BlaiRouteSramLayerState) =
  ## Apply route layer state to typed `PSRAM_ctrl` and layer fields.
  ctrl.lineW0 = state.lineW0
  layer.groups = state.groups
  layer.dramPatchNum = state.dramPatchNum

proc blaiFetchLayerApplyEvidence*(
    dramPatchCount: uint32): BlaiFetchLayerApplyEvidence =
  ## Project general fetch layer-side state through signed allocator-field ABI.
  let dramPatchNum = blaiAllocatorFieldAbi(dramPatchCount)
  if not dramPatchNum.valid:
    return
  result.dramPatchNum = dramPatchNum.value
  result.valid = true

proc blaiFetchLayerApplyPlan*(
    dramPatchCount: uint32): BlaiFetchLayerApplyPlan =
  ## Recover the layer-side assignment made by `fetch_BLAI_data_general`.
  let evidence = blaiFetchLayerApplyEvidence(dramPatchCount)
  result.dramPatchNum = evidence.dramPatchNum
  result.valid = evidence.valid

proc blaiFetchLayerState*(
    dramPatchNum: int32): BlaiFetchLayerState =
  ## Build caller-owned general fetch layer state.
  result.dramPatchNum = dramPatchNum

proc blaiFetchLayerState*(
    plan: BlaiFetchLayerApplyPlan): BlaiFetchLayerState =
  ## Project a valid general fetch layer apply plan into caller-owned state.
  doAssert plan.valid
  blaiFetchLayerState(plan.dramPatchNum)

proc blaiApplyFetchLayerState*(
    layer: var BlaiCpuInstLayer64,
    state: BlaiFetchLayerState) =
  ## Apply general fetch layer state.
  layer.dramPatchNum = state.dramPatchNum

proc blaiFetchInputSlotApplyPlan*(
    inputIndex: uint32,
    inputSlots: openArray[uint32]): BlaiFetchInputSlotApplyPlan =
  ## Recover one `SRAM_in[]` assignment from a planned fetch input slot.
  let inputCursor =
    blaiFetchInputStorageCursor(inputIndex, inputSlots.len)
  if not inputCursor.valid:
    return
  let sramSlot = blaiAllocatorFieldAbi(inputSlots[inputCursor.index])
  if not sramSlot.valid:
    return
  result.inputIndex = inputIndex
  result.slotIndex = inputCursor.index
  result.sramSlot = sramSlot.value
  result.valid = true

proc blaiFetchInputSlotState*(
    inputIndex: uint32,
    slotIndex: int,
    sramSlot: int32): BlaiFetchInputSlotState =
  ## Build caller-owned fetch input slot state.
  result.inputIndex = inputIndex
  result.slotIndex = slotIndex
  result.sramSlot = sramSlot

proc blaiFetchInputSlotState*(
    plan: BlaiFetchInputSlotApplyPlan): BlaiFetchInputSlotState =
  ## Project a valid fetch input slot apply plan into caller-owned state.
  doAssert plan.valid
  blaiFetchInputSlotState(plan.inputIndex, plan.slotIndex, plan.sramSlot)

proc blaiApplyFetchInputSlotState*(
    ctrl: var BlaiPsramCtrl,
    state: BlaiFetchInputSlotState) =
  ## Apply one fetch input slot state to `SRAM_in[]`.
  ctrl.sramIn[state.slotIndex] = state.sramSlot

proc blaiFetchInputSlotsApplyEvidence*(
    inputCount: uint32,
    inputSlots: openArray[uint32]): BlaiFetchInputSlotsApplyEvidence =
  ## Build checked aggregate state for recovered `SRAM_in[]` slot writes.
  result.inputCount = inputCount
  for inputIndex in 0 ..< blaiBoundedU32Count(inputCount, BlaiMaxInputNum):
    let inputApply = blaiFetchInputSlotApplyPlan(
      inputIndex.uint32, inputSlots)
    if not inputApply.valid:
      return
    result.slots[inputApply.slotIndex] =
      blaiFetchInputSlotState(inputApply)
  result.valid = true

proc blaiFetchInputSlotsApplyPlan*(
    inputCount: uint32,
    inputSlots: openArray[uint32]): BlaiFetchInputSlotsApplyPlan =
  ## Recover checked fetch `SRAM_in[]` slot projections before mutation.
  let evidence = blaiFetchInputSlotsApplyEvidence(inputCount, inputSlots)
  result.inputCount = evidence.inputCount
  result.slots = evidence.slots
  result.valid = evidence.valid

proc blaiFetchInputSlotsState*(
    plan: BlaiFetchInputSlotsApplyPlan): BlaiFetchInputSlotsState =
  ## Project a valid fetch input-slots apply plan into caller-owned state.
  doAssert plan.valid
  result.inputCount = plan.inputCount
  result.slots = plan.slots

proc blaiApplyFetchInputSlotsState*(
    ctrl: var BlaiPsramCtrl,
    state: BlaiFetchInputSlotsState) =
  ## Apply fetch input slots state to `SRAM_in[]`.
  for inputIndex in 0 ..< blaiBoundedU32Count(
      state.inputCount, BlaiMaxInputNum):
    let inputSlot = state.slots[inputIndex]
    ctrl.sramIn[inputSlot.slotIndex] = inputSlot.sramSlot

proc blaiFetchOutputSlotApplyEvidence*(
    midOutputSlot, outputSlot: uint32): BlaiFetchOutputSlotApplyEvidence =
  ## Project general fetch output slots through signed allocator-field ABI.
  let
    midOut = blaiAllocatorFieldAbi(midOutputSlot)
    out0 = blaiAllocatorFieldAbi(outputSlot)
  if not midOut.valid or not out0.valid:
    return
  result.sramMidOut = midOut.value
  result.sramOut0 = out0.value
  result.valid = true

proc blaiFetchOutputSlotApplyPlan*(
    midOutputSlot, outputSlot: uint32): BlaiFetchOutputSlotApplyPlan =
  ## Recover `SRAM_mid_out` and first `SRAM_out[]` application for general fetch.
  let evidence =
    blaiFetchOutputSlotApplyEvidence(midOutputSlot, outputSlot)
  result.sramMidOut = evidence.sramMidOut
  result.sramOut0 = evidence.sramOut0
  result.valid = evidence.valid

proc blaiFetchOutputSlotState*(
    sramMidOut, sramOut0: int32): BlaiFetchOutputSlotState =
  ## Build caller-owned general fetch output slot state.
  result.sramMidOut = sramMidOut
  result.sramOut0 = sramOut0

proc blaiFetchOutputSlotState*(
    plan: BlaiFetchOutputSlotApplyPlan): BlaiFetchOutputSlotState =
  ## Project a valid general fetch output apply plan into caller-owned state.
  doAssert plan.valid
  blaiFetchOutputSlotState(plan.sramMidOut, plan.sramOut0)

proc blaiApplyFetchOutputSlotState*(
    ctrl: var BlaiPsramCtrl,
    state: BlaiFetchOutputSlotState) =
  ## Apply general fetch output slot state.
  ctrl.sramMidOut = state.sramMidOut
  ctrl.sramOut[0] = state.sramOut0

proc blaiFetchPatchSizeApplyEvidence*(
    patchSize: uint32): BlaiFetchPatchSizeApplyEvidence =
  ## Project fetch patch size through signed allocator-field ABI.
  let field = blaiAllocatorFieldAbi(patchSize)
  if not field.valid:
    return
  result.patchSize = field.value
  result.valid = true

proc blaiFetchPatchSizeApplyPlan*(
    patchSize: uint32): BlaiFetchPatchSizeApplyPlan =
  ## Recover `PSRAM_patch_size` application for general and route fetch plans.
  let evidence = blaiFetchPatchSizeApplyEvidence(patchSize)
  result.patchSize = evidence.patchSize
  result.valid = evidence.valid

proc blaiFetchPatchSizeState*(
    patchSize: int32): BlaiFetchPatchSizeState =
  ## Build caller-owned fetch patch-size state.
  result.patchSize = patchSize

proc blaiFetchPatchSizeState*(
    plan: BlaiFetchPatchSizeApplyPlan): BlaiFetchPatchSizeState =
  ## Project a valid fetch patch-size apply plan into caller-owned state.
  doAssert plan.valid
  blaiFetchPatchSizeState(plan.patchSize)

proc blaiApplyFetchPatchSizeState*(
    ctrl: var BlaiPsramCtrl,
    state: BlaiFetchPatchSizeState) =
  ## Apply fetch patch-size state to `PSRAM_ctrl`.
  ctrl.psramPatchSize = state.patchSize

proc blaiFetchSramSlotsClearState*():
    BlaiFetchSramSlotsClearState =
  ## Build caller-owned zeroed fetch SRAM slot state.
  discard

proc blaiFetchSramSlotsClearApplyPlan*():
    BlaiFetchSramSlotsClearApplyPlan =
  ## Recover the fetch-visible `SRAM_in[]`/`SRAM_out[]` clear before slot writes.
  result.stateAfter = blaiFetchSramSlotsClearState()
  result.valid = true

proc blaiFetchSramSlotsClearState*(
    plan: BlaiFetchSramSlotsClearApplyPlan): BlaiFetchSramSlotsClearState =
  ## Project a valid SRAM slot clear apply plan into caller-owned state.
  doAssert plan.valid
  plan.stateAfter

proc blaiApplyFetchSramSlotsClearState*(
    ctrl: var BlaiPsramCtrl,
    state: BlaiFetchSramSlotsClearState) =
  ## Apply zeroed fetch SRAM slot arrays to `PSRAM_ctrl`.
  ctrl.sramIn = state.sramIn
  ctrl.sramOut = state.sramOut

proc blaiRouteOutputSlotApplyEvidence*(
    outputIndex: uint32,
    outputSlots: openArray[uint32]): BlaiRouteOutputSlotApplyEvidence =
  ## Project one route output slot through cursor and signed allocator ABI.
  let outputCursor = blaiRouteSlotCursor(outputIndex)
  if not outputCursor.valid or outputCursor.slotIndex >= outputSlots.len:
    return
  let sramSlot = blaiAllocatorFieldAbi(outputSlots[outputCursor.slotIndex])
  if not sramSlot.valid:
    return
  result.outputIndex = outputIndex
  result.slotIndex = outputCursor.slotIndex
  result.sramSlot = sramSlot.value
  result.valid = true

proc blaiRouteOutputSlotApplyPlan*(
    outputIndex: uint32,
    outputSlots: openArray[uint32]): BlaiRouteOutputSlotApplyPlan =
  ## Recover one `SRAM_out[]` assignment from a planned route output slot.
  let evidence = blaiRouteOutputSlotApplyEvidence(outputIndex, outputSlots)
  result.outputIndex = evidence.outputIndex
  result.slotIndex = evidence.slotIndex
  result.sramSlot = evidence.sramSlot
  result.valid = evidence.valid

proc blaiRouteOutputSlotState*(
    outputIndex: uint32,
    slotIndex: int,
    sramSlot: int32): BlaiRouteOutputSlotState =
  ## Build caller-owned route output slot state.
  result.outputIndex = outputIndex
  result.slotIndex = slotIndex
  result.sramSlot = sramSlot

proc blaiRouteOutputSlotState*(
    plan: BlaiRouteOutputSlotApplyPlan): BlaiRouteOutputSlotState =
  ## Project a valid route output slot apply plan into caller-owned state.
  doAssert plan.valid
  blaiRouteOutputSlotState(plan.outputIndex, plan.slotIndex, plan.sramSlot)

proc blaiApplyRouteOutputSlotState*(
    ctrl: var BlaiPsramCtrl,
    state: BlaiRouteOutputSlotState) =
  ## Apply one route output slot state to `SRAM_out[]`.
  ctrl.sramOut[state.slotIndex] = state.sramSlot

proc blaiRouteOutputSlotsApplyPlan*(
    outputSlotCount: uint32,
    outputSlots: openArray[uint32]): BlaiRouteOutputSlotsApplyPlan =
  ## Recover checked route `SRAM_out[]` slot projections before mutation.
  result.outputSlotCount = outputSlotCount
  for outputIndex in 0 ..< blaiBoundedU32Count(outputSlotCount, BlaiMaxInputNum):
    let outputApply = blaiRouteOutputSlotApplyPlan(
      outputIndex.uint32, outputSlots)
    if not outputApply.valid:
      return
    result.slots[outputApply.slotIndex] =
      blaiRouteOutputSlotState(outputApply)
  result.valid = true

proc blaiRouteOutputSlotsState*(
    plan: BlaiRouteOutputSlotsApplyPlan): BlaiRouteOutputSlotsState =
  ## Project a valid route output-slots apply plan into caller-owned state.
  doAssert plan.valid
  result.outputSlotCount = plan.outputSlotCount
  result.slots = plan.slots

proc blaiApplyRouteOutputSlotsState*(
    ctrl: var BlaiPsramCtrl,
    state: BlaiRouteOutputSlotsState) =
  ## Apply route output slots state to `SRAM_out[]`.
  for outputIndex in 0 ..< blaiBoundedU32Count(
      state.outputSlotCount, BlaiMaxInputNum):
    let outputSlot = state.slots[outputIndex]
    ctrl.sramOut[outputSlot.slotIndex] = outputSlot.sramSlot

proc blaiPlanRouteSramSlotsInto*(layer: BlaiCpuInstLayer64,
                                 ctrl: BlaiPsramCtrl,
                                 outResult: var BlaiRouteSramSlotPlan) =
  ## Recover the `fetch_BLAI_data_route` SRAM output-slot choreography.
  outResult = default(BlaiRouteSramSlotPlan)
  blaiPlanFetchMemoryInto(layer, ctrl, blaiFetchRoute, outResult.memory)
  if not outResult.memory.fits:
    return

  let inputTotal = blaiRouteInputPatchTotalPlan(
    outResult.memory.inputCount, outResult.memory.inputPatchCount)
  if not inputTotal.valid:
    return
  let firstOutput = blaiRouteFirstOutputSlotPlan(
    inputTotal.totalInputPatches, nonNegativeU32(ctrl.psramPatchCount))
  if not firstOutput.valid:
    return
  let intermediateOutputs = blaiRouteIntermediateOutputSlotsPlan(
    outResult.memory.inputCount, firstOutput.outputSlot, firstOutput.nextCursor,
    firstOutput.outputSlotCount, nonNegativeU32(layer.c),
    nonNegativeU32(layer.outW), nonNegativeU32(layer.outH),
    outResult.memory.patchSize, layer.cn)
  if not intermediateOutputs.valid:
    return
  outResult.outputSlots = intermediateOutputs.outputSlots
  outResult.outputSlotCount = intermediateOutputs.outputSlotCount
  outResult.finalPatchCursor = intermediateOutputs.finalPatchCursor
  outResult.fits = true

proc blaiPlanRouteSramSlots*(layer: BlaiCpuInstLayer64,
                             ctrl: BlaiPsramCtrl): BlaiRouteSramSlotPlan =
  ## Convenience result-returning wrapper for route SRAM slot planning.
  blaiPlanRouteSramSlotsInto(layer, ctrl, result)

proc blaiApplyRouteSramSlotPlan*(ctrl: var BlaiPsramCtrl,
                                 layer: var BlaiCpuInstLayer64,
                                 plan: BlaiRouteSramSlotPlan) =
  ## Apply recovered route SRAM slots to typed `PSRAM_ctrl` and layer state.
  doAssert plan.fits
  let clearApply = blaiFetchSramSlotsClearApplyPlan()
  doAssert clearApply.valid
  blaiApplyFetchSramSlotsClearState(
    ctrl, blaiFetchSramSlotsClearState(clearApply))
  let patchSizeApply = blaiFetchPatchSizeApplyPlan(plan.memory.patchSize)
  doAssert patchSizeApply.valid
  blaiApplyFetchPatchSizeState(
    ctrl, blaiFetchPatchSizeState(patchSizeApply))
  let inputSlotsApply = blaiFetchInputSlotsApplyPlan(
    plan.memory.inputCount, plan.memory.inputSlots)
  doAssert inputSlotsApply.valid
  blaiApplyFetchInputSlotsState(
    ctrl, blaiFetchInputSlotsState(inputSlotsApply))
  let outputSlotsApply = blaiRouteOutputSlotsApplyPlan(
    plan.outputSlotCount, plan.outputSlots)
  doAssert outputSlotsApply.valid
  blaiApplyRouteOutputSlotsState(
    ctrl, blaiRouteOutputSlotsState(outputSlotsApply))
  let layerApply = blaiRouteSramLayerApplyPlan(
    ctrl.linePatchW[0], layer.groups, plan.finalPatchCursor)
  doAssert layerApply.valid
  blaiApplyRouteSramLayerState(
    ctrl, layer, blaiRouteSramLayerState(layerApply))

proc blaiApplyFetchMemoryPlan*(ctrl: var BlaiPsramCtrl,
                               layer: var BlaiCpuInstLayer64,
                               plan: BlaiFetchMemoryPlan) =
  ## Apply the recovered fetch_BLAI_data_* slot fields to typed objects.
  doAssert plan.fits
  let clearApply = blaiFetchSramSlotsClearApplyPlan()
  doAssert clearApply.valid
  blaiApplyFetchSramSlotsClearState(
    ctrl, blaiFetchSramSlotsClearState(clearApply))
  let patchSizeApply = blaiFetchPatchSizeApplyPlan(plan.patchSize)
  doAssert patchSizeApply.valid
  blaiApplyFetchPatchSizeState(
    ctrl, blaiFetchPatchSizeState(patchSizeApply))
  let inputSlotsApply = blaiFetchInputSlotsApplyPlan(
    plan.inputCount, plan.inputSlots)
  doAssert inputSlotsApply.valid
  blaiApplyFetchInputSlotsState(
    ctrl, blaiFetchInputSlotsState(inputSlotsApply))
  let outputApply = blaiFetchOutputSlotApplyPlan(
    plan.midOutputSlot, plan.outputSlot)
  doAssert outputApply.valid
  blaiApplyFetchOutputSlotState(
    ctrl, blaiFetchOutputSlotState(outputApply))
  let layerApply = blaiFetchLayerApplyPlan(plan.dramPatchCount)
  doAssert layerApply.valid
  blaiApplyFetchLayerState(layer, blaiFetchLayerState(layerApply))

proc blaiFetchEmitCommitState*(layer: BlaiCpuInstLayer64,
                               ctrl: BlaiPsramCtrl):
    BlaiFetchEmitCommitState =
  ## Build caller-owned fetch-emitter commit state.
  result.layer = layer
  result.ctrl = ctrl

proc blaiFetchEmitCommitEvidence*(fits: bool,
                                  layer: BlaiCpuInstLayer64,
                                  ctrl: BlaiPsramCtrl):
    BlaiFetchEmitCommitEvidence =
  ## Project successful fetch-emitter append into staged commit evidence.
  if not fits:
    return
  result.stateAfter = blaiFetchEmitCommitState(layer, ctrl)
  result.valid = true

proc blaiFetchEmitCommitApplyPlan*(fits: bool,
                                   layer: BlaiCpuInstLayer64,
                                   ctrl: BlaiPsramCtrl):
    BlaiFetchEmitCommitApplyPlan =
  ## Recover final staged-state commit after fetch planning and emission fit.
  let evidence = blaiFetchEmitCommitEvidence(fits, layer, ctrl)
  result.stateAfter = evidence.stateAfter
  result.valid = evidence.valid

proc blaiFetchEmitCommitState*(plan: BlaiFetchEmitCommitApplyPlan):
    BlaiFetchEmitCommitState =
  ## Project a valid fetch-emitter commit plan into caller-owned state.
  doAssert plan.valid
  plan.stateAfter

proc blaiApplyFetchEmitCommitState*(layer: var BlaiCpuInstLayer64,
                                    ctrl: var BlaiPsramCtrl,
                                    state: BlaiFetchEmitCommitState) =
  ## Apply successful staged fetch-emitter state to caller-owned objects.
  layer = state.layer
  ctrl = state.ctrl

proc blaiEmitFetchLayerInstructionsInto*(layer: var BlaiCpuInstLayer64,
                                         ctrl: var BlaiPsramCtrl,
                                         stream: var openArray[BlaiInstruction],
                                         kind: BlaiFetchMemoryKind,
                                         useTflite: bool,
                                         outResult: var BlaiFetchEmitResult,
                                         c2: uint32 = 0'u32,
                                         includeExtra: bool = false,
                                         descriptorHalt: bool = false,
                                         midOutState: bool = false) =
  ## Plan fetch memory, emit recovered layer instructions, then commit state.
  ##
  ## The caller-owned layer, ctrl, and stream are unchanged unless both the
  ## fetch memory plan and full instruction append fit.
  outResult = default(BlaiFetchEmitResult)
  var
    stagedLayer = layer
    stagedCtrl = ctrl
  if kind == blaiFetchRoute:
    var routePlan: BlaiRouteSramSlotPlan
    blaiPlanRouteSramSlotsInto(stagedLayer, stagedCtrl, routePlan)
    outResult.memoryPlan = routePlan.memory
    outResult.fetchFits = routePlan.fits
    if not outResult.fetchFits:
      return
    blaiApplyRouteSramSlotPlan(stagedCtrl, stagedLayer, routePlan)
    blaiEmitRouteLayerInstructionsInto(
      stagedLayer, routePlan, stream, useTflite, outResult.instructions,
      includeExtra, descriptorHalt, midOutState)
  else:
    blaiPlanFetchMemoryInto(
      stagedLayer, stagedCtrl, kind, outResult.memoryPlan)
    outResult.fetchFits = outResult.memoryPlan.fits
    if not outResult.fetchFits:
      return
    blaiApplyFetchMemoryPlan(stagedCtrl, stagedLayer, outResult.memoryPlan)
    blaiEmitLayerInstructionsInto(
      stagedLayer, outResult.memoryPlan, stream, useTflite,
      outResult.instructions, c2, includeExtra, descriptorHalt, midOutState)
  outResult.fits = outResult.instructions.fits
  let commitApply = blaiFetchEmitCommitApplyPlan(
    outResult.fits, stagedLayer, stagedCtrl)
  if commitApply.valid:
    blaiApplyFetchEmitCommitState(
      layer, ctrl, blaiFetchEmitCommitState(commitApply))

proc blaiEmitFetchLayerInstructions*(layer: var BlaiCpuInstLayer64,
                                     ctrl: var BlaiPsramCtrl,
                                     stream: var openArray[BlaiInstruction],
                                     kind: BlaiFetchMemoryKind,
                                     useTflite: bool,
                                     c2: uint32 = 0'u32,
                                     includeExtra: bool = false,
                                     descriptorHalt: bool = false,
                                     midOutState: bool = false): BlaiFetchEmitResult =
  ## Convenience result-returning wrapper for fetch instruction emission.
  blaiEmitFetchLayerInstructionsInto(
    layer, ctrl, stream, kind, useTflite, result, c2, includeExtra,
    descriptorHalt, midOutState)

proc blaiEncodeCpuLayerInto*(layer: var BlaiCpuInstLayer64,
                             ctrl: var BlaiPsramCtrl,
                             stream: var openArray[BlaiInstruction],
                             allocationSucceeded: bool,
                             useTflite: bool,
                             outResult: var BlaiCpuLayerEncodeResult,
                             c2: uint32 = 0'u32,
                             includeExtra: bool = false,
                             descriptorHalt: bool = false,
                             midOutState: bool = false) =
  ## Recovered bounded `BLAI_encode` wrapper around the pure fetch emitter.
  ##
  ## This low-level variant accepts an explicit allocator success flag and a
  ## caller-populated `BlaiPsramCtrl`, which keeps allocator oracle tests
  ## separate from the allocator-backed wrapper.
  outResult = default(BlaiCpuLayerEncodeResult)
  blaiPlanEncodeInto(layer, allocationSucceeded, outResult.plan)
  if not outResult.plan.runnable:
    blaiMarkEncodeFailed(layer)
    return

  blaiClearInstructionStream(stream)
  let startApply = blaiEncodeStartApplyPlan()
  doAssert startApply.valid
  blaiApplyEncodeStartState(
    layer, outResult, blaiEncodeStartState(startApply))
  blaiEmitFetchLayerInstructionsInto(
    layer, ctrl, stream, blaiFetchKind(outResult.plan.dispatch),
    useTflite, outResult.fetch, c2, includeExtra, descriptorHalt, midOutState)
  outResult.encoded = outResult.fetch.fits
  if outResult.encoded:
    blaiApplyMemoryPlan(layer, ctrl)
  else:
    blaiMarkEncodeFailed(layer)

proc blaiEncodeCpuLayer*(layer: var BlaiCpuInstLayer64,
                         ctrl: var BlaiPsramCtrl,
                         stream: var openArray[BlaiInstruction],
                         allocationSucceeded: bool,
                         useTflite: bool,
                         c2: uint32 = 0'u32,
                         includeExtra: bool = false,
                         descriptorHalt: bool = false,
                         midOutState: bool = false): BlaiCpuLayerEncodeResult =
  ## Convenience result-returning wrapper for the recovered encoder.
  blaiEncodeCpuLayerInto(
    layer, ctrl, stream, allocationSucceeded, useTflite, result,
    c2, includeExtra, descriptorHalt, midOutState)

proc blaiEncodeCpuLayerWithAllocatorInto*(layer: var BlaiCpuInstLayer64,
                                          ctrl: var BlaiPsramCtrl,
                                          stream: var openArray[BlaiInstruction],
                                          outResult: var BlaiCpuLayerAllocEncodeResult,
                                          useTflite: bool,
                                          c2: uint32 = 0'u32,
                                          includeExtra: bool = false,
                                          descriptorHalt: bool = false,
                                          midOutState: bool = false) =
  ## Recovered bounded `BLAI_encode` wrapper including `BLAI_MEM_alloc`.
  outResult = default(BlaiCpuLayerAllocEncodeResult)
  blaiPlanMemAllocInto(layer, outResult.allocation)
  if outResult.allocation.fits:
    blaiApplyMemAllocPlan(ctrl, outResult.allocation)
  blaiEncodeCpuLayerInto(
    layer, ctrl, stream, outResult.allocation.fits,
    useTflite, outResult.encode, c2, includeExtra, descriptorHalt, midOutState)
  outResult.encoded = outResult.encode.encoded

proc blaiEncodeCpuLayerWithAllocator*(layer: var BlaiCpuInstLayer64,
                                      ctrl: var BlaiPsramCtrl,
                                      stream: var openArray[BlaiInstruction],
                                      useTflite: bool,
                                      c2: uint32 = 0'u32,
                                      includeExtra: bool = false,
                                      descriptorHalt: bool = false,
                                      midOutState: bool = false): BlaiCpuLayerAllocEncodeResult =
  ## Convenience result-returning wrapper for the recovered allocator-backed
  ## `BLAI_encode` path.
  blaiEncodeCpuLayerWithAllocatorInto(
    layer, ctrl, stream, result,
    useTflite, c2, includeExtra, descriptorHalt, midOutState)

