proc blaiCpuByteSpanFitsInto*(
    startIndex: Natural,
    spanBytes: uint32,
    byteCount: uint64,
    outResult: var BlaiCpuByteSpanFit) =
  ## Check one recovered CPU-stream byte span against caller-owned bytes.
  outResult = default(BlaiCpuByteSpanFit)
  let start = startIndex.uint64
  outResult.startIndex = blaiU64SaturatedU32Count(start)
  outResult.spanBytes = spanBytes
  outResult.startFits = start <= byteCount
  if not outResult.startFits:
    return
  let required = start + spanBytes.uint64
  outResult.requiredBytes = blaiU64SaturatedU32Count(required)
  outResult.bytesFit = byteCount - start >= spanBytes.uint64
  outResult.fits = outResult.bytesFit

proc blaiCpuByteSpanFits*(
    startIndex: Natural,
    spanBytes: uint32,
    byteCount: uint64): bool =
  ## Boolean wrapper for recovered CPU-stream byte-span checks.
  var fit: BlaiCpuByteSpanFit
  blaiCpuByteSpanFitsInto(startIndex, spanBytes, byteCount, fit)
  fit.fits

proc blaiU32ExactIntCount*(count: uint32, outCount: var int): bool =
  ## Project a recovered uint32 count into Nim's index domain without clamping.
  if count.uint64 > high(int).uint64:
    return false
  outCount = count.int
  true

proc blaiCheckedIntByteWindow*(offset, bytes: uint32): BlaiCheckedByteWindow =
  ## Convert a checked uint32 byte range into int indexes for Nim openArray views.
  let rangeFit = blaiUint32AddressRangeFit(offset, bytes)
  if not rangeFit.fits or rangeFit.endExclusive > high(int).uint64:
    return
  if not blaiU32ExactIntCount(offset, result.start):
    return
  if not blaiU32ExactIntCount(bytes, result.count):
    return
  result.fits = true

proc blaiCheckedByteIndex*(byteIndex: int): BlaiCheckedByteIndex =
  ## Validate one byte index before it is used against a typed byte stream.
  if byteIndex < 0:
    return
  result.byteIndex = byteIndex
  result.valid = true

proc blaiFixedRowByteCursor*(rowIndex, byteIndex, rowBytes: int):
    BlaiFixedRowByteCursor =
  ## Resolve one byte inside a fixed-width recovered row layout.
  let byte = blaiCheckedByteIndex(byteIndex)
  if rowIndex < 0 or rowBytes <= 0 or not byte.valid or
      byte.byteIndex >= rowBytes:
    return
  if rowIndex > (high(int) - byte.byteIndex) div rowBytes:
    return
  result.rowIndex = rowIndex
  result.byteIndex = byte.byteIndex
  result.rowBytes = rowBytes
  result.absoluteIndex = rowIndex * rowBytes + byte.byteIndex
  result.valid = true

proc blaiCanReadCpuBiasInto*(bytes: openArray[uint8],
                             startIndex: Natural,
                             useTflite: bool,
                             outResult: var BlaiCpuByteReadFitResult) =
  ## Check a little-endian CPU bias read against caller-provided bytes.
  outResult = default(BlaiCpuByteReadFitResult)
  outResult.readBytes = blaiCpuBiasBytesPerElement(useTflite)
  var spanFit: BlaiCpuByteSpanFit
  blaiCpuByteSpanFitsInto(
    startIndex, outResult.readBytes, bytes.len.uint64, spanFit)
  outResult.startFits = spanFit.startFits
  outResult.bytesFit = spanFit.bytesFit
  outResult.startIndex = spanFit.startIndex
  outResult.requiredBytes = spanFit.requiredBytes
  outResult.fits = spanFit.fits

proc blaiCanReadCpuBias*(bytes: openArray[uint8],
                         startIndex: Natural,
                         useTflite: bool): bool =
  ## Boolean wrapper for CPU bias byte-read bounds checks.
  var fit: BlaiCpuByteReadFitResult
  blaiCanReadCpuBiasInto(bytes, startIndex, useTflite, fit)
  fit.fits

proc blaiCpuBiasReadWindow*(bytes: openArray[uint8],
                            startIndex: Natural,
                            useTflite: bool): BlaiCpuByteWindow =
  ## Checked view over the bytes consumed by one CPU bias stream value.
  blaiCanReadCpuBiasInto(bytes, startIndex, useTflite, result.fit)
  if not result.fit.fits or result.fit.readBytes == 0:
    return
  let window =
    blaiCheckedIntByteWindow(result.fit.startIndex, result.fit.readBytes)
  if not window.fits:
    return
  result.start = window.start
  result.count = window.count
  result.fits = true

template blaiCpuByteOpenArray(bytes: untyped,
                              window: BlaiCpuByteWindow): untyped =
  bytes.toOpenArray(window.start, window.start + window.count - 1)

proc blaiLe32ByteCursor*(byteIndex: int): BlaiLe32ByteCursor
proc blaiLe32Byte*(value: uint32, cursor: BlaiLe32ByteCursor): uint8
proc blaiLe32MergeByte*(value: var uint32,
                        byte: uint8,
                        cursor: BlaiLe32ByteCursor)

proc blaiReadCpuBiasWindow*(bytes: openArray[uint8],
                            window: BlaiCpuByteWindow): uint32 =
  ## SDK bias stream little-endian accumulation over a checked byte window.
  doAssert window.fits
  for k in 0 ..< window.count:
    let cursor = blaiLe32ByteCursor(k)
    doAssert cursor.valid
    blaiLe32MergeByte(result, blaiCpuByteOpenArray(bytes, window)[k], cursor)

proc blaiReadCpuBias*(bytes: openArray[uint8],
                      startIndex: Natural,
                      useTflite: bool): uint32 =
  ## SDK bias stream little-endian byte accumulation.
  blaiReadCpuBiasWindow(
    bytes, blaiCpuBiasReadWindow(bytes, startIndex, useTflite))

proc blaiCpuWeightValue*(byte: uint8): int32 =
  ## SDK CPU weight loader stores `fixed_point_t` bytes, sign-extended when the
  ## destination is an `int` array.
  if byte >= 0x80'u8:
    byte.int32 - 0x100'i32
  else:
    byte.int32

proc blaiCpuWeightI8Value*(byte: uint8): int8 =
  blaiCpuWeightValue(byte).int8

proc blaiCanStoreCpuWeightsInto*(plan: BlaiCpuWeightStreamPlan,
                                 bytes: openArray[uint8],
                                 startIndex: Natural,
                                 weightElements: uint32,
                                 outResult: var BlaiCpuStreamStoreFitResult) =
  ## Check one CPU weight stream copy against source bytes and destination items.
  outResult = default(BlaiCpuStreamStoreFitResult)
  outResult.active = plan.active
  outResult.streamBytes = plan.streamBytes
  outResult.requiredElements = plan.elementCount
  outResult.availableElements = weightElements
  outResult.startIndex = blaiU64SaturatedU32Count(startIndex.uint64)
  if not plan.active:
    outResult.startFits = true
    outResult.bytesFit = true
    outResult.elementsFit = true
    outResult.fits = true
    return
  var spanFit: BlaiCpuByteSpanFit
  blaiCpuByteSpanFitsInto(
    startIndex, plan.streamBytes, bytes.len.uint64, spanFit)
  outResult.startFits = spanFit.startFits
  outResult.bytesFit = spanFit.bytesFit
  outResult.startIndex = spanFit.startIndex
  outResult.requiredBytes = spanFit.requiredBytes
  outResult.elementsFit = weightElements >= plan.elementCount
  outResult.fits =
    outResult.startFits and outResult.bytesFit and outResult.elementsFit

proc blaiCanStoreCpuWeights*(plan: BlaiCpuWeightStreamPlan,
                             bytes: openArray[uint8],
                             startIndex: Natural,
                             weightElements: uint32): bool =
  ## Boolean wrapper for CPU weight stream store bounds checks.
  var fit: BlaiCpuStreamStoreFitResult
  blaiCanStoreCpuWeightsInto(plan, bytes, startIndex, weightElements, fit)
  fit.fits

proc blaiCpuStreamWindowFromFit(
    fit: BlaiCpuStreamStoreFitResult): BlaiCpuStreamWindow =
  ## Convert an existing CPU stream fit result into a concrete byte window.
  result.fit = fit
  result.active = fit.active
  if not fit.active:
    result.fits = fit.fits
    return
  if not fit.fits:
    return
  if fit.streamBytes == 0'u32 and fit.requiredElements != 0'u32:
    return
  let window = blaiCheckedIntByteWindow(fit.startIndex, fit.streamBytes)
  if not window.fits:
    return
  result.start = window.start
  result.count = window.count
  if not blaiU32ExactIntCount(fit.requiredElements, result.elements):
    return
  result.fits = true

proc blaiCpuWeightStreamWindow*(plan: BlaiCpuWeightStreamPlan,
                                bytes: openArray[uint8],
                                startIndex: Natural,
                                weightElements: uint32): BlaiCpuStreamWindow =
  ## Checked view over one CPU weight stream segment.
  var fit: BlaiCpuStreamStoreFitResult
  blaiCanStoreCpuWeightsInto(plan, bytes, startIndex, weightElements, fit)
  blaiCpuStreamWindowFromFit(fit)

template blaiCpuStreamOpenArray(bytes: untyped,
                                window: BlaiCpuStreamWindow): untyped =
  bytes.toOpenArray(window.start, window.start + window.count - 1)

proc blaiStoreCpuWeightsI8Into*(plan: BlaiCpuWeightStreamPlan,
                                bytes: openArray[uint8],
                                startIndex: Natural,
                                weights: var openArray[int8],
                                outResult: var BlaiCpuWeightStoreResult) =
  ## Store one SDK CPU weight stream segment into a fixed-point weight buffer.
  outResult = default(BlaiCpuWeightStoreResult)
  outResult.active = plan.active
  outResult.storageMatches = true
  if not plan.active:
    outResult.fits = true
    outResult.stored = true
    return
  if plan.storage != blaiCpuWeightI8:
    outResult.storageMatches = false
    return
  let window = blaiCpuWeightStreamWindow(
    plan, bytes, startIndex, blaiOpenArrayLenU32(weights))
  outResult.fits = window.fits
  if not outResult.fits:
    return
  for i in 0 ..< window.elements:
    weights[i] =
      blaiCpuWeightI8Value(blaiCpuStreamOpenArray(bytes, window)[i])
  outResult.stored = true

proc blaiStoreCpuWeightsI8*(plan: BlaiCpuWeightStreamPlan,
                            bytes: openArray[uint8],
                            startIndex: Natural,
                            weights: var openArray[int8]): bool =
  ## Compatibility wrapper for the caller-owned fixed-point weight store result.
  var store: BlaiCpuWeightStoreResult
  blaiStoreCpuWeightsI8Into(plan, bytes, startIndex, weights, store)
  store.stored

proc blaiStoreCpuWeightsI32Into*(plan: BlaiCpuWeightStreamPlan,
                                 bytes: openArray[uint8],
                                 startIndex: Natural,
                                 weights: var openArray[int32],
                                 outResult: var BlaiCpuWeightStoreResult) =
  ## Store one SDK CPU weight stream segment into an `int`-style weight buffer.
  outResult = default(BlaiCpuWeightStoreResult)
  outResult.active = plan.active
  outResult.storageMatches = true
  if not plan.active:
    outResult.fits = true
    outResult.stored = true
    return
  if plan.storage != blaiCpuWeightI32:
    outResult.storageMatches = false
    return
  let window = blaiCpuWeightStreamWindow(
    plan, bytes, startIndex, blaiOpenArrayLenU32(weights))
  outResult.fits = window.fits
  if not outResult.fits:
    return
  for i in 0 ..< window.elements:
    weights[i] =
      blaiCpuWeightValue(blaiCpuStreamOpenArray(bytes, window)[i])
  outResult.stored = true

proc blaiStoreCpuWeightsI32*(plan: BlaiCpuWeightStreamPlan,
                             bytes: openArray[uint8],
                             startIndex: Natural,
                             weights: var openArray[int32]): bool =
  ## Compatibility wrapper for the caller-owned int-style weight store result.
  var store: BlaiCpuWeightStoreResult
  blaiStoreCpuWeightsI32Into(plan, bytes, startIndex, weights, store)
  store.stored

proc blaiStoreCpuWeightValuesInto*(plan: BlaiCpuWeightStreamPlan,
                                   bytes: openArray[uint8],
                                   startIndex: Natural,
                                   weights: var openArray[int32],
                                   outResult: var BlaiCpuWeightStoreResult) =
  ## Store one CPU weight stream segment as sign-extended values for NPU reorder.
  ##
  ## The recovered NPU weight materializer consumes int-like source values and
  ## later emits only the low byte into the hardware weight stream. This helper
  ## accepts either CPU stream storage mode and keeps that boundary explicit.
  outResult = default(BlaiCpuWeightStoreResult)
  outResult.active = plan.active
  outResult.storageMatches = true
  if not plan.active:
    outResult.fits = true
    outResult.stored = true
    return
  let window = blaiCpuWeightStreamWindow(
    plan, bytes, startIndex, blaiOpenArrayLenU32(weights))
  outResult.fits = window.fits
  if not outResult.fits:
    return
  for i in 0 ..< window.elements:
    weights[i] =
      blaiCpuWeightValue(blaiCpuStreamOpenArray(bytes, window)[i])
  outResult.stored = true

proc blaiStoreCpuWeightValues*(plan: BlaiCpuWeightStreamPlan,
                               bytes: openArray[uint8],
                               startIndex: Natural,
                               weights: var openArray[int32]): bool =
  ## Compatibility wrapper for caller-owned CPU weight value store results.
  var store: BlaiCpuWeightStoreResult
  blaiStoreCpuWeightValuesInto(plan, bytes, startIndex, weights, store)
  store.stored

proc blaiCanStoreCpuBiasesInto*(plan: BlaiCpuBiasStreamPlan,
                                bytes: openArray[uint8],
                                startIndex: Natural,
                                biasElements: uint32,
                                outResult: var BlaiCpuStreamStoreFitResult) =
  ## Check one CPU bias stream copy against source bytes and destination items.
  outResult = default(BlaiCpuStreamStoreFitResult)
  outResult.active = plan.active
  outResult.streamBytes = plan.streamBytes
  outResult.requiredElements = plan.elementCount
  outResult.availableElements = biasElements
  outResult.startIndex = blaiU64SaturatedU32Count(startIndex.uint64)
  if not plan.active:
    outResult.startFits = true
    outResult.bytesFit = true
    outResult.elementsFit = true
    outResult.fits = true
    return
  var spanFit: BlaiCpuByteSpanFit
  blaiCpuByteSpanFitsInto(
    startIndex, plan.streamBytes, bytes.len.uint64, spanFit)
  outResult.startFits = spanFit.startFits
  outResult.bytesFit = spanFit.bytesFit
  outResult.startIndex = spanFit.startIndex
  outResult.requiredBytes = spanFit.requiredBytes
  outResult.elementsFit = biasElements >= plan.elementCount
  outResult.fits =
    outResult.startFits and outResult.bytesFit and outResult.elementsFit

proc blaiCanStoreCpuBiases*(plan: BlaiCpuBiasStreamPlan,
                            bytes: openArray[uint8],
                            startIndex: Natural,
                            biasElements: uint32): bool =
  ## Boolean wrapper for CPU bias stream store bounds checks.
  var fit: BlaiCpuStreamStoreFitResult
  blaiCanStoreCpuBiasesInto(plan, bytes, startIndex, biasElements, fit)
  fit.fits

proc blaiCpuBiasStreamWindow*(plan: BlaiCpuBiasStreamPlan,
                              bytes: openArray[uint8],
                              startIndex: Natural,
                              biasElements: uint32): BlaiCpuStreamWindow =
  ## Checked view over one CPU bias stream segment.
  var fit: BlaiCpuStreamStoreFitResult
  blaiCanStoreCpuBiasesInto(plan, bytes, startIndex, biasElements, fit)
  blaiCpuStreamWindowFromFit(fit)

proc blaiCpuBiasElementWidth*(plan: BlaiCpuBiasStreamPlan,
                              outWidth: var int): bool =
  ## Resolve one recovered CPU-bias element width for little-endian lane loops.
  var maxWidth: int
  if not blaiU32ExactIntCount(BlaiNpuBiasElementBytes, maxWidth):
    return false
  if not blaiU32ExactIntCount(plan.bytesPerElement, outWidth):
    return false
  outWidth > 0 and outWidth <= maxWidth

proc blaiCpuBiasElementByteCursor*(elementIndex, laneIndex, elementWidth: int):
    BlaiCpuBiasElementByteCursor =
  ## Resolve one byte lane inside the compact CPU bias stream window.
  if elementIndex < 0 or laneIndex < 0 or elementWidth <= 0:
    return
  if laneIndex >= elementWidth:
    return
  let lane = blaiLe32ByteCursor(laneIndex)
  if not lane.valid:
    return
  if elementIndex > (high(int) - laneIndex) div elementWidth:
    return
  result.elementIndex = elementIndex
  result.laneIndex = laneIndex
  result.elementWidth = elementWidth
  result.byteIndex = elementIndex * elementWidth + laneIndex
  result.lane = lane
  result.valid = true

proc blaiStoreCpuBiasesInto*(plan: BlaiCpuBiasStreamPlan,
                             bytes: openArray[uint8],
                             startIndex: Natural,
                             biases: var openArray[int32],
                             outResult: var BlaiCpuBiasStoreResult) =
  ## Store one SDK CPU bias stream segment as little-endian accumulated `int`
  ## values. Fixed-point models still use unsigned one-byte bias entries.
  outResult = default(BlaiCpuBiasStoreResult)
  outResult.active = plan.active
  if not plan.active:
    outResult.fits = true
    outResult.stored = true
    return
  let window = blaiCpuBiasStreamWindow(
    plan, bytes, startIndex, blaiOpenArrayLenU32(biases))
  outResult.fits = window.fits
  if not outResult.fits:
    return
  var width: int
  if not blaiCpuBiasElementWidth(plan, width):
    return
  for i in 0 ..< window.elements:
    var value = 0'u32
    for k in 0 ..< width:
      let cursor = blaiCpuBiasElementByteCursor(i, k, width)
      if not cursor.valid:
        return
      blaiLe32MergeByte(
        value, blaiCpuStreamOpenArray(bytes, window)[cursor.byteIndex],
        cursor.lane)
    let biasAbi = blaiCpuBiasBitsAbi(value)
    if not biasAbi.valid:
      return
    biases[i] = biasAbi.value
  outResult.stored = true

proc blaiStoreCpuBiases*(plan: BlaiCpuBiasStreamPlan,
                         bytes: openArray[uint8],
                         startIndex: Natural,
                         biases: var openArray[int32]): bool =
  ## Compatibility wrapper for caller-owned CPU bias store results.
  var store: BlaiCpuBiasStoreResult
  blaiStoreCpuBiasesInto(plan, bytes, startIndex, biases, store)
  store.stored

proc blaiSpatialElements*(w, h: uint32): uint32 =
  w * h

proc blaiMainInputChannels*(layer: BlaiCpuInstLayer64,
                            layerIndex: uint32): uint32 =
  ## SDK `Store_tensor_data_to_NPU` first-input channel count.
  result = nonNegativeU32(layer.c)
  if layerIndex == 0'u32 and result == 3'u32:
    result = 4

proc blaiMainInputRowPadded*(layer: BlaiCpuInstLayer64,
                             layerIndex: uint32): bool =
  let channels = nonNegativeU32(layer.c)
  let firstLayerPad = layerIndex == 0'u32 and
    (channels == 3'u32 or channels == 1'u32)
  not (channels mod 4'u32 == 0'u32 or firstLayerPad)

proc blaiNpuInputTransferPlanInto*(layer: BlaiCpuInstLayer64,
                                   layerIndex: uint32,
                                   inputIndex: range[0 .. 7],
                                   outResult: var BlaiTensorTransferPlan) =
  ## Recover SDK `Store_tensor_data_to_NPU` byte counts for one input tensor.
  outResult = default(BlaiTensorTransferPlan)
  let
    w = nonNegativeU32(layer.w)
    h = nonNegativeU32(layer.h)
    spatial = blaiSpatialElements(w, h)
  outResult.active = inputIndex == 0 or
    (inputIndex.uint32 < nonNegativeU32(layer.inputNum) and blaiIsMultiInput(layer))
  if not outResult.active:
    return
  outResult.slot = nonNegativeU32(layer.dramIn[inputIndex])
  if inputIndex == 0:
    outResult.actualChannels = nonNegativeU32(layer.c)
    outResult.paddedChannels = blaiMainInputChannels(layer, layerIndex)
    outResult.rowPadded = blaiMainInputRowPadded(layer, layerIndex)
    if outResult.rowPadded:
      outResult.paddedChannels = blaiChannelAlign4(outResult.actualChannels)
  else:
    outResult.actualChannels = nonNegativeU32(
      blaiLayerCn(layer, inputIndex.uint32))
    outResult.paddedChannels = if outResult.actualChannels mod 4'u32 == 0'u32:
      outResult.actualChannels
    else:
      blaiChannelAlign4(outResult.actualChannels)
    outResult.rowPadded = outResult.paddedChannels != outResult.actualChannels
  outResult.elements = spatial * outResult.paddedChannels
  outResult.bytes = outResult.elements

proc blaiNpuInputTransferPlan*(layer: BlaiCpuInstLayer64,
                               layerIndex: uint32,
                               inputIndex: range[0 .. 7]): BlaiTensorTransferPlan =
  ## Convenience result-returning wrapper for input tensor staging counts.
  blaiNpuInputTransferPlanInto(layer, layerIndex, inputIndex, result)

proc blaiRouteMidInputChannels*(layer: BlaiCpuInstLayer64): uint32 =
  ## SDK mid-output route input channel accumulation.
  result = nonNegativeU32(layer.c)
  if blaiLayerTypeFromSdk(layer.layerType) in {blaiRouteConv, blaiRouteMax,
      blaiRouteUpsample, blaiRoute}:
    let count = max(nonNegativeU32(layer.n), 1'u32) - 1'u32
    for i in 0 ..< blaiBoundedU32Count(count, BlaiMaxInputNum - 1):
      result += nonNegativeU32(layer.cn[i])

proc blaiNpuOutputTransferPlanInto*(layer: BlaiCpuInstLayer64,
                                    outResult: var BlaiNpuOutputTransferPlan) =
  ## Recover SDK `Load_NPU_data_to_tensor` byte counts.
  outResult = default(BlaiNpuOutputTransferPlan)
  let
    outC = nonNegativeU32(layer.outC)
    outputPaddedC = blaiChannelAlign4(outC)
    outputSpatial =
      if outputPaddedC == outC:
        blaiSpatialElements(nonNegativeU32(layer.outW), nonNegativeU32(layer.outH))
      else:
        blaiSpatialElements(nonNegativeU32(layer.w), nonNegativeU32(layer.h))
  outResult.output.active = true
  outResult.output.slot = nonNegativeU32(layer.dramOut[0])
  outResult.output.actualChannels = outC
  outResult.output.paddedChannels = outputPaddedC
  outResult.output.rowPadded = outputPaddedC != outC
  outResult.output.elements = outputSpatial * outputPaddedC
  outResult.output.bytes = outResult.output.elements

  if layer.midOut != 0:
    let layerType = blaiLayerTypeFromSdk(layer.layerType)
    let midChannels = if layerType == blaiConvMax:
      outC
    else:
      blaiRouteMidInputChannels(layer)
    outResult.midOutput.active = true
    outResult.midOutput.slot = nonNegativeU32(layer.dramMidOut)
    outResult.midOutput.actualChannels = midChannels
    outResult.midOutput.paddedChannels = midChannels
    outResult.midOutput.elements =
      blaiSpatialElements(nonNegativeU32(layer.w), nonNegativeU32(layer.h)) * midChannels
    outResult.midOutput.bytes = outResult.midOutput.elements

proc blaiNpuOutputTransferPlan*(layer: BlaiCpuInstLayer64): BlaiNpuOutputTransferPlan =
  ## Convenience result-returning wrapper for output tensor readback counts.
  blaiNpuOutputTransferPlanInto(layer, result)

proc blaiPatchSlotOffset*(slot, patchSize: uint32): BlaiPatchSlotOffset =
  ## Resolve a recovered PSRAM/DATA patch slot to a bounded byte offset.
  result.slot = slot
  result.patchSize = patchSize
  if patchSize != 0'u32 and slot > high(uint32) div patchSize:
    return
  result.offset = slot * patchSize
  result.valid = true

proc blaiPatchSlotOffset*(slot: int32,
                          patchSize: uint32): BlaiPatchSlotOffset =
  ## Resolve a signed SDK memory slot, rejecting negative pointer-side values.
  let slotIndex = blaiPatchSlotIndexAbi(slot)
  if not slotIndex.valid:
    return
  blaiPatchSlotOffset(slotIndex.value, patchSize)

proc blaiTensorBufferOffset*(plan: BlaiTensorTransferPlan,
                             patchSize: uint32): uint32 =
  let offset = blaiPatchSlotOffset(plan.slot, patchSize)
  if offset.valid: offset.offset else: high(uint32)

proc blaiDataBufferRangeFitsInto*(
    active: bool,
    offset, bytes, bufferBytes: uint32,
    outResult: var BlaiDataBufferRangeFit) =
  ## Check a DATA-buffer-relative byte range and caller-owned capacity.
  outResult = default(BlaiDataBufferRangeFit)
  outResult.active = active
  outResult.offsetFits = true
  outResult.offset = offset
  outResult.bytes = bytes
  if not active:
    outResult.bufferFits = true
    outResult.fits = true
    return
  var rangeFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), offset, bytes, rangeFit)
  outResult.requiredBytes = rangeFit.requiredCount
  if not rangeFit.fits:
    outResult.offsetFits = false
    return
  var bufferFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(bufferBytes, offset, bytes, bufferFit)
  outResult.bufferFits = bufferFit.fits
  outResult.fits = outResult.offsetFits and outResult.bufferFits

proc blaiDataBufferRangeFits*(
    active: bool,
    offset, bytes, bufferBytes: uint32): bool =
  ## Boolean wrapper for DATA-buffer-relative range fit checks.
  var fit: BlaiDataBufferRangeFit
  blaiDataBufferRangeFitsInto(active, offset, bytes, bufferBytes, fit)
  fit.fits

proc blaiSdkInputBufferPlanInto*(
    bufferToken: uint32,
    bufferBytes: uint32,
    outResult: var BlaiSdkInputBufferPlan) =
  ## Recover SDK `blai_getInputBuffer` as a typed caller-owned token.
  outResult = default(BlaiSdkInputBufferPlan)
  outResult.bufferToken = bufferToken
  outResult.bufferBytes = bufferBytes
  outResult.bufferPresent = bufferToken != 0'u32
  outResult.capacityPresent = bufferBytes != 0'u32
  outResult.valid = outResult.bufferPresent and outResult.capacityPresent

proc blaiSdkInputBufferPlan*(
    bufferToken: uint32,
    bufferBytes: uint32): BlaiSdkInputBufferPlan =
  ## Convenience wrapper for SDK input-buffer projection.
  blaiSdkInputBufferPlanInto(bufferToken, bufferBytes, result)

proc blaiSdkNetInfoPlanInto*(
    modelToken: uint32,
    netToken: uint32,
    outResult: var BlaiSdkNetInfoPlan) =
  ## Recover SDK `blai_getNetInfo` without exposing a raw model pointer.
  outResult = default(BlaiSdkNetInfoPlan)
  outResult.modelToken = modelToken
  outResult.netToken = netToken
  outResult.modelPresent = modelToken != 0'u32
  outResult.netPresent = netToken != 0'u32
  outResult.valid = outResult.modelPresent and outResult.netPresent

proc blaiSdkNetInfoPlan*(
    modelToken: uint32,
    netToken: uint32): BlaiSdkNetInfoPlan =
  ## Convenience wrapper for SDK net-info projection.
  blaiSdkNetInfoPlanInto(modelToken, netToken, result)

proc blaiSdkLoadModelFromFilePlanInto*(
    modelToken: uint32,
    nameToken: uint32,
    outResult: var BlaiSdkLoadModelFromFilePlan) =
  ## Recover SDK `blai_load_model_from_file`: always invalid input.
  outResult = default(BlaiSdkLoadModelFromFilePlan)
  outResult.modelToken = modelToken
  outResult.nameToken = nameToken
  outResult.modelPresent = modelToken != 0'u32
  outResult.namePresent = nameToken != 0'u32
  outResult.status = blaiSdkInvalidInput
  outResult.returnsInvalidInput = true
  outResult.valid =
    outResult.status == blaiSdkInvalidInput and outResult.returnsInvalidInput

proc blaiSdkLoadModelFromFilePlan*(
    modelToken: uint32,
    nameToken: uint32): BlaiSdkLoadModelFromFilePlan =
  ## Convenience wrapper for unsupported file-load projection.
  blaiSdkLoadModelFromFilePlanInto(modelToken, nameToken, result)

proc blaiSdkCreatePlanInto*(
    initialNpuInited: bool,
    modelToken: uint32,
    netToken: uint32,
    outResult: var BlaiSdkCreatePlan) =
  ## Recover SDK `blai_create` allocation and initialization decisions.
  outResult = default(BlaiSdkCreatePlan)
  outResult.initialNpuInited = initialNpuInited
  outResult.modelToken = modelToken
  outResult.netToken = netToken
  outResult.modelAllocated = modelToken != 0'u32
  outResult.netAllocated = netToken != 0'u32
  outResult.callsHardwareInit = not initialNpuInited
  outResult.finalNpuInited = true
  if not outResult.modelAllocated:
    outResult.valid = outResult.finalNpuInited
    return
  if not outResult.netAllocated:
    outResult.freesModelOnNetFailure = true
    outResult.valid = outResult.finalNpuInited
    return
  outResult.netZeroed = true
  outResult.parentLinked = true
  outResult.shareBufferCleared = true
  outResult.callsRuntimeInit = true
  outResult.returnedModelToken = modelToken
  outResult.returnsModel = true
  outResult.valid =
    outResult.finalNpuInited and outResult.netZeroed and
      outResult.parentLinked and outResult.shareBufferCleared and
      outResult.callsRuntimeInit

proc blaiSdkCreatePlan*(
    initialNpuInited: bool,
    modelToken: uint32,
    netToken: uint32): BlaiSdkCreatePlan =
  ## Convenience wrapper for SDK create projection.
  blaiSdkCreatePlanInto(initialNpuInited, modelToken, netToken, result)

proc blaiSdkStartComputePlanInto*(
    modelToken: uint32,
    inferenceStatus: BlaiSdkStatus,
    outResult: var BlaiSdkStartComputePlan) =
  ## Recover SDK `blai_startCompute` null guard and inference delegation.
  outResult = default(BlaiSdkStartComputePlan)
  outResult.modelToken = modelToken
  outResult.inferenceStatus = inferenceStatus
  outResult.modelPresent = modelToken != 0'u32
  if not outResult.modelPresent:
    outResult.status = blaiSdkUnavailableDevice
    outResult.returnsUnavailableDevice = true
    outResult.valid = true
    return
  outResult.delegatesToInference = true
  outResult.status = inferenceStatus
  outResult.valid = true

proc blaiSdkStartComputePlan*(
    modelToken: uint32,
    inferenceStatus: BlaiSdkStatus): BlaiSdkStartComputePlan =
  ## Convenience wrapper for SDK start-compute projection.
  blaiSdkStartComputePlanInto(modelToken, inferenceStatus, result)

proc blaiSdkFreePlanInto*(
    modelToken: uint32,
    modelBufferAllocated, netAllocated: bool,
    cpuInstructionAllocated, cpuBiasAllocated, cpuWeightsAllocated: bool,
    npuInstructionAllocated, npuBiasAllocated, npuWeightsAllocated: bool,
    outResult: var BlaiSdkFreePlan) =
  ## Recover SDK `blai_free` top-level ownership release sequence.
  outResult = default(BlaiSdkFreePlan)
  outResult.modelToken = modelToken
  outResult.modelPresent = modelToken != 0'u32
  outResult.callsInstRelease = true
  outResult.freesModelBuffer = modelBufferAllocated
  outResult.clearsModelBuffer = true
  outResult.freesNet = netAllocated
  outResult.clearsNet = true
  outResult.freesCpuInstruction = cpuInstructionAllocated
  outResult.freesCpuBias = cpuBiasAllocated
  outResult.freesCpuWeights = cpuWeightsAllocated
  outResult.freesNpuInstruction = npuInstructionAllocated
  outResult.freesNpuBias = npuBiasAllocated
  outResult.freesNpuWeights = npuWeightsAllocated
  outResult.freesModel = outResult.modelPresent
  outResult.preservesNpuRuntime = true
  outResult.status = blaiSdkNoError
  outResult.valid =
    outResult.callsInstRelease and outResult.clearsModelBuffer and
      outResult.clearsNet and outResult.preservesNpuRuntime and
      outResult.status == blaiSdkNoError

proc blaiSdkFreePlan*(
    modelToken: uint32,
    modelBufferAllocated, netAllocated: bool,
    cpuInstructionAllocated, cpuBiasAllocated, cpuWeightsAllocated: bool,
    npuInstructionAllocated, npuBiasAllocated, npuWeightsAllocated: bool):
    BlaiSdkFreePlan =
  ## Convenience wrapper for SDK free projection.
  blaiSdkFreePlanInto(
    modelToken, modelBufferAllocated, netAllocated, cpuInstructionAllocated,
    cpuBiasAllocated, cpuWeightsAllocated, npuInstructionAllocated,
    npuBiasAllocated, npuWeightsAllocated, result)

proc blaiSdkOutputBufferPlanInto*(
    layers: openArray[BlaiCpuInstLayer64],
    layerCount: uint32,
    patchSize: uint32,
    bufferBytes: uint32,
    outResult: var BlaiSdkOutputBufferPlan) =
  ## Recover SDK `blai_getOutputBuffer` without pointer arithmetic.
  outResult = default(BlaiSdkOutputBufferPlan)
  outResult.layerCount = layerCount
  outResult.patchSize = patchSize
  outResult.bufferBytes = bufferBytes
  outResult.sizeReturned = patchSize
  outResult.layerCountValid =
    layerCount != 0'u32 and layerCount <= blaiOpenArrayLenU32(layers)
  if not outResult.layerCountValid:
    outResult.firstBlock = blaiSdkOutputBufferLayerCount
    return
  outResult.lastLayerIndex = (layerCount - 1'u32).int32
  outResult.patchSizeValid = patchSize != 0'u32
  if not outResult.patchSizeValid:
    outResult.firstBlock = blaiSdkOutputBufferPatchSize
    return
  let lastLayer = layers[outResult.lastLayerIndex.int]
  outResult.slotOffset = blaiPatchSlotOffset(lastLayer.outLayerMem, patchSize)
  outResult.slotValid = outResult.slotOffset.valid
  if not outResult.slotValid:
    outResult.firstBlock = blaiSdkOutputBufferSlot
    return
  outResult.outputSlot = outResult.slotOffset.slot
  outResult.outputOffset = outResult.slotOffset.offset
  outResult.outputBytes = patchSize
  blaiDataBufferRangeFitsInto(
    true, outResult.outputOffset, outResult.outputBytes, bufferBytes,
    outResult.rangeFit)
  outResult.rangeFits = outResult.rangeFit.fits
  if not outResult.rangeFits:
    outResult.firstBlock = blaiSdkOutputBufferRange
    return
  outResult.firstBlock = blaiSdkOutputBufferNoBlock
  outResult.valid = true

proc blaiSdkOutputBufferPlan*(
