proc blaiTensorBufferFitsInto*(plan: BlaiTensorTransferPlan,
                               patchSize: uint32,
                               bufferBytes: uint32,
                               outResult: var BlaiTensorBufferFitResult) =
  ## Check DATA-buffer slot arithmetic and caller-owned capacity.
  outResult = default(BlaiTensorBufferFitResult)
  outResult.active = plan.active
  outResult.offsetFits = true
  outResult.bytes = plan.bytes
  if not plan.active:
    outResult.bufferFits = true
    outResult.fits = true
    return
  let slotOffset = blaiPatchSlotOffset(plan.slot, patchSize)
  if not slotOffset.valid:
    outResult.offsetFits = false
    outResult.offset = high(uint32)
    outResult.requiredBytes = high(uint32)
    return
  var rangeFit: BlaiDataBufferRangeFit
  blaiDataBufferRangeFitsInto(
    plan.active, slotOffset.offset, plan.bytes, bufferBytes, rangeFit)
  outResult.offsetFits = rangeFit.offsetFits
  outResult.bufferFits = rangeFit.bufferFits
  outResult.offset = rangeFit.offset
  outResult.requiredBytes = rangeFit.requiredBytes
  outResult.fits = rangeFit.fits

proc blaiTensorBufferFits*(plan: BlaiTensorTransferPlan,
                           patchSize: uint32,
                           bufferBytes: uint32): bool =
  ## Boolean wrapper for DATA-buffer tensor bounds checks.
  var fit: BlaiTensorBufferFitResult
  blaiTensorBufferFitsInto(plan, patchSize, bufferBytes, fit)
  fit.fits

proc blaiBufferLenU32*(bufferLen: int): uint32 =
  ## Convert a Nim openArray length to the recovered uint32 capacity domain.
  if bufferLen <= 0:
    0'u32
  elif bufferLen.uint64 > high(uint32).uint64:
    high(uint32)
  else:
    bufferLen.uint32

proc blaiU64ExactU32Count*(count: uint64, outCount: var uint32): bool =
  ## Project a recovered uint64 element count into uint32 only when exact.
  if count > high(uint32).uint64:
    return false
  outCount = count.uint32
  true

proc blaiU64ExactI32Count*(count: uint64, outCount: var uint32): bool =
  ## Project a recovered uint64 count that will be consumed through int32 math.
  if count > high(int32).uint64:
    return false
  outCount = count.uint32
  true

proc blaiU64SaturatedU32Count*(count: uint64): uint32 =
  ## Project a recovered diagnostic count into a saturating uint32 SDK field.
  if count > high(uint32).uint64:
    high(uint32)
  else:
    count.uint32

proc blaiU64MaxExactU32Count*(count: uint64, outCount: var uint32): bool =
  ## Keep the largest recovered uint64 element count that fits the uint32 ABI.
  var projected: uint32
  if not blaiU64ExactU32Count(count, projected):
    return false
  outCount = max(outCount, projected)
  true

proc blaiOpenArrayLenU32*[T](items: openArray[T]): uint32 =
  ## Convert a Nim openArray element count to the recovered uint32 domain.
  blaiBufferLenU32(items.len)

proc blaiBoundedU32Count*(count: uint32, capacity: int): int =
  ## Bound a recovered uint32 count to a Nim container capacity before indexing.
  if capacity <= 0:
    return 0
  let bounded = min(count, blaiBufferLenU32(capacity))
  discard blaiU32ExactIntCount(bounded, result)

proc blaiU32ArrayIndexCursor*(index: uint32,
                              capacity: int): BlaiU32ArrayIndexCursor =
  ## Validate a recovered uint32 index before using it on a Nim container.
  if capacity <= 0:
    return
  if index >= blaiBufferLenU32(capacity):
    return
  if not blaiU32ExactIntCount(index, result.index):
    return
  result.valid = true

proc blaiU32CountCursor*(count: uint32,
                         capacity: int): BlaiU32CountCursor =
  ## Validate a recovered uint32 count before using it as a Nim loop bound.
  if capacity < 0:
    return
  if count > blaiBufferLenU32(capacity):
    return
  if not blaiU32ExactIntCount(count, result.count):
    return
  result.valid = true

proc blaiZeroBasedOpenArrayStop*(count: uint32,
                                 capacity: int,
                                 outStop: var int): bool =
  ## Resolve a non-empty recovered count to a zero-based openArray stop index.
  let cursor = blaiU32CountCursor(count, capacity)
  if not cursor.valid or cursor.count <= 0:
    return false
  outStop = cursor.count - 1
  true

proc blaiStartedOpenArrayStop*(startIndex: int,
                               count: uint32,
                               capacity: int,
                               outStop: var int): bool =
  ## Resolve a non-empty recovered span to a started openArray stop index.
  if startIndex < 0 or startIndex > capacity:
    return false
  let cursor = blaiU32CountCursor(count, capacity - startIndex)
  if not cursor.valid or cursor.count <= 0:
    return false
  if startIndex > high(int) - cursor.count + 1:
    return false
  outStop = startIndex + cursor.count - 1
  true

proc blaiI32ArrayIndexCursor*(index: int32,
                              capacity: int): BlaiU32ArrayIndexCursor =
  ## Validate a recovered signed cursor index, preserving negative sentinels.
  if index < 0:
    return
  blaiU32ArrayIndexCursor(index.uint32, capacity)

proc blaiRouteDescriptorStepCursor*(index: uint32): BlaiU32ArrayIndexCursor =
  ## Resolve one recovered route descriptor-loop step to the fixed step table.
  blaiU32ArrayIndexCursor(index, BlaiMaxInputNum - 1)

proc blaiSdkInt32Field*(value: uint32): BlaiSdkInt32Field =
  ## Project a decoded unsigned SDK scalar into signed int32 field storage.
  ##
  ## This is for semantic non-negative fields recovered as uint32. Raw
  ## bit-pattern fields must use the dedicated `blaiInt32FromBits` helpers.
  if value > high(int32).uint32:
    return
  result.value = value.int32
  result.valid = true

proc blaiRouteDescriptorChannelAbi*(channels: uint32): BlaiRouteDescriptorChannelAbi =
