proc blaiRouteDescriptorLayerApplyPlan*(step: BlaiRouteDescriptorStep):
    BlaiRouteDescriptorLayerApplyPlan =
  ## Recover the route descriptor's per-step `layer.c` projection.
  let field = blaiRouteDescriptorChannelAbi(step.descriptorC1)
  if not field.valid:
    return
  result.stateAfter = blaiRouteDescriptorLayerState(field.value)
  result.valid = true

proc blaiRouteDescriptorLayerState*(plan: BlaiRouteDescriptorLayerApplyPlan):
