proc blaiToolchainPsramSplitCountAbi*(
    rawSplitCount: int32): BlaiToolchainPsramSplitCountAbi =
  ## Resolve a recovered raw split count after the converter's minimum clamp.
  let selected =
    if rawSplitCount < BlaiToolchainPsramSplitMinCount:
      BlaiToolchainPsramSplitMinCount
    else:
      rawSplitCount
  if selected < 0:
    return
  result.value = selected.uint32
  result.valid = true

proc blaiToolchainPsramSplitDenominatorAbi*(
    splitDenominator: uint32): BlaiToolchainPsramSplitDenominatorAbi =
  ## Resolve a recovered split divisor before signed division.
  if splitDenominator == 0'u32 or splitDenominator > high(int32).uint32:
