  result.valid = true

proc blaiToolchainPsramInitialTfliteSentinelLayerAbi*(
    sentinel: int32): BlaiToolchainPsramInitialTfliteSentinelLayerAbi =
  ## Decode the recovered negative sentinel into an SDK int32 layer index.
  if sentinel >= 0 or sentinel == low(int32):
    return
  let selectedLayer = -(sentinel.int64) - 1'i64
  if selectedLayer < 0'i64 or selectedLayer > high(int32).int64:
    return
  result.value = selectedLayer.int32
  result.valid = true

