proc blaiLayerCursorIndexAbi*(index: int): BlaiLayerCursorIndexAbi =
  ## Resolve a Nim layer-table index before recovered uint32 cursor use.
  if index < 0:
    return
  when sizeof(int) > sizeof(uint32):
    if index > high(uint32).int:
      return
  result.value = index.uint32
  result.valid = true

