  readiness.fits

proc blaiReferenceTfliteFullyConnectedReadinessInto*(
    plan: BlaiReferenceTfliteFullyConnected2d,
    inputLen, weightsLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceTfliteFullyConnectedResult) =
  outResult = BlaiReferenceTfliteFullyConnectedResult()
  outResult.outputW = 1'u32
  outResult.outputH = plan.batchCount
  outResult.outputC = plan.outputC
  outResult.validInputShape =
    plan.batchCount != 0'u32 and plan.inputC != 0'u32 and
      plan.outputC != 0'u32
  let inputNeed =
    blaiReferenceMatmulActivationElements(plan.batchCount, plan.inputC)
  let weightNeed =
    blaiReferenceMatmulWeightElements(plan.inputC, plan.outputC)
  let biasNeed = if plan.useBias: plan.outputC.uint64 else: 0'u64
  let outputNeed =
    blaiReferenceMatmulActivationElements(plan.batchCount, plan.outputC)
  discard blaiU64ExactU32Count(inputNeed, outResult.inputElements)
  discard blaiU64ExactU32Count(weightNeed, outResult.weightElements)
  discard blaiU64ExactU32Count(biasNeed, outResult.biasElements)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.weightsFit = weightNeed <= weightsLen.uint64
  outResult.biasFits = biasNeed <= biasLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteFullyConnectedInputShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteFullyConnectedInputBuffer
  elif not outResult.weightsFit:
    outResult.firstBlock = blaiTfliteFullyConnectedWeightBuffer
  elif not outResult.biasFits:
    outResult.firstBlock = blaiTfliteFullyConnectedBiasBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteFullyConnectedOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteFullyConnectedNoBlock
    outResult.fits = true

proc blaiReferenceTfliteFullyConnected2d*(
    plan: BlaiReferenceTfliteFullyConnected2d,
    input: openArray[uint8],
    weights: openArray[uint8],
    biases: openArray[int32],
    output: var openArray[uint8]): BlaiReferenceTfliteFullyConnectedResult =
  ## CPU fixture for TFLite uint8 FullyConnected/MATMUL.
  blaiReferenceTfliteFullyConnectedReadinessInto(
    plan, input.len, weights.len, biases.len, output.len, result)
  if not result.fits:
    return

  for batch in 0'u32 ..< plan.batchCount:
    for outC in 0'u32 ..< plan.outputC:
      var acc =
        if plan.useBias:
          biases[outC.int]
        else:
          0'i32
      for inC in 0'u32 ..< plan.inputC:
        let inputIndex = blaiRowMajorIndex(batch, inC, plan.inputC)
        let weightIndex = blaiRowMajorIndex(outC, inC, plan.inputC)
        if not inputIndex.valid or not weightIndex.valid:
          return
        let inputValue = input[inputIndex.index.int].int32 + plan.inputOffset
        let weightValue =
          weights[weightIndex.index.int].int32 + plan.filterOffset
        acc = blaiClampI32(acc.int64 + inputValue.int64 * weightValue.int64)
      acc = blaiNmsisRequantize(acc, plan.outputMultiplier, plan.outputShift)
      acc = blaiClampI32(acc.int64 + plan.outputOffset.int64)
      acc = min(max(acc, plan.activationMin), plan.activationMax)
      let outputIndex = blaiRowMajorIndex(batch, outC, plan.outputC)
      if not outputIndex.valid:
        return
      output[outputIndex.index.int] = acc.uint8

proc blaiReferenceTfliteScalarConvSupported*(
    plan: BlaiReferenceTfliteScalarConv2d): bool =
  plan.kernelSize != 0'u32 and (plan.kernelSize mod 2'u32) == 1'u32

proc blaiTfliteScalarConvStart(plan: BlaiReferenceTfliteScalarConv2d): uint32 =
  if plan.stride == 2'u32: 1'u32 else: 0'u32

proc blaiTfliteScalarConvWindowCount(input, start, stride: uint32): uint32 =
  if stride == 0'u32 or input <= start:
    0'u32
  else:
    ((input - 1'u32 - start) div stride) + 1'u32

proc blaiReferenceTfliteScalarConvReadinessInto*(
    plan: BlaiReferenceTfliteScalarConv2d,
    inputLen, kernelLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceTfliteScalarConvResult)

proc blaiReferenceTfliteScalarConvFits*(
    plan: BlaiReferenceTfliteScalarConv2d,
    inputLen, kernelLen, biasLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteScalarConvResult
  blaiReferenceTfliteScalarConvReadinessInto(
    plan, inputLen, kernelLen, biasLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteScalarConvReadinessInto*(
    plan: BlaiReferenceTfliteScalarConv2d,
    inputLen, kernelLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceTfliteScalarConvResult) =
  outResult = BlaiReferenceTfliteScalarConvResult()
  outResult.supported = blaiReferenceTfliteScalarConvSupported(plan)
  let start = blaiTfliteScalarConvStart(plan)
  outResult.windowW =
    blaiTfliteScalarConvWindowCount(plan.inputW, start, plan.stride)
  outResult.windowH =
    blaiTfliteScalarConvWindowCount(plan.inputH, start, plan.stride)
  outResult.outputW =
    if plan.outputW == 0'u32: outResult.windowW else: plan.outputW
  outResult.outputH =
    if plan.outputH == 0'u32: outResult.windowH else: plan.outputH
  outResult.outputC = plan.outputC
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and
      plan.inputC != 0'u32 and plan.outputC != 0'u32 and
      plan.stride != 0'u32 and plan.groups != 0'u32
  outResult.validGroupShape =
    outResult.validInputShape and
      plan.inputC mod plan.groups == 0'u32 and
      plan.outputC mod plan.groups == 0'u32
  outResult.validOutputShape =
    outResult.windowW != 0'u32 and outResult.windowH != 0'u32 and
      outResult.outputW >= outResult.windowW and
      outResult.outputH >= outResult.windowH

  let inputPerGroup =
    if outResult.validGroupShape: plan.inputC div plan.groups else: 0'u32
  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  let kernelNeed =
    blaiReferenceGroupedKernelElementCount(
      plan.outputC, inputPerGroup, plan.kernelSize)
  let biasNeed = if plan.useBias: plan.outputC.uint64 else: 0'u64
  let outputNeed =
    blaiReferenceHwcElementCount(
      outResult.outputW, outResult.outputH, plan.outputC)
  discard blaiU64ExactU32Count(inputNeed, outResult.inputElements)
  discard blaiU64ExactU32Count(kernelNeed, outResult.kernelElements)
  discard blaiU64ExactU32Count(biasNeed, outResult.biasElements)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)

  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.kernelFits = kernelNeed <= kernelLen.uint64
  outResult.biasFits = biasNeed <= biasLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.supported:
    outResult.firstBlock = blaiTfliteScalarConvUnsupportedKernel
  elif not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteScalarConvInputShape
  elif not outResult.validGroupShape:
    outResult.firstBlock = blaiTfliteScalarConvGroupShape
  elif not outResult.validOutputShape:
    outResult.firstBlock = blaiTfliteScalarConvOutputShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteScalarConvInputBuffer
  elif not outResult.kernelFits:
    outResult.firstBlock = blaiTfliteScalarConvKernelBuffer
  elif not outResult.biasFits:
    outResult.firstBlock = blaiTfliteScalarConvBiasBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteScalarConvOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteScalarConvNoBlock
    outResult.fits = true

proc blaiReferenceTfliteScalarConvSample(
    plan: BlaiReferenceTfliteScalarConv2d,
    input: openArray[uint8],
    x, y: int32,
    channel: uint32): int32 =
  if x < 0 or y < 0 or x >= plan.inputW.int32 or y >= plan.inputH.int32:
    0'i32
  else:
    let inputHwc =
      blaiHwcIndex(y.uint32, x.uint32, plan.inputW, channel, plan.inputC)
    if inputHwc.valid:
      input[inputHwc.index.int].int32 - plan.inputOffset
    else:
      0'i32

proc blaiReferenceTfliteScalarConv2d*(
    plan: BlaiReferenceTfliteScalarConv2d,
    input: openArray[uint8],
    kernel: openArray[uint8],
    biases: openArray[int32],
    output: var openArray[uint8]): BlaiReferenceTfliteScalarConvResult =
  ## CPU fixture for odd-kernel SDK `forward_CONVOLUTIONAL_tflite`.
  blaiReferenceTfliteScalarConvReadinessInto(
    plan, input.len, kernel.len, biases.len, output.len, result)
  if not result.fits:
    return

  let start = blaiTfliteScalarConvStart(plan)
  let inputPerGroup = plan.inputC div plan.groups
  let outputPerGroup = plan.outputC div plan.groups
  let step = plan.kernelSize.int32 div 2'i32
  let dilationGap =
    if plan.dilation == 0'u32: 0'i32 else: plan.dilation.int32 - 1'i32
  for outC in 0'u32 ..< plan.outputC:
    let groupIndex = outC div outputPerGroup
    let cStart = groupIndex * inputPerGroup
    let cEnd = cStart + inputPerGroup
    for outY in 0'u32 ..< result.windowH:
      let centerY = (start + outY * plan.stride).int32
      for outX in 0'u32 ..< result.windowW:
        let centerX = (start + outX * plan.stride).int32
        var acc = 0'i32
        for inC in cStart ..< cEnd:
          var channelAcc = 0'i32
          var wt = 0'u32
          for ky in -step .. step:
            let sampleY =
              if ky == 0'i32: centerY
              elif ky < 0'i32: centerY - ((-ky) + dilationGap)
              else: centerY + (ky + dilationGap)
            for kx in -step .. step:
              let sampleX =
                if kx == 0'i32: centerX
                elif kx < 0'i32: centerX - ((-kx) + dilationGap)
                else: centerX + (kx + dilationGap)
              let sample = blaiReferenceTfliteScalarConvSample(
                plan, input, sampleX, sampleY, inC)
              let kernelColumns =
                inputPerGroup * plan.kernelSize * plan.kernelSize
              let kernelColumn =
                (inC - cStart) * plan.kernelSize * plan.kernelSize + wt
              let kernelIndex =
                blaiRowMajorIndex(outC, kernelColumn, kernelColumns)
              if not kernelIndex.valid:
                return
              let weight =
                kernel[kernelIndex.index.int].int32 - plan.filterOffset
              channelAcc = blaiClampI32(
                channelAcc.int64 + sample.int64 * weight.int64)
              inc wt
          acc = blaiClampI32(acc.int64 + channelAcc.int64)
        if plan.useBias:
          acc = blaiClampI32(acc.int64 + biases[outC.int].int64)
        acc = blaiTfliteMultiplyByQuantizedMultiplier(
          acc, plan.outputMultiplier, plan.outputShift)
        acc = blaiClampI32(acc.int64 + plan.outputOffset.int64)
        acc = min(max(acc, plan.activationMin), plan.activationMax)
        let outputHwc =
          blaiHwcIndex(outY, outX, result.outputW, outC, result.outputC)
        if not outputHwc.valid:
          return
        output[outputHwc.index.int] = (acc and 0xFF'i32).uint8

proc blaiReferenceTfliteScalarConvMaxSupported*(
    plan: BlaiReferenceTfliteScalarConvMax2d): bool =
  plan.kernelSize != 0'u32 and (plan.kernelSize mod 2'u32) == 1'u32

proc blaiTfliteScalarConvMaxStart(plan: BlaiReferenceTfliteScalarConvMax2d): uint32 =
  if plan.stride == 2'u32: 1'u32 else: 0'u32

proc blaiTfliteFoldedOutputDim(windowCount: uint32): uint32 =
  (windowCount + 1'u32) div 2'u32

proc blaiReferenceTfliteScalarConvMaxReadinessInto*(
    plan: BlaiReferenceTfliteScalarConvMax2d,
    inputLen, kernelLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceTfliteScalarConvMaxResult)

proc blaiReferenceTfliteScalarConvMaxFits*(
    plan: BlaiReferenceTfliteScalarConvMax2d,
    inputLen, kernelLen, biasLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteScalarConvMaxResult
  blaiReferenceTfliteScalarConvMaxReadinessInto(
    plan, inputLen, kernelLen, biasLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteScalarConvMaxReadinessInto*(
    plan: BlaiReferenceTfliteScalarConvMax2d,
    inputLen, kernelLen, biasLen, outputLen: int,
    outResult: var BlaiReferenceTfliteScalarConvMaxResult) =
  outResult = BlaiReferenceTfliteScalarConvMaxResult()
  outResult.supported = blaiReferenceTfliteScalarConvMaxSupported(plan)
  let start = blaiTfliteScalarConvMaxStart(plan)
  outResult.windowW =
    blaiTfliteScalarConvWindowCount(plan.inputW, start, plan.stride)
  outResult.windowH =
    blaiTfliteScalarConvWindowCount(plan.inputH, start, plan.stride)
  let foldedW = blaiTfliteFoldedOutputDim(outResult.windowW)
  let foldedH = blaiTfliteFoldedOutputDim(outResult.windowH)
  outResult.outputW = if plan.outputW == 0'u32: foldedW else: plan.outputW
  outResult.outputH = if plan.outputH == 0'u32: foldedH else: plan.outputH
  outResult.outputC = plan.outputC
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and
      plan.inputC != 0'u32 and plan.outputC != 0'u32 and
      plan.stride != 0'u32 and plan.groups != 0'u32
  outResult.validGroupShape =
    outResult.validInputShape and
      plan.inputC mod plan.groups == 0'u32 and
      plan.outputC mod plan.groups == 0'u32
  outResult.validOutputShape =
    outResult.windowW != 0'u32 and outResult.windowH != 0'u32 and
      outResult.outputW >= foldedW and outResult.outputH >= foldedH

  let inputPerGroup =
    if outResult.validGroupShape: plan.inputC div plan.groups else: 0'u32
  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  let kernelNeed =
    blaiReferenceGroupedKernelElementCount(
      plan.outputC, inputPerGroup, plan.kernelSize)
  let biasNeed = if plan.useBias: plan.outputC.uint64 else: 0'u64
  let outputNeed =
    blaiReferenceHwcElementCount(
      outResult.outputW, outResult.outputH, plan.outputC)
  discard blaiU64ExactU32Count(inputNeed, outResult.inputElements)
  discard blaiU64ExactU32Count(kernelNeed, outResult.kernelElements)
  discard blaiU64ExactU32Count(biasNeed, outResult.biasElements)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)

  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.kernelFits = kernelNeed <= kernelLen.uint64
  outResult.biasFits = biasNeed <= biasLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.supported:
    outResult.firstBlock = blaiTfliteScalarConvMaxUnsupportedKernel
  elif not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteScalarConvMaxInputShape
  elif not outResult.validGroupShape:
    outResult.firstBlock = blaiTfliteScalarConvMaxGroupShape
  elif not outResult.validOutputShape:
    outResult.firstBlock = blaiTfliteScalarConvMaxOutputShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteScalarConvMaxInputBuffer
  elif not outResult.kernelFits:
    outResult.firstBlock = blaiTfliteScalarConvMaxKernelBuffer
  elif not outResult.biasFits:
    outResult.firstBlock = blaiTfliteScalarConvMaxBiasBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteScalarConvMaxOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteScalarConvMaxNoBlock
    outResult.fits = true

proc blaiReferenceTfliteScalarConvMaxSample(
    plan: BlaiReferenceTfliteScalarConvMax2d,
    input: openArray[uint8],
    x, y: int32,
    channel: uint32): int32 =
  if x < 0 or y < 0 or x >= plan.inputW.int32 or y >= plan.inputH.int32:
    0'i32
  else:
    let inputHwc =
      blaiHwcIndex(y.uint32, x.uint32, plan.inputW, channel, plan.inputC)
    if inputHwc.valid:
      input[inputHwc.index.int].int32 - plan.inputOffset
    else:
      0'i32

proc blaiReferenceTfliteScalarConvMaxValue(
    plan: BlaiReferenceTfliteScalarConvMax2d,
    input: openArray[uint8],
    kernel: openArray[uint8],
    biases: openArray[int32],
    outC, outY, outX, start: uint32): uint8 =
  let inputPerGroup = plan.inputC div plan.groups
  let outputPerGroup = plan.outputC div plan.groups
  let groupIndex = outC div outputPerGroup
  let cStart = groupIndex * inputPerGroup
  let cEnd = cStart + inputPerGroup
  let step = plan.kernelSize.int32 div 2'i32
  let dilationGap =
    if plan.dilation == 0'u32: 0'i32 else: plan.dilation.int32 - 1'i32
  let centerY = (start + outY * plan.stride).int32
  let centerX = (start + outX * plan.stride).int32
  var acc = 0'i32
  for inC in cStart ..< cEnd:
    var channelAcc = 0'i32
    var wt = 0'u32
    for ky in -step .. step:
      let sampleY =
        if ky == 0'i32: centerY
        elif ky < 0'i32: centerY - ((-ky) + dilationGap)
        else: centerY + (ky + dilationGap)
      for kx in -step .. step:
        let sampleX =
          if kx == 0'i32: centerX
          elif kx < 0'i32: centerX - ((-kx) + dilationGap)
          else: centerX + (kx + dilationGap)
        let sample = blaiReferenceTfliteScalarConvMaxSample(
          plan, input, sampleX, sampleY, inC)
        let kernelColumns = inputPerGroup * plan.kernelSize * plan.kernelSize
        let kernelColumn =
          (inC - cStart) * plan.kernelSize * plan.kernelSize + wt
        let kernelIndex = blaiRowMajorIndex(outC, kernelColumn, kernelColumns)
        if not kernelIndex.valid:
          return 0'u8
        let weight = kernel[kernelIndex.index.int].int32 - plan.filterOffset
        channelAcc = blaiClampI32(channelAcc.int64 + sample.int64 * weight.int64)
        inc wt
    acc = blaiClampI32(acc.int64 + channelAcc.int64)
  if plan.useBias:
    acc = blaiClampI32(acc.int64 + biases[outC.int].int64)
  acc = blaiTfliteMultiplyByQuantizedMultiplier(
    acc, plan.outputMultiplier, plan.outputShift)
  acc = blaiClampI32(acc.int64 + plan.outputOffset.int64)
  acc = min(max(acc, plan.activationMin), plan.activationMax)
  (acc and 0xFF'i32).uint8

proc blaiReferenceTfliteScalarConvMax2d*(
    plan: BlaiReferenceTfliteScalarConvMax2d,
    input: openArray[uint8],
    kernel: openArray[uint8],
    biases: openArray[int32],
    output: var openArray[uint8]): BlaiReferenceTfliteScalarConvMaxResult =
  ## CPU fixture for odd-kernel SDK `forward_CONV_MAX_tflite`.
  blaiReferenceTfliteScalarConvMaxReadinessInto(
    plan, input.len, kernel.len, biases.len, output.len, result)
  if not result.fits:
    return

  let start = blaiTfliteScalarConvMaxStart(plan)
  for outC in 0'u32 ..< plan.outputC:
    for windowY in 0'u32 ..< result.windowH:
      for windowX in 0'u32 ..< result.windowW:
        let passData = blaiReferenceTfliteScalarConvMaxValue(
          plan, input, kernel, biases, outC, windowY, windowX, start)
        let outputHwc =
          blaiHwcIndex(windowY div 2'u32, windowX div 2'u32,
            result.outputW, outC, plan.outputC)
        if not outputHwc.valid:
          return
        let outputIndex = outputHwc.index
        if windowY mod 2'u32 == 0'u32 and windowX mod 2'u32 == 0'u32:
          output[outputIndex.int] = passData
        elif output[outputIndex.int] < passData:
          output[outputIndex.int] = passData

proc blaiReferenceMaxPoolReadinessInto*(
    plan: BlaiReferenceMaxPool2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceMaxPoolResult)

proc blaiReferenceMaxPoolFits*(plan: BlaiReferenceMaxPool2d,
                               inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceMaxPoolResult
  blaiReferenceMaxPoolReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceMaxPoolReadinessInto*(
    plan: BlaiReferenceMaxPool2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceMaxPoolResult) =
  outResult = BlaiReferenceMaxPoolResult()
  outResult.outputW = blaiReferenceDepthwiseOutputDim(
    plan.inputW, plan.paddingX, plan.kernelW, plan.strideX)
  outResult.outputH = blaiReferenceDepthwiseOutputDim(
    plan.inputH, plan.paddingY, plan.kernelH, plan.strideY)
  outResult.outputC = plan.inputC
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and
      plan.inputC != 0'u32 and plan.kernelW != 0'u32 and
      plan.kernelH != 0'u32 and plan.strideX != 0'u32 and
      plan.strideY != 0'u32
  outResult.validOutputShape =
    outResult.outputW != 0'u32 and outResult.outputH != 0'u32
  outResult.windowsCovered = outResult.validOutputShape
  if outResult.windowsCovered:
    for outY in 0'u32 ..< outResult.outputH:
      let baseY = outY.int32 * plan.strideY.int32 - plan.paddingY.int32
      let kernelYStart = max(0'i32, -baseY).uint32
      let kernelYEnd = min(plan.kernelH.int32, plan.inputH.int32 - baseY).uint32
      for outX in 0'u32 ..< outResult.outputW:
        let baseX = outX.int32 * plan.strideX.int32 - plan.paddingX.int32
        let kernelXStart = max(0'i32, -baseX).uint32
        let kernelXEnd = min(plan.kernelW.int32, plan.inputW.int32 - baseX).uint32
        if kernelYStart >= kernelYEnd or kernelXStart >= kernelXEnd:
          outResult.windowsCovered = false

  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  let outputNeed =
    blaiReferenceHwcElementCount(
      outResult.outputW, outResult.outputH, plan.inputC)
  discard blaiU64ExactU32Count(inputNeed, outResult.inputElements)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiMaxPoolInputShape
  elif not outResult.validOutputShape:
    outResult.firstBlock = blaiMaxPoolOutputShape
  elif not outResult.windowsCovered:
    outResult.firstBlock = blaiMaxPoolWindowCoverage
  elif not outResult.inputFits:
    outResult.firstBlock = blaiMaxPoolInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiMaxPoolOutputBuffer
  else:
    outResult.firstBlock = blaiMaxPoolNoBlock
    outResult.fits = true

proc blaiReferenceMaxPool2d*(plan: BlaiReferenceMaxPool2d,
                             input: openArray[uint8],
                             output: var openArray[uint8]): BlaiReferenceMaxPoolResult =
  ## CPU fixture for SDK `riscv_max_pool_u8` over HWC uint8 tensors.
  blaiReferenceMaxPoolReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  for outY in 0'u32 ..< result.outputH:
    let baseY = outY.int32 * plan.strideY.int32 - plan.paddingY.int32
    let kernelYStart = max(0'i32, -baseY).uint32
    let kernelYEnd = min(plan.kernelH.int32, plan.inputH.int32 - baseY).uint32
    for outX in 0'u32 ..< result.outputW:
      let baseX = outX.int32 * plan.strideX.int32 - plan.paddingX.int32
      let kernelXStart = max(0'i32, -baseX).uint32
      let kernelXEnd = min(plan.kernelW.int32, plan.inputW.int32 - baseX).uint32
      for channel in 0'u32 ..< plan.inputC:
        var maxValue = 0'u8
        var initialized = false
        for ky in kernelYStart ..< kernelYEnd:
          let inputY = baseY + ky.int32
          for kx in kernelXStart ..< kernelXEnd:
            let inputX = baseX + kx.int32
            let inputHwc =
              blaiHwcIndex(inputY.uint32, inputX.uint32, plan.inputW, channel,
                plan.inputC)
            if not inputHwc.valid:
              return
            let value = input[inputHwc.index.int]
            if not initialized or value > maxValue:
              maxValue = value
              initialized = true
        var clamped = maxValue.int32
        clamped = min(max(clamped, plan.activationMin), plan.activationMax)
        let outputHwc =
          blaiHwcIndex(outY, outX, result.outputW, channel, result.outputC)
        if not outputHwc.valid:
          return
        output[outputHwc.index.int] = clamped.uint8

proc blaiReferenceFixedMaxPoolSupported*(
    plan: BlaiReferenceFixedMaxPool2d): bool =
  plan.kernelSize != 0'u32 and (plan.kernelSize mod 2'u32) == 1'u32

proc blaiReferenceFixedMaxPoolReadinessInto*(
    plan: BlaiReferenceFixedMaxPool2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceFixedMaxPoolResult) =
  outResult = BlaiReferenceFixedMaxPoolResult()
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and plan.inputC != 0'u32
  outResult.validStride = plan.stride != 0'u32
  outResult.validDilation = plan.dilation != 0'u32
  outResult.supported = blaiReferenceFixedMaxPoolSupported(plan)
  outResult.outputW = blaiReferenceConvOutputDim(plan.inputW, plan.stride)
  outResult.outputH = blaiReferenceConvOutputDim(plan.inputH, plan.stride)
  outResult.outputC = plan.inputC
  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  let outputNeed =
    blaiReferenceHwcElementCount(
      outResult.outputW, outResult.outputH, plan.inputC)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiFixedMaxPoolInputShape
  elif not outResult.validStride:
    outResult.firstBlock = blaiFixedMaxPoolStride
  elif not outResult.validDilation:
    outResult.firstBlock = blaiFixedMaxPoolDilation
  elif not outResult.supported:
    outResult.firstBlock = blaiFixedMaxPoolKernel
  elif not outResult.inputFits:
    outResult.firstBlock = blaiFixedMaxPoolInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiFixedMaxPoolOutputBuffer
  else:
    outResult.firstBlock = blaiFixedMaxPoolNoBlock
    outResult.fits = true

proc blaiReferenceFixedMaxPoolFits*(
    plan: BlaiReferenceFixedMaxPool2d,
    inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceFixedMaxPoolResult
  blaiReferenceFixedMaxPoolReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceFixedMaxPoolSample(
    plan: BlaiReferenceFixedMaxPool2d,
    input: openArray[int8],
    x, y: int32,
    channel: uint32): int8 =
  if x < 0 or y < 0 or x >= plan.inputW.int32 or y >= plan.inputH.int32:
    -128'i8
  else:
    let inputHwc =
      blaiHwcIndex(y.uint32, x.uint32, plan.inputW, channel, plan.inputC)
    if inputHwc.valid:
      input[inputHwc.index.int]
    else:
      -128'i8

proc blaiReferenceFixedMaxPool2d*(
    plan: BlaiReferenceFixedMaxPool2d,
    input: openArray[int8],
    output: var openArray[int8]): BlaiReferenceFixedMaxPoolResult =
  ## CPU fixture for the odd-kernel SDK `forward_MAXPOOL` path over HWC int8.
  blaiReferenceFixedMaxPoolReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  let step = plan.kernelSize.int32 div 2'i32
  let dilationGap = plan.dilation.int32 - 1'i32
  for outY in 0'u32 ..< result.outputH:
    let centerY = (outY * plan.stride).int32
    for outX in 0'u32 ..< result.outputW:
      let centerX = (outX * plan.stride).int32
      for channel in 0'u32 ..< plan.inputC:
        var maxValue = -128'i8
        var initialized = false
        for ky in -step .. step:
          let sampleY =
            if ky == 0'i32: centerY
            elif ky < 0'i32: centerY - ((-ky) + dilationGap)
            else: centerY + (ky + dilationGap)
          for kx in -step .. step:
            let sampleX =
              if kx == 0'i32: centerX
              elif kx < 0'i32: centerX - ((-kx) + dilationGap)
              else: centerX + (kx + dilationGap)
            let sample = blaiReferenceFixedMaxPoolSample(
              plan, input, sampleX, sampleY, channel)
            if not initialized or sample > maxValue:
              maxValue = sample
              initialized = true
        let outputHwc =
          blaiHwcIndex(outY, outX, result.outputW, channel, result.outputC)
        if not outputHwc.valid:
          return
        output[outputHwc.index.int] = maxValue

proc blaiReferenceTfliteScalarMaxPoolSupported*(
    plan: BlaiReferenceTfliteScalarMaxPool2d): bool =
  plan.kernelSize != 0'u32 and (plan.kernelSize mod 2'u32) == 1'u32

proc blaiTfliteScalarMaxPoolStart(plan: BlaiReferenceTfliteScalarMaxPool2d): uint32 =
  if plan.stride == 2'u32: 1'u32 else: 0'u32

proc blaiTfliteScalarMaxPoolWindowCount(input, start, stride: uint32): uint32 =
  if stride == 0'u32 or input <= start:
    0'u32
  else:
    ((input - 1'u32 - start) div stride) + 1'u32

proc blaiReferenceTfliteScalarMaxPoolReadinessInto*(
    plan: BlaiReferenceTfliteScalarMaxPool2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteScalarMaxPoolResult) =
  outResult = BlaiReferenceTfliteScalarMaxPoolResult()
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and plan.inputC != 0'u32
  outResult.validStride = plan.stride != 0'u32
  outResult.supported = blaiReferenceTfliteScalarMaxPoolSupported(plan)
  let start = blaiTfliteScalarMaxPoolStart(plan)
  outResult.windowW =
    blaiTfliteScalarMaxPoolWindowCount(plan.inputW, start, plan.stride)
  outResult.windowH =
    blaiTfliteScalarMaxPoolWindowCount(plan.inputH, start, plan.stride)
  outResult.outputW =
    if plan.outputW == 0'u32: outResult.windowW else: plan.outputW
  outResult.outputH =
    if plan.outputH == 0'u32: outResult.windowH else: plan.outputH
  outResult.outputC = plan.inputC
  outResult.outputShapeValid =
    outResult.windowW != 0'u32 and outResult.windowH != 0'u32 and
    outResult.outputW >= outResult.windowW and
    outResult.outputH >= outResult.windowH
  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  let outputNeed =
    blaiReferenceHwcElementCount(
      outResult.outputW, outResult.outputH, plan.inputC)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteScalarMaxPoolInputShape
  elif not outResult.validStride:
    outResult.firstBlock = blaiTfliteScalarMaxPoolStride
  elif not outResult.supported:
    outResult.firstBlock = blaiTfliteScalarMaxPoolKernel
  elif not outResult.outputShapeValid:
    outResult.firstBlock = blaiTfliteScalarMaxPoolWindow
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteScalarMaxPoolInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteScalarMaxPoolOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteScalarMaxPoolNoBlock
    outResult.fits = true

proc blaiReferenceTfliteScalarMaxPoolFits*(
    plan: BlaiReferenceTfliteScalarMaxPool2d,
    inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteScalarMaxPoolResult
  blaiReferenceTfliteScalarMaxPoolReadinessInto(
    plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteScalarMaxPoolSample(
    plan: BlaiReferenceTfliteScalarMaxPool2d,
    input: openArray[uint8],
    x, y: int32,
    channel: uint32): int32 =
  if x < 0 or y < 0 or x >= plan.inputW.int32 or y >= plan.inputH.int32:
    -128'i32
  else:
    let inputHwc =
      blaiHwcIndex(y.uint32, x.uint32, plan.inputW, channel, plan.inputC)
    if inputHwc.valid:
      input[inputHwc.index.int].int32 - plan.inputOffset
    else:
      -128'i32

proc blaiReferenceTfliteScalarMaxPool2d*(
    plan: BlaiReferenceTfliteScalarMaxPool2d,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteScalarMaxPoolResult =
  ## CPU fixture for odd-kernel SDK `forward_MAXPOOL_tflite`.
  blaiReferenceTfliteScalarMaxPoolReadinessInto(
    plan, input.len, output.len, result)
  if not result.fits:
    return

  let start = blaiTfliteScalarMaxPoolStart(plan)
  let step = plan.kernelSize.int32 div 2'i32
  let dilationGap =
    if plan.dilation == 0'u32: 0'i32 else: plan.dilation.int32 - 1'i32
  for outY in 0'u32 ..< result.windowH:
    let centerY = (start + outY * plan.stride).int32
    for outX in 0'u32 ..< result.windowW:
      let centerX = (start + outX * plan.stride).int32
      for channel in 0'u32 ..< plan.inputC:
        var maxValue = -128'i32
        var initialized = false
        for ky in -step .. step:
          let sampleY =
            if ky == 0'i32: centerY
            elif ky < 0'i32: centerY - ((-ky) + dilationGap)
            else: centerY + (ky + dilationGap)
          for kx in -step .. step:
            let sampleX =
              if kx == 0'i32: centerX
              elif kx < 0'i32: centerX - ((-kx) + dilationGap)
              else: centerX + (kx + dilationGap)
            let sample = blaiReferenceTfliteScalarMaxPoolSample(
              plan, input, sampleX, sampleY, channel)
            if not initialized or sample > maxValue:
              maxValue = sample
              initialized = true
        let scaled = blaiTfliteMultiplyByQuantizedMultiplier(
          maxValue, plan.outputMultiplier, plan.outputShift)
        var clamped = (scaled and 0xFF'i32).uint8
        let activationMin = (plan.activationMin and 0xFF'i32).uint8
        let activationMax = (plan.activationMax and 0xFF'i32).uint8
        if clamped < activationMin:
          clamped = activationMin
        if clamped > activationMax:
          clamped = activationMax
        let outputHwc =
          blaiHwcIndex(outY, outX, result.outputW, channel, result.outputC)
        if not outputHwc.valid:
          return
        output[outputHwc.index.int] = clamped

proc blaiAvgPoolInputStrideC(plan: BlaiReferenceAvgPool2d): uint32 =
  if plan.inputStrideC == 0'u32: plan.inputC else: plan.inputStrideC

proc blaiAvgPoolOutputStrideC(plan: BlaiReferenceAvgPool2d): uint32 =
  if plan.outputStrideC == 0'u32: plan.inputC else: plan.outputStrideC

proc blaiReferenceAvgPoolReadinessInto*(
    plan: BlaiReferenceAvgPool2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceAvgPoolResult) =
  outResult = BlaiReferenceAvgPoolResult()
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and plan.inputC != 0'u32
  outResult.validStride = plan.stride != 0'u32
  outResult.inputStrideC = blaiAvgPoolInputStrideC(plan)
  outResult.outputStrideC = blaiAvgPoolOutputStrideC(plan)
  outResult.inputStrideValid = outResult.inputStrideC >= plan.inputC
  outResult.outputStrideValid = outResult.outputStrideC >= plan.inputC
  outResult.outputC = plan.inputC
  let inputNeed =
    blaiReferenceHwcStrideExtent(
      plan.inputW, plan.inputH, plan.inputC, outResult.inputStrideC)
  let outputNeed =
    blaiReferenceHwcStrideExtent(1'u32, 1'u32, plan.inputC,
                                 outResult.outputStrideC)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiAvgPoolInputShape
  elif not outResult.validStride:
    outResult.firstBlock = blaiAvgPoolStride
  elif not outResult.inputStrideValid:
    outResult.firstBlock = blaiAvgPoolInputStride
  elif not outResult.outputStrideValid:
    outResult.firstBlock = blaiAvgPoolOutputStride
  elif not outResult.inputFits:
    outResult.firstBlock = blaiAvgPoolInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiAvgPoolOutputBuffer
  else:
    outResult.firstBlock = blaiAvgPoolNoBlock
    outResult.fits = true

proc blaiReferenceAvgPoolFits*(plan: BlaiReferenceAvgPool2d,
                               inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceAvgPoolResult
  blaiReferenceAvgPoolReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceAvgPool2d*(plan: BlaiReferenceAvgPool2d,
                             input: openArray[uint8],
                             output: var openArray[uint8]): BlaiReferenceAvgPoolResult =
  ## CPU fixture for SDK `forward_AVGPOOL_tflite`.
  blaiReferenceAvgPoolReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  let divisor = (plan.inputH * plan.inputW).int32
  for channel in 0'u32 ..< plan.inputC:
    var acc = 0'i32
    var y = 0'u32
    while y < plan.inputH:
      var x = 0'u32
      while x < plan.inputW:
        let inputHwc =
          blaiHwcStrideIndex(y, x, plan.inputW, channel, result.inputStrideC)
        if not inputHwc.valid:
          return
        acc += input[inputHwc.index.int].int32
        x += plan.stride
      y += plan.stride
    acc = (acc + divisor div 2) div divisor
    acc = min(max(acc, plan.activationMin), plan.activationMax)
    let outputHwc =
      blaiHwcStrideIndex(0'u32, 0'u32, 1'u32, channel, result.outputStrideC)
    if not outputHwc.valid:
      return
    output[outputHwc.index.int] = acc.uint8
  if result.outputStrideC > plan.inputC:
    for channel in plan.inputC ..< result.outputStrideC:
      let outputHwc =
        blaiHwcStrideIndex(0'u32, 0'u32, 1'u32, channel, result.outputStrideC)
      if not outputHwc.valid:
        return
      output[outputHwc.index.int] = 0'u8

proc blaiMeanInputStrideC(plan: BlaiReferenceTfliteMean2d): uint32 =
  if plan.inputStrideC == 0'u32: plan.inputC else: plan.inputStrideC

proc blaiCTruncDiv(value, divisor: int32): int32 =
  ## C99 signed integer division truncates toward zero.
  if divisor == 0:
    return 0
  let negative = (value < 0) xor (divisor < 0)
  let quotient = abs(value.int64) div abs(divisor.int64)
  if negative: -quotient.int32 else: quotient.int32

proc blaiReferenceTfliteMeanReadinessInto*(
    plan: BlaiReferenceTfliteMean2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteMeanResult) =
  outResult = BlaiReferenceTfliteMeanResult()
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and plan.inputC != 0'u32
  let spatialElements64 =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, 1'u32)
  outResult.spatialElementsValid =
    spatialElements64 != 0'u64 and
      blaiU64ExactI32Count(spatialElements64, outResult.spatialElements)
  outResult.outputShiftValid = plan.outputShift >= -31 and plan.outputShift <= 30
  outResult.inputStrideC = blaiMeanInputStrideC(plan)
  outResult.inputStrideValid = outResult.inputStrideC >= plan.inputC
  outResult.outputC = plan.inputC
  let inputNeed =
    blaiReferenceHwcStrideExtent(
      plan.inputW, plan.inputH, plan.inputC, outResult.inputStrideC)
  let outputNeed =
    blaiReferenceHwcStrideExtent(1'u32, 1'u32, plan.inputC, plan.inputC)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteMeanInputShape
  elif not outResult.spatialElementsValid:
    outResult.firstBlock = blaiTfliteMeanSpatialElements
  elif not outResult.outputShiftValid:
    outResult.firstBlock = blaiTfliteMeanOutputShift
  elif not outResult.inputStrideValid:
    outResult.firstBlock = blaiTfliteMeanInputStride
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteMeanInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteMeanOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteMeanNoBlock
    outResult.fits = true

proc blaiReferenceTfliteMeanFits*(plan: BlaiReferenceTfliteMean2d,
                                  inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteMeanResult
  blaiReferenceTfliteMeanReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteMean2d*(plan: BlaiReferenceTfliteMean2d,
                                input: openArray[uint8],
                                output: var openArray[uint8]): BlaiReferenceTfliteMeanResult =
  ## CPU fixture for SDK `forward_MEAN_tflite` over HWC uint8 tensors.
  blaiReferenceTfliteMeanReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  let spatialElements = result.spatialElements.int32
  for channel in 0'u32 ..< plan.inputC:
    var acc = 0'i32
    for y in 0'u32 ..< plan.inputH:
      for x in 0'u32 ..< plan.inputW:
        let inputHwc =
          blaiHwcStrideIndex(y, x, plan.inputW, channel, result.inputStrideC)
        if not inputHwc.valid:
          return
        acc = blaiClampI32(
          acc.int64 + input[inputHwc.index.int].int32.int64 -
            plan.inputOffset.int64)
    acc = blaiTfliteMultiplyByQuantizedMultiplier(
      acc, plan.outputMultiplier, plan.outputShift)
    if acc > 0:
      acc = blaiCTruncDiv(acc + spatialElements div 2, spatialElements)
    else:
      acc = blaiCTruncDiv(acc - spatialElements div 2, spatialElements)
    acc = blaiClampI32(acc.int64 + plan.outputOffset.int64)
    acc = min(max(acc, 0'i32), 255'i32)
    let outputHwc =
      blaiHwcStrideIndex(0'u32, 0'u32, 1'u32, channel, result.outputC)
    if not outputHwc.valid:
      return
    output[outputHwc.index.int] = acc.uint8

proc blaiSoftmaxInputStrideC(plan: BlaiReferenceTfliteSoftmax2d): uint32 =
  if plan.inputStrideC == 0'u32: plan.channels else: plan.inputStrideC

proc blaiSoftmaxOutputStrideC(plan: BlaiReferenceTfliteSoftmax2d): uint32 =
  if plan.outputStrideC == 0'u32: plan.channels else: plan.outputStrideC

proc blaiReferenceTfliteSoftmaxReadinessInto*(
    plan: BlaiReferenceTfliteSoftmax2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteSoftmaxResult) =
  outResult = BlaiReferenceTfliteSoftmaxResult()
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and plan.channels != 0'u32
  outResult.inputStrideC = blaiSoftmaxInputStrideC(plan)
  outResult.outputStrideC = blaiSoftmaxOutputStrideC(plan)
  outResult.inputStrideValid = outResult.inputStrideC >= plan.channels
  outResult.outputStrideValid = outResult.outputStrideC >= plan.channels
  outResult.outputW = plan.width
  outResult.outputH = plan.height
  outResult.outputC = plan.channels
  let inputNeed =
    blaiReferenceHwcStrideExtent(
      plan.width, plan.height, plan.channels, outResult.inputStrideC)
  let outputNeed =
    blaiReferenceHwcStrideExtent(
      plan.width, plan.height, plan.channels, outResult.outputStrideC)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteSoftmaxInputShape
  elif not outResult.inputStrideValid:
    outResult.firstBlock = blaiTfliteSoftmaxInputStride
  elif not outResult.outputStrideValid:
    outResult.firstBlock = blaiTfliteSoftmaxOutputStride
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteSoftmaxInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteSoftmaxOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteSoftmaxNoBlock
    outResult.fits = true

proc blaiReferenceTfliteSoftmaxFits*(plan: BlaiReferenceTfliteSoftmax2d,
                                     inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteSoftmaxResult
  blaiReferenceTfliteSoftmaxReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteSoftmax2d*(
    plan: BlaiReferenceTfliteSoftmax2d,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteSoftmaxResult =
  ## CPU fixture for SDK `forward_SOFTMAX_tflite` DATA-buffer behavior.
  blaiReferenceTfliteSoftmaxReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  for y in 0'u32 ..< plan.height:
    for x in 0'u32 ..< plan.width:
      for channel in 0'u32 ..< plan.channels:
        let inputHwc =
          blaiHwcStrideIndex(y, x, plan.width, channel, result.inputStrideC)
        if not inputHwc.valid:
          return
        let outputHwc =
          blaiHwcStrideIndex(y, x, plan.width, channel, result.outputStrideC)
        if not outputHwc.valid:
          return
        output[outputHwc.index.int] = input[inputHwc.index.int]

proc blaiTransposeAxisDim(plan: BlaiReferenceTfliteTranspose2d,
                          axis: uint32): uint32 =
  if plan.rank == 4'u32:
    case axis
    of 1'u32: plan.inputH
    of 2'u32: plan.inputW
    of 3'u32: plan.inputC
    else: 0'u32
  elif plan.rank == 3'u32:
    case axis
    of 0'u32: plan.inputH
    of 1'u32: plan.inputW
    of 2'u32: plan.inputC
    else: 0'u32
  else:
    0'u32

proc blaiTransposeAxisCoord(plan: BlaiReferenceTfliteTranspose2d,
                            axis, h, w, c: uint32): uint32 =
  if plan.rank == 4'u32:
    case axis
    of 1'u32: h
    of 2'u32: w
    else: c
  else:
    case axis
    of 0'u32: h
    of 1'u32: w
    else: c

proc blaiReferenceTfliteTransposeReadinessInto*(
    plan: BlaiReferenceTfliteTranspose2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteTransposeResult) =
  ## Derive typed fit diagnostics for recovered TFLite TRANSPOSE movement.
  outResult = default(BlaiReferenceTfliteTransposeResult)
  outResult.outputH = blaiTransposeAxisDim(plan, plan.hPerm)
  outResult.outputW = blaiTransposeAxisDim(plan, plan.wPerm)
  outResult.outputC = blaiTransposeAxisDim(plan, plan.cPerm)
  outResult.validInputShape =
    plan.inputW != 0 and plan.inputH != 0 and plan.inputC != 0
  outResult.validRank = plan.rank == 3'u32 or plan.rank == 4'u32
  outResult.validPermutation =
    plan.hPerm != plan.wPerm and plan.hPerm != plan.cPerm and
    plan.wPerm != plan.cPerm
  outResult.outputShapeValid =
    outResult.outputH != 0 and outResult.outputW != 0 and
    outResult.outputC != 0

  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteTransposeInputShape
    return
  if not outResult.validRank:
    outResult.firstBlock = blaiTfliteTransposeRank
    return
  if not outResult.outputShapeValid:
    outResult.firstBlock = blaiTfliteTransposeOutputShape
    return
  if not outResult.validPermutation:
    outResult.firstBlock = blaiTfliteTransposePermutation
    return

  let inputElements =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  let outputElements =
    blaiReferenceHwcElementCount(
      outResult.outputW, outResult.outputH, outResult.outputC)
  outResult.inputFits = inputElements <= inputLen.uint64
  if not outResult.inputFits:
    outResult.firstBlock = blaiTfliteTransposeInputBuffer
    return
  outResult.outputFits =
    inputElements == outputElements and outputElements <= outputLen.uint64
  if not outResult.outputFits:
    outResult.firstBlock = blaiTfliteTransposeOutputBuffer
    return
  outResult.firstBlock = blaiTfliteTransposeNoBlock
  outResult.fits = true

proc blaiReferenceTfliteTransposeFits*(plan: BlaiReferenceTfliteTranspose2d,
                                       inputLen, outputLen: int): bool =
  var transpose: BlaiReferenceTfliteTransposeResult
  blaiReferenceTfliteTransposeReadinessInto(
    plan, inputLen, outputLen, transpose)
  transpose.fits

proc blaiReferenceTfliteTranspose2d*(
    plan: BlaiReferenceTfliteTranspose2d,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteTransposeResult =
  ## CPU fixture for SDK `forward_TRANSPOSE_tflite` over HWC uint8 tensors.
  blaiReferenceTfliteTransposeReadinessInto(
    plan, input.len, output.len, result)
  if not result.fits:
    return

  for cin in 0'u32 ..< plan.inputC:
    for hin in 0'u32 ..< plan.inputH:
      for win in 0'u32 ..< plan.inputW:
        let inputHwc = blaiHwcIndex(hin, win, plan.inputW, cin, plan.inputC)
        if not inputHwc.valid:
          return
        let outC = blaiTransposeAxisCoord(plan, plan.cPerm, hin, win, cin)
        let outW = blaiTransposeAxisCoord(plan, plan.wPerm, hin, win, cin)
        let outH = blaiTransposeAxisCoord(plan, plan.hPerm, hin, win, cin)
        let outputHwc =
          blaiHwcIndex(outH, outW, result.outputW, outC, result.outputC)
        if not outputHwc.valid:
          return
        output[outputHwc.index.int] = input[inputHwc.index.int]

proc blaiTransposeLkSequenceLength(plan: BlaiReferenceTfliteTransposeLk1d): uint32 =
  if plan.inputW == 1'u32: plan.inputH else: plan.inputW

proc blaiTransposeLkDilation(plan: BlaiReferenceTfliteTransposeLk1d): uint32 =
  if plan.inputW == 1'u32: plan.dilationH else: plan.dilationW

proc blaiTransposeLkAlignedKernelSize(plan: BlaiReferenceTfliteTransposeLk1d): uint32 =
  blaiChannelAlign4(plan.kernelSize)

proc blaiTransposeLkFetchSize(plan: BlaiReferenceTfliteTransposeLk1d): uint32 =
  let dilation = blaiTransposeLkDilation(plan)
  if dilation == 2'u32:
    plan.kernelSize * dilation - 1'u32
  else:
    plan.kernelSize

proc blaiReferenceTfliteTransposeLkReadinessInto*(
    plan: BlaiReferenceTfliteTransposeLk1d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteTransposeLkResult,
    rollingV2 = false) =
  outResult = BlaiReferenceTfliteTransposeLkResult()
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and plan.channels != 0'u32
  outResult.validKernel = plan.kernelSize != 0'u32
  outResult.validStride = plan.stride != 0'u32
  outResult.dilation = blaiTransposeLkDilation(plan)
  outResult.validDilation = outResult.dilation != 0'u32
  outResult.rollingStrideValid =
    not rollingV2 or plan.stride <= plan.kernelSize
  outResult.sequenceLength = blaiTransposeLkSequenceLength(plan)
  outResult.alignedKernelSize = blaiTransposeLkAlignedKernelSize(plan)
  outResult.fetchSize = blaiTransposeLkFetchSize(plan)
  outResult.windowValid = outResult.sequenceLength >= outResult.fetchSize
  if outResult.windowValid and outResult.validStride:
    outResult.windowCount =
      ((outResult.sequenceLength - outResult.fetchSize) div plan.stride) + 1'u32
  let inputNeed =
    blaiReferenceTransposeLkInputElements(
      outResult.sequenceLength, plan.channels)
  let outputNeed =
    blaiReferenceTransposeLkOutputElements(
      outResult.windowCount, plan.channels, outResult.alignedKernelSize)
  let outputElementsFit =
    blaiU64ExactU32Count(outputNeed, outResult.outputElements)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits =
    outputElementsFit and outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteTransposeLkInputShape
  elif not outResult.validKernel:
    outResult.firstBlock = blaiTfliteTransposeLkKernel
  elif not outResult.validStride:
    outResult.firstBlock = blaiTfliteTransposeLkStride
  elif not outResult.validDilation:
    outResult.firstBlock = blaiTfliteTransposeLkDilation
  elif not outResult.windowValid:
    outResult.firstBlock = blaiTfliteTransposeLkWindow
  elif not outResult.rollingStrideValid:
    outResult.firstBlock = blaiTfliteTransposeLkRollingStride
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteTransposeLkInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteTransposeLkOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteTransposeLkNoBlock
    outResult.fits = true

proc blaiReferenceTfliteTransposeLkFits*(
    plan: BlaiReferenceTfliteTransposeLk1d,
    inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteTransposeLkResult
  blaiReferenceTfliteTransposeLkReadinessInto(
    plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteTransposeLk1d*(
    plan: BlaiReferenceTfliteTransposeLk1d,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteTransposeLkResult =
  ## CPU fixture for direct SDK `forward_TRANSPOSELK_tflite`.
  blaiReferenceTfliteTransposeLkReadinessInto(
    plan, input.len, output.len, result)
  if not result.fits:
    return

  const padding = 128'u8
  var window = 0'u32
  var hin = 0'u32
  while hin < result.sequenceLength - result.fetchSize + 1'u32:
    for channel in 0'u32 ..< plan.channels:
      for wt in 0'u32 ..< result.alignedKernelSize:
        let outputHwc =
          blaiHwcIndex(window, channel, plan.channels, wt,
            result.alignedKernelSize)
        if not outputHwc.valid:
          return
        let sourceOffset = wt * result.dilation + hin
        if wt >= plan.kernelSize or sourceOffset > result.sequenceLength - 1'u32:
          output[outputHwc.index.int] = padding
        else:
          let inputHwc =
            blaiHwcIndex(sourceOffset, 0'u32, 1'u32, channel, plan.channels)
          if not inputHwc.valid:
            return
          output[outputHwc.index.int] = input[inputHwc.index.int]
    inc window
    hin += plan.stride

proc blaiReferenceTfliteTransposeLkV2Fits*(
    plan: BlaiReferenceTfliteTransposeLk1d,
    inputLen, outputLen: int): bool =
  ## Bounds check for SDK `forward_TRANSPOSELK_V2_tflite`.
  var readiness: BlaiReferenceTfliteTransposeLkResult
  blaiReferenceTfliteTransposeLkReadinessInto(
    plan, inputLen, outputLen, readiness, rollingV2 = true)
  readiness.fits

proc blaiReferenceTfliteTransposeLkV2_1d*(
    plan: BlaiReferenceTfliteTransposeLk1d,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteTransposeLkResult =
  ## CPU fixture for rolling SDK `forward_TRANSPOSELK_V2_tflite`.
  blaiReferenceTfliteTransposeLkReadinessInto(
    plan, input.len, output.len, result, rollingV2 = true)
  if not result.fits:
    return

  let copyCount = plan.kernelSize - plan.stride
  const padding = 128'u8
  var window = 0'u32
  var hin = 0'u32
  while hin < result.sequenceLength - result.fetchSize + 1'u32:
    for channel in 0'u32 ..< plan.channels:
      if window > 0'u32:
        for wt in 0'u32 ..< copyCount:
          let outputHwc =
            blaiHwcIndex(window, channel, plan.channels, wt,
              result.alignedKernelSize)
          let prevHwc =
            blaiHwcIndex(window - 1'u32, channel, plan.channels,
              plan.stride + wt, result.alignedKernelSize)
          if not outputHwc.valid or not prevHwc.valid:
            return
          output[outputHwc.index.int] = output[prevHwc.index.int]
      let firstFreshTap = if window == 0'u32: 0'u32 else: copyCount
      for wt in firstFreshTap ..< plan.kernelSize:
        let sourceOffset = wt * result.dilation + hin
        let outputHwc =
          blaiHwcIndex(window, channel, plan.channels, wt,
            result.alignedKernelSize)
        if not outputHwc.valid:
          return
        if sourceOffset > result.sequenceLength - 1'u32:
          output[outputHwc.index.int] = padding
        else:
          let inputHwc =
            blaiHwcIndex(sourceOffset, 0'u32, 1'u32, channel, plan.channels)
          if not inputHwc.valid:
            return
          output[outputHwc.index.int] = input[inputHwc.index.int]
      for wt in plan.kernelSize ..< result.alignedKernelSize:
        let outputHwc =
          blaiHwcIndex(window, channel, plan.channels, wt,
            result.alignedKernelSize)
        if not outputHwc.valid:
          return
        output[outputHwc.index.int] = padding
    inc window
    hin += plan.stride

proc blaiReferenceTflitePreTransconvReadinessInto*(
    plan: BlaiReferenceTflitePreTransconv2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTflitePreTransconvResult) =
  outResult = BlaiReferenceTflitePreTransconvResult()
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and plan.channels != 0'u32
  outResult.outputShapeValid =
    plan.outputW >= plan.inputW * 2'u32 and plan.outputH >= plan.inputH * 2'u32
  outResult.outputW = plan.outputW
  outResult.outputH = plan.outputH
  outResult.outputC = plan.channels
  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.channels)
  let outputNeed =
    blaiReferenceHwcElementCount(plan.outputW, plan.outputH, plan.channels)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiTflitePreTransconvInputShape
  elif not outResult.outputShapeValid:
    outResult.firstBlock = blaiTflitePreTransconvOutputShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTflitePreTransconvInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTflitePreTransconvOutputBuffer
  else:
    outResult.firstBlock = blaiTflitePreTransconvNoBlock
    outResult.fits = true

proc blaiReferenceTflitePreTransconvFits*(
    plan: BlaiReferenceTflitePreTransconv2d,
    inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTflitePreTransconvResult
  blaiReferenceTflitePreTransconvReadinessInto(
    plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTflitePreTransconv2d*(
    plan: BlaiReferenceTflitePreTransconv2d,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTflitePreTransconvResult =
  ## CPU fixture for SDK `forward_PRE_TRANSCONV_tflite` over HWC uint8 tensors.
  blaiReferenceTflitePreTransconvReadinessInto(
    plan, input.len, output.len, result)
  if not result.fits:
    return

  let padding = (plan.inputOffset and 0xFF'i32).uint8
  for hin in 0'u32 ..< plan.inputH:
    for win in 0'u32 ..< plan.inputW:
      for channel in 0'u32 ..< plan.channels:
        let inputHwc =
          blaiHwcIndex(hin, win, plan.inputW, channel, plan.channels)
        let outputHwc =
          blaiHwcIndex(hin * 2'u32 + 1'u32, win * 2'u32 + 1'u32,
            plan.outputW, channel, plan.channels)
        let padHwc =
          blaiHwcIndex(hin * 2'u32 + 1'u32, win * 2'u32,
            plan.outputW, channel, plan.channels)
        if not inputHwc.valid or not outputHwc.valid or not padHwc.valid:
          return
        output[outputHwc.index.int] = input[inputHwc.index.int]
        output[padHwc.index.int] = padding

    let padRow = hin * 2'u32
    for x in 0'u32 ..< plan.outputW:
      for channel in 0'u32 ..< plan.channels:
        let padHwc =
          blaiHwcIndex(padRow, x, plan.outputW, channel, plan.channels)
        if not padHwc.valid:
          return
        output[padHwc.index.int] = padding

proc blaiReferenceTfliteDequantizeReadinessInto*(
    plan: BlaiReferenceTfliteDequantize2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteDequantizeResult) =
  outResult = BlaiReferenceTfliteDequantizeResult()
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and plan.channels != 0'u32
  let elements =
    blaiReferenceHwcElementCount(plan.width, plan.height, plan.channels)
  discard blaiU64ExactU32Count(elements, outResult.elements)
  outResult.outputW = plan.width
  outResult.outputH = plan.height
  outResult.outputC = plan.channels
  outResult.inputFits = elements <= inputLen.uint64
  outResult.outputFits = elements <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteDequantizeInputShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteDequantizeInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteDequantizeOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteDequantizeNoBlock
    outResult.fits = true

proc blaiReferenceTfliteDequantizeFits*(
    plan: BlaiReferenceTfliteDequantize2d,
    inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteDequantizeResult
  blaiReferenceTfliteDequantizeReadinessInto(
    plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteDequantize2d*(
    plan: BlaiReferenceTfliteDequantize2d,
    input: openArray[uint8],
    output: var openArray[float32]): BlaiReferenceTfliteDequantizeResult =
  ## CPU fixture for SDK `forward_DEQUANTIZE_tflite` over HWC uint8 tensors.
  blaiReferenceTfliteDequantizeReadinessInto(
    plan, input.len, output.len, result)
  if not result.fits:
    return

  for channel in 0'u32 ..< plan.channels:
    for y in 0'u32 ..< plan.height:
      for x in 0'u32 ..< plan.width:
        let hwc = blaiHwcIndex(y, x, plan.width, channel, plan.channels)
        if not hwc.valid:
          return
        let index = hwc.index
        output[index.int] =
          (input[index.int].int32 - plan.inputOffset).float32 * plan.inputScale

proc blaiReferenceTfliteLogisticReadinessInto*(
    plan: BlaiReferenceTfliteLogistic2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteLogisticResult) =
  outResult = BlaiReferenceTfliteLogisticResult()
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and plan.channels != 0'u32
  outResult.outputScaleValid = plan.outputScale != 0.0'f32
  let elements =
    blaiReferenceHwcElementCount(plan.width, plan.height, plan.channels)
  discard blaiU64ExactU32Count(elements, outResult.elements)
  outResult.outputW = plan.width
  outResult.outputH = plan.height
  outResult.outputC = plan.channels
  outResult.inputFits = elements <= inputLen.uint64
  outResult.outputFits = elements <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteLogisticInputShape
  elif not outResult.outputScaleValid:
    outResult.firstBlock = blaiTfliteLogisticOutputScale
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteLogisticInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteLogisticOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteLogisticNoBlock
    outResult.fits = true

proc blaiReferenceTfliteLogisticFits*(
    plan: BlaiReferenceTfliteLogistic2d,
    inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteLogisticResult
  blaiReferenceTfliteLogisticReadinessInto(
    plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceExpApprox(value: float32): float32 =
  ## Bounded exp approximation for recovered CPU-reference fixtures.
  ##
  ## Bare-metal M0 firmware links without libm, so using std/math `exp` pulls in
  ## an unavailable `expf`. The logistic fixture only needs the recovered SDK
  ## cutoff range, so a range-reduced polynomial is sufficient and deterministic.
  const
    ln2 = 0.6931471805599453'f32
    invLn2 = 1.4426950408889634'f32
  if value <= -24.0'f32:
    return 0.0'f32
  if value >= 24.0'f32:
    return 26_489_712_640.0'f32

  let scaled = value * invLn2
  let k =
    if scaled >= 0.0'f32:
      int(scaled + 0.5'f32)
    else:
      int(scaled - 0.5'f32)
  let r = value - k.float32 * ln2
  var term = 1.0'f32
  var poly = 1.0'f32
  term = term * r
  poly = poly + term
  term = term * r * 0.5'f32
  poly = poly + term
  term = term * r * (1.0'f32 / 3.0'f32)
  poly = poly + term
  term = term * r * 0.25'f32
  poly = poly + term
  term = term * r * 0.2'f32
  poly = poly + term
  term = term * r * (1.0'f32 / 6.0'f32)
  poly = poly + term

  result = poly
  if k > 0:
    for _ in 0 ..< k:
      result = result * 2.0'f32
  elif k < 0:
    for _ in 0 ..< -k:
      result = result * 0.5'f32

proc blaiReferenceTfliteLogisticValue*(value: float32): float32 =
  ## SDK `forward_LOGISTIC_tflite` float sigmoid with recovered cutoffs.
  const
    cutoffUpper = 16.619047164916992188'f32
    cutoffLower = -9.0'f32
  if value > cutoffUpper:
    1.0'f32
  elif value < cutoffLower:
    blaiReferenceExpApprox(value)
  else:
    1.0'f32 / (1.0'f32 + blaiReferenceExpApprox(-value))

proc blaiReferenceTfliteLogistic2d*(
    plan: BlaiReferenceTfliteLogistic2d,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteLogisticResult =
  ## CPU fixture for SDK `forward_LOGISTIC_tflite` over HWC uint8 tensors.
  blaiReferenceTfliteLogisticReadinessInto(
    plan, input.len, output.len, result)
  if not result.fits:
    return

  for channel in 0'u32 ..< plan.channels:
    for y in 0'u32 ..< plan.height:
      for x in 0'u32 ..< plan.width:
        let hwc = blaiHwcIndex(y, x, plan.width, channel, plan.channels)
        if not hwc.valid:
          return
        let index = hwc.index
        let value = (input[index.int].int32 - plan.inputOffset).float32 *
          plan.inputScale
        let logistic = blaiReferenceTfliteLogisticValue(value)
        let scaled = logistic / plan.outputScale + plan.outputOffset.float32
        output[index.int] = scaled.uint8

proc blaiUpsampleOutputW(plan: BlaiReferenceUpsample2d): uint32 =
  if plan.outputW == 0'u32: plan.inputW * plan.stride else: plan.outputW

proc blaiUpsampleOutputH(plan: BlaiReferenceUpsample2d): uint32 =
  if plan.outputH == 0'u32: plan.inputH * plan.stride else: plan.outputH

proc blaiUpsampleOutputC(plan: BlaiReferenceUpsample2d): uint32 =
  if plan.outputC == 0'u32: plan.inputC else: plan.outputC

proc blaiReferenceUpsampleReadinessInto*(
    plan: BlaiReferenceUpsample2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceUpsampleResult) =
  outResult = BlaiReferenceUpsampleResult()
  outResult.validInputShape =
    plan.inputW != 0'u32 and plan.inputH != 0'u32 and plan.inputC != 0'u32
  outResult.validStride = plan.stride != 0'u32
  outResult.outputW = blaiUpsampleOutputW(plan)
  outResult.outputH = blaiUpsampleOutputH(plan)
  outResult.outputC = blaiUpsampleOutputC(plan)
  outResult.outputShapeValid =
    outResult.outputW >= plan.inputW * plan.stride and
    outResult.outputH >= plan.inputH * plan.stride and
    outResult.outputC >= plan.inputC
  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  discard blaiU64ExactU32Count(inputNeed, outResult.inputElements)
  var outputNeed = 0'u64
  if outResult.validInputShape and outResult.validStride:
    outputNeed =
      blaiReferenceUpsampleOutputExtent(
        plan.inputW, plan.inputH, plan.inputC, plan.stride,
        outResult.outputW, outResult.outputC)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiUpsampleInputShape
  elif not outResult.validStride:
    outResult.firstBlock = blaiUpsampleStride
  elif not outResult.outputShapeValid:
    outResult.firstBlock = blaiUpsampleOutputShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiUpsampleInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiUpsampleOutputBuffer
  else:
    outResult.firstBlock = blaiUpsampleNoBlock
    outResult.fits = true

proc blaiReferenceUpsampleFits*(plan: BlaiReferenceUpsample2d,
                                inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceUpsampleResult
  blaiReferenceUpsampleReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceUpsample2d*(plan: BlaiReferenceUpsample2d,
                              input: openArray[int8],
                              output: var openArray[int8]): BlaiReferenceUpsampleResult =
  ## CPU fixture for SDK `forward_UPSAMPLE` over HWC int8 tensors.
  blaiReferenceUpsampleReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  let fshift = plan.fdata - plan.fout
  for channel in 0'u32 ..< plan.inputC:
    for y in 0'u32 ..< plan.inputH:
      for x in 0'u32 ..< plan.inputW:
        let inputHwc = blaiHwcIndex(y, x, plan.inputW, channel, plan.inputC)
        if not inputHwc.valid:
          return
        let inputIndex = inputHwc.index
        let sample = blaiFixed8ToFixed8(input[inputIndex.int], fshift)
        for strideX in 0'u32 ..< plan.stride:
          for strideY in 0'u32 ..< plan.stride:
            var outputY, outputX: uint32
            if not blaiU64ExactU32Count(
                y.uint64 * plan.stride.uint64 + strideY.uint64, outputY):
              return
            if not blaiU64ExactU32Count(
                x.uint64 * plan.stride.uint64 + strideX.uint64, outputX):
              return
            let outputHwc =
              blaiHwcIndex(outputY, outputX, result.outputW, channel, result.outputC)
            if not outputHwc.valid:
              return
            let outputIndex = outputHwc.index
            output[outputIndex.int] = sample

proc blaiRouteUpsampleOutputW(plan: BlaiReferenceRouteUpsample2d): uint32 =
  if plan.outputW == 0'u32: plan.width * plan.stride else: plan.outputW

proc blaiRouteUpsampleOutputH(plan: BlaiReferenceRouteUpsample2d): uint32 =
  if plan.outputH == 0'u32: plan.height * plan.stride else: plan.outputH

proc blaiRouteUpsampleOutputC(plan: BlaiReferenceRouteUpsample2d): uint32 =
  if plan.outputC == 0'u32: plan.route1C + plan.route2C else: plan.outputC

proc blaiReferenceRouteUpsampleReadinessInto*(
    plan: BlaiReferenceRouteUpsample2d,
    input1Len, input2Len, outputLen: int,
    outResult: var BlaiReferenceRouteUpsampleResult) =
  outResult = BlaiReferenceRouteUpsampleResult()
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and
      plan.route1C != 0'u32 and plan.route2C != 0'u32
  outResult.validStride = plan.stride != 0'u32
  outResult.outputW = blaiRouteUpsampleOutputW(plan)
  outResult.outputH = blaiRouteUpsampleOutputH(plan)
  outResult.outputC = blaiRouteUpsampleOutputC(plan)

  let routeC = plan.route1C.uint64 + plan.route2C.uint64
  let routeCFits = blaiU64ExactU32Count(routeC, outResult.routeC)
  outResult.routeChannelsValid =
    routeCFits and outResult.outputC.uint64 == routeC

  let minimumOutputW = blaiReferenceScaledDimExtent(plan.width, plan.stride)
  let minimumOutputH = blaiReferenceScaledDimExtent(plan.height, plan.stride)
  outResult.outputShapeValid =
    outResult.outputW.uint64 >= minimumOutputW and
      outResult.outputH.uint64 >= minimumOutputH

  let input1Need =
    blaiReferenceHwcElementCount(plan.width, plan.height, plan.route1C)
  let input2Need =
    blaiReferenceHwcElementCount(plan.width, plan.height, plan.route2C)
  discard blaiU64ExactU32Count(input1Need, outResult.input1Elements)
  discard blaiU64ExactU32Count(input2Need, outResult.input2Elements)

  var outputNeed = 0'u64
  if outResult.validInputShape and outResult.validStride and
      outResult.routeChannelsValid and outResult.outputShapeValid:
    outputNeed =
      blaiReferenceUpsampleOutputExtent(
        plan.width, plan.height, outResult.outputC, plan.stride,
        outResult.outputW, outResult.outputC)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)

  outResult.input1Fits = input1Need <= input1Len.uint64
  outResult.input2Fits = input2Need <= input2Len.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiRouteUpsampleInputShape
  elif not outResult.validStride:
    outResult.firstBlock = blaiRouteUpsampleStride
  elif not outResult.routeChannelsValid:
    outResult.firstBlock = blaiRouteUpsampleRouteChannels
  elif not outResult.outputShapeValid:
    outResult.firstBlock = blaiRouteUpsampleOutputShape
  elif not outResult.input1Fits:
    outResult.firstBlock = blaiRouteUpsampleInput1Buffer
  elif not outResult.input2Fits:
    outResult.firstBlock = blaiRouteUpsampleInput2Buffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiRouteUpsampleOutputBuffer
  else:
    outResult.firstBlock = blaiRouteUpsampleNoBlock
    outResult.fits = true

proc blaiReferenceRouteUpsampleFits*(plan: BlaiReferenceRouteUpsample2d,
                                     input1Len, input2Len, outputLen: int): bool =
  var readiness: BlaiReferenceRouteUpsampleResult
  blaiReferenceRouteUpsampleReadinessInto(
    plan, input1Len, input2Len, outputLen, readiness)
  readiness.fits

proc blaiReferenceRouteUpsample2d*(
    plan: BlaiReferenceRouteUpsample2d,
    input1, input2: openArray[int8],
    output: var openArray[int8]): BlaiReferenceRouteUpsampleResult =
  ## CPU fixture for SDK `forward_ROUTE_UPSAMPLE` over HWC int8 tensors.
  blaiReferenceRouteUpsampleReadinessInto(
    plan, input1.len, input2.len, output.len, result)
  if not result.fits:
    return

  for channel in 0'u32 ..< result.outputC:
    let fromSecond = channel >= plan.route1C
    let localChannel = if fromSecond: channel - plan.route1C else: channel
    let inputC = if fromSecond: plan.route2C else: plan.route1C
    let routeShift =
      if fromSecond: plan.froute2 - plan.fdata else: plan.froute1 - plan.fdata
    for y in 0'u32 ..< plan.height:
      for x in 0'u32 ..< plan.width:
        let inputHwc = blaiHwcIndex(y, x, plan.width, localChannel, inputC)
        if not inputHwc.valid:
          return
        let inputIndex = inputHwc.index
        let routeSample =
          if fromSecond:
            blaiFixed8ToFixed8(input2[inputIndex.int], routeShift)
          else:
            blaiFixed8ToFixed8(input1[inputIndex.int], routeShift)
        let sample = blaiFixed8ToFixed8(routeSample, plan.fdata - plan.fout)
        for strideX in 0'u32 ..< plan.stride:
          for strideY in 0'u32 ..< plan.stride:
            var outputY, outputX: uint32
            if not blaiU64ExactU32Count(
                y.uint64 * plan.stride.uint64 + strideY.uint64, outputY):
              return
            if not blaiU64ExactU32Count(
                x.uint64 * plan.stride.uint64 + strideX.uint64, outputX):
              return
            let outputHwc =
              blaiHwcIndex(outputY, outputX, result.outputW, channel, result.outputC)
            if not outputHwc.valid:
              return
            let outputIndex = outputHwc.index
            output[outputIndex.int] = sample

proc blaiReferenceTflitePadSupported*(plan: BlaiReferenceTflitePad2d): bool =
  ## SDK `forward_PAD_tflite` only implements spatial padding.
  plan.leftPadC == 0 and plan.rightPadC == 0

proc blaiReferenceTflitePadChannelPaddingRequested*(
    plan: BlaiReferenceTflitePad2d): bool =
  ## True when the SDK warning-only channel-padding branch would be selected.
  plan.leftPadC != 0 or plan.rightPadC != 0

proc blaiReferenceTflitePadOutputW*(plan: BlaiReferenceTflitePad2d): uint32 =
  blaiReferencePaddedDim(plan.leftPadW, plan.inputW, plan.rightPadW)

proc blaiReferenceTflitePadOutputH*(plan: BlaiReferenceTflitePad2d): uint32 =
  blaiReferencePaddedDim(plan.leftPadH, plan.inputH, plan.rightPadH)

proc blaiReferenceTflitePadOutputC*(plan: BlaiReferenceTflitePad2d): uint32 =
  blaiReferencePaddedDim(plan.leftPadC, plan.inputC, plan.rightPadC)

proc blaiReferenceTflitePadReadinessInto*(
    plan: BlaiReferenceTflitePad2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTflitePadResult)

proc blaiReferenceTflitePadFits*(plan: BlaiReferenceTflitePad2d,
                                 inputLen, outputLen: int): bool =
  var pad: BlaiReferenceTflitePadResult
  blaiReferenceTflitePadReadinessInto(plan, inputLen, outputLen, pad)
  pad.fits

proc blaiReferenceTflitePadReadinessInto*(
    plan: BlaiReferenceTflitePad2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTflitePadResult) =
  ## Derive typed fit/support diagnostics for recovered TFLite PAD data movement.
  outResult = default(BlaiReferenceTflitePadResult)
  outResult.outputW = blaiReferenceTflitePadOutputW(plan)
  outResult.outputH = blaiReferenceTflitePadOutputH(plan)
  outResult.outputC = blaiReferenceTflitePadOutputC(plan)
  outResult.channelPaddingRequested =
    blaiReferenceTflitePadChannelPaddingRequested(plan)
  outResult.supported = not outResult.channelPaddingRequested

  if plan.inputW == 0 or plan.inputH == 0 or plan.inputC == 0:
    outResult.firstBlock = blaiTflitePadInputShape
    return
  if outResult.channelPaddingRequested:
    outResult.firstBlock = blaiTflitePadChannelPadding
    return
  if outResult.outputW == 0 or outResult.outputH == 0 or outResult.outputC == 0:
    outResult.firstBlock = blaiTflitePadOutputShape
    return

  let inputNeed =
    blaiReferenceHwcElementCount(plan.inputW, plan.inputH, plan.inputC)
  outResult.inputFits = inputNeed <= inputLen.uint64
  if not outResult.inputFits:
    outResult.firstBlock = blaiTflitePadInputBuffer
    return

  let outputNeed =
    blaiReferenceHwcElementCount(
      outResult.outputW, outResult.outputH, outResult.outputC)
  outResult.outputFits = outputNeed <= outputLen.uint64
  if not outResult.outputFits:
    outResult.firstBlock = blaiTflitePadOutputBuffer
    return

  outResult.firstBlock = blaiTflitePadNoBlock
  outResult.fits = true

proc blaiReferenceTflitePad2d*(plan: BlaiReferenceTflitePad2d,
                               input: openArray[uint8],
                               output: var openArray[uint8]): BlaiReferenceTflitePadResult =
  ## CPU fixture for SDK `forward_PAD_tflite` over HWC uint8 tensors.
  blaiReferenceTflitePadReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  for outY in 0'u32 ..< result.outputH:
    let inputY = outY.int64 - plan.leftPadH.int64
    for outX in 0'u32 ..< result.outputW:
      let inputX = outX.int64 - plan.leftPadW.int64
      let padCheck = inputY < 0 or inputX < 0 or
        inputY >= plan.inputH.int64 or inputX >= plan.inputW.int64
      if padCheck:
        for channel in 0'u32 ..< result.outputC:
          let outputHwc =
            blaiHwcIndex(outY, outX, result.outputW, channel, result.outputC)
          if not outputHwc.valid:
            return
          output[outputHwc.index.int] = plan.paddingValue
      else:
        for channel in 0'u32 ..< result.outputC:
          let inputHwc =
            blaiHwcIndex(inputY.uint32, inputX.uint32, plan.inputW, channel,
              plan.inputC)
          if not inputHwc.valid:
            return
          let outputHwc =
            blaiHwcIndex(outY, outX, result.outputW, channel, result.outputC)
          if not outputHwc.valid:
            return
          output[outputHwc.index.int] = input[inputHwc.index.int]

proc blaiReferenceRouteMaxReadinessInto*(
    plan: BlaiReferenceRouteMax2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceRouteMaxResult) =
  outResult = BlaiReferenceRouteMaxResult()
  outResult.outputW = plan.outputW
  outResult.outputH = plan.outputH
  outResult.validInputShape = plan.width != 0'u32 and plan.height != 0'u32
  outResult.validStride = plan.stride != 0'u32
  outResult.validInputCount =
    plan.inputCount != 0'u32 and plan.inputCount <= BlaiMaxInputNumU32
  outResult.inputsActive = true
  outResult.inputChannelsValid = true
  outResult.inputFits = true
  outResult.outputChannelsValid = true

  if plan.outputW != 0'u32 and plan.outputH != 0'u32 and
      outResult.validInputShape:
    let maxOutputY = (plan.height - 1'u32) div 2'u32
    let maxOutputX = (plan.width - 1'u32) div 2'u32
    outResult.validOutputShape =
      maxOutputY < plan.outputH and maxOutputX < plan.outputW

  var outputChannels = 0'u64
  var maxInputNeed = 0'u64
  if outResult.validInputCount:
    for inputIndex in 0'u32 ..< plan.inputCount:
      let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
      if not inputCursor.valid:
        outResult.inputsActive = false
        outResult.firstBlockedInput = inputIndex
        break
      let inputPlan = plan.inputs[inputCursor.index]
      if not inputPlan.active:
        outResult.inputsActive = false
        outResult.firstBlockedInput = inputIndex
        break
      if inputPlan.channels == 0'u32:
        outResult.inputChannelsValid = false
        outResult.firstBlockedInput = inputIndex
        break
      let inputNeed = blaiReferenceRouteInputExtent(
        inputPlan.offset, plan.width, plan.height, inputPlan.channels)
      if inputNeed > maxInputNeed:
        maxInputNeed = inputNeed
      if inputNeed > inputLen.uint64:
        outResult.inputFits = false
        outResult.firstBlockedInput = inputIndex
        discard blaiU64ExactU32Count(
          inputNeed, outResult.firstBlockedInputElements)
        break
      outputChannels += inputPlan.channels.uint64
      if outputChannels > high(uint32).uint64:
        outResult.outputChannelsValid = false
        outResult.firstBlockedInput = inputIndex
        break

  discard blaiU64MaxExactU32Count(
    maxInputNeed, outResult.firstBlockedInputElements)
  if not blaiU64ExactU32Count(outputChannels, outResult.outputC):
    outResult.outputChannelsValid = false
  if outputChannels == 0'u64:
    outResult.outputChannelsValid = false

  let outputNeed =
    blaiReferenceHwcElementCount(plan.outputW, plan.outputH, outputChannels)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.outputFits = outputNeed <= outputLen.uint64

  if not outResult.validInputShape:
    outResult.firstBlock = blaiRouteMaxInputShape
  elif not outResult.validOutputShape:
    outResult.firstBlock = blaiRouteMaxOutputShape
  elif not outResult.validStride:
    outResult.firstBlock = blaiRouteMaxStride
  elif not outResult.validInputCount:
    outResult.firstBlock = blaiRouteMaxInputCount
  elif not outResult.inputsActive:
    outResult.firstBlock = blaiRouteMaxInputInactive
  elif not outResult.inputChannelsValid:
    outResult.firstBlock = blaiRouteMaxInputChannels
  elif not outResult.inputFits:
    outResult.firstBlock = blaiRouteMaxInputBuffer
  elif not outResult.outputChannelsValid:
    outResult.firstBlock = blaiRouteMaxOutputChannels
  elif not outResult.outputFits:
    outResult.firstBlock = blaiRouteMaxOutputBuffer
  else:
    outResult.firstBlock = blaiRouteMaxNoBlock
    outResult.fits = true

proc blaiReferenceRouteConcatReadinessInto*(
    plan: BlaiReferenceRouteConcat2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceRouteConcatResult) =
  outResult = BlaiReferenceRouteConcatResult()
  outResult.outputW = plan.width
  outResult.outputH = plan.height
  outResult.validInputShape = plan.width != 0'u32 and plan.height != 0'u32
  outResult.validInputCount =
    plan.inputCount != 0'u32 and plan.inputCount <= BlaiMaxInputNumU32
  outResult.inputsActive = true
  outResult.inputChannelsValid = true
  outResult.inputFits = true
  outResult.outputChannelsValid = true

  var outputChannels = 0'u64
  var maxInputNeed = 0'u64
  if outResult.validInputCount:
    for inputIndex in 0'u32 ..< plan.inputCount:
      let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
      if not inputCursor.valid:
        outResult.inputsActive = false
        outResult.firstBlockedInput = inputIndex
        break
      let inputPlan = plan.inputs[inputCursor.index]
      if not inputPlan.active:
        outResult.inputsActive = false
        outResult.firstBlockedInput = inputIndex
        break
      if inputPlan.channels == 0'u32:
        outResult.inputChannelsValid = false
        outResult.firstBlockedInput = inputIndex
        break
      let inputNeed = blaiReferenceRouteInputExtent(
        inputPlan.offset, plan.width, plan.height, inputPlan.channels)
      if inputNeed > maxInputNeed:
        maxInputNeed = inputNeed
      if inputNeed > inputLen.uint64:
        outResult.inputFits = false
        outResult.firstBlockedInput = inputIndex
        discard blaiU64ExactU32Count(
          inputNeed, outResult.firstBlockedInputElements)
        break
      outputChannels += inputPlan.channels.uint64
      if outputChannels > high(uint32).uint64:
        outResult.outputChannelsValid = false
        outResult.firstBlockedInput = inputIndex
        break

  discard blaiU64MaxExactU32Count(
    maxInputNeed, outResult.firstBlockedInputElements)
  if not blaiU64ExactU32Count(outputChannels, outResult.outputC):
    outResult.outputChannelsValid = false
  if outputChannels == 0'u64:
    outResult.outputChannelsValid = false

  let outputNeed =
    blaiReferenceHwcElementCount(plan.width, plan.height, outputChannels)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.outputFits = outputNeed <= outputLen.uint64

  if not outResult.validInputShape:
    outResult.firstBlock = blaiRouteConcatInputShape
  elif not outResult.validInputCount:
    outResult.firstBlock = blaiRouteConcatInputCount
  elif not outResult.inputsActive:
    outResult.firstBlock = blaiRouteConcatInputInactive
  elif not outResult.inputChannelsValid:
    outResult.firstBlock = blaiRouteConcatInputChannels
  elif not outResult.inputFits:
    outResult.firstBlock = blaiRouteConcatInputBuffer
  elif not outResult.outputChannelsValid:
    outResult.firstBlock = blaiRouteConcatOutputChannels
  elif not outResult.outputFits:
    outResult.firstBlock = blaiRouteConcatOutputBuffer
  else:
    outResult.firstBlock = blaiRouteConcatNoBlock
    outResult.fits = true

proc blaiReferenceRouteInput*(source: BlaiCpuRouteInputSource,
                              patchSize: uint32): BlaiReferenceRouteInput =
  ## Project an SDK route input source to the flat-buffer reference fixture.
  if not source.active or source.memorySlot < 0 or source.channels <= 0:
    return
  let offset = blaiPatchSlotOffset(source.memorySlot, patchSize)
  if not offset.valid:
    return
  BlaiReferenceRouteInput(
    active: true,
    offset: offset.offset,
    channels: source.channels.uint32,
    fractionalBits: source.fractionalBits)

proc blaiReferenceRouteInput*(layer: BlaiCpuInstLayer64,
                              storage: BlaiCpuExtraInputStorage,
                              patchSize: uint32,
                              inputIndex: uint32): BlaiReferenceRouteInput =
  ## Project one parsed CPU route input through typed sidecar storage.
  blaiReferenceRouteInput(
    blaiCpuRouteInputSource(layer, storage, inputIndex), patchSize)

proc blaiReferenceRouteConcatPlan*(layer: BlaiCpuInstLayer64,
                                   storage: BlaiCpuExtraInputStorage,
                                   patchSize: uint32): BlaiReferenceRouteConcat2d =
  ## Build a `forward_ROUTE` reference plan from parsed CPU layer metadata.
  result.width = nonNegativeU32(layer.w)
  result.height = nonNegativeU32(layer.h)
  result.inputCount = min(nonNegativeU32(layer.inputNum), BlaiMaxInputNumU32)
  result.outputFractionalBits = layer.fdata
  for inputIndex in 0'u32 ..< result.inputCount:
    let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
    if not inputCursor.valid:
      return
    result.inputs[inputCursor.index] = blaiReferenceRouteInput(
      layer, storage, patchSize, inputIndex)

proc blaiReferenceRouteMaxPlan*(layer: BlaiCpuInstLayer64,
                                storage: BlaiCpuExtraInputStorage,
                                patchSize: uint32): BlaiReferenceRouteMax2d =
  ## Build a `forward_ROUTE_MAX` reference plan from parsed CPU layer metadata.
  result.width = nonNegativeU32(layer.w)
  result.height = nonNegativeU32(layer.h)
  result.outputW = nonNegativeU32(layer.outW)
  result.outputH = nonNegativeU32(layer.outH)
  result.stride = nonNegativeU32(layer.stride)
  result.inputCount = min(nonNegativeU32(layer.inputNum), BlaiMaxInputNumU32)
  result.outputFractionalBits = layer.fdata
  for inputIndex in 0'u32 ..< result.inputCount:
    let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
    if not inputCursor.valid:
      return
    result.inputs[inputCursor.index] = blaiReferenceRouteInput(
      layer, storage, patchSize, inputIndex)

proc blaiReferenceTfliteRouteInput*(source: BlaiCpuRouteInputSource,
                                    quant: BlaiCpuTfliteInputQuant,
                                    patchSize: uint32): BlaiReferenceTfliteRouteInput =
  ## Project one SDK TFLite route input to the flat-buffer reference fixture.
  if not source.active or not quant.active or source.memorySlot < 0 or
      source.channels <= 0:
    return
  let offset = blaiPatchSlotOffset(source.memorySlot, patchSize)
  if not offset.valid:
    return
  BlaiReferenceTfliteRouteInput(
    active: true,
    offset: offset.offset,
    channels: source.channels.uint32,
    inputOffset: quant.offset,
    inputMultiplier: quant.multiplier,
    inputShift: quant.shift)

proc blaiReferenceTfliteRouteInput*(layer: BlaiCpuInstLayer64,
                                    storage: BlaiCpuExtraInputStorage,
                                    patchSize: uint32,
                                    inputIndex: uint32): BlaiReferenceTfliteRouteInput =
  ## Project one parsed CPU TFLite route input through typed sidecar storage.
  blaiReferenceTfliteRouteInput(
    blaiCpuRouteInputSource(layer, storage, inputIndex),
    blaiCpuTfliteInputQuant(layer, storage, inputIndex),
    patchSize)

proc blaiReferenceTfliteRoutePlan*(layer: BlaiCpuInstLayer64,
                                   storage: BlaiCpuExtraInputStorage,
                                   patchSize: uint32): BlaiReferenceTfliteRoute2d =
  ## Build a `forward_ROUTE_tflite` reference plan from parsed CPU metadata.
  result.width = nonNegativeU32(layer.outW)
  if result.width == 0:
    result.width = nonNegativeU32(layer.w)
  result.height = nonNegativeU32(layer.h)
  result.outputC = nonNegativeU32(layer.outC)
  result.inputCount = min(nonNegativeU32(layer.inputNum), BlaiMaxInputNumU32)
  result.outputOffset = layer.tfOutputOffset
  result.outputMultiplier = layer.tfOutputMultiplier
  result.outputShift = layer.tfOutputShift
  result.activationMin = layer.quantizedActivationMin
  result.activationMax = layer.quantizedActivationMax
  for inputIndex in 0'u32 ..< result.inputCount:
    let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
    if not inputCursor.valid:
      return
    result.inputs[inputCursor.index] = blaiReferenceTfliteRouteInput(
      layer, storage, patchSize, inputIndex)

proc blaiReferenceTfliteRouteMaxPlan*(layer: BlaiCpuInstLayer64,
                                      storage: BlaiCpuExtraInputStorage,
                                      patchSize: uint32): BlaiReferenceTfliteRouteMax2d =
  ## Build a `forward_ROUTE_MAX_tflite` reference plan from parsed CPU metadata.
  result.width = nonNegativeU32(layer.w)
  result.height = nonNegativeU32(layer.h)
  result.outputW = nonNegativeU32(layer.outW)
  result.outputH = nonNegativeU32(layer.outH)
  result.stride = nonNegativeU32(layer.stride)
  result.outputC = nonNegativeU32(layer.outC)
  result.inputCount = min(nonNegativeU32(layer.inputNum), BlaiMaxInputNumU32)
  result.outputOffset = layer.tfOutputOffset
  result.outputMultiplier = layer.tfOutputMultiplier
  result.outputShift = layer.tfOutputShift
  result.activationMin = layer.quantizedActivationMin
  result.activationMax = layer.quantizedActivationMax
  for inputIndex in 0'u32 ..< result.inputCount:
    let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
    if not inputCursor.valid:
      return
    result.inputs[inputCursor.index] = blaiReferenceTfliteRouteInput(
      layer, storage, patchSize, inputIndex)

proc blaiReferenceTfliteRouteWPlan*(layer: BlaiCpuInstLayer64,
                                    storage: BlaiCpuExtraInputStorage,
                                    patchSize: uint32): BlaiReferenceTfliteRouteW2d =
  ## Build a `forward_ROUTE_W_tflite` reference plan from parsed CPU metadata.
  result.width = nonNegativeU32(layer.w)
  result.height = nonNegativeU32(layer.h)
  result.outputW = nonNegativeU32(layer.outW)
  result.outputC = nonNegativeU32(layer.outC)
  result.axis = nonNegativeU32(layer.axis)
  result.inputCount = min(nonNegativeU32(layer.inputNum), BlaiMaxInputNumU32)
  result.outputOffset = layer.tfOutputOffset
  result.outputMultiplier = layer.tfOutputMultiplier
  result.outputShift = layer.tfOutputShift
  result.activationMin = layer.quantizedActivationMin
  result.activationMax = layer.quantizedActivationMax
  for inputIndex in 0'u32 ..< result.inputCount:
    let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
    if not inputCursor.valid:
      return
    result.inputs[inputCursor.index] = blaiReferenceTfliteRouteInput(
      layer, storage, patchSize, inputIndex)

proc blaiReferenceTfliteTransposePlan*(
    layer: BlaiCpuInstLayer64,
    mask: BlaiCpuTfliteTransposeMask): BlaiReferenceTfliteTranspose2d =
  ## Build a `forward_TRANSPOSE_tflite` plan from layer metadata plus typed mask.
  if not mask.active:
    return
  BlaiReferenceTfliteTranspose2d(
    inputW: nonNegativeU32(layer.w),
    inputH: nonNegativeU32(layer.h),
    inputC: nonNegativeU32(layer.c),
    rank: mask.rank,
    hPerm: mask.hPerm,
    wPerm: mask.wPerm,
    cPerm: mask.cPerm)

proc blaiReferenceTfliteTransposeLkPlan*(
    layer: BlaiCpuInstLayer64): BlaiReferenceTfliteTransposeLk1d =
  ## Build a `forward_TRANSPOSELK*_tflite` plan from layer metadata.
  let dilation = nonNegativeU32(layer.dilation)
  BlaiReferenceTfliteTransposeLk1d(
    inputW: nonNegativeU32(layer.w),
    inputH: nonNegativeU32(layer.h),
    channels: nonNegativeU32(layer.c),
    kernelSize: nonNegativeU32(layer.size),
    stride: nonNegativeU32(layer.stride),
    dilationW: dilation,
    dilationH: dilation)

proc blaiReferenceTfliteRouteReadinessInto*(
    plan: BlaiReferenceTfliteRoute2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteRouteResult)

proc blaiReferenceTfliteRouteFits*(plan: BlaiReferenceTfliteRoute2d,
                                   inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteRouteResult
  blaiReferenceTfliteRouteReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteRouteReadinessInto*(
    plan: BlaiReferenceTfliteRoute2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteRouteResult) =
  outResult = BlaiReferenceTfliteRouteResult()
  outResult.outputW = plan.width
  outResult.outputH = plan.height
  outResult.outputC = plan.outputC
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and plan.outputC != 0'u32
  outResult.validInputCount =
    plan.inputCount != 0'u32 and plan.inputCount <= BlaiMaxInputNumU32
  outResult.outputShiftValid = plan.outputShift <= 0
  outResult.activationRangeValid =
    plan.activationMin >= 0 and plan.activationMax <= 255 and
      plan.activationMin <= plan.activationMax
  outResult.inputsActive = true
  outResult.inputChannelsValid = true
  outResult.inputShiftsValid = true
  outResult.inputFits = true
  outResult.outputChannelsValid = true

  var inputChannels = 0'u64
  var maxInputNeed = 0'u64
  if outResult.validInputCount:
    for inputIndex in 0'u32 ..< plan.inputCount:
      let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
      if not inputCursor.valid:
        outResult.inputsActive = false
        outResult.firstBlockedInput = inputIndex
        break
      let inputPlan = plan.inputs[inputCursor.index]
      if not inputPlan.active:
        outResult.inputsActive = false
        outResult.firstBlockedInput = inputIndex
        break
      if inputPlan.channels == 0'u32:
        outResult.inputChannelsValid = false
        outResult.firstBlockedInput = inputIndex
        break
      if inputPlan.inputShift > 0:
        outResult.inputShiftsValid = false
        outResult.firstBlockedInput = inputIndex
        break
      let inputNeed = blaiReferenceRouteInputExtent(
        inputPlan.offset, plan.width, plan.height, inputPlan.channels)
      if inputNeed > maxInputNeed:
        maxInputNeed = inputNeed
      if inputNeed > inputLen.uint64:
        outResult.inputFits = false
        outResult.firstBlockedInput = inputIndex
        discard blaiU64ExactU32Count(
          inputNeed, outResult.firstBlockedInputElements)
        break
      inputChannels += inputPlan.channels.uint64
      if inputChannels > high(uint32).uint64:
        outResult.outputChannelsValid = false
        outResult.firstBlockedInput = inputIndex
        break

  discard blaiU64MaxExactU32Count(
    maxInputNeed, outResult.firstBlockedInputElements)
  if inputChannels != plan.outputC.uint64:
    outResult.outputChannelsValid = false
  let outputNeed =
    blaiReferenceHwcElementCount(plan.width, plan.height, plan.outputC)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.outputFits = outputNeed <= outputLen.uint64

  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteRouteInputShape
  elif not outResult.validInputCount:
    outResult.firstBlock = blaiTfliteRouteInputCount
  elif not outResult.outputShiftValid:
    outResult.firstBlock = blaiTfliteRouteOutputShift
  elif not outResult.activationRangeValid:
    outResult.firstBlock = blaiTfliteRouteActivationRange
  elif not outResult.inputsActive:
    outResult.firstBlock = blaiTfliteRouteInputInactive
  elif not outResult.inputChannelsValid:
    outResult.firstBlock = blaiTfliteRouteInputChannels
  elif not outResult.inputShiftsValid:
    outResult.firstBlock = blaiTfliteRouteInputShift
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteRouteInputBuffer
  elif not outResult.outputChannelsValid:
    outResult.firstBlock = blaiTfliteRouteOutputChannels
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteRouteOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteRouteNoBlock
    outResult.fits = true

proc blaiReferenceTfliteRoute2d*(plan: BlaiReferenceTfliteRoute2d,
                                 input: openArray[uint8],
                                 output: var openArray[uint8]): BlaiReferenceTfliteRouteResult =
  ## CPU fixture for SDK `forward_ROUTE_tflite` over HWC uint8 tensors.
  blaiReferenceTfliteRouteReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  const leftShift = 20'i32
  var minusC = 0'u32
  var currentInputIndex = 0'u32
  var accumulateC = plan.inputs[0].channels
  for outC in 0'u32 ..< plan.outputC:
    if outC >= accumulateC:
      minusC = accumulateC
      inc currentInputIndex
      let currentInputCursor = blaiReferenceRouteInputCursor(currentInputIndex)
      if not currentInputCursor.valid:
        return
      accumulateC += plan.inputs[currentInputCursor.index].channels
    let currentInputCursor = blaiReferenceRouteInputCursor(currentInputIndex)
    if not currentInputCursor.valid:
      return
    let inputPlan = plan.inputs[currentInputCursor.index]
    let localC = outC - minusC
    for y in 0'u32 ..< plan.height:
      for x in 0'u32 ..< plan.width:
        let inputHwc =
          blaiHwcIndex(y, x, plan.width, localC, inputPlan.channels)
        var inputIndex: uint32
        if not blaiHwcIndexWithBase(inputPlan.offset, inputHwc, inputIndex):
          return
        var sample = input[inputIndex.int].int32 - inputPlan.inputOffset
        let shifted = blaiClampI32(sample.int64 * (1'i64 shl leftShift))
        let scaledInput = blaiTfliteMultiplyByQuantizedMultiplierSmallerThanOneExp(
          shifted, inputPlan.inputMultiplier, inputPlan.inputShift)
        sample = blaiTfliteMultiplyByQuantizedMultiplierSmallerThanOneExp(
          scaledInput, plan.outputMultiplier, plan.outputShift)
        sample = blaiClampI32(sample.int64 + plan.outputOffset.int64)
        sample = min(max(sample, plan.activationMin), plan.activationMax)
        let outputHwc = blaiHwcIndex(y, x, plan.width, outC, plan.outputC)
        if not outputHwc.valid:
          return
        let outputIndex = outputHwc.index
        output[outputIndex.int] = sample.uint8

proc blaiReferenceTfliteRouteMaxReadinessInto*(
    plan: BlaiReferenceTfliteRouteMax2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteRouteMaxResult)

proc blaiReferenceTfliteRouteMaxFits*(plan: BlaiReferenceTfliteRouteMax2d,
                                      inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteRouteMaxResult
  blaiReferenceTfliteRouteMaxReadinessInto(
    plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteRouteMaxReadinessInto*(
    plan: BlaiReferenceTfliteRouteMax2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteRouteMaxResult) =
  outResult = BlaiReferenceTfliteRouteMaxResult()
  outResult.outputW = plan.outputW
  outResult.outputH = plan.outputH
  outResult.outputC = plan.outputC
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and plan.outputC != 0'u32
  outResult.validStride = plan.stride != 0'u32
  outResult.validInputCount =
    plan.inputCount != 0'u32 and plan.inputCount <= BlaiMaxInputNumU32
  outResult.outputShiftValid = plan.outputShift <= 0
  outResult.activationRangeValid =
    plan.activationMin >= 0 and plan.activationMax <= 255 and
      plan.activationMin <= plan.activationMax
  outResult.inputsActive = true
  outResult.inputChannelsValid = true
  outResult.inputShiftsValid = true
  outResult.inputFits = true
  outResult.outputChannelsValid = true

  if plan.outputW != 0'u32 and plan.outputH != 0'u32 and
      outResult.validInputShape:
    let maxOutputY = (plan.height - 1'u32) div 2'u32
    let maxOutputX = (plan.width - 1'u32) div 2'u32
    outResult.validOutputShape =
      maxOutputY < plan.outputH and maxOutputX < plan.outputW

  var inputChannels = 0'u64
  var maxInputNeed = 0'u64
  if outResult.validInputCount:
    for inputIndex in 0'u32 ..< plan.inputCount:
      let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
      if not inputCursor.valid:
        outResult.inputsActive = false
        outResult.firstBlockedInput = inputIndex
        break
      let inputPlan = plan.inputs[inputCursor.index]
      if not inputPlan.active:
        outResult.inputsActive = false
        outResult.firstBlockedInput = inputIndex
        break
      if inputPlan.channels == 0'u32:
        outResult.inputChannelsValid = false
        outResult.firstBlockedInput = inputIndex
        break
      if inputPlan.inputShift > 0:
        outResult.inputShiftsValid = false
        outResult.firstBlockedInput = inputIndex
        break
      let inputNeed = blaiReferenceRouteInputExtent(
        inputPlan.offset, plan.width, plan.height, inputPlan.channels)
      if inputNeed > maxInputNeed:
        maxInputNeed = inputNeed
      if inputNeed > inputLen.uint64:
        outResult.inputFits = false
        outResult.firstBlockedInput = inputIndex
        discard blaiU64ExactU32Count(
          inputNeed, outResult.firstBlockedInputElements)
        break
      inputChannels += inputPlan.channels.uint64
      if inputChannels > high(uint32).uint64:
        outResult.outputChannelsValid = false
        outResult.firstBlockedInput = inputIndex
        break

  discard blaiU64MaxExactU32Count(
    maxInputNeed, outResult.firstBlockedInputElements)
  if inputChannels != plan.outputC.uint64:
    outResult.outputChannelsValid = false
  let outputNeed =
    blaiReferenceHwcElementCount(plan.outputW, plan.outputH, plan.outputC)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.outputFits = outputNeed <= outputLen.uint64

  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteRouteMaxInputShape
  elif not outResult.validOutputShape:
    outResult.firstBlock = blaiTfliteRouteMaxOutputShape
  elif not outResult.validStride:
    outResult.firstBlock = blaiTfliteRouteMaxStride
  elif not outResult.validInputCount:
    outResult.firstBlock = blaiTfliteRouteMaxInputCount
  elif not outResult.outputShiftValid:
    outResult.firstBlock = blaiTfliteRouteMaxOutputShift
  elif not outResult.activationRangeValid:
    outResult.firstBlock = blaiTfliteRouteMaxActivationRange
  elif not outResult.inputsActive:
    outResult.firstBlock = blaiTfliteRouteMaxInputInactive
  elif not outResult.inputChannelsValid:
    outResult.firstBlock = blaiTfliteRouteMaxInputChannels
  elif not outResult.inputShiftsValid:
    outResult.firstBlock = blaiTfliteRouteMaxInputShift
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteRouteMaxInputBuffer
  elif not outResult.outputChannelsValid:
    outResult.firstBlock = blaiTfliteRouteMaxOutputChannels
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteRouteMaxOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteRouteMaxNoBlock
    outResult.fits = true

proc blaiReferenceTfliteRouteMax2d*(
    plan: BlaiReferenceTfliteRouteMax2d,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteRouteMaxResult =
  ## CPU fixture for SDK `forward_ROUTE_MAX_tflite` over HWC uint8 tensors.
  blaiReferenceTfliteRouteMaxReadinessInto(
    plan, input.len, output.len, result)
  if not result.fits:
    return

  const leftShift = 20'i32
  var minusC = 0'u32
  var currentInputIndex = 0'u32
  var accumulateC = plan.inputs[0].channels
  for outC in 0'u32 ..< plan.outputC:
    if outC >= accumulateC:
      minusC = accumulateC
      inc currentInputIndex
      let currentInputCursor = blaiReferenceRouteInputCursor(currentInputIndex)
      if not currentInputCursor.valid:
        return
      accumulateC += plan.inputs[currentInputCursor.index].channels
    let currentInputCursor = blaiReferenceRouteInputCursor(currentInputIndex)
    if not currentInputCursor.valid:
      return
    let inputPlan = plan.inputs[currentInputCursor.index]
    let localC = outC - minusC
    for y in 0'u32 ..< plan.height:
      for x in 0'u32 ..< plan.width:
        let inputHwc =
          blaiHwcIndex(y, x, plan.width, localC, inputPlan.channels)
        var inputIndex: uint32
        if not blaiHwcIndexWithBase(inputPlan.offset, inputHwc, inputIndex):
          return
        var sample = input[inputIndex.int].int32 - inputPlan.inputOffset
        let shifted = blaiClampI32(sample.int64 * (1'i64 shl leftShift))
        let scaledInput = blaiTfliteMultiplyByQuantizedMultiplierSmallerThanOneExp(
          shifted, inputPlan.inputMultiplier, inputPlan.inputShift)
        sample = blaiTfliteMultiplyByQuantizedMultiplierSmallerThanOneExp(
          scaledInput, plan.outputMultiplier, plan.outputShift)
        sample = blaiClampI32(sample.int64 + plan.outputOffset.int64)
        sample = min(max(sample, plan.activationMin), plan.activationMax)
        let outputHwc =
          blaiHwcIndex(y div 2'u32, x div 2'u32, plan.outputW, outC,
            plan.outputC)
        if not outputHwc.valid:
          return
        let outputIndex = outputHwc.index
        if ((y div plan.stride) mod 2'u32 == 0'u32) and
            ((x div plan.stride) mod 2'u32 == 0'u32):
          output[outputIndex.int] = sample.uint8
        else:
          let previous = output[outputIndex.int]
          if previous.int32 > sample:
            sample = previous.int32
          output[outputIndex.int] = sample.uint8

proc blaiReferenceTfliteRouteWEasyCopy*(plan: BlaiReferenceTfliteRouteW2d): bool =
  ## SDK `easy_route_w` predicate.
  if plan.inputCount == 0 or plan.axis != 0'u32 or plan.outputOffset == 0:
    return false
  let firstOffset = plan.inputs[0].inputOffset
  for inputIndex in 0'u32 ..< plan.inputCount:
    let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
    if not inputCursor.valid:
      return false
    let inputPlan = plan.inputs[inputCursor.index]
    if not inputPlan.active or inputPlan.inputOffset != firstOffset:
      return false
  true

proc blaiReferenceTfliteRouteWReadinessInto*(
    plan: BlaiReferenceTfliteRouteW2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteRouteWResult)

proc blaiReferenceTfliteRouteWFits*(plan: BlaiReferenceTfliteRouteW2d,
                                    inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteRouteWResult
  blaiReferenceTfliteRouteWReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteRouteWEasyCopyCursor*(
    outputBase, inputBase, relativeIndex, slice: uint32,
    inputLen, outputLen: int): BlaiReferenceTfliteRouteWEasyCopyCursor =
  ## Resolve one byte copy for the ROUTE_W fast path without raw index math.
  if relativeIndex >= slice:
    return
  var outputOffset: uint32
  var inputOffset: uint32
  var outputFit: BlaiUint32AppendFitResult
  var inputFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), outputBase, relativeIndex, outputFit)
  blaiUint32AppendFitInto(high(uint32), inputBase, relativeIndex, inputFit)
  if not outputFit.fits or not inputFit.fits:
    return
  outputOffset = outputFit.requiredCount
  inputOffset = inputFit.requiredCount
  let outputWindow = blaiCheckedByteWindow(outputLen, outputOffset, 1'u32)
  let inputWindow = blaiCheckedByteWindow(inputLen, inputOffset, 1'u32)
  if not outputWindow.fits or not inputWindow.fits:
    return
  result.outputBase = outputBase
  result.inputBase = inputBase
  result.relativeIndex = relativeIndex
  result.outputIndex = outputWindow.start
  result.inputIndex = inputWindow.start
  result.valid = true

proc blaiReferenceTfliteRouteWReadinessInto*(
    plan: BlaiReferenceTfliteRouteW2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteRouteWResult) =
  outResult = BlaiReferenceTfliteRouteWResult()
  outResult.outputW = plan.outputW
  outResult.outputH = plan.height
  outResult.outputC = plan.outputC
  outResult.easyCopy = blaiReferenceTfliteRouteWEasyCopy(plan)
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and
      plan.outputW != 0'u32 and plan.outputC != 0'u32
  outResult.validInputCount =
    plan.inputCount != 0'u32 and plan.inputCount <= BlaiMaxInputNumU32
  outResult.axisValid = plan.axis <= 1'u32
  outResult.outputShiftValid = plan.outputShift <= 0
  outResult.activationRangeValid =
    plan.activationMin >= 0 and plan.activationMax <= 255 and
      plan.activationMin <= plan.activationMax
  outResult.inputsActive = true
  outResult.inputChannelsValid = true
  outResult.inputShiftsValid = true
  outResult.inputFits = true

  var inputExtent = 0'u64
  var maxInputNeed = 0'u64
  if outResult.validInputCount:
    for inputIndex in 0'u32 ..< plan.inputCount:
      let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
      if not inputCursor.valid:
        outResult.inputsActive = false
        outResult.firstBlockedInput = inputIndex
        break
      let inputPlan = plan.inputs[inputCursor.index]
      if not inputPlan.active:
        outResult.inputsActive = false
        outResult.firstBlockedInput = inputIndex
        break
      if inputPlan.channels == 0'u32:
        outResult.inputChannelsValid = false
        outResult.firstBlockedInput = inputIndex
        break
      if not outResult.easyCopy and inputPlan.inputShift > 0:
        outResult.inputShiftsValid = false
        outResult.firstBlockedInput = inputIndex
        break
      let inputNeed =
        if outResult.axisValid:
          blaiReferenceTfliteRouteWSegmentExtent(
            inputPlan.offset, plan.axis, plan.height, plan.outputW,
            plan.outputC, inputPlan.channels)
        else:
          inputPlan.offset.uint64
      if inputNeed > maxInputNeed:
        maxInputNeed = inputNeed
      if inputNeed > inputLen.uint64:
        outResult.inputFits = false
        outResult.firstBlockedInput = inputIndex
        discard blaiU64ExactU32Count(
          inputNeed, outResult.firstBlockedInputElements)
        break
      inputExtent += inputPlan.channels.uint64
      if inputExtent > high(uint32).uint64:
        break

  discard blaiU64MaxExactU32Count(
    maxInputNeed, outResult.firstBlockedInputElements)
  discard blaiU64ExactU32Count(inputExtent, outResult.inputExtent)

  outResult.outputExtentValid =
    (plan.axis == 0'u32 and inputExtent == plan.width.uint64) or
    (plan.axis == 1'u32 and inputExtent == plan.height.uint64)
  let outputNeed =
    blaiReferenceHwcElementCount(plan.outputW, plan.height, plan.outputC)
  discard blaiU64ExactU32Count(outputNeed, outResult.requiredOutputElements)
  outResult.outputFits = outputNeed <= outputLen.uint64

  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteRouteWInputShape
  elif not outResult.validInputCount:
    outResult.firstBlock = blaiTfliteRouteWInputCount
  elif not outResult.axisValid:
    outResult.firstBlock = blaiTfliteRouteWAxis
  elif not outResult.outputShiftValid:
    outResult.firstBlock = blaiTfliteRouteWOutputShift
  elif not outResult.activationRangeValid:
    outResult.firstBlock = blaiTfliteRouteWActivationRange
  elif not outResult.inputsActive:
    outResult.firstBlock = blaiTfliteRouteWInputInactive
  elif not outResult.inputChannelsValid:
    outResult.firstBlock = blaiTfliteRouteWInputChannels
  elif not outResult.inputShiftsValid:
    outResult.firstBlock = blaiTfliteRouteWInputShift
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteRouteWInputBuffer
  elif not outResult.outputExtentValid:
    outResult.firstBlock = blaiTfliteRouteWOutputExtent
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteRouteWOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteRouteWNoBlock
    outResult.fits = true

proc blaiReferenceTfliteRouteW2d*(
    plan: BlaiReferenceTfliteRouteW2d,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteRouteWResult =
  ## CPU fixture for SDK `forward_ROUTE_W_tflite` over HWC uint8 tensors.
  blaiReferenceTfliteRouteWReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  const leftShift = 20'i32
  if result.easyCopy:
    var outputCursor = 0'u32
    for y in 0'u32 ..< plan.height:
      for inputIndex in 0'u32 ..< plan.inputCount:
        let inputCursor = blaiReferenceRouteInputCursor(inputIndex)
        if not inputCursor.valid:
          return
        let inputPlan = plan.inputs[inputCursor.index]
        let slice = inputPlan.channels * plan.outputC
        let inputBaseWide = inputPlan.offset.uint64 + y.uint64 * slice.uint64
        if inputBaseWide > high(uint32).uint64:
          return
        let inputBase = inputBaseWide.uint32
        for offset in 0'u32 ..< slice:
          let copyCursor = blaiReferenceTfliteRouteWEasyCopyCursor(
            outputCursor, inputBase, offset, slice, input.len, output.len)
          if not copyCursor.valid:
            return
          output[copyCursor.outputIndex] = input[copyCursor.inputIndex]
        var nextOutputCursor: BlaiUint32AppendFitResult
        blaiUint32AppendFitInto(
          high(uint32), outputCursor, slice, nextOutputCursor)
        if not nextOutputCursor.fits:
          return
        outputCursor = nextOutputCursor.requiredCount
    return

  var minusC = 0'u32
  var currentInputIndex = 0'u32
  var accumulateC = plan.inputs[0].channels
  for y in 0'u32 ..< plan.height:
    for x in 0'u32 ..< plan.width:
      for outC in 0'u32 ..< plan.outputC:
        let compare = if plan.axis == 0'u32: x else: y
        if compare >= accumulateC:
          minusC = accumulateC
          inc currentInputIndex
          let currentInputCursor = blaiReferenceRouteInputCursor(currentInputIndex)
          if not currentInputCursor.valid:
            return
          accumulateC += plan.inputs[currentInputCursor.index].channels
        let currentInputCursor = blaiReferenceRouteInputCursor(currentInputIndex)
        if not currentInputCursor.valid:
          return
        let inputPlan = plan.inputs[currentInputCursor.index]
        let inputHwc =
          if plan.axis == 0'u32:
            blaiHwcIndex(y, x - minusC, inputPlan.channels, outC, plan.outputC)
          else:
            blaiHwcIndex(y - minusC, x, plan.outputW, outC, plan.outputC)
        var inputIndex: uint32
        if not blaiHwcIndexWithBase(inputPlan.offset, inputHwc, inputIndex):
          return
        var sample = input[inputIndex.int].int32 - inputPlan.inputOffset
        let shifted = blaiClampI32(sample.int64 * (1'i64 shl leftShift))
        let scaledInput = blaiTfliteMultiplyByQuantizedMultiplierSmallerThanOneExp(
          shifted, inputPlan.inputMultiplier, inputPlan.inputShift)
        sample = blaiTfliteMultiplyByQuantizedMultiplierSmallerThanOneExp(
          scaledInput, plan.outputMultiplier, plan.outputShift)
        sample = blaiClampI32(sample.int64 + plan.outputOffset.int64)
        sample = min(max(sample, plan.activationMin), plan.activationMax)
        let outputHwc = blaiHwcIndex(y, x, plan.outputW, outC, plan.outputC)
        if not outputHwc.valid:
          return
        let outputIndex = outputHwc.index
        output[outputIndex.int] = sample.uint8

proc blaiReferenceTfliteReshapeOutputElements*(
    plan: BlaiReferenceTfliteReshape2d): uint32 =
  ## Highest output element written by SDK `forward_RESHAPE_tflite`, plus one.
  if plan.width == 0 or plan.height == 0 or plan.inputC == 0 or
      plan.outputC == 0 or plan.outputStrideC < plan.outputC:
    return 0
  let sampleCount =
    blaiReferenceHwcElementCount(plan.width, plan.height, plan.inputC)
  if sampleCount == 0:
    return 0
  let outputNeed =
    if plan.inputC == plan.inputStrideC and plan.outputC == plan.outputStrideC:
      sampleCount
    else:
      let lastSample = sampleCount - 1'u64
      lastSample + (lastSample div plan.outputC.uint64) *
        (plan.outputStrideC.uint64 - plan.outputC.uint64) + 1'u64
  if outputNeed > high(uint32).uint64:
    return 0
  outputNeed.uint32

proc blaiReferenceTfliteReshapeReadinessInto*(
    plan: BlaiReferenceTfliteReshape2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteReshapeResult)

proc blaiReferenceTfliteReshapeFits*(plan: BlaiReferenceTfliteReshape2d,
                                     inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteReshapeResult
  blaiReferenceTfliteReshapeReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteReshapeReadinessInto*(
    plan: BlaiReferenceTfliteReshape2d,
    inputLen, outputLen: int,
    outResult: var BlaiReferenceTfliteReshapeResult) =
  outResult = BlaiReferenceTfliteReshapeResult()
  outResult.fastCopy =
    plan.inputC == plan.inputStrideC and plan.outputC == plan.outputStrideC
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and
      plan.inputC != 0'u32 and plan.outputC != 0'u32
  outResult.validInputStride = plan.inputStrideC >= plan.inputC
  outResult.validOutputStride = plan.outputStrideC >= plan.outputC

  let pixels = blaiReferenceHwcElementCount(plan.width, plan.height, 1'u32)
  let sampleCount =
    blaiReferenceHwcElementCount(plan.width, plan.height, plan.inputC)
  var sampleCountElements: uint32
  outResult.sampleCountValid =
    pixels != 0'u64 and
      blaiU64ExactU32Count(sampleCount, sampleCountElements)
  var inputNeed = 0'u64
  if outResult.sampleCountValid:
    inputNeed =
      if outResult.fastCopy:
        sampleCount
      else:
        blaiReferenceHwcStrideExtent(
          plan.width, plan.height, plan.inputC, plan.inputStrideC)
    discard blaiU64ExactU32Count(inputNeed, outResult.inputElements)

  let outputNeed = blaiReferenceTfliteReshapeOutputElements(plan).uint64
  outResult.outputShapeValid = outputNeed != 0'u64
  if outResult.outputShapeValid:
    discard blaiU64ExactU32Count(outputNeed, outResult.outputElements)
  outResult.inputFits = inputNeed <= inputLen.uint64
  outResult.outputFits = outputNeed <= outputLen.uint64

  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteReshapeInputShape
  elif not outResult.validInputStride:
    outResult.firstBlock = blaiTfliteReshapeInputStride
  elif not outResult.validOutputStride:
    outResult.firstBlock = blaiTfliteReshapeOutputStride
  elif not outResult.sampleCountValid:
    outResult.firstBlock = blaiTfliteReshapeSampleCount
  elif not outResult.outputShapeValid:
    outResult.firstBlock = blaiTfliteReshapeOutputShape
  elif not outResult.inputFits:
    outResult.firstBlock = blaiTfliteReshapeInputBuffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteReshapeOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteReshapeNoBlock
    outResult.fits = true

proc blaiReferenceTfliteReshape2d*(
    plan: BlaiReferenceTfliteReshape2d,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteReshapeResult =
  ## CPU fixture for SDK `forward_RESHAPE_tflite` over HWC uint8 tensors.
  blaiReferenceTfliteReshapeReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  if result.fastCopy:
    for index in 0'u32 ..< result.outputElements:
      output[index.int] = input[index.int]
    return

  var sampleOrdinal = 0'u32
  for y in 0'u32 ..< plan.height:
    for x in 0'u32 ..< plan.width:
      for cin in 0'u32 ..< plan.inputC:
        let inputHwc =
          blaiHwcStrideIndex(y, x, plan.width, cin, plan.inputStrideC)
        let outputChannel = sampleOrdinal mod plan.outputC
        let outputGroup = sampleOrdinal div plan.outputC
        let outputHwc =
          blaiHwcStrideIndex(
            outputGroup, 0'u32, 1'u32, outputChannel, plan.outputStrideC)
        if not inputHwc.valid or not outputHwc.valid:
          return
        output[outputHwc.index.int] = input[inputHwc.index.int]
        inc sampleOrdinal

proc blaiReferenceRouteConcatFits*(plan: BlaiReferenceRouteConcat2d,
                                   inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceRouteConcatResult
  blaiReferenceRouteConcatReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceRouteConcat2d*(plan: BlaiReferenceRouteConcat2d,
                                 input: openArray[int8],
                                 output: var openArray[int8]): BlaiReferenceRouteConcatResult =
  ## CPU fixture for SDK `forward_ROUTE` over HWC int8 tensors.
  blaiReferenceRouteConcatReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  var minusC = 0'u32
  var currentInputIndex = 0'u32
  var accumulateC = plan.inputs[0].channels
  for outC in 0'u32 ..< result.outputC:
    if outC >= accumulateC:
      minusC = accumulateC
      inc currentInputIndex
      let currentInputCursor = blaiReferenceRouteInputCursor(currentInputIndex)
      if not currentInputCursor.valid:
        return
      accumulateC += plan.inputs[currentInputCursor.index].channels
    let currentInputCursor = blaiReferenceRouteInputCursor(currentInputIndex)
    if not currentInputCursor.valid:
      return
    let inputPlan = plan.inputs[currentInputCursor.index]
    let localC = outC - minusC
    let fshift = inputPlan.fractionalBits - plan.outputFractionalBits
    for y in 0'u32 ..< plan.height:
      for x in 0'u32 ..< plan.width:
        let inputHwc =
          blaiHwcIndex(y, x, plan.width, localC, inputPlan.channels)
        var inputIndex: uint32
        if not blaiHwcIndexWithBase(inputPlan.offset, inputHwc, inputIndex):
          return
        let outputHwc = blaiHwcIndex(y, x, plan.width, outC, result.outputC)
        if not outputHwc.valid:
          return
        let outputIndex = outputHwc.index
        output[outputIndex.int] = blaiFixed8ToFixed8(input[inputIndex.int], fshift)

proc blaiReferenceRouteMaxFits*(plan: BlaiReferenceRouteMax2d,
                                inputLen, outputLen: int): bool =
  var readiness: BlaiReferenceRouteMaxResult
  blaiReferenceRouteMaxReadinessInto(plan, inputLen, outputLen, readiness)
  readiness.fits

proc blaiReferenceRouteMax2d*(plan: BlaiReferenceRouteMax2d,
                              input: openArray[int8],
                              output: var openArray[int8]): BlaiReferenceRouteMaxResult =
  ## CPU fixture for SDK `forward_ROUTE_MAX` over HWC int8 tensors.
  blaiReferenceRouteMaxReadinessInto(plan, input.len, output.len, result)
  if not result.fits:
    return

  var minusC = 0'u32
  var currentInputIndex = 0'u32
  var accumulateC = plan.inputs[0].channels
  for outC in 0'u32 ..< result.outputC:
    if outC >= accumulateC:
      minusC = accumulateC
      inc currentInputIndex
      let currentInputCursor = blaiReferenceRouteInputCursor(currentInputIndex)
      if not currentInputCursor.valid:
        return
      accumulateC += plan.inputs[currentInputCursor.index].channels
    let currentInputCursor = blaiReferenceRouteInputCursor(currentInputIndex)
    if not currentInputCursor.valid:
      return
    let inputPlan = plan.inputs[currentInputCursor.index]
    let localC = outC - minusC
    let fshift = inputPlan.fractionalBits - plan.outputFractionalBits
    for y in 0'u32 ..< plan.height:
      for x in 0'u32 ..< plan.width:
        let inputHwc =
          blaiHwcIndex(y, x, plan.width, localC, inputPlan.channels)
        var inputIndex: uint32
        if not blaiHwcIndexWithBase(inputPlan.offset, inputHwc, inputIndex):
          return
        var passData = blaiFixed8ToFixed8(input[inputIndex.int], fshift)
        let outputHwc =
          blaiHwcIndex(y div 2'u32, x div 2'u32, plan.outputW, outC,
            result.outputC)
        if not outputHwc.valid:
          return
        let outputIndex = outputHwc.index
        if ((y div plan.stride) mod 2'u32 == 0'u32) and
            ((x div plan.stride) mod 2'u32 == 0'u32):
          output[outputIndex.int] = passData
        else:
          let previous = output[outputIndex.int]
          if previous > passData:
            passData = previous
          output[outputIndex.int] = passData

proc blaiReferenceShortcutReadinessInto*(
    plan: BlaiReferenceShortcut2d,
    input1Len, input2Len, outputLen: int,
    outResult: var BlaiReferenceShortcutResult)

proc blaiReferenceShortcutFits*(plan: BlaiReferenceShortcut2d,
                                input1Len, input2Len, outputLen: int): bool =
  var readiness: BlaiReferenceShortcutResult
  blaiReferenceShortcutReadinessInto(
    plan, input1Len, input2Len, outputLen, readiness)
  readiness.fits

proc blaiReferenceShortcutReadinessInto*(
    plan: BlaiReferenceShortcut2d,
    input1Len, input2Len, outputLen: int,
    outResult: var BlaiReferenceShortcutResult) =
  outResult = BlaiReferenceShortcutResult()
  outResult.outputW = plan.width
  outResult.outputH = plan.height
  outResult.outputC = plan.channels
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and plan.channels != 0'u32
  let elements =
    blaiReferenceHwcElementCount(plan.width, plan.height, plan.channels)
  discard blaiU64ExactU32Count(elements, outResult.requiredElements)
  outResult.input1Fits = elements <= input1Len.uint64
  outResult.input2Fits = elements <= input2Len.uint64
  outResult.outputFits = elements <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiShortcutInputShape
  elif not outResult.input1Fits:
    outResult.firstBlock = blaiShortcutInput1Buffer
  elif not outResult.input2Fits:
    outResult.firstBlock = blaiShortcutInput2Buffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiShortcutOutputBuffer
  else:
    outResult.firstBlock = blaiShortcutNoBlock
    outResult.fits = true

proc blaiReferenceShortcut2d*(plan: BlaiReferenceShortcut2d,
                              input1, input2: openArray[int8],
                              output: var openArray[int8]): BlaiReferenceShortcutResult =
  ## CPU fixture for SDK `forward_SHORTCUT` over same-shape HWC int8 tensors.
  blaiReferenceShortcutReadinessInto(
    plan, input1.len, input2.len, output.len, result)
  if not result.fits:
    return

  let fdata = min(plan.froute1, plan.froute2)
  let fshift1 = plan.froute1 - fdata
  let fshift2 = plan.froute2 - fdata
  for y in 0'u32 ..< plan.height:
    for x in 0'u32 ..< plan.width:
      for channel in 0'u32 ..< plan.channels:
        let hwc = blaiHwcIndex(y, x, plan.width, channel, plan.channels)
        if not hwc.valid:
          return
        let index = hwc.index
        var acc = blaiFixed8ToFixed8(input1[index.int], fshift1).int32 +
          blaiFixed8ToFixed8(input2[index.int], fshift2).int32
        acc = blaiApplyReferenceActivation(acc, plan.activation, fdata)
        let alphaShift =
          if plan.activation == blaiActLeaky and acc < 0:
            9'i32
          else:
            0'i32
        output[index.int] = blaiFixed32ToFixed8(acc, fdata + alphaShift - plan.fout)

proc blaiReferenceTfliteShortcutReadinessInto*(
    plan: BlaiReferenceTfliteShortcut2d,
    input1Len, input2Len, outputLen: int,
    outResult: var BlaiReferenceTfliteShortcutResult)

proc blaiReferenceTfliteShortcutFits*(plan: BlaiReferenceTfliteShortcut2d,
                                      input1Len, input2Len, outputLen: int): bool =
  var readiness: BlaiReferenceTfliteShortcutResult
  blaiReferenceTfliteShortcutReadinessInto(
    plan, input1Len, input2Len, outputLen, readiness)
  readiness.fits

proc blaiReferenceTfliteShortcutReadinessInto*(
    plan: BlaiReferenceTfliteShortcut2d,
    input1Len, input2Len, outputLen: int,
    outResult: var BlaiReferenceTfliteShortcutResult) =
  outResult = BlaiReferenceTfliteShortcutResult()
  outResult.outputW = plan.width
  outResult.outputH = plan.height
  outResult.outputC = plan.channels
  outResult.validInputShape =
    plan.width != 0'u32 and plan.height != 0'u32 and plan.channels != 0'u32
  outResult.shiftsValid =
    plan.input1Shift <= 0 and plan.input2Shift <= 0 and plan.outputShift <= 0
  outResult.activationRangeValid =
    plan.activationMin >= 0 and plan.activationMax <= 255 and
      plan.activationMin <= plan.activationMax
  let elements =
    blaiReferenceHwcElementCount(plan.width, plan.height, plan.channels)
  discard blaiU64ExactU32Count(elements, outResult.requiredElements)
  outResult.input1Fits = elements <= input1Len.uint64
  outResult.input2Fits = elements <= input2Len.uint64
  outResult.outputFits = elements <= outputLen.uint64
  if not outResult.validInputShape:
    outResult.firstBlock = blaiTfliteShortcutInputShape
  elif not outResult.shiftsValid:
    outResult.firstBlock = blaiTfliteShortcutShift
  elif not outResult.activationRangeValid:
    outResult.firstBlock = blaiTfliteShortcutActivationRange
  elif not outResult.input1Fits:
    outResult.firstBlock = blaiTfliteShortcutInput1Buffer
  elif not outResult.input2Fits:
    outResult.firstBlock = blaiTfliteShortcutInput2Buffer
  elif not outResult.outputFits:
    outResult.firstBlock = blaiTfliteShortcutOutputBuffer
  else:
    outResult.firstBlock = blaiTfliteShortcutNoBlock
    outResult.fits = true

proc blaiReferenceTfliteShortcut2d*(
    plan: BlaiReferenceTfliteShortcut2d,
    input1, input2: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteShortcutResult =
  ## CPU fixture for SDK `forward_SHORTCUT_tflite` over same-shape HWC tensors.
  blaiReferenceTfliteShortcutReadinessInto(
    plan, input1.len, input2.len, output.len, result)
  if not result.fits:
    return

  const leftShift = 20'i32
  for y in 0'u32 ..< plan.height:
    for x in 0'u32 ..< plan.width:
      for channel in 0'u32 ..< plan.channels:
        let hwc = blaiHwcIndex(y, x, plan.width, channel, plan.channels)
        if not hwc.valid:
          return
        let index = hwc.index
        let data1 = input1[index.int].int32 - plan.input1Offset
        let data2 = input2[index.int].int32 - plan.input2Offset
        let shifted1 = blaiClampI32(data1.int64 * (1'i64 shl leftShift))
        let shifted2 = blaiClampI32(data2.int64 * (1'i64 shl leftShift))
        let scaled1 = blaiTfliteMultiplyByQuantizedMultiplierSmallerThanOneExp(
          shifted1, plan.input1Multiplier, plan.input1Shift)
        let scaled2 = blaiTfliteMultiplyByQuantizedMultiplierSmallerThanOneExp(
          shifted2, plan.input2Multiplier, plan.input2Shift)
        let rawSum = blaiClampI32(scaled1.int64 + scaled2.int64)
        var rawOutput = blaiTfliteMultiplyByQuantizedMultiplierSmallerThanOneExp(
          rawSum, plan.outputMultiplier, plan.outputShift)
        rawOutput = blaiClampI32(rawOutput.int64 + plan.outputOffset.int64)
        rawOutput = min(max(rawOutput, plan.activationMin), plan.activationMax)
        output[index.int] = rawOutput.uint8

proc blaiOutputCompareAddMismatches(count: var uint32, extra: int) =
  if extra <= 0:
    return
  let available = high(uint32) - count
  if extra.uint64 > available.uint64:
    count = high(uint32)
  else:
    count += extra.uint32

proc blaiCompareUint8OutputsInto*(expected, actual: openArray[uint8],
                                  outResult: var BlaiUint8OutputCompareResult) =
  ## Compare uint8 oracle output with an observed tensor without allocating.
  outResult = default(BlaiUint8OutputCompareResult)
  outResult.expectedElements = blaiOpenArrayLenU32(expected)
  outResult.actualElements = blaiOpenArrayLenU32(actual)
  outResult.lengthMatches = expected.len == actual.len
  outResult.firstMismatch = -1
  let compared = min(expected.len, actual.len)
  outResult.comparedElements = blaiBufferLenU32(compared)

  for index in 0 ..< compared:
    if expected[index] != actual[index]:
      if outResult.firstMismatch < 0:
        outResult.firstMismatch = blaiOutputMismatchIndexValue(index)
        outResult.expectedPresentAtFirstMismatch = true
        outResult.actualPresentAtFirstMismatch = true
        outResult.expectedAtFirstMismatch = expected[index]
        outResult.actualAtFirstMismatch = actual[index]
      blaiOutputCompareAddMismatches(outResult.mismatchCount, 1)

  let trailing =
    if expected.len > actual.len:
      expected.len - actual.len
    else:
      actual.len - expected.len
  outResult.trailingElements = blaiBufferLenU32(trailing)
  if trailing > 0:
    if outResult.firstMismatch < 0:
      outResult.firstMismatch = blaiOutputMismatchIndexValue(compared)
      outResult.expectedPresentAtFirstMismatch = compared < expected.len
      outResult.actualPresentAtFirstMismatch = compared < actual.len
      if outResult.expectedPresentAtFirstMismatch:
        outResult.expectedAtFirstMismatch = expected[compared]
      if outResult.actualPresentAtFirstMismatch:
        outResult.actualAtFirstMismatch = actual[compared]
    blaiOutputCompareAddMismatches(outResult.mismatchCount, trailing)

  outResult.matched = outResult.lengthMatches and outResult.mismatchCount == 0

proc blaiCompareUint8Outputs*(expected, actual: openArray[uint8]):
    BlaiUint8OutputCompareResult {.
      exportc: "blaiCompareUint8OutputsResult".} =
  ## Convenience wrapper for uint8 oracle/output comparison.
  blaiCompareUint8OutputsInto(expected, actual, result)

proc blaiProjectUint8OutputRawBytesInto*(
    expected: openArray[uint8],
    output: var openArray[uint8],
    outResult: var BlaiUint8OutputRawByteProjectionResult) =
  ## Project TFLite uint8 CPU-oracle output into raw NPU workspace bytes.
  outResult = default(BlaiUint8OutputRawByteProjectionResult)
  outResult.expectedElements = blaiOpenArrayLenU32(expected)
  outResult.outputElements = blaiOpenArrayLenU32(output)
  outResult.outputFits = output.len >= expected.len
  let copied = min(expected.len, output.len)
  outResult.copiedElements = blaiBufferLenU32(copied)
  for index in 0 ..< copied:
    output[index] = expected[index]
  if expected.len > output.len:
    outResult.trailingElements = blaiBufferLenU32(expected.len - output.len)
    outResult.firstBlock = blaiUint8OutputRawByteProjectionOutputTooShort
  else:
    outResult.firstBlock = blaiUint8OutputRawByteProjectionNoBlock
  outResult.projected =
    outResult.firstBlock == blaiUint8OutputRawByteProjectionNoBlock

proc blaiProjectUint8OutputRawBytes*(
    expected: openArray[uint8],
    output: var openArray[uint8]):
    BlaiUint8OutputRawByteProjectionResult =
  ## Convenience wrapper for TFLite uint8-to-raw-byte output projection.
  blaiProjectUint8OutputRawBytesInto(expected, output, result)

proc blaiInt8OutputRawByte*(value: int8): uint8 =
  ## Project a fixed int8 tensor element to its raw workspace byte.
  if value < 0:
    (value.int16 + 256).uint8
  else:
    value.uint8

proc blaiProjectInt8OutputRawBytesInto*(
    expected: openArray[int8],
    output: var openArray[uint8],
    outResult: var BlaiInt8OutputRawByteProjectionResult) =
  ## Project fixed int8 CPU-oracle output into raw NPU workspace bytes.
  outResult = default(BlaiInt8OutputRawByteProjectionResult)
  outResult.expectedElements = blaiOpenArrayLenU32(expected)
  outResult.outputElements = blaiOpenArrayLenU32(output)
  outResult.outputFits = output.len >= expected.len
  let converted = min(expected.len, output.len)
  outResult.convertedElements = blaiBufferLenU32(converted)
  for index in 0 ..< converted:
    output[index] = blaiInt8OutputRawByte(expected[index])
  if expected.len > output.len:
    outResult.trailingElements = blaiBufferLenU32(expected.len - output.len)
    outResult.firstBlock = blaiInt8OutputRawByteProjectionOutputTooShort
  else:
    outResult.firstBlock = blaiInt8OutputRawByteProjectionNoBlock
  outResult.projected =
    outResult.firstBlock == blaiInt8OutputRawByteProjectionNoBlock

proc blaiProjectInt8OutputRawBytes*(
    expected: openArray[int8],
    output: var openArray[uint8]):
    BlaiInt8OutputRawByteProjectionResult =
  ## Convenience wrapper for fixed int8-to-raw-byte output projection.
  blaiProjectInt8OutputRawBytesInto(expected, output, result)

proc blaiCompareInt8OutputRawBytesInto*(
    expected: openArray[int8],
    actual: openArray[uint8],
    projectedExpected: var openArray[uint8],
    outResult: var BlaiInt8OutputRawByteCompareResult) =
  ## Project fixed int8 oracle output to bytes and compare with NPU readback.
  outResult = default(BlaiInt8OutputRawByteCompareResult)
  blaiProjectInt8OutputRawBytesInto(
    expected, projectedExpected, outResult.projection)
  outResult.projected = outResult.projection.projected
  outResult.projectionExpectedElements =
    outResult.projection.expectedElements
  outResult.projectionOutputElements =
    outResult.projection.outputElements
  outResult.projectionTrailingElements =
    outResult.projection.trailingElements
  outResult.projectionFirstBlock = outResult.projection.firstBlock
  if not outResult.projected:
    outResult.firstBlock = blaiInt8OutputRawByteCompareProjection
    return
  blaiCompareUint8OutputsInto(projectedExpected, actual, outResult.compare)
  outResult.matched = outResult.compare.matched
  outResult.comparedElements = outResult.compare.comparedElements
  outResult.trailingElements = outResult.compare.trailingElements
  outResult.mismatchCount = outResult.compare.mismatchCount
  outResult.firstMismatch = outResult.compare.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    outResult.compare.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    outResult.compare.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch =
    outResult.compare.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch =
    outResult.compare.actualAtFirstMismatch
  if not outResult.matched:
    outResult.firstBlock = blaiInt8OutputRawByteCompareMismatch
  else:
    outResult.firstBlock = blaiInt8OutputRawByteCompareNoBlock
  outResult.valid =
    outResult.firstBlock == blaiInt8OutputRawByteCompareNoBlock

proc blaiCompareInt8OutputRawBytes*(
    expected: openArray[int8],
    actual: openArray[uint8],
    projectedExpected: var openArray[uint8]):
    BlaiInt8OutputRawByteCompareResult =
  ## Convenience wrapper for fixed int8 oracle vs raw NPU byte comparison.
  blaiCompareInt8OutputRawBytesInto(
    expected, actual, projectedExpected, result)

proc blaiValidateMnistTfliteSampleRawOutputInto*(
    sample: BlaiMnistTfliteSampleOracle,
    actual: openArray[uint8],
    projectedExpected: var openArray[uint8],
    outResult: var BlaiMnistTfliteSampleRawOutputValidation) =
  ## Compare raw NPU output bytes against the fetched MNIST sample oracle.
  ##
  ## This is the bridge the live generated MNIST path should use after output
  ## readback: the model oracle remains int8, while NPU workspace readback is a
  ## raw byte stream.
  outResult = default(BlaiMnistTfliteSampleRawOutputValidation)
  outResult.sampleValid = sample.valid
  outResult.outputTensor = sample.outputTensor
  outResult.expectedElements = blaiOpenArrayLenU32(sample.outputVector)
  outResult.observedElements = blaiOpenArrayLenU32(actual)
  outResult.topClass = sample.topClass
  outResult.topScoreRaw = blaiInt8OutputRawByte(sample.topScore)
  if not outResult.sampleValid:
    outResult.firstBlock = blaiMnistTfliteSampleRawOutputOracle
    return

  blaiCompareInt8OutputRawBytesInto(
    sample.outputVector, actual, projectedExpected, outResult.compare)
  outResult.projection = outResult.compare.projection
  outResult.projected = outResult.compare.projected
  outResult.matched = outResult.compare.matched
  outResult.mismatchCount = outResult.compare.mismatchCount
  outResult.firstMismatch = outResult.compare.firstMismatch
  outResult.expectedAtFirstMismatch =
    outResult.compare.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch =
    outResult.compare.actualAtFirstMismatch
  if not outResult.projected:
    outResult.firstBlock = blaiMnistTfliteSampleRawOutputProjection
  elif not outResult.matched:
    outResult.firstBlock = blaiMnistTfliteSampleRawOutputCompare
  else:
    outResult.firstBlock = blaiMnistTfliteSampleRawOutputNoBlock
  outResult.valid =
    outResult.firstBlock == blaiMnistTfliteSampleRawOutputNoBlock

proc blaiValidateMnistTfliteSampleRawOutput*(
    sample: BlaiMnistTfliteSampleOracle,
    actual: openArray[uint8],
    projectedExpected: var openArray[uint8]):
    BlaiMnistTfliteSampleRawOutputValidation =
  ## Convenience wrapper for MNIST sample raw-output validation.
  blaiValidateMnistTfliteSampleRawOutputInto(
    sample, actual, projectedExpected, result)

