proc blaiReferenceFixedLayer2d*(
    layer: BlaiCpuInstLayer64,
    input1, input2: openArray[int8],
    weights: openArray[int8],
    biases: openArray[int8],
    output: var openArray[int8]): BlaiReferenceFixedLayerResult =
  ## Dispatch one recovered fixed-point SDK CPU layer record to typed fixtures.
  ##
  ## This is a model-validation helper, not a blob-compatible pointer overlay:
  ## all tensor and parameter storage is supplied by the caller as bounded Nim
  ## slices, and unsupported layer kinds are reported without side effects.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = true
  let activation = blaiActivationFromSdk(layer.activation)
  case result.layerType
  of blaiConvolutional:
    let conv = blaiReferenceConv2d(
      BlaiReferenceConv2d(
        inputW: nonNegativeU32(layer.w),
        inputH: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        outputC: nonNegativeU32(layer.outC),
        kernelSize: nonNegativeU32(layer.size),
        stride: nonNegativeU32(layer.stride),
        dilation: nonNegativeU32(layer.dilation),
        groups: max(nonNegativeU32(layer.groups), 1'u32),
        fdata: layer.fdata,
        fweight: layer.fweight,
        fbias: layer.fbias,
        fout: layer.fout,
        activation: activation),
      input1, weights, biases, output)
    result.fits = conv.fits
    result.convBlock = conv.firstBlock
    if not conv.fits:
      result.firstBlock = blaiFixedLayerConv
    result.outputW = conv.outputW
    result.outputH = conv.outputH
    result.outputC = nonNegativeU32(layer.outC)
  of blaiConvMax:
    let convMax = blaiReferenceConvMax2d(
      BlaiReferenceConvMax2d(
        inputW: nonNegativeU32(layer.w),
        inputH: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        outputC: nonNegativeU32(layer.outC),
        outputW: nonNegativeU32(layer.outW),
        outputH: nonNegativeU32(layer.outH),
        kernelSize: nonNegativeU32(layer.size),
        stride: nonNegativeU32(layer.stride),
        dilation: nonNegativeU32(layer.dilation),
        groups: max(nonNegativeU32(layer.groups), 1'u32),
        fdata: layer.fdata,
        fweight: layer.fweight,
        fbias: layer.fbias,
        fout: layer.fout,
        activation: activation),
      input1, weights, biases, output)
    result.fits = convMax.fits
    result.convMaxBlock = convMax.firstBlock
    if not convMax.fits:
      result.firstBlock = blaiFixedLayerConvMax
    result.outputW = convMax.outputW
    result.outputH = convMax.outputH
    result.outputC = convMax.outputC
  of blaiMatmul:
    let matmul = blaiReferenceMatmul2d(
      BlaiReferenceMatmul2d(
        width: nonNegativeU32(layer.w),
        height: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        outputC: nonNegativeU32(layer.outC),
        fdata: layer.fdata,
        fweight: layer.fweight,
        fbias: layer.fbias,
        fout: layer.fout,
        activation: activation),
      input1, weights, biases, output)
    result.fits = matmul.fits
    result.matmulBlock = matmul.firstBlock
    if not matmul.fits:
      result.firstBlock = blaiFixedLayerMatmul
    result.outputW = matmul.outputW
    result.outputH = matmul.outputH
    result.outputC = matmul.outputC
  of blaiMaxpool:
    let maxPool = blaiReferenceFixedMaxPool2d(
      BlaiReferenceFixedMaxPool2d(
        inputW: nonNegativeU32(layer.w),
        inputH: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        kernelSize: nonNegativeU32(layer.size),
        stride: nonNegativeU32(layer.stride),
        dilation: nonNegativeU32(layer.dilation)),
      input1, output)
    result.fits = maxPool.fits
    result.maxPoolBlock = maxPool.firstBlock
    if not maxPool.fits:
      result.firstBlock = blaiFixedLayerMaxPool
    result.outputW = maxPool.outputW
    result.outputH = maxPool.outputH
    result.outputC = maxPool.outputC
  of blaiUpsample:
    let upsample = blaiReferenceUpsample2d(
      BlaiReferenceUpsample2d(
        inputW: nonNegativeU32(layer.w),
        inputH: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        stride: nonNegativeU32(layer.stride),
        outputW: nonNegativeU32(layer.outW),
        outputH: nonNegativeU32(layer.outH),
        outputC: nonNegativeU32(layer.outC),
        fdata: layer.fdata,
        fout: layer.fout),
      input1, output)
    result.fits = upsample.fits
    result.upsampleBlock = upsample.firstBlock
    if not upsample.fits:
      result.firstBlock = blaiFixedLayerUpsample
    result.outputW = upsample.outputW
    result.outputH = upsample.outputH
    result.outputC = upsample.outputC
  of blaiShortcut:
    let shortcut = blaiReferenceShortcut2d(
      BlaiReferenceShortcut2d(
        width: nonNegativeU32(layer.w),
        height: nonNegativeU32(layer.h),
        channels: nonNegativeU32(layer.c),
        froute1: layer.froute1,
        froute2: layer.froute2,
        fout: layer.fout,
        activation: activation),
      input1, input2, output)
    result.fits = shortcut.fits
    result.shortcutBlock = shortcut.firstBlock
    if not shortcut.fits:
      result.firstBlock = blaiFixedLayerShortcut
    result.outputW = shortcut.outputW
    result.outputH = shortcut.outputH
    result.outputC = shortcut.outputC
  else:
    result.supported = false
    result.firstBlock = blaiFixedLayerUnsupportedLayer

proc blaiReferenceFixedRouteLayer2d*(
    layer: BlaiCpuInstLayer64,
    storage: BlaiCpuExtraInputStorage,
    patchSize: uint32,
    input: openArray[int8],
    output: var openArray[int8]): BlaiReferenceFixedLayerResult =
  ## Dispatch a recovered fixed-point route-family CPU layer record.
  ##
  ## Route records are the first fixed-point model-validation path that needs
  ## typed sidecar storage for SDK pointer-backed input arrays. The caller owns
  ## the flat input buffer and the sidecar storage; this proc only projects the
  ## recovered layer record into existing route fixtures.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = true
  case result.layerType
  of blaiRoute:
    let route = blaiReferenceRouteConcat2d(
      blaiReferenceRouteConcatPlan(layer, storage, patchSize),
      input, output)
    result.fits = route.fits
    result.outputW = route.outputW
    result.outputH = route.outputH
    result.outputC = route.outputC
  of blaiRouteMax:
    let routeMax = blaiReferenceRouteMax2d(
      blaiReferenceRouteMaxPlan(layer, storage, patchSize),
      input, output)
    result.fits = routeMax.fits
    result.outputW = routeMax.outputW
    result.outputH = routeMax.outputH
    result.outputC = routeMax.outputC
  else:
    result.supported = false

proc blaiReferenceTfliteLayer2d*(
    layer: BlaiCpuInstLayer64,
    input1, input2: openArray[uint8],
    weights: openArray[uint8],
    biases: openArray[int32],
    output: var openArray[uint8]): BlaiReferenceTfliteLayerResult =
  ## Dispatch one recovered TFLite SDK CPU layer record to typed fixtures.
  ##
  ## Multi-input route records need typed sidecar storage, so they stay on the
  ## route-specific plan helpers. This direct dispatcher covers simple records
  ## whose tensors and parameters can be supplied as bounded Nim slices.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = true
  case result.layerType
  of blaiConvolutional:
    let conv = blaiReferenceTfliteScalarConv2d(
      BlaiReferenceTfliteScalarConv2d(
        inputW: nonNegativeU32(layer.w),
        inputH: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        outputC: nonNegativeU32(layer.outC),
        outputW: nonNegativeU32(layer.outW),
        outputH: nonNegativeU32(layer.outH),
        kernelSize: nonNegativeU32(layer.size),
        stride: nonNegativeU32(layer.stride),
        dilation: nonNegativeU32(layer.dilation),
        groups: max(nonNegativeU32(layer.groups), 1'u32),
        inputOffset: layer.tfInput1Offset,
        filterOffset: layer.tfInput2Offset,
        outputOffset: layer.tfOutputOffset,
        outputMultiplier: layer.tfOutputMultiplier,
        outputShift: layer.tfOutputShift,
        activationMin: layer.quantizedActivationMin,
        activationMax: layer.quantizedActivationMax,
        useBias: biases.len > 0),
      input1, weights, biases, output)
    result.fits = conv.fits
    result.convBlock = conv.firstBlock
    if not conv.fits:
      result.firstBlock = blaiTfliteLayerConv
    result.outputW = conv.outputW
    result.outputH = conv.outputH
    result.outputC = conv.outputC
  of blaiMatmul:
    let fullyConnected = blaiReferenceTfliteFullyConnected2d(
      BlaiReferenceTfliteFullyConnected2d(
        batchCount: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        outputC: nonNegativeU32(layer.outC),
        inputOffset: layer.tfInput1Offset,
        filterOffset: layer.tfInput2Offset,
        outputOffset: layer.tfOutputOffset,
        outputMultiplier: layer.tfOutputMultiplier,
        outputShift: layer.tfOutputShift,
        activationMin: layer.quantizedActivationMin,
        activationMax: layer.quantizedActivationMax,
        useBias: biases.len > 0),
      input1, weights, biases, output)
    result.fits = fullyConnected.fits
    result.fullyConnectedBlock = fullyConnected.firstBlock
    if not fullyConnected.fits:
      result.firstBlock = blaiTfliteLayerFullyConnected
    result.outputW = fullyConnected.outputW
    result.outputH = fullyConnected.outputH
    result.outputC = fullyConnected.outputC
  of blaiConvMax:
    let convMax = blaiReferenceTfliteScalarConvMax2d(
      BlaiReferenceTfliteScalarConvMax2d(
        inputW: nonNegativeU32(layer.w),
        inputH: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        outputC: nonNegativeU32(layer.outC),
        outputW: nonNegativeU32(layer.outW),
        outputH: nonNegativeU32(layer.outH),
        kernelSize: nonNegativeU32(layer.size),
        stride: nonNegativeU32(layer.stride),
        dilation: nonNegativeU32(layer.dilation),
        groups: max(nonNegativeU32(layer.groups), 1'u32),
        inputOffset: layer.tfInput1Offset,
        filterOffset: layer.tfInput2Offset,
        outputOffset: layer.tfOutputOffset,
        outputMultiplier: layer.tfOutputMultiplier,
        outputShift: layer.tfOutputShift,
        activationMin: layer.quantizedActivationMin,
        activationMax: layer.quantizedActivationMax,
        useBias: biases.len > 0),
      input1, weights, biases, output)
    result.fits = convMax.fits
    result.convMaxBlock = convMax.firstBlock
    if not convMax.fits:
      result.firstBlock = blaiTfliteLayerConvMax
    result.outputW = convMax.outputW
    result.outputH = convMax.outputH
    result.outputC = convMax.outputC
  of blaiMaxpool:
    let maxPool = blaiReferenceTfliteScalarMaxPool2d(
      BlaiReferenceTfliteScalarMaxPool2d(
        inputW: nonNegativeU32(layer.w),
        inputH: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        outputW: nonNegativeU32(layer.outW),
        outputH: nonNegativeU32(layer.outH),
        kernelSize: nonNegativeU32(layer.size),
        stride: nonNegativeU32(layer.stride),
        dilation: nonNegativeU32(layer.dilation),
        inputOffset: layer.tfInput1Offset,
        outputMultiplier: layer.tfOutputMultiplier,
        outputShift: layer.tfOutputShift,
        activationMin: layer.quantizedActivationMin,
        activationMax: layer.quantizedActivationMax),
      input1, output)
    result.fits = maxPool.fits
    result.maxPoolBlock = maxPool.firstBlock
    if not maxPool.fits:
      result.firstBlock = blaiTfliteLayerMaxPool
    result.outputW = maxPool.outputW
    result.outputH = maxPool.outputH
    result.outputC = maxPool.outputC
  of blaiAvgpool:
    let avgPool = blaiReferenceAvgPool2d(
      BlaiReferenceAvgPool2d(
        inputW: nonNegativeU32(layer.w),
        inputH: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        stride: nonNegativeU32(layer.stride),
        inputStrideC: nonNegativeU32(layer.c),
        outputStrideC: nonNegativeU32(layer.outC),
        activationMin: layer.quantizedActivationMin,
        activationMax: layer.quantizedActivationMax),
      input1, output)
    result.fits = avgPool.fits
    result.avgPoolBlock = avgPool.firstBlock
    if not avgPool.fits:
      result.firstBlock = blaiTfliteLayerAvgPool
    result.outputW = 1
    result.outputH = 1
    result.outputC = avgPool.outputC
  of blaiShortcut:
    let shortcut = blaiReferenceTfliteShortcut2d(
      BlaiReferenceTfliteShortcut2d(
        width: nonNegativeU32(layer.w),
        height: nonNegativeU32(layer.h),
        channels: nonNegativeU32(layer.c),
        input1Offset: layer.tfInput1Offset,
        input2Offset: layer.tfInput2Offset,
        outputOffset: layer.tfOutputOffset,
        input1Multiplier: layer.tfInput1Multiplier,
        input2Multiplier: layer.tfInput2Multiplier,
        outputMultiplier: layer.tfOutputMultiplier,
        input1Shift: layer.tfInput1Shift,
        input2Shift: layer.tfInput2Shift,
        outputShift: layer.tfOutputShift,
        activationMin: layer.quantizedActivationMin,
        activationMax: layer.quantizedActivationMax),
      input1, input2, output)
    result.fits = shortcut.fits
    result.shortcutBlock = shortcut.firstBlock
    if not shortcut.fits:
      result.firstBlock = blaiTfliteLayerShortcut
    result.outputW = shortcut.outputW
    result.outputH = shortcut.outputH
    result.outputC = shortcut.outputC
  else:
    result.supported = false
    result.firstBlock = blaiTfliteLayerUnsupportedLayer

proc blaiReferenceTfliteRouteLayer2d*(
    layer: BlaiCpuInstLayer64,
    storage: BlaiCpuExtraInputStorage,
    patchSize: uint32,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteLayerResult =
  ## Dispatch a recovered TFLite route-family CPU layer record.
  ##
  ## This keeps route-family model validation on typed sidecar storage instead
  ## of SDK pointer-backed arrays, while reusing the recovered route fixtures.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = true
  case result.layerType
  of blaiRoute:
    let route = blaiReferenceTfliteRoute2d(
      blaiReferenceTfliteRoutePlan(layer, storage, patchSize),
      input, output)
    result.fits = route.fits
    result.routeBlock = route.firstBlock
    if not route.fits:
      result.firstBlock = blaiTfliteLayerRoute
    result.outputW = route.outputW
    result.outputH = route.outputH
    result.outputC = route.outputC
  of blaiRouteMax:
    let routeMax = blaiReferenceTfliteRouteMax2d(
      blaiReferenceTfliteRouteMaxPlan(layer, storage, patchSize),
      input, output)
    result.fits = routeMax.fits
    result.routeMaxBlock = routeMax.firstBlock
    if not routeMax.fits:
      result.firstBlock = blaiTfliteLayerRouteMax
    result.outputW = routeMax.outputW
    result.outputH = routeMax.outputH
    result.outputC = routeMax.outputC
  of blaiRouteW:
    let routeW = blaiReferenceTfliteRouteW2d(
      blaiReferenceTfliteRouteWPlan(layer, storage, patchSize),
      input, output)
    result.fits = routeW.fits
    result.routeWBlock = routeW.firstBlock
    if not routeW.fits:
      result.firstBlock = blaiTfliteLayerRouteW
    result.outputW = routeW.outputW
    result.outputH = routeW.outputH
    result.outputC = routeW.outputC
  else:
    result.supported = false
    result.firstBlock = blaiTfliteLayerUnsupportedLayer

proc blaiReferenceTfliteTransposeLayer2d*(
    layer: BlaiCpuInstLayer64,
    mask: BlaiCpuTfliteTransposeMask,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteLayerResult =
  ## Dispatch a recovered TFLite transpose CPU layer record.
  ##
  ## The SDK stores the transpose mask behind a pointer field. This pure-Nim
  ## dispatcher accepts typed sidecar storage instead of dereferencing it.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  if result.layerType != blaiTranspose or not mask.active:
    result.firstBlock = blaiTfliteLayerUnsupportedLayer
    return
  result.supported = true
  let transpose = blaiReferenceTfliteTranspose2d(
    blaiReferenceTfliteTransposePlan(layer, mask),
    input, output)
  result.fits = transpose.fits
  result.transposeBlock = transpose.firstBlock
  if not transpose.fits:
    result.firstBlock = blaiTfliteLayerTranspose
  result.outputW = transpose.outputW
  result.outputH = transpose.outputH
  result.outputC = transpose.outputC

proc blaiReferenceTfliteTransposeLkLayer1d*(
    layer: BlaiCpuInstLayer64,
    input: openArray[uint8],
    output: var openArray[uint8],
    rollingV2 = false): BlaiReferenceTfliteLayerResult =
  ## Dispatch a recovered TFLite transpose-kernel CPU layer record.
  ##
  ## `rollingV2` selects the recovered `forward_TRANSPOSELK_V2_tflite` symbol;
  ## the default path selects the direct `forward_TRANSPOSELK_tflite` symbol.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  if result.layerType != blaiTransposeLk:
    result.firstBlock = blaiTfliteLayerUnsupportedLayer
    return
  result.supported = true
  let plan = blaiReferenceTfliteTransposeLkPlan(layer)
  let transpose =
    if rollingV2:
      blaiReferenceTfliteTransposeLkV2_1d(plan, input, output)
    else:
      blaiReferenceTfliteTransposeLk1d(plan, input, output)
  result.fits = transpose.fits
  result.transposeLkBlock = transpose.firstBlock
  if not transpose.fits:
    result.firstBlock = blaiTfliteLayerTransposeLk
  result.outputW = plan.channels
  result.outputH = transpose.windowCount
  result.outputC = transpose.alignedKernelSize

proc blaiReferenceTfliteDequantizeLayer2d*(
    layer: BlaiCpuInstLayer64,
    input: openArray[uint8],
    output: var openArray[float32]): BlaiReferenceTfliteFloatLayerResult =
  ## Dispatch a recovered TFLite dequantize CPU layer record.
  ##
  ## This is separate from uint8 layer dispatchers because the SDK writes
  ## `float32` output for `forward_DEQUANTIZE_tflite`.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  if result.layerType != blaiDequantize:
    result.firstBlock = blaiTfliteFloatLayerUnsupportedLayer
    return
  result.supported = true
  let dequantize = blaiReferenceTfliteDequantize2d(
    BlaiReferenceTfliteDequantize2d(
      width: nonNegativeU32(layer.w),
      height: nonNegativeU32(layer.h),
      channels: nonNegativeU32(layer.c),
      inputOffset: layer.tfInput1Offset,
      inputScale: layer.inputScale),
    input, output)
  result.fits = dequantize.fits
  result.dequantizeBlock = dequantize.firstBlock
  if not dequantize.fits:
    result.firstBlock = blaiTfliteFloatLayerDequantize
  result.outputW = dequantize.outputW
  result.outputH = dequantize.outputH
  result.outputC = dequantize.outputC

proc blaiReferenceTfliteTransformLayer2d*(
    layer: BlaiCpuInstLayer64,
    input: openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteLayerResult =
  ## Dispatch a recovered TFLite uint8 transform CPU layer record.
  ##
  ## This covers transform layers whose SDK records fully describe their uint8
  ## tensor movement or scalar math. Float-output dequantize remains a separate
  ## fixture because its output element type differs.
  result.layerType = blaiLayerTypeFromSdk(layer.layerType)
  result.supported = true
  case result.layerType
  of blaiMean:
    let mean = blaiReferenceTfliteMean2d(
      BlaiReferenceTfliteMean2d(
        inputW: nonNegativeU32(layer.w),
        inputH: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        inputStrideC: nonNegativeU32(layer.c),
        inputOffset: layer.tfInput1Offset,
        outputOffset: layer.tfOutputOffset,
        outputMultiplier: layer.tfOutputMultiplier,
        outputShift: layer.tfOutputShift),
      input, output)
    result.fits = mean.fits
    result.meanBlock = mean.firstBlock
    if not mean.fits:
      result.firstBlock = blaiTfliteLayerMean
    result.outputW = 1
    result.outputH = 1
    result.outputC = mean.outputC
  of blaiSoftmax:
    let softmax = blaiReferenceTfliteSoftmax2d(
      BlaiReferenceTfliteSoftmax2d(
        width: nonNegativeU32(layer.w),
        height: nonNegativeU32(layer.h),
        channels: nonNegativeU32(layer.c),
        inputStrideC: nonNegativeU32(layer.c),
        outputStrideC: nonNegativeU32(layer.outC)),
      input, output)
    result.fits = softmax.fits
    result.softmaxBlock = softmax.firstBlock
    if not softmax.fits:
      result.firstBlock = blaiTfliteLayerSoftmax
    result.outputW = softmax.outputW
    result.outputH = softmax.outputH
    result.outputC = softmax.outputC
  of blaiLogisticLayer:
    let logistic = blaiReferenceTfliteLogistic2d(
      BlaiReferenceTfliteLogistic2d(
        width: nonNegativeU32(layer.w),
        height: nonNegativeU32(layer.h),
        channels: nonNegativeU32(layer.c),
        inputOffset: layer.tfInput1Offset,
        inputScale: layer.inputScale,
        outputOffset: layer.tfOutputOffset,
        outputScale: layer.outputScale),
      input, output)
    result.fits = logistic.fits
    result.logisticBlock = logistic.firstBlock
    if not logistic.fits:
      result.firstBlock = blaiTfliteLayerLogistic
    result.outputW = logistic.outputW
    result.outputH = logistic.outputH
    result.outputC = logistic.outputC
  of blaiPad:
    let
      inputW = nonNegativeU32(layer.w)
      inputH = nonNegativeU32(layer.h)
      outputW = nonNegativeU32(layer.outW)
      outputH = nonNegativeU32(layer.outH)
      leftW = nonNegativeU32(layer.paddingX)
      leftH = nonNegativeU32(layer.paddingY)
      rightW =
        if outputW >= inputW + leftW: outputW - inputW - leftW else: 0'u32
      rightH =
        if outputH >= inputH + leftH: outputH - inputH - leftH else: 0'u32
    let pad = blaiReferenceTflitePad2d(
      BlaiReferenceTflitePad2d(
        inputW: inputW,
        inputH: inputH,
        inputC: nonNegativeU32(layer.c),
        leftPadW: leftW,
        rightPadW: rightW,
        leftPadH: leftH,
        rightPadH: rightH,
        paddingValue: (layer.tfOutputOffset and 0xFF'i32).uint8),
      input, output)
    result.fits = pad.fits
    result.padBlock = pad.firstBlock
    if not pad.fits:
      result.firstBlock = blaiTfliteLayerPad
    result.outputW = pad.outputW
    result.outputH = pad.outputH
    result.outputC = pad.outputC
    result.supported = pad.supported
  of blaiReshape:
    let reshape = blaiReferenceTfliteReshape2d(
      BlaiReferenceTfliteReshape2d(
        width: nonNegativeU32(layer.w),
        height: nonNegativeU32(layer.h),
        inputC: nonNegativeU32(layer.c),
        outputC: nonNegativeU32(layer.outC),
        inputStrideC: nonNegativeU32(layer.c),
        outputStrideC: nonNegativeU32(layer.outC)),
      input, output)
    result.fits = reshape.fits
    result.reshapeBlock = reshape.firstBlock
    if not reshape.fits:
      result.firstBlock = blaiTfliteLayerReshape
    result.outputW = nonNegativeU32(layer.outW)
    result.outputH = nonNegativeU32(layer.outH)
    result.outputC = nonNegativeU32(layer.outC)
  of blaiPreTransconv:
    let pre = blaiReferenceTflitePreTransconv2d(
      BlaiReferenceTflitePreTransconv2d(
        inputW: nonNegativeU32(layer.w),
        inputH: nonNegativeU32(layer.h),
        channels: nonNegativeU32(layer.c),
        outputW: nonNegativeU32(layer.outW),
        outputH: nonNegativeU32(layer.outH),
        inputOffset: layer.tfInput1Offset),
      input, output)
    result.fits = pre.fits
    result.preTransconvBlock = pre.firstBlock
    if not pre.fits:
      result.firstBlock = blaiTfliteLayerPreTransconv
    result.outputW = pre.outputW
    result.outputH = pre.outputH
    result.outputC = pre.outputC
  else:
    result.supported = false
    result.firstBlock = blaiTfliteLayerUnsupportedLayer

proc blaiStoreFixedCpuBiasesInto*(plan: BlaiCpuBiasStreamPlan,
                                  bytes: openArray[uint8],
                                  startIndex: Natural,
                                  biases: var openArray[int8],
                                  outResult: var BlaiFixedCpuBiasStoreResult) =
  ## Store one SDK fixed-point CPU bias stream segment into an int8 buffer.
  outResult = default(BlaiFixedCpuBiasStoreResult)
  outResult.active = plan.active
  outResult.storageMatches = true
  if not plan.active:
    outResult.fits = true
    outResult.stored = true
    return
  if plan.bytesPerElement != 1'u32:
    outResult.storageMatches = false
    return
  let window = blaiCpuBiasStreamWindow(
    plan, bytes, startIndex, blaiOpenArrayLenU32(biases))
  outResult.fits = window.fits
  if not outResult.fits:
    return
  for i in 0 ..< window.elements:
    biases[i] =
      blaiCpuWeightI8Value(blaiCpuStreamOpenArray(bytes, window)[i])
  outResult.stored = true

proc blaiStoreFixedCpuBiases*(plan: BlaiCpuBiasStreamPlan,
                              bytes: openArray[uint8],
                              startIndex: Natural,
                              biases: var openArray[int8]): bool =
  ## Compatibility wrapper for caller-owned fixed-point bias store results.
  var store: BlaiFixedCpuBiasStoreResult
  blaiStoreFixedCpuBiasesInto(plan, bytes, startIndex, biases, store)
  store.stored

proc blaiReferenceFixedParsedSingleLayerReadinessInto*(
    layer: BlaiReferenceFixedParsedSingleLayerResult,
    outResult: var BlaiReferenceFixedParsedSingleLayerReadiness) =
  ## Explain whether one fixed parsed single-layer oracle executed successfully.
  outResult = default(BlaiReferenceFixedParsedSingleLayerReadiness)
  outResult.active = layer.active
  outResult.fixedMode = not layer.useTflite
  outResult.streamLayerMatches = layer.streamLayerMatches
  outResult.streamsFit = layer.streamsFit
  outResult.weightStorageSupported = layer.weightStorageSupported
  outResult.supported = layer.supported
  outResult.tensorFits = layer.fits
  outResult.referenceFirstBlock = layer.referenceFirstBlock
  outResult.executed = outResult.active and outResult.fixedMode and
    outResult.streamLayerMatches and outResult.streamsFit and
    outResult.weightStorageSupported and outResult.supported and
    outResult.tensorFits

proc blaiReferenceFixedParsedSingleLayerReadiness*(
    layer: BlaiReferenceFixedParsedSingleLayerResult):
    BlaiReferenceFixedParsedSingleLayerReadiness =
  ## Convenience wrapper for fixed parsed single-layer readiness.
  blaiReferenceFixedParsedSingleLayerReadinessInto(layer, result)

proc blaiCaptureFixedParsedSingleLayerReference(
    result: var BlaiReferenceFixedParsedSingleLayerResult) =
  result.referenceFirstBlock = result.reference.firstBlock
  result.referenceConvBlock = result.reference.convBlock
  result.referenceConvMaxBlock = result.reference.convMaxBlock
  result.referenceMatmulBlock = result.reference.matmulBlock
  result.referenceMaxPoolBlock = result.reference.maxPoolBlock
  result.referenceUpsampleBlock = result.reference.upsampleBlock
  result.referenceShortcutBlock = result.reference.shortcutBlock

proc blaiCaptureFixedParsedLayerReference(
    result: var BlaiReferenceFixedParsedLayerResult) =
  result.referenceFirstBlock = result.reference.firstBlock
  result.referenceConvBlock = result.reference.convBlock
  result.referenceConvMaxBlock = result.reference.convMaxBlock
  result.referenceMatmulBlock = result.reference.matmulBlock
  result.referenceMaxPoolBlock = result.reference.maxPoolBlock
  result.referenceUpsampleBlock = result.reference.upsampleBlock
  result.referenceShortcutBlock = result.reference.shortcutBlock

proc blaiReferenceFixedParsedDecodedWindow*(
    elementCount: uint32,
    capacity: int): BlaiReferenceFixedParsedDecodedWindow =
  ## Resolve a non-empty decoded fixed weight/bias vector for layer dispatch.
  let countCursor = blaiU32CountCursor(elementCount, capacity)
  if not countCursor.valid or countCursor.count <= 0:
    return
  let lastCursor = blaiU32ArrayIndexCursor(elementCount - 1'u32, capacity)
  if not lastCursor.valid:
    return
  result.elementCount = elementCount
  result.count = countCursor.count
  result.startIndex = 0
  result.stopIndex = lastCursor.index
  result.valid = true

proc blaiReferenceFixedParsedSingleLayer2d*(
    layer: BlaiCpuInstLayer64,
    extraInputs: BlaiCpuExtraInputStorage,
    layerIndex: uint32,
    active: bool,
    useTflite: bool,
    input1, input2: openArray[int8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor, biasCursor: BlaiCpuStreamCursor,
    decodedWeights: var openArray[int8],
    decodedBiases: var openArray[int8],
    output: var openArray[int8]): BlaiReferenceFixedParsedSingleLayerResult =
  ## Execute one known parsed fixed-point CPU-reference layer with bounded streams.
  ##
  ## This is the same parsed-layer boundary as `blaiReferenceFixedParsedLayer2d`
  ## without requiring a caller-owned array of full parsed layer states. It is
  ## useful for small firmware validation paths where stack budget matters.
  result.nextWeightCursor = weightCursor
  result.nextBiasCursor = biasCursor
  result.useTflite = useTflite
  result.weightStorageSupported = true
  if not active:
    blaiReferenceFixedParsedSingleLayerReadinessInto(result, result.readiness)
    return
  result.active = true
  if useTflite:
    blaiReferenceFixedParsedSingleLayerReadinessInto(result, result.readiness)
    return

  let layerType = blaiLayerTypeFromSdk(layer.layerType)
  let layerIndexValue = blaiLayerIndexValue(layerIndex)
  var emptyWeights: array[0, int8]
  var emptyBiases: array[0, int8]
  var hasWeights = false
  var hasBiases = false
  var weightPlan: BlaiCpuWeightStreamPlan
  var biasPlan: BlaiCpuBiasStreamPlan
  let cpuWeightByteCount = blaiOpenArrayLenU32(cpuWeightBytes)
  let cpuBiasByteCount = blaiOpenArrayLenU32(cpuBiasBytes)

  result.streamLayerMatches = true
  result.streamsFit = true
  if blaiCpuLoadUsesWeights(layer):
    hasWeights = true
    weightPlan.active = true
    weightPlan.layerIndex = layerIndexValue
    weightPlan.elementCount = blaiCpuWeightElementCount(layer)
    weightPlan.streamBytes = weightPlan.elementCount
    weightPlan.storage = blaiCpuWeightStorage(layer)
    result.streamLayerMatches =
      result.streamLayerMatches and weightCursor.layerIndex <= layerIndexValue
    result.streamsFit = result.streamsFit and
      weightCursor.byteOffset <= cpuWeightByteCount and
      cpuWeightByteCount - weightCursor.byteOffset >= weightPlan.streamBytes
    result.weightStorageSupported = weightPlan.storage == blaiCpuWeightI8
    result.nextWeightCursor.layerIndex = blaiLayerIndexValue(layerIndex + 1'u32)
    result.nextWeightCursor.byteOffset =
      weightCursor.byteOffset + weightPlan.streamBytes
    if result.weightStorageSupported:
      var weightStore: BlaiCpuWeightStoreResult
      let streamStart = blaiCpuStreamStartCursor(weightCursor)
      if streamStart.valid:
        blaiStoreCpuWeightsI8Into(
          weightPlan, cpuWeightBytes, streamStart.startIndex,
          decodedWeights, weightStore)
      else:
        result.streamsFit = false
      result.streamsFit = result.streamsFit and weightStore.stored
  if blaiCpuLoadUsesBiases(layer):
    hasBiases = true
    biasPlan.active = true
    biasPlan.layerIndex = layerIndexValue
    biasPlan.elementCount = blaiCpuBiasElementCount(layer)
    biasPlan.bytesPerElement = blaiCpuBiasBytesPerElement(useTflite)
    biasPlan.streamBytes = biasPlan.elementCount * biasPlan.bytesPerElement
    result.streamLayerMatches =
      result.streamLayerMatches and biasCursor.layerIndex <= layerIndexValue
    result.streamsFit = result.streamsFit and
      biasCursor.byteOffset <= cpuBiasByteCount and
      cpuBiasByteCount - biasCursor.byteOffset >= biasPlan.streamBytes
    result.nextBiasCursor.layerIndex = blaiLayerIndexValue(layerIndex + 1'u32)
    result.nextBiasCursor.byteOffset = biasCursor.byteOffset + biasPlan.streamBytes
    var biasStore: BlaiFixedCpuBiasStoreResult
    let streamStart = blaiCpuStreamStartCursor(biasCursor)
    if streamStart.valid:
      blaiStoreFixedCpuBiasesInto(
        biasPlan, cpuBiasBytes, streamStart.startIndex,
        decodedBiases, biasStore)
    else:
      result.streamsFit = false
    result.streamsFit = result.streamsFit and biasStore.stored

  if not (result.streamLayerMatches and result.streamsFit and
      result.weightStorageSupported):
    blaiReferenceFixedParsedSingleLayerReadinessInto(result, result.readiness)
    return

  case layerType
  of blaiRoute, blaiRouteMax:
    result.reference = blaiReferenceFixedRouteLayer2d(
      layer, extraInputs, nonNegativeU32(layer.dramPatchSize), input1, output)
  else:
    let weightBytesPresent = hasWeights and weightPlan.elementCount > 0'u32
    let biasElementsPresent = hasBiases and biasPlan.elementCount > 0'u32
    if weightBytesPresent and biasElementsPresent:
      let weightWindow = blaiReferenceFixedParsedDecodedWindow(
        weightPlan.elementCount, decodedWeights.len)
      let biasWindow = blaiReferenceFixedParsedDecodedWindow(
        biasPlan.elementCount, decodedBiases.len)
      if not weightWindow.valid or not biasWindow.valid:
        result.streamsFit = false
        blaiReferenceFixedParsedSingleLayerReadinessInto(result, result.readiness)
        return
      result.reference = blaiReferenceFixedLayer2d(
        layer, input1, input2,
        decodedWeights.toOpenArray(weightWindow.startIndex, weightWindow.stopIndex),
        decodedBiases.toOpenArray(biasWindow.startIndex, biasWindow.stopIndex),
        output)
    elif weightBytesPresent:
      let weightWindow = blaiReferenceFixedParsedDecodedWindow(
        weightPlan.elementCount, decodedWeights.len)
      if not weightWindow.valid:
        result.streamsFit = false
        blaiReferenceFixedParsedSingleLayerReadinessInto(result, result.readiness)
        return
      result.reference = blaiReferenceFixedLayer2d(
        layer, input1, input2,
        decodedWeights.toOpenArray(weightWindow.startIndex, weightWindow.stopIndex),
        emptyBiases, output)
    elif biasElementsPresent:
      let biasWindow = blaiReferenceFixedParsedDecodedWindow(
        biasPlan.elementCount, decodedBiases.len)
      if not biasWindow.valid:
        result.streamsFit = false
        blaiReferenceFixedParsedSingleLayerReadinessInto(result, result.readiness)
        return
      result.reference = blaiReferenceFixedLayer2d(
        layer, input1, input2, emptyWeights,
        decodedBiases.toOpenArray(biasWindow.startIndex, biasWindow.stopIndex),
        output)
    else:
      result.reference = blaiReferenceFixedLayer2d(
        layer, input1, input2, emptyWeights, emptyBiases, output)

  result.supported = result.reference.supported
  result.fits = result.reference.fits
  blaiCaptureFixedParsedSingleLayerReference(result)
  blaiReferenceFixedParsedSingleLayerReadinessInto(result, result.readiness)

proc blaiReferenceFixedParsedLayer2d*(
    layers: openArray[BlaiCpuParsedLayerState],
    layerIndex: uint32,
    useTflite: bool,
    input1, input2: openArray[int8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor, biasCursor: BlaiCpuStreamCursor,
    decodedWeights: var openArray[int8],
    decodedBiases: var openArray[int8],
    output: var openArray[int8]): BlaiReferenceFixedParsedLayerResult =
  ## Execute one parsed-state fixed-point CPU-reference layer from bounded streams.
  result.nextWeightCursor = weightCursor
  result.nextBiasCursor = biasCursor
  result.useTflite = useTflite
  result.weightStorageSupported = true
  let layerCursor = blaiRecoveredLayerCursor(layerIndex, layers.len)
  if not layerCursor.valid:
    return
  let parsed = layers[layerCursor.index]
  if not parsed.active:
    return
  result.active = true
  if useTflite:
    return

  let layer = parsed.layer
  let layerType = blaiLayerTypeFromSdk(layer.layerType)
  let layerIndexValue = blaiLayerIndexValue(layerIndex)
  var emptyWeights: array[0, int8]
  var emptyBiases: array[0, int8]
  var hasWeights = false
  var hasBiases = false

  result.streamLayerMatches = true
  result.streamsFit = true
  if blaiCpuLoadUsesWeights(layer):
    blaiCpuWeightStreamSegmentInto(
      layers, weightCursor, blaiOpenArrayLenU32(cpuWeightBytes), result.weightStream)
    hasWeights = result.weightStream.active
    result.streamLayerMatches = result.streamLayerMatches and
      result.weightStream.active and
      result.weightStream.plan.layerIndex == layerIndexValue
    result.streamsFit = result.streamsFit and result.weightStream.fits
    result.weightStorageSupported =
      result.weightStream.active and
      result.weightStream.plan.storage == blaiCpuWeightI8
    if result.weightStream.active:
      result.nextWeightCursor = result.weightStream.nextCursor
      if result.weightStorageSupported:
        var weightStore: BlaiCpuWeightStoreResult
        let streamStart = blaiCpuStreamStartCursor(result.weightStream.cursor)
        if streamStart.valid:
          blaiStoreCpuWeightsI8Into(
            result.weightStream.plan, cpuWeightBytes,
            streamStart.startIndex, decodedWeights, weightStore)
        else:
          result.streamsFit = false
        result.streamsFit = result.streamsFit and weightStore.stored
  if blaiCpuLoadUsesBiases(layer):
    blaiCpuBiasStreamSegmentInto(
      layers, biasCursor, blaiOpenArrayLenU32(cpuBiasBytes), useTflite,
      result.biasStream)
    hasBiases = result.biasStream.active
    result.streamLayerMatches = result.streamLayerMatches and
      result.biasStream.active and
      result.biasStream.plan.layerIndex == layerIndexValue
    result.streamsFit = result.streamsFit and result.biasStream.fits
    if result.biasStream.active:
      result.nextBiasCursor = result.biasStream.nextCursor
      var biasStore: BlaiFixedCpuBiasStoreResult
      let streamStart = blaiCpuStreamStartCursor(result.biasStream.cursor)
      if streamStart.valid:
        blaiStoreFixedCpuBiasesInto(
          result.biasStream.plan, cpuBiasBytes,
          streamStart.startIndex, decodedBiases, biasStore)
      else:
        result.streamsFit = false
      result.streamsFit = result.streamsFit and biasStore.stored

  if not (result.streamLayerMatches and result.streamsFit and
      result.weightStorageSupported):
    return

  case layerType
  of blaiRoute, blaiRouteMax:
    result.reference = blaiReferenceFixedRouteLayer2d(
      layer, parsed.extraInputs, nonNegativeU32(layer.dramPatchSize),
      input1, output)
    result.supported = result.reference.supported
    result.fits = result.reference.fits
    blaiCaptureFixedParsedLayerReference(result)
    return
  else:
    discard

  let weightBytesPresent = hasWeights and
    result.weightStream.plan.elementCount > 0'u32
  let biasElementsPresent = hasBiases and
    result.biasStream.plan.elementCount > 0'u32
  if weightBytesPresent and biasElementsPresent:
    let weightWindow = blaiReferenceFixedParsedDecodedWindow(
      result.weightStream.plan.elementCount, decodedWeights.len)
    let biasWindow = blaiReferenceFixedParsedDecodedWindow(
      result.biasStream.plan.elementCount, decodedBiases.len)
    if not weightWindow.valid or not biasWindow.valid:
      result.streamsFit = false
      return
    result.reference = blaiReferenceFixedLayer2d(
      layer, input1, input2,
      decodedWeights.toOpenArray(weightWindow.startIndex, weightWindow.stopIndex),
      decodedBiases.toOpenArray(biasWindow.startIndex, biasWindow.stopIndex),
      output)
  elif weightBytesPresent:
    let weightWindow = blaiReferenceFixedParsedDecodedWindow(
      result.weightStream.plan.elementCount, decodedWeights.len)
    if not weightWindow.valid:
      result.streamsFit = false
      return
    result.reference = blaiReferenceFixedLayer2d(
      layer, input1, input2,
      decodedWeights.toOpenArray(weightWindow.startIndex, weightWindow.stopIndex),
      emptyBiases, output)
  elif biasElementsPresent:
    let biasWindow = blaiReferenceFixedParsedDecodedWindow(
      result.biasStream.plan.elementCount, decodedBiases.len)
    if not biasWindow.valid:
      result.streamsFit = false
      return
    result.reference = blaiReferenceFixedLayer2d(
      layer, input1, input2, emptyWeights,
      decodedBiases.toOpenArray(biasWindow.startIndex, biasWindow.stopIndex),
      output)
  else:
    result.reference = blaiReferenceFixedLayer2d(
      layer, input1, input2, emptyWeights, emptyBiases, output)

  result.supported = result.reference.supported
  result.fits = result.reference.fits
  blaiCaptureFixedParsedLayerReference(result)

proc blaiLastActiveParsedLayerIndex(
    layers: openArray[BlaiCpuParsedLayerState]): int32

proc blaiParsedFixedModelFailure(
    layer: BlaiReferenceFixedParsedLayerResult):
    BlaiReferenceFixedParsedModelFailure =
  if not layer.streamLayerMatches:
    return blaiRefFixedModelStreamLayerMismatch
  if not layer.streamsFit:
    return blaiRefFixedModelStreamDataUnavailable
  if not layer.weightStorageSupported:
    return blaiRefFixedModelUnsupportedWeightStorage
  if not layer.supported:
    return blaiRefFixedModelUnsupportedLayer
  if not layer.fits:
    return blaiRefFixedModelTensorDoesNotFit
  blaiRefFixedModelNoFailure

proc blaiReferenceFixedParsedModelValidityInto*(
    runnable: bool,
    allCompleted: bool,
    allWeightsConsumed: bool,
    allBiasesConsumed: bool,
    outResult: var BlaiReferenceFixedParsedModelValidity) =
  ## Compute strict fixed parsed-model fixture validity from terminal state.
  outResult = default(BlaiReferenceFixedParsedModelValidity)
  outResult.runnable = runnable
  outResult.allCompleted = allCompleted
  outResult.allWeightsConsumed = allWeightsConsumed
  outResult.allBiasesConsumed = allBiasesConsumed
  outResult.modelValid = runnable and allCompleted and
    allWeightsConsumed and allBiasesConsumed
  if not allWeightsConsumed:
    outResult.modelFailure = blaiRefFixedModelTrailingWeightStream
  elif not allBiasesConsumed:
    outResult.modelFailure = blaiRefFixedModelTrailingBiasStream
  else:
    outResult.modelFailure = blaiRefFixedModelNoFailure

proc blaiReferenceFixedParsedModelValidity*(
    runnable: bool,
    allCompleted: bool,
    allWeightsConsumed: bool,
    allBiasesConsumed: bool): BlaiReferenceFixedParsedModelValidity =
  ## Convenience wrapper for strict fixed parsed-model fixture validity.
  blaiReferenceFixedParsedModelValidityInto(
    runnable, allCompleted, allWeightsConsumed, allBiasesConsumed, result)

proc blaiReferenceFixedParsedModel2d*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    input: openArray[int8],
    layerInputs: openArray[BlaiReferenceFixedParsedModelInput],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int8],
    decodedBiases: var openArray[int8],
    scratchA, scratchB: var openArray[int8],
    output: var openArray[int8]): BlaiReferenceFixedParsedModelResult =
  ## Execute a simple linear parsed-state fixed-point reference model.
  result.useTflite = useTflite
  result.layerCount = blaiOpenArrayLenU32(layers)
  result.firstFailedLayer = -1
  result.lastCompletedLayer = -1
  result.weightStreamBytes = blaiOpenArrayLenU32(cpuWeightBytes)
  result.biasStreamBytes = blaiOpenArrayLenU32(cpuBiasBytes)
  result.nextWeightCursor = blaiCpuStreamCursor()
  result.nextBiasCursor = blaiCpuStreamCursor()
  if useTflite:
    result.firstFailure = blaiRefFixedModelTfliteInput
    result.modelFailure = blaiRefFixedModelTfliteInput
    result.validity.modelFailure = blaiRefFixedModelTfliteInput
    return
  result.runnable = true
  let lastActive = blaiLastActiveParsedLayerIndex(layers)
  if lastActive < 0:
    result.allWeightsConsumed = result.weightStreamBytes == 0'u32
    result.allBiasesConsumed = result.biasStreamBytes == 0'u32
    result.allCompleted = true
    blaiReferenceFixedParsedModelValidityInto(
      result.runnable, result.allCompleted, result.allWeightsConsumed,
      result.allBiasesConsumed, result.validity)
    result.modelValid = result.validity.modelValid
    result.modelFailure = result.validity.modelFailure
    return

  var previousScratch = -1
  var hasPreviousOutput = false
  for layerIndex in 0 ..< layers.len:
    let layerCursor = blaiRecoveredLayerCursor(layerIndex.uint32, layers.len)
    if not layerCursor.valid:
      inc result.skippedLayerCount
      continue
    let layerState = layers[layerCursor.index]
    if not layerState.active:
      inc result.skippedLayerCount
      continue

    inc result.attemptedLayerCount
    let referenceLayerIndex = blaiLayerCursorIndexAbi(layerCursor.index)
    if not referenceLayerIndex.valid:
      inc result.failedLayerCount
      if result.firstFailedLayer < 0:
        result.firstFailedLayer = blaiLayerIndexValue(layerCursor.index)
        result.firstFailure = blaiRefFixedModelUnsupportedLayer
        result.modelFailure = result.firstFailure
        result.validity.modelFailure = result.firstFailure
      return
    let writeFinal = blaiLayerIndexValue(layerCursor.index) == lastActive
    var layerResult: BlaiReferenceFixedParsedLayerResult
    let secondSource =
      if layerCursor.index < layerInputs.len:
        layerInputs[layerCursor.index].secondInput
      else:
        blaiRefFixedInputEmpty
    if secondSource == blaiRefFixedInputPrevious and not hasPreviousOutput:
      inc result.failedLayerCount
      if result.firstFailedLayer < 0:
        result.firstFailedLayer = blaiLayerIndexValue(layerCursor.index)
        result.firstFailure = blaiRefFixedModelSecondInputUnavailable
        result.modelFailure = result.firstFailure
        result.validity.modelFailure = result.firstFailure
      return

    template runLayer(inputOne, outputBuf: untyped) =
      case secondSource
      of blaiRefFixedInputModel:
        layerResult = blaiReferenceFixedParsedLayer2d(
          layers, referenceLayerIndex.value, useTflite, input1 = inputOne,
          input2 = input, cpuWeightBytes = cpuWeightBytes,
          cpuBiasBytes = cpuBiasBytes, weightCursor = result.nextWeightCursor,
          biasCursor = result.nextBiasCursor, decodedWeights = decodedWeights,
          decodedBiases = decodedBiases, output = outputBuf)
      of blaiRefFixedInputPrevious:
        if hasPreviousOutput and previousScratch == 0:
          layerResult = blaiReferenceFixedParsedLayer2d(
            layers, referenceLayerIndex.value, useTflite, input1 = inputOne,
            input2 = scratchA, cpuWeightBytes = cpuWeightBytes,
            cpuBiasBytes = cpuBiasBytes, weightCursor = result.nextWeightCursor,
            biasCursor = result.nextBiasCursor, decodedWeights = decodedWeights,
            decodedBiases = decodedBiases, output = outputBuf)
        elif hasPreviousOutput and previousScratch == 1:
          layerResult = blaiReferenceFixedParsedLayer2d(
            layers, referenceLayerIndex.value, useTflite, input1 = inputOne,
            input2 = scratchB, cpuWeightBytes = cpuWeightBytes,
            cpuBiasBytes = cpuBiasBytes, weightCursor = result.nextWeightCursor,
            biasCursor = result.nextBiasCursor, decodedWeights = decodedWeights,
            decodedBiases = decodedBiases, output = outputBuf)
      of blaiRefFixedInputEmpty:
        layerResult = blaiReferenceFixedParsedLayer2d(
          layers, referenceLayerIndex.value, useTflite, input1 = inputOne,
          input2 = [], cpuWeightBytes = cpuWeightBytes,
          cpuBiasBytes = cpuBiasBytes, weightCursor = result.nextWeightCursor,
          biasCursor = result.nextBiasCursor, decodedWeights = decodedWeights,
          decodedBiases = decodedBiases, output = outputBuf)

    if not hasPreviousOutput:
      if writeFinal:
        runLayer(input, output)
      else:
        runLayer(input, scratchA)
        previousScratch = 0
    elif previousScratch == 0:
      if writeFinal:
        runLayer(scratchA, output)
      else:
        runLayer(scratchA, scratchB)
        previousScratch = 1
    else:
      if writeFinal:
        runLayer(scratchB, output)
      else:
        runLayer(scratchB, scratchA)
        previousScratch = 0

    result.lastLayer = layerResult
    if layerResult.supported and layerResult.fits:
      inc result.completedLayerCount
      result.lastCompletedLayer = blaiLayerIndexValue(layerCursor.index)
      result.nextWeightCursor = layerResult.nextWeightCursor
      result.nextBiasCursor = layerResult.nextBiasCursor
      hasPreviousOutput = true
    else:
      inc result.failedLayerCount
      if result.firstFailedLayer < 0:
        result.firstFailedLayer = blaiLayerIndexValue(layerCursor.index)
        result.firstFailure = blaiParsedFixedModelFailure(layerResult)
        result.modelFailure = result.firstFailure
        result.validity.modelFailure = result.firstFailure
        result.firstFailedLayerResultCaptured = true
        result.firstFailedLayerResult = layerResult
      return

  result.allWeightsConsumed =
    result.nextWeightCursor.byteOffset == result.weightStreamBytes
  result.allBiasesConsumed =
    result.nextBiasCursor.byteOffset == result.biasStreamBytes
  result.allCompleted = result.failedLayerCount == 0
  blaiReferenceFixedParsedModelValidityInto(
    result.runnable, result.allCompleted, result.allWeightsConsumed,
    result.allBiasesConsumed, result.validity)
  result.modelValid = result.validity.modelValid
  if result.validity.modelFailure != blaiRefFixedModelNoFailure:
    result.modelFailure = result.validity.modelFailure

proc blaiReferenceFixedParsedModel2d*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    input: openArray[int8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int8],
    decodedBiases: var openArray[int8],
    scratchA, scratchB: var openArray[int8],
    output: var openArray[int8]): BlaiReferenceFixedParsedModelResult =
  ## Execute a simple linear parsed-state fixed-point reference model.
  var emptyInputs: array[0, BlaiReferenceFixedParsedModelInput]
  blaiReferenceFixedParsedModel2d(
    layers, useTflite, input, emptyInputs, cpuWeightBytes, cpuBiasBytes,
    decodedWeights, decodedBiases, scratchA, scratchB, output)

proc blaiReferenceTfliteParsedSingleLayerReadinessInto*(
    layer: BlaiReferenceTfliteParsedSingleLayerResult,
    outResult: var BlaiReferenceTfliteParsedSingleLayerReadiness) =
  ## Explain whether one TFLite parsed single-layer oracle executed successfully.
  outResult = default(BlaiReferenceTfliteParsedSingleLayerReadiness)
  outResult.active = layer.active
  outResult.tfliteMode = layer.useTflite
  outResult.streamLayerMatches = layer.streamLayerMatches
  outResult.streamsFit = layer.streamsFit
  outResult.supported = layer.supported
  outResult.tensorFits = layer.fits
  outResult.referenceFirstBlock = layer.referenceFirstBlock
  outResult.executed = outResult.active and outResult.tfliteMode and
    outResult.streamLayerMatches and outResult.streamsFit and
    outResult.supported and outResult.tensorFits

proc blaiReferenceTfliteParsedSingleLayerReadiness*(
    layer: BlaiReferenceTfliteParsedSingleLayerResult):
    BlaiReferenceTfliteParsedSingleLayerReadiness =
  ## Convenience wrapper for TFLite parsed single-layer readiness.
  blaiReferenceTfliteParsedSingleLayerReadinessInto(layer, result)

proc blaiCaptureTfliteParsedSingleLayerReference(
    result: var BlaiReferenceTfliteParsedSingleLayerResult) =
  result.referenceFirstBlock = result.reference.firstBlock
  result.referenceConvBlock = result.reference.convBlock
  result.referenceConvMaxBlock = result.reference.convMaxBlock
  result.referenceMaxPoolBlock = result.reference.maxPoolBlock
  result.referenceAvgPoolBlock = result.reference.avgPoolBlock
  result.referenceShortcutBlock = result.reference.shortcutBlock
  result.referenceRouteBlock = result.reference.routeBlock
  result.referenceRouteMaxBlock = result.reference.routeMaxBlock
  result.referenceRouteWBlock = result.reference.routeWBlock
  result.referenceMeanBlock = result.reference.meanBlock
  result.referenceSoftmaxBlock = result.reference.softmaxBlock
  result.referenceLogisticBlock = result.reference.logisticBlock
  result.referencePadBlock = result.reference.padBlock
  result.referenceReshapeBlock = result.reference.reshapeBlock
  result.referencePreTransconvBlock = result.reference.preTransconvBlock

proc blaiCaptureTfliteParsedLayerReference(
    result: var BlaiReferenceTfliteParsedLayerResult) =
  result.referenceFirstBlock = result.reference.firstBlock
  result.referenceConvBlock = result.reference.convBlock
  result.referenceConvMaxBlock = result.reference.convMaxBlock
  result.referenceMaxPoolBlock = result.reference.maxPoolBlock
  result.referenceAvgPoolBlock = result.reference.avgPoolBlock
  result.referenceShortcutBlock = result.reference.shortcutBlock
  result.referenceRouteBlock = result.reference.routeBlock
  result.referenceRouteMaxBlock = result.reference.routeMaxBlock
  result.referenceRouteWBlock = result.reference.routeWBlock
  result.referenceMeanBlock = result.reference.meanBlock
  result.referenceSoftmaxBlock = result.reference.softmaxBlock
  result.referenceLogisticBlock = result.reference.logisticBlock
  result.referencePadBlock = result.reference.padBlock
  result.referenceReshapeBlock = result.reference.reshapeBlock
  result.referencePreTransconvBlock = result.reference.preTransconvBlock

proc blaiReferenceTfliteParsedWeightWindow*(
    startIndex: int,
    streamBytes: uint32,
    capacity: int): BlaiReferenceTfliteParsedWeightWindow =
  ## Resolve a non-empty parsed TFLite CPU weight byte stream for dispatch.
  var stopIndex: int
  if not blaiStartedOpenArrayStop(startIndex, streamBytes, capacity, stopIndex):
    return
  result.streamBytes = streamBytes
  result.startIndex = startIndex
  result.stopIndex = stopIndex
  result.valid = true

proc blaiReferenceTfliteParsedBiasWindow*(
    elementCount: uint32,
    capacity: int): BlaiReferenceTfliteParsedBiasWindow =
  ## Resolve a non-empty decoded TFLite int32 bias vector for dispatch.
  let countCursor = blaiU32CountCursor(elementCount, capacity)
  if not countCursor.valid or countCursor.count <= 0:
    return
  let lastCursor = blaiU32ArrayIndexCursor(elementCount - 1'u32, capacity)
  if not lastCursor.valid:
    return
  result.elementCount = elementCount
  result.count = countCursor.count
  result.startIndex = 0
  result.stopIndex = lastCursor.index
  result.valid = true

proc blaiReferenceTfliteParsedSingleLayer2d*(
    layer: BlaiCpuInstLayer64,
    extraInputs: BlaiCpuExtraInputStorage,
    layerIndex: uint32,
    active: bool,
    useTflite: bool,
    input1, input2: openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor, biasCursor: BlaiCpuStreamCursor,
    decodedBiases: var openArray[int32],
    output: var openArray[uint8]): BlaiReferenceTfliteParsedSingleLayerResult =
  ## Execute one known parsed TFLite CPU-reference layer with bounded streams.
  ##
  ## This mirrors `blaiReferenceTfliteParsedLayer2d` without requiring an array of
  ## full parsed layer states, which keeps small firmware validation paths within
  ## the M0 stack budget.
  result.nextWeightCursor = weightCursor
  result.nextBiasCursor = biasCursor
  result.useTflite = useTflite
  if not active:
    blaiReferenceTfliteParsedSingleLayerReadinessInto(result, result.readiness)
    return
  result.active = true
  if not useTflite:
    blaiReferenceTfliteParsedSingleLayerReadinessInto(result, result.readiness)
    return

  let layerType = blaiLayerTypeFromSdk(layer.layerType)
  let layerIndexValue = blaiLayerIndexValue(layerIndex)
  var emptyWeights: array[0, uint8]
  var emptyBiases: array[0, int32]
  var hasWeights = false
  var hasBiases = false
  var weightPlan: BlaiCpuWeightStreamPlan
  var biasPlan: BlaiCpuBiasStreamPlan
  let cpuWeightByteCount = blaiOpenArrayLenU32(cpuWeightBytes)
  let cpuBiasByteCount = blaiOpenArrayLenU32(cpuBiasBytes)

  result.streamLayerMatches = true
  result.streamsFit = true
  if blaiCpuLoadUsesWeights(layer):
    hasWeights = true
    weightPlan.active = true
    weightPlan.layerIndex = layerIndexValue
    weightPlan.elementCount = blaiCpuWeightElementCount(layer)
    weightPlan.streamBytes = weightPlan.elementCount
    weightPlan.storage = blaiCpuWeightStorage(layer)
    result.streamLayerMatches =
      result.streamLayerMatches and weightCursor.layerIndex <= layerIndexValue
    result.streamsFit = result.streamsFit and
      weightCursor.byteOffset <= cpuWeightByteCount and
      cpuWeightByteCount - weightCursor.byteOffset >= weightPlan.streamBytes
    result.nextWeightCursor.layerIndex = blaiLayerIndexValue(layerIndex + 1'u32)
    result.nextWeightCursor.byteOffset =
      weightCursor.byteOffset + weightPlan.streamBytes
  if blaiCpuLoadUsesBiases(layer):
    hasBiases = true
    biasPlan.active = true
    biasPlan.layerIndex = layerIndexValue
    biasPlan.elementCount = blaiCpuBiasElementCount(layer)
    biasPlan.bytesPerElement = blaiCpuBiasBytesPerElement(useTflite)
    biasPlan.streamBytes = biasPlan.elementCount * biasPlan.bytesPerElement
    result.streamLayerMatches =
      result.streamLayerMatches and biasCursor.layerIndex <= layerIndexValue
    result.streamsFit = result.streamsFit and
      biasCursor.byteOffset <= cpuBiasByteCount and
      cpuBiasByteCount - biasCursor.byteOffset >= biasPlan.streamBytes
    result.nextBiasCursor.layerIndex = blaiLayerIndexValue(layerIndex + 1'u32)
    result.nextBiasCursor.byteOffset = biasCursor.byteOffset + biasPlan.streamBytes
    var biasStore: BlaiCpuBiasStoreResult
    let streamStart = blaiCpuStreamStartCursor(biasCursor)
    if streamStart.valid:
      blaiStoreCpuBiasesInto(
        biasPlan, cpuBiasBytes, streamStart.startIndex,
        decodedBiases, biasStore)
    else:
      result.streamsFit = false
    result.streamsFit = result.streamsFit and biasStore.stored

  if not (result.streamLayerMatches and result.streamsFit):
    blaiReferenceTfliteParsedSingleLayerReadinessInto(result, result.readiness)
    return

  case layerType
  of blaiRoute, blaiRouteMax, blaiRouteW:
    result.reference = blaiReferenceTfliteRouteLayer2d(
      layer, extraInputs, nonNegativeU32(layer.dramPatchSize), input1, output)
  of blaiMean, blaiSoftmax, blaiLogisticLayer, blaiPad, blaiReshape,
     blaiPreTransconv:
    result.reference = blaiReferenceTfliteTransformLayer2d(layer, input1, output)
  of blaiDequantize:
    result.reference.layerType = layerType
    result.reference.supported = false
  else:
    let weightBytesPresent = hasWeights and weightPlan.streamBytes > 0'u32
    let biasElementsPresent = hasBiases and biasPlan.elementCount > 0'u32
    if weightBytesPresent and biasElementsPresent:
      let weightStartCursor = blaiCpuStreamStartCursor(weightCursor)
      if not weightStartCursor.valid:
        result.streamsFit = false
        blaiReferenceTfliteParsedSingleLayerReadinessInto(result, result.readiness)
        return
      let weightWindow = blaiReferenceTfliteParsedWeightWindow(
        weightStartCursor.startIndex, weightPlan.streamBytes, cpuWeightBytes.len)
      let biasWindow = blaiReferenceTfliteParsedBiasWindow(
        biasPlan.elementCount, decodedBiases.len)
      if not weightWindow.valid or not biasWindow.valid:
        result.streamsFit = false
        blaiReferenceTfliteParsedSingleLayerReadinessInto(result, result.readiness)
        return
      result.reference = blaiReferenceTfliteLayer2d(
        layer, input1, input2,
        cpuWeightBytes.toOpenArray(weightWindow.startIndex, weightWindow.stopIndex),
        decodedBiases.toOpenArray(biasWindow.startIndex, biasWindow.stopIndex),
        output)
    elif weightBytesPresent:
      let weightStartCursor = blaiCpuStreamStartCursor(weightCursor)
      if not weightStartCursor.valid:
        result.streamsFit = false
        blaiReferenceTfliteParsedSingleLayerReadinessInto(result, result.readiness)
        return
      let weightWindow = blaiReferenceTfliteParsedWeightWindow(
        weightStartCursor.startIndex, weightPlan.streamBytes, cpuWeightBytes.len)
      if not weightWindow.valid:
        result.streamsFit = false
        blaiReferenceTfliteParsedSingleLayerReadinessInto(result, result.readiness)
        return
      result.reference = blaiReferenceTfliteLayer2d(
        layer, input1, input2,
        cpuWeightBytes.toOpenArray(weightWindow.startIndex, weightWindow.stopIndex),
        emptyBiases, output)
    elif biasElementsPresent:
      let biasWindow = blaiReferenceTfliteParsedBiasWindow(
        biasPlan.elementCount, decodedBiases.len)
      if not biasWindow.valid:
        result.streamsFit = false
        blaiReferenceTfliteParsedSingleLayerReadinessInto(result, result.readiness)
        return
      result.reference = blaiReferenceTfliteLayer2d(
        layer, input1, input2, emptyWeights,
        decodedBiases.toOpenArray(biasWindow.startIndex, biasWindow.stopIndex),
        output)
    else:
      result.reference = blaiReferenceTfliteLayer2d(
        layer, input1, input2, emptyWeights, emptyBiases, output)

  result.supported = result.reference.supported
  result.fits = result.reference.fits
  blaiCaptureTfliteParsedSingleLayerReference(result)
  blaiReferenceTfliteParsedSingleLayerReadinessInto(result, result.readiness)

proc blaiReferenceTfliteParsedLayer2d*(
    layers: openArray[BlaiCpuParsedLayerState],
    layerIndex: uint32,
    useTflite: bool,
    input1, input2: openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor, biasCursor: BlaiCpuStreamCursor,
    decodedBiases: var openArray[int32],
    output: var openArray[uint8]): BlaiReferenceTfliteParsedLayerResult {.
      exportc: "blaiReferenceTfliteParsedLayer2dResult".} =
  ## Execute one parsed-state TFLite CPU-reference layer from bounded streams.
  ##
  ## This bridges parsed sidecars and SDK CPU weight/bias stream cursor rules to
  ## the recovered per-layer fixtures. It deliberately stays allocation-free and
  ## reports unsupported graph/runtime cases instead of following SDK pointers.
  result.nextWeightCursor = weightCursor
  result.nextBiasCursor = biasCursor
  result.useTflite = useTflite
  let layerCursor = blaiRecoveredLayerCursor(layerIndex, layers.len)
  if not layerCursor.valid:
    return
  let parsed = layers[layerCursor.index]
  if not parsed.active:
    return
  result.active = true
  if not useTflite:
    return

  let layer = parsed.layer
  let layerType = blaiLayerTypeFromSdk(layer.layerType)
  let layerIndexValue = blaiLayerIndexValue(layerIndex)
  var emptyWeights: array[0, uint8]
  var emptyBiases: array[0, int32]
  var hasWeights = false
  var hasBiases = false

  result.streamLayerMatches = true
  result.streamsFit = true
  if blaiCpuLoadUsesWeights(layer):
    blaiCpuWeightStreamSegmentInto(
      layers, weightCursor, blaiOpenArrayLenU32(cpuWeightBytes), result.weightStream)
    hasWeights = result.weightStream.active
    result.streamLayerMatches = result.streamLayerMatches and
      result.weightStream.active and
      result.weightStream.plan.layerIndex == layerIndexValue
    result.streamsFit = result.streamsFit and result.weightStream.fits
    if result.weightStream.active:
      result.nextWeightCursor = result.weightStream.nextCursor
  if blaiCpuLoadUsesBiases(layer):
    blaiCpuBiasStreamSegmentInto(
      layers, biasCursor, blaiOpenArrayLenU32(cpuBiasBytes), useTflite,
      result.biasStream)
    hasBiases = result.biasStream.active
    result.streamLayerMatches = result.streamLayerMatches and
      result.biasStream.active and
      result.biasStream.plan.layerIndex == layerIndexValue
    result.streamsFit = result.streamsFit and result.biasStream.fits
    if result.biasStream.active:
      result.nextBiasCursor = result.biasStream.nextCursor
      var biasStore: BlaiCpuBiasStoreResult
      let streamStart = blaiCpuStreamStartCursor(result.biasStream.cursor)
      if streamStart.valid:
        blaiStoreCpuBiasesInto(
          result.biasStream.plan, cpuBiasBytes,
          streamStart.startIndex, decodedBiases, biasStore)
      else:
        result.streamsFit = false
      result.streamsFit = result.streamsFit and biasStore.stored

  if not (result.streamLayerMatches and result.streamsFit):
    return

  case layerType
  of blaiRoute, blaiRouteMax, blaiRouteW:
    result.reference = blaiReferenceTfliteRouteLayer2d(
      layer, parsed.extraInputs, nonNegativeU32(layer.dramPatchSize),
      input1, output)
  of blaiMean, blaiSoftmax, blaiLogisticLayer, blaiPad, blaiReshape,
     blaiPreTransconv:
    result.reference = blaiReferenceTfliteTransformLayer2d(layer, input1, output)
  of blaiDequantize:
    result.reference.layerType = layerType
    result.reference.supported = false
  else:
    let weightBytesPresent = hasWeights and
      result.weightStream.plan.streamBytes > 0'u32
    let biasElementsPresent = hasBiases and
      result.biasStream.plan.elementCount > 0'u32
    if weightBytesPresent and biasElementsPresent:
      let weightStartCursor = blaiCpuStreamStartCursor(result.weightStream.cursor)
      if not weightStartCursor.valid:
        result.streamsFit = false
        return
      let weightWindow = blaiReferenceTfliteParsedWeightWindow(
        weightStartCursor.startIndex, result.weightStream.plan.streamBytes,
        cpuWeightBytes.len)
      let biasWindow = blaiReferenceTfliteParsedBiasWindow(
        result.biasStream.plan.elementCount, decodedBiases.len)
      if not weightWindow.valid or not biasWindow.valid:
        result.streamsFit = false
        return
      result.reference = blaiReferenceTfliteLayer2d(
        layer, input1, input2,
        cpuWeightBytes.toOpenArray(weightWindow.startIndex, weightWindow.stopIndex),
        decodedBiases.toOpenArray(biasWindow.startIndex, biasWindow.stopIndex),
        output)
    elif weightBytesPresent:
      let weightStartCursor = blaiCpuStreamStartCursor(result.weightStream.cursor)
      if not weightStartCursor.valid:
        result.streamsFit = false
        return
      let weightWindow = blaiReferenceTfliteParsedWeightWindow(
        weightStartCursor.startIndex, result.weightStream.plan.streamBytes,
        cpuWeightBytes.len)
      if not weightWindow.valid:
        result.streamsFit = false
        return
      result.reference = blaiReferenceTfliteLayer2d(
        layer, input1, input2,
        cpuWeightBytes.toOpenArray(weightWindow.startIndex, weightWindow.stopIndex),
        emptyBiases, output)
    elif biasElementsPresent:
      let biasWindow = blaiReferenceTfliteParsedBiasWindow(
        result.biasStream.plan.elementCount, decodedBiases.len)
      if not biasWindow.valid:
        result.streamsFit = false
        return
      result.reference = blaiReferenceTfliteLayer2d(
        layer, input1, input2, emptyWeights,
        decodedBiases.toOpenArray(biasWindow.startIndex, biasWindow.stopIndex),
        output)
    else:
      result.reference = blaiReferenceTfliteLayer2d(
        layer, input1, input2, emptyWeights, emptyBiases, output)

  result.supported = result.reference.supported
  result.fits = result.reference.fits
  blaiCaptureTfliteParsedLayerReference(result)

proc blaiLastActiveParsedLayerIndex(layers: openArray[BlaiCpuParsedLayerState]): int32 =
  result = -1
  for i in 0 ..< layers.len:
    let layerCursor = blaiRecoveredLayerCursor(i.uint32, layers.len)
    if not layerCursor.valid:
      continue
    if layers[layerCursor.index].active:
      result = blaiLayerIndexValue(layerCursor.index)

proc blaiParsedModelFailure(
    layer: BlaiReferenceTfliteParsedLayerResult):
    BlaiReferenceTfliteParsedModelFailure =
  if not layer.streamLayerMatches:
    return blaiRefModelStreamLayerMismatch
  if not layer.streamsFit:
    return blaiRefModelStreamDataUnavailable
  if not layer.supported:
    return blaiRefModelUnsupportedLayer
  if not layer.fits:
    return blaiRefModelTensorDoesNotFit
  blaiRefModelNoFailure

proc blaiReferenceTfliteParsedModelValidityInto*(
    runnable: bool,
    allCompleted: bool,
    allWeightsConsumed: bool,
    allBiasesConsumed: bool,
    outResult: var BlaiReferenceTfliteParsedModelValidity) =
  ## Compute strict TFLite parsed-model fixture validity from terminal state.
  outResult = default(BlaiReferenceTfliteParsedModelValidity)
  outResult.runnable = runnable
  outResult.allCompleted = allCompleted
  outResult.allWeightsConsumed = allWeightsConsumed
  outResult.allBiasesConsumed = allBiasesConsumed
  outResult.modelValid = runnable and allCompleted and
    allWeightsConsumed and allBiasesConsumed
  if not allWeightsConsumed:
    outResult.modelFailure = blaiRefModelTrailingWeightStream
  elif not allBiasesConsumed:
    outResult.modelFailure = blaiRefModelTrailingBiasStream
  else:
    outResult.modelFailure = blaiRefModelNoFailure

proc blaiReferenceTfliteParsedModelValidity*(
    runnable: bool,
    allCompleted: bool,
    allWeightsConsumed: bool,
    allBiasesConsumed: bool): BlaiReferenceTfliteParsedModelValidity =
  ## Convenience wrapper for strict TFLite parsed-model fixture validity.
  blaiReferenceTfliteParsedModelValidityInto(
    runnable, allCompleted, allWeightsConsumed, allBiasesConsumed, result)

proc blaiReferenceTfliteParsedModel2d*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    input: openArray[uint8],
    layerInputs: openArray[BlaiReferenceTfliteParsedModelInput],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedBiases: var openArray[int32],
    scratchA, scratchB: var openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteParsedModelResult =
  ## Execute a simple sequential parsed-state TFLite reference model.
  ##
  ## This is intentionally a bounded model-validation fixture, not a full graph
  ## runtime. Active layers are evaluated in order, intermediate tensors use the
  ## caller-owned ping-pong scratch buffers, and final output is written to the
  ## caller-owned output buffer.
  result.useTflite = useTflite
  result.layerCount = blaiOpenArrayLenU32(layers)
  result.firstFailedLayer = -1
  result.lastCompletedLayer = -1
  result.weightStreamBytes = blaiOpenArrayLenU32(cpuWeightBytes)
  result.biasStreamBytes = blaiOpenArrayLenU32(cpuBiasBytes)
  result.nextWeightCursor = blaiCpuStreamCursor()
  result.nextBiasCursor = blaiCpuStreamCursor()
  if not useTflite:
    result.firstFailure = blaiRefModelNotTflite
    result.modelFailure = blaiRefModelNotTflite
    result.validity.modelFailure = blaiRefModelNotTflite
    return
  result.runnable = true
  let lastActive = blaiLastActiveParsedLayerIndex(layers)
  if lastActive < 0:
    result.allWeightsConsumed = result.weightStreamBytes == 0'u32
    result.allBiasesConsumed = result.biasStreamBytes == 0'u32
    result.allCompleted = true
    blaiReferenceTfliteParsedModelValidityInto(
      result.runnable, result.allCompleted, result.allWeightsConsumed,
      result.allBiasesConsumed, result.validity)
    result.modelValid = result.validity.modelValid
    result.modelFailure = result.validity.modelFailure
    return

  var previousScratch = -1
  var hasPreviousOutput = false
  for layerIndex in 0 ..< layers.len:
    let layerCursor = blaiRecoveredLayerCursor(layerIndex.uint32, layers.len)
    if not layerCursor.valid:
      inc result.skippedLayerCount
      continue
    let layerState = layers[layerCursor.index]
    if not layerState.active:
      inc result.skippedLayerCount
      continue

    inc result.attemptedLayerCount
    let referenceLayerIndex = blaiLayerCursorIndexAbi(layerCursor.index)
    if not referenceLayerIndex.valid:
      inc result.failedLayerCount
      if result.firstFailedLayer < 0:
        result.firstFailedLayer = blaiLayerIndexValue(layerCursor.index)
        result.firstFailure = blaiRefModelUnsupportedLayer
        result.modelFailure = result.firstFailure
        result.validity.modelFailure = result.firstFailure
      return
    let writeFinal = blaiLayerIndexValue(layerCursor.index) == lastActive
    var layerResult: BlaiReferenceTfliteParsedLayerResult
    let secondSource =
      if layerCursor.index < layerInputs.len:
        layerInputs[layerCursor.index].secondInput
      else:
        blaiRefInputEmpty
    if secondSource == blaiRefInputPrevious and not hasPreviousOutput:
      inc result.failedLayerCount
      if result.firstFailedLayer < 0:
        result.firstFailedLayer = blaiLayerIndexValue(layerCursor.index)
        result.firstFailure = blaiRefModelSecondInputUnavailable
        result.modelFailure = result.firstFailure
        result.validity.modelFailure = result.firstFailure
      return

    template runLayer(inputOne, outputBuf: untyped) =
      case secondSource
      of blaiRefInputModel:
        layerResult = blaiReferenceTfliteParsedLayer2d(
          layers, referenceLayerIndex.value, useTflite, input1 = inputOne,
          input2 = input, cpuWeightBytes = cpuWeightBytes,
          cpuBiasBytes = cpuBiasBytes, weightCursor = result.nextWeightCursor,
          biasCursor = result.nextBiasCursor, decodedBiases = decodedBiases,
          output = outputBuf)
      of blaiRefInputPrevious:
        if hasPreviousOutput and previousScratch == 0:
          layerResult = blaiReferenceTfliteParsedLayer2d(
            layers, referenceLayerIndex.value, useTflite, input1 = inputOne,
            input2 = scratchA, cpuWeightBytes = cpuWeightBytes,
            cpuBiasBytes = cpuBiasBytes, weightCursor = result.nextWeightCursor,
            biasCursor = result.nextBiasCursor, decodedBiases = decodedBiases,
            output = outputBuf)
        elif hasPreviousOutput and previousScratch == 1:
          layerResult = blaiReferenceTfliteParsedLayer2d(
            layers, referenceLayerIndex.value, useTflite, input1 = inputOne,
            input2 = scratchB, cpuWeightBytes = cpuWeightBytes,
            cpuBiasBytes = cpuBiasBytes, weightCursor = result.nextWeightCursor,
            biasCursor = result.nextBiasCursor, decodedBiases = decodedBiases,
            output = outputBuf)
      of blaiRefInputEmpty:
        layerResult = blaiReferenceTfliteParsedLayer2d(
          layers, referenceLayerIndex.value, useTflite, input1 = inputOne,
          input2 = [], cpuWeightBytes = cpuWeightBytes,
          cpuBiasBytes = cpuBiasBytes, weightCursor = result.nextWeightCursor,
          biasCursor = result.nextBiasCursor, decodedBiases = decodedBiases,
          output = outputBuf)

    if not hasPreviousOutput:
      if writeFinal:
        runLayer(input, output)
      else:
        runLayer(input, scratchA)
        previousScratch = 0
    elif previousScratch == 0:
      if writeFinal:
        runLayer(scratchA, output)
      else:
        runLayer(scratchA, scratchB)
        previousScratch = 1
    else:
      if writeFinal:
        runLayer(scratchB, output)
      else:
        runLayer(scratchB, scratchA)
        previousScratch = 0

    result.lastLayer = layerResult
    if layerResult.supported and layerResult.fits:
      inc result.completedLayerCount
      result.lastCompletedLayer = blaiLayerIndexValue(layerCursor.index)
      result.nextWeightCursor = layerResult.nextWeightCursor
      result.nextBiasCursor = layerResult.nextBiasCursor
      hasPreviousOutput = true
    else:
      inc result.failedLayerCount
      if result.firstFailedLayer < 0:
        result.firstFailedLayer = blaiLayerIndexValue(layerCursor.index)
        result.firstFailure = blaiParsedModelFailure(layerResult)
        result.modelFailure = result.firstFailure
        result.validity.modelFailure = result.firstFailure
        result.firstFailedLayerResultCaptured = true
        result.firstFailedLayerResult = layerResult
      return

  result.allWeightsConsumed =
    result.nextWeightCursor.byteOffset == result.weightStreamBytes
  result.allBiasesConsumed =
    result.nextBiasCursor.byteOffset == result.biasStreamBytes
  result.allCompleted = result.failedLayerCount == 0
  blaiReferenceTfliteParsedModelValidityInto(
    result.runnable, result.allCompleted, result.allWeightsConsumed,
    result.allBiasesConsumed, result.validity)
  result.modelValid = result.validity.modelValid
  if result.validity.modelFailure != blaiRefModelNoFailure:
    result.modelFailure = result.validity.modelFailure

proc blaiReferenceTfliteParsedModel2d*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    input: openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedBiases: var openArray[int32],
    scratchA, scratchB: var openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteParsedModelResult =
  ## Execute a simple linear parsed-state TFLite reference model.
  var emptyInputs: array[0, BlaiReferenceTfliteParsedModelInput]
  blaiReferenceTfliteParsedModel2d(
    layers, useTflite, input, emptyInputs, cpuWeightBytes, cpuBiasBytes,
    decodedBiases, scratchA, scratchB, output)

proc blaiReferenceFixedParsedCheckedReadinessInto*(
    preflight: BlaiReferenceFixedParsedPreflightResult,
    outResult: var BlaiReferenceFixedParsedCheckedReadiness) =
  ## Explain whether the checked fixed parsed-model oracle should execute.
  outResult = default(BlaiReferenceFixedParsedCheckedReadiness)
  outResult.activationShapesSupported =
    preflight.fit.activationShapesSupported
  outResult.weightStorageSupported = preflight.fit.weightStorageSupported
  outResult.buffersFit = preflight.fit.fits
  outResult.firstUnsupportedActivationShapeLayer =
    preflight.plan.firstUnsupportedActivationShapeLayer
  outResult.firstUnsupportedWeightStorageLayer =
    preflight.plan.firstUnsupportedWeightStorageLayer
  outResult.execute = outResult.activationShapesSupported and
    outResult.weightStorageSupported and outResult.buffersFit
  if not outResult.activationShapesSupported:
    outResult.firstBlock = blaiRefFixedCheckedActivationShapeUnsupported
  elif not outResult.weightStorageSupported:
    outResult.firstBlock = blaiRefFixedCheckedWeightStorageUnsupported
  elif not outResult.buffersFit:
    outResult.firstBlock = blaiRefFixedCheckedBuffersDoNotFit
  else:
    outResult.firstBlock = blaiRefFixedCheckedNoBlock

proc blaiReferenceFixedParsedCheckedReadiness*(
    preflight: BlaiReferenceFixedParsedPreflightResult):
    BlaiReferenceFixedParsedCheckedReadiness =
  ## Convenience wrapper for checked fixed parsed-model oracle readiness.
  blaiReferenceFixedParsedCheckedReadinessInto(preflight, result)

proc blaiReferenceTfliteParsedCheckedReadinessInto*(
    preflight: BlaiReferenceTfliteParsedPreflightResult,
    outResult: var BlaiReferenceTfliteParsedCheckedReadiness) =
  ## Explain whether the checked TFLite parsed-model oracle should execute.
  outResult = default(BlaiReferenceTfliteParsedCheckedReadiness)
  outResult.activationShapesSupported =
    preflight.fit.activationShapesSupported
  outResult.buffersFit = preflight.fit.fits
  outResult.firstUnsupportedActivationShapeLayer =
    preflight.plan.firstUnsupportedActivationShapeLayer
  outResult.execute = outResult.activationShapesSupported and
    outResult.buffersFit
  if not outResult.activationShapesSupported:
    outResult.firstBlock = blaiRefTfliteCheckedActivationShapeUnsupported
  elif not outResult.buffersFit:
    outResult.firstBlock = blaiRefTfliteCheckedBuffersDoNotFit
  else:
    outResult.firstBlock = blaiRefTfliteCheckedNoBlock

proc blaiReferenceTfliteParsedCheckedReadiness*(
    preflight: BlaiReferenceTfliteParsedPreflightResult):
    BlaiReferenceTfliteParsedCheckedReadiness =
  ## Convenience wrapper for checked TFLite parsed-model oracle readiness.
  blaiReferenceTfliteParsedCheckedReadinessInto(preflight, result)

proc blaiReferenceFixedParsedCheckedModel2d*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    input: openArray[int8],
    layerInputs: openArray[BlaiReferenceFixedParsedModelInput],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int8],
    decodedBiases: var openArray[int8],
    scratchA, scratchB: var openArray[int8],
  output: var openArray[int8]): BlaiReferenceFixedParsedCheckedModelResult =
  ## Preflight then execute a fixed parsed-model oracle only when buffers fit.
  blaiReferenceFixedParsedPreflightInto(
    layers, input, cpuWeightBytes, cpuBiasBytes, decodedWeights, decodedBiases,
    scratchA, scratchB, output, result.preflight)
  blaiReferenceFixedParsedCheckedReadinessInto(
    result.preflight, result.readiness)
  if not result.readiness.execute:
    return
  result.model = blaiReferenceFixedParsedModel2d(
    layers, useTflite, input, layerInputs, cpuWeightBytes, cpuBiasBytes,
    decodedWeights, decodedBiases, scratchA, scratchB, output)
  result.executed = true

proc blaiReferenceFixedParsedCheckedModel2d*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    input: openArray[int8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int8],
    decodedBiases: var openArray[int8],
    scratchA, scratchB: var openArray[int8],
    output: var openArray[int8]): BlaiReferenceFixedParsedCheckedModelResult =
  ## Preflight then execute a simple linear fixed parsed-model oracle.
  var emptyInputs: array[0, BlaiReferenceFixedParsedModelInput]
  blaiReferenceFixedParsedCheckedModel2d(
    layers, useTflite, input, emptyInputs, cpuWeightBytes, cpuBiasBytes,
    decodedWeights, decodedBiases, scratchA, scratchB, output)

proc blaiReferenceTfliteParsedCheckedModel2d*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    input: openArray[uint8],
    layerInputs: openArray[BlaiReferenceTfliteParsedModelInput],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedBiases: var openArray[int32],
    scratchA, scratchB: var openArray[uint8],
  output: var openArray[uint8]): BlaiReferenceTfliteParsedCheckedModelResult =
  ## Preflight then execute a TFLite parsed-model oracle only when buffers fit.
  blaiReferenceTfliteParsedPreflightInto(
    layers, input, cpuWeightBytes, cpuBiasBytes, decodedBiases,
    scratchA, scratchB, output, result.preflight)
  blaiReferenceTfliteParsedCheckedReadinessInto(
    result.preflight, result.readiness)
  if not result.readiness.execute:
    return
  result.model = blaiReferenceTfliteParsedModel2d(
    layers, useTflite, input, layerInputs, cpuWeightBytes, cpuBiasBytes,
    decodedBiases, scratchA, scratchB, output)
  result.executed = true

proc blaiReferenceTfliteParsedCheckedModel2d*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    input: openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedBiases: var openArray[int32],
    scratchA, scratchB: var openArray[uint8],
    output: var openArray[uint8]): BlaiReferenceTfliteParsedCheckedModelResult =
  ## Preflight then execute a simple linear TFLite parsed-model oracle.
  var emptyInputs: array[0, BlaiReferenceTfliteParsedModelInput]
  blaiReferenceTfliteParsedCheckedModel2d(
    layers, useTflite, input, emptyInputs, cpuWeightBytes, cpuBiasBytes,
    decodedBiases, scratchA, scratchB, output)

proc blaiUint32AddressRangeFitInto*(address, bytes: uint32,
                                    outResult:
                                      var BlaiUint32AddressRangeFitResult) =
  ## Check `[address, address + bytes)` against the 32-bit bus address space.
  outResult = default(BlaiUint32AddressRangeFitResult)
  outResult.address = address
  outResult.bytes = bytes
  outResult.endExclusive = blaiUint32AddressEndExclusive(address, bytes)
  outResult.fits = blaiUint32AddressRangeEndFits(address, bytes)

proc blaiUint32AddressRangeFit*(address, bytes: uint32):
                                 BlaiUint32AddressRangeFitResult =
  ## Convenience result-returning wrapper for 32-bit bus range checks.
  blaiUint32AddressRangeFitInto(address, bytes, result)

proc blaiUint32AddressRangeFits*(address, bytes: uint32): bool =
  ## Return true when `[address, address + bytes)` fits in a 32-bit bus address.
  blaiUint32AddressRangeFit(address, bytes).fits

proc blaiUint32RelativeAddressRangeFits*(
    base, offset, bytes: uint32,
    address: var uint32): bool =
  ## Resolve `[base + offset, base + offset + bytes)` without uint32 wraparound.
  var startFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), base, offset, startFit)
  if not startFit.fits:
    return false
  address = startFit.requiredCount
  blaiUint32AddressRangeFits(address, bytes)

proc blaiCacheRangeAddress*(dataBufferAddr: uint32,
                            cacheRange: BlaiCacheRange): BlaiCacheRangeAddress =
  ## Translate a DATA-buffer-relative cache range into an absolute address.
  result.operation = cacheRange.operation
  result.bytes = cacheRange.bytes
  if not cacheRange.active:
    result.fits = true
    return
  result.active = true
  result.fits = blaiUint32RelativeAddressRangeFits(
    dataBufferAddr, cacheRange.offset, cacheRange.bytes, result.address)

proc blaiApplyCacheRange*(dataBufferAddr: uint32,
                          cacheRange: BlaiCacheRange): BlaiCacheRangeApplyResult =
  ## Execute one recovered SDK cache range when compiled for a BL808 core.
  ##
  ## Host builds still return the checked absolute address plan, but leave
  ## `applied` false because T-Head cache opcodes are unavailable there.
  let address = blaiCacheRangeAddress(dataBufferAddr, cacheRange)
  result.active = address.active
  result.fits = address.fits
  result.operation = address.operation
  result.address = address.address
  result.bytes = address.bytes
  if not address.active or not address.fits:
    return
  when defined(bl808d0) or defined(bl808m0) or defined(bl808lp):
    when nimvm:
      discard
    else:
      case address.operation
      of blaiCacheClean:
        core.dcacheCleanRange(address.address.uint, address.bytes.uint)
      of blaiCacheInvalidate:
        core.dcacheInvalidateRange(address.address.uint, address.bytes.uint)
      result.applied = true

proc blaiApplyWorkspaceCleanSegment*(
    segment: BlaiForwardModelWorkspaceSegment): BlaiCacheRangeApplyResult =
  ## Clean one absolute reusable-workspace segment before BLAI DMA reads it.
  result.operation = blaiCacheClean
  result.active = segment.active and segment.bytes != 0'u32
  result.address = segment.address
  result.bytes = segment.bytes
  if not result.active:
    result.fits = true
    return
  result.fits = blaiUint32AddressRangeFits(segment.address, segment.bytes)
  if not result.fits:
    return
  when defined(bl808d0) or defined(bl808m0) or defined(bl808lp):
    when nimvm:
      discard
    else:
      core.dcacheCleanRange(segment.address.uint, segment.bytes.uint)
      result.applied = true

proc blaiPrepareForwardWorkspaceCacheInto*(
    workspace: BlaiForwardModelWorkspacePlan,
    outResult: var BlaiForwardWorkspaceCachePrepareResult) =
  ## Clean instruction, packed weight, and bias workspace segments before start.
  outResult = default(BlaiForwardWorkspaceCachePrepareResult)
  outResult.instruction = blaiApplyWorkspaceCleanSegment(workspace.instruction)
  outResult.weight = blaiApplyWorkspaceCleanSegment(workspace.weight)
  outResult.bias = blaiApplyWorkspaceCleanSegment(workspace.bias)
  outResult.fits = outResult.instruction.fits and outResult.weight.fits and
    outResult.bias.fits
  outResult.applied =
    (not outResult.instruction.active or outResult.instruction.applied) and
    (not outResult.weight.active or outResult.weight.applied) and
    (not outResult.bias.active or outResult.bias.applied)

proc blaiPrepareForwardWorkspaceCache*(
    workspace: BlaiForwardModelWorkspacePlan): BlaiForwardWorkspaceCachePrepareResult =
  ## Convenience result-returning wrapper for reusable-workspace cache prep.
  blaiPrepareForwardWorkspaceCacheInto(workspace, result)

proc blaiNpuInputCleanRangeInto*(plan: BlaiTensorTransferPlan,
                                 patchSize: uint32,
                                 outResult: var BlaiCacheRange) =
  ## SDK `Store_tensor_data_to_NPU` cleans each staged input tensor range.
  blaiCacheRangeInto(blaiCacheClean, plan, patchSize, outResult)

proc blaiNpuInputCleanRange*(plan: BlaiTensorTransferPlan,
                             patchSize: uint32): BlaiCacheRange =
  ## Convenience result-returning wrapper for staged input cache clean ranges.
  blaiNpuInputCleanRangeInto(plan, patchSize, result)

proc blaiNpuOutputInvalidateRangeInto*(plan: BlaiTensorTransferPlan,
                                       patchSize: uint32,
                                       outResult: var BlaiCacheRange) =
  ## SDK `Load_NPU_data_to_tensor` invalidates each output tensor range.
  blaiCacheRangeInto(blaiCacheInvalidate, plan, patchSize, outResult)

proc blaiNpuOutputInvalidateRange*(plan: BlaiTensorTransferPlan,
                                   patchSize: uint32): BlaiCacheRange =
  ## Convenience result-returning wrapper for output cache invalidate ranges.
  blaiNpuOutputInvalidateRangeInto(plan, patchSize, result)

proc blaiPlanForwardNpuInto*(layer: BlaiCpuInstLayer64,
                             layerIndex: uint32,
                             outResult: var BlaiForwardNpuPlan) =
  ## Recover the SDK `forward_NPU` wrapper decisions around the recovered
  ## encoder/materializer path without mutating caller buffers or executing
  ## hardware.
  outResult = default(BlaiForwardNpuPlan)
  outResult.layerIndex = layerIndex
  outResult.firstLayer = layerIndex == 0'u32
  outResult.patchSize = nonNegativeU32(layer.dramPatchSize)
  outResult.runnable = layer.npuOn != 0
  if not outResult.runnable:
    return
  blaiWeightBufferPlanInto(layer, outResult.weightBuffer)
  for inputIndex in 0 ..< BlaiMaxInputNum:
    blaiNpuInputTransferPlanInto(
      layer, layerIndex, range[0 .. 7](inputIndex),
      outResult.inputs[inputIndex])
    blaiNpuInputCleanRangeInto(
      outResult.inputs[inputIndex], outResult.patchSize,
      outResult.inputCleanRanges[inputIndex])
  blaiNpuOutputTransferPlanInto(layer, outResult.output)
  blaiNpuOutputInvalidateRangeInto(
    outResult.output.output, outResult.patchSize,
    outResult.outputInvalidateRange)
  blaiNpuOutputInvalidateRangeInto(
    outResult.output.midOutput, outResult.patchSize,
    outResult.midOutputInvalidateRange)

proc blaiPlanForwardNpu*(layer: BlaiCpuInstLayer64,
                         layerIndex: uint32): BlaiForwardNpuPlan =
  ## Convenience result-returning wrapper for `forward_NPU` planning.
  blaiPlanForwardNpuInto(layer, layerIndex, result)

proc blaiIncludeForwardDataRange(required: var BlaiForwardDataBufferPlan,
                                 active: bool,
                                 offset, bytes: uint32) =
  if not active:
    return
  var rangeFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), offset, bytes, rangeFit)
  if not rangeFit.fits:
    required.fits = false
    required.bytes = high(uint32)
  elif required.fits and rangeFit.requiredCount > required.bytes:
    required.bytes = rangeFit.requiredCount

proc blaiIncludeForwardDataTransfer(required: var BlaiForwardDataBufferPlan,
                                    transfer: BlaiTensorTransferPlan,
                                    patchSize: uint32) =
  blaiIncludeForwardDataRange(
    required, transfer.active, blaiTensorBufferOffset(transfer, patchSize),
    transfer.bytes)

proc blaiIncludeForwardDataCacheRange(required: var BlaiForwardDataBufferPlan,
                                      cacheRange: BlaiCacheRange) =
  blaiIncludeForwardDataRange(
    required, cacheRange.active, cacheRange.offset, cacheRange.bytes)

proc blaiForwardNpuDataBufferPlanInto*(
    plan: BlaiForwardNpuPlan,
    outResult: var BlaiForwardDataBufferPlan) =
  ## Compute the minimum caller-owned DATA buffer required by `forward_NPU`.
  ##
  ## The SDK addresses DATA_buf as slot * DRAM_patch_size for staging,
  ## readback, and cache maintenance. This folds all recovered ranges into one
  ## checked size requirement so callers do not duplicate slot arithmetic.
  outResult = default(BlaiForwardDataBufferPlan)
  outResult.runnable = plan.runnable
  outResult.fits = true
  if not plan.runnable:
    return
  for input in plan.inputs:
    blaiIncludeForwardDataTransfer(outResult, input, plan.patchSize)
  blaiIncludeForwardDataTransfer(outResult, plan.output.output, plan.patchSize)
  blaiIncludeForwardDataTransfer(
    outResult, plan.output.midOutput, plan.patchSize)
  for cacheRange in plan.inputCleanRanges:
    blaiIncludeForwardDataCacheRange(outResult, cacheRange)
  blaiIncludeForwardDataCacheRange(outResult, plan.outputInvalidateRange)
  blaiIncludeForwardDataCacheRange(outResult, plan.midOutputInvalidateRange)

proc blaiForwardNpuDataBufferPlan*(
    plan: BlaiForwardNpuPlan): BlaiForwardDataBufferPlan =
  ## Convenience result-returning wrapper for forward_NPU DATA-buffer sizing.
  blaiForwardNpuDataBufferPlanInto(plan, result)

proc blaiStageForwardMemoryPlan(layer: BlaiCpuInstLayer64): BlaiCpuInstLayer64 =
  ## Project the allocator/fetch memory state that `gen_npu_inst_layer` writes
  ## before forward_NPU resource sizing. Already-encoded layers keep their
  ## caller-provided memory layout.
  result = layer
  if result.dramPatchSize > 0 and result.instCnt > 0:
    return

  var allocation: BlaiMemAllocPlan
  blaiPlanMemAllocInto(result, allocation)
  if not allocation.fits:
    return

  var ctrl: BlaiPsramCtrl
  blaiApplyMemAllocPlan(ctrl, allocation)

  var encodePlan: BlaiEncodePlan
  blaiPlanEncodeInto(result, allocation.fits, encodePlan)
  if not encodePlan.runnable:
    return

  case blaiFetchKind(encodePlan.dispatch)
  of blaiFetchRoute:
    var routePlan: BlaiRouteSramSlotPlan
    blaiPlanRouteSramSlotsInto(result, ctrl, routePlan)
    if not routePlan.fits:
      return
    blaiApplyRouteSramSlotPlan(ctrl, result, routePlan)
  of blaiFetchGeneral:
    var fetchPlan: BlaiFetchMemoryPlan
    blaiPlanFetchMemoryInto(result, ctrl, blaiFetchGeneral, fetchPlan)
    if not fetchPlan.fits:
      return
    blaiApplyFetchMemoryPlan(ctrl, result, fetchPlan)

  blaiApplyMemoryPlan(result, ctrl)

proc blaiPlanForwardResourcesInto*(layer: BlaiCpuInstLayer64,
                                   layerIndex: uint32,
                                   useTflite: bool,
                                   outResult: var BlaiForwardResourcePlan) =
  ## Collect caller-owned buffers needed by the recovered `forward_NPU` path.
  ##
  ## This is still ownership-free: it reports instruction scratch, DATA,
  ## reordered weight, bias, and temporary grouped-weight requirements without
  ## allocating or executing the NPU.
  outResult = default(BlaiForwardResourcePlan)
  let plannedLayer = blaiStageForwardMemoryPlan(layer)
  var forward: BlaiForwardNpuPlan
  blaiPlanForwardNpuInto(plannedLayer, layerIndex, forward)
  outResult.runnable = forward.runnable
  outResult.supported = true
  if not outResult.runnable:
    return
  outResult.instructionBytes = BlaiInstructionScratchSize.uint32
  blaiForwardNpuDataBufferPlanInto(forward, outResult.data)
  outResult.weight = forward.weightBuffer
  outResult.weightLayer = outResult.weight.usesWeights
  blaiPlanNpuWeightLoadInto(plannedLayer, useTflite, outResult.weightLoad)
  if outResult.weightLayer:
    outResult.supported = outResult.weightLoad.supportedKernel
    let packedWeightBytes = blaiNpuPackedWeightBytes(plannedLayer, useTflite)
    outResult.weight.alignedWeightBytes =
      max(outResult.weight.alignedWeightBytes, blaiAlign4(packedWeightBytes))
    outResult.weight.biasOffset = outResult.weight.alignedWeightBytes
    outResult.weight.totalBytes =
      outResult.weight.alignedWeightBytes + outResult.weight.biasBytes
    if outResult.weightLoad.usesTemporaryGroupBuffer:
      outResult.temporaryWeightElements = outResult.weightLoad.temporaryWeightElements
      outResult.temporaryWeightBytes = outResult.weightLoad.temporaryWeightBytes
  outResult.supported = outResult.supported and outResult.data.fits

proc blaiPlanForwardResources*(layer: BlaiCpuInstLayer64,
                               layerIndex: uint32,
                               useTflite: bool): BlaiForwardResourcePlan =
  ## Convenience result-returning wrapper for forward resource planning.
  blaiPlanForwardResourcesInto(layer, layerIndex, useTflite, result)

proc blaiForwardResourceFitReadinessInto*(
    fit: BlaiForwardResourceFitResult,
    outResult: var BlaiForwardResourceFitReadiness) =
  ## Derive the public fit gate for one forward_NPU layer resource check.
  outResult = default(BlaiForwardResourceFitReadiness)
  outResult.runnable = fit.runnable
  outResult.supported = fit.supported
  outResult.instructionFits = fit.instructionFits
  outResult.dataFits = fit.dataFits
  outResult.weightFits = fit.weightFits
  outResult.temporaryFits = fit.temporaryFits
  if not outResult.runnable:
    outResult.firstBlock = blaiForwardResourceNoBlock
  elif not outResult.supported:
    outResult.firstBlock = blaiForwardResourceUnsupported
  elif not outResult.instructionFits:
    outResult.firstBlock = blaiForwardResourceInstruction
  elif not outResult.dataFits:
    outResult.firstBlock = blaiForwardResourceData
  elif not outResult.weightFits:
    outResult.firstBlock = blaiForwardResourceWeight
  elif not outResult.temporaryFits:
    outResult.firstBlock = blaiForwardResourceTemporaryWeights
  else:
    outResult.firstBlock = blaiForwardResourceNoBlock
  outResult.fits =
    (not outResult.runnable) or
    (outResult.supported and outResult.instructionFits and
     outResult.dataFits and outResult.weightFits and outResult.temporaryFits)

proc blaiForwardResourceFitReadiness*(
    fit: BlaiForwardResourceFitResult): BlaiForwardResourceFitReadiness =
  ## Convenience wrapper for one forward_NPU layer resource fit gate.
  blaiForwardResourceFitReadinessInto(fit, result)

proc blaiForwardResourcesFitInto*(plan: BlaiForwardResourcePlan,
                                  instructionBytes, dataBufferBytes,
                                  weightBufferBytes, biasBufferBytes,
                                  temporaryWeightElements: uint32,
                                  outResult: var BlaiForwardResourceFitResult) =
  ## Check caller-provided buffers against `blaiPlanForwardResources`.
  outResult = default(BlaiForwardResourceFitResult)
  outResult.runnable = plan.runnable
  outResult.supported = plan.supported
  if not plan.runnable:
    outResult.instructionFits = true
    outResult.dataFits = true
    outResult.weightFits = true
    outResult.temporaryFits = true
    blaiForwardResourceFitReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.fits = outResult.readiness.fits
    return
  if not plan.supported:
    blaiForwardResourceFitReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.fits = outResult.readiness.fits
    return
  outResult.instructionFits = instructionBytes >= plan.instructionBytes
  outResult.dataFits = dataBufferBytes >= plan.data.bytes
  var weightFit: BlaiWeightBufferFitResult
  blaiWeightBufferFitsInto(
    plan.weight, weightBufferBytes, biasBufferBytes, weightFit)
  outResult.weightFits = weightFit.fits
  outResult.temporaryFits =
    temporaryWeightElements >= plan.temporaryWeightElements
  blaiForwardResourceFitReadinessInto(outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.fits = outResult.readiness.fits

proc blaiForwardResourcesFit*(plan: BlaiForwardResourcePlan,
                              instructionBytes, dataBufferBytes,
                              weightBufferBytes, biasBufferBytes,
                              temporaryWeightElements: uint32): bool =
  ## Compatibility wrapper for caller-owned forward resource fit results.
  var fit: BlaiForwardResourceFitResult
  blaiForwardResourcesFitInto(
    plan, instructionBytes, dataBufferBytes, weightBufferBytes,
    biasBufferBytes, temporaryWeightElements, fit)
  fit.fits

proc blaiIncludeForwardModelLayer(result: var BlaiForwardModelResourcePlan,
                                  layer: BlaiForwardResourcePlan) =
  if not layer.runnable:
    return
  inc result.npuLayerCount
  result.supported = result.supported and layer.supported
  result.instructionBytes = max(result.instructionBytes, layer.instructionBytes)
  result.dataBufferBytes = max(result.dataBufferBytes, layer.data.bytes)
  result.weightBufferBytes =
    max(result.weightBufferBytes, layer.weight.alignedWeightBytes)
  result.biasBufferBytes = max(result.biasBufferBytes, layer.weight.biasBytes)
  result.temporaryWeightElements =
    max(result.temporaryWeightElements, layer.temporaryWeightElements)
  result.temporaryWeightBytes =
    max(result.temporaryWeightBytes, layer.temporaryWeightBytes)

proc blaiForwardModelLayerWindow*(capacity: int): BlaiForwardModelLayerWindow =
  ## Resolve caller-owned forward model layer table bounds.
  if capacity < 0:
    return
  result.count = capacity
  result.valid = true

proc blaiForwardModelLayerCursor*(
    window: BlaiForwardModelLayerWindow,
    layerIndex: int): BlaiForwardModelLayerCursor =
  ## Resolve one forward model layer row before table access.
  if not window.valid or layerIndex < 0 or layerIndex >= window.count:
    return
  result.layerIndex = layerIndex
  result.valid = true

proc blaiPlanForwardModelResourcesInto*(layers: openArray[BlaiCpuInstLayer64],
                                        useTflite: bool,
                                        outResult: var BlaiForwardModelResourcePlan) =
  ## Fold a CPU layer table into reusable buffers for recovered NPU execution.
  ##
  ## CPU model weights/biases are stream-sized totals. NPU instruction, DATA,
  ## reordered weight/bias, and temporary grouped-weight buffers are maxima
  ## because the recovered `forward_NPU` path consumes them one layer at a time.
  outResult = default(BlaiForwardModelResourcePlan)
  outResult.supported = true
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  blaiCpuStreamTotalsInto(layers, useTflite, outResult.cpuStreams)
  outResult.cpuWeightStreamBytes = outResult.cpuStreams.cpuWeightStreamBytes
  outResult.cpuBiasStreamBytes = outResult.cpuStreams.cpuBiasStreamBytes
  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    outResult.supported = false
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      outResult.supported = false
      return
    let forwardLayerIndex = blaiLayerCursorIndexAbi(layerCursor.layerIndex)
    if not forwardLayerIndex.valid:
      outResult.supported = false
      return
    var layerPlan: BlaiForwardResourcePlan
    blaiPlanForwardResourcesInto(
      layers[layerCursor.layerIndex], forwardLayerIndex.value, useTflite,
      layerPlan)
    blaiIncludeForwardModelLayer(outResult, layerPlan)

proc blaiPlanForwardModelResources*(
    layers: openArray[BlaiCpuInstLayer64],
    useTflite: bool): BlaiForwardModelResourcePlan =
  ## Convenience result-returning wrapper for model resource planning.
  blaiPlanForwardModelResourcesInto(layers, useTflite, result)

proc blaiPlanForwardModelResourcesInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    outResult: var BlaiForwardModelResourcePlan) =
  ## Fold parsed layer state into reusable buffers for recovered NPU execution.
  outResult = default(BlaiForwardModelResourcePlan)
  outResult.supported = true
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  blaiCpuStreamTotalsInto(layers, useTflite, outResult.cpuStreams)
  outResult.cpuWeightStreamBytes = outResult.cpuStreams.cpuWeightStreamBytes
  outResult.cpuBiasStreamBytes = outResult.cpuStreams.cpuBiasStreamBytes
  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    outResult.supported = false
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      outResult.supported = false
      return
    let layerState = layers[layerCursor.layerIndex]
    if not layerState.active:
      continue
    var layerPlan: BlaiForwardResourcePlan
    blaiPlanForwardResourcesInto(
      layerState.layer, layerState.index, useTflite, layerPlan)
    blaiIncludeForwardModelLayer(outResult, layerPlan)

proc blaiPlanForwardModelResources*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool): BlaiForwardModelResourcePlan =
  ## Convenience result-returning wrapper for parsed model resource planning.
  blaiPlanForwardModelResourcesInto(layers, useTflite, result)

proc blaiForwardModelResourceFitReadinessInto*(
    fit: BlaiForwardModelResourceFitResult,
    outResult: var BlaiForwardModelResourceFitReadiness) =
  ## Derive the public model-level forward_NPU resource fit gate.
  outResult = default(BlaiForwardModelResourceFitReadiness)
  outResult.supported = fit.supported
  outResult.instructionFits = fit.instructionFits
  outResult.dataFits = fit.dataFits
  outResult.weightFits = fit.weightFits
  outResult.biasFits = fit.biasFits
  outResult.temporaryFits = fit.temporaryFits
  outResult.cpuWeightsFit = fit.cpuWeightsFit
  outResult.cpuBiasesFit = fit.cpuBiasesFit
  if not outResult.supported:
    outResult.firstBlock = blaiForwardModelResourceUnsupported
  elif not outResult.instructionFits:
    outResult.firstBlock = blaiForwardModelResourceInstruction
  elif not outResult.dataFits:
    outResult.firstBlock = blaiForwardModelResourceData
  elif not outResult.weightFits:
    outResult.firstBlock = blaiForwardModelResourceWeight
  elif not outResult.biasFits:
    outResult.firstBlock = blaiForwardModelResourceBias
  elif not outResult.temporaryFits:
    outResult.firstBlock = blaiForwardModelResourceTemporaryWeights
  elif not outResult.cpuWeightsFit:
    outResult.firstBlock = blaiForwardModelResourceCpuWeights
  elif not outResult.cpuBiasesFit:
    outResult.firstBlock = blaiForwardModelResourceCpuBiases
  else:
    outResult.firstBlock = blaiForwardModelResourceNoBlock
  outResult.fits =
    outResult.supported and outResult.instructionFits and
    outResult.dataFits and outResult.weightFits and outResult.biasFits and
    outResult.temporaryFits and outResult.cpuWeightsFit and
    outResult.cpuBiasesFit

proc blaiForwardModelResourceFitReadiness*(
    fit: BlaiForwardModelResourceFitResult):
    BlaiForwardModelResourceFitReadiness =
  ## Convenience wrapper for model-level forward_NPU resource fit gate.
  blaiForwardModelResourceFitReadinessInto(fit, result)

proc blaiForwardModelResourcesFitInto*(plan: BlaiForwardModelResourcePlan,
                                       instructionBytes, dataBufferBytes,
                                       weightBufferBytes, biasBufferBytes,
                                       temporaryWeightElements,
                                       cpuWeightStreamBytes,
                                       cpuBiasStreamBytes: uint32,
                                       outResult: var BlaiForwardModelResourceFitResult) =
  ## Check caller-owned reusable buffers and CPU model streams for a layer table.
  outResult = default(BlaiForwardModelResourceFitResult)
  outResult.supported = plan.supported
  outResult.requiredCpuStreams = plan.cpuStreams
  outResult.providedCpuStreams = BlaiCpuStreamTotals(
    useTflite: plan.cpuStreams.useTflite,
    weightLayerCount: plan.cpuStreams.weightLayerCount,
    biasLayerCount: plan.cpuStreams.biasLayerCount,
    firstWeightLayer: plan.cpuStreams.firstWeightLayer,
    firstBiasLayer: plan.cpuStreams.firstBiasLayer,
    cpuWeightStreamBytes: cpuWeightStreamBytes,
    cpuBiasStreamBytes: cpuBiasStreamBytes)
  outResult.instructionFits = instructionBytes >= plan.instructionBytes
  outResult.dataFits = dataBufferBytes >= plan.dataBufferBytes
  outResult.weightFits = weightBufferBytes >= plan.weightBufferBytes
  outResult.biasFits = biasBufferBytes >= plan.biasBufferBytes
  outResult.temporaryFits =
    temporaryWeightElements >= plan.temporaryWeightElements
  outResult.cpuWeightsFit = cpuWeightStreamBytes >= plan.cpuWeightStreamBytes
  outResult.cpuBiasesFit = cpuBiasStreamBytes >= plan.cpuBiasStreamBytes
  blaiForwardModelResourceFitReadinessInto(outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.fits = outResult.readiness.fits

proc blaiForwardModelResourcesFit*(plan: BlaiForwardModelResourcePlan,
                                   instructionBytes, dataBufferBytes,
                                   weightBufferBytes, biasBufferBytes,
                                   temporaryWeightElements,
                                   cpuWeightStreamBytes,
                                   cpuBiasStreamBytes: uint32): bool =
  ## Boolean wrapper for model-level resource fit checks.
  var fit: BlaiForwardModelResourceFitResult
  blaiForwardModelResourcesFitInto(
    plan, instructionBytes, dataBufferBytes, weightBufferBytes, biasBufferBytes,
    temporaryWeightElements, cpuWeightStreamBytes, cpuBiasStreamBytes, fit)
  fit.fits

proc blaiAlignForwardWorkspaceOffset(offset, alignment: uint32): uint32 =
  if alignment <= 1'u32:
    return offset
  let rem = offset mod alignment
  if rem == 0'u32:
    offset
  else:
    let add = alignment - rem
    if offset > high(uint32) - add:
      high(uint32)
    else:
      offset + add

proc blaiAddForwardWorkspaceSegment(
    result: var BlaiForwardModelWorkspacePlan,
    segment: var BlaiForwardModelWorkspaceSegment,
    cursor: var uint32,
    bytes, alignment: uint32) =
  segment.fits = result.fits
  if bytes == 0'u32:
    return
  let aligned = blaiAlignForwardWorkspaceOffset(cursor, alignment)
  var segmentFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), aligned, bytes, segmentFit)
  if not segmentFit.fits:
    result.fits = false
    segment.fits = false
    return
  var segmentAddress: uint32
  if not blaiUint32RelativeAddressRangeFits(
        result.baseAddress, aligned, bytes, segmentAddress):
    result.fits = false
    segment.fits = false
    return
  segment.active = true
  segment.fits = true
  segment.offset = aligned
  segment.address = segmentAddress
  segment.bytes = bytes
  cursor = segmentFit.requiredCount

proc blaiPlanForwardModelWorkspaceInto*(
    resources: BlaiForwardModelResourcePlan,
    baseAddress: uint32,
    outResult: var BlaiForwardModelWorkspacePlan,
    alignment: uint32 = 16'u32) =
  ## Lay reusable NPU buffers out in one caller-owned address range.
  ##
  ## The layout is deterministic and allocation-free. CPU model streams are not
  ## included here because they remain model-owned source data, while these
  ## segments are the reusable NPU execution workspace.
  outResult = default(BlaiForwardModelWorkspacePlan)
  outResult.supported = resources.supported
  outResult.fits = resources.supported
  outResult.baseAddress = baseAddress
  var cursor: uint32
  blaiAddForwardWorkspaceSegment(
    outResult, outResult.instruction, cursor, resources.instructionBytes,
    alignment)
  blaiAddForwardWorkspaceSegment(
    outResult, outResult.data, cursor, resources.dataBufferBytes, alignment)
  blaiAddForwardWorkspaceSegment(
    outResult, outResult.weight, cursor, resources.weightBufferBytes, alignment)
  blaiAddForwardWorkspaceSegment(
    outResult, outResult.bias, cursor, resources.biasBufferBytes, alignment)
  blaiAddForwardWorkspaceSegment(
    outResult, outResult.temporaryWeights, cursor,
    resources.temporaryWeightBytes, alignment)
  outResult.totalBytes = cursor

proc blaiPlanForwardModelWorkspace*(
    resources: BlaiForwardModelResourcePlan,
    baseAddress: uint32,
    alignment: uint32 = 16'u32): BlaiForwardModelWorkspacePlan =
  ## Convenience result-returning wrapper for model workspace layout.
  blaiPlanForwardModelWorkspaceInto(
    resources, baseAddress, result, alignment)

proc blaiParsedForwardLayerWindow*(
    layerCount: uint32,
    capacity: int): BlaiParsedForwardLayerWindow =
  ## Resolve a non-empty parsed forward layer table for resource planning.
  let countCursor = blaiU32CountCursor(layerCount, capacity)
  if not countCursor.valid or countCursor.count <= 0:
    return
  let lastCursor = blaiU32ArrayIndexCursor(layerCount - 1'u32, capacity)
  if not lastCursor.valid:
    return
  result.layerCount = layerCount
  result.count = countCursor.count
  result.startIndex = 0
  result.stopIndex = lastCursor.index
  result.valid = true

proc blaiParsedForwardLayerCursor*(
    window: BlaiParsedForwardLayerWindow,
    layerIndex: int): BlaiParsedForwardLayerCursor =
  ## Resolve one parsed forward layer index inside a checked layer window.
  if not window.valid or layerIndex < window.startIndex or
      layerIndex > window.stopIndex:
    return
  result.layerIndex = layerIndex
  result.valid = true

proc blaiPlanParsedForwardModelWorkspaceInto*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuInstLayer64],
    baseAddress: uint32,
    outResult: var BlaiParsedForwardModelPlan,
    alignment: uint32 = 16'u32) =
  ## Plan reusable forward_NPU resources from parsed CPU records.
  ##
  ## This bridges raw CPU/DSP instruction parsing to the existing forward_NPU
  ## workspace planner, but only after the parsed NPU layers have post-encoder
  ## fields (`dramPatchSize` and `instCnt`). It does not allocate, encode, copy
  ## weights, or execute hardware.
  outResult = default(BlaiParsedForwardModelPlan)
  blaiParsedForwardModelReadinessInto(parsed, layers, outResult.readiness)
  if not outResult.readiness.forwardReady:
    return

  let layerCount = blaiBoundedU32Count(outResult.readiness.layerCount, layers.len)
  if layerCount > 0:
    let layerWindow =
      blaiParsedForwardLayerWindow(layerCount.uint32, layers.len)
    if not layerWindow.valid:
      return
    blaiPlanForwardModelResourcesInto(
      layers.toOpenArray(layerWindow.startIndex, layerWindow.stopIndex),
      outResult.readiness.useTflite, outResult.resources)
  else:
    outResult.resources.supported = true
  blaiPlanForwardModelWorkspaceInto(
    outResult.resources, baseAddress, outResult.workspace, alignment)
  outResult.planned = outResult.resources.supported
  outResult.workspaceReady = outResult.planned and
    outResult.workspace.supported and outResult.workspace.fits

proc blaiPlanParsedForwardModelWorkspace*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuInstLayer64],
    baseAddress: uint32,
    alignment: uint32 = 16'u32): BlaiParsedForwardModelPlan =
  ## Convenience result-returning wrapper for parsed model workspace planning.
  blaiPlanParsedForwardModelWorkspaceInto(
    parsed, layers, baseAddress, result, alignment)

proc blaiPlanParsedForwardModelWorkspaceInto*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuParsedLayerState],
    baseAddress: uint32,
    outResult: var BlaiParsedForwardModelPlan,
    alignment: uint32 = 16'u32) =
  ## Plan reusable forward_NPU resources from parsed layer state entries.
  outResult = default(BlaiParsedForwardModelPlan)
  blaiParsedForwardModelReadinessInto(parsed, layers, outResult.readiness)
  if not outResult.readiness.forwardReady:
    return

  let layerCount = blaiBoundedU32Count(outResult.readiness.layerCount, layers.len)
  if layerCount > 0:
    let layerWindow =
      blaiParsedForwardLayerWindow(layerCount.uint32, layers.len)
    if not layerWindow.valid:
      return
    blaiPlanForwardModelResourcesInto(
      layers.toOpenArray(layerWindow.startIndex, layerWindow.stopIndex),
      outResult.readiness.useTflite, outResult.resources)
  else:
    outResult.resources.supported = true
  blaiPlanForwardModelWorkspaceInto(
    outResult.resources, baseAddress, outResult.workspace, alignment)
  outResult.planned = outResult.resources.supported
  outResult.workspaceReady = outResult.planned and
    outResult.workspace.supported and outResult.workspace.fits

proc blaiPlanParsedForwardModelWorkspace*(
    parsed: BlaiCpuModelParseResult,
    layers: openArray[BlaiCpuParsedLayerState],
    baseAddress: uint32,
    alignment: uint32 = 16'u32): BlaiParsedForwardModelPlan =
  ## Convenience result-returning wrapper for parsed-state workspace planning.
  blaiPlanParsedForwardModelWorkspaceInto(
    parsed, layers, baseAddress, result, alignment)

proc blaiParseAndPlanForwardModelWorkspaceInto*(
    stream: openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuInstLayer64],
    baseAddress: uint32,
    outResult: var BlaiCpuModelForwardWorkspaceParsePlan,
    alignment: uint32 = 16'u32) =
  ## Parse a raw CPU/DSP instruction stream, then plan forward_NPU workspace.
  ##
  ## Raw CPU model records do not include allocator/encoder output fields, so
  ## the returned plan may legitimately report `forwardReady == false` until
  ## those fields are filled by the recovered encoder path.
  outResult = default(BlaiCpuModelForwardWorkspaceParsePlan)
  blaiParseCpuModelInstructionsInto(stream, layers, outResult.parsed)
  blaiPlanParsedForwardModelWorkspaceInto(
    outResult.parsed, layers, baseAddress, outResult.plan, alignment)

proc blaiParseAndPlanForwardModelWorkspace*(
    stream: openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuInstLayer64],
    baseAddress: uint32,
    alignment: uint32 = 16'u32): BlaiCpuModelForwardWorkspaceParsePlan =
  ## Convenience result-returning wrapper for parse-and-plan.
  blaiParseAndPlanForwardModelWorkspaceInto(
    stream, layers, baseAddress, result, alignment)

proc blaiParseAndPlanForwardModelWorkspaceInto*(
    stream: openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuParsedLayerState],
    baseAddress: uint32,
    outResult: var BlaiCpuModelForwardWorkspaceParsePlan,
    alignment: uint32 = 16'u32) =
  ## Parse raw CPU/DSP records into parsed layer state, then plan workspace.
  outResult = default(BlaiCpuModelForwardWorkspaceParsePlan)
  blaiParseCpuModelInstructionsInto(stream, layers, outResult.parsed)
  blaiPlanParsedForwardModelWorkspaceInto(
    outResult.parsed, layers, baseAddress, outResult.plan, alignment)

proc blaiParseAndPlanForwardModelWorkspace*(
    stream: openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuParsedLayerState],
    baseAddress: uint32,
    alignment: uint32 = 16'u32): BlaiCpuModelForwardWorkspaceParsePlan =
  ## Convenience result-returning wrapper for parsed-state parse-and-plan.
  blaiParseAndPlanForwardModelWorkspaceInto(
    stream, layers, baseAddress, result, alignment)

proc blaiForwardWorkspaceSegmentFitsInto*(
    segment: BlaiForwardModelWorkspaceSegment,
    bufferBytes: uint32,
    outResult: var BlaiForwardWorkspaceSegmentFitResult) =
  ## Check one workspace segment against caller-owned byte storage.
  outResult = default(BlaiForwardWorkspaceSegmentFitResult)
  outResult.active = segment.active
  outResult.segmentFits = segment.fits
  outResult.offset = segment.offset
  outResult.bytes = segment.bytes
  if not segment.active:
    outResult.bufferFits = true
    outResult.firstBlock = blaiForwardWorkspaceSegmentNoBlock
    outResult.fits = true
    return
  if not segment.fits:
    outResult.firstBlock = blaiForwardWorkspaceSegmentLayout
    return
  var layoutFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(
    high(uint32), segment.offset, segment.bytes, layoutFit)
  outResult.requiredBytes = layoutFit.requiredCount
  if not layoutFit.fits:
    outResult.firstBlock = blaiForwardWorkspaceSegmentLayout
    return
  var bufferFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(bufferBytes, segment.offset, segment.bytes, bufferFit)
  outResult.bufferFits = bufferFit.fits
  if outResult.bufferFits:
    outResult.firstBlock = blaiForwardWorkspaceSegmentNoBlock
  else:
    outResult.firstBlock = blaiForwardWorkspaceSegmentBuffer
  outResult.fits = outResult.bufferFits

proc blaiForwardWorkspaceSegmentFits*(
    segment: BlaiForwardModelWorkspaceSegment,
    bufferBytes: uint32): bool =
  ## Boolean wrapper for one workspace segment fit check.
  var fit: BlaiForwardWorkspaceSegmentFitResult
  blaiForwardWorkspaceSegmentFitsInto(segment, bufferBytes, fit)
  fit.fits

proc blaiForwardWorkspaceFitReadinessInto*(
    fit: BlaiForwardWorkspaceFitResult,
    outResult: var BlaiForwardWorkspaceFitReadiness) =
  ## Derive the complete reusable-workspace byte-storage fit gate.
  outResult = default(BlaiForwardWorkspaceFitReadiness)
  outResult.supported = fit.supported
  outResult.layoutFits = fit.layoutFits
  outResult.instructionFits = fit.instructionFits
  outResult.dataFits = fit.dataFits
  outResult.weightFits = fit.weightFits
  outResult.biasFits = fit.biasFits
  outResult.temporaryWeightsFit = fit.temporaryWeightsFit
  if not outResult.supported:
    outResult.firstBlock = blaiForwardWorkspaceUnsupported
  elif not outResult.layoutFits:
    outResult.firstBlock = blaiForwardWorkspaceLayout
  elif not outResult.instructionFits:
    outResult.firstBlock = blaiForwardWorkspaceInstruction
  elif not outResult.dataFits:
    outResult.firstBlock = blaiForwardWorkspaceData
  elif not outResult.weightFits:
    outResult.firstBlock = blaiForwardWorkspaceWeight
  elif not outResult.biasFits:
    outResult.firstBlock = blaiForwardWorkspaceBias
  elif not outResult.temporaryWeightsFit:
    outResult.firstBlock = blaiForwardWorkspaceTemporaryWeights
  else:
    outResult.firstBlock = blaiForwardWorkspaceNoBlock
  outResult.fits =
    outResult.supported and outResult.layoutFits and
    outResult.instructionFits and outResult.dataFits and
    outResult.weightFits and outResult.biasFits and
    outResult.temporaryWeightsFit

proc blaiForwardWorkspaceFitReadiness*(
    fit: BlaiForwardWorkspaceFitResult): BlaiForwardWorkspaceFitReadiness =
  ## Convenience wrapper for complete reusable-workspace fit readiness.
  blaiForwardWorkspaceFitReadinessInto(fit, result)

proc blaiForwardWorkspaceFitsInto*(
    workspace: BlaiForwardModelWorkspacePlan,
    bufferBytes: uint32,
    outResult: var BlaiForwardWorkspaceFitResult) =
  ## Check every active reusable workspace segment against byte storage.
  outResult = default(BlaiForwardWorkspaceFitResult)
  outResult.supported = workspace.supported
  outResult.layoutFits = workspace.fits
  var segmentFit: BlaiForwardWorkspaceSegmentFitResult
  blaiForwardWorkspaceSegmentFitsInto(
    workspace.instruction, bufferBytes, segmentFit)
  outResult.instructionFits = segmentFit.fits
  blaiForwardWorkspaceSegmentFitsInto(workspace.data, bufferBytes, segmentFit)
  outResult.dataFits = segmentFit.fits
  blaiForwardWorkspaceSegmentFitsInto(workspace.weight, bufferBytes, segmentFit)
  outResult.weightFits = segmentFit.fits
  blaiForwardWorkspaceSegmentFitsInto(workspace.bias, bufferBytes, segmentFit)
  outResult.biasFits = segmentFit.fits
  blaiForwardWorkspaceSegmentFitsInto(
    workspace.temporaryWeights, bufferBytes, segmentFit)
  outResult.temporaryWeightsFit = segmentFit.fits
  blaiForwardWorkspaceFitReadinessInto(outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.fits = outResult.readiness.fits

proc blaiForwardWorkspaceFits*(
    workspace: BlaiForwardModelWorkspacePlan,
    bufferBytes: uint32): bool =
  ## Boolean wrapper for complete forward workspace fit checks.
  var fit: BlaiForwardWorkspaceFitResult
  blaiForwardWorkspaceFitsInto(workspace, bufferBytes, fit)
  fit.fits

proc blaiForwardWorkspaceBufferBytes(bufferLen: int): uint32 =
  ## Semantic alias for reusable-workspace caller-owned byte capacity.
  blaiBufferLenU32(bufferLen)

proc blaiForwardWorkspaceSegmentWindow(
    segment: BlaiForwardModelWorkspaceSegment,
    requestedBytes: uint32,
    bufferLen: int): BlaiForwardWorkspaceSegmentWindow =
  ## Resolve a typed workspace segment to a checked byte-window.
  ##
  ## Callers keep working with `BlaiForwardModelWorkspaceSegment`; this is the
  ## only local conversion from segment offset/length to byte-array indexes.
  result.segment = segment
  result.requestedBytes = requestedBytes
  result.active = segment.active
  result.segmentFits = segment.fits
  if bufferLen < 0 or not segment.active or not segment.fits:
    return
  if requestedBytes > segment.bytes:
    return
  result.requestFits = true
  let window = blaiCheckedIntByteWindow(segment.offset, requestedBytes)
  if not window.fits:
    return
  let rangeFit = blaiUint32AddressRangeFit(segment.offset, requestedBytes)
  if not rangeFit.fits or rangeFit.endExclusive > bufferLen.uint64:
    return
  result.bufferFits = true
  result.start = window.start
  result.count = window.count
  result.fits = true

proc blaiForwardWorkspaceSegmentByteWindow(
    segment: BlaiForwardModelWorkspaceSegment,
    requestedBytes, bufferBytes: uint32): BlaiForwardWorkspaceSegmentWindow =
  ## Resolve a typed workspace segment when the caller's capacity is already in
  ## the recovered uint32 byte-count domain.
  let capacityWindow = blaiCheckedIntByteWindow(0'u32, bufferBytes)
  if not capacityWindow.fits:
    result.segment = segment
    result.requestedBytes = requestedBytes
    result.active = segment.active
    result.segmentFits = segment.fits
    result.requestFits =
      segment.active and segment.fits and requestedBytes <= segment.bytes
    return
  blaiForwardWorkspaceSegmentWindow(
    segment, requestedBytes, capacityWindow.count)

proc blaiForwardWorkspaceSegmentWindowMatches*(
    window: BlaiForwardWorkspaceSegmentWindow,
    offset, bytes: uint32): bool =
  ## Compare a Nim workspace byte window with a recovered uint32 byte range.
  var start, count: int
  if not blaiU32ExactIntCount(offset, start):
    return false
  if not blaiU32ExactIntCount(bytes, count):
    return false
  result = window.start == start and window.count == count

template blaiForwardWorkspaceSegmentOpenArray(buffer: untyped,
    window: BlaiForwardWorkspaceSegmentWindow): untyped =
  buffer.toOpenArray(window.start, window.start + window.count - 1)

proc blaiForwardWorkspaceRelativeByteOffset*(relativeOffset: uint32,
                                             outOffset: var int): bool =
  ## Resolve one segment-relative byte offset before combining with a window.
  if relativeOffset == high(uint32):
    return false
  blaiU32ExactIntCount(relativeOffset, outOffset)

proc blaiForwardWorkspaceLe32LaneOffset*(relativeOffset: uint32,
                                         cursor: BlaiLe32ByteCursor,
                                         outOffset: var uint32): bool =
  ## Resolve one LE32 byte lane as a segment-relative uint32 offset.
  if not cursor.valid:
    return false
  var lane: uint32
  if not blaiU64ExactU32Count(cursor.byteIndex.uint64, lane):
    return false
  var fit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), relativeOffset, lane, fit)
  if not fit.fits:
    return false
  outOffset = fit.requiredCount
  true

proc blaiForwardWorkspaceAbsoluteOffset*(baseOffset: uint32,
                                         relativeBytes: uint64,
                                         outOffset: var uint32): bool =
  ## Resolve a recovered workspace base plus relative byte count exactly.
  var relativeOffset: uint32
  if not blaiU64ExactU32Count(relativeBytes, relativeOffset):
    return false
  var fit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), baseOffset, relativeOffset, fit)
  if not fit.fits:
    return false
  outOffset = fit.requiredCount
  true

proc blaiForwardWorkspaceSegmentByteIndex(
    segment: BlaiForwardModelWorkspaceSegment,
    bufferLen: int,
    relativeOffset: uint32,
    index: var int): bool =
  ## Resolve one byte inside a typed workspace segment to a checked array index.
  var offsetIndex: int
  if not blaiForwardWorkspaceRelativeByteOffset(relativeOffset, offsetIndex):
    return false
  let window =
    blaiForwardWorkspaceSegmentWindow(segment, relativeOffset + 1'u32, bufferLen)
  if not window.fits:
    return false
  index = window.start + offsetIndex
  true

proc blaiReadForwardWorkspaceSegmentByte*(
    segment: BlaiForwardModelWorkspaceSegment,
    buffer: openArray[uint8],
    relativeOffset: uint32,
    value: var uint8): bool =
  ## Read one byte from a caller-owned workspace segment using a relative
  ## segment offset, not a raw workspace-array index.
  var index: int
  if not blaiForwardWorkspaceSegmentByteIndex(
      segment, buffer.len, relativeOffset, index):
    return false
  value = buffer[index]
  true

proc blaiWriteForwardWorkspaceSegmentByte*(
    segment: BlaiForwardModelWorkspaceSegment,
    buffer: var openArray[uint8],
    relativeOffset: uint32,
    value: uint8): bool =
  ## Write one byte to a caller-owned workspace segment using a relative
  ## segment offset, not a raw workspace-array index.
  var index: int
  if not blaiForwardWorkspaceSegmentByteIndex(
      segment, buffer.len, relativeOffset, index):
    return false
  buffer[index] = value
  true

proc blaiNpuBiasWordByteCount*(outCount: var int): bool =
  ## Resolve the recovered NPU bias word byte size for little-endian loops.
  blaiU32ExactIntCount(BlaiNpuBiasElementBytes, outCount)

proc blaiReadForwardWorkspaceSegmentLe32*(
    segment: BlaiForwardModelWorkspaceSegment,
    buffer: openArray[uint8],
    relativeOffset: uint32,
    value: var uint32): bool =
  ## Read one little-endian uint32 from a typed workspace segment.
  if relativeOffset > high(uint32) - (BlaiNpuBiasElementBytes - 1'u32):
    return false
  value = 0
  var byteCount: int
  if not blaiNpuBiasWordByteCount(byteCount):
    return false
  for byteIndex in 0 ..< byteCount:
    let cursor = blaiLe32ByteCursor(byteIndex)
    if not cursor.valid:
      return false
    var laneOffset: uint32
    if not blaiForwardWorkspaceLe32LaneOffset(
        relativeOffset, cursor, laneOffset):
      return false
    var byte: uint8
    if not blaiReadForwardWorkspaceSegmentByte(
        segment, buffer, laneOffset, byte):
      return false
    blaiLe32MergeByte(value, byte, cursor)
  true

proc blaiWriteForwardWorkspaceSegmentLe32*(
    segment: BlaiForwardModelWorkspaceSegment,
    buffer: var openArray[uint8],
    relativeOffset: uint32,
    value: uint32): bool =
  ## Write one little-endian uint32 into a typed workspace segment.
  if relativeOffset > high(uint32) - (BlaiNpuBiasElementBytes - 1'u32):
    return false
  var byteCount: int
  if not blaiNpuBiasWordByteCount(byteCount):
    return false
  for byteIndex in 0 ..< byteCount:
    let cursor = blaiLe32ByteCursor(byteIndex)
    if not cursor.valid:
      return false
    var laneOffset: uint32
    if not blaiForwardWorkspaceLe32LaneOffset(
        relativeOffset, cursor, laneOffset):
      return false
    if not blaiWriteForwardWorkspaceSegmentByte(
        segment, buffer, laneOffset, blaiLe32Byte(value, cursor)):
      return false
  true

proc blaiForwardWorkspaceSegmentLe32Equals*(
    segment: BlaiForwardModelWorkspaceSegment,
    buffer: openArray[uint8],
    relativeOffset: uint32,
    expected: uint32): bool =
  ## Compare one little-endian uint32 inside a typed workspace segment.
  var actual: uint32
  blaiReadForwardWorkspaceSegmentLe32(
    segment, buffer, relativeOffset, actual) and actual == expected

proc blaiForwardWorkspaceSegmentByteEquals*(
    segment: BlaiForwardModelWorkspaceSegment,
    buffer: openArray[uint8],
    relativeOffset: uint32,
    expected: uint8): bool =
  ## Compare one byte inside a typed workspace segment.
  var actual: uint8
  blaiReadForwardWorkspaceSegmentByte(segment, buffer, relativeOffset, actual) and
    actual == expected

proc blaiUintAddressInRange*(address, base, size: uint): bool =
  ## Check an address against a half-open range without overflowing base + size.
  size != 0 and address >= base and address - base < size

doAssert blaiUintAddressInRange(0x1004'u, 0x1000'u, 8'u)
doAssert not blaiUintAddressInRange(0x1008'u, 0x1000'u, 8'u)
doAssert blaiUintAddressInRange(high(uint), high(uint) - 3'u, 4'u)

proc blaiProjectHardwareAddress*(address: uint): BlaiHardwareAddressProjection =
  ## Project CPU-visible RAM aliases to addresses suitable for hardware DMA.
  result.originalAddress = address
  template projectCached(cachedBase, size: untyped): bool =
    blaiUintAddressInRange(address, cachedBase.uint, size.uint)
  template directRange(base, size: untyped): bool =
    blaiUintAddressInRange(address, base.uint, size.uint)
  if projectCached(OcramCachedBase, OcramSize):
    result.hardwareAddress =
      (OcramBase + (address - OcramCachedBase.uint)).uint32
    result.alias = blaiHardwareAddressOcramCached
    result.addressFits = true
    result.projected = true
  elif projectCached(WramCachedBase, WramSize):
    result.hardwareAddress =
      (WramBase + (address - WramCachedBase.uint)).uint32
    result.alias = blaiHardwareAddressWramCached
    result.addressFits = true
    result.projected = true
  elif projectCached(DramCachedBase, DramSize):
    result.hardwareAddress =
      (DramBase + (address - DramCachedBase.uint)).uint32
    result.alias = blaiHardwareAddressDramCached
    result.addressFits = true
    result.projected = true
  elif projectCached(VramCachedBase, VramSize):
    result.hardwareAddress =
      (VramBase + (address - VramCachedBase.uint)).uint32
    result.alias = blaiHardwareAddressVramCached
    result.addressFits = true
    result.projected = true
  elif directRange(OcramBase, OcramSize) or
      directRange(WramBase, WramSize) or
      directRange(DramBase, DramSize) or
      directRange(VramBase, VramSize) or
      directRange(PsramBase, PsramSize):
    result.hardwareAddress = address.uint32
    result.alias = blaiHardwareAddressDirect
    result.addressFits = true
    result.projected = true
  elif address <= high(uint32).uint:
    result.alias = blaiHardwareAddressUnsupported
  else:
    result.alias = blaiHardwareAddressTooWide

proc blaiRawByteAddress(byte: var uint8): uint =
  ## Localize the only byte-buffer object-address extraction used by live NPU DMA.
  cast[uint](unsafeAddr byte)

proc blaiProjectFirstByteAddress(buffer: var openArray[uint8]):
    BlaiHardwareAddressProjection =
  ## Project the first byte of caller-owned storage to a BLAI-visible address.
  ##
  ## Callers keep typed storage and receive a typed projection result instead of
  ## doing pointer arithmetic themselves; raw address extraction is isolated in
  ## `blaiRawByteAddress`.
  if buffer.len <= 0:
    return
  when nimvm:
    discard buffer
  else:
    result = blaiProjectHardwareAddress(blaiRawByteAddress(buffer[0]))

proc blaiForwardWorkspaceBufferBaseAddress(
    buffer: var openArray[uint8],
    addressAvailable: var bool,
    addressFits: var bool): uint32 =
  ## Return the base address for caller-owned workspace storage.
  ##
  ## The address cast is intentionally localized here: BLAI registers consume
  ## 32-bit addresses, while higher-level callers work with typed buffers.
  addressAvailable = buffer.len > 0
  addressFits = false
  if not addressAvailable:
    return 0'u32
  when nimvm:
    discard buffer
    return 0'u32
  else:
    let projected = blaiProjectFirstByteAddress(buffer)
    addressFits = projected.addressFits
    projected.hardwareAddress

proc blaiProjectWorkspaceBufferAddress*[N: static[int]](
    buffer: var array[N, uint8]): BlaiHardwareAddressProjection =
  ## Project a fixed Nim workspace byte array to a hardware-visible base.
  ##
  ## This keeps the required address cast at the typed NPU boundary for callers
  ## that need to pass an explicit workspace base into BLAI register planning.
  if N <= 0:
    return
  when nimvm:
    discard buffer
  else:
    result = blaiProjectFirstByteAddress(buffer.toOpenArray(0, N - 1))

proc blaiAddressInWram(address: uint32): bool =
  blaiUintAddressInRange(address.uint, WramBase.uint, WramSize.uint)

proc blaiUint32AddressSpanInRange*(address, bytes, base, size: uint32): bool =
  ## Return true when a non-empty 32-bit bus byte span is contained in a range.
  if bytes == 0'u32:
    return false
  let fit = blaiUint32AddressRangeFit(address, bytes)
  if not fit.fits:
    return false
  address >= base and fit.endExclusive <= base.uint64 + size.uint64

proc blaiUint32AddressSpanInWram*(address, bytes: uint32): bool =
  ## Return true when a non-empty 32-bit bus byte span is fully WRAM-visible.
  blaiUint32AddressSpanInRange(address, bytes, WramBase.uint32, WramSize.uint32)

proc blaiForwardWorkspaceWramEvidenceInto*(
    projection: BlaiHardwareAddressProjection,
    workspace: BlaiForwardModelWorkspacePlan,
    outResult: var BlaiForwardWorkspaceWramEvidence) =
  ## Derive evidence that projected reusable workspace storage is in WRAM.
  outResult = default(BlaiForwardWorkspaceWramEvidence)
  outResult.projected = projection.projected
  outResult.addressFits = projection.addressFits
  outResult.aliasMatches = projection.alias == blaiHardwareAddressWramCached
  outResult.baseInWram = blaiAddressInWram(projection.hardwareAddress)
  outResult.projectionValid =
    outResult.projected and outResult.addressFits and outResult.aliasMatches and
      outResult.baseInWram
  outResult.instructionInWram = blaiAddressInWram(workspace.instruction.address)
  outResult.dataInWram = blaiAddressInWram(workspace.data.address)
  outResult.weightInWram = blaiAddressInWram(workspace.weight.address)
  outResult.biasInWram = blaiAddressInWram(workspace.bias.address)
  outResult.segmentsInWram =
    outResult.instructionInWram and outResult.dataInWram and
      outResult.weightInWram and outResult.biasInWram
  outResult.valid =
    outResult.projectionValid and outResult.segmentsInWram

proc blaiForwardWorkspaceWramEvidence*(
    projection: BlaiHardwareAddressProjection,
    workspace: BlaiForwardModelWorkspacePlan): BlaiForwardWorkspaceWramEvidence =
  ## Convenience wrapper for WRAM-visible workspace evidence.
  blaiForwardWorkspaceWramEvidenceInto(projection, workspace, result)

proc blaiLe32ByteCursor*(byteIndex: int): BlaiLe32ByteCursor =
  ## Resolve one byte lane inside a little-endian uint32 word.
  var byteCount: int
  if not blaiNpuBiasWordByteCount(byteCount):
    return
  if byteIndex < 0 or byteIndex >= byteCount:
    return
  result.byteIndex = byteIndex
  result.shift = (byteIndex * 8).uint32
  result.mask = 0xFF'u32
  result.valid = true

proc blaiLe32Byte*(value: uint32, cursor: BlaiLe32ByteCursor): uint8 =
  ## Extract the cursor-selected byte from a little-endian uint32 word.
  doAssert cursor.valid
  ((value shr cursor.shift) and cursor.mask).uint8

proc blaiLe32MergeByte*(value: var uint32,
                        byte: uint8,
                        cursor: BlaiLe32ByteCursor) =
  ## Merge one cursor-selected byte into a little-endian uint32 word.
  doAssert cursor.valid
  value = value or (byte.uint32 shl cursor.shift)

proc blaiInt32Bits(value: int32): uint32 =
  let wide = value.int64
  if wide < 0:
    (wide + 0x1_0000_0000'i64).uint64.uint32
  else:
    wide.uint64.uint32

proc blaiCheckedByteWindow(bufferLen: int,
                           offset, bytes: uint32): BlaiCheckedByteWindow =
  ## Resolve one byte subrange to a checked openArray window descriptor.
  if bufferLen < 0:
    return
  let window = blaiCheckedIntByteWindow(offset, bytes)
  if not window.fits:
    return
  let rangeFit = blaiUint32AddressRangeFit(offset, bytes)
  if not rangeFit.fits or rangeFit.endExclusive > bufferLen.uint64:
    return
  result.fits = true
  result.start = window.start
  result.count = window.count

template blaiCheckedByteOpenArray(buffer: untyped,
                                  window: BlaiCheckedByteWindow): untyped =
  buffer.toOpenArray(window.start, window.start + window.count - 1)

proc blaiStoreLe32(buffer: var openArray[uint8],
                   offset: uint32,
                   value: uint32): bool =
  let word = blaiCheckedByteWindow(buffer.len, offset, BlaiNpuBiasElementBytes)
  var byteCount: int
  if not blaiNpuBiasWordByteCount(byteCount):
    return false
  if not word.fits or word.count != byteCount:
    return false
  for byteIndex in 0 ..< byteCount:
    let cursor = blaiLe32ByteCursor(byteIndex)
    if not cursor.valid:
      return false
    blaiCheckedByteOpenArray(buffer, word)[cursor.byteIndex] =
      blaiLe32Byte(value, cursor)
  true

proc blaiLoadLe32(buffer: openArray[uint8],
                  offset: uint32,
                  value: var uint32): bool =
  let word = blaiCheckedByteWindow(buffer.len, offset, BlaiNpuBiasElementBytes)
  var byteCount: int
  if not blaiNpuBiasWordByteCount(byteCount):
    return false
  if not word.fits or word.count != byteCount:
    return false
  value = 0
  for byteIndex in 0 ..< byteCount:
    let cursor = blaiLe32ByteCursor(byteIndex)
    if not cursor.valid:
      return false
    blaiLe32MergeByte(
      value, blaiCheckedByteOpenArray(buffer, word)[cursor.byteIndex], cursor)
  true

proc blaiGeneratedModelFixtureByteCursor*(
    sectionOffset: uint32,
    relativeIndex: int,
    bufferLen: int): BlaiGeneratedModelFixtureByteCursor =
  ## Resolve a generated-model fixture byte without open-coded base arithmetic.
  if relativeIndex < 0 or bufferLen < 0:
    return
  var absoluteOffset: uint32
  var fit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(
    high(uint32), sectionOffset, relativeIndex.uint32, fit)
  if not fit.fits:
    return
  absoluteOffset = fit.requiredCount
  let window = blaiCheckedByteWindow(bufferLen, absoluteOffset, 1'u32)
  if not window.fits:
    return
  result.sectionOffset = sectionOffset
  result.relativeIndex = relativeIndex
  result.absoluteIndex = window.start
  result.valid = true

proc blaiStoreGeneratedModelFixtureByte*(
    buffer: var openArray[uint8],
    sectionOffset: uint32,
    relativeIndex: int,
    value: uint8): bool =
  ## Store one generated-model fixture byte through the checked fixture cursor.
  let cursor =
    blaiGeneratedModelFixtureByteCursor(
      sectionOffset, relativeIndex, buffer.len)
  if not cursor.valid:
    return false
  buffer[cursor.absoluteIndex] = value
  true

proc blaiGeneratedModelDirectoryWordCursor*(wordIndex: uint32):
    BlaiGeneratedModelDirectoryWordCursor =
  ## Resolve one word in the four-word generated model directory entry.
  let byteOffset = wordIndex.uint64 * BlaiNpuBiasElementBytes.uint64
  if byteOffset + BlaiNpuBiasElementBytes.uint64 > BlaiInstructionSize.uint64:
    return
  result.wordIndex = wordIndex
  result.byteOffset = byteOffset.uint32
  result.valid = true

proc blaiLoadGeneratedModelDirectoryWord(
    blob: openArray[uint8],
    entryOffset, wordIndex: uint32,
    value: var uint32): bool =
  ## Load one checked little-endian word from a generated-model directory entry.
  let cursor = blaiGeneratedModelDirectoryWordCursor(wordIndex)
  if not cursor.valid:
    return false
  let absoluteOffset = entryOffset.uint64 + cursor.byteOffset.uint64
  if absoluteOffset > high(uint32).uint64:
    return false
  blaiLoadLe32(blob, absoluteOffset.uint32, value)

proc blaiGeneratedModelDirectoryEntryInto*(
    blob: openArray[uint8],
    offset: uint32,
    outEntry: var BlaiGeneratedModelDirectoryEntry) =
  ## Decode one generated-model directory entry from a byte buffer.
  ##
  ## The generated C headers expose the model as bytes. This parser treats the
  ## front matter as a typed little-endian directory and keeps all bounds checks
  ## in byte-index form.
  outEntry = default(BlaiGeneratedModelDirectoryEntry)
  let entryRange = blaiUint32AddressRangeFit(offset, BlaiInstructionSize.uint32)
  outEntry.entryRangeFits = entryRange.fits
  if not outEntry.entryRangeFits:
    outEntry.firstBlock = blaiGeneratedModelDirectoryEntryRange
    return
  var w0, w1, w2, w3: uint32
  if not blaiLoadGeneratedModelDirectoryWord(blob, offset, 0'u32, w0):
    outEntry.firstBlock = blaiGeneratedModelDirectoryEntryWord0
    return
  if not blaiLoadGeneratedModelDirectoryWord(blob, offset, 1'u32, w1):
    outEntry.firstBlock = blaiGeneratedModelDirectoryEntryWord1
    return
  if not blaiLoadGeneratedModelDirectoryWord(blob, offset, 2'u32, w2):
    outEntry.firstBlock = blaiGeneratedModelDirectoryEntryWord2
    return
  if not blaiLoadGeneratedModelDirectoryWord(blob, offset, 3'u32, w3):
    outEntry.firstBlock = blaiGeneratedModelDirectoryEntryWord3
    return
  outEntry.wordsLoaded = true
  outEntry.prefixBytes = w0
  outEntry.recoveredWord1 = w1
  outEntry.recoveredWord2 = w2
  outEntry.recoveredWord3 = w3
  outEntry.active = w0 != 0'u32
  outEntry.prefixAligned = (w0 and (BlaiInstructionSize.uint32 - 1'u32)) == 0'u32
  outEntry.prefixWithinBlob = w0 <= blaiBufferLenU32(blob.len)
  if not outEntry.active:
    outEntry.firstBlock = blaiGeneratedModelDirectoryEntryInactive
  elif not outEntry.prefixAligned:
    outEntry.firstBlock = blaiGeneratedModelDirectoryEntryAlignment
  elif not outEntry.prefixWithinBlob:
    outEntry.firstBlock = blaiGeneratedModelDirectoryEntryBlobBounds
  else:
    outEntry.firstBlock = blaiGeneratedModelDirectoryEntryNoBlock
  outEntry.valid =
    outEntry.entryRangeFits and outEntry.wordsLoaded and outEntry.active and
      outEntry.prefixAligned and outEntry.prefixWithinBlob and
      outEntry.firstBlock == blaiGeneratedModelDirectoryEntryNoBlock

proc blaiGeneratedModelDirectoryEntry*(
    blob: openArray[uint8],
    offset: uint32): BlaiGeneratedModelDirectoryEntry =
  ## Convenience wrapper for one generated-model directory entry.
  blaiGeneratedModelDirectoryEntryInto(blob, offset, result)

proc blaiGeneratedModelDirectoryInto*(
    blob: openArray[uint8],
    outDirectory: var BlaiGeneratedModelDirectory) =
  ## Decode the generated `blai_model_bin[]` front directory.
  ##
  ## A second directory entry is considered present only when both byte-0 and
  ## byte-16 entries are valid and the byte-0 prefix extends beyond the byte-16
  ## prefix. This matches the recovered SDK generated fixtures without naming
  ## the still-unexplained directory scalar fields.
  outDirectory = default(BlaiGeneratedModelDirectory)
  outDirectory.blobBytes = blaiBufferLenU32(blob.len)
  blaiGeneratedModelDirectoryEntryInto(blob, 0'u32, outDirectory.prefix)
  blaiGeneratedModelDirectoryEntryInto(
    blob, BlaiInstructionSize.uint32, outDirectory.cpu)
  let secondEntryLooksCpu =
    outDirectory.cpu.active and outDirectory.cpu.prefixAligned
  outDirectory.hasPrefixDirectory =
    outDirectory.prefix.active and outDirectory.prefix.prefixAligned and
      secondEntryLooksCpu and
      outDirectory.prefix.prefixBytes > outDirectory.cpu.prefixBytes
  if not outDirectory.hasPrefixDirectory and not secondEntryLooksCpu:
    outDirectory.cpu = outDirectory.prefix
  outDirectory.firstPayloadBoundary =
    if outDirectory.hasPrefixDirectory:
      outDirectory.prefix.prefixBytes
    else:
      outDirectory.cpu.prefixBytes
  outDirectory.firstPayloadBoundaryValid =
    outDirectory.firstPayloadBoundary != 0'u32 and
      outDirectory.firstPayloadBoundary <= outDirectory.blobBytes
  outDirectory.cpuFirstBlock = outDirectory.cpu.firstBlock
  if not outDirectory.cpu.valid:
    outDirectory.firstBlock = blaiGeneratedModelDirectoryCpuEntry
  elif not outDirectory.firstPayloadBoundaryValid:
    outDirectory.firstBlock = blaiGeneratedModelDirectoryPayloadBoundary
  else:
    outDirectory.firstBlock = blaiGeneratedModelDirectoryNoBlock
  outDirectory.valid = outDirectory.cpu.valid and
    outDirectory.firstPayloadBoundaryValid and
    outDirectory.firstBlock == blaiGeneratedModelDirectoryNoBlock

proc blaiGeneratedModelDirectory*(
    blob: openArray[uint8]): BlaiGeneratedModelDirectory =
  ## Convenience wrapper for the generated model directory.
  blaiGeneratedModelDirectoryInto(blob, result)

proc blaiGeneratedModelSectionWindowInto*(
    blobBytes, offset, endExclusive: uint32,
    outWindow: var BlaiGeneratedModelSectionWindow) =
  ## Resolve one generated-model section as a checked byte window.
  outWindow = default(BlaiGeneratedModelSectionWindow)
  outWindow.offset = offset
  outWindow.endExclusive = endExclusive
  outWindow.active = endExclusive != offset
  outWindow.ordered = endExclusive >= offset
  if outWindow.ordered:
    outWindow.bytes = endExclusive - offset
    let fit = blaiUint32AddressRangeFit(offset, outWindow.bytes)
    outWindow.rangeFits = fit.fits
    outWindow.withinBlob = outWindow.rangeFits and
      fit.endExclusive <= blobBytes.uint64
  if not outWindow.active:
    outWindow.firstBlock = blaiGeneratedModelSectionWindowInactive
  elif not outWindow.ordered:
    outWindow.firstBlock = blaiGeneratedModelSectionWindowOrder
  elif not outWindow.rangeFits:
    outWindow.firstBlock = blaiGeneratedModelSectionWindowRange
  elif not outWindow.withinBlob:
    outWindow.firstBlock = blaiGeneratedModelSectionWindowBlobBounds
  else:
    outWindow.firstBlock = blaiGeneratedModelSectionWindowNoBlock
  outWindow.valid = outWindow.active and outWindow.ordered and
    outWindow.rangeFits and outWindow.withinBlob and
    outWindow.firstBlock == blaiGeneratedModelSectionWindowNoBlock

proc blaiGeneratedModelSectionWindow*(
    blobBytes, offset, endExclusive: uint32):
    BlaiGeneratedModelSectionWindow =
  ## Convenience wrapper for one generated-model section window.
  blaiGeneratedModelSectionWindowInto(blobBytes, offset, endExclusive, result)

proc blaiGeneratedModelSectionFromSizeInto(
    blobBytes: uint32,
    offset: var uint32,
    bytes: uint32,
    outWindow: var BlaiGeneratedModelSectionWindow): bool =
  ## Resolve one generated-model payload section from its size-table byte count.
  var endFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), offset, bytes, endFit)
  if not endFit.fits:
    outWindow = default(BlaiGeneratedModelSectionWindow)
    outWindow.offset = offset
    outWindow.bytes = bytes
    outWindow.active = bytes != 0'u32
    outWindow.ordered = true
    outWindow.rangeFits = false
    outWindow.firstBlock = blaiGeneratedModelSectionWindowRange
    return false
  blaiGeneratedModelSectionWindowInto(
    blobBytes, offset, endFit.requiredCount, outWindow)
  offset = endFit.requiredCount
  outWindow.withinBlob

proc blaiGeneratedModelHasSecondSizeEntry(
    directory: BlaiGeneratedModelDirectory): bool =
  ## True when the decoded directory still carries the second 16-byte size row.
  directory.cpu.prefixBytes != directory.prefix.prefixBytes or
    directory.cpu.recoveredWord1 != directory.prefix.recoveredWord1 or
    directory.cpu.recoveredWord2 != directory.prefix.recoveredWord2 or
    directory.cpu.recoveredWord3 != directory.prefix.recoveredWord3

proc blaiGeneratedModelSectionPlanInto*(
    blob: openArray[uint8],
    outPlan: var BlaiGeneratedModelSectionPlan) =
  ## Recover conservative section windows from a generated model blob.
  outPlan = default(BlaiGeneratedModelSectionPlan)
  outPlan.blobBytes = blaiBufferLenU32(blob.len)
  blaiGeneratedModelDirectoryInto(blob, outPlan.directory)
  outPlan.headerBytes =
    if blaiGeneratedModelHasSecondSizeEntry(outPlan.directory):
      (2'u32 * BlaiInstructionSize.uint32)
    else:
      BlaiInstructionSize.uint32
  blaiGeneratedModelSectionWindowInto(
    outPlan.blobBytes, 0'u32, outPlan.headerBytes, outPlan.headerWindow)
  outPlan.prefixDirectoryWindow = outPlan.headerWindow

  var payloadCursor = outPlan.headerBytes
  let cpu = outPlan.directory.prefix
  let npu = outPlan.directory.cpu
  let cpuInstructionFits = blaiGeneratedModelSectionFromSizeInto(
    outPlan.blobBytes, payloadCursor, cpu.prefixBytes,
    outPlan.cpuInstructionWindow)
  outPlan.cpuInstructionFits = cpuInstructionFits
  let cpuBiasFits = blaiGeneratedModelSectionFromSizeInto(
    outPlan.blobBytes, payloadCursor, cpu.recoveredWord1,
    outPlan.cpuBiasWindow)
  outPlan.cpuBiasFits = cpuBiasFits
  let cpuWeightFits = blaiGeneratedModelSectionFromSizeInto(
    outPlan.blobBytes, payloadCursor, cpu.recoveredWord2,
    outPlan.cpuWeightWindow)
  outPlan.cpuWeightFits = cpuWeightFits
  let npuInstructionFits = blaiGeneratedModelSectionFromSizeInto(
    outPlan.blobBytes, payloadCursor, npu.prefixBytes,
    outPlan.npuInstructionWindow)
  outPlan.npuInstructionFits = npuInstructionFits
  let npuBiasFits = blaiGeneratedModelSectionFromSizeInto(
    outPlan.blobBytes, payloadCursor, npu.recoveredWord1,
    outPlan.npuBiasWindow)
  outPlan.npuBiasFits = npuBiasFits
  let npuWeightFits = blaiGeneratedModelSectionFromSizeInto(
    outPlan.blobBytes, payloadCursor, npu.recoveredWord2,
    outPlan.npuWeightWindow)
  outPlan.npuWeightFits = npuWeightFits
  outPlan.cpuRecordWindow = outPlan.cpuInstructionWindow
  outPlan.cpuAuxiliaryWindow = outPlan.cpuBiasWindow
  outPlan.cpuPayloadWindow = outPlan.cpuWeightWindow
  outPlan.payloadBytesExpected = payloadCursor
  outPlan.payloadFits =
    outPlan.headerWindow.withinBlob and cpuInstructionFits and cpuBiasFits and
      cpuWeightFits and npuInstructionFits and npuBiasFits and npuWeightFits
  outPlan.directoryFirstBlock = outPlan.directory.firstBlock
  if not outPlan.directory.valid:
    outPlan.firstBlock = blaiGeneratedModelSectionPlanDirectory
    outPlan.firstWindowBlock = blaiGeneratedModelSectionWindowNoBlock
  elif not outPlan.headerWindow.withinBlob:
    outPlan.firstBlock = blaiGeneratedModelSectionPlanHeader
    outPlan.firstWindowBlock = outPlan.headerWindow.firstBlock
  elif not cpuInstructionFits:
    outPlan.firstBlock = blaiGeneratedModelSectionPlanCpuInstruction
    outPlan.firstWindowBlock = outPlan.cpuInstructionWindow.firstBlock
  elif not cpuBiasFits:
    outPlan.firstBlock = blaiGeneratedModelSectionPlanCpuBias
    outPlan.firstWindowBlock = outPlan.cpuBiasWindow.firstBlock
  elif not cpuWeightFits:
    outPlan.firstBlock = blaiGeneratedModelSectionPlanCpuWeight
    outPlan.firstWindowBlock = outPlan.cpuWeightWindow.firstBlock
  elif not npuInstructionFits:
    outPlan.firstBlock = blaiGeneratedModelSectionPlanNpuInstruction
    outPlan.firstWindowBlock = outPlan.npuInstructionWindow.firstBlock
  elif not npuBiasFits:
    outPlan.firstBlock = blaiGeneratedModelSectionPlanNpuBias
    outPlan.firstWindowBlock = outPlan.npuBiasWindow.firstBlock
  elif not npuWeightFits:
    outPlan.firstBlock = blaiGeneratedModelSectionPlanNpuWeight
    outPlan.firstWindowBlock = outPlan.npuWeightWindow.firstBlock
  else:
    outPlan.firstBlock = blaiGeneratedModelSectionPlanNoBlock
    outPlan.firstWindowBlock = blaiGeneratedModelSectionWindowNoBlock
  outPlan.valid = outPlan.directory.valid and outPlan.payloadFits and
    outPlan.firstBlock == blaiGeneratedModelSectionPlanNoBlock

proc blaiGeneratedModelSectionPlan*(
    blob: openArray[uint8]): BlaiGeneratedModelSectionPlan =
  ## Convenience wrapper for generated-model section recovery.
  blaiGeneratedModelSectionPlanInto(blob, result)

proc blaiGeneratedModelSectionByte*(
    blob: openArray[uint8],
    section: BlaiGeneratedModelSectionWindow,
    relativeOffset: uint32,
    value: var uint8): bool =
  ## Read one byte from a recovered generated-model section.
  if not section.valid or relativeOffset >= section.bytes:
    return false
  var absoluteOffset: uint32
  var appendFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(high(uint32), section.offset, relativeOffset, appendFit)
  if not appendFit.fits:
    return false
  absoluteOffset = appendFit.requiredCount
  let window = blaiCheckedByteWindow(blob.len, absoluteOffset, 1'u32)
  if not window.fits:
    return false
  value = blaiCheckedByteOpenArray(blob, window)[0]
  true

proc blaiGeneratedModelSectionCopyByteCursor*(
    byteIndex, count: int): BlaiGeneratedModelSectionCopyByteCursor =
  ## Checked byte cursor for section copy loops and boundary-byte evidence.
  if byteIndex < 0 or count < 0 or byteIndex >= count:
    return
  result.byteIndex = byteIndex
  result.valid = true

proc blaiCopyGeneratedModelSectionInto*(
    blob: openArray[uint8],
    section: BlaiGeneratedModelSectionWindow,
    destination: var openArray[uint8],
    outResult: var BlaiGeneratedModelSectionCopyResult) =
  ## Copy one recovered generated-model section into caller-owned byte storage.
  outResult = default(BlaiGeneratedModelSectionCopyResult)
  outResult.section = section
  outResult.windowFirstBlock = section.firstBlock
  outResult.destinationBytes = blaiBufferLenU32(destination.len)
  if section.bytes == 0'u32 and section.ordered and section.withinBlob:
    outResult.sourceFits = true
    outResult.destinationFits = true
    outResult.copied = true
    outResult.firstBlock = blaiGeneratedModelSectionCopyNoBlock
    outResult.valid = true
    return
  if not section.valid:
    outResult.firstBlock = blaiGeneratedModelSectionCopySection
    return
  let sourceWindow = blaiCheckedByteWindow(blob.len, section.offset, section.bytes)
  outResult.sourceFits = sourceWindow.fits
  let destinationWindow =
    blaiCheckedByteWindow(destination.len, 0'u32, section.bytes)
  outResult.destinationFits = destinationWindow.fits
  if not outResult.sourceFits:
    outResult.firstBlock = blaiGeneratedModelSectionCopySource
    return
  if not outResult.destinationFits:
    outResult.firstBlock = blaiGeneratedModelSectionCopyDestination
    return
  for rawByteIndex in 0 ..< sourceWindow.count:
    let cursor =
      blaiGeneratedModelSectionCopyByteCursor(rawByteIndex, sourceWindow.count)
    if not cursor.valid:
      outResult.firstBlock = blaiGeneratedModelSectionCopyCursor
      return
    blaiCheckedByteOpenArray(destination, destinationWindow)[cursor.byteIndex] =
      blaiCheckedByteOpenArray(blob, sourceWindow)[cursor.byteIndex]
  outResult.copiedBytes = section.bytes
  if sourceWindow.count > 0:
    let firstCursor =
      blaiGeneratedModelSectionCopyByteCursor(0, sourceWindow.count)
    let lastCursor =
      blaiGeneratedModelSectionCopyByteCursor(
        sourceWindow.count - 1, sourceWindow.count)
    if not firstCursor.valid or not lastCursor.valid:
      outResult.firstBlock = blaiGeneratedModelSectionCopyCursor
      return
    outResult.firstByte =
      blaiCheckedByteOpenArray(blob, sourceWindow)[firstCursor.byteIndex]
    outResult.lastByte =
      blaiCheckedByteOpenArray(blob, sourceWindow)[lastCursor.byteIndex]
  outResult.copied = true
  outResult.firstBlock = blaiGeneratedModelSectionCopyNoBlock
  outResult.valid = true

proc blaiCopyGeneratedModelSection*(
    blob: openArray[uint8],
    section: BlaiGeneratedModelSectionWindow,
    destination: var openArray[uint8]): BlaiGeneratedModelSectionCopyResult =
  ## Convenience wrapper for generated-model section copying.
  blaiCopyGeneratedModelSectionInto(blob, section, destination, result)

proc blaiGeneratedNpuPayloadSectionsInto*(
    plan: BlaiGeneratedModelSectionPlan,
    outSections: var BlaiGeneratedNpuPayloadSections) =
  ## Project generated model section recovery to hardware-facing NPU payloads.
  outSections = default(BlaiGeneratedNpuPayloadSections)
  outSections.instruction = plan.npuInstructionWindow
  outSections.bias = plan.npuBiasWindow
  outSections.weight = plan.npuWeightWindow
  outSections.instructionBytes = plan.npuInstructionWindow.bytes
  outSections.biasBytes = plan.npuBiasWindow.bytes
  outSections.weightBytes = plan.npuWeightWindow.bytes
  var firstFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(
    high(uint32), outSections.instructionBytes, outSections.biasBytes, firstFit)
  outSections.instructionFits =
    plan.npuInstructionFits and plan.npuInstructionWindow.withinBlob
  outSections.biasFits = plan.npuBiasFits and plan.npuBiasWindow.withinBlob
  outSections.weightFits = plan.npuWeightFits and plan.npuWeightWindow.withinBlob
  if firstFit.fits:
    var totalFit: BlaiUint32AppendFitResult
    blaiUint32AppendFitInto(
      high(uint32), firstFit.requiredCount, outSections.weightBytes, totalFit)
    outSections.totalFits = totalFit.fits
    if totalFit.fits:
      outSections.totalBytes = totalFit.requiredCount
  outSections.payloadPresent = outSections.totalBytes != 0'u32
  outSections.payloadFits =
    plan.payloadFits and outSections.instructionFits and outSections.biasFits and
      outSections.weightFits and firstFit.fits and outSections.totalFits and
      outSections.payloadPresent
  if not plan.valid:
    outSections.firstBlock = blaiGeneratedNpuPayloadSectionsPlan
  elif not outSections.instructionFits:
    outSections.firstBlock = blaiGeneratedNpuPayloadSectionsInstruction
  elif not outSections.biasFits:
    outSections.firstBlock = blaiGeneratedNpuPayloadSectionsBias
  elif not outSections.weightFits:
    outSections.firstBlock = blaiGeneratedNpuPayloadSectionsWeight
  elif not firstFit.fits or not outSections.totalFits:
    outSections.firstBlock = blaiGeneratedNpuPayloadSectionsTotal
  elif not outSections.payloadPresent:
    outSections.firstBlock = blaiGeneratedNpuPayloadSectionsEmpty
  else:
    outSections.firstBlock = blaiGeneratedNpuPayloadSectionsNoBlock
  outSections.valid = plan.valid and outSections.payloadFits

proc blaiGeneratedNpuPayloadSections*(
    plan: BlaiGeneratedModelSectionPlan): BlaiGeneratedNpuPayloadSections =
  ## Convenience wrapper for generated NPU payload section projection.
  blaiGeneratedNpuPayloadSectionsInto(plan, result)

proc blaiCopyGeneratedNpuPayloadsInto*(
    blob: openArray[uint8],
    plan: BlaiGeneratedModelSectionPlan,
    instructions: var openArray[uint8],
    biases: var openArray[uint8],
    weights: var openArray[uint8],
    outResult: var BlaiGeneratedNpuPayloadCopyResult) =
  ## Copy generated NPU instruction, bias, and weight payloads to caller buffers.
  outResult = default(BlaiGeneratedNpuPayloadCopyResult)
  blaiGeneratedNpuPayloadSectionsInto(plan, outResult.sections)
  if not outResult.sections.valid:
    outResult.firstBlock = blaiGeneratedNpuPayloadCopySections
    outResult.firstSectionCopyBlock = blaiGeneratedModelSectionCopyNoBlock
    outResult.firstWindowBlock = plan.firstWindowBlock
    return
  blaiCopyGeneratedModelSectionInto(
    blob, outResult.sections.instruction, instructions, outResult.instruction)
  blaiCopyGeneratedModelSectionInto(
    blob, outResult.sections.bias, biases, outResult.bias)
  blaiCopyGeneratedModelSectionInto(
    blob, outResult.sections.weight, weights, outResult.weight)
  outResult.instructionCopied = outResult.instruction.copied
  outResult.biasCopied = outResult.bias.copied
  outResult.weightCopied = outResult.weight.copied
  outResult.copied =
    outResult.instructionCopied and outResult.biasCopied and
      outResult.weightCopied
  if not outResult.instructionCopied:
    outResult.firstBlock = blaiGeneratedNpuPayloadCopyInstruction
    outResult.firstSectionCopyBlock = outResult.instruction.firstBlock
    outResult.firstWindowBlock = outResult.instruction.windowFirstBlock
  elif not outResult.biasCopied:
    outResult.firstBlock = blaiGeneratedNpuPayloadCopyBias
    outResult.firstSectionCopyBlock = outResult.bias.firstBlock
    outResult.firstWindowBlock = outResult.bias.windowFirstBlock
  elif not outResult.weightCopied:
    outResult.firstBlock = blaiGeneratedNpuPayloadCopyWeight
    outResult.firstSectionCopyBlock = outResult.weight.firstBlock
    outResult.firstWindowBlock = outResult.weight.windowFirstBlock
  else:
    outResult.firstBlock = blaiGeneratedNpuPayloadCopyNoBlock
    outResult.firstSectionCopyBlock = blaiGeneratedModelSectionCopyNoBlock
    outResult.firstWindowBlock = blaiGeneratedModelSectionWindowNoBlock
  outResult.valid = outResult.sections.valid and outResult.copied

proc blaiCopyGeneratedNpuPayloads*(
    blob: openArray[uint8],
    plan: BlaiGeneratedModelSectionPlan,
    instructions: var openArray[uint8],
    biases: var openArray[uint8],
    weights: var openArray[uint8]):
    BlaiGeneratedNpuPayloadCopyResult =
  ## Convenience wrapper for generated NPU payload copying.
  blaiCopyGeneratedNpuPayloadsInto(
    blob, plan, instructions, biases, weights, result)

proc blaiGeneratedCpuRecordStreamCursor*(
    recordIndex, recordCount: int): BlaiGeneratedCpuRecordStreamCursor =
  ## Resolve one copied generated CPU-record row without open-coded indexes.
  if recordIndex < 0 or recordCount < 0 or recordIndex >= recordCount:
    return
  result.recordIndex = recordIndex
  result.valid = true

proc blaiGeneratedCpuRecordStreamWindow*(
    recordCount: uint32,
    streamCapacity: int): BlaiGeneratedCpuRecordStreamWindow =
  ## Resolve copied generated CPU-record rows to a parser input window.
  let countCursor = blaiInstructionStreamCountCursor(recordCount, streamCapacity)
  if not countCursor.valid or countCursor.count <= 0:
    return
  let lastCursor =
    blaiGeneratedCpuRecordStreamCursor(countCursor.count - 1, countCursor.count)
  if not lastCursor.valid:
    return
  result.recordCount = recordCount
  result.count = countCursor.count
  result.startIndex = 0
  result.stopIndex = lastCursor.recordIndex
  result.valid = true

proc blaiCopyGeneratedCpuRecordStreamInto*(
    blob: openArray[uint8],
    section: BlaiGeneratedModelSectionWindow,
    stream: var openArray[BlaiInstruction],
    outResult: var BlaiGeneratedCpuRecordStreamCopyResult) =
  ## Copy a generated CPU-record section into typed 16-byte instruction rows.
  outResult = default(BlaiGeneratedCpuRecordStreamCopyResult)
  outResult.section = section
  outResult.windowFirstBlock = section.firstBlock
  if not section.valid:
    outResult.firstBlock = blaiGeneratedCpuRecordStreamCopySection
    return
  outResult.recordBytesAligned =
    (section.bytes mod BlaiInstructionSize.uint32) == 0'u32
  if not outResult.recordBytesAligned:
    outResult.firstBlock = blaiGeneratedCpuRecordStreamCopyAlignment
    return
  outResult.recordCount = section.bytes div BlaiInstructionSize.uint32
  let countCursor =
    blaiInstructionStreamCountCursor(outResult.recordCount, stream.len)
  outResult.streamFits = countCursor.valid
  if not countCursor.valid:
    outResult.firstBlock = blaiGeneratedCpuRecordStreamCopyStream
    return
  for instructionIndex in 0 ..< countCursor.count:
    for byteIndex in 0 ..< BlaiInstructionSize:
      let cursor = blaiInstructionByteCursor(instructionIndex, byteIndex)
      if not cursor.valid:
        outResult.firstBlock = blaiGeneratedCpuRecordStreamCopyByteCursor
        return
      var relativeOffset: uint32
      if not blaiU64ExactU32Count(cursor.absoluteIndex.uint64, relativeOffset):
        outResult.firstBlock = blaiGeneratedCpuRecordStreamCopyByteCursor
        return
      var value: uint8
      if not blaiGeneratedModelSectionByte(blob, section, relativeOffset, value):
        outResult.firstBlock = blaiGeneratedCpuRecordStreamCopySectionByte
        return
      stream[cursor.instructionIndex][cursor.byteIndex] = value
  outResult.copiedRecords = outResult.recordCount
  if countCursor.count > 0:
    let firstCursor =
      blaiGeneratedCpuRecordStreamCursor(0, countCursor.count)
    let lastCursor =
      blaiGeneratedCpuRecordStreamCursor(
        countCursor.count - 1, countCursor.count)
    if not firstCursor.valid or not lastCursor.valid:
      outResult.firstBlock = blaiGeneratedCpuRecordStreamCopyRecordCursor
      return
    outResult.firstRecordKind =
      decodeBlaiCpuInstructionType(stream[firstCursor.recordIndex])
    outResult.lastRecordKind =
      decodeBlaiCpuInstructionType(stream[lastCursor.recordIndex])
  outResult.copied = true
  outResult.firstBlock = blaiGeneratedCpuRecordStreamCopyNoBlock
  outResult.valid = true

proc blaiCopyGeneratedCpuRecordStream*(
    blob: openArray[uint8],
    section: BlaiGeneratedModelSectionWindow,
    stream: var openArray[BlaiInstruction]):
    BlaiGeneratedCpuRecordStreamCopyResult =
  ## Convenience wrapper for generated CPU-record stream copying.
  blaiCopyGeneratedCpuRecordStreamInto(blob, section, stream, result)

proc blaiParseGeneratedCpuRecordSectionInto*(
    blob: openArray[uint8],
    section: BlaiGeneratedModelSectionWindow,
    stream: var openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuInstLayer64],
    outResult: var BlaiGeneratedCpuRecordParseResult) =
  ## Copy a generated CPU-record section, then parse exactly those records.
  outResult = default(BlaiGeneratedCpuRecordParseResult)
  blaiCopyGeneratedCpuRecordStreamInto(
    blob, section, stream, outResult.copy)
  outResult.copyFirstBlock = outResult.copy.firstBlock
  outResult.windowFirstBlock = outResult.copy.windowFirstBlock
  outResult.copied = outResult.copy.copied
  if not outResult.copy.valid or outResult.copy.recordCount == 0'u32:
    outResult.firstBlock = blaiGeneratedCpuRecordParseCopy
    return
  let recordWindow =
    blaiGeneratedCpuRecordStreamWindow(outResult.copy.recordCount, stream.len)
  if not recordWindow.valid:
    outResult.firstBlock = blaiGeneratedCpuRecordParseWindow
    return
  blaiParseCpuModelInstructionsInto(
    stream.toOpenArray(recordWindow.startIndex, recordWindow.stopIndex),
    layers, outResult.parsed)
  outResult.parsedComplete = outResult.parsed.complete
  if not outResult.parsedComplete:
    outResult.firstBlock = blaiGeneratedCpuRecordParseInstructions
    return
  outResult.firstBlock = blaiGeneratedCpuRecordParseNoBlock
  outResult.valid = outResult.copied and outResult.parsedComplete

proc blaiParseGeneratedCpuRecordSection*(
    blob: openArray[uint8],
    section: BlaiGeneratedModelSectionWindow,
    stream: var openArray[BlaiInstruction],
    layers: var openArray[BlaiCpuInstLayer64]):
    BlaiGeneratedCpuRecordParseResult =
  ## Convenience wrapper for generated CPU-record section parsing.
  blaiParseGeneratedCpuRecordSectionInto(blob, section, stream, layers, result)

proc blaiClearTemporaryBytes(buffer: var openArray[uint8]) =
  for byteIndex in 0 ..< buffer.len:
    buffer[byteIndex] = 0

proc blaiForwardBiasWordCursor*(biasIndex: int): BlaiForwardBiasWordCursor
proc blaiForwardBiasWordBits*(biasInts: openArray[int32],
                              cursor: BlaiForwardBiasWordCursor): uint32

proc blaiStoreTemporaryWeightBytes(weightBytes: openArray[uint8],
                                   weightByteCount: uint32,
                                   weightWindow: var openArray[uint8]) =
  let byteCountCursor =
    blaiForwardWeightByteCountCursor(
      weightByteCount, min(weightBytes.len, weightWindow.len))
  doAssert byteCountCursor.valid
  for byteIndex in 0 ..< byteCountCursor.count:
    weightWindow[byteIndex] = weightBytes[byteIndex]

proc blaiStoreTemporaryBiasBytes(biases: openArray[int32],
                                 biasByteCount: uint32,
                                 biasWindow: var openArray[uint8]): bool =
  let biasCount = biasByteCount div BlaiNpuBiasElementBytes
  let biasCountCursor = blaiForwardBiasWordCountCursor(biasCount, biases.len)
  if not biasCountCursor.valid:
    return false
  for biasIndex in 0 ..< biasCountCursor.count:
    let cursor = blaiForwardBiasWordCursor(biasIndex)
    if not cursor.valid:
      return false
    if not blaiStoreLe32(
        biasWindow, cursor.byteOffset, blaiForwardBiasWordBits(biases, cursor)):
      return false
  true

proc blaiTemporaryWeightBytesMatch(buffer: openArray[uint8],
                                   expectedWeightBytes: openArray[uint8],
                                   expectedWeightByteCount: uint32): bool =
  let byteCountCursor =
    blaiForwardWeightByteCountCursor(
      expectedWeightByteCount, min(buffer.len, expectedWeightBytes.len))
  if not byteCountCursor.valid:
    return false
  for byteIndex in 0 ..< byteCountCursor.count:
    if buffer[byteIndex] != expectedWeightBytes[byteIndex]:
      return false
  true

proc blaiTemporaryBiasBytesMatch(buffer: openArray[uint8],
                                 expectedBiases: openArray[int32],
                                 expectedBiasByteCount: uint32): bool =
  let biasCount = expectedBiasByteCount div BlaiNpuBiasElementBytes
  let biasCountCursor =
    blaiForwardBiasWordCountCursor(biasCount, expectedBiases.len)
  if not biasCountCursor.valid:
    return false
  for biasIndex in 0 ..< biasCountCursor.count:
    var actual: uint32
    let cursor = blaiForwardBiasWordCursor(biasIndex)
    if not cursor.valid:
      return false
    if not blaiLoadLe32(buffer, cursor.byteOffset, actual):
      return false
    if actual != blaiForwardBiasWordBits(expectedBiases, cursor):
      return false
  true

proc blaiPrepareForwardNpuTemporaryWeightBiasBufferInto*[N: static[int]](
    weightBytes: openArray[uint8],
    weightByteCount: uint32,
    biases: openArray[int32],
    biasByteCount: uint32,
    buffer: var array[N, uint8],
    outResult: var BlaiForwardNpuTemporaryWeightBiasBufferResult) =
  ## Materialize the SDK-style temporary weight/bias buffer for live forward_NPU.
  ##
  ## The SDK allocates one aligned byte region for `Load_NPU_weights` output
  ## and places the int32 bias stream after the 4-byte-aligned weight bytes.
  ## This helper keeps that layout in typed caller-owned storage and returns
  ## the projected BLAI addresses plus cache-clean evidence.
  outResult = default(BlaiForwardNpuTemporaryWeightBiasBufferResult)
  outResult.weightBytes = weightByteCount
  outResult.biasBytes = biasByteCount
  outResult.biasOffset = blaiAlign4(weightByteCount)
  var totalFit: BlaiUint32AppendFitResult
  blaiUint32AppendFitInto(
    high(uint32), outResult.biasOffset, biasByteCount, totalFit)
  outResult.totalBytes = totalFit.requiredCount
  outResult.bufferFits = totalFit.fits and outResult.totalBytes <= N.uint32
  outResult.weightFits = weightByteCount <= blaiOpenArrayLenU32(weightBytes)
  outResult.biasAligned = (biasByteCount mod BlaiNpuBiasElementBytes) == 0
  outResult.biasFits = outResult.biasAligned and
    totalFit.fits and
    (biasByteCount div BlaiNpuBiasElementBytes <= blaiOpenArrayLenU32(biases))
  if not outResult.bufferFits or not outResult.weightFits or
      not outResult.biasFits:
    return
  let totalWindow = blaiCheckedByteWindow(N, 0'u32, outResult.totalBytes)
  if totalWindow.fits and totalWindow.count > 0:
    blaiClearTemporaryBytes(blaiCheckedByteOpenArray(buffer, totalWindow))
  if weightByteCount != 0'u32:
    let weightWindow = blaiCheckedByteWindow(N, 0'u32, weightByteCount)
    if not weightWindow.fits:
      return
    blaiStoreTemporaryWeightBytes(
      weightBytes, weightByteCount,
      blaiCheckedByteOpenArray(buffer, weightWindow))
  if biasByteCount != 0'u32:
    let biasWindow =
      blaiCheckedByteWindow(N, outResult.biasOffset, biasByteCount)
    if not biasWindow.fits:
      return
    if not blaiStoreTemporaryBiasBytes(
        biases, biasByteCount,
        blaiCheckedByteOpenArray(buffer, biasWindow)):
      return
  outResult.projection = blaiProjectWorkspaceBufferAddress(buffer)
  outResult.addressRangeFits =
    outResult.projection.projected and outResult.projection.addressFits and
      blaiUint32AddressRangeFits(
        outResult.projection.hardwareAddress, outResult.totalBytes)
  if not outResult.addressRangeFits:
    return
  outResult.weightAddr = outResult.projection.hardwareAddress
  outResult.biasAddr = outResult.projection.hardwareAddress + outResult.biasOffset
  outResult.weightClean = blaiApplyWorkspaceCleanSegment(
    BlaiForwardModelWorkspaceSegment(
      active: true, fits: true, address: outResult.weightAddr,
      bytes: weightByteCount))
  outResult.biasClean = blaiApplyWorkspaceCleanSegment(
    BlaiForwardModelWorkspaceSegment(
      active: true, fits: true, address: outResult.biasAddr,
      bytes: biasByteCount))
  outResult.prepared =
    outResult.weightClean.fits and outResult.biasClean.fits and
      outResult.weightClean.applied and outResult.biasClean.applied

proc blaiPrepareForwardNpuTemporaryWeightBiasBuffer*[N: static[int]](
    weightBytes: openArray[uint8],
    weightByteCount: uint32,
    biases: openArray[int32],
    biasByteCount: uint32,
    buffer: var array[N, uint8]):
    BlaiForwardNpuTemporaryWeightBiasBufferResult =
  ## Convenience wrapper for SDK-style temporary weight/bias buffer prep.
  blaiPrepareForwardNpuTemporaryWeightBiasBufferInto(
    weightBytes, weightByteCount, biases, biasByteCount, buffer, result)

proc blaiForwardNpuTemporaryWeightBiasBufferEvidenceInto*(
    prepared: BlaiForwardNpuTemporaryWeightBiasBufferResult,
    buffer: openArray[uint8],
    expectedWeightBytes: openArray[uint8],
    expectedWeightByteCount: uint32,
    expectedBiases: openArray[int32],
    expectedBiasByteCount: uint32,
    outResult: var BlaiForwardNpuTemporaryWeightBiasBufferEvidence) =
  ## Derive evidence for SDK-style temporary weight/bias buffer layout.
  outResult = default(BlaiForwardNpuTemporaryWeightBiasBufferEvidence)
  outResult.projected = prepared.projection.projected
  outResult.addressFits = prepared.projection.addressFits
  outResult.addressRangeFits = prepared.addressRangeFits
  outResult.weightAligned = (prepared.weightAddr and 0x0F'u32) == 0
  outResult.biasAddressMatches =
    prepared.biasAddr == prepared.weightAddr + blaiAlign4(expectedWeightByteCount)
  outResult.prepared = prepared.prepared
  outResult.bufferFits = prepared.bufferFits
  outResult.weightFits = prepared.weightFits
  outResult.biasAligned = prepared.biasAligned
  outResult.biasFits = prepared.biasFits
  outResult.weightBytesMatch = prepared.weightBytes == expectedWeightByteCount
  outResult.biasBytesMatch = prepared.biasBytes == expectedBiasByteCount
  outResult.biasOffsetMatches =
    prepared.biasOffset == blaiAlign4(expectedWeightByteCount)
  outResult.weightBufferPresent =
    expectedWeightByteCount <= blaiOpenArrayLenU32(expectedWeightBytes) and
      expectedWeightByteCount <= blaiBufferLenU32(buffer.len)
  if outResult.weightBufferPresent:
    if expectedWeightByteCount == 0'u32:
      outResult.weightBufferMatches = true
    else:
      let weightWindow =
        blaiCheckedByteWindow(buffer.len, 0'u32, expectedWeightByteCount)
      outResult.weightBufferMatches =
        weightWindow.fits and
        blaiTemporaryWeightBytesMatch(
          blaiCheckedByteOpenArray(buffer, weightWindow),
          expectedWeightBytes, expectedWeightByteCount)
  let biasCountFits =
    expectedBiasByteCount mod BlaiNpuBiasElementBytes == 0 and
      expectedBiasByteCount div BlaiNpuBiasElementBytes <=
        blaiOpenArrayLenU32(expectedBiases)
  let biasWindow =
    blaiCheckedByteWindow(buffer.len, prepared.biasOffset, expectedBiasByteCount)
  outResult.biasBufferPresent =
    biasCountFits and biasWindow.fits
  if outResult.biasBufferPresent:
    if expectedBiasByteCount == 0'u32:
      outResult.biasBufferMatches = true
    else:
      outResult.biasBufferMatches =
        blaiTemporaryBiasBytesMatch(
          blaiCheckedByteOpenArray(buffer, biasWindow),
          expectedBiases, expectedBiasByteCount)
  outResult.weightCacheActive = prepared.weightClean.active
  outResult.weightCacheFits = prepared.weightClean.fits
  outResult.weightCacheApplied = prepared.weightClean.applied
  outResult.weightCacheClean =
    prepared.weightClean.operation == blaiCacheClean
  outResult.weightCacheAddressMatches =
    prepared.weightClean.address == prepared.weightAddr
  outResult.weightCacheBytesMatch =
    prepared.weightClean.bytes == prepared.weightBytes
  outResult.weightCacheValid =
    outResult.weightCacheActive and outResult.weightCacheFits and
      outResult.weightCacheApplied and outResult.weightCacheClean and
      outResult.weightCacheAddressMatches and outResult.weightCacheBytesMatch
  outResult.biasCacheActive = prepared.biasClean.active
  outResult.biasCacheFits = prepared.biasClean.fits
  outResult.biasCacheApplied = prepared.biasClean.applied
  outResult.biasCacheClean = prepared.biasClean.operation == blaiCacheClean
  outResult.biasCacheAddressMatches =
    prepared.biasClean.address == prepared.biasAddr
  outResult.biasCacheBytesMatch =
    prepared.biasClean.bytes == prepared.biasBytes
  outResult.biasCacheValid =
    outResult.biasCacheActive and outResult.biasCacheFits and
      outResult.biasCacheApplied and outResult.biasCacheClean and
      outResult.biasCacheAddressMatches and outResult.biasCacheBytesMatch
  outResult.cacheValid =
    outResult.weightCacheValid and outResult.biasCacheValid
  outResult.projectionValid =
    outResult.projected and outResult.addressFits and
      outResult.addressRangeFits and outResult.weightAligned and
      outResult.biasAddressMatches
  outResult.typedResultValid =
    outResult.prepared and outResult.bufferFits and outResult.weightFits and
      outResult.biasAligned and outResult.biasFits and
      outResult.weightBytesMatch and outResult.biasBytesMatch and
      outResult.biasOffsetMatches
  outResult.bytesValid =
    outResult.weightBufferPresent and outResult.weightBufferMatches and
      outResult.biasBufferPresent and outResult.biasBufferMatches
  outResult.valid =
    outResult.projectionValid and outResult.typedResultValid and
      outResult.bytesValid and outResult.cacheValid

proc blaiForwardNpuTemporaryWeightBiasBufferEvidence*(
    prepared: BlaiForwardNpuTemporaryWeightBiasBufferResult,
    buffer: openArray[uint8],
    expectedWeightBytes: openArray[uint8],
    expectedWeightByteCount: uint32,
    expectedBiases: openArray[int32],
    expectedBiasByteCount: uint32):
    BlaiForwardNpuTemporaryWeightBiasBufferEvidence =
  ## Convenience wrapper for SDK-style temporary weight/bias buffer evidence.
  blaiForwardNpuTemporaryWeightBiasBufferEvidenceInto(
    prepared, buffer, expectedWeightBytes, expectedWeightByteCount,
    expectedBiases, expectedBiasByteCount, result)

proc blaiInstructionCountBytes*(instructionCount: uint32,
                                outBytes: var uint32): bool =
  ## Project a recovered BLAI instruction count into byte capacity exactly.
  blaiU64ExactU32Count(
    instructionCount.uint64 * BlaiInstructionSize.uint64, outBytes)

proc blaiForwardWorkspaceMaterializedByteEvidenceInto*(
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: openArray[uint8],
    instructions: openArray[BlaiInstruction],
    instructionCount: uint32,
    weightBytes: openArray[uint8],
    weightByteCount: uint32,
    biases: openArray[int32],
    biasByteCount: uint32,
    outResult: var BlaiForwardWorkspaceMaterializedByteEvidence) =
  ## Compare materialized instruction/weight/bias workspace bytes explicitly.
  outResult = default(BlaiForwardWorkspaceMaterializedByteEvidence)
  let instructionSized =
    blaiInstructionCountBytes(instructionCount, outResult.instructionBytes)
  outResult.instructionByteCountMatches = instructionSized
  outResult.weightBytes = weightByteCount
  outResult.biasBytes = biasByteCount
  let instructionWindow =
    blaiForwardWorkspaceSegmentWindow(
      workspace.instruction, outResult.instructionBytes, workspaceBytes.len)
  let instructionBufferFits = instructionWindow.fits
  let instructionCountCapacity = blaiOpenArrayLenU32(instructions)
  let instructionCountCursor =
    blaiInstructionStreamCountCursor(instructionCount, instructions.len)
  outResult.instructionFits =
    instructionSized and workspace.instruction.active and
      outResult.instructionBytes <= workspace.instruction.bytes and
      instructionCount <= instructionCountCapacity and instructionBufferFits and
      instructionCountCursor.valid
  if outResult.instructionFits:
    outResult.instructionMatches = true
    for instIndex in 0 ..< instructionCountCursor.count:
      for byteIndex in 0 ..< BlaiInstructionSize:
        let cursor = blaiInstructionByteCursor(instIndex, byteIndex)
        if not cursor.valid:
          outResult.instructionMatches = false
          continue
        let relativeOffset = cursor.absoluteIndex.uint32
        if not blaiForwardWorkspaceSegmentByteEquals(
            workspace.instruction, workspaceBytes, relativeOffset,
            blaiInstructionByte(instructions, cursor)):
          outResult.instructionMatches = false
  outResult.streamBytesValid =
    outResult.instructionFits and outResult.instructionMatches
  var trailingOffset, trailingAddress: uint32
  let trailingOffsetFits =
    blaiForwardWorkspaceAbsoluteOffset(
      workspace.instruction.offset, outResult.instructionBytes.uint64,
      trailingOffset)
  let trailingAddressFits =
    blaiForwardWorkspaceAbsoluteOffset(
      workspace.instruction.address, outResult.instructionBytes.uint64,
      trailingAddress)
  let trailingSegment =
    BlaiForwardModelWorkspaceSegment(
      active: true,
      fits: workspace.instruction.fits,
      offset: if trailingOffsetFits: trailingOffset else: high(uint32),
      address: if trailingAddressFits: trailingAddress else: high(uint32),
      bytes: BlaiInstructionSize.uint32)
  let trailingWindow =
    blaiForwardWorkspaceSegmentWindow(
      trailingSegment, BlaiInstructionSize.uint32, workspaceBytes.len)
  outResult.trailingInstructionFits =
    instructionSized and workspace.instruction.active and
      outResult.instructionBytes.uint64 + BlaiInstructionSize.uint64 <=
        workspace.instruction.bytes.uint64 and
      trailingOffsetFits and trailingAddressFits and trailingWindow.fits
  if outResult.trailingInstructionFits:
    outResult.trailingInstructionZero = true
    for byteIndex in 0 ..< BlaiInstructionSize:
      if not blaiForwardWorkspaceSegmentByteEquals(
          trailingSegment, workspaceBytes, byteIndex.uint32, 0'u8):
        outResult.trailingInstructionZero = false
  outResult.trailingInstructionValid =
    outResult.trailingInstructionFits and outResult.trailingInstructionZero
  let weightWindow =
    blaiForwardWorkspaceSegmentWindow(
      workspace.weight, weightByteCount, workspaceBytes.len)
  let weightBufferFits = weightWindow.fits
  let weightByteCapacity = blaiOpenArrayLenU32(weightBytes)
  let weightByteCountCursor =
    blaiForwardWeightByteCountCursor(weightByteCount, weightBytes.len)
  outResult.weightFits =
    workspace.weight.active and weightByteCount <= workspace.weight.bytes and
      weightByteCount <= weightByteCapacity and weightBufferFits and
      weightByteCountCursor.valid
  if outResult.weightFits:
    outResult.weightMatches = true
    for byteIndex in 0 ..< weightByteCountCursor.count:
      if not blaiForwardWorkspaceSegmentByteEquals(
          workspace.weight, workspaceBytes, byteIndex.uint32,
          weightBytes[byteIndex]):
        outResult.weightMatches = false
  outResult.weightBytesValid =
    outResult.weightFits and outResult.weightMatches
  outResult.biasAligned = (biasByteCount mod BlaiNpuBiasElementBytes) == 0
  let biasCount =
    if outResult.biasAligned:
      biasByteCount div BlaiNpuBiasElementBytes
    else:
      0'u32
  let biasWindow =
    blaiForwardWorkspaceSegmentWindow(
      workspace.bias, biasByteCount, workspaceBytes.len)
  let biasBufferFits = biasWindow.fits
  let biasCountCapacity = blaiOpenArrayLenU32(biases)
  let biasCountCursor = blaiForwardBiasWordCountCursor(biasCount, biases.len)
  outResult.biasFits =
    outResult.biasAligned and workspace.bias.active and
      biasByteCount <= workspace.bias.bytes and
      biasCount <= biasCountCapacity and biasBufferFits and
      biasCountCursor.valid
  if outResult.biasFits:
    outResult.biasMatches = true
    for biasIndex in 0 ..< biasCountCursor.count:
      let cursor = blaiForwardBiasWordCursor(biasIndex)
      if not cursor.valid:
        outResult.biasMatches = false
        continue
      if not blaiForwardWorkspaceSegmentLe32Equals(
          workspace.bias, workspaceBytes, cursor.byteOffset,
          blaiForwardBiasWordBits(biases, cursor)):
        outResult.biasMatches = false
  outResult.biasBytesValid =
    outResult.biasAligned and outResult.biasFits and outResult.biasMatches
  outResult.matches =
    outResult.instructionByteCountMatches and outResult.streamBytesValid and
      outResult.trailingInstructionValid and outResult.weightBytesValid and
      outResult.biasBytesValid
  outResult.workspaceBytesValid =
    outResult.matches and outResult.instructionByteCountMatches

proc blaiForwardWorkspaceMaterializedByteEvidence*(
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: openArray[uint8],
    instructions: openArray[BlaiInstruction],
    instructionCount: uint32,
    weightBytes: openArray[uint8],
    weightByteCount: uint32,
    biases: openArray[int32],
    biasByteCount: uint32): BlaiForwardWorkspaceMaterializedByteEvidence =
  ## Convenience wrapper for materialized workspace byte evidence.
  blaiForwardWorkspaceMaterializedByteEvidenceInto(
    workspace, workspaceBytes, instructions, instructionCount,
    weightBytes, weightByteCount, biases, biasByteCount, result)

proc blaiForwardWorkspaceDataSlotEvidenceInto*(
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: openArray[uint8],
    layer: BlaiCpuInstLayer64,
    inputIndex: uint32,
    expectedInputByte: uint8,
    outResult: var BlaiForwardWorkspaceDataSlotEvidence) =
  ## Report DATA-buffer slot offsets and first staged input byte evidence.
  outResult = default(BlaiForwardWorkspaceDataSlotEvidence)
  outResult.patchSize = nonNegativeU32(layer.dramPatchSize)
  let inputCursor = blaiForwardInputCursor(inputIndex)
  if not inputCursor.valid:
    return
  outResult.inputSlot = nonNegativeU32(layer.dramIn[inputCursor.index])
  outResult.outputSlot = nonNegativeU32(layer.dramOut[0])
  outResult.slotsDistinct = outResult.inputSlot != outResult.outputSlot
  let inputSlotOffset =
    blaiPatchSlotOffset(outResult.inputSlot, outResult.patchSize)
  let outputSlotOffset =
    blaiPatchSlotOffset(outResult.outputSlot, outResult.patchSize)
  let inputRelative =
    if inputSlotOffset.valid: inputSlotOffset.offset.uint64 else: high(uint64)
  let outputRelative =
    if outputSlotOffset.valid: outputSlotOffset.offset.uint64 else: high(uint64)
  let inputRelativeOffset = inputSlotOffset.offset
  let outputRelativeOffset = outputSlotOffset.offset
  let inputRelativeFits = inputSlotOffset.valid
  let outputRelativeFits = outputSlotOffset.valid
  outResult.inputOffsetMatches =
    blaiForwardWorkspaceAbsoluteOffset(
      workspace.data.offset, inputRelative, outResult.inputOffset)
  outResult.outputOffsetMatches =
    blaiForwardWorkspaceAbsoluteOffset(
      workspace.data.offset, outputRelative, outResult.outputOffset)
  var inputByteIndex, outputByteIndex: int
  outResult.inputFits =
    inputRelativeFits and
      blaiForwardWorkspaceSegmentByteIndex(
        workspace.data, workspaceBytes.len, inputRelativeOffset,
        inputByteIndex)
  outResult.outputFits =
    outputRelativeFits and
      blaiForwardWorkspaceSegmentByteIndex(
        workspace.data, workspaceBytes.len, outputRelativeOffset,
        outputByteIndex)
  outResult.slotsValid =
    outResult.slotsDistinct and outResult.inputFits and
      outResult.outputFits and outResult.inputOffsetMatches and
      outResult.outputOffsetMatches
  outResult.stagedInputExpected = expectedInputByte
  if outResult.inputFits:
    discard blaiReadForwardWorkspaceSegmentByte(
      workspace.data, workspaceBytes, inputRelativeOffset,
      outResult.stagedInputActual)
    outResult.stagedInputPresent =
      outResult.stagedInputActual == expectedInputByte
  outResult.stagedInputMatches =
    outResult.stagedInputPresent and
      outResult.stagedInputActual == outResult.stagedInputExpected
  outResult.valid =
    outResult.slotsValid and outResult.stagedInputMatches

proc blaiForwardWorkspaceDataSlotEvidence*(
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: openArray[uint8],
    layer: BlaiCpuInstLayer64,
    inputIndex: uint32,
    expectedInputByte: uint8): BlaiForwardWorkspaceDataSlotEvidence =
  ## Convenience wrapper for DATA-buffer slot evidence.
  blaiForwardWorkspaceDataSlotEvidenceInto(
    workspace, workspaceBytes, layer, inputIndex, expectedInputByte, result)

proc blaiBindForwardWorkspaceBufferInto*(
    resources: BlaiForwardModelResourcePlan,
    buffer: var openArray[uint8],
    outResult: var BlaiForwardWorkspaceBufferBinding,
    alignment: uint32 = 16'u32) =
  ## Bind recovered forward_NPU workspace layout to live caller-owned bytes.
  ##
  ## Future live model fixtures should use this instead of synthetic base
  ## addresses, so instruction, DATA, weight, and bias pointers all refer to the
  ## same checked byte storage that is later staged and read back.
  outResult = default(BlaiForwardWorkspaceBufferBinding)
  outResult.bufferBytes = blaiForwardWorkspaceBufferBytes(buffer.len)
  if buffer.len <= 0:
    outResult.firstBlock = blaiForwardWorkspaceBufferBindBuffer
    return
  outResult.baseAddress = blaiForwardWorkspaceBufferBaseAddress(
    buffer, outResult.addressAvailable, outResult.addressFits)
  if not outResult.addressAvailable or not outResult.addressFits:
    outResult.firstBlock = blaiForwardWorkspaceBufferBindAddress
    return
  blaiPlanForwardModelWorkspaceInto(
    resources, outResult.baseAddress, outResult.workspace, alignment)
  blaiForwardWorkspaceFitsInto(
    outResult.workspace, outResult.bufferBytes, outResult.workspaceFit)
  outResult.workspaceFirstBlock = outResult.workspaceFit.firstBlock
  if not outResult.workspaceFit.fits:
    outResult.firstBlock = blaiForwardWorkspaceBufferBindWorkspace
    return
  outResult.firstBlock = blaiForwardWorkspaceBufferBindNoBlock
  outResult.bound = true

proc blaiBindForwardWorkspaceBuffer*(
    resources: BlaiForwardModelResourcePlan,
    buffer: var openArray[uint8],
    alignment: uint32 = 16'u32): BlaiForwardWorkspaceBufferBinding =
  ## Convenience wrapper for live workspace buffer binding.
  blaiBindForwardWorkspaceBufferInto(resources, buffer, result, alignment)

proc blaiBindForwardWorkspaceAddressInto*(
    resources: BlaiForwardModelResourcePlan,
    baseAddress: uint32,
    bufferBytes: uint32,
    outResult: var BlaiForwardWorkspaceBufferBinding,
    alignment: uint32 = 16'u32) =
  ## Bind a forward_NPU workspace to a caller-supplied hardware-visible base.
  ##
  ## This is for callers that already know the physical address of their
  ## workspace storage. It deliberately avoids inferring an address from a Nim
  ## byte array while still reusing the same fit and first-block diagnostics as
  ## live buffer binding.
  outResult = default(BlaiForwardWorkspaceBufferBinding)
  outResult.bufferBytes = bufferBytes
  outResult.baseAddress = baseAddress
  outResult.addressAvailable = baseAddress != 0'u32
  outResult.addressFits = outResult.addressAvailable
  if bufferBytes == 0'u32:
    outResult.firstBlock = blaiForwardWorkspaceBufferBindBuffer
    return
  if not outResult.addressAvailable or not outResult.addressFits:
    outResult.firstBlock = blaiForwardWorkspaceBufferBindAddress
    return
  blaiPlanForwardModelWorkspaceInto(
    resources, baseAddress, outResult.workspace, alignment)
  blaiForwardWorkspaceFitsInto(
    outResult.workspace, bufferBytes, outResult.workspaceFit)
  outResult.workspaceFirstBlock = outResult.workspaceFit.firstBlock
  if not outResult.workspaceFit.fits:
    outResult.firstBlock = blaiForwardWorkspaceBufferBindWorkspace
    return
  outResult.firstBlock = blaiForwardWorkspaceBufferBindNoBlock
  outResult.bound = true

proc blaiBindForwardWorkspaceAddress*(
    resources: BlaiForwardModelResourcePlan,
    baseAddress: uint32,
    bufferBytes: uint32,
    alignment: uint32 = 16'u32): BlaiForwardWorkspaceBufferBinding =
  ## Convenience wrapper for explicit-address workspace binding.
  blaiBindForwardWorkspaceAddressInto(
    resources, baseAddress, bufferBytes, result, alignment)

proc blaiBindForwardWorkspaceFixtureAddressInto*(
    resources: BlaiForwardModelResourcePlan,
    baseAddress: uint32,
    bufferBytes: uint32,
    outResult: var BlaiForwardWorkspaceBufferBinding,
    alignment: uint32 = 16'u32) =
  ## Bind a caller-supplied fixture address while preserving later address gates.
  ##
  ## Model fixtures use this when the test needs a typed workspace layout even
  ## for address zero, so `blaiForwardWorkspaceHardwareAddressReadiness` reports
  ## the recovered hardware-address block instead of the earlier binder block.
  outResult = default(BlaiForwardWorkspaceBufferBinding)
  outResult.bufferBytes = bufferBytes
  outResult.baseAddress = baseAddress
  outResult.addressAvailable = true
  outResult.addressFits = true
  if bufferBytes == 0'u32:
    outResult.firstBlock = blaiForwardWorkspaceBufferBindBuffer
    return
  blaiPlanForwardModelWorkspaceInto(
    resources, baseAddress, outResult.workspace, alignment)
  blaiForwardWorkspaceFitsInto(
    outResult.workspace, bufferBytes, outResult.workspaceFit)
  outResult.workspaceFirstBlock = outResult.workspaceFit.firstBlock
  if not outResult.workspaceFit.fits:
    outResult.firstBlock = blaiForwardWorkspaceBufferBindWorkspace
    return
  outResult.firstBlock = blaiForwardWorkspaceBufferBindNoBlock
  outResult.bound = true

proc blaiBindForwardWorkspaceFixtureAddress*(
    resources: BlaiForwardModelResourcePlan,
    baseAddress: uint32,
    bufferBytes: uint32,
    alignment: uint32 = 16'u32): BlaiForwardWorkspaceBufferBinding =
  ## Convenience wrapper for fixture explicit-address workspace binding.
  blaiBindForwardWorkspaceFixtureAddressInto(
    resources, baseAddress, bufferBytes, result, alignment)

proc blaiClearForwardWorkspaceSegment*(
    segment: BlaiForwardModelWorkspaceSegment,
    buffer: var openArray[uint8]): bool =
  ## Zero one active workspace segment in caller-owned byte storage.
  if not segment.active:
    return true
  let window = blaiForwardWorkspaceSegmentWindow(segment, segment.bytes, buffer.len)
  if not window.fits:
    return false
  for i in 0 ..< window.count:
    blaiForwardWorkspaceSegmentOpenArray(buffer, window)[i] = 0
  true

proc blaiForwardWorkspaceClearReadinessInto*(
    clear: BlaiForwardWorkspaceClearResult,
    outResult: var BlaiForwardWorkspaceClearReadiness) =
  ## Derive the public gate for reusable-workspace clearing.
  outResult = default(BlaiForwardWorkspaceClearReadiness)
  outResult.workspaceReady = clear.workspaceReady
  outResult.bufferFits = clear.bufferFits
  outResult.workspaceFitFirstBlock = clear.workspaceFitFirstBlock
  if not outResult.workspaceReady:
    outResult.firstBlock = blaiForwardWorkspaceClearWorkspace
  elif not outResult.bufferFits:
    outResult.firstBlock = blaiForwardWorkspaceClearBuffer
  else:
    outResult.firstBlock = blaiForwardWorkspaceClearNoBlock
  outResult.cleared = outResult.workspaceReady and outResult.bufferFits and
    clear.cleared

proc blaiForwardWorkspaceClearReadiness*(
    clear: BlaiForwardWorkspaceClearResult): BlaiForwardWorkspaceClearReadiness =
  ## Convenience wrapper for reusable-workspace clear readiness.
  blaiForwardWorkspaceClearReadinessInto(clear, result)

proc blaiClearForwardModelWorkspaceInto*(
    workspace: BlaiForwardModelWorkspacePlan,
    buffer: var openArray[uint8],
    outResult: var BlaiForwardWorkspaceClearResult) =
  ## Zero all active reusable workspace segments in caller-owned byte storage.
  outResult = default(BlaiForwardWorkspaceClearResult)
  outResult.workspaceReady = workspace.supported and workspace.fits
  var workspaceFit: BlaiForwardWorkspaceFitResult
  blaiForwardWorkspaceFitsInto(workspace, blaiBufferLenU32(buffer.len), workspaceFit)
  outResult.bufferFits = workspaceFit.fits
  outResult.workspaceFitFirstBlock = workspaceFit.firstBlock
  if not outResult.bufferFits:
    blaiForwardWorkspaceClearReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.cleared = outResult.readiness.cleared
    return
  if not blaiClearForwardWorkspaceSegment(workspace.instruction, buffer):
    blaiForwardWorkspaceClearReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.cleared = outResult.readiness.cleared
    return
  if not blaiClearForwardWorkspaceSegment(workspace.data, buffer):
    blaiForwardWorkspaceClearReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.cleared = outResult.readiness.cleared
    return
  if not blaiClearForwardWorkspaceSegment(workspace.weight, buffer):
    blaiForwardWorkspaceClearReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.cleared = outResult.readiness.cleared
    return
  if not blaiClearForwardWorkspaceSegment(workspace.bias, buffer):
    blaiForwardWorkspaceClearReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.cleared = outResult.readiness.cleared
    return
  if not blaiClearForwardWorkspaceSegment(workspace.temporaryWeights, buffer):
    blaiForwardWorkspaceClearReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.cleared = outResult.readiness.cleared
    return
  outResult.cleared = true
  blaiForwardWorkspaceClearReadinessInto(outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.cleared = outResult.readiness.cleared

proc blaiClearForwardModelWorkspace*(
    workspace: BlaiForwardModelWorkspacePlan,
    buffer: var openArray[uint8]): BlaiForwardWorkspaceClearResult =
  ## Convenience result-returning wrapper for workspace clearing.
  blaiClearForwardModelWorkspaceInto(workspace, buffer, result)

proc blaiForwardInstructionWorkspaceReadinessInto*(
    storage: BlaiForwardInstructionWorkspaceResult,
    outResult: var BlaiForwardInstructionWorkspaceReadiness) =
  ## Derive the public gate for instruction workspace storage.
  outResult = default(BlaiForwardInstructionWorkspaceReadiness)
  outResult.workspaceReady = storage.workspaceReady
  outResult.streamFits = storage.streamFits
  outResult.segmentFits = storage.segmentFits
  outResult.bufferFits = storage.bufferFits
  if not outResult.workspaceReady:
    outResult.firstBlock = blaiForwardInstructionWorkspaceWorkspace
  elif not outResult.streamFits:
    outResult.firstBlock = blaiForwardInstructionWorkspaceStream
  elif not outResult.segmentFits:
    outResult.firstBlock = blaiForwardInstructionWorkspaceSegment
  elif not outResult.bufferFits:
    outResult.firstBlock = blaiForwardInstructionWorkspaceBuffer
  else:
    outResult.firstBlock = blaiForwardInstructionWorkspaceNoBlock
  outResult.copied = outResult.workspaceReady and outResult.streamFits and
    outResult.segmentFits and outResult.bufferFits and storage.copied

proc blaiForwardInstructionWorkspaceReadiness*(
    storage: BlaiForwardInstructionWorkspaceResult):
    BlaiForwardInstructionWorkspaceReadiness =
  ## Convenience wrapper for instruction workspace storage readiness.
  blaiForwardInstructionWorkspaceReadinessInto(storage, result)

proc blaiInstructionByteCursor*(instructionIndex, byteIndex: int):
    BlaiInstructionByteCursor =
  ## Resolve one byte inside the recovered fixed-width BLAI instruction rows.
  let cursor =
    blaiFixedRowByteCursor(instructionIndex, byteIndex, BlaiInstructionSize)
  if not cursor.valid:
    return
  result.instructionIndex = cursor.rowIndex
  result.byteIndex = cursor.byteIndex
  result.absoluteIndex = cursor.absoluteIndex
  result.valid = true

proc blaiInstructionByte*(stream: openArray[BlaiInstruction],
                          cursor: BlaiInstructionByteCursor): uint8 =
  ## Read a typed instruction byte selected by a checked row cursor.
  doAssert cursor.valid
  stream[cursor.instructionIndex][cursor.byteIndex]

proc blaiStoreInstructionRows(stream: openArray[BlaiInstruction],
                              instructionCount: uint32,
                              instructionWindow: var openArray[uint8]) =
  let instructionCountCursor =
    blaiInstructionStreamCountCursor(instructionCount, stream.len)
  doAssert instructionCountCursor.valid
  for instIndex in 0 ..< instructionCountCursor.count:
    for byteIndex in 0 ..< BlaiInstructionSize:
      let cursor = blaiInstructionByteCursor(instIndex, byteIndex)
      doAssert cursor.valid
      instructionWindow[cursor.absoluteIndex] =
        blaiInstructionByte(stream, cursor)

proc blaiStoreForwardInstructionsInWorkspaceInto*(
    workspace: BlaiForwardModelWorkspacePlan,
    stream: openArray[BlaiInstruction],
    instructionCount: uint32,
    buffer: var openArray[uint8],
    outResult: var BlaiForwardInstructionWorkspaceResult) =
  ## Copy typed BLAI instruction records into caller-owned instruction storage.
  outResult = default(BlaiForwardInstructionWorkspaceResult)
  outResult.workspaceReady = workspace.supported and workspace.fits and
    workspace.instruction.active
  if not blaiInstructionCountBytes(instructionCount, outResult.bytes):
    blaiForwardInstructionWorkspaceReadinessInto(
      outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.copied = outResult.readiness.copied
    return
  outResult.streamFits = instructionCount <= blaiOpenArrayLenU32(stream)
  outResult.segmentFits = outResult.bytes <= workspace.instruction.bytes
  let instructionWindow =
    blaiForwardWorkspaceSegmentWindow(
      workspace.instruction, outResult.bytes, buffer.len)
  let instructionWindowFits = instructionWindow.fits
  let instructionBufferSegmentFits =
    blaiForwardWorkspaceSegmentFits(
      workspace.instruction, blaiBufferLenU32(buffer.len))
  outResult.bufferFits = outResult.workspaceReady and outResult.streamFits and
    outResult.segmentFits and instructionBufferSegmentFits and
    instructionWindowFits
  if not outResult.bufferFits:
    blaiForwardInstructionWorkspaceReadinessInto(
      outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.copied = outResult.readiness.copied
    return
  if outResult.bytes != 0'u32:
    blaiStoreInstructionRows(
      stream, instructionCount,
      blaiForwardWorkspaceSegmentOpenArray(buffer, instructionWindow))
  outResult.copied = true
  blaiForwardInstructionWorkspaceReadinessInto(outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.copied = outResult.readiness.copied

proc blaiStoreForwardInstructionsInWorkspace*(
    workspace: BlaiForwardModelWorkspacePlan,
    stream: openArray[BlaiInstruction],
    instructionCount: uint32,
    buffer: var openArray[uint8]): BlaiForwardInstructionWorkspaceResult =
  ## Convenience wrapper for instruction workspace storage.
  blaiStoreForwardInstructionsInWorkspaceInto(
    workspace, stream, instructionCount, buffer, result)

proc blaiForwardWeightByteCursor*(byteIndex: int): BlaiForwardWeightByteCursor =
  ## Resolve one byte inside a materialized NPU weight byte stream.
  let byte = blaiCheckedByteIndex(byteIndex)
  if not byte.valid:
    return
  result.byteIndex = byte.byteIndex
  result.valid = true

proc blaiForwardWeightByte*(weightBytesIn: openArray[uint8],
                            cursor: BlaiForwardWeightByteCursor): uint8 =
  ## Read a materialized NPU weight byte selected by a checked cursor.
  doAssert cursor.valid
  weightBytesIn[cursor.byteIndex]

proc blaiStoreWeightBytes(weightBytesIn: openArray[uint8],
                          weightBytes: uint32,
                          weightWindow: var openArray[uint8]) =
  let weightByteCountCursor =
    blaiForwardWeightByteCountCursor(
      weightBytes, min(weightBytesIn.len, weightWindow.len))
  doAssert weightByteCountCursor.valid
  for i in 0 ..< weightByteCountCursor.count:
    let cursor = blaiForwardWeightByteCursor(i)
    doAssert cursor.valid
    weightWindow[cursor.byteIndex] =
      blaiForwardWeightByte(weightBytesIn, cursor)

proc blaiForwardBiasWordByteOffset*(biasIndex: uint32,
                                    outOffset: var uint32): bool =
  ## Project one recovered int32 bias word index into a byte offset exactly.
  blaiBiasWordCountBytes(biasIndex, outOffset)

proc blaiForwardBiasWordCursor*(biasIndex: int): BlaiForwardBiasWordCursor =
  ## Resolve one int32 bias word to its recovered little-endian byte offset.
  if biasIndex < 0:
    return
  var byteOffset: uint32
  if not blaiForwardBiasWordByteOffset(biasIndex.uint32, byteOffset):
    return
  result.biasIndex = biasIndex
  result.byteOffset = byteOffset
  result.valid = true

proc blaiForwardBiasWordBits*(biasInts: openArray[int32],
                              cursor: BlaiForwardBiasWordCursor): uint32 =
  ## Read one caller-provided bias word as the recovered unsigned bit pattern.
  doAssert cursor.valid
  blaiInt32Bits(biasInts[cursor.biasIndex])

proc blaiBiasWordCountBytes*(biasCount: uint32, outBytes: var uint32): bool =
  ## Project a recovered int32 bias word count into byte capacity exactly.
  blaiU64ExactU32Count(
    biasCount.uint64 * BlaiNpuBiasElementBytes.uint64, outBytes)

proc blaiStoreForwardBiasWordsInWorkspaceSegment*(
    segment: BlaiForwardModelWorkspaceSegment,
    biasInts: openArray[int32],
    biasCount: uint32,
    buffer: var openArray[uint8]): bool =
  ## Store recovered int32 bias words through segment-relative LE32 writes.
  let biasCountCursor =
    blaiForwardBiasWordCountCursor(biasCount, biasInts.len)
  if not biasCountCursor.valid:
    return false
  for i in 0 ..< biasCountCursor.count:
    let cursor = blaiForwardBiasWordCursor(i)
    if not cursor.valid:
      return false
    if not blaiWriteForwardWorkspaceSegmentLe32(
        segment, buffer, cursor.byteOffset,
        blaiForwardBiasWordBits(biasInts, cursor)):
      return false
  true

proc blaiForwardWeightWorkspaceReadinessInto*(
    storage: BlaiForwardWeightWorkspaceResult,
    outResult: var BlaiForwardWeightWorkspaceReadiness) =
  ## Derive the public gate for weight/bias workspace storage.
  outResult = default(BlaiForwardWeightWorkspaceReadiness)
  outResult.workspaceReady = storage.workspaceReady
  outResult.weightFits = storage.weightFits
  outResult.biasFits = storage.biasFits
  outResult.bufferFits = storage.bufferFits
  if not outResult.workspaceReady:
    outResult.firstBlock = blaiForwardWeightWorkspaceWorkspace
  elif not outResult.weightFits:
    outResult.firstBlock = blaiForwardWeightWorkspaceWeight
  elif not outResult.biasFits:
    outResult.firstBlock = blaiForwardWeightWorkspaceBias
  elif not outResult.bufferFits:
    outResult.firstBlock = blaiForwardWeightWorkspaceBuffer
  else:
    outResult.firstBlock = blaiForwardWeightWorkspaceNoBlock
  outResult.copied = outResult.workspaceReady and outResult.weightFits and
    outResult.biasFits and outResult.bufferFits and storage.copied

proc blaiForwardWeightWorkspaceReadiness*(
    storage: BlaiForwardWeightWorkspaceResult):
    BlaiForwardWeightWorkspaceReadiness =
  ## Convenience wrapper for weight/bias workspace storage readiness.
  blaiForwardWeightWorkspaceReadinessInto(storage, result)

proc blaiStoreForwardWeightsInWorkspaceInto*(
    workspace: BlaiForwardModelWorkspacePlan,
    weightBytesIn: openArray[uint8],
    weightBytes: uint32,
    biasInts: openArray[int32],
    biasCount: uint32,
    buffer: var openArray[uint8],
    outResult: var BlaiForwardWeightWorkspaceResult) =
  ## Copy materialized split weight bytes and bias int32s into workspace storage.
  outResult = default(BlaiForwardWeightWorkspaceResult)
  outResult.workspaceReady = workspace.supported and workspace.fits
  if not blaiBiasWordCountBytes(biasCount, outResult.biasBytes):
    blaiForwardWeightWorkspaceReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.copied = outResult.readiness.copied
    return
  outResult.weightBytes = weightBytes
  let weightSegmentFits =
    weightBytes == 0'u32 or
    (workspace.weight.active and weightBytes <= workspace.weight.bytes)
  let biasSegmentFits =
    biasCount == 0'u32 or
    (workspace.bias.active and outResult.biasBytes <= workspace.bias.bytes)
  outResult.weightFits =
    weightBytes <= blaiOpenArrayLenU32(weightBytesIn) and weightSegmentFits
  outResult.biasFits =
    biasCount <= blaiOpenArrayLenU32(biasInts) and biasSegmentFits
  let weightBufferSegmentFits =
    weightBytes == 0'u32 or
    blaiForwardWorkspaceSegmentFits(
      workspace.weight, blaiBufferLenU32(buffer.len))
  let weightWindow =
    blaiForwardWorkspaceSegmentWindow(workspace.weight, weightBytes, buffer.len)
  let weightBufferFits =
    weightBytes == 0'u32 or weightWindow.fits
  let biasBufferSegmentFits =
    biasCount == 0'u32 or
    blaiForwardWorkspaceSegmentFits(
      workspace.bias, blaiBufferLenU32(buffer.len))
  let biasWindow =
    blaiForwardWorkspaceSegmentWindow(
      workspace.bias, outResult.biasBytes, buffer.len)
  let biasBufferFits =
    biasCount == 0'u32 or biasWindow.fits
  outResult.bufferFits = outResult.workspaceReady and outResult.weightFits and
    outResult.biasFits and weightBufferSegmentFits and biasBufferSegmentFits and
    weightBufferFits and biasBufferFits
  if not outResult.bufferFits:
    blaiForwardWeightWorkspaceReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.copied = outResult.readiness.copied
    return
  if weightBytes != 0'u32:
    blaiStoreWeightBytes(
      weightBytesIn, weightBytes,
      blaiForwardWorkspaceSegmentOpenArray(buffer, weightWindow))
  if biasCount != 0'u32:
    if not blaiStoreForwardBiasWordsInWorkspaceSegment(
        workspace.bias, biasInts, biasCount, buffer):
      outResult.bufferFits = false
      blaiForwardWeightWorkspaceReadinessInto(outResult, outResult.readiness)
      outResult.firstBlock = outResult.readiness.firstBlock
      outResult.copied = outResult.readiness.copied
      return
  outResult.copied = true
  blaiForwardWeightWorkspaceReadinessInto(outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.copied = outResult.readiness.copied

proc blaiStoreForwardWeightsInWorkspace*(
    workspace: BlaiForwardModelWorkspacePlan,
    weightBytesIn: openArray[uint8],
    weightBytes: uint32,
    biasInts: openArray[int32],
    biasCount: uint32,
    buffer: var openArray[uint8]): BlaiForwardWeightWorkspaceResult =
  ## Convenience wrapper for weight workspace storage.
  blaiStoreForwardWeightsInWorkspaceInto(
    workspace, weightBytesIn, weightBytes, biasInts, biasCount, buffer, result)

proc blaiForwardNpuBufferFitsInto*(plan: BlaiForwardNpuPlan,
                                   dataBufferBytes: uint32,
                                   outResult: var BlaiForwardNpuBufferFitResult) =
  ## Check every recovered DATA-buffer range used by SDK `forward_NPU`.
  outResult = default(BlaiForwardNpuBufferFitResult)
  outResult.runnable = plan.runnable
  var required: BlaiForwardDataBufferPlan
  blaiForwardNpuDataBufferPlanInto(plan, required)
  outResult.dataPlanFits = required.fits
  outResult.requiredBytes = required.bytes
  outResult.bufferFits = dataBufferBytes >= required.bytes
  outResult.fits =
    (not outResult.runnable) or (outResult.dataPlanFits and outResult.bufferFits)

proc blaiForwardNpuBufferFits*(plan: BlaiForwardNpuPlan,
                               dataBufferBytes: uint32): bool =
  ## Boolean wrapper for recovered forward_NPU DATA-buffer range checks.
  var fit: BlaiForwardNpuBufferFitResult
  blaiForwardNpuBufferFitsInto(plan, dataBufferBytes, fit)
  fit.fits

proc blaiPlanForwardNpuInto*(layer: BlaiCpuInstLayer64,
                             layerIndex: uint32,
                             dataBufferBytes: uint32,
                             outResult: var BlaiForwardNpuPlan) =
  ## Plan SDK `forward_NPU` and include whole-DATA-buffer bounds status.
  blaiPlanForwardNpuInto(layer, layerIndex, outResult)
  var fit: BlaiForwardNpuBufferFitResult
  blaiForwardNpuBufferFitsInto(outResult, dataBufferBytes, fit)
  outResult.bufferFits = fit.fits

proc blaiPlanForwardNpu*(layer: BlaiCpuInstLayer64,
                         layerIndex: uint32,
                         dataBufferBytes: uint32): BlaiForwardNpuPlan =
  ## Convenience result-returning wrapper for bounded `forward_NPU` planning.
  blaiPlanForwardNpuInto(layer, layerIndex, dataBufferBytes, result)

proc blaiForwardNpuWeightMaterializeReadinessInto*(
    materialization: BlaiForwardNpuWeightMaterializeResult,
    outResult: var BlaiForwardNpuWeightMaterializeReadiness) =
  ## Derive readiness for the forward_NPU weight materialization step.
  outResult = default(BlaiForwardNpuWeightMaterializeReadiness)
  outResult.runnable = materialization.runnable
  outResult.weightLayer = materialization.weightLayer
  outResult.weightsMaterialized = materialization.weights.materialized
  if not outResult.runnable:
    outResult.firstBlock = blaiForwardNpuWeightMaterializeForwardPlan
  elif outResult.weightLayer and not outResult.weightsMaterialized:
    outResult.firstBlock = blaiForwardNpuWeightMaterializeWeights
  else:
    outResult.firstBlock = blaiForwardNpuWeightMaterializeNoBlock
  outResult.materialized =
    outResult.runnable and ((not outResult.weightLayer) or
      outResult.weightsMaterialized)

proc blaiForwardNpuWeightMaterializeReadiness*(
    materialization: BlaiForwardNpuWeightMaterializeResult):
    BlaiForwardNpuWeightMaterializeReadiness =
  ## Convenience wrapper for forward_NPU weight materialization readiness.
  blaiForwardNpuWeightMaterializeReadinessInto(materialization, result)

proc blaiMaterializeForwardNpuWeightsInto*(
    layer: BlaiCpuInstLayer64,
    layerIndex: uint32,
    useTflite: bool,
    weightBuf: var openArray[uint8],
    biasBuf: var openArray[int32],
    weightsIn: openArray[int32],
    biasesIn: openArray[int32],
    temporaryWeights: var openArray[int32],
    outResult: var BlaiForwardNpuWeightMaterializeResult,
    pack: uint32 = BlaiNpuWeightPack) =
  ## Recover the `forward_NPU` weight step using caller-owned buffers.
  outResult = default(BlaiForwardNpuWeightMaterializeResult)
  blaiPlanForwardNpuInto(layer, layerIndex, outResult.forwardPlan)
  outResult.runnable = outResult.forwardPlan.runnable
  if not outResult.runnable:
    blaiForwardNpuWeightMaterializeReadinessInto(
      outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.materialized = outResult.readiness.materialized
    return
  outResult.weightLayer = outResult.forwardPlan.weightBuffer.usesWeights
  if not outResult.weightLayer:
    blaiForwardNpuWeightMaterializeReadinessInto(
      outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.materialized = outResult.readiness.materialized
    return
  blaiNpuMaterializeWeightBuffersInto(
    layer, useTflite, weightBuf, biasBuf, weightsIn, biasesIn,
    temporaryWeights, outResult.weights, pack)
  blaiForwardNpuWeightMaterializeReadinessInto(
    outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.materialized = outResult.readiness.materialized

proc blaiMaterializeForwardNpuWeights*(
    layer: BlaiCpuInstLayer64,
    layerIndex: uint32,
    useTflite: bool,
    weightBuf: var openArray[uint8],
    biasBuf: var openArray[int32],
    weightsIn: openArray[int32],
    biasesIn: openArray[int32],
    temporaryWeights: var openArray[int32],
    pack: uint32 = BlaiNpuWeightPack): BlaiForwardNpuWeightMaterializeResult =
  ## Convenience wrapper for the recovered forward_NPU weight step.
  blaiMaterializeForwardNpuWeightsInto(
    layer, layerIndex, useTflite, weightBuf, biasBuf, weightsIn, biasesIn,
    temporaryWeights, result, pack)

proc blaiForwardLayerWeightWorkspaceReadinessInto*(
    materialization: BlaiForwardLayerWeightWorkspaceResult,
    outResult: var BlaiForwardLayerWeightWorkspaceReadiness) =
  ## Derive readiness for a per-layer CPU-stream to workspace materialization.
  outResult = default(BlaiForwardLayerWeightWorkspaceReadiness)
  outResult.runnable = materialization.runnable
  outResult.weightLayer = materialization.weightLayer
  outResult.streamLayerMatches = materialization.streamLayerMatches
  outResult.streamsFit = materialization.streamsFit
  outResult.cpuWeightsStored = materialization.cpuWeightsStored
  outResult.cpuBiasesStored = materialization.cpuBiasesStored
  outResult.materialized = materialization.materialized
  outResult.workspaceCopied = materialization.workspace.copied
  outResult.weightMaterializeFirstBlock = materialization.weights.firstBlock
  outResult.workspaceFirstBlock = materialization.workspace.firstBlock
  if not outResult.runnable:
    outResult.firstBlock = blaiForwardLayerWeightWorkspaceForwardPlan
  elif outResult.weightLayer and
      (not outResult.streamLayerMatches or not outResult.streamsFit):
    outResult.firstBlock = blaiForwardLayerWeightWorkspaceStream
  elif outResult.weightLayer and
      (not outResult.cpuWeightsStored or not outResult.cpuBiasesStored):
    outResult.firstBlock = blaiForwardLayerWeightWorkspaceCpuDecode
  elif outResult.weightLayer and not outResult.materialized:
    outResult.firstBlock = blaiForwardLayerWeightWorkspaceMaterialize
  elif outResult.weightLayer and not outResult.workspaceCopied:
    outResult.firstBlock = blaiForwardLayerWeightWorkspaceStorage
  else:
    outResult.firstBlock = blaiForwardLayerWeightWorkspaceNoBlock
  if not outResult.runnable:
    outResult.workspaceStored = false
  elif not outResult.weightLayer:
    outResult.workspaceStored = true
  else:
    outResult.workspaceStored =
      outResult.streamLayerMatches and outResult.streamsFit and
      outResult.cpuWeightsStored and outResult.cpuBiasesStored and
      outResult.materialized and outResult.workspaceCopied

proc blaiForwardLayerWeightWorkspaceReadiness*(
    materialization: BlaiForwardLayerWeightWorkspaceResult):
    BlaiForwardLayerWeightWorkspaceReadiness =
  ## Convenience wrapper for layer weight workspace readiness.
  blaiForwardLayerWeightWorkspaceReadinessInto(materialization, result)

proc blaiFinalizeForwardLayerWeightWorkspace(
    outResult: var BlaiForwardLayerWeightWorkspaceResult) =
  blaiForwardLayerWeightWorkspaceReadinessInto(
    outResult, outResult.readiness)
  outResult.weightMaterializeFirstBlock =
    outResult.readiness.weightMaterializeFirstBlock
  outResult.workspaceFirstBlock = outResult.readiness.workspaceFirstBlock
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.workspaceStored = outResult.readiness.workspaceStored

proc blaiMaterializeForwardLayerWeightsInWorkspaceInto*(
    layers: openArray[BlaiCpuInstLayer64],
    layerIndex: uint32,
    useTflite: bool,
    workspace: BlaiForwardModelWorkspacePlan,
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor: BlaiCpuStreamCursor,
    biasCursor: BlaiCpuStreamCursor,
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    workspaceBytes: var openArray[uint8],
    outResult: var BlaiForwardLayerWeightWorkspaceResult,
    pack: uint32 = BlaiNpuWeightPack) =
  ## Decode CPU model streams, reorder NPU weights, and store them in workspace.
  outResult = default(BlaiForwardLayerWeightWorkspaceResult)
  let layerCursor = blaiRecoveredLayerCursor(layerIndex, layers.len)
  if not layerCursor.valid:
    blaiForwardLayerWeightWorkspaceReadinessInto(
      outResult, outResult.readiness)
    outResult.weightMaterializeFirstBlock =
      outResult.readiness.weightMaterializeFirstBlock
    outResult.workspaceFirstBlock = outResult.readiness.workspaceFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.workspaceStored = outResult.readiness.workspaceStored
    return
  let layer = layers[layerCursor.index]
  var forwardPlan: BlaiForwardNpuPlan
  blaiPlanForwardNpuInto(layer, layerIndex, forwardPlan)
  outResult.runnable = forwardPlan.runnable
  if not outResult.runnable:
    blaiForwardLayerWeightWorkspaceReadinessInto(
      outResult, outResult.readiness)
    outResult.weightMaterializeFirstBlock =
      outResult.readiness.weightMaterializeFirstBlock
    outResult.workspaceFirstBlock = outResult.readiness.workspaceFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.workspaceStored = outResult.readiness.workspaceStored
    return

  var weightPlan: BlaiWeightBufferPlan
  blaiWeightBufferPlanInto(layer, weightPlan)
  outResult.weightLayer = weightPlan.usesWeights
  outResult.nextWeightCursor = weightCursor
  outResult.nextBiasCursor = biasCursor
  if not outResult.weightLayer:
    outResult.streamLayerMatches = true
    outResult.streamsFit = true
    outResult.cpuWeightsStored = true
    outResult.cpuBiasesStored = true
    outResult.materialized = true
    blaiForwardLayerWeightWorkspaceReadinessInto(
      outResult, outResult.readiness)
    outResult.weightMaterializeFirstBlock =
      outResult.readiness.weightMaterializeFirstBlock
    outResult.workspaceFirstBlock = outResult.readiness.workspaceFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.workspaceStored = outResult.readiness.workspaceStored
    return

  blaiCpuWeightStreamSegmentInto(
    layers, weightCursor, blaiOpenArrayLenU32(cpuWeightBytes),
    outResult.weightStream)
  blaiCpuBiasStreamSegmentInto(
    layers, biasCursor, blaiOpenArrayLenU32(cpuBiasBytes), useTflite,
    outResult.biasStream)
  let layerIndexValue = blaiLayerIndexValue(layerIndex)
  outResult.streamLayerMatches =
    outResult.weightStream.active and outResult.biasStream.active and
    outResult.weightStream.plan.layerIndex == layerIndexValue and
    outResult.biasStream.plan.layerIndex == layerIndexValue
  outResult.streamsFit = outResult.streamLayerMatches and
    outResult.weightStream.fits and outResult.biasStream.fits
  if not outResult.streamsFit:
    blaiForwardLayerWeightWorkspaceReadinessInto(
      outResult, outResult.readiness)
    outResult.weightMaterializeFirstBlock =
      outResult.readiness.weightMaterializeFirstBlock
    outResult.workspaceFirstBlock = outResult.readiness.workspaceFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.workspaceStored = outResult.readiness.workspaceStored
    return

  var weightStore: BlaiCpuWeightStoreResult
  let weightStreamStart = blaiCpuStreamStartCursor(outResult.weightStream.cursor)
  if weightStreamStart.valid:
    blaiStoreCpuWeightValuesInto(
      outResult.weightStream.plan, cpuWeightBytes,
      weightStreamStart.startIndex, decodedWeights, weightStore)
  else:
    outResult.streamsFit = false
  outResult.cpuWeightsStored = weightStore.stored
  var biasStore: BlaiCpuBiasStoreResult
  let biasStreamStart = blaiCpuStreamStartCursor(outResult.biasStream.cursor)
  if biasStreamStart.valid:
    blaiStoreCpuBiasesInto(
      outResult.biasStream.plan, cpuBiasBytes,
      biasStreamStart.startIndex, decodedBiases, biasStore)
  else:
    outResult.streamsFit = false
  outResult.cpuBiasesStored = biasStore.stored
  if not outResult.cpuWeightsStored or not outResult.cpuBiasesStored:
    blaiForwardLayerWeightWorkspaceReadinessInto(
      outResult, outResult.readiness)
    outResult.weightMaterializeFirstBlock =
      outResult.readiness.weightMaterializeFirstBlock
    outResult.workspaceFirstBlock = outResult.readiness.workspaceFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.workspaceStored = outResult.readiness.workspaceStored
    return

  blaiMaterializeForwardNpuWeightsInto(
    layer, layerIndex, useTflite,
    npuWeightBytes, npuBiases, decodedWeights, decodedBiases,
    temporaryWeights, outResult.weights, pack)
  outResult.materialized = outResult.weights.materialized
  if not outResult.materialized:
    blaiForwardLayerWeightWorkspaceReadinessInto(
      outResult, outResult.readiness)
    outResult.weightMaterializeFirstBlock =
      outResult.readiness.weightMaterializeFirstBlock
    outResult.workspaceFirstBlock = outResult.readiness.workspaceFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.workspaceStored = outResult.readiness.workspaceStored
    return

  blaiStoreForwardWeightsInWorkspaceInto(
    workspace, npuWeightBytes, outResult.weights.weights.weightCursor,
    npuBiases, outResult.weights.weights.biasCursor, workspaceBytes,
    outResult.workspace)
  blaiForwardLayerWeightWorkspaceReadinessInto(
    outResult, outResult.readiness)
  outResult.weightMaterializeFirstBlock =
    outResult.readiness.weightMaterializeFirstBlock
  outResult.workspaceFirstBlock = outResult.readiness.workspaceFirstBlock
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.workspaceStored = outResult.readiness.workspaceStored
  if outResult.workspaceStored:
    outResult.nextWeightCursor = outResult.weightStream.nextCursor
    outResult.nextBiasCursor = outResult.biasStream.nextCursor

proc blaiMaterializeForwardLayerWeightsInWorkspace*(
    layers: openArray[BlaiCpuInstLayer64],
    layerIndex: uint32,
    useTflite: bool,
    workspace: BlaiForwardModelWorkspacePlan,
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor: BlaiCpuStreamCursor,
    biasCursor: BlaiCpuStreamCursor,
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    workspaceBytes: var openArray[uint8],
    pack: uint32 = BlaiNpuWeightPack): BlaiForwardLayerWeightWorkspaceResult =
  ## Convenience result-returning wrapper for layer weight workspace materialization.
  blaiMaterializeForwardLayerWeightsInWorkspaceInto(
    layers, layerIndex, useTflite, workspace, cpuWeightBytes, cpuBiasBytes,
    weightCursor, biasCursor, decodedWeights, decodedBiases, npuWeightBytes,
    npuBiases, temporaryWeights, workspaceBytes, result, pack)

proc blaiMaterializeForwardLayerWeightsInWorkspaceInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    layerIndex: uint32,
    useTflite: bool,
    workspace: BlaiForwardModelWorkspacePlan,
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor: BlaiCpuStreamCursor,
    biasCursor: BlaiCpuStreamCursor,
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    workspaceBytes: var openArray[uint8],
    outResult: var BlaiForwardLayerWeightWorkspaceResult,
    pack: uint32 = BlaiNpuWeightPack) =
  ## Decode CPU model streams and store NPU weights for parsed layer state.
  outResult = default(BlaiForwardLayerWeightWorkspaceResult)
  let layerCursor = blaiRecoveredLayerCursor(layerIndex, layers.len)
  if not layerCursor.valid or not layers[layerCursor.index].active:
    blaiFinalizeForwardLayerWeightWorkspace(outResult)
    return
  let layer = layers[layerCursor.index].layer
  var forwardPlan: BlaiForwardNpuPlan
  blaiPlanForwardNpuInto(layer, layerIndex, forwardPlan)
  outResult.runnable = forwardPlan.runnable
  if not outResult.runnable:
    blaiFinalizeForwardLayerWeightWorkspace(outResult)
    return

  var weightPlan: BlaiWeightBufferPlan
  blaiWeightBufferPlanInto(layer, weightPlan)
  outResult.weightLayer = weightPlan.usesWeights
  outResult.nextWeightCursor = weightCursor
  outResult.nextBiasCursor = biasCursor
  if not outResult.weightLayer:
    outResult.streamLayerMatches = true
    outResult.streamsFit = true
    outResult.cpuWeightsStored = true
    outResult.cpuBiasesStored = true
    outResult.materialized = true
    blaiFinalizeForwardLayerWeightWorkspace(outResult)
    return

  blaiCpuWeightStreamSegmentInto(
    layers, weightCursor, blaiOpenArrayLenU32(cpuWeightBytes),
    outResult.weightStream)
  blaiCpuBiasStreamSegmentInto(
    layers, biasCursor, blaiOpenArrayLenU32(cpuBiasBytes), useTflite,
    outResult.biasStream)
  let layerIndexValue = blaiLayerIndexValue(layerIndex)
  outResult.streamLayerMatches =
    outResult.weightStream.active and outResult.biasStream.active and
    outResult.weightStream.plan.layerIndex == layerIndexValue and
    outResult.biasStream.plan.layerIndex == layerIndexValue
  outResult.streamsFit = outResult.streamLayerMatches and
    outResult.weightStream.fits and outResult.biasStream.fits
  if not outResult.streamsFit:
    blaiFinalizeForwardLayerWeightWorkspace(outResult)
    return

  var weightStore: BlaiCpuWeightStoreResult
  let weightStreamStart = blaiCpuStreamStartCursor(outResult.weightStream.cursor)
  if weightStreamStart.valid:
    blaiStoreCpuWeightValuesInto(
      outResult.weightStream.plan, cpuWeightBytes,
      weightStreamStart.startIndex, decodedWeights, weightStore)
  else:
    outResult.streamsFit = false
  outResult.cpuWeightsStored = weightStore.stored
  var biasStore: BlaiCpuBiasStoreResult
  let biasStreamStart = blaiCpuStreamStartCursor(outResult.biasStream.cursor)
  if biasStreamStart.valid:
    blaiStoreCpuBiasesInto(
      outResult.biasStream.plan, cpuBiasBytes,
      biasStreamStart.startIndex, decodedBiases, biasStore)
  else:
    outResult.streamsFit = false
  outResult.cpuBiasesStored = biasStore.stored
  if not outResult.cpuWeightsStored or not outResult.cpuBiasesStored:
    blaiFinalizeForwardLayerWeightWorkspace(outResult)
    return

  blaiMaterializeForwardNpuWeightsInto(
    layer, layerIndex, useTflite,
    npuWeightBytes, npuBiases, decodedWeights, decodedBiases,
    temporaryWeights, outResult.weights, pack)
  outResult.materialized = outResult.weights.materialized
  if not outResult.materialized:
    blaiFinalizeForwardLayerWeightWorkspace(outResult)
    return

  blaiStoreForwardWeightsInWorkspaceInto(
    workspace, npuWeightBytes, outResult.weights.weights.weightCursor,
    npuBiases, outResult.weights.weights.biasCursor, workspaceBytes,
    outResult.workspace)
  blaiFinalizeForwardLayerWeightWorkspace(outResult)
  if outResult.workspaceStored:
    outResult.nextWeightCursor = outResult.weightStream.nextCursor
    outResult.nextBiasCursor = outResult.biasStream.nextCursor

proc blaiMaterializeForwardLayerWeightsInWorkspace*(
    layers: openArray[BlaiCpuParsedLayerState],
    layerIndex: uint32,
    useTflite: bool,
    workspace: BlaiForwardModelWorkspacePlan,
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor: BlaiCpuStreamCursor,
    biasCursor: BlaiCpuStreamCursor,
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    workspaceBytes: var openArray[uint8],
    pack: uint32 = BlaiNpuWeightPack): BlaiForwardLayerWeightWorkspaceResult =
  ## Convenience wrapper for parsed-state layer weight workspace materialization.
  blaiMaterializeForwardLayerWeightsInWorkspaceInto(
    layers, layerIndex, useTflite, workspace, cpuWeightBytes, cpuBiasBytes,
    weightCursor, biasCursor, decodedWeights, decodedBiases, npuWeightBytes,
    npuBiases, temporaryWeights, workspaceBytes, result, pack)

proc blaiForwardModelWeightWorkspaceStorageInto*(
    materialization: BlaiForwardModelWeightWorkspaceResult,
    outResult: var BlaiForwardModelWeightWorkspaceStorage) =
  ## Derive model weight/bias workspace storage status.
  outResult = default(BlaiForwardModelWeightWorkspaceStorage)
  outResult.layerCount = materialization.layerCount
  outResult.attemptedLayerCount = materialization.attemptedLayerCount
  outResult.weightLayerCount = materialization.weightLayerCount
  outResult.storedLayerCount = materialization.storedLayerCount
  outResult.blockedLayerCount = materialization.blockedLayerCount
  outResult.firstBlockedLayer = materialization.firstBlockedLayer
  outResult.lastStoredLayer = materialization.lastStoredLayer
  outResult.firstBlockedLayerFirstBlock =
    materialization.firstBlockedLayerFirstBlock
  outResult.firstBlockedWeightMaterializeFirstBlock =
    materialization.firstBlockedWeightMaterializeFirstBlock
  outResult.firstBlockedWorkspaceFirstBlock =
    materialization.firstBlockedWorkspaceFirstBlock
  outResult.expectedWeightCursor = materialization.expectedWeightCursor
  outResult.actualWeightCursor = materialization.nextWeightCursor
  outResult.expectedBiasCursor = materialization.expectedBiasCursor
  outResult.actualBiasCursor = materialization.nextBiasCursor
  blaiCompareCpuStreamCursorInto(
    outResult.expectedWeightCursor, outResult.actualWeightCursor,
    outResult.weightCursorCompare)
  blaiCompareCpuStreamCursorInto(
    outResult.expectedBiasCursor, outResult.actualBiasCursor,
    outResult.biasCursorCompare)
  outResult.weightStreamConsumed = outResult.weightCursorCompare.matched
  outResult.biasStreamConsumed = outResult.biasCursorCompare.matched
  outResult.streamsConsumed =
    outResult.weightStreamConsumed and outResult.biasStreamConsumed
  if outResult.blockedLayerCount != 0:
    outResult.firstBlock = blaiForwardModelWeightWorkspaceLayer
  elif not outResult.streamsConsumed:
    outResult.firstBlock = blaiForwardModelWeightWorkspaceStreamConsumption
  else:
    outResult.firstBlock = blaiForwardModelWeightWorkspaceNoBlock
  outResult.stored = outResult.blockedLayerCount == 0 and
    outResult.storedLayerCount == outResult.weightLayerCount and
    outResult.streamsConsumed

proc blaiForwardModelWeightWorkspaceStorage*(
    materialization: BlaiForwardModelWeightWorkspaceResult):
    BlaiForwardModelWeightWorkspaceStorage =
  ## Convenience wrapper for model weight/bias workspace storage status.
  blaiForwardModelWeightWorkspaceStorageInto(materialization, result)

proc blaiMaterializeForwardModelWeightsInWorkspaceInto*(
    layers: openArray[BlaiCpuInstLayer64],
    useTflite: bool,
    workspace: BlaiForwardModelWorkspacePlan,
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    workspaceBytes: var openArray[uint8],
    outResult: var BlaiForwardModelWeightWorkspaceResult,
    pack: uint32 = BlaiNpuWeightPack) =
  ## Materialize every NPU weight layer from CPU streams into reusable workspace.
  outResult = default(BlaiForwardModelWeightWorkspaceResult)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.firstBlockedLayer = -1
  outResult.lastStoredLayer = -1
  outResult.nextWeightCursor = blaiCpuStreamCursor()
  outResult.nextBiasCursor = blaiCpuStreamCursor()
  blaiCpuStreamEndCursorsInto(
    layers, useTflite, outResult.expectedWeightCursor,
    outResult.expectedBiasCursor)

  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    outResult.blockedLayerCount = 1
    outResult.firstBlockedLayerCaptured = true
    blaiForwardModelWeightWorkspaceStorageInto(outResult, outResult.storage)
    outResult.firstBlock = outResult.storage.firstBlock
    outResult.allStored = outResult.storage.stored
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      inc outResult.blockedLayerCount
      outResult.firstBlockedLayerCaptured = true
      break
    let layer = layers[layerCursor.layerIndex]
    if layer.npuOn == 0:
      inc outResult.skippedLayerCount
      continue
    inc outResult.attemptedLayerCount
    var weightPlan: BlaiWeightBufferPlan
    blaiWeightBufferPlanInto(layer, weightPlan)
    if not weightPlan.usesWeights:
      inc outResult.skippedLayerCount
      continue

    inc outResult.weightLayerCount
    let workspaceLayerIndex =
      blaiLayerCursorIndexAbi(layerCursor.layerIndex)
    if not workspaceLayerIndex.valid:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        let diagnosticLayerIndex = blaiLayerIndexAbi(layerCursor.layerIndex)
        if diagnosticLayerIndex.valid:
          outResult.firstBlockedLayer = diagnosticLayerIndex.value
        outResult.firstBlockedLayerCaptured = true
      break
    var layerResult: BlaiForwardLayerWeightWorkspaceResult
    blaiMaterializeForwardLayerWeightsInWorkspaceInto(
      layers, workspaceLayerIndex.value, useTflite, workspace,
      cpuWeightBytes, cpuBiasBytes,
      outResult.nextWeightCursor, outResult.nextBiasCursor,
      decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
      temporaryWeights, workspaceBytes, layerResult, pack)
    outResult.lastLayer = layerResult
    if layerResult.workspaceStored:
      inc outResult.storedLayerCount
      outResult.lastStoredLayer = blaiLayerIndexValue(layerCursor.layerIndex)
      outResult.nextWeightCursor = layerResult.nextWeightCursor
      outResult.nextBiasCursor = layerResult.nextBiasCursor
    else:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        outResult.firstBlockedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
        outResult.firstBlockedLayerCaptured = true
        outResult.firstBlockedLayerReadiness = layerResult.readiness
        outResult.firstBlockedLayerFirstBlock = layerResult.firstBlock
        outResult.firstBlockedWeightMaterializeFirstBlock =
          layerResult.weightMaterializeFirstBlock
        outResult.firstBlockedWorkspaceFirstBlock =
          layerResult.workspaceFirstBlock
      break

  blaiForwardModelWeightWorkspaceStorageInto(outResult, outResult.storage)
  outResult.weightCursorCompare = outResult.storage.weightCursorCompare
  outResult.biasCursorCompare = outResult.storage.biasCursorCompare
  outResult.weightStreamConsumed = outResult.storage.weightStreamConsumed
  outResult.biasStreamConsumed = outResult.storage.biasStreamConsumed
  outResult.streamsConsumed = outResult.storage.streamsConsumed
  outResult.firstBlock = outResult.storage.firstBlock
  outResult.allStored = outResult.storage.stored

proc blaiMaterializeForwardModelWeightsInWorkspace*(
    layers: openArray[BlaiCpuInstLayer64],
    useTflite: bool,
    workspace: BlaiForwardModelWorkspacePlan,
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    workspaceBytes: var openArray[uint8],
    pack: uint32 = BlaiNpuWeightPack): BlaiForwardModelWeightWorkspaceResult =
  ## Convenience wrapper for model weight workspace materialization.
  blaiMaterializeForwardModelWeightsInWorkspaceInto(
    layers, useTflite, workspace, cpuWeightBytes, cpuBiasBytes,
    decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
    temporaryWeights, workspaceBytes, result, pack)

proc blaiMaterializeForwardModelWeightsInWorkspaceInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    workspace: BlaiForwardModelWorkspacePlan,
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    workspaceBytes: var openArray[uint8],
    outResult: var BlaiForwardModelWeightWorkspaceResult,
    pack: uint32 = BlaiNpuWeightPack) =
  ## Materialize active parsed-state NPU weight layers into reusable workspace.
  outResult = default(BlaiForwardModelWeightWorkspaceResult)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.firstBlockedLayer = -1
  outResult.lastStoredLayer = -1
  outResult.nextWeightCursor = blaiCpuStreamCursor()
  outResult.nextBiasCursor = blaiCpuStreamCursor()
  blaiCpuStreamEndCursorsInto(
    layers, useTflite, outResult.expectedWeightCursor,
    outResult.expectedBiasCursor)

  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    outResult.blockedLayerCount = 1
    outResult.firstBlockedLayerCaptured = true
    blaiForwardModelWeightWorkspaceStorageInto(outResult, outResult.storage)
    outResult.firstBlock = outResult.storage.firstBlock
    outResult.allStored = outResult.storage.stored
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      inc outResult.blockedLayerCount
      outResult.firstBlockedLayerCaptured = true
      break
    let layerState = layers[layerCursor.layerIndex]
    if not layerState.active or layerState.layer.npuOn == 0:
      inc outResult.skippedLayerCount
      continue
    inc outResult.attemptedLayerCount
    var weightPlan: BlaiWeightBufferPlan
    blaiWeightBufferPlanInto(layerState.layer, weightPlan)
    if not weightPlan.usesWeights:
      inc outResult.skippedLayerCount
      continue

    inc outResult.weightLayerCount
    let workspaceLayerIndex =
      blaiLayerCursorIndexAbi(layerCursor.layerIndex)
    if not workspaceLayerIndex.valid:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        let diagnosticLayerIndex = blaiLayerIndexAbi(layerCursor.layerIndex)
        if diagnosticLayerIndex.valid:
          outResult.firstBlockedLayer = diagnosticLayerIndex.value
        outResult.firstBlockedLayerCaptured = true
      break
    var layerResult: BlaiForwardLayerWeightWorkspaceResult
    blaiMaterializeForwardLayerWeightsInWorkspaceInto(
      layers, workspaceLayerIndex.value, useTflite, workspace,
      cpuWeightBytes, cpuBiasBytes,
      outResult.nextWeightCursor, outResult.nextBiasCursor,
      decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
      temporaryWeights, workspaceBytes, layerResult, pack)
    outResult.lastLayer = layerResult
    if layerResult.workspaceStored:
      inc outResult.storedLayerCount
      outResult.lastStoredLayer = blaiLayerIndexValue(layerCursor.layerIndex)
      outResult.nextWeightCursor = layerResult.nextWeightCursor
      outResult.nextBiasCursor = layerResult.nextBiasCursor
    else:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        outResult.firstBlockedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
        outResult.firstBlockedLayerCaptured = true
        outResult.firstBlockedLayerReadiness = layerResult.readiness
        outResult.firstBlockedLayerFirstBlock = layerResult.firstBlock
        outResult.firstBlockedWeightMaterializeFirstBlock =
          layerResult.weightMaterializeFirstBlock
        outResult.firstBlockedWorkspaceFirstBlock =
          layerResult.workspaceFirstBlock
      break

  blaiForwardModelWeightWorkspaceStorageInto(outResult, outResult.storage)
  outResult.weightCursorCompare = outResult.storage.weightCursorCompare
  outResult.biasCursorCompare = outResult.storage.biasCursorCompare
  outResult.weightStreamConsumed = outResult.storage.weightStreamConsumed
  outResult.biasStreamConsumed = outResult.storage.biasStreamConsumed
  outResult.streamsConsumed = outResult.storage.streamsConsumed
  outResult.firstBlock = outResult.storage.firstBlock
  outResult.allStored = outResult.storage.stored

proc blaiMaterializeForwardModelWeightsInWorkspace*(
    layers: openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    workspace: BlaiForwardModelWorkspacePlan,
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    workspaceBytes: var openArray[uint8],
    pack: uint32 = BlaiNpuWeightPack): BlaiForwardModelWeightWorkspaceResult =
  ## Convenience wrapper for parsed-state model weight workspace materialization.
  blaiMaterializeForwardModelWeightsInWorkspaceInto(
    layers, useTflite, workspace, cpuWeightBytes, cpuBiasBytes,
    decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
    temporaryWeights, workspaceBytes, result, pack)

proc blaiAddForwardCacheRange(plan: var BlaiForwardNpuRunPlan,
                              cacheRange: BlaiCacheRange) =
  if cacheRange.active and plan.cacheRangeCount < BlaiForwardMaxCacheRanges.uint32:
    let cacheIndex = blaiForwardCacheRangeCount(plan.cacheRangeCount)
    plan.cacheRanges[cacheIndex] = cacheRange
    inc plan.cacheRangeCount

proc blaiForwardNpuRunConfigReadinessInto*(
    forwardPlan: BlaiForwardNpuPlan,
    instAddr: uint32,
    dataBufferAddr: uint32,
    weightAddr: uint32,
    biasAddr: uint32,
    outResult: var BlaiForwardNpuRunConfigReadiness) =
  ## Explain whether recovered `forward_NPU` layer config can be issued.
  outResult = default(BlaiForwardNpuRunConfigReadiness)
  outResult.runnable = forwardPlan.runnable
  outResult.bufferFits = forwardPlan.bufferFits
  outResult.hasInstructionBuffer = instAddr != 0'u32
  outResult.hasDataBuffer = dataBufferAddr != 0'u32
  outResult.weightLayer = forwardPlan.weightBuffer.usesWeights
  outResult.needsWeightBuffers = outResult.weightLayer
  outResult.hasWeightBuffer = weightAddr != 0'u32
  outResult.hasBiasBuffer = biasAddr != 0'u32
  outResult.weightBuffersReady =
    (not outResult.needsWeightBuffers) or
    (outResult.hasWeightBuffer and outResult.hasBiasBuffer)
  outResult.configurable =
    outResult.runnable and outResult.bufferFits and
    outResult.hasInstructionBuffer and outResult.hasDataBuffer and
    outResult.weightBuffersReady
  if not outResult.runnable:
    outResult.firstBlock = blaiForwardNpuRunConfigForwardPlan
  elif not outResult.bufferFits:
    outResult.firstBlock = blaiForwardNpuRunConfigBufferFit
  elif not outResult.hasInstructionBuffer:
    outResult.firstBlock = blaiForwardNpuRunConfigInstructionBuffer
  elif not outResult.hasDataBuffer:
    outResult.firstBlock = blaiForwardNpuRunConfigDataBuffer
  elif not outResult.weightBuffersReady:
    outResult.firstBlock = blaiForwardNpuRunConfigWeightBuffers
  else:
    outResult.firstBlock = blaiForwardNpuRunConfigNoBlock

proc blaiForwardNpuRunConfigReadiness*(
    forwardPlan: BlaiForwardNpuPlan,
    instAddr: uint32,
    dataBufferAddr: uint32,
    weightAddr: uint32 = 0'u32,
    biasAddr: uint32 = 0'u32): BlaiForwardNpuRunConfigReadiness =
  ## Convenience wrapper for recovered `forward_NPU` config readiness.
  blaiForwardNpuRunConfigReadinessInto(
    forwardPlan, instAddr, dataBufferAddr, weightAddr, biasAddr, result)

proc blaiPlanForwardNpuRunInto*(
    layer: BlaiCpuInstLayer64,
    layerIndex: uint32,
    dataBufferBytes: uint32,
    instAddr: uint32,
    dataBufferAddr: uint32,
    outResult: var BlaiForwardNpuRunPlan,
    weightAddr: uint32 = 0'u32,
    biasAddr: uint32 = 0'u32) =
  ## Recover the `forward_NPU` run-preparation sequence as typed plan data.
  ##
  ## This covers the SDK steps after instruction generation and tensor/weight
  ## planning: cache ranges for staged inputs/readback, layer-config arguments,
  ## and the null weight/bias address convention for non-weight layers. It does
  ## not execute cache operations, take the NPU lock, or start inference.
  outResult = default(BlaiForwardNpuRunPlan)
  blaiPlanForwardNpuInto(
    layer, layerIndex, dataBufferBytes, outResult.forwardPlan)
  outResult.runnable = outResult.forwardPlan.runnable
  outResult.bufferFits = outResult.forwardPlan.bufferFits
  blaiForwardNpuRunConfigReadinessInto(
    outResult.forwardPlan, instAddr, dataBufferAddr, weightAddr, biasAddr,
    outResult.configReadiness)
  outResult.configurable = outResult.configReadiness.configurable
  if not outResult.runnable:
    return

  outResult.weightLayer = outResult.forwardPlan.weightBuffer.usesWeights
  outResult.layerConfig = NpuLayerConfig(
    buffers: NpuLayerBuffers(
      instAddr: instAddr,
      weightAddr: if outResult.weightLayer: weightAddr else: 0'u32,
      biasAddr: if outResult.weightLayer: biasAddr else: 0'u32),
    inputBufferAddr: dataBufferAddr,
    patchSize: outResult.forwardPlan.patchSize,
    firstLayer: outResult.forwardPlan.firstLayer,
    resetUnsignedInput: not outResult.forwardPlan.firstLayer)

  for cacheRange in outResult.forwardPlan.inputCleanRanges:
    blaiAddForwardCacheRange(outResult, cacheRange)
  blaiAddForwardCacheRange(outResult, outResult.forwardPlan.outputInvalidateRange)
  blaiAddForwardCacheRange(outResult, outResult.forwardPlan.midOutputInvalidateRange)

proc blaiPlanForwardNpuRun*(
    layer: BlaiCpuInstLayer64,
    layerIndex: uint32,
    dataBufferBytes: uint32,
    instAddr: uint32,
    dataBufferAddr: uint32,
    weightAddr: uint32 = 0'u32,
    biasAddr: uint32 = 0'u32): BlaiForwardNpuRunPlan =
  ## Convenience result-returning wrapper for run-preparation planning.
  blaiPlanForwardNpuRunInto(
    layer, layerIndex, dataBufferBytes, instAddr, dataBufferAddr, result,
    weightAddr, biasAddr)

proc blaiForwardNpuRunPlanEvidenceInto*(
    plan: BlaiForwardNpuRunPlan,
    expectedLayerIndex: uint32,
    expectedFirstLayer: bool,
    expectedResetUnsignedInput: bool,
    expectedInstAddr: uint32,
    expectedDataAddr: uint32,
    expectedWeightAddr: uint32,
    expectedBiasAddr: uint32,
    expectedPatchSize: uint32,
    outResult: var BlaiForwardNpuRunPlanEvidence) =
  ## Derive focused layer-config/cache evidence from a recovered run plan.
  outResult = default(BlaiForwardNpuRunPlanEvidence)
  outResult.configurable = plan.configurable
  outResult.sdkIndexMatches =
    plan.forwardPlan.layerIndex == expectedLayerIndex
  outResult.firstLayerMatches = plan.layerConfig.firstLayer == expectedFirstLayer
  outResult.resetUnsignedInputMatches =
    plan.layerConfig.resetUnsignedInput == expectedResetUnsignedInput
  outResult.patchSizeMatches = plan.layerConfig.patchSize == expectedPatchSize
  outResult.instructionAddrMatches =
    plan.layerConfig.buffers.instAddr == expectedInstAddr
  outResult.weightAddrMatches =
    plan.layerConfig.buffers.weightAddr == expectedWeightAddr
  outResult.biasAddrMatches =
    plan.layerConfig.buffers.biasAddr == expectedBiasAddr
  outResult.dataAddrMatches = plan.layerConfig.inputBufferAddr == expectedDataAddr
  outResult.sdkPolicyMatches =
    outResult.sdkIndexMatches and outResult.firstLayerMatches and
      outResult.resetUnsignedInputMatches
  outResult.bufferAddressesMatch =
    outResult.instructionAddrMatches and outResult.weightAddrMatches and
      outResult.biasAddrMatches and outResult.dataAddrMatches
  outResult.firstCacheRangePresent = plan.cacheRangeCount >= 1'u32
  if outResult.firstCacheRangePresent:
    let firstRange = plan.cacheRanges[0]
    outResult.firstCacheRangeClean =
      firstRange.active and firstRange.operation == blaiCacheClean
    outResult.firstCacheRangeOffsetMatches = firstRange.offset == 0'u32
    outResult.firstCacheRangeBytesFitPatch =
      firstRange.bytes >= 1'u32 and firstRange.bytes <= expectedPatchSize
  outResult.firstDataCachePlanValid =
    outResult.firstCacheRangePresent and outResult.firstCacheRangeClean and
      outResult.firstCacheRangeOffsetMatches and
      outResult.firstCacheRangeBytesFitPatch
  outResult.valid =
    outResult.configurable and outResult.sdkPolicyMatches and
      outResult.patchSizeMatches and outResult.bufferAddressesMatch and
      outResult.firstDataCachePlanValid

proc blaiForwardNpuRunPlanEvidence*(
    plan: BlaiForwardNpuRunPlan,
    expectedLayerIndex: uint32,
    expectedFirstLayer: bool,
    expectedResetUnsignedInput: bool,
    expectedInstAddr: uint32,
    expectedDataAddr: uint32,
    expectedWeightAddr: uint32,
    expectedBiasAddr: uint32,
    expectedPatchSize: uint32): BlaiForwardNpuRunPlanEvidence =
  ## Convenience wrapper for focused layer-config/cache evidence.
  blaiForwardNpuRunPlanEvidenceInto(
    plan, expectedLayerIndex, expectedFirstLayer, expectedResetUnsignedInput,
    expectedInstAddr, expectedDataAddr, expectedWeightAddr, expectedBiasAddr,
    expectedPatchSize, result)

proc blaiForwardActiveDataMappingEvidenceInto*(
    run: BlaiForwardNpuRunPlanEvidence,
    data: BlaiForwardWorkspaceDataSlotEvidence,
    outResult: var BlaiForwardActiveDataMappingEvidence) =
  ## Derive focused active DATA mapping and staging evidence.
  outResult = default(BlaiForwardActiveDataMappingEvidence)
  outResult.runPlanValid = run.valid
  outResult.dataSlotsValid = data.slotsValid
  outResult.patchSizeMatches =
    run.patchSizeMatches and data.patchSize != 0'u32
  outResult.inputOutputDistinct = data.slotsDistinct
  outResult.stagedInputReady =
    data.inputFits and data.stagedInputPresent and data.stagedInputMatches
  outResult.outputSlotReady = data.outputFits and data.outputOffsetMatches
  outResult.firstDataCacheReady = run.firstDataCachePlanValid
  outResult.valid =
    outResult.runPlanValid and outResult.dataSlotsValid and
      outResult.patchSizeMatches and outResult.inputOutputDistinct and
      outResult.stagedInputReady and outResult.outputSlotReady and
      outResult.firstDataCacheReady

proc blaiForwardActiveDataMappingEvidence*(
    run: BlaiForwardNpuRunPlanEvidence,
    data: BlaiForwardWorkspaceDataSlotEvidence):
    BlaiForwardActiveDataMappingEvidence =
  ## Convenience wrapper for active DATA mapping evidence.
  blaiForwardActiveDataMappingEvidenceInto(run, data, result)

proc blaiForwardMaterializedLaunchBridgeEvidenceInto*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    workspace: BlaiForwardModelWorkspacePlan,
    runPlan: BlaiForwardNpuRunPlan,
    runEvidence: BlaiForwardNpuRunPlanEvidence,
    streamSemantics: BlaiForwardWorkspaceInstructionStreamSemanticEvidence,
    workspaceBytes: BlaiForwardWorkspaceMaterializedByteEvidence,
    dataMapping: BlaiForwardActiveDataMappingEvidence,
    tempWeightBias: BlaiForwardNpuTemporaryWeightBiasBufferResult,
    tempEvidence: BlaiForwardNpuTemporaryWeightBiasBufferEvidence,
    outResult: var BlaiForwardMaterializedLaunchBridgeEvidence) =
  ## Compose materialized bytes and recovered launch configuration evidence.
  outResult = default(BlaiForwardMaterializedLaunchBridgeEvidence)
  outResult.materializationReady =
    materialization.allReady and materialization.readiness.ready and
      materialization.lastLayer.ready
  outResult.streamSemanticValid = streamSemantics.valid
  outResult.workspaceBytesValid = workspaceBytes.workspaceBytesValid
  outResult.tempWeightBiasValid =
    tempWeightBias.prepared and tempEvidence.valid
  outResult.dataMappingValid = dataMapping.valid
  outResult.runPlanValid = runPlan.configurable and runEvidence.valid
  outResult.instructionAddressMatchesWorkspace =
    runPlan.layerConfig.buffers.instAddr == workspace.instruction.address and
      runEvidence.instructionAddrMatches
  outResult.dataAddressMatchesWorkspace =
    runPlan.layerConfig.inputBufferAddr == workspace.data.address and
      runEvidence.dataAddrMatches
  outResult.weightAddressMatchesTemp =
    runPlan.layerConfig.buffers.weightAddr == tempWeightBias.weightAddr and
      runEvidence.weightAddrMatches
  outResult.biasAddressMatchesTemp =
    runPlan.layerConfig.buffers.biasAddr == tempWeightBias.biasAddr and
      runEvidence.biasAddrMatches
  outResult.instructionBytesMatchMaterialization =
    workspaceBytes.instructionBytes ==
      materialization.lastLayer.instructions.instructions.bytes
  outResult.weightBytesMatchMaterialization =
    workspaceBytes.weightBytes ==
      materialization.lastLayer.weights.workspace.weightBytes and
      tempEvidence.weightBytesMatch
  outResult.biasBytesMatchMaterialization =
    workspaceBytes.biasBytes ==
      materialization.lastLayer.weights.workspace.biasBytes and
      tempEvidence.biasBytesMatch
  outResult.byteEvidenceMatchesMaterialization =
    workspaceBytes.matches and outResult.instructionBytesMatchMaterialization and
      outResult.weightBytesMatchMaterialization and
      outResult.biasBytesMatchMaterialization
  outResult.cachePlanReady =
    runEvidence.firstDataCachePlanValid and dataMapping.firstDataCacheReady and
      tempEvidence.cacheValid
  outResult.launchAddressesCoherent =
    outResult.instructionAddressMatchesWorkspace and
      outResult.dataAddressMatchesWorkspace and
      outResult.weightAddressMatchesTemp and
      outResult.biasAddressMatchesTemp
  outResult.materializedLaunchReady =
    outResult.materializationReady and outResult.streamSemanticValid and
      outResult.workspaceBytesValid and outResult.tempWeightBiasValid and
      outResult.dataMappingValid and outResult.runPlanValid and
      outResult.byteEvidenceMatchesMaterialization and
      outResult.cachePlanReady and outResult.launchAddressesCoherent
  outResult.valid = outResult.materializedLaunchReady

proc blaiForwardMaterializedLaunchBridgeEvidence*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    workspace: BlaiForwardModelWorkspacePlan,
    runPlan: BlaiForwardNpuRunPlan,
    runEvidence: BlaiForwardNpuRunPlanEvidence,
    streamSemantics: BlaiForwardWorkspaceInstructionStreamSemanticEvidence,
    workspaceBytes: BlaiForwardWorkspaceMaterializedByteEvidence,
    dataMapping: BlaiForwardActiveDataMappingEvidence,
    tempWeightBias: BlaiForwardNpuTemporaryWeightBiasBufferResult,
    tempEvidence: BlaiForwardNpuTemporaryWeightBiasBufferEvidence):
    BlaiForwardMaterializedLaunchBridgeEvidence =
  ## Convenience wrapper for materialized launch-bridge evidence.
  blaiForwardMaterializedLaunchBridgeEvidenceInto(
    materialization, workspace, runPlan, runEvidence, streamSemantics,
    workspaceBytes, dataMapping, tempWeightBias, tempEvidence, result)

proc blaiForwardWorkspaceCacheEvidenceInto*(
    workspaceCache: BlaiForwardWorkspaceCachePrepareResult,
    executionCache: BlaiForwardNpuCacheApplyResult,
    runPlan: BlaiForwardNpuRunPlan,
    workspace: BlaiForwardModelWorkspacePlan,
    dataAddr: uint32,
    outResult: var BlaiForwardWorkspaceCacheEvidence) =
  ## Derive focused workspace and first DATA cache-application evidence.
  outResult = default(BlaiForwardWorkspaceCacheEvidence)
  outResult.workspaceFits = workspaceCache.fits
  outResult.workspaceApplied = workspaceCache.applied
  outResult.workspaceCacheValid =
    outResult.workspaceFits and outResult.workspaceApplied
  outResult.instructionActive = workspaceCache.instruction.active
  outResult.instructionFits = workspaceCache.instruction.fits
  outResult.instructionApplied = workspaceCache.instruction.applied
  outResult.instructionClean =
    workspaceCache.instruction.operation == blaiCacheClean
  outResult.instructionAddressMatches =
    workspaceCache.instruction.address == workspace.instruction.address
  outResult.instructionBytesMatches =
    workspaceCache.instruction.bytes == workspace.instruction.bytes
  outResult.instructionCacheValid =
    outResult.instructionActive and outResult.instructionFits and
      outResult.instructionApplied and outResult.instructionClean and
      outResult.instructionAddressMatches and
      outResult.instructionBytesMatches
  outResult.weightActive = workspaceCache.weight.active
  outResult.weightFits = workspaceCache.weight.fits
  outResult.weightApplied = workspaceCache.weight.applied
  outResult.weightClean = workspaceCache.weight.operation == blaiCacheClean
  outResult.weightAddressMatches =
    workspaceCache.weight.address == workspace.weight.address
  outResult.weightBytesMatches =
    workspaceCache.weight.bytes == workspace.weight.bytes
  outResult.weightCacheValid =
    outResult.weightActive and outResult.weightFits and
      outResult.weightApplied and outResult.weightClean and
      outResult.weightAddressMatches and
      outResult.weightBytesMatches
  outResult.biasActive = workspaceCache.bias.active
  outResult.biasFits = workspaceCache.bias.fits
  outResult.biasApplied = workspaceCache.bias.applied
  outResult.biasClean = workspaceCache.bias.operation == blaiCacheClean
  outResult.biasAddressMatches =
    workspaceCache.bias.address == workspace.bias.address
  outResult.biasBytesMatches =
    workspaceCache.bias.bytes == workspace.bias.bytes
  outResult.biasCacheValid =
    outResult.biasActive and outResult.biasFits and outResult.biasApplied and
      outResult.biasClean and outResult.biasAddressMatches and
      outResult.biasBytesMatches
  outResult.dataCacheRangeCountMatches =
    executionCache.cacheRangeCount == runPlan.cacheRangeCount
  if executionCache.cacheRangeCount >= 1'u32:
    let firstRange = executionCache.cacheRanges[0]
    outResult.firstDataCacheActive = firstRange.active
    outResult.firstDataCacheFits = firstRange.fits
    outResult.firstDataCacheApplied = firstRange.applied
    outResult.firstDataCacheClean = firstRange.operation == blaiCacheClean
    outResult.firstDataCacheAddressMatches = firstRange.address == dataAddr
    outResult.firstDataCacheBytesMatches =
      firstRange.bytes == runPlan.cacheRanges[0].bytes
  outResult.firstDataCacheValid =
    outResult.dataCacheRangeCountMatches and outResult.firstDataCacheActive and
      outResult.firstDataCacheFits and outResult.firstDataCacheApplied and
      outResult.firstDataCacheClean and outResult.firstDataCacheAddressMatches and
      outResult.firstDataCacheBytesMatches
  outResult.valid =
    outResult.workspaceCacheValid and outResult.instructionCacheValid and
      outResult.weightCacheValid and outResult.biasCacheValid and
      outResult.firstDataCacheValid

proc blaiForwardWorkspaceCacheEvidence*(
    workspaceCache: BlaiForwardWorkspaceCachePrepareResult,
    executionCache: BlaiForwardNpuCacheApplyResult,
    runPlan: BlaiForwardNpuRunPlan,
    workspace: BlaiForwardModelWorkspacePlan,
    dataAddr: uint32): BlaiForwardWorkspaceCacheEvidence =
  ## Convenience wrapper for workspace and first DATA cache evidence.
  blaiForwardWorkspaceCacheEvidenceInto(
    workspaceCache, executionCache, runPlan, workspace, dataAddr, result)

proc blaiForwardActiveCacheContractEvidenceInto*(
    cache: BlaiForwardWorkspaceCacheEvidence,
    outResult: var BlaiForwardActiveCacheContractEvidence) =
  ## Derive focused active-run cache visibility contract evidence.
  outResult = default(BlaiForwardActiveCacheContractEvidence)
  outResult.workspaceSegmentsActive =
    cache.instructionActive and cache.weightActive and cache.biasActive
  outResult.workspaceSegmentsFit =
    cache.workspaceFits and cache.instructionFits and cache.weightFits and
      cache.biasFits
  outResult.workspaceSegmentsApplied =
    cache.workspaceApplied and cache.instructionApplied and
      cache.weightApplied and cache.biasApplied
  outResult.workspaceSegmentsClean =
    cache.instructionClean and cache.weightClean and cache.biasClean
  outResult.workspaceAddressesMatch =
    cache.instructionAddressMatches and cache.weightAddressMatches and
      cache.biasAddressMatches
  outResult.workspaceBytesMatch =
    cache.instructionBytesMatches and cache.weightBytesMatches and
      cache.biasBytesMatches
  outResult.workspaceContractValid =
    outResult.workspaceSegmentsActive and outResult.workspaceSegmentsFit and
      outResult.workspaceSegmentsApplied and outResult.workspaceSegmentsClean and
      outResult.workspaceAddressesMatch and outResult.workspaceBytesMatch
  outResult.dataRangeCountMatches = cache.dataCacheRangeCountMatches
  outResult.dataRangeCleanValid = cache.firstDataCacheValid
  outResult.valid =
    cache.valid and outResult.workspaceContractValid and
      outResult.dataRangeCountMatches and outResult.dataRangeCleanValid

proc blaiForwardActiveCacheContractEvidence*(
    cache: BlaiForwardWorkspaceCacheEvidence):
    BlaiForwardActiveCacheContractEvidence =
  ## Convenience wrapper for active cache contract evidence.
  blaiForwardActiveCacheContractEvidenceInto(cache, result)

proc blaiForwardLaunchCacheRegisterEvidenceInto*(
    launch: BlaiForwardMaterializedLaunchBridgeEvidence,
    cache: BlaiForwardWorkspaceCacheEvidence,
    contract: BlaiForwardActiveCacheContractEvidence,
    temp: BlaiForwardNpuTemporaryWeightBiasBufferEvidence,
    outResult: var BlaiForwardLaunchCacheRegisterEvidence) =
  ## Prove launch-register fetch addresses match cleaned cache ranges.
  outResult = default(BlaiForwardLaunchCacheRegisterEvidence)
  outResult.launchBridgeValid = launch.valid
  outResult.cacheContractValid = contract.valid
  outResult.tempCacheValid = temp.cacheValid
  outResult.instructionRegisterCacheClean =
    launch.instructionAddressMatchesWorkspace and cache.instructionCacheValid
  outResult.dataRegisterCacheClean =
    launch.dataAddressMatchesWorkspace and cache.firstDataCacheValid
  outResult.weightRegisterCacheClean =
    launch.weightAddressMatchesTemp and temp.weightCacheValid
  outResult.biasRegisterCacheClean =
    launch.biasAddressMatchesTemp and temp.biasCacheValid
  outResult.registerCacheAddressesMatch =
    outResult.instructionRegisterCacheClean and
      outResult.dataRegisterCacheClean and
      outResult.weightRegisterCacheClean and
      outResult.biasRegisterCacheClean
  outResult.registerCacheBytesReady =
    cache.instructionBytesMatches and cache.firstDataCacheBytesMatches and
      temp.weightCacheBytesMatch and temp.biasCacheBytesMatch
  outResult.valid =
    outResult.launchBridgeValid and outResult.cacheContractValid and
      outResult.tempCacheValid and outResult.registerCacheAddressesMatch and
      outResult.registerCacheBytesReady

proc blaiForwardLaunchCacheRegisterEvidence*(
    launch: BlaiForwardMaterializedLaunchBridgeEvidence,
    cache: BlaiForwardWorkspaceCacheEvidence,
    contract: BlaiForwardActiveCacheContractEvidence,
    temp: BlaiForwardNpuTemporaryWeightBiasBufferEvidence):
    BlaiForwardLaunchCacheRegisterEvidence =
  ## Convenience wrapper for launch/cache register evidence.
  blaiForwardLaunchCacheRegisterEvidenceInto(
    launch, cache, contract, temp, result)

proc blaiForwardLaunchSramAddressEvidenceInto*(
    launchSnapshot: NpuRegisterSnapshot,
    launchRegistersCaptured: bool,
    workspaceWram: BlaiForwardWorkspaceWramEvidence,
    launch: BlaiForwardMaterializedLaunchBridgeEvidence,
    launchCache: BlaiForwardLaunchCacheRegisterEvidence,
    runtime: NpuRuntimeInitEvidence,
    outResult: var BlaiForwardLaunchSramAddressEvidence) =
  ## Tie live launch-register addresses to WRAM and released BLAI SRAM.
  outResult = default(BlaiForwardLaunchSramAddressEvidence)
  outResult.launchRegistersCaptured = launchRegistersCaptured
  outResult.workspaceWramValid = workspaceWram.valid
  outResult.launchBridgeValid = launch.valid
  outResult.launchCacheRegisterValid = launchCache.valid
  outResult.runtimeSramValid = runtime.sramValid
  outResult.instructionRegisterInWram =
    blaiAddressInWram(launchSnapshot.instAddr)
  outResult.dataRegisterInWram =
    blaiAddressInWram(launchSnapshot.imageAddr)
  outResult.weightRegisterInWram =
    blaiAddressInWram(launchSnapshot.weightAddr)
  outResult.biasRegisterInWram =
    blaiAddressInWram(launchSnapshot.biasAddr)
  outResult.registerAddressesInWram =
    outResult.instructionRegisterInWram and outResult.dataRegisterInWram and
      outResult.weightRegisterInWram and outResult.biasRegisterInWram
  outResult.sramReleased = runtime.sramReleased
  outResult.sramSelected = runtime.sramSelected
  outResult.sysramSetSelfCleared = runtime.sysramSetSelfCleared
  outResult.launchAddressSurfaceValid =
    outResult.launchRegistersCaptured and outResult.workspaceWramValid and
      outResult.launchBridgeValid and outResult.launchCacheRegisterValid and
      outResult.registerAddressesInWram
  outResult.valid =
    outResult.launchAddressSurfaceValid and outResult.runtimeSramValid and
      outResult.sramReleased and outResult.sramSelected and
      outResult.sysramSetSelfCleared

proc blaiForwardLaunchSramAddressEvidence*(
    launchSnapshot: NpuRegisterSnapshot,
    launchRegistersCaptured: bool,
    workspaceWram: BlaiForwardWorkspaceWramEvidence,
    launch: BlaiForwardMaterializedLaunchBridgeEvidence,
    launchCache: BlaiForwardLaunchCacheRegisterEvidence,
    runtime: NpuRuntimeInitEvidence): BlaiForwardLaunchSramAddressEvidence =
  ## Convenience wrapper for launch-register WRAM/SRAM evidence.
  blaiForwardLaunchSramAddressEvidenceInto(
    launchSnapshot, launchRegistersCaptured, workspaceWram, launch, launchCache,
    runtime, result)

proc blaiForwardLaunchWramSpanEvidenceInto*(
    launchSnapshot: NpuRegisterSnapshot,
    launchRegistersCaptured: bool,
    launchSram: BlaiForwardLaunchSramAddressEvidence,
    instructionBytes, dataBytes, weightBytes, biasBytes: uint32,
    outResult: var BlaiForwardLaunchWramSpanEvidence) =
  ## Tie each live launch-register fetch range to a complete WRAM byte span.
  outResult = default(BlaiForwardLaunchWramSpanEvidence)
  outResult.launchRegistersCaptured = launchRegistersCaptured
  outResult.launchSramAddressValid = launchSram.valid
  outResult.instructionBytes = instructionBytes
  outResult.dataBytes = dataBytes
  outResult.weightBytes = weightBytes
  outResult.biasBytes = biasBytes
  outResult.instructionRangeFitsBus =
    blaiUint32AddressRangeFits(launchSnapshot.instAddr, instructionBytes)
  outResult.dataRangeFitsBus =
    blaiUint32AddressRangeFits(launchSnapshot.imageAddr, dataBytes)
  outResult.weightRangeFitsBus =
    blaiUint32AddressRangeFits(launchSnapshot.weightAddr, weightBytes)
  outResult.biasRangeFitsBus =
    blaiUint32AddressRangeFits(launchSnapshot.biasAddr, biasBytes)
  outResult.registerSpansFitBus =
    outResult.instructionRangeFitsBus and outResult.dataRangeFitsBus and
      outResult.weightRangeFitsBus and outResult.biasRangeFitsBus
  outResult.instructionSpanInWram =
    blaiUint32AddressSpanInWram(launchSnapshot.instAddr, instructionBytes)
  outResult.dataSpanInWram =
    blaiUint32AddressSpanInWram(launchSnapshot.imageAddr, dataBytes)
  outResult.weightSpanInWram =
    blaiUint32AddressSpanInWram(launchSnapshot.weightAddr, weightBytes)
  outResult.biasSpanInWram =
    blaiUint32AddressSpanInWram(launchSnapshot.biasAddr, biasBytes)
  outResult.registerSpansInWram =
    outResult.instructionSpanInWram and outResult.dataSpanInWram and
      outResult.weightSpanInWram and outResult.biasSpanInWram
  outResult.valid =
    outResult.launchRegistersCaptured and outResult.launchSramAddressValid and
      outResult.registerSpansFitBus and outResult.registerSpansInWram

proc blaiForwardLaunchWramSpanEvidence*(
    launchSnapshot: NpuRegisterSnapshot,
    launchRegistersCaptured: bool,
    launchSram: BlaiForwardLaunchSramAddressEvidence,
    instructionBytes, dataBytes, weightBytes, biasBytes: uint32):
      BlaiForwardLaunchWramSpanEvidence =
  ## Convenience wrapper for live launch-register WRAM byte-span evidence.
  blaiForwardLaunchWramSpanEvidenceInto(
    launchSnapshot, launchRegistersCaptured, launchSram, instructionBytes,
    dataBytes, weightBytes, biasBytes, result)

proc blaiForwardLaunchInstructionFetchEvidenceInto*(
    launchSnapshot: NpuRegisterSnapshot,
    launchRegistersCaptured: bool,
    workspace: BlaiForwardModelWorkspacePlan,
    launchSram: BlaiForwardLaunchSramAddressEvidence,
    launchSpan: BlaiForwardLaunchWramSpanEvidence,
    raw: BlaiForwardWorkspaceInstructionRawWordEvidence,
    walk: BlaiNpuSdkStreamWalkEvidence,
    terminal: BlaiForwardWorkspaceInstructionTerminalControlEvidence,
    outResult: var BlaiForwardLaunchInstructionFetchEvidence) =
  ## Prove the launch instruction address points at a decoded executable stream.
  outResult = default(BlaiForwardLaunchInstructionFetchEvidence)
  outResult.launchRegistersCaptured = launchRegistersCaptured
  outResult.launchSramAddressValid = launchSram.valid
  outResult.launchSpanValid = launchSpan.valid
  outResult.streamRawValid = raw.valid
  outResult.streamWalkValid = walk.valid
  outResult.terminalControlValid = terminal.valid
  outResult.instructionAddressMatchesWorkspace =
    launchSnapshot.instAddr == workspace.instruction.address
  outResult.twoInstructionRecords =
    raw.countMatches and raw.expectedCount == 2'u32
  outResult.instructionBytesMatchRawRecords =
    launchSpan.instructionBytes == raw.expectedCount * BlaiInstructionSize.uint32
  outResult.quantRecordMatchesEncoder = raw.quantWordsMatch
  outResult.layerRecordMatchesEncoder = raw.layerWordsMatch
  outResult.sdkWalkAllocatesOneLayer =
    walk.wouldAllocateOneLayer and walk.decodedLayerCountMatches
  outResult.terminalLayerRecord =
    walk.secondRecordLayerInstruction and walk.secondRecordTerminal
  outResult.descriptorControlCoherent = terminal.controlCoherent
  outResult.fetchSurfaceExecutable =
    outResult.launchRegistersCaptured and outResult.launchSramAddressValid and
      outResult.launchSpanValid and outResult.streamRawValid and
      outResult.streamWalkValid and outResult.terminalControlValid and
      outResult.instructionAddressMatchesWorkspace and
      outResult.instructionBytesMatchRawRecords and
      outResult.twoInstructionRecords and outResult.quantRecordMatchesEncoder and
      outResult.layerRecordMatchesEncoder and outResult.sdkWalkAllocatesOneLayer and
      outResult.terminalLayerRecord and outResult.descriptorControlCoherent
  outResult.valid = outResult.fetchSurfaceExecutable

proc blaiForwardLaunchInstructionFetchEvidence*(
    launchSnapshot: NpuRegisterSnapshot,
    launchRegistersCaptured: bool,
    workspace: BlaiForwardModelWorkspacePlan,
    launchSram: BlaiForwardLaunchSramAddressEvidence,
    launchSpan: BlaiForwardLaunchWramSpanEvidence,
    raw: BlaiForwardWorkspaceInstructionRawWordEvidence,
    walk: BlaiNpuSdkStreamWalkEvidence,
    terminal: BlaiForwardWorkspaceInstructionTerminalControlEvidence):
      BlaiForwardLaunchInstructionFetchEvidence =
  ## Convenience wrapper for launch instruction-fetch evidence.
  blaiForwardLaunchInstructionFetchEvidenceInto(
    launchSnapshot, launchRegistersCaptured, workspace, launchSram, launchSpan,
    raw, walk, terminal, result)

proc blaiForwardLaunchOperandFetchEvidenceInto*(
    launchSnapshot: NpuRegisterSnapshot,
    launchRegistersCaptured: bool,
    run: BlaiForwardNpuRunPlanEvidence,
    data: BlaiForwardWorkspaceDataSlotEvidence,
    dataMapping: BlaiForwardActiveDataMappingEvidence,
    packed: BlaiNpuPackedWeightBiasEvidence,
    temp: BlaiForwardNpuTemporaryWeightBiasBufferResult,
    tempEvidence: BlaiForwardNpuTemporaryWeightBiasBufferEvidence,
    launchSpan: BlaiForwardLaunchWramSpanEvidence,
    stream: BlaiForwardWorkspaceInstructionStreamEvidence,
    semantics: BlaiForwardWorkspaceInstructionStreamSemanticEvidence,
    outResult: var BlaiForwardLaunchOperandFetchEvidence) =
  ## Prove live operand fetch registers agree with decoded DATA/weight/bias use.
  outResult = default(BlaiForwardLaunchOperandFetchEvidence)
  outResult.launchRegistersCaptured = launchRegistersCaptured
  outResult.runPlanValid = run.valid
  outResult.dataMappingValid = dataMapping.valid
  outResult.packedWeightBiasValid = packed.valid
  outResult.tempWeightBiasValid = temp.prepared and tempEvidence.valid
  outResult.launchSpanValid = launchSpan.valid
  outResult.streamValid = stream.valid
  outResult.streamSemanticValid = semantics.valid
  outResult.dataRegisterMatchesRun =
    launchSnapshot.imageAddr != 0'u32 and run.dataAddrMatches
  outResult.weightRegisterMatchesTemp =
    launchSnapshot.weightAddr == temp.weightAddr and run.weightAddrMatches
  outResult.biasRegisterMatchesTemp =
    launchSnapshot.biasAddr == temp.biasAddr and run.biasAddrMatches
  outResult.dataSegmentMatchesPatch =
    launchSnapshot.imageSeg == data.patchSize and run.patchSizeMatches
  outResult.descriptorInputSlotMatchesData =
    stream.decodedLayer.inLayer1Mem == data.inputSlot
  outResult.descriptorOutputSlotMatchesData =
    stream.decodedLayer.outLayerMem == data.outputSlot
  outResult.descriptorSingleInputMatches =
    semantics.c2Matches and semantics.operandSingleInputC2Matches
  outResult.stagedInputReady =
    dataMapping.stagedInputReady and data.stagedInputMatches
  outResult.outputSlotReady =
    dataMapping.outputSlotReady and data.outputFits
  outResult.weightBytesMatchTemp =
    launchSpan.weightBytes == temp.weightBytes and
      tempEvidence.weightBytesMatch and packed.materializedWeightBytesMatch
  outResult.biasBytesMatchTemp =
    launchSpan.biasBytes == temp.biasBytes and
      tempEvidence.biasBytesMatch and packed.biasBytesMatch
  outResult.weightBiasBytesReady =
    outResult.weightBytesMatchTemp and outResult.biasBytesMatchTemp and
      packed.packedBytesValid and packed.biasValid and tempEvidence.bytesValid
  outResult.operandSurfaceCoherent =
    outResult.launchRegistersCaptured and outResult.runPlanValid and
      outResult.dataMappingValid and outResult.packedWeightBiasValid and
      outResult.tempWeightBiasValid and outResult.launchSpanValid and
      outResult.streamValid and outResult.streamSemanticValid and
      outResult.dataRegisterMatchesRun and outResult.weightRegisterMatchesTemp and
      outResult.biasRegisterMatchesTemp and outResult.dataSegmentMatchesPatch and
      outResult.descriptorInputSlotMatchesData and
      outResult.descriptorOutputSlotMatchesData and
      outResult.descriptorSingleInputMatches and outResult.stagedInputReady and
      outResult.outputSlotReady and outResult.weightBiasBytesReady
  outResult.valid = outResult.operandSurfaceCoherent

proc blaiForwardLaunchOperandFetchEvidence*(
    launchSnapshot: NpuRegisterSnapshot,
    launchRegistersCaptured: bool,
    run: BlaiForwardNpuRunPlanEvidence,
    data: BlaiForwardWorkspaceDataSlotEvidence,
    dataMapping: BlaiForwardActiveDataMappingEvidence,
    packed: BlaiNpuPackedWeightBiasEvidence,
    temp: BlaiForwardNpuTemporaryWeightBiasBufferResult,
    tempEvidence: BlaiForwardNpuTemporaryWeightBiasBufferEvidence,
    launchSpan: BlaiForwardLaunchWramSpanEvidence,
    stream: BlaiForwardWorkspaceInstructionStreamEvidence,
    semantics: BlaiForwardWorkspaceInstructionStreamSemanticEvidence):
      BlaiForwardLaunchOperandFetchEvidence =
  ## Convenience wrapper for live operand fetch-surface evidence.
  blaiForwardLaunchOperandFetchEvidenceInto(
    launchSnapshot, launchRegistersCaptured, run, data, dataMapping, packed,
    temp, tempEvidence, launchSpan, stream, semantics, result)

proc blaiInstructionBufferBytes(stream: openArray[BlaiInstruction]): uint32 =
  ## Project a typed instruction stream length into the recovered uint32 ABI.
  let instructionCount = blaiOpenArrayLenU32(stream)
  var bytes: uint32
  if blaiInstructionCountBytes(instructionCount, bytes):
    bytes
  else:
    high(uint32)

proc blaiForwardPreparedRunReadinessInto*(
    prepared: BlaiForwardPreparedRunPlan,
    outResult: var BlaiForwardPreparedRunReadiness) =
  ## Derive readiness for one encoded forward_NPU layer preparation.
  outResult = default(BlaiForwardPreparedRunReadiness)
  outResult.runnable = prepared.runnable
  outResult.encoded = prepared.encoded
  outResult.resourcesFit = prepared.resourcesFit
  outResult.runConfigurable = prepared.run.configurable
  outResult.runConfigFirstBlock = prepared.run.configReadiness.firstBlock
  if not outResult.runnable:
    outResult.firstBlock = blaiForwardPreparedRunForwardPlan
  elif not outResult.encoded:
    outResult.firstBlock = blaiForwardPreparedRunEncoding
  elif not outResult.resourcesFit:
    outResult.firstBlock = blaiForwardPreparedRunResources
  elif not outResult.runConfigurable:
    outResult.firstBlock = blaiForwardPreparedRunConfig
  else:
    outResult.firstBlock = blaiForwardPreparedRunNoBlock
  outResult.ready = outResult.runnable and outResult.encoded and
    outResult.resourcesFit and outResult.runConfigurable

proc blaiForwardPreparedRunReadiness*(
    prepared: BlaiForwardPreparedRunPlan): BlaiForwardPreparedRunReadiness =
  ## Convenience wrapper for encoded forward_NPU layer preparation readiness.
  blaiForwardPreparedRunReadinessInto(prepared, result)

proc blaiPrepareForwardNpuLayerInto*(
    layer: var BlaiCpuInstLayer64,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    outResult: var BlaiForwardPreparedRunPlan,
    layerIndex: uint32,
    useTflite: bool,
    dataBufferBytes: uint32,
    instAddr: uint32,
    dataBufferAddr: uint32,
    weightAddr: uint32 = 0'u32,
    biasAddr: uint32 = 0'u32,
    weightBufferBytes: uint32 = 0'u32,
    biasBufferBytes: uint32 = 0'u32,
    temporaryWeightElements: uint32 = 0'u32,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false) =
  ## Compose recovered instruction encoding, resource sizing, and run setup.
  ##
  ## The proc stays allocation-free: callers provide the typed instruction
  ## stream plus DATA/weight/bias capacities and later own the actual buffers.
  outResult = default(BlaiForwardPreparedRunPlan)
  outResult.instructionBufferBytes = blaiInstructionBufferBytes(stream)
  outResult.dataBufferBytes = dataBufferBytes
  outResult.weightBufferBytes = weightBufferBytes
  outResult.biasBufferBytes = biasBufferBytes
  outResult.temporaryWeightElements = temporaryWeightElements
  if outResult.instructionBufferBytes < BlaiInstructionScratchSize.uint32:
    blaiPlanForwardResourcesInto(
      layer, layerIndex, useTflite, outResult.resources)
    outResult.runnable = outResult.resources.runnable
    blaiPlanForwardNpuRunInto(
      layer, layerIndex, dataBufferBytes, instAddr, dataBufferAddr,
      outResult.run,
      weightAddr, biasAddr)
    blaiForwardPreparedRunReadinessInto(outResult, outResult.readiness)
    outResult.runConfigFirstBlock = outResult.readiness.runConfigFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.ready = outResult.readiness.ready
    return

  blaiEncodeCpuLayerWithAllocatorInto(
    layer, ctrl, stream, outResult.encode,
    useTflite, c2, includeExtra, descriptorHalt, midOutState)
  outResult.encoded = outResult.encode.encoded
  blaiPlanForwardResourcesInto(
    layer, layerIndex, useTflite, outResult.resources)
  outResult.runnable = outResult.resources.runnable
  var fit: BlaiForwardResourceFitResult
  blaiForwardResourcesFitInto(
    outResult.resources, outResult.instructionBufferBytes, dataBufferBytes,
    weightBufferBytes, biasBufferBytes, temporaryWeightElements, fit)
  outResult.resourcesFit = fit.fits
  blaiPlanForwardNpuRunInto(
    layer, layerIndex, dataBufferBytes, instAddr, dataBufferAddr,
    outResult.run,
    weightAddr, biasAddr)
  blaiForwardPreparedRunReadinessInto(outResult, outResult.readiness)
  outResult.runConfigFirstBlock = outResult.readiness.runConfigFirstBlock
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.ready = outResult.readiness.ready

proc blaiPrepareForwardNpuLayer*(
    layer: var BlaiCpuInstLayer64,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    layerIndex: uint32,
    useTflite: bool,
    dataBufferBytes: uint32,
    instAddr: uint32,
    dataBufferAddr: uint32,
    weightAddr: uint32 = 0'u32,
    biasAddr: uint32 = 0'u32,
    weightBufferBytes: uint32 = 0'u32,
    biasBufferBytes: uint32 = 0'u32,
    temporaryWeightElements: uint32 = 0'u32,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiForwardPreparedRunPlan =
  ## Convenience result-returning wrapper for `blaiPrepareForwardNpuLayerInto`.
  blaiPrepareForwardNpuLayerInto(
    layer, ctrl, stream, result,
    layerIndex, useTflite, dataBufferBytes, instAddr, dataBufferAddr,
    weightAddr, biasAddr, weightBufferBytes, biasBufferBytes,
    temporaryWeightElements, c2, includeExtra, descriptorHalt, midOutState)

proc blaiPrepareForwardNpuLayerInWorkspaceInto*(
    layer: var BlaiCpuInstLayer64,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    outResult: var BlaiForwardPreparedRunPlan,
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    layerIndex: uint32,
    useTflite: bool,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false) =
  ## Prepare one layer using typed model workspace segment addresses.
  outResult = default(BlaiForwardPreparedRunPlan)
  if not (modelResources.supported and workspace.supported and workspace.fits and
          workspace.instruction.active and workspace.data.active):
    blaiForwardPreparedRunReadinessInto(outResult, outResult.readiness)
    outResult.runConfigFirstBlock = outResult.readiness.runConfigFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.ready = outResult.readiness.ready
    return
  blaiPrepareForwardNpuLayerInto(
    layer, ctrl, stream, outResult,
    layerIndex, useTflite,
    dataBufferBytes = workspace.data.bytes,
    instAddr = workspace.instruction.address,
    dataBufferAddr = workspace.data.address,
    weightAddr = workspace.weight.address,
    biasAddr = workspace.bias.address,
    weightBufferBytes = workspace.weight.bytes,
    biasBufferBytes = workspace.bias.bytes,
    temporaryWeightElements = modelResources.temporaryWeightElements,
    c2 = c2,
    includeExtra = includeExtra,
    descriptorHalt = descriptorHalt,
    midOutState = midOutState)

proc blaiPrepareForwardNpuLayerInWorkspace*(
    layer: var BlaiCpuInstLayer64,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    layerIndex: uint32,
    useTflite: bool,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiForwardPreparedRunPlan =
  ## Convenience result-returning wrapper for workspace-backed layer preparation.
  blaiPrepareForwardNpuLayerInWorkspaceInto(
    layer, ctrl, stream, result, modelResources, workspace, layerIndex,
    useTflite, c2, includeExtra, descriptorHalt, midOutState)

proc blaiForwardLayerInstructionWorkspaceReadinessInto*(
    prepared: BlaiForwardLayerInstructionWorkspaceResult,
    outResult: var BlaiForwardLayerInstructionWorkspaceReadiness) =
  ## Derive readiness for one prepared layer's instruction workspace bytes.
  outResult = default(BlaiForwardLayerInstructionWorkspaceReadiness)
  outResult.prepared =
    prepared.prepared.runnable and prepared.prepared.encoded and
    prepared.prepared.resourcesFit
  outResult.stored = prepared.stored
  outResult.instructionFirstBlock = prepared.instructions.firstBlock
  if not outResult.prepared:
    outResult.firstBlock = blaiForwardLayerInstructionWorkspacePrepared
  elif not outResult.stored:
    outResult.firstBlock = blaiForwardLayerInstructionWorkspaceStorage
  else:
    outResult.firstBlock = blaiForwardLayerInstructionWorkspaceNoBlock
  outResult.instructionCount = prepared.instructionCount
  outResult.ready = outResult.prepared and outResult.stored

proc blaiForwardLayerInstructionWorkspaceReadiness*(
    prepared: BlaiForwardLayerInstructionWorkspaceResult):
    BlaiForwardLayerInstructionWorkspaceReadiness =
  ## Convenience wrapper for layer instruction workspace readiness.
  blaiForwardLayerInstructionWorkspaceReadinessInto(prepared, result)

proc blaiPrepareForwardLayerInstructionsInWorkspaceInto*(
    layer: var BlaiCpuInstLayer64,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    layerIndex: uint32,
    useTflite: bool,
    outResult: var BlaiForwardLayerInstructionWorkspaceResult,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false) =
  ## Prepare one layer and copy its typed instruction stream into workspace.
  outResult = default(BlaiForwardLayerInstructionWorkspaceResult)
  blaiPrepareForwardNpuLayerInWorkspaceInto(
    layer, ctrl, stream, outResult.prepared, modelResources, workspace,
    layerIndex, useTflite, c2, includeExtra, descriptorHalt, midOutState)
  blaiForwardLayerInstructionWorkspaceReadinessInto(
    outResult, outResult.readiness)
  if not outResult.readiness.prepared:
    outResult.instructionFirstBlock = outResult.readiness.instructionFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.ready = outResult.readiness.ready
    return
  outResult.instructionCount = nonNegativeU32(layer.instCnt)
  blaiStoreForwardInstructionsInWorkspaceInto(
    workspace, stream, outResult.instructionCount, workspaceBytes,
    outResult.instructions)
  outResult.stored = outResult.instructions.copied
  blaiForwardLayerInstructionWorkspaceReadinessInto(
    outResult, outResult.readiness)
  outResult.instructionFirstBlock = outResult.readiness.instructionFirstBlock
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.ready = outResult.readiness.ready

proc blaiPrepareForwardLayerInstructionsInWorkspace*(
    layer: var BlaiCpuInstLayer64,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    layerIndex: uint32,
    useTflite: bool,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiForwardLayerInstructionWorkspaceResult =
  ## Convenience result-returning wrapper for layer instruction workspace prep.
  blaiPrepareForwardLayerInstructionsInWorkspaceInto(
    layer, ctrl, stream, modelResources, workspace, workspaceBytes,
    layerIndex, useTflite, result, c2, includeExtra, descriptorHalt,
    midOutState)

proc blaiForwardLayerWorkspaceMaterializeReadinessInto*(
    materialization: BlaiForwardLayerWorkspaceMaterializeResult,
    outResult: var BlaiForwardLayerWorkspaceMaterializeReadiness) =
  ## Derive readiness for one materialized layer workspace.
  outResult = default(BlaiForwardLayerWorkspaceMaterializeReadiness)
  outResult.instructionsReady = materialization.instructions.ready
  outResult.instructionCount = materialization.instructions.instructionCount
  outResult.weightLayer = materialization.weights.weightLayer
  outResult.weightsStored = materialization.weights.workspaceStored
  outResult.instructionFirstBlock = materialization.instructions.firstBlock
  outResult.weightWorkspaceFirstBlock = materialization.weights.workspace.firstBlock
  if not outResult.instructionsReady:
    outResult.firstBlock = blaiForwardLayerWorkspaceMaterializeInstructions
  elif not outResult.weightsStored:
    outResult.firstBlock = blaiForwardLayerWorkspaceMaterializeWeights
  else:
    outResult.firstBlock = blaiForwardLayerWorkspaceMaterializeNoBlock
  outResult.ready = outResult.instructionsReady and outResult.weightsStored

proc blaiForwardLayerWorkspaceMaterializeReadiness*(
    materialization: BlaiForwardLayerWorkspaceMaterializeResult):
    BlaiForwardLayerWorkspaceMaterializeReadiness =
  ## Convenience wrapper for layer workspace materialization readiness.
  blaiForwardLayerWorkspaceMaterializeReadinessInto(materialization, result)

proc blaiMaterializeForwardLayerWorkspaceInto*(
    layers: var openArray[BlaiCpuInstLayer64],
    layerIndex: uint32,
    useTflite: bool,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor: BlaiCpuStreamCursor,
    biasCursor: BlaiCpuStreamCursor,
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false,
    outResult: var BlaiForwardLayerWorkspaceMaterializeResult) =
  ## Prepare one layer and populate reusable instruction/weight workspace bytes.
  outResult = default(BlaiForwardLayerWorkspaceMaterializeResult)
  outResult.nextWeightCursor = weightCursor
  outResult.nextBiasCursor = biasCursor
  let layerCursor = blaiRecoveredLayerCursor(layerIndex, layers.len)
  if not layerCursor.valid:
    blaiForwardLayerWorkspaceMaterializeReadinessInto(
      outResult, outResult.readiness)
    outResult.instructionFirstBlock = outResult.readiness.instructionFirstBlock
    outResult.weightWorkspaceFirstBlock =
      outResult.readiness.weightWorkspaceFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    return

  blaiPrepareForwardLayerInstructionsInWorkspaceInto(
    layers[layerCursor.index], ctrl, stream, modelResources, workspace,
    workspaceBytes, layerIndex, useTflite, outResult.instructions, c2,
    includeExtra, descriptorHalt, midOutState)
  if not outResult.instructions.ready:
    blaiForwardLayerWorkspaceMaterializeReadinessInto(
      outResult, outResult.readiness)
    outResult.instructionFirstBlock = outResult.readiness.instructionFirstBlock
    outResult.weightWorkspaceFirstBlock =
      outResult.readiness.weightWorkspaceFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    return

  blaiMaterializeForwardLayerWeightsInWorkspaceInto(
    layers, layerIndex, useTflite, workspace, cpuWeightBytes, cpuBiasBytes,
    weightCursor, biasCursor, decodedWeights, decodedBiases, npuWeightBytes,
    npuBiases, temporaryWeights, workspaceBytes, outResult.weights, pack)
  if outResult.weights.workspaceStored:
    outResult.nextWeightCursor = outResult.weights.nextWeightCursor
    outResult.nextBiasCursor = outResult.weights.nextBiasCursor
  blaiForwardLayerWorkspaceMaterializeReadinessInto(
    outResult, outResult.readiness)
  outResult.instructionFirstBlock = outResult.readiness.instructionFirstBlock
  outResult.weightWorkspaceFirstBlock =
    outResult.readiness.weightWorkspaceFirstBlock
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.ready = outResult.readiness.ready

proc blaiMaterializeForwardLayerWorkspace*(
    layers: var openArray[BlaiCpuInstLayer64],
    layerIndex: uint32,
    useTflite: bool,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor: BlaiCpuStreamCursor,
    biasCursor: BlaiCpuStreamCursor,
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiForwardLayerWorkspaceMaterializeResult =
  ## Convenience wrapper for one raw layer workspace materialization.
  blaiMaterializeForwardLayerWorkspaceInto(
    layers, layerIndex, useTflite, ctrl, stream, modelResources, workspace,
    workspaceBytes, cpuWeightBytes, cpuBiasBytes, weightCursor, biasCursor,
    decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
    temporaryWeights, pack, c2, includeExtra, descriptorHalt, midOutState,
    result)

proc blaiMaterializeForwardLayerWorkspaceInto*(
    layers: var openArray[BlaiCpuParsedLayerState],
    layerIndex: uint32,
    useTflite: bool,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor: BlaiCpuStreamCursor,
    biasCursor: BlaiCpuStreamCursor,
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false,
    outResult: var BlaiForwardLayerWorkspaceMaterializeResult) =
  ## Prepare one parsed-state layer and populate reusable workspace bytes.
  outResult = default(BlaiForwardLayerWorkspaceMaterializeResult)
  outResult.nextWeightCursor = weightCursor
  outResult.nextBiasCursor = biasCursor
  let layerCursor = blaiRecoveredLayerCursor(layerIndex, layers.len)
  if not layerCursor.valid or not layers[layerCursor.index].active:
    blaiForwardLayerWorkspaceMaterializeReadinessInto(
      outResult, outResult.readiness)
    outResult.instructionFirstBlock = outResult.readiness.instructionFirstBlock
    outResult.weightWorkspaceFirstBlock =
      outResult.readiness.weightWorkspaceFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    return

  blaiPrepareForwardLayerInstructionsInWorkspaceInto(
    layers[layerCursor.index].layer, ctrl, stream, modelResources, workspace,
    workspaceBytes, layerIndex, useTflite, outResult.instructions, c2,
    includeExtra, descriptorHalt, midOutState)
  if not outResult.instructions.ready:
    blaiForwardLayerWorkspaceMaterializeReadinessInto(
      outResult, outResult.readiness)
    outResult.instructionFirstBlock = outResult.readiness.instructionFirstBlock
    outResult.weightWorkspaceFirstBlock =
      outResult.readiness.weightWorkspaceFirstBlock
    outResult.firstBlock = outResult.readiness.firstBlock
    return

  blaiMaterializeForwardLayerWeightsInWorkspaceInto(
    layers, layerIndex, useTflite, workspace, cpuWeightBytes, cpuBiasBytes,
    weightCursor, biasCursor, decodedWeights, decodedBiases, npuWeightBytes,
    npuBiases, temporaryWeights, workspaceBytes, outResult.weights, pack)
  if outResult.weights.workspaceStored:
    outResult.nextWeightCursor = outResult.weights.nextWeightCursor
    outResult.nextBiasCursor = outResult.weights.nextBiasCursor
  blaiForwardLayerWorkspaceMaterializeReadinessInto(
    outResult, outResult.readiness)
  outResult.instructionFirstBlock = outResult.readiness.instructionFirstBlock
  outResult.weightWorkspaceFirstBlock =
    outResult.readiness.weightWorkspaceFirstBlock
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.ready = outResult.readiness.ready

proc blaiMaterializeForwardLayerWorkspace*(
    layers: var openArray[BlaiCpuParsedLayerState],
    layerIndex: uint32,
    useTflite: bool,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    weightCursor: BlaiCpuStreamCursor,
    biasCursor: BlaiCpuStreamCursor,
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiForwardLayerWorkspaceMaterializeResult =
  ## Convenience wrapper for one parsed-state layer workspace materialization.
  blaiMaterializeForwardLayerWorkspaceInto(
    layers, layerIndex, useTflite, ctrl, stream, modelResources, workspace,
    workspaceBytes, cpuWeightBytes, cpuBiasBytes, weightCursor, biasCursor,
    decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
    temporaryWeights, pack, c2, includeExtra, descriptorHalt, midOutState,
    result)

proc blaiForwardModelWorkspaceMaterializeReadinessInto*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    outResult: var BlaiForwardModelWorkspaceMaterializeReadiness) =
  ## Derive the public readiness summary for model workspace materialization.
  outResult = default(BlaiForwardModelWorkspaceMaterializeReadiness)
  outResult.layerCount = materialization.layerCount
  outResult.expectedLayerCount = materialization.expectedLayerCount
  outResult.layerStorageFits = materialization.layerStorageFits
  outResult.missingLayerCount = materialization.missingLayerCount
  outResult.attemptedLayerCount = materialization.attemptedLayerCount
  outResult.readyLayerCount = materialization.readyLayerCount
  outResult.blockedLayerCount = materialization.blockedLayerCount
  outResult.firstBlockedLayer = materialization.firstBlockedLayer
  outResult.lastReadyLayer = materialization.lastReadyLayer
  outResult.firstBlockedLayerFirstBlock =
    materialization.firstBlockedLayerFirstBlock
  outResult.firstBlockedInstructionFirstBlock =
    materialization.firstBlockedInstructionFirstBlock
  outResult.firstBlockedWeightWorkspaceFirstBlock =
    materialization.firstBlockedWeightWorkspaceFirstBlock
  if not outResult.layerStorageFits:
    outResult.firstBlock = blaiForwardModelWorkspaceMaterializeLayerStorage
  elif outResult.blockedLayerCount != 0:
    outResult.firstBlock = blaiForwardModelWorkspaceMaterializeLayer
  else:
    outResult.firstBlock = blaiForwardModelWorkspaceMaterializeNoBlock
  outResult.ready = outResult.layerStorageFits and outResult.blockedLayerCount == 0

proc blaiForwardModelWorkspaceMaterializeReadiness*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult):
    BlaiForwardModelWorkspaceMaterializeReadiness =
  ## Convenience wrapper for model workspace materialization readiness.
  blaiForwardModelWorkspaceMaterializeReadinessInto(materialization, result)

proc blaiForwardModelWorkspaceMaterializeActiveEvidenceInto*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    expectedStorageLayerCount: uint32,
    expectedModelLayerCount: uint32,
    expectedSkippedLayerCount: uint32,
    expectedAttemptedLayerCount: uint32,
    expectedReadyLayerCount: uint32,
    expectedLastReadyLayer: int32,
    outResult: var BlaiForwardModelWorkspaceMaterializeActiveEvidence) =
  ## Derive focused active-fixture evidence for successful materialization.
  outResult = default(BlaiForwardModelWorkspaceMaterializeActiveEvidence)
  outResult.storageLayerCountMatches =
    materialization.layerCount == expectedStorageLayerCount
  outResult.expectedLayerCountMatches =
    materialization.expectedLayerCount == expectedModelLayerCount
  outResult.skippedLayerCountMatches =
    materialization.skippedLayerCount == expectedSkippedLayerCount
  outResult.attemptedLayerCountMatches =
    materialization.attemptedLayerCount == expectedAttemptedLayerCount
  outResult.readyLayerCountMatches =
    materialization.readyLayerCount == expectedReadyLayerCount
  outResult.noMissingLayers = materialization.missingLayerCount == 0'u32
  outResult.noBlockedLayers = materialization.blockedLayerCount == 0'u32
  outResult.noFirstBlockedLayer = materialization.firstBlockedLayer < 0
  outResult.lastReadyLayerMatches =
    materialization.lastReadyLayer == expectedLastReadyLayer
  outResult.firstBlockNone =
    materialization.firstBlock == blaiForwardModelWorkspaceMaterializeNoBlock
  outResult.readinessFirstBlockMatches =
    materialization.readiness.firstBlock == materialization.firstBlock
  outResult.allReadyMatchesReadiness =
    materialization.allReady == materialization.readiness.ready
  outResult.readinessReady = materialization.readiness.ready
  outResult.valid =
    outResult.storageLayerCountMatches and outResult.expectedLayerCountMatches and
      outResult.skippedLayerCountMatches and
      outResult.attemptedLayerCountMatches and
      outResult.readyLayerCountMatches and outResult.noMissingLayers and
      outResult.noBlockedLayers and outResult.noFirstBlockedLayer and
      outResult.lastReadyLayerMatches and outResult.firstBlockNone and
      outResult.readinessFirstBlockMatches and
      outResult.allReadyMatchesReadiness and outResult.readinessReady

proc blaiForwardModelWorkspaceMaterializeActiveEvidence*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    expectedStorageLayerCount: uint32,
    expectedModelLayerCount: uint32,
    expectedSkippedLayerCount: uint32,
    expectedAttemptedLayerCount: uint32,
    expectedReadyLayerCount: uint32,
    expectedLastReadyLayer: int32):
    BlaiForwardModelWorkspaceMaterializeActiveEvidence =
  ## Convenience wrapper for active-fixture materialization evidence.
  blaiForwardModelWorkspaceMaterializeActiveEvidenceInto(
    materialization, expectedStorageLayerCount, expectedModelLayerCount,
    expectedSkippedLayerCount, expectedAttemptedLayerCount,
    expectedReadyLayerCount, expectedLastReadyLayer, result)

proc blaiMaterializeForwardModelWorkspaceInto*(
    layers: var openArray[BlaiCpuInstLayer64],
    useTflite: bool,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false,
    outResult: var BlaiForwardModelWorkspaceMaterializeResult) =
  ## Materialize every currently NPU-enabled layer into one reusable workspace.
  ##
  ## The workspace is reusable per layer; after success it contains the last
  ## materialized layer's instruction/weight/bias bytes and the returned cursors
  ## identify consumed CPU model streams.
  outResult = default(BlaiForwardModelWorkspaceMaterializeResult)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.expectedLayerCount = modelResources.layerCount
  outResult.layerStorageFits = outResult.layerCount >= outResult.expectedLayerCount
  if not outResult.layerStorageFits:
    outResult.missingLayerCount =
      outResult.expectedLayerCount - outResult.layerCount
  outResult.firstBlockedLayer = -1
  outResult.lastReadyLayer = -1
  outResult.nextWeightCursor = blaiCpuStreamCursor()
  outResult.nextBiasCursor = blaiCpuStreamCursor()
  if not outResult.layerStorageFits:
    blaiForwardModelWorkspaceMaterializeReadinessInto(
      outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.allReady = outResult.readiness.ready
    return

  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    inc outResult.blockedLayerCount
    outResult.firstBlockedLayerCaptured = true
    blaiForwardModelWorkspaceMaterializeReadinessInto(
      outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.allReady = outResult.readiness.ready
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      inc outResult.blockedLayerCount
      outResult.firstBlockedLayerCaptured = true
      break
    let layer = layers[layerCursor.layerIndex]
    if layer.npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    inc outResult.attemptedLayerCount
    let materializeLayerIndex =
      blaiLayerCursorIndexAbi(layerCursor.layerIndex)
    if not materializeLayerIndex.valid:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        let diagnosticLayerIndex = blaiLayerIndexAbi(layerCursor.layerIndex)
        if diagnosticLayerIndex.valid:
          outResult.firstBlockedLayer = diagnosticLayerIndex.value
        outResult.firstBlockedLayerCaptured = true
      break
    var layerResult: BlaiForwardLayerWorkspaceMaterializeResult
    blaiMaterializeForwardLayerWorkspaceInto(
      layers, materializeLayerIndex.value, useTflite, ctrl, stream, modelResources,
      workspace, workspaceBytes, cpuWeightBytes, cpuBiasBytes,
      outResult.nextWeightCursor, outResult.nextBiasCursor,
      decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
      temporaryWeights, pack, c2, includeExtra, descriptorHalt, midOutState,
      layerResult)
    outResult.lastLayer = layerResult
    if layerResult.ready:
      inc outResult.readyLayerCount
      outResult.lastReadyLayer = blaiLayerIndexValue(layerCursor.layerIndex)
      outResult.nextWeightCursor = layerResult.nextWeightCursor
      outResult.nextBiasCursor = layerResult.nextBiasCursor
    else:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        outResult.firstBlockedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
        outResult.firstBlockedLayerCaptured = true
        outResult.firstBlockedLayerReadiness = layerResult.readiness
        outResult.firstBlockedLayerFirstBlock = layerResult.firstBlock
        outResult.firstBlockedInstructionFirstBlock =
          layerResult.instructionFirstBlock
        outResult.firstBlockedWeightWorkspaceFirstBlock =
          layerResult.weightWorkspaceFirstBlock
      break

  blaiForwardModelWorkspaceMaterializeReadinessInto(
    outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.allReady = outResult.readiness.ready

proc blaiMaterializeForwardModelWorkspace*(
    layers: var openArray[BlaiCpuInstLayer64],
    useTflite: bool,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiForwardModelWorkspaceMaterializeResult =
  ## Convenience result-returning wrapper for model workspace materialization.
  blaiMaterializeForwardModelWorkspaceInto(
    layers, useTflite, ctrl, stream, modelResources, workspace, workspaceBytes,
    cpuWeightBytes, cpuBiasBytes, decodedWeights, decodedBiases, npuWeightBytes,
    npuBiases, temporaryWeights, pack, c2, includeExtra, descriptorHalt,
    midOutState, result)

proc blaiMaterializeForwardModelWorkspaceInto*(
    layers: var openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false,
    outResult: var BlaiForwardModelWorkspaceMaterializeResult) =
  ## Materialize every active NPU-enabled parsed-state layer into workspace.
  outResult = default(BlaiForwardModelWorkspaceMaterializeResult)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.expectedLayerCount = modelResources.layerCount
  outResult.layerStorageFits = outResult.layerCount >= outResult.expectedLayerCount
  if not outResult.layerStorageFits:
    outResult.missingLayerCount =
      outResult.expectedLayerCount - outResult.layerCount
  outResult.firstBlockedLayer = -1
  outResult.lastReadyLayer = -1
  outResult.nextWeightCursor = blaiCpuStreamCursor()
  outResult.nextBiasCursor = blaiCpuStreamCursor()
  if not outResult.layerStorageFits:
    blaiForwardModelWorkspaceMaterializeReadinessInto(
      outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.allReady = outResult.readiness.ready
    return

  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    inc outResult.blockedLayerCount
    outResult.firstBlockedLayerCaptured = true
    blaiForwardModelWorkspaceMaterializeReadinessInto(
      outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.allReady = outResult.readiness.ready
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      inc outResult.blockedLayerCount
      outResult.firstBlockedLayerCaptured = true
      break
    let layerState = layers[layerCursor.layerIndex]
    if not layerState.active or layerState.layer.npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    inc outResult.attemptedLayerCount
    let materializeLayerIndex =
      blaiLayerCursorIndexAbi(layerCursor.layerIndex)
    if not materializeLayerIndex.valid:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        let diagnosticLayerIndex = blaiLayerIndexAbi(layerCursor.layerIndex)
        if diagnosticLayerIndex.valid:
          outResult.firstBlockedLayer = diagnosticLayerIndex.value
        outResult.firstBlockedLayerCaptured = true
      break
    var layerResult: BlaiForwardLayerWorkspaceMaterializeResult
    blaiMaterializeForwardLayerWorkspaceInto(
      layers, materializeLayerIndex.value, useTflite, ctrl, stream, modelResources,
      workspace, workspaceBytes, cpuWeightBytes, cpuBiasBytes,
      outResult.nextWeightCursor, outResult.nextBiasCursor,
      decodedWeights, decodedBiases, npuWeightBytes, npuBiases,
      temporaryWeights, pack, c2, includeExtra, descriptorHalt, midOutState,
      layerResult)
    outResult.lastLayer = layerResult
    if layerResult.ready:
      inc outResult.readyLayerCount
      outResult.lastReadyLayer = blaiLayerIndexValue(layerCursor.layerIndex)
      outResult.nextWeightCursor = layerResult.nextWeightCursor
      outResult.nextBiasCursor = layerResult.nextBiasCursor
    else:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        outResult.firstBlockedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
        outResult.firstBlockedLayerCaptured = true
        outResult.firstBlockedLayerReadiness = layerResult.readiness
        outResult.firstBlockedLayerFirstBlock = layerResult.firstBlock
        outResult.firstBlockedInstructionFirstBlock =
          layerResult.instructionFirstBlock
        outResult.firstBlockedWeightWorkspaceFirstBlock =
          layerResult.weightWorkspaceFirstBlock
      break

  blaiForwardModelWorkspaceMaterializeReadinessInto(
    outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.allReady = outResult.readiness.ready

proc blaiMaterializeForwardModelWorkspace*(
    layers: var openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
