    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiForwardModelWorkspaceMaterializeResult =
  ## Convenience wrapper for parsed-state model materialization.
  blaiMaterializeForwardModelWorkspaceInto(
    layers, useTflite, ctrl, stream, modelResources, workspace, workspaceBytes,
    cpuWeightBytes, cpuBiasBytes, decodedWeights, decodedBiases, npuWeightBytes,
    npuBiases, temporaryWeights, pack, c2, includeExtra, descriptorHalt,
    midOutState, result)

proc blaiForwardModelPrepareReadinessInto*(
    prepare: BlaiForwardModelPreparePlan,
    outResult: var BlaiForwardModelPrepareReadiness) =
  ## Derive the public readiness summary for workspace-backed model preparation.
  outResult = default(BlaiForwardModelPrepareReadiness)
  outResult.supported = prepare.supported
  outResult.workspaceReady = prepare.workspaceReady
  outResult.layerCount = prepare.layerCount
  outResult.expectedLayerCount = prepare.expectedLayerCount
  outResult.layerStorageFits = prepare.layerStorageFits
  outResult.missingLayerCount = prepare.missingLayerCount
  outResult.attemptedLayerCount = prepare.attemptedLayerCount
  outResult.readyLayerCount = prepare.readyLayerCount
  outResult.blockedLayerCount = prepare.blockedLayerCount
  outResult.firstBlockedLayer = prepare.firstBlockedLayer
  outResult.lastReadyLayer = prepare.lastReadyLayer
  outResult.firstBlockedPreparedFirstBlock =
    prepare.firstBlockedPreparedFirstBlock
  if not outResult.supported:
    outResult.firstBlock = blaiForwardModelPrepareResources
  elif not outResult.workspaceReady:
    outResult.firstBlock = blaiForwardModelPrepareWorkspace
  elif not outResult.layerStorageFits:
    outResult.firstBlock = blaiForwardModelPrepareLayerStorage
  elif outResult.blockedLayerCount != 0:
    outResult.firstBlock = blaiForwardModelPrepareLayer
  else:
    outResult.firstBlock = blaiForwardModelPrepareNoBlock
  outResult.ready = outResult.supported and outResult.workspaceReady and
    outResult.layerStorageFits and outResult.blockedLayerCount == 0

proc blaiForwardModelPrepareReadiness*(
    prepare: BlaiForwardModelPreparePlan): BlaiForwardModelPrepareReadiness =
  ## Convenience wrapper for workspace-backed model preparation readiness.
  blaiForwardModelPrepareReadinessInto(prepare, result)

proc blaiPrepareForwardModelInWorkspaceInto*(
    layers: var openArray[BlaiCpuInstLayer64],
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    outResult: var BlaiForwardModelPreparePlan,
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    useTflite: bool,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false) =
  ## Prepare every currently NPU-enabled layer using one reusable workspace.
  outResult = default(BlaiForwardModelPreparePlan)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.expectedLayerCount = modelResources.layerCount
  outResult.layerStorageFits = outResult.layerCount >= outResult.expectedLayerCount
  if not outResult.layerStorageFits:
    outResult.missingLayerCount =
      outResult.expectedLayerCount - outResult.layerCount
  outResult.firstBlockedLayer = -1
  outResult.lastReadyLayer = -1
  outResult.supported = modelResources.supported
  outResult.workspaceReady = workspace.supported and workspace.fits
  if not (outResult.supported and outResult.workspaceReady and
      outResult.layerStorageFits):
    blaiForwardModelPrepareReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.allReady = outResult.readiness.ready
    return

  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    inc outResult.blockedLayerCount
    blaiForwardModelPrepareReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.allReady = outResult.readiness.ready
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      inc outResult.blockedLayerCount
      break
    if layers[layerCursor.layerIndex].npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    inc outResult.attemptedLayerCount
    let prepareLayerIndex = blaiLayerCursorIndexAbi(layerCursor.layerIndex)
    if not prepareLayerIndex.valid:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        let diagnosticLayerIndex = blaiLayerIndexAbi(layerCursor.layerIndex)
        if diagnosticLayerIndex.valid:
          outResult.firstBlockedLayer = diagnosticLayerIndex.value
      break
    var prepared: BlaiForwardPreparedRunPlan
    blaiPrepareForwardNpuLayerInWorkspaceInto(
      layers[layerCursor.layerIndex], ctrl, stream, prepared,
      modelResources, workspace, prepareLayerIndex.value, useTflite,
      c2, includeExtra, descriptorHalt, midOutState)
    outResult.lastPrepared = prepared
    if prepared.ready:
      inc outResult.readyLayerCount
      outResult.lastReadyLayer = blaiLayerIndexValue(layerCursor.layerIndex)
    else:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        outResult.firstBlockedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
        outResult.firstBlockedPreparedFirstBlock = prepared.firstBlock

  blaiForwardModelPrepareReadinessInto(outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.allReady = outResult.readiness.ready

proc blaiPrepareForwardModelInWorkspaceInto*(
    layers: var openArray[BlaiCpuParsedLayerState],
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    outResult: var BlaiForwardModelPreparePlan,
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    useTflite: bool,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false) =
  ## Prepare every active NPU-enabled parsed-state layer using one workspace.
  outResult = default(BlaiForwardModelPreparePlan)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.expectedLayerCount = modelResources.layerCount
  outResult.layerStorageFits = outResult.layerCount >= outResult.expectedLayerCount
  if not outResult.layerStorageFits:
    outResult.missingLayerCount =
      outResult.expectedLayerCount - outResult.layerCount
  outResult.firstBlockedLayer = -1
  outResult.lastReadyLayer = -1
  outResult.supported = modelResources.supported
  outResult.workspaceReady = workspace.supported and workspace.fits
  if not (outResult.supported and outResult.workspaceReady and
      outResult.layerStorageFits):
    blaiForwardModelPrepareReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.allReady = outResult.readiness.ready
    return

  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    inc outResult.blockedLayerCount
    blaiForwardModelPrepareReadinessInto(outResult, outResult.readiness)
    outResult.firstBlock = outResult.readiness.firstBlock
    outResult.allReady = outResult.readiness.ready
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      inc outResult.blockedLayerCount
      break
    let layerState = layers[layerCursor.layerIndex]
    if not layerState.active or layerState.layer.npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    inc outResult.attemptedLayerCount
    let prepareLayerIndex = blaiLayerCursorIndexAbi(layerCursor.layerIndex)
    if not prepareLayerIndex.valid:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        let diagnosticLayerIndex = blaiLayerIndexAbi(layerCursor.layerIndex)
        if diagnosticLayerIndex.valid:
          outResult.firstBlockedLayer = diagnosticLayerIndex.value
      break
    var prepared: BlaiForwardPreparedRunPlan
    blaiPrepareForwardNpuLayerInWorkspaceInto(
      layers[layerCursor.layerIndex].layer, ctrl, stream, prepared,
      modelResources, workspace, prepareLayerIndex.value, useTflite,
      c2, includeExtra, descriptorHalt, midOutState)
    outResult.lastPrepared = prepared
    if prepared.ready:
      inc outResult.readyLayerCount
      outResult.lastReadyLayer = blaiLayerIndexValue(layerCursor.layerIndex)
    else:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        outResult.firstBlockedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
        outResult.firstBlockedPreparedFirstBlock = prepared.firstBlock

  blaiForwardModelPrepareReadinessInto(outResult, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.allReady = outResult.readiness.ready

proc blaiPrepareForwardModelInWorkspace*(
    layers: var openArray[BlaiCpuInstLayer64],
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    useTflite: bool,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false): BlaiForwardModelPreparePlan =
  ## Convenience result-returning wrapper for workspace-backed model preparation.
  blaiPrepareForwardModelInWorkspaceInto(
    layers, ctrl, stream, result, modelResources, workspace, useTflite,
    c2, includeExtra, descriptorHalt, midOutState)

proc blaiPrepareForwardModelInWorkspace*(
