proc blaiForwardModelRunSequenceReadinessInto*(
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    outResult: var BlaiForwardModelRunSequenceReadiness) =
  ## Explain whether a prepared model workspace can be used for run planning.
  outResult = default(BlaiForwardModelRunSequenceReadiness)
  outResult.resourcesSupported = modelResources.supported
  outResult.workspaceSupported = workspace.supported
  outResult.workspaceFits = workspace.fits
  outResult.hasInstructionWorkspace = workspace.instruction.active
  outResult.hasDataWorkspace = workspace.data.active
  outResult.workspaceReady = outResult.workspaceSupported and
    outResult.workspaceFits and outResult.hasInstructionWorkspace and
    outResult.hasDataWorkspace
  outResult.ready = outResult.resourcesSupported and outResult.workspaceReady
  if not outResult.resourcesSupported:
    outResult.firstBlock = blaiForwardModelRunSequenceReadinessResources
  elif not outResult.workspaceReady:
    outResult.firstBlock = blaiForwardModelRunSequenceReadinessWorkspace
  else:
    outResult.firstBlock = blaiForwardModelRunSequenceReadinessNoBlock

proc blaiForwardModelRunSequenceReadiness*(
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan): BlaiForwardModelRunSequenceReadiness =
  ## Convenience wrapper for model run-sequence readiness diagnostics.
  blaiForwardModelRunSequenceReadinessInto(
    modelResources, workspace, result)

proc blaiForwardModelRunSequenceConfigurabilityInto*(
    plan: BlaiForwardModelRunSequencePlan,
    outResult: var BlaiForwardModelRunSequenceConfigurability) =
  ## Derive per-layer configurability for a planned model run sequence.
  outResult = default(BlaiForwardModelRunSequenceConfigurability)
  outResult.supported = plan.supported
  outResult.workspaceReady = plan.workspaceReady
  outResult.layerCount = plan.layerCount
  outResult.expectedLayerCount = plan.expectedLayerCount
  outResult.layerStorageFits = plan.layerStorageFits
  outResult.missingLayerCount = plan.missingLayerCount
  outResult.attemptedLayerCount = plan.attemptedLayerCount
  outResult.configurableLayerCount = plan.configurableLayerCount
  outResult.blockedLayerCount = plan.blockedLayerCount
  outResult.cacheRangeCount = plan.cacheRangeCount
  outResult.firstBlockedLayer = plan.firstBlockedLayer
  outResult.lastConfigurableLayer = plan.lastConfigurableLayer
  outResult.firstBlockedRunCaptured = plan.firstBlockedRunCaptured
  outResult.firstBlockedRunConfigReadiness =
    plan.firstBlockedRunConfigReadiness
  outResult.readinessFirstBlock = plan.readinessFirstBlock
  outResult.firstBlockedRunConfigFirstBlock =
    plan.firstBlockedRunConfigFirstBlock
  if not (outResult.supported and outResult.workspaceReady):
    outResult.firstBlock = blaiForwardModelRunSequenceReadiness
  elif not outResult.layerStorageFits:
    outResult.firstBlock = blaiForwardModelRunSequenceLayerStorage
  elif outResult.blockedLayerCount != 0:
    outResult.firstBlock = blaiForwardModelRunSequenceRunConfig
  else:
    outResult.firstBlock = blaiForwardModelRunSequenceNoBlock
  outResult.configurable = outResult.supported and outResult.workspaceReady and
    outResult.layerStorageFits and outResult.blockedLayerCount == 0

proc blaiForwardModelRunSequenceConfigurability*(
    plan: BlaiForwardModelRunSequencePlan):
    BlaiForwardModelRunSequenceConfigurability =
  ## Convenience wrapper for model run-sequence configurability.
  blaiForwardModelRunSequenceConfigurabilityInto(plan, result)

proc blaiPlanForwardModelRunSequenceInto*(
    layers: openArray[BlaiCpuInstLayer64],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    outResult: var BlaiForwardModelRunSequencePlan) =
  ## Build recovered per-layer run plans from a prepared layer table.
  outResult = default(BlaiForwardModelRunSequencePlan)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.expectedLayerCount = modelResources.layerCount
  outResult.layerStorageFits = outResult.layerCount >= outResult.expectedLayerCount
  if not outResult.layerStorageFits:
    outResult.missingLayerCount =
      outResult.expectedLayerCount - outResult.layerCount
  outResult.firstBlockedLayer = -1
  outResult.lastConfigurableLayer = -1
  var readiness: BlaiForwardModelRunSequenceReadiness
  blaiForwardModelRunSequenceReadinessInto(
    modelResources, workspace, readiness)
  outResult.readiness = readiness
  outResult.supported = readiness.resourcesSupported
  outResult.workspaceReady = readiness.workspaceReady
  outResult.readinessFirstBlock = readiness.firstBlock
  if not readiness.ready or not outResult.layerStorageFits:
    blaiForwardModelRunSequenceConfigurabilityInto(
      outResult, outResult.configurability)
    outResult.firstBlock = outResult.configurability.firstBlock
    outResult.allConfigurable = outResult.configurability.configurable
    return

  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    inc outResult.blockedLayerCount
    blaiForwardModelRunSequenceConfigurabilityInto(
      outResult, outResult.configurability)
    outResult.firstBlock = outResult.configurability.firstBlock
    outResult.allConfigurable = outResult.configurability.configurable
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      inc outResult.blockedLayerCount
      break
    let layer = layers[layerCursor.layerIndex]
    if layer.npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    inc outResult.attemptedLayerCount
    let runSequenceLayerIndex =
      blaiLayerCursorIndexAbi(layerCursor.layerIndex)
    if not runSequenceLayerIndex.valid:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        let diagnosticLayerIndex = blaiLayerIndexAbi(layerCursor.layerIndex)
        if diagnosticLayerIndex.valid:
          outResult.firstBlockedLayer = diagnosticLayerIndex.value
        outResult.firstBlockedRunCaptured = true
      continue
    var runPlan: BlaiForwardNpuRunPlan
    blaiPlanForwardNpuRunInto(
      layer, runSequenceLayerIndex.value,
      dataBufferBytes = workspace.data.bytes,
      instAddr = workspace.instruction.address,
      dataBufferAddr = workspace.data.address,
      runPlan,
      weightAddr = workspace.weight.address,
      biasAddr = workspace.bias.address)
    outResult.lastRun = runPlan
    outResult.cacheRangeCount += runPlan.cacheRangeCount
    if runPlan.configurable:
      inc outResult.configurableLayerCount
      outResult.lastConfigurableLayer =
        blaiLayerIndexValue(layerCursor.layerIndex)
    else:
      inc outResult.blockedLayerCount
      if outResult.firstBlockedLayer < 0:
        outResult.firstBlockedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
        outResult.firstBlockedRunCaptured = true
        outResult.firstBlockedRunConfigReadiness =
          runPlan.configReadiness
        outResult.firstBlockedRunConfigFirstBlock =
          runPlan.configReadiness.firstBlock

  blaiForwardModelRunSequenceConfigurabilityInto(
    outResult, outResult.configurability)
  outResult.firstBlock = outResult.configurability.firstBlock
  outResult.allConfigurable = outResult.configurability.configurable

