proc blaiForwardModelExecuteCompletionInto*(
    execution: BlaiForwardModelExecuteResult,
    outResult: var BlaiForwardModelExecuteCompletion) =
  ## Derive terminal completion status for prepared model execution.
  outResult = default(BlaiForwardModelExecuteCompletion)
  outResult.runnable = execution.runnable
  outResult.layerCount = execution.layerCount
  outResult.expectedLayerCount = execution.expectedLayerCount
  outResult.layerStorageFits = execution.layerStorageFits
  outResult.missingLayerCount = execution.missingLayerCount
  outResult.attemptedLayerCount = execution.attemptedLayerCount
  outResult.completedLayerCount = execution.completedLayerCount
  outResult.failedLayerCount = execution.failedLayerCount
  outResult.firstFailedLayer = execution.firstFailedLayer
  outResult.lastCompletedLayer = execution.lastCompletedLayer
  outResult.runSequenceFirstBlock = execution.runSequenceFirstBlock
  if not execution.layerStorageFits:
    outResult.firstBlock = blaiForwardModelExecuteLayerStorage
  elif not execution.runnable:
    outResult.firstBlock = blaiForwardModelExecuteRunSequence
  elif execution.failedLayerCount != 0:
    outResult.firstBlock = blaiForwardModelExecuteLayerExecution
  else:
    outResult.firstBlock = blaiForwardModelExecuteNoBlock
  outResult.completed = outResult.runnable and outResult.layerStorageFits and
    outResult.failedLayerCount == 0

proc blaiForwardModelExecuteCompletion*(
    execution: BlaiForwardModelExecuteResult): BlaiForwardModelExecuteCompletion =
  ## Convenience wrapper for prepared model execution completion.
  blaiForwardModelExecuteCompletionInto(execution, result)

proc blaiSetForwardModelExecuteRunSequence(
    sequence: BlaiForwardModelRunSequencePlan,
    outResult: var BlaiForwardModelExecuteResult) =
  outResult.expectedLayerCount = sequence.expectedLayerCount
  outResult.layerStorageFits = sequence.layerStorageFits
  outResult.missingLayerCount = sequence.missingLayerCount
  outResult.runSequenceFirstBlock = sequence.firstBlock
  outResult.runSequenceReadinessFirstBlock = sequence.readinessFirstBlock
  outResult.runSequenceFirstBlockedLayer = sequence.firstBlockedLayer
  outResult.runSequenceFirstBlockedRunCaptured =
    sequence.firstBlockedRunCaptured
  outResult.runSequenceFirstBlockedRunConfigFirstBlock =
    sequence.firstBlockedRunConfigFirstBlock
  outResult.runSequenceFirstBlockedRunConfigReadiness =
    sequence.firstBlockedRunConfigReadiness
  outResult.runnable = sequence.supported and sequence.workspaceReady and
    sequence.allConfigurable

proc blaiExecuteForwardModelRunSequenceInto*(
    layers: openArray[BlaiCpuInstLayer64],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    executor: BlaiForwardLayerExecutor,
    outResult: var BlaiForwardModelExecuteResult) =
  ## Execute a prepared model's configurable run plans with a caller executor.
  outResult = default(BlaiForwardModelExecuteResult)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.firstFailedLayer = -1
  outResult.lastCompletedLayer = -1
  var sequence: BlaiForwardModelRunSequencePlan
  blaiPlanForwardModelRunSequenceInto(
    layers, modelResources, workspace, sequence)
  blaiSetForwardModelExecuteRunSequence(sequence, outResult)
  if not outResult.runnable:
    blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
    outResult.firstBlock = outResult.completion.firstBlock
    outResult.allCompleted = outResult.completion.completed
    return
  blaiPrepareForwardWorkspaceCacheInto(workspace, outResult.workspaceCache)
  if not outResult.workspaceCache.fits:
    outResult.failedLayerCount = 1
    outResult.firstFailedLayer = 0
    blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
    outResult.firstBlock = blaiForwardModelExecuteLayerExecution
    outResult.allCompleted = false
    return

  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    inc outResult.failedLayerCount
    blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
    outResult.firstBlock = outResult.completion.firstBlock
    outResult.allCompleted = outResult.completion.completed
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      inc outResult.failedLayerCount
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return
    let layer = layers[layerCursor.layerIndex]
    if layer.npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    let executeLayerIndex = blaiLayerCursorIndexAbi(layerCursor.layerIndex)
    if not executeLayerIndex.valid:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        let diagnosticLayerIndex = blaiLayerIndexAbi(layerCursor.layerIndex)
        if diagnosticLayerIndex.valid:
          outResult.firstFailedLayer = diagnosticLayerIndex.value
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return

    var runPlan: BlaiForwardNpuRunPlan
    blaiPlanForwardNpuRunInto(
      layer, executeLayerIndex.value,
      dataBufferBytes = workspace.data.bytes,
      instAddr = workspace.instruction.address,
      dataBufferAddr = workspace.data.address,
      runPlan,
      weightAddr = workspace.weight.address,
      biasAddr = workspace.bias.address)
    if not runPlan.configurable:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        outResult.firstFailedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return

    inc outResult.attemptedLayerCount
    let execution = executor(runPlan, executeLayerIndex.value)
    outResult.lastExecution = execution
    if not execution.completed and not outResult.firstFailedExecutionCaptured:
      outResult.firstFailedExecutionCaptured = true
      outResult.firstFailedExecution = execution
    if execution.completed:
      inc outResult.completedLayerCount
      outResult.lastCompletedLayer =
        blaiLayerIndexValue(layerCursor.layerIndex)
    else:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        outResult.firstFailedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return

  blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
  outResult.firstBlock = outResult.completion.firstBlock
  outResult.allCompleted = outResult.completion.completed

proc blaiExecuteForwardModelRunSequence*(
    layers: openArray[BlaiCpuInstLayer64],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    executor: BlaiForwardLayerExecutor): BlaiForwardModelExecuteResult =
  ## Convenience result-returning wrapper for callback-driven execution.
  blaiExecuteForwardModelRunSequenceInto(
    layers, modelResources, workspace, executor, result)

