proc blaiFinishParsedForwardWorkspaceFixtureValidation(
    outResult: var BlaiParsedForwardWorkspaceFixtureValidationResult) =
  outResult.bindingFirstBlock = outResult.binding.firstBlock
  outResult.hardwareAddressFirstBlock =
    outResult.hardwareAddresses.firstBlock
  outResult.inputFirstBlock = outResult.input.firstBlock
  outResult.executionFirstBlock = outResult.execution.firstBlock
  outResult.workspaceExecutionFirstBlock =
    outResult.execution.execution.firstBlock
  outResult.outputFirstBlock = outResult.output.firstBlock
  if not outResult.binding.bound:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationBinding
  elif not outResult.hardwareAddresses.ready:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationHardwareAddresses
  elif not outResult.input.moved:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationInput
  elif not outResult.execution.execution.allCompleted:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationExecution
  elif not outResult.output.valid:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationOutput
  else:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationNoBlock
  outResult.valid =
    outResult.firstBlock ==
      blaiParsedForwardWorkspaceFixtureValidationNoBlock

proc blaiParsedForwardWorkspaceFixtureValidationReadinessInto*(
    validation: BlaiParsedForwardWorkspaceFixtureValidationResult,
    outResult: var BlaiParsedForwardWorkspaceFixtureValidationReadiness) =
  ## Derive the public gate summary for parsed workspace fixture validation.
  outResult = default(BlaiParsedForwardWorkspaceFixtureValidationReadiness)
  outResult.bound = validation.binding.bound
  outResult.hardwareAddressesReady = validation.hardwareAddresses.ready
  outResult.inputMoved = validation.input.moved
  outResult.parsedExecutable = validation.execution.executable
  outResult.executed = validation.execution.execution.allCompleted
  outResult.outputValid = validation.output.valid
  outResult.outputMatched = validation.output.validation.outputMatched
  outResult.expectedElements = validation.output.expectedElements
  outResult.actualElements = validation.output.actualElements
  outResult.comparedElements = validation.output.comparedElements
  outResult.trailingElements = validation.output.trailingElements
  outResult.lengthMatches = validation.output.lengthMatches
  outResult.mismatchCount = validation.output.mismatchCount
  outResult.firstMismatch = validation.output.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    validation.output.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    validation.output.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch = validation.output.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch = validation.output.actualAtFirstMismatch
  blaiForwardWorkspaceOutputValidationReadinessInto(
    validation.output, outResult.outputReadiness)
  outResult.bindingFirstBlock = validation.bindingFirstBlock
  outResult.hardwareAddressFirstBlock = validation.hardwareAddressFirstBlock
  outResult.inputFirstBlock = validation.inputFirstBlock
  outResult.executionFirstBlock = validation.executionFirstBlock
  outResult.workspaceExecutionFirstBlock =
    validation.workspaceExecutionFirstBlock
  outResult.outputFirstBlock = validation.outputFirstBlock
  if not outResult.bound:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationBinding
  elif not outResult.hardwareAddressesReady:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationHardwareAddresses
  elif not outResult.inputMoved:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationInput
  elif not outResult.executed:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationExecution
  elif not outResult.outputValid:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationOutput
  else:
    outResult.firstBlock =
      blaiParsedForwardWorkspaceFixtureValidationNoBlock
  outResult.valid =
    outResult.firstBlock ==
      blaiParsedForwardWorkspaceFixtureValidationNoBlock

proc blaiParsedForwardWorkspaceFixtureValidationReadiness*(
    validation: BlaiParsedForwardWorkspaceFixtureValidationResult):
    BlaiParsedForwardWorkspaceFixtureValidationReadiness =
  ## Convenience wrapper for parsed workspace fixture validation readiness.
  blaiParsedForwardWorkspaceFixtureValidationReadinessInto(validation, result)

proc blaiValidateParsedForwardWorkspaceFixtureInto*(
    parsed: BlaiCpuModelParseResult,
    layers: var openArray[BlaiCpuParsedLayerState],
    plan: BlaiParsedForwardModelPlan,
    tensorPlan: BlaiForwardNpuPlan,
    inputIndex: uint32,
    input: openArray[uint8],
    expectedOutput: openArray[uint8],
    output: var openArray[uint8],
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    executor: BlaiForwardLayerExecutor,
    outResult: var BlaiParsedForwardWorkspaceFixtureValidationResult,
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false) =
  ## Bind, stage, execute, and validate a parsed-state workspace fixture.
  outResult = default(BlaiParsedForwardWorkspaceFixtureValidationResult)
  blaiBindForwardWorkspaceBufferInto(
    plan.resources, workspaceBytes, outResult.binding)
  if not outResult.binding.bound:
    blaiFinishParsedForwardWorkspaceFixtureValidation(outResult)
    return
  blaiForwardWorkspaceHardwareAddressReadinessInto(
    outResult.binding, outResult.hardwareAddresses)
  if not outResult.hardwareAddresses.ready:
    blaiFinishParsedForwardWorkspaceFixtureValidation(outResult)
    return
  blaiStageForwardWorkspaceInputInto(
    outResult.binding, tensorPlan, inputIndex, input, workspaceBytes,
    outResult.input)
  if not outResult.input.moved:
    blaiFinishParsedForwardWorkspaceFixtureValidation(outResult)
    return

  var boundPlan = plan
  boundPlan.workspace = outResult.binding.workspace
  boundPlan.workspaceReady =
    boundPlan.planned and boundPlan.workspace.supported and
    boundPlan.workspace.fits
  blaiMaterializeAndExecuteParsedForwardModelWorkspaceInto(
    parsed, layers, boundPlan, ctrl, stream, workspaceBytes,
    cpuWeightBytes, cpuBiasBytes, decodedWeights, decodedBiases,
    npuWeightBytes, npuBiases, temporaryWeights, executor, pack, c2,
    includeExtra, descriptorHalt, midOutState, outResult.execution)
  if not outResult.execution.execution.allCompleted:
    blaiFinishParsedForwardWorkspaceFixtureValidation(outResult)
    return
  blaiValidateForwardWorkspaceOutputInto(
    outResult.execution.execution, outResult.binding, tensorPlan,
    blaiForwardPrimaryOutput, workspaceBytes, expectedOutput, output,
    outResult.output)
  blaiFinishParsedForwardWorkspaceFixtureValidation(outResult)

