proc blaiTfliteParsedWorkspaceOracleValidationInto*(
    reference: BlaiReferenceTfliteParsedCheckedModelResult,
    fixture: BlaiParsedForwardWorkspaceFixtureValidationResult,
    outResult: var BlaiTfliteParsedWorkspaceOracleValidationResult) =
  ## Combine a checked TFLite CPU oracle with a parsed workspace fixture result.
  outResult = default(BlaiTfliteParsedWorkspaceOracleValidationResult)
  outResult.reference = reference
  outResult.fixture = fixture
  outResult.compare = fixture.output.compare
  outResult.referenceFirstBlock = reference.readiness.firstBlock
  outResult.fixtureFirstBlock = fixture.firstBlock
  outResult.referenceExecuted = reference.executed
  outResult.referenceValid =
    reference.executed and reference.model.modelValid and
    reference.model.allCompleted and reference.model.allWeightsConsumed and
    reference.model.allBiasesConsumed
  outResult.fixtureValid = fixture.valid
  outResult.outputValid = fixture.output.valid
  outResult.outputMatched = fixture.output.compare.matched
  outResult.completedLayerCount = fixture.execution.execution.completedLayerCount
  outResult.expectedElements = fixture.output.expectedElements
  outResult.actualElements = fixture.output.actualElements
  outResult.comparedElements = fixture.output.comparedElements
  outResult.trailingElements = fixture.output.trailingElements
  outResult.lengthMatches = fixture.output.lengthMatches
  outResult.mismatchCount = fixture.output.compare.mismatchCount
  outResult.firstMismatch = fixture.output.compare.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    fixture.output.compare.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    fixture.output.compare.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch =
    fixture.output.compare.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch =
    fixture.output.compare.actualAtFirstMismatch
  outResult.outputFirstBlock = fixture.outputFirstBlock
  if not outResult.referenceValid:
    outResult.firstBlock =
      blaiTfliteParsedWorkspaceOracleValidationReference
  elif not outResult.fixtureValid:
    outResult.firstBlock =
      blaiTfliteParsedWorkspaceOracleValidationFixture
  else:
    outResult.firstBlock =
      blaiTfliteParsedWorkspaceOracleValidationNoBlock
  outResult.valid =
    outResult.firstBlock ==
      blaiTfliteParsedWorkspaceOracleValidationNoBlock

proc blaiTfliteParsedWorkspaceOracleValidation*(
    reference: BlaiReferenceTfliteParsedCheckedModelResult,
    fixture: BlaiParsedForwardWorkspaceFixtureValidationResult):
    BlaiTfliteParsedWorkspaceOracleValidationResult =
  ## Convenience wrapper for TFLite oracle plus workspace fixture validation.
  blaiTfliteParsedWorkspaceOracleValidationInto(
    reference, fixture, result)

proc blaiTfliteParsedWorkspaceOracleValidationReadinessInto*(
    validation: BlaiTfliteParsedWorkspaceOracleValidationResult,
    outResult: var BlaiTfliteParsedWorkspaceOracleValidationReadiness) =
  ## Derive the public gate summary for TFLite workspace oracle validation.
  outResult = default(BlaiTfliteParsedWorkspaceOracleValidationReadiness)
  outResult.referenceExecuted = validation.referenceExecuted
  outResult.referenceValid = validation.referenceValid
  outResult.fixtureValid = validation.fixtureValid
  outResult.outputValid = validation.outputValid
  outResult.outputMatched = validation.outputMatched
  blaiForwardWorkspaceOutputValidationReadinessInto(
    validation.fixture.output, outResult.outputReadiness)
  blaiParsedForwardWorkspaceFixtureValidationReadinessInto(
    validation.fixture, outResult.fixtureReadiness)
  outResult.referenceFirstBlock = validation.referenceFirstBlock
  outResult.fixtureFirstBlock = validation.fixtureFirstBlock
  outResult.completedLayerCount = validation.completedLayerCount
  outResult.expectedElements = validation.expectedElements
  outResult.actualElements = validation.actualElements
  outResult.comparedElements = validation.comparedElements
  outResult.trailingElements = validation.trailingElements
  outResult.lengthMatches = validation.lengthMatches
  outResult.mismatchCount = validation.mismatchCount
  outResult.firstMismatch = validation.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    validation.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    validation.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch = validation.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch = validation.actualAtFirstMismatch
  outResult.outputFirstBlock = validation.outputFirstBlock
  if not outResult.referenceValid:
    outResult.firstBlock =
      blaiTfliteParsedWorkspaceOracleValidationReference
  elif not outResult.fixtureValid:
    outResult.firstBlock =
      blaiTfliteParsedWorkspaceOracleValidationFixture
  else:
    outResult.firstBlock =
      blaiTfliteParsedWorkspaceOracleValidationNoBlock
  outResult.valid =
    outResult.firstBlock ==
      blaiTfliteParsedWorkspaceOracleValidationNoBlock

proc blaiTfliteParsedWorkspaceOracleValidationReadiness*(
    validation: BlaiTfliteParsedWorkspaceOracleValidationResult):
    BlaiTfliteParsedWorkspaceOracleValidationReadiness =
  ## Convenience wrapper for TFLite workspace oracle validation readiness.
  blaiTfliteParsedWorkspaceOracleValidationReadinessInto(validation, result)

proc blaiFinishTfliteParsedWorkspaceOracleAddressFixture(
    outResult: var BlaiTfliteParsedWorkspaceOracleAddressFixtureResult) =
  outResult.projected = outResult.projection.projected
  outResult.fixtureValid = outResult.fixture.valid
  outResult.validationValid = outResult.validation.valid
  outResult.outputValid = outResult.validation.outputValid
  outResult.outputMatched = outResult.validation.outputMatched
  outResult.completedLayerCount = outResult.validation.completedLayerCount
  outResult.expectedElements = outResult.validation.expectedElements
  outResult.actualElements = outResult.validation.actualElements
  outResult.comparedElements = outResult.validation.comparedElements
  outResult.trailingElements = outResult.validation.trailingElements
  outResult.lengthMatches = outResult.validation.lengthMatches
  outResult.mismatchCount = outResult.validation.mismatchCount
  outResult.firstMismatch = outResult.validation.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    outResult.validation.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    outResult.validation.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch =
    outResult.validation.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch =
    outResult.validation.actualAtFirstMismatch
  outResult.projectionFirstBlock = outResult.projection.firstBlock
  outResult.fixtureFirstBlock = outResult.fixture.firstBlock
  outResult.validationFirstBlock = outResult.validation.firstBlock
  outResult.outputFirstBlock = outResult.validation.outputFirstBlock
  if not outResult.projected:
