proc blaiFixedParsedWorkspaceOracleValidationInto*(
    reference: BlaiReferenceFixedParsedCheckedModelResult,
    fixture: BlaiParsedForwardWorkspaceFixtureValidationResult,
    outResult: var BlaiFixedParsedWorkspaceOracleValidationResult) =
  ## Combine a checked fixed CPU oracle with a parsed workspace fixture result.
  outResult = default(BlaiFixedParsedWorkspaceOracleValidationResult)
  outResult.reference = reference
  outResult.fixture = fixture
  outResult.compare = fixture.output.compare
  outResult.referenceFirstBlock = reference.readiness.firstBlock
  outResult.fixtureFirstBlock = fixture.firstBlock
  outResult.referenceExecuted = reference.executed
  outResult.referenceValid =
    reference.executed and reference.model.modelValid and
    reference.model.allCompleted and reference.model.allWeightsConsumed and
    reference.model.allBiasesConsumed
  outResult.fixtureValid = fixture.valid
  outResult.outputValid = fixture.output.valid
  outResult.outputMatched = fixture.output.compare.matched
  outResult.completedLayerCount = fixture.execution.execution.completedLayerCount
  outResult.expectedElements = fixture.output.expectedElements
  outResult.actualElements = fixture.output.actualElements
  outResult.comparedElements = fixture.output.comparedElements
  outResult.trailingElements = fixture.output.trailingElements
  outResult.lengthMatches = fixture.output.lengthMatches
  outResult.mismatchCount = fixture.output.compare.mismatchCount
  outResult.firstMismatch = fixture.output.compare.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    fixture.output.compare.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    fixture.output.compare.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch =
    fixture.output.compare.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch =
    fixture.output.compare.actualAtFirstMismatch
  outResult.outputFirstBlock = fixture.outputFirstBlock
  if not outResult.referenceValid:
    outResult.firstBlock =
      blaiFixedParsedWorkspaceOracleValidationReference
  elif not outResult.fixtureValid:
    outResult.firstBlock =
      blaiFixedParsedWorkspaceOracleValidationFixture
  else:
    outResult.firstBlock =
      blaiFixedParsedWorkspaceOracleValidationNoBlock
  outResult.valid =
    outResult.firstBlock ==
      blaiFixedParsedWorkspaceOracleValidationNoBlock

