  var eligibility: BlaiNpuEligibilityResult
  blaiNpuEligibilityInto(parsed, eligibility)
  eligibility.eligible

const
  BlaiToolchainNpuRunConvType* = 0'i32
  BlaiToolchainNpuRunMaxpoolType* = 3'i32
  BlaiToolchainNpuRunMatmulType* = 9'i32
  BlaiToolchainNpuRunRouteWType* = 14'i32
  BlaiToolchainNpuRunSpecialDirectType* = 32'i32
  BlaiToolchainNpuRunFallbackDirectType* = 38'i32
  BlaiToolchainNpuRunRouteMaxType* = 50'i32
  BlaiToolchainNpuRunConvMaxKernel* = 7'u32
  BlaiToolchainNpuRunPoolMaxKernel* = 3'u32
  BlaiToolchainNpuRunMaxStride* = 2'u32
  BlaiToolchainNpuRunMaxDilation* = 2'u32
  BlaiToolchainNpuRunDepthwiseScaleNumerator* = 4'u64
  BlaiToolchainNpuRunDepthwiseScaleDenominator* = 9'u64
  BlaiToolchainNpuRunDepthwisePressureLimit* = 8192'u64

proc blaiToolchainNpuRunScalars*(
    layerTypeValue: int32,
    kernelW, kernelH, strideX, dilation, inputW, inputH, inputC, groups,
    strideY: uint32): BlaiToolchainNpuRunScalars =
  ## Build the recovered scalar ABI for toolchain `check_BLAI_NPU_RUN`.
  BlaiToolchainNpuRunScalars(
    layerTypeValue: layerTypeValue,
    kernelW: kernelW,
    kernelH: kernelH,
    strideX: strideX,
    dilation: dilation,
    inputW: inputW,
    inputH: inputH,
    inputC: inputC,
    groups: groups,
    strideY: strideY)

proc blaiToolchainNpuRunScalars*(layer: BlaiDecodedLayer):
    BlaiToolchainNpuRunScalars =
  ## Project a decoded instruction-layer view into the converter scalar gate.
  blaiToolchainNpuRunScalars(
    ord(layer.layerType).int32,
    layer.size, layer.size, layer.stride, layer.dilation,
    layer.w, layer.h, layer.c, max(layer.groups, 1'u32), layer.stride)

proc blaiToolchainNpuRunScalars*(layer: BlaiCpuInstLayer64):
    BlaiToolchainNpuRunScalars =
  ## Project the recovered SDK CPU-layer ABI into the converter scalar gate.
  let
    kernelW = if layer.sizeX > 0: layer.sizeX else: layer.size
    kernelH = if layer.sizeY > 0: layer.sizeY else: layer.size
    strideX = if layer.strideX > 0: layer.strideX else: layer.stride
    strideY = if layer.strideY > 0: layer.strideY else: layer.stride
  blaiToolchainNpuRunScalars(
    layer.layerType,
    nonNegativeU32(kernelW), nonNegativeU32(kernelH),
    nonNegativeU32(strideX), nonNegativeU32(layer.dilation),
    nonNegativeU32(layer.w), nonNegativeU32(layer.h),
    nonNegativeU32(layer.c), max(nonNegativeU32(layer.groups), 1'u32),
    nonNegativeU32(strideY))

proc blaiToolchainDepthwisePressureTooLarge(
    kernelW, inputC: uint32): bool =
  let kernelArea =
    if kernelW <= 4'u32: uint64(kernelW) * uint64(kernelW) else: 0x51'u64
  (kernelArea * uint64(inputC) * BlaiToolchainNpuRunDepthwiseScaleNumerator) >
    (BlaiToolchainNpuRunDepthwisePressureLimit *
      BlaiToolchainNpuRunDepthwiseScaleDenominator)

proc blaiToolchainNpuRunGateInto*(
    scalars: BlaiToolchainNpuRunScalars,
    outResult: var BlaiToolchainNpuRunGate) =
  ## Pure Nim translation of toolchain `check_BLAI_NPU_RUN`.
  outResult = default(BlaiToolchainNpuRunGate)
  outResult.kernelSquare = scalars.kernelW == scalars.kernelH
  if not outResult.kernelSquare:
    return

  case scalars.layerTypeValue
  of BlaiToolchainNpuRunConvType:
    outResult.knownLayer = true
    outResult.kernelSupported =
      scalars.kernelW <= BlaiToolchainNpuRunConvMaxKernel
    outResult.dilationSupported =
      scalars.dilation <= BlaiToolchainNpuRunMaxDilation
    outResult.strideXSupported =
      scalars.strideX <= BlaiToolchainNpuRunMaxStride
    outResult.strideYSupported =
      scalars.strideY <= BlaiToolchainNpuRunMaxStride
    outResult.depthwisePressureChecked =
      scalars.groups == scalars.inputC and scalars.groups > 1'u32
    outResult.depthwisePressureAccepted =
      not outResult.depthwisePressureChecked or
        not blaiToolchainDepthwisePressureTooLarge(
          scalars.kernelW, scalars.inputC)
    outResult.stride2KernelAccepted =
      scalars.strideX != 2'u32 or scalars.strideY != 2'u32 or
        scalars.kernelW == 2'u32
    outResult.stride2ParityAccepted =
      scalars.strideX != 2'u32 or
        ((scalars.inputW mod 2'u32) + (scalars.inputH mod 2'u32)) != 1'u32
    outResult.eligible =
      outResult.kernelSupported and outResult.dilationSupported and
      outResult.strideXSupported and outResult.strideYSupported and
      outResult.depthwisePressureAccepted and
      outResult.stride2KernelAccepted and outResult.stride2ParityAccepted
  of BlaiToolchainNpuRunMaxpoolType:
    outResult.knownLayer = true
    outResult.kernelSupported =
      scalars.kernelW <= BlaiToolchainNpuRunPoolMaxKernel
    outResult.strideXSupported =
      scalars.strideX <= BlaiToolchainNpuRunMaxStride
    outResult.strideYSupported = true
    outResult.dilationSupported = true
    outResult.depthwisePressureAccepted = true
    outResult.stride2ParityAccepted = true
    outResult.stride2KernelAccepted =
      scalars.strideX != 2'u32 or scalars.kernelW != 2'u32
    outResult.eligible =
      outResult.kernelSupported and outResult.strideXSupported and
      outResult.stride2KernelAccepted
  of BlaiToolchainNpuRunMatmulType,
     BlaiToolchainNpuRunRouteWType,
     BlaiToolchainNpuRunSpecialDirectType,
     BlaiToolchainNpuRunFallbackDirectType,
     BlaiToolchainNpuRunRouteMaxType:
    outResult.knownLayer = true
    outResult.directAcceptedLayer = true
    outResult.kernelSupported = true
    outResult.strideXSupported = true
    outResult.strideYSupported = true
    outResult.dilationSupported = true
    outResult.depthwisePressureAccepted = true
    outResult.stride2KernelAccepted = true
    outResult.stride2ParityAccepted = true
    outResult.eligible = true
  else:
    discard

proc blaiToolchainNpuRunGate*(
    scalars: BlaiToolchainNpuRunScalars): BlaiToolchainNpuRunGate =
  ## Result-returning wrapper for toolchain `check_BLAI_NPU_RUN`.
  blaiToolchainNpuRunGateInto(scalars, result)

proc blaiToolchainNpuRunGate*(layer: BlaiDecodedLayer):
    BlaiToolchainNpuRunGate =
  ## Decoded-layer wrapper for toolchain `check_BLAI_NPU_RUN`.
  blaiToolchainNpuRunGate(blaiToolchainNpuRunScalars(layer))

proc blaiToolchainNpuRunGate*(layer: BlaiCpuInstLayer64):
    BlaiToolchainNpuRunGate =
  ## CPU-layer ABI wrapper for toolchain `check_BLAI_NPU_RUN`.
  blaiToolchainNpuRunGate(blaiToolchainNpuRunScalars(layer))

proc blaiNpuCompletionStatusInto*(
    configured, interruptObserved: bool,
    outResult: var BlaiNpuCompletionStatusResult) =
  ## Project recovered SDK completion wait state to a typed status decision.
  outResult = default(BlaiNpuCompletionStatusResult)
  outResult.configured = configured
  outResult.interruptObserved = interruptObserved
  if not configured:
    outResult.unsupported = true
    outResult.status = npuUnsupported
  elif interruptObserved:
    outResult.completed = true
    outResult.status = npuOk
  else:
    outResult.timedOut = true
    outResult.status = npuTimeout

proc blaiNpuCompletionStatusResult*(
    configured, interruptObserved: bool): BlaiNpuCompletionStatusResult =
  ## Convenience result-returning wrapper for completion wait status.
  blaiNpuCompletionStatusInto(configured, interruptObserved, result)

proc blaiNpuCompletionStatus*(configured, interruptObserved: bool): NpuError =
  ## Compatibility wrapper for the recovered SDK completion wait status.
  blaiNpuCompletionStatusResult(configured, interruptObserved).status

proc blaiNpuCompletionStartPlanInto*(
    waitPlan: BlaiNpuCompletionWaitPlan,
    outResult: var BlaiNpuCompletionStartPlan) =
  ## Resolve the pre-start completion wait gate without touching hardware.
  outResult = default(BlaiNpuCompletionStartPlan)
  outResult.waitPlan = waitPlan
  blaiNpuCompletionStatusInto(
    waitPlan.configured, interruptObserved = false, outResult.initialStatus)
  outResult.starts = waitPlan.configured

proc blaiNpuCompletionStartPlan*(
    waitPlan: BlaiNpuCompletionWaitPlan): BlaiNpuCompletionStartPlan =
  ## Convenience wrapper for completion wait pre-start planning.
  blaiNpuCompletionStartPlanInto(waitPlan, result)

proc blaiNpuCompletionExitPlanInto*(
    waitPlan: BlaiNpuCompletionWaitPlan,
    interruptObserved: bool,
    outResult: var BlaiNpuCompletionExitPlan) =
  ## Resolve wait-exit interrupt-clear and clock-gate side effects.
  outResult = default(BlaiNpuCompletionExitPlan)
  outResult.waitPlan = waitPlan
  outResult.interruptObserved = interruptObserved
  outResult.clearInterrupt = waitPlan.clearOnComplete and interruptObserved
  outResult.disableClock = waitPlan.disableClockOnExit
  outResult.valid = waitPlan.configured

proc blaiNpuCompletionExitPlan*(
    waitPlan: BlaiNpuCompletionWaitPlan,
    interruptObserved: bool): BlaiNpuCompletionExitPlan =
  ## Convenience wrapper for completion wait-exit side-effect planning.
  blaiNpuCompletionExitPlanInto(waitPlan, interruptObserved, result)

proc npuInterruptPollTerminalPlanInto*(
    timeout, polls: uint32,
    interruptObserved, finalInterruptPending: bool,
    outResult: var NpuInterruptPollTerminalPlan) =
  ## Classify the terminal state of a recovered interrupt polling loop.
  outResult = default(NpuInterruptPollTerminalPlan)
  outResult.timeout = timeout
  outResult.polls = polls
  outResult.interruptObserved = interruptObserved
  outResult.finalInterruptPending = finalInterruptPending
  outResult.exhausted = not interruptObserved and polls == timeout
  outResult.completedBeforeBudget = interruptObserved and polls <= timeout
  outResult.terminalMatchesBudget =
    (outResult.exhausted and not finalInterruptPending) or
    (outResult.completedBeforeBudget and finalInterruptPending)
  outResult.valid = polls <= timeout and outResult.terminalMatchesBudget

proc npuInterruptPollTerminalPlan*(
    timeout, polls: uint32,
    interruptObserved, finalInterruptPending: bool): NpuInterruptPollTerminalPlan =
  ## Convenience wrapper for interrupt polling terminal classification.
  npuInterruptPollTerminalPlanInto(
    timeout, polls, interruptObserved, finalInterruptPending, result)

proc blaiNpuPollingWaitEvidencePlanInto*(
    completion: BlaiNpuCompletionWaitResult,
    outResult: var BlaiNpuPollingWaitEvidencePlan) =
  ## Derive polling wait terminal evidence without mutating the public result.
  outResult = default(BlaiNpuPollingWaitEvidencePlan)
  outResult.configured = completion.configured
  outResult.pollBudget = completion.timeout
  outResult.actualPolls = completion.poll.polls
  outResult.started = completion.started
  outResult.interruptObserved = completion.interruptObserved
  outResult.finalInterruptPending = completion.poll.finalInterruptPending
  outResult.statusUnsupported = completion.statusDecision.unsupported
  outResult.statusTimedOut = completion.statusDecision.timedOut
  outResult.statusCompleted = completion.statusDecision.completed
  if not completion.configured:
    outResult.terminal = blaiNpuPollingWaitUnsupported
  elif completion.interruptObserved:
    outResult.terminal = blaiNpuPollingWaitInterruptObserved
  else:
    outResult.terminal = blaiNpuPollingWaitTimeout
  outResult.budgetExhausted =
    completion.configured and completion.started and
      not completion.interruptObserved and completion.statusDecision.timedOut
  outResult.completedBeforeBudget =
    completion.configured and completion.started and
      completion.interruptObserved and completion.poll.completedBeforeBudget
  outResult.budgetMatchesPolls =
    (outResult.budgetExhausted and
      completion.poll.exhausted and outResult.actualPolls == outResult.pollBudget) or
    (outResult.completedBeforeBudget and outResult.actualPolls <= outResult.pollBudget)
  outResult.pollTraceValid =
    (not completion.started and completion.poll.polls == 0'u32) or
    completion.poll.valid
  outResult.terminalMatchesStatus =
    (outResult.terminal == blaiNpuPollingWaitUnsupported and
      outResult.statusUnsupported and not outResult.started) or
    (outResult.terminal == blaiNpuPollingWaitInterruptObserved and
      outResult.statusCompleted and outResult.interruptObserved) or
    (outResult.terminal == blaiNpuPollingWaitTimeout and
      outResult.statusTimedOut and outResult.budgetExhausted)
  outResult.valid =
    outResult.terminalMatchesStatus and
      ((outResult.statusUnsupported and completion.status == npuUnsupported) or
       (outResult.statusTimedOut and completion.status == npuTimeout) or
       (outResult.statusCompleted and completion.status == npuOk)) and
      (outResult.budgetMatchesPolls or not completion.started) and
      outResult.pollTraceValid

proc blaiNpuPollingWaitEvidencePlan*(
    completion: BlaiNpuCompletionWaitResult): BlaiNpuPollingWaitEvidencePlan =
  ## Convenience wrapper for polling wait evidence planning.
  blaiNpuPollingWaitEvidencePlanInto(completion, result)

proc blaiNpuPollingBudgetScaleEvidenceInto*(
    shortWait, longWait: BlaiNpuPollingWaitEvidence,
    outResult: var BlaiNpuPollingBudgetScaleEvidence) =
  ## Compare short and longer completion polling waits from live executions.
  outResult = default(BlaiNpuPollingBudgetScaleEvidence)
  outResult.shortValid = shortWait.valid
  outResult.longValid = longWait.valid
  outResult.shortBudget = shortWait.pollBudget
  outResult.longBudget = longWait.pollBudget
  outResult.budgetsOrdered =
    shortWait.pollBudget > 0'u32 and longWait.pollBudget > shortWait.pollBudget
  outResult.bothStarted = shortWait.started and longWait.started
  outResult.bothTimeout =
    shortWait.terminal == blaiNpuPollingWaitTimeout and
      longWait.terminal == blaiNpuPollingWaitTimeout
  outResult.bothBudgetExhausted =
    shortWait.budgetExhausted and longWait.budgetExhausted and
      shortWait.budgetMatchesPolls and longWait.budgetMatchesPolls
  outResult.longerPollsObserved =
    longWait.actualPolls == longWait.pollBudget and
      shortWait.actualPolls == shortWait.pollBudget and
      longWait.actualPolls > shortWait.actualPolls
  outResult.noInterruptObserved =
    not shortWait.interruptObserved and not longWait.interruptObserved
  outResult.finalSamplesClear =
    not shortWait.finalInterruptPending and not longWait.finalInterruptPending
  outResult.statusStable =
    shortWait.statusTimedOut and longWait.statusTimedOut and
      not shortWait.statusCompleted and not longWait.statusCompleted and
      not shortWait.statusUnsupported and not longWait.statusUnsupported
  outResult.terminalStable =
    shortWait.terminalMatchesStatus and longWait.terminalMatchesStatus and
      outResult.bothTimeout
  outResult.scaleMatchesEvidence =
    outResult.shortValid and outResult.longValid and
      outResult.budgetsOrdered and outResult.bothStarted and
      outResult.bothTimeout and outResult.bothBudgetExhausted and
      outResult.longerPollsObserved and outResult.noInterruptObserved and
      outResult.finalSamplesClear and outResult.statusStable and
      outResult.terminalStable
  if not outResult.shortValid:
    outResult.firstBlock = blaiNpuPollingBudgetScaleShort
  elif not outResult.longValid:
    outResult.firstBlock = blaiNpuPollingBudgetScaleLong
  elif not outResult.budgetsOrdered:
    outResult.firstBlock = blaiNpuPollingBudgetScaleOrder
  elif not (outResult.bothTimeout and outResult.bothBudgetExhausted and
      outResult.longerPollsObserved and outResult.terminalStable):
    outResult.firstBlock = blaiNpuPollingBudgetScaleTerminal
  elif not (outResult.noInterruptObserved and outResult.finalSamplesClear):
    outResult.firstBlock = blaiNpuPollingBudgetScaleInterrupt
  elif not outResult.statusStable:
    outResult.firstBlock = blaiNpuPollingBudgetScaleStatus
  else:
    outResult.firstBlock = blaiNpuPollingBudgetScaleNoBlock
  outResult.valid =
    outResult.scaleMatchesEvidence and
      outResult.firstBlock == blaiNpuPollingBudgetScaleNoBlock

proc blaiNpuPollingBudgetScaleEvidence*(
    shortWait, longWait: BlaiNpuPollingWaitEvidence):
    BlaiNpuPollingBudgetScaleEvidence =
  ## Convenience wrapper for completion polling budget-scale evidence.
  blaiNpuPollingBudgetScaleEvidenceInto(shortWait, longWait, result)

proc blaiNpuCompletionSideEffectPlanInto*(
    completion: BlaiNpuCompletionWaitResult,
    outResult: var BlaiNpuCompletionSideEffectPlan) =
  ## Derive wait-exit side-effect evidence without mutating public evidence.
  outResult = default(BlaiNpuCompletionSideEffectPlan)
  outResult.configured = completion.configured
  outResult.started = completion.started
  outResult.interruptObserved = completion.interruptObserved
  outResult.clearOnComplete = completion.clearOnComplete
  outResult.disableClockOnExit = completion.disableClockOnExit
  outResult.interruptCleared = completion.interruptCleared
  outResult.clockDisabled = completion.clockDisabled
  if not completion.configured:
    outResult.path = blaiNpuCompletionSideEffectUnsupported
  elif completion.interruptObserved:
    outResult.path = blaiNpuCompletionSideEffectCompleted
  else:
    outResult.path = blaiNpuCompletionSideEffectTimeout
  outResult.noSideEffects =
    not completion.started and not completion.interruptCleared and
      not completion.clockDisabled
  outResult.interruptClearSuppressed =
    not completion.interruptObserved and not completion.interruptCleared
  outResult.clockDisabledOnExit =
    (not completion.disableClockOnExit) or completion.clockDisabled
  outResult.completedSideEffectsApplied =
    completion.configured and completion.started and
      completion.statusDecision.completed and completion.interruptObserved and
      ((not completion.clearOnComplete) or completion.interruptCleared) and
      outResult.clockDisabledOnExit
  outResult.timeoutSideEffectsApplied =
    completion.configured and completion.started and
      completion.statusDecision.timedOut and
      outResult.interruptClearSuppressed and outResult.clockDisabledOnExit
  outResult.pathMatchesStatus =
    (outResult.path == blaiNpuCompletionSideEffectUnsupported and
      completion.statusDecision.unsupported and outResult.noSideEffects) or
    (outResult.path == blaiNpuCompletionSideEffectTimeout and
      outResult.timeoutSideEffectsApplied) or
    (outResult.path == blaiNpuCompletionSideEffectCompleted and
      outResult.completedSideEffectsApplied)
  outResult.valid =
    outResult.pathMatchesStatus and
      ((completion.statusDecision.unsupported and
          completion.status == npuUnsupported) or
       (completion.statusDecision.timedOut and
          completion.status == npuTimeout) or
       (completion.statusDecision.completed and completion.status == npuOk))

proc blaiNpuCompletionSideEffectPlan*(
    completion: BlaiNpuCompletionWaitResult): BlaiNpuCompletionSideEffectPlan =
  ## Convenience wrapper for wait-exit side-effect evidence planning.
  blaiNpuCompletionSideEffectPlanInto(completion, result)

proc blaiNpuClockExitPlanInto*(
    completion: BlaiNpuCompletionWaitResult,
    outResult: var BlaiNpuClockExitPlan) =
  ## Derive wait-exit clock evidence without mutating public evidence.
  outResult = default(BlaiNpuClockExitPlan)
  outResult.configured = completion.configured
  outResult.started = completion.started
  outResult.disableClockOnExit = completion.disableClockOnExit
  outResult.waitExitClockEnabled = completion.waitExitClock.enabled
  outResult.waitExitClockSourceKnown = completion.waitExitClock.sourceKnown
  outResult.waitExitClockSource320M =
    completion.waitExitClock.source == npuClk320M
  outResult.waitExitClockDividerZero = completion.waitExitClock.divider == 0
  outResult.clockDisabled = completion.clockDisabled
  outResult.statusUnsupported = completion.statusDecision.unsupported
  outResult.statusTimedOut = completion.statusDecision.timedOut
  outResult.statusCompleted = completion.statusDecision.completed
  if not completion.started:
    outResult.path = blaiNpuClockExitUnsupportedNoStart
  elif not completion.disableClockOnExit:
    outResult.path = blaiNpuClockExitRetainedNoDisable
  elif completion.statusDecision.timedOut:
    outResult.path = blaiNpuClockExitDisabledAfterTimeout
  else:
    outResult.path = blaiNpuClockExitDisabledAfterCompletion
  outResult.noStartNoClockChange =
    not completion.started and not completion.clockDisabled
  outResult.retainedUntilWaitExit =
    completion.started and completion.waitExitClock.enabled and
      completion.waitExitClock.sourceKnown and
      completion.waitExitClock.source == npuClk320M and
      completion.waitExitClock.divider == 0
  outResult.disabledAfterTimeout =
    completion.started and completion.statusDecision.timedOut and
      completion.disableClockOnExit and outResult.retainedUntilWaitExit and
      completion.clockDisabled
  outResult.disabledAfterCompletion =
    completion.started and completion.statusDecision.completed and
      completion.disableClockOnExit and outResult.retainedUntilWaitExit and
      completion.clockDisabled
  outResult.retainedWithoutDisable =
    completion.started and not completion.disableClockOnExit and
      outResult.retainedUntilWaitExit and not completion.clockDisabled
  outResult.pathMatchesStatus =
    (outResult.path == blaiNpuClockExitUnsupportedNoStart and
      outResult.statusUnsupported and outResult.noStartNoClockChange) or
    (outResult.path == blaiNpuClockExitRetainedNoDisable and
      outResult.retainedWithoutDisable) or
    (outResult.path == blaiNpuClockExitDisabledAfterTimeout and
      outResult.disabledAfterTimeout) or
    (outResult.path == blaiNpuClockExitDisabledAfterCompletion and
      outResult.disabledAfterCompletion)
  outResult.valid = outResult.pathMatchesStatus

proc blaiNpuClockExitPlan*(
    completion: BlaiNpuCompletionWaitResult): BlaiNpuClockExitPlan =
  ## Convenience wrapper for completion clock-exit evidence planning.
  blaiNpuClockExitPlanInto(completion, result)

proc blaiNpuRuntimeOwnershipPlan*(): BlaiNpuRuntimeOwnershipPlan =
  ## Recover SDK `blai_npu_init` / `forward_NPU` RTOS primitive ownership.
  ##
  ## The vendor runtime creates a counting semaphore for CNN interrupt delivery
  ## and a mutex for forward_NPU execution serialization. This bare-metal HAL
  ## keeps those as typed evidence while actively using a polling wait and a
  ## single-thread execution guard.
  BlaiNpuRuntimeOwnershipPlan(
    initCreatesInterruptSemaphore: true,
    initCreatesExecutionMutex: true,
    initDisablesClock: true,
    sdkInterruptWait: blaiNpuRuntimeWaitSdkCountingSemaphore,
    activeInterruptWait: blaiNpuRuntimeWaitBareMetalPolling,
    sdkExecutionLock: blaiNpuRuntimeLockSdkMutex,
    activeExecutionLock: blaiNpuRuntimeLockBareMetalSingleThread,
    forwardRunTakesExecutionLock: true,
    forwardRunReleasesExecutionLock: true,
    forwardRunStopsAfterInference: true)

proc blaiNpuRuntimeLifecycleEvidenceInto*(
    initiallyInitialized: bool,
    operation: BlaiNpuRuntimeLifecycleOp,
    outResult: var BlaiNpuRuntimeLifecycleEvidence) =
  ## Classify SDK `blai_npu_init` / `blai_npu_destroy` lifecycle side effects.
  outResult = default(BlaiNpuRuntimeLifecycleEvidence)
  outResult.initiallyInitialized = initiallyInitialized
  outResult.operation = operation
  case operation
  of blaiNpuRuntimeLifecycleInit:
    if initiallyInitialized:
      outResult.initNoopWhenAlreadyInitialized = true
      outResult.finalInitialized = true
    else:
      outResult.createsInterruptSemaphore = true
      outResult.createsExecutionMutex = true
      outResult.disablesClockOnInit = true
      outResult.setsInitialized = true
      outResult.finalInitialized = true
  of blaiNpuRuntimeLifecycleDestroy:
    if initiallyInitialized:
      outResult.deletesInterruptSemaphore = true
      outResult.deletesExecutionMutex = true
      outResult.clearsInitialized = true
      outResult.finalInitialized = false
    else:
      outResult.destroyNoopWhenNotInitialized = true
      outResult.finalInitialized = false
  outResult.transitionMatchesSdk =
    (operation == blaiNpuRuntimeLifecycleInit and initiallyInitialized and
      outResult.initNoopWhenAlreadyInitialized and
      outResult.finalInitialized) or
    (operation == blaiNpuRuntimeLifecycleInit and not initiallyInitialized and
      outResult.createsInterruptSemaphore and
      outResult.createsExecutionMutex and outResult.disablesClockOnInit and
      outResult.setsInitialized and outResult.finalInitialized) or
    (operation == blaiNpuRuntimeLifecycleDestroy and initiallyInitialized and
      outResult.deletesInterruptSemaphore and outResult.deletesExecutionMutex and
      outResult.clearsInitialized and not outResult.finalInitialized) or
    (operation == blaiNpuRuntimeLifecycleDestroy and not initiallyInitialized and
      outResult.destroyNoopWhenNotInitialized and not outResult.finalInitialized)
  outResult.valid = outResult.transitionMatchesSdk

proc blaiNpuRuntimeLifecycleEvidence*(
    initiallyInitialized: bool,
    operation: BlaiNpuRuntimeLifecycleOp): BlaiNpuRuntimeLifecycleEvidence =
  ## Convenience wrapper for recovered NPU runtime lifecycle evidence.
  blaiNpuRuntimeLifecycleEvidenceInto(initiallyInitialized, operation, result)

proc blaiNpuReleasePlanInto*(
    layers: openArray[BlaiCpuInstLayer64],
    cnAllocated: openArray[bool],
    npuLayerCount: uint32,
    npuLayersAllocated: bool,
    outResult: var BlaiNpuReleasePlan) =
  ## Plan SDK `blai_npu_release` without performing allocator side effects.
  ##
  ## The SDK walks `model->net->npu_layer_cnt`, frees each allocated layer `cn`
  ## side allocation, then frees `model->net->npu_layers` if present, and
  ## returns `BLAI_STATUS_NO_ERROR`. This projection keeps those ownership
  ## decisions as typed evidence over caller-owned storage.
  outResult = default(BlaiNpuReleasePlan)
  outResult.npuLayerCount = npuLayerCount
  outResult.layerStorageCount = blaiOpenArrayLenU32(layers)
  outResult.cnStorageCount = blaiOpenArrayLenU32(cnAllocated)
  outResult.npuLayersAllocated = npuLayersAllocated
  outResult.layerStorageFits =
    npuLayerCount <= outResult.layerStorageCount
  outResult.cnStorageFits =
    npuLayerCount <= outResult.cnStorageCount
  outResult.returnsNoError = true
  if not outResult.layerStorageFits:
    outResult.firstBlock = blaiNpuReleaseLayerStorage
    return
  if not outResult.cnStorageFits:
    outResult.firstBlock = blaiNpuReleaseCnStorage
    return

  let layerCount = blaiU32CountCursor(npuLayerCount, layers.len)
  if not layerCount.valid:
    outResult.firstBlock = blaiNpuReleaseLayerStorage
    return
  let layerWindow = blaiReleaseLayerTableWindow(layerCount.count)
  if not layerWindow.valid:
    outResult.firstBlock = blaiNpuReleaseLayerStorage
    return
  for layerIndex in 0 ..< layerCount.count:
    let layerCursor = blaiReleaseLayerTableCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      outResult.firstBlock = blaiNpuReleaseLayerStorage
      return
    discard layers[layerCursor.layerIndex]
    inc outResult.scannedLayerCount
    if cnAllocated[layerCursor.layerIndex]:
      inc outResult.cnAllocatedCount
      inc outResult.cnFreeCount
  outResult.layerTableFree = npuLayersAllocated
  outResult.complete =
    outResult.scannedLayerCount == npuLayerCount and
      outResult.cnFreeCount == outResult.cnAllocatedCount
  outResult.firstBlock =
    if outResult.complete: blaiNpuReleaseNoBlock
    else: blaiNpuReleaseLayerStorage
  outResult.valid =
    outResult.complete and outResult.returnsNoError and
      outResult.firstBlock == blaiNpuReleaseNoBlock

proc blaiNpuReleasePlan*(
    layers: openArray[BlaiCpuInstLayer64],
    cnAllocated: openArray[bool],
    npuLayerCount: uint32,
    npuLayersAllocated: bool): BlaiNpuReleasePlan =
  ## Convenience wrapper for recovered SDK `blai_npu_release` planning.
  blaiNpuReleasePlanInto(
    layers, cnAllocated, npuLayerCount, npuLayersAllocated, result)

proc blaiNpuReleasePlan*(
    layers: openArray[BlaiCpuInstLayer64],
    cnAllocated: openArray[bool],
    npuLayersAllocated: bool): BlaiNpuReleasePlan =
  ## Plan release for all provided NPU layers.
  blaiNpuReleasePlan(
    layers, cnAllocated, blaiOpenArrayLenU32(layers), npuLayersAllocated)

proc npuPlanCompletionWait*(
    timeout: uint32 = 5_000_000,
    configured: bool = npuHasConfiguredInstructionStream,
    clearOnComplete: bool = true,
    disableClockOnExit: bool = true): BlaiNpuCompletionWaitPlan =
  ## Plan the recovered `blai_npu_inference` completion wait policy.
  BlaiNpuCompletionWaitPlan(
    configured: configured,
    timeout: timeout,
    clearOnComplete: clearOnComplete,
    disableClockOnExit: disableClockOnExit)

proc blaiPlanForwardNpuCompletionWaitInto*(
    plan: BlaiForwardNpuRunPlan,
    outResult: var BlaiNpuCompletionWaitPlan,
    timeout: uint32 = 5_000_000,
    clearOnComplete: bool = true,
    disableClockOnExit: bool = true) =
  ## Derive the recovered completion wait policy into caller-owned storage.
  outResult = BlaiNpuCompletionWaitPlan(
    configured: plan.configurable,
    timeout: timeout,
    clearOnComplete: clearOnComplete,
    disableClockOnExit: disableClockOnExit)

proc blaiPlanForwardNpuCompletionWait*(
    plan: BlaiForwardNpuRunPlan,
    timeout: uint32 = 5_000_000,
    clearOnComplete: bool = true,
    disableClockOnExit: bool = true): BlaiNpuCompletionWaitPlan =
  ## Derive the recovered completion wait policy from a checked run plan.
  blaiPlanForwardNpuCompletionWaitInto(
    plan, result, timeout, clearOnComplete, disableClockOnExit)

static:
  proc putBits(inst: var BlaiInstruction, base, len: Natural, value: uint32) =
    blaiPutBits(inst, base, len, value)

  proc fakeForwardLayerExecutor(
      plan: BlaiForwardNpuRunPlan,
      layerIndex: uint32): BlaiForwardNpuExecuteResult =
    discard layerIndex
    result.runnable = plan.runnable
    result.configurable = plan.configurable
    result.cacheApplied = plan.configurable
    result.waitPlan = blaiPlanForwardNpuCompletionWait(plan)
    result.cache = BlaiForwardNpuCacheApplyResult(
      runnable: plan.runnable,
      configurable: plan.configurable,
      fits: plan.configurable,
      applied: plan.configurable)
    result.started = plan.configurable
    result.completed = plan.configurable
    result.status = if result.completed: npuOk else: npuTimeout
    result.completion = BlaiNpuCompletionWaitResult(
      configured: plan.configurable,
      started: plan.configurable,
      interruptObserved: result.completed,
      interruptCleared: result.completed,
      clockDisabled: plan.configurable,
      statusDecision: BlaiNpuCompletionStatusResult(
        configured: plan.configurable,
        interruptObserved: result.completed,
        completed: result.completed,
        status: result.status),
      status: result.status)
    result.outcome = BlaiForwardNpuExecuteOutcome(
      runnable: result.runnable,
      configurable: result.configurable,
      cacheFits: result.cache.fits,
      started: result.started,
      waitCompleted: result.completion.statusDecision.completed,
      completed: result.completed,
      status: result.status)

  proc failingForwardLayerExecutor(
      plan: BlaiForwardNpuRunPlan,
      layerIndex: uint32): BlaiForwardNpuExecuteResult =
    discard layerIndex
    result.runnable = plan.runnable
    result.configurable = plan.configurable
    result.waitPlan = blaiPlanForwardNpuCompletionWait(plan)
    result.cache = BlaiForwardNpuCacheApplyResult(
      runnable: plan.runnable,
      configurable: plan.configurable,
      fits: plan.configurable)
    result.started = plan.configurable
    result.status = npuTimeout
    result.completion = BlaiNpuCompletionWaitResult(
      configured: plan.configurable,
      started: plan.configurable,
      interruptObserved: false,
      interruptCleared: false,
      clockDisabled: plan.configurable,
      statusDecision: BlaiNpuCompletionStatusResult(
        configured: plan.configurable,
        interruptObserved: false,
        timedOut: plan.configurable,
        status: result.status),
      status: result.status)
    result.outcome = BlaiForwardNpuExecuteOutcome(
      runnable: result.runnable,
      configurable: result.configurable,
      cacheFits: result.cache.fits,
      started: result.started,
      waitCompleted: result.completion.statusDecision.completed,
      completed: result.completed,
      status: result.status)

  proc unexpectedForwardLayerExecutor(
      plan: BlaiForwardNpuRunPlan,
      layerIndex: uint32): BlaiForwardNpuExecuteResult =
    discard plan
    discard layerIndex
    doAssert false

  var sample: BlaiInstruction
  var unsupportedCompletionStatusInto: BlaiNpuCompletionStatusResult
  blaiNpuCompletionStatusInto(
    configured = false, interruptObserved = false,
    unsupportedCompletionStatusInto)
  let unsupportedCompletionStatus =
    blaiNpuCompletionStatusResult(configured = false,
                                  interruptObserved = false)
  doAssert unsupportedCompletionStatusInto == unsupportedCompletionStatus
  doAssert unsupportedCompletionStatus.unsupported
  doAssert not unsupportedCompletionStatus.timedOut
  doAssert not unsupportedCompletionStatus.completed
  doAssert unsupportedCompletionStatus.status == npuUnsupported
  let timeoutCompletionStatus =
    blaiNpuCompletionStatusResult(configured = true,
                                  interruptObserved = false)
  doAssert timeoutCompletionStatus.configured
  doAssert timeoutCompletionStatus.timedOut
  doAssert timeoutCompletionStatus.status == npuTimeout
  let okCompletionStatus =
    blaiNpuCompletionStatusResult(configured = true,
                                  interruptObserved = true)
  doAssert okCompletionStatus.completed
  doAssert okCompletionStatus.status == npuOk
  doAssert blaiNpuCompletionStatus(configured = false,
                                   interruptObserved = false) == npuUnsupported
  doAssert blaiNpuCompletionStatus(configured = true,
                                   interruptObserved = false) == npuTimeout
  doAssert blaiNpuCompletionStatus(configured = true,
                                   interruptObserved = true) == npuOk
  let runtimeOwnership = blaiNpuRuntimeOwnershipPlan()
  doAssert runtimeOwnership.initCreatesInterruptSemaphore
  doAssert runtimeOwnership.initCreatesExecutionMutex
  doAssert runtimeOwnership.initDisablesClock
  doAssert runtimeOwnership.sdkInterruptWait ==
    blaiNpuRuntimeWaitSdkCountingSemaphore
  doAssert runtimeOwnership.activeInterruptWait ==
    blaiNpuRuntimeWaitBareMetalPolling
  doAssert runtimeOwnership.sdkExecutionLock == blaiNpuRuntimeLockSdkMutex
  doAssert runtimeOwnership.activeExecutionLock ==
    blaiNpuRuntimeLockBareMetalSingleThread
  doAssert runtimeOwnership.forwardRunTakesExecutionLock
  doAssert runtimeOwnership.forwardRunReleasesExecutionLock
  doAssert runtimeOwnership.forwardRunStopsAfterInference
  var coldInitLifecycleInto: BlaiNpuRuntimeLifecycleEvidence
  blaiNpuRuntimeLifecycleEvidenceInto(
    initiallyInitialized = false,
    operation = blaiNpuRuntimeLifecycleInit,
    coldInitLifecycleInto)
  let coldInitLifecycle =
    blaiNpuRuntimeLifecycleEvidence(false, blaiNpuRuntimeLifecycleInit)
  doAssert coldInitLifecycleInto == coldInitLifecycle
  doAssert coldInitLifecycle.valid
  doAssert coldInitLifecycle.createsInterruptSemaphore
  doAssert coldInitLifecycle.createsExecutionMutex
  doAssert coldInitLifecycle.disablesClockOnInit
  doAssert coldInitLifecycle.setsInitialized
  doAssert coldInitLifecycle.finalInitialized
  let repeatedInitLifecycle =
    blaiNpuRuntimeLifecycleEvidence(true, blaiNpuRuntimeLifecycleInit)
  doAssert repeatedInitLifecycle.valid
  doAssert repeatedInitLifecycle.initNoopWhenAlreadyInitialized
  doAssert repeatedInitLifecycle.finalInitialized
  let initializedDestroyLifecycle =
    blaiNpuRuntimeLifecycleEvidence(true, blaiNpuRuntimeLifecycleDestroy)
  doAssert initializedDestroyLifecycle.valid
  doAssert initializedDestroyLifecycle.deletesInterruptSemaphore
  doAssert initializedDestroyLifecycle.deletesExecutionMutex
  doAssert initializedDestroyLifecycle.clearsInitialized
  doAssert not initializedDestroyLifecycle.finalInitialized
  let coldDestroyLifecycle =
    blaiNpuRuntimeLifecycleEvidence(false, blaiNpuRuntimeLifecycleDestroy)
  doAssert coldDestroyLifecycle.valid
  doAssert coldDestroyLifecycle.destroyNoopWhenNotInitialized
  doAssert not coldDestroyLifecycle.finalInitialized
  var npuReleaseLayers = [
    BlaiCpuInstLayer64(npuOn: 1),
    BlaiCpuInstLayer64(npuOn: 1),
    BlaiCpuInstLayer64(npuOn: 1)]
  let releaseCnAllocated = [true, false, true]
  var npuReleasePlanInto: BlaiNpuReleasePlan
  blaiNpuReleasePlanInto(
    npuReleaseLayers, releaseCnAllocated, 3'u32, true, npuReleasePlanInto)
  let npuReleasePlan =
    blaiNpuReleasePlan(npuReleaseLayers, releaseCnAllocated, 3'u32, true)
  doAssert npuReleasePlanInto == npuReleasePlan
  doAssert npuReleasePlan.valid
  doAssert npuReleasePlan.returnsNoError
  doAssert npuReleasePlan.scannedLayerCount == 3
  doAssert npuReleasePlan.cnAllocatedCount == 2
  doAssert npuReleasePlan.cnFreeCount == 2
  doAssert npuReleasePlan.layerTableFree
  doAssert npuReleasePlan.firstBlock == blaiNpuReleaseNoBlock
  let npuReleaseAllPlan =
    blaiNpuReleasePlan(npuReleaseLayers, releaseCnAllocated, true)
  doAssert npuReleaseAllPlan == npuReleasePlan
  let npuReleaseNoLayerTable =
    blaiNpuReleasePlan(npuReleaseLayers, releaseCnAllocated, 3'u32, false)
  doAssert npuReleaseNoLayerTable.valid
  doAssert not npuReleaseNoLayerTable.layerTableFree
  let npuReleaseLayerOverflow =
    blaiNpuReleasePlan(npuReleaseLayers, releaseCnAllocated, 4'u32, true)
  doAssert not npuReleaseLayerOverflow.valid
  doAssert not npuReleaseLayerOverflow.layerStorageFits
  doAssert npuReleaseLayerOverflow.firstBlock == blaiNpuReleaseLayerStorage
  let npuReleaseCnOverflow =
    blaiNpuReleasePlan(npuReleaseLayers, [true, false], 3'u32, true)
  doAssert not npuReleaseCnOverflow.valid
  doAssert npuReleaseCnOverflow.layerStorageFits
  doAssert not npuReleaseCnOverflow.cnStorageFits
  doAssert npuReleaseCnOverflow.firstBlock == blaiNpuReleaseCnStorage
  let completionPlan = npuPlanCompletionWait(
    timeout = 17, configured = true,
    clearOnComplete = false, disableClockOnExit = false)
  doAssert completionPlan.configured
  doAssert completionPlan.timeout == 17
  doAssert not completionPlan.clearOnComplete
  doAssert not completionPlan.disableClockOnExit
  let completionStartPlan = blaiNpuCompletionStartPlan(completionPlan)
  var completionStartPlanInto: BlaiNpuCompletionStartPlan
  blaiNpuCompletionStartPlanInto(completionPlan, completionStartPlanInto)
  doAssert completionStartPlanInto == completionStartPlan
  doAssert completionStartPlan.waitPlan == completionPlan
  doAssert completionStartPlan.starts
  doAssert completionStartPlan.initialStatus.timedOut
  doAssert completionStartPlan.initialStatus.status == npuTimeout
  let blockedCompletionStartPlan =
    blaiNpuCompletionStartPlan(
      npuPlanCompletionWait(timeout = 19, configured = false))
  doAssert not blockedCompletionStartPlan.starts
  doAssert blockedCompletionStartPlan.initialStatus.unsupported
  doAssert blockedCompletionStartPlan.initialStatus.status == npuUnsupported
  let completedCompletionExitPlan =
    blaiNpuCompletionExitPlan(
      npuPlanCompletionWait(
        timeout = 23, configured = true,
        clearOnComplete = true, disableClockOnExit = true),
      interruptObserved = true)
  var completedCompletionExitPlanInto: BlaiNpuCompletionExitPlan
  blaiNpuCompletionExitPlanInto(
    completedCompletionExitPlan.waitPlan, interruptObserved = true,
    completedCompletionExitPlanInto)
  doAssert completedCompletionExitPlanInto == completedCompletionExitPlan
  doAssert completedCompletionExitPlan.valid
  doAssert completedCompletionExitPlan.clearInterrupt
  doAssert completedCompletionExitPlan.disableClock
  let timedOutCompletionExitPlan =
    blaiNpuCompletionExitPlan(
      npuPlanCompletionWait(
        timeout = 29, configured = true,
        clearOnComplete = true, disableClockOnExit = true),
      interruptObserved = false)
  doAssert timedOutCompletionExitPlan.valid
  doAssert not timedOutCompletionExitPlan.clearInterrupt
  doAssert timedOutCompletionExitPlan.disableClock
  let blockedCompletionExitPlan =
    blaiNpuCompletionExitPlan(
      npuPlanCompletionWait(timeout = 31, configured = false),
      interruptObserved = false)
  doAssert not blockedCompletionExitPlan.valid
  doAssert not blockedCompletionExitPlan.clearInterrupt
  let exhaustedPollTerminal =
    npuInterruptPollTerminalPlan(
      timeout = 5, polls = 5,
      interruptObserved = false, finalInterruptPending = false)
  var exhaustedPollTerminalInto: NpuInterruptPollTerminalPlan
  npuInterruptPollTerminalPlanInto(
    timeout = 5, polls = 5,
    interruptObserved = false, finalInterruptPending = false,
    exhaustedPollTerminalInto)
  doAssert exhaustedPollTerminalInto == exhaustedPollTerminal
  doAssert exhaustedPollTerminal.exhausted
  doAssert not exhaustedPollTerminal.completedBeforeBudget
  doAssert exhaustedPollTerminal.terminalMatchesBudget
  doAssert exhaustedPollTerminal.valid
  let completedPollTerminal =
    npuInterruptPollTerminalPlan(
      timeout = 5, polls = 3,
      interruptObserved = true, finalInterruptPending = true)
  doAssert not completedPollTerminal.exhausted
  doAssert completedPollTerminal.completedBeforeBudget
  doAssert completedPollTerminal.terminalMatchesBudget
  doAssert completedPollTerminal.valid
  let invalidPollTerminal =
    npuInterruptPollTerminalPlan(
      timeout = 5, polls = 6,
      interruptObserved = false, finalInterruptPending = false)
  doAssert not invalidPollTerminal.valid
  let unsupportedPollingPlan =
    blaiNpuPollingWaitEvidencePlan(
      BlaiNpuCompletionWaitResult(
        configured: false,
        timeout: 7,
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: false,
          unsupported: true,
          status: npuUnsupported),
        status: npuUnsupported))
  var unsupportedPollingPlanInto: BlaiNpuPollingWaitEvidencePlan
  blaiNpuPollingWaitEvidencePlanInto(
    BlaiNpuCompletionWaitResult(
      configured: false,
      timeout: 7,
      statusDecision: BlaiNpuCompletionStatusResult(
        configured: false,
        unsupported: true,
        status: npuUnsupported),
      status: npuUnsupported),
    unsupportedPollingPlanInto)
  doAssert unsupportedPollingPlanInto == unsupportedPollingPlan
  doAssert unsupportedPollingPlan.terminal == blaiNpuPollingWaitUnsupported
  doAssert unsupportedPollingPlan.terminalMatchesStatus
  doAssert unsupportedPollingPlan.valid
  let timedOutPollingPlan =
    blaiNpuPollingWaitEvidencePlan(
      BlaiNpuCompletionWaitResult(
        configured: true,
        timeout: 5,
        started: true,
        poll: NpuInterruptPollResult(
          timeout: 5, polls: 5, exhausted: true,
          terminalMatchesBudget: true, valid: true),
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: true,
          timedOut: true,
          status: npuTimeout),
        status: npuTimeout))
  doAssert timedOutPollingPlan.terminal == blaiNpuPollingWaitTimeout
  doAssert timedOutPollingPlan.budgetExhausted
  doAssert timedOutPollingPlan.budgetMatchesPolls
  doAssert timedOutPollingPlan.valid
  let completedPollingPlan =
    blaiNpuPollingWaitEvidencePlan(
      BlaiNpuCompletionWaitResult(
        configured: true,
        timeout: 5,
        started: true,
        interruptObserved: true,
        poll: NpuInterruptPollResult(
          timeout: 5, polls: 3, interruptObserved: true,
          finalInterruptPending: true, completedBeforeBudget: true,
          terminalMatchesBudget: true, valid: true),
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: true,
          interruptObserved: true,
          completed: true,
          status: npuOk),
        status: npuOk))
  doAssert completedPollingPlan.terminal == blaiNpuPollingWaitInterruptObserved
  doAssert completedPollingPlan.completedBeforeBudget
  doAssert completedPollingPlan.budgetMatchesPolls
  doAssert completedPollingPlan.valid
  let unsupportedSideEffectPlan =
    blaiNpuCompletionSideEffectPlan(
      BlaiNpuCompletionWaitResult(
        configured: false,
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: false,
          unsupported: true,
          status: npuUnsupported),
        status: npuUnsupported))
  var unsupportedSideEffectPlanInto: BlaiNpuCompletionSideEffectPlan
  blaiNpuCompletionSideEffectPlanInto(
    BlaiNpuCompletionWaitResult(
      configured: false,
      statusDecision: BlaiNpuCompletionStatusResult(
        configured: false,
        unsupported: true,
        status: npuUnsupported),
      status: npuUnsupported),
    unsupportedSideEffectPlanInto)
  doAssert unsupportedSideEffectPlanInto == unsupportedSideEffectPlan
  doAssert unsupportedSideEffectPlan.path ==
    blaiNpuCompletionSideEffectUnsupported
  doAssert unsupportedSideEffectPlan.noSideEffects
  doAssert unsupportedSideEffectPlan.valid
  let timedOutSideEffectPlan =
    blaiNpuCompletionSideEffectPlan(
      BlaiNpuCompletionWaitResult(
        configured: true,
        started: true,
        disableClockOnExit: true,
        clockDisabled: true,
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: true,
          timedOut: true,
          status: npuTimeout),
        status: npuTimeout))
  doAssert timedOutSideEffectPlan.path == blaiNpuCompletionSideEffectTimeout
  doAssert timedOutSideEffectPlan.interruptClearSuppressed
  doAssert timedOutSideEffectPlan.clockDisabledOnExit
  doAssert timedOutSideEffectPlan.timeoutSideEffectsApplied
  doAssert timedOutSideEffectPlan.valid
  let completedSideEffectPlan =
    blaiNpuCompletionSideEffectPlan(
      BlaiNpuCompletionWaitResult(
        configured: true,
        started: true,
        interruptObserved: true,
        clearOnComplete: true,
        disableClockOnExit: true,
        interruptCleared: true,
        clockDisabled: true,
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: true,
          interruptObserved: true,
          completed: true,
          status: npuOk),
        status: npuOk))
  doAssert completedSideEffectPlan.path ==
    blaiNpuCompletionSideEffectCompleted
  doAssert completedSideEffectPlan.completedSideEffectsApplied
  doAssert completedSideEffectPlan.valid
  let unsupportedClockExitPlan =
    blaiNpuClockExitPlan(
      BlaiNpuCompletionWaitResult(
        configured: false,
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: false,
          unsupported: true,
          status: npuUnsupported),
        status: npuUnsupported))
  var unsupportedClockExitPlanInto: BlaiNpuClockExitPlan
  blaiNpuClockExitPlanInto(
    BlaiNpuCompletionWaitResult(
      configured: false,
      statusDecision: BlaiNpuCompletionStatusResult(
        configured: false,
        unsupported: true,
        status: npuUnsupported),
      status: npuUnsupported),
    unsupportedClockExitPlanInto)
  doAssert unsupportedClockExitPlanInto == unsupportedClockExitPlan
  doAssert unsupportedClockExitPlan.path == blaiNpuClockExitUnsupportedNoStart
  doAssert unsupportedClockExitPlan.noStartNoClockChange
  doAssert unsupportedClockExitPlan.valid
  let retainedClockExitPlan =
    blaiNpuClockExitPlan(
      BlaiNpuCompletionWaitResult(
        configured: true,
        started: true,
        disableClockOnExit: false,
        waitExitClock: NpuClockStatusResult(
          enabled: true, sourceKnown: true, source: npuClk320M, divider: 0),
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: true,
          timedOut: true,
          status: npuTimeout),
        status: npuTimeout))
  doAssert retainedClockExitPlan.path == blaiNpuClockExitRetainedNoDisable
  doAssert retainedClockExitPlan.retainedUntilWaitExit
  doAssert retainedClockExitPlan.retainedWithoutDisable
  doAssert retainedClockExitPlan.valid
  let timedOutClockExitPlan =
    blaiNpuClockExitPlan(
      BlaiNpuCompletionWaitResult(
        configured: true,
        started: true,
        disableClockOnExit: true,
        waitExitClock: NpuClockStatusResult(
          enabled: true, sourceKnown: true, source: npuClk320M, divider: 0),
        clockDisabled: true,
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: true,
          timedOut: true,
          status: npuTimeout),
        status: npuTimeout))
  doAssert timedOutClockExitPlan.path == blaiNpuClockExitDisabledAfterTimeout
  doAssert timedOutClockExitPlan.disabledAfterTimeout
  doAssert timedOutClockExitPlan.valid
  let completedClockExitPlan =
    blaiNpuClockExitPlan(
      BlaiNpuCompletionWaitResult(
        configured: true,
        started: true,
        disableClockOnExit: true,
        waitExitClock: NpuClockStatusResult(
          enabled: true, sourceKnown: true, source: npuClk320M, divider: 0),
        clockDisabled: true,
        statusDecision: BlaiNpuCompletionStatusResult(
          configured: true,
          interruptObserved: true,
          completed: true,
          status: npuOk),
        status: npuOk))
  doAssert completedClockExitPlan.path == blaiNpuClockExitDisabledAfterCompletion
  doAssert completedClockExitPlan.disabledAfterCompletion
  doAssert completedClockExitPlan.valid
  putBits(sample, 1, 12, 8)
  putBits(sample, 13, 12, 7)
  putBits(sample, 25, 12, 4)
  putBits(sample, 37, 12, 16)
  putBits(sample, 49, 12, 12)
  putBits(sample, 61, 5, 3)
  putBits(sample, 66, 5, 4)
  putBits(sample, 71, 5, 5)
  putBits(sample, 76, 5, 6)
  putBits(sample, 81, 5, 7)
  putBits(sample, 86, 5, 8)
  putBits(sample, 91, 3, 3)
  putBits(sample, 94, 5, 2)
  putBits(sample, 98, 1, 0)
  putBits(sample, 99, 1, 0)
  putBits(sample, 100, 2, 1)
  putBits(sample, 102, 5, 9)
  putBits(sample, 107, 5, 10)
  putBits(sample, 112, 5, 11)
  putBits(sample, 127, 1, 1)
  let decoded = decodeBlaiLayer(sample)
  doAssert decoded.layerType == blaiConvolutional
  doAssert decoded.w == 8
  doAssert decoded.h == 7
  doAssert decoded.c == 4
  doAssert decoded.cn0 == 16
  doAssert decoded.outC == 12
  doAssert decoded.fdata == 3
  doAssert decoded.fweight == 4
  doAssert decoded.fbias == 5
  doAssert decoded.froute1 == 6
  doAssert decoded.froute2 == 7
  doAssert decoded.fout == 8
  doAssert decoded.size == 3
  doAssert decoded.activation == 2
  doAssert decoded.inLayer1Mem == 9
  doAssert decoded.inLayer2Mem == 10
  doAssert decoded.outLayerMem == 11
  doAssert decoded.stride == 1
  doAssert decoded.dilation == 1
  doAssert decoded.groups == 4
  doAssert decoded.halt
  let encodedShape = blaiEncodeShapeDescriptor(BlaiNpuShapeDescriptor(
    layerW: 13,
    layerH: 11,
    layerC1: 7,
    layerC2: 5,
    layerO: 17))
  doAssert isBlaiLayerInstruction(encodedShape)
  let shapeDecoded = decodeBlaiLayer(encodedShape)
  doAssert shapeDecoded.w == 13
  doAssert shapeDecoded.h == 11
  doAssert shapeDecoded.c == 7
  doAssert shapeDecoded.cn0 == 5
  doAssert shapeDecoded.outC == 17
  let layerShape = blaiShapeDescriptor(BlaiCpuInstLayer64(
    w: 9,
    h: 8,
    c: 6,
    outC: 4), c2 = 3)
  let layerShapeDecoded = decodeBlaiLayer(blaiEncodeShapeDescriptor(layerShape))
  doAssert layerShapeDecoded.w == 9
  doAssert layerShapeDecoded.h == 8
  doAssert layerShapeDecoded.c == 6
  doAssert layerShapeDecoded.cn0 == 3
  doAssert layerShapeDecoded.outC == 4
  let encodedNormal = blaiEncodeNormalDescriptor(BlaiNpuNormalDescriptor(
    shape: BlaiNpuShapeDescriptor(layerW: 9, layerH: 8, layerC1: 7,
                                  layerC2: 6, layerO: 5),
    fdata: 1,
    fweight: 2,
    fbias: 3,
    froute1: 4,
    froute2: 5,
    fout: 6,
    convSize: 3,
    activation: 2))
  let normalDecoded = decodeBlaiLayer(encodedNormal)
  let normalDescriptorDecoded =
    decodeBlaiNormalDescriptorInstruction(encodedNormal)
  doAssert normalDecoded.w == 9
  doAssert normalDecoded.h == 8
  doAssert normalDecoded.c == 7
  doAssert normalDecoded.cn0 == 6
  doAssert normalDecoded.outC == 5
  doAssert normalDecoded.fdata == 1
  doAssert normalDecoded.fweight == 2
  doAssert normalDecoded.fbias == 3
  doAssert normalDecoded.froute1 == 4
  doAssert normalDecoded.froute2 == 5
  doAssert normalDecoded.fout == 6
  doAssert normalDecoded.size == 3
  doAssert normalDecoded.activation == 2
  doAssert normalDescriptorDecoded.shape.layerW == 9
  doAssert normalDescriptorDecoded.shape.layerH == 8
  doAssert normalDescriptorDecoded.shape.layerC1 == 7
  doAssert normalDescriptorDecoded.shape.layerC2 == 6
  doAssert normalDescriptorDecoded.shape.layerO == 5
  doAssert normalDescriptorDecoded.fdata == 1
  doAssert normalDescriptorDecoded.fweight == 2
  doAssert normalDescriptorDecoded.fbias == 3
  doAssert normalDescriptorDecoded.froute1 == 4
  doAssert normalDescriptorDecoded.froute2 == 5
  doAssert normalDescriptorDecoded.fout == 6
  doAssert normalDescriptorDecoded.convSize == 3
  doAssert normalDescriptorDecoded.activation == 2
  let projectedNormal = blaiNormalDescriptor(BlaiCpuInstLayer64(
    w: 4,
    h: 3,
    c: 2,
    outC: 8,
    fdata: 7,
    fweight: 8,
    fbias: 9,
    froute1: 10,
    froute2: 11,
    fout: 12,
    size: 5,
    activation: 1), c2 = 13)
  let projectedDecoded = decodeBlaiLayer(
    blaiEncodeNormalDescriptor(projectedNormal))
  let projectedNormalDecoded =
    decodeBlaiNormalDescriptorInstruction(
      blaiEncodeNormalDescriptor(projectedNormal))
  doAssert projectedDecoded.w == 4
  doAssert projectedDecoded.h == 3
  doAssert projectedDecoded.c == 2
  doAssert projectedDecoded.cn0 == 13
  doAssert projectedDecoded.outC == 8
  doAssert projectedDecoded.fdata == 7
  doAssert projectedDecoded.fout == 12
  doAssert projectedDecoded.size == 5
  doAssert projectedDecoded.activation == 1
  doAssert projectedNormalDecoded.shape.layerW == 4
  doAssert projectedNormalDecoded.shape.layerH == 3
  doAssert projectedNormalDecoded.shape.layerC1 == 2
  doAssert projectedNormalDecoded.shape.layerC2 == 13
  doAssert projectedNormalDecoded.shape.layerO == 8
  doAssert projectedNormalDecoded.fdata == 7
  doAssert projectedNormalDecoded.fweight == 8
  doAssert projectedNormalDecoded.fbias == 9
  doAssert projectedNormalDecoded.froute1 == 10
  doAssert projectedNormalDecoded.froute2 == 11
  doAssert projectedNormalDecoded.fout == 12
  doAssert projectedNormalDecoded.convSize == 5
  doAssert projectedNormalDecoded.activation == 1
  let encodedTflite = blaiEncodeTfliteDescriptor(BlaiNpuTfliteDescriptor(
    shape: BlaiNpuShapeDescriptor(layerW: 10, layerH: 9, layerC1: 8,
                                  layerC2: 7, layerO: 6),
    tfInput1Offset: 128,
    tfInput2Offset: 129,
    tfOutputOffset: 130,
    tfOutputShift: -1,
    convSize: 3,
    activation: 2))
  let tfliteDecoded = decodeBlaiLayer(encodedTflite)
  let tfliteDescriptorDecoded =
    decodeBlaiTfliteDescriptorInstruction(encodedTflite)
  doAssert tfliteDecoded.w == 10
  doAssert tfliteDecoded.h == 9
  doAssert tfliteDecoded.c == 8
  doAssert tfliteDecoded.cn0 == 7
  doAssert tfliteDecoded.outC == 6
  doAssert blaiBits(encodedTflite, 61, 8) == 128
  doAssert blaiBits(encodedTflite, 69, 8) == 129
  doAssert tfliteDecoded.tfOutputOffset == 130
  doAssert blaiSignedBits(encodedTflite, 85, 6) == -1
  doAssert tfliteDecoded.size == 3
  doAssert tfliteDecoded.activation == 2
  doAssert tfliteDescriptorDecoded.shape.layerW == 10
  doAssert tfliteDescriptorDecoded.shape.layerH == 9
  doAssert tfliteDescriptorDecoded.shape.layerC1 == 8
