# =============================================================================
# NPU integration operations
# =============================================================================
proc npuMmClkCpuWithClock*(
    mmClkCpu: uint32,
    enable: bool = true,
    source: NpuClockSource = npuClk160M,
    divider: uint32 = 0): uint32 =
  ## Return `MM_CLK_CPU` with recovered CNN clock fields updated.
  let cleared = mmClkCpu and not (CnnClkDivEnMask or CnnClkSelMask or CnnClkDivMask)
  var fields =
    ((source.uint32 and 0x03'u32) shl CnnClkSelShift) or
    ((divider and 0x07'u32) shl CnnClkDivShift)
  if enable:
    fields = fields or CnnClkDivEnMask
  cleared or fields

proc npuMmClkCpuWithClockEnable*(mmClkCpu: uint32, enable: bool): uint32 =
  ## Return `MM_CLK_CPU` with only the recovered CNN clock gate updated.
  let cleared = mmClkCpu and not CnnClkDivEnMask
  if enable:
    cleared or CnnClkDivEnMask
  else:
    cleared

proc npuMmClkCpuWithClockSource*(mmClkCpu: uint32,
                                 source: NpuClockSource): uint32 =
  ## Return `MM_CLK_CPU` with only the recovered CNN clock source updated.
  let cleared = mmClkCpu and not CnnClkSelMask
  cleared or ((source.uint32 and 0x03'u32) shl CnnClkSelShift)

proc npuClockStatusFromMmClkCpuInto*(mmClkCpu: uint32,
                                     outResult: var NpuClockStatusResult) =
  ## Decode the recovered CNN clock selector/divider register fields.
  outResult = default(NpuClockStatusResult)
  outResult.mmClkCpu = mmClkCpu
  outResult.enabled = (mmClkCpu and CnnClkDivEnMask) != 0
  outResult.sourceBits =
    (mmClkCpu and CnnClkSelMask) shr CnnClkSelShift
  outResult.sourceKnown =
    outResult.sourceBits <= ord(high(NpuClockSource)).uint32
  if outResult.sourceKnown:
    outResult.source = NpuClockSource(outResult.sourceBits)
  outResult.divider = (mmClkCpu and CnnClkDivMask) shr CnnClkDivShift

proc npuClockStatusFromMmClkCpu*(mmClkCpu: uint32): NpuClockStatusResult =
  ## Convenience wrapper for pure CNN clock state decoding.
  npuClockStatusFromMmClkCpuInto(mmClkCpu, result)

proc npuD0BootClockControlEvidenceInto*(
    mmClkCtrlCpu: uint32,
    outResult: var NpuD0BootClockControlEvidence) =
  ## Decode MM clock-control fields against Sipeed `mm_clk_config`.
  outResult = default(NpuD0BootClockControlEvidence)
  outResult.mmClkCtrlCpu = mmClkCtrlCpu
  outResult.xclkSel = (mmClkCtrlCpu and MmXclkSelMask) shr MmXclkSelShift
  outResult.bclk1xSel =
    (mmClkCtrlCpu and MmBclk1xSelMask) shr MmBclk1xSelShift
  outResult.cpuRootClkSel =
    (mmClkCtrlCpu and MmCpuRootClkSelMask) shr MmCpuRootClkSelShift
  outResult.cpuClkSel =
    (mmClkCtrlCpu and MmCpuClkSelMask) shr MmCpuClkSelShift
  outResult.uartClkSel =
    (mmClkCtrlCpu and MmUartClkSelMask) shr MmUartClkSelShift
  outResult.i2cClkSel =
    (mmClkCtrlCpu and MmI2cClkSelMask) shr MmI2cClkSelShift
  outResult.xclkMatchesD0Boot =
    outResult.xclkSel == SipeedD0BootXclkXtal
  outResult.bclkMatchesD0Boot =
    outResult.bclk1xSel == SipeedD0BootBclkMuxPll160M
  outResult.cpuRootMatchesD0Boot =
    outResult.cpuRootClkSel == SipeedD0BootCpuRootPll
  outResult.cpuClkMatchesD0Boot =
    outResult.cpuClkSel == SipeedD0BootCpuClkMuxPll400M
  outResult.uartMatchesD0Boot =
    outResult.uartClkSel == SipeedD0BootUartClkXclk
  outResult.i2cMatchesD0Boot =
    outResult.i2cClkSel == SipeedD0BootI2cClkXclk
  outResult.matchesD0BootClockConfig =
    outResult.xclkMatchesD0Boot and outResult.bclkMatchesD0Boot and
      outResult.cpuRootMatchesD0Boot and outResult.cpuClkMatchesD0Boot and
      outResult.uartMatchesD0Boot and outResult.i2cMatchesD0Boot
  outResult.possibleD0BootClockPrecondition =
    not outResult.matchesD0BootClockConfig
  outResult.valid = true

proc npuD0BootClockControlEvidence*(
    mmClkCtrlCpu: uint32): NpuD0BootClockControlEvidence =
  ## Convenience wrapper for Sipeed D0 boot MM clock-control classification.
  npuD0BootClockControlEvidenceInto(mmClkCtrlCpu, result)

proc npuD0BootClockControlEvidenceInto*(
    outResult: var NpuD0BootClockControlEvidence) =
  ## Read and decode live MM clock-control state.
  npuD0BootClockControlEvidenceInto(
    blaiLoadReg(mmClockCtrl()[].mmClkCtrlCpu), outResult)

proc npuD0BootClockControlEvidence*(): NpuD0BootClockControlEvidence =
  ## Convenience wrapper for live MM clock-control classification.
  npuD0BootClockControlEvidenceInto(result)

proc npuMmClockCtrlWithD0BootClockControl*(mmClkCtrlCpu: uint32): uint32 =
  ## Compose the MM clock-control fields written by Sipeed `mm_clk_config`.
  (mmClkCtrlCpu and not SipeedD0BootClockControlFieldMask) or
    (SipeedD0BootXclkXtal shl MmXclkSelShift) or
    (SipeedD0BootBclkMuxPll160M shl MmBclk1xSelShift) or
    (SipeedD0BootCpuRootPll shl MmCpuRootClkSelShift) or
    (SipeedD0BootCpuClkMuxPll400M shl MmCpuClkSelShift) or
    (SipeedD0BootUartClkXclk shl MmUartClkSelShift) or
    (SipeedD0BootI2cClkXclk shl MmI2cClkSelShift)

proc npuD0BootClockControlPlanInto*(
    mmClkCtrlCpu: uint32,
    outResult: var NpuD0BootClockControlPlan) =
  ## Build the Sipeed D0 boot MM clock-control RMW candidate.
  outResult = default(NpuD0BootClockControlPlan)
  outResult.initialMmClkCtrlCpu = mmClkCtrlCpu
  npuD0BootClockControlEvidenceInto(mmClkCtrlCpu, outResult.initialEvidence)
  outResult.encoded = npuMmClockCtrlWithD0BootClockControl(mmClkCtrlCpu)
  npuD0BootClockControlEvidenceInto(outResult.encoded, outResult.encodedEvidence)
  outResult.preservesUnrelatedBits =
    (outResult.initialMmClkCtrlCpu and not SipeedD0BootClockControlFieldMask) ==
      (outResult.encoded and not SipeedD0BootClockControlFieldMask)
  outResult.changesClockControl =
    outResult.initialMmClkCtrlCpu != outResult.encoded
  outResult.candidatePrecondition =
    outResult.initialEvidence.possibleD0BootClockPrecondition and
      outResult.encodedEvidence.matchesD0BootClockConfig
  outResult.valid =
    outResult.initialEvidence.valid and outResult.encodedEvidence.valid and
      outResult.preservesUnrelatedBits and
      outResult.encodedEvidence.matchesD0BootClockConfig

proc npuD0BootClockControlPlan*(
    mmClkCtrlCpu: uint32): NpuD0BootClockControlPlan =
  ## Convenience wrapper for Sipeed D0 boot MM clock-control RMW planning.
  npuD0BootClockControlPlanInto(mmClkCtrlCpu, result)

proc npuApplyD0BootClockControlPlan*(plan: NpuD0BootClockControlPlan) =
  ## Apply a validated Sipeed D0 boot MM clock-control candidate.
  if plan.valid:
    blaiStoreReg(mmClockCtrl()[].mmClkCtrlCpu, plan.encoded)

proc npuBlaiTzmidStatusFromRawInto*(tzmid, lock: uint32,
                                    outResult: var NpuBlaiTzmidStatus) =
  ## Decode the SDK `TZC_NSEC_TZC_MM_BMX_TZMID` BLAI master fields.
  outResult = default(NpuBlaiTzmidStatus)
  outResult.tzmid = tzmid
  outResult.lock = lock
  outResult.group =
    (tzmid and TzcNsecMmBmxBlaiTzmidMask) shr TzcNsecMmBmxBlaiTzmidBit
  outResult.selected = (tzmid and TzcNsecMmBmxBlaiTzmidSelMask) != 0
  outResult.groupKnown = outResult.selected
  outResult.locked = (lock and TzcNsecMmBmxBlaiTzmidLockMask) != 0
  outResult.readable = tzmid != 0xFFFF_FFFF'u32 and lock != 0xFFFF_FFFF'u32
  outResult.candidateCompletionPrecondition =
    outResult.readable and not outResult.selected
  outResult.valid = outResult.readable and outResult.group <= 1'u32

proc npuBlaiTzmidStatusFromRaw*(tzmid, lock: uint32): NpuBlaiTzmidStatus =
  ## Convenience wrapper for BLAI TZMID raw-register decoding.
  npuBlaiTzmidStatusFromRawInto(tzmid, lock, result)

proc npuBlaiTzmidPlanInto*(tzmid, lock, group: uint32,
                           lockAfterWrite: bool,
                           outResult: var NpuBlaiTzmidPlan) =
  ## Plan a BLAI TZMID group update while preserving other MM-domain masters.
  outResult = default(NpuBlaiTzmidPlan)
  outResult.initialTzmid = tzmid
  outResult.initialLock = lock
  outResult.group = group
  outResult.lock = lockAfterWrite
  outResult.groupFits = group <= 1'u32
  if not outResult.groupFits:
    return
  outResult.encodedTzmid =
    (tzmid and not TzcNsecMmBmxBlaiTzmidMask) or
      ((group shl TzcNsecMmBmxBlaiTzmidBit) and
        TzcNsecMmBmxBlaiTzmidMask) or
      TzcNsecMmBmxBlaiTzmidSelMask
  outResult.encodedLock = lock
  if lockAfterWrite:
    outResult.encodedLock = outResult.encodedLock or
      TzcNsecMmBmxBlaiTzmidLockMask
  npuBlaiTzmidStatusFromRawInto(
    outResult.encodedTzmid, outResult.encodedLock, outResult.status)
  outResult.preservesOtherMasters =
    (outResult.initialTzmid and
      not (TzcNsecMmBmxBlaiTzmidMask or TzcNsecMmBmxBlaiTzmidSelMask)) ==
    (outResult.encodedTzmid and
      not (TzcNsecMmBmxBlaiTzmidMask or TzcNsecMmBmxBlaiTzmidSelMask))
  outResult.valid =
    outResult.status.valid and outResult.status.groupKnown and
      outResult.status.group == group and
      outResult.status.locked ==
        ((outResult.encodedLock and TzcNsecMmBmxBlaiTzmidLockMask) != 0) and
      outResult.preservesOtherMasters

proc npuBlaiTzmidPlan*(tzmid, lock, group: uint32,
                       lockAfterWrite: bool = false): NpuBlaiTzmidPlan =
  ## Convenience wrapper for BLAI TZMID update planning.
  npuBlaiTzmidPlanInto(tzmid, lock, group, lockAfterWrite, result)

proc npuBlaiTzmidStatusInto*(outResult: var NpuBlaiTzmidStatus) =
  ## Read and decode the live BLAI TZMID state through the typed overlay.
  npuBlaiTzmidStatusFromRawInto(
    blaiLoadReg(tzcNsecMmBmxTzmid()[].mmBmxTzmid),
    blaiLoadReg(tzcNsecMmBmxTzmid()[].mmBmxTzmidLock),
    outResult)

proc npuBlaiTzmidStatus*(): NpuBlaiTzmidStatus =
  ## Convenience wrapper for live BLAI TZMID state.
  npuBlaiTzmidStatusInto(result)

proc npuClockConfigPlanInto*(
    mmClkCpu: uint32,
    enable: bool,
    source: NpuClockSource,
    divider: uint32,
    outResult: var NpuClockConfigPlan) =
  ## Plan an MM_CLK_CPU CNN clock source/divider/gate update.
  outResult = default(NpuClockConfigPlan)
  outResult.initialMmClkCpu = mmClkCpu
  outResult.enable = enable
  outResult.source = source
  outResult.divider = divider and 0x07'u32
  outResult.encoded = npuMmClkCpuWithClock(mmClkCpu, enable, source, divider)
  npuClockStatusFromMmClkCpuInto(outResult.encoded, outResult.status)
  outResult.valid =
    outResult.status.enabled == enable and
      outResult.status.sourceKnown and
      outResult.status.source == source and
      outResult.status.divider == outResult.divider

proc npuClockConfigPlan*(
    mmClkCpu: uint32,
    enable: bool = true,
    source: NpuClockSource = npuClk160M,
    divider: uint32 = 0): NpuClockConfigPlan =
  ## Convenience wrapper for CNN clock configuration planning.
  npuClockConfigPlanInto(mmClkCpu, enable, source, divider, result)

proc npuApplyClockConfigPlan*(plan: NpuClockConfigPlan) =
  ## Apply a planned CNN clock source/divider/gate update.
  doAssert plan.valid
  blaiStoreReg(cnnClockReset()[].mmClkCpu, plan.encoded)

proc npuInitClockSelectRegisterPlanInto*(
    mmClkCpu: uint32,
    outResult: var NpuInitClockSelectRegisterPlan) =
  ## Plan SDK `bl_npu_init` / `CLKRST_NPU_CLK_Sel(2)`.
  outResult = default(NpuInitClockSelectRegisterPlan)
  outResult.initialMmClkCpu = mmClkCpu
  outResult.source = npuClk320M
  outResult.encoded = npuMmClkCpuWithClockSource(mmClkCpu, outResult.source)
  npuClockStatusFromMmClkCpuInto(mmClkCpu, outResult.initialStatus)
  npuClockStatusFromMmClkCpuInto(outResult.encoded, outResult.status)
  outResult.preservesGate =
    outResult.status.enabled == outResult.initialStatus.enabled
  outResult.preservesDivider =
    outResult.status.divider == outResult.initialStatus.divider
  outResult.valid =
    outResult.status.sourceKnown and
      outResult.status.source == outResult.source and
      outResult.preservesGate and outResult.preservesDivider

proc npuInitClockSelectRegisterPlan*(
    mmClkCpu: uint32): NpuInitClockSelectRegisterPlan =
  ## Convenience wrapper for SDK `bl_npu_init` clock-source selection.
  npuInitClockSelectRegisterPlanInto(mmClkCpu, result)

proc npuApplyInitClockSelectRegisterPlan*(plan: NpuInitClockSelectRegisterPlan) =
  ## Apply SDK `bl_npu_init` clock-source selection.
  doAssert plan.valid
  blaiStoreReg(cnnClockReset()[].mmClkCpu, plan.encoded)

proc npuSetClock*(enable: bool = true,
                  source: NpuClockSource = npuClk160M,
                  divider: uint32 = 0) =
  ## Configure the SDK-documented CNN clock selector/divider.
  npuApplyClockConfigPlan(
    npuClockConfigPlan(
      blaiLoadReg(cnnClockReset()[].mmClkCpu), enable, source, divider))

proc npuClockGatePlanInto*(mmClkCpu: uint32,
                           enable: bool,
                           outResult: var NpuClockGatePlan) =
  ## Plan a CNN clock-gate-only update while preserving source/divider fields.
  outResult = default(NpuClockGatePlan)
  outResult.initialMmClkCpu = mmClkCpu
  outResult.enable = enable
  outResult.encoded = npuMmClkCpuWithClockEnable(mmClkCpu, enable)
  npuClockStatusFromMmClkCpuInto(mmClkCpu, outResult.initialStatus)
  npuClockStatusFromMmClkCpuInto(outResult.encoded, outResult.status)
  outResult.preservesSource =
    outResult.status.sourceBits == outResult.initialStatus.sourceBits
  outResult.preservesDivider =
    outResult.status.divider == outResult.initialStatus.divider
  outResult.valid =
    outResult.status.enabled == enable and
      outResult.preservesSource and outResult.preservesDivider

proc npuClockGatePlan*(mmClkCpu: uint32,
                       enable: bool): NpuClockGatePlan =
  ## Convenience wrapper for CNN clock-gate-only planning.
  npuClockGatePlanInto(mmClkCpu, enable, result)

proc npuApplyClockGatePlan*(plan: NpuClockGatePlan) =
  ## Apply a planned CNN clock-gate-only update.
  doAssert plan.valid
  blaiStoreReg(cnnClockReset()[].mmClkCpu, plan.encoded)

proc npuClockEnableRegisterPlanInto*(mmClkCpu: uint32,
                                     enable: bool,
                                     outResult: var NpuClockEnableRegisterPlan) =
  ## Plan recovered SDK `bl_npu_clk_en(en)` without changing source/divider.
  outResult = default(NpuClockEnableRegisterPlan)
  outResult.initialMmClkCpu = mmClkCpu
  outResult.enable = enable
  npuClockGatePlanInto(mmClkCpu, enable, outResult.gatePlan)
  outResult.preservesSource = outResult.gatePlan.preservesSource
  outResult.preservesDivider = outResult.gatePlan.preservesDivider
  outResult.valid =
    outResult.gatePlan.valid and
      outResult.gatePlan.initialMmClkCpu == mmClkCpu and
      outResult.gatePlan.enable == enable and
      outResult.preservesSource and outResult.preservesDivider

proc npuClockEnableRegisterPlan*(mmClkCpu: uint32,
                                 enable: bool): NpuClockEnableRegisterPlan =
  ## Convenience wrapper for recovered SDK `bl_npu_clk_en(en)` planning.
  npuClockEnableRegisterPlanInto(mmClkCpu, enable, result)

proc npuApplyClockEnableRegisterPlan*(plan: NpuClockEnableRegisterPlan) =
  ## Apply recovered SDK `bl_npu_clk_en(en)` register side effects.
  doAssert plan.valid
  npuApplyClockGatePlan(plan.gatePlan)

proc npuSetClockEnable*(enable: bool) =
  ## SDK `bl_npu_clk_en(en)`: toggle the gate, preserving source/divider.
  npuApplyClockEnableRegisterPlan(
    npuClockEnableRegisterPlan(blaiLoadReg(cnnClockReset()[].mmClkCpu), enable))

proc npuClockStatusInto*(outResult: var NpuClockStatusResult) =
  ## Read and decode the live CNN clock selector/divider state.
  npuClockStatusFromMmClkCpuInto(blaiLoadReg(cnnClockReset()[].mmClkCpu), outResult)

proc npuClockStatus*(): NpuClockStatusResult =
  ## Convenience wrapper for live CNN clock selector/divider state.
  npuClockStatusInto(result)

proc npuClockEnabled*(): bool =
  npuClockStatus().enabled

proc npuResetStatusFromSwResetCodecSubInto*(
    swResetCodecSub: uint32,
    outResult: var NpuResetStatusResult) =
  ## Decode the recovered CNN reset bit from `MM_GLB_SW_RESET_CODEC_SUB`.
  outResult = default(NpuResetStatusResult)
  outResult.swResetCodecSub = swResetCodecSub
  outResult.resetAsserted = (swResetCodecSub and CnnResetMask) != 0
  outResult.resetReleased = not outResult.resetAsserted

proc npuResetStatusFromSwResetCodecSub*(
    swResetCodecSub: uint32): NpuResetStatusResult =
  ## Convenience wrapper for pure CNN reset state decoding.
  npuResetStatusFromSwResetCodecSubInto(swResetCodecSub, result)

proc npuResetStatusInto*(outResult: var NpuResetStatusResult) =
  ## Read and decode live CNN reset state.
  npuResetStatusFromSwResetCodecSubInto(
    blaiLoadReg(cnnClockReset()[].swResetCodecSub), outResult)

proc npuResetStatus*(): NpuResetStatusResult =
  ## Convenience wrapper for live CNN reset state.
  npuResetStatusInto(result)

proc npuSwResetCodecSubWithCnnReset*(swResetCodecSub: uint32,
                                     asserted: bool): uint32 =
  ## Return `SW_RESET_CODEC_SUB` with the recovered CNN reset bit updated.
  let cleared = swResetCodecSub and not CnnResetMask
  if asserted:
    cleared or CnnResetMask
  else:
    cleared

proc npuResetLinePlanInto*(swResetCodecSub: uint32,
                           asserted: bool,
                           outResult: var NpuResetLinePlan) =
  ## Plan one CNN reset-line register update without touching hardware.
  outResult = default(NpuResetLinePlan)
  outResult.initialSwResetCodecSub = swResetCodecSub
  outResult.asserted = asserted
  outResult.encoded =
    npuSwResetCodecSubWithCnnReset(swResetCodecSub, asserted)
  npuResetStatusFromSwResetCodecSubInto(outResult.encoded, outResult.status)
  outResult.valid =
    outResult.status.resetAsserted == asserted and
      outResult.status.resetReleased == not asserted

proc npuResetLinePlan*(swResetCodecSub: uint32,
                       asserted: bool): NpuResetLinePlan =
  ## Convenience wrapper for CNN reset-line planning.
  npuResetLinePlanInto(swResetCodecSub, asserted, result)

proc npuApplyResetLinePlan*(plan: NpuResetLinePlan) =
  ## Apply one planned CNN reset-line update.
  doAssert plan.valid
  blaiStoreReg(cnnClockReset()[].swResetCodecSub, plan.encoded)

proc npuResetPulsePlanInto*(swResetCodecSub: uint32,
                            outResult: var NpuResetPulsePlan) =
  ## Plan the recovered assert/settle/release CNN reset pulse sequence.
  outResult = default(NpuResetPulsePlan)
  outResult.initialSwResetCodecSub = swResetCodecSub
  outResult.assertWrite =
    npuSwResetCodecSubWithCnnReset(swResetCodecSub, asserted = true)
  outResult.releaseWrite =
    npuSwResetCodecSubWithCnnReset(outResult.assertWrite, asserted = false)
  outResult.settleReadCount = NpuResetSettleReads
  npuResetStatusFromSwResetCodecSubInto(
    outResult.assertWrite, outResult.assertStatus)
  npuResetStatusFromSwResetCodecSubInto(
    outResult.releaseWrite, outResult.releaseStatus)
  outResult.clearsWrapperState = true
  outResult.valid =
    outResult.assertStatus.resetAsserted and
      not outResult.assertStatus.resetReleased and
      outResult.releaseStatus.resetReleased and
      not outResult.releaseStatus.resetAsserted and
      outResult.settleReadCount > 0'u32 and
      outResult.clearsWrapperState

proc npuResetPulsePlan*(swResetCodecSub: uint32): NpuResetPulsePlan =
  ## Convenience wrapper for CNN reset pulse planning.
  npuResetPulsePlanInto(swResetCodecSub, result)

proc npuResetSettleReadCountCursor*(settleReadCount: uint32):
    BlaiU32CountCursor =
  ## Resolve the recovered reset settle-read count before live MMIO polling.
  if settleReadCount == 0'u32:
    return
  blaiU32CountCursor(settleReadCount, high(int))

proc npuWrapperResetState*(): NpuWrapperResetState =
  ## Build caller-owned SDK wrapper state after reset.
  discard

proc npuWrapperResetApplyPlan*(plan: NpuResetPulsePlan):
    NpuWrapperResetApplyPlan =
  ## Recover wrapper-state clearing caused by a valid reset pulse.
  if not plan.valid or not plan.clearsWrapperState:
    return
  result.stateAfter = npuWrapperResetState()
  result.valid = true

proc npuWrapperResetState*(plan: NpuWrapperResetApplyPlan):
    NpuWrapperResetState =
  ## Project a valid reset apply plan into caller-owned wrapper state.
  doAssert plan.valid
  plan.stateAfter

proc npuApplyWrapperResetState*(state: NpuWrapperResetState) =
  ## Apply recovered reset wrapper state to SDK-compatible globals.
  npuHasStarted = state.started
  npuHasConfiguredInstructionStream = state.instructionStreamConfigured
  npuLastLaunchRegisterSnapshotCapturedFlag = state.launchSnapshotCaptured
  npuLastStartedRegisterSnapshotCapturedFlag = state.startedSnapshotCaptured

proc npuApplyResetPulsePlan*(plan: NpuResetPulsePlan) =
  ## Apply a planned CNN reset pulse and clear wrapper execution state.
  doAssert plan.valid
  blaiStoreReg(cnnClockReset()[].swResetCodecSub, plan.assertWrite)
  let settleReadCount = npuResetSettleReadCountCursor(plan.settleReadCount)
  doAssert settleReadCount.valid
  for _ in 0 ..< settleReadCount.count:
    discard blaiLoadReg(cnnClockReset()[].swResetCodecSub)
  blaiStoreReg(cnnClockReset()[].swResetCodecSub, plan.releaseWrite)
  let wrapperResetApply = npuWrapperResetApplyPlan(plan)
  doAssert wrapperResetApply.valid
  npuApplyWrapperResetState(npuWrapperResetState(wrapperResetApply))

proc npuHoldReset*() =
  ## Assert the CNN reset bit in MM_GLB_SW_RESET_CODEC_SUB.
  npuApplyResetLinePlan(
    npuResetLinePlan(blaiLoadReg(cnnClockReset()[].swResetCodecSub),
      asserted = true))

proc npuReleaseReset*() =
  ## Deassert the CNN reset bit in MM_GLB_SW_RESET_CODEC_SUB.
  npuApplyResetLinePlan(
    npuResetLinePlan(blaiLoadReg(cnnClockReset()[].swResetCodecSub),
      asserted = false))

proc npuReset*() =
  npuApplyResetPulsePlan(
    npuResetPulsePlan(blaiLoadReg(cnnClockReset()[].swResetCodecSub)))

proc npuVramCtrlWithBlaiSramRelease*(vramCtrl: uint32): uint32 =
  ## Return `MM_MISC_VRAM_CTRL` with BLAI SRAM released to the BLAI block.
  vramCtrl or BlaiSramRelMask

proc npuVramCtrlWithSysramSet*(vramCtrl: uint32): uint32 =
  ## Return `MM_MISC_VRAM_CTRL` with the SYSRAM_SET latch requested.
  vramCtrl or SysramSetMask

proc npuSramStatusFromVramCtrlInto*(vramCtrl: uint32,
                                    outResult: var NpuSramStatusResult) =
  ## Decode the recovered BLAI SRAM ownership bits from `MM_MISC_VRAM_CTRL`.
  outResult = default(NpuSramStatusResult)
  outResult.vramCtrl = vramCtrl
  outResult.sysramSetLatched = (vramCtrl and SysramSetMask) != 0
  outResult.l2SramRel =
    (vramCtrl and L2SramRelMask) shr L2SramRel
  outResult.pfSramRel =
    (vramCtrl and PfSramRelMask) shr PfSramRelShift
  outResult.apuSramRel =
    (vramCtrl and ApuSramRelMask) shr BlaiSramRel
  outResult.dsp2SramRel =
    (vramCtrl and Dsp2SramRelMask) shr Dsp2SramRel
  outResult.blaiSramReleased = (vramCtrl and BlaiSramRelMask) != 0
  outResult.blaiSramSelected = (vramCtrl and BlaiSramSelMask) != 0

proc npuSramStatusFromVramCtrl*(vramCtrl: uint32): NpuSramStatusResult =
  ## Convenience wrapper for pure SRAM ownership decoding.
  npuSramStatusFromVramCtrlInto(vramCtrl, result)

proc npuD0BootVramRouteEvidenceInto*(
    status: NpuSramStatusResult,
    outResult: var NpuD0BootVramRouteEvidence) =
  ## Classify MM_MISC_VRAM_CTRL against Sipeed's D0 boot SRAM routing.
  outResult = default(NpuD0BootVramRouteEvidence)
  outResult.vramCtrl = status.vramCtrl
  outResult.decoded = true
  outResult.l2MatchesD0Boot = status.l2SramRel == SipeedD0BootL2SramRel
  outResult.pfMatchesD0Boot = status.pfSramRel == SipeedD0BootPfSramRel
  outResult.apuMatchesD0Boot = status.apuSramRel == SipeedD0BootApuSramRel
  outResult.dsp2MatchesD0Boot = status.dsp2SramRel == SipeedD0BootDsp2SramRel
  outResult.matchesD0BootRoute =
    outResult.l2MatchesD0Boot and outResult.pfMatchesD0Boot and
      outResult.apuMatchesD0Boot and outResult.dsp2MatchesD0Boot
  outResult.localBlaiReleaseActive = status.blaiSramReleased
  outResult.routeDiffersFromLocalRelease =
    outResult.matchesD0BootRoute != outResult.localBlaiReleaseActive
  outResult.possibleD0BootRoutePrecondition =
    not outResult.matchesD0BootRoute
  outResult.rulesOutD0BootRoutePrecondition =
    outResult.matchesD0BootRoute
  outResult.valid = outResult.decoded

proc npuD0BootVramRouteEvidence*(
    status: NpuSramStatusResult): NpuD0BootVramRouteEvidence =
  ## Convenience wrapper for Sipeed D0 boot SRAM-route classification.
  npuD0BootVramRouteEvidenceInto(status, result)

proc npuVramCtrlWithD0BootSramRoute*(vramCtrl: uint32): uint32 =
  ## Return `MM_MISC_VRAM_CTRL` with Sipeed D0 boot SRAM route fields encoded.
  var encoded =
    vramCtrl and not (
      L2SramRelMask or PfSramRelMask or ApuSramRelMask or Dsp2SramRelMask)
  encoded = encoded or (SipeedD0BootL2SramRel shl L2SramRel)
  encoded = encoded or (SipeedD0BootPfSramRel shl PfSramRelShift)
  encoded = encoded or (SipeedD0BootApuSramRel shl BlaiSramRel)
  encoded = encoded or (SipeedD0BootDsp2SramRel shl Dsp2SramRel)
  encoded

proc npuD0BootVramRoutePlanInto*(vramCtrl: uint32,
                                 outResult: var NpuD0BootVramRoutePlan) =
  ## Plan Sipeed `l2_sram_vram_config` route write plus SYSRAM_SET latch.
  outResult = default(NpuD0BootVramRoutePlan)
  outResult.initialVramCtrl = vramCtrl
  outResult.routeWrite = npuVramCtrlWithD0BootSramRoute(vramCtrl)
  outResult.latchWrite = npuVramCtrlWithSysramSet(outResult.routeWrite)
  npuSramStatusFromVramCtrlInto(outResult.routeWrite, outResult.routeStatus)
  npuSramStatusFromVramCtrlInto(outResult.latchWrite, outResult.latchStatus)
  npuD0BootVramRouteEvidenceInto(outResult.latchStatus, outResult.routeEvidence)
  outResult.valid =
    outResult.routeEvidence.valid and outResult.routeEvidence.matchesD0BootRoute

proc npuD0BootVramRoutePlan*(vramCtrl: uint32): NpuD0BootVramRoutePlan =
  ## Convenience wrapper for Sipeed D0 boot SRAM-route planning.
  npuD0BootVramRoutePlanInto(vramCtrl, result)

proc npuApplyD0BootVramRoutePlan*(plan: NpuD0BootVramRoutePlan) =
  ## Apply the recovered D0 boot SRAM route through MM_MISC_VRAM_CTRL.
  doAssert plan.valid
  blaiStoreReg(mmMiscVram()[].vramCtrl, plan.routeWrite)
  blaiStoreReg(mmMiscVram()[].vramCtrl, plan.latchWrite)

proc npuSramReleasePlanInto*(vramCtrl: uint32,
                             outResult: var NpuSramReleasePlan) =
  ## Plan the recovered two-write SRAM release/SYSRAM_SET latch sequence.
  outResult = default(NpuSramReleasePlan)
  outResult.initialVramCtrl = vramCtrl
  outResult.releaseWrite = npuVramCtrlWithBlaiSramRelease(vramCtrl)
  outResult.latchWrite = npuVramCtrlWithSysramSet(outResult.releaseWrite)
  npuSramStatusFromVramCtrlInto(outResult.releaseWrite, outResult.releaseStatus)
  npuSramStatusFromVramCtrlInto(outResult.latchWrite, outResult.latchStatus)
  outResult.valid =
    outResult.releaseStatus.blaiSramReleased and
      not outResult.releaseStatus.sysramSetLatched and
      outResult.latchStatus.blaiSramReleased and
      outResult.latchStatus.sysramSetLatched

proc npuSramReleasePlan*(vramCtrl: uint32): NpuSramReleasePlan =
  ## Convenience wrapper for SRAM release planning.
  npuSramReleasePlanInto(vramCtrl, result)

proc npuApplySramReleasePlan*(plan: NpuSramReleasePlan) =
  ## Apply the recovered SRAM release/SYSRAM_SET latch sequence.
  doAssert plan.valid
  blaiStoreReg(mmMiscVram()[].vramCtrl, plan.releaseWrite)
  blaiStoreReg(mmMiscVram()[].vramCtrl, plan.latchWrite)

proc npuReleaseSram*() =
  ## Make the BLAI SRAM banks available and latch the SYSRAM_SET update.
  npuApplySramReleasePlan(npuSramReleasePlan(blaiLoadReg(mmMiscVram()[].vramCtrl)))

proc npuSramStatusInto*(outResult: var NpuSramStatusResult) =
  ## Read and decode live BLAI SRAM ownership state.
  npuSramStatusFromVramCtrlInto(blaiLoadReg(mmMiscVram()[].vramCtrl), outResult)

proc npuSramStatus*(): NpuSramStatusResult =
  ## Convenience wrapper for live BLAI SRAM ownership state.
  npuSramStatusInto(result)

proc npuSramReleased*(): bool =
  npuSramStatus().blaiSramReleased

proc npuRuntimeInitRegisterPlanInto*(
    mmClkCpu, swResetCodecSub, vramCtrl: uint32,
    outResult: var NpuRuntimeInitRegisterPlan) =
  ## Plan SDK clock-source selection plus local reset/SRAM ownership.
  outResult = default(NpuRuntimeInitRegisterPlan)
  outResult.initialMmClkCpu = mmClkCpu
  outResult.initialSwResetCodecSub = swResetCodecSub
  outResult.initialVramCtrl = vramCtrl
  npuInitClockSelectRegisterPlanInto(mmClkCpu, outResult.initClockSelect)
  npuClockConfigPlanInto(
    outResult.initClockSelect.encoded,
    enable = true, source = npuClk320M, divider = 0,
    outResult.clock)
  npuResetPulsePlanInto(swResetCodecSub, outResult.reset)
  npuSramReleasePlanInto(vramCtrl, outResult.sram)
  npuClockGatePlanInto(outResult.clock.encoded, enable = false,
    outResult.finalClockGate)
  outResult.runtimeOwnership = blaiNpuRuntimeOwnershipPlan()
  outResult.disablesClock =
    outResult.runtimeOwnership.initDisablesClock and
      not outResult.finalClockGate.status.enabled
  outResult.valid =
    outResult.initClockSelect.valid and
      outResult.initClockSelect.status.source == npuClk320M and
      outResult.clock.valid and outResult.clock.status.enabled and
      outResult.clock.status.source == npuClk320M and
      outResult.clock.status.divider == 0'u32 and
      outResult.reset.valid and outResult.sram.valid and
      outResult.finalClockGate.valid and
      outResult.finalClockGate.status.source == npuClk320M and
      outResult.finalClockGate.status.divider == 0'u32 and
      outResult.disablesClock

proc npuRuntimeInitRegisterPlan*(
    mmClkCpu, swResetCodecSub, vramCtrl: uint32): NpuRuntimeInitRegisterPlan =
  ## Convenience wrapper for recovered runtime-init register planning.
  npuRuntimeInitRegisterPlanInto(mmClkCpu, swResetCodecSub, vramCtrl, result)

proc npuApplyRuntimeInitRegisterPlan*(plan: NpuRuntimeInitRegisterPlan) =
  ## Apply SDK clock-source selection plus local reset/SRAM ownership.
  doAssert plan.valid
  npuApplyInitClockSelectRegisterPlan(plan.initClockSelect)
  npuApplyClockConfigPlan(plan.clock)
  npuApplyResetPulsePlan(plan.reset)
  npuApplySramReleasePlan(plan.sram)
  npuApplyClockGatePlan(plan.finalClockGate)

static:
  var staticRuntimeInitPlanInto: NpuRuntimeInitRegisterPlan
  npuRuntimeInitRegisterPlanInto(
    mmClkCpu = 0xA5A5_0001'u32,
    swResetCodecSub = 0x1234_0000'u32,
    vramCtrl = 0x55AA_0000'u32,
    staticRuntimeInitPlanInto)
  let staticRuntimeInitPlan =
    npuRuntimeInitRegisterPlan(
      0xA5A5_0001'u32, 0x1234_0000'u32, 0x55AA_0000'u32)
  doAssert staticRuntimeInitPlanInto == staticRuntimeInitPlan
  doAssert staticRuntimeInitPlan.valid
  doAssert staticRuntimeInitPlan.initClockSelect.valid
  doAssert staticRuntimeInitPlan.initClockSelect.status.source == npuClk320M
  doAssert staticRuntimeInitPlan.initClockSelect.preservesGate
  doAssert staticRuntimeInitPlan.initClockSelect.preservesDivider
  doAssert staticRuntimeInitPlan.clock.status.enabled
  doAssert staticRuntimeInitPlan.clock.status.source == npuClk320M
  doAssert staticRuntimeInitPlan.clock.status.divider == 0'u32
  doAssert staticRuntimeInitPlan.reset.releaseStatus.resetReleased
  doAssert staticRuntimeInitPlan.sram.latchStatus.blaiSramReleased
  doAssert staticRuntimeInitPlan.finalClockGate.valid
  doAssert not staticRuntimeInitPlan.finalClockGate.status.enabled
  doAssert staticRuntimeInitPlan.disablesClock

proc npuCodecQosCtrlWithCnnQos*(qosCtrl: uint32,
                                aw: bool = true,
                                ar: bool = true): uint32 =
  ## Return `CODEC_QOS_CTRL` with recovered CNN AW/AR QoS bits updated.
  let cleared = qosCtrl and not (CnnAwqosMask or CnnArqosMask)
  var value = 0'u32
  if aw:
    value = value or CnnAwqosMask
  if ar:
    value = value or CnnArqosMask
  cleared or value

proc npuCodecQosPlanInto*(qosCtrl: uint32,
                          aw: bool,
                          ar: bool,
                          outResult: var NpuCodecQosPlan) =
  ## Plan a CODEC QoS register update without touching hardware.
  outResult = default(NpuCodecQosPlan)
  outResult.initialQosCtrl = qosCtrl
  outResult.aw = aw
  outResult.ar = ar
  outResult.encoded = npuCodecQosCtrlWithCnnQos(qosCtrl, aw, ar)

proc npuCodecQosPlan*(qosCtrl: uint32,
                      aw: bool = true,
                      ar: bool = true): NpuCodecQosPlan =
  ## Convenience wrapper for CODEC QoS planning.
  npuCodecQosPlanInto(qosCtrl, aw, ar, result)

proc npuApplyCodecQosPlan*(plan: NpuCodecQosPlan) =
  ## Apply a planned CODEC QoS register update.
  blaiStoreReg(codecMisc()[].qosCtrl, plan.encoded)

proc npuCodecQosStatusFromRawInto*(
    qosCtrl: uint32,
    outResult: var NpuCodecQosStatus) =
  ## Decode recovered CNN AW/AR QoS bits from CODEC_MISC.
  outResult = default(NpuCodecQosStatus)
  outResult.qosCtrl = qosCtrl
  outResult.cnnAwqos = (qosCtrl and CnnAwqosMask) != 0'u32
  outResult.cnnArqos = (qosCtrl and CnnArqosMask) != 0'u32
  outResult.valid =
    (qosCtrl and (CnnAwqosMask or CnnArqosMask)) <=
      (CnnAwqosMask or CnnArqosMask)

proc npuCodecQosStatusFromRaw*(qosCtrl: uint32): NpuCodecQosStatus =
  ## Convenience wrapper for pure CODEC QoS decoding.
  npuCodecQosStatusFromRawInto(qosCtrl, result)

proc npuCodecQosStatusInto*(outResult: var NpuCodecQosStatus) =
  ## Read and decode live CNN QoS bits from CODEC_MISC.
  npuCodecQosStatusFromRawInto(blaiLoadReg(codecMisc()[].qosCtrl), outResult)

proc npuCodecQosStatus*(): NpuCodecQosStatus =
  ## Convenience wrapper for live CODEC QoS decoding.
  npuCodecQosStatusInto(result)

proc npuCodecQosReadbackEvidenceInto*(
    plan: NpuCodecQosPlan,
    status: NpuCodecQosStatus,
    outResult: var NpuCodecQosReadbackEvidence) =
  ## Compare a planned CNN QoS update with decoded CODEC_MISC readback.
  outResult = default(NpuCodecQosReadbackEvidence)
  outResult.plan = plan
  outResult.status = status
  outResult.awMatches = status.cnnAwqos == plan.aw
  outResult.arMatches = status.cnnArqos == plan.ar
  outResult.encodedMatches =
    (status.qosCtrl and (CnnAwqosMask or CnnArqosMask)) ==
      (plan.encoded and (CnnAwqosMask or CnnArqosMask))
  outResult.valid =
    status.valid and outResult.awMatches and outResult.arMatches and
      outResult.encodedMatches

proc npuCodecQosReadbackEvidence*(
    plan: NpuCodecQosPlan,
    status: NpuCodecQosStatus): NpuCodecQosReadbackEvidence =
  ## Convenience wrapper for CNN QoS readback evidence.
  npuCodecQosReadbackEvidenceInto(plan, status, result)

proc npuCodecBusStatusFromRawInto*(
    busCtrl, busThreshold: uint32,
    outResult: var NpuCodecBusStatus) =
  ## Decode recovered CODEC bus-control and BLAI threshold fields.
  outResult = default(NpuCodecBusStatus)
  outResult.busCtrl = busCtrl
  outResult.busThreshold = busThreshold
  outResult.pclkForceOnMask = busCtrl and CodecPclkForceOnMask
  outResult.pclkAnyForceOn = outResult.pclkForceOnMask != 0'u32
  outResult.blai2SysramThreshold =
    (busThreshold and CodecBlai2SysramThresholdMask) shr
      CodecBlai2SysramThresholdShift
  outResult.blai2ExtThreshold =
    (busThreshold and CodecBlai2ExtThresholdMask) shr
      CodecBlai2ExtThresholdShift
  outResult.blaiThresholdsKnown =
    outResult.blai2SysramThreshold <= CodecBlaiThresholdMask and
      outResult.blai2ExtThreshold <= CodecBlaiThresholdMask
  outResult.valid =
    outResult.pclkForceOnMask <= CodecPclkForceOnMask and
      outResult.blaiThresholdsKnown

proc npuCodecBusStatusFromRaw*(
    busCtrl, busThreshold: uint32): NpuCodecBusStatus =
  ## Convenience wrapper for pure CODEC bus-control decoding.
  npuCodecBusStatusFromRawInto(busCtrl, busThreshold, result)

proc npuCodecBusStatusInto*(outResult: var NpuCodecBusStatus) =
  ## Read and decode live CODEC bus-control state near the BLAI path.
  npuCodecBusStatusFromRawInto(
    blaiLoadReg(codecMisc()[].busCtrl),
    blaiLoadReg(codecMisc()[].busThreshold),
    outResult)

proc npuCodecBusStatus*(): NpuCodecBusStatus =
  ## Convenience wrapper for live CODEC bus-control decoding.
  npuCodecBusStatusInto(result)

proc npuBusLimiterValue*(count: uint32, mode: bool = true): uint32 =
  ## Encode one recovered BLAI bus limiter count/mode register.
  var value = count and BlaiLimiterCountMask
  if mode:
    value = value or BlaiLimiterModeMask
  value

proc npuBusLimiterPlanInto*(readCount, writeCount: uint32,
                            readMode: bool,
                            writeMode: bool,
                            outResult: var NpuBusLimiterPlan) =
  ## Plan BLAI read/write limiter register values without touching hardware.
  outResult = default(NpuBusLimiterPlan)
  outResult.read = npuBusLimiterValue(readCount, readMode)
  outResult.write = npuBusLimiterValue(writeCount, writeMode)

proc npuBusLimiterPlan*(readCount, writeCount: uint32,
                        readMode: bool = true,
                        writeMode: bool = true): NpuBusLimiterPlan =
  ## Convenience wrapper for BLAI read/write limiter planning.
  npuBusLimiterPlanInto(readCount, writeCount, readMode, writeMode, result)

proc npuBusLimiterReadbackEvidenceInto*(
    plan: NpuBusLimiterPlan,
    status: NpuBlaiCommandStatusResult,
    outResult: var NpuBusLimiterReadbackEvidence) =
  ## Compare a planned BLAI read/write limiter update with decoded readback.
  outResult = default(NpuBusLimiterReadbackEvidence)
  outResult.plan = plan
  outResult.status = status
  outResult.readMatches = status.codecLimiterRead == plan.read
  outResult.writeMatches = status.codecLimiterWrite == plan.write
  outResult.readCountMatches =
    status.readCommandCount == (plan.read and BlaiLimiterCountMask)
  outResult.writeCountMatches =
    status.writeCommandCount == (plan.write and BlaiLimiterCountMask)
  outResult.readModeMatches =
    status.readCommandMode == ((plan.read and BlaiLimiterModeMask) != 0'u32)
  outResult.writeModeMatches =
    status.writeCommandMode == ((plan.write and BlaiLimiterModeMask) != 0'u32)
  outResult.noMmCommandActivity =
    status.mmCommandCount == 0'u32 and not status.mmCommandMode
  outResult.valid =
    status.valid and outResult.readMatches and outResult.writeMatches and
      outResult.readCountMatches and outResult.writeCountMatches and
      outResult.readModeMatches and outResult.writeModeMatches and
      outResult.noMmCommandActivity

proc npuBusLimiterReadbackEvidence*(
    plan: NpuBusLimiterPlan,
    status: NpuBlaiCommandStatusResult): NpuBusLimiterReadbackEvidence =
  ## Convenience wrapper for pure BLAI limiter readback evidence.
  npuBusLimiterReadbackEvidenceInto(plan, status, result)

proc npuApplyBusLimiterPlan*(plan: NpuBusLimiterPlan) =
  ## Apply planned BLAI read/write limiter register values.
  blaiStoreReg(codecMisc()[].blaiLimiterRead, plan.read)
  blaiStoreReg(codecMisc()[].blaiLimiterWrite, plan.write)

proc npuSetCodecQos*(aw: bool = true, ar: bool = true) =
  let plan = npuCodecQosPlan(blaiLoadReg(codecMisc()[].qosCtrl), aw, ar)
  npuApplyCodecQosPlan(plan)

proc npuSetBusLimiters*(readCount, writeCount: uint32,
                        readMode: bool = true,
                        writeMode: bool = true) =
  let plan = npuBusLimiterPlan(readCount, writeCount, readMode, writeMode)
  npuApplyBusLimiterPlan(plan)

proc npuPlanInstructionStreamRegistersInto*(
    instAddr, weightAddr, biasAddr: uint32,
    outResult: var NpuInstructionStreamRegisterPlan) =
  ## Plan unconditional BLAI instruction/weight/bias register writes.
  outResult = default(NpuInstructionStreamRegisterPlan)
  outResult.instAddr = instAddr
  outResult.weightAddr = weightAddr
  outResult.biasAddr = biasAddr
  outResult.streamConfigured = instAddr != 0'u32

proc npuPlanInstructionStreamRegisters*(
    instAddr, weightAddr, biasAddr: uint32): NpuInstructionStreamRegisterPlan =
  ## Convenience wrapper for compatibility stream register planning.
  npuPlanInstructionStreamRegistersInto(instAddr, weightAddr, biasAddr, result)

proc blaiGeneratedNpuPayloadAddressPlanInto*(
    payload: BlaiGeneratedNpuPayloadCopyResult,
    instAddr, biasAddr, weightAddr: uint32,
    outResult: var BlaiGeneratedNpuPayloadAddressPlan) =
  ## Plan BLAI register addresses for staged generated NPU payload buffers.
  outResult = default(BlaiGeneratedNpuPayloadAddressPlan)
  outResult.payload = payload
  outResult.instAddr = instAddr
  outResult.biasAddr = biasAddr
  outResult.weightAddr = weightAddr
  outResult.instructionAddressPresent =
    payload.sections.instructionBytes == 0'u32 or instAddr != 0'u32
  outResult.biasAddressPresent =
    payload.sections.biasBytes == 0'u32 or biasAddr != 0'u32
  outResult.weightAddressPresent =
    payload.sections.weightBytes == 0'u32 or weightAddr != 0'u32
  npuPlanInstructionStreamRegistersInto(
    instAddr, weightAddr, biasAddr, outResult.registerPlan)
  if not payload.valid:
    outResult.firstBlock = blaiGeneratedNpuPayloadAddressInvalidPayload
  elif not outResult.instructionAddressPresent:
    outResult.firstBlock = blaiGeneratedNpuPayloadAddressMissingInstruction
  elif not outResult.biasAddressPresent:
    outResult.firstBlock = blaiGeneratedNpuPayloadAddressMissingBias
  elif not outResult.weightAddressPresent:
    outResult.firstBlock = blaiGeneratedNpuPayloadAddressMissingWeight
  elif not outResult.registerPlan.streamConfigured:
    outResult.firstBlock = blaiGeneratedNpuPayloadAddressNoInstructionStream
  else:
    outResult.firstBlock = blaiGeneratedNpuPayloadAddressNoBlock
  outResult.valid =
    payload.valid and outResult.instructionAddressPresent and
      outResult.biasAddressPresent and outResult.weightAddressPresent and
      outResult.registerPlan.streamConfigured

proc blaiGeneratedNpuPayloadAddressPlan*(
    payload: BlaiGeneratedNpuPayloadCopyResult,
    instAddr, biasAddr, weightAddr: uint32):
    BlaiGeneratedNpuPayloadAddressPlan =
  ## Convenience wrapper for generated NPU payload address planning.
  blaiGeneratedNpuPayloadAddressPlanInto(
    payload, instAddr, biasAddr, weightAddr, result)

proc blaiStageGeneratedNpuPayloadsInto*(
    blob: openArray[uint8],
    sectionPlan: BlaiGeneratedModelSectionPlan,
    instructions: var openArray[uint8],
    biases: var openArray[uint8],
    weights: var openArray[uint8],
    instAddr, biasAddr, weightAddr: uint32,
    outResult: var BlaiGeneratedNpuStagedPayloadResult) =
  ## Copy generated NPU payloads and bind staged buffers to BLAI registers.
  outResult = default(BlaiGeneratedNpuStagedPayloadResult)
  outResult.sectionPlan = sectionPlan
  blaiCopyGeneratedNpuPayloadsInto(
    blob, sectionPlan, instructions, biases, weights, outResult.payloadCopy)
  outResult.payloadCopyBlock = outResult.payloadCopy.firstBlock
  outResult.copied = outResult.payloadCopy.valid
  if not outResult.copied:
    outResult.firstBlock = blaiGeneratedNpuStagedPayloadCopy
    return
  blaiGeneratedNpuPayloadAddressPlanInto(
    outResult.payloadCopy, instAddr, biasAddr, weightAddr,
    outResult.addressPlan)
  outResult.addressBlock = outResult.addressPlan.firstBlock
  outResult.addressesValid = outResult.addressPlan.valid
  outResult.registerPlan = outResult.addressPlan.registerPlan
  outResult.readyToConfigure = outResult.copied and outResult.addressesValid
  if not outResult.addressesValid:
    outResult.firstBlock = blaiGeneratedNpuStagedPayloadAddress
    return
  outResult.firstBlock = blaiGeneratedNpuStagedPayloadNoBlock
  outResult.valid = outResult.readyToConfigure

proc blaiStageGeneratedNpuPayloads*(
    blob: openArray[uint8],
    sectionPlan: BlaiGeneratedModelSectionPlan,
    instructions: var openArray[uint8],
    biases: var openArray[uint8],
    weights: var openArray[uint8],
    instAddr, biasAddr, weightAddr: uint32):
    BlaiGeneratedNpuStagedPayloadResult =
  ## Convenience wrapper for generated NPU payload staging.
  blaiStageGeneratedNpuPayloadsInto(
    blob, sectionPlan, instructions, biases, weights,
    instAddr, biasAddr, weightAddr, result)

proc blaiPrepareGeneratedNpuPayloadsInto*(
    blob: openArray[uint8],
    instructions: var openArray[uint8],
    biases: var openArray[uint8],
    weights: var openArray[uint8],
    instAddr, biasAddr, weightAddr: uint32,
    outResult: var BlaiGeneratedNpuPreparedPayloadResult) =
  ## Recover and stage generated NPU payloads without touching hardware.
  outResult = default(BlaiGeneratedNpuPreparedPayloadResult)
  blaiGeneratedModelPackagePreflightInto(
    blob, blaiGeneratedModelHeaderContract(), outResult.packagePreflight)
  outResult.sectionPlan = outResult.packagePreflight.sectionPlan
  outResult.sectionPlanValid = outResult.packagePreflight.sectionPlanValid
  outResult.headerValid = outResult.packagePreflight.headerValid
  outResult.loadPlanValid = outResult.packagePreflight.loadPlanValid
  outResult.packageFirstBlock = outResult.packagePreflight.firstBlock
  if not outResult.packagePreflight.valid:
    outResult.firstBlock = blaiGeneratedNpuPreparedPayloadPackage
    return
  blaiStageGeneratedNpuPayloadsInto(
    blob, outResult.sectionPlan, instructions, biases, weights,
    instAddr, biasAddr, weightAddr, outResult.staged)
  outResult.stagedFirstBlock = outResult.staged.firstBlock
  outResult.payloadCopyBlock = outResult.staged.payloadCopyBlock
  outResult.addressBlock = outResult.staged.addressBlock
  outResult.payloadStaged = outResult.staged.valid
  outResult.registerPlan = outResult.staged.registerPlan
  outResult.readyToConfigure = outResult.staged.readyToConfigure
  if not outResult.payloadStaged:
    outResult.firstBlock = blaiGeneratedNpuPreparedPayloadStage
    return
  outResult.firstBlock = blaiGeneratedNpuPreparedPayloadNoBlock
  outResult.valid =
    outResult.sectionPlanValid and outResult.payloadStaged and
      outResult.readyToConfigure

proc blaiPrepareGeneratedNpuPayloads*(
    blob: openArray[uint8],
    instructions: var openArray[uint8],
    biases: var openArray[uint8],
    weights: var openArray[uint8],
    instAddr, biasAddr, weightAddr: uint32):
    BlaiGeneratedNpuPreparedPayloadResult =
  ## Convenience wrapper for pure generated NPU payload preparation.
  blaiPrepareGeneratedNpuPayloadsInto(
    blob, instructions, biases, weights,
    instAddr, biasAddr, weightAddr, result)

proc npuInstructionStreamConfiguredApplyPlan*(
    plan: NpuInstructionStreamRegisterPlan):
    NpuInstructionStreamConfiguredApplyPlan
proc npuInstructionStreamConfiguredState*(
    plan: NpuInstructionStreamConfiguredApplyPlan):
    NpuInstructionStreamConfiguredState

proc blaiGeneratedNpuConfigurePlanInto*(
    prepared: BlaiGeneratedNpuPreparedPayloadResult,
    outResult: var BlaiGeneratedNpuConfigurePlan) =
  ## Plan generated NPU register configuration without touching hardware.
  outResult = default(BlaiGeneratedNpuConfigurePlan)
  outResult.prepared = prepared
  if not prepared.readyToConfigure:
    outResult.firstBlock = blaiGeneratedNpuConfigurePrepared
    return
  outResult.registerPlan = prepared.registerPlan
  outResult.configuredApply =
    npuInstructionStreamConfiguredApplyPlan(outResult.registerPlan)
  if not outResult.configuredApply.valid:
    outResult.firstBlock = blaiGeneratedNpuConfigureConfiguredApply
    return
  outResult.configuredState =
    npuInstructionStreamConfiguredState(outResult.configuredApply)
  outResult.wouldApply = outResult.configuredState.configured
  if not outResult.wouldApply:
    outResult.firstBlock = blaiGeneratedNpuConfigureConfiguredState
    return
  outResult.firstBlock = blaiGeneratedNpuConfigureNoBlock
  outResult.valid = outResult.wouldApply

proc blaiGeneratedNpuConfigurePlan*(
    prepared: BlaiGeneratedNpuPreparedPayloadResult):
    BlaiGeneratedNpuConfigurePlan =
  ## Convenience wrapper for pure generated NPU configure planning.
  blaiGeneratedNpuConfigurePlanInto(prepared, result)

proc npuInstructionStreamConfiguredState*(configured: bool):
    NpuInstructionStreamConfiguredState =
  ## Build caller-owned wrapper stream-configured state.
  result.configured = configured

proc npuInstructionStreamConfiguredApplyPlan*(configured: bool):
    NpuInstructionStreamConfiguredApplyPlan =
  ## Recover checked wrapper stream-configured state before global mutation.
  result.stateAfter = npuInstructionStreamConfiguredState(configured)
  result.valid = true

proc npuInstructionStreamConfiguredApplyPlan*(
    plan: NpuInstructionStreamRegisterPlan):
    NpuInstructionStreamConfiguredApplyPlan =
  ## Project unconditional stream-register planning into wrapper state.
  npuInstructionStreamConfiguredApplyPlan(plan.streamConfigured)

proc npuInstructionStreamConfiguredApplyPlan*(
    plan: NpuLayerBufferRegisterPlan):
    NpuInstructionStreamConfiguredApplyPlan =
  ## Project optional layer-buffer planning into wrapper state.
  if not plan.marksStreamConfigured:
    return
  npuInstructionStreamConfiguredApplyPlan(true)

proc npuInstructionStreamConfiguredState*(
    plan: NpuInstructionStreamConfiguredApplyPlan):
    NpuInstructionStreamConfiguredState =
  ## Project a valid stream-configured apply plan into caller-owned state.
  doAssert plan.valid
  plan.stateAfter

proc npuApplyInstructionStreamConfiguredState*(
    state: NpuInstructionStreamConfiguredState) =
  ## Apply recovered stream-configured state to the SDK-compatible global flag.
  npuHasConfiguredInstructionStream = state.configured

proc npuApplyInstructionStreamRegisterPlan*(
    plan: NpuInstructionStreamRegisterPlan) =
  ## Apply unconditional BLAI instruction/weight/bias register writes.
  blaiStoreReg(blaiRegs()[].instAddr, plan.instAddr)
  blaiStoreReg(blaiRegs()[].weightAddr, plan.weightAddr)
  blaiStoreReg(blaiRegs()[].biasAddr, plan.biasAddr)
  let configuredApply = npuInstructionStreamConfiguredApplyPlan(plan)
  doAssert configuredApply.valid
  npuApplyInstructionStreamConfiguredState(
    npuInstructionStreamConfiguredState(configuredApply))

proc blaiConfigureStagedGeneratedNpuPayloadInto*(
    staged: BlaiGeneratedNpuStagedPayloadResult,
    outResult: var BlaiGeneratedNpuConfigureResult) =
  ## Apply BLAI instruction/weight/bias registers for a staged generated model.
  outResult = default(BlaiGeneratedNpuConfigureResult)
  outResult.staged = staged
  if not staged.readyToConfigure:
    outResult.firstBlock = blaiGeneratedNpuConfigurePrepared
    return
  outResult.registerPlan = staged.registerPlan
  outResult.configuredApply =
    npuInstructionStreamConfiguredApplyPlan(outResult.registerPlan)
  if not outResult.configuredApply.valid:
    outResult.firstBlock = blaiGeneratedNpuConfigureConfiguredApply
    return
  outResult.configuredState =
    npuInstructionStreamConfiguredState(outResult.configuredApply)
  if not outResult.configuredState.configured:
    outResult.firstBlock = blaiGeneratedNpuConfigureConfiguredState
    return
  npuApplyInstructionStreamRegisterPlan(outResult.registerPlan)
  outResult.applied = true
  outResult.firstBlock = blaiGeneratedNpuConfigureNoBlock
  outResult.valid = outResult.configuredState.configured

proc blaiConfigureStagedGeneratedNpuPayload*(
    staged: BlaiGeneratedNpuStagedPayloadResult):
    BlaiGeneratedNpuConfigureResult =
  ## Convenience wrapper for staged generated NPU register configuration.
  blaiConfigureStagedGeneratedNpuPayloadInto(staged, result)

proc npuConfigureInstructionStream*(instAddr, weightAddr, biasAddr: uint32) =
  ## Configure the recovered SDK BLAI instruction, weight, and bias pointers.
  ##
  ## This does not start execution. The instruction stream format is still under
  ## recovery and must be produced by a validated encoder before use.
  npuApplyInstructionStreamRegisterPlan(
    npuPlanInstructionStreamRegisters(instAddr, weightAddr, biasAddr))

proc npuPlanLayerBufferRegistersInto*(buffers: NpuLayerBuffers,
                                      outResult: var NpuLayerBufferRegisterPlan) =
  ## Plan SDK optional BLAI instruction/weight/bias register writes.
  outResult = default(NpuLayerBufferRegisterPlan)
  outResult.buffers = buffers
  outResult.writeInstAddr = buffers.instAddr != 0'u32
  outResult.writeWeightAddr = buffers.weightAddr != 0'u32
  outResult.writeBiasAddr = buffers.biasAddr != 0'u32
  outResult.anyWrite =
    outResult.writeInstAddr or outResult.writeWeightAddr or
      outResult.writeBiasAddr
  outResult.marksStreamConfigured = outResult.writeInstAddr

proc npuPlanLayerBufferRegisters*(
    buffers: NpuLayerBuffers): NpuLayerBufferRegisterPlan =
  ## Convenience wrapper for SDK optional layer-buffer register planning.
  npuPlanLayerBufferRegistersInto(buffers, result)

proc npuApplyLayerBufferRegisterPlan*(plan: NpuLayerBufferRegisterPlan) =
  ## Apply optional BLAI instruction/weight/bias register writes.
  if plan.writeInstAddr:
    blaiStoreReg(blaiRegs()[].instAddr, plan.buffers.instAddr)
    let configuredApply = npuInstructionStreamConfiguredApplyPlan(plan)
    doAssert configuredApply.valid
    npuApplyInstructionStreamConfiguredState(
      npuInstructionStreamConfiguredState(configuredApply))
  if plan.writeWeightAddr:
    blaiStoreReg(blaiRegs()[].weightAddr, plan.buffers.weightAddr)
  if plan.writeBiasAddr:
    blaiStoreReg(blaiRegs()[].biasAddr, plan.buffers.biasAddr)

proc npuConfigureLayerBuffers*(buffers: NpuLayerBuffers) =
  ## Configure any nonzero BLAI instruction, weight, and bias pointers.
  ##
  ## This mirrors the SDK `bl_npu_layer_setup` ABI, whose null pointer arguments
  ## intentionally preserve the previous hardware register values.
  npuApplyLayerBufferRegisterPlan(npuPlanLayerBufferRegisters(buffers))

proc npuPlanInputBufferRegistersInto*(bufferAddr, segmentCount: uint32,
                                      outResult: var NpuInputBufferRegisterPlan) =
  ## Plan BLAI DATA base and image patch-size register writes.
  outResult = default(NpuInputBufferRegisterPlan)
  outResult.inputBufferAddr = bufferAddr
  outResult.segmentCount = segmentCount
  outResult.writeInputBuffer = true

proc npuPlanInputBufferRegisters*(
    bufferAddr, segmentCount: uint32): NpuInputBufferRegisterPlan =
  ## Convenience wrapper for input DATA register planning.
  npuPlanInputBufferRegistersInto(bufferAddr, segmentCount, result)

proc npuApplyInputBufferRegisterPlan*(plan: NpuInputBufferRegisterPlan) =
  ## Apply BLAI DATA base and image patch-size register writes.
  if plan.writeInputBuffer:
    blaiStoreReg(blaiRegs()[].imageAddr, plan.inputBufferAddr)
    blaiStoreReg(blaiRegs()[].imageSeg, plan.segmentCount)

proc npuSetInputBuffer*(bufferAddr, segmentCount: uint32) =
  ## Configure BLAI input buffer address and image patch size.
  npuApplyInputBufferRegisterPlan(
    npuPlanInputBufferRegisters(bufferAddr, segmentCount))

proc npuPlanLaunchRegistersInto*(
    buffers: NpuLayerBuffers,
    inputBufferAddr, segmentCount: uint32,
    outResult: var NpuLaunchRegisterPlan) =
  ## Plan SDK launch-register writes without touching hardware.
  outResult = default(NpuLaunchRegisterPlan)
  outResult.buffers = buffers
  outResult.inputBufferAddr = inputBufferAddr
  outResult.segmentCount = segmentCount
  outResult.writeInstAddr = buffers.instAddr != 0'u32
  outResult.writeWeightAddr = buffers.weightAddr != 0'u32
  outResult.writeBiasAddr = buffers.biasAddr != 0'u32
  outResult.writeInputBuffer = true
  outResult.anyLayerBufferWrite =
    outResult.writeInstAddr or outResult.writeWeightAddr or
      outResult.writeBiasAddr

proc npuPlanLaunchRegisters*(
    buffers: NpuLayerBuffers,
    inputBufferAddr, segmentCount: uint32): NpuLaunchRegisterPlan =
  ## Convenience wrapper for SDK launch-register write planning.
  npuPlanLaunchRegistersInto(
    buffers, inputBufferAddr, segmentCount, result)

proc npuApplyLaunchRegisterPlan*(plan: NpuLaunchRegisterPlan) =
  ## Apply a recovered SDK launch-register write plan.
  npuApplyLayerBufferRegisterPlan(npuPlanLayerBufferRegisters(plan.buffers))
  if plan.writeInputBuffer:
    npuApplyInputBufferRegisterPlan(
      npuPlanInputBufferRegisters(plan.inputBufferAddr, plan.segmentCount))

proc npuPlanLayerConfig*(buffers: NpuLayerBuffers,
                         inputBufferAddr, patchSize: uint32,
                         firstLayer: bool): NpuLayerConfig =
  ## Plan SDK `blai_npu_layer_config` without touching hardware.
  NpuLayerConfig(
    buffers: buffers,
    inputBufferAddr: inputBufferAddr,
    patchSize: patchSize,
    firstLayer: firstLayer,
    resetUnsignedInput: not firstLayer)

proc npuPlanLayerConfigRegistersInto*(config: NpuLayerConfig,
                                      outResult: var NpuLayerConfigRegisterPlan) =
  ## Plan register-side effects for SDK `blai_npu_layer_config`.
  outResult = default(NpuLayerConfigRegisterPlan)
  outResult.config = config
  npuPlanLaunchRegistersInto(
    config.buffers, config.inputBufferAddr, config.patchSize,
    outResult.launch)
  outResult.resetUnsignedInput = config.resetUnsignedInput
  outResult.firstLayerPreservesUnsignedInput =
    config.firstLayer and not config.resetUnsignedInput
  outResult.valid =
    outResult.launch.writeInputBuffer and
      outResult.resetUnsignedInput == not config.firstLayer and
      (outResult.resetUnsignedInput or outResult.firstLayerPreservesUnsignedInput)

proc npuPlanLayerConfigRegisters*(
    config: NpuLayerConfig): NpuLayerConfigRegisterPlan =
  ## Convenience wrapper for layer-config register planning.
  npuPlanLayerConfigRegistersInto(config, result)

proc npuLayerConfigPatchSizeRegisterEvidenceInto*(
    plan: NpuLayerConfigRegisterPlan,
    outResult: var NpuLayerConfigPatchSizeRegisterEvidence) =
  ## Prove SDK `patch_size` is the value written to `APU_DM1_ADDR`.
  outResult = default(NpuLayerConfigPatchSizeRegisterEvidence)
  outResult.planValid = plan.valid
  outResult.configPatchSize = plan.config.patchSize
  outResult.launchImageSeg = plan.launch.segmentCount
  outResult.sdkPatchSizeWritten =
    plan.launch.writeInputBuffer and
      outResult.launchImageSeg == outResult.configPatchSize
  outResult.imageSegNamesPatchSize = outResult.sdkPatchSizeWritten
  outResult.valid =
    outResult.planValid and outResult.sdkPatchSizeWritten and
      outResult.imageSegNamesPatchSize

proc npuLayerConfigPatchSizeRegisterEvidence*(
    plan: NpuLayerConfigRegisterPlan): NpuLayerConfigPatchSizeRegisterEvidence =
  ## Convenience wrapper for SDK patch-size register evidence.
  npuLayerConfigPatchSizeRegisterEvidenceInto(plan, result)

proc npuResetUnsignedInput*()
proc npuConfigureNetParams*(params: NpuNetParams)
proc npuPlanNetParamRegistersInto*(
    params: NpuNetParams,
    generalCfg, intCfg, tfCfg0: uint32,
    outResult: var NpuNetParamRegisterPlan)
proc npuApplyNetParamRegisterPlan*(plan: NpuNetParamRegisterPlan)

proc npuApplyLayerConfig*(config: NpuLayerConfig) =
  ## Apply SDK `blai_npu_layer_config`: optional layer buffers, input buffer,
  ## then clear unsigned-input mode for non-first layers.
  let plan = npuPlanLayerConfigRegisters(config)
  doAssert plan.valid
  npuApplyLaunchRegisterPlan(plan.launch)
  if plan.resetUnsignedInput:
    npuResetUnsignedInput()

proc npuPlanInitConfig*(buffers: NpuLayerBuffers,
                        inputBufferAddr, patchSize: uint32,
                        netParams: NpuNetParams): NpuInitConfig =
  ## Plan SDK `blai_npu_initCfg` without touching hardware.
  ##
  ## The recovered SDK also registers/enables `CNN_IRQn` at priority 7,1. This
  ## proc records that request as data; `npuApplyInitConfigRegisters` only
  ## performs the validated register writes.
  NpuInitConfig(
    buffers: buffers,
    inputBufferAddr: inputBufferAddr,
    patchSize: patchSize,
    netParams: netParams,
    interrupt: NpuInterruptConfig(
      irq: NpuCnnIrq,
      preemptPriority: NpuCnnIrqPreemptPriority,
      subPriority: NpuCnnIrqSubPriority,
      enable: true))

proc npuPlanInitConfigRegistersInto*(config: NpuInitConfig,
                                     generalCfg, intCfg, tfCfg0: uint32,
                                     outResult: var NpuInitConfigRegisterPlan) =
  ## Plan the register-programming subset of SDK `blai_npu_initCfg`.
  outResult = default(NpuInitConfigRegisterPlan)
  outResult.config = config
  npuPlanLaunchRegistersInto(
    config.buffers, config.inputBufferAddr, config.patchSize,
    outResult.launch)
  npuPlanNetParamRegistersInto(
    config.netParams, generalCfg, intCfg, tfCfg0, outResult.netParams)
  outResult.interruptRequested = config.interrupt.enable
  outResult.interruptDeferred = outResult.interruptRequested
  outResult.valid =
    outResult.launch.writeInputBuffer and outResult.netParams.valid and
      config.interrupt.irq == NpuCnnIrq and
      config.interrupt.preemptPriority == NpuCnnIrqPreemptPriority and
      config.interrupt.subPriority == NpuCnnIrqSubPriority and
      outResult.interruptDeferred

proc npuPlanInitConfigRegisters*(
    config: NpuInitConfig,
    generalCfg, intCfg, tfCfg0: uint32): NpuInitConfigRegisterPlan =
  ## Convenience wrapper for init register-programming planning.
  npuPlanInitConfigRegistersInto(config, generalCfg, intCfg, tfCfg0, result)

proc npuGlbMcuInterruptSourceCursor*(irq: uint32):
    NpuGlbMcuInterruptSourceCursor =
  ## Resolve a CLIC IRQ number to the SDK GLB MCU source offset space.
  result.irq = irq
  result.externalLine = irq >= 16'u32
  if result.externalLine:
    result.sourceOffset = irq - 16'u32
  result.withinM0ClicRange = irq < NpuM0ClicMaxIrq
  result.withinGlbMcuSourceRange =
    result.externalLine and result.sourceOffset < NpuGlbMcuIntSourceCount
  result.valid = result.withinM0ClicRange and result.withinGlbMcuSourceRange

proc npuInterruptLineOwnershipInto*(
    interrupt: NpuInterruptConfig,
    outResult: var NpuInterruptLineOwnership) =
  ## Explain which core-local interrupt line the recovered CNN IRQ number names.
  outResult = default(NpuInterruptLineOwnership)
  let sourceCursor = npuGlbMcuInterruptSourceCursor(interrupt.irq)
  outResult.irq = sourceCursor.irq
  outResult.sourceOffset = sourceCursor.sourceOffset
  outResult.withinM0ClicRange = sourceCursor.withinM0ClicRange
  outResult.withinGlbMcuSourceRange = sourceCursor.withinGlbMcuSourceRange
  outResult.sdkCnnLineKnown = outResult.sourceOffset == NpuCnnIrqOffset
  outResult.matchesD0ApuLine = interrupt.irq == NpuD0ApuIrq
  outResult.matchesE907ApuLine = interrupt.irq == NpuE907ApuIrq
  outResult.m0ApuLineExcluded =
    outResult.sdkCnnLineKnown and NpuM0ApuHeaderExcluded
  outResult.glbMcuSourceAliasesI2c1 =
    outResult.sourceOffset == NpuGlbMcuI2c1Source
  outResult.aliasesM0I2c1Line = outResult.glbMcuSourceAliasesI2c1
  outResult.m0LocalCnnSourceKnown = false
  outResult.d0ApuBindingCandidate =
    outResult.matchesD0ApuLine and outResult.matchesE907ApuLine and
      outResult.withinGlbMcuSourceRange
  outResult.m0BindingSafe =
    outResult.m0LocalCnnSourceKnown and not outResult.aliasesM0I2c1Line
  outResult.bindingBlocked =
    outResult.d0ApuBindingCandidate and outResult.m0ApuLineExcluded and
      outResult.glbMcuSourceAliasesI2c1 and not outResult.m0BindingSafe

proc npuInterruptLineOwnership*(
    interrupt: NpuInterruptConfig): NpuInterruptLineOwnership =
  ## Convenience wrapper for recovered CNN IRQ line ownership.
  npuInterruptLineOwnershipInto(interrupt, result)

proc npuInterruptGlbRouteMapInto*(
    interrupt: NpuInterruptConfig,
    outResult: var NpuInterruptGlbRouteMap) =
  ## Classify the recovered SDK CNN IRQ request against the GLB route maps.
  outResult = default(NpuInterruptGlbRouteMap)
  let sourceCursor = npuGlbMcuInterruptSourceCursor(interrupt.irq)
  outResult.irq = sourceCursor.irq
  outResult.sourceOffset = sourceCursor.sourceOffset
  outResult.sdkCnnOffset = outResult.sourceOffset == NpuCnnIrqOffset
  outResult.mcuSourceInRange = sourceCursor.withinGlbMcuSourceRange
  outResult.mcuMmAggregateSource = NpuGlbMcuMmIrqAllSource
  outResult.mcuMmAggregateAvailable =
    NpuGlbMcuMmIrqAllSource < NpuGlbMcuIntSourceCount
  outResult.mcuSourceAliasesI2c1 =
    outResult.sourceOffset == NpuGlbMcuI2c1Source
  outResult.dspSourceIsReserved39 =
    outResult.sourceOffset == NpuGlbDspRsv39Source
  outResult.directM0CnnSourceKnown = false
  outResult.requiresMmAggregateDemux =
    outResult.sdkCnnOffset and outResult.mcuMmAggregateAvailable and
      outResult.mcuSourceAliasesI2c1 and not outResult.directM0CnnSourceKnown
  outResult.m0DirectBindingUnsafe =
    outResult.sdkCnnOffset and outResult.mcuSourceAliasesI2c1 and
      outResult.dspSourceIsReserved39 and not outResult.directM0CnnSourceKnown
  outResult.pollingRequired =
    outResult.requiresMmAggregateDemux and outResult.m0DirectBindingUnsafe
  outResult.valid =
    outResult.sdkCnnOffset and outResult.mcuSourceInRange and
      outResult.mcuMmAggregateAvailable and outResult.pollingRequired

proc npuInterruptGlbRouteMap*(
    interrupt: NpuInterruptConfig): NpuInterruptGlbRouteMap =
  ## Convenience wrapper for recovered GLB CNN IRQ route classification.
  npuInterruptGlbRouteMapInto(interrupt, result)

proc npuMmAggregateRawIndexCursor*(index: uint32):
    NpuMmAggregateRawIndexCursor =
  ## Resolve one raw MM aggregate bitmap index to its typed bank/bit cursor.
  result.index = index
  result.inRange = index < NpuMmAggregateBankCount * NpuMmAggregateRawBitmapWidth
  if result.inRange:
    result.bank = index div NpuMmAggregateRawBitmapWidth
    result.bit = index mod NpuMmAggregateRawBitmapWidth
    result.mask = 1'u32 shl result.bit
  result.valid = result.inRange and result.mask != 0'u32

proc npuMmAggregateRawIndexPlanInto*(index: uint32,
                                     outResult: var NpuMmAggregateRawIndexPlan) =
  ## Plan the SDK raw MM aggregate bitmap bank/bit address for one index.
  outResult = default(NpuMmAggregateRawIndexPlan)
  let cursor = npuMmAggregateRawIndexCursor(index)
  outResult.index = cursor.index
  outResult.inRange = cursor.inRange
  outResult.bank = cursor.bank
  outResult.bit = cursor.bit
  outResult.mask = cursor.mask
  outResult.usesBank0 = outResult.inRange and outResult.bank == 0'u32
  outResult.usesBank1 = outResult.inRange and outResult.bank == 1'u32
  outResult.valid =
    cursor.valid and (outResult.usesBank0 or outResult.usesBank1)

proc npuMmAggregateRawIndexPlan*(index: uint32): NpuMmAggregateRawIndexPlan =
  ## Convenience wrapper for raw MM aggregate bitmap addressing.
  npuMmAggregateRawIndexPlanInto(index, result)

proc npuMmAggregateSdkHelperEvidenceInto*(index: uint32,
    initialMaskWord: uint32,
    outResult: var NpuMmAggregateSdkHelperEvidence) =
  ## Recover SDK GLB MM aggregate status/mask/clear helper register selection.
  outResult = default(NpuMmAggregateSdkHelperEvidence)
  npuMmAggregateRawIndexPlanInto(index, outResult.plan)
  if not outResult.plan.valid:
    return

  if outResult.plan.usesBank0:
    outResult.statusAddress = MmMiscIntSta0
    outResult.maskAddress = MmMiscIntMask0
    outResult.clearAddress = MmMiscIntClr0
    outResult.usesStatus0 = true
    outResult.usesMask0 = true
    outResult.usesClear0 = true
  elif outResult.plan.usesBank1:
    outResult.statusAddress = MmMiscIntSta1
    outResult.maskAddress = MmMiscIntMask1
    outResult.clearAddress = MmMiscIntClr1
    outResult.usesStatus1 = true
    outResult.usesMask1 = true
    outResult.usesClear1 = true

  outResult.clearWrite = outResult.plan.mask
  outResult.maskSetWrite = initialMaskWord or outResult.plan.mask
  outResult.maskUnmaskWrite = initialMaskWord and not outResult.plan.mask
  outResult.maskSetsMaskBit =
    (outResult.maskSetWrite and outResult.plan.mask) != 0'u32
  outResult.unmaskClearsMaskBit =
    (outResult.maskUnmaskWrite and outResult.plan.mask) == 0'u32
  outResult.clearIsWriteOne = outResult.clearWrite == outResult.plan.mask
  outResult.valid =
    outResult.plan.valid and outResult.clearAddress != 0'u and
      outResult.maskAddress != 0'u and outResult.statusAddress != 0'u and
      outResult.clearIsWriteOne and outResult.maskSetsMaskBit and
      outResult.unmaskClearsMaskBit

proc npuMmAggregateSdkHelperEvidence*(index: uint32,
    initialMaskWord: uint32): NpuMmAggregateSdkHelperEvidence =
  ## Convenience wrapper for SDK MM aggregate helper register evidence.
  npuMmAggregateSdkHelperEvidenceInto(index, initialMaskWord, result)

proc npuMmAggregateInterruptSnapshotFromRawInto*(
    status0, mask0, status1, mask1: uint32,
    outResult: var NpuMmAggregateInterruptSnapshot) =
  ## Decode raw MM_MISC aggregate interrupt banks without naming a subsource.
  outResult = default(NpuMmAggregateInterruptSnapshot)
  outResult.status0 = status0
  outResult.mask0 = mask0
  outResult.clear0 = status0
  outResult.status1 = status1
  outResult.mask1 = mask1
  outResult.clear1 = status1
  outResult.unmaskedStatus0 = status0 and not mask0
  outResult.unmaskedStatus1 = status1 and not mask1
  outResult.maskedStatus0 = status0 and mask0
  outResult.maskedStatus1 = status1 and mask1
  outResult.anyRawStatus = (status0 or status1) != 0'u32
  outResult.anyUnmaskedPending =
    (outResult.unmaskedStatus0 or outResult.unmaskedStatus1) != 0'u32
  outResult.allRawStatusMasked =
    outResult.anyRawStatus and not outResult.anyUnmaskedPending
  if outResult.anyUnmaskedPending:
    outResult.pendingClass = npuMmAggregatePendingUnmasked
  elif outResult.allRawStatusMasked:
    outResult.pendingClass = npuMmAggregatePendingMaskedOnly
  else:
    outResult.pendingClass = npuMmAggregatePendingNone
  outResult.bank0Known = NpuMmAggregateBank0Known
  outResult.bank1E907Known = NpuMmAggregateBank1E907Known
  outResult.clearWriteOne = outResult.clear0 == status0 and
    outResult.clear1 == status1
  outResult.valid =
    outResult.bank0Known and outResult.bank1E907Known and
      outResult.clearWriteOne

proc npuMmAggregateInterruptSnapshotFromRaw*(
    status0, mask0, status1, mask1: uint32): NpuMmAggregateInterruptSnapshot =
  ## Convenience wrapper for raw MM_MISC aggregate interrupt bitmap decoding.
  npuMmAggregateInterruptSnapshotFromRawInto(status0, mask0, status1, mask1,
    result)

proc npuMmAggregateRawIndexSnapshotEvidenceInto*(snapshot:
    NpuMmAggregateInterruptSnapshot, index: uint32,
    outResult: var NpuMmAggregateRawIndexSnapshotEvidence) =
  ## Project one raw MM aggregate index through a decoded snapshot.
  outResult = default(NpuMmAggregateRawIndexSnapshotEvidence)
  npuMmAggregateRawIndexPlanInto(index, outResult.plan)
  outResult.snapshotValid = snapshot.valid
  if outResult.plan.valid:
    if outResult.plan.usesBank0:
      outResult.statusWord = snapshot.status0
      outResult.maskWord = snapshot.mask0
      outResult.clearWord = snapshot.clear0
    elif outResult.plan.usesBank1:
      outResult.statusWord = snapshot.status1
      outResult.maskWord = snapshot.mask1
      outResult.clearWord = snapshot.clear1
    outResult.rawPending = (outResult.statusWord and outResult.plan.mask) != 0'u32
    outResult.masked = (outResult.maskWord and outResult.plan.mask) != 0'u32
    outResult.clearWouldWrite =
      (outResult.clearWord and outResult.plan.mask) != 0'u32
  outResult.unmaskedPending = outResult.rawPending and not outResult.masked
  outResult.maskedOnly = outResult.rawPending and outResult.masked
  outResult.valid =
    outResult.snapshotValid and outResult.plan.valid and
      outResult.clearWouldWrite == outResult.rawPending and
      outResult.unmaskedPending == (outResult.rawPending and not outResult.masked) and
      outResult.maskedOnly == (outResult.rawPending and outResult.masked)

proc npuMmAggregateRawIndexSnapshotEvidence*(
    snapshot: NpuMmAggregateInterruptSnapshot,
    index: uint32): NpuMmAggregateRawIndexSnapshotEvidence =
  ## Convenience wrapper for per-index MM aggregate snapshot evidence.
  npuMmAggregateRawIndexSnapshotEvidenceInto(snapshot, index, result)

proc npuMmAggregateRawIndexClearEvidenceInto*(snapshot:
    NpuMmAggregateInterruptSnapshot, index: uint32,
    outResult: var NpuMmAggregateRawIndexClearEvidence) =
  ## Plan a write-one clear for one raw MM aggregate index.
  outResult = default(NpuMmAggregateRawIndexClearEvidence)
  npuMmAggregateRawIndexSnapshotEvidenceInto(snapshot, index, outResult.snapshot)
  if outResult.snapshot.valid and outResult.snapshot.clearWouldWrite:
    if outResult.snapshot.plan.usesBank0:
      outResult.clear0 = outResult.snapshot.plan.mask
      outResult.write0 = true
    elif outResult.snapshot.plan.usesBank1:
      outResult.clear1 = outResult.snapshot.plan.mask
      outResult.write1 = true
  outResult.anyClear = outResult.write0 or outResult.write1
  outResult.onlySelectedBit =
    (not outResult.write0 or outResult.clear0 == outResult.snapshot.plan.mask) and
      (not outResult.write1 or outResult.clear1 == outResult.snapshot.plan.mask) and
      not (outResult.write0 and outResult.write1)
  outResult.valid =
    outResult.snapshot.valid and outResult.onlySelectedBit and
      outResult.anyClear == outResult.snapshot.rawPending and
      outResult.write0 == (outResult.snapshot.rawPending and
        outResult.snapshot.plan.usesBank0) and
      outResult.write1 == (outResult.snapshot.rawPending and
        outResult.snapshot.plan.usesBank1)

proc npuMmAggregateRawIndexClearEvidence*(
    snapshot: NpuMmAggregateInterruptSnapshot,
    index: uint32): NpuMmAggregateRawIndexClearEvidence =
  ## Convenience wrapper for per-index MM aggregate clear evidence.
  npuMmAggregateRawIndexClearEvidenceInto(snapshot, index, result)

proc npuMmAggregatePendingIndexScanEvidenceInto*(snapshot:
    NpuMmAggregateInterruptSnapshot,
    outResult: var NpuMmAggregatePendingIndexScanEvidence) =
  ## Scan all raw MM aggregate indexes and summarize pending candidates.
  outResult = default(NpuMmAggregatePendingIndexScanEvidence)
  outResult.snapshotValid = snapshot.valid
  outResult.firstRawPendingIndex =
    NpuMmAggregateBankCount * NpuMmAggregateRawBitmapWidth
  outResult.firstUnmaskedPendingIndex = outResult.firstRawPendingIndex
  outResult.firstMaskedOnlyIndex = outResult.firstRawPendingIndex
  for index in 0'u32 ..< NpuMmAggregateBankCount * NpuMmAggregateRawBitmapWidth:
    let evidence = npuMmAggregateRawIndexSnapshotEvidence(snapshot, index)
    if evidence.valid:
      inc outResult.scannedCount
      if evidence.rawPending:
        inc outResult.rawPendingCount
        if not outResult.hasRawPending:
          outResult.firstRawPendingIndex = index
        outResult.hasRawPending = true
      if evidence.unmaskedPending:
        inc outResult.unmaskedPendingCount
        if not outResult.hasUnmaskedPending:
          outResult.firstUnmaskedPendingIndex = index
        outResult.hasUnmaskedPending = true
      if evidence.maskedOnly:
        inc outResult.maskedOnlyCount
        if not outResult.hasMaskedOnly:
          outResult.firstMaskedOnlyIndex = index
        outResult.hasMaskedOnly = true
  outResult.countsMatchSnapshot =
    outResult.hasRawPending == snapshot.anyRawStatus and
      outResult.hasUnmaskedPending == snapshot.anyUnmaskedPending and
      outResult.hasMaskedOnly ==
        ((snapshot.maskedStatus0 or snapshot.maskedStatus1) != 0'u32)
  outResult.valid =
    outResult.snapshotValid and
      outResult.scannedCount ==
        NpuMmAggregateBankCount * NpuMmAggregateRawBitmapWidth and
      outResult.countsMatchSnapshot

proc npuMmAggregatePendingIndexScanEvidence*(
    snapshot: NpuMmAggregateInterruptSnapshot):
    NpuMmAggregatePendingIndexScanEvidence =
  ## Convenience wrapper for raw MM aggregate pending-index scan evidence.
  npuMmAggregatePendingIndexScanEvidenceInto(snapshot, result)

proc npuMmAggregateInterruptSnapshotInto*(
    outResult: var NpuMmAggregateInterruptSnapshot) =
  ## Read and decode the MM_MISC aggregate interrupt banks.
  npuMmAggregateInterruptSnapshotFromRawInto(
    blaiLoadReg(mmMiscInterrupt()[].status0),
    blaiLoadReg(mmMiscInterrupt()[].mask0),
    blaiLoadReg(mmMiscInterrupt()[].status1),
    blaiLoadReg(mmMiscInterrupt()[].mask1),
    outResult)

proc npuMmAggregateInterruptSnapshot*(): NpuMmAggregateInterruptSnapshot =
  ## Convenience wrapper for a read-only MM_MISC aggregate interrupt snapshot.
  npuMmAggregateInterruptSnapshotInto(result)

proc npuMmAggregateInterruptClearPlanInto*(
    snapshot: NpuMmAggregateInterruptSnapshot,
    outResult: var NpuMmAggregateInterruptClearPlan) =
  ## Plan MM_MISC aggregate interrupt clears from a decoded snapshot.
  outResult = default(NpuMmAggregateInterruptClearPlan)
  outResult.snapshot = snapshot
  outResult.clear0 = snapshot.clear0
  outResult.clear1 = snapshot.clear1
  outResult.write0 = snapshot.clear0 != 0'u32
  outResult.write1 = snapshot.clear1 != 0'u32
  outResult.anyClear = outResult.write0 or outResult.write1
  outResult.preservesMask =
    outResult.clear0 == snapshot.status0 and outResult.clear1 == snapshot.status1
  outResult.clearWriteOne = snapshot.clearWriteOne
  outResult.valid =
    snapshot.valid and outResult.preservesMask and outResult.clearWriteOne and
      outResult.anyClear == snapshot.anyRawStatus

proc npuMmAggregateInterruptClearPlan*(
    snapshot: NpuMmAggregateInterruptSnapshot): NpuMmAggregateInterruptClearPlan =
  ## Convenience wrapper for MM_MISC aggregate interrupt clear planning.
  npuMmAggregateInterruptClearPlanInto(snapshot, result)

proc npuApplyMmAggregateInterruptClearPlan*(
    plan: NpuMmAggregateInterruptClearPlan) =
  ## Apply a planned MM_MISC aggregate write-one interrupt clear.
  doAssert plan.valid
  if plan.write0:
    blaiStoreReg(mmMiscInterrupt()[].clear0, plan.clear0)
  if plan.write1:
    blaiStoreReg(mmMiscInterrupt()[].clear1, plan.clear1)

proc npuMmAggregateSubrouteCatalogEvidenceInto*(
    outResult: var NpuMmAggregateSubrouteCatalogEvidence) =
  ## Report what the recovered SDK headers do and do not name for MM_MISC IRQs.
  outResult = default(NpuMmAggregateSubrouteCatalogEvidence)
  outResult.bankCount = NpuMmAggregateBankCount
  outResult.bitmapWidth = NpuMmAggregateRawBitmapWidth
  outResult.stdBank0Known = NpuMmAggregateStdBank0Known
  outResult.stdBank1Known = NpuMmAggregateStdBank1Known
  outResult.e907Bank0Known = NpuMmAggregateE907Bank0Known
  outResult.e907Bank1Known = NpuMmAggregateE907Bank1Known
  outResult.rawBitmapBanksKnown =
    outResult.bankCount == 2'u32 and outResult.bitmapWidth == 32'u32 and
      outResult.stdBank0Known and outResult.e907Bank0Known and
      outResult.e907Bank1Known
  outResult.headersSplitByCore =
    outResult.stdBank0Known and not outResult.stdBank1Known and
      outResult.e907Bank1Known
  outResult.namedCnnSubrouteKnown = NpuMmAggregateNamedCnnSubrouteKnown
  outResult.namedNpuSubrouteKnown = NpuMmAggregateNamedNpuSubrouteKnown
  outResult.namedApuSubrouteKnown = NpuMmAggregateNamedApuSubrouteKnown
  outResult.noNamedNpuSubroute =
    not outResult.namedCnnSubrouteKnown and
      not outResult.namedNpuSubrouteKnown and
      not outResult.namedApuSubrouteKnown
  outResult.valid =
    outResult.rawBitmapBanksKnown and outResult.headersSplitByCore and
      outResult.noNamedNpuSubroute

proc npuMmAggregateSubrouteCatalogEvidence*():
    NpuMmAggregateSubrouteCatalogEvidence =
  ## Convenience wrapper for MM aggregate source-header catalog evidence.
  npuMmAggregateSubrouteCatalogEvidenceInto(result)

proc npuMmAggregateInterruptRouteEvidenceInto*(
    route: NpuInterruptGlbRouteMap,
    snapshot: NpuMmAggregateInterruptSnapshot,
    outResult: var NpuMmAggregateInterruptRouteEvidence) =
  ## Classify whether the MM aggregate surface is enough for local binding.
  outResult = default(NpuMmAggregateInterruptRouteEvidence)
  let catalog = npuMmAggregateSubrouteCatalogEvidence()
  outResult.routeValid = route.valid
  outResult.catalogValid = catalog.valid
  outResult.bank0Known = snapshot.bank0Known
  outResult.bank1E907Known = snapshot.bank1E907Known
  outResult.rawBitmapBanksKnown = catalog.rawBitmapBanksKnown
  outResult.noNamedNpuSubroute = catalog.noNamedNpuSubroute
  outResult.registerSurfaceKnown =
    snapshot.valid and snapshot.bank0Known and snapshot.bank1E907Known and
      catalog.rawBitmapBanksKnown
  outResult.aggregateSourceAvailable = route.mcuMmAggregateAvailable
  outResult.rawSnapshotValid = snapshot.valid
  outResult.subrouteBitKnown = false
  outResult.subrouteUnknown =
    outResult.registerSurfaceKnown and route.requiresMmAggregateDemux and
      outResult.noNamedNpuSubroute and not outResult.subrouteBitKnown
  outResult.directBindingUnsafe = route.m0DirectBindingUnsafe
  outResult.pollingPreserved =
    route.pollingRequired and outResult.subrouteUnknown and
      outResult.directBindingUnsafe
  outResult.valid =
    outResult.routeValid and outResult.catalogValid and
      outResult.aggregateSourceAvailable and outResult.rawSnapshotValid and
      outResult.subrouteUnknown and outResult.pollingPreserved

proc npuMmAggregateInterruptRouteEvidence*(
    route: NpuInterruptGlbRouteMap,
    snapshot: NpuMmAggregateInterruptSnapshot): NpuMmAggregateInterruptRouteEvidence =
  ## Convenience wrapper for MM aggregate route evidence.
  npuMmAggregateInterruptRouteEvidenceInto(route, snapshot, result)

proc npuMmAggregateSdkOffsetCandidateEvidenceInto*(
    route: NpuInterruptGlbRouteMap,
    snapshot: NpuMmAggregateInterruptSnapshot,
    outResult: var NpuMmAggregateSdkOffsetCandidateEvidence) =
  ## Project the recovered SDK CNN offset into the MM aggregate bitmap.
  outResult = default(NpuMmAggregateSdkOffsetCandidateEvidence)
  outResult.routeValid = route.valid
  outResult.snapshotValid = snapshot.valid
  outResult.sdkCnnOffset = route.sdkCnnOffset
  outResult.candidateIndex = NpuCnnIrqOffset
  npuMmAggregateRawIndexSnapshotEvidenceInto(
    snapshot, outResult.candidateIndex, outResult.candidate)
  outResult.bank1Candidate =
    outResult.candidate.plan.valid and outResult.candidate.plan.usesBank1
  outResult.bitMatchesSdkOffset =
    outResult.candidate.plan.index == NpuCnnIrqOffset and
      outResult.candidate.plan.bank == 1'u32 and
      outResult.candidate.plan.bit == 7'u32 and
      outResult.candidate.plan.mask == 0x80'u32
  outResult.rawPending = outResult.candidate.rawPending
  outResult.unmaskedPending = outResult.candidate.unmaskedPending
  outResult.maskedOnly = outResult.candidate.maskedOnly
  outResult.noCandidatePending =
    not outResult.rawPending and not outResult.unmaskedPending and
      not outResult.maskedOnly
  outResult.subrouteStillUnverified =
    route.requiresMmAggregateDemux and route.m0DirectBindingUnsafe and
      outResult.noCandidatePending
  outResult.pollingPreserved =
    route.pollingRequired and outResult.subrouteStillUnverified
  outResult.valid =
    outResult.routeValid and outResult.snapshotValid and outResult.sdkCnnOffset and
      outResult.candidate.valid and outResult.bank1Candidate and
      outResult.bitMatchesSdkOffset and outResult.subrouteStillUnverified and
      outResult.pollingPreserved

proc npuMmAggregateSdkOffsetCandidateEvidence*(
    route: NpuInterruptGlbRouteMap,
    snapshot: NpuMmAggregateInterruptSnapshot):
    NpuMmAggregateSdkOffsetCandidateEvidence =
  ## Convenience wrapper for SDK-offset MM aggregate candidate evidence.
  npuMmAggregateSdkOffsetCandidateEvidenceInto(route, snapshot, result)

proc npuInterruptCoreBindingPolicyInto*(
    interrupt: NpuInterruptConfig,
    runtime: BlaiNpuRuntimeOwnershipPlan,
    bindingVerified: bool,
    outResult: var NpuInterruptCoreBindingPolicy) =
  ## Derive the core-specific binding policy for the recovered CNN IRQ request.
  outResult = default(NpuInterruptCoreBindingPolicy)
  npuInterruptLineOwnershipInto(interrupt, outResult.lineOwnership)
  outResult.requested = interrupt.enable and interrupt.irq == NpuCnnIrq
  outResult.priorityMatched =
    interrupt.preemptPriority == NpuCnnIrqPreemptPriority and
      interrupt.subPriority == NpuCnnIrqSubPriority
  outResult.activeCoreUsesPolling =
    runtime.activeInterruptWait == blaiNpuRuntimeWaitBareMetalPolling
  outResult.d0ApuCandidate = outResult.lineOwnership.d0ApuBindingCandidate
  outResult.m0AliasConflict = outResult.lineOwnership.aliasesM0I2c1Line
  outResult.m0PollingRequired =
    outResult.requested and outResult.priorityMatched and
      outResult.activeCoreUsesPolling and outResult.d0ApuCandidate and
      outResult.m0AliasConflict and not outResult.lineOwnership.m0BindingSafe
  outResult.d0BindingCandidate =
    outResult.requested and outResult.priorityMatched and
      outResult.d0ApuCandidate
  outResult.activeCoreBindingVerified = bindingVerified
  let activeCoreRouteSafe =
    when defined(bl808d0):
      outResult.d0ApuCandidate
    elif defined(bl808m0):
      outResult.lineOwnership.m0BindingSafe
    else:
      false
  outResult.activeCoreReady =
    outResult.requested and outResult.priorityMatched and
      activeCoreRouteSafe and bindingVerified and
      not outResult.activeCoreUsesPolling
  if outResult.activeCoreReady:
    outResult.decision = npuInterruptCoreBindingActiveCoreReady
  elif outResult.m0PollingRequired:
    outResult.decision = npuInterruptCoreBindingM0PollingRequired
  elif outResult.d0BindingCandidate:
    outResult.decision = npuInterruptCoreBindingD0ApuCandidate
  else:
    outResult.decision = npuInterruptCoreBindingNone
  outResult.decisionMatchesEvidence =
    (outResult.decision == npuInterruptCoreBindingActiveCoreReady and
      outResult.activeCoreReady) or
    (outResult.decision == npuInterruptCoreBindingM0PollingRequired and
      outResult.m0PollingRequired) or
    (outResult.decision == npuInterruptCoreBindingD0ApuCandidate and
      outResult.d0BindingCandidate and not outResult.m0PollingRequired and
      not outResult.activeCoreReady) or
    (outResult.decision == npuInterruptCoreBindingNone and
      not outResult.d0BindingCandidate and not outResult.m0PollingRequired and
      not outResult.activeCoreReady)
  outResult.valid =
    outResult.requested and outResult.priorityMatched and
      outResult.d0BindingCandidate and outResult.decisionMatchesEvidence

proc npuInterruptCoreBindingPolicy*(
    interrupt: NpuInterruptConfig,
    runtime: BlaiNpuRuntimeOwnershipPlan,
    bindingVerified: bool = false): NpuInterruptCoreBindingPolicy =
  ## Convenience wrapper for core-specific CNN IRQ binding policy.
  npuInterruptCoreBindingPolicyInto(interrupt, runtime, bindingVerified, result)

proc npuInterruptBindingOperationPlanInto*(
    interrupt: NpuInterruptConfig,
    policy: NpuInterruptCoreBindingPolicy,
    outResult: var NpuInterruptBindingOperationPlan) =
  ## Plan recovered SDK IRQ side effects without touching the interrupt controller.
  outResult = default(NpuInterruptBindingOperationPlan)
  outResult.policy = policy
  outResult.irq = interrupt.irq
  outResult.priority = interrupt.preemptPriority
  if policy.activeCoreReady:
    outResult.operations[0] = npuInterruptBindingRegisterHandler
    outResult.operations[1] = npuInterruptBindingClearPending
    outResult.operations[2] = npuInterruptBindingSetPriority
    outResult.operations[3] = npuInterruptBindingEnableIrq
    outResult.operationCount = 4'u8
    outResult.registerHandlerPlanned = true
    outResult.clearPendingPlanned = true
    outResult.setPriorityPlanned = true
    outResult.enableIrqPlanned = true
  else:
    outResult.activeOperationsSuppressed = true
  outResult.m0PollingPreserved =
    policy.m0PollingRequired and outResult.operationCount == 0'u8 and
      not outResult.registerHandlerPlanned and not outResult.enableIrqPlanned
  outResult.d0CandidatePreserved =
    policy.d0BindingCandidate and policy.d0ApuCandidate
  outResult.valid =
    (policy.activeCoreReady and outResult.operationCount == 4'u8 and
      outResult.registerHandlerPlanned and outResult.clearPendingPlanned and
      outResult.setPriorityPlanned and outResult.enableIrqPlanned) or
    (policy.m0PollingRequired and outResult.activeOperationsSuppressed and
      outResult.m0PollingPreserved and outResult.d0CandidatePreserved)

proc npuInterruptBindingOperationPlan*(
    interrupt: NpuInterruptConfig,
    policy: NpuInterruptCoreBindingPolicy): NpuInterruptBindingOperationPlan =
  ## Convenience wrapper for recovered IRQ binding operation planning.
  npuInterruptBindingOperationPlanInto(interrupt, policy, result)

proc npuInterruptBindingOperationReadinessInto*(
    plan: NpuInterruptBindingOperationPlan,
    outResult: var NpuInterruptBindingOperationReadiness) =
  ## Derive the first gate for applying the recovered SDK IRQ binding sequence.
  outResult = default(NpuInterruptBindingOperationReadiness)
  outResult.policyValid = plan.policy.valid
  outResult.activeCoreReady = plan.policy.activeCoreReady
  outResult.m0PollingRequired = plan.policy.m0PollingRequired
  outResult.operationCount = plan.operationCount
  outResult.operationSequenceKnown =
    (plan.operations[0] == npuInterruptBindingRegisterHandler) and
      (plan.operations[1] == npuInterruptBindingClearPending) and
      (plan.operations[2] == npuInterruptBindingSetPriority) and
      (plan.operations[3] == npuInterruptBindingEnableIrq)
  outResult.operationsPlanned =
    plan.registerHandlerPlanned and plan.clearPendingPlanned and
      plan.setPriorityPlanned and plan.enableIrqPlanned and
      plan.operationCount == 4'u8 and outResult.operationSequenceKnown
  outResult.activeOperationsSuppressed = plan.activeOperationsSuppressed
  outResult.hasDeferredOperation =
    outResult.activeOperationsSuppressed and outResult.m0PollingRequired
  if outResult.hasDeferredOperation:
    outResult.firstDeferredOperation = npuInterruptBindingRegisterHandler
  if not outResult.policyValid or not outResult.activeCoreReady:
    outResult.firstBlock = npuInterruptBindingOperationCorePolicy
  elif not plan.registerHandlerPlanned:
    outResult.firstBlock = npuInterruptBindingOperationRegisterHandler
  elif not plan.clearPendingPlanned:
    outResult.firstBlock = npuInterruptBindingOperationClearPending
  elif not plan.setPriorityPlanned:
    outResult.firstBlock = npuInterruptBindingOperationSetPriority
  elif not plan.enableIrqPlanned:
    outResult.firstBlock = npuInterruptBindingOperationEnableIrq
  else:
    outResult.firstBlock = npuInterruptBindingOperationNoBlock
  outResult.ready =
    plan.valid and outResult.activeCoreReady and outResult.operationsPlanned and
      outResult.firstBlock == npuInterruptBindingOperationNoBlock

proc npuInterruptBindingOperationReadiness*(
    plan: NpuInterruptBindingOperationPlan):
    NpuInterruptBindingOperationReadiness =
  ## Convenience wrapper for IRQ binding operation readiness.
  npuInterruptBindingOperationReadinessInto(plan, result)

proc npuInterruptBindingApplyPreflightInto*(
    plan: NpuInterruptBindingOperationPlan,
    outResult: var NpuInterruptBindingApplyPreflight) =
  ## Pure gate before executing recovered IRQ binding side effects.
  outResult = default(NpuInterruptBindingApplyPreflight)
  outResult.planValid = plan.valid
  npuInterruptBindingOperationReadinessInto(plan, outResult.readiness)
  outResult.activeOperationsSuppressed = plan.activeOperationsSuppressed
  outResult.m0PollingPreserved = plan.m0PollingPreserved
  outResult.readyToApply =
    outResult.planValid and outResult.readiness.ready and
      outResult.readiness.operationsPlanned
  outResult.deferredByPolicy =
    outResult.planValid and outResult.activeOperationsSuppressed and
      outResult.m0PollingPreserved and
      outResult.readiness.hasDeferredOperation
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.valid = outResult.readyToApply or outResult.deferredByPolicy

proc npuInterruptBindingApplyPreflight*(
    plan: NpuInterruptBindingOperationPlan): NpuInterruptBindingApplyPreflight =
  ## Convenience wrapper for recovered IRQ binding apply preflight.
  npuInterruptBindingApplyPreflightInto(plan, result)

when defined(bl808d0) or defined(bl808m0) or defined(bl808lp):
  proc npuApplyInterruptBindingOperationPlan*(
      plan: NpuInterruptBindingOperationPlan,
      handler: irq.TrapHandler): NpuInterruptBindingApplyResult =
    ## Apply the recovered IRQ binding sequence through typed HAL IRQ APIs.
    ##
    ## If the active core is not verified as owning the recovered CNN/APU route,
    ## this returns a valid deferred result and does not touch the controller.
    result.preflight = npuInterruptBindingApplyPreflight(plan)
    result.deferredByPolicy = result.preflight.deferredByPolicy
    result.firstBlock = result.preflight.firstBlock
    if result.deferredByPolicy:
      result.valid = true
      return
    if not result.preflight.readyToApply:
      result.valid = false
      return
    result.handlerPresent = handler != nil
    if not result.handlerPresent:
      result.firstBlock = npuInterruptBindingOperationRegisterHandler
      result.valid = false
      return
    irq.registerTrapHandler(plan.irq, handler)
    result.registerHandlerApplied = true
    irq.irqClearPending(plan.irq)
    result.clearPendingApplied = true
    irq.irqSetLevel(plan.irq, plan.priority)
    result.setPriorityApplied = true
    irq.irqEnable(plan.irq)
    result.enableIrqApplied = true
    result.applied =
      result.registerHandlerApplied and result.clearPendingApplied and
        result.setPriorityApplied and result.enableIrqApplied
    result.valid = result.applied

proc npuInterruptBindingApiContractInto*(
    interrupt: NpuInterruptConfig,
    plan: NpuInterruptBindingOperationPlan,
    outResult: var NpuInterruptBindingApiContract) =
  ## Map recovered SDK IRQ side effects to typed HAL IRQ API calls.
  outResult = default(NpuInterruptBindingApiContract)
  outResult.planValid = plan.valid
  outResult.irqMatchesPlan = plan.irq == interrupt.irq
  outResult.priorityMatchesPlan = plan.priority == interrupt.preemptPriority
  outResult.sdkPriorityMatches =
    interrupt.preemptPriority == NpuCnnIrqPreemptPriority and
      interrupt.subPriority == NpuCnnIrqSubPriority
  outResult.registerHandlerApi =
    plan.registerHandlerPlanned or plan.activeOperationsSuppressed
  outResult.clearPendingApi =
    plan.clearPendingPlanned or plan.activeOperationsSuppressed
  outResult.setLevelApi =
    plan.setPriorityPlanned or plan.activeOperationsSuppressed
  outResult.enableIrqApi =
    plan.enableIrqPlanned or plan.activeOperationsSuppressed
  outResult.apiSequenceComplete =
    outResult.registerHandlerApi and outResult.clearPendingApi and
      outResult.setLevelApi and outResult.enableIrqApi
  outResult.activeCallsDeferred =
    plan.activeOperationsSuppressed and plan.operationCount == 0'u8 and
      not plan.registerHandlerPlanned and not plan.clearPendingPlanned and
      not plan.setPriorityPlanned and not plan.enableIrqPlanned
  outResult.m0PollingPreserved = plan.m0PollingPreserved
  outResult.d0RoutePreserved = plan.d0CandidatePreserved
  outResult.contractMatchesPlan =
    outResult.planValid and outResult.irqMatchesPlan and
      outResult.priorityMatchesPlan and outResult.sdkPriorityMatches and
      outResult.apiSequenceComplete and
      ((plan.policy.activeCoreReady and not outResult.activeCallsDeferred) or
       (plan.policy.m0PollingRequired and outResult.activeCallsDeferred and
        outResult.m0PollingPreserved and outResult.d0RoutePreserved))
  outResult.valid = outResult.contractMatchesPlan

proc npuInterruptBindingApiContract*(
    interrupt: NpuInterruptConfig,
    plan: NpuInterruptBindingOperationPlan): NpuInterruptBindingApiContract =
  ## Convenience wrapper for recovered IRQ API contract planning.
  npuInterruptBindingApiContractInto(interrupt, plan, result)

proc npuSdkInterruptApiEvidenceInto*(
    interrupt: NpuInterruptConfig,
    handlerPresent: bool,
    outResult: var NpuSdkInterruptApiEvidence) =
  ## Recover the exact SDK interrupt wrapper semantics for `blai_npu_initCfg`.
  outResult = default(NpuSdkInterruptApiEvidence)
  outResult.irq = interrupt.irq
  outResult.preemptPriority = interrupt.preemptPriority
  outResult.subPriority = interrupt.subPriority
  outResult.handlerPresent = handlerPresent
  outResult.requestedCnnIrq = interrupt.enable and interrupt.irq == NpuCnnIrq
  outResult.priorityTupleRequested =
    interrupt.preemptPriority == NpuCnnIrqPreemptPriority and
      interrupt.subPriority == NpuCnnIrqSubPriority
  outResult.registerGuardedByIrqLast = NpuSdkInterruptRegisterGuardsIrqLast
  outResult.preemptPriorityApplied =
    NpuSdkInterruptPriorityUsesPreemptOnly and
      interrupt.preemptPriority == NpuCnnIrqPreemptPriority
  outResult.subPriorityIgnoredBySdk =
    NpuSdkInterruptPriorityUsesPreemptOnly and
      interrupt.subPriority == NpuCnnIrqSubPriority
  outResult.enableRaisesZeroPriority = NpuSdkInterruptEnableRaisesZeroPriority
  outResult.clearPendingApiSeparate = not NpuSdkInterruptInitClearsPending
  outResult.initOperationCount = NpuSdkInterruptInitOperationCount
  outResult.initOperations[0] = npuSdkInterruptRegisterHandler
  outResult.initOperations[1] = npuSdkInterruptSetPriority
  outResult.initOperations[2] = npuSdkInterruptEnableIrq
  outResult.initRegistersHandler =
    handlerPresent and outResult.requestedCnnIrq
  outResult.initSetsPriority =
    outResult.requestedCnnIrq and outResult.preemptPriorityApplied
  outResult.initEnablesIrq =
    outResult.requestedCnnIrq and interrupt.enable
  outResult.initClearsPending = NpuSdkInterruptInitClearsPending
  outResult.matchesBlaiInitCfg =
    outResult.requestedCnnIrq and outResult.priorityTupleRequested and
      outResult.initRegistersHandler and outResult.initSetsPriority and
      outResult.initEnablesIrq and outResult.clearPendingApiSeparate and
      outResult.initOperationCount == 3'u8 and not outResult.initClearsPending
  outResult.valid = outResult.matchesBlaiInitCfg

proc npuSdkInterruptApiEvidence*(
    interrupt: NpuInterruptConfig,
    handlerPresent: bool): NpuSdkInterruptApiEvidence =
  ## Convenience wrapper for recovered SDK interrupt wrapper evidence.
  npuSdkInterruptApiEvidenceInto(interrupt, handlerPresent, result)

proc npuInterruptBindingReadinessInto*(
    interrupt: NpuInterruptConfig,
    runtime: BlaiNpuRuntimeOwnershipPlan,
    bindingVerified: bool,
    outResult: var NpuInterruptBindingReadiness) =
  ## Explain whether the recovered CNN IRQ request can replace polling.
  outResult = default(NpuInterruptBindingReadiness)
  outResult.requested = interrupt.enable
  outResult.irqMatchesSdk = interrupt.irq == NpuCnnIrq
  outResult.priorityMatchesSdk =
    interrupt.preemptPriority == NpuCnnIrqPreemptPriority and
      interrupt.subPriority == NpuCnnIrqSubPriority
  outResult.enableRequested = interrupt.enable
  npuInterruptLineOwnershipInto(interrupt, outResult.lineOwnership)
  npuInterruptCoreBindingPolicyInto(
    interrupt, runtime, bindingVerified, outResult.corePolicy)
  npuInterruptBindingOperationPlanInto(
    interrupt, outResult.corePolicy, outResult.operationPlan)
  npuInterruptBindingApiContractInto(
    interrupt, outResult.operationPlan, outResult.apiContract)
  outResult.d0ApuLineCandidate = outResult.corePolicy.d0ApuCandidate
  outResult.m0LineConflict = outResult.corePolicy.m0AliasConflict
  outResult.m0BindingSafe = outResult.corePolicy.lineOwnership.m0BindingSafe
  outResult.activeWaitIsPolling =
    runtime.activeInterruptWait == blaiNpuRuntimeWaitBareMetalPolling
  outResult.bindingVerified = bindingVerified
  outResult.ready =
    outResult.requested and outResult.irqMatchesSdk and
      outResult.priorityMatchesSdk and outResult.enableRequested and
      outResult.corePolicy.activeCoreReady

proc npuInterruptBindingReadiness*(
    interrupt: NpuInterruptConfig,
    runtime: BlaiNpuRuntimeOwnershipPlan,
    bindingVerified: bool = false): NpuInterruptBindingReadiness =
  ## Convenience wrapper for CNN IRQ binding readiness.
  npuInterruptBindingReadinessInto(
    interrupt, runtime, bindingVerified, result)

proc npuCnnIrqControllerSnapshotEvidenceFromRawInto*(
    snapshotValid: bool,
    irqLine, sourceOffset: uint32,
    intip, intie, intattr, intctl: uint8,
    glbPending, glbMasked: bool,
    outResult: var NpuCnnIrqControllerSnapshotEvidence) =
  ## Interpret a live CLIC/GLB readback for the recovered SDK CNN IRQ line.
  outResult = default(NpuCnnIrqControllerSnapshotEvidence)
  outResult.snapshotValid = snapshotValid
  outResult.irqMatchesSdk = irqLine == NpuCnnIrq
  outResult.sourceMatchesSdkOffset = sourceOffset == NpuCnnIrqOffset
  outResult.sourceAliasesM0I2c1 = sourceOffset == NpuGlbMcuI2c1Source
  outResult.pendingClear = (intip and 1'u8) == 0'u8 and not glbPending
  outResult.clicDisabled = (intie and 1'u8) == 0'u8
  outResult.glbMasked = glbMasked
  outResult.attrVectorMode = (intattr and 0x01'u8) != 0'u8
  outResult.attrReadable = outResult.attrVectorMode
  outResult.levelReadable = intctl <= 0xFF'u8
  outResult.deferredBindingConsistent =
    outResult.irqMatchesSdk and outResult.sourceMatchesSdkOffset and
      outResult.sourceAliasesM0I2c1 and outResult.pendingClear and
      outResult.clicDisabled and outResult.glbMasked
  outResult.valid =
    outResult.snapshotValid and outResult.attrReadable and
      outResult.levelReadable and outResult.deferredBindingConsistent

proc npuCnnIrqControllerSnapshotEvidenceFromRaw*(
    snapshotValid: bool,
    irqLine, sourceOffset: uint32,
    intip, intie, intattr, intctl: uint8,
    glbPending, glbMasked: bool): NpuCnnIrqControllerSnapshotEvidence =
  ## Convenience wrapper for raw CNN IRQ controller readback evidence.
  npuCnnIrqControllerSnapshotEvidenceFromRawInto(
    snapshotValid, irqLine, sourceOffset, intip, intie, intattr, intctl,
    glbPending, glbMasked, result)

when defined(bl808m0):
  proc npuCnnIrqControllerSnapshotEvidenceInto*(
      snapshot: irq.M0ClicIrqSnapshot,
      outResult: var NpuCnnIrqControllerSnapshotEvidence) =
    ## Interpret the live M0 CLIC/GLB mux snapshot for SDK `CNN_IRQn`.
    npuCnnIrqControllerSnapshotEvidenceFromRawInto(
      snapshot.valid, snapshot.irq, snapshot.sourceOffset,
      snapshot.intip, snapshot.intie, snapshot.intattr, snapshot.intctl,
      snapshot.glbPending, snapshot.glbMasked, outResult)

  proc npuCnnIrqControllerSnapshotEvidence*(
      snapshot: irq.M0ClicIrqSnapshot): NpuCnnIrqControllerSnapshotEvidence =
    ## Convenience wrapper for live M0 CNN IRQ controller readback evidence.
    npuCnnIrqControllerSnapshotEvidenceInto(snapshot, result)

proc npuApplyInitConfigRegisters*(config: NpuInitConfig) =
  ## Apply the register-programming portion of SDK `blai_npu_initCfg`.
  ##
  ## Interrupt handler registration and enable are intentionally not performed
  ## here until the local CNN/APU IRQ ownership is verified for each core.
  let plan = npuPlanInitConfigRegisters(
    config,
    blaiLoadReg(blaiRegs()[].generalCfg),
    blaiLoadReg(blaiRegs()[].intCfg),
    blaiLoadReg(blaiRegs()[].tfCfg0))
  doAssert plan.valid
  npuApplyLaunchRegisterPlan(plan.launch)
  npuApplyNetParamRegisterPlan(plan.netParams)

proc npuGeneralCfgWithImageInputMode*(
    generalCfg: uint32,
    mode: NpuImageInputMode): uint32 =
  ## Return `generalCfg` with SDK `IMG_IN_MODE` updated.
  let cleared = generalCfg and not BlaiImageModeMask
  cleared or ((mode.uint32 shl BlaiImageModeShift) and BlaiImageModeMask)

proc npuGeneralCfgWithUnsignedInput*(generalCfg: uint32,
                                     enabled: bool): uint32 =
  ## Return `generalCfg` with SDK `IMGI_UNSGN` updated.
  let cleared = generalCfg and not BlaiImgiUnsignMask
  if enabled:
    cleared or BlaiImgiUnsignMask
  else:
    cleared

proc npuIntCfgWithReluN*(intCfg, value: uint32): uint32 =
  ## Return `intCfg` with SDK `RELU_N` updated.
  let cleared = intCfg and not BlaiReluNMask
  cleared or ((value shl BlaiReluNShift) and BlaiReluNMask)

proc npuPlanImageInputModeFieldInto*(generalCfg: uint32,
                                     mode: NpuImageInputMode,
                                     outResult: var NpuNetParamFieldPlan) =
  ## Plan a `BALI_GENERAL_CFG.IMG_IN_MODE` update.
  outResult = default(NpuNetParamFieldPlan)
  outResult.kind = npuNetParamImageInputMode
  outResult.initial = generalCfg
  outResult.imageInputMode = mode
  outResult.encoded = npuGeneralCfgWithImageInputMode(generalCfg, mode)
  outResult.generalDecode.generalCfg = outResult.encoded
  outResult.generalDecode.unsignedInput =
    (outResult.encoded and BlaiImgiUnsignMask) != 0
  outResult.generalDecode.imageInputModeBits =
    (outResult.encoded and BlaiImageModeMask) shr BlaiImageModeShift
  outResult.generalDecode.imageInputModeKnown =
    outResult.generalDecode.imageInputModeBits <= ord(npuInputYuv422).uint32
  if outResult.generalDecode.imageInputModeKnown:
    outResult.generalDecode.imageInputMode =
      NpuImageInputMode(outResult.generalDecode.imageInputModeBits)
  outResult.valid =
    outResult.generalDecode.imageInputModeKnown and
      outResult.generalDecode.imageInputMode == mode

proc npuPlanImageInputModeField*(
    generalCfg: uint32,
    mode: NpuImageInputMode): NpuNetParamFieldPlan =
  ## Convenience wrapper for image input mode field planning.
  npuPlanImageInputModeFieldInto(generalCfg, mode, result)

proc npuPlanUnsignedInputFieldInto*(generalCfg: uint32,
                                   enabled: bool,
                                   outResult: var NpuNetParamFieldPlan) =
  ## Plan a `BALI_GENERAL_CFG.IMGI_UNSGN` update.
  outResult = default(NpuNetParamFieldPlan)
  outResult.kind = npuNetParamUnsignedInput
  outResult.initial = generalCfg
  outResult.enabled = enabled
  outResult.encoded = npuGeneralCfgWithUnsignedInput(generalCfg, enabled)
  outResult.generalDecode.generalCfg = outResult.encoded
  outResult.generalDecode.unsignedInput =
    (outResult.encoded and BlaiImgiUnsignMask) != 0
  outResult.generalDecode.imageInputModeBits =
    (outResult.encoded and BlaiImageModeMask) shr BlaiImageModeShift
  outResult.generalDecode.imageInputModeKnown =
    outResult.generalDecode.imageInputModeBits <= ord(npuInputYuv422).uint32
  if outResult.generalDecode.imageInputModeKnown:
    outResult.generalDecode.imageInputMode =
      NpuImageInputMode(outResult.generalDecode.imageInputModeBits)
  outResult.valid = outResult.generalDecode.unsignedInput == enabled

proc npuPlanUnsignedInputField*(generalCfg: uint32,
                                enabled: bool): NpuNetParamFieldPlan =
  ## Convenience wrapper for unsigned input field planning.
  npuPlanUnsignedInputFieldInto(generalCfg, enabled, result)

proc npuPlanReluNFieldInto*(intCfg, value: uint32,
                            outResult: var NpuNetParamFieldPlan) =
  ## Plan a `BLAI_INT_CFG.RELU_N` update.
  outResult = default(NpuNetParamFieldPlan)
  outResult.kind = npuNetParamReluN
  outResult.initial = intCfg
  outResult.reluN = value and 0x1F'u32
  outResult.encoded = npuIntCfgWithReluN(intCfg, value)
  outResult.intDecode.intCfg = outResult.encoded
  outResult.intDecode.startRequested =
    (outResult.encoded and BlaiStartMask) != 0
  outResult.intDecode.stopRequested =
    (outResult.encoded and BlaiStopMask) != 0
  outResult.intDecode.resumeRequested =
    (outResult.encoded and BlaiResumeMask) != 0
  outResult.intDecode.interruptPending =
    (outResult.encoded and BlaiInterruptStatusMask) != 0
  outResult.intDecode.clearRequested =
    (outResult.encoded and BlaiInterruptClearMask) != 0
  outResult.intDecode.reluN =
    (outResult.encoded and BlaiReluNMask) shr BlaiReluNShift
  outResult.valid = outResult.intDecode.reluN == outResult.reluN

proc npuPlanReluNField*(intCfg, value: uint32): NpuNetParamFieldPlan =
  ## Convenience wrapper for ReLU-N field planning.
  npuPlanReluNFieldInto(intCfg, value, result)

proc npuApplyNetParamFieldPlan*(plan: NpuNetParamFieldPlan) =
  ## Apply one planned BLAI net-parameter field update.
  doAssert plan.valid
  case plan.kind
  of npuNetParamImageInputMode, npuNetParamUnsignedInput:
    blaiStoreReg(blaiRegs()[].generalCfg, plan.encoded)
  of npuNetParamReluN:
    blaiStoreReg(blaiRegs()[].intCfg, plan.encoded)
  of npuNetParamTensorflowMode:
    blaiStoreReg(blaiRegs()[].tfCfg0, plan.encoded)

proc npuSetImageInputMode*(mode: NpuImageInputMode) =
  npuApplyNetParamFieldPlan(
    npuPlanImageInputModeField(blaiLoadReg(blaiRegs()[].generalCfg), mode))

proc npuSetUnsignedInput*(enabled: bool) =
  npuApplyNetParamFieldPlan(
    npuPlanUnsignedInputField(blaiLoadReg(blaiRegs()[].generalCfg), enabled))

proc npuSetReluN*(value: uint32) =
  npuApplyNetParamFieldPlan(
    npuPlanReluNField(blaiLoadReg(blaiRegs()[].intCfg), value))

proc npuTfCfgDecodeFromRawInto*(tfCfg0: uint32,
                                outResult: var NpuTfCfgDecode) =
  ## Decode recovered fields from `BLAI_TF_CFG0`.
  outResult = default(NpuTfCfgDecode)
  outResult.tfCfg0 = tfCfg0
  outResult.tensorflowMode = (tfCfg0 and BlaiTensorflowEnableMask) != 0

proc npuTfCfgDecodeFromRaw*(tfCfg0: uint32): NpuTfCfgDecode =
  ## Convenience wrapper for pure TF_CFG0 decoding.
  npuTfCfgDecodeFromRawInto(tfCfg0, result)

proc npuTfCfgWithTensorflowMode*(tfCfg0: uint32, enabled: bool): uint32 =
  ## Return `tfCfg0` with SDK `TENFLOW_EN` updated.
  let cleared = tfCfg0 and not BlaiTensorflowEnableMask
  if enabled:
    cleared or BlaiTensorflowEnableMask
  else:
    cleared

proc npuPlanTensorflowModeFieldInto*(tfCfg0: uint32,
                                     enabled: bool,
                                     outResult: var NpuNetParamFieldPlan) =
  ## Plan a `BLAI_TF_CFG0.TENFLOW_EN` update.
  outResult = default(NpuNetParamFieldPlan)
  outResult.kind = npuNetParamTensorflowMode
  outResult.initial = tfCfg0
  outResult.enabled = enabled
  outResult.encoded = npuTfCfgWithTensorflowMode(tfCfg0, enabled)
  npuTfCfgDecodeFromRawInto(outResult.encoded, outResult.tfDecode)
  outResult.valid = outResult.tfDecode.tensorflowMode == enabled

proc npuPlanTensorflowModeField*(tfCfg0: uint32,
                                 enabled: bool): NpuNetParamFieldPlan =
  ## Convenience wrapper for TensorFlow mode field planning.
  npuPlanTensorflowModeFieldInto(tfCfg0, enabled, result)

proc npuSetTensorflowMode*(enabled: bool) =
  npuApplyNetParamFieldPlan(
    npuPlanTensorflowModeField(blaiLoadReg(blaiRegs()[].tfCfg0), enabled))

proc npuPlanActivationTableBasesInto*(
    indexBase, dataBase: uint32,
    outResult: var NpuActivationTableBasePlan) =
  ## Plan recovered `BALI_GENERAL_CFG` FTABLE index/data base fields.
  outResult = default(NpuActivationTableBasePlan)
  outResult.indexBase = indexBase
  outResult.dataBase = dataBase
  outResult.indexBaseFits = indexBase <= BlaiFtableBaseValueMask
  outResult.dataBaseFits = dataBase <= BlaiFtableBaseValueMask
  outResult.valid = outResult.indexBaseFits and outResult.dataBaseFits
  outResult.encoded =
    ((indexBase and BlaiFtableBaseValueMask) shl BlaiFtableIndexBaseShift) or
    ((dataBase and BlaiFtableBaseValueMask) shl BlaiFtableDataBaseShift)

proc npuPlanActivationTableBases*(
    indexBase, dataBase: uint32): NpuActivationTableBasePlan =
  ## Convenience wrapper for activation table base planning.
  npuPlanActivationTableBasesInto(indexBase, dataBase, result)

proc npuGeneralCfgWithActivationTableBases*(
    generalCfg: uint32,
    plan: NpuActivationTableBasePlan): uint32 =
  ## Return `generalCfg` with recovered FTABLE base fields updated.
  let cleared =
    generalCfg and not (BlaiFtableIndexBaseMask or BlaiFtableDataBaseMask)
  cleared or plan.encoded

proc npuActivationTableBasePlanFromGeneralCfgInto*(
    generalCfg: uint32,
    outResult: var NpuActivationTableBasePlan) =
  ## Decode recovered FTABLE base fields from `BALI_GENERAL_CFG`.
  let indexBase =
    (generalCfg and BlaiFtableIndexBaseMask) shr BlaiFtableIndexBaseShift
  let dataBase =
    (generalCfg and BlaiFtableDataBaseMask) shr BlaiFtableDataBaseShift
  npuPlanActivationTableBasesInto(indexBase, dataBase, outResult)

proc npuActivationTableBasePlanFromGeneralCfg*(
    generalCfg: uint32): NpuActivationTableBasePlan =
  ## Convenience wrapper for decoding activation table base fields.
  npuActivationTableBasePlanFromGeneralCfgInto(generalCfg, result)

proc npuGeneralCfgDecodeFromRawInto*(generalCfg: uint32,
                                     outResult: var NpuGeneralCfgDecode) =
  ## Decode recovered fields from `BALI_GENERAL_CFG`.
  outResult = default(NpuGeneralCfgDecode)
  outResult.generalCfg = generalCfg
  outResult.unsignedInput = (generalCfg and BlaiImgiUnsignMask) != 0
  outResult.imageInputModeBits =
    (generalCfg and BlaiImageModeMask) shr BlaiImageModeShift
  outResult.imageInputModeKnown =
    outResult.imageInputModeBits <= ord(npuInputYuv422).uint32
  if outResult.imageInputModeKnown:
    outResult.imageInputMode =
      NpuImageInputMode(outResult.imageInputModeBits)
  let activationTableBases =
    npuActivationTableBasePlanFromGeneralCfg(generalCfg)
  outResult.activationTableIndexBase = activationTableBases.indexBase
  outResult.activationTableDataBase = activationTableBases.dataBase
  outResult.axiWriteIdle = (generalCfg and BlaiAxiWriteIdleMask) != 0
  outResult.axiReadIdle = (generalCfg and BlaiAxiReadIdleMask) != 0
  outResult.busy = not (outResult.axiWriteIdle and outResult.axiReadIdle)

proc npuGeneralCfgDecodeFromRaw*(generalCfg: uint32): NpuGeneralCfgDecode =
  ## Convenience wrapper for pure GENERAL_CFG decoding.
  npuGeneralCfgDecodeFromRawInto(generalCfg, result)

proc npuActivationTableBaseRegisterPlanInto*(
    generalCfg: uint32,
    bases: NpuActivationTableBasePlan,
    outResult: var NpuActivationTableBaseRegisterPlan) =
  ## Plan a `BALI_GENERAL_CFG` activation-table base-field update.
  outResult = default(NpuActivationTableBaseRegisterPlan)
  outResult.initialGeneralCfg = generalCfg
  outResult.bases = bases
  outResult.encodedGeneralCfg =
    npuGeneralCfgWithActivationTableBases(generalCfg, bases)
  npuGeneralCfgDecodeFromRawInto(outResult.encodedGeneralCfg, outResult.decoded)
  outResult.preservesOtherFields =
    (outResult.encodedGeneralCfg and not (
      BlaiFtableIndexBaseMask or BlaiFtableDataBaseMask)) ==
      (generalCfg and not (BlaiFtableIndexBaseMask or BlaiFtableDataBaseMask))
  outResult.valid =
    bases.valid and
      outResult.decoded.activationTableIndexBase == bases.indexBase and
      outResult.decoded.activationTableDataBase == bases.dataBase and
      outResult.preservesOtherFields

proc npuActivationTableBaseRegisterPlan*(
    generalCfg: uint32,
    bases: NpuActivationTableBasePlan): NpuActivationTableBaseRegisterPlan =
  ## Convenience wrapper for activation-table base register planning.
  npuActivationTableBaseRegisterPlanInto(generalCfg, bases, result)

proc npuApplyActivationTableBaseRegisterPlan*(
    plan: NpuActivationTableBaseRegisterPlan) =
  ## Apply a planned activation-table base update to `BALI_GENERAL_CFG`.
  doAssert plan.valid
  blaiStoreReg(blaiRegs()[].generalCfg, plan.encodedGeneralCfg)

proc npuActivationTableEntryCursor*(entryIndex: int):
    NpuActivationTableEntryCursor =
  ## Resolve one 8-bit activation-table entry lane inside a packed word.
  if entryIndex < 0 or entryIndex >= BlaiActivationTableEntriesPerWord:
    return
  result.entryIndex = entryIndex
  result.shift = (entryIndex * BlaiActivationTableEntryWidth).uint32
  result.mask = BlaiActivationTableEntryMask
  result.valid = true

proc npuActivationTableEntryByte*(raw: uint32,
                                  cursor: NpuActivationTableEntryCursor): uint8 =
  ## Extract one activation-table byte from a packed register word.
  doAssert cursor.valid
  ((raw shr cursor.shift) and cursor.mask).uint8

proc npuMergeActivationTableEntry*(raw: var uint32,
                                   entry: uint8,
                                   cursor: NpuActivationTableEntryCursor) =
  ## Merge one activation-table byte into a packed register word.
  doAssert cursor.valid
  raw = raw or (entry.uint32 shl cursor.shift)

proc npuActivationTableWordCursor*(wordIndex: uint32):
    NpuActivationTableWordCursor =
  ## Project one activation-table word index to table entry and MMIO offsets.
  result.wordIndex = wordIndex
  let firstEntry =
    wordIndex.uint64 * BlaiActivationTableEntriesPerWord.uint64
  let registerOffset =
    BlaiActivationTableBaseOffset.uint64 +
      wordIndex.uint64 * BlaiActivationTableWordBytes.uint64
  if not blaiU64ExactU32Count(firstEntry, result.firstEntryIndex):
    return
  if not blaiU64ExactU32Count(registerOffset, result.registerOffset):
    return
  if not blaiU64ExactU32Count(
      BlaiBase.uint64 + result.registerOffset.uint64, result.registerAddress):
    return
  result.valid = wordIndex < BlaiActivationTableWordCount

proc npuPlanActivationTableWordInto*(
    wordIndex: uint32,
    entry0, entry1, entry2, entry3: uint8,
    outResult: var NpuActivationTableWordPlan) =
  ## Plan one recovered packed `BLAI_ACT_TABLE*` register word.
  outResult = default(NpuActivationTableWordPlan)
  outResult.wordIndex = wordIndex
  let wordCursor = npuActivationTableWordCursor(wordIndex)
  outResult.firstEntryIndex = wordCursor.firstEntryIndex
  outResult.registerOffset = wordCursor.registerOffset
  outResult.registerAddress = wordCursor.registerAddress
  outResult.entries[0] = entry0
  outResult.entries[1] = entry1
  outResult.entries[2] = entry2
  outResult.entries[3] = entry3
  outResult.wordIndexFits = wordCursor.valid
  for entryIndex in 0 ..< BlaiActivationTableEntriesPerWord:
    let cursor = npuActivationTableEntryCursor(entryIndex)
    if not cursor.valid:
      continue
    npuMergeActivationTableEntry(
      outResult.encoded, outResult.entries[entryIndex], cursor)
  outResult.valid = outResult.wordIndexFits

proc npuPlanActivationTableWord*(
    wordIndex: uint32,
    entry0, entry1, entry2, entry3: uint8): NpuActivationTableWordPlan =
  ## Convenience wrapper for activation-table word planning.
  npuPlanActivationTableWordInto(
    wordIndex, entry0, entry1, entry2, entry3, result)

proc npuActivationTableWordFromRawInto*(
    wordIndex, raw: uint32,
    outResult: var NpuActivationTableWordPlan) =
  ## Decode one recovered packed `BLAI_ACT_TABLE*` register word.
  npuPlanActivationTableWordInto(
    wordIndex,
    npuActivationTableEntryByte(raw, npuActivationTableEntryCursor(0)),
    npuActivationTableEntryByte(raw, npuActivationTableEntryCursor(1)),
    npuActivationTableEntryByte(raw, npuActivationTableEntryCursor(2)),
    npuActivationTableEntryByte(raw, npuActivationTableEntryCursor(3)),
    outResult)

proc npuActivationTableWordFromRaw*(
    wordIndex, raw: uint32): NpuActivationTableWordPlan =
  ## Convenience wrapper for activation-table word decoding.
  npuActivationTableWordFromRawInto(wordIndex, raw, result)

proc npuActivationTableDefaultEvidenceInto*(
    wordIndex, raw: uint32,
    outResult: var NpuActivationTableDefaultEvidence) =
  ## Check recovered activation-table reset defaults for the first word.
  outResult = default(NpuActivationTableDefaultEvidence)
  outResult.wordIndex = wordIndex
  outResult.raw = raw
  let decoded = npuActivationTableWordFromRaw(wordIndex, raw)
  outResult.wordIndexMatches = wordIndex == 0'u32
  outResult.rawMatchesReset = raw == BlaiActivationTableResetWord0
  outResult.decodedValid = decoded.valid
  if decoded.valid:
    outResult.entry0Matches =
      decoded.entries[0] == BlaiActivationTableResetEntry0
    outResult.entry1Matches =
      decoded.entries[1] == BlaiActivationTableResetEntry1
    outResult.entry2Matches =
      decoded.entries[2] == BlaiActivationTableResetEntry2
    outResult.entry3Matches =
      decoded.entries[3] == BlaiActivationTableResetEntry3
  outResult.entriesMatchReset =
    outResult.entry0Matches and outResult.entry1Matches and
      outResult.entry2Matches and outResult.entry3Matches
  outResult.valid =
    outResult.wordIndexMatches and outResult.rawMatchesReset and
      outResult.decodedValid and outResult.entriesMatchReset

proc npuActivationTableDefaultEvidence*(
    wordIndex, raw: uint32): NpuActivationTableDefaultEvidence =
  ## Convenience wrapper for activation-table reset-default evidence.
  npuActivationTableDefaultEvidenceInto(wordIndex, raw, result)

proc npuIntCfgDecodeFromRawInto*(intCfg: uint32,
                                 outResult: var NpuIntCfgDecode) =
  ## Decode the recovered command, interrupt, and ReLU fields from INT_CFG.
  outResult = default(NpuIntCfgDecode)
  outResult.intCfg = intCfg
  outResult.startRequested = (intCfg and BlaiStartMask) != 0
  outResult.stopRequested = (intCfg and BlaiStopMask) != 0
  outResult.resumeRequested = (intCfg and BlaiResumeMask) != 0
  outResult.interruptPending = (intCfg and BlaiInterruptStatusMask) != 0
  outResult.clearRequested = (intCfg and BlaiInterruptClearMask) != 0
  outResult.reluN = (intCfg and BlaiReluNMask) shr BlaiReluNShift

proc npuIntCfgDecodeFromRaw*(intCfg: uint32): NpuIntCfgDecode =
  ## Convenience wrapper for pure INT_CFG decoding.
  npuIntCfgDecodeFromRawInto(intCfg, result)

proc npuPlanNetParamRegistersInto*(
    params: NpuNetParams,
    generalCfg, intCfg, tfCfg0: uint32,
    outResult: var NpuNetParamRegisterPlan) =
  ## Plan SDK net-wide BLAI parameter register updates without touching hardware.
  outResult = default(NpuNetParamRegisterPlan)
  outResult.params = params
  outResult.initialGeneralCfg = generalCfg
  outResult.initialIntCfg = intCfg
  outResult.initialTfCfg0 = tfCfg0
  outResult.generalCfg =
    npuGeneralCfgWithUnsignedInput(generalCfg, params.unsignedInput)
  outResult.intCfg = npuIntCfgWithReluN(intCfg, params.reluN)
  outResult.tfCfg0 = npuTfCfgWithTensorflowMode(tfCfg0, params.tensorflowMode)
  outResult.generalDecode = npuGeneralCfgDecodeFromRaw(outResult.generalCfg)
  outResult.intDecode = npuIntCfgDecodeFromRaw(outResult.intCfg)
  outResult.tfDecode = npuTfCfgDecodeFromRaw(outResult.tfCfg0)
  outResult.valid =
    outResult.generalDecode.unsignedInput == params.unsignedInput and
      outResult.intDecode.reluN == min(params.reluN, 0x1F'u32) and
      outResult.tfDecode.tensorflowMode == params.tensorflowMode

proc npuPlanNetParamRegisters*(
    params: NpuNetParams,
    generalCfg, intCfg, tfCfg0: uint32): NpuNetParamRegisterPlan =
  ## Convenience wrapper for net-parameter register planning.
  npuPlanNetParamRegistersInto(params, generalCfg, intCfg, tfCfg0, result)

proc npuApplyNetParamRegisterPlan*(plan: NpuNetParamRegisterPlan) =
  ## Apply a precomputed net-parameter register plan.
  doAssert plan.valid
  blaiStoreReg(blaiRegs()[].generalCfg, plan.generalCfg)
  blaiStoreReg(blaiRegs()[].intCfg, plan.intCfg)
  blaiStoreReg(blaiRegs()[].tfCfg0, plan.tfCfg0)

proc npuConfigureNetParams*(params: NpuNetParams) =
  ## Program SDK-recovered net-wide BLAI execution parameters.
  let plan = npuPlanNetParamRegisters(
    params,
    blaiLoadReg(blaiRegs()[].generalCfg),
    blaiLoadReg(blaiRegs()[].intCfg),
    blaiLoadReg(blaiRegs()[].tfCfg0))
  npuApplyNetParamRegisterPlan(plan)

proc npuResetUnsignedInput*() =
  ## SDK `bl_npu_reset_unsign`: clear the unsigned-input flag after the first layer.
  npuSetUnsignedInput(false)

proc npuRegisterSnapshotFromRegsInto*(
    generalCfg, intCfg, weightAddr, biasAddr, instAddr, imageAddr, imageSeg,
    tfCfg0: uint32,
    outResult: var NpuRegisterSnapshot) =
  ## Decode the BLAI launch/configuration register set from raw words.
  outResult = default(NpuRegisterSnapshot)
  outResult.generalCfg = generalCfg
  outResult.intCfg = intCfg
  outResult.weightAddr = weightAddr
  outResult.biasAddr = biasAddr
  outResult.instAddr = instAddr
  outResult.imageAddr = imageAddr
  outResult.imageSeg = imageSeg
  outResult.tfCfg0 = tfCfg0
  let generalDecode = npuGeneralCfgDecodeFromRaw(generalCfg)
  outResult.unsignedInput = generalDecode.unsignedInput
  outResult.imageInputModeBits = generalDecode.imageInputModeBits
  outResult.imageInputModeKnown = generalDecode.imageInputModeKnown
  outResult.imageInputMode = generalDecode.imageInputMode
  outResult.activationTableIndexBase =
    generalDecode.activationTableIndexBase
  outResult.activationTableDataBase = generalDecode.activationTableDataBase
  let intDecode = npuIntCfgDecodeFromRaw(intCfg)
  outResult.reluN = intDecode.reluN
  let tfDecode = npuTfCfgDecodeFromRaw(tfCfg0)
  outResult.tensorflowMode = tfDecode.tensorflowMode
  outResult.startRequested = intDecode.startRequested
  outResult.stopRequested = intDecode.stopRequested
  outResult.resumeRequested = intDecode.resumeRequested
  outResult.interruptPending = intDecode.interruptPending
  outResult.clearRequested = intDecode.clearRequested
  outResult.axiWriteIdle = generalDecode.axiWriteIdle
  outResult.axiReadIdle = generalDecode.axiReadIdle
  outResult.busy = generalDecode.busy

proc npuRegisterSnapshotFromRegs*(
    generalCfg, intCfg, weightAddr, biasAddr, instAddr, imageAddr, imageSeg,
    tfCfg0: uint32): NpuRegisterSnapshot =
  ## Convenience wrapper for pure BLAI register snapshot decoding.
  npuRegisterSnapshotFromRegsInto(
    generalCfg, intCfg, weightAddr, biasAddr, instAddr, imageAddr, imageSeg,
    tfCfg0, result)

proc npuRegisterSnapshotInto*(outResult: var NpuRegisterSnapshot) =
  ## Read and decode the live BLAI launch/configuration register set.
  npuRegisterSnapshotFromRegsInto(
    blaiLoadReg(blaiRegs()[].generalCfg),
    blaiLoadReg(blaiRegs()[].intCfg),
    blaiLoadReg(blaiRegs()[].weightAddr),
    blaiLoadReg(blaiRegs()[].biasAddr),
    blaiLoadReg(blaiRegs()[].instAddr),
    blaiLoadReg(blaiRegs()[].imageAddr),
    blaiLoadReg(blaiRegs()[].imageSeg),
    blaiLoadReg(blaiRegs()[].tfCfg0),
    outResult)

proc npuRegisterSnapshot*(): NpuRegisterSnapshot =
  ## Convenience wrapper for a live BLAI launch/configuration snapshot.
  npuRegisterSnapshotInto(result)

proc npuRegisterSnapshotCaptureState*(snapshot: NpuRegisterSnapshot,
                                      captured: bool):
    NpuRegisterSnapshotCaptureState =
  ## Build caller-owned state for one BLAI register snapshot capture.
  result.snapshot = snapshot
  result.captured = captured

proc npuRegisterSnapshotCaptureApplyPlan*(snapshot: NpuRegisterSnapshot):
    NpuRegisterSnapshotCaptureApplyPlan =
  ## Recover a successful live BLAI register snapshot capture commit.
  result.stateAfter = npuRegisterSnapshotCaptureState(snapshot, captured = true)
  result.valid = true

proc npuRegisterSnapshotCaptureState*(
    plan: NpuRegisterSnapshotCaptureApplyPlan):
    NpuRegisterSnapshotCaptureState =
  ## Project a valid snapshot-capture plan into caller-owned state.
  doAssert plan.valid
  plan.stateAfter

proc npuApplyLastLaunchRegisterSnapshotState*(
    state: NpuRegisterSnapshotCaptureState) =
  ## Apply a captured pre-start BLAI register snapshot to wrapper globals.
  npuLastLaunchRegisters = state.snapshot
  npuLastLaunchRegisterSnapshotCapturedFlag = state.captured

proc npuApplyLastStartedRegisterSnapshotState*(
    state: NpuRegisterSnapshotCaptureState) =
  ## Apply a captured post-start BLAI register snapshot to wrapper globals.
  npuLastStartedRegisters = state.snapshot
  npuLastStartedRegisterSnapshotCapturedFlag = state.captured

static:
  let staticRegisterSnapshotCapture = npuRegisterSnapshotFromRegs(
    generalCfg = BlaiTensorflowEnableMask,
    intCfg = 0'u32,
    weightAddr = 0x2200_1000'u32,
    biasAddr = 0x2200_2000'u32,
    instAddr = 0x2200_3000'u32,
    imageAddr = 0x2200_4000'u32,
    imageSeg = 2'u32,
    tfCfg0 = BlaiTensorflowEnableMask)
  let staticRegisterSnapshotApply =
    npuRegisterSnapshotCaptureApplyPlan(staticRegisterSnapshotCapture)
  doAssert staticRegisterSnapshotApply.valid
  let staticRegisterSnapshotState =
    npuRegisterSnapshotCaptureState(staticRegisterSnapshotApply)
  doAssert staticRegisterSnapshotState.captured
  doAssert staticRegisterSnapshotState.snapshot.instAddr == 0x2200_3000'u32
  doAssert staticRegisterSnapshotState.snapshot.imageSeg == 2'u32

proc npuLastLaunchRegisterSnapshotCaptured*(): bool =
  ## Whether the live wait path has captured a pre-start BLAI register snapshot.
  npuLastLaunchRegisterSnapshotCapturedFlag

proc npuLastStartedRegisterSnapshotCaptured*(): bool =
  ## Whether the live wait path has captured a post-start BLAI register snapshot.
  npuLastStartedRegisterSnapshotCapturedFlag

proc npuLastLaunchRegisterSnapshotInto*(outResult: var NpuRegisterSnapshot) =
  ## Return the last pre-start BLAI register snapshot captured by the wait path.
  outResult = npuLastLaunchRegisters

proc npuLastLaunchRegisterSnapshot*(): NpuRegisterSnapshot =
  ## Convenience wrapper for the last pre-start BLAI register snapshot.
  npuLastLaunchRegisterSnapshotInto(result)

proc npuLastStartedRegisterSnapshotInto*(outResult: var NpuRegisterSnapshot) =
  ## Return the last post-start BLAI register snapshot captured by the wait path.
  outResult = npuLastStartedRegisters

proc npuLastStartedRegisterSnapshot*(): NpuRegisterSnapshot =
  ## Convenience wrapper for the last post-start BLAI register snapshot.
  npuLastStartedRegisterSnapshotInto(result)

proc npuRegisterSnapshotEvidenceInto*(
    snapshot: NpuRegisterSnapshot,
    captured: bool,
    expectedInstAddr: uint32,
    expectedWeightAddr: uint32,
    expectedBiasAddr: uint32,
    expectedDataAddr: uint32,
    expectedSegment: uint32,
    checkStartBit: bool,
    expectedUnsignedInput: bool,
    outResult: var NpuRegisterSnapshotEvidence) =
  ## Compare one captured BLAI register snapshot against expected launch state.
  outResult = default(NpuRegisterSnapshotEvidence)
  outResult.captured = captured
  outResult.instAddrMatches = snapshot.instAddr == expectedInstAddr
  outResult.weightAddrMatches = snapshot.weightAddr == expectedWeightAddr
  outResult.biasAddrMatches = snapshot.biasAddr == expectedBiasAddr
  outResult.dataAddrMatches = snapshot.imageAddr == expectedDataAddr
  outResult.segmentMatches = snapshot.imageSeg == expectedSegment
  outResult.unsignedInputMatches = snapshot.unsignedInput == expectedUnsignedInput
  outResult.tensorflowModeMatches = snapshot.tensorflowMode
  outResult.reluNMatches = snapshot.reluN == 0'u32
  outResult.netMatches =
    outResult.unsignedInputMatches and outResult.tensorflowModeMatches and
      outResult.reluNMatches
  outResult.startCommandClean = not snapshot.startRequested
  outResult.resumeCommandClean = not snapshot.resumeRequested
  outResult.stopCommandClean = not snapshot.stopRequested
  outResult.interruptClearCommandClean =
    not snapshot.clearRequested
  outResult.interruptStatusClean = not snapshot.interruptPending
  outResult.intCfgClean =
    (if checkStartBit: outResult.startCommandClean else: true) and
      outResult.resumeCommandClean and outResult.stopCommandClean and
      outResult.interruptClearCommandClean and outResult.interruptStatusClean
  outResult.valid =
    outResult.captured and outResult.instAddrMatches and
      outResult.weightAddrMatches and outResult.biasAddrMatches and
      outResult.dataAddrMatches and outResult.segmentMatches and
      outResult.netMatches and outResult.intCfgClean

proc npuRegisterSnapshotEvidence*(
    snapshot: NpuRegisterSnapshot,
    captured: bool,
    expectedInstAddr: uint32,
    expectedWeightAddr: uint32,
    expectedBiasAddr: uint32,
    expectedDataAddr: uint32,
    expectedSegment: uint32,
    checkStartBit: bool = false,
    expectedUnsignedInput: bool = false): NpuRegisterSnapshotEvidence =
  ## Convenience wrapper for BLAI register snapshot evidence.
  npuRegisterSnapshotEvidenceInto(
    snapshot, captured, expectedInstAddr, expectedWeightAddr, expectedBiasAddr,
    expectedDataAddr, expectedSegment, checkStartBit, expectedUnsignedInput,
    result)

proc npuGeneralCfgDefaultEvidenceInto*(
    snapshot: NpuRegisterSnapshot,
    captured: bool,
    expectedUnsignedInput: bool,
    outResult: var NpuGeneralCfgDefaultEvidence) =
  ## Check `BALI_GENERAL_CFG` against recovered SDK reset/default fields.
  outResult = default(NpuGeneralCfgDefaultEvidence)
  outResult.generalCfg = snapshot.generalCfg
  outResult.captured = captured
  outResult.expectedUnsignedInput = expectedUnsignedInput
  outResult.unsignedInputMatches =
    snapshot.unsignedInput == expectedUnsignedInput
  outResult.imageModeKnown = snapshot.imageInputModeKnown
  outResult.imageModeDefault =
    snapshot.imageInputModeKnown and snapshot.imageInputMode == npuInputSound
  outResult.activationIndexBaseDefault =
    snapshot.activationTableIndexBase == BlaiFtableIndexBaseReset
  outResult.activationDataBaseDefault =
    snapshot.activationTableDataBase == BlaiFtableDataBaseReset
  outResult.reservedBitsClear =
    (snapshot.generalCfg and not BlaiGeneralCfgKnownMask) == 0'u32
  outResult.axiIdleBitsSet =
    snapshot.axiWriteIdle and snapshot.axiReadIdle
  outResult.notBusy = not snapshot.busy
  outResult.defaultsMatch =
    outResult.unsignedInputMatches and outResult.imageModeDefault and
      outResult.activationIndexBaseDefault and
      outResult.activationDataBaseDefault and outResult.reservedBitsClear
  outResult.valid =
    outResult.captured and outResult.imageModeKnown and
      outResult.defaultsMatch and outResult.axiIdleBitsSet and
      outResult.notBusy

proc npuGeneralCfgDefaultEvidence*(
    snapshot: NpuRegisterSnapshot,
    captured: bool,
    expectedUnsignedInput: bool = false): NpuGeneralCfgDefaultEvidence =
  ## Convenience wrapper for `BALI_GENERAL_CFG` default evidence.
  npuGeneralCfgDefaultEvidenceInto(
    snapshot, captured, expectedUnsignedInput, result)

proc npuIntCfgKnownFieldEvidenceInto*(
    snapshot: NpuRegisterSnapshot,
    captured: bool,
    expectedReluN: uint32,
    outResult: var NpuIntCfgKnownFieldEvidence) =
  ## Check `BLAI_INT_CFG` against the recovered SDK known-field map.
  outResult = default(NpuIntCfgKnownFieldEvidence)
  outResult.intCfg = snapshot.intCfg
  outResult.captured = captured
  outResult.knownMask = BlaiIntCfgKnownMask
  outResult.reservedBitsClear =
    (snapshot.intCfg and not BlaiIntCfgKnownMask) == 0'u32
  let decoded = npuIntCfgDecodeFromRaw(snapshot.intCfg)
  outResult.reluNMatches =
    decoded.reluN == (expectedReluN and 0x1F'u32)
  outResult.startCommandClean = not decoded.startRequested
  outResult.stopCommandClean = not decoded.stopRequested
  outResult.resumeCommandClean = not decoded.resumeRequested
  outResult.clearCommandClean = not decoded.clearRequested
  outResult.interruptStatusClean = not decoded.interruptPending
  outResult.commandBitsClean =
    outResult.startCommandClean and outResult.stopCommandClean and
      outResult.resumeCommandClean and outResult.clearCommandClean
  outResult.interruptBitsClean =
    outResult.clearCommandClean and outResult.interruptStatusClean
  outResult.defaultsMatch =
    outResult.reservedBitsClear and outResult.reluNMatches and
      outResult.commandBitsClean and outResult.interruptBitsClean
  outResult.valid = outResult.captured and outResult.defaultsMatch

proc npuIntCfgKnownFieldEvidence*(
    snapshot: NpuRegisterSnapshot,
    captured: bool,
    expectedReluN: uint32 = 0): NpuIntCfgKnownFieldEvidence =
  ## Convenience wrapper for `BLAI_INT_CFG` known-field evidence.
  npuIntCfgKnownFieldEvidenceInto(
    snapshot, captured, expectedReluN, result)

proc blaiParsedForwardConfiguredWorkspaceLaunchRegisterEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    expectedInstAddr: uint32,
    expectedWeightAddr: uint32,
    expectedBiasAddr: uint32,
    expectedDataAddr: uint32,
    expectedSegment: uint32,
    expectedUnsignedInput: bool,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceLaunchRegisterEvidence) =
  ## Combine captured launch/start BLAI register evidence for a configured run.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceLaunchRegisterEvidence)
  outResult.launch = npuRegisterSnapshotEvidence(
    snapshot.launchRegisters, snapshot.launchRegistersCaptured,
    expectedInstAddr = expectedInstAddr, expectedWeightAddr = expectedWeightAddr,
    expectedBiasAddr = expectedBiasAddr, expectedDataAddr = expectedDataAddr,
    expectedSegment = expectedSegment, checkStartBit = true,
    expectedUnsignedInput = expectedUnsignedInput)
  outResult.started = npuRegisterSnapshotEvidence(
    snapshot.startedRegisters, snapshot.startedRegistersCaptured,
    expectedInstAddr = expectedInstAddr, expectedWeightAddr = expectedWeightAddr,
    expectedBiasAddr = expectedBiasAddr, expectedDataAddr = expectedDataAddr,
    expectedSegment = expectedSegment,
    expectedUnsignedInput = expectedUnsignedInput)
  outResult.capturesValid =
    outResult.launch.captured and outResult.started.captured
  outResult.launchValid = outResult.launch.valid
  outResult.startedValid = outResult.started.valid
  outResult.startObserved = validation.execution.lastExecution.completion.started
  outResult.snapshotStartedMatches =
    snapshot.lastExecutionStarted == validation.execution.lastExecution.started
  outResult.valid =
    outResult.capturesValid and outResult.launchValid and
      outResult.startedValid and outResult.startObserved and
      outResult.snapshotStartedMatches

proc blaiParsedForwardConfiguredWorkspaceLaunchRegisterEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    expectedInstAddr: uint32,
    expectedWeightAddr: uint32,
    expectedBiasAddr: uint32,
    expectedDataAddr: uint32,
    expectedSegment: uint32,
    expectedUnsignedInput: bool = false):
    BlaiParsedForwardConfiguredWorkspaceLaunchRegisterEvidence =
  ## Convenience wrapper for configured launch/start register evidence.
  blaiParsedForwardConfiguredWorkspaceLaunchRegisterEvidenceInto(
    snapshot, validation, expectedInstAddr, expectedWeightAddr, expectedBiasAddr,
    expectedDataAddr, expectedSegment, expectedUnsignedInput, result)

proc blaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidenceInto*(
    launchStart: BlaiParsedForwardConfiguredWorkspaceLaunchRegisterEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidence) =
  ## Derive focused launch-to-start register retention evidence.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidence)
  outResult.capturesValid = launchStart.capturesValid
  outResult.addressRetained =
    launchStart.launch.instAddrMatches and launchStart.started.instAddrMatches and
      launchStart.launch.weightAddrMatches and launchStart.started.weightAddrMatches and
      launchStart.launch.biasAddrMatches and launchStart.started.biasAddrMatches and
      launchStart.launch.dataAddrMatches and launchStart.started.dataAddrMatches
  outResult.segmentRetained =
    launchStart.launch.segmentMatches and launchStart.started.segmentMatches
  outResult.netRetained =
    launchStart.launch.netMatches and launchStart.started.netMatches
  outResult.launchCommandsClean = launchStart.launch.intCfgClean
  outResult.startedCommandsClean =
    launchStart.started.startCommandClean and launchStart.started.intCfgClean
  outResult.startObserved = launchStart.startObserved
  outResult.snapshotStartedMatches = launchStart.snapshotStartedMatches
  outResult.valid =
    outResult.capturesValid and outResult.addressRetained and
      outResult.segmentRetained and outResult.netRetained and
      outResult.launchCommandsClean and outResult.startedCommandsClean and
      outResult.startObserved and outResult.snapshotStartedMatches

proc blaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidence*(
    launchStart: BlaiParsedForwardConfiguredWorkspaceLaunchRegisterEvidence):
    BlaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidence =
  ## Convenience wrapper for launch-to-start register retention evidence.
  blaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidenceInto(
    launchStart, result)

proc npuInterruptStatusFromIntCfgInto*(intCfg: uint32,
                                       outResult: var NpuInterruptStatusResult) =
  ## Decode the recovered BLAI interrupt bits from `BLAI_INT_CFG`.
  outResult = default(NpuInterruptStatusResult)
  let intDecode = npuIntCfgDecodeFromRaw(intCfg)
  outResult.intCfg = intDecode.intCfg
  outResult.interruptPending = intDecode.interruptPending
  outResult.clearRequested = intDecode.clearRequested

proc npuInterruptStatusFromIntCfg*(intCfg: uint32): NpuInterruptStatusResult =
  ## Convenience wrapper for pure BLAI interrupt state decoding.
  npuInterruptStatusFromIntCfgInto(intCfg, result)

proc npuInterruptStatusInto*(outResult: var NpuInterruptStatusResult) =
  ## Read and decode live BLAI interrupt state.
  npuInterruptStatusFromIntCfgInto(blaiLoadReg(blaiRegs()[].intCfg), outResult)

proc npuInterruptStatus*(): NpuInterruptStatusResult =
  ## Convenience wrapper for live BLAI interrupt state.
  npuInterruptStatusInto(result)

proc npuCnnWrapperCfgDecodeFromRawInto*(
    generalCfg: uint32,
    outResult: var NpuCnnWrapperCfgDecode) =
  ## Decode the alternate E907 `CNN_BL_CNN_CFG` view of offset zero.
  outResult = default(NpuCnnWrapperCfgDecode)
  outResult.raw = generalCfg
  outResult.lowerConfigBits = generalCfg and CnnWrapperLowerConfigMask
  outResult.interruptClearRequested =
    (generalCfg and CnnWrapperIntClearMask) != 0'u32
  outResult.interruptPending =
    (generalCfg and CnnWrapperIntStatusMask) != 0'u32
  outResult.busResetRequested =
    (generalCfg and CnnWrapperBusResetMask) != 0'u32
  outResult.axiIdle = (generalCfg and CnnWrapperAxiIdleMask) != 0'u32
  outResult.blaiFtableDataBase =
    (generalCfg and BlaiFtableDataBaseMask) shr BlaiFtableDataBaseShift
  outResult.overlapsBlaiFtableDataBase =
    ((CnnWrapperIntClearMask or CnnWrapperIntStatusMask or
      CnnWrapperBusResetMask) and BlaiFtableDataBaseMask) != 0'u32
  outResult.overlapsBlaiAxiReadIdle =
    (CnnWrapperAxiIdleMask and BlaiAxiReadIdleMask) != 0'u32
  outResult.headerSurfaceConflict =
    outResult.overlapsBlaiFtableDataBase and outResult.overlapsBlaiAxiReadIdle
  outResult.valid = true

proc npuCnnWrapperCfgDecodeFromRaw*(
    generalCfg: uint32): NpuCnnWrapperCfgDecode =
  ## Convenience wrapper for the read-only alternate CNN wrapper view.
  npuCnnWrapperCfgDecodeFromRawInto(generalCfg, result)

proc npuCnnWrapperCompletionSurfaceEvidenceInto*(
    generalCfg, intCfg: uint32,
    outResult: var NpuCnnWrapperCompletionSurfaceEvidence) =
  ## Compare `BLAI_INT_CFG[9]` with the alternate E907 CNN status bit.
  outResult = default(NpuCnnWrapperCompletionSurfaceEvidence)
  outResult.generalCfg = generalCfg
  outResult.intCfg = intCfg
  let standard = npuInterruptStatusFromIntCfg(intCfg)
  outResult.standardInterruptPending = standard.interruptPending
  outResult.standardClearRequested = standard.clearRequested
  outResult.standardStatusClear = not standard.interruptPending
  outResult.wrapper = npuCnnWrapperCfgDecodeFromRaw(generalCfg)
  outResult.wrapperCandidatePending = outResult.wrapper.interruptPending
  outResult.wrapperPendingOnly =
    outResult.wrapperCandidatePending and not outResult.standardInterruptPending
  outResult.bothPending =
    outResult.wrapperCandidatePending and outResult.standardInterruptPending
  outResult.candidateConflictsWithFtable =
    outResult.wrapper.overlapsBlaiFtableDataBase
  outResult.candidateConflictsWithStdHeader =
    outResult.wrapper.headerSurfaceConflict
  outResult.readOnlyProbe = true
  outResult.runtimePolicyUnchanged = true
  outResult.valid =
    outResult.wrapper.valid and outResult.readOnlyProbe and
      outResult.runtimePolicyUnchanged

proc npuCnnWrapperCompletionSurfaceEvidence*(
    generalCfg, intCfg: uint32): NpuCnnWrapperCompletionSurfaceEvidence =
  ## Convenience wrapper for alternate CNN completion-surface evidence.
  npuCnnWrapperCompletionSurfaceEvidenceInto(generalCfg, intCfg, result)

proc npuHalCompletionObjdumpEvidenceInto*(
    sourceBaseLui, intCfgOffset, getIntStatusMask, clearIntMask, startMask,
    stopMask, resumeMask: uint32,
    outResult: var NpuHalCompletionObjdumpEvidence) =
  ## Decode objdump-derived SDK HAL completion helper facts.
  outResult = default(NpuHalCompletionObjdumpEvidence)
  outResult.sourceBaseLui = sourceBaseLui
  outResult.baseAddress = sourceBaseLui shl 12
  outResult.intCfgOffset = intCfgOffset
  outResult.getIntStatusMask = getIntStatusMask
  outResult.clearIntMask = clearIntMask
  outResult.startMask = startMask
  outResult.stopMask = stopMask
  outResult.resumeMask = resumeMask
  outResult.baseMatchesBlai =
    outResult.baseAddress == NpuHalObjdumpBlaiBaseAddress and
      outResult.baseAddress == BlaiBase.uint32
  outResult.usesStandardIntCfgOffset =
    intCfgOffset == NpuHalObjdumpIntCfgOffset and
      intCfgOffset == (BlaiIntCfg - BlaiBase).uint32
  outResult.getIntMatchesStatusBit =
    getIntStatusMask == NpuHalObjdumpGetIntStatusMask and
      getIntStatusMask == BlaiInterruptStatusMask
  outResult.clearMatchesIntCfgClearBit =
    clearIntMask == NpuHalObjdumpClearIntMask and
      clearIntMask == BlaiInterruptClearMask
  outResult.startMatchesIntCfgStartBit =
    startMask == NpuHalObjdumpStartMask and startMask == BlaiStartMask
  outResult.stopMatchesIntCfgStopBit =
    stopMask == NpuHalObjdumpStopMask and stopMask == BlaiStopMask
  outResult.resumeMatchesIntCfgResumeBit =
    resumeMask == NpuHalObjdumpResumeMask and resumeMask == BlaiResumeMask
  outResult.wrapperCfgNotUsedForHalCompletion =
    intCfgOffset != (CnnWrapperCfg - BlaiBase).uint32
  outResult.resolvesWrapperHeaderConflict =
    outResult.usesStandardIntCfgOffset and
      outResult.wrapperCfgNotUsedForHalCompletion
  outResult.valid =
    outResult.baseMatchesBlai and outResult.usesStandardIntCfgOffset and
      outResult.getIntMatchesStatusBit and
      outResult.clearMatchesIntCfgClearBit and
      outResult.startMatchesIntCfgStartBit and
      outResult.stopMatchesIntCfgStopBit and
      outResult.resumeMatchesIntCfgResumeBit and
      outResult.resolvesWrapperHeaderConflict

proc npuHalCompletionObjdumpEvidence*(
    sourceBaseLui, intCfgOffset, getIntStatusMask, clearIntMask, startMask,
    stopMask, resumeMask: uint32): NpuHalCompletionObjdumpEvidence =
  ## Convenience wrapper for SDK HAL completion objdump evidence.
  npuHalCompletionObjdumpEvidenceInto(
    sourceBaseLui, intCfgOffset, getIntStatusMask, clearIntMask, startMask,
    stopMask, resumeMask, result)

proc npuRecoveredHalCompletionObjdumpEvidence*():
    NpuHalCompletionObjdumpEvidence =
  ## Evidence from THEAD-aware objdump of cached SDK `bl80x_npu.c`.
  npuHalCompletionObjdumpEvidence(
    NpuHalObjdumpBlaiBaseLui,
    NpuHalObjdumpIntCfgOffset,
    NpuHalObjdumpGetIntStatusMask,
    NpuHalObjdumpClearIntMask,
    NpuHalObjdumpStartMask,
    NpuHalObjdumpStopMask,
    NpuHalObjdumpResumeMask)

proc npuHalNetParamObjdumpEvidenceInto*(
    sourceBaseLui, reluIntCfgOffset, reluMask, tfCfgOffset, tfEnableMask:
      uint32,
    outResult: var NpuHalNetParamObjdumpEvidence) =
  ## Decode objdump-derived SDK HAL network parameter helper facts.
  outResult = default(NpuHalNetParamObjdumpEvidence)
  outResult.sourceBaseLui = sourceBaseLui
  outResult.baseAddress = sourceBaseLui shl 12
  outResult.reluIntCfgOffset = reluIntCfgOffset
  outResult.reluMask = reluMask
  outResult.tfCfgOffset = tfCfgOffset
  outResult.tfEnableMask = tfEnableMask
  outResult.baseMatchesBlai =
    outResult.baseAddress == NpuHalObjdumpBlaiBaseAddress and
      outResult.baseAddress == BlaiBase.uint32
  outResult.reluUsesIntCfgOffset =
    reluIntCfgOffset == NpuHalObjdumpIntCfgOffset and
      reluIntCfgOffset == (BlaiIntCfg - BlaiBase).uint32
  outResult.reluUsesReluNMask =
    reluMask == BlaiReluNMask
  outResult.reluPreservesCommandStatusBits =
    (reluMask and
      (BlaiStartMask or BlaiStopMask or BlaiResumeMask or
       BlaiInterruptClearMask or BlaiInterruptStatusMask)) == 0'u32
  outResult.tfUsesTfCfgOffset =
    tfCfgOffset == NpuHalObjdumpTfCfgOffset and
      tfCfgOffset == (BlaiTfCfg0 - BlaiBase).uint32
  outResult.tfUsesBit31 =
    tfEnableMask == NpuHalObjdumpTfEnableMask and
      tfEnableMask == BlaiTensorflowEnableMask
  outResult.tfPreservesLowerBits =
    (tfEnableMask and 0x7FFF_FFFF'u32) == 0'u32
  outResult.noCompletionEnableInNetParams =
    outResult.reluUsesIntCfgOffset and outResult.reluUsesReluNMask and
      outResult.reluPreservesCommandStatusBits and
      outResult.tfUsesTfCfgOffset and outResult.tfUsesBit31 and
      outResult.tfPreservesLowerBits
  outResult.completionSurfaceStillIntCfgStatus =
    outResult.noCompletionEnableInNetParams and
      NpuHalObjdumpGetIntStatusMask == BlaiInterruptStatusMask
  outResult.valid =
    outResult.baseMatchesBlai and outResult.noCompletionEnableInNetParams and
      outResult.completionSurfaceStillIntCfgStatus

proc npuHalNetParamObjdumpEvidence*(
    sourceBaseLui, reluIntCfgOffset, reluMask, tfCfgOffset, tfEnableMask:
      uint32): NpuHalNetParamObjdumpEvidence =
  ## Convenience wrapper for SDK HAL network parameter objdump evidence.
  npuHalNetParamObjdumpEvidenceInto(
    sourceBaseLui, reluIntCfgOffset, reluMask, tfCfgOffset, tfEnableMask,
    result)

proc npuRecoveredHalNetParamObjdumpEvidence*():
    NpuHalNetParamObjdumpEvidence =
  ## Evidence from THEAD-aware objdump of cached SDK `bl80x_npu.c`.
  npuHalNetParamObjdumpEvidence(
    NpuHalObjdumpBlaiBaseLui,
    NpuHalObjdumpIntCfgOffset,
    BlaiReluNMask,
    NpuHalObjdumpTfCfgOffset,
    NpuHalObjdumpTfEnableMask)

proc npuBlaiInitCfgSdkSequenceEvidenceInto*(
    plan: NpuInitConfigRegisterPlan,
    interruptApi: NpuSdkInterruptApiEvidence,
    binding: NpuInterruptBindingReadiness,
    netParamObjdump: NpuHalNetParamObjdumpEvidence,
    outResult: var NpuBlaiInitCfgSdkSequenceEvidence) =
  ## Compose recovered SDK `blai_npu_initCfg` ordering and route policy.
  outResult = default(NpuBlaiInitCfgSdkSequenceEvidence)
  outResult.registerPlanValid = plan.valid
  outResult.layerSetupRepresented =
    plan.launch.anyLayerBufferWrite and plan.launch.writeInstAddr
  outResult.inputBufferRepresented =
    plan.launch.writeInputBuffer and
      plan.launch.inputBufferAddr == plan.config.inputBufferAddr and
      plan.launch.segmentCount == plan.config.patchSize
  outResult.netParamsRepresented =
    plan.netParams.valid and
      plan.netParams.params.unsignedInput == plan.config.netParams.unsignedInput and
      plan.netParams.params.reluN == plan.config.netParams.reluN and
      plan.netParams.params.tensorflowMode ==
        plan.config.netParams.tensorflowMode
  outResult.interruptApiValid = interruptApi.valid
  outResult.interruptRequestMatchesSdk =
    interruptApi.requestedCnnIrq and interruptApi.priorityTupleRequested and
      plan.interruptRequested and plan.config.interrupt.enable
  outResult.interruptOperationOrderMatchesSdk =
    interruptApi.initOperationCount == 3'u8 and
      interruptApi.initOperations[0] == npuSdkInterruptRegisterHandler and
      interruptApi.initOperations[1] == npuSdkInterruptSetPriority and
      interruptApi.initOperations[2] == npuSdkInterruptEnableIrq and
      not interruptApi.initClearsPending
  outResult.bindingReadinessKnown =
    binding.requested and binding.irqMatchesSdk and
      binding.priorityMatchesSdk and binding.enableRequested
  outResult.activeBindingDeferred =
    plan.interruptDeferred and binding.operationPlan.activeOperationsSuppressed
  outResult.pollingPreserved =
    binding.activeWaitIsPolling and binding.operationPlan.m0PollingPreserved
  outResult.noHiddenCompletionEnable =
    netParamObjdump.valid and netParamObjdump.noCompletionEnableInNetParams
  outResult.initCfgRepresented =
    outResult.registerPlanValid and outResult.layerSetupRepresented and
      outResult.inputBufferRepresented and outResult.netParamsRepresented and
      outResult.interruptApiValid and
      outResult.interruptRequestMatchesSdk and
      outResult.interruptOperationOrderMatchesSdk and
      outResult.bindingReadinessKnown and outResult.activeBindingDeferred and
      outResult.pollingPreserved and outResult.noHiddenCompletionEnable
  outResult.valid = outResult.initCfgRepresented

proc npuBlaiInitCfgSdkSequenceEvidence*(
    plan: NpuInitConfigRegisterPlan,
    interruptApi: NpuSdkInterruptApiEvidence,
    binding: NpuInterruptBindingReadiness,
    netParamObjdump: NpuHalNetParamObjdumpEvidence):
      NpuBlaiInitCfgSdkSequenceEvidence =
  ## Convenience wrapper for SDK `blai_npu_initCfg` boundary evidence.
  npuBlaiInitCfgSdkSequenceEvidenceInto(
    plan, interruptApi, binding, netParamObjdump, result)

proc npuInterruptPending*(): bool =
  npuInterruptStatus().interruptPending

proc npuIntCfgCommandMask*(command: NpuIntCfgCommand): uint32 =
  ## Return the recovered `BLAI_INT_CFG` bit for one SDK command.
  case command
  of npuIntCommandStart:
    BlaiStartMask
  of npuIntCommandResume:
    BlaiResumeMask
  of npuIntCommandStop:
    BlaiStopMask
  of npuIntCommandInterruptClear:
    BlaiInterruptClearMask

proc npuPlanIntCfgCommandInto*(intCfg: uint32,
                               command: NpuIntCfgCommand,
                               outResult: var NpuIntCfgCommandPlan) =
  ## Plan one SDK INT_CFG command write without touching hardware.
  outResult = default(NpuIntCfgCommandPlan)
  outResult.intCfg = intCfg
  outResult.command = command
  outResult.commandMask = npuIntCfgCommandMask(command)
  outResult.encoded = intCfg or outResult.commandMask

proc npuPlanIntCfgCommand*(intCfg: uint32,
                           command: NpuIntCfgCommand): NpuIntCfgCommandPlan =
  ## Convenience wrapper for INT_CFG command planning.
  npuPlanIntCfgCommandInto(intCfg, command, result)

proc npuApplyIntCfgCommandPlan*(plan: NpuIntCfgCommandPlan) =
  ## Apply one planned `BLAI_INT_CFG` command write.
  blaiStoreReg(blaiRegs()[].intCfg, plan.encoded)

proc npuIntCfgWithCommand*(intCfg: uint32,
                           command: NpuIntCfgCommand): uint32 =
  ## Return `intCfg` with one SDK command bit set.
  npuPlanIntCfgCommand(intCfg, command).encoded

proc npuIntCfgWithStart*(intCfg: uint32): uint32 =
  ## Mirror SDK `NPU_Start`: preserve existing INT_CFG fields and set start.
  npuIntCfgWithCommand(intCfg, npuIntCommandStart)

proc npuIntCfgWithResume*(intCfg: uint32): uint32 =
  ## Mirror SDK `NPU_Resume`: preserve existing INT_CFG fields and set resume.
  npuIntCfgWithCommand(intCfg, npuIntCommandResume)

proc npuIntCfgWithStop*(intCfg: uint32): uint32 =
  ## Mirror SDK `NPU_Stop`: preserve existing INT_CFG fields and set stop.
  npuIntCfgWithCommand(intCfg, npuIntCommandStop)

proc npuIntCfgWithInterruptClear*(intCfg: uint32): uint32 =
  ## Mirror SDK `NPU_Clr_Int`: preserve existing INT_CFG fields and set clear.
  npuIntCfgWithCommand(intCfg, npuIntCommandInterruptClear)

proc npuIntCfgSdkCommandEvidenceInto*(
    intCfg: uint32,
    outResult: var NpuIntCfgSdkCommandEvidence) =
  ## Derive aggregate evidence for the SDK INT_CFG command helpers.
  outResult = default(NpuIntCfgSdkCommandEvidence)
  outResult.initialIntCfg = intCfg
  npuPlanIntCfgCommandInto(intCfg, npuIntCommandStart, outResult.start)
  npuPlanIntCfgCommandInto(intCfg, npuIntCommandResume, outResult.resume)
  npuPlanIntCfgCommandInto(intCfg, npuIntCommandStop, outResult.stop)
  npuPlanIntCfgCommandInto(intCfg, npuIntCommandInterruptClear, outResult.clear)
  npuInterruptStatusFromIntCfgInto(intCfg, outResult.getInt)
  outResult.startMatchesSdk =
    outResult.start.commandMask == BlaiStartMask and
      outResult.start.encoded == (intCfg or BlaiStartMask)
  outResult.resumeMatchesSdk =
    outResult.resume.commandMask == BlaiResumeMask and
      outResult.resume.encoded == (intCfg or BlaiResumeMask)
  outResult.stopMatchesSdk =
    outResult.stop.commandMask == BlaiStopMask and
      outResult.stop.encoded == (intCfg or BlaiStopMask)
  outResult.clearMatchesSdk =
    outResult.clear.commandMask == BlaiInterruptClearMask and
      outResult.clear.encoded == (intCfg or BlaiInterruptClearMask)
  outResult.getIntMatchesSdk =
    outResult.getInt.interruptPending ==
      ((intCfg and BlaiInterruptStatusMask) != 0'u32)
  outResult.commandMasksDistinct =
    outResult.start.commandMask != outResult.resume.commandMask and
      outResult.start.commandMask != outResult.stop.commandMask and
      outResult.start.commandMask != outResult.clear.commandMask and
      outResult.resume.commandMask != outResult.stop.commandMask and
      outResult.resume.commandMask != outResult.clear.commandMask and
      outResult.stop.commandMask != outResult.clear.commandMask
  outResult.commandsPreserveReluN =
    (outResult.start.encoded and BlaiReluNMask) == (intCfg and BlaiReluNMask) and
      (outResult.resume.encoded and BlaiReluNMask) ==
        (intCfg and BlaiReluNMask) and
      (outResult.stop.encoded and BlaiReluNMask) ==
        (intCfg and BlaiReluNMask) and
      (outResult.clear.encoded and BlaiReluNMask) ==
        (intCfg and BlaiReluNMask)
  outResult.commandsPreserveInterruptStatus =
    (outResult.start.encoded and BlaiInterruptStatusMask) ==
        (intCfg and BlaiInterruptStatusMask) and
      (outResult.resume.encoded and BlaiInterruptStatusMask) ==
        (intCfg and BlaiInterruptStatusMask) and
      (outResult.stop.encoded and BlaiInterruptStatusMask) ==
        (intCfg and BlaiInterruptStatusMask) and
      (outResult.clear.encoded and BlaiInterruptStatusMask) ==
        (intCfg and BlaiInterruptStatusMask)
  outResult.valid =
    outResult.startMatchesSdk and outResult.resumeMatchesSdk and
      outResult.stopMatchesSdk and outResult.clearMatchesSdk and
      outResult.getIntMatchesSdk and outResult.commandMasksDistinct and
      outResult.commandsPreserveReluN and
      outResult.commandsPreserveInterruptStatus

proc npuIntCfgSdkCommandEvidence*(
    intCfg: uint32): NpuIntCfgSdkCommandEvidence =
  ## Convenience wrapper for SDK INT_CFG command helper evidence.
  npuIntCfgSdkCommandEvidenceInto(intCfg, result)

proc npuInterruptAckRegisterPlanInto*(
    intCfg: uint32,
    outResult: var NpuInterruptAckRegisterPlan) =
  ## Plan SDK `bl_npu_ack_irq` / `NPU_Clr_Int` without touching hardware.
  outResult = default(NpuInterruptAckRegisterPlan)
  outResult.initialIntCfg = intCfg
  npuPlanIntCfgCommandInto(
    intCfg, npuIntCommandInterruptClear, outResult.commandPlan)
  outResult.clearRequested =
    (outResult.commandPlan.encoded and BlaiInterruptClearMask) != 0'u32
  outResult.preservesInterruptStatus =
    (outResult.commandPlan.encoded and BlaiInterruptStatusMask) ==
      (intCfg and BlaiInterruptStatusMask)
  outResult.preservesReluN =
    (outResult.commandPlan.encoded and BlaiReluNMask) ==
      (intCfg and BlaiReluNMask)
  outResult.valid =
    outResult.commandPlan.command == npuIntCommandInterruptClear and
      outResult.commandPlan.commandMask == BlaiInterruptClearMask and
      outResult.clearRequested and outResult.preservesInterruptStatus and
      outResult.preservesReluN

proc npuInterruptAckRegisterPlan*(
    intCfg: uint32): NpuInterruptAckRegisterPlan =
  ## Convenience wrapper for SDK interrupt-ACK register planning.
  npuInterruptAckRegisterPlanInto(intCfg, result)

proc npuApplyInterruptAckRegisterPlan*(plan: NpuInterruptAckRegisterPlan) =
  ## Apply a planned SDK interrupt ACK write.
  doAssert plan.valid
  npuApplyIntCfgCommandPlan(plan.commandPlan)

proc npuCompletionPreStartClearPlanInto*(
    initial: NpuInterruptStatusResult,
    outResult: var NpuCompletionPreStartClearPlan) =
  ## Plan the stale-completion guard needed by the polling wait route.
  outResult = default(NpuCompletionPreStartClearPlan)
  outResult.initial = initial
  outResult.stalePending = initial.interruptPending
  outResult.clearRequired = outResult.stalePending
  npuInterruptAckRegisterPlanInto(initial.intCfg, outResult.clearPlan)
  outResult.valid =
    not initial.clearRequested and
      (not outResult.clearRequired or outResult.clearPlan.valid)

proc npuCompletionPreStartClearPlan*(
    initial: NpuInterruptStatusResult): NpuCompletionPreStartClearPlan =
  ## Convenience wrapper for the SDK-semaphore-equivalent pre-start guard.
  npuCompletionPreStartClearPlanInto(initial, result)

proc npuApplyCompletionPreStartClearPlan*(
    plan: NpuCompletionPreStartClearPlan): bool =
  ## Clear a stale completion bit before a new polling wait, if required.
  doAssert plan.valid
  if plan.clearRequired:
    npuApplyInterruptAckRegisterPlan(plan.clearPlan)
    true
  else:
    false

proc npuPlanStartTransitionInto*(intCfg: uint32,
                                 alreadyStarted: bool,
                                 outResult: var NpuStartTransitionPlan) =
  ## Plan SDK first-start versus later-resume behavior without touching hardware.
  outResult = default(NpuStartTransitionPlan)
  outResult.initialStarted = alreadyStarted
  if alreadyStarted:
    npuPlanIntCfgCommandInto(
      intCfg, npuIntCommandResume, outResult.commandPlan)
    outResult.resumesExistingRun = true
  else:
    npuPlanIntCfgCommandInto(
      intCfg, npuIntCommandStart, outResult.commandPlan)
    outResult.startsFirstRun = true
  outResult.resultingStarted = true
  outResult.valid =
    outResult.resultingStarted and
      (outResult.startsFirstRun xor outResult.resumesExistingRun) and
      ((outResult.startsFirstRun and
          outResult.commandPlan.command == npuIntCommandStart) or
       (outResult.resumesExistingRun and
          outResult.commandPlan.command == npuIntCommandResume))

proc npuPlanStartTransition*(intCfg: uint32,
                             alreadyStarted: bool): NpuStartTransitionPlan =
  ## Convenience wrapper for start/resume transition planning.
  npuPlanStartTransitionInto(intCfg, alreadyStarted, result)

proc npuWrapperStartedState*(started: bool): NpuWrapperStartedState =
  ## Build caller-owned wrapper started-flag state.
  result.started = started

proc npuWrapperStartedApplyPlan*(valid: bool,
                                 resultingStarted: bool):
    NpuWrapperStartedApplyPlan =
  ## Recover a checked wrapper started-flag transition before global mutation.
  if not valid:
    return
  result.stateAfter = npuWrapperStartedState(resultingStarted)
  result.valid = true

proc npuWrapperStartedApplyPlan*(plan: NpuStartTransitionPlan):
    NpuWrapperStartedApplyPlan =
  ## Project a valid start/resume transition into wrapper started state.
  npuWrapperStartedApplyPlan(plan.valid, plan.resultingStarted)

proc npuWrapperStartedApplyPlan*(plan: NpuStopTransitionPlan):
    NpuWrapperStartedApplyPlan =
  ## Project a valid STOP transition into wrapper started state.
  npuWrapperStartedApplyPlan(plan.valid, plan.resultingStarted)

proc npuWrapperStartedState*(plan: NpuWrapperStartedApplyPlan):
    NpuWrapperStartedState =
  ## Project a valid wrapper started apply plan into caller-owned state.
  doAssert plan.valid
  plan.stateAfter

proc npuApplyWrapperStartedState*(state: NpuWrapperStartedState) =
  ## Apply recovered wrapper started state to the SDK-compatible global flag.
  npuHasStarted = state.started

proc npuApplyStartTransitionPlan*(plan: NpuStartTransitionPlan) =
  ## Apply a planned SDK start/resume transition and wrapper-state update.
  doAssert plan.valid
  npuApplyIntCfgCommandPlan(plan.commandPlan)
  let startedApply = npuWrapperStartedApplyPlan(plan)
  doAssert startedApply.valid
  npuApplyWrapperStartedState(npuWrapperStartedState(startedApply))

proc npuPlanStopTransitionInto*(intCfg: uint32,
                                alreadyStarted: bool,
                                outResult: var NpuStopTransitionPlan) =
  ## Plan SDK STOP behavior and wrapper-state clear without touching hardware.
  outResult = default(NpuStopTransitionPlan)
  outResult.initialStarted = alreadyStarted
  npuPlanIntCfgCommandInto(intCfg, npuIntCommandStop, outResult.commandPlan)
  outResult.stopsExecution = true
  outResult.resultingStarted = false
  outResult.valid =
    outResult.stopsExecution and
      outResult.commandPlan.command == npuIntCommandStop and
      not outResult.resultingStarted

proc npuPlanStopTransition*(intCfg: uint32,
                            alreadyStarted: bool): NpuStopTransitionPlan =
  ## Convenience wrapper for STOP transition planning.
  npuPlanStopTransitionInto(intCfg, alreadyStarted, result)

proc blaiNpuStopWrapperEvidenceInto*(
    intCfg: uint32,
    alreadyStarted: bool,
    outResult: var BlaiNpuStopWrapperEvidence) =
  ## Classify SDK `blai_npu_stop`: stop the NPU and return no error.
  outResult = default(BlaiNpuStopWrapperEvidence)
  outResult.initialStarted = alreadyStarted
  npuPlanStopTransitionInto(intCfg, alreadyStarted, outResult.transition)
  outResult.stopCommandIssued =
    outResult.transition.valid and outResult.transition.stopsExecution and
      outResult.transition.commandPlan.command == npuIntCommandStop
  outResult.clearsStarted =
    outResult.transition.valid and not outResult.transition.resultingStarted
  outResult.returnsNoError = true
  outResult.matchesSdk =
    outResult.stopCommandIssued and outResult.clearsStarted and
      outResult.returnsNoError
  outResult.valid = outResult.matchesSdk

proc blaiNpuStopWrapperEvidence*(
    intCfg: uint32,
    alreadyStarted: bool): BlaiNpuStopWrapperEvidence =
  ## Convenience wrapper for recovered SDK `blai_npu_stop` evidence.
  blaiNpuStopWrapperEvidenceInto(intCfg, alreadyStarted, result)

proc npuApplyStopTransitionPlan*(plan: NpuStopTransitionPlan) =
  ## Apply a planned SDK STOP command and clear wrapper start state.
  doAssert plan.valid
  npuApplyIntCfgCommandPlan(plan.commandPlan)
  let startedApply = npuWrapperStartedApplyPlan(plan)
  doAssert startedApply.valid
  npuApplyWrapperStartedState(npuWrapperStartedState(startedApply))

proc npuRuntimeInitEvidenceInto*(
    clock: NpuClockStatusResult,
    reset: NpuResetStatusResult,
    sram: NpuSramStatusResult,
    intCfgSeed: uint32,
    outResult: var NpuRuntimeInitEvidence,
    expectedClockSource: NpuClockSource = npuClk320M,
    expectedClockDivider: uint32 = 0) =
  ## Derive evidence for recovered runtime init register state.
  outResult = default(NpuRuntimeInitEvidence)
  outResult.clockDisabled = not clock.enabled
  outResult.clockSourceKnown = clock.sourceKnown
  outResult.clockSourceMatches =
    clock.sourceKnown and clock.source == expectedClockSource
  outResult.clockDividerMatches = clock.divider == expectedClockDivider
  outResult.resetReleased = reset.resetReleased
  outResult.resetNotAsserted = not reset.resetAsserted
  outResult.sramReleased = sram.blaiSramReleased
  outResult.sramSelected = sram.blaiSramSelected
  outResult.sysramSetSelfCleared = not sram.sysramSetLatched
  outResult.startCommandMatches =
    npuIntCfgWithStart(intCfgSeed) == (intCfgSeed or BlaiStartMask)
  outResult.resumeCommandMatches =
    npuIntCfgWithResume(intCfgSeed) == (intCfgSeed or BlaiResumeMask)
  outResult.stopCommandMatches =
    npuIntCfgWithStop(intCfgSeed) == (intCfgSeed or BlaiStopMask)
  outResult.interruptClearCommandMatches =
    npuIntCfgWithInterruptClear(intCfgSeed) ==
      (intCfgSeed or BlaiInterruptClearMask)
  outResult.clockValid =
    outResult.clockDisabled and outResult.clockSourceKnown and
      outResult.clockSourceMatches and outResult.clockDividerMatches
  outResult.resetValid =
    outResult.resetReleased and outResult.resetNotAsserted
  outResult.sramValid =
    outResult.sramReleased and outResult.sramSelected and
      outResult.sysramSetSelfCleared
  outResult.intCfgCommandsValid =
    outResult.startCommandMatches and outResult.resumeCommandMatches and
      outResult.stopCommandMatches and outResult.interruptClearCommandMatches
  outResult.valid =
    outResult.clockValid and outResult.resetValid and outResult.sramValid and
      outResult.intCfgCommandsValid

proc npuRuntimeInitEvidence*(
    clock: NpuClockStatusResult,
    reset: NpuResetStatusResult,
    sram: NpuSramStatusResult,
    intCfgSeed: uint32,
    expectedClockSource: NpuClockSource = npuClk320M,
    expectedClockDivider: uint32 = 0): NpuRuntimeInitEvidence =
  ## Convenience wrapper for recovered runtime init evidence.
  npuRuntimeInitEvidenceInto(
    clock, reset, sram, intCfgSeed, result, expectedClockSource,
    expectedClockDivider)

proc npuRuntimeInitSdkBoundaryEvidenceInto*(
    plan: NpuRuntimeInitRegisterPlan,
    live: NpuRuntimeInitEvidence,
    outResult: var NpuRuntimeInitSdkBoundaryEvidence) =
  ## Split SDK `bl_npu_init` from local reset/SRAM/clock ownership steps.
  outResult = default(NpuRuntimeInitSdkBoundaryEvidence)
  outResult.planValid = plan.valid
  outResult.liveEvidenceValid = live.valid
  outResult.sdkSelectsClockSource =
    plan.initClockSelect.valid and
      plan.initClockSelect.status.source == npuClk320M
  outResult.sdkPreservesGate = plan.initClockSelect.preservesGate
  outResult.sdkPreservesDivider = plan.initClockSelect.preservesDivider
  outResult.localEnablesClockDuringInit =
    plan.clock.valid and plan.clock.status.enabled and
      plan.clock.status.source == npuClk320M
  outResult.localPulsesReset =
    plan.reset.valid and plan.reset.assertStatus.resetAsserted and
      plan.reset.releaseStatus.resetReleased
  outResult.localReleasesSram =
    plan.sram.valid and plan.sram.latchStatus.blaiSramReleased and
      live.sramReleased
  outResult.localSelectsSram =
    plan.sram.valid and plan.sram.latchStatus.blaiSramSelected and
      live.sramSelected
  outResult.localDisablesClockAfterInit =
    plan.finalClockGate.valid and not plan.finalClockGate.status.enabled and
      live.clockDisabled
  outResult.runtimePolicyDisablesClock =
    plan.runtimeOwnership.initDisablesClock and plan.disablesClock
  outResult.boundaryExplicit =
    outResult.sdkSelectsClockSource and outResult.sdkPreservesGate and
      outResult.sdkPreservesDivider and outResult.localEnablesClockDuringInit and
      outResult.localPulsesReset and outResult.localReleasesSram and
      outResult.localSelectsSram and outResult.localDisablesClockAfterInit and
      outResult.runtimePolicyDisablesClock
  outResult.valid =
    outResult.planValid and outResult.liveEvidenceValid and
      outResult.boundaryExplicit

proc npuRuntimeInitSdkBoundaryEvidence*(
    plan: NpuRuntimeInitRegisterPlan,
    live: NpuRuntimeInitEvidence): NpuRuntimeInitSdkBoundaryEvidence =
  ## Convenience wrapper for runtime-init SDK/local boundary evidence.
  npuRuntimeInitSdkBoundaryEvidenceInto(plan, live, result)

proc npuClearInterrupt*() =
  let intCfg = blaiLoadReg(blaiRegs()[].intCfg)
  npuApplyInterruptAckRegisterPlan(npuInterruptAckRegisterPlan(intCfg))

proc npuWaitForInterruptInto*(timeout: uint32,
                              outResult: var NpuInterruptPollResult) =
  ## Poll for the SDK BLAI completion interrupt status bit with telemetry.
  outResult = default(NpuInterruptPollResult)
  outResult.timeout = timeout
  var remaining = timeout
  while remaining > 0:
    inc outResult.polls
    if npuInterruptPending():
      outResult.interruptObserved = true
      outResult.finalInterruptPending = true
      break
    dec remaining
  if not outResult.interruptObserved:
    outResult.finalInterruptPending = npuInterruptPending()
    outResult.interruptObserved = outResult.finalInterruptPending
  let terminal = npuInterruptPollTerminalPlan(
    timeout, outResult.polls, outResult.interruptObserved,
    outResult.finalInterruptPending)
  outResult.exhausted = terminal.exhausted
  outResult.completedBeforeBudget = terminal.completedBeforeBudget
  outResult.terminalMatchesBudget = terminal.terminalMatchesBudget
  outResult.valid = terminal.valid

proc npuWaitForInterruptResult*(timeout: uint32): NpuInterruptPollResult =
  ## Convenience result-returning wrapper for completion interrupt polling.
  npuWaitForInterruptInto(timeout, result)

proc npuWaitForInterrupt*(timeout: uint32): bool =
  ## Poll for the SDK BLAI completion interrupt status bit.
  npuWaitForInterruptResult(timeout).interruptObserved

proc npuStart*()
proc npuBusyStatusInto*(outResult: var NpuBusyStatusResult)

proc npuWaitForCompletionInto*(
    plan: BlaiNpuCompletionWaitPlan,
    outResult: var BlaiNpuCompletionWaitResult) =
  ## Start/resume BLAI execution and wait for the recovered completion signal.
  ##
  ## The SDK uses an interrupt handler plus an RTOS semaphore here. This pure
  ## Nim boundary captures the same observable state while the local HAL still
  ## polls the recovered interrupt bit.
  outResult = default(BlaiNpuCompletionWaitResult)
  let startPlan = blaiNpuCompletionStartPlan(plan)
  outResult.configured = startPlan.waitPlan.configured
  outResult.timeout = startPlan.waitPlan.timeout
  outResult.clearOnComplete = startPlan.waitPlan.clearOnComplete
  outResult.disableClockOnExit = startPlan.waitPlan.disableClockOnExit
  outResult.statusDecision = startPlan.initialStatus
  outResult.status = outResult.statusDecision.status
  if not startPlan.starts:
    return
  when nimvm:
    discard
  else:
    var preStartInterrupt: NpuInterruptStatusResult
    npuInterruptStatusInto(preStartInterrupt)
    npuCompletionPreStartClearPlanInto(
      preStartInterrupt, outResult.preStartClear)
    doAssert outResult.preStartClear.valid
    outResult.staleInterruptPending =
      outResult.preStartClear.stalePending
    outResult.staleInterruptCleared =
      npuApplyCompletionPreStartClearPlan(outResult.preStartClear)
    var launchSnapshot: NpuRegisterSnapshot
    npuRegisterSnapshotInto(launchSnapshot)
    let launchSnapshotApply = npuRegisterSnapshotCaptureApplyPlan(
      launchSnapshot)
    doAssert launchSnapshotApply.valid
    npuApplyLastLaunchRegisterSnapshotState(
      npuRegisterSnapshotCaptureState(launchSnapshotApply))
    outResult.startTransition =
      npuPlanStartTransition(launchSnapshot.intCfg, npuHasStarted)
    doAssert outResult.startTransition.valid
  npuSetClockEnable(true)
  npuClockStatusInto(outResult.startClock)
  npuStart()
  when nimvm:
    discard
  else:
    outResult.wrapperStartedAfterStart = npuHasStarted
  outResult.started = true
  when nimvm:
    discard
  else:
    var startedSnapshot: NpuRegisterSnapshot
    npuRegisterSnapshotInto(startedSnapshot)
    let startedSnapshotApply = npuRegisterSnapshotCaptureApplyPlan(
      startedSnapshot)
    doAssert startedSnapshotApply.valid
    npuApplyLastStartedRegisterSnapshotState(
      npuRegisterSnapshotCaptureState(startedSnapshotApply))
  npuWaitForInterruptInto(plan.timeout, outResult.poll)
  outResult.interruptObserved = outResult.poll.interruptObserved
  npuInterruptStatusInto(outResult.waitExitInterrupt)
  npuMmAggregateInterruptSnapshotInto(outResult.waitExitMmAggregate)
  npuBusyStatusInto(outResult.waitExitBusy)
  npuClockStatusInto(outResult.waitExitClock)
  blaiNpuCompletionStatusInto(
    plan.configured, outResult.interruptObserved, outResult.statusDecision)
  outResult.status = outResult.statusDecision.status
  let exitPlan =
    blaiNpuCompletionExitPlan(startPlan.waitPlan, outResult.interruptObserved)
  doAssert exitPlan.valid
  if exitPlan.clearInterrupt:
    npuClearInterrupt()
    outResult.interruptCleared = true
  if exitPlan.disableClock:
    npuSetClockEnable(false)
    outResult.clockDisabled = true

proc npuWaitForCompletion*(
    plan: BlaiNpuCompletionWaitPlan): BlaiNpuCompletionWaitResult =
  ## Convenience result-returning wrapper for completion wait state.
  npuWaitForCompletionInto(plan, result)

proc blaiNpuPollingWaitEvidenceInto*(
    completion: BlaiNpuCompletionWaitResult,
    outResult: var BlaiNpuPollingWaitEvidence) =
  ## Classify the terminal reason for a recovered polling completion wait.
  outResult = default(BlaiNpuPollingWaitEvidence)
  let plan = blaiNpuPollingWaitEvidencePlan(completion)
  outResult.terminal = plan.terminal
  outResult.configured = plan.configured
  outResult.pollBudget = plan.pollBudget
  outResult.actualPolls = plan.actualPolls
  outResult.started = plan.started
  outResult.interruptObserved = plan.interruptObserved
  outResult.finalInterruptPending = plan.finalInterruptPending
  outResult.budgetExhausted = plan.budgetExhausted
  outResult.completedBeforeBudget = plan.completedBeforeBudget
  outResult.budgetMatchesPolls = plan.budgetMatchesPolls
  outResult.pollTraceValid = plan.pollTraceValid
  outResult.statusUnsupported = plan.statusUnsupported
  outResult.statusTimedOut = plan.statusTimedOut
  outResult.statusCompleted = plan.statusCompleted
  outResult.terminalMatchesStatus = plan.terminalMatchesStatus
  outResult.valid = plan.valid

proc blaiNpuPollingWaitEvidence*(
    completion: BlaiNpuCompletionWaitResult): BlaiNpuPollingWaitEvidence =
  ## Convenience wrapper for polling wait terminal evidence.
  blaiNpuPollingWaitEvidenceInto(completion, result)

proc blaiNpuCompletionSideEffectEvidenceInto*(
    completion: BlaiNpuCompletionWaitResult,
    outResult: var BlaiNpuCompletionSideEffectEvidence) =
  ## Classify interrupt-clear and clock-gate effects after completion wait exit.
  outResult = default(BlaiNpuCompletionSideEffectEvidence)
  let plan = blaiNpuCompletionSideEffectPlan(completion)
  outResult.path = plan.path
  outResult.configured = plan.configured
  outResult.started = plan.started
  outResult.interruptObserved = plan.interruptObserved
  outResult.clearOnComplete = plan.clearOnComplete
  outResult.disableClockOnExit = plan.disableClockOnExit
  outResult.interruptCleared = plan.interruptCleared
  outResult.clockDisabled = plan.clockDisabled
  outResult.noSideEffects = plan.noSideEffects
  outResult.interruptClearSuppressed = plan.interruptClearSuppressed
  outResult.clockDisabledOnExit = plan.clockDisabledOnExit
  outResult.completedSideEffectsApplied = plan.completedSideEffectsApplied
  outResult.timeoutSideEffectsApplied = plan.timeoutSideEffectsApplied
  outResult.pathMatchesStatus = plan.pathMatchesStatus
  outResult.valid = plan.valid

proc blaiNpuCompletionSideEffectEvidence*(
    completion: BlaiNpuCompletionWaitResult): BlaiNpuCompletionSideEffectEvidence =
  ## Convenience wrapper for wait-exit side-effect evidence.
  blaiNpuCompletionSideEffectEvidenceInto(completion, result)

proc blaiNpuClockExitEvidenceInto*(
    completion: BlaiNpuCompletionWaitResult,
    outResult: var BlaiNpuClockExitEvidence) =
  ## Classify wait-exit clock retention and post-wait clock gating.
  outResult = default(BlaiNpuClockExitEvidence)
  let plan = blaiNpuClockExitPlan(completion)
  outResult.path = plan.path
  outResult.configured = plan.configured
  outResult.started = plan.started
  outResult.disableClockOnExit = plan.disableClockOnExit
  outResult.waitExitClockEnabled = plan.waitExitClockEnabled
  outResult.waitExitClockSourceKnown = plan.waitExitClockSourceKnown
  outResult.waitExitClockSource320M = plan.waitExitClockSource320M
  outResult.waitExitClockDividerZero = plan.waitExitClockDividerZero
  outResult.clockDisabled = plan.clockDisabled
  outResult.statusUnsupported = plan.statusUnsupported
  outResult.statusTimedOut = plan.statusTimedOut
  outResult.statusCompleted = plan.statusCompleted
  outResult.noStartNoClockChange = plan.noStartNoClockChange
  outResult.retainedUntilWaitExit = plan.retainedUntilWaitExit
  outResult.disabledAfterTimeout = plan.disabledAfterTimeout
  outResult.disabledAfterCompletion = plan.disabledAfterCompletion
  outResult.retainedWithoutDisable = plan.retainedWithoutDisable
  outResult.pathMatchesStatus = plan.pathMatchesStatus
  outResult.valid = plan.valid

proc blaiNpuClockExitEvidence*(
    completion: BlaiNpuCompletionWaitResult): BlaiNpuClockExitEvidence =
  ## Convenience wrapper for completion clock-exit evidence.
  blaiNpuClockExitEvidenceInto(completion, result)

proc blaiNpuStartClockEvidenceInto*(
    completion: BlaiNpuCompletionWaitResult,
    outResult: var BlaiNpuStartClockEvidence) =
  ## Prove the recovered clock gate is enabled at the start boundary.
  outResult = default(BlaiNpuStartClockEvidence)
  outResult.configured = completion.configured
  outResult.started = completion.started
  outResult.startClockEnabled = completion.startClock.enabled
  outResult.startClockSourceKnown = completion.startClock.sourceKnown
  outResult.startClockSource320M =
    completion.startClock.source == npuClk320M
  outResult.startClockDividerZero = completion.startClock.divider == 0
  outResult.waitExitClockEnabled = completion.waitExitClock.enabled
  outResult.waitExitClockMatchesStart =
    completion.waitExitClock.enabled == completion.startClock.enabled and
      completion.waitExitClock.sourceKnown == completion.startClock.sourceKnown and
      completion.waitExitClock.source == completion.startClock.source and
      completion.waitExitClock.divider == completion.startClock.divider
  outResult.clockEnabledBeforeStart =
    outResult.configured and outResult.started and outResult.startClockEnabled and
      outResult.startClockSourceKnown and outResult.startClockSource320M and
      outResult.startClockDividerZero
  outResult.valid =
    outResult.clockEnabledBeforeStart and outResult.waitExitClockEnabled and
      outResult.waitExitClockMatchesStart

proc blaiNpuStartClockEvidence*(
    completion: BlaiNpuCompletionWaitResult): BlaiNpuStartClockEvidence =
  ## Convenience wrapper for start-boundary clock evidence.
  blaiNpuStartClockEvidenceInto(completion, result)

proc blaiNpuStartTransitionEvidenceInto*(
    completion: BlaiNpuCompletionWaitResult,
    outResult: var BlaiNpuStartTransitionEvidence) =
  ## Classify the SDK wrapper's first-start/resume choice at the live boundary.
  outResult = default(BlaiNpuStartTransitionEvidence)
  outResult.configured = completion.configured
  outResult.started = completion.started
  outResult.transitionValid = completion.startTransition.valid
  outResult.initialWrapperStarted = completion.startTransition.initialStarted
  outResult.wrapperStartedAfterStart = completion.wrapperStartedAfterStart
  outResult.startsFirstRun = completion.startTransition.startsFirstRun
  outResult.resumesExistingRun = completion.startTransition.resumesExistingRun
  outResult.startCommandSelected =
    completion.startTransition.commandPlan.command == npuIntCommandStart
  outResult.resumeCommandSelected =
    completion.startTransition.commandPlan.command == npuIntCommandResume
  outResult.exactlyOneCommandSelected =
    outResult.startsFirstRun xor outResult.resumesExistingRun
  outResult.wrapperStateUpdated =
    completion.startTransition.resultingStarted and
      outResult.wrapperStartedAfterStart
  outResult.matchesSdk =
    outResult.transitionValid and outResult.exactlyOneCommandSelected and
      ((not outResult.initialWrapperStarted and outResult.startsFirstRun and
          outResult.startCommandSelected) or
       (outResult.initialWrapperStarted and outResult.resumesExistingRun and
          outResult.resumeCommandSelected)) and outResult.wrapperStateUpdated
  outResult.valid =
    outResult.configured and outResult.started and outResult.matchesSdk

proc blaiNpuStartTransitionEvidence*(
    completion: BlaiNpuCompletionWaitResult): BlaiNpuStartTransitionEvidence =
  ## Convenience wrapper for start/resume wrapper transition evidence.
  blaiNpuStartTransitionEvidenceInto(completion, result)

proc blaiNpuInferenceSdkSequenceEvidenceInto*(
    runtime: BlaiNpuRuntimeOwnershipPlan,
    completion: BlaiNpuCompletionWaitResult,
    sideEffects: BlaiNpuCompletionSideEffectEvidence,
    clockExit: BlaiNpuClockExitEvidence,
    outResult: var BlaiNpuInferenceSdkSequenceEvidence) =
  ## Classify the recovered SDK `blai_npu_inference` ordering.
  outResult = default(BlaiNpuInferenceSdkSequenceEvidence)
  outResult.sdkWaitsOnSemaphore =
    runtime.sdkInterruptWait == blaiNpuRuntimeWaitSdkCountingSemaphore
  outResult.activePollsInterrupt =
    runtime.activeInterruptWait == blaiNpuRuntimeWaitBareMetalPolling
  outResult.startIssued = completion.started
  outResult.clockRetainedUntilWaitExit = clockExit.retainedUntilWaitExit
  outResult.waitStarted = completion.started
  outResult.waitSatisfiedByInterrupt = completion.interruptObserved
  outResult.waitStillPending =
    completion.started and completion.statusDecision.timedOut and
      not completion.interruptObserved
  outResult.sdkIrqAckBeforeSemaphore = completion.clearOnComplete
  outResult.interruptAckAppliedOnCompletion =
    completion.interruptObserved and sideEffects.interruptCleared
  outResult.interruptAckDeferredOnTimeout =
    outResult.waitStillPending and sideEffects.interruptClearSuppressed
  outResult.interruptAckOrderRepresented =
    outResult.sdkIrqAckBeforeSemaphore and
      (outResult.interruptAckAppliedOnCompletion or
       outResult.interruptAckDeferredOnTimeout)
  outResult.clockDisabledAfterWait = clockExit.clockDisabled
  outResult.returnsCpuProcess = completion.started
  outResult.sequenceMatchesSdk =
    outResult.sdkWaitsOnSemaphore and outResult.activePollsInterrupt and
      outResult.startIssued and outResult.clockRetainedUntilWaitExit and
      outResult.waitStarted and
      (outResult.waitSatisfiedByInterrupt or outResult.waitStillPending) and
      outResult.interruptAckOrderRepresented and
      outResult.clockDisabledAfterWait and outResult.returnsCpuProcess
  if not outResult.sdkWaitsOnSemaphore or not outResult.activePollsInterrupt:
    outResult.firstBlock = blaiNpuInferenceSdkSequenceRuntime
  elif not outResult.startIssued or not outResult.clockRetainedUntilWaitExit:
    outResult.firstBlock = blaiNpuInferenceSdkSequenceStart
  elif not outResult.waitStarted or
      not (outResult.waitSatisfiedByInterrupt or outResult.waitStillPending):
    outResult.firstBlock = blaiNpuInferenceSdkSequenceWait
  elif not outResult.interruptAckOrderRepresented:
    outResult.firstBlock = blaiNpuInferenceSdkSequenceInterruptAck
  elif not outResult.clockDisabledAfterWait:
    outResult.firstBlock = blaiNpuInferenceSdkSequenceClockExit
  else:
    outResult.firstBlock = blaiNpuInferenceSdkSequenceNoBlock
  outResult.valid =
    outResult.sequenceMatchesSdk and
      outResult.firstBlock == blaiNpuInferenceSdkSequenceNoBlock

proc blaiNpuInferenceSdkSequenceEvidence*(
    runtime: BlaiNpuRuntimeOwnershipPlan,
    completion: BlaiNpuCompletionWaitResult,
    sideEffects: BlaiNpuCompletionSideEffectEvidence,
    clockExit: BlaiNpuClockExitEvidence): BlaiNpuInferenceSdkSequenceEvidence =
  ## Convenience wrapper for recovered `blai_npu_inference` sequence evidence.
  blaiNpuInferenceSdkSequenceEvidenceInto(
    runtime, completion, sideEffects, clockExit, result)

static:
  let sdkInferenceRuntime = blaiNpuRuntimeOwnershipPlan()
  let sdkInferenceTimeoutCompletion = BlaiNpuCompletionWaitResult(
    configured: true,
    timeout: 5,
    clearOnComplete: true,
    disableClockOnExit: true,
    started: true,
    poll: NpuInterruptPollResult(
      timeout: 5, polls: 5, exhausted: true, terminalMatchesBudget: true,
      valid: true),
    waitExitClock: NpuClockStatusResult(
      enabled: true, sourceKnown: true, source: npuClk320M),
    statusDecision: BlaiNpuCompletionStatusResult(
      configured: true, timedOut: true, status: npuTimeout),
    status: npuTimeout,
    clockDisabled: true)
  let sdkInferenceTimeoutSideEffects =
    blaiNpuCompletionSideEffectEvidence(sdkInferenceTimeoutCompletion)
  let sdkInferenceTimeoutClockExit =
    blaiNpuClockExitEvidence(sdkInferenceTimeoutCompletion)
  var sdkInferenceTimeoutInto: BlaiNpuInferenceSdkSequenceEvidence
  blaiNpuInferenceSdkSequenceEvidenceInto(
    sdkInferenceRuntime, sdkInferenceTimeoutCompletion,
    sdkInferenceTimeoutSideEffects, sdkInferenceTimeoutClockExit,
    sdkInferenceTimeoutInto)
  let sdkInferenceTimeout =
    blaiNpuInferenceSdkSequenceEvidence(
      sdkInferenceRuntime, sdkInferenceTimeoutCompletion,
      sdkInferenceTimeoutSideEffects, sdkInferenceTimeoutClockExit)
  doAssert sdkInferenceTimeoutInto == sdkInferenceTimeout
  doAssert sdkInferenceTimeout.valid
  doAssert sdkInferenceTimeout.waitStillPending
  doAssert sdkInferenceTimeout.interruptAckDeferredOnTimeout
  doAssert sdkInferenceTimeout.firstBlock ==
    blaiNpuInferenceSdkSequenceNoBlock
  let sdkInferenceCompletedCompletion = BlaiNpuCompletionWaitResult(
    configured: true,
    timeout: 5,
    clearOnComplete: true,
    disableClockOnExit: true,
    started: true,
    interruptObserved: true,
    poll: NpuInterruptPollResult(
      timeout: 5, polls: 2, interruptObserved: true,
      finalInterruptPending: true, completedBeforeBudget: true,
      terminalMatchesBudget: true, valid: true),
    waitExitClock: NpuClockStatusResult(
      enabled: true, sourceKnown: true, source: npuClk320M),
    statusDecision: BlaiNpuCompletionStatusResult(
      configured: true, interruptObserved: true, completed: true,
      status: npuOk),
    status: npuOk,
    interruptCleared: true,
    clockDisabled: true)
  let sdkInferenceCompleted =
    blaiNpuInferenceSdkSequenceEvidence(
      sdkInferenceRuntime, sdkInferenceCompletedCompletion,
      blaiNpuCompletionSideEffectEvidence(sdkInferenceCompletedCompletion),
      blaiNpuClockExitEvidence(sdkInferenceCompletedCompletion))
  doAssert sdkInferenceCompleted.valid
  doAssert sdkInferenceCompleted.waitSatisfiedByInterrupt
  doAssert sdkInferenceCompleted.interruptAckAppliedOnCompletion
  doAssert not sdkInferenceCompleted.interruptAckDeferredOnTimeout

proc npuStartRaw*() =
  ## Start a preconfigured BLAI instruction stream.
  ##
  ## This low-level helper is recovered from the SDK NPU HAL. Callers must
  ## configure a validated instruction stream before starting execution.
  let intCfg = blaiLoadReg(blaiRegs()[].intCfg)
  npuApplyIntCfgCommandPlan(npuPlanIntCfgCommand(intCfg, npuIntCommandStart))

proc npuResumeRaw*() =
  let intCfg = blaiLoadReg(blaiRegs()[].intCfg)
  npuApplyIntCfgCommandPlan(npuPlanIntCfgCommand(intCfg, npuIntCommandResume))

proc npuStopRaw*() =
  let intCfg = blaiLoadReg(blaiRegs()[].intCfg)
  npuApplyIntCfgCommandPlan(npuPlanIntCfgCommand(intCfg, npuIntCommandStop))

proc npuWrapperStateInto*(started, instructionStreamConfigured: bool,
                          outResult: var NpuWrapperStateResult) =
  ## Project SDK-compatible NPU wrapper globals into typed state.
  outResult = default(NpuWrapperStateResult)
  outResult.started = started
  outResult.instructionStreamConfigured = instructionStreamConfigured
  outResult.runnable = instructionStreamConfigured

proc npuWrapperStateFromFlags*(started, instructionStreamConfigured: bool):
    NpuWrapperStateResult =
  ## Convenience wrapper for pure NPU wrapper-state projection.
  npuWrapperStateInto(started, instructionStreamConfigured, result)

proc npuWrapperStateInto*(outResult: var NpuWrapperStateResult) =
  ## Read the live SDK-compatible NPU wrapper globals as typed state.
  npuWrapperStateInto(
    npuHasStarted, npuHasConfiguredInstructionStream, outResult)

proc npuWrapperState*(): NpuWrapperStateResult =
  ## Convenience wrapper for live NPU wrapper state.
  npuWrapperStateInto(result)

proc npuExecutionStarted*(): bool =
  ## Return the SDK wrapper's remembered start/resume state.
  npuWrapperState().started

proc npuInstructionStreamConfigured*(): bool =
  ## Return whether the compatibility runner has seen a nonzero instruction stream.
  npuWrapperState().instructionStreamConfigured

proc npuStart*() =
  ## Start the first preconfigured BLAI instruction stream, then resume on later
  ## calls until `npuStop` or `npuReset` clears the wrapper state.
  npuApplyStartTransitionPlan(
    npuPlanStartTransition(blaiLoadReg(blaiRegs()[].intCfg), npuHasStarted))

proc npuStop*() =
  ## Stop BLAI execution and reset the SDK-compatible start/resume state.
  npuApplyStopTransitionPlan(
    npuPlanStopTransition(blaiLoadReg(blaiRegs()[].intCfg), npuHasStarted))

proc npuRunConfigured*(timeout: uint32 = 5_000_000): NpuError =
  ## Run a preconfigured BLAI instruction stream and wait for its interrupt.
  ##
  ## This mirrors SDK `blai_npu_inference` but polls the recovered interrupt
  ## status bit instead of depending on FreeRTOS semaphores.
  npuWaitForCompletion(npuPlanCompletionWait(timeout)).status

proc npuRunConfigured*(
    plan: BlaiNpuCompletionWaitPlan): BlaiNpuCompletionWaitResult =
  ## Run a preconfigured BLAI stream using an explicit completion wait plan.
  npuWaitForCompletion(plan)

proc blaiForwardNpuExecuteOutcomeInto*(
    execution: BlaiForwardNpuExecuteResult,
    outResult: var BlaiForwardNpuExecuteOutcome) =
  ## Derive terminal status for one live forward_NPU layer execution.
  outResult = default(BlaiForwardNpuExecuteOutcome)
  outResult.runnable = execution.runnable
  outResult.configurable = execution.configurable
  outResult.cacheFits = execution.cache.fits
  outResult.started = execution.started
  outResult.waitCompleted = execution.completion.statusDecision.completed
  outResult.stopped = execution.stopped
  outResult.status = execution.status
  outResult.completed = outResult.runnable and outResult.configurable and
    outResult.cacheFits and outResult.waitCompleted and outResult.status == npuOk

proc blaiForwardNpuExecuteOutcome*(
    execution: BlaiForwardNpuExecuteResult): BlaiForwardNpuExecuteOutcome =
  ## Convenience wrapper for live forward_NPU layer execution outcome.
  blaiForwardNpuExecuteOutcomeInto(execution, result)

proc blaiExecuteForwardNpuRunInto*(
    plan: BlaiForwardNpuRunPlan,
    waitPlan: BlaiNpuCompletionWaitPlan,
    outResult: var BlaiForwardNpuExecuteResult) =
  ## Apply the recovered `forward_NPU` run plan and execute configured hardware.
  outResult = default(BlaiForwardNpuExecuteResult)
  outResult.runnable = plan.runnable
  outResult.configurable = plan.configurable
  outResult.waitPlan = waitPlan
  outResult.runtimeOwnership = blaiNpuRuntimeOwnershipPlan()
  outResult.status = npuUnsupported
  if not plan.runnable:
    blaiForwardNpuExecuteOutcomeInto(outResult, outResult.outcome)
    outResult.completed = outResult.outcome.completed
    return
  if not plan.configurable:
    outResult.status = npuBusy
    blaiForwardNpuExecuteOutcomeInto(outResult, outResult.outcome)
    outResult.completed = outResult.outcome.completed
    return
  outResult.cache.runnable = plan.runnable
  outResult.cache.configurable = plan.configurable
  outResult.cache.fits = true
  outResult.cache.cacheRangeCount = plan.cacheRangeCount
  for cacheIndex in 0 ..< blaiForwardCacheRangeCount(plan.cacheRangeCount):
    if plan.cacheRanges[cacheIndex].operation == blaiCacheClean:
      let applied = blaiApplyCacheRange(
        plan.layerConfig.inputBufferAddr, plan.cacheRanges[cacheIndex])
      outResult.cache.cacheRanges[cacheIndex] = applied
      if not applied.fits:
        outResult.cache.fits = false
        outResult.status = npuBusy
        blaiForwardNpuExecuteOutcomeInto(outResult, outResult.outcome)
        outResult.completed = outResult.outcome.completed
        return
  when defined(bl808d0) or defined(bl808m0) or defined(bl808lp):
    when nimvm:
      discard
    else:
      outResult.cache.applied = true
  outResult.cacheApplied = outResult.cache.applied
  if not outResult.cache.fits:
    outResult.status = npuBusy
    blaiForwardNpuExecuteOutcomeInto(outResult, outResult.outcome)
    outResult.completed = outResult.outcome.completed
    return
  npuApplyLayerConfig(plan.layerConfig)
  npuWaitForCompletionInto(waitPlan, outResult.completion)
  outResult.started = outResult.completion.started
  outResult.status = outResult.completion.status
  if outResult.started and outResult.runtimeOwnership.forwardRunStopsAfterInference:
    npuStop()
    outResult.stopped = true
    when nimvm:
      discard
    else:
      var postStopSnapshot: NpuRegisterSnapshot
      npuRegisterSnapshotInto(postStopSnapshot)
      let postStopSnapshotApply = npuRegisterSnapshotCaptureApplyPlan(
        postStopSnapshot)
      doAssert postStopSnapshotApply.valid
      let postStopSnapshotState =
        npuRegisterSnapshotCaptureState(postStopSnapshotApply)
      outResult.postStopRegisters = postStopSnapshotState.snapshot
      outResult.postStopRegistersCaptured = postStopSnapshotState.captured
  blaiForwardNpuExecuteOutcomeInto(outResult, outResult.outcome)
  outResult.completed = outResult.outcome.completed
  if not outResult.completed:
    return
  for cacheIndex in 0 ..< blaiForwardCacheRangeCount(plan.cacheRangeCount):
    if plan.cacheRanges[cacheIndex].operation == blaiCacheInvalidate:
      let applied = blaiApplyCacheRange(
        plan.layerConfig.inputBufferAddr, plan.cacheRanges[cacheIndex])
      outResult.cache.cacheRanges[cacheIndex] = applied
      if not applied.fits:
        outResult.cache.fits = false
        outResult.status = npuBusy
        blaiForwardNpuExecuteOutcomeInto(outResult, outResult.outcome)
        outResult.completed = outResult.outcome.completed
        return
  blaiForwardNpuExecuteOutcomeInto(outResult, outResult.outcome)
  outResult.completed = outResult.outcome.completed

proc blaiExecuteForwardNpuRun*(
    plan: BlaiForwardNpuRunPlan,
    waitPlan: BlaiNpuCompletionWaitPlan): BlaiForwardNpuExecuteResult =
  ## Convenience result-returning wrapper for live NPU run execution.
  blaiExecuteForwardNpuRunInto(plan, waitPlan, result)

proc blaiExecuteForwardNpuRun*(
    plan: BlaiForwardNpuRunPlan,
    timeout: uint32 = 5_000_000): BlaiForwardNpuExecuteResult =
  ## Execute a recovered `forward_NPU` run plan with the default wait policy.
  blaiExecuteForwardNpuRun(plan, blaiPlanForwardNpuCompletionWait(plan, timeout))

proc blaiNpuStopAfterInferenceEvidenceInto*(
    execution: BlaiForwardNpuExecuteResult,
    outResult: var BlaiNpuStopAfterInferenceEvidence) =
  ## Classify the recovered `forward_NPU` stop-after-inference cleanup path.
  outResult = default(BlaiNpuStopAfterInferenceEvidence)
  outResult.stopPolicy = execution.runtimeOwnership.forwardRunStopsAfterInference
  outResult.runnable = execution.runnable
  outResult.configurable = execution.configurable
  outResult.started = execution.started
  outResult.completed = execution.completed
  outResult.timedOut = execution.status == npuTimeout
  outResult.stopped = execution.stopped
  outResult.outcomeStopped = execution.outcome.stopped
  if not execution.started:
    outResult.path = blaiNpuStopAfterInferenceNoStart
  elif execution.status == npuTimeout:
    outResult.path = blaiNpuStopAfterInferenceStoppedAfterTimeout
  else:
    outResult.path = blaiNpuStopAfterInferenceStoppedAfterCompletion
  outResult.noStartNoStop =
    not execution.started and not execution.stopped and
      not execution.outcome.stopped
  outResult.stoppedAfterTimeout =
    execution.started and execution.status == npuTimeout and
      execution.runtimeOwnership.forwardRunStopsAfterInference and
      execution.stopped and execution.outcome.stopped
  outResult.stoppedAfterCompletion =
    execution.started and execution.completed and execution.status == npuOk and
      execution.runtimeOwnership.forwardRunStopsAfterInference and
      execution.stopped and execution.outcome.stopped
  outResult.pathMatchesExecution =
    (outResult.path == blaiNpuStopAfterInferenceNoStart and
      outResult.noStartNoStop) or
    (outResult.path == blaiNpuStopAfterInferenceStoppedAfterTimeout and
      outResult.stoppedAfterTimeout) or
    (outResult.path == blaiNpuStopAfterInferenceStoppedAfterCompletion and
      outResult.stoppedAfterCompletion)
  outResult.valid =
    outResult.stopPolicy and outResult.pathMatchesExecution and
      (outResult.noStartNoStop or outResult.stopped)

proc blaiNpuStopAfterInferenceEvidence*(
    execution: BlaiForwardNpuExecuteResult): BlaiNpuStopAfterInferenceEvidence =
  ## Convenience wrapper for stop-after-inference cleanup evidence.
  blaiNpuStopAfterInferenceEvidenceInto(execution, result)

proc blaiNpuPostStopSnapshotEvidenceInto*(
    plan: BlaiForwardNpuRunPlan,
    execution: BlaiForwardNpuExecuteResult,
    outResult: var BlaiNpuPostStopSnapshotEvidence) =
  ## Classify the live BLAI register snapshot captured after `blai_npu_stop`.
  outResult = default(BlaiNpuPostStopSnapshotEvidence)
  outResult.stopped = execution.stopped
  outResult.outcomeStopped = execution.outcome.stopped
  outResult.captured = execution.postStopRegistersCaptured
  npuRegisterSnapshotEvidenceInto(
    execution.postStopRegisters,
    execution.postStopRegistersCaptured,
    plan.layerConfig.buffers.instAddr,
    plan.layerConfig.buffers.weightAddr,
    plan.layerConfig.buffers.biasAddr,
    plan.layerConfig.inputBufferAddr,
    plan.layerConfig.patchSize,
    checkStartBit = false,
    expectedUnsignedInput = plan.layerConfig.firstLayer,
    outResult.snapshot)
  outResult.addressRetained =
    outResult.snapshot.instAddrMatches and outResult.snapshot.weightAddrMatches and
      outResult.snapshot.biasAddrMatches and outResult.snapshot.dataAddrMatches
  outResult.segmentRetained = outResult.snapshot.segmentMatches
  outResult.netRetained = outResult.snapshot.netMatches
  outResult.commandStateKnown =
    outResult.captured and not execution.postStopRegisters.startRequested and
      not execution.postStopRegisters.resumeRequested and
      not execution.postStopRegisters.clearRequested
  outResult.stopCommandRetained = execution.postStopRegisters.stopRequested
  outResult.stopCommandSelfCleared = not execution.postStopRegisters.stopRequested
  outResult.stopCommandTerminalKnown =
    outResult.stopCommandRetained or outResult.stopCommandSelfCleared
  outResult.interruptStillClear = not execution.postStopRegisters.interruptPending
  outResult.engineIdle = not execution.postStopRegisters.busy
  outResult.valid =
    outResult.stopped and outResult.outcomeStopped and outResult.captured and
      outResult.addressRetained and outResult.segmentRetained and
      outResult.netRetained and outResult.commandStateKnown and
      outResult.stopCommandTerminalKnown and outResult.interruptStillClear and
      outResult.engineIdle

proc blaiNpuPostStopSnapshotEvidence*(
    plan: BlaiForwardNpuRunPlan,
    execution: BlaiForwardNpuExecuteResult): BlaiNpuPostStopSnapshotEvidence =
  ## Convenience wrapper for post-stop BLAI register snapshot evidence.
  blaiNpuPostStopSnapshotEvidenceInto(plan, execution, result)

proc blaiNpuPostCompletionCacheEvidenceInto*(
    plan: BlaiForwardNpuRunPlan,
    execution: BlaiForwardNpuExecuteResult,
    outResult: var BlaiNpuPostCompletionCacheEvidence) =
  ## Classify SDK output-cache invalidation ordering after completion wait.
  outResult = default(BlaiNpuPostCompletionCacheEvidence)
  outResult.runnable = execution.runnable
  outResult.configurable = execution.configurable
  outResult.started = execution.started
  outResult.completed = execution.completed
  outResult.timedOut = execution.status == npuTimeout
  for cacheIndex in 0 ..< blaiForwardCacheRangeCount(plan.cacheRangeCount):
    if plan.cacheRanges[cacheIndex].active:
      case plan.cacheRanges[cacheIndex].operation
      of blaiCacheClean:
        inc outResult.plannedCleanCount
      of blaiCacheInvalidate:
        inc outResult.plannedInvalidateCount
  for cacheIndex in 0 ..< blaiForwardCacheRangeCount(execution.cache.cacheRangeCount):
    let applied = execution.cache.cacheRanges[cacheIndex]
    if applied.active and applied.applied:
      case applied.operation
      of blaiCacheClean:
        inc outResult.appliedCleanCount
      of blaiCacheInvalidate:
        inc outResult.appliedInvalidateCount
  if not execution.started:
    outResult.path = blaiNpuPostCompletionCacheNoStart
  elif not execution.completed:
    outResult.path = blaiNpuPostCompletionCacheInvalidateDeferred
  else:
    outResult.path = blaiNpuPostCompletionCacheInvalidateApplied
  outResult.cleanAppliedBeforeWait =
    outResult.plannedCleanCount == outResult.appliedCleanCount
  outResult.invalidateDeferred =
    execution.started and not execution.completed and
      outResult.plannedInvalidateCount > 0'u32 and
      outResult.appliedInvalidateCount == 0'u32
  outResult.invalidateAppliedAfterCompletion =
    execution.completed and
      outResult.plannedInvalidateCount == outResult.appliedInvalidateCount
  outResult.noStartNoCache =
    not execution.started and outResult.appliedCleanCount == 0'u32 and
      outResult.appliedInvalidateCount == 0'u32
  outResult.pathMatchesExecution =
    (outResult.path == blaiNpuPostCompletionCacheNoStart and
      outResult.noStartNoCache) or
    (outResult.path == blaiNpuPostCompletionCacheInvalidateDeferred and
      outResult.cleanAppliedBeforeWait and outResult.invalidateDeferred) or
    (outResult.path == blaiNpuPostCompletionCacheInvalidateApplied and
      outResult.cleanAppliedBeforeWait and
      outResult.invalidateAppliedAfterCompletion)
  outResult.valid = outResult.pathMatchesExecution

proc blaiNpuPostCompletionCacheEvidence*(
    plan: BlaiForwardNpuRunPlan,
    execution: BlaiForwardNpuExecuteResult): BlaiNpuPostCompletionCacheEvidence =
  ## Convenience wrapper for post-completion cache ordering evidence.
  blaiNpuPostCompletionCacheEvidenceInto(plan, execution, result)

proc blaiForwardNpuSdkSequenceEvidenceInto*(
    plan: BlaiForwardNpuRunPlan,
    execution: BlaiForwardNpuExecuteResult,
    stop: BlaiNpuStopAfterInferenceEvidence,
    postCache: BlaiNpuPostCompletionCacheEvidence,
    outResult: var BlaiForwardNpuSdkSequenceEvidence) =
  ## Classify the recovered SDK `forward_NPU` ordering for one live attempt.
  outResult = default(BlaiForwardNpuSdkSequenceEvidence)
  outResult.runConfigurable = plan.configurable and execution.configurable
  outResult.runtimeOwnsExecutionLock =
    execution.runtimeOwnership.forwardRunTakesExecutionLock and
      execution.runtimeOwnership.forwardRunReleasesExecutionLock and
      execution.runtimeOwnership.activeExecutionLock ==
        blaiNpuRuntimeLockBareMetalSingleThread
  outResult.cleanBeforeWait =
    postCache.valid and postCache.cleanAppliedBeforeWait
  outResult.waitStarted = execution.started
  outResult.stopAfterWait = stop.valid and stop.stopped
  outResult.outputInvalidatePlanned =
    postCache.plannedInvalidateCount > 0'u32
  outResult.outputInvalidateAfterCompletion =
    execution.completed and postCache.invalidateAppliedAfterCompletion
  outResult.outputInvalidateDeferredOnTimeout =
    execution.started and execution.status == npuTimeout and
      postCache.invalidateDeferred
  outResult.outputReadbackDeferredOnTimeout =
    outResult.outputInvalidateDeferredOnTimeout and not execution.completed
  outResult.sequenceMatchesSdk =
    outResult.runConfigurable and outResult.runtimeOwnsExecutionLock and
      outResult.cleanBeforeWait and outResult.waitStarted and
      outResult.stopAfterWait and outResult.outputInvalidatePlanned and
      (outResult.outputInvalidateAfterCompletion or
       outResult.outputInvalidateDeferredOnTimeout)
  if not outResult.runConfigurable:
    outResult.firstBlock = blaiForwardNpuSdkSequenceRunPlan
  elif not outResult.runtimeOwnsExecutionLock:
    outResult.firstBlock = blaiForwardNpuSdkSequenceRuntime
  elif not outResult.cleanBeforeWait:
    outResult.firstBlock = blaiForwardNpuSdkSequenceClean
  elif not outResult.waitStarted:
    outResult.firstBlock = blaiForwardNpuSdkSequenceWait
  elif not outResult.stopAfterWait:
    outResult.firstBlock = blaiForwardNpuSdkSequenceStop
  elif not outResult.outputInvalidatePlanned or
      not (outResult.outputInvalidateAfterCompletion or
           outResult.outputInvalidateDeferredOnTimeout):
    outResult.firstBlock = blaiForwardNpuSdkSequenceOutputCache
  else:
    outResult.firstBlock = blaiForwardNpuSdkSequenceNoBlock
  outResult.valid =
    outResult.sequenceMatchesSdk and
      outResult.firstBlock == blaiForwardNpuSdkSequenceNoBlock

proc blaiForwardNpuSdkSequenceEvidence*(
    plan: BlaiForwardNpuRunPlan,
    execution: BlaiForwardNpuExecuteResult,
    stop: BlaiNpuStopAfterInferenceEvidence,
    postCache: BlaiNpuPostCompletionCacheEvidence):
    BlaiForwardNpuSdkSequenceEvidence =
  ## Convenience wrapper for recovered `forward_NPU` sequence evidence.
  blaiForwardNpuSdkSequenceEvidenceInto(
    plan, execution, stop, postCache, result)

proc blaiForwardNpuSdkTailEvidenceInto*(
    plan: BlaiForwardNpuRunPlan,
    execution: BlaiForwardNpuExecuteResult,
    sdkSequence: BlaiForwardNpuSdkSequenceEvidence,
    readback: BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence,
    temporary: BlaiForwardNpuTemporaryWeightBiasBufferResult,
    outResult: var BlaiForwardNpuSdkTailEvidence) =
  ## Classify the recovered SDK `forward_NPU` tail after the wait path.
  outResult = default(BlaiForwardNpuSdkTailEvidence)
  outResult.sdkSequenceValid = sdkSequence.valid
  outResult.runnablePath = plan.runnable
  outResult.weightLayer = plan.weightLayer
  outResult.temporaryPreparedWhenNeeded =
    plan.weightLayer and temporary.prepared and temporary.totalBytes > 0'u32
  outResult.noTemporaryRequired =
    not plan.weightLayer and temporary.totalBytes == 0'u32
  outResult.stopBeforeTail =
    sdkSequence.stopAfterWait and execution.stopped
  outResult.lockReleasedBeforeOutputLoad =
    execution.runtimeOwnership.forwardRunReleasesExecutionLock and
      readback.readbackPlanReady
  outResult.outputLoadPlanned =
    readback.valid and readback.readbackPlanReady and
      readback.primaryOutputActive and readback.outputBytesKnown
  outResult.outputLoadDeferredOnTimeout =
    execution.started and execution.status == npuTimeout and
      readback.readbackDeferredByExecution
  outResult.outputLoadAllowedOnCompletion =
    execution.completed and execution.status == npuOk and
      readback.readbackPlanReady and not readback.readbackDeferredByExecution
  outResult.temporaryFreeAfterOutputLoad =
    outResult.weightLayer and outResult.temporaryPreparedWhenNeeded and
      outResult.outputLoadPlanned
  outResult.noTemporaryFreeWithoutWeightLayer =
    not outResult.weightLayer and outResult.noTemporaryRequired
  outResult.returnsTrueFromRunnableWrapper =
    outResult.runnablePath and outResult.sdkSequenceValid
  outResult.timeoutDoesNotValidateOutput =
    execution.status == npuTimeout and
      outResult.outputLoadDeferredOnTimeout and
      not execution.completed
  outResult.tailMatchesSdk =
    outResult.sdkSequenceValid and outResult.runnablePath and
      (outResult.temporaryPreparedWhenNeeded or outResult.noTemporaryRequired) and
      outResult.stopBeforeTail and outResult.lockReleasedBeforeOutputLoad and
      outResult.outputLoadPlanned and
      (outResult.outputLoadDeferredOnTimeout or
       outResult.outputLoadAllowedOnCompletion) and
      (outResult.temporaryFreeAfterOutputLoad or
       outResult.noTemporaryFreeWithoutWeightLayer) and
      outResult.returnsTrueFromRunnableWrapper
  outResult.valid = outResult.tailMatchesSdk

proc blaiForwardNpuSdkTailEvidence*(
    plan: BlaiForwardNpuRunPlan,
    execution: BlaiForwardNpuExecuteResult,
    sdkSequence: BlaiForwardNpuSdkSequenceEvidence,
    readback: BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence,
    temporary: BlaiForwardNpuTemporaryWeightBiasBufferResult):
      BlaiForwardNpuSdkTailEvidence =
  ## Convenience wrapper for recovered `forward_NPU` tail evidence.
  blaiForwardNpuSdkTailEvidenceInto(
    plan, execution, sdkSequence, readback, temporary, result)

static:
  var sdkSequenceRunPlan = BlaiForwardNpuRunPlan(
    runnable: true,
    bufferFits: true,
    configurable: true,
    cacheRangeCount: 2)
  sdkSequenceRunPlan.cacheRanges[0] =
    BlaiCacheRange(active: true, operation: blaiCacheClean, bytes: 4)
  sdkSequenceRunPlan.cacheRanges[1] =
    BlaiCacheRange(active: true, operation: blaiCacheInvalidate, bytes: 4)
  var sdkSequenceTimeoutExecution = BlaiForwardNpuExecuteResult(
    runnable: true,
    configurable: true,
    started: true,
    status: npuTimeout,
    runtimeOwnership: blaiNpuRuntimeOwnershipPlan(),
    stopped: true,
    cache: BlaiForwardNpuCacheApplyResult(
      cacheRangeCount: 2))
  sdkSequenceTimeoutExecution.cache.cacheRanges[0] =
    BlaiCacheRangeApplyResult(
      active: true, fits: true, applied: true,
      operation: blaiCacheClean, bytes: 4)
  blaiForwardNpuExecuteOutcomeInto(
    sdkSequenceTimeoutExecution, sdkSequenceTimeoutExecution.outcome)
  let sdkSequenceTimeoutStop =
    blaiNpuStopAfterInferenceEvidence(sdkSequenceTimeoutExecution)
  let sdkSequenceTimeoutCache =
    blaiNpuPostCompletionCacheEvidence(
      sdkSequenceRunPlan, sdkSequenceTimeoutExecution)
  var sdkSequenceTimeoutInto: BlaiForwardNpuSdkSequenceEvidence
  blaiForwardNpuSdkSequenceEvidenceInto(
    sdkSequenceRunPlan, sdkSequenceTimeoutExecution, sdkSequenceTimeoutStop,
    sdkSequenceTimeoutCache, sdkSequenceTimeoutInto)
  let sdkSequenceTimeout =
    blaiForwardNpuSdkSequenceEvidence(
      sdkSequenceRunPlan, sdkSequenceTimeoutExecution,
      sdkSequenceTimeoutStop, sdkSequenceTimeoutCache)
  doAssert sdkSequenceTimeoutInto == sdkSequenceTimeout
  doAssert sdkSequenceTimeout.valid
  doAssert sdkSequenceTimeout.cleanBeforeWait
  doAssert sdkSequenceTimeout.stopAfterWait
  doAssert sdkSequenceTimeout.outputInvalidateDeferredOnTimeout
  doAssert sdkSequenceTimeout.outputReadbackDeferredOnTimeout
  doAssert sdkSequenceTimeout.firstBlock == blaiForwardNpuSdkSequenceNoBlock
  let sdkSequenceTimeoutReadback =
    BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence(
      outputBlockedValid: true,
      deferredOutputValid: true,
      outputCacheGateValid: true,
      planRunnable: true,
      primaryOutputActive: true,
      outputBytesKnown: true,
      outputSlotMatchesInvalidate: true,
      outputBytesMatchInvalidate: true,
      outputInvalidatePlanned: true,
      outputInvalidateDeferred: true,
      workspaceOutputNotMoved: true,
      readbackFirstBlocksClear: true,
      readbackPlanReady: true,
      readbackDeferredByExecution: true,
      valid: true)
  let sdkSequenceTimeoutTail =
    blaiForwardNpuSdkTailEvidence(
      sdkSequenceRunPlan, sdkSequenceTimeoutExecution, sdkSequenceTimeout,
      sdkSequenceTimeoutReadback, BlaiForwardNpuTemporaryWeightBiasBufferResult())
  var sdkSequenceTimeoutTailInto: BlaiForwardNpuSdkTailEvidence
  blaiForwardNpuSdkTailEvidenceInto(
    sdkSequenceRunPlan, sdkSequenceTimeoutExecution, sdkSequenceTimeout,
    sdkSequenceTimeoutReadback, BlaiForwardNpuTemporaryWeightBiasBufferResult(),
    sdkSequenceTimeoutTailInto)
  doAssert sdkSequenceTimeoutTailInto == sdkSequenceTimeoutTail
  doAssert sdkSequenceTimeoutTail.valid
  doAssert sdkSequenceTimeoutTail.lockReleasedBeforeOutputLoad
  doAssert sdkSequenceTimeoutTail.outputLoadDeferredOnTimeout
  doAssert sdkSequenceTimeoutTail.timeoutDoesNotValidateOutput
  doAssert sdkSequenceTimeoutTail.returnsTrueFromRunnableWrapper
  var sdkSequenceCompletedExecution = sdkSequenceTimeoutExecution
  sdkSequenceCompletedExecution.completed = true
  sdkSequenceCompletedExecution.status = npuOk
  sdkSequenceCompletedExecution.cache.cacheRanges[1] =
    BlaiCacheRangeApplyResult(
      active: true, fits: true, applied: true,
      operation: blaiCacheInvalidate, bytes: 4)
  blaiForwardNpuExecuteOutcomeInto(
    sdkSequenceCompletedExecution, sdkSequenceCompletedExecution.outcome)
  let sdkSequenceCompletedStop =
    blaiNpuStopAfterInferenceEvidence(sdkSequenceCompletedExecution)
  let sdkSequenceCompletedCache =
    blaiNpuPostCompletionCacheEvidence(
      sdkSequenceRunPlan, sdkSequenceCompletedExecution)
  let sdkSequenceCompleted =
    blaiForwardNpuSdkSequenceEvidence(
      sdkSequenceRunPlan, sdkSequenceCompletedExecution,
      sdkSequenceCompletedStop, sdkSequenceCompletedCache)
  doAssert sdkSequenceCompleted.valid
  doAssert sdkSequenceCompleted.outputInvalidateAfterCompletion
  doAssert not sdkSequenceCompleted.outputReadbackDeferredOnTimeout
  let sdkSequenceCompletedReadback =
    BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence(
      outputBlockedValid: true,
      deferredOutputValid: true,
      outputCacheGateValid: true,
      planRunnable: true,
      primaryOutputActive: true,
      outputBytesKnown: true,
      outputSlotMatchesInvalidate: true,
      outputBytesMatchInvalidate: true,
      outputInvalidatePlanned: true,
      outputInvalidateDeferred: false,
      workspaceOutputNotMoved: false,
      readbackFirstBlocksClear: true,
      readbackPlanReady: true,
      readbackDeferredByExecution: false,
      valid: true)
  let sdkSequenceCompletedTail =
    blaiForwardNpuSdkTailEvidence(
      sdkSequenceRunPlan, sdkSequenceCompletedExecution, sdkSequenceCompleted,
      sdkSequenceCompletedReadback,
      BlaiForwardNpuTemporaryWeightBiasBufferResult())
  doAssert sdkSequenceCompletedTail.valid
  doAssert sdkSequenceCompletedTail.outputLoadAllowedOnCompletion
  doAssert not sdkSequenceCompletedTail.timeoutDoesNotValidateOutput
  var sdkSequenceWeightRunPlan = sdkSequenceRunPlan
  sdkSequenceWeightRunPlan.weightLayer = true
  let sdkSequenceWeightTail =
    blaiForwardNpuSdkTailEvidence(
      sdkSequenceWeightRunPlan, sdkSequenceTimeoutExecution, sdkSequenceTimeout,
      sdkSequenceTimeoutReadback,
      BlaiForwardNpuTemporaryWeightBiasBufferResult(
        weightBytes: 4'u32, biasBytes: 4'u32, totalBytes: 8'u32,
        bufferFits: true, weightFits: true, biasAligned: true,
        biasFits: true, addressRangeFits: true, prepared: true))
  doAssert sdkSequenceWeightTail.valid
  doAssert sdkSequenceWeightTail.temporaryPreparedWhenNeeded
  doAssert sdkSequenceWeightTail.temporaryFreeAfterOutputLoad

proc blaiExecuteForwardModelConfiguredInto*(
    layers: openArray[BlaiCpuInstLayer64],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    outResult: var BlaiForwardModelExecuteResult,
    timeout: uint32 = 5_000_000) =
  ## Execute a prepared model with the recovered live single-layer NPU runner.
  ##
  ## Callers must provide layers whose instruction/weight/DATA workspace has
  ## already been prepared and populated. This proc only sequences recovered
  ## run configuration and live execution.
  outResult = default(BlaiForwardModelExecuteResult)
  outResult.layerCount = blaiOpenArrayLenU32(layers)
  outResult.firstFailedLayer = -1
  outResult.lastCompletedLayer = -1
  var sequence: BlaiForwardModelRunSequencePlan
  blaiPlanForwardModelRunSequenceInto(
    layers, modelResources, workspace, sequence)
  blaiSetForwardModelExecuteRunSequence(sequence, outResult)
  if not outResult.runnable:
    blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
    outResult.firstBlock = outResult.completion.firstBlock
    outResult.allCompleted = outResult.completion.completed
    return
  blaiPrepareForwardWorkspaceCacheInto(workspace, outResult.workspaceCache)
  if not outResult.workspaceCache.fits:
    outResult.failedLayerCount = 1
    outResult.firstFailedLayer = 0
    blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
    outResult.firstBlock = blaiForwardModelExecuteLayerExecution
    outResult.allCompleted = false
    return

  let layerWindow = blaiForwardModelLayerWindow(layers.len)
  if not layerWindow.valid:
    inc outResult.failedLayerCount
    blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
    outResult.firstBlock = outResult.completion.firstBlock
    outResult.allCompleted = outResult.completion.completed
    return
  for layerIndex in 0 ..< layerWindow.count:
    let layerCursor = blaiForwardModelLayerCursor(layerWindow, layerIndex)
    if not layerCursor.valid:
      inc outResult.failedLayerCount
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return
    let layer = layers[layerCursor.layerIndex]
    if layer.npuOn == 0:
      inc outResult.skippedLayerCount
      continue

    let configuredLayerIndex =
      blaiLayerCursorIndexAbi(layerCursor.layerIndex)
    if not configuredLayerIndex.valid:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        let diagnosticLayerIndex = blaiLayerIndexAbi(layerCursor.layerIndex)
        if diagnosticLayerIndex.valid:
          outResult.firstFailedLayer = diagnosticLayerIndex.value
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = blaiForwardModelExecuteLayerExecution
      outResult.allCompleted = outResult.completion.completed
      return

    var runPlan: BlaiForwardNpuRunPlan
    blaiPlanForwardNpuRunInto(
      layer, configuredLayerIndex.value,
      dataBufferBytes = workspace.data.bytes,
      instAddr = workspace.instruction.address,
      dataBufferAddr = workspace.data.address,
      runPlan,
      weightAddr = workspace.weight.address,
      biasAddr = workspace.bias.address)
    if not runPlan.configurable:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        outResult.firstFailedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return

    inc outResult.attemptedLayerCount
    var waitPlan: BlaiNpuCompletionWaitPlan
    blaiPlanForwardNpuCompletionWaitInto(runPlan, waitPlan, timeout)
    var execution: BlaiForwardNpuExecuteResult
    blaiExecuteForwardNpuRunInto(runPlan, waitPlan, execution)
    outResult.lastExecution = execution
    if not execution.completed and not outResult.firstFailedExecutionCaptured:
      outResult.firstFailedExecutionCaptured = true
      outResult.firstFailedExecution = execution
    if execution.completed:
      inc outResult.completedLayerCount
      outResult.lastCompletedLayer =
        blaiLayerIndexValue(layerCursor.layerIndex)
    else:
      inc outResult.failedLayerCount
      if outResult.firstFailedLayer < 0:
        outResult.firstFailedLayer =
          blaiLayerIndexValue(layerCursor.layerIndex)
      blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
      outResult.firstBlock = outResult.completion.firstBlock
      outResult.allCompleted = outResult.completion.completed
      return

  blaiForwardModelExecuteCompletionInto(outResult, outResult.completion)
  outResult.firstBlock = outResult.completion.firstBlock
  outResult.allCompleted = outResult.completion.completed

proc blaiExecuteForwardModelConfigured*(
    layers: openArray[BlaiCpuInstLayer64],
    modelResources: BlaiForwardModelResourcePlan,
    workspace: BlaiForwardModelWorkspacePlan,
    timeout: uint32 = 5_000_000): BlaiForwardModelExecuteResult =
  ## Convenience result-returning wrapper for live configured model execution.
  blaiExecuteForwardModelConfiguredInto(
    layers, modelResources, workspace, result, timeout)

