    timeout: uint32 = 5_000_000): BlaiForwardModelExecuteResult =
  ## Convenience wrapper for explicit-buffer configured execution.
  blaiExecuteForwardModelConfiguredWithLayerBuffersInto(
    layers, modelResources, workspace, layerBuffers, result, timeout)

proc blaiFinishParsedForwardConfiguredWorkspaceFixture(
    outResult: var BlaiParsedForwardConfiguredWorkspaceFixtureResult) =
  outResult.bindingFirstBlock = outResult.binding.firstBlock
  outResult.hardwareAddressFirstBlock =
    outResult.hardwareAddresses.firstBlock
  outResult.inputFirstBlock = outResult.input.firstBlock
  outResult.executionFirstBlock = outResult.execution.firstBlock
  outResult.executionRunSequenceFirstBlock =
    outResult.execution.runSequenceFirstBlock
  outResult.executionRunSequenceReadinessFirstBlock =
    outResult.execution.runSequenceReadinessFirstBlock
  outResult.executionRunSequenceFirstBlockedLayer =
    outResult.execution.runSequenceFirstBlockedLayer
  outResult.executionRunSequenceFirstBlockedRunCaptured =
    outResult.execution.runSequenceFirstBlockedRunCaptured
  outResult.executionRunSequenceFirstBlockedRunConfigFirstBlock =
    outResult.execution.runSequenceFirstBlockedRunConfigFirstBlock
  outResult.executionRunSequenceFirstBlockedRunConfigReadiness =
    outResult.execution.runSequenceFirstBlockedRunConfigReadiness
  outResult.executionSkippedLayerCount =
    outResult.execution.skippedLayerCount
  outResult.executionAttemptedLayerCount =
    outResult.execution.attemptedLayerCount
  outResult.executionCompletedLayerCount =
    outResult.execution.completedLayerCount
  outResult.executionFailedLayerCount =
    outResult.execution.failedLayerCount
  outResult.executionFirstFailedLayer =
    outResult.execution.firstFailedLayer
  outResult.executionFirstFailedCaptured =
    outResult.execution.firstFailedExecutionCaptured
  outResult.executionFirstFailedStarted =
    outResult.execution.firstFailedExecution.started
  outResult.executionFirstFailedStatus =
    outResult.execution.firstFailedExecution.status
  outResult.executionFirstFailedTimedOut =
    outResult.execution.firstFailedExecution.completion.statusDecision.timedOut
  outResult.executionLastStarted =
    outResult.execution.lastExecution.started
  outResult.executionLastCompleted =
    outResult.execution.lastExecution.completed
  outResult.executionLastStatus =
    outResult.execution.lastExecution.status
  outResult.executionLastTimedOut =
    outResult.execution.lastExecution.completion.statusDecision.timedOut
  outResult.executionLastInterruptObserved =
    outResult.execution.lastExecution.completion.interruptObserved
  outResult.outputFirstBlock = outResult.output.firstBlock
  if not outResult.binding.bound:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureBinding
  elif not outResult.hardwareAddresses.ready:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureHardwareAddresses
  elif not outResult.input.moved:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureInput
  elif not outResult.execution.allCompleted:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureExecution
  elif not outResult.output.valid:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureOutput
  else:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureNoBlock
  outResult.valid =
    outResult.firstBlock ==
      blaiParsedForwardConfiguredWorkspaceFixtureNoBlock

proc blaiParsedForwardConfiguredWorkspaceFixtureReadinessInto*(
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    outResult: var BlaiParsedForwardConfiguredWorkspaceFixtureReadiness) =
  ## Derive the public gate summary for parsed configured-live fixtures.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceFixtureReadiness)
  outResult.bound = validation.binding.bound
  outResult.hardwareAddressesReady = validation.hardwareAddresses.ready
  outResult.inputMoved = validation.input.moved
  outResult.executionRunnable = validation.execution.runnable
  outResult.executed = validation.execution.allCompleted
  outResult.outputValid = validation.output.valid
  outResult.outputMatched = validation.output.validation.outputMatched
  outResult.expectedElements = validation.output.expectedElements
  outResult.actualElements = validation.output.actualElements
  outResult.comparedElements = validation.output.comparedElements
  outResult.trailingElements = validation.output.trailingElements
  outResult.lengthMatches = validation.output.lengthMatches
  outResult.mismatchCount = validation.output.mismatchCount
  outResult.firstMismatch = validation.output.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    validation.output.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    validation.output.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch = validation.output.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch = validation.output.actualAtFirstMismatch
  blaiForwardWorkspaceOutputValidationReadinessInto(
    validation.output, outResult.outputReadiness)
  outResult.bindingFirstBlock = validation.bindingFirstBlock
  outResult.hardwareAddressFirstBlock = validation.hardwareAddressFirstBlock
  outResult.inputFirstBlock = validation.inputFirstBlock
  outResult.executionFirstBlock = validation.executionFirstBlock
  outResult.executionRunSequenceFirstBlock =
    validation.execution.runSequenceFirstBlock
  outResult.executionRunSequenceReadinessFirstBlock =
    validation.execution.runSequenceReadinessFirstBlock
  outResult.executionRunSequenceFirstBlockedLayer =
    validation.execution.runSequenceFirstBlockedLayer
  outResult.executionRunSequenceFirstBlockedRunCaptured =
    validation.execution.runSequenceFirstBlockedRunCaptured
  outResult.executionRunSequenceFirstBlockedRunConfigFirstBlock =
    validation.execution.runSequenceFirstBlockedRunConfigFirstBlock
  outResult.executionRunSequenceFirstBlockedRunConfigReadiness =
    validation.execution.runSequenceFirstBlockedRunConfigReadiness
  outResult.executionSkippedLayerCount =
    validation.execution.skippedLayerCount
  outResult.executionAttemptedLayerCount =
    validation.execution.attemptedLayerCount
  outResult.executionCompletedLayerCount =
    validation.execution.completedLayerCount
  outResult.executionFailedLayerCount =
    validation.execution.failedLayerCount
  outResult.executionFirstFailedLayer =
    validation.execution.firstFailedLayer
  outResult.executionFirstFailedCaptured =
    validation.executionFirstFailedCaptured
  outResult.executionFirstFailedStarted =
    validation.executionFirstFailedStarted
  outResult.executionFirstFailedStatus =
    validation.executionFirstFailedStatus
  outResult.executionFirstFailedTimedOut =
    validation.executionFirstFailedTimedOut
  outResult.executionLastStarted =
    validation.executionLastStarted
  outResult.executionLastCompleted =
    validation.executionLastCompleted
  outResult.executionLastStatus =
    validation.executionLastStatus
  outResult.executionLastTimedOut =
    validation.executionLastTimedOut
  outResult.executionLastInterruptObserved =
    validation.executionLastInterruptObserved
  outResult.outputFirstBlock = validation.outputFirstBlock
  if not outResult.bound:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureBinding
  elif not outResult.hardwareAddressesReady:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureHardwareAddresses
  elif not outResult.inputMoved:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureInput
  elif not outResult.executed:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureExecution
  elif not outResult.outputValid:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureOutput
  else:
    outResult.firstBlock =
      blaiParsedForwardConfiguredWorkspaceFixtureNoBlock
  outResult.valid =
    outResult.firstBlock ==
      blaiParsedForwardConfiguredWorkspaceFixtureNoBlock

proc blaiParsedForwardConfiguredWorkspaceFixtureReadiness*(
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult):
    BlaiParsedForwardConfiguredWorkspaceFixtureReadiness =
  ## Convenience wrapper for parsed configured-live fixture readiness.
  blaiParsedForwardConfiguredWorkspaceFixtureReadinessInto(validation, result)

proc blaiParsedForwardConfiguredWorkspaceClassificationEvidenceInto*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    readiness: BlaiParsedForwardConfiguredWorkspaceFixtureReadiness,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceClassificationEvidence) =
  ## Derive evidence for configured-live fixture classification summaries.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceClassificationEvidence)
  outResult.materializationFirstBlockKnown =
    materialization.firstBlock in {
      blaiForwardModelWorkspaceMaterializeNoBlock,
      blaiForwardModelWorkspaceMaterializeLayerStorage,
      blaiForwardModelWorkspaceMaterializeLayer}
  outResult.runSequenceFirstBlockKnown =
    validation.executionRunSequenceFirstBlock in {
      blaiForwardModelRunSequenceNoBlock,
      blaiForwardModelRunSequenceReadiness,
      blaiForwardModelRunSequenceLayerStorage,
      blaiForwardModelRunSequenceRunConfig}
  outResult.runSequenceBlockedCaptureMatches =
    validation.executionRunSequenceFirstBlockedRunCaptured ==
      (validation.executionRunSequenceFirstBlock ==
        blaiForwardModelRunSequenceRunConfig)
  outResult.runSequenceClassificationValid =
    outResult.runSequenceFirstBlockKnown and
      outResult.runSequenceBlockedCaptureMatches
  outResult.readinessRunSequenceMatches =
    readiness.executionRunSequenceFirstBlock ==
      validation.executionRunSequenceFirstBlock and
    readiness.executionRunSequenceFirstBlockedRunCaptured ==
      validation.executionRunSequenceFirstBlockedRunCaptured and
    readiness.executionRunSequenceFirstBlockedLayer ==
      validation.executionRunSequenceFirstBlockedLayer and
    readiness.executionRunSequenceFirstBlockedRunConfigFirstBlock ==
      validation.executionRunSequenceFirstBlockedRunConfigFirstBlock
  outResult.fixtureFirstBlockMatches =
    readiness.firstBlock == validation.firstBlock
  outResult.fixtureFirstBlockKnown =
    validation.firstBlock in {
      blaiParsedForwardConfiguredWorkspaceFixtureBinding,
      blaiParsedForwardConfiguredWorkspaceFixtureHardwareAddresses,
      blaiParsedForwardConfiguredWorkspaceFixtureInput,
      blaiParsedForwardConfiguredWorkspaceFixtureExecution,
      blaiParsedForwardConfiguredWorkspaceFixtureOutput,
      blaiParsedForwardConfiguredWorkspaceFixtureNoBlock}
  outResult.fixtureClassificationValid =
    outResult.fixtureFirstBlockMatches and outResult.fixtureFirstBlockKnown
  outResult.outputClassificationValid =
    (validation.valid and validation.output.valid) or
      ((not validation.valid) and
        validation.output.valid ==
          (validation.firstBlock ==
            blaiParsedForwardConfiguredWorkspaceFixtureOutput))
  outResult.materializationValid = outResult.materializationFirstBlockKnown
  outResult.runSequenceValid =
    outResult.runSequenceClassificationValid and
      outResult.readinessRunSequenceMatches
  outResult.fixtureValid =
    outResult.fixtureClassificationValid and
      outResult.outputClassificationValid
  outResult.valid =
    outResult.materializationValid and outResult.runSequenceValid and
      outResult.fixtureValid

proc blaiParsedForwardConfiguredWorkspaceClassificationEvidence*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    readiness: BlaiParsedForwardConfiguredWorkspaceFixtureReadiness,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult):
    BlaiParsedForwardConfiguredWorkspaceClassificationEvidence =
  ## Convenience wrapper for configured-live fixture classification evidence.
  blaiParsedForwardConfiguredWorkspaceClassificationEvidenceInto(
    materialization, readiness, validation, result)

proc blaiParsedForwardConfiguredWorkspaceActiveClassificationEvidenceInto*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    readiness: BlaiParsedForwardConfiguredWorkspaceFixtureReadiness,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    classification: BlaiParsedForwardConfiguredWorkspaceClassificationEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveClassificationEvidence) =
  ## Derive focused active-fixture classification evidence for the live path
  ## that materializes, configures, starts, then terminates at execution wait.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveClassificationEvidence)
  outResult.materializationNoBlock =
    materialization.firstBlock == blaiForwardModelWorkspaceMaterializeNoBlock
  outResult.runSequenceNoBlock =
    validation.executionRunSequenceFirstBlock ==
      blaiForwardModelRunSequenceNoBlock
  outResult.runSequenceNotBlocked =
    not validation.executionRunSequenceFirstBlockedRunCaptured
  outResult.readinessRunSequenceNoBlock =
    readiness.executionRunSequenceFirstBlock ==
      blaiForwardModelRunSequenceNoBlock
  outResult.fixtureExecutionBlock =
    validation.firstBlock ==
      blaiParsedForwardConfiguredWorkspaceFixtureExecution
  outResult.readinessFixtureExecutionBlock =
    readiness.firstBlock ==
      blaiParsedForwardConfiguredWorkspaceFixtureExecution
  outResult.outputDeferred =
    not validation.output.valid and
      validation.firstBlock ==
        blaiParsedForwardConfiguredWorkspaceFixtureExecution
  outResult.classificationValid = classification.valid
  outResult.valid =
    outResult.materializationNoBlock and outResult.runSequenceNoBlock and
      outResult.runSequenceNotBlocked and
      outResult.readinessRunSequenceNoBlock and
      outResult.fixtureExecutionBlock and
      outResult.readinessFixtureExecutionBlock and
      outResult.outputDeferred and outResult.classificationValid

proc blaiParsedForwardConfiguredWorkspaceActiveClassificationEvidence*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    readiness: BlaiParsedForwardConfiguredWorkspaceFixtureReadiness,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    classification: BlaiParsedForwardConfiguredWorkspaceClassificationEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveClassificationEvidence =
  ## Convenience wrapper for active configured-live classification evidence.
  blaiParsedForwardConfiguredWorkspaceActiveClassificationEvidenceInto(
    materialization, readiness, validation, classification, result)

proc blaiParsedForwardConfiguredWorkspaceFixtureGateSnapshotInto*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    outResult: var BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot) =
  ## Derive one typed gate snapshot for materialize-then-configured-live tests.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot)
  outResult.materialized = materialization.allReady
  outResult.bound = validation.binding.bound
  outResult.hardwareAddressesReady = validation.hardwareAddresses.ready
  outResult.inputMoved = validation.input.moved
  outResult.runSequenceReady =
    validation.executionRunSequenceFirstBlock ==
      blaiForwardModelRunSequenceNoBlock
  outResult.executionCompleted = validation.execution.allCompleted
  outResult.outputValid = validation.output.valid
  outResult.outputMatched = validation.output.validation.outputMatched
  outResult.valid = validation.valid
  outResult.materializationFirstBlock = materialization.firstBlock
  outResult.bindingFirstBlock = validation.bindingFirstBlock
  outResult.hardwareAddressFirstBlock = validation.hardwareAddressFirstBlock
  outResult.inputFirstBlock = validation.inputFirstBlock
  outResult.executionFirstBlock = validation.executionFirstBlock
  outResult.runSequenceFirstBlock =
    validation.executionRunSequenceFirstBlock
  outResult.runSequenceReadinessFirstBlock =
    validation.executionRunSequenceReadinessFirstBlock
  outResult.runSequenceFirstBlockedLayer =
    validation.executionRunSequenceFirstBlockedLayer
  outResult.runSequenceFirstBlockedRunCaptured =
    validation.executionRunSequenceFirstBlockedRunCaptured
  outResult.runSequenceFirstBlockedRunConfigFirstBlock =
    validation.executionRunSequenceFirstBlockedRunConfigFirstBlock
  outResult.runSequenceFirstBlockedRunConfigReadiness =
    validation.executionRunSequenceFirstBlockedRunConfigReadiness
  outResult.workspaceCache = validation.execution.workspaceCache
  outResult.lastExecutionCache = validation.execution.lastExecution.cache
  outResult.launchRegistersCaptured = npuLastLaunchRegisterSnapshotCaptured()
  if outResult.launchRegistersCaptured:
    npuLastLaunchRegisterSnapshotInto(outResult.launchRegisters)
  outResult.startedRegistersCaptured = npuLastStartedRegisterSnapshotCaptured()
  if outResult.startedRegistersCaptured:
    npuLastStartedRegisterSnapshotInto(outResult.startedRegisters)
  outResult.outputFirstBlock = validation.outputFirstBlock
  outResult.attemptedLayerCount = validation.executionAttemptedLayerCount
  outResult.completedLayerCount = validation.executionCompletedLayerCount
  outResult.failedLayerCount = validation.executionFailedLayerCount
  outResult.firstFailedLayer = validation.executionFirstFailedLayer
  outResult.firstFailedExecutionCaptured =
    validation.execution.firstFailedExecutionCaptured
  outResult.firstFailedExecutionStarted =
    validation.execution.firstFailedExecution.started
  outResult.firstFailedExecutionStatus =
    validation.execution.firstFailedExecution.status
  outResult.firstFailedExecutionTimedOut =
    validation.execution.firstFailedExecution.completion.statusDecision.timedOut
  outResult.firstFailedExecutionWaitPlan =
    validation.execution.firstFailedExecution.waitPlan
  outResult.firstFailedExecutionWaitExitInterrupt =
    validation.execution.firstFailedExecution.completion.waitExitInterrupt
  outResult.firstFailedExecutionWaitExitMmAggregate =
    validation.execution.firstFailedExecution.completion.waitExitMmAggregate
  outResult.firstFailedExecutionWaitExitBusy =
    validation.execution.firstFailedExecution.completion.waitExitBusy
  outResult.firstFailedExecutionWaitExitClock =
    validation.execution.firstFailedExecution.completion.waitExitClock
  outResult.firstFailedExecutionStatusDecision =
    validation.execution.firstFailedExecution.completion.statusDecision
  outResult.firstFailedExecutionInterruptCleared =
    validation.execution.firstFailedExecution.completion.interruptCleared
  outResult.firstFailedExecutionClockDisabled =
    validation.execution.firstFailedExecution.completion.clockDisabled
  outResult.lastExecutionStarted = validation.execution.lastExecution.started
  outResult.lastExecutionCompleted =
    validation.execution.lastExecution.completed
  outResult.lastExecutionStatus = validation.execution.lastExecution.status
  outResult.lastExecutionTimedOut =
    validation.execution.lastExecution.completion.statusDecision.timedOut
  outResult.lastExecutionInterruptObserved =
    validation.execution.lastExecution.completion.interruptObserved
  outResult.lastExecutionWaitPlan = validation.execution.lastExecution.waitPlan
  outResult.lastExecutionWaitExitInterrupt =
    validation.execution.lastExecution.completion.waitExitInterrupt
  outResult.lastExecutionWaitExitMmAggregate =
    validation.execution.lastExecution.completion.waitExitMmAggregate
  outResult.lastExecutionWaitExitBusy =
    validation.execution.lastExecution.completion.waitExitBusy
  outResult.lastExecutionWaitExitClock =
    validation.execution.lastExecution.completion.waitExitClock
  outResult.lastExecutionStatusDecision =
    validation.execution.lastExecution.completion.statusDecision
  outResult.lastExecutionInterruptCleared =
    validation.execution.lastExecution.completion.interruptCleared
  outResult.lastExecutionClockDisabled =
    validation.execution.lastExecution.completion.clockDisabled
  outResult.expectedElements = validation.output.expectedElements
  outResult.actualElements = validation.output.actualElements
  outResult.comparedElements = validation.output.comparedElements
  outResult.trailingElements = validation.output.trailingElements
  outResult.lengthMatches = validation.output.lengthMatches
  outResult.mismatchCount = validation.output.mismatchCount
  outResult.firstMismatch = validation.output.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    validation.output.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    validation.output.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch = validation.output.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch = validation.output.actualAtFirstMismatch
  if not outResult.bound:
    outResult.terminalGate =
      blaiParsedConfiguredWorkspaceGateBinding
  elif not outResult.materialized:
    outResult.terminalGate =
      blaiParsedConfiguredWorkspaceGateMaterialization
  elif not outResult.hardwareAddressesReady:
    outResult.terminalGate =
      blaiParsedConfiguredWorkspaceGateHardwareAddresses
  elif not outResult.inputMoved:
    outResult.terminalGate =
      blaiParsedConfiguredWorkspaceGateInput
  elif not outResult.runSequenceReady:
    outResult.terminalGate =
      blaiParsedConfiguredWorkspaceGateRunSequence
  elif not outResult.executionCompleted:
    outResult.terminalGate =
      blaiParsedConfiguredWorkspaceGateExecution
  elif not outResult.outputValid:
    outResult.terminalGate =
      blaiParsedConfiguredWorkspaceGateOutput
  else:
    outResult.terminalGate =
      blaiParsedConfiguredWorkspaceGateComplete

proc blaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot*(
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult):
    BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot =
  ## Convenience wrapper for materialize-then-configured-live gate evidence.
  blaiParsedForwardConfiguredWorkspaceFixtureGateSnapshotInto(
    materialization, validation, result)

proc blaiParsedForwardConfiguredWorkspaceSnapshotCoherenceEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceSnapshotCoherenceEvidence) =
  ## Derive evidence that a gate snapshot mirrors its source fixture state.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceSnapshotCoherenceEvidence)
  outResult.materializedMatches =
    snapshot.materialized == materialization.allReady
  outResult.boundMatches = snapshot.bound == validation.binding.bound
  outResult.hardwareAddressesReadyMatches =
    snapshot.hardwareAddressesReady == validation.hardwareAddresses.ready
  outResult.inputMovedMatches = snapshot.inputMoved == validation.input.moved
  outResult.runSequenceReadyMatches =
    snapshot.runSequenceReady ==
      (validation.executionRunSequenceFirstBlock ==
        blaiForwardModelRunSequenceNoBlock)
  outResult.executionCompletedMatches =
    snapshot.executionCompleted == validation.execution.allCompleted
  outResult.outputValidMatches = snapshot.outputValid == validation.output.valid
  outResult.outputMatchedMatches =
    snapshot.outputMatched == validation.output.validation.outputMatched
  outResult.stateMirrorsValid =
    outResult.materializedMatches and outResult.boundMatches and
      outResult.hardwareAddressesReadyMatches and outResult.inputMovedMatches and
      outResult.runSequenceReadyMatches and outResult.executionCompletedMatches and
      outResult.outputValidMatches and outResult.outputMatchedMatches
  outResult.materializationFirstBlockMatches =
    snapshot.materializationFirstBlock == materialization.firstBlock
  outResult.executionFirstBlockMatches =
    snapshot.executionFirstBlock == validation.executionFirstBlock
  outResult.runSequenceFirstBlockMatches =
    snapshot.runSequenceFirstBlock == validation.executionRunSequenceFirstBlock
  outResult.outputFirstBlockMatches =
    snapshot.outputFirstBlock == validation.outputFirstBlock
  outResult.blockMirrorsValid =
    outResult.materializationFirstBlockMatches and
      outResult.executionFirstBlockMatches and
      outResult.runSequenceFirstBlockMatches and
      outResult.outputFirstBlockMatches
  outResult.firstFailedExecutionCapturedMatches =
    snapshot.firstFailedExecutionCaptured ==
      validation.execution.firstFailedExecutionCaptured
  outResult.lastExecutionStartedMatches =
    snapshot.lastExecutionStarted == validation.execution.lastExecution.started
  outResult.lastExecutionStatusMatches =
    snapshot.lastExecutionStatus == validation.execution.lastExecution.status
  outResult.executionMirrorsValid =
    outResult.firstFailedExecutionCapturedMatches and
      outResult.lastExecutionStartedMatches and
      outResult.lastExecutionStatusMatches
  outResult.coherent =
    outResult.stateMirrorsValid and outResult.blockMirrorsValid and
      outResult.executionMirrorsValid
  outResult.valid = outResult.coherent

proc blaiParsedForwardConfiguredWorkspaceSnapshotCoherenceEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    materialization: BlaiForwardModelWorkspaceMaterializeResult,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult):
    BlaiParsedForwardConfiguredWorkspaceSnapshotCoherenceEvidence =
  ## Convenience wrapper for gate snapshot coherence evidence.
  blaiParsedForwardConfiguredWorkspaceSnapshotCoherenceEvidenceInto(
    snapshot, materialization, validation, result)

proc blaiParsedForwardConfiguredWorkspaceSnapshotOutputEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    outResult: var BlaiParsedForwardConfiguredWorkspaceSnapshotOutputEvidence) =
  ## Derive evidence for snapshot output counters and mismatch bytes.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceSnapshotOutputEvidence)
  outResult.attemptedLayerCountMatches =
    snapshot.attemptedLayerCount == validation.executionAttemptedLayerCount
  outResult.completedLayerCountMatches =
    snapshot.completedLayerCount == validation.executionCompletedLayerCount
  outResult.failedLayerCountMatches =
    snapshot.failedLayerCount == validation.executionFailedLayerCount
  outResult.firstFailedLayerMatches =
    snapshot.firstFailedLayer == validation.executionFirstFailedLayer
  outResult.expectedElementsMatches =
    snapshot.expectedElements == validation.output.expectedElements
  outResult.actualElementsMatches =
    snapshot.actualElements == validation.output.actualElements
  outResult.comparedElementsMatches =
    snapshot.comparedElements == validation.output.comparedElements
  outResult.trailingElementsMatches =
    snapshot.trailingElements == validation.output.trailingElements
  outResult.lengthMatchesMatches =
    snapshot.lengthMatches == validation.output.lengthMatches
  outResult.mismatchCountMatches =
    snapshot.mismatchCount == validation.output.mismatchCount
  outResult.firstMismatchMatches =
    snapshot.firstMismatch == validation.output.firstMismatch
  outResult.expectedPresentAtFirstMismatchMatches =
    snapshot.expectedPresentAtFirstMismatch ==
      validation.output.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatchMatches =
    snapshot.actualPresentAtFirstMismatch ==
      validation.output.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatchMatches =
    snapshot.expectedAtFirstMismatch == validation.output.expectedAtFirstMismatch
  outResult.actualAtFirstMismatchMatches =
    snapshot.actualAtFirstMismatch == validation.output.actualAtFirstMismatch
  outResult.countersValid =
    outResult.attemptedLayerCountMatches and
      outResult.completedLayerCountMatches and
      outResult.failedLayerCountMatches and
      outResult.firstFailedLayerMatches and
      outResult.expectedElementsMatches and outResult.actualElementsMatches and
      outResult.comparedElementsMatches and
      outResult.trailingElementsMatches and outResult.lengthMatchesMatches and
      outResult.mismatchCountMatches and outResult.firstMismatchMatches
  outResult.mismatchBytesValid =
    outResult.expectedPresentAtFirstMismatchMatches and
      outResult.actualPresentAtFirstMismatchMatches and
      outResult.expectedAtFirstMismatchMatches and
      outResult.actualAtFirstMismatchMatches
  outResult.valid = outResult.countersValid and outResult.mismatchBytesValid

proc blaiParsedForwardConfiguredWorkspaceSnapshotOutputEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult):
    BlaiParsedForwardConfiguredWorkspaceSnapshotOutputEvidence =
  ## Convenience wrapper for snapshot output counter/mismatch evidence.
  blaiParsedForwardConfiguredWorkspaceSnapshotOutputEvidenceInto(
    snapshot, validation, result)

proc blaiParsedForwardConfiguredWorkspaceDeferredOutputEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    outputEvidence: BlaiParsedForwardConfiguredWorkspaceSnapshotOutputEvidence,
    outResult: var BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence) =
  ## Derive evidence that the active fixture deferred output validation.
  outResult = default(BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence)
  outResult.fixtureExecutionGate =
    validation.firstBlock ==
      blaiParsedForwardConfiguredWorkspaceFixtureExecution
  outResult.executionIncomplete = not snapshot.executionCompleted
  outResult.outputInvalid = not snapshot.outputValid and not validation.output.valid
  outResult.outputUnmatched =
    not snapshot.outputMatched and not validation.output.validation.outputMatched
  outResult.zeroExpectedElements = snapshot.expectedElements == 0'u32
  outResult.zeroActualElements = snapshot.actualElements == 0'u32
  outResult.zeroComparedElements = snapshot.comparedElements == 0'u32
  outResult.zeroTrailingElements = snapshot.trailingElements == 0'u32
  outResult.zeroMismatchCount = snapshot.mismatchCount == 0'u32
  outResult.noFirstMismatch =
    snapshot.mismatchCount == 0'u32 or snapshot.firstMismatch < 0
  outResult.noMismatchBytes =
    not snapshot.expectedPresentAtFirstMismatch and
      not snapshot.actualPresentAtFirstMismatch
  outResult.mirrorsValid = outputEvidence.valid
  outResult.valid =
    outResult.fixtureExecutionGate and outResult.executionIncomplete and
      outResult.outputInvalid and outResult.outputUnmatched and
      outResult.zeroExpectedElements and outResult.zeroActualElements and
      outResult.zeroComparedElements and outResult.zeroTrailingElements and
      outResult.zeroMismatchCount and outResult.noFirstMismatch and
      outResult.noMismatchBytes and outResult.mirrorsValid

proc blaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    outputEvidence: BlaiParsedForwardConfiguredWorkspaceSnapshotOutputEvidence):
    BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence =
  ## Convenience wrapper for active deferred-output evidence.
  blaiParsedForwardConfiguredWorkspaceDeferredOutputEvidenceInto(
    snapshot, validation, outputEvidence, result)

proc blaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidenceInto*(
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    readiness: BlaiParsedForwardConfiguredWorkspaceFixtureReadiness,
    deferredOutput: BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence) =
  ## Derive focused evidence that output validation is blocked by execution.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence)
  outResult.fixtureExecutionGate =
    validation.firstBlock ==
      blaiParsedForwardConfiguredWorkspaceFixtureExecution
  outResult.readinessExecutionGate =
    readiness.firstBlock ==
      blaiParsedForwardConfiguredWorkspaceFixtureExecution
  outResult.outputInvalid = not validation.output.valid and not readiness.outputValid
  outResult.outputUnmatched =
    not validation.output.validation.outputMatched and not readiness.outputMatched
  outResult.outputReadinessInvalid = not readiness.outputReadiness.valid
  outResult.workspaceOutputNotMoved =
    not readiness.outputReadiness.workspaceOutputMoved
  outResult.workspaceOutputFirstBlockNone =
    readiness.outputReadiness.workspaceOutputFirstBlock ==
      blaiForwardWorkspaceTensorIoNoBlock
  outResult.validationFirstBlockNone =
    readiness.outputReadiness.validationFirstBlock ==
      blaiForwardModelOutputValidationNoBlock
  outResult.modelValidationFirstBlockNone =
    readiness.outputReadiness.validation.firstBlock ==
      blaiForwardModelOutputValidationNoBlock
  outResult.zeroCounters =
    readiness.outputReadiness.expectedElements == 0'u32 and
      readiness.outputReadiness.actualElements == 0'u32 and
      readiness.outputReadiness.comparedElements == 0'u32 and
      readiness.outputReadiness.trailingElements == 0'u32 and
      readiness.outputReadiness.mismatchCount == 0'u32
  outResult.noMismatch =
    (readiness.outputReadiness.mismatchCount == 0'u32 or
      readiness.outputReadiness.firstMismatch < 0) and
      not readiness.outputReadiness.expectedPresentAtFirstMismatch and
      not readiness.outputReadiness.actualPresentAtFirstMismatch
  outResult.deferredOutputValid = deferredOutput.valid
  outResult.valid =
    outResult.fixtureExecutionGate and outResult.readinessExecutionGate and
      outResult.outputInvalid and outResult.outputUnmatched and
      outResult.outputReadinessInvalid and outResult.workspaceOutputNotMoved and
      outResult.workspaceOutputFirstBlockNone and
      outResult.validationFirstBlockNone and
      outResult.modelValidationFirstBlockNone and outResult.zeroCounters and
      outResult.noMismatch and outResult.deferredOutputValid

proc blaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence*(
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    readiness: BlaiParsedForwardConfiguredWorkspaceFixtureReadiness,
    deferredOutput: BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence =
  ## Convenience wrapper for active output-blocked evidence.
  blaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidenceInto(
    validation, readiness, deferredOutput, result)

proc blaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidenceInto*(
    outputBlocked: BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence,
    deferredOutput: BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence,
    postCompletionCache: BlaiNpuPostCompletionCacheEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidence) =
  ## Tie deferred output validation to deferred post-wait output invalidation.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidence)
  outResult.outputBlockedValid = outputBlocked.valid
  outResult.deferredOutputValid = deferredOutput.valid
  outResult.postCompletionCacheValid = postCompletionCache.valid
  outResult.outputInvalid =
    outputBlocked.outputInvalid and deferredOutput.outputInvalid
  outResult.workspaceOutputNotMoved = outputBlocked.workspaceOutputNotMoved
  outResult.invalidatePlanned =
    postCompletionCache.plannedInvalidateCount > 0'u32
  outResult.invalidateDeferred = postCompletionCache.invalidateDeferred
  outResult.noInvalidateApplied =
    postCompletionCache.appliedInvalidateCount == 0'u32
  outResult.gateMatchesCache =
    outResult.outputInvalid and outResult.workspaceOutputNotMoved and
      outResult.invalidatePlanned and outResult.invalidateDeferred and
      outResult.noInvalidateApplied
  outResult.valid =
    outResult.outputBlockedValid and outResult.deferredOutputValid and
      outResult.postCompletionCacheValid and outResult.gateMatchesCache

proc blaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidence*(
    outputBlocked: BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence,
    deferredOutput: BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence,
    postCompletionCache: BlaiNpuPostCompletionCacheEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidence =
  ## Convenience wrapper for active output/cache gate evidence.
  blaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidenceInto(
    outputBlocked, deferredOutput, postCompletionCache, result)

proc blaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanInto*(
    plan: BlaiForwardNpuPlan,
    outputBlocked: BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence,
    deferredOutput: BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence,
    outputCacheGate: BlaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlan) =
  ## Project the recovered primary-output readback and cache-invalidate plan.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlan)
  outResult.planRunnable = plan.runnable
  outResult.primaryOutputActive = plan.output.output.active
  outResult.outputBytesKnown = plan.output.output.bytes > 0'u32
  outResult.outputSlotMatchesInvalidate =
    plan.outputInvalidateRange.active and
      plan.outputInvalidateRange.offset ==
        blaiTensorBufferOffset(plan.output.output, plan.patchSize)
  outResult.outputBytesMatchInvalidate =
    plan.outputInvalidateRange.active and
      plan.outputInvalidateRange.bytes == plan.output.output.bytes
  outResult.outputInvalidatePlanned =
    outputCacheGate.invalidatePlanned and plan.outputInvalidateRange.active and
      plan.outputInvalidateRange.operation == blaiCacheInvalidate
  outResult.outputInvalidateDeferred =
    outputCacheGate.invalidateDeferred and outputCacheGate.noInvalidateApplied
  outResult.workspaceOutputNotMoved =
    outputBlocked.workspaceOutputNotMoved and deferredOutput.outputInvalid
  outResult.readbackFirstBlocksClear =
    outputBlocked.workspaceOutputFirstBlockNone and
      outputBlocked.validationFirstBlockNone and
      outputBlocked.modelValidationFirstBlockNone
  outResult.readbackPlanReady =
    outResult.planRunnable and outResult.primaryOutputActive and
      outResult.outputBytesKnown and outResult.outputSlotMatchesInvalidate and
      outResult.outputBytesMatchInvalidate and
      outResult.outputInvalidatePlanned
  outResult.readbackDeferredByExecution =
    outResult.readbackPlanReady and outResult.outputInvalidateDeferred and
      outResult.workspaceOutputNotMoved and outResult.readbackFirstBlocksClear
  outResult.valid = outResult.readbackDeferredByExecution

proc blaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlan*(
    plan: BlaiForwardNpuPlan,
    outputBlocked: BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence,
    deferredOutput: BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence,
    outputCacheGate: BlaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlan =
  ## Convenience wrapper for the active output-readback plan.
  blaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanInto(
    plan, outputBlocked, deferredOutput, outputCacheGate, result)

proc blaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidenceInto*(
    plan: BlaiForwardNpuPlan,
    outputBlocked: BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence,
    deferredOutput: BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence,
    outputCacheGate: BlaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence) =
  ## Tie recovered output readback sizing to the active deferred-output gate.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence)
  let readbackPlan =
    blaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlan(
      plan, outputBlocked, deferredOutput, outputCacheGate)
  outResult.outputBlockedValid = outputBlocked.valid
  outResult.deferredOutputValid = deferredOutput.valid
  outResult.outputCacheGateValid = outputCacheGate.valid
  outResult.planRunnable = readbackPlan.planRunnable
  outResult.primaryOutputActive = readbackPlan.primaryOutputActive
  outResult.outputBytesKnown = readbackPlan.outputBytesKnown
  outResult.outputSlotMatchesInvalidate =
    readbackPlan.outputSlotMatchesInvalidate
  outResult.outputBytesMatchInvalidate =
    readbackPlan.outputBytesMatchInvalidate
  outResult.outputInvalidatePlanned = readbackPlan.outputInvalidatePlanned
  outResult.outputInvalidateDeferred = readbackPlan.outputInvalidateDeferred
  outResult.workspaceOutputNotMoved = readbackPlan.workspaceOutputNotMoved
  outResult.readbackFirstBlocksClear =
    readbackPlan.readbackFirstBlocksClear
  outResult.readbackPlanReady = readbackPlan.readbackPlanReady
  outResult.readbackDeferredByExecution =
    readbackPlan.readbackDeferredByExecution
  outResult.valid =
    outResult.outputBlockedValid and outResult.deferredOutputValid and
      outResult.outputCacheGateValid and readbackPlan.valid

proc blaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence*(
    plan: BlaiForwardNpuPlan,
    outputBlocked: BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence,
    deferredOutput: BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence,
    outputCacheGate: BlaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence =
