    plan, outputBlocked, deferredOutput, outputCacheGate, result)

proc blaiParsedForwardConfiguredWorkspaceIdleOutputReadbackGateEvidenceInto*(
    idle:
      BlaiParsedForwardConfiguredWorkspaceActiveIdleCompletionEvidence,
    readback:
      BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceIdleOutputReadbackGateEvidence) =
  ## Gate diagnostic output readback after an idle/no-interrupt terminal.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceIdleOutputReadbackGateEvidence)
  outResult.idleCompletionValid = idle.valid
  outResult.readbackPlanValid = readback.valid
  outResult.idleCompletionCandidate = idle.idleCompletionCandidate
  outResult.outputStillGated = idle.outputStillGated
  outResult.readbackPlanReady = readback.readbackPlanReady
  outResult.primaryOutputActive = readback.primaryOutputActive
  outResult.outputInvalidatePlanned = readback.outputInvalidatePlanned
  outResult.diagnosticReadbackAllowed =
    outResult.idleCompletionCandidate and outResult.readbackPlanReady and
      outResult.primaryOutputActive and outResult.outputInvalidatePlanned
  outResult.validationStillBlocked =
    outResult.outputStillGated and readback.readbackDeferredByExecution
  outResult.valid =
    outResult.idleCompletionValid and outResult.readbackPlanValid and
      outResult.diagnosticReadbackAllowed and outResult.validationStillBlocked

proc blaiParsedForwardConfiguredWorkspaceIdleOutputReadbackGateEvidence*(
    idle:
      BlaiParsedForwardConfiguredWorkspaceActiveIdleCompletionEvidence,
    readback:
      BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence):
    BlaiParsedForwardConfiguredWorkspaceIdleOutputReadbackGateEvidence =
  ## Convenience wrapper for idle-terminal diagnostic readback gating.
  blaiParsedForwardConfiguredWorkspaceIdleOutputReadbackGateEvidenceInto(
    idle, readback, result)

proc blaiParsedForwardConfiguredWorkspaceIdleOutputReadbackDiagnosticInto*(
    gate: BlaiParsedForwardConfiguredWorkspaceIdleOutputReadbackGateEvidence,
    binding: BlaiForwardWorkspaceBufferBinding,
    plan: BlaiForwardNpuPlan,
    kind: BlaiForwardOutputKind,
    workspaceBytes: openArray[uint8],
    expected: openArray[uint8],
    output: var openArray[uint8],
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceIdleOutputReadbackDiagnostic) =
  ## Read and compare output bytes after an idle/no-interrupt terminal.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceIdleOutputReadbackDiagnostic)
  outResult.gateValid = gate.valid
  outResult.readbackAllowed = gate.diagnosticReadbackAllowed
  outResult.validationStillBlocked = gate.validationStillBlocked
  if outResult.readbackAllowed:
    blaiLoadForwardWorkspaceOutputInto(
      binding, plan, kind, workspaceBytes, output, outResult.workspaceOutput)
    blaiCompareUint8OutputsInto(expected, output, outResult.compare)
  outResult.outputMoved = outResult.workspaceOutput.moved
  outResult.outputMatched = outResult.compare.matched
  outResult.expectedElements = outResult.compare.expectedElements
  outResult.actualElements = outResult.compare.actualElements
  outResult.comparedElements = outResult.compare.comparedElements
  outResult.firstMismatch = outResult.compare.firstMismatch
  outResult.readbackObserved =
    outResult.workspaceOutput.moved and
      outResult.workspaceOutput.firstBlock == blaiForwardWorkspaceTensorIoNoBlock
  outResult.compareObserved =
    outResult.compare.lengthMatches and outResult.comparedElements > 0'u32
  outResult.diagnosticValid =
    outResult.gateValid and outResult.readbackAllowed and
      outResult.readbackObserved and outResult.compareObserved and
      outResult.outputMatched
  outResult.modelValidationStillBlocked =
    outResult.validationStillBlocked and outResult.diagnosticValid
  outResult.valid =
    outResult.diagnosticValid and outResult.modelValidationStillBlocked

proc blaiParsedForwardConfiguredWorkspaceIdleOutputReadbackDiagnostic*(
    gate: BlaiParsedForwardConfiguredWorkspaceIdleOutputReadbackGateEvidence,
    binding: BlaiForwardWorkspaceBufferBinding,
    plan: BlaiForwardNpuPlan,
    kind: BlaiForwardOutputKind,
    workspaceBytes: openArray[uint8],
    expected: openArray[uint8],
    output: var openArray[uint8]):
    BlaiParsedForwardConfiguredWorkspaceIdleOutputReadbackDiagnostic =
  ## Convenience wrapper for idle-terminal diagnostic output readback.
  blaiParsedForwardConfiguredWorkspaceIdleOutputReadbackDiagnosticInto(
    gate, binding, plan, kind, workspaceBytes, expected, output, result)

proc blaiParsedForwardConfiguredWorkspaceActiveOutputTransferScopeEvidenceInto*(
    plan: BlaiForwardNpuPlan,
    readback:
      BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveOutputTransferScopeEvidence) =
  ## Classify whether active output equivalence is primary-only or includes mid output.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveOutputTransferScopeEvidence)
  outResult.readbackPlanValid = readback.valid
  outResult.planRunnable = plan.runnable and readback.planRunnable
  outResult.primaryOutputActive =
    plan.output.output.active and readback.primaryOutputActive
  outResult.primaryInvalidateActive =
    plan.outputInvalidateRange.active and readback.outputInvalidatePlanned
  outResult.primaryBytesKnown =
    plan.output.output.bytes > 0'u32 and readback.outputBytesKnown
  outResult.midOutputInactive = not plan.output.midOutput.active
  outResult.midInvalidateInactive = not plan.midOutputInvalidateRange.active
  outResult.primaryOnly =
    outResult.primaryOutputActive and outResult.primaryInvalidateActive and
      outResult.primaryBytesKnown and outResult.midOutputInactive and
      outResult.midInvalidateInactive
  outResult.scopeMatchesReadbackPlan =
    readback.readbackPlanReady and readback.readbackDeferredByExecution and
      outResult.primaryOnly
  outResult.valid =
    outResult.readbackPlanValid and outResult.planRunnable and
      outResult.scopeMatchesReadbackPlan

proc blaiParsedForwardConfiguredWorkspaceActiveOutputTransferScopeEvidence*(
    plan: BlaiForwardNpuPlan,
    readback:
      BlaiParsedForwardConfiguredWorkspaceActiveOutputReadbackPlanEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveOutputTransferScopeEvidence =
  ## Convenience wrapper for active output-transfer scope evidence.
  blaiParsedForwardConfiguredWorkspaceActiveOutputTransferScopeEvidenceInto(
    plan, readback, result)

proc blaiParsedForwardConfiguredWorkspaceActiveExitCleanupEvidenceInto*(
    policy: BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence,
    sideEffects: BlaiNpuCompletionSideEffectEvidence,
    clockExit: BlaiNpuClockExitEvidence,
    stop: BlaiNpuStopAfterInferenceEvidence,
    postCompletionCache: BlaiNpuPostCompletionCacheEvidence,
    outputCacheGate:
      BlaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveExitCleanupEvidence) =
  ## Tie the active timeout cleanup facets to one coherent terminal contract.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveExitCleanupEvidence)
  outResult.completionPolicyValid = policy.valid
  outResult.sideEffectsValid = sideEffects.valid
  outResult.clockExitValid = clockExit.valid
  outResult.stopValid = stop.valid
  outResult.postCompletionCacheValid = postCompletionCache.valid
  outResult.outputCacheGateValid = outputCacheGate.valid
  outResult.timeoutTerminal =
    policy.statusTimedOut and sideEffects.timeoutSideEffectsApplied and
      clockExit.disabledAfterTimeout and stop.stoppedAfterTimeout and
      postCompletionCache.invalidateDeferred
  outResult.interruptClearSuppressed =
    policy.interruptClearSuppressed and sideEffects.interruptClearSuppressed
  outResult.clockDisabled =
    policy.clockDisabledOnExit and sideEffects.clockDisabledOnExit and
      clockExit.disabledAfterTimeout
  outResult.stoppedAfterTimeout = stop.stoppedAfterTimeout
  outResult.invalidateDeferred =
    postCompletionCache.invalidateDeferred and
      outputCacheGate.noInvalidateApplied
  outResult.outputReadbackDeferred =
    outputCacheGate.workspaceOutputNotMoved and outputCacheGate.outputInvalid
  outResult.cleanupCoherent =
    outResult.timeoutTerminal and outResult.interruptClearSuppressed and
      outResult.clockDisabled and outResult.stoppedAfterTimeout and
      outResult.invalidateDeferred and outResult.outputReadbackDeferred
  outResult.valid =
    outResult.completionPolicyValid and outResult.sideEffectsValid and
      outResult.clockExitValid and outResult.stopValid and
      outResult.postCompletionCacheValid and outResult.outputCacheGateValid and
      outResult.cleanupCoherent

proc blaiParsedForwardConfiguredWorkspaceActiveExitCleanupEvidence*(
    policy: BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence,
    sideEffects: BlaiNpuCompletionSideEffectEvidence,
    clockExit: BlaiNpuClockExitEvidence,
    stop: BlaiNpuStopAfterInferenceEvidence,
    postCompletionCache: BlaiNpuPostCompletionCacheEvidence,
    outputCacheGate:
      BlaiParsedForwardConfiguredWorkspaceActiveOutputCacheGateEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveExitCleanupEvidence =
  ## Convenience wrapper for active timeout cleanup coherence evidence.
  blaiParsedForwardConfiguredWorkspaceActiveExitCleanupEvidenceInto(
    policy, sideEffects, clockExit, stop, postCompletionCache,
    outputCacheGate, result)

proc blaiParsedForwardConfiguredWorkspaceSnapshotTerminalDetailEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceSnapshotTerminalDetailEvidence) =
  ## Derive evidence for snapshot run-sequence and execution terminal detail.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceSnapshotTerminalDetailEvidence)
  outResult.runSequenceReadinessFirstBlockMatches =
    snapshot.runSequenceReadinessFirstBlock ==
      validation.executionRunSequenceReadinessFirstBlock
  outResult.runSequenceFirstBlockedLayerMatches =
    snapshot.runSequenceFirstBlockedLayer ==
      validation.executionRunSequenceFirstBlockedLayer
  outResult.runSequenceFirstBlockedRunCapturedMatches =
    snapshot.runSequenceFirstBlockedRunCaptured ==
      validation.executionRunSequenceFirstBlockedRunCaptured
  outResult.runSequenceFirstBlockedRunConfigFirstBlockMatches =
    snapshot.runSequenceFirstBlockedRunConfigFirstBlock ==
      validation.executionRunSequenceFirstBlockedRunConfigFirstBlock
  outResult.firstFailedExecutionStartedMatches =
    snapshot.firstFailedExecutionStarted ==
      validation.executionFirstFailedStarted
  outResult.firstFailedExecutionStatusMatches =
    snapshot.firstFailedExecutionStatus == validation.executionFirstFailedStatus
  outResult.firstFailedExecutionTimedOutMatches =
    snapshot.firstFailedExecutionTimedOut ==
      validation.executionFirstFailedTimedOut
  outResult.lastExecutionCompletedMatches =
    snapshot.lastExecutionCompleted == validation.executionLastCompleted
  outResult.lastExecutionTimedOutMatches =
    snapshot.lastExecutionTimedOut == validation.executionLastTimedOut
  outResult.lastExecutionInterruptObservedMatches =
    snapshot.lastExecutionInterruptObserved ==
      validation.executionLastInterruptObserved
  outResult.runSequenceDetailValid =
    outResult.runSequenceReadinessFirstBlockMatches and
      outResult.runSequenceFirstBlockedLayerMatches and
      outResult.runSequenceFirstBlockedRunCapturedMatches and
      outResult.runSequenceFirstBlockedRunConfigFirstBlockMatches
  outResult.executionTerminalValid =
    outResult.firstFailedExecutionStartedMatches and
      outResult.firstFailedExecutionStatusMatches and
      outResult.firstFailedExecutionTimedOutMatches and
      outResult.lastExecutionCompletedMatches and
      outResult.lastExecutionTimedOutMatches and
      outResult.lastExecutionInterruptObservedMatches
  outResult.terminalDetailValid =
    outResult.runSequenceDetailValid and outResult.executionTerminalValid
  outResult.valid = outResult.terminalDetailValid

proc blaiParsedForwardConfiguredWorkspaceSnapshotTerminalDetailEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult):
    BlaiParsedForwardConfiguredWorkspaceSnapshotTerminalDetailEvidence =
  ## Convenience wrapper for snapshot run-sequence/terminal detail evidence.
  blaiParsedForwardConfiguredWorkspaceSnapshotTerminalDetailEvidenceInto(
    snapshot, validation, result)

proc blaiParsedForwardConfiguredWorkspaceSnapshotRuntimeEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    outResult: var BlaiParsedForwardConfiguredWorkspaceSnapshotRuntimeEvidence) =
  ## Derive evidence for snapshot runtime/cache/register completion state.
  outResult = default(BlaiParsedForwardConfiguredWorkspaceSnapshotRuntimeEvidence)
  outResult.firstFailedExecutionWaitPlanMatches =
    snapshot.firstFailedExecutionWaitPlan ==
      validation.execution.firstFailedExecution.waitPlan
  outResult.lastExecutionWaitPlanMatches =
    snapshot.lastExecutionWaitPlan == validation.execution.lastExecution.waitPlan
  outResult.workspaceCacheMatches =
    snapshot.workspaceCache == validation.execution.workspaceCache
  outResult.lastExecutionCacheMatches =
    snapshot.lastExecutionCache == validation.execution.lastExecution.cache
  outResult.launchRegistersCapturedMatches =
    snapshot.launchRegistersCaptured == npuLastLaunchRegisterSnapshotCaptured()
  outResult.startedRegistersCapturedMatches =
    snapshot.startedRegistersCaptured == npuLastStartedRegisterSnapshotCaptured()
  outResult.launchRegistersMatch =
    snapshot.launchRegisters == npuLastLaunchRegisterSnapshot()
  outResult.startedRegistersMatch =
    snapshot.startedRegisters == npuLastStartedRegisterSnapshot()
  outResult.firstFailedExecutionWaitExitInterruptMatches =
    snapshot.firstFailedExecutionWaitExitInterrupt ==
      validation.execution.firstFailedExecution.completion.waitExitInterrupt
  outResult.firstFailedExecutionWaitExitMmAggregateMatches =
    snapshot.firstFailedExecutionWaitExitMmAggregate ==
      validation.execution.firstFailedExecution.completion.waitExitMmAggregate
  outResult.firstFailedExecutionWaitExitBusyMatches =
    snapshot.firstFailedExecutionWaitExitBusy ==
      validation.execution.firstFailedExecution.completion.waitExitBusy
  outResult.firstFailedExecutionWaitExitClockMatches =
    snapshot.firstFailedExecutionWaitExitClock ==
      validation.execution.firstFailedExecution.completion.waitExitClock
  outResult.lastExecutionWaitExitInterruptMatches =
    snapshot.lastExecutionWaitExitInterrupt ==
      validation.execution.lastExecution.completion.waitExitInterrupt
  outResult.lastExecutionWaitExitMmAggregateMatches =
    snapshot.lastExecutionWaitExitMmAggregate ==
      validation.execution.lastExecution.completion.waitExitMmAggregate
  outResult.lastExecutionWaitExitBusyMatches =
    snapshot.lastExecutionWaitExitBusy ==
      validation.execution.lastExecution.completion.waitExitBusy
  outResult.lastExecutionWaitExitClockMatches =
    snapshot.lastExecutionWaitExitClock ==
      validation.execution.lastExecution.completion.waitExitClock
  outResult.firstFailedExecutionStatusDecisionMatches =
    snapshot.firstFailedExecutionStatusDecision ==
      validation.execution.firstFailedExecution.completion.statusDecision
  outResult.lastExecutionStatusDecisionMatches =
    snapshot.lastExecutionStatusDecision ==
      validation.execution.lastExecution.completion.statusDecision
  outResult.firstFailedExecutionInterruptClearedMatches =
    snapshot.firstFailedExecutionInterruptCleared ==
      validation.execution.firstFailedExecution.completion.interruptCleared
  outResult.firstFailedExecutionClockDisabledMatches =
    snapshot.firstFailedExecutionClockDisabled ==
      validation.execution.firstFailedExecution.completion.clockDisabled
  outResult.lastExecutionInterruptClearedMatches =
    snapshot.lastExecutionInterruptCleared ==
      validation.execution.lastExecution.completion.interruptCleared
  outResult.lastExecutionClockDisabledMatches =
    snapshot.lastExecutionClockDisabled ==
      validation.execution.lastExecution.completion.clockDisabled
  outResult.runConfigReadinessMatches =
    snapshot.runSequenceFirstBlockedRunConfigReadiness ==
      validation.executionRunSequenceFirstBlockedRunConfigReadiness
  outResult.waitPlansValid =
    outResult.firstFailedExecutionWaitPlanMatches and
      outResult.lastExecutionWaitPlanMatches
  outResult.cacheResultsValid =
    outResult.workspaceCacheMatches and outResult.lastExecutionCacheMatches
  outResult.registerCapturesValid =
    outResult.launchRegistersCapturedMatches and
      outResult.startedRegistersCapturedMatches and
      outResult.launchRegistersMatch and outResult.startedRegistersMatch
  outResult.waitExitRegistersValid =
    outResult.firstFailedExecutionWaitExitInterruptMatches and
      outResult.firstFailedExecutionWaitExitMmAggregateMatches and
      outResult.firstFailedExecutionWaitExitBusyMatches and
      outResult.firstFailedExecutionWaitExitClockMatches and
      outResult.lastExecutionWaitExitInterruptMatches and
      outResult.lastExecutionWaitExitMmAggregateMatches and
      outResult.lastExecutionWaitExitBusyMatches and
      outResult.lastExecutionWaitExitClockMatches
  outResult.statusDecisionsValid =
    outResult.firstFailedExecutionStatusDecisionMatches and
      outResult.lastExecutionStatusDecisionMatches
  outResult.completionSideEffectsValid =
    outResult.firstFailedExecutionInterruptClearedMatches and
      outResult.firstFailedExecutionClockDisabledMatches and
      outResult.lastExecutionInterruptClearedMatches and
      outResult.lastExecutionClockDisabledMatches
  outResult.runConfigReadinessValid = outResult.runConfigReadinessMatches
  outResult.valid =
    outResult.waitPlansValid and outResult.cacheResultsValid and
      outResult.registerCapturesValid and outResult.waitExitRegistersValid and
      outResult.statusDecisionsValid and
      outResult.completionSideEffectsValid and
      outResult.runConfigReadinessValid

proc blaiParsedForwardConfiguredWorkspaceSnapshotRuntimeEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult):
    BlaiParsedForwardConfiguredWorkspaceSnapshotRuntimeEvidence =
  ## Convenience wrapper for snapshot runtime/cache/register evidence.
  blaiParsedForwardConfiguredWorkspaceSnapshotRuntimeEvidenceInto(
    snapshot, validation, result)

proc blaiParsedForwardConfiguredWorkspaceActiveRuntimeMirrorEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    runtime: BlaiParsedForwardConfiguredWorkspaceSnapshotRuntimeEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveRuntimeMirrorEvidence) =
  ## Derive evidence that first-failed and last execution mirror one active run.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveRuntimeMirrorEvidence)
  outResult.statusMatches =
    snapshot.firstFailedExecutionStatus == snapshot.lastExecutionStatus
  outResult.timedOutMatches =
    snapshot.firstFailedExecutionTimedOut == snapshot.lastExecutionTimedOut
  outResult.waitPlanMatches =
    snapshot.firstFailedExecutionWaitPlan == snapshot.lastExecutionWaitPlan
  outResult.waitExitInterruptMatches =
    snapshot.firstFailedExecutionWaitExitInterrupt ==
      snapshot.lastExecutionWaitExitInterrupt
  outResult.waitExitMmAggregateMatches =
    snapshot.firstFailedExecutionWaitExitMmAggregate ==
      snapshot.lastExecutionWaitExitMmAggregate
  outResult.waitExitBusyMatches =
    snapshot.firstFailedExecutionWaitExitBusy ==
      snapshot.lastExecutionWaitExitBusy
  outResult.waitExitClockMatches =
    snapshot.firstFailedExecutionWaitExitClock ==
      snapshot.lastExecutionWaitExitClock
  outResult.statusDecisionMatches =
    snapshot.firstFailedExecutionStatusDecision ==
      snapshot.lastExecutionStatusDecision
  outResult.interruptClearedMatches =
    snapshot.firstFailedExecutionInterruptCleared ==
      snapshot.lastExecutionInterruptCleared
  outResult.clockDisabledMatches =
    snapshot.firstFailedExecutionClockDisabled ==
      snapshot.lastExecutionClockDisabled
  outResult.runtimeMirrorsValid = runtime.valid
  outResult.valid =
    outResult.statusMatches and outResult.timedOutMatches and
      outResult.waitPlanMatches and outResult.waitExitInterruptMatches and
      outResult.waitExitMmAggregateMatches and
      outResult.waitExitBusyMatches and outResult.waitExitClockMatches and
      outResult.statusDecisionMatches and outResult.interruptClearedMatches and
      outResult.clockDisabledMatches and outResult.runtimeMirrorsValid

proc blaiParsedForwardConfiguredWorkspaceActiveRuntimeMirrorEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    runtime: BlaiParsedForwardConfiguredWorkspaceSnapshotRuntimeEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveRuntimeMirrorEvidence =
  ## Convenience wrapper for active runtime mirror evidence.
  blaiParsedForwardConfiguredWorkspaceActiveRuntimeMirrorEvidenceInto(
    snapshot, runtime, result)

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    expectedTimeout: uint32,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence) =
  ## Derive focused active completion wait-policy evidence.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence)
  outResult.waitPlansMatch =
    snapshot.firstFailedExecutionWaitPlan == snapshot.lastExecutionWaitPlan and
      snapshot.lastExecutionWaitPlan ==
        validation.execution.lastExecution.waitPlan
  outResult.waitConfigured =
    snapshot.lastExecutionWaitPlan.configured and
      validation.execution.lastExecution.waitPlan.configured
  outResult.timeoutMatches =
    snapshot.lastExecutionWaitPlan.timeout == expectedTimeout and
      validation.execution.lastExecution.waitPlan.timeout == expectedTimeout
  outResult.clearOnComplete =
    snapshot.lastExecutionWaitPlan.clearOnComplete and
      validation.execution.lastExecution.waitPlan.clearOnComplete
  outResult.disableClockOnExit =
    snapshot.lastExecutionWaitPlan.disableClockOnExit and
      validation.execution.lastExecution.waitPlan.disableClockOnExit
  outResult.started =
    snapshot.lastExecutionStarted and validation.executionLastStarted and
      validation.execution.lastExecution.completion.started
  outResult.noInterrupt =
    not snapshot.lastExecutionInterruptObserved and
      not validation.executionLastInterruptObserved and
      not validation.execution.lastExecution.completion.interruptObserved
  outResult.statusConfigured =
    snapshot.lastExecutionStatusDecision.configured and
      validation.execution.lastExecution.completion.statusDecision.configured
  outResult.statusTimedOut =
    snapshot.lastExecutionStatusDecision.timedOut and
      validation.execution.lastExecution.completion.statusDecision.timedOut
  outResult.statusIncomplete =
    not snapshot.lastExecutionStatusDecision.completed and
      not validation.execution.lastExecution.completion.statusDecision.completed
  outResult.statusMatches =
    snapshot.lastExecutionStatus == npuTimeout and
      validation.executionLastStatus == npuTimeout and
      validation.execution.lastExecution.completion.status == npuTimeout
  outResult.interruptClearSuppressed =
    not snapshot.lastExecutionInterruptCleared and
      not validation.execution.lastExecution.completion.interruptCleared
  outResult.clockDisabledOnExit =
    snapshot.lastExecutionClockDisabled and
      validation.execution.lastExecution.completion.clockDisabled
  outResult.valid =
    outResult.waitPlansMatch and outResult.waitConfigured and
      outResult.timeoutMatches and outResult.clearOnComplete and
      outResult.disableClockOnExit and outResult.started and outResult.noInterrupt and
      outResult.statusConfigured and outResult.statusTimedOut and
      outResult.statusIncomplete and outResult.statusMatches and
      outResult.interruptClearSuppressed and outResult.clockDisabledOnExit

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    expectedTimeout: uint32):
    BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence =
  ## Convenience wrapper for active completion wait-policy evidence.
  blaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidenceInto(
    snapshot, validation, expectedTimeout, result)

proc blaiParsedForwardConfiguredWorkspaceTerminalGateEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    outResult: var BlaiParsedForwardConfiguredWorkspaceTerminalGateEvidence) =
  ## Derive evidence for terminal-gate classification and selected gate.
  outResult = default(BlaiParsedForwardConfiguredWorkspaceTerminalGateEvidence)
  case snapshot.terminalGate
  of blaiParsedConfiguredWorkspaceGateComplete,
      blaiParsedConfiguredWorkspaceGateMaterialization,
      blaiParsedConfiguredWorkspaceGateBinding,
      blaiParsedConfiguredWorkspaceGateHardwareAddresses,
      blaiParsedConfiguredWorkspaceGateInput,
      blaiParsedConfiguredWorkspaceGateRunSequence,
      blaiParsedConfiguredWorkspaceGateExecution,
      blaiParsedConfiguredWorkspaceGateOutput:
    outResult.terminalGateKnown = true
  outResult.terminalValidFlagMatches =
    snapshot.valid ==
      (snapshot.terminalGate == blaiParsedConfiguredWorkspaceGateComplete)
  outResult.completeGateEvidence =
    snapshot.valid and snapshot.outputValid and snapshot.outputMatched and
      validation.valid
  outResult.materializationGateEvidence =
    snapshot.bound and not snapshot.materialized
  outResult.bindingGateEvidence = not snapshot.bound
  outResult.hardwareAddressesGateEvidence =
    snapshot.materialized and snapshot.bound and
      not snapshot.hardwareAddressesReady
  outResult.inputGateEvidence =
    snapshot.materialized and snapshot.bound and
      snapshot.hardwareAddressesReady and not snapshot.inputMoved
  outResult.runSequenceGateEvidence =
    snapshot.materialized and snapshot.inputMoved and
      not snapshot.runSequenceReady and
      snapshot.executionFirstBlock == blaiForwardModelExecuteRunSequence
  outResult.executionGateEvidence =
    snapshot.materialized and snapshot.inputMoved and
      snapshot.runSequenceReady and not snapshot.executionCompleted and
      snapshot.executionFirstBlock == blaiForwardModelExecuteLayerExecution
  outResult.outputGateEvidence =
    snapshot.materialized and snapshot.executionCompleted and
      not snapshot.outputValid and
      validation.firstBlock == blaiParsedForwardConfiguredWorkspaceFixtureOutput
  case snapshot.terminalGate
  of blaiParsedConfiguredWorkspaceGateComplete:
    outResult.selectedGateEvidence = outResult.completeGateEvidence
  of blaiParsedConfiguredWorkspaceGateMaterialization:
    outResult.selectedGateEvidence = outResult.materializationGateEvidence
  of blaiParsedConfiguredWorkspaceGateBinding:
    outResult.selectedGateEvidence = outResult.bindingGateEvidence
  of blaiParsedConfiguredWorkspaceGateHardwareAddresses:
    outResult.selectedGateEvidence = outResult.hardwareAddressesGateEvidence
  of blaiParsedConfiguredWorkspaceGateInput:
    outResult.selectedGateEvidence = outResult.inputGateEvidence
  of blaiParsedConfiguredWorkspaceGateRunSequence:
    outResult.selectedGateEvidence = outResult.runSequenceGateEvidence
  of blaiParsedConfiguredWorkspaceGateExecution:
    outResult.selectedGateEvidence = outResult.executionGateEvidence
  of blaiParsedConfiguredWorkspaceGateOutput:
    outResult.selectedGateEvidence = outResult.outputGateEvidence
  outResult.classified =
    outResult.terminalGateKnown and outResult.terminalValidFlagMatches
  outResult.valid = outResult.classified and outResult.selectedGateEvidence

proc blaiParsedForwardConfiguredWorkspaceTerminalGateEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult):
    BlaiParsedForwardConfiguredWorkspaceTerminalGateEvidence =
  ## Convenience wrapper for terminal-gate classification evidence.
  blaiParsedForwardConfiguredWorkspaceTerminalGateEvidenceInto(
    snapshot, validation, result)

proc blaiParsedForwardConfiguredWorkspaceExecutionGateEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence) =
  ## Derive evidence for the active execution terminal gate.
  outResult = default(BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence)
  outResult.terminalExecutionEvidence =
    snapshot.materialized and snapshot.inputMoved and
      snapshot.runSequenceReady and not snapshot.executionCompleted and
      snapshot.executionFirstBlock == blaiForwardModelExecuteLayerExecution
  outResult.oneLayerAttempted =
    snapshot.attemptedLayerCount == 1'u32 and snapshot.failedLayerCount == 1'u32
  outResult.failedExecutionCaptured =
    snapshot.firstFailedExecutionCaptured and snapshot.firstFailedLayer == 0
  outResult.executionStarted =
    snapshot.firstFailedExecutionStarted and snapshot.lastExecutionStarted
  outResult.executionIncomplete =
    not snapshot.firstFailedExecutionTimedOut or snapshot.lastExecutionTimedOut
  outResult.timeoutStatus = snapshot.lastExecutionStatus == npuTimeout
  outResult.timeoutTimedOut =
    snapshot.firstFailedExecutionTimedOut and snapshot.lastExecutionTimedOut
  outResult.waitNoInterrupt =
    not snapshot.lastExecutionWaitExitInterrupt.interruptPending
  outResult.waitInterruptRawClear =
    (snapshot.lastExecutionWaitExitInterrupt.intCfg and
      BlaiInterruptStatusMask) == 0
  outResult.waitResumeCommandClean =
    (snapshot.lastExecutionWaitExitInterrupt.intCfg and BlaiResumeMask) == 0
  outResult.waitStopCommandClean =
    (snapshot.lastExecutionWaitExitInterrupt.intCfg and BlaiStopMask) == 0
  outResult.waitInterruptClearCommandClean =
    (snapshot.lastExecutionWaitExitInterrupt.intCfg and
      BlaiInterruptClearMask) == 0
  outResult.waitInterruptStatusClean =
    (snapshot.lastExecutionWaitExitInterrupt.intCfg and
      BlaiInterruptStatusMask) == 0
  outResult.waitInterruptConfigClean =
    outResult.waitResumeCommandClean and outResult.waitStopCommandClean and
      outResult.waitInterruptClearCommandClean and
      outResult.waitInterruptStatusClean
  if snapshot.lastExecutionWaitExitBusy.busy:
    outResult.waitBusy = true
    outResult.waitAxiWriteActive =
      (snapshot.lastExecutionWaitExitBusy.generalCfg and
        BlaiAxiWriteIdleMask) == 0
    outResult.waitAxiReadActive =
      (snapshot.lastExecutionWaitExitBusy.generalCfg and
        BlaiAxiReadIdleMask) == 0
    outResult.waitBusyRawActive =
      outResult.waitAxiWriteActive or outResult.waitAxiReadActive
  else:
    outResult.waitIdle = true
  outResult.waitClockEnabled = snapshot.lastExecutionWaitExitClock.enabled
  outResult.waitClockSourceKnown =
    snapshot.lastExecutionWaitExitClock.sourceKnown
  outResult.waitClockSource320M =
    snapshot.lastExecutionWaitExitClock.source == npuClk320M
  outResult.waitClockDividerZero =
    snapshot.lastExecutionWaitExitClock.divider == 0
  outResult.waitClockSourceMatches =
    outResult.waitClockSourceKnown and outResult.waitClockSource320M and
      outResult.waitClockDividerZero
  outResult.timeoutWaitEvidence =
    outResult.timeoutTimedOut and outResult.waitNoInterrupt and
      outResult.waitInterruptRawClear and outResult.waitInterruptConfigClean and
      ((outResult.waitBusy and outResult.waitBusyRawActive) or
       outResult.waitIdle) and outResult.waitClockEnabled and
      outResult.waitClockSourceMatches
  outResult.unsupportedStatus = snapshot.lastExecutionStatus == npuUnsupported
  outResult.busyStatus = snapshot.lastExecutionStatus == npuBusy
  outResult.unexpectedOkStatus = snapshot.lastExecutionStatus == npuOk
  outResult.okStatusEvidence = not outResult.unexpectedOkStatus
  case snapshot.lastExecutionStatus
  of npuTimeout:
    outResult.statusEvidence = outResult.timeoutWaitEvidence
  of npuOk:
    outResult.statusEvidence = false
  of npuUnsupported:
    outResult.statusEvidence = outResult.unsupportedStatus
  of npuBusy:
    outResult.statusEvidence = outResult.busyStatus
  outResult.valid =
    outResult.terminalExecutionEvidence and outResult.oneLayerAttempted and
      outResult.failedExecutionCaptured and outResult.executionStarted and
      outResult.executionIncomplete and outResult.statusEvidence

proc blaiParsedForwardConfiguredWorkspaceExecutionGateEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot):
    BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence =
  ## Convenience wrapper for active execution terminal-gate evidence.
  blaiParsedForwardConfiguredWorkspaceExecutionGateEvidenceInto(
    snapshot, result)

proc blaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidenceInto*(
    execution: BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence) =
  ## Derive focused active-timeout evidence from execution-gate state.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence)
  outResult.timeoutStatus = execution.timeoutStatus
  outResult.timedOut = execution.timeoutTimedOut
  outResult.noInterrupt = execution.waitNoInterrupt
  outResult.interruptRawClear = execution.waitInterruptRawClear
  outResult.commandBitsClean = execution.waitInterruptConfigClean
  outResult.busyOrIdleKnown = execution.waitBusy or execution.waitIdle
  outResult.busyRawMatches =
    (execution.waitBusy and execution.waitBusyRawActive) or execution.waitIdle
  outResult.clockRetained =
    execution.waitClockEnabled and execution.waitClockSourceMatches
  outResult.statusValid = execution.statusEvidence
  outResult.valid =
    outResult.timeoutStatus and outResult.timedOut and
      outResult.noInterrupt and outResult.interruptRawClear and
      outResult.commandBitsClean and outResult.busyOrIdleKnown and
      outResult.busyRawMatches and outResult.clockRetained and
      outResult.statusValid

proc blaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence*(
    execution: BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence =
  ## Convenience wrapper for active execution timeout evidence.
  blaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidenceInto(
    execution, result)

proc blaiParsedForwardConfiguredWorkspaceWaitExitMode*(
    execution: BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence):
    BlaiParsedForwardConfiguredWorkspaceWaitExitMode =
  ## Classify AXI activity observed at the active configured-run wait exit.
  if execution.waitBusy:
    if execution.waitAxiWriteActive and execution.waitAxiReadActive:
      blaiParsedConfiguredWaitExitReadWriteActive
    elif execution.waitAxiWriteActive:
      blaiParsedConfiguredWaitExitWriteActive
    elif execution.waitAxiReadActive:
      blaiParsedConfiguredWaitExitReadActive
    else:
      blaiParsedConfiguredWaitExitIdle
  else:
    blaiParsedConfiguredWaitExitIdle

proc blaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidenceInto*(
    execution: BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence,
    timeout: BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence) =
  ## Derive focused raw wait-exit terminal-register evidence.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence)
  outResult.mode = blaiParsedForwardConfiguredWorkspaceWaitExitMode(execution)
  outResult.timeoutValid = timeout.timeoutStatus and timeout.timedOut
  outResult.noCompletionInterrupt =
    timeout.noInterrupt and timeout.interruptRawClear and
      execution.waitNoInterrupt and execution.waitInterruptRawClear
  outResult.commandBitsClean =
    timeout.commandBitsClean and execution.waitInterruptConfigClean
  outResult.busyOrIdleKnown =
    timeout.busyOrIdleKnown and (execution.waitBusy or execution.waitIdle)
  outResult.axiActivityKnown =
    (execution.waitBusy and execution.waitBusyRawActive and
      (execution.waitAxiWriteActive or execution.waitAxiReadActive)) or
    execution.waitIdle
  outResult.idleMode =
    outResult.mode == blaiParsedConfiguredWaitExitIdle
  outResult.writeActiveMode =
    outResult.mode == blaiParsedConfiguredWaitExitWriteActive
  outResult.readActiveMode =
    outResult.mode == blaiParsedConfiguredWaitExitReadActive
  outResult.readWriteActiveMode =
    outResult.mode == blaiParsedConfiguredWaitExitReadWriteActive
  outResult.modeMatchesBusyBits =
    (outResult.idleMode and execution.waitIdle) or
    (outResult.writeActiveMode and execution.waitBusy and
      execution.waitAxiWriteActive and not execution.waitAxiReadActive) or
    (outResult.readActiveMode and execution.waitBusy and
      execution.waitAxiReadActive and not execution.waitAxiWriteActive) or
    (outResult.readWriteActiveMode and execution.waitBusy and
      execution.waitAxiWriteActive and execution.waitAxiReadActive)
  outResult.clockRetained =
    timeout.clockRetained and execution.waitClockEnabled and
      execution.waitClockSourceMatches
  outResult.statusValid = timeout.statusValid and execution.statusEvidence
  outResult.valid =
    outResult.timeoutValid and outResult.noCompletionInterrupt and
      outResult.commandBitsClean and outResult.busyOrIdleKnown and
      outResult.axiActivityKnown and outResult.modeMatchesBusyBits and
      outResult.clockRetained and outResult.statusValid

proc blaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence*(
    execution: BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence,
    timeout: BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence =
  ## Convenience wrapper for active wait-exit terminal evidence.
  blaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidenceInto(
    execution, timeout, result)

proc blaiParsedForwardConfiguredWorkspaceActiveIdleCompletionEvidenceInto*(
    execution: BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence,
    timeout: BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveIdleCompletionEvidence) =
  ## Classify the observed idle wait-exit terminal without treating it as a
  ## completed SDK interrupt wait.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveIdleCompletionEvidence)
  outResult.timeoutValid = timeout.valid
  outResult.waitExitValid = waitExit.valid
  outResult.engineStarted = execution.executionStarted
  outResult.noCompletionInterrupt =
    timeout.noInterrupt and waitExit.noCompletionInterrupt
  outResult.waitExitIdle = waitExit.idleMode and execution.waitIdle
  outResult.axiWriteIdle = execution.waitIdle and not execution.waitAxiWriteActive
  outResult.axiReadIdle = execution.waitIdle and not execution.waitAxiReadActive
  outResult.commandBitsClean =
    timeout.commandBitsClean and waitExit.commandBitsClean
  outResult.clockRetained = timeout.clockRetained and waitExit.clockRetained
  outResult.idleCompletionCandidate =
    outResult.engineStarted and outResult.noCompletionInterrupt and
      outResult.waitExitIdle and outResult.axiWriteIdle and
      outResult.axiReadIdle and outResult.commandBitsClean and
      outResult.clockRetained
  outResult.outputStillGated =
    timeout.timedOut and timeout.timeoutStatus and not execution.unexpectedOkStatus
  outResult.valid =
    outResult.timeoutValid and outResult.waitExitValid and
      outResult.idleCompletionCandidate and outResult.outputStillGated

proc blaiParsedForwardConfiguredWorkspaceActiveIdleCompletionEvidence*(
    execution: BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence,
    timeout: BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveIdleCompletionEvidence =
  ## Convenience wrapper for active idle-completion candidate evidence.
  blaiParsedForwardConfiguredWorkspaceActiveIdleCompletionEvidenceInto(
    execution, timeout, waitExit, result)

proc blaiParsedForwardConfiguredWorkspaceActiveWaitExitModeEvidenceInto*(
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveWaitExitModeEvidence) =
  ## Derive the active fixture's terminal AXI-mode evidence.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveWaitExitModeEvidence)
  outResult.mode = waitExit.mode
  outResult.waitExitValid = waitExit.valid
  outResult.modeKnown =
    waitExit.idleMode or waitExit.writeActiveMode or waitExit.readActiveMode or
      waitExit.readWriteActiveMode
  outResult.idleMode = waitExit.idleMode
  outResult.writeActiveMode = waitExit.writeActiveMode
  outResult.readActiveMode = waitExit.readActiveMode
  outResult.readWriteActive = waitExit.readWriteActiveMode
  outResult.timeoutTerminal = waitExit.timeoutValid
  outResult.noCompletionInterrupt = waitExit.noCompletionInterrupt
  outResult.clockRetained = waitExit.clockRetained
  outResult.modeMatchesBits = waitExit.modeMatchesBusyBits
  outResult.valid =
    outResult.waitExitValid and outResult.modeKnown and
      outResult.timeoutTerminal and outResult.noCompletionInterrupt and
      outResult.clockRetained and outResult.modeMatchesBits

proc blaiParsedForwardConfiguredWorkspaceActiveWaitExitModeEvidence*(
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveWaitExitModeEvidence =
  ## Convenience wrapper for active wait-exit AXI-mode evidence.
  blaiParsedForwardConfiguredWorkspaceActiveWaitExitModeEvidenceInto(
    waitExit, result)

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionWaitBudgetEvidenceInto*(
    policy: BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence,
    polling: BlaiNpuPollingWaitEvidence,
    timeout: BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveCompletionWaitBudgetEvidence) =
  ## Derive focused evidence for the active completion polling budget terminal.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveCompletionWaitBudgetEvidence)
  outResult.policyValid = policy.valid
  outResult.pollingValid = polling.valid
  outResult.timeoutValid = timeout.valid
  outResult.waitExitValid = waitExit.valid
  outResult.waitConfigured =
    policy.waitConfigured and polling.configured and policy.started and
      polling.started
  outResult.budgetMatchesPolicy =
    policy.timeoutMatches and polling.pollBudget > 0'u32
  outResult.terminalTimeout =
    polling.terminal == blaiNpuPollingWaitTimeout and
      polling.terminalMatchesStatus
  outResult.pollBudgetExhausted = polling.budgetExhausted
  outResult.noInterruptObserved =
    policy.noInterrupt and not polling.interruptObserved and
      timeout.noInterrupt and waitExit.noCompletionInterrupt
  outResult.statusTimedOut =
    policy.statusTimedOut and polling.statusTimedOut and
      timeout.timeoutStatus and timeout.timedOut and waitExit.timeoutValid
  outResult.waitExitNoInterrupt =
    waitExit.noCompletionInterrupt and timeout.interruptRawClear
  outResult.waitExitKnown =
    waitExit.timeoutValid and waitExit.busyOrIdleKnown and
      waitExit.axiActivityKnown and waitExit.statusValid
  outResult.commandBitsClean =
    timeout.commandBitsClean and waitExit.commandBitsClean
  outResult.clockRetained = timeout.clockRetained and waitExit.clockRetained
  outResult.deterministicTimeout =
    outResult.policyValid and outResult.pollingValid and
      outResult.timeoutValid and outResult.waitExitValid and
      outResult.waitConfigured and outResult.budgetMatchesPolicy and
      outResult.terminalTimeout and outResult.pollBudgetExhausted and
      outResult.noInterruptObserved and outResult.statusTimedOut and
      outResult.waitExitNoInterrupt and outResult.waitExitKnown and
      outResult.commandBitsClean and outResult.clockRetained
  outResult.valid = outResult.deterministicTimeout

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionWaitBudgetEvidence*(
    policy: BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence,
    polling: BlaiNpuPollingWaitEvidence,
    timeout: BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveCompletionWaitBudgetEvidence =
  ## Convenience wrapper for active completion polling budget evidence.
  blaiParsedForwardConfiguredWorkspaceActiveCompletionWaitBudgetEvidenceInto(
    policy, polling, timeout, waitExit, result)

proc blaiParsedForwardConfiguredWorkspaceActiveEngineProgressEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    execution: BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveEngineProgressEvidence) =
  ## Derive focused active engine-progress evidence from execution counters.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveEngineProgressEvidence)
  outResult.terminalExecutionGate = execution.terminalExecutionEvidence
  outResult.runSequenceReady =
    snapshot.runSequenceReady and
      validation.executionRunSequenceFirstBlock ==
        blaiForwardModelRunSequenceNoBlock
  outResult.countersMatch =
    snapshot.attemptedLayerCount == validation.executionAttemptedLayerCount and
      snapshot.completedLayerCount ==
        validation.executionCompletedLayerCount and
      snapshot.failedLayerCount == validation.executionFailedLayerCount and
      snapshot.firstFailedLayer == validation.executionFirstFailedLayer
  outResult.oneLayerAttempted =
    snapshot.attemptedLayerCount == 1'u32 and
      validation.executionAttemptedLayerCount == 1'u32
  outResult.noLayerCompleted =
    snapshot.completedLayerCount == 0'u32 and
      validation.executionCompletedLayerCount == 0'u32
  outResult.oneLayerFailed =
    snapshot.failedLayerCount == 1'u32 and
      validation.executionFailedLayerCount == 1'u32
  outResult.firstFailedLayerZero =
    snapshot.firstFailedLayer == 0 and validation.executionFirstFailedLayer == 0
  outResult.failedExecutionCaptured =
    snapshot.firstFailedExecutionCaptured and
      validation.executionFirstFailedCaptured
  outResult.executionStarted =
    snapshot.firstFailedExecutionStarted and snapshot.lastExecutionStarted and
      validation.executionFirstFailedStarted and validation.executionLastStarted
  outResult.executionIncomplete =
    not snapshot.lastExecutionCompleted and not validation.executionLastCompleted
  outResult.timeoutTerminal =
    execution.timeoutStatus and execution.timeoutTimedOut and
      snapshot.lastExecutionStatus == npuTimeout and
      validation.executionLastStatus == npuTimeout
  outResult.valid =
    outResult.terminalExecutionGate and outResult.runSequenceReady and
      outResult.countersMatch and outResult.oneLayerAttempted and
      outResult.noLayerCompleted and outResult.oneLayerFailed and
      outResult.firstFailedLayerZero and outResult.failedExecutionCaptured and
      outResult.executionStarted and outResult.executionIncomplete and
      outResult.timeoutTerminal

proc blaiParsedForwardConfiguredWorkspaceActiveEngineProgressEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    validation: BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    execution: BlaiParsedForwardConfiguredWorkspaceExecutionGateEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveEngineProgressEvidence =
  ## Convenience wrapper for active engine-progress evidence.
  blaiParsedForwardConfiguredWorkspaceActiveEngineProgressEvidenceInto(
    snapshot, validation, execution, result)

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionBoundaryEvidenceInto*(
    policy: BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence,
    engine: BlaiParsedForwardConfiguredWorkspaceActiveEngineProgressEvidence,
    timeout: BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence,
    deferredOutput: BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveCompletionBoundaryEvidence) =
  ## Derive focused active completion/output boundary evidence.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveCompletionBoundaryEvidence)
  outResult.completionPolicyValid = policy.valid
  outResult.engineProgressValid = engine.valid
  outResult.timeoutEvidenceValid = timeout.valid
  outResult.deferredOutputValid = deferredOutput.valid
  outResult.noCompletionInterrupt =
    policy.noInterrupt and timeout.noInterrupt and timeout.interruptRawClear
  outResult.busyOrIdleKnown = timeout.busyOrIdleKnown and timeout.busyRawMatches
  outResult.outputDeferred =
    deferredOutput.fixtureExecutionGate and deferredOutput.executionIncomplete and
      deferredOutput.outputInvalid and deferredOutput.outputUnmatched
  outResult.remainingCompletionProgress =
    outResult.completionPolicyValid and outResult.engineProgressValid and
      outResult.timeoutEvidenceValid and outResult.deferredOutputValid and
      outResult.noCompletionInterrupt and outResult.outputDeferred
  outResult.valid =
    outResult.remainingCompletionProgress and outResult.busyOrIdleKnown

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionBoundaryEvidence*(
    policy: BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence,
    engine: BlaiParsedForwardConfiguredWorkspaceActiveEngineProgressEvidence,
    timeout: BlaiParsedForwardConfiguredWorkspaceActiveTimeoutEvidence,
    deferredOutput: BlaiParsedForwardConfiguredWorkspaceDeferredOutputEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveCompletionBoundaryEvidence =
  ## Convenience wrapper for active completion/output boundary evidence.
  blaiParsedForwardConfiguredWorkspaceActiveCompletionBoundaryEvidenceInto(
    policy, engine, timeout, deferredOutput, result)

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidenceInto*(
    boundary: BlaiParsedForwardConfiguredWorkspaceActiveCompletionBoundaryEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    outputBlocked: BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidence) =
  ## Derive focused evidence for the remaining active completion gap.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidence)
  outResult.boundaryValid = boundary.valid
  outResult.waitExitValid = waitExit.valid
  outResult.outputBlockedValid = outputBlocked.valid
  outResult.noCompletionInterrupt =
    boundary.noCompletionInterrupt and waitExit.noCompletionInterrupt
  outResult.waitExitKnown =
    waitExit.timeoutValid and waitExit.commandBitsClean and
      waitExit.busyOrIdleKnown and waitExit.axiActivityKnown and
      waitExit.clockRetained and waitExit.statusValid
  outResult.outputGateKnown =
    boundary.outputDeferred and outputBlocked.deferredOutputValid and
      outputBlocked.outputReadinessInvalid and
      outputBlocked.workspaceOutputNotMoved and outputBlocked.zeroCounters and
      outputBlocked.noMismatch
  outResult.completionSignalMissing =
    outResult.boundaryValid and outResult.waitExitValid and
      outResult.noCompletionInterrupt and outResult.waitExitKnown and
      outResult.outputGateKnown
  outResult.outputEquivalencePending =
    outResult.boundaryValid and outResult.waitExitValid and
      not outResult.noCompletionInterrupt and outResult.outputGateKnown
  if outResult.completionSignalMissing:
    outResult.reason = blaiParsedConfiguredActiveGapCompletionSignal
  elif outResult.outputEquivalencePending:
    outResult.reason = blaiParsedConfiguredActiveGapOutputEquivalence
  else:
    outResult.reason = blaiParsedConfiguredActiveGapNone
  outResult.reasonMatchesEvidence =
    (outResult.reason == blaiParsedConfiguredActiveGapCompletionSignal and
      outResult.completionSignalMissing) or
    (outResult.reason == blaiParsedConfiguredActiveGapOutputEquivalence and
      outResult.outputEquivalencePending) or
    (outResult.reason == blaiParsedConfiguredActiveGapNone and
      not outResult.completionSignalMissing and
      not outResult.outputEquivalencePending)
  outResult.remainingCompletionProgress =
    boundary.remainingCompletionProgress and outResult.noCompletionInterrupt and
      outResult.waitExitKnown and outResult.outputGateKnown
  outResult.valid =
    outResult.boundaryValid and outResult.waitExitValid and
      outResult.outputBlockedValid and outResult.reasonMatchesEvidence and
      outResult.remainingCompletionProgress

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidence*(
    boundary: BlaiParsedForwardConfiguredWorkspaceActiveCompletionBoundaryEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    outputBlocked: BlaiParsedForwardConfiguredWorkspaceActiveOutputBlockedEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidence =
  ## Convenience wrapper for the remaining active completion gap.
  blaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidenceInto(
    boundary, waitExit, outputBlocked, result)

proc blaiParsedForwardConfiguredWorkspaceCompletionSignalEvidenceInto*(
    runtime: BlaiNpuRuntimeOwnershipPlan,
    binding: NpuInterruptBindingReadiness,
    policy: BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    gap: BlaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence) =
  ## Derive focused evidence for the active completion notification source.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence)
  outResult.sdkSemaphoreExpected =
    runtime.sdkInterruptWait == blaiNpuRuntimeWaitSdkCountingSemaphore
  outResult.sdkCnnIrqRequested = binding.requested and binding.enableRequested
  outResult.sdkPriorityMatched =
    binding.irqMatchesSdk and binding.priorityMatchesSdk
  outResult.d0ApuLineCandidate = binding.d0ApuLineCandidate
  outResult.m0LineConflict = binding.m0LineConflict
  outResult.m0BindingSafe = binding.m0BindingSafe
  outResult.coreBindingPolicyValid = binding.corePolicy.valid
  outResult.coreBindingDecisionMatches =
    binding.corePolicy.decisionMatchesEvidence
  outResult.m0PollingRequired = binding.corePolicy.m0PollingRequired
  outResult.d0BindingCandidate = binding.corePolicy.d0BindingCandidate
  outResult.operationPlanValid = binding.operationPlan.valid
  outResult.operationPlanSuppressed =
    binding.operationPlan.activeOperationsSuppressed
  outResult.operationPlanPreservesPolling =
    binding.operationPlan.m0PollingPreserved
  let glbRoute = npuInterruptGlbRouteMap(
    NpuInterruptConfig(
      irq: binding.lineOwnership.irq,
      preemptPriority: NpuCnnIrqPreemptPriority,
      subPriority: NpuCnnIrqSubPriority,
      enable: true))
  let mmAggregateRoute = npuMmAggregateInterruptRouteEvidence(
    glbRoute, npuMmAggregateInterruptSnapshotFromRaw(0'u32, 0'u32, 0'u32, 0'u32))
  outResult.glbRouteValid = glbRoute.valid
  outResult.mmAggregateRouteValid = mmAggregateRoute.valid
  outResult.mmAggregateSurfaceKnown =
    mmAggregateRoute.registerSurfaceKnown and
      mmAggregateRoute.aggregateSourceAvailable
  outResult.mmAggregateSubrouteUnknown = mmAggregateRoute.subrouteUnknown
  outResult.mmAggregatePollingPreserved = mmAggregateRoute.pollingPreserved
  outResult.localBindingVerified = binding.bindingVerified
  outResult.activePolling =
    runtime.activeInterruptWait == blaiNpuRuntimeWaitBareMetalPolling and
      binding.activeWaitIsPolling
  outResult.waitConfigured = policy.waitConfigured
  outResult.streamStarted = policy.started
  outResult.noCompletionInterrupt =
    policy.noInterrupt and waitExit.noCompletionInterrupt and
      gap.noCompletionInterrupt
  outResult.waitExitActive =
    waitExit.idleMode or waitExit.writeActiveMode or waitExit.readActiveMode or
      waitExit.readWriteActiveMode
  outResult.timeoutTerminal =
    policy.statusTimedOut and waitExit.timeoutValid and
      gap.completionSignalMissing
  outResult.completionSignalMissing =
    gap.completionSignalMissing and outResult.noCompletionInterrupt
  if outResult.activePolling:
    outResult.source = blaiParsedConfiguredCompletionSignalBareMetalPolling
  elif outResult.sdkSemaphoreExpected:
    outResult.source = blaiParsedConfiguredCompletionSignalSdkCnnIrqSemaphore
  else:
    outResult.source = blaiParsedConfiguredCompletionSignalNone
  outResult.sourceMatchesRuntime =
    (outResult.source == blaiParsedConfiguredCompletionSignalBareMetalPolling and
      outResult.activePolling) or
    (outResult.source == blaiParsedConfiguredCompletionSignalSdkCnnIrqSemaphore and
      outResult.sdkSemaphoreExpected and not outResult.activePolling) or
    (outResult.source == blaiParsedConfiguredCompletionSignalNone and
      not outResult.sdkSemaphoreExpected and not outResult.activePolling)
  outResult.bindingBlocksIrq =
      outResult.sdkCnnIrqRequested and outResult.sdkPriorityMatched and
      outResult.d0ApuLineCandidate and outResult.m0LineConflict and
      outResult.m0PollingRequired and not outResult.m0BindingSafe and
      not outResult.localBindingVerified and not binding.ready
  outResult.pollingObservedMissingSignal =
    outResult.activePolling and outResult.waitConfigured and
      outResult.streamStarted and outResult.noCompletionInterrupt and
      outResult.waitExitActive and outResult.timeoutTerminal
  outResult.valid =
    outResult.sdkSemaphoreExpected and outResult.sdkCnnIrqRequested and
      outResult.sdkPriorityMatched and outResult.d0ApuLineCandidate and
      outResult.m0LineConflict and not outResult.m0BindingSafe and
      outResult.coreBindingPolicyValid and outResult.coreBindingDecisionMatches and
      outResult.m0PollingRequired and outResult.d0BindingCandidate and
      outResult.operationPlanValid and outResult.operationPlanSuppressed and
      outResult.operationPlanPreservesPolling and outResult.glbRouteValid and
      outResult.mmAggregateRouteValid and outResult.mmAggregateSurfaceKnown and
      outResult.mmAggregateSubrouteUnknown and
      outResult.mmAggregatePollingPreserved and outResult.activePolling and
      outResult.sourceMatchesRuntime and outResult.bindingBlocksIrq and
      outResult.pollingObservedMissingSignal and
      outResult.completionSignalMissing

proc blaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence*(
    runtime: BlaiNpuRuntimeOwnershipPlan,
    binding: NpuInterruptBindingReadiness,
    policy: BlaiParsedForwardConfiguredWorkspaceActiveCompletionPolicyEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    gap: BlaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidence):
    BlaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence =
  ## Convenience wrapper for active completion signal-source evidence.
  blaiParsedForwardConfiguredWorkspaceCompletionSignalEvidenceInto(
    runtime, binding, policy, waitExit, gap, result)

proc blaiParsedForwardConfiguredWorkspaceActivePollingSignalEvidenceInto*(
    signal: BlaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence,
    waitBudget:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionWaitBudgetEvidence,
    polling: BlaiNpuPollingWaitEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActivePollingSignalEvidence) =
  ## Derive evidence that the missing completion signal is observed by polling.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActivePollingSignalEvidence)
  outResult.signalValid = signal.valid
  outResult.waitBudgetValid = waitBudget.valid
  outResult.pollingValid = polling.valid
  outResult.activePolling = signal.activePolling
  outResult.pollingSource =
    signal.source == blaiParsedConfiguredCompletionSignalBareMetalPolling
  outResult.fullBudgetConsumed =
    polling.budgetExhausted and polling.budgetMatchesPolls and
      polling.actualPolls == polling.pollBudget and
      waitBudget.pollBudgetExhausted
  outResult.finalSampleClear =
    not polling.finalInterruptPending and waitBudget.waitExitNoInterrupt
  outResult.noInterruptObserved =
    not polling.interruptObserved and waitBudget.noInterruptObserved and
      signal.noCompletionInterrupt
  outResult.timeoutTerminal =
    polling.terminal == blaiNpuPollingWaitTimeout and
      signal.timeoutTerminal and waitBudget.deterministicTimeout
  outResult.missingSignal =
    signal.completionSignalMissing and signal.pollingObservedMissingSignal
  outResult.bindingStillDeferred =
    signal.bindingBlocksIrq and signal.m0PollingRequired and
      not signal.localBindingVerified
  outResult.signalMatchesPollTrace =
    outResult.activePolling and outResult.pollingSource and
      outResult.fullBudgetConsumed and outResult.finalSampleClear and
      outResult.noInterruptObserved and outResult.timeoutTerminal and
      outResult.missingSignal and outResult.bindingStillDeferred
  outResult.valid =
    outResult.signalValid and outResult.waitBudgetValid and
      outResult.pollingValid and outResult.signalMatchesPollTrace

proc blaiParsedForwardConfiguredWorkspaceActivePollingSignalEvidence*(
    signal: BlaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence,
    waitBudget:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionWaitBudgetEvidence,
    polling: BlaiNpuPollingWaitEvidence):
    BlaiParsedForwardConfiguredWorkspaceActivePollingSignalEvidence =
  ## Convenience wrapper for active polling-signal evidence.
  blaiParsedForwardConfiguredWorkspaceActivePollingSignalEvidenceInto(
    signal, waitBudget, polling, result)

proc blaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidenceInto*(
    signal: BlaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence,
    snapshot: NpuMmAggregateInterruptSnapshot,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidence) =
  ## Classify the live MM aggregate wait-exit sample without naming a subroute.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidence)
  let catalog = npuMmAggregateSubrouteCatalogEvidence()
  outResult.signalValid = signal.valid
  outResult.routeValid = signal.mmAggregateRouteValid
  outResult.catalogValid = catalog.valid
  outResult.snapshotValid = snapshot.valid
  outResult.bank0Known = snapshot.bank0Known
  outResult.bank1E907Known = snapshot.bank1E907Known
  outResult.rawBitmapBanksKnown = catalog.rawBitmapBanksKnown
  outResult.clearPlanMatchesRaw =
    snapshot.clearWriteOne and snapshot.clear0 == snapshot.status0 and
      snapshot.clear1 == snapshot.status1
  outResult.noBlaiInterrupt = signal.noCompletionInterrupt
  outResult.anyRawStatus = snapshot.anyRawStatus
  outResult.anyUnmaskedPending = snapshot.anyUnmaskedPending
  outResult.noUnmaskedPending = not snapshot.anyUnmaskedPending
  outResult.allRawStatusMasked = snapshot.allRawStatusMasked
  outResult.pendingClass = snapshot.pendingClass
  outResult.pendingClassMatchesSnapshot =
    (outResult.pendingClass == npuMmAggregatePendingUnmasked and
      outResult.anyUnmaskedPending) or
    (outResult.pendingClass == npuMmAggregatePendingMaskedOnly and
      outResult.allRawStatusMasked) or
    (outResult.pendingClass == npuMmAggregatePendingNone and
      not outResult.anyRawStatus and outResult.noUnmaskedPending)
  outResult.pendingClassificationKnown =
    outResult.pendingClassMatchesSnapshot
  npuMmAggregatePendingIndexScanEvidenceInto(snapshot, outResult.pendingScan)
  outResult.pendingScanValid = outResult.pendingScan.valid
  outResult.rawPendingCount = outResult.pendingScan.rawPendingCount
  outResult.unmaskedPendingCount = outResult.pendingScan.unmaskedPendingCount
  outResult.maskedOnlyCount = outResult.pendingScan.maskedOnlyCount
  outResult.firstRawPendingIndex = outResult.pendingScan.firstRawPendingIndex
  outResult.firstUnmaskedPendingIndex =
    outResult.pendingScan.firstUnmaskedPendingIndex
  outResult.firstMaskedOnlyIndex = outResult.pendingScan.firstMaskedOnlyIndex
  outResult.noNamedNpuSubroute = catalog.noNamedNpuSubroute
  outResult.subrouteUnknown = signal.mmAggregateSubrouteUnknown
  outResult.pollingPreserved = signal.mmAggregatePollingPreserved
  if not outResult.signalValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitSignal
  elif not outResult.routeValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitRoute
  elif not outResult.catalogValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitCatalog
  elif not outResult.snapshotValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitSnapshot
  elif not outResult.bank0Known:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitBank0
  elif not outResult.bank1E907Known:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitBank1
  elif not outResult.rawBitmapBanksKnown:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitRawBanks
  elif not outResult.clearPlanMatchesRaw:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitClearPlan
  elif not outResult.noBlaiInterrupt:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitInterrupt
  elif not outResult.pendingClassificationKnown:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitPendingClass
  elif not outResult.pendingScanValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitPendingScan
  elif not outResult.noNamedNpuSubroute:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitNamedSubroute
  elif not outResult.subrouteUnknown:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitSubroute
  elif not outResult.pollingPreserved:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitPolling
  else:
    outResult.firstBlock =
      blaiParsedConfiguredActiveMmAggregateWaitExitNoBlock
  outResult.valid =
    outResult.signalValid and outResult.routeValid and outResult.catalogValid and
      outResult.snapshotValid and
      outResult.bank0Known and outResult.bank1E907Known and
      outResult.rawBitmapBanksKnown and outResult.clearPlanMatchesRaw and
      outResult.noBlaiInterrupt and outResult.pendingClassMatchesSnapshot and
      outResult.pendingClassificationKnown and outResult.pendingScanValid and
      outResult.subrouteUnknown and outResult.noNamedNpuSubroute and
      outResult.pollingPreserved

proc blaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidence*(
    signal: BlaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence,
    snapshot: NpuMmAggregateInterruptSnapshot):
    BlaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidence =
  ## Convenience wrapper for active MM aggregate wait-exit evidence.
  blaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidenceInto(
    signal, snapshot, result)

proc blaiParsedForwardConfiguredWorkspaceActiveLocalAggregateInterruptEvidenceInto*(
    polling: BlaiNpuPollingWaitEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    aggregate:
      BlaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveLocalAggregateInterruptEvidence) =
  ## Compare local BLAI interrupt status with the live MM aggregate snapshot.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveLocalAggregateInterruptEvidence)
  outResult.pollingValid = polling.valid
  outResult.waitExitValid = waitExit.valid
  outResult.aggregateValid = aggregate.valid
  outResult.localPollBitClear =
    not polling.interruptObserved and not polling.finalInterruptPending
  outResult.localWaitExitBitClear = waitExit.noCompletionInterrupt
  outResult.localInterruptClear =
    outResult.localPollBitClear and outResult.localWaitExitBitClear
  outResult.aggregateNoRawPending =
    not aggregate.anyRawStatus and aggregate.rawPendingCount == 0'u32
  outResult.aggregateNoUnmaskedPending =
    aggregate.noUnmaskedPending and aggregate.unmaskedPendingCount == 0'u32
  outResult.aggregateNoMaskedPending =
    not aggregate.allRawStatusMasked and aggregate.maskedOnlyCount == 0'u32
  outResult.aggregateNoCompletionCandidate =
    aggregate.noBlaiInterrupt and outResult.aggregateNoRawPending and
      outResult.aggregateNoUnmaskedPending and outResult.aggregateNoMaskedPending
  outResult.aggregateRouteUnresolved =
    aggregate.noNamedNpuSubroute and aggregate.subrouteUnknown
  outResult.pollingPreserved = aggregate.pollingPreserved
  outResult.timeoutTerminal =
    polling.terminal == blaiNpuPollingWaitTimeout and waitExit.timeoutValid
  outResult.localAndAggregateAgree =
    outResult.localInterruptClear and outResult.aggregateNoCompletionCandidate and
      outResult.aggregateRouteUnresolved and outResult.pollingPreserved
  outResult.completionSignalMissing =
    outResult.pollingValid and outResult.waitExitValid and
      outResult.aggregateValid and outResult.timeoutTerminal and
      outResult.localAndAggregateAgree
  if not outResult.pollingValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveLocalAggregateInterruptPolling
  elif not outResult.waitExitValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveLocalAggregateInterruptWaitExit
  elif not outResult.aggregateValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveLocalAggregateInterruptAggregate
  elif not outResult.localInterruptClear:
    outResult.firstBlock =
      blaiParsedConfiguredActiveLocalAggregateInterruptLocalBit
  elif not outResult.aggregateNoCompletionCandidate:
    outResult.firstBlock =
      blaiParsedConfiguredActiveLocalAggregateInterruptAggregateBits
  elif not (outResult.aggregateRouteUnresolved and outResult.pollingPreserved):
    outResult.firstBlock =
      blaiParsedConfiguredActiveLocalAggregateInterruptRoute
  elif not outResult.timeoutTerminal:
    outResult.firstBlock =
      blaiParsedConfiguredActiveLocalAggregateInterruptTerminal
  else:
    outResult.firstBlock =
      blaiParsedConfiguredActiveLocalAggregateInterruptNoBlock
  outResult.valid =
    outResult.completionSignalMissing and
      outResult.firstBlock ==
        blaiParsedConfiguredActiveLocalAggregateInterruptNoBlock

proc blaiParsedForwardConfiguredWorkspaceActiveLocalAggregateInterruptEvidence*(
    polling: BlaiNpuPollingWaitEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    aggregate:
      BlaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveLocalAggregateInterruptEvidence =
  ## Convenience wrapper for local/aggregate interrupt evidence.
  blaiParsedForwardConfiguredWorkspaceActiveLocalAggregateInterruptEvidenceInto(
    polling, waitExit, aggregate, result)

proc blaiParsedForwardConfiguredWorkspaceActiveCommandIdleEvidenceInto*(
    command: NpuBlaiCommandStatusResult,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    interrupt:
      BlaiParsedForwardConfiguredWorkspaceActiveLocalAggregateInterruptEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveCommandIdleEvidence) =
  ## Tie live BLAI command-counter diagnostics to the active idle timeout.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveCommandIdleEvidence)
  outResult.commandStatusValid = command.valid
  outResult.waitExitValid = waitExit.valid
  outResult.localAggregateValid = interrupt.valid
  outResult.mmCounterClear = command.mmCommandCount == 0'u32
  outResult.readCounterClear = command.readCommandCount == 0'u32
  outResult.writeCounterClear = command.writeCommandCount == 0'u32
  outResult.countersClear =
    outResult.mmCounterClear and outResult.readCounterClear and
      outResult.writeCounterClear and not command.anyCommandCount
  outResult.mmModeClear = not command.mmCommandMode
  outResult.readModeClear = not command.readCommandMode
  outResult.writeModeClear = not command.writeCommandMode
  outResult.modesClear =
    outResult.mmModeClear and outResult.readModeClear and
      outResult.writeModeClear and not command.anyCommandMode
  outResult.noCommandActivity =
    outResult.commandStatusValid and outResult.countersClear and
      outResult.modesClear
  outResult.waitExitIdle =
    waitExit.idleMode and waitExit.busyOrIdleKnown and waitExit.axiActivityKnown
  outResult.noCompletionInterrupt =
    waitExit.noCompletionInterrupt and interrupt.localInterruptClear
  outResult.completionSignalMissing = interrupt.completionSignalMissing
  outResult.commandIdleMatchesWaitExit =
    outResult.noCommandActivity and outResult.waitExitIdle and
      outResult.noCompletionInterrupt and outResult.completionSignalMissing
  outResult.valid =
    outResult.commandStatusValid and outResult.waitExitValid and
      outResult.localAggregateValid and outResult.commandIdleMatchesWaitExit

proc blaiParsedForwardConfiguredWorkspaceActiveCommandIdleEvidence*(
    command: NpuBlaiCommandStatusResult,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    interrupt:
      BlaiParsedForwardConfiguredWorkspaceActiveLocalAggregateInterruptEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveCommandIdleEvidence =
  ## Convenience wrapper for active command-idle evidence.
  blaiParsedForwardConfiguredWorkspaceActiveCommandIdleEvidenceInto(
    command, waitExit, interrupt, result)

proc blaiParsedForwardConfiguredWorkspaceActiveLaunchGapEvidenceInto*(
    retention: BlaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidence,
    engine: BlaiParsedForwardConfiguredWorkspaceActiveEngineProgressEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    interrupt:
      BlaiParsedForwardConfiguredWorkspaceActiveLocalAggregateInterruptEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveLaunchGapEvidence) =
  ## Bind retained launch state to the active missing-completion frontier.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveLaunchGapEvidence)
  outResult.launchRetentionValid = retention.valid
  outResult.engineProgressValid = engine.valid
  outResult.waitExitValid = waitExit.valid
  outResult.localAggregateValid = interrupt.valid
  outResult.launchAddressesRetained =
    retention.addressRetained and retention.segmentRetained
  outResult.launchNetRetained = retention.netRetained
  outResult.launchCommandsClean =
    retention.launchCommandsClean and retention.startedCommandsClean
  outResult.startObserved =
    retention.startObserved and retention.snapshotStartedMatches
  outResult.engineStarted = engine.executionStarted
  outResult.executionIncomplete = engine.executionIncomplete
  outResult.waitExitKnown =
    waitExit.timeoutValid and waitExit.commandBitsClean and
      waitExit.busyOrIdleKnown and waitExit.axiActivityKnown and
      waitExit.clockRetained and waitExit.statusValid
  outResult.localAggregateMissing = interrupt.completionSignalMissing
  outResult.completionSignalMissing =
    outResult.waitExitKnown and outResult.localAggregateMissing
  outResult.launchStateReachesCompletionGap =
    outResult.launchRetentionValid and outResult.engineProgressValid and
      outResult.waitExitValid and outResult.localAggregateValid and
      outResult.launchAddressesRetained and outResult.launchNetRetained and
      outResult.launchCommandsClean and outResult.startObserved and
      outResult.engineStarted and outResult.executionIncomplete and
      outResult.completionSignalMissing
  if not outResult.launchRetentionValid:
    outResult.firstBlock = blaiParsedConfiguredActiveLaunchGapRetention
  elif not outResult.engineProgressValid:
    outResult.firstBlock = blaiParsedConfiguredActiveLaunchGapEngine
  elif not outResult.waitExitValid:
    outResult.firstBlock = blaiParsedConfiguredActiveLaunchGapWaitExit
  elif not outResult.localAggregateValid:
    outResult.firstBlock = blaiParsedConfiguredActiveLaunchGapInterrupt
  elif not outResult.completionSignalMissing:
    outResult.firstBlock = blaiParsedConfiguredActiveLaunchGapTerminal
  else:
    outResult.firstBlock = blaiParsedConfiguredActiveLaunchGapNoBlock
  outResult.valid =
    outResult.launchStateReachesCompletionGap and
      outResult.firstBlock == blaiParsedConfiguredActiveLaunchGapNoBlock

proc blaiParsedForwardConfiguredWorkspaceActiveLaunchGapEvidence*(
    retention: BlaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidence,
    engine: BlaiParsedForwardConfiguredWorkspaceActiveEngineProgressEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    interrupt:
      BlaiParsedForwardConfiguredWorkspaceActiveLocalAggregateInterruptEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveLaunchGapEvidence =
  ## Convenience wrapper for active launch-to-completion-gap evidence.
  blaiParsedForwardConfiguredWorkspaceActiveLaunchGapEvidenceInto(
    retention, engine, waitExit, interrupt, result)

proc blaiParsedForwardConfiguredWorkspaceActiveStartEdgeEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    retention: BlaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveStartEdgeEvidence) =
  ## Classify the immediate BLAI register transition around the start command.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveStartEdgeEvidence)
  outResult.launchCaptured = snapshot.launchRegistersCaptured
  outResult.startedCaptured = snapshot.startedRegistersCaptured
  outResult.waitExitValid = waitExit.valid
  outResult.startObserved =
    retention.startObserved and retention.snapshotStartedMatches
  outResult.segmentStable = retention.segmentRetained
  outResult.netStable = retention.netRetained
  outResult.registersRetained =
    retention.valid and retention.addressRetained and
      outResult.segmentStable and outResult.netStable
  outResult.launchIdle =
    not snapshot.launchRegisters.busy and snapshot.launchRegisters.axiWriteIdle and
      snapshot.launchRegisters.axiReadIdle
  outResult.startedIdle =
    not snapshot.startedRegisters.busy and snapshot.startedRegisters.axiWriteIdle and
      snapshot.startedRegisters.axiReadIdle
  outResult.waitExitIdle = waitExit.idleMode
  outResult.startCommandSelfCleared =
    not snapshot.startedRegisters.startRequested
  outResult.commandBitsCleanAfterStart =
    outResult.startCommandSelfCleared and
      not snapshot.startedRegisters.resumeRequested and
      not snapshot.startedRegisters.stopRequested and
      not snapshot.startedRegisters.clearRequested
  outResult.noPostStartInterrupt =
    not snapshot.startedRegisters.interruptPending
  outResult.noWaitExitInterrupt = waitExit.noCompletionInterrupt
  outResult.busyEdgeObserved =
    snapshot.startedRegisters.busy or
      not snapshot.startedRegisters.axiWriteIdle or
      not snapshot.startedRegisters.axiReadIdle
  outResult.interruptEdgeObserved =
    snapshot.startedRegisters.interruptPending
  outResult.noImmediateBusyOrInterruptEdge =
    not outResult.busyEdgeObserved and not outResult.interruptEdgeObserved
  outResult.classifiedAsIdleNoCompletion =
    outResult.launchCaptured and outResult.startedCaptured and
      outResult.waitExitValid and outResult.startObserved and
      outResult.registersRetained and outResult.launchIdle and
      outResult.startedIdle and outResult.waitExitIdle and
      outResult.commandBitsCleanAfterStart and
      outResult.noPostStartInterrupt and outResult.noWaitExitInterrupt and
      outResult.noImmediateBusyOrInterruptEdge
  outResult.valid = outResult.classifiedAsIdleNoCompletion

proc blaiParsedForwardConfiguredWorkspaceActiveStartEdgeEvidence*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    retention: BlaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidence,
    waitExit: BlaiParsedForwardConfiguredWorkspaceActiveWaitExitEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveStartEdgeEvidence =
  ## Convenience wrapper for active start-edge evidence.
  blaiParsedForwardConfiguredWorkspaceActiveStartEdgeEvidenceInto(
    snapshot, retention, waitExit, result)

proc blaiParsedForwardConfiguredWorkspaceActiveStartCommandSurfaceEvidenceInto*(
    snapshot: BlaiParsedForwardConfiguredWorkspaceFixtureGateSnapshot,
    retention: BlaiParsedForwardConfiguredWorkspaceLaunchRetentionEvidence,
    startEdge: BlaiParsedForwardConfiguredWorkspaceActiveStartEdgeEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveStartCommandSurfaceEvidence) =
  ## Prove the active live start path matches the recovered SDK command surface.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveStartCommandSurfaceEvidence)
  outResult.startEdgeValid = startEdge.valid
  outResult.launchCaptured = snapshot.launchRegistersCaptured
  outResult.startedCaptured = snapshot.startedRegistersCaptured
  outResult.waitExitBusyCaptured =
    snapshot.lastExecutionStarted and
      snapshot.lastExecutionWaitExitBusy.generalCfg != 0'u32
  outResult.generalStableToStart =
    snapshot.launchRegisters.generalCfg ==
      snapshot.startedRegisters.generalCfg
  outResult.generalStableToWaitExit =
    snapshot.startedRegisters.generalCfg ==
      snapshot.lastExecutionWaitExitBusy.generalCfg
  outResult.intCfgCleanBeforeStart =
    not snapshot.launchRegisters.startRequested and
      not snapshot.launchRegisters.resumeRequested and
      not snapshot.launchRegisters.stopRequested and
      not snapshot.launchRegisters.clearRequested and
      not snapshot.launchRegisters.interruptPending
  outResult.intCfgCleanAfterStart =
    not snapshot.startedRegisters.startRequested and
      not snapshot.startedRegisters.resumeRequested and
      not snapshot.startedRegisters.stopRequested and
      not snapshot.startedRegisters.clearRequested and
      not snapshot.startedRegisters.interruptPending
  outResult.startSelfCleared = startEdge.startCommandSelfCleared
  outResult.noResumeStopClearAfterStart =
    not snapshot.startedRegisters.resumeRequested and
      not snapshot.startedRegisters.stopRequested and
      not snapshot.startedRegisters.clearRequested
  outResult.addressesRetained = retention.addressRetained
  outResult.netRetained = retention.netRetained
  outResult.noBusyAfterStart =
    not snapshot.startedRegisters.busy and
      not snapshot.lastExecutionWaitExitBusy.busy and
      startEdge.noImmediateBusyOrInterruptEdge
  outResult.noInterruptAfterStart =
    not snapshot.startedRegisters.interruptPending and
      startEdge.noPostStartInterrupt and startEdge.noWaitExitInterrupt
  outResult.startOnlyTouchesIntCfg =
    outResult.generalStableToStart and outResult.generalStableToWaitExit and
      outResult.intCfgCleanBeforeStart and outResult.intCfgCleanAfterStart and
      outResult.startSelfCleared and outResult.noResumeStopClearAfterStart
  outResult.valid =
    outResult.startEdgeValid and outResult.launchCaptured and
      outResult.startedCaptured and outResult.waitExitBusyCaptured and
      outResult.startOnlyTouchesIntCfg and outResult.addressesRetained and
      outResult.netRetained and outResult.noBusyAfterStart and
      outResult.noInterruptAfterStart

