proc blaiParsedForwardConfiguredWorkspaceActiveRecoveryFrontierEvidenceInto*(
    cleanup: BlaiParsedForwardConfiguredWorkspaceActiveExitCleanupEvidence,
    gap: BlaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidence,
    signal: BlaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveRecoveryFrontierEvidence) =
  ## Classify the current active recovery frontier after coherent cleanup.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveRecoveryFrontierEvidence)
  outResult.cleanupValid = cleanup.valid
  outResult.gapValid = gap.valid
  outResult.signalValid = signal.valid
  outResult.cleanupComplete =
    cleanup.cleanupCoherent and cleanup.clockDisabled and
      cleanup.stoppedAfterTimeout and cleanup.invalidateDeferred and
      cleanup.outputReadbackDeferred
  outResult.completionSignalMissing =
    gap.completionSignalMissing and signal.completionSignalMissing and
      signal.pollingObservedMissingSignal
  outResult.activePolling = signal.activePolling
  outResult.m0PollingRequired =
    signal.m0PollingRequired and signal.bindingBlocksIrq
  outResult.outputEquivalenceNotPending = not gap.outputEquivalencePending
  outResult.frontierMatchesEvidence =
    outResult.cleanupComplete and outResult.completionSignalMissing and
      outResult.activePolling and outResult.m0PollingRequired and
      outResult.outputEquivalenceNotPending
  outResult.valid =
    outResult.cleanupValid and outResult.gapValid and outResult.signalValid and
      outResult.frontierMatchesEvidence

