proc blaiParsedForwardConfiguredWorkspaceActiveCompletionRouteAggregateEvidenceInto*(
    frontier: BlaiParsedForwardConfiguredWorkspaceActiveRecoveryFrontierEvidence,
    signal: BlaiParsedForwardConfiguredWorkspaceCompletionSignalEvidence,
    aggregate:
      BlaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidence,
    route: BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteAggregateEvidence) =
  ## Classify the active completion route against the live aggregate sample.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteAggregateEvidence)
  outResult.frontierValid = frontier.valid
  outResult.signalValid = signal.valid
  outResult.aggregateWaitExitValid = aggregate.valid
  outResult.routeTargetValid = route.valid
  outResult.liveAggregateSnapshotValid =
    aggregate.snapshotValid and aggregate.bank0Known and aggregate.bank1E907Known
  outResult.noBlaiInterrupt =
    aggregate.noBlaiInterrupt and signal.noCompletionInterrupt and
      frontier.completionSignalMissing
  outResult.subrouteUnknown =
    aggregate.subrouteUnknown and signal.mmAggregateSubrouteUnknown and
      route.mmAggregateSubrouteUnknown
  outResult.pollingPreserved =
    aggregate.pollingPreserved and signal.mmAggregatePollingPreserved and
      route.mmAggregatePollingPreserved and frontier.activePolling
  outResult.routeTargetDeferred =
    route.localBindingDeferred and route.routeOperationsDeferred
  outResult.routeMatchesLiveAggregate =
    outResult.liveAggregateSnapshotValid and outResult.noBlaiInterrupt and
      outResult.subrouteUnknown and outResult.pollingPreserved and
      outResult.routeTargetDeferred
  if not outResult.frontierValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteAggregateFrontier
  elif not outResult.signalValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteAggregateSignal
  elif not outResult.aggregateWaitExitValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteAggregateWaitExit
  elif not outResult.routeTargetValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteAggregateRouteTarget
  elif not outResult.liveAggregateSnapshotValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteAggregateSnapshot
  elif not outResult.noBlaiInterrupt:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteAggregateInterrupt
  elif not outResult.subrouteUnknown:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteAggregateSubroute
  elif not outResult.pollingPreserved:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteAggregatePolling
  elif not outResult.routeTargetDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteAggregateDeferredTarget
  else:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteAggregateNoBlock
  outResult.valid =
    outResult.frontierValid and outResult.signalValid and
      outResult.aggregateWaitExitValid and outResult.routeTargetValid and
      outResult.routeMatchesLiveAggregate

