proc blaiParsedForwardConfiguredWorkspaceActiveLiveRouteEvidenceInto*(
    route: BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    aggregate:
      BlaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidence,
    liveRoute: NpuMmAggregateInterruptRouteEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveLiveRouteEvidence) =
  ## Bind the active completion route to the live aggregate snapshot route.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveLiveRouteEvidence)
  outResult.routeTargetValid = route.valid
  outResult.aggregateWaitExitValid = aggregate.valid
  outResult.liveRouteValid = liveRoute.valid
  outResult.liveSnapshotValid =
    liveRoute.rawSnapshotValid and aggregate.snapshotValid and
      aggregate.bank0Known and aggregate.bank1E907Known
  outResult.noRawPending =
    not aggregate.anyRawStatus and aggregate.rawPendingCount == 0'u32
  outResult.noUnmaskedPending =
    aggregate.noUnmaskedPending and aggregate.unmaskedPendingCount == 0'u32
  outResult.noMaskedOnlyPending =
    not aggregate.allRawStatusMasked and aggregate.maskedOnlyCount == 0'u32
  outResult.noNamedNpuSubroute =
    aggregate.noNamedNpuSubroute and liveRoute.noNamedNpuSubroute
  outResult.subrouteUnknown =
    route.mmAggregateSubrouteUnknown and aggregate.subrouteUnknown and
      liveRoute.subrouteUnknown
  outResult.pollingPreserved =
    route.mmAggregatePollingPreserved and aggregate.pollingPreserved and
      liveRoute.pollingPreserved
  outResult.noBlaiInterrupt = aggregate.noBlaiInterrupt
  outResult.routeMatchesTarget =
    route.glbRouteValid and route.mmAggregateRouteValid and
      liveRoute.routeValid and liveRoute.aggregateSourceAvailable
  outResult.routeMatchesLiveSnapshot =
    outResult.liveSnapshotValid and outResult.noRawPending and
      outResult.noUnmaskedPending and outResult.noMaskedOnlyPending and
      outResult.noNamedNpuSubroute and outResult.subrouteUnknown and
      outResult.pollingPreserved and outResult.noBlaiInterrupt
  outResult.valid =
    outResult.routeTargetValid and outResult.aggregateWaitExitValid and
      outResult.liveRouteValid and outResult.routeMatchesTarget and
      outResult.routeMatchesLiveSnapshot

