proc blaiParsedForwardConfiguredWorkspaceActiveCompletionToOutputHandoffEvidenceInto*(
    route:
      BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    routeAggregate:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteAggregateEvidence,
    outputScope:
      BlaiParsedForwardConfiguredWorkspaceActiveOutputTransferScopeEvidence,
    outputFrontier:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceFrontierEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveCompletionToOutputHandoffEvidence) =
  ## Classify the next active target after the completion route is recovered.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveCompletionToOutputHandoffEvidence)
  outResult.routeTargetValid = route.valid
  outResult.routeAggregateValid = routeAggregate.valid
  outResult.outputScopeValid = outputScope.valid
  outResult.outputFrontierValid = outputFrontier.valid
  outResult.routeDeferred =
    route.localBindingDeferred and route.apiCallsDeferred and
      route.routeOperationsDeferred
  outResult.liveRouteAggregate =
    routeAggregate.routeMatchesLiveAggregate and
      routeAggregate.liveAggregateSnapshotValid and
      routeAggregate.routeTargetDeferred
  outResult.primaryOnlyOutput =
    outputScope.primaryOnly and outputScope.midOutputInactive and
      outputScope.midInvalidateInactive
  outResult.readbackReady =
    outputScope.scopeMatchesReadbackPlan and outputScope.primaryInvalidateActive
  outResult.outputEquivalenceDeferred =
    outputFrontier.outputEquivalenceDeferred and
      outputFrontier.outputReadbackNotStarted and
      outputFrontier.compareNotStarted
  outResult.outputNextAfterCompletion =
    outputFrontier.outputEquivalenceNextAfterCompletion and
      outputScope.scopeMatchesReadbackPlan
  outResult.handoffMatchesEvidence =
    outResult.routeDeferred and outResult.liveRouteAggregate and
      outResult.primaryOnlyOutput and outResult.readbackReady and
      outResult.outputEquivalenceDeferred and outResult.outputNextAfterCompletion
  outResult.valid =
    outResult.routeTargetValid and outResult.routeAggregateValid and
      outResult.outputScopeValid and outResult.outputFrontierValid and
      outResult.handoffMatchesEvidence

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionToOutputHandoffEvidence*(
