proc blaiParsedForwardConfiguredWorkspaceActivePostBudgetOutputGateEvidenceInto*(
    waitBudget:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionWaitBudgetEvidence,
    outputScope:
      BlaiParsedForwardConfiguredWorkspaceActiveOutputTransferScopeEvidence,
    outputFrontier:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceFrontierEvidence,
    handoff:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionToOutputHandoffEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActivePostBudgetOutputGateEvidence) =
  ## Derive evidence for the output gate after the active polling budget expires.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActivePostBudgetOutputGateEvidence)
  outResult.waitBudgetValid = waitBudget.valid
  outResult.outputScopeValid = outputScope.valid
  outResult.outputFrontierValid = outputFrontier.valid
  outResult.handoffValid = handoff.valid
  outResult.deterministicTimeout = waitBudget.deterministicTimeout
  outResult.noCompletionInterrupt =
    waitBudget.noInterruptObserved and waitBudget.waitExitNoInterrupt
  outResult.liveRouteBackedHandoff =
    handoff.routeAggregateValid and handoff.liveRouteAggregate and
      handoff.handoffMatchesEvidence
  outResult.outputPlanReady =
    outputScope.scopeMatchesReadbackPlan and outputScope.primaryInvalidateActive and
      outputScope.primaryBytesKnown
  outResult.outputReadbackDeferred =
    outputFrontier.outputReadbackNotStarted and
      outputFrontier.outputEquivalenceDeferred
  outResult.compareDeferred =
    outputFrontier.compareNotStarted and
      outputFrontier.noOutputMismatchObserved
  outResult.primaryOnlyOutput =
    outputScope.primaryOnly and handoff.primaryOnlyOutput
  outResult.completionBeforeOutput =
    handoff.routeDeferred and handoff.outputNextAfterCompletion and
      outputFrontier.outputEquivalenceNextAfterCompletion
  outResult.nextStageOutputEquivalence =
    outResult.outputPlanReady and outResult.outputReadbackDeferred and
      outResult.compareDeferred and outResult.primaryOnlyOutput
  outResult.gateMatchesEvidence =
    outResult.deterministicTimeout and outResult.noCompletionInterrupt and
      outResult.liveRouteBackedHandoff and outResult.completionBeforeOutput and
      outResult.nextStageOutputEquivalence
  outResult.valid =
    outResult.waitBudgetValid and outResult.outputScopeValid and
      outResult.outputFrontierValid and outResult.handoffValid and
      outResult.gateMatchesEvidence

proc blaiParsedForwardConfiguredWorkspaceActivePostBudgetOutputGateEvidence*(
    waitBudget:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionWaitBudgetEvidence,
    outputScope:
      BlaiParsedForwardConfiguredWorkspaceActiveOutputTransferScopeEvidence,
    outputFrontier:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceFrontierEvidence,
