proc blaiParsedForwardConfiguredWorkspaceActiveGapOutputRouteEvidenceInto*(
    gap: BlaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidence,
    postBudget:
      BlaiParsedForwardConfiguredWorkspaceActivePostBudgetOutputGateEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveGapOutputRouteEvidence) =
  ## Bind the active completion gap's output gate to the live route-backed gate.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveGapOutputRouteEvidence)
  outResult.gapValid = gap.valid
  outResult.postBudgetGateValid = postBudget.valid
  outResult.completionSignalMissing = gap.completionSignalMissing
  outResult.gapOutputGateKnown = gap.outputGateKnown
  outResult.liveRouteBackedOutputGate =
    postBudget.liveRouteBackedHandoff and postBudget.gateMatchesEvidence
  outResult.outputEquivalenceDeferred =
    postBudget.outputReadbackDeferred and postBudget.compareDeferred and
      postBudget.nextStageOutputEquivalence
  outResult.reasonStillCompletionSignal =
    gap.reason == blaiParsedConfiguredActiveGapCompletionSignal and
      gap.reasonMatchesEvidence
  outResult.outputPendingDeferred =
    not gap.outputEquivalencePending and outResult.outputEquivalenceDeferred
  outResult.gapMatchesRouteGate =
    outResult.completionSignalMissing and outResult.gapOutputGateKnown and
      outResult.liveRouteBackedOutputGate and outResult.reasonStillCompletionSignal and
      outResult.outputPendingDeferred
  outResult.valid =
    outResult.gapValid and outResult.postBudgetGateValid and
      outResult.gapMatchesRouteGate

proc blaiParsedForwardConfiguredWorkspaceActiveGapOutputRouteEvidence*(
    gap: BlaiParsedForwardConfiguredWorkspaceActiveCompletionGapEvidence,
    postBudget:
      BlaiParsedForwardConfiguredWorkspaceActivePostBudgetOutputGateEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveGapOutputRouteEvidence =
  ## Convenience wrapper for active gap output-route evidence.
  blaiParsedForwardConfiguredWorkspaceActiveGapOutputRouteEvidenceInto(
    gap, postBudget, result)

proc blaiParsedForwardConfiguredWorkspaceActiveRecoveryRouteFrontierEvidenceInto*(
    frontier: BlaiParsedForwardConfiguredWorkspaceActiveRecoveryFrontierEvidence,
    routeAggregate:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteAggregateEvidence,
    gapRoute:
      BlaiParsedForwardConfiguredWorkspaceActiveGapOutputRouteEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveRecoveryRouteFrontierEvidence) =
  ## Bind the active recovery frontier to live route and output-gate evidence.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveRecoveryRouteFrontierEvidence)
  outResult.frontierValid = frontier.valid
  outResult.routeAggregateValid = routeAggregate.valid
  outResult.gapOutputRouteValid = gapRoute.valid
  outResult.completionSignalMissing =
    frontier.completionSignalMissing and gapRoute.completionSignalMissing
  outResult.activePolling = frontier.activePolling
  outResult.m0PollingPreserved =
    frontier.m0PollingRequired and routeAggregate.pollingPreserved
  outResult.liveRouteDeferred =
    routeAggregate.routeMatchesLiveAggregate and routeAggregate.routeTargetDeferred
  outResult.outputGateLiveRouteBacked =
    gapRoute.liveRouteBackedOutputGate and gapRoute.gapMatchesRouteGate
  outResult.outputEquivalenceDeferred =
    frontier.outputEquivalenceNotPending and gapRoute.outputPendingDeferred
  outResult.frontierMatchesLiveRoute =
    outResult.completionSignalMissing and outResult.activePolling and
      outResult.m0PollingPreserved and outResult.liveRouteDeferred and
      outResult.outputGateLiveRouteBacked and outResult.outputEquivalenceDeferred
  if not outResult.frontierValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveRecoveryRouteFrontierFrontier
  elif not outResult.routeAggregateValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveRecoveryRouteFrontierRouteAggregate
  elif not outResult.gapOutputRouteValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveRecoveryRouteFrontierGapOutputRoute
  elif not outResult.completionSignalMissing:
    outResult.firstBlock =
      blaiParsedConfiguredActiveRecoveryRouteFrontierCompletionSignal
  elif not outResult.activePolling:
    outResult.firstBlock =
      blaiParsedConfiguredActiveRecoveryRouteFrontierActivePolling
  elif not outResult.m0PollingPreserved:
    outResult.firstBlock =
      blaiParsedConfiguredActiveRecoveryRouteFrontierM0Polling
  elif not outResult.liveRouteDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredActiveRecoveryRouteFrontierLiveRoute
  elif not outResult.outputGateLiveRouteBacked:
    outResult.firstBlock =
      blaiParsedConfiguredActiveRecoveryRouteFrontierOutputGate
  elif not outResult.outputEquivalenceDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredActiveRecoveryRouteFrontierOutputEquivalence
  else:
    outResult.firstBlock =
      blaiParsedConfiguredActiveRecoveryRouteFrontierNoBlock
  outResult.valid =
    outResult.frontierValid and outResult.routeAggregateValid and
      outResult.gapOutputRouteValid and outResult.frontierMatchesLiveRoute

proc blaiParsedForwardConfiguredWorkspaceActiveRecoveryRouteFrontierEvidence*(
    frontier: BlaiParsedForwardConfiguredWorkspaceActiveRecoveryFrontierEvidence,
    routeAggregate:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteAggregateEvidence,
    gapRoute:
      BlaiParsedForwardConfiguredWorkspaceActiveGapOutputRouteEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveRecoveryRouteFrontierEvidence =
  ## Convenience wrapper for active recovery route-frontier evidence.
  blaiParsedForwardConfiguredWorkspaceActiveRecoveryRouteFrontierEvidenceInto(
    frontier, routeAggregate, gapRoute, result)

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionRouteResolutionEvidenceInto*(
    route: BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    routeFrontier:
      BlaiParsedForwardConfiguredWorkspaceActiveRecoveryRouteFrontierEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteResolutionEvidence) =
  ## Bind the concrete route target to the live-route-backed recovery frontier.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteResolutionEvidence)
  outResult.routeTargetValid = route.valid
  outResult.routeFrontierValid = routeFrontier.valid
  outResult.sdkRoutePreserved =
    route.sdkRouteRequested and route.d0RoutePreserved and route.glbRouteValid and
      route.mmAggregateRouteValid
  outResult.localBindingDeferred =
    route.localBindingDeferred and route.apiCallsDeferred and
      route.activeOperationsSuppressed
  outResult.routeOperationsDeferred =
    route.routeOperationsDeferred and route.registerHandlerDeferred and
      route.clearPendingDeferred and route.setPriorityDeferred and
      route.enableIrqDeferred
  outResult.pollingPreserved =
    route.m0PollingPreserved and route.mmAggregatePollingPreserved and
      routeFrontier.m0PollingPreserved
  outResult.liveRouteFrontier =
    routeFrontier.liveRouteDeferred and routeFrontier.frontierMatchesLiveRoute
  outResult.outputGateDeferred =
    routeFrontier.outputGateLiveRouteBacked and
      routeFrontier.outputEquivalenceDeferred
  outResult.resolutionMatchesFrontier =
    outResult.sdkRoutePreserved and outResult.localBindingDeferred and
      outResult.routeOperationsDeferred and outResult.pollingPreserved and
      outResult.liveRouteFrontier and outResult.outputGateDeferred
  if not outResult.routeTargetValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteResolutionRouteTarget
  elif not outResult.routeFrontierValid:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteResolutionRouteFrontier
  elif not outResult.sdkRoutePreserved:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteResolutionSdkRoute
  elif not outResult.localBindingDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteResolutionLocalBinding
  elif not outResult.routeOperationsDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteResolutionRouteOperations
  elif not outResult.pollingPreserved:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteResolutionPolling
  elif not outResult.liveRouteFrontier:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteResolutionLiveFrontier
  elif not outResult.outputGateDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteResolutionOutputGate
  else:
    outResult.firstBlock =
      blaiParsedConfiguredActiveCompletionRouteResolutionNoBlock
  outResult.valid =
    outResult.routeTargetValid and outResult.routeFrontierValid and
      outResult.resolutionMatchesFrontier

proc blaiParsedForwardConfiguredWorkspaceActiveCompletionRouteResolutionEvidence*(
    route: BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    routeFrontier:
      BlaiParsedForwardConfiguredWorkspaceActiveRecoveryRouteFrontierEvidence):
    BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteResolutionEvidence =
  ## Convenience wrapper for active completion-route resolution evidence.
  blaiParsedForwardConfiguredWorkspaceActiveCompletionRouteResolutionEvidenceInto(
    route, routeFrontier, result)

proc blaiParsedForwardConfiguredWorkspaceCompletionRouteControlReadinessEvidenceInto*(
    route: BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    resolution:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteResolutionEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceCompletionRouteControlReadinessEvidence) =
  ## Project the exact deferred route controls that must run before readback.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceCompletionRouteControlReadinessEvidence)
  outResult.routeTargetValid = route.valid
  outResult.routeResolutionValid = resolution.valid
  outResult.sdkRoutePreserved =
    route.sdkRouteRequested and route.d0RoutePreserved and
      resolution.sdkRoutePreserved
  outResult.localBindingDeferred =
    route.localBindingDeferred and route.apiCallsDeferred and
      resolution.localBindingDeferred
  outResult.hasDeferredOperation = route.hasDeferredOperation
  outResult.firstDeferredOperation = route.firstDeferredOperation
  outResult.registerHandlerDeferred = route.registerHandlerDeferred
  outResult.clearPendingDeferred = route.clearPendingDeferred
  outResult.setPriorityDeferred = route.setPriorityDeferred
  outResult.enableIrqDeferred = route.enableIrqDeferred
  outResult.routeOperationsDeferred =
    route.routeOperationsDeferred and resolution.routeOperationsDeferred and
      outResult.registerHandlerDeferred and outResult.clearPendingDeferred and
      outResult.setPriorityDeferred and outResult.enableIrqDeferred
  outResult.m0PollingPreserved =
    route.m0PollingPreserved and resolution.pollingPreserved
  outResult.mmAggregateRouteValid =
    route.mmAggregateRouteValid and route.glbRouteValid
  outResult.mmAggregateSubrouteUnknown = route.mmAggregateSubrouteUnknown
  outResult.outputGateDeferred = resolution.outputGateDeferred
  outResult.controlOpsReady =
    outResult.sdkRoutePreserved and outResult.localBindingDeferred and
      outResult.hasDeferredOperation and
      outResult.firstDeferredOperation == npuInterruptBindingRegisterHandler and
      outResult.routeOperationsDeferred and outResult.m0PollingPreserved and
      outResult.mmAggregateRouteValid and outResult.mmAggregateSubrouteUnknown
  outResult.mustBindRouteBeforeReadback =
    outResult.controlOpsReady and outResult.outputGateDeferred
  if not outResult.routeTargetValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteControlReadinessRouteTarget
  elif not outResult.routeResolutionValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteControlReadinessResolution
  elif not outResult.sdkRoutePreserved:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteControlReadinessSdkRoute
  elif not outResult.localBindingDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteControlReadinessLocalBinding
  elif not outResult.routeOperationsDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteControlReadinessOperations
  elif not outResult.m0PollingPreserved:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteControlReadinessPolling
  elif not (outResult.mmAggregateRouteValid and
      outResult.mmAggregateSubrouteUnknown):
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteControlReadinessMmAggregate
  elif not outResult.outputGateDeferred:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteControlReadinessOutputGate
  else:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteControlReadinessNoBlock
  outResult.valid =
    outResult.routeTargetValid and outResult.routeResolutionValid and
      outResult.mustBindRouteBeforeReadback

proc blaiParsedForwardConfiguredWorkspaceCompletionRouteControlReadinessEvidence*(
    route: BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    resolution:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteResolutionEvidence):
    BlaiParsedForwardConfiguredWorkspaceCompletionRouteControlReadinessEvidence =
  ## Convenience wrapper for completion-route control readiness.
  blaiParsedForwardConfiguredWorkspaceCompletionRouteControlReadinessEvidenceInto(
    route, resolution, result)

proc blaiParsedForwardConfiguredWorkspaceCompletionRouteBindingSafetyEvidenceInto*(
    route: BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    control:
      BlaiParsedForwardConfiguredWorkspaceCompletionRouteControlReadinessEvidence,
    controller: NpuCnnIrqControllerSnapshotEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceCompletionRouteBindingSafetyEvidence) =
  ## Keep recovered CNN IRQ controls diagnostic-only on M0 until route verified.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceCompletionRouteBindingSafetyEvidence)
  outResult.routeTargetValid = route.valid
  outResult.controlReadinessValid = control.valid
  outResult.controllerValid = controller.valid
  outResult.sdkRoutePreserved =
    route.sdkRouteRequested and route.d0RoutePreserved and
      control.sdkRoutePreserved
  outResult.m0AliasObserved =
    controller.irqMatchesSdk and controller.sourceMatchesSdkOffset and
      controller.sourceAliasesM0I2c1
  outResult.controllerBindingDeferred =
    controller.deferredBindingConsistent and controller.clicDisabled and
      controller.glbMasked and controller.pendingClear
  outResult.activeOperationsSuppressed = route.activeOperationsSuppressed
  outResult.routeOperationsDeferred =
    route.routeOperationsDeferred and control.routeOperationsDeferred
  outResult.m0PollingPreserved =
    route.m0PollingPreserved and control.m0PollingPreserved
  outResult.readbackGated = control.mustBindRouteBeforeReadback
  outResult.mmAggregateSubrouteUnknown =
    route.mmAggregateSubrouteUnknown and control.mmAggregateSubrouteUnknown
  outResult.mustNotEnableM0Alias =
    outResult.m0AliasObserved and outResult.controllerBindingDeferred and
      outResult.activeOperationsSuppressed and outResult.routeOperationsDeferred
  outResult.nextRequiresVerifiedRoute =
    outResult.mustNotEnableM0Alias and outResult.mmAggregateSubrouteUnknown and
      outResult.readbackGated
  outResult.bindingSafetyMatchesEvidence =
    outResult.sdkRoutePreserved and outResult.mustNotEnableM0Alias and
      outResult.m0PollingPreserved and outResult.nextRequiresVerifiedRoute
  if not outResult.routeTargetValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteBindingSafetyRouteTarget
  elif not outResult.controlReadinessValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteBindingSafetyControlReadiness
  elif not outResult.controllerValid:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteBindingSafetyController
  elif not outResult.m0AliasObserved:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteBindingSafetyM0Alias
  elif not outResult.mustNotEnableM0Alias:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteBindingSafetySuppression
  elif not outResult.m0PollingPreserved:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteBindingSafetyPolling
  elif not outResult.nextRequiresVerifiedRoute:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteBindingSafetyReadbackGate
  else:
    outResult.firstBlock =
      blaiParsedConfiguredCompletionRouteBindingSafetyNoBlock
  outResult.valid =
    outResult.routeTargetValid and outResult.controlReadinessValid and
      outResult.controllerValid and outResult.bindingSafetyMatchesEvidence

proc blaiParsedForwardConfiguredWorkspaceCompletionRouteBindingSafetyEvidence*(
    route: BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    control:
      BlaiParsedForwardConfiguredWorkspaceCompletionRouteControlReadinessEvidence,
    controller: NpuCnnIrqControllerSnapshotEvidence):
    BlaiParsedForwardConfiguredWorkspaceCompletionRouteBindingSafetyEvidence =
  ## Convenience wrapper for completion-route binding safety.
  blaiParsedForwardConfiguredWorkspaceCompletionRouteBindingSafetyEvidenceInto(
    route, control, controller, result)

proc blaiParsedForwardConfiguredWorkspaceCompletionRouteProbePlanInto*(
    route: BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    liveRoute: BlaiParsedForwardConfiguredWorkspaceActiveLiveRouteEvidence,
    binding:
      BlaiParsedForwardConfiguredWorkspaceCompletionRouteBindingSafetyEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceCompletionRouteProbePlan) =
  ## Select the next safe live action for the unresolved completion route.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceCompletionRouteProbePlan)
  outResult.routeTargetValid = route.valid
  outResult.liveRouteValid = liveRoute.valid
  outResult.bindingSafetyValid = binding.valid
  outResult.mmAggregateRouteValid =
    route.mmAggregateRouteValid and liveRoute.routeMatchesTarget
  outResult.mmAggregateSubrouteUnknown =
    route.mmAggregateSubrouteUnknown and liveRoute.subrouteUnknown and
      binding.mmAggregateSubrouteUnknown
  outResult.noPendingCandidate =
    liveRoute.noRawPending and liveRoute.noUnmaskedPending and
      liveRoute.noMaskedOnlyPending
  outResult.m0AliasUnsafe =
    binding.m0AliasObserved and binding.mustNotEnableM0Alias and
      binding.controllerBindingDeferred
  outResult.d0RoutePreserved =
    route.d0RoutePreserved and binding.sdkRoutePreserved
  outResult.pollingPreserved =
    route.m0PollingPreserved and liveRoute.pollingPreserved and
      binding.m0PollingPreserved
  outResult.outputReadbackBlocked =
    binding.readbackGated and binding.nextRequiresVerifiedRoute
  outResult.requiresRouteProbe =
    outResult.mmAggregateRouteValid and outResult.mmAggregateSubrouteUnknown and
      outResult.noPendingCandidate and outResult.m0AliasUnsafe and
      outResult.d0RoutePreserved and outResult.pollingPreserved and
      outResult.outputReadbackBlocked
  if outResult.requiresRouteProbe:
    outResult.nextAction =
      blaiParsedConfiguredCompletionRouteProbeVerifyMmSubroute
  elif outResult.routeTargetValid and outResult.liveRouteValid and
      outResult.bindingSafetyValid and not outResult.mmAggregateSubrouteUnknown:
    outResult.nextAction =
      blaiParsedConfiguredCompletionRouteProbeReadbackAfterCompletion
  elif outResult.d0RoutePreserved and not outResult.m0AliasUnsafe:
    outResult.nextAction =
      blaiParsedConfiguredCompletionRouteProbeBindD0Route
  else:
    outResult.nextAction = blaiParsedConfiguredCompletionRouteProbeNoAction
  outResult.routeProbeBeforeReadback =
    outResult.nextAction ==
      blaiParsedConfiguredCompletionRouteProbeVerifyMmSubroute and
      outResult.outputReadbackBlocked
  outResult.valid =
    outResult.routeTargetValid and outResult.liveRouteValid and
      outResult.bindingSafetyValid and outResult.routeProbeBeforeReadback

proc blaiParsedForwardConfiguredWorkspaceCompletionRouteProbePlan*(
    route: BlaiParsedForwardConfiguredWorkspaceCompletionRouteTargetEvidence,
    liveRoute: BlaiParsedForwardConfiguredWorkspaceActiveLiveRouteEvidence,
    binding:
      BlaiParsedForwardConfiguredWorkspaceCompletionRouteBindingSafetyEvidence):
      BlaiParsedForwardConfiguredWorkspaceCompletionRouteProbePlan =
  ## Convenience wrapper for the active completion-route probe plan.
  blaiParsedForwardConfiguredWorkspaceCompletionRouteProbePlanInto(
    route, liveRoute, binding, result)

proc blaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidenceInto*(
    routeResolution:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteResolutionEvidence,
    handoff:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionToOutputHandoffEvidence,
    postBudget:
      BlaiParsedForwardConfiguredWorkspaceActivePostBudgetOutputGateEvidence,
    outputFrontier:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceFrontierEvidence,
    outResult:
      var BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence) =
  ## Project the next live output-equivalence gate without bypassing completion.
  outResult =
    default(BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence)
  outResult.routeResolutionValid = routeResolution.valid
  outResult.handoffValid = handoff.valid
  outResult.postBudgetGateValid = postBudget.valid
  outResult.outputFrontierValid = outputFrontier.valid
  outResult.routeStillDeferred =
    routeResolution.localBindingDeferred and routeResolution.routeOperationsDeferred
  outResult.completionStillMissing =
    routeResolution.liveRouteFrontier and routeResolution.pollingPreserved and
      outputFrontier.currentGapIsCompletionSignal
  outResult.outputPlanReady =
    postBudget.outputPlanReady and handoff.readbackReady
  outResult.readbackReadyAfterCompletion =
    handoff.readbackReady and postBudget.outputReadbackDeferred and
      outputFrontier.outputReadbackNotStarted
  outResult.compareReadyAfterCompletion =
    postBudget.compareDeferred and outputFrontier.compareNotStarted and
      outputFrontier.noOutputMismatchObserved
  outResult.outputEquivalenceBlockedByCompletion =
    outputFrontier.outputEquivalenceDeferred and
      postBudget.completionBeforeOutput and outResult.completionStillMissing
  outResult.nextStageOutputEquivalence =
    handoff.outputNextAfterCompletion and
      postBudget.nextStageOutputEquivalence and
      outputFrontier.outputEquivalenceNextAfterCompletion
  outResult.readinessMatchesEvidence =
    outResult.routeStillDeferred and outResult.completionStillMissing and
      outResult.outputPlanReady and outResult.readbackReadyAfterCompletion and
      outResult.compareReadyAfterCompletion and
      outResult.outputEquivalenceBlockedByCompletion and
      outResult.nextStageOutputEquivalence
  if not outResult.routeResolutionValid:
    outResult.firstBlock =
      blaiParsedConfiguredOutputEquivalenceReadinessRouteResolution
  elif not outResult.handoffValid:
    outResult.firstBlock =
      blaiParsedConfiguredOutputEquivalenceReadinessHandoff
  elif not outResult.postBudgetGateValid:
    outResult.firstBlock =
      blaiParsedConfiguredOutputEquivalenceReadinessPostBudget
  elif not outResult.outputFrontierValid:
    outResult.firstBlock =
      blaiParsedConfiguredOutputEquivalenceReadinessOutputFrontier
  elif outResult.outputEquivalenceBlockedByCompletion:
    outResult.firstBlock =
      blaiParsedConfiguredOutputEquivalenceReadinessCompletion
  else:
    outResult.firstBlock =
      blaiParsedConfiguredOutputEquivalenceReadinessNoBlock
  outResult.valid =
    outResult.routeResolutionValid and outResult.handoffValid and
      outResult.postBudgetGateValid and outResult.outputFrontierValid and
      outResult.readinessMatchesEvidence

proc blaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence*(
    routeResolution:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteResolutionEvidence,
    handoff:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionToOutputHandoffEvidence,
    postBudget:
      BlaiParsedForwardConfiguredWorkspaceActivePostBudgetOutputGateEvidence,
    outputFrontier:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceFrontierEvidence):
    BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence =
  ## Convenience wrapper for generated live output-equivalence readiness.
  blaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidenceInto(
    routeResolution, handoff, postBudget, outputFrontier, result)

proc blaiMnistTfliteActiveOutputValidationEvidenceInto*(
    mnist: BlaiMnistTfliteSupportPlan,
    active:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence,
    outResult: var BlaiMnistTfliteActiveOutputValidationEvidence) =
  ## Bind the fetched MNIST model readiness to active output-validation evidence.
  outResult = default(BlaiMnistTfliteActiveOutputValidationEvidence)
  outResult.modelMetadataValid = mnist.metadataValid
  outResult.parsedReferenceRunnable =
    mnist.parsedReferenceRunnable and mnist.fullyConnectedReferenceSupported
  outResult.npuOutputPending =
    mnist.supportBlock == blaiMnistTfliteNpuOutputValidationPending and
      not mnist.npuOutputValidated and not mnist.runnable
  outResult.activeReadinessValid = active.valid
  outResult.activeReadinessFirstBlock = active.firstBlock
  outResult.completionStillMissing =
    active.completionStillMissing and
      active.firstBlock == blaiParsedConfiguredOutputEquivalenceReadinessCompletion
  outResult.outputPlanReady = active.outputPlanReady
  outResult.readbackReadyAfterCompletion = active.readbackReadyAfterCompletion
  outResult.compareReadyAfterCompletion = active.compareReadyAfterCompletion
  outResult.outputBlockedByCompletion =
    active.outputEquivalenceBlockedByCompletion
  outResult.nextStageOutputEquivalence = active.nextStageOutputEquivalence
  outResult.statusMatchesActiveFrontier =
    outResult.npuOutputPending and outResult.activeReadinessValid and
      outResult.completionStillMissing and outResult.outputPlanReady and
      outResult.readbackReadyAfterCompletion and
      outResult.compareReadyAfterCompletion and
      outResult.outputBlockedByCompletion and
      outResult.nextStageOutputEquivalence
  if not outResult.modelMetadataValid:
    outResult.firstBlock = blaiMnistTfliteActiveOutputValidationModel
  elif not outResult.parsedReferenceRunnable:
    outResult.firstBlock = blaiMnistTfliteActiveOutputValidationReference
  elif not outResult.npuOutputPending:
    outResult.firstBlock = blaiMnistTfliteActiveOutputValidationNpuStatus
  elif not outResult.activeReadinessValid:
    outResult.firstBlock = blaiMnistTfliteActiveOutputValidationActiveReadiness
  elif not outResult.completionStillMissing:
    outResult.firstBlock = blaiMnistTfliteActiveOutputValidationCompletion
  else:
    outResult.firstBlock = blaiMnistTfliteActiveOutputValidationNoBlock
  outResult.valid =
    outResult.modelMetadataValid and outResult.parsedReferenceRunnable and
      outResult.npuOutputPending and outResult.statusMatchesActiveFrontier

proc blaiMnistTfliteActiveOutputValidationEvidence*(
    mnist: BlaiMnistTfliteSupportPlan,
    active:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence):
    BlaiMnistTfliteActiveOutputValidationEvidence =
  ## Convenience wrapper for MNIST active output-validation frontier evidence.
  blaiMnistTfliteActiveOutputValidationEvidenceInto(mnist, active, result)

proc blaiMnistTfliteLiveCompletionRouteEvidenceInto*(
    mnist: BlaiMnistTfliteSupportPlan,
    active: BlaiMnistTfliteActiveOutputValidationEvidence,
    aggregate:
      BlaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidence,
    route:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteAggregateEvidence,
    outResult: var BlaiMnistTfliteLiveCompletionRouteEvidence) =
  ## Bind fetched MNIST output validation to the live completion-route sample.
  outResult = default(BlaiMnistTfliteLiveCompletionRouteEvidence)
  outResult.modelMetadataValid = mnist.metadataValid
  outResult.persistentBuffersIdentified = mnist.persistentBuffersIdentified
  outResult.activeValidationValid = active.valid
  outResult.aggregateWaitExitValid = aggregate.valid
  outResult.routeAggregateValid = route.valid
  outResult.completionStillMissing =
    active.completionStillMissing and route.routeTargetDeferred
  outResult.noRawPending =
    not aggregate.anyRawStatus and aggregate.rawPendingCount == 0'u32
  outResult.noUnmaskedPending =
    aggregate.noUnmaskedPending and aggregate.unmaskedPendingCount == 0'u32
  outResult.noMaskedOnlyPending =
    not aggregate.allRawStatusMasked and aggregate.maskedOnlyCount == 0'u32
  outResult.noNamedNpuSubroute = aggregate.noNamedNpuSubroute
  outResult.subrouteUnknown =
    aggregate.subrouteUnknown and route.subrouteUnknown
  outResult.pollingPreserved =
    aggregate.pollingPreserved and route.pollingPreserved
  outResult.routeDeferred = route.routeTargetDeferred
  outResult.outputReadinessDeferred =
    active.outputBlockedByCompletion and active.readbackReadyAfterCompletion and
      active.compareReadyAfterCompletion
  outResult.nextStageOutputEquivalence =
    active.nextStageOutputEquivalence
  outResult.liveRouteMatchesModelFrontier =
    outResult.modelMetadataValid and outResult.persistentBuffersIdentified and
      outResult.activeValidationValid and outResult.aggregateWaitExitValid and
      outResult.routeAggregateValid and outResult.completionStillMissing and
      outResult.noRawPending and outResult.noUnmaskedPending and
      outResult.noMaskedOnlyPending and outResult.noNamedNpuSubroute and
      outResult.subrouteUnknown and outResult.pollingPreserved and
      outResult.routeDeferred and outResult.outputReadinessDeferred and
      outResult.nextStageOutputEquivalence
  if not outResult.modelMetadataValid or
      not outResult.persistentBuffersIdentified:
    outResult.firstBlock = blaiMnistTfliteLiveCompletionRouteModel
  elif not outResult.activeValidationValid:
    outResult.firstBlock =
      blaiMnistTfliteLiveCompletionRouteActiveValidation
  elif not outResult.aggregateWaitExitValid:
    outResult.firstBlock = blaiMnistTfliteLiveCompletionRouteAggregate
  elif not outResult.routeAggregateValid:
    outResult.firstBlock = blaiMnistTfliteLiveCompletionRouteRoute
  elif not (outResult.noRawPending and outResult.noUnmaskedPending and
      outResult.noMaskedOnlyPending and outResult.noNamedNpuSubroute and
      outResult.subrouteUnknown):
    outResult.firstBlock = blaiMnistTfliteLiveCompletionRoutePendingBits
  elif not outResult.completionStillMissing:
    outResult.firstBlock = blaiMnistTfliteLiveCompletionRouteCompletion
  else:
    outResult.firstBlock = blaiMnistTfliteLiveCompletionRouteNoBlock
  outResult.valid =
    outResult.liveRouteMatchesModelFrontier and
      outResult.firstBlock == blaiMnistTfliteLiveCompletionRouteNoBlock

proc blaiMnistTfliteLiveCompletionRouteEvidence*(
    mnist: BlaiMnistTfliteSupportPlan,
    active: BlaiMnistTfliteActiveOutputValidationEvidence,
    aggregate:
      BlaiParsedForwardConfiguredWorkspaceActiveMmAggregateWaitExitEvidence,
    route:
      BlaiParsedForwardConfiguredWorkspaceActiveCompletionRouteAggregateEvidence):
    BlaiMnistTfliteLiveCompletionRouteEvidence =
  ## Convenience wrapper for real-model live completion-route evidence.
  blaiMnistTfliteLiveCompletionRouteEvidenceInto(
    mnist, active, aggregate, route, result)

proc blaiMnistTfliteLiveValidationNextStepEvidenceInto*(
    active: BlaiMnistTfliteActiveOutputValidationEvidence,
    liveRoute: BlaiMnistTfliteLiveCompletionRouteEvidence,
    outResult: var BlaiMnistTfliteLiveValidationNextStepEvidence) =
  ## Preserve the required order: completion route before output equivalence.
  outResult = default(BlaiMnistTfliteLiveValidationNextStepEvidence)
  outResult.activeValidationValid = active.valid
  outResult.liveRouteValid = liveRoute.valid
  outResult.activeFirstBlock = active.firstBlock
  outResult.liveRouteFirstBlock = liveRoute.firstBlock
  outResult.completionStillMissing =
    active.completionStillMissing and liveRoute.completionStillMissing
  outResult.routeDeferred = liveRoute.routeDeferred
  outResult.outputPlanReady = active.outputPlanReady
  outResult.readbackReadyAfterCompletion =
    active.readbackReadyAfterCompletion
  outResult.compareReadyAfterCompletion =
    active.compareReadyAfterCompletion
  outResult.outputValidationDeferred =
    active.outputBlockedByCompletion and liveRoute.outputReadinessDeferred
  outResult.mustResolveCompletionRoute =
    outResult.completionStillMissing and outResult.routeDeferred
  outResult.readbackCompareReadyAfterRoute =
    liveRoute.nextStageOutputEquivalence and outResult.outputPlanReady and
      outResult.readbackReadyAfterCompletion and
      outResult.compareReadyAfterCompletion
  outResult.noPrematureReadback =
    outResult.mustResolveCompletionRoute and outResult.outputValidationDeferred
  if outResult.mustResolveCompletionRoute:
    outResult.nextAction = blaiMnistLiveValidationResolveCompletionRoute
  elif outResult.readbackCompareReadyAfterRoute:
    outResult.nextAction = blaiMnistLiveValidationReadbackCompare
  else:
    outResult.nextAction = blaiMnistLiveValidationBlocked
  outResult.valid =
    outResult.activeValidationValid and outResult.liveRouteValid and
      outResult.noPrematureReadback and
      outResult.readbackCompareReadyAfterRoute and
      outResult.nextAction == blaiMnistLiveValidationResolveCompletionRoute

proc blaiMnistTfliteLiveValidationNextStepEvidence*(
    active: BlaiMnistTfliteActiveOutputValidationEvidence,
    liveRoute: BlaiMnistTfliteLiveCompletionRouteEvidence):
    BlaiMnistTfliteLiveValidationNextStepEvidence =
  ## Convenience wrapper for the live MNIST validation next step.
  blaiMnistTfliteLiveValidationNextStepEvidenceInto(
    active, liveRoute, result)

proc blaiMnistTfliteD0SyntheticContrastEvidenceInto*(
    mnistNext: BlaiMnistTfliteLiveValidationNextStepEvidence,
    d0Completion: NpuD0ProbeCompletionEdgeEvidence,
    outResult: var BlaiMnistTfliteD0SyntheticContrastEvidence) =
  ## Contrast D0 synthetic DATA movement with real-model validation gating.
  outResult = default(BlaiMnistTfliteD0SyntheticContrastEvidence)
  outResult.mnistNextStepValid = mnistNext.valid
  outResult.d0CompletionEvidenceValid = d0Completion.valid
  outResult.d0StreamValid = d0Completion.streamValid
  outResult.d0OutputMoved = d0Completion.outputMoved
  outResult.d0CompletionMissing = d0Completion.completionEdgeMissing
  outResult.mnistActiveFirstBlock = mnistNext.activeFirstBlock
  outResult.mnistLiveRouteFirstBlock = mnistNext.liveRouteFirstBlock
  outResult.mnistNextAction = mnistNext.nextAction
  outResult.mnistCompletionStillMissing = mnistNext.completionStillMissing
  outResult.mnistRouteDeferred = mnistNext.routeDeferred
  outResult.mnistReadbackReadyAfterRoute =
    mnistNext.readbackCompareReadyAfterRoute
  outResult.mnistNoPrematureReadback = mnistNext.noPrematureReadback
  outResult.syntheticProvesDataMovementOnly =
    outResult.d0CompletionEvidenceValid and outResult.d0StreamValid and
      outResult.d0OutputMoved and outResult.d0CompletionMissing
  outResult.generatedModelStillRequiresCompletionRoute =
    outResult.mnistNextStepValid and outResult.mnistCompletionStillMissing and
      outResult.mnistRouteDeferred and outResult.mnistReadbackReadyAfterRoute and
      outResult.mnistNoPrematureReadback
  outResult.nextWorkIsCompletionRoute =
    outResult.syntheticProvesDataMovementOnly and
      outResult.generatedModelStillRequiresCompletionRoute
  outResult.valid = outResult.nextWorkIsCompletionRoute

proc blaiMnistTfliteD0SyntheticContrastEvidence*(
    mnistNext: BlaiMnistTfliteLiveValidationNextStepEvidence,
    d0Completion: NpuD0ProbeCompletionEdgeEvidence):
      BlaiMnistTfliteD0SyntheticContrastEvidence =
  ## Convenience wrapper for D0 synthetic versus MNIST-live contrast evidence.
  blaiMnistTfliteD0SyntheticContrastEvidenceInto(
    mnistNext, d0Completion, result)

proc blaiValidateParsedForwardConfiguredWorkspaceFixtureInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    modelResources: BlaiForwardModelResourcePlan,
    tensorPlan: BlaiForwardNpuPlan,
    inputIndex: uint32,
    input: openArray[uint8],
    expectedOutput: openArray[uint8],
    output: var openArray[uint8],
    workspaceBytes: var openArray[uint8],
    outResult: var BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    timeout: uint32 = 5_000_000) =
  ## Stage input, execute, and validate output from a projected live buffer.
  ##
  ## This variant binds the caller-owned byte array through
  ## `blaiBindForwardWorkspaceBufferInto`, so cached RAM aliases are projected to
  ## hardware-visible addresses before BLAI register planning.
  outResult = default(BlaiParsedForwardConfiguredWorkspaceFixtureResult)
  blaiBindForwardWorkspaceBufferInto(
    modelResources, workspaceBytes, outResult.binding)
  if not outResult.binding.bound:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiForwardWorkspaceHardwareAddressReadinessInto(
    outResult.binding, outResult.hardwareAddresses)
  if not outResult.hardwareAddresses.ready:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiStageForwardWorkspaceInputInto(
    outResult.binding, tensorPlan, inputIndex, input, workspaceBytes,
    outResult.input)
  if not outResult.input.moved:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiExecuteForwardModelConfiguredInto(
    layers, modelResources, outResult.binding.workspace, outResult.execution,
    timeout)
  if not outResult.execution.allCompleted:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiValidateForwardWorkspaceOutputInto(
    outResult.execution, outResult.binding, tensorPlan,
    blaiForwardPrimaryOutput, workspaceBytes, expectedOutput, output,
    outResult.output)
  blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)

proc blaiValidateParsedForwardConfiguredWorkspaceFixture*(
    layers: openArray[BlaiCpuParsedLayerState],
    modelResources: BlaiForwardModelResourcePlan,
    tensorPlan: BlaiForwardNpuPlan,
    inputIndex: uint32,
    input: openArray[uint8],
    expectedOutput: openArray[uint8],
    output: var openArray[uint8],
    workspaceBytes: var openArray[uint8],
    timeout: uint32 = 5_000_000):
    BlaiParsedForwardConfiguredWorkspaceFixtureResult =
  ## Convenience wrapper for buffer-bound configured-live validation.
  blaiValidateParsedForwardConfiguredWorkspaceFixtureInto(
    layers, modelResources, tensorPlan, inputIndex, input, expectedOutput,
    output, workspaceBytes, result, timeout)

proc blaiValidateParsedForwardConfiguredWorkspaceAddressFixtureInto*(
    layers: openArray[BlaiCpuParsedLayerState],
    modelResources: BlaiForwardModelResourcePlan,
    workspaceBaseAddress: uint32,
    tensorPlan: BlaiForwardNpuPlan,
    inputIndex: uint32,
    input: openArray[uint8],
    expectedOutput: openArray[uint8],
    output: var openArray[uint8],
    workspaceBytes: var openArray[uint8],
    outResult: var BlaiParsedForwardConfiguredWorkspaceFixtureResult,
  timeout: uint32 = 5_000_000) =
  ## Stage input, execute a prepared parsed model live, and validate output.
  outResult = default(BlaiParsedForwardConfiguredWorkspaceFixtureResult)
  blaiBindForwardWorkspaceFixtureAddressInto(
    modelResources, workspaceBaseAddress,
    blaiForwardWorkspaceBufferBytes(workspaceBytes.len), outResult.binding)
  if not outResult.binding.bound:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiForwardWorkspaceHardwareAddressReadinessInto(
    outResult.binding, outResult.hardwareAddresses)
  if not outResult.hardwareAddresses.ready:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiStageForwardWorkspaceInputInto(
    outResult.binding, tensorPlan, inputIndex, input, workspaceBytes,
    outResult.input)
  if not outResult.input.moved:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiExecuteForwardModelConfiguredInto(
    layers, modelResources, outResult.binding.workspace, outResult.execution,
    timeout)
  if not outResult.execution.allCompleted:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiValidateForwardWorkspaceOutputInto(
    outResult.execution, outResult.binding, tensorPlan,
    blaiForwardPrimaryOutput, workspaceBytes, expectedOutput, output,
    outResult.output)
  blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)

proc blaiValidateParsedForwardConfiguredWorkspaceAddressFixture*(
    layers: openArray[BlaiCpuParsedLayerState],
    modelResources: BlaiForwardModelResourcePlan,
    workspaceBaseAddress: uint32,
    tensorPlan: BlaiForwardNpuPlan,
