  ## Convenience wrapper for parsed configured-live workspace validation.
  blaiValidateParsedForwardConfiguredWorkspaceAddressFixtureInto(
    layers, modelResources, workspaceBaseAddress, tensorPlan, inputIndex,
    input, expectedOutput, output, workspaceBytes, result, timeout)

proc blaiValidateParsedForwardConfiguredWorkspaceAddressFixtureWithLayerBuffersInto*(
    layers: openArray[BlaiCpuParsedLayerState],
