  timeout: uint32 = 5_000_000) =
  ## Stage input, execute with explicit layer buffers, then validate output.
  outResult = default(BlaiParsedForwardConfiguredWorkspaceFixtureResult)
  blaiBindForwardWorkspaceFixtureAddressInto(
    modelResources, workspaceBaseAddress,
    blaiForwardWorkspaceBufferBytes(workspaceBytes.len), outResult.binding)
  blaiForwardWorkspaceHardwareAddressReadinessInto(
    outResult.binding, outResult.hardwareAddresses)
  if not outResult.hardwareAddresses.ready:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiStageForwardWorkspaceInputInto(
    outResult.binding, tensorPlan, inputIndex, input, workspaceBytes,
    outResult.input)
  if not outResult.input.moved:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiExecuteForwardModelConfiguredWithLayerBuffersInto(
    layers, modelResources, outResult.binding.workspace, layerBuffers,
    outResult.execution, timeout)
  if not outResult.execution.allCompleted:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)
    return
  blaiValidateForwardWorkspaceOutputInto(
    outResult.execution, outResult.binding, tensorPlan,
    blaiForwardPrimaryOutput, workspaceBytes, expectedOutput, output,
    outResult.output)
  blaiFinishParsedForwardConfiguredWorkspaceFixture(outResult)

proc blaiValidateParsedForwardConfiguredWorkspaceAddressFixtureWithLayerBuffers*(
    layers: openArray[BlaiCpuParsedLayerState],
    modelResources: BlaiForwardModelResourcePlan,
    workspaceBaseAddress: uint32,
