proc blaiMaterializeAndValidateParsedForwardConfiguredWorkspaceAddressFixtureInto*(
    layers: var openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    modelResources: BlaiForwardModelResourcePlan,
    workspaceBaseAddress: uint32,
    tensorPlan: BlaiForwardNpuPlan,
    inputIndex: uint32,
    input: openArray[uint8],
    expectedOutput: openArray[uint8],
    output: var openArray[uint8],
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    outMaterialization: var BlaiForwardModelWorkspaceMaterializeResult,
    outFixture: var BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false,
    timeout: uint32 = 5_000_000) =
  ## Materialize parsed workspace bytes, then validate through configured live.
  ##
  ## Generated fixtures use this boundary when instruction/DATA/weight/bias
  ## workspace storage is caller-owned: materialization is exposed separately
  ## from the configured-live fixture result to avoid inflating either record.
  outMaterialization = default(BlaiForwardModelWorkspaceMaterializeResult)
  outFixture = default(BlaiParsedForwardConfiguredWorkspaceFixtureResult)
  var binding: BlaiForwardWorkspaceBufferBinding
  blaiBindForwardWorkspaceAddressInto(
    modelResources, workspaceBaseAddress, blaiBufferLenU32(workspaceBytes.len),
    binding)
  outFixture.binding = binding
  if not binding.bound:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outFixture)
    return
  blaiMaterializeForwardModelWorkspaceInto(
    layers, useTflite, ctrl, stream, modelResources, binding.workspace,
    workspaceBytes, cpuWeightBytes, cpuBiasBytes, decodedWeights,
    decodedBiases, npuWeightBytes, npuBiases, temporaryWeights, pack, c2,
    includeExtra, descriptorHalt, midOutState, outMaterialization)
  if not outMaterialization.allReady:
    blaiForwardWorkspaceHardwareAddressReadinessInto(
      binding, outFixture.hardwareAddresses)
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outFixture)
    return
  blaiValidateParsedForwardConfiguredWorkspaceAddressFixtureInto(
    layers, modelResources, workspaceBaseAddress, tensorPlan, inputIndex,
    input, expectedOutput, output, workspaceBytes, outFixture, timeout)

proc blaiMaterializeAndValidateParsedForwardConfiguredWorkspaceFixtureInto*(
    layers: var openArray[BlaiCpuParsedLayerState],
    useTflite: bool,
    modelResources: BlaiForwardModelResourcePlan,
    tensorPlan: BlaiForwardNpuPlan,
    inputIndex: uint32,
    input: openArray[uint8],
    expectedOutput: openArray[uint8],
    output: var openArray[uint8],
    ctrl: var BlaiPsramCtrl,
    stream: var openArray[BlaiInstruction],
    workspaceBytes: var openArray[uint8],
    cpuWeightBytes: openArray[uint8],
    cpuBiasBytes: openArray[uint8],
    decodedWeights: var openArray[int32],
    decodedBiases: var openArray[int32],
    npuWeightBytes: var openArray[uint8],
    npuBiases: var openArray[int32],
    temporaryWeights: var openArray[int32],
    outMaterialization: var BlaiForwardModelWorkspaceMaterializeResult,
    outFixture: var BlaiParsedForwardConfiguredWorkspaceFixtureResult,
    pack: uint32 = BlaiNpuWeightPack,
    c2: uint32 = 0'u32,
    includeExtra: bool = false,
    descriptorHalt: bool = false,
    midOutState: bool = false,
    timeout: uint32 = 5_000_000) =
  ## Materialize parsed workspace bytes, then validate using projected storage.
  outMaterialization = default(BlaiForwardModelWorkspaceMaterializeResult)
  outFixture = default(BlaiParsedForwardConfiguredWorkspaceFixtureResult)
  var binding: BlaiForwardWorkspaceBufferBinding
  blaiBindForwardWorkspaceBufferInto(modelResources, workspaceBytes, binding)
  outFixture.binding = binding
  if not binding.bound:
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outFixture)
    return
  blaiMaterializeForwardModelWorkspaceInto(
    layers, useTflite, ctrl, stream, modelResources, binding.workspace,
    workspaceBytes, cpuWeightBytes, cpuBiasBytes, decodedWeights,
    decodedBiases, npuWeightBytes, npuBiases, temporaryWeights, pack, c2,
    includeExtra, descriptorHalt, midOutState, outMaterialization)
  if not outMaterialization.allReady:
    blaiForwardWorkspaceHardwareAddressReadinessInto(
      binding, outFixture.hardwareAddresses)
    blaiFinishParsedForwardConfiguredWorkspaceFixture(outFixture)
    return
  blaiValidateParsedForwardConfiguredWorkspaceFixtureInto(
    layers, modelResources, tensorPlan, inputIndex, input, expectedOutput,
    output, workspaceBytes, outFixture, timeout)

proc blaiFinishTfliteParsedConfiguredWorkspaceOracleAddressFixture(
    outResult:
      var BlaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureResult) =
  outResult.projected = outResult.projection.projected
  outResult.referenceFirstBlock = outResult.reference.readiness.firstBlock
  outResult.referenceValid =
    outResult.reference.executed and outResult.reference.model.modelValid and
    outResult.reference.model.allCompleted and
    outResult.reference.model.allWeightsConsumed and
    outResult.reference.model.allBiasesConsumed
  outResult.fixtureValid = outResult.fixture.valid
  outResult.executionRunnable = outResult.fixture.execution.runnable
  outResult.executed = outResult.fixture.execution.allCompleted
  outResult.outputValid = outResult.fixture.output.valid
  outResult.outputMatched = outResult.fixture.output.compare.matched
  outResult.completedLayerCount = outResult.fixture.execution.completedLayerCount
  outResult.executionAttemptedLayerCount =
    outResult.fixture.executionAttemptedLayerCount
  outResult.executionCompletedLayerCount =
    outResult.fixture.executionCompletedLayerCount
  outResult.executionFailedLayerCount =
    outResult.fixture.executionFailedLayerCount
  outResult.executionFirstFailedLayer =
    outResult.fixture.executionFirstFailedLayer
  outResult.executionFirstFailedCaptured =
    outResult.fixture.executionFirstFailedCaptured
  outResult.executionLastStarted =
    outResult.fixture.executionLastStarted
  outResult.executionLastCompleted =
    outResult.fixture.executionLastCompleted
  outResult.executionLastTimedOut =
    outResult.fixture.executionLastTimedOut
  outResult.executionLastInterruptObserved =
    outResult.fixture.executionLastInterruptObserved
  outResult.expectedElements = outResult.fixture.output.expectedElements
  outResult.actualElements = outResult.fixture.output.actualElements
  outResult.comparedElements = outResult.fixture.output.comparedElements
  outResult.trailingElements = outResult.fixture.output.trailingElements
  outResult.lengthMatches = outResult.fixture.output.lengthMatches
  outResult.mismatchCount = outResult.fixture.output.compare.mismatchCount
  outResult.firstMismatch = outResult.fixture.output.compare.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    outResult.fixture.output.compare.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    outResult.fixture.output.compare.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch =
    outResult.fixture.output.compare.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch =
    outResult.fixture.output.compare.actualAtFirstMismatch
  outResult.projectionFirstBlock = outResult.projection.firstBlock
  outResult.fixtureFirstBlock = outResult.fixture.firstBlock
  outResult.outputFirstBlock = outResult.fixture.outputFirstBlock
  if not outResult.projected:
    outResult.firstBlock =
      blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureProjection
  elif not outResult.referenceValid:
    outResult.firstBlock =
      blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureReference
  elif not outResult.fixtureValid:
    outResult.firstBlock =
      blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureFixture
  else:
    outResult.firstBlock =
      blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureNoBlock
  outResult.valid =
    outResult.firstBlock ==
      blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureNoBlock

proc blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureReadinessInto*(
    validation:
      BlaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureResult,
    outResult:
      var BlaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureReadiness) =
  ## Derive the public gate summary for TFLite configured-live oracle checks.
  outResult = default(
    BlaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureReadiness)
  outResult.projected = validation.projected
  outResult.referenceValid = validation.referenceValid
  outResult.fixtureValid = validation.fixtureValid
  outResult.executionRunnable = validation.executionRunnable
  outResult.executed = validation.executed
  outResult.outputValid = validation.outputValid
  outResult.outputMatched = validation.outputMatched
  outResult.completedLayerCount = validation.completedLayerCount
  outResult.executionAttemptedLayerCount =
    validation.executionAttemptedLayerCount
  outResult.executionCompletedLayerCount =
    validation.executionCompletedLayerCount
  outResult.executionFailedLayerCount =
    validation.executionFailedLayerCount
  outResult.executionFirstFailedLayer =
    validation.executionFirstFailedLayer
  outResult.executionFirstFailedCaptured =
    validation.executionFirstFailedCaptured
  outResult.executionLastStarted =
    validation.executionLastStarted
  outResult.executionLastCompleted =
    validation.executionLastCompleted
  outResult.executionLastTimedOut =
    validation.executionLastTimedOut
  outResult.executionLastInterruptObserved =
    validation.executionLastInterruptObserved
  outResult.expectedElements = validation.expectedElements
  outResult.actualElements = validation.actualElements
  outResult.comparedElements = validation.comparedElements
  outResult.trailingElements = validation.trailingElements
  outResult.lengthMatches = validation.lengthMatches
  outResult.mismatchCount = validation.mismatchCount
  outResult.firstMismatch = validation.firstMismatch
  outResult.expectedPresentAtFirstMismatch =
    validation.expectedPresentAtFirstMismatch
  outResult.actualPresentAtFirstMismatch =
    validation.actualPresentAtFirstMismatch
  outResult.expectedAtFirstMismatch = validation.expectedAtFirstMismatch
  outResult.actualAtFirstMismatch = validation.actualAtFirstMismatch
  blaiForwardWorkspaceOutputValidationReadinessInto(
    validation.fixture.output, outResult.outputReadiness)
  blaiParsedForwardConfiguredWorkspaceFixtureReadinessInto(
    validation.fixture, outResult.fixtureReadiness)
  outResult.projectionFirstBlock = validation.projectionFirstBlock
  outResult.referenceFirstBlock = validation.referenceFirstBlock
  outResult.fixtureFirstBlock = validation.fixtureFirstBlock
  outResult.outputFirstBlock = validation.outputFirstBlock
  if not outResult.projected:
    outResult.firstBlock =
      blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureProjection
  elif not outResult.referenceValid:
    outResult.firstBlock =
      blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureReference
  elif not outResult.fixtureValid:
    outResult.firstBlock =
      blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureFixture
  else:
    outResult.firstBlock =
      blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureNoBlock
  outResult.valid =
    outResult.firstBlock ==
      blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureNoBlock

proc blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureReadiness*(
    validation:
      BlaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureResult):
    BlaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureReadiness =
  ## Convenience wrapper for TFLite configured-live oracle readiness.
  blaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureReadinessInto(
    validation, result)

proc blaiValidateTfliteParsedConfiguredWorkspaceOracleAddressFixtureInto*(
    reference: BlaiReferenceTfliteParsedCheckedModelResult,
    referenceOutput: openArray[uint8],
    layers: openArray[BlaiCpuParsedLayerState],
    modelResources: BlaiForwardModelResourcePlan,
    workspaceBaseAddress: uint32,
    tensorPlan: BlaiForwardNpuPlan,
    inputIndex: uint32,
    input: openArray[uint8],
    expectedWorkspaceOutput: var openArray[uint8],
    output: var openArray[uint8],
    workspaceBytes: var openArray[uint8],
    outResult:
      var BlaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureResult,
    timeout: uint32 = 5_000_000) =
  ## Project a TFLite CPU oracle output, run a configured-live fixture, validate.
  outResult =
    default(BlaiTfliteParsedConfiguredWorkspaceOracleAddressFixtureResult)
  outResult.reference = reference
  blaiProjectUint8OutputRawBytesInto(
    referenceOutput, expectedWorkspaceOutput, outResult.projection)
  if not outResult.projection.projected:
    blaiFinishTfliteParsedConfiguredWorkspaceOracleAddressFixture(outResult)
    return
