proc npuInit*() =
  ## Bring the BLAI/CNN integration block into a usable reset/clock state.
  ## SDK `bl_npu_init` selects clock source 2 before inference toggles the gate.
  npuApplyRuntimeInitRegisterPlan(
    npuRuntimeInitRegisterPlan(
      blaiLoadReg(cnnClockReset()[].mmClkCpu),
      blaiLoadReg(cnnClockReset()[].swResetCodecSub),
      blaiLoadReg(mmMiscVram()[].vramCtrl)))

proc npuPlanConvLayerCompatibility*(
    inputAddr, outputAddr, weightAddr, biasAddr: uint32,
    inputW, inputH, inputC: uint32,
    outputC: uint32,
    kernelW, kernelH: uint32,
    strideW, strideH: uint32,
    padW, padH: uint32,
    activation: NpuActivation = npuActRelu): NpuConvCompatibilityPlan =
  ## Adapt the legacy dimension-based conv facade to recovered BLAI registers.
  ##
  ## The address subset is faithfully representable: input maps to the BLAI
  ## input buffer register, and nonzero weight/bias pointers map through the
  ## SDK layer-buffer setup semantics. The dimensions are retained as typed
  ## plan data because live BL808 execution requires a validated encoded
  ## instruction stream rather than direct dimension MMIO.
  result.inputAddr = inputAddr
  result.outputAddr = outputAddr
  result.weightAddr = weightAddr
  result.biasAddr = biasAddr
  result.inputW = inputW
  result.inputH = inputH
  result.inputC = inputC
  result.outputC = outputC
  result.kernelW = kernelW
  result.kernelH = kernelH
  result.strideW = strideW
  result.strideH = strideH
  result.padW = padW
  result.padH = padH
  result.activation = activation
  result.layerConfig = npuPlanLayerConfig(
    NpuLayerBuffers(weightAddr: weightAddr, biasAddr: biasAddr),
    inputBufferAddr = inputAddr,
    patchSize = 0,
    firstLayer = true)
  result.hasInputBuffer = inputAddr != 0'u32
  result.hasOutputBuffer = outputAddr != 0'u32
  result.hasWeightBuffer = weightAddr != 0'u32
  result.hasBiasBuffer = biasAddr != 0'u32
  result.outputBufferPlanOnly = result.hasOutputBuffer
  if result.hasInputBuffer:
    inc result.registerBackedAddressCount
  if result.hasWeightBuffer:
    inc result.registerBackedAddressCount
  if result.hasBiasBuffer:
    inc result.registerBackedAddressCount
  if result.outputBufferPlanOnly:
    inc result.planOnlyAddressCount
  result.addressConfigurable =
    result.hasInputBuffer or result.hasWeightBuffer or result.hasBiasBuffer
  result.nonzeroDimensions =
    inputW != 0'u32 and inputH != 0'u32 and inputC != 0'u32 and
    outputC != 0'u32 and kernelW != 0'u32 and kernelH != 0'u32 and
    strideW != 0'u32 and strideH != 0'u32
  result.squareKernel = kernelW == kernelH
  result.squareStride = strideW == strideH
  result.squarePadding = padW == padH
  result.descriptorDimensionsRepresentable =
    result.nonzeroDimensions and result.squareKernel and
    result.squareStride and result.squarePadding
  result.requiresInstructionStream = true
  result.directlyRunnable = false
  if not result.addressConfigurable:
    result.firstBlock = npuConvCompatibilityAddressSubset
    result.status = npuConvRequiresInstructionStream
  elif not result.descriptorDimensionsRepresentable:
    result.firstBlock = npuConvCompatibilityDimensions
    result.status = npuConvInvalidDimensions
  else:
    result.firstBlock = npuConvCompatibilityInstructionStream
    result.status = npuConvRequiresInstructionStream

proc npuApplyConvLayerCompatibilityInto*(
    plan: NpuConvCompatibilityPlan,
    outResult: var NpuConvCompatibilityApplyResult) =
  ## Apply the register-backed subset of a legacy conv facade plan.
  ##
  ## The output address and dimensions remain plan-only until encoded stream
  ## generation is validated for live execution.
  outResult = default(NpuConvCompatibilityApplyResult)
  outResult.addressConfigurable = plan.addressConfigurable
  outResult.outputBufferPlanOnly = plan.outputBufferPlanOnly
  outResult.firstBlock = plan.firstBlock
  if plan.hasWeightBuffer or plan.hasBiasBuffer:
    npuConfigureLayerBuffers(plan.layerConfig.buffers)
    outResult.layerBuffersApplied = true
  if plan.hasInputBuffer:
    npuSetInputBuffer(plan.inputAddr, plan.layerConfig.patchSize)
    outResult.inputBufferApplied = true
  when nimvm:
    discard
  else:
    let configuredApply = npuInstructionStreamConfiguredApplyPlan(false)
    doAssert configuredApply.valid
    npuApplyInstructionStreamConfiguredState(
      npuInstructionStreamConfiguredState(configuredApply))
  outResult.instructionStreamCleared = true
  outResult.applied = outResult.layerBuffersApplied or
    outResult.inputBufferApplied

proc npuApplyConvLayerCompatibility*(
    plan: NpuConvCompatibilityPlan): bool =
  ## Apply the register-backed subset and return legacy boolean status.
  var applied: NpuConvCompatibilityApplyResult
  npuApplyConvLayerCompatibilityInto(plan, applied)
  applied.addressConfigurable

proc npuConfigureConvLayerResult*(
    inputAddr, outputAddr, weightAddr, biasAddr: uint32,
    inputW, inputH, inputC: uint32,
    outputC: uint32,
    kernelW, kernelH: uint32,
    strideW, strideH: uint32,
    padW, padH: uint32,
    activation: NpuActivation = npuActRelu): NpuConvCompatibilityApplyResult =
  ## Compatibility facade that exposes the recovered register-side effects.
  ##
  ## Use this when a caller needs typed diagnostics for the legacy direct
  ## dimension API. It applies the same recovered address subset as
  ## `npuConfigureConvLayer` and still reports the remaining encoded-stream
  ## gate through `firstBlock`.
  npuApplyConvLayerCompatibilityInto(
    npuPlanConvLayerCompatibility(
      inputAddr, outputAddr, weightAddr, biasAddr,
      inputW, inputH, inputC, outputC, kernelW, kernelH,
      strideW, strideH, padW, padH, activation),
    result)

proc npuConvCompatibilityEvidenceInto*(
    plan: NpuConvCompatibilityPlan,
    applied: NpuConvCompatibilityApplyResult,
    outResult: var NpuConvCompatibilityEvidence) =
  ## Derive evidence for the legacy conv facade's recovered hardware boundary.
  outResult = default(NpuConvCompatibilityEvidence)
  outResult.planAddressConfigurable = plan.addressConfigurable
  outResult.applyAddressConfigurable = applied.addressConfigurable
  outResult.registerBackedAddresses =
    plan.registerBackedAddressCount > 0'u32 and
      applied.layerBuffersApplied == (plan.hasWeightBuffer or plan.hasBiasBuffer) and
      applied.inputBufferApplied == plan.hasInputBuffer
  outResult.outputPlanOnly =
    plan.outputBufferPlanOnly and applied.outputBufferPlanOnly and
      not applied.outputBufferApplied
  outResult.dimensionsRepresentable =
    plan.nonzeroDimensions and plan.squareKernel and plan.squareStride and
      plan.squarePadding and plan.descriptorDimensionsRepresentable
  outResult.instructionStreamRequired =
    plan.requiresInstructionStream and
      plan.firstBlock == npuConvCompatibilityInstructionStream and
      applied.firstBlock == plan.firstBlock
  outResult.notDirectlyRunnable = not plan.directlyRunnable
  outResult.streamStateCleared = applied.instructionStreamCleared
  outResult.applyMatchesPlan =
    applied.addressConfigurable == plan.addressConfigurable and
      applied.outputBufferPlanOnly == plan.outputBufferPlanOnly and
      applied.applied == plan.addressConfigurable
  outResult.boundaryMatchesRecoveredHardware =
    outResult.planAddressConfigurable and outResult.applyAddressConfigurable and
      outResult.registerBackedAddresses and outResult.outputPlanOnly and
      outResult.dimensionsRepresentable and
      outResult.instructionStreamRequired and outResult.notDirectlyRunnable and
      outResult.streamStateCleared and outResult.applyMatchesPlan
  outResult.valid = outResult.boundaryMatchesRecoveredHardware

proc npuConvCompatibilityEvidence*(
    plan: NpuConvCompatibilityPlan,
    applied: NpuConvCompatibilityApplyResult): NpuConvCompatibilityEvidence =
  ## Convenience wrapper for legacy conv facade boundary evidence.
  npuConvCompatibilityEvidenceInto(plan, applied, result)

proc npuInstructionStreamGuardEvidenceInto*(
    configuredWrapper: NpuWrapperStateResult,
    configuredReadiness: NpuLayerRunReadiness,
    clearedWrapper: NpuWrapperStateResult,
    clearedReadiness: NpuLayerRunReadiness,
    applied: NpuConvCompatibilityApplyResult,
    blockedRun: NpuLayerRunResult,
    outResult: var NpuInstructionStreamGuardEvidence) =
  ## Derive evidence for the recovered configured-stream start guard.
  outResult = default(NpuInstructionStreamGuardEvidence)
  outResult.configuredStateCaptured =
    configuredWrapper.instructionStreamConfigured
  outResult.configuredWrapperRunnable = configuredWrapper.runnable
  outResult.configuredReadinessFirstBlockClean =
    configuredReadiness.firstBlock == npuLayerRunNoBlock
  outResult.configuredReadinessTimeoutCaptured =
    configuredReadiness.timeout != 0'u32
  outResult.configuredReadinessRunnable =
    configuredReadiness.runnable and
      configuredReadiness.firstBlock == npuLayerRunNoBlock
  outResult.configuredReadinessMatchesState =
    configuredReadiness.instructionStreamConfigured ==
      configuredWrapper.instructionStreamConfigured and
    configuredReadiness.runnable == configuredWrapper.runnable
  outResult.facadeClearedStream = applied.instructionStreamCleared
  outResult.clearedWrapperBlocked =
    not clearedWrapper.instructionStreamConfigured and
      not clearedWrapper.runnable
  outResult.clearedReadinessTimeoutCaptured =
    clearedReadiness.timeout != 0'u32
  outResult.clearedReadinessBlocked =
    not clearedReadiness.instructionStreamConfigured and
      not clearedReadiness.runnable and
      clearedReadiness.firstBlock == npuLayerRunInstructionStream
  outResult.facadeInvalidatedConfiguredStream =
    outResult.configuredStateCaptured and outResult.configuredWrapperRunnable and
      outResult.configuredReadinessFirstBlockClean and
      outResult.facadeClearedStream and outResult.clearedWrapperBlocked and
      outResult.clearedReadinessBlocked
  outResult.blockedRunNotStarted =
    not blockedRun.started and not blockedRun.completed
  outResult.blockedRunUnsupported =
    blockedRun.status == npuUnsupported and
      blockedRun.firstBlock == npuLayerRunInstructionStream
  outResult.blockedRunWaitPlanNotConfigured =
    not blockedRun.waitPlan.configured and
      blockedRun.readiness.firstBlock == npuLayerRunInstructionStream
  outResult.guardMatchesRecoveredHardware =
    outResult.configuredStateCaptured and
      outResult.configuredWrapperRunnable and
      outResult.configuredReadinessFirstBlockClean and
      outResult.configuredReadinessTimeoutCaptured and
      outResult.configuredReadinessRunnable and
      outResult.configuredReadinessMatchesState and
      outResult.facadeClearedStream and
      outResult.clearedWrapperBlocked and
      outResult.clearedReadinessTimeoutCaptured and
      outResult.clearedReadinessBlocked and
      outResult.facadeInvalidatedConfiguredStream and
      outResult.blockedRunNotStarted and
      outResult.blockedRunUnsupported and
      outResult.blockedRunWaitPlanNotConfigured
  outResult.valid = outResult.guardMatchesRecoveredHardware

proc npuInstructionStreamGuardEvidence*(
    configuredWrapper: NpuWrapperStateResult,
    configuredReadiness: NpuLayerRunReadiness,
    clearedWrapper: NpuWrapperStateResult,
    clearedReadiness: NpuLayerRunReadiness,
    applied: NpuConvCompatibilityApplyResult,
    blockedRun: NpuLayerRunResult): NpuInstructionStreamGuardEvidence =
  ## Convenience wrapper for configured-stream guard evidence.
  npuInstructionStreamGuardEvidenceInto(
    configuredWrapper, configuredReadiness, clearedWrapper, clearedReadiness,
    applied, blockedRun, result)

proc npuConfigureConvLayer*(inputAddr, outputAddr, weightAddr, biasAddr: uint32,
                            inputW, inputH, inputC: uint32,
                            outputC: uint32,
                            kernelW, kernelH: uint32,
                            strideW, strideH: uint32,
                            padW, padH: uint32,
                            activation: NpuActivation = npuActRelu) =
  ## Compatibility facade for callers that still provide direct conv dimensions.
  ##
  ## This configures the recovered address registers that can be represented
  ## faithfully and clears runnable stream state because the dimensions alone do
  ## not form a validated BL808 BLAI instruction stream.
  discard npuConfigureConvLayerResult(
    inputAddr, outputAddr, weightAddr, biasAddr,
    inputW, inputH, inputC, outputC, kernelW, kernelH,
    strideW, strideH, padW, padH, activation)

proc npuLayerRunReadinessInto*(instructionStreamConfigured: bool,
                               timeout: uint32,
                               outResult: var NpuLayerRunReadiness) =
  ## Explain whether the legacy `npuRunLayer` facade is allowed to start.
  outResult = default(NpuLayerRunReadiness)
  outResult.instructionStreamConfigured = instructionStreamConfigured
  outResult.timeout = timeout
  outResult.runnable = instructionStreamConfigured
  if outResult.runnable:
    outResult.firstBlock = npuLayerRunNoBlock
  else:
    outResult.firstBlock = npuLayerRunInstructionStream

proc npuLayerRunReadiness*(instructionStreamConfigured: bool,
                           timeout: uint32): NpuLayerRunReadiness =
  ## Convenience wrapper for pure `npuRunLayer` readiness planning.
  npuLayerRunReadinessInto(instructionStreamConfigured, timeout, result)

proc npuPlanLayerRunInto*(instructionStreamConfigured: bool,
                          timeout: uint32,
                          outResult: var NpuLayerRunPlan) =
  ## Plan the legacy layer-run guard and completion wait policy together.
  outResult = default(NpuLayerRunPlan)
  npuLayerRunReadinessInto(
    instructionStreamConfigured, timeout, outResult.readiness)
  outResult.firstBlock = outResult.readiness.firstBlock
  outResult.runnable = outResult.readiness.runnable
  outResult.waitPlan = npuPlanCompletionWait(
    timeout = timeout,
    configured = outResult.readiness.instructionStreamConfigured)

proc npuPlanLayerRun*(instructionStreamConfigured: bool,
                      timeout: uint32): NpuLayerRunPlan =
  ## Convenience wrapper for legacy layer-run planning.
  npuPlanLayerRunInto(instructionStreamConfigured, timeout, result)

proc blaiGeneratedNpuRunPlanInto*(
    configure: BlaiGeneratedNpuConfigureResult,
    timeout: uint32,
    outResult: var BlaiGeneratedNpuRunPlan) =
  ## Plan a generated NPU run from guarded register-configuration evidence.
  outResult = default(BlaiGeneratedNpuRunPlan)
  outResult.configure = configure
  outResult.timeout = timeout
  outResult.configureBlock = configure.firstBlock
  outResult.configured = configure.valid and configure.applied and
    configure.configuredState.configured
  npuPlanLayerRunInto(outResult.configured, timeout, outResult.layerRun)
  outResult.runnable = outResult.layerRun.runnable
  outResult.firstBlock = outResult.layerRun.firstBlock
  outResult.valid = outResult.configured and outResult.runnable

proc blaiGeneratedNpuRunPlan*(
    configure: BlaiGeneratedNpuConfigureResult,
    timeout: uint32): BlaiGeneratedNpuRunPlan =
  ## Convenience wrapper for generated NPU run planning.
  blaiGeneratedNpuRunPlanInto(configure, timeout, result)

proc blaiGeneratedNpuRunPreflightPlanInto*(
    configure: BlaiGeneratedNpuConfigurePlan,
    timeout: uint32,
    outResult: var BlaiGeneratedNpuRunPreflightPlan) =
  ## Plan generated NPU run readiness before hardware configuration.
  outResult = default(BlaiGeneratedNpuRunPreflightPlan)
  outResult.configure = configure
  outResult.timeout = timeout
  outResult.configureBlock = configure.firstBlock
  outResult.wouldConfigure = configure.valid and configure.wouldApply and
    configure.configuredState.configured
  npuPlanLayerRunInto(outResult.wouldConfigure, timeout, outResult.layerRun)
  outResult.runnableAfterConfigure = outResult.layerRun.runnable
  outResult.firstBlock = outResult.layerRun.firstBlock
  outResult.valid = outResult.wouldConfigure and outResult.runnableAfterConfigure

proc blaiGeneratedNpuRunPreflightPlan*(
    configure: BlaiGeneratedNpuConfigurePlan,
    timeout: uint32): BlaiGeneratedNpuRunPreflightPlan =
  ## Convenience wrapper for generated NPU run preflight planning.
  blaiGeneratedNpuRunPreflightPlanInto(configure, timeout, result)

proc blaiGeneratedNpuPipelinePreflightInto*(
    blob: openArray[uint8],
    instructions: var openArray[uint8],
    biases: var openArray[uint8],
    weights: var openArray[uint8],
    instAddr, biasAddr, weightAddr: uint32,
    timeout: uint32,
    outResult: var BlaiGeneratedNpuPipelinePreflightResult) =
  ## Compose pure generated-blob preparation, configure evidence, and run gate.
  outResult = default(BlaiGeneratedNpuPipelinePreflightResult)
  outResult.timeout = timeout
  blaiPrepareGeneratedNpuPayloadsInto(
    blob, instructions, biases, weights,
    instAddr, biasAddr, weightAddr, outResult.prepared)
  outResult.preparedValid = outResult.prepared.valid
  outResult.preparedBlock = outResult.prepared.firstBlock
  outResult.packageBlock = outResult.prepared.packageFirstBlock
  outResult.stagedBlock = outResult.prepared.stagedFirstBlock
  outResult.payloadCopyBlock = outResult.prepared.payloadCopyBlock
  outResult.addressBlock = outResult.prepared.addressBlock
  blaiGeneratedNpuConfigurePlanInto(outResult.prepared, outResult.configure)
  outResult.configureValid = outResult.configure.valid
  outResult.configureBlock = outResult.configure.firstBlock
  blaiGeneratedNpuRunPreflightPlanInto(
    outResult.configure, timeout, outResult.run)
  outResult.runPreflightValid = outResult.run.valid
  outResult.runBlock = outResult.run.firstBlock
  outResult.readyForHardwareConfigure =
    outResult.preparedValid and outResult.configureValid and
      outResult.runPreflightValid
  if not outResult.prepared.sectionPlanValid:
    outResult.firstBlock = blaiGeneratedNpuPipelineSectionPlan
  elif outResult.preparedBlock == blaiGeneratedNpuPreparedPayloadPackage:
    outResult.firstBlock = blaiGeneratedNpuPipelinePackagePreflight
  elif not outResult.prepared.staged.copied:
    outResult.firstBlock = blaiGeneratedNpuPipelinePayloadStage
  elif not outResult.prepared.staged.addressesValid:
    outResult.firstBlock = blaiGeneratedNpuPipelineAddressPlan
  elif not outResult.configureValid:
    outResult.firstBlock = blaiGeneratedNpuPipelineConfigurePlan
  elif not outResult.runPreflightValid:
    outResult.firstBlock = blaiGeneratedNpuPipelineRunPreflight
  else:
    outResult.firstBlock = blaiGeneratedNpuPipelineNoBlock
  outResult.valid = outResult.readyForHardwareConfigure

proc blaiGeneratedNpuPipelinePreflight*(
    blob: openArray[uint8],
    instructions: var openArray[uint8],
    biases: var openArray[uint8],
    weights: var openArray[uint8],
    instAddr, biasAddr, weightAddr: uint32,
    timeout: uint32):
    BlaiGeneratedNpuPipelinePreflightResult =
  ## Convenience wrapper for pure generated-blob pipeline preflight.
  blaiGeneratedNpuPipelinePreflightInto(
    blob, instructions, biases, weights,
    instAddr, biasAddr, weightAddr, timeout, result)

proc npuRunLayerInto*(timeout: uint32,
                      outResult: var NpuLayerRunResult) =
  ## Run the legacy layer facade while preserving typed guard evidence.
  outResult = default(NpuLayerRunResult)
  let runPlan = npuPlanLayerRun(npuInstructionStreamConfigured(), timeout)
  outResult.readiness = runPlan.readiness
  outResult.firstBlock = runPlan.firstBlock
  outResult.waitPlan = runPlan.waitPlan
  if not runPlan.runnable:
    outResult.status = npuUnsupported
    return
  npuWaitForCompletionInto(outResult.waitPlan, outResult.completion)
  outResult.started = outResult.completion.started
  outResult.completed = outResult.completion.statusDecision.completed
  outResult.status = outResult.completion.status

proc blaiRunGeneratedNpuPlanInto*(
    plan: BlaiGeneratedNpuRunPlan,
    outResult: var BlaiGeneratedNpuRunResult) =
  ## Execute a generated NPU run plan only after typed readiness passes.
  outResult = default(BlaiGeneratedNpuRunResult)
  outResult.plan = plan
  outResult.configureBlock = plan.configureBlock
  outResult.firstBlock = plan.firstBlock
  outResult.layerRun.readiness = plan.layerRun.readiness
  outResult.layerRun.firstBlock = plan.layerRun.firstBlock
  outResult.layerRun.waitPlan = plan.layerRun.waitPlan
  if not plan.runnable:
    outResult.status = npuUnsupported
    outResult.layerRun.status = npuUnsupported
    return
  npuWaitForCompletionInto(plan.layerRun.waitPlan, outResult.layerRun.completion)
  outResult.layerRun.started = outResult.layerRun.completion.started
  outResult.layerRun.completed =
    outResult.layerRun.completion.statusDecision.completed
  outResult.layerRun.status = outResult.layerRun.completion.status
  outResult.started = outResult.layerRun.started
  outResult.completed = outResult.layerRun.completed
  outResult.status = outResult.layerRun.status
  outResult.valid = outResult.started

proc blaiRunGeneratedNpuPlan*(
    plan: BlaiGeneratedNpuRunPlan): BlaiGeneratedNpuRunResult =
  ## Convenience wrapper for generated NPU run execution.
  blaiRunGeneratedNpuPlanInto(plan, result)

proc npuRunLayerResult*(timeout: uint32 = 5_000_000): NpuLayerRunResult =
  ## Convenience result-returning wrapper for typed layer-run execution.
  npuRunLayerInto(timeout, result)

proc npuRunLayer*(timeout: uint32 = 5_000_000): NpuError =
  ## Compatibility wrapper for running an already configured instruction stream.
  npuRunLayerResult(timeout).status

proc npuBusyStatusFromGeneralCfgInto*(generalCfg: uint32,
                                      outResult: var NpuBusyStatusResult) =
  ## Decode recovered BLAI AXI idle bits from `BALI_GENERAL_CFG`.
  outResult = default(NpuBusyStatusResult)
  let generalDecode = npuGeneralCfgDecodeFromRaw(generalCfg)
  outResult.generalCfg = generalDecode.generalCfg
  outResult.axiWriteIdle = generalDecode.axiWriteIdle
  outResult.axiReadIdle = generalDecode.axiReadIdle
  outResult.busy = generalDecode.busy

proc npuBusyStatusFromGeneralCfg*(generalCfg: uint32): NpuBusyStatusResult =
  ## Convenience wrapper for pure BLAI busy-status decoding.
  npuBusyStatusFromGeneralCfgInto(generalCfg, result)

proc npuBusyStatusInto*(outResult: var NpuBusyStatusResult) =
  ## Read and decode the live BLAI AXI idle/busy status bits.
  npuBusyStatusFromGeneralCfgInto(blaiLoadReg(blaiRegs()[].generalCfg), outResult)

proc npuBusyStatus*(): NpuBusyStatusResult =
  ## Convenience wrapper for live BLAI busy-status decoding.
  npuBusyStatusInto(result)

proc npuIsBusy*(): bool =
  ## Report BLAI AXI activity from the recovered GENERAL_CFG idle status bits.
  npuBusyStatus().busy

proc npuBlaiCommandStatusFromRawInto*(
    mmCodecMisc1, codecLimiterRead, codecLimiterWrite: uint32,
    outResult: var NpuBlaiCommandStatusResult) =
  ## Decode the MM_MISC/CODEC_MISC BLAI command-count diagnostic registers.
  outResult = default(NpuBlaiCommandStatusResult)
  outResult.mmCodecMisc1 = mmCodecMisc1
  outResult.mmCommandCount = mmCodecMisc1 and BlaiCommandCountMask
  outResult.mmCommandMode = (mmCodecMisc1 and BlaiCommandModeMask) != 0'u32
  outResult.codecLimiterRead = codecLimiterRead
  outResult.readCommandCount = codecLimiterRead and BlaiLimiterCountMask
  outResult.readCommandMode =
    (codecLimiterRead and BlaiLimiterModeMask) != 0'u32
  outResult.codecLimiterWrite = codecLimiterWrite
  outResult.writeCommandCount = codecLimiterWrite and BlaiLimiterCountMask
  outResult.writeCommandMode =
    (codecLimiterWrite and BlaiLimiterModeMask) != 0'u32
  outResult.anyCommandMode =
    outResult.mmCommandMode or outResult.readCommandMode or
      outResult.writeCommandMode
  outResult.anyCommandCount =
    (outResult.mmCommandCount or outResult.readCommandCount or
      outResult.writeCommandCount) != 0'u32
  outResult.valid =
    outResult.mmCommandCount <= BlaiCommandCountMask and
      outResult.readCommandCount <= BlaiLimiterCountMask and
      outResult.writeCommandCount <= BlaiLimiterCountMask

proc npuBlaiCommandStatusFromRaw*(
    mmCodecMisc1, codecLimiterRead, codecLimiterWrite: uint32):
    NpuBlaiCommandStatusResult =
  ## Convenience wrapper for raw BLAI command-count diagnostics.
  npuBlaiCommandStatusFromRawInto(
    mmCodecMisc1, codecLimiterRead, codecLimiterWrite, result)

proc npuBlaiCommandStatusInto*(
    outResult: var NpuBlaiCommandStatusResult) =
  ## Read and decode live BLAI command-count diagnostic registers.
  npuBlaiCommandStatusFromRawInto(
    blaiLoadReg(mmMiscBlaiCommand()[].codecMisc1),
    blaiLoadReg(codecMisc()[].blaiLimiterRead),
    blaiLoadReg(codecMisc()[].blaiLimiterWrite),
    outResult)

proc npuBlaiCommandStatus*(): NpuBlaiCommandStatusResult =
  ## Convenience wrapper for the live BLAI command-count diagnostics.
  npuBlaiCommandStatusInto(result)

proc npuBusDecodeStatusFromRawInto*(
    mmBusDecErr, mmBusDecErrAddr, mcuBusDecErr, mcuBusDecErrAddr: uint32,
    outResult: var NpuBusDecodeStatusResult) =
  ## Decode MM_MISC bus decode-error latch words.
  outResult = default(NpuBusDecodeStatusResult)
  outResult.mmBusDecErr = mmBusDecErr
  outResult.mmBusDecErrAddr = mmBusDecErrAddr
  outResult.mcuBusDecErr = mcuBusDecErr
  outResult.mcuBusDecErrAddr = mcuBusDecErrAddr
  outResult.mmErrorLatched = (mmBusDecErr and MmBusDecErrLatchMask) != 0'u32
  outResult.mmErrorWasWrite = (mmBusDecErr and MmBusDecErrWriteMask) != 0'u32
  outResult.mmErrorSource =
    (mmBusDecErr and MmBusDecErrSrcMask) shr BusDecErrSrcShift
  outResult.mmErrorId =
    (mmBusDecErr and MmBusDecErrIdMask) shr BusDecErrIdShift
  outResult.mcuErrorLatched = (mcuBusDecErr and McuBusDecErrLatchMask) != 0'u32
  outResult.mcuErrorWasWrite = (mcuBusDecErr and McuBusDecErrWriteMask) != 0'u32
  outResult.mcuErrorSource =
    (mcuBusDecErr and McuBusDecErrSrcMask) shr BusDecErrSrcShift
  outResult.mcuErrorId =
    (mcuBusDecErr and McuBusDecErrIdMask) shr BusDecErrIdShift
  outResult.anyErrorLatched =
    outResult.mmErrorLatched or outResult.mcuErrorLatched
  outResult.noDecodeError = not outResult.anyErrorLatched
  outResult.valid =
    outResult.mmErrorSource <= 0x7'u32 and outResult.mmErrorId <= 0x1F'u32 and
      outResult.mcuErrorSource <= 0x3'u32 and outResult.mcuErrorId <= 0x3F'u32

proc npuBusDecodeStatusFromRaw*(
    mmBusDecErr, mmBusDecErrAddr, mcuBusDecErr, mcuBusDecErrAddr: uint32):
      NpuBusDecodeStatusResult =
  ## Convenience wrapper for raw bus decode-error diagnostics.
  npuBusDecodeStatusFromRawInto(
    mmBusDecErr, mmBusDecErrAddr, mcuBusDecErr, mcuBusDecErrAddr, result)

proc npuBusDecodeStatusInto*(outResult: var NpuBusDecodeStatusResult) =
  ## Read and decode live MM_MISC bus decode-error diagnostics.
  npuBusDecodeStatusFromRawInto(
    blaiLoadReg(mmMiscBusDecode()[].mmBusDecErr),
    blaiLoadReg(mmMiscBusDecode()[].mmBusDecErrAddr),
    blaiLoadReg(mmMiscBusDecode()[].mcuBusDecErr),
    blaiLoadReg(mmMiscBusDecode()[].mcuBusDecErrAddr),
    outResult)

proc npuBusDecodeStatus*(): NpuBusDecodeStatusResult =
  ## Convenience wrapper for live MM_MISC bus decode-error diagnostics.
  npuBusDecodeStatusInto(result)

proc npuD0ProbeOutputMovementEvidenceInto*(
    inputByte, expectedInputByte, outputByte, sentinelByte: uint8,
    command: NpuBlaiCommandStatusResult,
    bus: NpuBusDecodeStatusResult,
    completionObserved, cpuOracleValidated: bool,
    outResult: var NpuD0ProbeOutputMovementEvidence) =
  ## Classify D0 raw-stream DATA movement without claiming model correctness.
  outResult = default(NpuD0ProbeOutputMovementEvidence)
  outResult.inputByte = inputByte
  outResult.expectedInputByte = expectedInputByte
  outResult.outputByte = outputByte
  outResult.sentinelByte = sentinelByte
  outResult.inputMatches = inputByte == expectedInputByte
  outResult.outputMoved = outputByte != sentinelByte
  outResult.outputObserved = outResult.outputMoved
  outResult.commandValid = command.valid
  outResult.commandActivity = command.anyCommandCount
  outResult.busValid = bus.valid
  outResult.busDecodeClean = bus.noDecodeError
  outResult.completionObserved = completionObserved
  outResult.cpuOracleValidated = cpuOracleValidated
  outResult.movementEvidenceValid =
    outResult.inputMatches and outResult.outputObserved and
      outResult.commandValid and outResult.commandActivity and
      outResult.busValid and outResult.busDecodeClean
  outResult.modelOutputStillUnvalidated =
    outResult.movementEvidenceValid and not outResult.cpuOracleValidated
  outResult.valid =
    outResult.movementEvidenceValid and
      (outResult.cpuOracleValidated or outResult.modelOutputStillUnvalidated)

proc npuD0ProbeOutputMovementEvidence*(
    inputByte, expectedInputByte, outputByte, sentinelByte: uint8,
    command: NpuBlaiCommandStatusResult,
    bus: NpuBusDecodeStatusResult,
    completionObserved: bool = false,
    cpuOracleValidated: bool = false): NpuD0ProbeOutputMovementEvidence =
  ## Convenience wrapper for D0 raw-stream DATA movement evidence.
  npuD0ProbeOutputMovementEvidenceInto(
    inputByte, expectedInputByte, outputByte, sentinelByte, command, bus,
    completionObserved, cpuOracleValidated, result)

proc npuD0WeightByteExperimentEvidenceInto*(
    baseline, experiment: NpuD0ProbeOutputMovementEvidence,
    baselineFirstWeightByte, experimentFirstWeightByte,
    expectedActiveFirstWeightByte: uint8,
    outResult: var NpuD0WeightByteExperimentEvidence) =
  ## Classify whether the active first-weight byte changes D0 DATA movement.
  outResult = default(NpuD0WeightByteExperimentEvidence)
  outResult.baselineValid = baseline.movementEvidenceValid
  outResult.experimentInputValid = experiment.inputMatches
  outResult.experimentCommandValid = experiment.commandValid
  outResult.experimentBusClean = experiment.busValid and experiment.busDecodeClean
  outResult.baselineFirstWeightByte = baselineFirstWeightByte
  outResult.experimentFirstWeightByte = experimentFirstWeightByte
  outResult.expectedActiveFirstWeightByte = expectedActiveFirstWeightByte
  outResult.changedToActiveWeightByte =
    baselineFirstWeightByte != experimentFirstWeightByte and
      experimentFirstWeightByte == expectedActiveFirstWeightByte
  outResult.baselineOutputMoved = baseline.outputMoved
  outResult.experimentOutputMoved = experiment.outputMoved
  outResult.experimentOutputGated =
    not experiment.outputMoved and experiment.outputByte == experiment.sentinelByte
  outResult.classified =
    outResult.baselineValid and outResult.experimentInputValid and
      outResult.experimentCommandValid and outResult.experimentBusClean and
      outResult.changedToActiveWeightByte and
      (outResult.experimentOutputMoved or outResult.experimentOutputGated)
  outResult.supportsWeightSensitiveMovement =
    outResult.classified and outResult.baselineOutputMoved and
      outResult.experimentOutputGated
  outResult.supportsCorePathDifference =
    outResult.classified and outResult.baselineOutputMoved and
      outResult.experimentOutputMoved
  outResult.valid = outResult.classified

proc npuD0WeightByteExperimentEvidence*(
    baseline, experiment: NpuD0ProbeOutputMovementEvidence,
    baselineFirstWeightByte, experimentFirstWeightByte,
    expectedActiveFirstWeightByte: uint8): NpuD0WeightByteExperimentEvidence =
  ## Convenience wrapper for D0 first-weight-byte experiment classification.
  npuD0WeightByteExperimentEvidenceInto(
    baseline, experiment, baselineFirstWeightByte, experimentFirstWeightByte,
    expectedActiveFirstWeightByte, result)

