      (outResult.m0OutputMoved or outResult.m0OutputGated)
  outResult.supportsM0CoreRouteIssue =
    outResult.classified and outResult.m0OutputGated
  outResult.supportsMaterializedContextIssue =
    outResult.classified and outResult.m0OutputMoved
  outResult.valid = outResult.classified

