proc npuM0SyntheticAddressAliasContrastEvidenceInto*(
    stream: NpuD0ProbeInstructionStreamEvidence,
    cached, projected: NpuD0ProbeOutputMovementEvidence,
    instProjection, weightProjection, biasProjection,
    dataProjection: BlaiHardwareAddressProjection,
    outResult: var NpuM0SyntheticAddressAliasContrastEvidence) =
  ## Classify M0 synthetic DATA movement after hardware-address projection.
  outResult = default(NpuM0SyntheticAddressAliasContrastEvidence)
  outResult.streamValid = stream.valid
  outResult.cachedInputValid = cached.inputMatches
  outResult.cachedCommandValid = cached.commandValid
  outResult.cachedBusClean = cached.busValid and cached.busDecodeClean
  outResult.cachedOutputGated =
    not cached.outputMoved and cached.outputByte == cached.sentinelByte
  outResult.instProjected =
    instProjection.projected and instProjection.addressFits
  outResult.weightProjected =
    weightProjection.projected and weightProjection.addressFits
  outResult.biasProjected =
    biasProjection.projected and biasProjection.addressFits
  outResult.dataProjected =
    dataProjection.projected and dataProjection.addressFits
  outResult.projectedAddressesValid =
    outResult.instProjected and outResult.weightProjected and
      outResult.biasProjected and outResult.dataProjected
  outResult.projectedInputValid = projected.inputMatches
  outResult.projectedCommandValid = projected.commandValid
  outResult.projectedBusClean =
    projected.busValid and projected.busDecodeClean
  outResult.projectedOutputMoved = projected.outputMoved
  outResult.projectedOutputGated =
    not projected.outputMoved and
      projected.outputByte == projected.sentinelByte
  outResult.classified =
    outResult.streamValid and outResult.cachedInputValid and
      outResult.cachedCommandValid and outResult.cachedBusClean and
      outResult.cachedOutputGated and outResult.projectedAddressesValid and
      outResult.projectedInputValid and outResult.projectedCommandValid and
      outResult.projectedBusClean and
      (outResult.projectedOutputMoved or outResult.projectedOutputGated)
  outResult.supportsAddressAliasBlocker =
    outResult.classified and outResult.projectedOutputMoved
  outResult.supportsCoreRouteBlocker =
    outResult.classified and outResult.projectedOutputGated
  outResult.valid = outResult.classified

