    outResult: var NpuM0InterruptBoundDramContrastEvidence) =
  ## Classify whether forced M0 IRQ binding changes DRAM synthetic movement.
  outResult = default(NpuM0InterruptBoundDramContrastEvidence)
  outResult.streamValid = stream.valid
  outResult.baselineDramGated =
    not baselineDram.outputMoved and
      baselineDram.outputByte == baselineDram.sentinelByte
  outResult.baselineDramMoved = baselineDram.outputMoved
  outResult.forcedBindingRequested = forcedBindingRequested
  outResult.bindingApplied = bindingApplied
  outResult.boundInputValid = boundDram.inputMatches
  outResult.boundCommandValid = boundDram.commandValid
  outResult.boundBusClean = boundDram.busValid and boundDram.busDecodeClean
  outResult.boundOutputMoved = boundDram.outputMoved
  outResult.boundOutputGated =
    not boundDram.outputMoved and boundDram.outputByte == boundDram.sentinelByte
  outResult.irqHandlerObserved = irqHandlerObserved
  outResult.classified =
    outResult.streamValid and outResult.baselineDramGated and
      outResult.forcedBindingRequested and outResult.bindingApplied and
      outResult.boundInputValid and outResult.boundCommandValid and
      outResult.boundBusClean and
      (outResult.boundOutputMoved or outResult.boundOutputGated)
  outResult.baselineAlreadyMoved =
    outResult.streamValid and outResult.baselineDramMoved and
      outResult.forcedBindingRequested and outResult.bindingApplied and
      outResult.boundInputValid and outResult.boundCommandValid and
      outResult.boundBusClean and outResult.boundOutputMoved
  outResult.supportsInterruptBindingBlocker =
    outResult.classified and outResult.boundOutputMoved
  outResult.supportsM0StartRouteBlocker =
    outResult.classified and outResult.boundOutputGated
  outResult.valid = outResult.classified or outResult.baselineAlreadyMoved

