proc npuM0DramCompletionSurfaceEvidenceInto*(
    stream: NpuD0ProbeInstructionStreamEvidence,
    movement: NpuD0ProbeOutputMovementEvidence,
    completion: BlaiNpuCompletionWaitResult,
    outResult: var NpuM0DramCompletionSurfaceEvidence) =
  ## Classify the stable M0 DRAM wait-exit surface after synthetic launch.
  outResult = default(NpuM0DramCompletionSurfaceEvidence)
  outResult.streamValid = stream.valid
  outResult.movementValid =
    movement.inputMatches and movement.commandValid and movement.commandActivity and
      movement.busValid and movement.busDecodeClean
  outResult.outputMoved = movement.outputMoved
  outResult.outputGated =
    not movement.outputMoved and movement.outputByte == movement.sentinelByte
  outResult.waitStarted = completion.started
  outResult.pollExhausted = completion.poll.exhausted
  outResult.noInterrupt =
    not completion.interruptObserved and
      not completion.waitExitInterrupt.interruptPending
  outResult.waitIdle = not completion.waitExitBusy.busy
  outResult.commandActivity = movement.commandActivity
  outResult.busClean = movement.busValid and movement.busDecodeClean
  outResult.movedWithoutCompletion =
    outResult.outputMoved and outResult.noInterrupt
  outResult.gatedIdleNoInterrupt =
    outResult.outputGated and outResult.noInterrupt and outResult.waitIdle
  outResult.completionSurfaceKnown =
    outResult.movedWithoutCompletion or outResult.gatedIdleNoInterrupt
  outResult.valid =
    outResult.streamValid and outResult.movementValid and
      outResult.waitStarted and outResult.pollExhausted and
      outResult.noInterrupt and outResult.waitIdle and
      outResult.commandActivity and outResult.busClean and
      outResult.completionSurfaceKnown

proc npuM0DramCompletionSurfaceEvidence*(
    stream: NpuD0ProbeInstructionStreamEvidence,
    movement: NpuD0ProbeOutputMovementEvidence,
    completion: BlaiNpuCompletionWaitResult):
      NpuM0DramCompletionSurfaceEvidence =
  ## Convenience wrapper for M0 DRAM wait-exit surface classification.
  npuM0DramCompletionSurfaceEvidenceInto(
    stream, movement, completion, result)

proc blaiForwardCompletionEdgeRecoveryFrontierEvidenceInto*(
    terminal: BlaiForwardD0TerminalControlContrastEvidence,
    engine: BlaiForwardD0EngineContextGapEvidence,
    buffer: BlaiForwardD0BufferContextContrastEvidence,
    weight: NpuD0WeightByteExperimentEvidence,
    route: NpuM0D0SyntheticRouteContrastEvidence,
    alias: NpuM0SyntheticAddressAliasContrastEvidence,
    dram: NpuM0DramCompletionSurfaceEvidence,
    forced: NpuM0InterruptBoundDramContrastEvidence,
    vram: NpuM0D0BootVramRouteDramContrastEvidence,
    clock: NpuM0D0BootClockControlDramContrastEvidence,
    output:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence,
    outResult: var BlaiForwardCompletionEdgeRecoveryFrontierEvidence) =
  ## Compose the current completion-edge recovery frontier.
  outResult = default(BlaiForwardCompletionEdgeRecoveryFrontierEvidence)
  outResult.terminalContrastValid = terminal.valid
  outResult.engineContextValid = engine.valid
  outResult.bufferContextValid = buffer.valid
  outResult.d0WeightExperimentValid = weight.valid
  outResult.m0RouteContrastValid = route.valid
  outResult.addressAliasContrastValid = alias.valid
  outResult.m0DramSurfaceValid = dram.valid
  outResult.forcedBindingContrastValid = forced.valid
  outResult.d0BootVramContrastValid = vram.valid
  outResult.d0BootClockContrastValid = clock.valid
  outResult.outputReadinessValid = output.valid
  outResult.terminalControlRuledOut =
    terminal.terminalControlNotSoleBlock and terminal.nextWorkIsEngineContext
  outResult.instructionMaterializationRuledOut =
    buffer.instructionWordsMatch and
      buffer.sameInstructionsDifferentOperandContext
  outResult.firstWeightByteRuledOut =
    weight.supportsCorePathDifference and weight.experimentOutputMoved
  outResult.cachedAddressAliasRuledOut =
    alias.supportsCoreRouteBlocker and alias.projectedOutputGated
  outResult.forcedInterruptBindingRuledOut =
    forced.valid and not forced.supportsInterruptBindingBlocker and
      (forced.supportsM0StartRouteBlocker or forced.baselineAlreadyMoved)
  outResult.d0BootVramRouteRuledOut =
    vram.valid and not vram.supportsD0BootVramRoutePrecondition and
      vram.supportsDeeperM0StartRouteBlocker
  outResult.d0BootClockControlRuledOut =
    clock.valid and not clock.supportsD0BootClockPrecondition and
      (clock.supportsDeeperM0StartRouteBlocker or clock.baselineAlreadyMoved)
  outResult.m0DramCompletionSurfaceKnown =
    dram.completionSurfaceKnown and dram.noInterrupt and dram.waitIdle and
      dram.busClean
  outResult.completionEdgeStillMissing =
    outResult.m0DramCompletionSurfaceKnown and
      (dram.movedWithoutCompletion or dram.gatedIdleNoInterrupt)
  outResult.outputValidationStillBlocked =
    output.outputEquivalenceBlockedByCompletion and output.completionStillMissing
  outResult.remainingCoreStartRouteOrCompletionEnable =
    outResult.terminalControlRuledOut and
      outResult.instructionMaterializationRuledOut and
      outResult.firstWeightByteRuledOut and
      outResult.cachedAddressAliasRuledOut and
      outResult.forcedInterruptBindingRuledOut and
      outResult.d0BootVramRouteRuledOut and
      outResult.d0BootClockControlRuledOut and
      outResult.completionEdgeStillMissing and
      outResult.outputValidationStillBlocked
  outResult.valid =
    outResult.terminalContrastValid and outResult.engineContextValid and
      outResult.bufferContextValid and outResult.d0WeightExperimentValid and
      outResult.m0RouteContrastValid and outResult.addressAliasContrastValid and
      outResult.m0DramSurfaceValid and outResult.forcedBindingContrastValid and
      outResult.d0BootVramContrastValid and outResult.d0BootClockContrastValid and
      outResult.outputReadinessValid and
      outResult.remainingCoreStartRouteOrCompletionEnable

proc blaiForwardCompletionEdgeRecoveryFrontierEvidence*(
    terminal: BlaiForwardD0TerminalControlContrastEvidence,
    engine: BlaiForwardD0EngineContextGapEvidence,
    buffer: BlaiForwardD0BufferContextContrastEvidence,
    weight: NpuD0WeightByteExperimentEvidence,
    route: NpuM0D0SyntheticRouteContrastEvidence,
    alias: NpuM0SyntheticAddressAliasContrastEvidence,
    dram: NpuM0DramCompletionSurfaceEvidence,
    forced: NpuM0InterruptBoundDramContrastEvidence,
    vram: NpuM0D0BootVramRouteDramContrastEvidence,
    clock: NpuM0D0BootClockControlDramContrastEvidence,
    output:
      BlaiParsedForwardConfiguredWorkspaceOutputEquivalenceReadinessEvidence):
      BlaiForwardCompletionEdgeRecoveryFrontierEvidence =
  ## Convenience wrapper for the completion-edge recovery frontier.
  blaiForwardCompletionEdgeRecoveryFrontierEvidenceInto(
    terminal, engine, buffer, weight, route, alias, dram, forced, vram, clock,
    output, result)

proc npuD0ProbeStatusEvidenceInto*(
    status, requiredMask, startedMask, buffersReadyMask, configuredMask,
    startAttemptedMask, busyObservedMask, interruptObservedMask,
    commandActivityMask, commandIdleSampledMask, busDecodeCleanMask,
    outputMovedMask, failedMask, doneMask: uint32,
    movement: NpuD0ProbeOutputMovementEvidence,
    outResult: var NpuD0ProbeStatusEvidence) =
  ## Classify the M0-observed D0 probe status word without claiming ML accuracy.
  outResult = default(NpuD0ProbeStatusEvidence)
  outResult.started = (status and startedMask) != 0'u32
  outResult.buffersReady = (status and buffersReadyMask) != 0'u32
  outResult.configured = (status and configuredMask) != 0'u32
  outResult.startAttempted = (status and startAttemptedMask) != 0'u32
  outResult.busyObserved = (status and busyObservedMask) != 0'u32
  outResult.interruptObserved = (status and interruptObservedMask) != 0'u32
  outResult.commandActivity = (status and commandActivityMask) != 0'u32
  outResult.commandIdleSampled = (status and commandIdleSampledMask) != 0'u32
  outResult.busDecodeClean = (status and busDecodeCleanMask) != 0'u32
  outResult.outputMovedStatus = (status and outputMovedMask) != 0'u32
  outResult.failed = (status and failedMask) != 0'u32
  outResult.done = (status and doneMask) != 0'u32
  outResult.requiredStatusPresent = (status and requiredMask) == requiredMask
  outResult.outputMovementValid = movement.valid
  outResult.outputMoved =
    outResult.outputMovedStatus and movement.outputMoved and
      movement.outputObserved
  outResult.modelOutputStillUnvalidated =
    movement.modelOutputStillUnvalidated
  outResult.completedWithoutFailure =
    outResult.done and not outResult.failed and outResult.requiredStatusPresent
  outResult.movementWithoutOracle =
    outResult.completedWithoutFailure and outResult.outputMovementValid and
      outResult.outputMoved and outResult.modelOutputStillUnvalidated
  outResult.valid = outResult.movementWithoutOracle

proc npuD0ProbeStatusEvidence*(
    status, requiredMask, startedMask, buffersReadyMask, configuredMask,
    startAttemptedMask, busyObservedMask, interruptObservedMask,
    commandActivityMask, commandIdleSampledMask, busDecodeCleanMask,
    outputMovedMask, failedMask, doneMask: uint32,
    movement: NpuD0ProbeOutputMovementEvidence): NpuD0ProbeStatusEvidence =
  ## Convenience wrapper for D0 probe status evidence.
  npuD0ProbeStatusEvidenceInto(
    status, requiredMask, startedMask, buffersReadyMask, configuredMask,
    startAttemptedMask, busyObservedMask, interruptObservedMask,
    commandActivityMask, commandIdleSampledMask, busDecodeCleanMask,
    outputMovedMask, failedMask, doneMask, movement, result)

proc npuD0ProbeInstructionStreamEvidenceInto*(
    stream: openArray[BlaiInstruction],
    outResult: var NpuD0ProbeInstructionStreamEvidence) =
  ## Decode the typed D0 probe stream and identify its terminal control bits.
  outResult = default(NpuD0ProbeInstructionStreamEvidence)
  outResult.streamLen = blaiOpenArrayLenU32(stream)
  if stream.len == 0:
    return
  outResult.setupWords = blaiInstructionWords(stream[0])
  outResult.hasSetupDescriptor = isBlaiExternalInstruction(stream[0])
  let terminal = decodeBlaiLayer(stream[stream.high])
  outResult.terminalWords = blaiInstructionWords(stream[stream.high])
  outResult.terminalLayerType = terminal.layerType
  outResult.terminalDescriptorHaltBitClear = not terminal.descriptorHaltBit
  outResult.terminalStreamEndBitSet = terminal.instEndBit
  outResult.terminalHaltSet = terminal.halt
  outResult.terminalInstructionPresent = true
  outResult.valid =
    outResult.terminalInstructionPresent and
      outResult.terminalStreamEndBitSet and outResult.terminalHaltSet and
      outResult.terminalDescriptorHaltBitClear

proc npuD0ProbeInstructionStreamEvidence*(
    stream: openArray[BlaiInstruction]): NpuD0ProbeInstructionStreamEvidence =
  ## Convenience wrapper for D0 probe instruction-stream evidence.
  npuD0ProbeInstructionStreamEvidenceInto(stream, result)

proc npuD0ProbeCompletionEdgeEvidenceInto*(
    stream: NpuD0ProbeInstructionStreamEvidence,
    movement: NpuD0ProbeOutputMovementEvidence,
    completion: BlaiNpuCompletionWaitResult,
    irqHandlerObserved, irqPendingObserved: bool,
    outResult: var NpuD0ProbeCompletionEdgeEvidence) =
  ## Explain the live D0 probe state without promoting it to ML correctness.
  outResult = default(NpuD0ProbeCompletionEdgeEvidence)
  outResult.streamValid = stream.valid
  outResult.terminalStreamEndBitSet = stream.terminalStreamEndBitSet
  outResult.terminalDescriptorHaltBitClear = stream.terminalDescriptorHaltBitClear
  outResult.outputMovementValid = movement.movementEvidenceValid
  outResult.outputMoved = movement.outputMoved
  outResult.commandActivity = movement.commandActivity
  outResult.busDecodeClean = movement.busDecodeClean
  outResult.waitStarted = completion.started
  outResult.completionObserved = completion.interruptObserved
  outResult.irqHandlerObserved = irqHandlerObserved
  outResult.irqPendingObserved = irqPendingObserved
  outResult.completionEdgeMissing =
    outResult.waitStarted and not outResult.completionObserved and
      not outResult.irqHandlerObserved and not outResult.irqPendingObserved
  outResult.outputMovedWithoutCompletion =
    outResult.streamValid and outResult.outputMovementValid and
      outResult.outputMoved and outResult.commandActivity and
      outResult.busDecodeClean and outResult.completionEdgeMissing
  outResult.valid = outResult.outputMovedWithoutCompletion

proc npuD0ProbeCompletionEdgeEvidence*(
    stream: NpuD0ProbeInstructionStreamEvidence,
    movement: NpuD0ProbeOutputMovementEvidence,
    completion: BlaiNpuCompletionWaitResult,
    irqHandlerObserved, irqPendingObserved: bool):
      NpuD0ProbeCompletionEdgeEvidence =
  ## Convenience wrapper for D0 probe completion-edge evidence.
  npuD0ProbeCompletionEdgeEvidenceInto(
    stream, movement, completion, irqHandlerObserved, irqPendingObserved, result)

static:
  let composedClock =
    npuMmClkCpuWithClock(
      0xA5A5_0001'u32, enable = true, source = npuClk320M, divider = 9'u32)
  doAssert (composedClock and 0xA5A5_0001'u32 and
    not (CnnClkDivEnMask or CnnClkSelMask or CnnClkDivMask)) ==
    (0xA5A5_0001'u32 and not (CnnClkDivEnMask or CnnClkSelMask or CnnClkDivMask))
  doAssert npuClockStatusFromMmClkCpu(composedClock).enabled
  doAssert npuClockStatusFromMmClkCpu(composedClock).source == npuClk320M
  doAssert npuClockStatusFromMmClkCpu(composedClock).divider == 1'u32
  var clockConfigPlanInto: NpuClockConfigPlan
  npuClockConfigPlanInto(
    0xA5A5_0001'u32, enable = true, source = npuClk320M, divider = 9'u32,
    clockConfigPlanInto)
  let clockConfigPlan =
    npuClockConfigPlan(
      0xA5A5_0001'u32, enable = true, source = npuClk320M, divider = 9'u32)
  doAssert clockConfigPlanInto == clockConfigPlan
  doAssert clockConfigPlan.initialMmClkCpu == 0xA5A5_0001'u32
  doAssert clockConfigPlan.enable
  doAssert clockConfigPlan.source == npuClk320M
  doAssert clockConfigPlan.divider == 1'u32
  doAssert clockConfigPlan.status.enabled
  doAssert clockConfigPlan.status.source == npuClk320M
  doAssert clockConfigPlan.status.divider == 1'u32
  doAssert clockConfigPlan.valid
  doAssert (clockConfigPlan.encoded and not (
    CnnClkDivEnMask or CnnClkSelMask or CnnClkDivMask)) ==
    (0xA5A5_0001'u32 and not (
      CnnClkDivEnMask or CnnClkSelMask or CnnClkDivMask))
  let disabledClockConfigPlan =
    npuClockConfigPlan(composedClock, enable = false,
      source = npuClk240M, divider = 3'u32)
  doAssert disabledClockConfigPlan.valid
  doAssert not disabledClockConfigPlan.status.enabled
  doAssert disabledClockConfigPlan.status.source == npuClk240M
  doAssert disabledClockConfigPlan.status.divider == 3'u32
  let disabledComposedClock =
    npuMmClkCpuWithClockEnable(composedClock, false)
  doAssert not npuClockStatusFromMmClkCpu(disabledComposedClock).enabled
  doAssert npuClockStatusFromMmClkCpu(disabledComposedClock).source == npuClk320M
  doAssert npuClockStatusFromMmClkCpu(disabledComposedClock).divider == 1'u32
  var clockGatePlanInto: NpuClockGatePlan
  npuClockGatePlanInto(composedClock, enable = false, clockGatePlanInto)
  let clockGatePlan = npuClockGatePlan(composedClock, enable = false)
  doAssert clockGatePlanInto == clockGatePlan
  doAssert clockGatePlan.initialMmClkCpu == composedClock
  doAssert not clockGatePlan.enable
  doAssert clockGatePlan.encoded == disabledComposedClock
  doAssert not clockGatePlan.status.enabled
  doAssert clockGatePlan.preservesSource
  doAssert clockGatePlan.preservesDivider
  doAssert clockGatePlan.valid
  var clockEnablePlanInto: NpuClockEnableRegisterPlan
  npuClockEnableRegisterPlanInto(composedClock, enable = false,
    clockEnablePlanInto)
  let clockEnablePlan =
    npuClockEnableRegisterPlan(composedClock, enable = false)
  doAssert clockEnablePlanInto == clockEnablePlan
  doAssert clockEnablePlan.initialMmClkCpu == composedClock
  doAssert not clockEnablePlan.enable
  doAssert clockEnablePlan.gatePlan == clockGatePlan
  doAssert clockEnablePlan.preservesSource
  doAssert clockEnablePlan.preservesDivider
  doAssert clockEnablePlan.valid
  doAssert npuVramCtrlWithBlaiSramRelease(0x1234_0000'u32) ==
    (0x1234_0000'u32 or BlaiSramRelMask)
  doAssert npuVramCtrlWithSysramSet(0x1234_0000'u32) ==
    (0x1234_0000'u32 or SysramSetMask)
  var sramReleasePlanInto: NpuSramReleasePlan
  npuSramReleasePlanInto(0x1234_0000'u32, sramReleasePlanInto)
  let sramReleasePlan = npuSramReleasePlan(0x1234_0000'u32)
  doAssert sramReleasePlanInto == sramReleasePlan
  doAssert sramReleasePlan.initialVramCtrl == 0x1234_0000'u32
  doAssert sramReleasePlan.releaseWrite ==
    (0x1234_0000'u32 or BlaiSramRelMask)
  doAssert sramReleasePlan.latchWrite ==
