  doAssert not sramReleasePlan.releaseStatus.sysramSetLatched
  doAssert sramReleasePlan.latchStatus.blaiSramReleased
  doAssert sramReleasePlan.latchStatus.sysramSetLatched
  doAssert npuSwResetCodecSubWithCnnReset(0x1234_0000'u32, true) ==
