    0x1234_F00F'u32,
    CodecBlai2SysramThresholdMask or (2'u32 shl CodecBlai2ExtThresholdShift),
    codecBusStatusInto)
  let codecBusStatus = npuCodecBusStatusFromRaw(
    0x1234_F00F'u32,
