  doAssert localReleaseRouteEvidence.localBlaiReleaseActive
  doAssert localReleaseRouteEvidence.routeDiffersFromLocalRelease
  doAssert localReleaseRouteEvidence.possibleD0BootRoutePrecondition
  doAssert npuVramCtrlWithD0BootSramRoute(
