  var d0BootRoutePlanInto: NpuD0BootVramRoutePlan
  npuD0BootVramRoutePlanInto(0x1234_D7D6'u32, d0BootRoutePlanInto)
  let d0BootRoutePlan = npuD0BootVramRoutePlan(0x1234_D7D6'u32)
  doAssert d0BootRoutePlanInto == d0BootRoutePlan
  doAssert d0BootRoutePlan.valid
