  doAssert blockedForwardRunInto == blockedForwardRun
  let blockedForwardRunOutcome = blaiForwardNpuExecuteOutcome(blockedForwardRun)
  var blockedForwardRunOutcomeInto: BlaiForwardNpuExecuteOutcome
  blaiForwardNpuExecuteOutcomeInto(blockedForwardRun, blockedForwardRunOutcomeInto)
  doAssert blockedForwardRunOutcomeInto == blockedForwardRunOutcome
  doAssert blockedForwardRun.outcome == blockedForwardRunOutcome
  doAssert blockedForwardRun.waitPlan == blockedCompletion
  doAssert blockedForwardRun.waitPlan.timeout == 29
  doAssert blockedForwardRun.runtimeOwnership == blaiNpuRuntimeOwnershipPlan()
  doAssert not blockedForwardRun.stopped
  doAssert not blockedForwardRun.runnable
  doAssert not blockedForwardRun.outcome.runnable
  doAssert not blockedForwardRun.outcome.stopped
  doAssert not blockedForwardRun.outcome.completed
  doAssert blockedForwardRun.status == npuUnsupported

  var invalidConfiguredLayers = [
    BlaiCpuInstLayer64(npuOn: 1, layerType: ord(blaiConvolutional).int32)]
  let invalidConfiguredResources = BlaiForwardModelResourcePlan(supported: true)
  let invalidConfiguredWorkspace = BlaiForwardModelWorkspacePlan()
  let invalidConfiguredExecution = blaiExecuteForwardModelConfigured(
    invalidConfiguredLayers, invalidConfiguredResources,
    invalidConfiguredWorkspace, timeout = 31)
  var invalidConfiguredExecutionInto: BlaiForwardModelExecuteResult
  blaiExecuteForwardModelConfiguredInto(
    invalidConfiguredLayers, invalidConfiguredResources,
    invalidConfiguredWorkspace, invalidConfiguredExecutionInto, timeout = 31)
  doAssert invalidConfiguredExecutionInto == invalidConfiguredExecution
  doAssert invalidConfiguredExecution.completion ==
    blaiForwardModelExecuteCompletion(invalidConfiguredExecution)
  doAssert not invalidConfiguredExecution.completion.completed
  doAssert invalidConfiguredExecution.allCompleted ==
    invalidConfiguredExecution.completion.completed
  doAssert not invalidConfiguredExecution.runnable
  doAssert invalidConfiguredExecution.layerStorageFits
  doAssert invalidConfiguredExecution.firstBlock ==
    blaiForwardModelExecuteRunSequence
  doAssert invalidConfiguredExecution.runSequenceFirstBlock ==
    blaiForwardModelRunSequenceReadiness
  doAssert invalidConfiguredExecution.expectedLayerCount == 0
  doAssert invalidConfiguredExecution.missingLayerCount == 0
  doAssert invalidConfiguredExecution.attemptedLayerCount == 0
  doAssert not invalidConfiguredExecution.firstFailedExecutionCaptured

  var invalidConfiguredStates = [
    BlaiCpuParsedLayerState(
      active: true, index: 0, layer: invalidConfiguredLayers[0])]
  let invalidConfiguredStateExecution = blaiExecuteForwardModelConfigured(
    invalidConfiguredStates, invalidConfiguredResources,
    invalidConfiguredWorkspace, timeout = 37)
  var invalidConfiguredStateExecutionInto: BlaiForwardModelExecuteResult
  blaiExecuteForwardModelConfiguredInto(
    invalidConfiguredStates, invalidConfiguredResources,
    invalidConfiguredWorkspace, invalidConfiguredStateExecutionInto,
    timeout = 37)
  doAssert invalidConfiguredStateExecutionInto == invalidConfiguredStateExecution
  doAssert invalidConfiguredStateExecution.completion ==
    blaiForwardModelExecuteCompletion(invalidConfiguredStateExecution)
  doAssert not invalidConfiguredStateExecution.completion.completed
  doAssert invalidConfiguredStateExecution.allCompleted ==
    invalidConfiguredStateExecution.completion.completed
  doAssert not invalidConfiguredStateExecution.runnable
  doAssert invalidConfiguredStateExecution.layerStorageFits
  doAssert invalidConfiguredStateExecution.firstBlock ==
    blaiForwardModelExecuteRunSequence
  doAssert invalidConfiguredStateExecution.runSequenceFirstBlock ==
    blaiForwardModelRunSequenceReadiness
  doAssert invalidConfiguredStateExecution.expectedLayerCount == 0
  doAssert invalidConfiguredStateExecution.missingLayerCount == 0
  doAssert invalidConfiguredStateExecution.attemptedLayerCount == 0
  doAssert not invalidConfiguredStateExecution.firstFailedExecutionCaptured
